export type LegacyThemeAdapter = {
	CreateDefinition: (self: LegacyThemeAdapter, id: any, theme: any, options: any?) -> (any?, StructuredErrorValue?),
	Register: (self: LegacyThemeAdapter, id: any, theme: any, options: any?) -> (boolean, StructuredErrorValue?),
	Compile: (self: LegacyThemeAdapter, id: any, theme: any, context: any?, options: any?) -> (any?, StructuredErrorValue?),
	CreatePresetDefinition: (self: LegacyThemeAdapter, preset: any, options: any?) -> (any?, StructuredErrorValue?),
	RegisterPreset: (self: LegacyThemeAdapter, preset: any, options: any?) -> (boolean, StructuredErrorValue?),
	CompilePreset: (self: LegacyThemeAdapter, preset: any, context: any?, options: any?) -> (any?, StructuredErrorValue?),
}

local LegacyThemeAdapter = {}
LegacyThemeAdapter.__index = LegacyThemeAdapter

local DEFAULT_SCHEMA_VERSION = table.freeze({ major = 0, minor = 1, patch = 0 })
local DEFAULT_CONTENT_VERSION = table.freeze({ major = 0, minor = 1, patch = 0 })

local function fail(code: string, message: string, operation: string, details: any?): StructuredErrorValue
	return StructuredError.from(code, message, { domain = "legacyThemeAdapter", operation = operation, details = details })
end

local function color(value: Color3): string
	return string.format("#%02X%02X%02X", math.round(value.R * 255), math.round(value.G * 255), math.round(value.B * 255))
end

local function scalar(value: any): any?
	local kind = type(value)
	if kind == "boolean" or kind == "number" or kind == "string" then return value end
	if typeof(value) == "Color3" then return color(value) end
	if typeof(value) == "Vector2" then return string.format("%s,%s", tostring(value.X), tostring(value.Y)) end
	if typeof(value) == "EnumItem" then return tostring(value.EnumType) .. "." .. value.Name end
	if typeof(value) == "Font" then return tostring(value) end
	return nil
end

local function put(tokens: { [string]: any }, key: string, value: any)
	local encoded = scalar(value)
	if encoded ~= nil then tokens[key] = encoded end
end

local function flatten(tokens: { [string]: any }, prefix: string, value: any)
	if type(value) ~= "table" then
		put(tokens, prefix, value)
		return
	end
	for key, item in pairs(value) do
		if type(key) == "string" then flatten(tokens, prefix .. "." .. key, item) end
	end
end

local function presetId(preset: string): string
	local normalized = string.lower(preset):gsub("[^a-z0-9]+", "-"):gsub("^-", ""):gsub("-$", "")
	if normalized == "" then normalized = "default" end
	return "potassium:legacy-theme-" .. normalized
end

local function options(value: any, operation: string): (any?, StructuredErrorValue?)
	local resolved = if value == nil then {} else value
	if type(resolved) ~= "table" then return nil, fail("invalid_adapter_options", "Legacy theme adapter options must be a table", operation) end
	for key in pairs(resolved) do
		if key ~= "schemaVersion" and key ~= "contentVersion" and key ~= "variant" then
			return nil, fail("unknown_adapter_option", "Legacy theme adapter option is not supported", operation, { option = key })
		end
	end
	return resolved, nil
end

function LegacyThemeAdapter.new(compiler: any): (LegacyThemeAdapter?, StructuredErrorValue?)
	if type(compiler) ~= "table" or type(compiler.Register) ~= "function" or type(compiler.Compile) ~= "function" then
		return nil, fail("invalid_skin_compiler", "LegacyThemeAdapter requires the SkinCompiler contract", "create")
	end
	return setmetatable({ _compiler = compiler }, LegacyThemeAdapter) :: any, nil
end

function LegacyThemeAdapter:CreateDefinition(id: any, theme: any, rawOptions: any?): (any?, StructuredErrorValue?)
	local resolvedOptions, optionErr = options(rawOptions, "createDefinition")
	if resolvedOptions == nil then return nil, optionErr end
	if type(id) ~= "string" then return nil, fail("invalid_legacy_skin_id", "Legacy skin id must be a NamespacedId string", "createDefinition") end
	local resolvedTheme, themeErr = Theme.resolve(theme)
	if resolvedTheme == nil then return nil, themeErr end
	local tokens: { [string]: any } = {}
	put(tokens, "variant", resolvedTheme.variant)
	put(tokens, "density", resolvedTheme.density)
	put(tokens, "textScale", resolvedTheme.textScale)
	put(tokens, "reducedMotion", resolvedTheme.reducedMotion)
	put(tokens, "font", resolvedTheme.font)
	put(tokens, "fontFace", resolvedTheme.fontFace)
	put(tokens, "opacity", resolvedTheme.opacity)
	put(tokens, "rowLines", resolvedTheme.rowLines)
	put(tokens, "checkboxStyle", resolvedTheme.checkboxStyle)
	put(tokens, "layout", resolvedTheme.layout)
	put(tokens, "sectionStyle", resolvedTheme.sectionStyle)
	put(tokens, "accentA", resolvedTheme.accentA)
	put(tokens, "accentB", resolvedTheme.accentB)
	flatten(tokens, "color", resolvedTheme.colors)
	flatten(tokens, "spacing", resolvedTheme.spacing)
	flatten(tokens, "radius", resolvedTheme.radius)
	flatten(tokens, "typography", resolvedTheme.typography)
	flatten(tokens, "state", resolvedTheme.states)
	flatten(tokens, "zIndex", resolvedTheme.zIndex)
	flatten(tokens, "effect", resolvedTheme.effects)
	local metrics = {}
	for key, value in pairs(resolvedTheme.metrics) do metrics[key] = value end
	return {
		id = id,
		schemaVersion = rawget(resolvedOptions, "schemaVersion") or DEFAULT_SCHEMA_VERSION,
		contentVersion = rawget(resolvedOptions, "contentVersion") or DEFAULT_CONTENT_VERSION,
		semanticTokens = tokens,
		metrics = metrics,
		variants = {
			legacy = {
