	if definition == nil then return false, definitionErr end
	return self._compiler:Register(definition)
end

function LegacyThemeAdapter:Compile(id: any, theme: any, context: any?, rawOptions: any?): (any?, StructuredErrorValue?)
	local registered, registerErr = self:Register(id, theme, rawOptions)
	if not registered then return nil, registerErr end
	return self._compiler:Compile(id, context)
end

function LegacyThemeAdapter:CreatePresetDefinition(preset: any, rawOptions: any?): (any?, StructuredErrorValue?)
	if type(preset) ~= "string" then return nil, fail("unknown_preset", "Legacy preset name must be a string", "createPresetDefinition") end
	local selected = rawget(Theme.presets, preset)
	if selected == nil then return nil, fail("unknown_preset", "Unknown legacy theme preset", "createPresetDefinition", { preset = preset }) end
	return self:CreateDefinition(presetId(preset), selected, rawOptions)
end

function LegacyThemeAdapter:RegisterPreset(preset: any, rawOptions: any?): (boolean, StructuredErrorValue?)
	local definition, definitionErr = self:CreatePresetDefinition(preset, rawOptions)
	if definition == nil then return false, definitionErr end
	return self._compiler:Register(definition)
end

function LegacyThemeAdapter:CompilePreset(preset: any, context: any?, rawOptions: any?): (any?, StructuredErrorValue?)
	local definition, definitionErr = self:CreatePresetDefinition(preset, rawOptions)
	if definition == nil then return nil, definitionErr end
	local registered, registerErr = self._compiler:Register(definition)
	if not registered then return nil, registerErr end
	return self._compiler:Compile(definition.id, context)
end

return LegacyThemeAdapter

end

__modules["adapters/LegacyWorkspaceAdapter"] = function()
--!strict

local StructuredError = __require("core/StructuredError")

-- This adapter owns only the named V1 schema. Wire-version migration belongs to
-- WorkspaceManager so named and document inputs converge on the same V3 authority.
local LegacyWorkspaceAdapter = {}

local function failure(code: string, message: string, operation: string, details: any?): any
	return StructuredError.from(code, message, { domain = "workspace", operation = operation, details = details })
end

local function copy(value: any, depth: number?, seen: any?): any
	depth, seen = depth or 0, seen or {}
	local kind = type(value)
	if kind ~= "table" then
		if kind ~= "nil" and kind ~= "boolean" and kind ~= "number" and kind ~= "string" then error("workspace value type is invalid") end
		if kind == "number" and (value ~= value or value == math.huge or value == -math.huge) then error("workspace number must be finite") end
		return value
	end
	if getmetatable(value) ~= nil or depth >= 12 or seen[value] then error("unsupported workspace value") end
	seen[value] = true
	local result, count = {}, 0
	for key, item in pairs(value) do
		count += 1
		if count > 512 then error("workspace is too large") end
		if type(key) ~= "string" and type(key) ~= "number" then error("workspace key is invalid") end
		result[key] = copy(item, depth + 1, seen)
	end
	seen[value] = nil
	return result
end

local function legacyUDim2(value: any): any
	if type(value) ~= "table" then return nil end
	if type(value.xScale) == "number" and type(value.xOffset) == "number" and type(value.yScale) == "number" and type(value.yOffset) == "number" then
		return copy(value)
	end
	if type(value.xs) == "number" and type(value.xo) == "number" and type(value.ys) == "number" and type(value.yo) == "number" then
		return { xScale = value.xs, xOffset = value.xo, yScale = value.ys, yOffset = value.yo }
	end
	return nil
end

local function legacyPanels(value: any): any
	if type(value) ~= "table" then return nil end
	local panels = {}
	for index, panel in ipairs(value) do
		if type(panel) == "table" then
			panels[index] = {
				position = legacyUDim2(panel.position),
				size = legacyUDim2(panel.size),
				visible = panel.visible,
				alwaysOnTop = panel.alwaysOnTop,
			}
		end
	end
	return panels
end

local function window(value: any, id: string?): any
	if type(value) ~= "table" then error("legacy window must be a table") end
	local windowId = id or value.id
	if type(windowId) ~= "string" or windowId == "" then error("legacy window id is required") end
	if value.id ~= nil and value.id ~= windowId then error("legacy keyed window id conflicts with its key") end
	if value.visibility ~= nil then error("legacy V1 windows cannot declare visibility") end
	local geometry = type(value.geometry) == "table" and value.geometry or {}
	local position = legacyUDim2(value.position) or legacyUDim2(geometry.position)
	local size = legacyUDim2(value.size) or legacyUDim2(geometry.size)
	local dock = if value.dock ~= nil then value.dock else value.dockEdge
	local route = if value.activeSubtab ~= nil then value.activeSubtab else (if value.route ~= nil then value.route else value.activeTab)
	return {
		id = windowId,
		position = position,
		size = size,
		open = value.open,
		scale = value.scale,
		autoScale = value.autoScale,
		dock = dock,
		route = route,
		scroll = copy(value.scroll),
		panel = legacyPanels(value.panel or value.floatingPanels or value.panels),
		alwaysOnTop = value.alwaysOnTop,
		category = value.category,
	}
end

function LegacyWorkspaceAdapter.MigrateNamed(document: any): (any?, any?)
	if type(document) ~= "table" or document.version ~= 1 or type(document.windows) ~= "table" then
		return nil, failure("invalid_legacy_workspace", "Workspace V1 must be literal {version=1, windows={...}}", "migrateNamed")
	end
	local ok, result = pcall(function()
		local windows, count, arrayLength = {}, 0, #document.windows
		local keyed = false
		for key in pairs(document.windows) do
			count += 1
			if type(key) ~= "number" or key < 1 or key % 1 ~= 0 or key > arrayLength then keyed = true end
		end
		if keyed and arrayLength > 0 then error("legacy workspace windows cannot mix array and keyed entries") end
		if not keyed and count ~= arrayLength then error("legacy workspace windows array is sparse") end
		if keyed then
			for key, value in pairs(document.windows) do
				if type(key) ~= "string" or key == "" then error("legacy keyed window map requires nonempty string keys") end
				windows[key] = window(value, key)
			end
		else
			for index, value in ipairs(document.windows) do windows[index] = window(value) end
		end
		return { format = "potassium-ui-workspace", wireVersion = 2, workspaceSchemaVersion = "2.0", payload = { windows = windows }, unknownNamespaces = {} }
	end)
	if not ok then return nil, failure("invalid_legacy_workspace", tostring(result), "migrateNamed") end
	return result, nil
end

LegacyWorkspaceAdapter.Migrate = LegacyWorkspaceAdapter.MigrateNamed

return LegacyWorkspaceAdapter

end

