	Version = "1.0.0",
	ApiVersion = 1,
	Style = "compact-script-sidebar",
	LayoutMode = "auto",
	DefaultWindowSize = Vector2.new(600, 400),
	NavigationBreakpoint = 540,
	SidebarWidth = 130,
	InteractionHeight = 44,
	ThemeMetrics = table.freeze({
