		contentPadding = 10,
		pageGap = 10,
		sectionPadding = 10,
		searchWidth = 190,
	}),
	LoadModes = table.freeze({ "ModuleScript", "Bundle" }),
})

local function errorResult(code: string, message: string)
	return { code = code, message = message }
end
local function controlKey(name: any): (string?, any?)
	if type(name) ~= "string" or name == "" then
		return nil, errorResult("invalid_control_name", "Control name must be a non-empty string")
	end
	local key = Util.sanitizeId(name, "")
	if key == "" then
		return nil,
			errorResult("invalid_control_name", "Control name must contain a letter, number, underscore, or hyphen")
	end
	return key, nil
end

local function instance(className: string, properties: any, parent: Instance): Instance
	return Factory.make(className, properties, parent)
end

local function destroy(value: any)
	if value ~= nil and type(value.Destroy) == "function" then
		pcall(function()
			value:Destroy()
		end)
	end
end
local FONT_CHOICES = Fonts.List()
local BACKGROUND_EFFECT_NAMES = Util.deepCopy(BackgroundEffects.Names)
local function callableCatalog(source: any)
	local catalog = Util.deepCopy(source)
	return setmetatable(catalog, {
		__call = function()
			local names = {}
			if #catalog > 0 then
				for _, name in ipairs(catalog) do
					table.insert(names, name)
				end
			else
				for name in pairs(catalog) do
					table.insert(names, name)
				end
				table.sort(names)
			end
			return names
		end,
	})
end
Library.ThemePresets = callableCatalog(Theme.presets)
Library.FontChoices = callableCatalog(FONT_CHOICES)
Library.BackgroundEffectsNames = callableCatalog(BACKGROUND_EFFECT_NAMES)
Library.Icons = Icons

