local CONSUMER_MIGRATION_RECORDS = table.freeze({
	table.freeze({
		kind = "consumer-migration",
		id = "courier-consumer-migration",
		consumer = "Courier",
		fixture = "consumer-public-api.smoke.luau",
		completed = true,
	}),
	table.freeze({
		kind = "consumer-migration",
		id = "neverlose-consumer-migration",
		consumer = "Neverlose",
		fixture = "consumer-private-observations.smoke.luau",
		completed = true,
	}),
})
local function refreshFontChoices()
	table.clear(FONT_CHOICES)
	for _, name in ipairs(Fonts.List()) do
		table.insert(FONT_CHOICES, name)
	end
	table.clear(Library.FontChoices)
	for _, name in ipairs(FONT_CHOICES) do
		table.insert(Library.FontChoices, name)
	end
end

local function refreshBackgroundEffectNames(names: any)
	table.clear(BACKGROUND_EFFECT_NAMES)
	table.clear(Library.BackgroundEffectsNames)
	for _, name in ipairs(names) do
		table.insert(BACKGROUND_EFFECT_NAMES, name)
		table.insert(Library.BackgroundEffectsNames, name)
	end
end

local function applyThemeFont(theme: any, value: any, fontRegistry: any?): (boolean, any?)
	local registry = fontRegistry or Fonts
	local face, faceError = Theme.resolveFontFace(value, registry)
	if face == nil then
		return false, faceError
	end
	local legacy = Theme.resolveFont(value, registry)
	theme.font = legacy
	theme.fontFace = face
	return true, nil
end

local function normalizeThemeCompatibility(value: any, fontRegistry: any?): any
	if type(value) ~= "table" then
		return value
	end
	local theme = Util.deepCopy(value)
	if theme.accent ~= nil then
		if typeof(theme.accent) == "Color3" then
			theme.accentA, theme.accentB = theme.accent, theme.accent
			theme.colors = Util.deepMerge(theme.colors or {}, { focus = theme.accent })
			theme.states = Util.deepMerge(theme.states or {}, { selected = { border = theme.accent } })
		end
		theme.accent = nil
	end
	if type(theme.opacity) == "number" and theme.opacity > 1 then
		theme.opacity /= 100
	end
	if type(theme.rounding) == "number" then
		theme.radius = Util.deepMerge(theme.radius or {}, {
			sm = theme.rounding,
			md = theme.rounding,
			lg = theme.rounding,
		})
		theme.rounding = nil
	end
	if theme.font ~= nil then
		applyThemeFont(theme, theme.font, fontRegistry)
	end
	return theme
end
local function mergeThemeOverrides(baseTheme: any, overrides: any, fontRegistry: any?): (any?, any?)
	local base = Util.deepCopy(baseTheme)
	if type(overrides) == "table" and overrides.variant ~= nil and overrides.variant ~= base.variant then
		local variant, variantError = Theme.resolve({ variant = overrides.variant }, fontRegistry)
		if variant == nil then return nil, variantError end
		base = variant
	end
	local source = Util.deepMerge(base, overrides or {})
	if type(overrides) == "table" and type(overrides.spacing) == "table" and overrides.spacingBase == nil then
		source.spacingBase = Util.deepMerge(base.spacingBase or {}, overrides.spacing)
	end
	if type(overrides) == "table" and type(overrides.metrics) == "table" and overrides.metricsBase == nil then
		source.metricsBase = Util.deepMerge(base.metricsBase or {}, overrides.metrics)
	end
	return source, nil
end
local function mergedOptions(options: any): (any?, any?)
	if options == nil then
		return {}, nil
	end
	if type(options) ~= "table" then
		return nil, errorResult("invalid_options", "Library options must be a table")
	end
	local opts = Util.deepCopy(options)
	local theme = if type(opts.Theme) == "table" then normalizeThemeCompatibility(opts.Theme) else {}
	if type(opts.theme) == "table" then
		theme = Util.deepMerge(theme, normalizeThemeCompatibility(opts.theme))
	end
	local themeName = if type(opts.theme) == "string" then opts.theme elseif type(opts.Theme) == "string" then opts.Theme else nil
	if themeName ~= nil then
		local preset, presetError = Theme.applyPreset(themeName, theme)
		if preset == nil then return nil, presetError end
		theme = preset
	end
	for _, key in ipairs({ "accentA", "accentB", "opacity", "rounding", "rowLines", "checkboxStyle" }) do
		if opts[key] ~= nil then
			if key == "rounding" then
				theme.radius = Util.deepMerge(theme.radius or {}, { sm = opts[key], md = opts[key], lg = opts[key] })
			else
				theme[key] = opts[key]
			end
		end
	end
	for _, effect in ipairs({
		"glass",
		"glow",
		"glowColor",
		"glowSpread",
		"glowSoftness",
		"glowStyle",
		"glowEdgeLength",
		"glowThickness",
		"blur",
		"glassTint",
		"glassBorder",
		"glassFrost",
		"shadow",
		"shadowColor",
		"shadowSpread",
		"shadowOffset",
		"accentGlow",
	}) do
		if opts[effect] ~= nil then
			theme.effects = Util.deepMerge(theme.effects or {}, { [effect] = opts[effect] })
		end
	end
	local fontValue = if opts.Font ~= nil then opts.Font else opts.font
	if fontValue ~= nil then
		local applied, fontError = applyThemeFont(theme, fontValue)
		if not applied then
			return nil, fontError
		end
	end
	opts.Theme = theme
	opts.Persistence =
		Util.deepMerge(opts.Persistence or {}, if opts.configFolder ~= nil then { folder = opts.configFolder } else {})
	return opts, nil
end

local function firstNonNil(primary: any, fallback: any): any
	if primary ~= nil then
		return primary
	end
	return fallback
end

local function normalizeBackgroundAppearance(value: any): any
	local appearance = Util.deepCopy(value)
	local rawBackground = appearance.background
	local rawState = if type(rawBackground) == "table" then firstNonNil(rawBackground.state, rawBackground.State) else nil
	local rawOptions = if type(rawBackground) == "table" then firstNonNil(rawBackground.options, rawBackground.Options) else nil
	local rawImage = if type(rawState) == "table" then firstNonNil(rawState.Image, rawState.image) else appearance.backgroundImage
	local state = Util.deepCopy(if type(rawState) == "table" then rawState else {})
	state.Effect = if type(rawState) == "table"
		then firstNonNil(rawState.Effect, rawState.effect)
		else firstNonNil(appearance.backgroundEffect, "Off")
	state.Color = if type(rawState) == "table"
		then firstNonNil(rawState.Color, rawState.color)
		else appearance.backgroundEffectColor
	if rawImage == nil then
		rawImage = {}
	end
	if type(rawImage) == "table" then
		state.Image = {
			Source = firstNonNil(rawImage.Source, rawImage.source),
			Transparency = firstNonNil(firstNonNil(rawImage.Transparency, rawImage.transparency), 0),
		}
	else
		state.Image = rawImage
	end
	state.effect, state.color, state.image = nil, nil, nil
	appearance.background = {
		state = state,
		options = Util.deepCopy(if rawOptions ~= nil then rawOptions else {}),
	}
	appearance.backgroundEffect = nil
	appearance.backgroundEffectColor = nil
	appearance.backgroundImage = nil
	return appearance
end

function Library.new(options: any)
	local opts, optionsError = mergedOptions(options)
	if opts == nil then
		return nil, optionsError
	end
	local screenGuiName = if opts.ScreenGuiName ~= nil then opts.ScreenGuiName else opts.screenGuiName
	if
		screenGuiName ~= nil
		and (type(screenGuiName) ~= "string" or string.match(screenGuiName, "%S") == nil or #screenGuiName > 100)
	then
		return nil, errorResult("invalid_screen_gui_name", "ScreenGuiName must be a non-empty string up to 100 characters")
	end

	local runtimeOk, runtime, runtimeError = pcall(function()
		return Runtime.resolve(opts.Runtime or opts)
	end)
	if not runtimeOk or runtime == nil then
		return nil,
			if type(runtimeError) == "table"
				then runtimeError
				else errorResult("runtime_resolution_failed", tostring(runtimeError or runtime))
	end

	local themeOk, theme, themeError = pcall(function()
		return Theme.resolve(opts.Theme)
	end)
	if not themeOk or theme == nil then
		destroy(runtime)
		return nil,
			if type(themeError) == "table"
				then themeError
				else errorResult("theme_resolution_failed", tostring(themeError or theme))
	end

	local maid = Maid.new()
	local store, storeError = Store.new(nil, { onCallbackError = opts.OnCallbackError })
	if store == nil then
		destroy(maid)
		destroy(runtime)
		return nil, storeError or errorResult("store_unavailable", "Could not create a value store")
	end
	local dependencyGraph = DependencyGraph.new(store)

	local themeChanged = Signal.new()
	local gui: ScreenGui? = nil
	local created = {}
	local function rollback(errorValue: any)
		for index = #created, 1, -1 do
			destroy(created[index])
		end
		destroy(themeChanged)
		destroy(store)
		destroy(dependencyGraph)
		destroy(maid)
		destroy(runtime)
		return nil,
			if type(errorValue) == "table" then errorValue else errorResult("construction_failed", tostring(errorValue))
	end

	local constructed, constructionError = xpcall(function()
		local screenGui, guiError = runtime:CreateScreenGui({
			Name = screenGuiName,
			DisplayOrder = opts.DisplayOrder or 100,
			IgnoreGuiInset = true,
			ResetOnSpawn = false,
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		})
		if screenGui == nil then
			error(guiError or errorResult("screen_gui_failed", "Could not create a ScreenGui"), 0)
		end
		gui = screenGui
		table.insert(created, gui)

		local root = instance("Frame", {
			Name = "Root",
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Size = UDim2.fromScale(1, 1),
			ZIndex = theme.zIndex.base,
		}, gui) :: Frame
		local aligningRoot = false
		local function alignRoot()
			if aligningRoot then
				return
			end
			local absolute = root.AbsolutePosition
			if math.abs(absolute.X) < 0.5 and math.abs(absolute.Y) < 0.5 then
				return
			end
			aligningRoot = true
			root.Position += UDim2.fromOffset(-absolute.X, -absolute.Y)
			aligningRoot = false
		end
		maid:GiveTask(root:GetPropertyChangedSignal("AbsolutePosition"):Connect(alignRoot))
		alignRoot()
		task.defer(alignRoot)
		local portal = instance("Frame", {
			Name = "Portal",
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Size = UDim2.fromScale(1, 1),
			ZIndex = theme.zIndex.popup,
		}, root) :: Frame
		local modal = instance("Frame", {
			Name = "Modal",
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Size = UDim2.fromScale(1, 1),
			ZIndex = theme.zIndex.modal,
		}, root) :: Frame
		local toast = instance("Frame", {
			Name = "Toast",
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Size = UDim2.fromScale(1, 1),
			ZIndex = theme.zIndex.toast,
		}, root) :: Frame
		local motion = Motion.new(runtime, maid, { reducedMotion = theme.reducedMotion })
		local inputRouter = InputRouter.new(runtime, maid)
		local focusManager = FocusManager.new(runtime, maid)
		table.insert(created, motion)
		table.insert(created, inputRouter)
		table.insert(created, focusManager)
		local localization = Localization.new(nil, opts.Localization or opts.localization)
		table.insert(created, localization)
		table.insert(created, dependencyGraph)
		local diagnosticsOptions = if type(opts.Diagnostics) == "table"
			then opts.Diagnostics
			else if type(opts.diagnostics) == "table" then opts.diagnostics else {}
		local diagnostics = Diagnostics.new(diagnosticsOptions)
		local capability = Capability.detect(
			runtime,
			if type(opts.Capabilities) == "table" then opts.Capabilities else opts.capabilities
		)
		local budgetOptions = Util.deepCopy(
			if type(opts.Budget) == "table" then opts.Budget else if type(opts.budget) == "table" then opts.budget else {}
		)
		budgetOptions.diagnostics = diagnostics
		local budgetLedger, budgetError = BudgetLedger.new(budgetOptions)
		if budgetLedger == nil then
			error(budgetError or errorResult("budget_unavailable", "Could not create a budget ledger"), 0)
		end
		local hostOptions = Util.deepCopy(
			if type(opts.ExtensionHost) == "table"
				then opts.ExtensionHost
				else if type(opts.extensionHost) == "table" then opts.extensionHost else {}
		)
		hostOptions.diagnostics = diagnostics
		hostOptions.budgetLedger = budgetLedger
		hostOptions.capability = capability
		local extensionHost, extensionError = ExtensionHost.new(hostOptions)
		if extensionHost == nil then
			error(extensionError or errorResult("extension_host_unavailable", "Could not create an extension host"), 0)
		end
		local migrationOptions = if type(opts.Migrations) == "table"
			then opts.Migrations
			else if type(opts.migrations) == "table" then opts.migrations else {}
		local migrationRegistry, migrationError = MigrationRegistry.new(migrationOptions)
		if migrationRegistry == nil then
			error(migrationError or errorResult("migration_registry_unavailable", "Could not create a migration registry"), 0)
		end
		local legacyControlAdapter, adapterError = LegacyControlAdapter.new(extensionHost)
		if legacyControlAdapter == nil then
			error(adapterError or errorResult("legacy_adapter_unavailable", "Could not create the legacy control adapter"), 0)
		end
		local schemaCodec = SchemaCodec.new({
			diagnostics = diagnostics,
		})
		local packManager, packManagerError = PackManager.new({
			extensionHost = extensionHost,
			codec = schemaCodec,
			diagnostics = diagnostics,
			capabilities = capability:GetSnapshot(),
			migrationRegistry = migrationRegistry,
		})
		if packManager == nil then
			error(packManagerError or errorResult("pack_manager_unavailable", "Could not create a pack manager"), 0)
		end
		local skinCompiler = SkinCompiler.new({
			codec = schemaCodec,
			diagnostics = diagnostics,
		})
		local legacyThemeAdapter, legacyThemeAdapterError = LegacyThemeAdapter.new(skinCompiler)
		if legacyThemeAdapter == nil then
			error(legacyThemeAdapterError or errorResult("legacy_theme_adapter_unavailable", "Could not create the legacy theme adapter"), 0)
		end
		local assetOptions = if type(opts.AssetPolicy) == "table"
			then Util.deepCopy(opts.AssetPolicy)
			else if type(opts.assetPolicy) == "table" then Util.deepCopy(opts.assetPolicy) else {}
		if assetOptions.mode == nil then
			assetOptions.mode = "neutral"
		end
		assetOptions.capability = capability
		local assetPolicy, assetPolicyError = AssetPolicy.new(assetOptions)
		if assetPolicy == nil then
			error(assetPolicyError or errorResult("asset_policy_unavailable", "Could not create an asset policy"), 0)
		end
		local fonts = Fonts.new(assetPolicy)
		local icons = Icons.new(runtime, assetPolicy)
		local materialRenderer, materialRendererError = MaterialRenderer.new({
			budgetLedger = budgetLedger,
			assetPolicy = assetPolicy,
			factory = Factory,
			runtime = runtime,
			maidFactory = Maid,
			diagnostics = diagnostics,
			ownerId = "potassium-ui",
		})
		if materialRenderer == nil then
			error(materialRendererError or errorResult("material_renderer_unavailable", "Could not create a material renderer"), 0)
		end
		local controlHost, controlHostError = ControlHost.new({
			target = root,
			ownerId = "potassium-ui",
			budget = budgetLedger,
			diagnostics = diagnostics,
		})
		if controlHost == nil then
			error(controlHostError or errorResult("control_host_unavailable", "Could not create a control host"), 0)
		end
		local addonRail, addonRailError = OldschoolPrimitives.AddonRail.new({
			ownerId = "potassium-ui",
		})
		if addonRail == nil then
			error(addonRailError or errorResult("addon_rail_unavailable", "Could not create an addon rail"), 0)
		end
		local slotHost, slotHostError = SlotHost.new({
			ownerId = "potassium-ui",
			localization = localization,
			slots = {
				root = { target = root },
				portal = { target = portal },
				modal = { target = modal },
				toast = { target = toast },
			},
		})
		if slotHost == nil then
			error(slotHostError or errorResult("slot_host_unavailable", "Could not create a slot host"), 0)
		end
		local layoutEngine, layoutEngineError = LayoutEngine.new({
			ownerId = "potassium-ui",
			target = root,
			budget = budgetLedger,
			diagnostics = diagnostics,
			slotHost = slotHost,
		})
		if layoutEngine == nil then
			error(layoutEngineError or errorResult("layout_engine_unavailable", "Could not create a layout engine"), 0)
		end
		maid:Set("customization.controlHost", controlHost)
		maid:Set("customization.addonRail", addonRail)
		maid:Set("customization.slotHost", slotHost)
		maid:Set("customization.layoutEngine", layoutEngine)
		table.insert(created, controlHost)
		table.insert(created, addonRail)
		table.insert(created, slotHost)
		table.insert(created, layoutEngine)

		maid:Set("customization.materialRenderer", materialRenderer)
		local routes = NavigationModel.new()
		local resources = ResourceController.new()
		local edits = EditSession.new()
		local adaptive = AdaptiveController.new(opts.Adaptive or opts.adaptive)
		local menuSchema = MenuSchema.new(schemaCodec)
		local trustedActions = if type(opts.TrustedActions) == "table" then opts.TrustedActions else if type(opts.trustedActions) == "table" then opts.trustedActions else {}
		local hapticOptions = if type(opts.Haptics) == "table"
			then Util.deepCopy(opts.Haptics)
			else if type(opts.haptics) == "table" then Util.deepCopy(opts.haptics) else {}
		if hapticOptions.enabled == nil then
			hapticOptions.enabled = false
		end
		local haptics = Haptics.new(runtime, capability, adaptive, maid, hapticOptions)
		local runtimeBindings = { entries = {} }
		local menuServices = { _forms = {}, _library = nil }
		function menuServices:PreflightRegisterResource(resource: any): (boolean, any?)
			if resources._entries[resource.id] ~= nil then return false, errorResult("duplicate_resource", "Menu resource is already registered") end
			return true, nil
		end
		function menuServices:RegisterResource(resource: any): (any?, any?)
			return resources:Create(resource.id, function() return resource.definition.provider end)
		end
		function menuServices:UnregisterResource(id: string)
			local entry = resources._entries[id]
			if entry ~= nil then entry.signal:Destroy(); resources._entries[id] = nil end
		end
		function menuServices:PreflightRegisterForm(form: any): (boolean, any?)
			if self._forms[form.id] ~= nil then return false, errorResult("duplicate_form", "Menu form is already registered") end
			return true, nil
		end
		function menuServices:RegisterForm(declaration: any): (any?, any?)
			local library = self._library
			if library == nil then return nil, errorResult("menu_services_unavailable", "Menu form service is unavailable") end
			local instance = library:CreateForm(declaration.definition)
			self._forms[declaration.id] = instance
			return instance, nil
		end
		function menuServices:UnregisterForm(id: string)
			local form = self._forms[id]
			if form ~= nil then
				local library = self._library
				if library ~= nil then
					library._forms[form] = nil
					for inspector in pairs(library._developerInspectors) do inspector:UnregisterForm(form) end
				end
				form:Destroy()
				self._forms[id] = nil
			end
		end
		function menuServices:PreflightRegisterRuntimeBinding(binding: any): (boolean, any?)
			local key = binding.source .. ":" .. binding.id
			if runtimeBindings.entries[key] ~= nil then return false, errorResult("duplicate_runtime_binding", "Menu runtime binding is already registered") end
			return true, nil
		end
		function menuServices:RegisterRuntimeBinding(binding: any): (boolean, any?)
			local key = binding.source .. ":" .. binding.id
			runtimeBindings.entries[key] = binding
			return true, nil
		end
		function menuServices:UnregisterRuntimeBinding(source: string, id: string)
			runtimeBindings.entries[source .. ":" .. id] = nil
		end
		local controlServices = {
			Store = store,
			InputRouter = inputRouter,
			Haptics = haptics,
			Resources = resources,
			EditSession = edits,
			Localization = localization,
			Dependencies = dependencyGraph,
			Navigation = routes,
			DataControls = Controls,
			TrustedActions = {
				Execute = function(_: any, id: string, args: any, descriptor: any)
					local action = trustedActions[id]
					if type(action) ~= "function" then return false, errorResult("unknown_trusted_action", "Trusted action is not registered") end
					local ok, result = pcall(action, args, descriptor)
					if ok then return true, result end
					return false, errorResult("trusted_action_failed", tostring(result))
				end,
			},
		}
		local modernControls = ModernControls.new(controlServices)
		for kind, renderer in pairs(modernControls.Renderers) do
			local rendererOk, rendererError = controlHost:RegisterRenderer(kind, renderer)
			if not rendererOk then
				error(rendererError or errorResult("modern_renderer_unavailable", "Could not register modern control renderer"), 0)
			end
		end
		local legacyRendererOk, legacyRendererError = controlHost:RegisterRenderer("legacy", OldschoolPrimitives.RenderLegacy)
		if not legacyRendererOk then
			error(legacyRendererError or errorResult("legacy_renderer_unavailable", "Could not register legacy control renderer"), 0)
		end
		local values = StateView.new(store)
		local workspaceOrderProjector = { _manager = nil }
		function workspaceOrderProjector:ApplyCompositionOrder(parentId: any, snapshot: any, projection: any)
			if self._manager ~= nil then return self._manager:ApplyCompositionOrder(parentId, snapshot, projection) end
			return true
		end
		function workspaceOrderProjector:ClearCompositionOrder(parentId: any)
			if self._manager ~= nil then return self._manager:ClearCompositionOrder(parentId) end
			return true
		end
		local compositionBuilder = CompositionBuilder.new({
			participants = { layoutEngine, slotHost, controlHost, store },
			layoutEngine = layoutEngine,
			focusManager = focusManager,
			workspace = workspaceOrderProjector,
		})
		table.insert(created, routes)
		table.insert(created, resources)
		table.insert(created, edits)
		table.insert(created, fonts)
		table.insert(created, icons)
		table.insert(created, haptics)
		table.insert(created, adaptive)
		table.insert(created, materialRenderer)
		maid:Set("kernel.extensionHost", extensionHost)
		maid:Set("kernel.diagnostics", diagnostics)
		table.insert(created, extensionHost)
		table.insert(created, diagnostics)

		local self = setmetatable({
			Name = tostring(opts.Name or "PotassiumUI"),
			Runtime = runtime,
			Player = opts.Player or opts.player,
			PlayerLocale = opts.PlayerLocale or opts.playerLocale,
			Theme = theme,
			ThemeChanged = themeChanged,
			Maid = maid,
			Store = store,
			DependencyGraph = dependencyGraph,
			Motion = motion,
			InputRouter = inputRouter,
			Diagnostics = diagnostics,
			Capabilities = capability,
			BudgetLedger = budgetLedger,
			ExtensionHost = extensionHost,
			PackManager = packManager,
			MigrationRegistry = migrationRegistry,
			LegacyControlAdapter = legacyControlAdapter,
			Routes = routes,
			Resources = resources,
			Edits = edits,
			RuntimeBindings = runtimeBindings,
			Adaptive = adaptive,
			MenuSchema = menuSchema,
			_menuServices = menuServices,
			Factory = Factory,
			SchemaCodec = schemaCodec,
			Values = values,
			CompositionBuilder = compositionBuilder,
			OfflineAssets = OfflineAssets,
			Fonts = fonts,
			Haptics = haptics,
			SkinCompiler = skinCompiler,
			LegacyThemeAdapter = legacyThemeAdapter,
			MaterialRenderer = materialRenderer,
			ConsumerMigrationRecords = CONSUMER_MIGRATION_RECORDS,
			AssetPolicy = assetPolicy,
			AdapterRecords = ADAPTER_RECORDS,
			ControlDescriptors = ControlDescriptors,
			CompositionDescriptors = CompositionDescriptors,
			TableModel = TableModel,
			ControlHost = controlHost,
			OldschoolPrimitives = OldschoolPrimitives,
			AddonRail = addonRail,
			ModernControls = modernControls,
			SlotHost = slotHost,
			LayoutSpec = LayoutSpec,
			LayoutEngine = layoutEngine,
			Kernel = table.freeze({
				Diagnostics = diagnostics,
				Capabilities = capability,
				BudgetLedger = budgetLedger,
				ExtensionHost = extensionHost,
				PackManager = packManager,
				MigrationRegistry = migrationRegistry,
				LegacyControlAdapter = legacyControlAdapter,
				SchemaCodec = schemaCodec,
				SkinCompiler = skinCompiler,
				LegacyThemeAdapter = legacyThemeAdapter,
				MaterialRenderer = materialRenderer,
				AssetPolicy = assetPolicy,
				ControlDescriptors = ControlDescriptors,
				CompositionDescriptors = CompositionDescriptors,
				TableModel = TableModel,
				ControlHost = controlHost,
				OldschoolPrimitives = OldschoolPrimitives,
				AddonRail = addonRail,
				SlotHost = slotHost,
				ModernControls = modernControls,
				LayoutSpec = LayoutSpec,
				ConsumerMigrationRecords = CONSUMER_MIGRATION_RECORDS,
				LayoutEngine = layoutEngine,
				RuntimeBindings = runtimeBindings,
				AdapterRecords = ADAPTER_RECORDS,
			}),
			FocusManager = focusManager,
			Localization = localization,
			ScreenGui = gui,
			Root = root,
			Portal = portal,
			Modal = modal,
			Toast = toast,
			Icons = icons,
			_destroyed = false,
			_searchEntries = {},
			_controlFactories = {},
			_windows = {},
			_activeWindow = nil,
			_pendingCategory = nil,
			_startOpen = opts.startOpen ~= false,
			ThemePresets = Library.ThemePresets,
			FontChoices = fonts:List(),
			BackgroundEffectNames = Library.BackgroundEffectsNames,
			MotionPresets = motion.Presets,
			_syncingAppearance = false,
			_defaultProfile = opts.configName or "default",
			_folderExplicit = (opts.configFolder ~= nil) or (opts.Persistence and opts.Persistence.folder ~= nil),
			_developerInspectors = {},
			_forms = {},
			_themeEditors = {},
		}, Library)
		menuServices._library = self
		controlServices.Context = self
		localization._context = self
		self.ThemeTransitions = Theme.newTransitionCoordinator(self, motion)
		maid:Set("theme.transitions", self.ThemeTransitions)
		localization:AttachContext(self)
		self.LocaleChanged = localization.LocaleChanged
		local function applyContextFont(descendant: Instance)
			if
				(descendant:IsA("TextLabel") or descendant:IsA("TextButton") or descendant:IsA("TextBox"))
				and not self:_isLocalWindowDescendant(descendant)
			then
				local textObject = descendant :: any
				Factory.applyTypography(textObject, self.Theme)
			end
		end
		maid:GiveTask(root.DescendantAdded:Connect(applyContextFont))
		local effects = BackgroundEffects.new(self)
		table.insert(created, effects)
		self.BackgroundEffects = effects
		refreshBackgroundEffectNames(BackgroundEffects.Names)
		local backdropGlass = BackdropGlass.new(runtime, budgetLedger)
		table.insert(created, backdropGlass)
		self.BackdropGlass = backdropGlass
		local antiAfk = AntiAfk.new(runtime)
		table.insert(created, antiAfk)
		self.AntiAfk = antiAfk
		local antiAfkOptions = if opts.AntiAfk ~= nil then opts.AntiAfk else opts.antiAfk
		if antiAfkOptions ~= nil and antiAfkOptions ~= false then
			local configured, configureError
			if antiAfkOptions == true then
				configured, configureError = antiAfk:SetEnabled(true)
			elseif type(antiAfkOptions) == "table" then
				configured, configureError = antiAfk:Configure(antiAfkOptions)
			else
				configured, configureError =
					false, errorResult("invalid_anti_afk", "AntiAfk must be a boolean or options table")
			end
			if not configured then
				error(configureError or errorResult("anti_afk_failed", "Could not configure Anti-AFK"), 0)
			end
		end

		local appearanceId = "potassium-appearance"
		local registered, registerError = store:Register({
			id = appearanceId,
			default = {
				theme = theme,
				background = {
					state = {
						Effect = "Off",
						Image = { Source = nil, Transparency = 0 },
					},
					options = {},
				},
				performance = false,
				keybindOverlay = false,
				gameInput = true,
			},
			normalize = function(value)
				return normalizeBackgroundAppearance(value)
			end,
			validate = function(value)
				if type(value) ~= "table" or type(value.theme) ~= "table" then
					return false, "appearance must be a table with a theme"
				end
				local storedTheme = value.theme
				if
					type(storedTheme.variant) ~= "string"
					or type(storedTheme.density) ~= "number"
					or type(storedTheme.textScale) ~= "number"
					or type(storedTheme.reducedMotion) ~= "boolean"
					or typeof(storedTheme.font) ~= "EnumItem"
					or type(storedTheme.opacity) ~= "number"
					or type(storedTheme.colors) ~= "table"
					or type(storedTheme.spacing) ~= "table"
					or type(storedTheme.radius) ~= "table"
					or type(storedTheme.typography) ~= "table"
					or type(storedTheme.states) ~= "table"
					or type(storedTheme.zIndex) ~= "table"
				then
					return false, "appearance theme must be fully resolved"
				end
				local themeValid, themeError = Theme.validate(value.theme, self.Fonts)
				if not themeValid then
					return false, themeError and themeError.message or "invalid appearance theme"
				end
				if type(value.background) ~= "table" or type(value.background.state) ~= "table" or type(value.background.options) ~= "table" then
					return false, "appearance background must contain state and options tables"
				end
				local prepared, backgroundError =
					self.BackgroundEffects:Prepare(value.background.state, value.background.options)
				if prepared == nil then
					return false, backgroundError and backgroundError.message or "appearance background is invalid"
				end
				self.BackgroundEffects:AbortPrepared(prepared)
				if
					type(value.performance) ~= "boolean"
					or type(value.keybindOverlay) ~= "boolean"
					or type(value.gameInput) ~= "boolean"
				then
					return false, "appearance flags must be booleans"
				end
				return true
			end,
			onChange = function(value)
				if not self._syncingAppearance then
					local applied, applyError = self:_applyAppearance(value)
					if not applied then
						error((applyError and applyError.message) or "Could not apply appearance")
					end
				end
			end,
		})
		if not registered then
			error(registerError or errorResult("appearance_registration_failed", "Could not register appearance"), 0)
		end
		self._appearanceId = appearanceId

		local persistence = Persistence.new(store, runtime, opts.Persistence)
		table.insert(created, persistence)
		local presentation = Presentation.new(self)
		table.insert(created, presentation)
		self.Persistence = persistence
		local workspacePersistence = if type(opts.WorkspacePersistence) == "table"
			then opts.WorkspacePersistence
			else if type(opts.workspacePersistence) == "table" then opts.workspacePersistence else nil
		local workspaceManager = WorkspaceManager.new(workspacePersistence, capability)
		table.insert(created, workspaceManager)
		self.WorkspaceManager = workspaceManager
		workspaceOrderProjector._manager = workspaceManager
		workspaceManager:SetCompositionOrderProjector(function(parentId: any, snapshot: any, projection: any)
			local consumers = { layoutEngine, controlHost, focusManager }
			local firstError = nil
			if snapshot == nil and projection == nil then
				for _, consumer in ipairs(consumers) do
					local cleared, clearError
					if type(consumer.ClearCompositionOrder) == "function" then
						cleared, clearError = consumer:ClearCompositionOrder(parentId)
					elseif consumer == controlHost then
						controlHost._compositionOrders = controlHost._compositionOrders or {}
						controlHost._compositionOrders[parentId] = nil
						cleared = true
					else
						cleared, clearError = false, "Composition order consumer cannot clear its order"
					end
					if cleared == false and firstError == nil then firstError = clearError end
				end
			else
				for _, consumer in ipairs(consumers) do
					local applied, applyError = consumer:ApplyCompositionOrder(parentId, snapshot, projection)
					if applied == false and firstError == nil then firstError = applyError end
				end
			end
			if firstError ~= nil then return false, firstError end
			return true
		end)
		local commandPalette = CommandPalette.new(self)
		table.insert(created, commandPalette)
		self.CommandPalette = commandPalette
		local function contributionFailure(code: string, message: string)
			return errorResult(code, message)
		end
		local function installMenuContribution(contribution: any)
			local schema, installError = menuSchema:Install(
				contribution.definition,
				routes,
				commandPalette,
				menuServices
			)
			if schema == nil then
				return nil, installError
			end
			return function()
				for index = #schema.actions, 1, -1 do
					commandPalette:UnregisterCommand(schema.actions[index].id)
				end
				for index = #schema.routes, 1, -1 do
					local route = schema.routes[index]
					if type(routes.Unregister) == "function" then
						routes:Unregister(route.id)
					elseif type(routes._routes) == "table" then
						routes._routes[route.id] = nil
					end
				end
				for index = #schema.runtimeBindings, 1, -1 do
					local binding = schema.runtimeBindings[index]
					menuServices:UnregisterRuntimeBinding(binding.source, binding.id)
				end
				for index = #schema.forms, 1, -1 do
					menuServices:UnregisterForm(schema.forms[index].id)
				end
				for index = #schema.resources, 1, -1 do
					menuServices:UnregisterResource(schema.resources[index].id)
				end
			end
		end
		local function installCompositionContribution(contribution: any)
			local composition, compositionError = controlHost:LowerComposition(contribution.definition)
			if composition == nil then return nil, compositionError end
			local mounted, mountError = slotHost:Mount("root", composition.root)
			if mounted == nil then return nil, mountError end
			return function()
				mounted:Unmount()
			end
		end

		local hostsConfigured, hostsError = packManager:SetHosts({
			skin = {
				Install = function(_: any, contribution: any, manifest: any)
					local registration, registerError = skinCompiler:RegisterOwned(contribution.definition, manifest.id)
					if registration == nil then return nil, registerError end
					return function()
						registration:Unregister()
					end
				end,
				Uninstall = function() end,
			},
			menu = {
				Install = function(_: any, contribution: any)
					return installMenuContribution(contribution)
				end,
				Uninstall = function() end,
			},
			layout = {
				Install = function(_: any, contribution: any)
					local previous = layoutEngine:GetSnapshot().layout
					local applied, applyError = layoutEngine:Apply(contribution.definition)
					if not applied then return nil, applyError end
					return function()
						if previous ~= nil then layoutEngine:Apply(previous) end
					end
				end,
				Uninstall = function() end,
			},
			control = {
				Install = function(_: any, contribution: any)
					return controlHost:Mount(contribution.definition)
				end,
				Uninstall = function(_: any, _: any, handle: any)
					if handle and type(handle.Unmount) == "function" then handle:Unmount() end
				end,
			},
			content = {
				Install = function(_: any, contribution: any)
					return installCompositionContribution(contribution)
				end,
				Uninstall = function() end,
			},
			container = {
				Install = function(_: any, contribution: any)
					return installCompositionContribution(contribution)
				end,
				Uninstall = function() end,
			},
		})
		if not hostsConfigured then
			error(hostsError or contributionFailure("contribution_hosts_unavailable", "Could not configure contribution hosts"), 0)
		end
		controlServices.Commands = {
			Execute = function(_: any, id: string, args: any)
				return commandPalette:ExecuteCommand(id, args)
			end,
		}
		self.Presentation = presentation
		presentation:RegisterSpotlightShortcut("potassium.spotlight", {
			keys = { Enum.KeyCode.LeftControl, Enum.KeyCode.Space },
			allowWhileTextEntry = false,
		}, nil, { Label = "Spotlight" })
		local configuredBackground = if opts.Background ~= nil then opts.Background else opts.background
		if configuredBackground ~= nil then
			local applied, applyError = self:ConfigureBackground(configuredBackground)
			if not applied then
				error(applyError, 0)
			end
		else
			if opts.backgroundEffect ~= nil then
				local applied, applyError = self:SetBackgroundEffect(opts.backgroundEffect)
				if not applied then
					error(applyError, 0)
				end
			end
			if opts.backgroundEffectColor ~= nil then
				local applied, applyError = self:SetBackgroundEffectColor(opts.backgroundEffectColor)
				if not applied then
					error(applyError, 0)
				end
			end
			if opts.backgroundImage ~= nil then
				local imageSource = opts.backgroundImage
				local imageTransparency = opts.backgroundImageTransparency
				if type(imageSource) == "table" and (imageSource.source ~= nil or imageSource.transparency ~= nil) then
					imageTransparency = imageSource.transparency
					imageSource = imageSource.source
				end
				local applied, applyError = self:SetBackgroundImage(imageSource, imageTransparency)
				if not applied then
					error(applyError, 0)
				end
			end
		end
		if opts.autoSave ~= nil then
			local saved, saveError = self:SetAutoSave(opts.autoSave == true)
			if not saved then
				error(saveError, 0)
			end
		end
		if opts.gameInput ~= nil then
			local inputOk, inputError = self:SetGameInput(opts.gameInput ~= false)
			if not inputOk then
				error(inputError, 0)
			end
		end
		task.defer(function()
			if self._destroyed then
				return
			end
			local loaded, loadError = persistence:LoadAuto()
			local benign = type(loadError) == "table"
				and (loadError.code == "AUTOLOAD_NOT_FOUND" or loadError.code == "AUTOLOAD_NOT_SET")
			if not loaded and not benign then
				self:Notify({ Title = "Autoload failed", Text = loadError.message, Type = "error" })
			end
		end)
		return self
	end, function(errorValue)
		if type(errorValue) == "table" then return errorValue end
		return debug.traceback(tostring(errorValue), 2)
	end)

	if not constructed then
		return rollback(constructionError)
	end
	return constructionError, nil
end

