function Library:_setActiveWindow(window: any)
	if window ~= nil and not window._destroyed then
		self._activeWindow = window
	end
end


function Library:_onWindowDestroyed(window: any)
	if self._activeWindow == window then
		self._activeWindow = nil
		self:_activeLiveWindow("active window selection")
	end
	self:_reflowDocked()
end

function Library:_orderWindows()
	local normal, top = {}, {}
	for _, window in ipairs(self._windows) do
		if not window._destroyed then
			table.insert(if window._alwaysOnTop then top else normal, window)
		end
	end
	for _, window in ipairs(normal) do
		window._geometry.Parent = nil
		window._geometry.Parent = self.Root
	end
	for _, window in ipairs(top) do
		window._geometry.Parent = nil
		window._geometry.Parent = self.Root
	end
end

function Library:_reflowDocked()
	local groups = {}
	for _, window in ipairs(self._windows) do
		if not window._destroyed and window._dockState then
			local edge = window._dockState.edge
			groups[edge] = groups[edge] or {}
			table.insert(groups[edge], window)
		end
	end
	local view, root = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1280, 720), self.Root.AbsolutePosition
	for edge, windows in pairs(groups) do
		table.sort(windows, function(a, b) return a._id < b._id end)
		local count = #windows
		for index, window in ipairs(windows) do
			local x, y, width, height = 0, 0, view.X, view.Y
			if edge == "left" or edge == "right" then
				width, height = math.floor(view.X / 2), math.floor(view.Y / count)
				x, y = if edge == "left" then 0 else view.X - width, (index - 1) * height
			elseif edge == "top" or edge == "bottom" then
				width, height = math.floor(view.X / count), math.floor(view.Y / 2)
				x, y = (index - 1) * width, if edge == "top" then 0 else view.Y - height
			else
				width, height = math.floor(view.X / 2), math.floor(view.Y / (count * 2))
				local right = edge == "top-right" or edge == "bottom-right"
				local bottom = edge == "bottom-left" or edge == "bottom-right"
				x, y = if right then view.X - width else 0, (if bottom then view.Y / 2 else 0) + (index - 1) * height
			end
			window._geometry.Position = UDim2.fromOffset(math.floor(x - root.X), math.floor(y - root.Y))
			window:_setLogicalSize(Vector2.new(math.max(1, math.floor(width / window._scale)), math.max(1, math.floor(height / window._scale))))
			window:_layout()
		end
	end
	self:_orderWindows()
end

function Library:_dockFromPosition(window: any)
	if window._destroyed or window._dockState then return end
	local position, view, distance = window._geometry.AbsolutePosition, workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1280, 720), window._snapDistance
	local left, right = position.X <= distance, position.X + window._geometry.AbsoluteSize.X >= view.X - distance
	local top, bottom = position.Y <= distance, position.Y + window._geometry.AbsoluteSize.Y >= view.Y - distance
	local edge = if top and left then "top-left" elseif top and right then "top-right" elseif bottom and left then "bottom-left" elseif bottom and right then "bottom-right" elseif left then "left" elseif right then "right" elseif top then "top" elseif bottom then "bottom" else nil
	if edge then window:Dock(edge) end
end
function Library:_isLocalWindowDescendant(descendant: Instance): boolean
	for _, window in ipairs(self._windows) do
		if window._inheritsTheme == false and window._frame ~= nil and descendant:IsDescendantOf(window._frame) then
			return true
		end
	end
	return false
end

function Library:_forwardWindow(operation: string, ...: any)
	self:_assertLive()
	local window, windowError = self:_activeLiveWindow(operation)
	if window == nil then
		return false, windowError
	end
	local method = window[operation]
	if type(method) ~= "function" then
		return false, errorResult("window_operation_unavailable", "Active window does not support " .. operation)
	end
	return method(window, ...)
end

function Library:_activeLiveWindow(operation: string): (any?, any?)
	local active = self._activeWindow
	if active ~= nil and not active._destroyed and type(active.GetVisibilitySnapshot) == "function" then
		local visibility = active:GetVisibilitySnapshot().visibility
		if visibility == "shown" or visibility == "minimized"
			or (visibility == "hidden" and (operation == "Show" or operation == "SetOpen" or operation == "Toggle"))
		then
			return active, nil
		end
	end
	local minimized: any = nil
	for index = #self._windows, 1, -1 do
		local candidate = self._windows[index]
		if candidate ~= nil and not candidate._destroyed and type(candidate.GetVisibilitySnapshot) == "function" then
			local visibility = candidate:GetVisibilitySnapshot().visibility
			if visibility == "shown" then
				self._activeWindow = candidate
				return candidate, nil
			elseif visibility == "minimized" and minimized == nil then
				minimized = candidate
			end
		end
	end
	if minimized ~= nil then
		self._activeWindow = minimized
		return minimized, nil
	end
	self._activeWindow = nil
	return nil, errorResult("no_active_window", "No shown or minimized window is available before calling Library:" .. operation)
end

