function Library:TransitionTheme(target: any, options: any?)
	self:_assertLive()
	local source: any
	if type(target) == "string" then
		local preset, presetError = Theme.applyPreset(target, nil, self.Fonts)
		if preset == nil then return false, presetError end
		source = preset
	elseif type(target) == "table" then
		local sourceError
		source, sourceError = mergeThemeOverrides(self.Theme, normalizeThemeCompatibility(target, self.Fonts), self.Fonts)
		if source == nil then return false, sourceError end
	else
		return false, errorResult("invalid_theme", "Theme transition target must be a preset name or overrides table")
	end
	local nextTheme, themeError = Theme.resolve(source, self.Fonts)
	if nextTheme == nil then return false, themeError end
	local plan, planError = Theme.compileTransitionPlan(options, self.Motion)
	if plan == nil then return false, planError end
	local appearance, appearanceError = self:_appearance()
	if appearance == nil then return false, appearanceError end
	appearance.theme = nextTheme
	self._pendingThemeTransitionOptions = plan
	local applied, applyError = self:_setAppearance(appearance)
	self._pendingThemeTransitionOptions = nil
	if not applied then return false, applyError end
	return true, nil
end

