function Library:CreateWindow(options: any)
	self:_assertLive()
	assert(type(options) == "table", "CreateWindow requires options table")
	local normalized = Util.deepCopy(options)
	if normalized.StartOpen == nil and normalized.startOpen == nil then
		normalized.StartOpen = self._startOpen
	end
	local function windowOption(upper: string, lower: string): any
		if normalized[upper] ~= nil then
			return normalized[upper]
		end
		return normalized[lower]
	end
	local windowTheme = windowOption("Theme", "theme")
	local hasWindowAppearance = windowTheme ~= nil
	local localTheme = {}
	if type(windowTheme) == "string" then
		local preset, presetError = Theme.applyPreset(windowTheme, nil, self.Fonts)
		if preset == nil then
			error((presetError and presetError.message) or "Window theme preset could not be resolved", 2)
		end
		localTheme = preset
	elseif type(windowTheme) == "table" then
		localTheme = normalizeThemeCompatibility(windowTheme, self.Fonts)
	elseif windowTheme ~= nil then
		error("Window Theme must be a table or preset name", 2)
	end
	local accentA, accentB = windowOption("AccentA", "accentA"), windowOption("AccentB", "accentB")
	if accentA ~= nil then
		hasWindowAppearance = true
		localTheme.accentA, localTheme.accentB = accentA, accentB or accentA
		localTheme.colors = Util.deepMerge(localTheme.colors or {}, { focus = accentA })
		localTheme.states = Util.deepMerge(localTheme.states or {}, { selected = { border = localTheme.accentB } })
	end
	local windowFont = windowOption("Font", "font")
	if windowFont ~= nil then
		hasWindowAppearance = true
		local applied, fontError = applyThemeFont(localTheme, windowFont, self.Fonts)
		if not applied then
			error((fontError and fontError.message) or "Window font could not be resolved", 2)
		end
	end
	local windowOpacity = windowOption("Opacity", "opacity")
	if windowOpacity ~= nil then
		hasWindowAppearance = true
		if type(windowOpacity) == "number" and windowOpacity > 1 then
			windowOpacity /= 100
		end
		localTheme.opacity = windowOpacity
	end
	local windowRounding = windowOption("Rounding", "rounding")
	if windowRounding ~= nil then
		hasWindowAppearance = true
		localTheme.radius = Util.deepMerge(localTheme.radius or {}, {
			sm = windowRounding,
			md = windowRounding,
			lg = windowRounding,
		})
	end
	local rowLines = windowOption("RowLines", "rowLines")
	if rowLines ~= nil then
		hasWindowAppearance = true
		localTheme.rowLines = rowLines == true
	end
	local checkboxStyle = windowOption("CheckboxStyle", "checkboxStyle")
	if checkboxStyle ~= nil then
		hasWindowAppearance = true
		localTheme.checkboxStyle = checkboxStyle == true
	end
	local layout = windowOption("Layout", "layout")
	if layout ~= nil then
		hasWindowAppearance = true
		localTheme.layout = layout
	end
	if hasWindowAppearance then
		normalized.Theme = localTheme
		normalized.theme = nil
	end
	local appearanceBefore = Util.deepCopy(select(1, self:_appearance()))
	local folderBefore = self.Persistence._folder
	local folderExplicitBefore = self._folderExplicit
	local defaultProfileBefore = self._defaultProfile
	local function rollbackCompatibility()
		if appearanceBefore then
			self:_setAppearance(appearanceBefore)
		end
		self.Persistence._folder = folderBefore
		self._folderExplicit = folderExplicitBefore
		self._defaultProfile = defaultProfileBefore
	end
	local function requireApplied(ok: any, errorValue: any)
		if ok == false then
			rollbackCompatibility()
			error((errorValue and errorValue.message) or "Window compatibility option failed", 2)
		end
	end
	if
		not self._folderExplicit
		and #self._windows == 0
		and normalized.ConfigFolder == nil
		and normalized.configFolder == nil
	then
		local folderTitle = tostring(normalized.Title or normalized.title or "PotassiumUI")
		folderTitle = string.sub(string.gsub(folderTitle, "[^%w _%-]", "-"), 1, 48)
		requireApplied(self.Persistence:SetFolder("PotassiumUI_" .. folderTitle))
		self._folderExplicit = true
	end
	if normalized.KeybindOverlay ~= nil or normalized.keybindOverlay ~= nil then
		requireApplied(self:SetKeybindOverlay((normalized.KeybindOverlay or normalized.keybindOverlay) == true))
	end
	local configuredBackground = if normalized.Background ~= nil then normalized.Background else normalized.background
	if configuredBackground ~= nil then
		requireApplied(self:ConfigureBackground(configuredBackground))
	else
		if normalized.BackgroundEffect ~= nil or normalized.backgroundEffect ~= nil then
			requireApplied(self:SetBackgroundEffect(normalized.BackgroundEffect or normalized.backgroundEffect))
		end
		if normalized.BackgroundEffectColor ~= nil or normalized.backgroundEffectColor ~= nil then
			requireApplied(
				self:SetBackgroundEffectColor(normalized.BackgroundEffectColor or normalized.backgroundEffectColor)
			)
		end
	end
	if normalized.SmartFps ~= nil or normalized.smartFps ~= nil then
		requireApplied(self:SetPerformance((normalized.SmartFps or normalized.smartFps) == true))
	end
	local configFolder = normalized.ConfigFolder or normalized.configFolder
	if configFolder ~= nil then
		requireApplied(self.Persistence:SetFolder(configFolder))
		self._folderExplicit = true
	end
	local configName = normalized.ConfigName or normalized.configName
	if configName ~= nil then
		self._defaultProfile = tostring(configName)
	end
	if normalized.GameInput ~= nil or normalized.gameInput ~= nil then
		requireApplied(self:SetGameInput((normalized.GameInput or normalized.gameInput) == true))
	end
	local existingChildren = {}
	for _, child in ipairs(self.Root:GetChildren()) do
		existingChildren[child] = true
	end
	local created, windowOrError = xpcall(function()
		return Window.new(self, normalized)
	end, debug.traceback)
	if not created then
		for _, child in ipairs(self.Root:GetChildren()) do
			if not existingChildren[child] then
				child:Destroy()
			end
		end
		rollbackCompatibility()
		error(windowOrError, 2)
	end
	local window = windowOrError
	table.insert(self._windows, window)
	self:_setActiveWindow(window)
	return window
end

