local function workspaceWindows(library: any)
	local windows = {}
	for _, window in ipairs(library._windows) do
		if not window._destroyed and type(window.GetVisibilitySnapshot) == "function" then
			local visibility = window:GetVisibilitySnapshot()
			local state = { id = window._id, visibility = visibility.visibility }
			if type(window.GetWorkspaceSnapshot) == "function" then
				local snapshot = window:GetWorkspaceSnapshot()
				if type(snapshot) == "table" then
					for key, value in pairs(snapshot) do
						if key ~= "id" and key ~= "visibility" then state[key] = Util.deepCopy(value) end
					end
				end
			else
				if type(window.GetDockState) == "function" then
					local dock = window:GetDockState()
					if type(dock) == "table" then state.dockEdge = dock.edge end
				end
				if type(window.GetScale) == "function" then state.scale = window:GetScale() end
				if type(window.GetAutoScale) == "function" then state.autoScale = window:GetAutoScale() end
				if type(window.GetNavigationSnapshot) == "function" then
					local navigation = window:GetNavigationSnapshot()
					if type(navigation) == "table" and type(navigation.routes) == "table" then
						for _, route in ipairs(navigation.routes) do
							if type(route) == "table" and route.selected == true and type(route.id) == "string" then
								state.route = route.id
								break
							end
						end
					end
				end
			end
			windows[state.id] = state
		end
	end
	return windows
end

local function workspaceWindowOrder(library: any): { string }
	local ids, byGeometry = {}, {}
	for _, window in ipairs(library._windows) do
		if not window._destroyed then byGeometry[window._geometry] = window._id end
	end
	for _, child in ipairs(library.Root:GetChildren()) do
		local id = byGeometry[child]
		if id then table.insert(ids, id) end
	end
	return ids
end

function Library:CaptureWorkspace()
	self:_assertLive()
	return {
		format = "potassium-ui-workspace",
		wireVersion = 3,
		workspaceSchemaVersion = "3",
		payload = {
			windows = workspaceWindows(self),
			windowOrder = workspaceWindowOrder(self),
			order = self.WorkspaceManager:GetCompositionOrderSnapshot(),
		},
		unknownNamespaces = {},
	}
end

