function Library:LoadWorkspace(name: string)
	self:_assertLive()
	local loaded, raw = self.Persistence:LoadWorkspace(name)
	if not loaded then
		return false, raw
	end
	if type(raw) == "table" and raw.version == 1 then
		return self:ApplyNamedWorkspace(raw)
	end
	return self:ApplyWorkspaceDocument(raw)
end
