function Library:_appearance()
	local appearance, appearanceError = self.Store:Get(self._appearanceId)
	if appearance == nil then
		return nil, appearanceError
	end
	return appearance, nil
end

function Library:_applyAppearance(appearance: any, backgroundApplied: boolean?, inputApplied: boolean?)
	appearance = normalizeBackgroundAppearance(appearance)
	if type(appearance.theme) ~= "table" then
		return false, errorResult("invalid_appearance", "Appearance must contain a theme table")
	end
	local themeDetail, themeError = Theme.resolveDetailed(appearance.theme, self.Fonts)
	if themeDetail == nil then
		return false, themeError
	end
	local nextTheme = themeDetail.theme
	local background = appearance.background
	if not backgroundApplied then
		local prepared, backgroundError = self.BackgroundEffects:Prepare(background.state, background.options)
		if prepared == nil then return false, backgroundError end
		local backgroundOk, applyError = self.BackgroundEffects:CommitPrepared(prepared)
		if not backgroundOk then return false, applyError end
	end
	self.Motion:SetReducedMotion(nextTheme.reducedMotion)
	if self.ThemeTransitions ~= nil then
		self.ThemeTransitions:Transition(themeDetail, self._pendingThemeTransitionOptions)
	else
		self.Theme = nextTheme
	end
	for _, window in ipairs(self._windows) do
		if not window._destroyed and type(window.ApplyInheritedTheme) == "function" then
			window:ApplyInheritedTheme(themeDetail, self._pendingThemeTransitionOptions)
		end
	end
	self.ThemeChanged:Fire(nextTheme)
	self.BackgroundEffects:SetLowPower(appearance.performance == true)
	self.Presentation:SetKeybindOverlayVisible(appearance.keybindOverlay == true)
	if not inputApplied then
		local inputOk, inputError = self.InputRouter:SetGameInput(appearance.gameInput ~= false)
		if not inputOk then
			return false, inputError
		end
	end
	return true, nil
end

function Library:_setAppearance(nextAppearance: any)
	nextAppearance = normalizeBackgroundAppearance(nextAppearance)
	if type(nextAppearance.theme) ~= "table" then
		return false, errorResult("invalid_appearance", "Appearance must contain a theme table")
	end
	if self._frameworkThemeMetrics ~= nil then
		local themeSource = Util.deepCopy(nextAppearance.theme)
		themeSource.metricsBase = Util.deepMerge(
			themeSource.metricsBase or themeSource.metrics or {},
			self._frameworkThemeMetrics
		)
		local frameworkTheme, frameworkThemeError = Theme.resolve(themeSource, self.Fonts)
		if frameworkTheme == nil then
			return false, frameworkThemeError
		end
		nextAppearance.theme = frameworkTheme
	end
	local themeValid, themeError = Theme.validate(nextAppearance.theme, self.Fonts)
	if not themeValid then
		return false, themeError
	end
	local background = nextAppearance.background
	local prepared, backgroundError = self.BackgroundEffects:Prepare(background.state, background.options)
	if prepared == nil then
		return false, backgroundError
	end
	local previousAppearance, appearanceError = self:_appearance()
	if previousAppearance == nil then
		self.BackgroundEffects:AbortPrepared(prepared)
		return false, appearanceError
	end
	local previousInputEnabled = previousAppearance.gameInput ~= false
	local nextInputEnabled = nextAppearance.gameInput ~= false
	local inputChanged = previousInputEnabled ~= nextInputEnabled
	if inputChanged then
		local inputOk, inputError = self.InputRouter:SetGameInput(nextInputEnabled)
		if not inputOk then
			self.BackgroundEffects:AbortPrepared(prepared)
			return false, inputError
		end
	end
	nextAppearance.background = { state = Util.deepCopy(prepared.state), options = Util.deepCopy(prepared.options) }
	local snapshot = self.BackgroundEffects:Snapshot()
	local backgroundOk, applyError = self.BackgroundEffects:CommitPrepared(prepared)
	if not backgroundOk then
		self.BackgroundEffects:Set(snapshot.state, snapshot.options)
		if inputChanged then
			self.InputRouter:SetGameInput(previousInputEnabled)
		end
		return false, applyError
	end
	self._syncingAppearance = true
	local stored, storeError = self.Store:Set(self._appearanceId, nextAppearance)
	self._syncingAppearance = false
	if not stored then
		self.BackgroundEffects:Set(snapshot.state, snapshot.options)
		if inputChanged then
			self.InputRouter:SetGameInput(previousInputEnabled)
		end
		return false, storeError
	end
	return self:_applyAppearance(nextAppearance, true, true)
end

function Library:ApplyTheme(overrides: any)
	overrides = normalizeThemeCompatibility(overrides, self.Fonts)
	local complete = type(overrides) == "table"
		and type(overrides.variant) == "string"
		and type(overrides.density) == "number"
		and type(overrides.textScale) == "number"
		and type(overrides.reducedMotion) == "boolean"
		and typeof(overrides.font) == "EnumItem"
		and type(overrides.opacity) == "number"
		and type(overrides.colors) == "table"
		and type(overrides.spacing) == "table"
		and type(overrides.radius) == "table"
		and type(overrides.metrics) == "table"
		and type(overrides.typography) == "table"
		and type(overrides.states) == "table"
		and type(overrides.zIndex) == "table"
	local source, sourceError
	if complete then
		source = overrides
	else
		source, sourceError = mergeThemeOverrides(self.Theme, overrides, self.Fonts)
	end
	if source == nil then return false, sourceError end
	local nextTheme, themeError = Theme.resolve(source, self.Fonts)
	if nextTheme == nil then
		return false, themeError or errorResult("theme_resolution_failed", "Could not resolve theme")
	end
	local appearance, appearanceError = self:_appearance()
	if appearance == nil then
		return false, appearanceError
	end
	appearance.theme = nextTheme
	return self:_setAppearance(appearance)
end
Library.SetTheme = Library.ApplyTheme

function Library:SetAccent(accentA: any, accentB: any?)
	self:_assertLive()
	if typeof(accentA) ~= "Color3" or (accentB ~= nil and typeof(accentB) ~= "Color3") then
		return false, errorResult("invalid_accent", "Accent colors must be Color3 values")
	end
	local theme = Util.deepCopy(self.Theme)
	theme.accentA = accentA
	theme.accentB = accentB or accentA
	theme.colors.focus = accentA
	theme.states.selected.border = theme.accentB
	return self:ApplyTheme(theme)
end

function Library:SetGlass(amount: any, options: any?)
	self:_assertLive()
	if type(amount) ~= "number" or amount ~= amount or amount < 0 or amount > 1 then
		return false, errorResult("invalid_glass", "Glass must be a number from 0 to 1")
	end
	if options ~= nil and type(options) ~= "table" then
		return false, errorResult("invalid_glass_options", "Glass options must be a table")
	end
	local configured = options or {}
	if configured.Blur ~= nil or configured.blur ~= nil then
		return false,
			errorResult(
				"unsupported_local_blur",
				"Per-Gui backdrop blur is unavailable; SetGlass only changes the window surface and never blurs the world"
			)
	end
	local effects = Util.deepCopy(self.Theme.effects)
	effects.glass = amount
	for optionName, token in pairs({ Tint = "glassTint", Border = "glassBorder", Frost = "glassFrost" }) do
		local value = configured[optionName]
		if value == nil then
			value = configured[string.lower(optionName)]
		end
		if value ~= nil then
			if type(value) ~= "number" or value ~= value or value < 0 or value > 1 then
				return false, errorResult("invalid_glass", optionName .. " must be a number from 0 to 1")
			end
			effects[token] = value
		end
	end
	return self:ApplyTheme({ effects = effects })
end

