		glowStyle = effects.glowStyle,
		glowEdgeLength = effects.glowEdgeLength,
		glowThickness = effects.glowThickness,
		thickness = effects.glowThickness,
		style = effects.glowStyle,
		edgeLength = effects.glowEdgeLength,
		edgeRoles = if effects.glow > 0 and effects.glowStyle == "edge"
			then { "TopRail", "RightRail", "BottomRail", "LeftRail" }
			else {},
		layers = if effects.glow <= 0
			then 0
			elseif effects.glowStyle == "edge" then 17
			elseif effects.glowSoftness >= 0.5 then 7
			else 3,
	}
end


