function Library:RegisterControl(name: any, factory: any)
	self:_assertLive()
	local key, nameError = controlKey(name)
	if key == nil then
		return false, nameError
	end
	if type(factory) ~= "function" then
		return false, errorResult("invalid_control_factory", "Control factory must be a function")
	end
	if self._controlFactories[key] ~= nil then
		return false, errorResult("duplicate_control", "Control is already registered: " .. tostring(name))
	end
	self._controlFactories[key] = {
		name = name,
		factory = factory,
	}
	return true, nil
end

function Library:UnregisterControl(name: any)
	self:_assertLive()
	local key, nameError = controlKey(name)
	if key == nil then
		return false, nameError
	end
	if self._controlFactories[key] == nil then
		return false, errorResult("unknown_control", "Unknown custom control: " .. tostring(name))
	end
	self._controlFactories[key] = nil
	return true, nil
end

function Library:_resolveControlFactory(name: any)
	local key, nameError = controlKey(name)
	if key == nil then
		return nil, nameError
	end
	local registration = self._controlFactories[key]
	if registration == nil then
		return nil, errorResult("unknown_control", "Unknown custom control: " .. tostring(name))
	end
	return registration.factory, nil
end

