function Library:ConfigureBackground(options: any)
	self:_assertLive()
	if type(options) ~= "table" then
		return false, errorResult("invalid_background", "Background configuration must be a table")
	end
	local wrapped = options.state ~= nil or options.options ~= nil
	if wrapped then
		for key in pairs(options) do
			if key ~= "state" and key ~= "options" then
				return false, errorResult("invalid_background", "Background wrapper contains an unknown key")
			end
		end
		if (options.state ~= nil and type(options.state) ~= "table") or (options.options ~= nil and type(options.options) ~= "table") then
			return false, errorResult("invalid_background", "Background wrapper state and options must be tables")
		end
	end
	local appearance, appearanceError = self:_appearance()
	if appearance == nil then
		return false, appearanceError
	end
	if wrapped then
		appearance.background = {
			state = Util.deepMerge(appearance.background.state, options.state or {}),
			options = Util.deepMerge(appearance.background.options, options.options or {}),
		}
	else
		appearance.background = {
			state = Util.deepMerge(appearance.background.state, options),
			options = Util.deepCopy(appearance.background.options),
		}
	end
	return self:_setAppearance(appearance)
end

