function Library:ApplyBackgroundPreset(name: any)
	self:_assertLive()
	local snapshot = self.BackgroundEffects:Snapshot()
	local applied, applyError = self.BackgroundEffects:ApplyPreset(name)
	if not applied then
		return false, applyError
	end
	local configured = self.BackgroundEffects:GetState()
	local appearance, appearanceError = self:_appearance()
	if appearance == nil then
		self.BackgroundEffects:Set(snapshot.state, snapshot.options)
		return false, appearanceError
	end
	appearance.background = configured
	local stored, storeError = self:_setAppearance(appearance)
	if not stored then
		self.BackgroundEffects:Set(snapshot.state, snapshot.options)
		return false, storeError
	end
	return true, nil
end

