function Library:GetWindowSnapshot()
	self:_assertLive()
	local windows = {}
	local activeIndex = nil
	for index, window in ipairs(self._windows) do
		if not window:GetOwnershipSnapshot().destroyed then
			if window == self._activeWindow then
				activeIndex = index
			end
			table.insert(windows, table.freeze({
				index = index,
				ownership = window:GetOwnershipSnapshot(),
				geometry = window:GetGeometrySnapshot(),
				navigation = window:GetNavigationSnapshot(),
				visual = window:GetVisualSnapshot(),
				search = window:GetSearchSnapshot(),
				focus = window:GetFocusSnapshot(),
				motion = window:GetMotionSnapshot(),
				slots = window:GetSlotSnapshot(),
			}))
		end
	end
	return table.freeze({ activeIndex = activeIndex, windows = table.freeze(windows) })
end

function Library:GetSearchSnapshot()
	self:_assertLive()
	local windows = self:GetWindowSnapshot().windows
	local searches = {}
	for _, window in ipairs(windows) do
		table.insert(searches, table.freeze({ index = window.index, search = window.search, entries = window.navigation.routes }))
	end
	return table.freeze({ windows = table.freeze(searches) })
end

function Library:GetOwnershipSnapshot()
	self:_assertLive()
	local windowSnapshot = self:GetWindowSnapshot()
	local tabs, sections, controls = 0, 0, 0
	for _, window in ipairs(windowSnapshot.windows) do
		tabs += window.ownership.counts.tabs
		sections += window.ownership.counts.sections
		controls += window.ownership.counts.controls
	end
	local controlSnapshot = self.ControlHost:GetSnapshot()
	local slotSnapshot = self.SlotHost:GetSnapshot()
	local addonSnapshot = self.AddonRail:GetSnapshot()
	local mountedControls, mountedSlots, mountedAddons = 0, 0, 0
	for _, handle in pairs(controlSnapshot.controls) do
		if handle.state == "mounted" then mountedControls += 1 end
	end
	for _, handle in pairs(slotSnapshot.slots) do
		if handle.state == "mounted" then mountedSlots += 1 end
	end
	for _, handle in pairs(addonSnapshot.addons) do
		if handle.state == "mounted" then mountedAddons += 1 end
	end
	return table.freeze({
		destroyed = false,
		counts = table.freeze({
			windows = #windowSnapshot.windows,
			tabs = tabs,
			sections = sections,
			controls = controls,
			mountedControls = mountedControls,
			mountedSlots = mountedSlots,
			mountedAddons = mountedAddons,
		}),
	})
end

