function Library:ConfigureAssetPolicy(options: any): (boolean, any?)
	self:_assertLive()
	if type(options) ~= "table" then
		return false, errorResult("invalid_asset_policy", "Asset policy options must be a table")
	end
	local requestedOptions = Util.deepCopy(options)
	requestedOptions.capability = self.Capabilities
	local requested, requestedError = AssetPolicy.new(requestedOptions)
	if requested == nil then
		return false, requestedError
	end
	local current = self.AssetPolicy:GetSnapshot()
	local nextSnapshot = requested:GetSnapshot()
	destroy(requested)
	if current.mode ~= nextSnapshot.mode
		or current.maxAssets ~= nextSnapshot.maxAssets
		or current.allowImageFallback ~= nextSnapshot.allowImageFallback
		or current.assetRoot ~= nextSnapshot.assetRoot
	then
		return false, errorResult("asset_policy_immutable", "Asset policy is configured at Library construction so all consumers share one policy")
	end
	return true, current
end

