function Library:Destroy()
	if self._destroyed then
		destroy(self.InputRouter)
		return
	end
	self._destroyed = true
	destroy(self.ThemeTransitions)
	destroy(self.Haptics)
	destroy(self.Fonts)
	destroy(self.AssetPolicy)
	for editor in pairs(self._themeEditors) do
		destroy(editor)
	end
	table.clear(self._themeEditors)
	destroy(self.CommandPalette)
	destroy(self.WorkspaceManager)
	destroy(self.Adaptive)
	destroy(self.Edits)
	destroy(self.Resources)
	destroy(self.Routes)

	for inspector in pairs(self._developerInspectors) do
		destroy(inspector)
	end
	table.clear(self._developerInspectors)
	table.clear(self._forms)
	destroy(self.Persistence)
	destroy(self.Presentation)
	destroy(self.BackgroundEffects)
	destroy(self.AntiAfk)
	destroy(self.Localization)
	destroy(self.LayoutEngine)
	destroy(self.SlotHost)
	destroy(self.AddonRail)
	destroy(self.ControlHost)
	for _, window in ipairs(self._windows) do
		destroy(window)
	end
	destroy(self.BackdropGlass)
	table.clear(self._windows)
	table.clear(self._searchEntries)
	table.clear(self._controlFactories)
	if self.Icons ~= nil and type(self.Icons.Destroy) == "function" then
		self.Icons.Destroy()
	end

	pcall(function()
		self.Portal:ClearAllChildren()
		self.Modal:ClearAllChildren()
		self.Toast:ClearAllChildren()
	end)
	destroy(self.FocusManager)
	destroy(self.InputRouter)
	destroy(self.Motion)
	destroy(self.MaterialRenderer)
	destroy(self.ThemeChanged)
	destroy(self.Maid)
	destroy(self.DependencyGraph)
	destroy(self.Store)
	destroy(self.Runtime)
end

Library.Unload = Library.Destroy


function Library.bootstrap(options: any?)
	if options ~= nil and type(options) ~= "table" then
		return nil, nil, errorResult("invalid_framework_options", "Framework options must be a table")
	end
	local input = options or {}
	local libraryInput = if input.Library ~= nil then input.Library else input.library
	local windowInput = if input.Window ~= nil then input.Window else input.window
	if libraryInput ~= nil and type(libraryInput) ~= "table" then
		return nil, nil, errorResult("invalid_library_options", "Framework Library options must be a table")
	end
	if windowInput ~= nil and type(windowInput) ~= "table" then
		return nil, nil, errorResult("invalid_window_options", "Framework Window options must be a table")
	end

	local function shallowCopy(source: any): any
		local result = {}
		for key, value in pairs(source or {}) do
			result[key] = value
		end
		return result
	end
	local libraryOptions = shallowCopy(libraryInput)
	local windowOptions = shallowCopy(windowInput)
	local function windowDefault(upper: string, lower: string, value: any)
		if windowOptions[upper] == nil and windowOptions[lower] == nil then
			windowOptions[upper] = value
		end
	end
	windowDefault("Id", "id", "main")
	windowDefault("Title", "title", "Potassium")
	windowDefault("Size", "size", Library.Framework.DefaultWindowSize)
	windowDefault("LayoutMode", "layoutMode", Library.Framework.LayoutMode)
	windowDefault("NavigationBreakpoint", "navigationBreakpoint", Library.Framework.NavigationBreakpoint)
	windowDefault("StartOpen", "startOpen", true)
	windowDefault("Minimizable", "minimizable", false)
	windowDefault("Resizable", "resizable", false)
	windowDefault("TabTransitionPreset", "tabTransitionPreset", "rayfieldPanel")
	windowDefault("Presence", "presence", "scale")
	windowDefault("PresencePreset", "presencePreset", "rayfieldWindow")
	windowDefault("PresenceExitPreset", "presenceExitPreset", "rayfieldHide")

	local ui, window, bootstrapError = RuntimeFreeWindow.create({
		Library = libraryOptions,
		Window = windowOptions,
	})
