	end
	return ui, window, nil
end

setmetatable(Library, {
	__call = function(_, options: any)
		local context, errorValue = Library.new(options)
		if context == nil then
			error((errorValue and errorValue.message) or "Could not create PotassiumUI", 2)
		end
		return context
	end,
})
