local CompositionDescriptors = __require("models/CompositionDescriptors")
local LayoutSpec = __require("customization/LayoutSpec")
local OrderingModel = __require("core/OrderingModel")

local CompositionBuilder = {}
CompositionBuilder.__index = CompositionBuilder

local MAX_NODES, MAX_CONTROLS, MAX_DEPTH, MAX_DIAGNOSTICS, MAX_DRAFTS = 256, 192, 16, 64, 8

local function failure(code: string, message: string, operation: string, details: any?): any
	return StructuredError.from(code, message, { domain = "composition", operation = operation, details = details })
end

local function descriptorHash(value: any): string
	local function encode(item: any): string
		if type(item) ~= "table" then return type(item) .. ":" .. tostring(item) end
		local keys = {}
		for key in pairs(item) do table.insert(keys, key) end
		table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
