end

local function addDiagnostic(draft: any, code: string, message: string, details: any?)
	if #draft._diagnostics < MAX_DIAGNOSTICS then table.insert(draft._diagnostics, table.freeze({ code = code, message = message, details = details })) end
end

local function assertLive(draft: any, operation: string): any?
	if draft._state ~= "open" then return failure("consumed_draft", "Composition drafts are single-use", operation) end
	return nil
end

local function validateId(id: any, operation: string): any?
	if type(id) ~= "string" or id == "" then return failure("invalid_composition_id", "Composition ids must be nonempty strings", operation) end
	return nil
end

local function node(kind: string, id: string, fields: any?): any
