local FLOW_OPTION_NAMES = table.freeze({
	Direction = "direction", Wrap = "wrap", Gap = "gap", MinItemWidth = "minItemWidth",
	MaxColumns = "maxColumns", Align = "align", Flex = "flex", Weight = "weight",
})
local function normalizeFlowOptions(fields: any): (any?, any?)
	for public, canonical in pairs(FLOW_OPTION_NAMES) do
		local publicValue, canonicalValue = rawget(fields, public), rawget(fields, canonical)
		if publicValue ~= nil and canonicalValue ~= nil and publicValue ~= canonicalValue then
