end

local CompositionHandle = {}
CompositionHandle.__index = CompositionHandle
function CompositionHandle:GetSnapshot(): any return table.freeze({ id = self._id, compositionId = self._compositionId, kind = self._kind, hash = self._hash, state = self._retired and "retired" or "live" }) end
