			if (not aborted or abortResult ~= true) and rollbackError == nil then
				rollbackError = failure("participant_rollback_failed", "Could not compensate a committed composition participant", "commit", { participant = record.participant, cause = if aborted then abortResult else tostring(abortResult) })
			end
		end
		for index = #attemptedParticipants, 1, -1 do abortParticipant(attemptedParticipants[index]) end
		for index = #staged, 1, -1 do
			if not attemptedSet[staged[index]] then abortParticipant(staged[index]) end
		end
		self._state = "failed"
		if rollbackError ~= nil then
			return nil, failure("composition_rollback_failed", "Could not fully compensate a committed composition", "commit", { cause = commitError, rollback = rollbackError })
		end
		return nil, commitError
	end
	-- Store commits first. Composition participants publish in reverse staging
	-- order so LayoutEngine can stage targets first but publish the common root last.
	for _, record in ipairs(staged) do
		if record.kind == "transaction" then
			table.insert(attemptedParticipants, record)
			attemptedSet[record] = true
			local committed, commitError = lifecycle(record, "commit")
			if not committed then return abortCommitted(commitError) end
		end
	end
	for index = #staged, 1, -1 do
		local record = staged[index]
		if record.kind ~= "transaction" then
			table.insert(attemptedParticipants, record)
			attemptedSet[record] = true
			local committed, commitError = lifecycle(record, "commit")
			if not committed then return abortCommitted(commitError) end
		end
	end
	table.clear(appliedOrders)
	for key, pendingOrder in pairs(pending) do
		pendingOrder.prior = self._builder._orderSnapshots[key]
		local applied, applyError = self._builder:_applyOrder(key, pendingOrder.parentId, pendingOrder.snapshot, pendingOrder.projection)
		if not applied then return abortCommitted(applyError) end
		table.insert(appliedOrders, { key = key, pending = pendingOrder })
	end
	for _, applied in ipairs(appliedOrders) do
		local committed, commitError = nextOrders[applied.key]:CommitStaged(applied.pending.candidate)
		if committed == nil then return abortCommitted(commitError) end
		table.insert(committedOrders, { model = nextOrders[applied.key], candidate = applied.pending.candidate })
		self._builder._orders[applied.key] = nextOrders[applied.key]
	end
	local handles, nextHandles = self._builder._committed[self._id] and self._builder._committed[self._id].handles or {}, {}
	for id, draftNode in pairs(self._ids) do
		local hash = descriptorHash(if draftNode.descriptor then draftNode.descriptor else exportNode(draftNode))
		local existing = handles[id]
		if existing and not existing._retired then
			existing._hash, existing._kind, existing._parentId, existing._orderKey =
				hash, draftNode.kind, draftNode._parent and draftNode._parent.id,
				draftNode._parent and orderKey(self._id, draftNode._parent.id) or nil
			nextHandles[id] = existing
		else
			local handle = draftNode._handle or {}
			handle._id, handle._hash, handle._builder, handle._compositionId, handle._kind, handle._parentId, handle._orderKey =
				id, hash, self._builder, self._id, draftNode.kind, draftNode._parent and draftNode._parent.id,
				draftNode._parent and orderKey(self._id, draftNode._parent.id) or nil
			nextHandles[id] = setmetatable(handle, CompositionHandle)
		end
	end
	for id, handle in pairs(handles) do
		if nextHandles[id] == nil then handle._retired = true end
	end
	local committedPlan = table.freeze(plan)
	local activeParents = {}
	for _, pendingOrder in pairs(pending) do activeParents[pendingOrder.parentId] = true end
	for compositionId, committed in pairs(self._builder._committed) do
		if compositionId ~= self._id then
			for _, handle in pairs(committed.handles or {}) do handle._retired = true end
		end
		for key, order in pairs(committed.orders or {}) do
			if compositionId ~= self._id or nextOrders[key] == nil then
				local oldParent = order:GetSnapshot().parentId
				if activeParents[oldParent] ~= true then self._builder:_clearOrder(oldParent) end
				self._builder._orders[key], self._builder._orderSnapshots[key] = nil, nil
				order:Destroy()
			end
		end
		if compositionId ~= self._id then self._builder._committed[compositionId] = nil end
	end
	self._builder._committed[self._id] = { plan = committedPlan, handles = nextHandles, orders = nextOrders }
	self._builder._activeCompositionId = self._id
	self._state = "committed"
	for pass = 1, 2 do
		for _, record in ipairs(staged) do
			if record.finalize ~= nil and ((pass == 1 and record.kind == "transaction") or (pass == 2 and record.kind ~= "transaction")) then
				pcall(record.finalize)
			end
		end
	end
	return table.freeze({ id = self._id, plan = committedPlan, handles = table.freeze(nextHandles), diagnostics = table.freeze(self._diagnostics) }), nil
end
function CompositionBuilder.new(options: any?): any
	options = options or {}
	return setmetatable({ _participants = options.participants or {}, _committed = {}, _orders = {}, _orderSnapshots = {}, _activeDrafts = 0, _activeCompositionId = nil, _orderProjector = options.orderProjector, _layoutEngine = options.layoutEngine, _focusManager = options.focusManager, _workspace = options.workspace }, CompositionBuilder)
end
function CompositionBuilder:_clearOrder(parentId: string)
	for _, seam in ipairs({ self._layoutEngine or false, self._focusManager or false, self._workspace or false }) do
		if type(seam) == "table" and type(seam.ClearCompositionOrder) == "function" then pcall(seam.ClearCompositionOrder, seam, parentId) end
	end
end
function CompositionBuilder:_restoreOrder(storageKey: string, parentId: string, previous: any)
	for _, seam in ipairs({ self._workspace or false, self._focusManager or false, self._layoutEngine or false }) do
		if type(seam) == "table" then
			if previous ~= nil and type(seam.ApplyCompositionOrder) == "function" then
				pcall(seam.ApplyCompositionOrder, seam, parentId, previous.snapshot, previous.layout)
			elseif previous == nil and type(seam.ClearCompositionOrder) == "function" then
				pcall(seam.ClearCompositionOrder, seam, parentId)
			end
		end
	end
	if previous ~= nil and type(self._orderProjector) == "function" then
		pcall(self._orderProjector, parentId, previous.snapshot, previous.layout, false)
	end
	self._orderSnapshots[storageKey] = previous
end
function CompositionBuilder:_preflightOrder(parentId: string?, snapshot: any, projection: any, skipLayout: boolean?): (boolean, any?)
	if parentId == nil then return true, nil end
	if type(projection) ~= "table" then return false, failure("invalid_order_projection", "Composition order projection is unavailable", "move") end
	local function invoke(callback: any): (boolean, any?)
		local ok, accepted, projectionError = pcall(callback, parentId, snapshot, projection)
		if not ok then return false, failure("order_projection_failed", tostring(accepted), "preflight") end
		if accepted == false then return false, projectionError or failure("order_projection_failed", "A composition order consumer rejected the projection", "preflight") end
		return true, nil
	end
	local seams = { self._focusManager or false, self._workspace or false }
	if not skipLayout then table.insert(seams, 1, self._layoutEngine or false) end
	for _, seam in ipairs(seams) do
		if type(seam) == "table" and type(seam.PreflightCompositionOrder) == "function" then
			local accepted, seamError = invoke(function(parent, orderSnapshot, layout) return seam:PreflightCompositionOrder(parent, orderSnapshot, layout) end)
			if not accepted then return false, seamError end
		end
	end
	if type(self._orderProjector) == "function" then
		local accepted, projectorError = invoke(function(parent, orderSnapshot, layout) return self._orderProjector(parent, orderSnapshot, layout, true) end)
		if not accepted then return false, projectorError end
	end
	return true, nil
end
function CompositionBuilder:_applyOrder(storageKey: string, parentId: string, snapshot: any, projection: any): (boolean, any?)
	local previous = self._orderSnapshots[storageKey]
	local function invoke(callback: any): (boolean, any?)
		local ok, accepted, projectionError = pcall(callback, parentId, snapshot, projection)
		if not ok then return false, failure("order_projection_failed", tostring(accepted), "apply") end
		if accepted == false then return false, projectionError or failure("order_projection_failed", "A composition order consumer rejected the projection", "apply") end
		return true, nil
	end
	for _, seam in ipairs({ self._layoutEngine or false, self._focusManager or false, self._workspace or false }) do
		if type(seam) == "table" and type(seam.ApplyCompositionOrder) == "function" then
			local accepted, seamError = invoke(function(parent, orderSnapshot, layout) return seam:ApplyCompositionOrder(parent, orderSnapshot, layout) end)
			if not accepted then
				self:_restoreOrder(storageKey, parentId, previous)
				return false, seamError
			end
		end
	end
	if type(self._orderProjector) == "function" then
		local accepted, projectorError = invoke(function(parent, orderSnapshot, layout) return self._orderProjector(parent, orderSnapshot, layout, false) end)
		if not accepted then
			self:_restoreOrder(storageKey, parentId, previous)
			return false, projectorError
		end
	end
	self._orderSnapshots[storageKey] = table.freeze({ snapshot = snapshot, layout = projection })
	return true, nil
end
function CompositionBuilder:_projectOrder(storageKey: string, parentId: string, snapshot: any, providedProjection: any?): (boolean, any?)
	local projection = providedProjection or (snapshot and self._orders[storageKey] and self._orders[storageKey]:ProjectLayoutOrders())
	local accepted, preflightError = self:_preflightOrder(parentId, snapshot, projection)
	if not accepted then return false, preflightError end
	return self:_applyOrder(storageKey, parentId, snapshot, projection)
end
function CompositionBuilder:GetOrderSnapshot(parentId: any, compositionId: any?): any
	if type(compositionId) == "string" then return self._orderSnapshots[orderKey(compositionId, parentId)] end
	local found = nil
	for key, value in pairs(self._orderSnapshots) do
		local separator = string.find(key, "\0", 1, true)
		if separator ~= nil and string.sub(key, separator + 1) == parentId then
			if found ~= nil then return nil end
			found = value
		end
	end
	return found
end
function CompositionBuilder:GetOrderSnapshots(): any local copy = {}; for id, value in pairs(self._orderSnapshots) do copy[id] = value end; return table.freeze(copy) end
function CompositionBuilder:RestoreOrderSnapshot(snapshot: any): (boolean, any?)
	if type(snapshot) ~= "table" or type(snapshot.compositionId) ~= "string" or type(snapshot.parentId) ~= "string" or type(snapshot.ids) ~= "table" then
		return false, failure("invalid_order_snapshot", "Persisted order snapshot requires compositionId, parentId, and ids", "restoreOrder")
	end
	local key = orderKey(snapshot.compositionId, snapshot.parentId)
	local order, created = self._orders[key], false
	if order == nil then
		local createError
		order, createError = OrderingModel.new(snapshot.parentId, snapshot.ids)
		if order == nil then return false, createError end
		created = true
	end
	local staged, stageError = order:Stage(snapshot.ids); if staged == nil then return false, stageError end
	local nextSnapshot, snapshotError = order:GetStagedSnapshot(staged)
	if nextSnapshot == nil then return false, snapshotError end
	local prior = self._orderSnapshots[key]
	local projected, projectionError = self:_projectOrder(key, snapshot.parentId, nextSnapshot, order:ProjectLayoutOrdersFor(nextSnapshot.ids))
	if not projected then return false, projectionError end
	local committed, commitError = order:CommitStaged(staged)
	if committed == nil then
		self:_restoreOrder(key, snapshot.parentId, prior)
		return false, commitError
	end
	if created then self._orders[key] = order end
	return true, nil
end
function CompositionBuilder:BeginComposition(options: any): (any?, any?)
	local id, window = options, nil
	if type(options) == "table" then id, window = options.Id or options.id, options.Window or options.window end
	local idError = validateId(id, "begin"); if idError then return nil, idError end
	if self._activeDrafts >= MAX_DRAFTS then return nil, failure("active_draft_limit", "At most eight composition drafts may be active", "begin") end
	self._activeDrafts += 1
	local rootId = if string.find(id, ":", 1, true) ~= nil then id .. "-root" else id .. ":root"
	local root = { kind = "column", id = rootId, _depth = 0, _children = {} }
	local draft = setmetatable({ _builder = self, _id = id, _window = window, _root = root, _ids = { [root.id] = root }, _nodes = 1, _controls = 0, _diagnostics = {}, _state = "open" }, Draft); root._draft = draft
	return draft, nil
end
return CompositionBuilder

end

__modules["api/StateView"] = function()
--!strict

-- StateView is the single public mutation façade over Store.
local StructuredError = __require("core/StructuredError")

local StateView = {}

export type StateView = {
	Get: (self: StateView, id: string) -> (any, any?),
	Set: (self: StateView, id: string, value: any, options: any?) -> (boolean, any?),
	Reset: (self: StateView, id: string, options: any?) -> (boolean, any?),
	Observe: (self: StateView, id: string, callback: (any, any, string, any) -> ()) -> (any?, any?),
	List: (self: StateView) -> { string },
}

local function optionError(code: string, message: string, path: string?): any
	return StructuredError.from(code, message, {
		domain = "state",
		operation = "normalizeOptions",
		path = path,
	})
end

local function normalizeOptions(options: any): (any?, any?)
	if options == nil then return table.freeze({}), nil end
	if type(options) ~= "table" then
		return nil, optionError("invalid_options", "StateView options must be a table", "options")
	end
	local normalized = {}
	for key, value in pairs(options) do
		if key == "Source" then
			if type(value) ~= "string" then
				return nil, optionError("invalid_source", "StateView Source must be a string", "options.Source")
			end
			normalized.Source = value
		elseif key == "SuppressDefinitionCallback" then
			if type(value) ~= "boolean" then
				return nil, optionError(
					"invalid_suppress_definition_callback",
					"SuppressDefinitionCallback must be a boolean",
					"options.SuppressDefinitionCallback"
				)
			end
			normalized.SuppressDefinitionCallback = value
		else
			return nil, optionError("unknown_option", "StateView options contain an unknown field", "options." .. tostring(key))
		end
	end
	return table.freeze(normalized), nil
end

function StateView.new(store: any): StateView
	assert(type(store) == "table" and type(store.Get) == "function" and type(store.Set) == "function" and type(store.Reset) == "function", "StateView.new requires a Store")
	local view = {}
	function view:Get(id: string): (any, any?) return store:Get(id) end
	local function mutate(method: string, id: string, value: any, options: any?): (boolean, any?)
		local normalized, optionError = normalizeOptions(options)
		if normalized == nil then return false, optionError end
		local function apply() return if method == "set" then store:Set(id, value, normalized.Source) else store:Reset(id, normalized.Source) end
		if normalized.SuppressDefinitionCallback then return store:SuppressDefinitionCallback(apply) end
		return apply()
	end
	function view:Set(id: string, value: any, options: any?): (boolean, any?) return mutate("set", id, value, options) end
	function view:Reset(id: string, options: any?): (boolean, any?) return mutate("reset", id, nil, options) end
	function view:Observe(id: string, callback: (any, any, string, any) -> ()): (any?, any?) return store:Subscribe(id, callback) end
	function view:List(): { string } return store:List() end
	return table.freeze(view) :: any
end

return StateView

end

__modules["components/Controls"] = function()
--!strict
local Maid = __require("core/Maid")
local AsyncProvider = __require("core/AsyncProvider")
local Store = __require("core/Store")
local Util = __require("core/Util")
local Theme = __require("core/Theme")
local Factory = __require("ui/Factory")
local Signal = __require("core/Signal")
local DataControls = __require("components/DataControls")
local TweenService = game:GetService("TweenService")

local Controls = {}
local MAX_RESULTS = 100
local RAYFIELD_TOGGLE_MOTION = TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
local RAYFIELD_DROPDOWN_REVEAL_MOTION = TweenInfo.new(0.2, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
local RAYFIELD_DROPDOWN_CHEVRON_MOTION = TweenInfo.new(0.2, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
local RAYFIELD_DROPDOWN_PANEL_MOTION = TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local RAYFIELD_DROPDOWN_OPTION_MOTION = TweenInfo.new(0.2, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
local RAYFIELD_DROPDOWN_HOVER_MOTION = TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local RAYFIELD_SLIDER_HOVER_MOTION = TweenInfo.new(0.45, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
local RAYFIELD_SLIDER_HELD_MOTION = TweenInfo.new(0.3, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
local RAYFIELD_SLIDER_FOLLOW_MOTION = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local BLACK = Color3.new(0, 0, 0)
local WHITE = Color3.new(1, 1, 1)

local function linearColorChannel(channel: number): number
	return if channel <= 0.04045 then channel / 12.92 else ((channel + 0.055) / 1.055) ^ 2.4
end

local function colorLuminance(color: Color3): number
	return 0.2126 * linearColorChannel(color.R)
		+ 0.7152 * linearColorChannel(color.G)
		+ 0.0722 * linearColorChannel(color.B)
end

local function colorContrast(first: Color3, second: Color3): number
	local lighter = colorLuminance(first)
	local darker = colorLuminance(second)
	if lighter < darker then
		lighter, darker = darker, lighter
	end
	return (lighter + 0.05) / (darker + 0.05)
end

local function contrastingInk(background: Color3, preferred: Color3): Color3
	if colorContrast(background, preferred) >= 3 then
		return preferred
	end
	return if colorLuminance(background) > 0.179 then BLACK else WHITE
end

local function motionTween(handle: any, instance: Instance, properties: { [string]: any }, info: TweenInfo)
	local motion = handle._context and handle._context.Motion
	if motion and type(motion.Tween) == "function" then
		motion:Tween(instance, properties, nil, info)
		return
	end
	for property, value in pairs(properties) do
		(instance :: any)[property] = value
	end
end
local function call(fn: any, ...: any)
	if type(fn) == "function" then
		Util.safeCallback(fn, ...)
	end
end
local function frozenValueSnapshot(value: any): any
	if type(value) ~= "table" then return value end
	local copy = {}
	for key, nested in pairs(value) do copy[key] = frozenValueSnapshot(nested) end
	return table.freeze(copy)
end
local function id(section: any, o: any, name: string): string
	assert(type(o) == "table", name .. " requires options")
	local localId = o.Id
	if type(localId) ~= "string" or localId == "" then
		localId = name .. "-" .. tostring(o.Title or o.Name or name)
	end
	local result = section:_fullId(Util.sanitizeId(localId))
	assert(result == Util.sanitizeId(result), "Id must be sanitized")
	return result
end

local function positional(o: any, title: any, default: any, callback: any): any
	if type(o) == "table" then
		return o
	end
	return { Title = o, Default = default, Callback = callback, _positional = true }
end
local function asKeyCode(value: any): any
	if typeof(value) == "EnumItem" and value.EnumType == Enum.KeyCode then
		return value
	end
	if type(value) == "string" then
		local needle = string.lower(value)
		for _, keyCode in ipairs(Enum.KeyCode:GetEnumItems()) do
			if string.lower(keyCode.Name) == needle then
				return keyCode
			end
		end
	end
	return value
end
local function active(h: any): boolean
	return not h._destroyed and h._visible and not h._locked
end
local function effectivelyVisible(root: Instance): boolean
	local ancestor: Instance? = root
	while ancestor do
		if ancestor:IsA("GuiObject") and not ancestor.Visible then return false end
		if ancestor:IsA("LayerCollector") and not ancestor.Enabled then return false end
		ancestor = ancestor.Parent
	end
	return true
end
local function selectionHaptic(h: any)
	local haptics = h._context and h._context.Haptics
	if haptics and type(haptics.Pulse) == "function" then
		haptics:Pulse("selection", function()
			return active(h)
		end)
	end
end
type DropdownPresenceOptions = {
	enter: string,
	exit: string,
}

local function dropdownPresence(value: any, motion: any, multi: boolean): DropdownPresenceOptions?
	if value == false then
		return nil
	end
	local options: DropdownPresenceOptions
	if value == nil or value == true then
		options = if multi
			then { enter = "multiDropdownEnter", exit = "multiDropdownExit" }
			else { enter = "rayfieldPanel", exit = "rayfieldPanel" }
	elseif type(value) == "string" and value ~= "" then
		options = { enter = value, exit = "exit" }
	elseif type(value) == "table" then
		local enter = if value.Enter ~= nil then value.Enter else value.enter
		local exit = if value.Exit ~= nil then value.Exit else value.exit
		enter = if enter == nil then "enter" else enter
		exit = if exit == nil then "exit" else exit
		assert(type(enter) == "string" and enter ~= "", "Dropdown Presence.Enter must be a non-empty preset name")
		assert(type(exit) == "string" and exit ~= "", "Dropdown Presence.Exit must be a non-empty preset name")
		options = { enter = enter, exit = exit }
	else
		error("Dropdown Presence must be false, true, a preset name, or { Enter, Exit }", 3)
	end
	assert(type(motion) == "table" and type(motion.GetMotionPreset) == "function", "Dropdown Presence requires Motion")
	assert(motion:GetMotionPreset(options.enter) ~= nil, "Dropdown Presence.Enter must name a registered motion preset")
	assert(motion:GetMotionPreset(options.exit) ~= nil, "Dropdown Presence.Exit must name a registered motion preset")
	return options
end

local function dropdownAnimate(
	h: any,
	maid: any,
	instance: Instance,
	properties: { [string]: any },
	info: TweenInfo,
	presetName: string?
): any
	local motion = h._context.Motion
	if motion and type(motion.Animate) == "function" then
		local presetOrOptions: any = if presetName ~= nil
			then presetName
			else {
				Duration = info.Time,
				EasingStyle = info.EasingStyle,
				EasingDirection = info.EasingDirection,
			}
		local handle = motion:Animate(instance, properties, presetOrOptions)
		if maid then
			maid:GiveTask(handle)
		end
		return handle
	end
	for property, value in pairs(properties) do
		(instance :: any)[property] = value
	end
	return nil
end
local function dropdownMotionDuration(h: any, presetName: string?, fallback: number): number
	if presetName ~= nil then
		local preset = h._context.Motion:GetMotionPreset(presetName)
		if preset ~= nil then
			return preset.Duration
		end
	end
	return fallback
end
local function staticRisk(h: any, v: string)
	if h._title then
		h._title.TextColor3 = if v == "danger"
			then h._context.Theme.states.danger.text
			else h._context.Theme.colors.text
	end
end

local function attachAsyncProvider(handle: any, options: any, applyItems: ({ any }) -> ())
	if type(options.Provider) ~= "function" then
		return
	end
	local theme = handle._context.Theme
	local indicator = Factory.text(
		handle.Root,
		"",
		theme.typography.caption * theme.textScale,
		theme.colors.textMuted,
		{
			Name = "ProviderState",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.new(0, 8, 1, -4),
			Size = UDim2.new(1, -16, 0, 18),
			TextTruncate = Enum.TextTruncate.AtEnd,
			TextXAlignment = Enum.TextXAlignment.Left,
			Visible = false,
			theme = theme,
		}
	)
	local function updateIndicator(state: string, message: string?)
		if state == "ready" then
			indicator.Visible = false
			return
		end
		local text = ""
		if state == "loading" then
			text = "Loading…"
		elseif state == "empty" then
			text = "No items"
		elseif state == "error" then
			text = "Unable to load: " .. tostring(message or "Unknown error")
		elseif state == "cancelled" then
			text = "Refresh cancelled"
		end
		indicator.Text = text
		indicator.TextColor3 = if state == "error" then theme.states.danger.text else theme.colors.textMuted
		indicator.Visible = text ~= ""
	end
	local controller = AsyncProvider.new({
		Provider = options.Provider,
		RefreshInterval = options.RefreshInterval,
		Timeout = options.Timeout,
		RetryCount = options.RetryCount,
		RetryDelay = options.RetryDelay,
		LoadImmediately = options.LoadImmediately,
		ClearOnError = options.ClearOnError,
		Apply = applyItems,
		OnStateChanged = updateIndicator,
	})
	handle._maid:GiveTask(controller)
	handle.ProviderIndicator = indicator
	handle.Refresh = function(self: any)
		controller:Refresh()
		return self
	end
	handle.CancelRefresh = function(self: any)
		controller:CancelRefresh()
		return self
	end
	handle.GetProviderState = function(_self: any)
		return controller:GetProviderState()
	end
	handle.SetProvider = function(self: any, provider: any)
		controller:SetProvider(provider)
		return self
	end
end

local function apply(b: TextButton, h: any, selected: boolean?)
	local s = if h._locked
		then "disabled"
		elseif h._risk == "danger" then "danger"
		elseif selected then "selected"
		else "default"
	Factory.setButtonState(b, s, h._context.Theme)
	Factory.setInteractive(b, active(h), h._context.Theme)
end
local function valueText(v: any): string
	return tostring(if type(v) == "table" then v.Title or v.Name or v.Value else v)
end
local function valueOf(v: any): any
	return if type(v) == "table" and v.Value ~= nil then v.Value else v
end

local function dependencyIds(dependencies: any): { string }
	local values = if type(dependencies) == "table" and dependencies.Id == nil then dependencies else { dependencies }
	assert(#values > 0, "Dependencies require at least one control or id")
	local result = {}
	for index, dependency in ipairs(values) do
		local dependencyId = if type(dependency) == "table" then dependency.Id else dependency
		assert(
			type(dependencyId) == "string" and dependencyId ~= "",
			"Dependency " .. tostring(index) .. " requires control or id"
		)
		table.insert(result, dependencyId)
	end
	return result
end

local function dependencyCondition(predicate: any, values: { any }, count: number): boolean
	if type(predicate) == "function" then
		return not not predicate(table.unpack(values, 1, count))
	end
	if predicate ~= nil then
		assert(count == 1, "Multiple dependencies require a predicate function")
		return values[1] == predicate
	end
	for index = 1, count do
		if not values[index] then
			return false
		end
	end
	return true
end

local function bindDependency(handle: any, key: string, dependencies: any, callback: (...any) -> ())
	local sources = dependencyIds(dependencies)
	local target = handle.Id
	if type(target) ~= "string" or target == "" then
		target = handle._dependencyNode
		if target == nil then
			target = "control:" .. tostring(handle)
			handle._dependencyNode = target
		end
	end
	local graph = handle._context.DependencyGraph
	assert(graph ~= nil and type(graph.Bind) == "function", "DependencyGraph is unavailable")
	local binding, bindError = graph:Bind(target, key, sources, callback)
	if binding == nil then
		error(bindError.message, 3)
	end
	handle._maid:Set("dependency-" .. key, binding)
	return handle
end

local function metric(context: any, name: string): number
	local value = Theme.metric(context.Theme, name)
	if name == "inputHeight" or name == "hitTargetMin" then
		local metricsBase = context.Theme.metricsBase
		local minimum = if type(metricsBase) == "table" and type(metricsBase.hitTargetMin) == "number"
			then metricsBase.hitTargetMin
			else value
		return math.max(value, minimum)
	end
	return value
end

local function controlHeight(context: any, baseHeight: number, unscaled: boolean, metricName: string?): number
	if metricName ~= nil then
		return math.max(metric(context, "hitTargetMin"), metric(context, metricName))
	end
	if unscaled then
		return baseHeight
	end
	local density = tonumber(context.Theme.density) or 1
	local minimum = if context.Runtime and context.Runtime.services and context.Runtime.services.UserInputService.TouchEnabled
		then math.max(40, metric(context, "hitTargetMin"))
		else metric(context, "hitTargetMin")
	return math.max(minimum, math.floor(baseHeight * density + 0.5))
end

local focusedHandles = setmetatable({}, { __mode = "k" }) :: { [any]: any }

local function setFocusState(handle: any, focused: boolean, reason: string)
	local manager = handle._context and handle._context.FocusManager
	if focused then
		local previous = if manager then focusedHandles[manager] else nil
		if previous == handle then return end
		if previous ~= nil then
			previous._focusChanged:Fire(false, reason)
		end
		if manager then focusedHandles[manager] = handle end
		handle._focusChanged:Fire(true, reason)
	elseif manager == nil or focusedHandles[manager] == handle then
		if manager then focusedHandles[manager] = nil end
		handle._focusChanged:Fire(false, reason)
	end
end

local function static(section: any, o: any, height: number, metricName: string?): any
	local baseHeight = height
	local scaledHeight = controlHeight(section._context, baseHeight, o.UnscaledHeight == true, metricName)
	local root = Factory.make("Frame", {
		BackgroundTransparency = 1,
		Size = if o._inline then UDim2.fromOffset(88, scaledHeight) else UDim2.new(1, 0, 0, scaledHeight),
		AnchorPoint = Vector2.new(),
		Position = UDim2.new(),
		LayoutOrder = o._inlineOrder or section:_nextOrder(),
	}, o._parent or section._content) :: Frame
	root:SetAttribute("BaseHeight", baseHeight)
	root:SetAttribute("BaseMetric", metricName)
	root:SetAttribute("UnscaledHeight", o.UnscaledHeight == true)
	local maid = Maid.new()
	local rowLine = Factory.make("Frame", {
		Name = "PotassiumRowLine",
		BackgroundColor3 = section._context.Theme.colors.border,
		BorderSizePixel = 0,
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 0, 1, 0),
		Size = UDim2.new(1, 0, 0, 1),
		Visible = section._context.Theme.rowLines == true,
	}, root) :: Frame
	Factory.make("UIGradient", {
		Name = "PotassiumRowLineFade",
		Rotation = 0,
		Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1),
			NumberSequenceKeypoint.new(0.5, 0.18),
			NumberSequenceKeypoint.new(1, 1),
		}),
	}, rowLine)
	if section._context.ThemeChanged then
		maid:GiveTask(section._context.ThemeChanged:Connect(function(theme: any)
			rowLine.BackgroundColor3, rowLine.Visible = theme.colors.border, theme.rowLines == true
			local nextHeight = controlHeight(section._context, baseHeight, o.UnscaledHeight == true, metricName)
			root.Size = if o._inline then UDim2.fromOffset(88, nextHeight) else UDim2.new(1, 0, 0, nextHeight)
		end))
	end
	local h = {
		Root = root,
		_maid = maid,
		_destroyed = false,
		_visible = true,
		_context = section._context,
		_baseHeight = baseHeight,
		_focusChanged = Signal.new(),
		_section = section,
	}
	maid:GiveTask(h._focusChanged)
	maid:GiveTask(function()
		local manager = h._context and h._context.FocusManager
		if manager and focusedHandles[manager] == h then focusedHandles[manager] = nil end
	end)
	function h:ObserveFocusChanged(callback: (focused: boolean, reason: string) -> ())
		assert(type(callback) == "function", "Focus observer must be a function")
		return self._focusChanged:Connect(callback)
	end
	function h:Focus(reason: string?): boolean
		local object = self._focusObject
		local manager = self._context.FocusManager
		if self._destroyed or object == nil or manager == nil or type(manager.SetFocused) ~= "function" then
			return false
		end
		local focused = manager:SetFocused(object, reason or "control")
		if focused then
			setFocusState(self, true, reason or "control")
		end
		return focused
	end
	function h:SetVisible(visible: boolean)
		self._visible = visible == true
		root.Visible = self._visible
		return self
	end
	function h:SetText(v: any)
		local target = self._text or self._title
		if target then
			target.Text = tostring(v)
			if type(self._syncTextMetadata) == "function" then
				self:_syncTextMetadata()
			end
		end
		return self
	end
	function h:SetTranslation(key: any, params: any?, property: any?)
		local localization = self._context.Localization
		assert(localization ~= nil and type(localization.CreateLocalizedText) == "function", "Localization is unavailable")
		local attribute = if property == "Description" or property == "EmptyText" then tostring(property) else nil
		local target = if property == "Title" then self._title elseif property == "Text" or property == nil then (self._text or self._title) else self[property]
		assert(attribute ~= nil or target ~= nil, "Translation target is unavailable")
		local values = type(params) == "table" and Util.deepCopy(params) or {}
		if values.Default == nil and target ~= nil then values.Default = target.Text end
		local localized = localization:CreateLocalizedText(key, values)
		local function applyText(text: string)
			if self._destroyed then return end
			if attribute then
				self.Root:SetAttribute(attribute, text)
				if property == "Description" and self._description then
					self._description.Text = text
				end
				if attribute == "Description" then self.Root:SetAttribute("AccessibleDescription", text) end
				if type(self._syncTextMetadata) == "function" then
					self:_syncTextMetadata()
				end
				return
			end
			target.Text = text
			if type(self._syncTextMetadata) == "function" then
				self:_syncTextMetadata()
			end
			local direction = localization:GetDirection()
			target:SetAttribute("LayoutDirection", direction)
			if target:IsA("TextLabel") or target:IsA("TextButton") or target:IsA("TextBox") then
				target.TextXAlignment = if direction == "RTL" then Enum.TextXAlignment.Right else Enum.TextXAlignment.Left
			end
			self.Root:SetAttribute("LayoutDirection", direction)
		end
		self._maid:Set("translation-" .. tostring(property or "Text"), localized)
		self._maid:GiveTask(localized:Subscribe(applyText))
		applyText(localized:Get())
		return self
	end
	function h:Tooltip(v: any)
		self._tooltip = tostring(v)
		local presentation = self._context.Presentation
		if presentation and type(presentation.RegisterTooltip) == "function" then
			presentation:RegisterTooltip(root, self._tooltip, function()
				return self._context.Theme
			end, self._context.ThemeChanged)
		else
			root:SetAttribute("Tooltip", self._tooltip)
		end
		return self
	end
	function h:SetLocked(_v: boolean)
		return self
	end
	function h:SetRisk(v: boolean | string)
		self._risk = if v == true then "danger" elseif v == false then "default" else v
		if self._title then
			self._title.TextColor3 = if self._risk == "danger"
				then self._context.Theme.states.danger.text
				else self._context.Theme.colors.text
		end
		return self
	end
	function h:SetColor(color: Color3)
		if self._title then
			self._title.TextColor3 = color
		end
		return self
	end
	function h:SetVisibleWhen(dependencies: any, predicate: any)
		return bindDependency(self, "visible", dependencies, function(...: any)
			local values = table.pack(...)
			self:SetVisible(dependencyCondition(predicate, values, values.n))
		end)
	end
	function h:SetEnabledWhen(dependencies: any, predicate: any)
		return bindDependency(self, "enabled", dependencies, function(...: any)
			local values = table.pack(...)
			self:SetLocked(not dependencyCondition(predicate, values, values.n))
		end)
	end
	function h:SetValueFrom(dependencies: any, transform: any)
		assert(type(self.Set) == "function" and type(self.Id) == "string", "SetValueFrom requires a value control")
		return bindDependency(self, "value", dependencies, function(...: any)
			local values = table.pack(...)
			local value
			if type(transform) == "function" then
				value = transform(table.unpack(values, 1, values.n))
			else
				assert(values.n == 1, "Multiple dependencies require a transform function")
				value = values[1]
			end
			self:Set(value)
		end)
	end
	function h:DependsOn(dependencies: any, predicate: any)
		return self:SetVisibleWhen(dependencies, predicate)
	end
	function h:Destroy()
		if self._destroyed then
			return
		end
		self._destroyed = true
		maid:Destroy()
		root:Destroy()
	end
	if o.DescriptionKey then
		h:SetTranslation(o.DescriptionKey, o.Params, "Description")
	end
	if o.EmptyTextKey then
		h:SetTranslation(o.EmptyTextKey, o.Params, "EmptyText")
	end
	h.Unload = h.Destroy
	section:_registerControl(h)
	return h
end
local function registerSearch(section: any, h: any, o: any, name: string)
	local presentation = h._context.Presentation
	if not presentation or type(presentation.RegisterSearch) ~= "function" or o.Searchable == false then return end
	presentation:RegisterSearch({
		id = h.Id,
		title = tostring(o.Title or o.Name or name),
		description = tostring(o.Description or ""),
		keywords = o.Keywords or {},
		owner = h,
		activate = function()
			if h._destroyed then return end
			section._window:SetOpen(true)
			section._tab:Select({ Animate = false })
			if section:IsFolded() then section:SetFolded(false) end
			task.spawn(function()
				task.wait()
				if h._destroyed then return end
				if type(h._spotlightActivate) == "function" then
					call(h._spotlightActivate)
				else
					h:Focus("search")
				end
			end)
		end,
	})
	h._maid:GiveTask(function()
		presentation:UnregisterSearch(h.Id)
	end)
end

local function base(section: any, o: any, name: string, default: any, validator: any, normalizer: any): any
	local usesMetric = o.Height == nil
	local h = static(section, o, o.Height or metric(section._context, "controlHeight"), if usesMetric then "controlHeight" else nil)
	h.Id = id(section, o, name)
	h._options = o
	h._locked = o.Locked == true
	h._risk = o.Risk or "default"
	local ok, err = h._context.Store:Register({
		id = h.Id,
		default = default,
		validate = validator,
		normalize = normalizer,
		persist = section._persistControls ~= false and o.Persist ~= false,
		onChange = function(v, old, changed, source)
			call(o.Callback, v, old, changed, source)
		end,
	})
	if not ok then
		h:Destroy()
		error(err.message, 2)
	end
	h._maid:GiveTask(function()
		h._context.Store:Unregister(h.Id)
	end)
	function h:Get()
		local v, e = self._context.Store:Get(self.Id)
		if e then
			error(e.message, 2)
		end
		return v
	end
	function h:ValueSnapshot()
		return table.freeze({ id = self.Id, value = frozenValueSnapshot(self:Get()) })
	end
	function h:Observe(callback: any, options: any?)
		assert(type(callback) == "function", "Observe requires a callback")
		local subscription, observeError = self._context.Store:Subscribe(self.Id, function(value, oldValue, changed, source)
			callback(value, oldValue, changed, source)
		end)
		if subscription == nil then
			error(observeError.message, 2)
		end
		if type(options) == "table" and options.EmitInitial == true then
			callback(self:Get(), nil, self.Id, "program")
		end
		return subscription
	end
	function h:Set(v: any, options: any?)
		local source = if type(options) == "table" and options.Source ~= nil then options.Source else "program"
		local function commit()
			return self._context.Store:Set(self.Id, v, source)
		end
		local success, e = if type(options) == "table" and options.Silent == true
			then self._context.Store:SuppressDefinitionCallback(commit)
			else commit()
		if not success then
			error(e.message, 2)
		end
		return self
	end
	function h:Reset(options: any?)
		local source = if type(options) == "table" and options.Source ~= nil then options.Source else "program"
		local function commit()
			return self._context.Store:Reset(self.Id, source)
		end
		local success, e = if type(options) == "table" and options.Silent == true
			then self._context.Store:SuppressDefinitionCallback(commit)
			else commit()
		if not success then
			error(e.message, 2)
		end
		return self
	end
	function h:SetLocked(v: boolean)
		self._locked = v == true
		if self._render then
			self:_render(self:Get())
		end
		return self
	end
	function h:SetRisk(v: boolean | string)
		self._risk = if v == true then "danger" elseif v == false then "default" else v
		staticRisk(self, self._risk)
		if self._render then
			self:_render(self:Get())
		end
		return self
	end
	function h:SetColor(color: Color3)
		if self._title then
			self._title.TextColor3 = color
		end
		return self
	end
	function h:BindForm(form: any, options: any?)
		assert(type(form) == "table" and type(form.RegisterField) == "function", "BindForm requires FormState")
		form:RegisterField(self, options)
		self._maid:Set("form-binding", function()
			if type(form.UnregisterField) == "function" then
				form:UnregisterField(self)
			end
		end)
		self._form = form
		return self
	end
	function h:GetFieldState()
		return self._fieldState and table.clone(self._fieldState) or { status = "idle" }
	end
	function h:SetFieldState(state: any)
		state = state or { status = "idle" }
		self._fieldState = state
		if self._fieldThemeBound == nil and self._context.ThemeChanged then
			self._fieldThemeBound = true
			self._maid:GiveTask(self._context.ThemeChanged:Connect(function()
				if not self._destroyed then self:SetFieldState(self._fieldState) end
			end))
		end
		local status = state.status or "idle"
		local theme = self._context.Theme
		if self._fieldStroke == nil then
			self._fieldStroke = Factory.make("UIStroke", {
				Name = "FieldStateStroke",
				ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				Thickness = 1,
				Transparency = 1,
			}, self.Root)
			self._maid:GiveTask(self._fieldStroke)
		end
		local semantic = if status == "error" then theme.colors.danger
			elseif status == "warning" then theme.colors.warning
			elseif status == "success" then theme.colors.success
			else nil
		self._fieldStroke.Transparency = if semantic then 0 else 1
		if semantic then self._fieldStroke.Color = semantic end
		if status ~= "idle" and state.message and self._fieldMessage == nil then
			self._fieldMessage = Factory.text(self.Root, "", theme.typography.caption * theme.textScale, theme.colors.textMuted, {
				Name = "FieldMessage", AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -6, 1, -2),
				Size = UDim2.new(0.45, -8, 0, 14), TextTruncate = Enum.TextTruncate.AtEnd,
				TextXAlignment = Enum.TextXAlignment.Right, ZIndex = self.Root.ZIndex + 1,
			})
			self._maid:GiveTask(self._fieldMessage)
		end
		if self._fieldMessage then
			self._fieldMessage.Text = tostring(state.message or "")
			self._fieldMessage.TextColor3 = semantic or theme.colors.textMuted
			self._fieldMessage.Visible = status ~= "idle" and state.message ~= nil
		end
		self.Root:SetAttribute("AccessibleDescription", if status ~= "idle" and state.message then tostring(state.message) else "")
		return self
	end
	function h:IsActivated()
		return active(self)
	end
	local con, e = h._context.Store:Subscribe(h.Id, function(v)
		if h._render then
			h:_render(v)
		end
	end)
	assert(con, e and e.message)
	h._maid:GiveTask(con)
	registerSearch(section, h, o, name)
	return h
end
local function registerThemeBinding(h: any, instance: Instance, tokens: { [string]: string })
	local context = h._context
	local owner = if type(context) == "table" and type(context._themeTransitionOwner) == "table"
		then context._themeTransitionOwner
		else context
	if type(owner) ~= "table" or type(owner.RegisterThemeTransition) ~= "function" then return false end
	local binding = owner:RegisterThemeTransition({ instance = instance, tokens = tokens })
	if binding == nil then return false end
	h._maid:GiveTask(function()
		if type(owner.UnregisterThemeTransition) == "function" then
			owner:UnregisterThemeTransition(binding)
		end
	end)
	return true
end
local function label(h: any, title: string)

	h._title = Factory.text(
		h.Root,
		title,
		h._context.Theme.typography.label * h._context.Theme.textScale,
		h._context.Theme.colors.text,
		{
			theme = h._context.Theme,
			Size = if h._options and h._options._inline
				then UDim2.new()
				else UDim2.new(metric(h._context, "labelWidth") / 100, -metric(h._context, "controlGap"), 1, 0),
			TextWrapped = true,
			TextTruncate = Enum.TextTruncate.None,
			Visible = not (h._options and h._options._inline),
		}
	)
	if h._risk ~= "danger" then
		h._titleThemeTransition = registerThemeBinding(h, h._title, {
			TextColor3 = "colors.text",
		})
	end
	if h._options and h._options.TitleKey then
		h:SetTranslation(h._options.TitleKey, h._options.Params, "Title")
	end
	return h._title
end
local function focus(section: any, h: any, obj: GuiObject, ringObject: GuiObject?)
	h._focusId = h.Id
	h._focusObject = obj
	section:_focus(h.Id, obj, h._maid, ringObject)
	h._maid:GiveTask(obj.SelectionGained:Connect(function()
		if not h._destroyed then setFocusState(h, true, "selection") end
	end))
	h._maid:GiveTask(obj.SelectionLost:Connect(function()
		if not h._destroyed then setFocusState(h, false, "selection") end
	end))
	if obj:IsA("TextBox") then
		h._maid:GiveTask(obj.Focused:Connect(function()
			if not h._destroyed then setFocusState(h, true, "text_entry") end
		end))
		h._maid:GiveTask(obj.FocusLost:Connect(function()
			if not h._destroyed then setFocusState(h, false, "text_entry") end
		end))
	end
end
local function bindPillFocus(section: any, h: any, maid: any, focusId: string, button: TextButton)
	section:_focus(focusId, button, maid)
	maid:GiveTask(button.SelectionGained:Connect(function()
		if not h._destroyed then
			h._pillFocusTarget = button
			setFocusState(h, true, "pill_enter")
		end
	end))
	maid:GiveTask(button.SelectionLost:Connect(function()
		if not h._destroyed and h._pillFocusTarget == button and not h._rebuildingPills then
			task.defer(function()
				if not h._destroyed and h._pillFocusTarget == button and not h._rebuildingPills then
					h._pillFocusTarget = nil
					setFocusState(h, false, "pill_blur")
				end
			end)
		end
	end))
end

local function restorePillFocus(h: any, items: { any }, reason: string)
	local previous = h._pillFocusTarget
	local manager = h._context.FocusManager
	local wasFocused = previous ~= nil and manager ~= nil and focusedHandles[manager] == h
	local previousKey = if previous then previous:GetAttribute("PillKey") else nil
	h._pillFocusTarget = nil
	if not wasFocused then return end
	local target = if previousKey ~= nil then h._buttons[previousKey] else nil
	if target == nil or not target.Active then
		for _, item in ipairs(items) do
			local candidate = h._buttons[item.Key]
			if not item.Disabled and candidate and candidate.Parent ~= nil and candidate.Active then
				target = candidate
				break
			end
		end
	end
	if target and manager and type(manager.SetFocused) == "function" then
		h._pillFocusTarget = target
		manager:SetFocused(target, reason)
		setFocusState(h, true, reason)
	else
		setFocusState(h, false, reason)
	end
end

local function installPillFocus(h: any, ordered: () -> { any })
	function h:Focus(reason: string?): boolean
		if self._destroyed or not active(self) then return false end
		local target: TextButton? = nil
		for _, item in ipairs(ordered()) do
			if not item.Disabled then
				local button = self._buttons[item.Key]
				if button and button.Parent ~= nil and button.Active then
					target = button
					break
				end
			end
		end
		local manager = self._context.FocusManager
		if target == nil or manager == nil or type(manager.SetFocused) ~= "function" then return false end
		local focused = manager:SetFocused(target, reason or "control")
		if focused then
			self._pillFocusTarget = target
			setFocusState(self, true, reason or "control")
		end
		return focused
	end
end
local function themeConnection(h: any)
	local changed = h._context.ThemeChanged
	if changed and type(changed.Connect) == "function" then
		h._maid:GiveTask(changed:Connect(function(nextTheme: any)
			if h._title then
				if not (h._options and h._options._inline) then
					h._title.Size =
						UDim2.new(metric(h._context, "labelWidth") / 100, -metric(h._context, "controlGap"), 1, 0)
				end
				if not h._titleThemeTransition and h._context._themeTransitionActive ~= true then
					h._title.TextColor3 = if h._risk == "danger"
						then nextTheme.states.danger.text
						else nextTheme.colors.text
				end
				if h._context._themeTransitionActive ~= true then
					h._title.TextSize = nextTheme.typography.label * nextTheme.textScale
				end
			end
			if h._render and h._context._themeTransitionActive ~= true then
				h:_render(h:Get())
			end
		end))
	end
end
local function bindTheme(handle: any, callback: (any) -> ())
	callback(handle._context.Theme)
	if handle._context.ThemeChanged then
		handle._maid:GiveTask(handle._context.ThemeChanged:Connect(function(theme: any)
			if handle._context._themeTransitionActive ~= true then
				callback(theme)
			end
		end))
	end
end
local function ensureTrailing(handle: any): Frame
	if handle._trailing then
		return handle._trailing
	end
	local trailing = Factory.make("Frame", {
		Name = "Trailing",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -64, 0.5, 0),
		Size = UDim2.fromOffset(180, 40),
	}, handle.Root) :: Frame
	Factory.list(trailing, 4, true)
	handle._trailing = trailing
	if handle._title then
		handle._title.Size = UDim2.new(1, -252, 1, 0)
	end
	return trailing
end
local function trailingCopy(h: any, labelText: string, description: any, actionWidth: number?, reserveDescription: boolean?): (TextLabel, TextLabel?)
	local reserved = (actionWidth or 32) + 20
	local descriptionText = if description == nil then "" else tostring(description)
	local hasDescription = reserveDescription == true or descriptionText ~= ""
	local title = Factory.text(
		h.Root,
		labelText,
		h._context.Theme.typography.label * h._context.Theme.textScale,
		h._context.Theme.colors.text,
		{
			Name = "Label",
			Position = UDim2.fromOffset(0, if hasDescription then 3 else 0),
			Size = if hasDescription
				then UDim2.new(1, -reserved, 0, 20)
				else UDim2.new(1, -reserved, 1, 0),
			TextTruncate = Enum.TextTruncate.AtEnd,
			TextWrapped = false,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = if hasDescription then Enum.TextYAlignment.Bottom else Enum.TextYAlignment.Center,
			theme = h._context.Theme,
		}
	)
	h._title = title
	local descriptionLabel: TextLabel? = nil
	if hasDescription then
		descriptionLabel = Factory.text(
			h.Root,
			descriptionText,
			h._context.Theme.typography.caption * h._context.Theme.textScale,
			h._context.Theme.colors.textMuted,
			{
				Name = "Description",
				Position = UDim2.fromOffset(0, 22),
				Size = UDim2.new(1, -reserved, 0, 18),
				TextTruncate = Enum.TextTruncate.AtEnd,
				TextWrapped = false,
				TextYAlignment = Enum.TextYAlignment.Top,
				theme = h._context.Theme,
			}
		)
		h._description = descriptionLabel
	end
	h.Root:SetAttribute("Layout", "trailing")
	h.Root:SetAttribute("Label", labelText)
	h.Root:SetAttribute("Description", if hasDescription then descriptionText else "")
	h.Root:SetAttribute("AccessibleName", labelText)
	h.Root:SetAttribute("AccessibleDescription", if hasDescription then descriptionText else "")
	bindTheme(h, function(theme)
		title.TextColor3 = if h._risk == "danger" then theme.states.danger.text else theme.colors.text
		title.TextSize = theme.typography.label * theme.textScale
		if descriptionLabel then
			descriptionLabel.TextColor3 = theme.colors.textMuted
			descriptionLabel.TextSize = theme.typography.caption * theme.textScale
		end
	end)
	return title, descriptionLabel
end

local function syncTrailingTextMetadata(h: any, action: TextButton?, syncActionTitle: boolean?)
	local function sync()
		local title = if h._title then h._title.Text else ""
		local description = if h._description then h._description.Text else ""
		h.Root:SetAttribute("Label", title)
		h.Root:SetAttribute("Description", description)
		h.Root:SetAttribute("AccessibleName", title)
		h.Root:SetAttribute("AccessibleDescription", description)
		if action then
			if syncActionTitle then
				h.Root:SetAttribute("ActionTitle", action.Text)
			end
			action:SetAttribute("AccessibleName", if syncActionTitle then action.Text else title)
			action:SetAttribute("AccessibleDescription", description)
		end
	end
	h._syncTextMetadata = sync
	if h._title then
		h._maid:GiveTask(h._title:GetPropertyChangedSignal("Text"):Connect(sync))
	end
	if h._description then
		h._maid:GiveTask(h._description:GetPropertyChangedSignal("Text"):Connect(sync))
	end
	if action then
		h._maid:GiveTask(action:GetPropertyChangedSignal("Text"):Connect(sync))
	end
	sync()
end

function Controls.KeyValue(section: any, o: any)
	assert(type(o) == "table", "KeyValue requires options")
	local height = o.Height or metric(section._context, "controlHeight")
	local h = static(section, o, height, if o.Height == nil then "controlHeight" else nil)
	h.Id = id(section, o, "KeyValue")
	local labelText = tostring(o.Label or o.Title or o.Key or "Key")
	local value = o.Value
	local function valueText(nextValue: any): string
		return if nextValue == nil then "" else tostring(nextValue)
	end
	local title, _ = trailingCopy(h, labelText, nil, 180)
	h.Root:SetAttribute("Layout", "key-value")
	title.Size = UDim2.new(0.48, 0, 1, 0)
	local valueLabel = Factory.text(
		h.Root,
		valueText(value),
		h._context.Theme.typography.body * h._context.Theme.textScale,
		h._context.Theme.colors.textMuted,
		{
			Name = "Value",
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -8, 0.5, 0),
			Size = UDim2.new(0.48, -8, 0, 22),
			TextTruncate = Enum.TextTruncate.AtEnd,
			TextWrapped = false,
			TextXAlignment = Enum.TextXAlignment.Right,
			theme = h._context.Theme,
		}
	)
	h._text = valueLabel
	h.Root:SetAttribute("ReadOnly", true)
	h.Root:SetAttribute("AccessibleRole", "text")
	function h:_syncTextMetadata()
		local currentLabel = title.Text
		self.Root:SetAttribute("Label", currentLabel)
		self.Root:SetAttribute("Description", "")
		self.Root:SetAttribute("AccessibleName", currentLabel)
		self.Root:SetAttribute("AccessibleDescription", "")
		self.Root:SetAttribute("Value", valueLabel.Text)
		self.Root:SetAttribute("AccessibleValue", valueLabel.Text)
	end
	h._maid:GiveTask(valueLabel:GetPropertyChangedSignal("Text"):Connect(function()
		h:_syncTextMetadata()
	end))
	function h:SetLabel(nextLabel: any)
		labelText = tostring(nextLabel)
		title.Text = labelText
		self.Root:SetAttribute("Label", labelText)
		self.Root:SetAttribute("AccessibleName", labelText)
		return self
	end
	function h:SetValue(nextValue: any)
		value = nextValue
		local text = valueText(nextValue)
		valueLabel.Text = text
		self.Root:SetAttribute("Value", text)
		self.Root:SetAttribute("AccessibleValue", text)
		return self
	end
	function h:GetValue()
		return value
	end
	h.SetText = h.SetValue
	bindTheme(h, function(theme)
		valueLabel.TextColor3 = theme.colors.textMuted
		valueLabel.TextSize = theme.typography.body * theme.textScale
	end)
	h:SetValue(value)
	if o.TitleKey then
		h:SetTranslation(o.TitleKey, o.Params, "Title")
	end
	if o.TextKey then
		h:SetTranslation(o.TextKey, o.Params, "Text")
	end
	return h
end


function Controls.Toggle(section: any, o: any, default: any, callback: any, tooltip: any?)
	if type(o) ~= "table" then
		o = { Title = o, Default = default, Callback = callback, Tooltip = tooltip, _positional = true }
	end
	local h = base(section, o, "Toggle", o.Default == true, Store.Validators.boolean)
	if o.Tooltip then
		h:Tooltip(o.Tooltip)
	end
	local trailing = o.Layout == nil or o.Layout == "trailing"
	local switchWidth = metric(h._context, "switchWidth")
	local switchHeight = metric(h._context, "switchHeight")
	local switchThumb = metric(h._context, "switchThumb")
	local b: TextButton
	local knob: Frame? = nil
	local knobGlow: Frame? = nil
	local knobStroke: UIStroke? = nil
	local switchVisual: Frame? = nil
	local toggleStroke: UIStroke? = nil
	local togglePressScale: UIScale? = nil
	local togglePressGeneration = 0
	if trailing then
		local targetWidth = math.max(44, switchWidth, metric(h._context, "hitTargetMin"))
		local targetHeight = math.max(44, metric(h._context, "hitTargetMin"))
		trailingCopy(h, tostring(o.Title or o.Name or "Toggle"), o.Description, targetWidth, o.DescriptionKey ~= nil)
		b = Factory.plainButton(
			h.Root,
			"",
			h._context.Theme,
			{
				Name = "SwitchTarget",
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, -8, 0.5, 0),
				Size = UDim2.fromOffset(targetWidth, targetHeight),
				TextTransparency = 1,
			}
		)
		b.BackgroundTransparency = 1
		switchVisual = Factory.make("Frame", {
			Name = "Switch",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(switchWidth, switchHeight),
			BackgroundColor3 = h._context.Theme.states.default.background,
			BorderSizePixel = 0,
		}, b) :: Frame
		Factory.corner(switchVisual, math.min(h._context.Theme.radius.pill, switchHeight / 2))
		knobGlow = Factory.make("Frame", {
			Name = "ThumbGlow",
			BackgroundColor3 = h._context.Theme.accentA,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromOffset(switchHeight / 2, switchHeight / 2),
			Size = UDim2.fromOffset(switchThumb + 8, switchThumb + 8),
			ZIndex = 1,
		}, switchVisual) :: Frame
		Factory.corner(knobGlow, math.min(h._context.Theme.radius.pill, (switchThumb + 8) / 2))
		knob = Factory.make("Frame", {
			Name = "Thumb",
			BackgroundColor3 = h._context.Theme.colors.textMuted,
			BorderSizePixel = 0,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromOffset(switchHeight / 2, switchHeight / 2),
			Size = UDim2.fromOffset(switchThumb, switchThumb),
			ZIndex = 2,
		}, switchVisual) :: Frame
		Factory.corner(knob, math.min(h._context.Theme.radius.pill, switchThumb / 2))
		knobStroke = Factory.stroke(knob, h._context.Theme.colors.borderStrong, 1)
		knobStroke.Transparency = 0.7
		toggleStroke = Factory.stroke(switchVisual, h._context.Theme.colors.borderStrong, 1)
		toggleStroke.Transparency = 0.85
		b:SetAttribute("AccessibleName", tostring(o.Title or o.Name or "Toggle"))
		b:SetAttribute("AccessibleDescription", tostring(o.Description or ""))
		switchVisual:SetAttribute("SwitchWidth", switchWidth)
		switchVisual:SetAttribute("SwitchHeight", switchHeight)
	else
		label(h, tostring(o.Title or o.Name or "Toggle"))
		b = Factory.button(
			h.Root,
			"",
			h._context.Theme,
			{
				Role = "segment",
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, 0, 0.5, 0),
				Size = UDim2.fromOffset(metric(h._context, "inputHeight") + metric(h._context, "controlGap") * 2, metric(h._context, "inputHeight")),
			}
		)
		toggleStroke = Factory.stroke(b, h._context.Theme.colors.borderStrong, 1)
		toggleStroke.Transparency = 0.85
	end
	togglePressScale = Factory.make("UIScale", { Scale = 1 }, if switchVisual then switchVisual else b) :: UIScale
	togglePressScale:SetAttribute("RayfieldMotionPressDuration", 0.6)
	togglePressScale:SetAttribute("RayfieldMotionRestoreDelay", 0.11)
	togglePressScale:SetAttribute("RayfieldMotionRestoreDuration", 0.25)
	if toggleStroke then
		toggleStroke:SetAttribute("RayfieldMotionGhostDuration", 0.25)
	end
	if trailing then
		syncTrailingTextMetadata(h, b)
		if o.TitleKey then
			h:SetTranslation(o.TitleKey, o.Params, "Title")
		end
		if o.DescriptionKey then
			h:SetTranslation(o.DescriptionKey, o.Params, "Description")
		end
	end
	local renderedValue: boolean? = nil
	local function playPress()
		togglePressGeneration += 1
		local generation = togglePressGeneration
		local pressTarget = if switchVisual then switchVisual else b
		local width = math.max(1, pressTarget.AbsoluteSize.X, pressTarget.Size.X.Offset)
		local pressedScale = math.max(0.5, (width - 6) / width)
		if togglePressScale then
			motionTween(h, togglePressScale, { Scale = pressedScale }, TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out))
		end
		if toggleStroke then
			motionTween(h, toggleStroke, { Transparency = 1 }, TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out))
		end
		task.delay(0.11, function()
			if h._destroyed or generation ~= togglePressGeneration then
				return
			end
			if togglePressScale then
				motionTween(h, togglePressScale, { Scale = 1 }, TweenInfo.new(0.25, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out))
			end
			if toggleStroke then
				motionTween(h, toggleStroke, { Transparency = 0.85 }, TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out))
			end
		end)
	end
	function h:_render(v: boolean)
		b.Text = if trailing then "" else (if v then "ON" else "OFF")
		b:SetAttribute("Value", v)
		if not trailing then apply(b, self, v) end
		if knob and switchVisual then
			switchWidth = metric(self._context, "switchWidth")
			switchHeight = metric(self._context, "switchHeight")
			switchThumb = metric(self._context, "switchThumb")
			local targetWidth = math.max(44, switchWidth, metric(self._context, "hitTargetMin"))
			local targetHeight = math.max(44, metric(self._context, "hitTargetMin"))
			b.Size = UDim2.fromOffset(targetWidth, targetHeight)
			b.BackgroundTransparency = 1
			switchVisual.Size = UDim2.fromOffset(switchWidth, switchHeight)
			local thumbPosition = UDim2.fromOffset(if v then switchWidth - switchHeight / 2 else switchHeight / 2, switchHeight / 2)
			local trackGoal = {
				BackgroundColor3 = if v then self._context.Theme.accentA else self._context.Theme.states.default.background,
			}
			local activeThumbColor = contrastingInk(self._context.Theme.accentA, self._context.Theme.colors.text)
			local thumbGoal = {
				Position = thumbPosition,
				BackgroundColor3 = if v then activeThumbColor else self._context.Theme.colors.textMuted,
				BackgroundTransparency = if v then 0 else 0.2,
			}
			local knobStrokeGoal = {
				Color = if v then activeThumbColor else self._context.Theme.colors.borderStrong,
				Transparency = if v then 0.45 else 0.7,
			}
			local glowGoal = {
				Position = thumbPosition,
				BackgroundColor3 = self._context.Theme.accentA,
				BackgroundTransparency = if v then 0.72 else 1,
			}
			if renderedValue == nil then
				switchVisual.BackgroundColor3 = trackGoal.BackgroundColor3
				knob.Position = thumbGoal.Position
				knob.BackgroundColor3 = thumbGoal.BackgroundColor3
				knob.BackgroundTransparency = thumbGoal.BackgroundTransparency
				if knobStroke then
					knobStroke.Color = knobStrokeGoal.Color
					knobStroke.Transparency = knobStrokeGoal.Transparency
				end
				if knobGlow then
					knobGlow.Position = glowGoal.Position
					knobGlow.BackgroundColor3 = glowGoal.BackgroundColor3
					knobGlow.BackgroundTransparency = glowGoal.BackgroundTransparency
				end
			else
				motionTween(self, switchVisual, trackGoal, RAYFIELD_TOGGLE_MOTION)
				motionTween(self, knob, thumbGoal, RAYFIELD_TOGGLE_MOTION)
				if knobStroke then
					motionTween(self, knobStroke, knobStrokeGoal, RAYFIELD_TOGGLE_MOTION)
				end
				if knobGlow then
					motionTween(self, knobGlow, glowGoal, RAYFIELD_TOGGLE_MOTION)
				end
			end
			switchVisual:SetAttribute("MotionProfile", "rayfield-gen2")
			switchVisual:SetAttribute("MotionDuration", RAYFIELD_TOGGLE_MOTION.Time)
			switchVisual:SetAttribute("RayfieldMotionStateDuration", RAYFIELD_TOGGLE_MOTION.Time)
			renderedValue = v
		elseif toggleStroke then
			toggleStroke.Color = self._context.Theme.colors.borderStrong
			toggleStroke:SetAttribute("RayfieldMotionStateDuration", RAYFIELD_TOGGLE_MOTION.Time)
		end
	end
	h._maid:GiveTask(b.Activated:Connect(function()
		if active(h) then
			playPress()
			h:Set(not h:Get(), { Source = "user" })
		end
	end))
	function h:AddKeybind(x: any, mode: any?, activationCallback: any?)
		if type(x) ~= "table" then
			x = {
				Id = h.Id .. "-keybind",
				Title = "Keybind",
				Default = asKeyCode(x),
				Mode = mode or "Toggle",
				ActivationCallback = activationCallback,
			}
		end
		x._parent = ensureTrailing(h)
		x._inline = true
		x._inlineOrder = 1
		local child = Controls.Keybind(section, x)
		h._maid:GiveTask(child)
		return child
	end
	function h:AddColorpicker(x: any, defaultColor: any?, colorCallback: any?, alpha: any?)
		if type(x) ~= "table" then
			x = {
				Id = h.Id .. "-color",
				Title = tostring(x or "Color"),
				Default = defaultColor,
				Callback = colorCallback,
				Alpha = alpha ~= nil,
			}
			if typeof(defaultColor) == "Color3" and type(alpha) == "number" then
				x.Default = { r = defaultColor.R, g = defaultColor.G, b = defaultColor.B, a = math.clamp(alpha, 0, 1) }
			end
		end
		x._parent = ensureTrailing(h)
		x._inline = true
		x._inlineOrder = 2
		local child = Controls.Colorpicker(section, x)
		h._maid:GiveTask(child)
		return child
	end
	focus(section, h, b, if trailing then switchVisual else nil)
	if trailing then
		bindTheme(h, function()
			h:_render(h:Get())
		end)
	else
		themeConnection(h)
	end
	h:_render(h:Get())
	return h
end
function Controls.Checkbox(section: any, o: any, default: any, callback: any, tooltip: any?)
	if type(o) ~= "table" then
		o = { Title = o, Default = default, Callback = callback, Tooltip = tooltip, _positional = true }
	end
	local h = base(section, o, "Checkbox", o.Default == true, Store.Validators.boolean)
	if o.Tooltip then
		h:Tooltip(o.Tooltip)
	end
	label(h, tostring(o.Title or o.Name or "Checkbox"))
	local b = Factory.button(
		h.Root,
		"",
		h._context.Theme,
		{
			Role = "segment",
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, 0, 0.5, 0),
			Size = UDim2.fromOffset(metric(h._context, "inputHeight"), metric(h._context, "inputHeight")),
		}
	)
	function h:_render(v: boolean)
		local toggleStyle = self._context.Theme.checkboxStyle == true or self._context.Theme.checkboxStyle == "toggle"
		b.Text = if v then (if toggleStyle then "ON" else "✓") else (if toggleStyle then "OFF" else "")
		apply(b, self, v)
		b.Size = if toggleStyle
			then UDim2.fromOffset(metric(self._context, "inputHeight") + metric(self._context, "controlGap") * 2, metric(self._context, "inputHeight"))
			else UDim2.fromOffset(metric(self._context, "inputHeight"), metric(self._context, "inputHeight"))
	end
	h._maid:GiveTask(b.Activated:Connect(function()
		if active(h) then
			h:Set(not h:Get(), { Source = "user" })
		end
	end))
	focus(section, h, b)
	themeConnection(h)
	h:_render(h:Get())
	return h
end
local function track(h: any): (Frame, Frame, TextButton, Frame)
	local t = Factory.make("Frame", {
		Name = "PotassiumSliderTrack",
		BackgroundColor3 = h._context.Theme.colors.border,
		BorderSizePixel = 0,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, 0, 0.5, 0),
		Size = UDim2.new((100 - metric(h._context, "labelWidth")) / 100, 0, 0, metric(h._context, "borderWidth") * 8),
	}, h.Root) :: Frame
	Factory.corner(t, 4)
	local f = Factory.make("Frame", {
		Name = "PotassiumSliderFill",
		BackgroundColor3 = h._context.Theme.states.selected.background,
		BorderSizePixel = 0,
		Size = UDim2.fromScale(0, 1),
	}, t) :: Frame
	Factory.corner(f, 4)
	local thumb = Factory.make("Frame", {
		Name = "PotassiumSliderThumb",
		BackgroundColor3 = h._context.Theme.colors.text,
		BorderSizePixel = 0,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.fromOffset(16, 16),
		ZIndex = 2,
	}, t) :: Frame
	Factory.corner(thumb, 8)
	local hit = Factory.plainButton(t, "", h._context.Theme, {
		Name = "PotassiumSliderHitTarget",
		BackgroundTransparency = 1,
		TextTransparency = 1,
		Size = UDim2.new(1, 0, 0, metric(h._context, "inputHeight")),
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 0, 0.5, 0),
	})
	return t, f, hit, thumb
end
local function sliderDecimalPlaces(step: number): number
	for decimals = 0, 8 do
		local scale = 10 ^ decimals
		if math.abs(step * scale - math.round(step * scale)) < 1e-8 then
			return decimals
		end
	end
	return 8
end

local function sliderValueText(options: any, value: number, decimalPlaces: number): string
	local formatted: string
	if type(options.Format) == "function" then
		formatted = tostring(options.Format(value))
	elseif type(options.Precision) == "number" then
		formatted = string.format("%." .. tostring(math.max(0, math.floor(options.Precision))) .. "f", value)
	else
		local scale = 10 ^ decimalPlaces
		local rounded = math.round(value * scale) / scale
		if rounded == 0 then
			rounded = 0
		end
		formatted = string.format("%." .. tostring(decimalPlaces) .. "f", rounded)
	end
	local suffix = if options.Suffix == nil then "" else tostring(options.Suffix)
	return formatted .. suffix
end

function Controls.Slider(
	section: any,
	o: any,
	defaultValue: any,
	stepValue: any,
	minimum: any,
	maximum: any,
	suffix: any,
	callback: any,
	tooltip: any
)
	if type(o) ~= "table" then
		o = {
			Title = o,
			Default = defaultValue,
			Step = stepValue,
			Min = minimum,
			Max = maximum,
			Suffix = suffix,
			Callback = callback,
			Tooltip = tooltip,
			_positional = true,
		}
	end
	assert(type(o.Min) == "number" and type(o.Max) == "number" and o.Min < o.Max, "Slider requires Min < Max")
	local step = o.Step or 1
	assert(step > 0, "Slider Step must be positive")
	local decimalPlaces = sliderDecimalPlaces(step)
	local function norm(v: number): number
		return Util.clamp(Util.roundToStep(v, step, o.Min), o.Min, o.Max)
	end
	local h = base(section, o, "Slider", norm(o.Default or o.Min), Store.Validators.number(o.Min, o.Max), norm)
	if o.Tooltip then
		h:Tooltip(o.Tooltip)
	end
	label(h, tostring(o.Title or o.Name or "Slider"))
	local t, f, hit, thumb = track(h)
	local valueLabel = Factory.text(
		h.Root,
		"",
		h._context.Theme.typography.label * h._context.Theme.textScale,
		h._context.Theme.colors.text,
		{
			Name = "PotassiumSliderValue",
			Position = UDim2.new(metric(h._context, "labelWidth") / 100, 0, 0, 0),
			Size = UDim2.new((100 - metric(h._context, "labelWidth")) / 100, 0, 0, 18),
			TextXAlignment = Enum.TextXAlignment.Right,
			TextYAlignment = Enum.TextYAlignment.Top,
			fontRole = "medium",
			theme = h._context.Theme,
			typographyRole = "label",
		}
	)
	local sliderRendered = false
	local sliderDragging = false
	local sliderDragInput: InputObject? = nil
	thumb.BackgroundTransparency = 1
	local thumbVisual = Factory.make("Frame", {
		Name = "PotassiumSliderThumbVisual",
		AnchorPoint = Vector2.new(0.5, 0.5),
		BackgroundColor3 = h._context.Theme.colors.text,
		BorderSizePixel = 0,
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(16, 16),
		ZIndex = thumb.ZIndex,
	}, thumb) :: Frame
	Factory.corner(thumbVisual, 8)
	local thumbStroke = Factory.stroke(thumbVisual, h._context.Theme.colors.borderStrong, 1)
	thumbStroke.Transparency = 1
	local function setHeld(held: boolean)
		motionTween(h, thumbVisual, {
			Size = UDim2.fromOffset(if held then 18 else 16, if held then 18 else 16),
			BackgroundTransparency = if held then 0.7 else 0,
		}, RAYFIELD_SLIDER_HELD_MOTION)
		motionTween(h, thumbStroke, { Transparency = if held then 0.6 else 1 }, RAYFIELD_SLIDER_HELD_MOTION)
	end
	h._maid:GiveTask(function()
		if sliderDragInput then
			h._context.InputRouter:EndPointerDrag(sliderDragInput)
		end
	end)
	local function set(p: Vector2)
		h:Set(o.Min + (o.Max - o.Min) * Util.clamp((p.X - t.AbsolutePosition.X) / math.max(1, t.AbsoluteSize.X), 0, 1), { Source = "user" })
	end
	function h:_render(v: number)
		local ratio = (v - o.Min) / (o.Max - o.Min)
		local theme = h._context.Theme
		t.BackgroundColor3 = theme.colors.border
		t.BackgroundTransparency = 0.35
		t.Position = UDim2.new(1, 0, 0.66, 0)
		t.Size = UDim2.new(
			(100 - metric(self._context, "labelWidth")) / 100,
			0,
			0,
			math.max(2, metric(self._context, "borderWidth") * 4)
		)
		hit.Size = UDim2.new(1, 0, 0, metric(self._context, "inputHeight"))
		valueLabel.Position = UDim2.new(metric(self._context, "labelWidth") / 100, 0, 0, 0)
		valueLabel.Size = UDim2.new((100 - metric(self._context, "labelWidth")) / 100, 0, 0, 18)
		valueLabel.TextSize = theme.typography.label * theme.textScale
		valueLabel.TextColor3 = theme.colors.text
		valueLabel.Text = sliderValueText(o, v, decimalPlaces)
		f.BackgroundColor3 = theme.states.selected.background
		thumbVisual.BackgroundColor3 = theme.colors.text
		local fillGoal = { Size = UDim2.fromScale(ratio, 1) }
		local thumbGoal = { Position = UDim2.fromScale(ratio, 0.5) }
		if sliderRendered then
			local progressMotion = if sliderDragging then RAYFIELD_SLIDER_FOLLOW_MOTION else RAYFIELD_SLIDER_HOVER_MOTION
			motionTween(self, f, fillGoal, progressMotion)
			motionTween(self, thumb, thumbGoal, progressMotion)
		else
			f.Size = fillGoal.Size
			thumb.Position = thumbGoal.Position
			sliderRendered = true
		end
		t:SetAttribute("MotionProfile", "rayfield-gen2")
		t:SetAttribute("MotionFollowDuration", RAYFIELD_SLIDER_FOLLOW_MOTION.Time)
		t:SetAttribute("RayfieldMotionSetDuration", RAYFIELD_SLIDER_HOVER_MOTION.Time)
		t:SetAttribute("RayfieldMotionHeldDuration", RAYFIELD_SLIDER_HELD_MOTION.Time)
		hit.Text = tostring(v)
		Factory.setPresenceInteractive(hit, active(self))
	end
	h._maid:GiveTask(hit.InputBegan:Connect(function(i)
		if
			hit.Active
			and active(h)
			and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch)
		then
			if sliderDragInput then
				h._context.InputRouter:EndPointerDrag(sliderDragInput)
			end
			sliderDragging = true
			sliderDragInput = i
			selectionHaptic(h)
			setHeld(true)
			set(i.Position)
			h._context.InputRouter:BeginPointerDrag(i, function(p)
				if active(h) and hit.Active and sliderDragInput == i then
					set(p)
				end
			end, function()
				if sliderDragInput ~= i then
					return
				end
				sliderDragInput = nil
				sliderDragging = false
				setHeld(false)
			end)
		elseif
			hit.Active
			and active(h)
			and (
				i.KeyCode == Enum.KeyCode.Left
				or i.KeyCode == Enum.KeyCode.Down
				or i.KeyCode == Enum.KeyCode.DPadLeft
				or i.KeyCode == Enum.KeyCode.DPadDown
			)
		then
			h:Set(h:Get() - step, { Source = "user" })
		elseif
			hit.Active
			and active(h)
			and (
				i.KeyCode == Enum.KeyCode.Right
				or i.KeyCode == Enum.KeyCode.Up
				or i.KeyCode == Enum.KeyCode.DPadRight
				or i.KeyCode == Enum.KeyCode.DPadUp
			)
		then
			h:Set(h:Get() + step, { Source = "user" })
		end
	end))
	h._maid:GiveTask(hit.MouseEnter:Connect(function()
		if active(h) then
			motionTween(h, t, { BackgroundColor3 = h._context.Theme.states.hover.background }, RAYFIELD_SLIDER_HOVER_MOTION)
		end
	end))
	h._maid:GiveTask(hit.MouseLeave:Connect(function()
		motionTween(h, t, { BackgroundColor3 = h._context.Theme.colors.border }, RAYFIELD_SLIDER_HOVER_MOTION)
	end))
	focus(section, h, hit)
	themeConnection(h)
	h:_render(h:Get())
	return h
end
function Controls.RangeSlider(
	section: any,
	o: any,
	low: any,
	high: any,
	stepValue: any,
	minimum: any,
	maximum: any,
	suffix: any,
	callback: any,
	tooltip: any
)
	if type(o) ~= "table" then
		o = {
			Title = o,
			Default = { min = low, max = high },
			Step = stepValue,
			Min = minimum,
			Max = maximum,
			Suffix = suffix,
			Callback = if type(callback) == "function"
				then function(value)
					callback(value.min, value.max)
				end
				else nil,
			Tooltip = tooltip,
			_positional = true,
		}
	end
	assert(type(o.Min) == "number" and type(o.Max) == "number" and o.Min < o.Max, "RangeSlider requires Min < Max")
	local step = o.Step or 1
	local function norm(v: any): any
		local a = Util.clamp(Util.roundToStep(v.min, step, o.Min), o.Min, o.Max)
		local b = Util.clamp(Util.roundToStep(v.max, step, o.Min), o.Min, o.Max)
		return { min = math.min(a, b), max = math.max(a, b) }
	end
	local h =
		base(section, o, "RangeSlider", norm(o.Default or { min = o.Min, max = o.Max }), Store.Validators.range, norm)
	if o.Tooltip then
		h:Tooltip(o.Tooltip)
	end
	label(h, tostring(o.Title or o.Name or "Range"))
	local t, f, hit, baseThumb = track(h)
	baseThumb:Destroy()
	hit:Destroy()
	local thumbVisuals = {} :: { [TextButton]: { dot: Frame, stroke: UIStroke } }
	local function thumbButton(name: string): TextButton
		local b = Factory.plainButton(t, "", h._context.Theme, {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0, 0.5),
			Size = UDim2.fromOffset(metric(h._context, "inputHeight"), metric(h._context, "inputHeight")),
			BackgroundTransparency = 1,
			TextTransparency = 1,
		})
		local dot = Factory.make("Frame", {
			Name = name,
			BackgroundColor3 = h._context.Theme.colors.text,
			BorderSizePixel = 0,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(16, 16),
		}, b) :: Frame
		Factory.corner(dot, 8)
		local stroke = Factory.stroke(dot, h._context.Theme.colors.borderStrong, 1)
		stroke.Transparency = 1
		thumbVisuals[b] = { dot = dot, stroke = stroke }
		return b
	end
	local low, high = thumbButton("Minimum"), thumbButton("Maximum")
	local rangeDragging = false
	local rangeDragInput: InputObject? = nil
	local function setHeld(thumb: TextButton, held: boolean)
		local visual = thumbVisuals[thumb]
		motionTween(h, visual.dot, {
			Size = UDim2.fromOffset(if held then 18 else 16, if held then 18 else 16),
			BackgroundTransparency = if held then 0.7 else 0,
		}, RAYFIELD_SLIDER_HELD_MOTION)
		motionTween(h, visual.stroke, { Transparency = if held then 0.6 else 1 }, RAYFIELD_SLIDER_HELD_MOTION)
	end
	local function at(p: Vector2): number
		return Util.clamp(
			Util.roundToStep(
				o.Min + (o.Max - o.Min) * Util.clamp((p.X - t.AbsolutePosition.X) / math.max(1, t.AbsoluteSize.X), 0, 1),
				step,
				o.Min
			),
			o.Min,
			o.Max
		)
	end
	local function set(which: string, n: number)
		local v = h:Get()
		if which == "min" then
			v.min = math.min(n, v.max)
		else
			v.max = math.max(n, v.min)
		end
		h:Set(v, { Source = "user" })
	end
	local function drag(which: string, input: InputObject, thumb: TextButton)
		if not thumb.Active then
			return
		end
		if rangeDragInput then
			h._context.InputRouter:EndPointerDrag(rangeDragInput)
		end
		rangeDragging = true
		rangeDragInput = input
		selectionHaptic(h)
		setHeld(thumb, true)
		set(which, at(input.Position))
		h._context.InputRouter:BeginPointerDrag(input, function(p)
			if active(h) and thumb.Active and rangeDragInput == input then
				set(which, at(p))
			end
		end, function()
			if rangeDragInput ~= input then
				return
			end
			rangeDragInput = nil
			rangeDragging = false
			setHeld(thumb, false)
		end)
	end
	h._maid:GiveTask(function()
		if rangeDragInput then
			h._context.InputRouter:EndPointerDrag(rangeDragInput)
		end
	end)
	local rangeRendered = false
	function h:_render(v: any)
		local a = (v.min - o.Min) / (o.Max - o.Min)
		local b = (v.max - o.Min) / (o.Max - o.Min)
		local theme = h._context.Theme
		t.BackgroundColor3 = theme.colors.border
		t.Size = UDim2.new(
			(100 - metric(self._context, "labelWidth")) / 100,
			0,
			0,
			metric(self._context, "borderWidth") * 8
		)
		low.Size = UDim2.fromOffset(metric(self._context, "inputHeight"), metric(self._context, "inputHeight"))
		high.Size = UDim2.fromOffset(metric(self._context, "inputHeight"), metric(self._context, "inputHeight"))
		f.BackgroundColor3 = theme.states.selected.background
		local fillGoal = {
			Position = UDim2.fromScale(a, 0),
			Size = UDim2.fromScale(b - a, 1),
		}
		local lowGoal = { Position = UDim2.fromScale(a, 0.5) }
		local highGoal = { Position = UDim2.fromScale(b, 0.5) }
		if rangeRendered then
			local progressMotion = if rangeDragging then RAYFIELD_SLIDER_FOLLOW_MOTION else RAYFIELD_SLIDER_HOVER_MOTION
			motionTween(self, f, fillGoal, progressMotion)
			motionTween(self, low, lowGoal, progressMotion)
			motionTween(self, high, highGoal, progressMotion)
		else
			f.Position = fillGoal.Position
			f.Size = fillGoal.Size
			low.Position = lowGoal.Position
			high.Position = highGoal.Position
			rangeRendered = true
		end
		t:SetAttribute("MotionProfile", "rayfield-gen2")
		t:SetAttribute("MotionFollowDuration", RAYFIELD_SLIDER_FOLLOW_MOTION.Time)
		t:SetAttribute("RayfieldMotionSetDuration", RAYFIELD_SLIDER_HOVER_MOTION.Time)
		t:SetAttribute("RayfieldMotionHeldDuration", RAYFIELD_SLIDER_HELD_MOTION.Time)
		for _, thumb in ipairs({ low, high }) do
			thumbVisuals[thumb].dot.BackgroundColor3 = theme.colors.text
		end
		Factory.setPresenceInteractive(low, active(self))
		Factory.setPresenceInteractive(high, active(self))
	end
	for _, entry in ipairs({ { low, "min", -1 }, { high, "max", 1 } }) do
		h._maid:GiveTask(entry[1].InputBegan:Connect(function(input)
			if
				entry[1].Active
				and active(h)
				and (
					input.UserInputType == Enum.UserInputType.MouseButton1
					or input.UserInputType == Enum.UserInputType.Touch
				)
			then
				drag(entry[2], input, entry[1])
			elseif
				entry[1].Active
				and active(h)
				and (
					input.KeyCode == Enum.KeyCode.Left
					or input.KeyCode == Enum.KeyCode.Down
					or input.KeyCode == Enum.KeyCode.DPadLeft
					or input.KeyCode == Enum.KeyCode.DPadDown
				)
			then
				set(entry[2], h:Get()[entry[2]] - step)
			elseif
				entry[1].Active
				and active(h)
				and (
					input.KeyCode == Enum.KeyCode.Right
					or input.KeyCode == Enum.KeyCode.Up
					or input.KeyCode == Enum.KeyCode.DPadRight
					or input.KeyCode == Enum.KeyCode.DPadUp
				)
			then
				set(entry[2], h:Get()[entry[2]] + step)
			end
		end))
	end
	local rangeHoverCount = 0
	for _, thumb in ipairs({ low, high }) do
		h._maid:GiveTask(thumb.MouseEnter:Connect(function()
			if active(h) then
				rangeHoverCount += 1
				motionTween(h, t, { BackgroundColor3 = h._context.Theme.states.hover.background }, RAYFIELD_SLIDER_HOVER_MOTION)
			end
		end))
		h._maid:GiveTask(thumb.MouseLeave:Connect(function()
			rangeHoverCount = math.max(0, rangeHoverCount - 1)
			if rangeHoverCount == 0 then
				motionTween(h, t, { BackgroundColor3 = h._context.Theme.colors.border }, RAYFIELD_SLIDER_HOVER_MOTION)
			end
		end))
	end
	focus(section, h, low)
	section:_focus(h.Id .. ".max", high, h._maid)
	themeConnection(h)
	h:_render(h:Get())
	return h
end
local function choices(o: any): (boolean, { any }, string?)
	local source = if type(o.Provider) == "function" then o.Choices or o.Options or {} else o.Provider or o.Choices or o.Options or {}
	if type(source) == "function" then
		local ok, result = pcall(source)
		if not ok then
			return false, {}, tostring(result)
		end
		local validResult = type(result) == "table"
		return validResult,
			if validResult then result else {},
			if validResult then nil else "Provider returned no choices"
	end
	return true, if type(source) == "table" then source else {}, nil
end
local function dropdownTriggerHeight(context: any, _multi: boolean): number
	local rowHeight = metric(context, "compactControlHeight")
	return math.min(rowHeight, math.max(metric(context, "hitTargetMin"), metric(context, "searchHeight")))
end

function Controls.Dropdown(
	section: any,
	o: any,
	defaultValue: any,
	choicesArg: any,
	multiValue: any,
	callback: any,
	tooltip: any,
	searchable: any,
	maxSelections: any
)
	if type(o) ~= "table" then
		o = {
			Title = o,
			Default = defaultValue,
			Choices = choicesArg,
			Multi = multiValue == true,
			Callback = callback,
			Tooltip = tooltip,
			Searchable = searchable == true,
			MaxSelections = maxSelections,
			_positional = true,
		}
	end
	local multi = o.Multi == true
	local presenceOptions = dropdownPresence(o.Presence, section._context.Motion, multi)
	local ok, items, loadError = choices(o)
	local positionalArray = o._positional == true and not multi
	if not multi and not positionalArray and type(o.Default) == "table" then
		o.Default = valueOf(o.Default[1])
	end
	local limit = o.MaxSelections
	local function valid(v: any): (boolean, string?)
		local function known(x: any): boolean
			for _, q in ipairs(items) do
				if valueOf(q) == x then
					return true
				end
			end
			return false
		end
		if multi then
			if type(v) ~= "table" then
				return false, "Multi-select must be an array"
			end
			if limit and #v > limit then
				return false, "Selection limit reached"
			end
			for _, x in ipairs(v) do
				if not known(x) then
					return false, "Unknown choice"
				end
			end
			return true
		end
		if positionalArray then
			if type(v) ~= "table" then
				return false, "Single-select positional value must be an array"
			end
			if #v == 0 then
				return true
			end
			return #v == 1 and known(v[1]), "Unknown choice"
		end
		if #items == 0 and v == nil then
			return true
		end
		return known(v), "Unknown choice"
	end
	local default = if multi
		then (o.Default or {})
		elseif positionalArray then (o.Default or if items[1] ~= nil then { valueOf(items[1]) } else {})
		else (if o.Default ~= nil then o.Default else valueOf(items[1]))
	local h = base(section, o, "Dropdown", default, valid)
	if o.Tooltip then
		h:Tooltip(o.Tooltip)
	end
	label(h, tostring(o.Title or o.Name or "Dropdown"))
	local b = Factory.button(
		h.Root,
		"",
		h._context.Theme,
		{
			Role = "control",
			AnimatePress = false,
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, 0, 0.5, 0),
			Size = UDim2.new(
				(100 - metric(h._context, "labelWidth")) / 100,
				0,
				0,
				dropdownTriggerHeight(h._context, multi)
			),
		}
	)
	local triggerContent = Factory.buttonContent(b, "", h._context.Theme, {
		Icon = "chevrondown",
		IconPosition = "right",
		IconSize = metric(h._context, "iconSize"),
		Gap = metric(h._context, "iconTextGap"),
		Insets = { left = h._context.Theme.spacing.md, right = h._context.Theme.spacing.md },
		TextXAlignment = Enum.TextXAlignment.Left,
		Icons = h._context.Icons,
	})
	if triggerContent.Icon then
		triggerContent.Icon.Rotation = 0
		triggerContent.Icon:SetAttribute("MotionProfile", "rayfield-gen2")
		triggerContent.Icon:SetAttribute("MotionDuration", RAYFIELD_DROPDOWN_CHEVRON_MOTION.Time)
	end
	local query = ""
	local exitSerial = 0
	local activeMultiExitKey: string?
	local popupSerial = 0
	local popup: GuiObject?
	local popupPanel: CanvasGroup?
	local popupMaid: any
	local popupShadow: any
	local popupQuery: TextBox?
	local modal = h.Id .. ".dropdown"
	local popupFocusIds = {}
	local focusedChoiceIndex: number?
	local function resetChevronImmediately()
		if triggerContent.Icon then
			h._context.Motion:Cancel(triggerContent.Icon)
			triggerContent.Icon.Rotation = 0
		end
	end
	local function clearMultiExit()
		if activeMultiExitKey == nil then
			return
		end
		local exitKey = activeMultiExitKey
		activeMultiExitKey = nil
		h._maid:Remove(exitKey)
	end
	local function disablePopup(root: GuiObject)
		root.Active = false
		for _, descendant in ipairs(root:GetDescendants()) do
			if descendant:IsA("TextBox") then
				descendant:ReleaseFocus()
				descendant.TextEditable = false
				descendant.Selectable = false
				descendant.Active = false
			elseif descendant:IsA("GuiButton") then
				descendant.Active = false
				descendant.Selectable = false
			elseif descendant:IsA("GuiObject") then
				descendant.Active = false
			end
		end
	end
	local function close(immediate: boolean?)
		local closingPopup = popup
		local closingPanel = popupPanel
		local closingShadow = popupShadow
		if closingPopup == nil then
			if immediate and multi then
				clearMultiExit()
				resetChevronImmediately()
			end
			return
		end
		popup = nil
		popupPanel = nil
		popupShadow = nil
		popupSerial += 1
		h._context.InputRouter:PopModal(modal)
		h._context.FocusManager:PopModal(modal)
		for _, focusId in ipairs(popupFocusIds) do
			h._context.FocusManager:Unregister(focusId)
		end
		table.clear(popupFocusIds)
		if popupQuery then
			popupQuery:ReleaseFocus()
			popupQuery = nil
		end
		disablePopup(closingPopup)
		local closingMaid = popupMaid
		popupMaid = nil
		if closingMaid then
			closingMaid:Destroy()
			h._maid:Set("dropdown.popup", nil)
		end
		if immediate or presenceOptions == nil or closingPanel == nil then
			resetChevronImmediately()
			if closingShadow then
				closingShadow:Destroy()
			end
			closingPopup:Destroy()
			return
		end

		if multi then
			clearMultiExit()
		end
		exitSerial += 1
		local exitKey = "dropdown.exit." .. tostring(exitSerial)
		local exitMaid = Maid.new()
		if multi then
			activeMultiExitKey = exitKey
		end
		h._maid:Set(exitKey, exitMaid)
		exitMaid:GiveTask(closingPopup)
		if closingShadow then
			exitMaid:GiveTask(closingShadow)
		end
		local exitPresetName = if multi then presenceOptions.exit else nil
		local containerDuration = dropdownMotionDuration(
			h,
			exitPresetName,
			RAYFIELD_DROPDOWN_REVEAL_MOTION.Time
		)
		local panelDuration = dropdownMotionDuration(h, exitPresetName, RAYFIELD_DROPDOWN_PANEL_MOTION.Time)
		closingPopup:SetAttribute("RayfieldMotionContainerDuration", containerDuration)
		closingPanel:SetAttribute("RayfieldMotionPanelDuration", panelDuration)
		local closingSurfaceStroke = if multi
			then closingPanel:FindFirstChild("PotassiumSurfaceBorder")
			else closingPanel:FindFirstChildWhichIsA("UIStroke", true)
		if closingSurfaceStroke and closingSurfaceStroke:IsA("UIStroke") then
			closingSurfaceStroke:SetAttribute("RayfieldMotionDuration", panelDuration)
			dropdownAnimate(
				h,
				exitMaid,
				closingSurfaceStroke,
				{ Transparency = 1 },
				RAYFIELD_DROPDOWN_PANEL_MOTION,
				exitPresetName
			)
		end
		for _, descendant in ipairs(closingPanel:GetDescendants()) do
			if descendant ~= closingSurfaceStroke
				and descendant:IsA("UIStroke")
				and descendant:GetAttribute("RayfieldMotionStroke") ~= nil
			then
				descendant:SetAttribute("RayfieldMotionDuration", panelDuration)
				dropdownAnimate(
					h,
					exitMaid,
					descendant,
					{ Transparency = 1 },
					RAYFIELD_DROPDOWN_PANEL_MOTION,
					exitPresetName
				)
			end
		end
		local closingSearchIcon = closingPanel:FindFirstChild("PotassiumDropdownSearchIcon", true)
		if closingSearchIcon and closingSearchIcon:IsA("CanvasGroup") then
			closingSearchIcon:SetAttribute("RayfieldMotionDuration", panelDuration)
			dropdownAnimate(
				h,
				exitMaid,
				closingSearchIcon,
				{ GroupTransparency = 1 },
				RAYFIELD_DROPDOWN_PANEL_MOTION,
				exitPresetName
			)
		end
		dropdownAnimate(
			h,
			exitMaid,
			closingPanel,
			{ GroupTransparency = 1 },
			RAYFIELD_DROPDOWN_PANEL_MOTION,
			exitPresetName
		)
		if triggerContent.Icon then
			if multi then
				triggerContent.Icon:SetAttribute("MotionDuration", containerDuration)
				dropdownAnimate(
					h,
					exitMaid,
					triggerContent.Icon,
					{ Rotation = 0 },
					RAYFIELD_DROPDOWN_CHEVRON_MOTION,
					exitPresetName
				)
			else
				motionTween(h, triggerContent.Icon, { Rotation = 0 }, RAYFIELD_DROPDOWN_CHEVRON_MOTION)
			end
		end
		local exitMotion = dropdownAnimate(
			h,
			exitMaid,
			closingPopup,
			{ Size = UDim2.fromOffset(closingPopup.Size.X.Offset, 0) },
			RAYFIELD_DROPDOWN_REVEAL_MOTION,
			exitPresetName
		)
		if exitMotion then
			local completedConnection = exitMotion:OnCompleted(function(state: string)
				if state == "Cancelled" then
					return
				end
				if activeMultiExitKey == exitKey then
					activeMultiExitKey = nil
				end
				h._maid:Remove(exitKey)
			end)
			if completedConnection.Connected and not exitMaid:IsDestroyed() then
				exitMaid:GiveTask(completedConnection)
			end
		else
			if activeMultiExitKey == exitKey then
				activeMultiExitKey = nil
			end
			h._maid:Remove(exitKey)
		end
	end
	local function open(refreshing: boolean?)
		local priorFocusedChoiceIndex = focusedChoiceIndex
		local priorQueryWasFocused = false
		local priorQueryCursorPosition: number? = nil
		local priorQuerySelectionStart: number? = nil
		if refreshing and popupQuery then
			priorQueryWasFocused = popupQuery:IsFocused()
			if priorQueryWasFocused then
				priorQueryCursorPosition = popupQuery.CursorPosition
				priorQuerySelectionStart = popupQuery.SelectionStart
			end
		end
		if refreshing and (popup == nil or popupPanel == nil) then refreshing = false end
		if refreshing then
			local staleMaid = popupMaid
			popupMaid = nil
			if staleMaid then staleMaid:Destroy() end
			for _, focusId in ipairs(popupFocusIds) do h._context.FocusManager:Unregister(focusId) end
			table.clear(popupFocusIds)
			if popupQuery then popupQuery:ReleaseFocus(); popupQuery = nil end
			h._context.InputRouter:PopModal(modal)
			h._context.FocusManager:PopModal(modal)
			if popupShadow then popupShadow:Destroy() end
			popupShadow = nil
			(popupPanel :: CanvasGroup):Destroy()
			popupPanel = nil
		else
			close()
			if multi then clearMultiExit() end
			popupSerial += 1
		end
		popupMaid = Maid.new()
		h._maid:Set("dropdown.popup", popupMaid)
		if not refreshing and triggerContent.Icon then
			if presenceOptions then
				if multi then
					local enterDuration = dropdownMotionDuration(h, presenceOptions.enter, RAYFIELD_DROPDOWN_CHEVRON_MOTION.Time)
					triggerContent.Icon:SetAttribute("MotionDuration", enterDuration)
					dropdownAnimate(h, popupMaid, triggerContent.Icon, { Rotation = 180 }, RAYFIELD_DROPDOWN_CHEVRON_MOTION, presenceOptions.enter)
				else
					motionTween(h, triggerContent.Icon, { Rotation = 180 }, RAYFIELD_DROPDOWN_CHEVRON_MOTION)
				end
			else
				triggerContent.Icon.Rotation = 180
			end
		end
		local popupPadding = 8
		local rowGap = 2
		local rowHeight = if multi then 34 else math.max(36, math.floor(metric(h._context, "inputHeight") * 0.82 + 0.5))
		local searchVisible = if multi then o.Searchable ~= false and #items >= 8 else o.Searchable ~= false
		local searchHeight = if searchVisible then rowHeight else 0
		local currentSelection = h:Get()
		local selectedCount = if multi then #currentSelection else 0
		local headerHeight = if multi then 28 else 0
		local visibleChoiceCount = 0
		for _, candidate in ipairs(items) do
			local candidateTitle = valueText(candidate)
			if query == "" or string.find(string.lower(candidateTitle), string.lower(query), 1, true) then
				visibleChoiceCount += 1
				if visibleChoiceCount >= MAX_RESULTS then break end
			end
		end
		local visibleRows = math.max(1, math.min(visibleChoiceCount, 6))
		local listTop = headerHeight + if searchVisible then searchHeight + 8 else 0
		local contentHeight = visibleRows * rowHeight + math.max(0, visibleRows - 1) * rowGap
		local popupHeight = math.min(300, popupPadding * 2 + listTop + contentHeight)
		local popupSize = UDim2.fromOffset(math.max(220, b.AbsoluteSize.X), popupHeight)
		local enterPresetName = if multi and presenceOptions then presenceOptions.enter else nil
		local containerDuration = dropdownMotionDuration(
			h,
			enterPresetName,
			RAYFIELD_DROPDOWN_REVEAL_MOTION.Time
		)
		local panelDuration = dropdownMotionDuration(h, enterPresetName, RAYFIELD_DROPDOWN_PANEL_MOTION.Time)
		if refreshing then
			(popup :: GuiObject).Size = popupSize
		else
			popup = Factory.make("Frame", {
				Active = true,
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				ClipsDescendants = true,
				Size = if presenceOptions then UDim2.fromOffset(popupSize.X.Offset, 0) else popupSize,
				ZIndex = h._context.Theme.zIndex.popup,
			}, h._context.Portal) :: GuiObject
			popup:SetAttribute("RayfieldMotionContainer", "reveal")
			popup:SetAttribute("RayfieldMotionContainerDuration", containerDuration)
		end
		popupPanel = Factory.make("CanvasGroup", {
			Name = "PotassiumDropdownPanel",
			Active = false,
			BackgroundColor3 = h._context.Theme.colors.popup,
			BorderSizePixel = 0,
			GroupTransparency = if refreshing or presenceOptions == nil then 0 else 1,
			Size = UDim2.fromScale(1, 1),
			ZIndex = h._context.Theme.zIndex.popup,
		}, popup) :: CanvasGroup
		popupPanel:SetAttribute("RayfieldMotionPanel", "opacity")
		popupPanel:SetAttribute("RayfieldMotionPanelDuration", panelDuration)
		if not refreshing then Factory.corner(popup :: GuiObject, h._context.Theme.radius.md) end
		Factory.corner(popupPanel, h._context.Theme.radius.md)
		local popupSurface = Factory.surface(
			popupPanel,
			h._context.Theme,
			"raised",
			{ popup = true, glassDecorations = true }
		)
		local popupSurfaceStroke = popupPanel:FindFirstChild("PotassiumSurfaceBorder")
		local popupSurfaceStrokeTransparency = if popupSurfaceStroke and popupSurfaceStroke:IsA("UIStroke")
			then popupSurfaceStroke.Transparency
			else nil
		if multi then
			if not refreshing and presenceOptions and popupSurfaceStroke and popupSurfaceStroke:IsA("UIStroke") then
				popupSurfaceStroke.Transparency = 1
				popupSurfaceStroke:SetAttribute("RayfieldMotionStroke", "opacity")
				popupSurfaceStroke:SetAttribute("RayfieldMotionDuration", panelDuration)
			end
		else
			popupMaid:GiveTask(popupSurface)
		end
		if multi then
			local header = Factory.make("Frame", {
				Name = "PotassiumDropdownHeader",
				Active = false,
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Size = UDim2.new(1, 0, 0, headerHeight),
				ZIndex = h._context.Theme.zIndex.popup + 1,
			}, popupPanel) :: Frame
			Factory.text(header, tostring(o.Title or o.Name or "Dropdown"), 14, h._context.Theme.colors.text, {
				Name = "PotassiumDropdownTitle",
				Size = UDim2.new(0.65, 0, 1, 0),
				TextXAlignment = Enum.TextXAlignment.Left,
				TextYAlignment = Enum.TextYAlignment.Center,
			})
			Factory.text(header, tostring(selectedCount) .. " / " .. tostring(#items), 13, h._context.Theme.colors.textMuted, {
				Name = "PotassiumDropdownCount",
				AnchorPoint = Vector2.new(1, 0),
				Position = UDim2.fromScale(1, 0),
				Size = UDim2.new(0.35, 0, 1, 0),
				TextXAlignment = Enum.TextXAlignment.Right,
				TextYAlignment = Enum.TextYAlignment.Center,
			})
		end
		local shadow = Factory.windowShadow(popupPanel, h._context.Theme)
		if multi then
			popupShadow = shadow
		else
			popupMaid:GiveTask(shadow)
		end
		Factory.padding(popupPanel, popupPadding)
		if Factory.placePopup then
			Factory.placePopup(popup, b)
		else
			popup.Position = UDim2.fromOffset(b.AbsolutePosition.X, b.AbsolutePosition.Y + b.AbsoluteSize.Y + 4)
		end
		local q = Factory.make("TextBox", {
			BackgroundColor3 = h._context.Theme.states.default.background,
			BorderSizePixel = 0,
			ClearTextOnFocus = false,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Center,
			PlaceholderText = "Search…",
			Text = query,
			TextColor3 = h._context.Theme.colors.text,
			PlaceholderColor3 = h._context.Theme.colors.textMuted,
			TextSize = h._context.Theme.typography.body * h._context.Theme.textScale,
			Font = h._context.Theme.font,
			FontFace = h._context.Theme.fontFace,
			Position = UDim2.fromOffset(0, headerHeight),
			Size = UDim2.new(1, 0, 0, searchHeight),
			ZIndex = h._context.Theme.zIndex.popup + 1,
			Selectable = searchVisible,
			Visible = searchVisible,
		}, popupPanel) :: TextBox
		popupQuery = q
		Factory.corner(q, h._context.Theme.radius.sm)
		local searchStroke = Factory.make("UIStroke", {
			Color = h._context.Theme.colors.borderStrong,
			Transparency = if refreshing or presenceOptions == nil then 0 else 1,
			Thickness = 1,
		}, q) :: UIStroke
		searchStroke:SetAttribute("RayfieldMotionStroke", "opacity")
		searchStroke:SetAttribute("RayfieldMotionDuration", panelDuration)
		local searchIcon = Factory.make("CanvasGroup", {
			Name = "PotassiumDropdownSearchIcon",
			Active = false,
			AnchorPoint = Vector2.new(1, 0.5),
			BackgroundTransparency = 1,
			GroupTransparency = if refreshing or presenceOptions == nil then 0 else 1,
			Position = UDim2.new(1, -8, 0.5, 0),
			Size = UDim2.fromOffset(16, 16),
			Visible = searchVisible,
			ZIndex = h._context.Theme.zIndex.popup + 2,
		}, q) :: CanvasGroup
		searchIcon:SetAttribute("RayfieldMotionSearchIcon", "opacity")
		searchIcon:SetAttribute("RayfieldMotionDuration", panelDuration)
		h._context.Icons.Render(searchIcon, "search", h._context.Theme, 16, {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(16, 16),
			ZIndex = searchIcon.ZIndex,
		})
		local queryFocusId = modal .. ".query"
		if searchVisible then
			h._context.FocusManager:Register(queryFocusId, q, { order = 1, group = modal })
			table.insert(popupFocusIds, queryFocusId)
		end
		Factory.padding(q, 8)
		local list = Factory.make("ScrollingFrame", {
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Position = UDim2.fromOffset(0, listTop),
			Size = UDim2.new(1, 0, 1, -listTop),
			CanvasSize = UDim2.new(),
			AutomaticCanvasSize = Enum.AutomaticSize.Y,
			ScrollBarThickness = 2,
			ScrollBarImageColor3 = h._context.Theme.colors.borderStrong:Lerp(h._context.Theme.accentA, 0.28),
			ZIndex = h._context.Theme.zIndex.popup + 1,
		}, popupPanel) :: ScrollingFrame
		Factory.list(list, rowGap)
		local rendered, selected = 0, 1
		local resultActions = {}
		if not ok then
			Factory.text(
				list,
				"Unable to load: " .. tostring(loadError),
				14,
				h._context.Theme.states.danger.text,
				{ Size = UDim2.new(1, 0, 0, metric(h._context, "inputHeight")), TextWrapped = true }
			)
		else
			for choiceIndex, item in ipairs(items) do
				local title = valueText(item)
				if query == "" or string.find(string.lower(title), string.lower(query), 1, true) then
					rendered += 1
					if rendered > MAX_RESULTS then
						break
					end
					local value = valueOf(item)
					local row = Factory.button(
						list,
						title,
						h._context.Theme,
						{
							Role = "ghost",
							AnimatePress = false,
							BackgroundTransparency = if multi then 1 else 0,
							Size = UDim2.new(1, 0, 0, rowHeight),
							ZIndex = h._context.Theme.zIndex.popup + 2,
						}
					)
					row:SetAttribute("PotassiumDropdownChoiceIndex", choiceIndex)
					local currentValue = currentSelection
					local chosen = if positionalArray then currentValue[1] == value else currentValue == value
					if multi then
						chosen = false
						for _, selectedValue in ipairs(currentValue) do
							if selectedValue == value then
								chosen = true
								break
							end
						end
					end
					local disabled = multi and limit ~= nil and limit ~= 1 and #currentValue >= limit and not chosen
					row:SetAttribute("PotassiumDropdownLimitDisabled", disabled)
					if disabled then
						row.Active = false
						row.Selectable = false
					end
					local selectionLayer = Factory.make("Frame", {
						Name = "PotassiumDropdownSelection",
						Active = false,
						BackgroundColor3 = h._context.Theme.colors.popup:Lerp(h._context.Theme.accentA, 0.07),
						BorderSizePixel = 0,
						Size = UDim2.fromScale(1, 1),
						Visible = chosen,
						ZIndex = row.ZIndex,
					}, row) :: Frame
					Factory.corner(selectionLayer, h._context.Theme.radius.sm)
					local accentRail = Factory.make("Frame", {
						Name = "PotassiumDropdownAccent",
						Active = false,
						AnchorPoint = Vector2.new(0, 0.5),
						BackgroundColor3 = h._context.Theme.accentA,
						BorderSizePixel = 0,
						Position = UDim2.new(0, 3, 0.5, 0),
						Size = UDim2.fromOffset(2, 18),
						Visible = chosen,
						ZIndex = row.ZIndex + 1,
					}, selectionLayer) :: Frame
					Factory.corner(accentRail, 2)
					local checkbox: Frame?
					if multi then
						checkbox = Factory.make("Frame", {
							Name = "PotassiumDropdownCheckbox",
							Active = false,
							AnchorPoint = Vector2.new(0, 0.5),
							BackgroundColor3 = if chosen then h._context.Theme.accentA else h._context.Theme.colors.popup,
							BorderSizePixel = 0,
							Position = UDim2.new(0, h._context.Theme.spacing.md, 0.5, 0),
							Size = UDim2.fromOffset(16, 16),
							ZIndex = row.ZIndex + 2,
						}, row) :: Frame
						Factory.corner(checkbox, h._context.Theme.radius.sm)
						Factory.make("UIStroke", {
							Color = if chosen then h._context.Theme.accentA else h._context.Theme.colors.borderStrong,
							Thickness = 1,
						}, checkbox)
						if chosen then
							h._context.Icons.Render(checkbox, "check", h._context.Theme, 14, {
								AnchorPoint = Vector2.new(0.5, 0.5),
								Position = UDim2.fromScale(0.5, 0.5),
								Size = UDim2.fromOffset(12, 12),
								ZIndex = checkbox.ZIndex + 1,
							})
						end
					end
					local rowContent = Factory.buttonContent(row, title, h._context.Theme, {
						Icon = if multi then nil else if chosen then "check" else nil,
						IconPosition = "right",
						IconSize = math.max(12, metric(h._context, "iconSize") - 1),
						Insets = {
							left = if multi then h._context.Theme.spacing.md + 24 else h._context.Theme.spacing.md,
							right = h._context.Theme.spacing.sm,
						},
						TextXAlignment = Enum.TextXAlignment.Left,
						Icons = h._context.Icons,
					})
					local rowLabel = rowContent.Label
					if rowLabel and rowLabel:IsA("TextLabel") then
						rowLabel.TextColor3 = if disabled
							then h._context.Theme.colors.textMuted
							else if multi and chosen then h._context.Theme.accentA else h._context.Theme.colors.text
					end
					row:SetAttribute("RayfieldMotionOptionHoverDuration", RAYFIELD_DROPDOWN_HOVER_MOTION.Time)
					selectionLayer:SetAttribute("RayfieldMotionOptionSelectionDuration", RAYFIELD_DROPDOWN_OPTION_MOTION.Time)
					local function setOptionHover(hovered: boolean)
						if disabled then
							return
						end
						local background = if hovered
							then h._context.Theme.states.hover.background
							else if multi then h._context.Theme.colors.popup else h._context.Theme.states.default.background
						local text = if multi and chosen
							then h._context.Theme.accentA
							else if hovered then h._context.Theme.states.hover.text else h._context.Theme.states.default.text
						if presenceOptions then
							dropdownAnimate(h, popupMaid, row, {
								BackgroundColor3 = background,
								TextColor3 = text,
							}, RAYFIELD_DROPDOWN_HOVER_MOTION)
						else
							row.BackgroundColor3 = background
							row.TextColor3 = text
						end
						if rowLabel and rowLabel:IsA("TextLabel") then
							rowLabel.TextColor3 = text
						end
					end
					popupMaid:GiveTask(row.MouseEnter:Connect(function()
						setOptionHover(true)
					end))
					popupMaid:GiveTask(row.MouseLeave:Connect(function()
						setOptionHover(false)
					end))
					local function activateChoice()
						if not active(h) or disabled then
							return
						end
						local activatedPopup, activatedSerial = popup, popupSerial
						local cur = h:Get()
						if multi then
							local out, found = {}, false
							for _, x in ipairs(cur) do
								if x == value then
									found = true
								else
									table.insert(out, x)
								end
							end
							if not found then
								if limit == 1 then
									table.clear(out)
								elseif limit and #out >= limit then
									return
								end
								table.insert(out, value)
							end
							h:Set(out, { Source = "user" })
							if h._destroyed or popup ~= activatedPopup or popupSerial ~= activatedSerial then return end
							selectionHaptic(h)
							focusedChoiceIndex = choiceIndex
							open(true)
							return
						else
							selectionLayer.Visible = true
							accentRail.Visible = true
							selectionLayer.BackgroundTransparency = 1
							dropdownAnimate(
								h,
								popupMaid,
								selectionLayer,
								{ BackgroundTransparency = 0 },
								RAYFIELD_DROPDOWN_OPTION_MOTION
							)
							rowContent:Apply(h._context.Theme, {
								Icon = "check",
								IconPosition = "right",
								IconSize = math.max(12, metric(h._context, "iconSize") - 1),
								Insets = { left = h._context.Theme.spacing.md, right = h._context.Theme.spacing.sm },
								TextXAlignment = Enum.TextXAlignment.Left,
								Icons = h._context.Icons,
							})
							h:Set(if positionalArray then { value } else value, { Source = "user" })
							if h._destroyed or popup ~= activatedPopup or popupSerial ~= activatedSerial then return end
							local choicePopup = popup
							local choiceSerial = popupSerial
							popupMaid:GiveTask(task.delay(0.1, function()
								if popup == choicePopup and popupSerial == choiceSerial then
									close()
								end
							end))
						end
						selectionHaptic(h)
					end
					if not disabled then
						table.insert(resultActions, { button = row, activate = activateChoice, choiceIndex = choiceIndex })
						popupMaid:GiveTask(row.Activated:Connect(activateChoice))
						local resultFocusId = modal .. ".choice." .. tostring(choiceIndex)
						h._context.FocusManager:Register(resultFocusId, row, { order = choiceIndex + 1, group = modal })
						table.insert(popupFocusIds, resultFocusId)
					end
				end
			end
		end
		if rendered == 0 and ok then
			Factory.text(
				list,
				"No results",
				14,
				h._context.Theme.colors.textMuted,
				{ Size = UDim2.new(1, 0, 0, metric(h._context, "inputHeight")), TextXAlignment = Enum.TextXAlignment.Center }
			)
		end
		local function selectResult(nextIndex: number)
			if #resultActions == 0 then
				return
			end
			selected = math.clamp(nextIndex, 1, #resultActions)
			for index, result in ipairs(resultActions) do
				Factory.setButtonState(
					result.button,
					if index == selected then "focused" else "default",
					h._context.Theme
				)
			end
			focusedChoiceIndex = resultActions[selected].choiceIndex
			h._context.FocusManager:SetFocused(resultActions[selected].button, "dropdown")
			h._context.Runtime.services.GuiService.SelectedObject = resultActions[selected].button
		end
		if searchVisible then
			popupMaid:GiveTask(q:GetPropertyChangedSignal("Text"):Connect(function()
				query = q.Text
				open(true)
			end))
		end
		popupMaid:GiveTask(q.InputBegan:Connect(function(input)
			if input.KeyCode == Enum.KeyCode.Down or input.KeyCode == Enum.KeyCode.DPadDown then
				selectResult(selected + 1)
			elseif input.KeyCode == Enum.KeyCode.Up or input.KeyCode == Enum.KeyCode.DPadUp then
				selectResult(selected - 1)
			elseif input.KeyCode == Enum.KeyCode.Return or input.KeyCode == Enum.KeyCode.ButtonA then
				if resultActions[selected] then
					resultActions[selected].activate()
				end
			end
		end))
		h._context.InputRouter:PushModal(modal, {
			OnBack = function()
				close()
			end,
			OnPointerBegan = function(_self: any, input: InputObject)
				if
					popup
					and not (
						input.Position.X >= popup.AbsolutePosition.X
						and input.Position.X <= popup.AbsolutePosition.X + popup.AbsoluteSize.X
						and input.Position.Y >= popup.AbsolutePosition.Y
						and input.Position.Y <= popup.AbsolutePosition.Y + popup.AbsoluteSize.Y
					)
				then
					close()
				end
				return true
			end,
		})
		local restoredIndex: number? = nil
		if not priorQueryWasFocused and priorFocusedChoiceIndex then
			restoredIndex = 1
			for index, result in ipairs(resultActions) do
				if result.choiceIndex == priorFocusedChoiceIndex then
					restoredIndex = index
					break
				end
			end
		end
		local modalFocus = if priorQueryWasFocused
			then q
			else if restoredIndex
				then resultActions[restoredIndex] and resultActions[restoredIndex].button or q
				else if searchVisible then q else resultActions[1] and resultActions[1].button or q
		h._context.FocusManager:PushModal(modal, modalFocus)
		if priorQueryWasFocused then
			q:CaptureFocus()
			q.CursorPosition = priorQueryCursorPosition :: number
			q.SelectionStart = priorQuerySelectionStart :: number
		elseif restoredIndex then
			q:ReleaseFocus()
			selectResult(restoredIndex)
		elseif searchVisible then
			q:CaptureFocus()
		else
			selectResult(1)
		end
		if presenceOptions and not refreshing and popup and popupPanel then
			if popupSurfaceStroke
				and popupSurfaceStroke:IsA("UIStroke")
				and popupSurfaceStrokeTransparency ~= nil
			then
				dropdownAnimate(
					h,
					popupMaid,
					popupSurfaceStroke,
					{ Transparency = popupSurfaceStrokeTransparency },
					RAYFIELD_DROPDOWN_PANEL_MOTION,
					enterPresetName
				)
			end
			dropdownAnimate(
				h,
				popupMaid,
				popupPanel,
				{ GroupTransparency = 0 },
				RAYFIELD_DROPDOWN_PANEL_MOTION,
				enterPresetName
			)
			dropdownAnimate(
				h,
				popupMaid,
				searchStroke,
				{ Transparency = 0 },
				RAYFIELD_DROPDOWN_PANEL_MOTION,
				enterPresetName
			)
			dropdownAnimate(
				h,
				popupMaid,
				searchIcon,
				{ GroupTransparency = 0 },
				RAYFIELD_DROPDOWN_PANEL_MOTION,
				enterPresetName
			)
			dropdownAnimate(
				h,
				popupMaid,
				popup,
				{ Size = popupSize },
				RAYFIELD_DROPDOWN_REVEAL_MOTION,
				enterPresetName
			)
		end
	end
	function h:_render(v: any)
		local valueLabel: string
		if #items == 0 then
			valueLabel = "No choices"
		elseif multi then
			local selectedCount = #v
			if selectedCount == 0 then
				valueLabel = "None"
			elseif selectedCount == #items then
				valueLabel = "All"
			else
				valueLabel = tostring(selectedCount) .. " / " .. tostring(#items)
			end
		else
			valueLabel = tostring(if positionalArray then v[1] else v)
		end
		triggerContent:SetText(valueLabel)
		if triggerContent.IconSlot then
			triggerContent.IconSlot.Position = UDim2.new(1, 0, 0.5, 1)
		end
		if triggerContent.Icon then
			triggerContent.Icon.Rotation = if popup then 180 else 0
			triggerContent.Icon:SetAttribute("MotionProfile", "rayfield-gen2")
			local chevronPresetName = if multi and presenceOptions
				then if popup then presenceOptions.enter else presenceOptions.exit
				else nil
			triggerContent.Icon:SetAttribute(
				"MotionDuration",
				dropdownMotionDuration(h, chevronPresetName, RAYFIELD_DROPDOWN_CHEVRON_MOTION.Time)
			)
		end
		apply(b, self)
		Factory.setButtonSurface(
			b,
			self._context.Theme.colors.background:Lerp(self._context.Theme.colors.surfaceRaised, 0.58)
		)
		b.Size = UDim2.new(
			(100 - metric(self._context, "labelWidth")) / 100,
			0,
			0,
			dropdownTriggerHeight(self._context, multi)
		)
	end
	local function reconcile(): any
		local v = h:Get()
		local changed = false
		if multi then
			local keep = {}
			for _, x in ipairs(v) do
				if valid({ x }) and (limit == nil or #keep < limit) then
					table.insert(keep, x)
				end
			end
			if #keep ~= #v then
				h:Set(keep)
				changed = true
			end
		else
			local good = valid(v)
			if not good then
				if #items > 0 then
					local replacement = valueOf(items[1])
					h:Set(if positionalArray then { replacement } else replacement)
					changed = true
				else
					close(true)
					h:_render(v)
					return { ok = false, code = "empty_choices", message = "Dropdown has no choices" }
				end
			end
		end
		if not changed and not h._destroyed then h:_render(v) end
		if popup ~= nil and not h._destroyed then open(true) end
		return { ok = true }
	end
	function h:Refresh()
		ok, items, loadError = choices(o)
		close()
		return reconcile()
	end
	function h:UpdateChoices(next: any)
		if type(next) ~= "table" then
			return { ok = false, code = "invalid_choices", message = "Choices must be an array" }
		end
		items = next
		close()
		return reconcile()
	end
	function h:AddChoice(x: any)
		table.insert(items, x)
		return reconcile()
	end
	function h:RemoveChoice(x: any)
		for n, q in ipairs(items) do
			if valueOf(q) == x then
				table.remove(items, n)
				return reconcile()
			end
		end
		return { ok = false, code = "unknown_choice", message = "Choice was not found" }
	end
	function h:ClearChoices()
		items = {}
		close()
		return reconcile()
	end
	local originalSetVisible, originalSetLocked = h.SetVisible, h.SetLocked
	function h:SetVisible(visible: boolean)
		if visible ~= true then close(true) end
		return originalSetVisible(self, visible)
	end
	function h:SetLocked(locked: boolean)
		if locked == true then close(true) end
		return originalSetLocked(self, locked)
	end
	h._maid:GiveTask(h.Root:GetPropertyChangedSignal("Visible"):Connect(function()
		if not h.Root.Visible then close(true) end
	end))
	function h:SetSearchable(v: boolean)
		o.Searchable = v == true
		return self
	end
	function h:SetMaxSelections(v: number?)
		limit = v
		return reconcile()
	end
	function h:SetRefresh(provider: any)
		o.Provider = provider
		return self
	end
	function h:Open()
		if active(self) and popup == nil then
			open()
		end
		return self
	end
	function h:Close(immediate: boolean?)
		close(immediate)
		return self
	end
	function h:TogglePopup()
		if popup then
			close()
		elseif active(self) then
			open()
		end
		return self
	end
	function h:IsOpen(): boolean
		return popup ~= nil
	end
	local originalDestroy = h.Destroy
	function h:Destroy()
		if self._destroyed then
			return
		end
		self:Close(true)
		originalDestroy(self)
	end
	h.Unload = h.Destroy
	h._maid:GiveTask(function()
		h:Close()
	end)
	h._maid:GiveTask(b.Activated:Connect(function()
		if active(h) then
			if popup then
				close()
			else
				open()
			end
		end
	end))
	focus(section, h, b)
	attachAsyncProvider(h, o, function(nextItems)
		h:UpdateChoices(nextItems)
	end)
	themeConnection(h)
	h:_render(h:Get())
	return h
end

function Controls.Colorpicker(section: any, o: any, defaultArg: any, callback: any, alpha: any?)
	o = positional(o, nil, defaultArg, callback)
	if o._positional then
		o.Alpha = alpha ~= nil
		if typeof(defaultArg) == "Color3" and type(alpha) == "number" then
			o.Default = { r = defaultArg.R, g = defaultArg.G, b = defaultArg.B, a = math.clamp(alpha, 0, 1) }
		end
		if type(callback) == "function" then
			o.Callback = function(value)
				local color = if typeof(value) == "Color3" then value else Color3.new(value.r, value.g, value.b)
				local alphaValue = if type(value) == "table" then value.a or 1 else 1
				callback(color, alphaValue)
			end
		end
	end
	local default = o.Default or { r = 1, g = 1, b = 1, a = 1 }
	local h = base(section, o, "Colorpicker", default, Store.Validators.color, Store.Normalizers.color)
	label(h, tostring(o.Title or o.Name or "Color"))
	local b = Factory.button(
		h.Root,
		"",
		h._context.Theme,
		if o._inline
			then { Size = UDim2.fromScale(1, 1) }
			else {
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, 0, 0.5, 0),
				Size = UDim2.new((100 - metric(h._context, "labelWidth")) / 100, 0, 0, metric(h._context, "inputHeight")),
			}
	)
	local popup: Frame?
	local modal = h.Id .. ".color"
	local popupFocusIds = {}
	local dragInput: InputObject? = nil
	local ownsTextEntry = false
	local function close()
		if dragInput then
			local input = dragInput
			dragInput = nil
			h._context.InputRouter:EndPointerDrag(input)
		end
		if ownsTextEntry then
			ownsTextEntry = false
			h._context.InputRouter:SetTextEntryActive(false)
		end
		if popup then
			h._context.InputRouter:PopModal(modal)
			h._context.FocusManager:PopModal(modal)
			for _, focusId in ipairs(popupFocusIds) do
				h._context.FocusManager:Unregister(focusId)
			end
			table.clear(popupFocusIds)
			local closingPopup = popup
			popup = nil
			closingPopup:Destroy()
		end
	end
	local function open()
		close()
		local raw = h:Get()
		local color = if typeof(raw) == "Color3" then raw else Color3.new(raw.r, raw.g, raw.b)
		local hue, sat, val = color:ToHSV()
		popup = Factory.make("Frame", {
			BackgroundColor3 = h._context.Theme.colors.surfaceRaised,
			BorderSizePixel = 0,
			Size = UDim2.fromOffset(280, if o.Alpha then 270 else 218),
			ZIndex = h._context.Theme.zIndex.popup,
		}, h._context.Portal) :: Frame
		local openedPopup = popup
		local function rgbaValue(): any
			local value = h:Get()
			return if typeof(value) == "Color3"
				then { r = value.R, g = value.G, b = value.B, a = 1 }
				else value
		end
		local function beginDrag(input: InputObject, move: (Vector2) -> ())
			if not active(h) or popup ~= openedPopup then return end
			if dragInput then h._context.InputRouter:EndPointerDrag(dragInput) end
			dragInput = input
			move(input.Position)
			if not active(h) or popup ~= openedPopup then return end
			h._context.InputRouter:BeginPointerDrag(input, function(position)
				if active(h) and popup == openedPopup and dragInput == input then move(position) end
			end, function()
				if dragInput == input then dragInput = nil end
			end)
		end
		Factory.corner(popup, h._context.Theme.radius.md)
		Factory.surface(popup, h._context.Theme, "raised", { popup = true, glassDecorations = true })
		Factory.windowShadow(popup, h._context.Theme)
		Factory.padding(popup, 8)
		if Factory.placePopup then
			Factory.placePopup(popup, b)
		else
			popup.Position = UDim2.fromOffset(b.AbsolutePosition.X, math.max(8, b.AbsolutePosition.Y - 220))
		end
		local sv = Factory.button(popup, "SV", h._context.Theme, {
			Position = UDim2.fromOffset(0, 0),
			Size = UDim2.fromOffset(210, 150),
			ZIndex = h._context.Theme.zIndex.popup + 1,
		})
		local hueButton = Factory.button(popup, "HUE", h._context.Theme, {
			Position = UDim2.fromOffset(218, 0),
			Size = UDim2.fromOffset(54, 150),
			ZIndex = h._context.Theme.zIndex.popup + 1,
		})
		sv.Text = ""
		hueButton.Text = ""
		local whiteLayer = Factory.make("Frame", {
			Active = false,
			BackgroundColor3 = Color3.new(1, 1, 1),
			BorderSizePixel = 0,
			Size = UDim2.fromScale(1, 1),
			ZIndex = sv.ZIndex + 1,
		}, sv) :: Frame
		Factory.make("UIGradient", {
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0),
				NumberSequenceKeypoint.new(1, 1),
			}),
		}, whiteLayer)
		local blackLayer = Factory.make("Frame", {
			Active = false,
			BackgroundColor3 = Color3.new(0, 0, 0),
			BorderSizePixel = 0,
			Size = UDim2.fromScale(1, 1),
			ZIndex = sv.ZIndex + 2,
		}, sv) :: Frame
		Factory.make("UIGradient", {
			Rotation = 90,
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1),
				NumberSequenceKeypoint.new(1, 0),
			}),
		}, blackLayer)
		Factory.make("UIGradient", {
			Rotation = 90,
			Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, Color3.fromHSV(0, 1, 1)),
				ColorSequenceKeypoint.new(0.17, Color3.fromHSV(0.17, 1, 1)),
				ColorSequenceKeypoint.new(0.33, Color3.fromHSV(0.33, 1, 1)),
				ColorSequenceKeypoint.new(0.5, Color3.fromHSV(0.5, 1, 1)),
				ColorSequenceKeypoint.new(0.67, Color3.fromHSV(0.67, 1, 1)),
				ColorSequenceKeypoint.new(0.83, Color3.fromHSV(0.83, 1, 1)),
				ColorSequenceKeypoint.new(1, Color3.fromHSV(1, 1, 1)),
			}),
		}, hueButton)
		local svMarker = Factory.make("Frame", {
			Active = false,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Size = UDim2.fromOffset(14, 14),
			ZIndex = sv.ZIndex + 3,
		}, sv) :: Frame
		Factory.corner(svMarker, 7)
		Factory.stroke(svMarker, Color3.new(1, 1, 1), 2)
		local hueMarker = Factory.make("Frame", {
			Active = false,
			BackgroundColor3 = Color3.new(1, 1, 1),
			BorderSizePixel = 0,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Size = UDim2.new(1, 4, 0, 3),
			ZIndex = hueButton.ZIndex + 2,
		}, hueButton) :: Frame
		Factory.stroke(hueMarker, Color3.new(0, 0, 0), 1)
		local output = Factory.make("TextBox", {
			BackgroundColor3 = h._context.Theme.states.default.background,
			BorderSizePixel = 0,
			ClearTextOnFocus = false,
			TextColor3 = h._context.Theme.colors.text,
			TextSize = h._context.Theme.typography.body * h._context.Theme.textScale,
			Font = h._context.Theme.font,
			FontFace = h._context.Theme.fontFace,
			Position = UDim2.fromOffset(0, 158),
			Size = UDim2.new(1, 0, 0, metric(h._context, "inputHeight")),
			ZIndex = h._context.Theme.zIndex.popup + 1,
			Selectable = true,
		}, popup) :: TextBox
		Factory.padding(output, 6)
		local alphaButton: TextButton? = nil
		local alphaMarker: Frame? = nil
		local function commit(previewOnly: boolean?)
			if not active(h) or popup ~= openedPopup then return end
			local c = Color3.fromHSV(hue, sat, val)
			local before = rgbaValue()
			if not previewOnly then
				h:Set({ r = c.R, g = c.G, b = c.B, a = if o.Alpha then (before.a or 1) else 1 }, { Source = "user" })
				if h._destroyed or popup ~= openedPopup then return end
			end
			output.Text = string.format(
				"#%02X%02X%02X  RGB %d, %d, %d",
				c.R * 255,
				c.G * 255,
				c.B * 255,
				c.R * 255,
				c.G * 255,
				c.B * 255
			)
			Factory.setButtonSurface(sv, Color3.fromHSV(hue, math.max(0.12, sat), math.max(0.16, val)))
			Factory.setButtonSurface(hueButton, Color3.fromHSV(hue, 1, 1))
			svMarker.Position = UDim2.fromScale(sat, 1 - val)
			hueMarker.Position = UDim2.fromScale(0.5, hue)
			if alphaMarker then
				alphaMarker.Position = UDim2.fromScale(if type(before) == "table" then before.a or 1 else 1, 0.5)
			end
			if alphaButton then
				alphaButton.Text =
					string.format("ALPHA %d%%", (if type(before) == "table" then before.a or 1 else 1) * 100)
			end
		end
		local function svMove(p: Vector2)
			sat = Util.clamp((p.X - sv.AbsolutePosition.X) / math.max(1, sv.AbsoluteSize.X), 0, 1)
			val = 1 - Util.clamp((p.Y - sv.AbsolutePosition.Y) / math.max(1, sv.AbsoluteSize.Y), 0, 1)
			commit()
		end
		local function hueMove(p: Vector2)
			hue = Util.clamp((p.Y - hueButton.AbsolutePosition.Y) / math.max(1, hueButton.AbsoluteSize.Y), 0, 1)
			commit()
		end
		for _, entry in ipairs({ { sv, svMove }, { hueButton, hueMove } }) do
			entry[1].InputBegan:Connect(function(input)
				if
					input.UserInputType == Enum.UserInputType.MouseButton1
					or input.UserInputType == Enum.UserInputType.Touch
				then
					beginDrag(input, entry[2])
				end
			end)
		end
		sv.InputBegan:Connect(function(input)
			if input.KeyCode == Enum.KeyCode.Left or input.KeyCode == Enum.KeyCode.DPadLeft then
				sat = Util.clamp(sat - 0.05, 0, 1)
				commit()
			elseif input.KeyCode == Enum.KeyCode.Right or input.KeyCode == Enum.KeyCode.DPadRight then
				sat = Util.clamp(sat + 0.05, 0, 1)
				commit()
			elseif input.KeyCode == Enum.KeyCode.Up or input.KeyCode == Enum.KeyCode.DPadUp then
				val = Util.clamp(val + 0.05, 0, 1)
				commit()
			elseif input.KeyCode == Enum.KeyCode.Down or input.KeyCode == Enum.KeyCode.DPadDown then
				val = Util.clamp(val - 0.05, 0, 1)
				commit()
			end
		end)
		hueButton.InputBegan:Connect(function(input)
			if input.KeyCode == Enum.KeyCode.Up or input.KeyCode == Enum.KeyCode.DPadUp then
				hue = (hue - 0.02) % 1
				commit()
			elseif input.KeyCode == Enum.KeyCode.Down or input.KeyCode == Enum.KeyCode.DPadDown then
				hue = (hue + 0.02) % 1
				commit()
			end
		end)
		output.Focused:Connect(function()
			ownsTextEntry = true
			h._context.InputRouter:SetTextEntryActive(true)
		end)
		output.FocusLost:Connect(function()
			if ownsTextEntry then
				ownsTextEntry = false
				h._context.InputRouter:SetTextEntryActive(false)
			end
			if not active(h) or popup ~= openedPopup then return end
			local hex = string.match(output.Text, "#?(%x%x%x%x%x%x)")
			if hex then
				local n = tonumber(hex, 16) or 0
				local c = Color3.fromRGB(math.floor(n / 65536) % 256, math.floor(n / 256) % 256, n % 256)
				hue, sat, val = c:ToHSV()
			end
			commit()
		end)
		if o.Alpha then
			local alpha = Factory.button(popup, "ALPHA", h._context.Theme, {
				Position = UDim2.fromOffset(0, 210),
				Size = UDim2.new(1, 0, 0, metric(h._context, "inputHeight")),
				ZIndex = h._context.Theme.zIndex.popup + 1,
			})
			alphaButton = alpha
			alphaMarker = Factory.make("Frame", {
				Active = false,
				BackgroundColor3 = h._context.Theme.colors.text,
				BorderSizePixel = 0,
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale((if type(h:Get()) == "table" then h:Get().a or 1 else 1), 0.5),
				Size = UDim2.fromOffset(3, 28),
				ZIndex = alpha.ZIndex + 2,
			}, alpha) :: Frame
			local function alphaMove(position: Vector2)
				if not active(h) or popup ~= openedPopup then return end
				local current = rgbaValue()
				current.a =
					Util.clamp((position.X - alpha.AbsolutePosition.X) / math.max(1, alpha.AbsoluteSize.X), 0, 1)
				h:Set(current, { Source = "user" })
				if h._destroyed or popup ~= openedPopup then return end
				alpha.Text = string.format("ALPHA %d%%", current.a * 100)
				if alphaMarker then
					alphaMarker.Position = UDim2.fromScale(current.a, 0.5)
				end
			end
			alpha.InputBegan:Connect(function(input)
				if not active(h) or popup ~= openedPopup then return end
				if
					input.UserInputType == Enum.UserInputType.MouseButton1
					or input.UserInputType == Enum.UserInputType.Touch
				then
					beginDrag(input, alphaMove)
				elseif input.KeyCode == Enum.KeyCode.Left or input.KeyCode == Enum.KeyCode.DPadLeft then
					local current = rgbaValue()
					current.a = Util.clamp(current.a - 0.05, 0, 1)
					h:Set(current, { Source = "user" })
					if h._destroyed or popup ~= openedPopup then return end
					alpha.Text = string.format("ALPHA %d%%", current.a * 100)
					if alphaMarker then
						alphaMarker.Position = UDim2.fromScale(current.a, 0.5)
					end
				elseif input.KeyCode == Enum.KeyCode.Right or input.KeyCode == Enum.KeyCode.DPadRight then
					local current = rgbaValue()
					current.a = Util.clamp(current.a + 0.05, 0, 1)
					h:Set(current, { Source = "user" })
					if h._destroyed or popup ~= openedPopup then return end
					alpha.Text = string.format("ALPHA %d%%", current.a * 100)
					if alphaMarker then
						alphaMarker.Position = UDim2.fromScale(current.a, 0.5)
					end
				end
			end)
		end
		commit(true)
		local popupFocus = {
			{ suffix = "sv", object = sv },
			{ suffix = "hue", object = hueButton },
			{ suffix = "hex", object = output },
		}
		if alphaButton then
			table.insert(popupFocus, { suffix = "alpha", object = alphaButton })
		end
		for order, entry in ipairs(popupFocus) do
			local focusId = modal .. "." .. entry.suffix
			h._context.FocusManager:Register(focusId, entry.object, { order = order, group = modal })
			table.insert(popupFocusIds, focusId)
		end
		h._context.InputRouter:PushModal(modal, {
			OnBack = function()
				close()
			end,
			OnPointerBegan = function(_owner: any, input: InputObject)
				if popup then
					local position, size = popup.AbsolutePosition, popup.AbsoluteSize
					local inside = input.Position.X >= position.X
						and input.Position.X <= position.X + size.X
						and input.Position.Y >= position.Y
						and input.Position.Y <= position.Y + size.Y
					if not inside then
						close()
					end
				end
				return true
			end,
		})
		h._context.FocusManager:PushModal(modal, sv)
	end
	function h:_render(v: any)
		local c = if typeof(v) == "Color3" then v else Color3.new(v.r, v.g, v.b)
		Factory.setButtonSurface(b, c)
		b.Text = string.format("#%02X%02X%02X", c.R * 255, c.G * 255, c.B * 255)
		apply(b, self)
		b.TextColor3 = if c.R * 0.299 + c.G * 0.587 + c.B * 0.114 > 0.55 then Color3.new() else Color3.new(1, 1, 1)
		if not o._inline then
			b.Size = UDim2.new(
				(100 - metric(self._context, "labelWidth")) / 100,
				0,
				0,
				metric(self._context, "inputHeight")
			)
		end
	end
	function h:Close()
		close()
		return self
	end
	local originalSetVisible, originalSetLocked = h.SetVisible, h.SetLocked
	function h:SetVisible(visible: boolean)
		if visible ~= true then close() end
		return originalSetVisible(self, visible)
	end
	function h:SetLocked(locked: boolean)
		if locked == true then close() end
		return originalSetLocked(self, locked)
	end
	h._maid:GiveTask(h.Root:GetPropertyChangedSignal("Visible"):Connect(function()
		if not h.Root.Visible then close() end
	end))
	h._maid:GiveTask(close)
	h._maid:GiveTask(b.Activated:Connect(function()
		if active(h) then
			if popup then
				close()
			else
				open()
			end
		end
	end))
	focus(section, h, b)
	themeConnection(h)
	h:_render(h:Get())
	return h
end

function Controls.Textbox(section: any, o: any, defaultArg: any, callback: any, tooltip: any?)
	o = positional(o, nil, defaultArg, callback)
	if o._positional then
		o.Tooltip = tooltip
	end
	local max = o.MaxLength or 512
	local h = base(section, o, "Textbox", tostring(o.Default or ""), Store.Validators.string(max))
	if o.Tooltip then
		h:Tooltip(o.Tooltip)
	end
	label(h, tostring(o.Title or o.Name or "Textbox"))
	local t = h._context.Theme
	local box = Factory.make("TextBox", {
		BackgroundColor3 = t.states.default.background,
		BorderSizePixel = 0,
		ClearTextOnFocus = false,
		PlaceholderText = tostring(o.Placeholder or ""),
		PlaceholderColor3 = t.colors.textMuted,
		TextColor3 = t.colors.text,
		TextSize = t.typography.body * t.textScale,
		LineHeight = t.typography.lineBody / t.typography.body,
		Font = t.font,
		FontFace = t.fontFace,
		TextXAlignment = Enum.TextXAlignment.Left,
		Size = UDim2.new((100 - metric(h._context, "labelWidth")) / 100, 0, 0, metric(h._context, "inputHeight")),
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, 0, 0.5, 0),
		Selectable = true,
	}, h.Root) :: TextBox
	Factory.corner(box, t.radius.md)
	Factory.padding(box, metric(h._context, "controlGap"))
	local ownsTextEntry = false
	function h:_render(v: string)
		local theme = h._context.Theme
		if box.Text ~= v then
			box.Text = v
		end
		box.BackgroundColor3 = theme.states.default.background
		box.TextColor3 = theme.colors.text
		box.PlaceholderColor3 = theme.colors.textMuted
		box.TextSize = theme.typography.body * theme.textScale
		box.LineHeight = theme.typography.lineBody / theme.typography.body
		local boxCorner = box:FindFirstChildWhichIsA("UICorner")
		if boxCorner then boxCorner.CornerRadius = UDim.new(0, theme.radius.md) end
		box.TextEditable = active(self)
		box.Size = UDim2.new(
			(100 - metric(self._context, "labelWidth")) / 100,
			0,
			0,
			metric(self._context, "inputHeight")
		)
	end
	h._maid:GiveTask(box.Focused:Connect(function()
		ownsTextEntry = true
		h._context.InputRouter:SetTextEntryActive(true)
	end))
	h._maid:GiveTask(box.FocusLost:Connect(function()
		ownsTextEntry = false
		h._context.InputRouter:SetTextEntryActive(false)
		h:Set(string.sub(box.Text, 1, max), { Source = "user" })
	end))
	h._maid:GiveTask(function()
		if ownsTextEntry then
			h._context.InputRouter:SetTextEntryActive(false)
		end
	end)
	h._maid:GiveTask(box:GetPropertyChangedSignal("Text"):Connect(function()
		if #box.Text > max then
			box.Text = string.sub(box.Text, 1, max)
		end
	end))
	focus(section, h, box)
	themeConnection(h)
	h:_render(h:Get())
	return h
end

function Controls.Keybind(section: any, o: any, defaultArg: any, callback: any, tooltip: any?)
	o = positional(o, nil, defaultArg, callback)
	if type(o) == "table" then
		o.Default = asKeyCode(o.Default or o.Key)
	end
		if o.Mode == nil then
			o.Mode = "Toggle"
		end
		assert(o.Mode == "Toggle" or o.Mode == "Hold" or o.Mode == "Always", "Keybind Mode must be Toggle, Hold, or Always")
	if o._positional then
		o.Tooltip = tooltip
		if type(callback) == "function" then
			o.Callback = function(value)
				local key = if typeof(value) == "EnumItem"
					then value.Name
					elseif type(value) == "table" and typeof(value.keyCode) == "EnumItem" then value.keyCode.Name
					else tostring(value)
				callback(string.lower(key))
			end
		end
	end
	local h = base(
		section,
		o,
		"Keybind",
		o.Default or o.Key or Enum.KeyCode.Unknown,
		Store.Validators.keybind,
		Store.Normalizers.keybind
	)
	if o.Tooltip then
		h:Tooltip(o.Tooltip)
	end
	label(h, tostring(o.Title or o.Name or "Keybind"))
	local b = Factory.button(
		h.Root,
		"",
		h._context.Theme,
		if o._inline
			then { Role = "control", Size = UDim2.fromScale(1, 1) }
			else {
				Role = "control",
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, 0, 0.5, 0),
				Size = UDim2.new(
					(100 - metric(h._context, "labelWidth")) / 100,
					0,
					0,
					metric(h._context, "inputHeight")
				),
			}
	)
	local capture, held, toggled = false, false, false
	local captureRelease: (() -> ())? = nil
	local registerId = h.Id .. ".activation"
	local registeredKey: Enum.KeyCode? = nil
	local registeredMode: string? = nil
	local holdCancel: (() -> ())? = nil
	local registeredSignature: string? = nil
	local registeredPresentation: any = nil
	local function unpack(v: any): any
		return if type(v) == "table" then v else { keyCode = v, mode = o.Mode or "Toggle" }
	end
	local function unregister()
		if registeredPresentation and registeredSignature then
		if holdCancel then holdCancel(); holdCancel = nil end
			registeredPresentation:UnregisterKeybind(registerId)
		end
		registeredKey = nil
		registeredMode = nil
		registeredSignature = nil
		registeredPresentation = nil
	end
	local function register()
		local p = h._context.Presentation
		local d = unpack(h:Get())
		local keyCode = if typeof(d.keyCode) == "EnumItem" and d.keyCode ~= Enum.KeyCode.Unknown then d.keyCode else nil
		local mode = d.mode or "Toggle"
		local signature = if keyCode then keyCode.Name .. "\0" .. tostring(mode) else nil
		if
			p == registeredPresentation
			and keyCode == registeredKey
			and mode == registeredMode
			and signature == registeredSignature
		then
			return
		end
		unregister()
		if p and keyCode then
			registeredKey = keyCode
			registeredMode = mode
			registeredSignature = signature
			registeredPresentation = p
			p:RegisterKeybind(registerId, { keys = { keyCode }, allowWhileTextEntry = false }, function()
				if not active(h) then
					return false
				end
				local currentMode = registeredMode
				if currentMode == "Toggle" then
					toggled = not toggled
				elseif currentMode == "Hold" then
					local threshold = tonumber(o.HoldThreshold) or 0
					if threshold > 0 then
						local router = h._context.InputRouter
						if router == nil or type(router.ScheduleHold) ~= "function" then return false end
						holdCancel = router:ScheduleHold(registerId, threshold, function()
							holdCancel = nil
							if not active(h) then return end
							held = true
							call(o.ActivationCallback, true, h:Get())
							if h._context.Haptics then h._context.Haptics:Play("confirm", function() return active(h) end) end
							p:_refreshHotkeyList()
						end, { disabled = h._locked, readOnly = false, allowWhileTextEntry = false })
						return true
					end
					held = true
				elseif currentMode ~= "Always" then
					return false
				end
				call(o.ActivationCallback, currentMode == "Always" or toggled or held, h:Get())
				p:_refreshHotkeyList()
				return true
			end, {
				Label = if o.OverlayLabel == false
					then nil
					else tostring(o.OverlayLabel or o.Title or o.Name or "Keybind"),
				Hidden = o.OverlayLabel == false,
				Order = o.OverlayOrder,
				Mode = mode,
				OnEnded = function(input)
					if registeredMode == "Hold" and input.KeyCode == registeredKey then
						if holdCancel then holdCancel(); holdCancel = nil end
						if not held then return end
						held = false
						call(o.ActivationCallback, false, h:Get())
						p:_refreshHotkeyList()
					end
				end,
				IsActive = function()
					return h:IsActive()
				end,
			})
		end
	end
	function h:IsActive()
		return active(self) and (registeredMode == "Always" or toggled or held)
	end
	function h:_render(v: any)
		local d = unpack(v)
		b.Text = if capture
			then "Press a key…"
			else tostring(if typeof(d.keyCode) == "EnumItem" then d.keyCode.Name else d.keyCode)
		apply(b, self, capture)
		register()
		if not o._inline then
			b.Size = UDim2.new(
				(100 - metric(self._context, "labelWidth")) / 100,
				0,
				0,
				metric(self._context, "inputHeight")
			)
		end
	end
	local function stopCapture(render: boolean)
		if not capture then return end
		capture = false
		local release = captureRelease
		captureRelease = nil
		if release then release() end
		if render and not h._destroyed then h:_render(h:Get()) end
	end
	local function beginCapture()
		if not active(h) then return end
		local router = h._context.InputRouter
		if router == nil or type(router.BeginCapture) ~= "function" then return end
		stopCapture(false)
		capture = true
		h:_render(h:Get())
		captureRelease = router:BeginCapture(h, function(input)
			if input.KeyCode == Enum.KeyCode.Escape then
				stopCapture(true)
				return true
			end
			if input.KeyCode == Enum.KeyCode.Delete then
				stopCapture(false)
				h:Set({ keyCode = Enum.KeyCode.Unknown, mode = o.Mode or "Toggle" }, { Source = "user" })
				return true
			end
			local keyCode = input.KeyCode
			if keyCode == Enum.KeyCode.Unknown and input.UserInputType == Enum.UserInputType.Touch then
				keyCode = Enum.KeyCode.ButtonA
			end
			if keyCode ~= Enum.KeyCode.Unknown then
				stopCapture(false)
				h:Set({ keyCode = keyCode, mode = o.Mode or "Toggle" }, { Source = "user" })
			end
			return true
		end, function()
			capture = false
			captureRelease = nil
			if not h._destroyed then h:_render(h:Get()) end
		end)
	end
	function h:Capture(): boolean
		beginCapture()
		return capture
	end
	h._maid:GiveTask(b.Activated:Connect(function()
		h:Capture()
	end))
	h._maid:GiveTask(function()
		stopCapture(false)
	end)

	h._maid:GiveTask(unregister)
	focus(section, h, b)
	themeConnection(h)
	h:_render(h:Get())
	return h
end

function Controls.Button(section: any, o: any, callback: any, tooltip: any?)
	if type(o) ~= "table" then
		o = { Title = o, Callback = callback, Tooltip = tooltip, _positional = true }
	end
	assert(type(o) == "table" and type(o.Callback) == "function", "Button requires Callback")
	local trailing = o.Layout == "trailing"
	local actionWidth = 112
	if trailing and o.ActionWidth ~= nil then
		actionWidth = tonumber(o.ActionWidth)
		assert(
			type(actionWidth) == "number"
				and actionWidth == actionWidth
				and actionWidth ~= math.huge
				and actionWidth ~= -math.huge
				and actionWidth > 0,
			"Button ActionWidth must be a finite positive number"
		)
	end
	local usesMetric = o.Height == nil
	local h = static(
		section,
		o,
		o.Height or metric(section._context, if trailing then "controlHeight" else "compactControlHeight"),
		if usesMetric then (if trailing then "controlHeight" else "compactControlHeight") else nil
	)
	local function standaloneHeight(): number
		local rowHeight = tonumber(o.Height) or metric(h._context, "compactControlHeight")
		return math.min(rowHeight, math.max(metric(h._context, "hitTargetMin"), metric(h._context, "searchHeight")))
	end
	h._risk = o.Risk or "default"
	h._locked = o.Locked == true
	h.Id = section:_fullId(o.Id or ("button-" .. tostring(h.Root.LayoutOrder)))
	if o.Tooltip then
		h:Tooltip(o.Tooltip)
	end
	if trailing then
		trailingCopy(h, tostring(o.Label or o.Name or "Button"), o.Description, actionWidth, o.DescriptionKey ~= nil)
	end
	local b = Factory.button(
		h.Root,
		tostring(o.Title or o.Name or "Button"),
		h._context.Theme,
		if trailing
			then {
				Name = "Action",
				Role = "control",
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, -8, 0.5, 0),
				Size = UDim2.fromOffset(actionWidth, metric(h._context, "inputHeight")),
			}
			else {
				Role = "control",
				AnchorPoint = Vector2.new(0, 0.5),
				Position = UDim2.fromScale(0, 0.5),
				Size = UDim2.new(1, 0, 0, standaloneHeight()),
			}
	)
	if trailing then
		h.Root:SetAttribute("ActionWidth", actionWidth)
	end
	h._text = b
	if trailing then
		syncTrailingTextMetadata(h, b, true)
		bindTheme(h, function()
			b.Size = UDim2.fromOffset(actionWidth, metric(h._context, "inputHeight"))
		end)
		if o.DescriptionKey then
			h:SetTranslation(o.DescriptionKey, o.Params, "Description")
		end
	end
	if o.TextKey or o.TitleKey then
		h:SetTranslation(o.TextKey or o.TitleKey, o.Params, "Text")
	end
	h._maid:GiveTask(b.Activated:Connect(function()
		if h._destroyed or not b.Active then
			return
		end
		local function run()
			call(o.Callback)
		end
		if
			h._risk == "danger"
			and h._context.Presentation
			and type(h._context.Presentation.ConfirmRisk) == "function"
		then
			h._context.Presentation:ConfirmRisk({
				Id = (o.Id or "button") .. ".confirm",
				Title = o.ConfirmTitle or "Confirm action",
				Text = o.ConfirmText or "This action may have consequences.",
				ThemeProvider = function()
					return h._context.Theme
				end,
				ThemeChanged = h._context.ThemeChanged,
				Callback = function(accepted: any)
					if accepted then
						run()
					end
				end,
			})
		else
			run()
		end
	end))
	function h:SetLocked(v: boolean)
		h._locked = v == true
		Factory.setButtonState(
			b,
			if h._locked then "disabled" elseif h._risk == "danger" then "danger" else "default",
			h._context.Theme
		)
		Factory.setInteractive(b, not h._locked, h._context.Theme)
		return self
	end
	function h:SetRisk(v: boolean | string)
		h._risk = if v == true then "danger" elseif v == false then "default" else v
		staticRisk(h, h._risk)
		Factory.setButtonState(
			b,
			if h._locked then "disabled" elseif h._risk == "danger" then "danger" else "default",
			h._context.Theme
		)
		return self
	end
	function h:IsActivated()
		return not h._destroyed and not h._locked and h._visible
	end
	function h:AddButton(x: any, callback: any?)
		if type(x) ~= "table" then
			local nextIndex = if h._trailing then #h._trailing:GetChildren() + 1 else 1
			x = { Id = h.Id .. "-button-" .. tostring(nextIndex), Title = x, Callback = callback }
		end
		if not h._trailing then
			local trailing = Factory.make("Frame", {
				BackgroundTransparency = 1,
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, 0, 0.5, 0),
				Size = UDim2.fromOffset(180, 40),
			}, h.Root) :: Frame
			Factory.list(trailing, 4, true)
			h._trailing = trailing
			b.Size = UDim2.new(1, -188, 0, standaloneHeight())
		end
		x._parent = h._trailing
		x._inline = true
		x._inlineOrder = #h._trailing:GetChildren()
		local child = Controls.Button(section, x)
		h._maid:GiveTask(child)
		return child
	end
	focus(section, h, b)
	registerSearch(section, h, o, "Button")
	bindTheme(h, function(theme)
		b.TextSize = theme.typography.body * theme.textScale
		if not trailing then
			b.Position = UDim2.fromScale(0, 0.5)
			b.Size = UDim2.new(b.Size.X.Scale, b.Size.X.Offset, 0, standaloneHeight())
		end
		Factory.setButtonState(
			b,
			if h._locked then "disabled" elseif h._risk == "danger" then "danger" else "default",
			theme
		)
		Factory.setInteractive(b, not h._locked, theme)
	end)
	return h
end
function Controls.Stat(section: any, o: any, initialArg: any)
	if type(o) ~= "table" then o = { Title = o, Value = initialArg } end
	local initial = if o.Value ~= nil then o.Value elseif o.Default ~= nil then o.Default else 0
	assert(type(initial) == "number", "Stat Value must be a number")
	local deltaMode = o.Delta or "absolute"
	local baselineMode = o.Baseline or "previous"
	local numberMotion = o.NumberMotion or "none"
	assert(deltaMode == "absolute" or deltaMode == "percentage" or deltaMode == "none", "Stat Delta must be absolute, percentage, or none")
	assert(baselineMode == "previous" or baselineMode == "initial" or baselineMode == "manual", "Stat Baseline must be previous, initial, or manual")
	assert(numberMotion == "roll" or numberMotion == "crossfade" or numberMotion == "none", "Stat NumberMotion must be roll, crossfade, or none")
	local h = static(section, o, o.Height or metric(section._context, "controlHeight"), if o.Height == nil then "controlHeight" else nil)
	h.Id = id(section, o, "Stat")
	h._locked, h._readOnly = true, true
	h._value, h._initial, h._baseline = initial, initial, if baselineMode == "manual" then (if type(o.BaselineValue) == "number" then o.BaselineValue else initial) else initial
	h._signal = Signal.new()
	local theme = h._context.Theme
	local title = Factory.text(h.Root, tostring(o.Title or o.Name or "Stat"), theme.typography.body * theme.textScale, theme.colors.textMuted, {
		Position = UDim2.new(0, 0, 0, 0), Size = UDim2.new(0.52, 0, 1, 0), TextXAlignment = Enum.TextXAlignment.Left,
		theme = theme, typographyRole = "body",
	})
	local valueLabel = Factory.text(h.Root, "", theme.typography.body * theme.textScale, theme.colors.text, {
		Position = UDim2.new(0.52, 0, 0, 0), Size = UDim2.new(0.32, 0, 1, 0), TextXAlignment = Enum.TextXAlignment.Right, Visible = false,
		theme = theme, fontRole = "strong", typographyRole = "body",
	})
	local deltaLabel = Factory.text(h.Root, "", theme.typography.caption * theme.textScale, theme.colors.textMuted, {
		Position = UDim2.new(0.85, 0, 0, 0), Size = UDim2.new(0.15, 0, 1, 0), TextXAlignment = Enum.TextXAlignment.Right,
		theme = theme, typographyRole = "caption",
	})
	local pool, digitMetrics = table.create(24), {}
	local activeBank = 1
	for index = 1, 24 do
		local segment = Factory.text(h.Root, "", theme.typography.body * theme.textScale, theme.colors.text, {
			Name = "DigitSegment" .. tostring(index), Visible = false, BackgroundTransparency = 1,
			TextXAlignment = Enum.TextXAlignment.Center, TextYAlignment = Enum.TextYAlignment.Center,
			theme = theme, typographyRole = "body",
		})
		pool[index] = segment
	end
	h._digitPool = pool
	local function format(value: number): string
		if type(o.Format) == "function" then return tostring(o.Format(value)) end
		if type(o.Precision) == "number" then return string.format("%." .. tostring(math.max(0, math.floor(o.Precision))) .. "f", value) end
		return tostring(value)
	end
	local function metricFor(segment: TextLabel): number
		local key = tostring(segment.Font) .. ":" .. tostring(segment.TextSize)
		local cached = digitMetrics[key]
		if cached == nil then
			cached = math.max(6, math.floor(segment.TextSize * 0.62 + 0.5))
			digitMetrics[key] = cached
		end
		return cached
	end
	local rollGeneration = 0
	local function stopMotion()
		rollGeneration += 1
		local motion = h._context.Motion
		if motion and type(motion.Cancel) == "function" then
			for _, segment in ipairs(pool) do
				motion:Cancel(segment)
			end
		end
	end
	h._maid:GiveTask(stopMotion)
	local function placeBank(bank: number, rendered: string, yScale: number, transparency: number)
		local count = #rendered
		local first = if bank == 1 then 1 else 13
		local width = metricFor(pool[first])
		for offset = 1, 12 do
			local segment = pool[first + offset - 1]
			local visible = offset <= count
			segment.Visible = visible
			if visible then
				segment.Text = string.sub(rendered, offset, offset)
				segment.TextTransparency = transparency
				segment.Position = UDim2.new(0.84, -((count - offset + 1) * width), yScale, 0)
				segment.Size = UDim2.fromOffset(width, math.max(1, h.Root.AbsoluteSize.Y))
			end
		end
	end
	local function present(rendered: string, previous: string?, motion: string)
		stopMotion()
		if #rendered > 12 then
			for _, segment in ipairs(pool) do segment.Visible = false end
			valueLabel.Text, valueLabel.Visible = rendered, true
			return
		end
		valueLabel.Visible = false
		local nextBank = if activeBank == 1 then 2 else 1
		if previous == nil or #previous > 12 or motion == "none" then
			placeBank(nextBank, rendered, 0, 0)
			placeBank(activeBank, "", 0, 1)
			activeBank = nextBank
			return
		end
		placeBank(activeBank, previous, 0, 0)
		placeBank(nextBank, rendered, if motion == "roll" then 1 else 0, if motion == "roll" then 0 else 1)
		local generation = rollGeneration
		local rollInfo = TweenInfo.new(0.55, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		for offset = 1, 12 do
			if generation ~= rollGeneration then
				return
			end
			local oldSegment = pool[(if activeBank == 1 then 0 else 12) + offset]
			local newSegment = pool[(if nextBank == 1 then 0 else 12) + offset]
			if oldSegment.Visible then
				motionTween(h, oldSegment, {
					TextTransparency = 1,
					Position = if motion == "roll" then UDim2.new(oldSegment.Position.X.Scale, oldSegment.Position.X.Offset, -1, 0) else oldSegment.Position,
				}, rollInfo)
			end
			if newSegment.Visible then
				motionTween(h, newSegment, {
					TextTransparency = 0,
					Position = if motion == "roll" then UDim2.new(newSegment.Position.X.Scale, newSegment.Position.X.Offset, 0, 0) else newSegment.Position,
				}, rollInfo)
			end
		end
		h.Root:SetAttribute("RayfieldMotionRollDuration", rollInfo.Time)
		activeBank = nextBank
	end
	local previousRendered: string? = nil
	local function render(value: number, oldValue: number?)
		local rendered = format(value)
		local baseline = h._baseline
		local change = value - baseline
		if deltaMode == "none" then
			deltaLabel.Text = ""
		elseif deltaMode == "percentage" then
			deltaLabel.Text = if baseline == 0 then "0%" else string.format("%+.1f%%", (change / math.abs(baseline)) * 100)
		else
			deltaLabel.Text = string.format("%+g", change)
		end
		local effectiveMotion = if h._context.Theme.reducedMotion == true then "none" else numberMotion
		present(rendered, previousRendered, effectiveMotion)
		previousRendered = rendered
		h.Root:SetAttribute("NumberMotion", effectiveMotion)
		h.Root:SetAttribute("PreviousValue", oldValue)
	end
	function h:Get() return self._value end
	function h:ValueSnapshot() return table.freeze({ id = self.Id, value = self._value, readOnly = true }) end
	function h:Set(value: any, options: any?)
		assert(type(value) == "number", "Stat value must be a number")
		local oldValue = self._value
		if baselineMode == "previous" then self._baseline = oldValue end
		self._value = value
		render(value, oldValue)
		if not (type(options) == "table" and options.Silent == true) then
			call(o.Callback, value, oldValue, self.Id, if type(options) == "table" and options.Source ~= nil then options.Source else "program")
		end
		self._signal:Fire(value, oldValue, self.Id, if type(options) == "table" and options.Source ~= nil then options.Source else "program")
		return self
	end
	function h:Reset(options: any?) return self:Set(self._initial, options) end
	function h:ResetBaseline(value: any?)
		self._baseline = if value == nil then self._value else value
		assert(type(self._baseline) == "number", "Stat baseline must be a number")
		render(self._value, self._value)
		return self
	end
	function h:GetDeltaSnapshot()
		local baseline = self._baseline
		local absolute = self._value - baseline
		return table.freeze({ value = self._value, baseline = baseline, absolute = absolute, percentage = if baseline == 0 then 0 else (absolute / math.abs(baseline)) * 100, mode = deltaMode })
	end
	function h:Observe(callback: any, options: any?)
		assert(type(callback) == "function", "Observe requires a callback")
		local connection = self._signal:Connect(callback)
		if type(options) == "table" and options.EmitInitial == true then callback(self._value, nil, self.Id, "program") end
		return connection
	end
	h._maid:GiveTask(h._signal)
	bindTheme(h, function(nextTheme)
		title.TextColor3, title.TextSize = nextTheme.colors.textMuted, nextTheme.typography.body * nextTheme.textScale
		valueLabel.TextColor3, valueLabel.TextSize = nextTheme.colors.text, nextTheme.typography.body * nextTheme.textScale
		deltaLabel.TextSize = nextTheme.typography.caption * nextTheme.textScale
		for _, segment in ipairs(pool) do segment.TextColor3, segment.TextSize = nextTheme.colors.text, nextTheme.typography.body * nextTheme.textScale end
		render(h._value, h._value)
	end)
	render(initial, initial)
	return h
end
function Controls.Label(section: any, o: any, text: any)
	if type(o) ~= "table" then
		o = { Title = if text == nil then o else text }
	end
	local h = static(section, o, o.Height or 28)
	local t = h._context.Theme
	local value = if o.Text ~= nil then o.Text else o.Title
	local producer = if type(value) == "function" then value else nil
	local initial = value
	if producer then
		local ok, produced = pcall(producer)
		initial = if ok then produced else "Unavailable"
	end
	h._text = Factory.text(
		h.Root,
		tostring(initial or ""),
		t.typography.body * t.textScale,
		t.colors.textMuted,
		{ Size = UDim2.fromScale(1, 1), TextWrapped = o.Wrap ~= false, TextTruncate = Enum.TextTruncate.None }
	)
	if o.TextKey or o.TitleKey then
		h:SetTranslation(o.TextKey or o.TitleKey, o.Params, "Text")
	end
	if producer then
		h._maid:GiveTask(task.spawn(function()
			while not h._destroyed do
				task.wait(0.5)
				if not h._destroyed and effectivelyVisible(h.Root) then
					local ok, produced = pcall(producer)
					if ok then
						h._text.Text = tostring(produced)
					end
				end
			end
		end))
	end
	h.Root.AutomaticSize = Enum.AutomaticSize.Y
	h.Root.Size = UDim2.new(1, 0, 0, 0)
	h._text.AutomaticSize = Enum.AutomaticSize.Y
	h._text.Size = UDim2.new(1, 0, 0, 0)
	h._text.TextYAlignment = Enum.TextYAlignment.Top
	bindTheme(h, function(theme)
		h._text.TextColor3 = theme.colors.textMuted
		h._text.TextSize = theme.typography.body * theme.textScale
	end)
	return h
end
function Controls.Info(section: any, o: any, text: any)
	return Controls.Label(section, o, text)
end
function Controls.Paragraph(section: any, o: any, text: any)
	if type(o) ~= "table" then
		o = { Title = if text == nil then o else text }
	end
	o.Height = o.Height or 64
	o.Wrap = true
	return Controls.Label(section, o)
end
function Controls.Divider(section: any, o: any)
	if type(o) ~= "table" then
		o = { Title = o }
	end
	local title = tostring(o.Title or "")
	local h = static(section, o, if title == "" then 1 else 24)
	h.Root.BackgroundTransparency = 1
	local leftLine = Factory.make("Frame", {
		BackgroundColor3 = h._context.Theme.colors.border,
		BorderSizePixel = 0,
		Position = UDim2.new(0, 0, 0.5, 0),
		Size = if title == "" then UDim2.new(1, 0, 0, 1) else UDim2.new(0.38, 0, 0, 1),
	}, h.Root) :: Frame
	local rightLine: Frame? = nil
	if title ~= "" then
		rightLine = Factory.make("Frame", {
			BackgroundColor3 = h._context.Theme.colors.border,
			BorderSizePixel = 0,
			Position = UDim2.new(0.62, 0, 0.5, 0),
			Size = UDim2.new(0.38, 0, 0, 1),
		}, h.Root) :: Frame
		h._text = Factory.text(
			h.Root,
			title,
			h._context.Theme.typography.caption * h._context.Theme.textScale,
			h._context.Theme.colors.textMuted,
			{
				Position = UDim2.new(0.38, 4, 0, 0),
				Size = UDim2.new(0.24, -8, 1, 0),
				TextXAlignment = Enum.TextXAlignment.Center,
			}
		)
	end
	bindTheme(h, function(theme)
		leftLine.BackgroundColor3 = theme.colors.border
		if rightLine then
			rightLine.BackgroundColor3 = theme.colors.border
		end
		if h._text then
			h._text.TextColor3 = theme.colors.textMuted
			h._text.TextSize = theme.typography.caption * theme.textScale
		end
	end)
	return h
end
function Controls.Custom(section: any, name: any, o: any)
	assert(type(o) == "table", "Custom requires options")
	local factory, factoryError = section._context:_resolveControlFactory(name)
	if factory == nil then
		error(factoryError.message, 2)
	end

	local h = base(section, o, tostring(name), o.Default, o.Validate or o.Validator, o.Normalize or o.Normalizer)
	h.ControlType = tostring(name)

	local renderer: any = nil
	local primaryFocus: GuiObject? = nil
	local tooltipTarget: GuiObject = h.Root
	local tooltipTaskKey = {}
	local pluginContext: any

	local function installTooltip()
		h._maid:Set(tooltipTaskKey, nil)
		local text = h._tooltip
		if text == nil or text == "" then
			tooltipTarget:SetAttribute("Tooltip", nil)
			return
		end
		local presentation = h._context.Presentation
		if presentation and type(presentation.RegisterTooltip) == "function" then
			local target = tooltipTarget
			presentation:RegisterTooltip(target, text, function()
				return h._context.Theme
			end, h._context.ThemeChanged)
			h._maid:Set(tooltipTaskKey, function()
				presentation:UnregisterTooltip(target)
			end)
		else
			tooltipTarget:SetAttribute("Tooltip", text)
			h._maid:Set(tooltipTaskKey, function()
				tooltipTarget:SetAttribute("Tooltip", nil)
			end)
		end
	end

	function h:Tooltip(value: any)
		self._tooltip = if value == nil then nil else tostring(value)
		installTooltip()
		return self
	end

	function h:_render(value: any)
		if renderer ~= nil then
			Util.safeCallback(renderer, value, self._context.Theme, self)
		end
	end

	pluginContext = {
		Root = h.Root,
		Id = h.Id,
		Options = o,
		Handle = h,
		Theme = h._context.Theme,
		ThemeChanged = h._context.ThemeChanged,
		Motion = h._context.Motion,
	}
	if h._context.ThemeChanged then
		h._maid:GiveTask(h._context.ThemeChanged:Connect(function(theme: any)
			pluginContext.Theme = theme
			if h._context._themeTransitionActive == true and renderer ~= nil then
				h:_render(h:Get())
			end
		end))
	end

	function pluginContext:Create(className: string, properties: any?, parent: Instance?): Instance
		return Factory.make(className, properties or {}, parent or h.Root)
	end

	function pluginContext:GiveTask(taskValue: any): any
		return h._maid:GiveTask(taskValue)
	end

	function pluginContext:Connect(signal: any, callback: (...any) -> ()): any
		assert(signal ~= nil and type(signal.Connect) == "function", "Connect requires a signal")
		assert(type(callback) == "function", "Connect requires a callback")
		local connection = signal:Connect(callback)
		h._maid:GiveTask(connection)
		return connection
	end

	function pluginContext:OnThemeChanged(callback: (any) -> ()): any
		assert(type(callback) == "function", "OnThemeChanged requires a callback")
		Util.safeCallback(callback, h._context.Theme)
		if h._context.ThemeChanged == nil then
			return nil
		end
		return self:Connect(h._context.ThemeChanged, callback)
	end

	function pluginContext:GetTheme(): any
		return h._context.Theme
	end

	function pluginContext:Get(): any
		return h:Get()
	end

	function pluginContext:Set(value: any): any
		h:Set(value)
		return h
	end

	function pluginContext:Reset(): any
		h:Reset()
		return h
	end

	function pluginContext:SetRenderer(callback: (any, any, any) -> ())
		assert(type(callback) == "function", "SetRenderer requires a callback")
		renderer = callback
	end
	function pluginContext:SetSpotlightAction(callback: () -> ())
		assert(type(callback) == "function", "SetSpotlightAction requires a callback")
		h._spotlightActivate = callback
	end

	function pluginContext:RegisterFocus(object: GuiObject, suffix: any?): GuiObject
		assert(typeof(object) == "Instance" and object:IsA("GuiObject"), "RegisterFocus requires a GuiObject")
		local focusId = h.Id
		if suffix ~= nil and tostring(suffix) ~= "" then
			focusId ..= "." .. Util.sanitizeId(suffix)
		end
		section:_focus(focusId, object, h._maid)
		if primaryFocus == nil then
			primaryFocus = object
		end
		return object
	end

	function pluginContext:SetTooltipTarget(object: GuiObject): GuiObject
		assert(typeof(object) == "Instance" and object:IsA("GuiObject"), "SetTooltipTarget requires a GuiObject")
		tooltipTarget = object
		installTooltip()
		return object
	end

	function pluginContext:Expose(methodName: string, value: any)
		assert(
			type(methodName) == "string" and methodName ~= "" and string.sub(methodName, 1, 1) ~= "_",
			"Expose requires a public method name"
		)
		assert(h[methodName] == nil, "Custom control cannot replace handle member: " .. methodName)
		h[methodName] = value
	end

	local ok, result = pcall(factory, pluginContext)
	if not ok then
		h:Destroy()
		error("Custom control " .. tostring(name) .. " factory failed: " .. tostring(result), 2)
	end
	if result ~= nil and type(result) ~= "table" and type(result) ~= "function" then
		h:Destroy()
		error("Custom control factory must return nil, a cleanup function, or a descriptor table", 2)
	end

	local configured, configureError = pcall(function()
		if type(result) == "function" then
			h._maid:GiveTask(result)
		elseif type(result) == "table" then
			if result.Destroy ~= nil then
				assert(type(result.Destroy) == "function", "Custom control descriptor Destroy must be a function")
				h._maid:GiveTask(function()
					result:Destroy()
				end)
			elseif result.Cleanup ~= nil then
				assert(type(result.Cleanup) == "function", "Custom control descriptor Cleanup must be a function")
				h._maid:GiveTask(function()
					result:Cleanup()
				end)
			end
			if result.Render ~= nil then
				assert(type(result.Render) == "function", "Custom control descriptor Render must be a function")
				renderer = result.Render
			end
			if result.Activate ~= nil then
				assert(type(result.Activate) == "function", "Custom control descriptor Activate must be a function")
				h._spotlightActivate = function()
					result.Activate(h)
				end
			end
			if result.Focus ~= nil then
				pluginContext:RegisterFocus(result.Focus)
			end
			if result.TooltipTarget ~= nil then
				pluginContext:SetTooltipTarget(result.TooltipTarget)
			end
			if result.Api ~= nil then
				assert(type(result.Api) == "table", "Custom control descriptor Api must be a table")
				for methodName, value in pairs(result.Api) do
					pluginContext:Expose(methodName, value)
				end
			end
		end
	end)
	if not configured then
		h:Destroy()
		error("Custom control " .. tostring(name) .. " descriptor failed: " .. tostring(configureError), 2)
	end

	if h._spotlightActivate == nil and primaryFocus ~= nil then
		h._spotlightActivate = function()
			h._context.FocusManager:SetFocused(primaryFocus, "spotlight")
		end
	end
	if h._spotlightActivate == nil and type(o.Callback) ~= "function" then
		local presentation = h._context.Presentation
		if presentation and type(presentation.UnregisterSearch) == "function" then
			presentation:UnregisterSearch(h.Id)
		end
	end
	if o.Tooltip ~= nil then
		h:Tooltip(o.Tooltip)
	end
	themeConnection(h)
	h:_render(h:Get())
	return h
end

function Controls.ListView(section: any, o: any)
	assert(type(o) == "table", "ListView requires options")
	local options = {}
	for key, value in pairs(o) do
		options[key] = value
	end
	local listHeight = math.max(120, tonumber(o.Height) or 240)
	local rowHeight = math.max(28, tonumber(o.RowHeight) or 40)
	local overscan = math.max(0, math.floor(tonumber(o.Overscan) or 2))
	options.Height = listHeight
	options.Persist = o.Persist == true
	local multiSelect = o.MultiSelect == true
	local maxSelections = if o.MaxSelections ~= nil then math.max(1, math.floor(tonumber(o.MaxSelections) or 1)) else nil

	local function keyFor(item: any, index: number): string | number | boolean
		local key: any = nil
		if type(o.Key) == "function" then
			key = o.Key(item, index)
		elseif type(o.Key) == "string" and type(item) == "table" then
			key = item[o.Key]
		elseif type(item) == "table" then
			key = item.Id
			if key == nil then
				key = item.Key
			end
			if key == nil then
				key = item.Value
			end
		else
			key = item
		end
		if key == nil then
			key = index
		end
		local keyType = type(key)
		assert(
			keyType == "string" or keyType == "number" or keyType == "boolean",
			"ListView keys must be strings, numbers, or booleans"
		)
		return key
	end

	local function prepare(source: any): ({ any }, { [any]: number }, { string | number | boolean })
		assert(type(source) == "table", "ListView Items must be an array")
		local nextItems, nextKeyIndex, nextKeys = {}, {}, {}
		for index, item in ipairs(source) do
			local itemKey = keyFor(item, index)
			assert(nextKeyIndex[itemKey] == nil, "Duplicate ListView key: " .. tostring(itemKey))
			table.insert(nextItems, item)
			nextKeyIndex[itemKey] = index
			nextKeys[index] = itemKey
		end
		return nextItems, nextKeyIndex, nextKeys
	end

	local items, keyIndex, keys = prepare(o.Items or {})
	local function validSelection(value: any): (boolean, string?)
		if multiSelect then
			if type(value) ~= "table" then
				return false, "multi-selection must be an array of ListView keys"
			end
			if maxSelections and #value > maxSelections then
				return false, "selection exceeds the ListView maximum"
			end
			local seen = {}
			for _, selectedKey in ipairs(value) do
				if keyIndex[selectedKey] == nil then
					return false, "selection is not present in the ListView"
				end
				if seen[selectedKey] then
					return false, "selection contains a duplicate ListView key"
				end
				seen[selectedKey] = true
			end
			return true, nil
		end
		if value == nil or keyIndex[value] ~= nil then
			return true, nil
		end
		return false, "selection is not present in the ListView"
	end
	local originalCallback, onSelect, onActivate = o.Callback, o.OnSelect, o.OnActivate
	options.Callback = function(value: any, oldValue: any, changed: any)
		call(originalCallback, value, oldValue, changed)
		if type(onSelect) == "function" then
			if multiSelect then
				local selectedItems, selectedIndices = {}, {}
				for _, selectedKey in ipairs(value) do
					local index = keyIndex[selectedKey]
					if index then
						table.insert(selectedItems, items[index])
						table.insert(selectedIndices, index)
					end
				end
				call(onSelect, selectedItems, selectedIndices, value)
			else
				local index = keyIndex[value]
				call(onSelect, if index then items[index] else nil, index, value)
			end
		end
	end

	local defaultSelection = if o.Default ~= nil
		then o.Default
		elseif o.Selected ~= nil then o.Selected
		elseif multiSelect then {}
		else nil
	local h = base(section, options, "ListView", defaultSelection, validSelection)
	local theme = h._context.Theme
	local headerHeight = math.max(30, tonumber(o.HeaderHeight) or 30)
	local contentWidth = math.max(0, tonumber(o.ContentWidth) or 0)
	local title = Factory.text(
		h.Root,
		tostring(o.Title or o.Name or "Items"),
		theme.typography.label * theme.textScale,
		theme.colors.text,
		{
			Position = UDim2.fromOffset(2, 0),
			Size = UDim2.new(1, -70, 0, headerHeight),
			theme = theme,
		}
	)
	h._title = title
	local countLabel = Factory.text(
		h.Root,
		tostring(#items),
		theme.typography.caption * theme.textScale,
		theme.colors.textMuted,
		{
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -2, 0, 0),
			Size = UDim2.fromOffset(64, headerHeight),
			TextXAlignment = Enum.TextXAlignment.Right,
			theme = theme,
		}
	)
	local viewport = Factory.make("Frame", {
		Name = "ListViewport",
		BackgroundColor3 = theme.colors.surface,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		Position = UDim2.fromOffset(0, headerHeight),
		Size = UDim2.new(1, 0, 1, -headerHeight),
	}, h.Root) :: Frame
	Factory.corner(viewport, theme.radius.sm)
	local surface = Factory.surface(viewport, theme, "surface")
	h._maid:GiveTask(surface)
	local scroll = Factory.make("ScrollingFrame", {
		Name = "Scroller",
		Active = true,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		HorizontalScrollBarInset = Enum.ScrollBarInset.None,
		ScrollBarImageColor3 = theme.colors.textMuted,
		ScrollBarThickness = 4,
		ScrollingDirection = if contentWidth > 0 then Enum.ScrollingDirection.XY else Enum.ScrollingDirection.Y,
		Size = UDim2.fromScale(1, 1),
	}, viewport) :: ScrollingFrame
	local headerRoot: Frame? = nil
	if headerHeight > 30 then
		headerRoot = Factory.make("Frame", {
			Name = "ListHeader",
			BackgroundTransparency = 1,
			ClipsDescendants = true,
			Position = UDim2.fromOffset(0, 30),
			Size = UDim2.new(1, 0, 0, headerHeight - 30),
		}, h.Root) :: Frame
	end
	h.Viewport = viewport
	h.Scroller = scroll
	h.HeaderRoot = headerRoot
	local empty = Factory.text(
		viewport,
		tostring(o.EmptyText or "No items"),
		theme.typography.body * theme.textScale,
		theme.colors.textMuted,
		{
			Position = UDim2.fromOffset(16, 0),
			Size = UDim2.new(1, -32, 1, 0),
			TextXAlignment = Enum.TextXAlignment.Center,
			TextWrapped = true,
			Visible = #items == 0,
			theme = theme,
		}
	)

	local pool = {}
	local firstVisible: number? = nil
	local lastVisible: number? = nil
	local lastFirst = -1
	local renderer = o.Render

	local function displayText(item: any, index: number): string
		if type(o.GetTitle) == "function" then
			return tostring(o.GetTitle(item, index))
		end
		if type(item) == "table" then
			return tostring(item.Title or item.Name or item.Text or item.Label or keyFor(item, index))
		end
		return tostring(item)
	end
	local function detailText(item: any, index: number): string
		if type(o.GetDetail) == "function" then
			return tostring(o.GetDetail(item, index) or "")
		end
		if type(item) == "table" then
			return tostring(item.Detail or item.Description or item.Subtitle or "")
		end
		return ""
	end

	local function destroyRow(row: any)
		if row.Destroyed then
			return
		end
		row.Destroyed = true
		row.Maid:Destroy()
		row.Button:Destroy()
	end

	local function createRow(poolIndex: number): any
		local rowMaid = Maid.new()
		local button = Factory.button(scroll, "", h._context.Theme, {
			Name = "VirtualRow" .. tostring(poolIndex),
			Size = UDim2.new(1, -8, 0, rowHeight - 2),
			TextTransparency = 1,
			Visible = false,
		})
		local primary = Factory.text(
			button,
			"",
			h._context.Theme.typography.body * h._context.Theme.textScale,
			h._context.Theme.colors.text,
			{
				Position = UDim2.fromOffset(12, 0),
				Size = UDim2.new(1, -24, 1, 0),
				theme = h._context.Theme,
			}
		)
		local secondary = Factory.text(
			button,
			"",
			h._context.Theme.typography.caption * h._context.Theme.textScale,
			h._context.Theme.colors.textMuted,
			{
				AnchorPoint = Vector2.new(0, 1),
				Position = UDim2.new(0, 12, 1, -5),
				Size = UDim2.new(1, -24, 0, 16),
				Visible = false,
				theme = h._context.Theme,
			}
		)
		local row: any = {
			Button = button,
			Primary = primary,
			Secondary = secondary,
			Maid = rowMaid,
			Index = nil,
			Key = nil,
			Destroyed = false,
		}
		local context = {
			Root = button,
			Button = button,
			Primary = primary,
			Secondary = secondary,
			Index = nil,
			Key = nil,
			Selected = false,
			Theme = h._context.Theme,
		}
		function context:SetText(nextTitle: any, nextDetail: any?)
			primary.Text = tostring(nextTitle)
			local detail = if nextDetail == nil then "" else tostring(nextDetail)
			secondary.Text = detail
			secondary.Visible = detail ~= ""
			primary.Size = if detail == ""
				then UDim2.new(1, -24, 1, 0)
				else UDim2.new(1, -24, 1, -14)
			primary.TextYAlignment = if detail == "" then Enum.TextYAlignment.Center else Enum.TextYAlignment.Top
			primary.Position = if detail == "" then UDim2.fromOffset(12, 0) else UDim2.fromOffset(12, 4)
			return context
		end
		row.Context = context
		rowMaid:GiveTask(button.Activated:Connect(function()
			if row.Index and active(h) then
				local selected = false
				if type(onActivate) == "function" then
					call(onActivate, row.Context, items[row.Index], row.Index, row.Key)
				elseif multiSelect then
					local current = h:Get()
					if table.find(current, row.Key) ~= nil or maxSelections == nil or #current < maxSelections then
						h:ToggleSelected(row.Key)
						selected = true
					end
				else
					h:Set(row.Key, { Source = "user" })
					selected = true
				end
				if selected then selectionHaptic(h) end
			end
		end))
		section:_focus(h.Id .. ".row." .. tostring(poolIndex), button, rowMaid)
		function row:Destroy()
			destroyRow(self)
		end
		return row
	end
	h._maid:GiveTask(function()
		for _, row in ipairs(pool) do
			destroyRow(row)
		end
		table.clear(pool)
		table.clear(items)
		table.clear(keyIndex)
		table.clear(keys)
	end)


	local function refresh(force: boolean?)
		if h._destroyed then
			return
		end
		local count = #items
		countLabel.Text = tostring(count)
		empty.Visible = count == 0
		local canvasWidth = if contentWidth > 0 then math.max(contentWidth, scroll.AbsoluteSize.X) else 0
		scroll.CanvasSize = UDim2.fromOffset(canvasWidth, count * rowHeight)
		local viewportHeight = scroll.AbsoluteSize.Y
		if viewportHeight <= 0 then
			viewportHeight = math.max(1, listHeight - headerHeight)
		end
		local capacity = math.min(128, math.max(1, math.ceil(viewportHeight / rowHeight) + 1 + overscan * 2))
		local required = math.min(count, capacity)
		while #pool < required do
			table.insert(pool, createRow(#pool + 1))
		end
		while #pool > required do
			local row = table.remove(pool)
			destroyRow(row)
		end
		if count == 0 then
			firstVisible, lastVisible, lastFirst = nil, nil, -1
			return
		end
		local maximumCanvas = math.max(0, count * rowHeight - viewportHeight)
		if scroll.CanvasPosition.Y > maximumCanvas then
			scroll.CanvasPosition = Vector2.new(scroll.CanvasPosition.X, maximumCanvas)
		end
		local first = math.max(1, math.floor(scroll.CanvasPosition.Y / rowHeight) + 1 - overscan)
		local last = math.min(count, first + required - 1)
		firstVisible, lastVisible = first, last
		if not force and first == lastFirst then
			return
		end
		lastFirst = first
		local selected = h:Get()
		for poolIndex, row in ipairs(pool) do
			local itemIndex = first + poolIndex - 1
			local item = items[itemIndex]
			if item == nil then
				row.Index, row.Key = nil, nil
				row.Button.Visible = false
			else
				local itemKey = keys[itemIndex]
				local isSelected = if multiSelect
					then table.find(selected, itemKey) ~= nil
					else selected == itemKey
				local stateName = if h._locked then "disabled" elseif isSelected then "selected" else "default"
				local stateTokens = h._context.Theme.states[stateName] or h._context.Theme.states.default
				row.Index, row.Key = itemIndex, itemKey
				row.Button.Position = UDim2.fromOffset(4, (itemIndex - 1) * rowHeight + 1)
				row.Button.Size = if contentWidth > 0
					then UDim2.fromOffset(math.max(contentWidth - 8, scroll.AbsoluteSize.X - 8), rowHeight - 2)
					else UDim2.new(1, -8, 0, rowHeight - 2)
				row.Button.Visible = true
				Factory.setButtonState(row.Button, stateName, h._context.Theme)
				row.Primary.TextColor3 = stateTokens.text
				row.Secondary.TextColor3 =
					if stateName == "default" then h._context.Theme.colors.textMuted else stateTokens.text
				row.Secondary.TextTransparency = if stateName == "default" then 0 else 0.2
				row.Context.Index = itemIndex
				row.Context.Key = itemKey
				row.Context.Selected = isSelected
				row.Context.Theme = h._context.Theme
				row.Context:SetText(displayText(item, itemIndex), detailText(item, itemIndex))
				if type(renderer) == "function" then
					call(renderer, row.Context, item, itemIndex, isSelected)
				end
			end
		end
	end

	function h:_render(_value: any)
		refresh(true)
	end
	function h:SetItems(nextItems: any)
		local prepared, preparedKeyIndex, preparedKeys = prepare(nextItems)
		items, keyIndex, keys = prepared, preparedKeyIndex, preparedKeys
		local selected = self:Get()
		if multiSelect then
			local reconciled = {}
			for _, selectedKey in ipairs(selected) do
				if keyIndex[selectedKey] ~= nil then
					table.insert(reconciled, selectedKey)
				end
			end
			if #reconciled ~= #selected then
				self:Set(reconciled)
			else
				refresh(true)
			end
		elseif selected ~= nil and keyIndex[selected] == nil then
			self:Set(nil)
		else
			refresh(true)
		end
		return self
	end
	function h:GetItems()
		return table.clone(items)
	end
	function h:GetSelected()
		local selected = self:Get()
		if multiSelect then
			local selectedItems, selectedIndices = {}, {}
			for _, selectedKey in ipairs(selected) do
				local index = keyIndex[selectedKey]
				if index then
					table.insert(selectedItems, items[index])
					table.insert(selectedIndices, index)
				end
			end
			return selectedItems, selectedIndices, selected
		end
		local index = keyIndex[selected]
		return if index then items[index] else nil, index, selected
	end
	function h:SetSelected(key: any)
		return self:Set(key)
	end
	function h:ToggleSelected(key: any)
		assert(multiSelect, "ToggleSelected requires MultiSelect")
		assert(keyIndex[key] ~= nil, "Unknown ListView key: " .. tostring(key))
		local selected = self:Get()
		local index = table.find(selected, key)
		if index then
			table.remove(selected, index)
		else
			assert(maxSelections == nil or #selected < maxSelections, "Selection limit reached")
			table.insert(selected, key)
		end
		return self:Set(selected)
	end
	function h:IsMultiSelect(): boolean
		return multiSelect
	end
	function h:GetVisibleRange()
		return firstVisible, lastVisible
	end
	function h:GetPoolSize(): number
		return #pool
	end
	function h:Refresh()
		refresh(true)
		return self
	end
	function h:ScrollTo(index: number, alignment: string?)
		assert(type(index) == "number" and index % 1 == 0 and index >= 1 and index <= #items, "Invalid ListView index")
		local viewportHeight = math.max(1, scroll.AbsoluteSize.Y)
		local target = (index - 1) * rowHeight
		if alignment == "center" then
			target -= (viewportHeight - rowHeight) / 2
		elseif alignment == "end" then
			target -= viewportHeight - rowHeight
		elseif alignment ~= nil and alignment ~= "start" then
			error("ListView alignment must be start, center, or end", 2)
		end
		local maximum = math.max(0, #items * rowHeight - viewportHeight)
		scroll.CanvasPosition = Vector2.new(scroll.CanvasPosition.X, math.clamp(target, 0, maximum))
		refresh(true)
		return self
	end
	function h:ScrollToKey(key: any, alignment: string?)
		local index = keyIndex[key]
		assert(index ~= nil, "Unknown ListView key: " .. tostring(key))
		return self:ScrollTo(index, alignment)
	end
	function h:SetHeight(height: number)
		assert(type(height) == "number" and height >= 120, "ListView height must be at least 120")
		listHeight = height
		self.Root.Size = UDim2.new(1, 0, 0, height)
		refresh(true)
		return self
	end
	function h:SetContentWidth(width: number)
		assert(type(width) == "number" and width >= 0, "ListView content width must be non-negative")
		contentWidth = width
		scroll.ScrollingDirection = if contentWidth > 0 then Enum.ScrollingDirection.XY else Enum.ScrollingDirection.Y
		refresh(true)
		return self
	end

	h._maid:GiveTask(scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
		refresh(false)
	end))
	h._maid:GiveTask(scroll:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		refresh(true)
	end))
	if h._context.ThemeChanged then
		h._maid:GiveTask(h._context.ThemeChanged:Connect(function(nextTheme: any)
			local function repaintText(textObject: TextLabel, color: Color3, size: number)
				textObject.TextColor3 = color
				textObject.TextSize = size
				textObject.Font = nextTheme.font
				if nextTheme.fontFace ~= nil then
					pcall(function()
						textObject.FontFace = nextTheme.fontFace
					end)
				end
			end
			repaintText(title, nextTheme.colors.text, nextTheme.typography.label * nextTheme.textScale)
			repaintText(countLabel, nextTheme.colors.textMuted, nextTheme.typography.caption * nextTheme.textScale)
			repaintText(empty, nextTheme.colors.textMuted, nextTheme.typography.body * nextTheme.textScale)
			for _, row in ipairs(pool) do
				repaintText(row.Primary, nextTheme.colors.text, nextTheme.typography.body * nextTheme.textScale)
				repaintText(row.Secondary, nextTheme.colors.textMuted, nextTheme.typography.caption * nextTheme.textScale)
			end
			scroll.ScrollBarImageColor3 = nextTheme.colors.textMuted
			surface:Apply(nextTheme, "surface")
			refresh(true)
		end))
	end
	attachAsyncProvider(h, o, function(nextItems)
		h:SetItems(nextItems)
	end)
	refresh(true)
	return h
end

function Controls.LogViewer(section: any, o: any): any
	assert(type(o) == "table", "LogViewer requires options")
	local levels = { "trace", "debug", "info", "warn", "error", "success" }
	local knownLevels = {}
	for _, level in ipairs(levels) do
		knownLevels[level] = true
	end
	local maxEntries = math.floor(tonumber(o.MaxEntries) or 1000)
	local maxPending = math.floor(tonumber(o.MaxPendingEntries or o.MaxPending) or maxEntries)
	assert(maxEntries > 0, "LogViewer MaxEntries must be a positive integer")
	assert(maxPending > 0, "LogViewer MaxPendingEntries must be a positive integer")

	local function errorResult(code: string, message: string): any
		return { code = code, message = message }
	end
	local function copyEntry(entry: any): any
		return {
			Id = entry.Id,
			Level = entry.Level,
			Timestamp = entry.Timestamp,
			Message = entry.Message,
			Detail = entry.Detail,
			Source = entry.Source,
		}
	end
	local function normalizeLevel(value: any): string
		local level = string.lower(tostring(value or "info"))
		assert(knownLevels[level] == true, "Unknown LogViewer level: " .. level)
		return level
	end
	local function normalizeEntry(value: any, fallbackLevel: any, detail: any, source: any, entryId: number): any
		local input = if type(value) == "table" then value else {}
		local message = if type(value) == "table" then input.Message or input.message else value
		assert(message ~= nil, "LogViewer entry requires Message")
		return {
			Id = entryId,
			Level = normalizeLevel(if type(value) == "table" then input.Level or input.level or fallbackLevel else fallbackLevel),
			Timestamp = if type(value) == "table" then input.Timestamp or input.timestamp else nil,
			Message = tostring(message),
			Detail = tostring(if type(value) == "table" then input.Detail or input.detail or "" else detail or ""),
			Source = tostring(if type(value) == "table" then input.Source or input.source or "" else source or ""),
		}
	end
	local function normalizeLevels(value: any): { string }
		assert(type(value) == "table", "LogViewer levels must be an array")
		local result, seen = {}, {}
		for _, level in ipairs(value) do
			local normalized = normalizeLevel(level)
			if not seen[normalized] then
				seen[normalized] = true
				table.insert(result, normalized)
			end
		end
		return result
	end
	local initialLevels = normalizeLevels(o.Levels or levels)
	local query = tostring(o.Query or "")
	local entries, pending = {}, {}
	local nextId = 0
	local paused = o.Paused == true
	local autoFollow = o.AutoFollow ~= false
	local selectedLevels = {}
	for _, level in ipairs(initialLevels) do
		selectedLevels[level] = true
	end
	local function visibleEntries(): { any }
		local result = {}
		local needle = string.lower(query)
		for _, entry in ipairs(entries) do
			local searchable = string.lower(entry.Level .. "\n" .. tostring(entry.Timestamp or "") .. "\n" .. entry.Message .. "\n" .. entry.Detail .. "\n" .. entry.Source)
			if selectedLevels[entry.Level] and (needle == "" or string.find(searchable, needle, 1, true) ~= nil) then
				table.insert(result, entry)
			end
		end
		return result
	end
	local function levelColor(theme: any, level: string): Color3
		if level == "trace" then
			return theme.colors.textMuted
		elseif level == "debug" then
			return theme.colors.info
		elseif level == "warn" then
			return theme.colors.warning
		elseif level == "error" then
			return theme.colors.danger
		elseif level == "success" then
			return theme.colors.success
		end
		return theme.colors.text
	end
	local function entryText(entry: any): string
		local prefix = if entry.Timestamp ~= nil and tostring(entry.Timestamp) ~= "" then "[" .. tostring(entry.Timestamp) .. "] " else ""
		local sourceText = if entry.Source ~= "" then entry.Source .. ": " else ""
		return prefix .. string.upper(entry.Level) .. " " .. sourceText .. entry.Message
	end
	local function exportText(source: { any }): string
		local lines = {}
		for _, entry in ipairs(source) do
			table.insert(lines, entryText(entry))
			if entry.Detail ~= "" then
				table.insert(lines, "  " .. entry.Detail)
			end
		end
		return table.concat(lines, "\n")
	end

	local listOptions = {}
	for key, value in pairs(o) do
		listOptions[key] = value
	end
	listOptions.Items = {}
	listOptions.Key = "Id"
	listOptions.Title = o.Title or o.Name or "Log"
	listOptions.EmptyText = o.EmptyText or "No log entries"
	listOptions.Persist = false
	listOptions.Render = function(row: any, entry: any, index: number, selected: boolean)
		row.Primary.TextColor3 = levelColor(row.Theme, entry.Level)
		if type(o.Render) == "function" then
			call(o.Render, row, entry, index, selected)
		end
	end
	local list = Controls.ListView(section, listOptions)
	local originalDestroy = list.Destroy
	local searchControl: any = nil
	local levelControl: any = nil

	local function refresh(follow: boolean?)
		if list._destroyed then
			return
		end
		list:SetItems(visibleEntries())
		if follow and autoFollow and #list:GetItems() > 0 then
			list:ScrollTo(#list:GetItems(), "end")
		end
	end
	local function commit(entry: any, follow: boolean?)
		table.insert(entries, entry)
		if #entries > maxEntries then
			table.remove(entries, 1)
		end
		refresh(follow)
	end
	local function append(entry: any, level: any, detail: any, source: any)
		local candidateId = nextId + 1
		local normalized = normalizeEntry(entry, level, detail, source, candidateId)
		nextId = candidateId
		if paused then
			table.insert(pending, normalized)
			if #pending > maxPending then
				table.remove(pending, 1)
			end
		else
			commit(normalized, true)
		end
		return list
	end

	if o.Searchable ~= false and o.Search ~= false and o.ShowSearch ~= false then
		searchControl = Controls.Textbox(section, {
			Id = list.Id .. "-query",
			Title = o.SearchTitle or "Search",
			Placeholder = o.SearchPlaceholder or "Filter log entries",
			Default = query,
			Persist = false,
			Callback = function(value: string)
				query = value
				refresh(false)
			end,
		})
	end
	if searchControl then
		local searchBox = searchControl.Root:FindFirstChildWhichIsA("TextBox")
		if searchBox then
			list._maid:GiveTask(searchBox:GetPropertyChangedSignal("Text"):Connect(function()
				query = searchBox.Text
				refresh(false)
			end))
		end
	end
	if o.LevelChips ~= false and o.ShowLevelChips ~= false and o.ShowLevels ~= false and o.LevelsVisible ~= false then
		levelControl = Controls.Chips(section, {
			Id = list.Id .. "-levels",
			Title = o.LevelsTitle or "Levels",
			Options = levels,
			MultiSelect = true,
			Default = initialLevels,
			Persist = false,
			Callback = function(value: { string })
				selectedLevels = {}
				for _, level in ipairs(value) do
					selectedLevels[level] = true
				end
				refresh(false)
			end,
		})
	end

	function list:Append(entry: any, level: any?, detail: any?, source: any?)
		return append(entry, level, detail, source)
	end
	function list:Add(entry: any, level: any?, detail: any?, source: any?)
		return append(entry, level, detail, source)
	end
	function list:Log(level: any, message: any, detail: any?, source: any?)
		return append(message, level, detail, source)
	end
	function list:Clear()
		table.clear(entries)
		table.clear(pending)
		refresh(false)
		return self
	end
	function list:SetEntries(source: any)
		assert(type(source) == "table", "LogViewer entries must be an array")
		local prepared = {}
		local candidateId = nextId
		for _, entry in ipairs(source) do
			candidateId += 1
			table.insert(prepared, normalizeEntry(entry, nil, nil, nil, candidateId))
		end
		while #prepared > maxEntries do
			table.remove(prepared, 1)
		end
		entries, pending, nextId = prepared, {}, candidateId
		refresh(false)
		return self
	end
	function list:GetEntries()
		local result = {}
		for index, entry in ipairs(entries) do
			result[index] = copyEntry(entry)
		end
		return result
	end
	function list:SetQuery(value: any)
		query = tostring(value or "")
		if searchControl then
			searchControl:Set(query)
		else
			refresh(false)
		end
		return self
	end
	function list:GetQuery(): string
		return query
	end
	function list:SetLevels(value: any)
		local normalized = normalizeLevels(value)
		if levelControl then
			levelControl:Set(normalized)
		else
			selectedLevels = {}
			for _, level in ipairs(normalized) do
				selectedLevels[level] = true
			end
			refresh(false)
		end
		return self
	end
	function list:GetLevels()
		local result = {}
		for _, level in ipairs(levels) do
			if selectedLevels[level] then
				table.insert(result, level)
			end
		end
		return result
	end
	function list:SetPaused(value: boolean)
		local nextPaused = value == true
		if paused and not nextPaused then
			paused = false
			for _, entry in ipairs(pending) do
				commit(entry, false)
			end
			table.clear(pending)
			if autoFollow and #entries > 0 then
				refresh(true)
			end
		else
			paused = nextPaused
		end
		return self
	end
	function list:IsPaused(): boolean
		return paused
	end
	function list:SetAutoFollow(value: boolean)
		autoFollow = value == true
		return self
	end
	function list:GetAutoFollow(): boolean
		return autoFollow
	end
	function list:GetVisibleEntries()
		local source = visibleEntries()
		local result = {}
		for index, entry in ipairs(source) do
			result[index] = copyEntry(entry)
		end
		return result
	end
	function list:Export(format: any)
		local selectedFormat = string.lower(tostring(format or "text"))
		if selectedFormat == "text" then
			return exportText(entries), nil
		end
		if selectedFormat == "json" then
			local payload, encodeError = self._context.Runtime:jsonEncode(self:GetEntries())
			if type(payload) ~= "string" then
				return nil, encodeError or errorResult("json_encode_failed", "LogViewer JSON export failed.")
			end
			return payload, nil
		end
		return nil, errorResult("invalid_export_format", "LogViewer export format must be text or json.")
	end
	function list:Copy(format: any)
		local payload, exportError = self:Export(format)
		if payload == nil then
			return false, exportError
		end
		local clipboard = self._context.Runtime.clipboard
		if type(clipboard) ~= "table" or type(clipboard.write) ~= "function" then
			return false, errorResult("clipboard_unavailable", "No runtime clipboard write adapter is available.")
		end
		local ok, written, writeError = pcall(function()
			return clipboard:write(payload)
		end)
		if not ok or written ~= true then
			return false, errorResult("clipboard_write_failed", tostring(if ok then writeError or "Clipboard write failed." else written))
		end
		return true, nil
	end
	function list:Destroy()
		if self._destroyed then
			return
		end
		if searchControl then
			searchControl:Destroy()
		end
		if levelControl then
			levelControl:Destroy()
		end
		originalDestroy(self)
	end
	list.Unload = list.Destroy
	list.Search = searchControl
	list.LevelChips = levelControl
	list.MaxEntries = maxEntries
	list.MaxPendingEntries = maxPending
	refresh(false)
	return list
end

function Controls.Timeline(section: any, o: any): any
	assert(type(o) == "table", "Timeline requires options")
	local maxEntries = math.floor(tonumber(o.MaxEntries) or 1000)
	local maxPending = math.floor(tonumber(o.MaxPendingEntries or o.MaxPending) or maxEntries)
	assert(maxEntries > 0, "Timeline MaxEntries must be a positive integer")
	assert(maxPending > 0, "Timeline MaxPendingEntries must be a positive integer")
	local order = o.Order or "asc"
	assert(order == "asc" or order == "desc", 'Timeline Order must be "asc" or "desc"')
	local groupBy = o.GroupBy
	assert(groupBy == nil or groupBy == "day" or groupBy == "group" or type(groupBy) == "function", "Timeline GroupBy must be day, group, a function, or nil")

	local function normalizeType(value: any): string
		return string.lower(tostring(value or "info"))
	end
	local function timestampValue(value: number | string): number?
		if type(value) == "number" then
			return value
		end
		local parsed = tonumber(value)
		if parsed ~= nil then
			return parsed
		end
		local year, month, day = string.match(value, "^(%d%d%d%d)%-(%d%d)%-(%d%d)$")
		local hour, minute, second
		if not year then
			year, month, day, hour, minute, second = string.match(value, "^(%d%d%d%d)%-(%d%d)%-(%d%d)[Tt ](%d%d):(%d%d):(%d%d)Z?$")
		end
		if not year then
			return nil
		end
		local y, mo, d = tonumber(year) or 0, tonumber(month) or 0, tonumber(day) or 0
		local h, mi, s = tonumber(hour) or 0, tonumber(minute) or 0, tonumber(second) or 0
		local daysInMonth = ({ 31, if y % 4 == 0 and (y % 100 ~= 0 or y % 400 == 0) then 29 else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 })[mo]
		if daysInMonth == nil or d < 1 or d > daysInMonth or h > 23 or mi > 59 or s > 59 then
			return nil
		end
		return y * 10000000000 + mo * 100000000 + d * 1000000 + h * 10000 + mi * 100 + s
	end
	local function normalizeTimestamp(value: any): number | string
		assert(type(value) == "number" or type(value) == "string", "Timeline entry Timestamp must be a number or string")
		assert(timestampValue(value) ~= nil, "Timeline entry Timestamp must be a supported number or ISO date/time")
		return value
	end
	local function copyEntry(entry: any): any
		return {
			Id = entry.Id,
			Timestamp = entry.Timestamp,
			Type = entry.Type,
			Title = entry.Title,
			Text = entry.Text,
			Detail = entry.Detail,
			Group = entry.Group,
			Data = entry.Data,
		}
	end
	local function normalizeEntry(value: any, generatedId: number): any
		assert(type(value) == "table", "Timeline entry must be a table")
		local id = value.Id
		if id == nil then id = value.ID end
		if id == nil then id = generatedId end
		local idType = type(id)
		assert(idType == "string" or idType == "number" or idType == "boolean", "Timeline entry Id must be a scalar")
		local title = value.Title
		if title == nil then title = value.Name end
		local text = value.Text
		if text == nil then text = value.Message end
		assert(title ~= nil or text ~= nil, "Timeline entry requires Title or Text")
		return {
			Id = id,
			Timestamp = normalizeTimestamp(value.Timestamp),
			Type = normalizeType(value.Type),
			Title = tostring(title or text),
			Text = tostring(text or ""),
			Detail = tostring(value.Detail or ""),
			Group = if value.Group == nil then nil else tostring(value.Group),
			Data = value.Data,
			_Sequence = generatedId,
		}
	end
	local function typeColor(theme: any, entryType: string): Color3
		if entryType == "error" or entryType == "critical" or entryType == "failure" then
			return theme.colors.danger
		elseif entryType == "warn" or entryType == "warning" then
			return theme.colors.warning
		elseif entryType == "success" or entryType == "complete" then
			return theme.colors.success
		elseif entryType == "debug" then
			return theme.colors.info
		elseif entryType == "trace" then
			return theme.colors.textMuted
		end
		return theme.colors.text
	end
	local function groupKey(entry: any): string?
		if groupBy == "day" then
			if type(entry.Timestamp) == "string" then
				return string.sub(entry.Timestamp, 1, 10)
			end
			return os.date("!%Y-%m-%d", entry.Timestamp)
		elseif groupBy == "group" then
			return entry.Group or "Ungrouped"
		elseif type(groupBy) == "function" then
			local value = groupBy(entry)
			return if value == nil then nil else tostring(value)
		end
		return nil
	end

	local entries, pending = {}, {}
	local nextId = 0
	local query = tostring(o.Query or "")
	local selectedTypes = {}
	local initialTypes = o.Types
	local typeFilterActive = initialTypes ~= nil
	if initialTypes ~= nil then
		assert(type(initialTypes) == "table", "Timeline Types must be an array")
		for _, value in ipairs(initialTypes) do selectedTypes[normalizeType(value)] = true end
	end
	local availableTypes, knownTypes = {}, {}
	local function learnType(value: any): boolean
		local entryType = normalizeType(value)
		if knownTypes[entryType] then return false end
		knownTypes[entryType] = true
		table.insert(availableTypes, entryType)
		return true
	end
	for _, value in ipairs(o.AvailableTypes or {}) do learnType(value) end
	for _, value in ipairs(initialTypes or {}) do learnType(value) end
	local paused = o.Paused == true
	local autoFollow = o.AutoFollow ~= false
	local selectedEventId: any = nil
	local refreshing = false

	local function visibleEvents(): { any }
		local result, needle = {}, string.lower(query)
		for _, entry in ipairs(entries) do
			local searchable = string.lower(tostring(entry.Timestamp) .. "\n" .. entry.Type .. "\n" .. entry.Title .. "\n" .. entry.Text .. "\n" .. entry.Detail .. "\n" .. tostring(entry.Group or ""))
			if (not typeFilterActive or selectedTypes[entry.Type]) and (needle == "" or string.find(searchable, needle, 1, true)) then
				table.insert(result, entry)
			end
		end
		table.sort(result, function(a: any, b: any)
			if groupBy ~= nil and groupBy ~= "day" then
				local aGroup, bGroup = groupKey(a) or "", groupKey(b) or ""
				if aGroup ~= bGroup then
					return aGroup < bGroup
				end
			end
			local aTime, bTime = timestampValue(a.Timestamp), timestampValue(b.Timestamp)
			if aTime == bTime then
				return if order == "asc" then a._Sequence < b._Sequence else a._Sequence > b._Sequence
			end
			return if order == "asc" then aTime < bTime else aTime > bTime
		end)
		return result
	end
	local function flatVisible(): { any }
		local result, previousGroup, usedKeys = {}, nil, {}
		local source = visibleEvents()
		for _, entry in ipairs(source) do
			usedKeys[entry.Id] = true
		end
		for _, entry in ipairs(source) do
			local group = groupKey(entry)
			if group ~= nil and group ~= previousGroup then
				local key, suffix = "__timeline_header__:" .. group, 1
				while usedKeys[key] do
					key = "__timeline_header__:" .. group .. ":" .. tostring(suffix)
					suffix += 1
				end
				usedKeys[key] = true
				table.insert(result, { _TimelineHeader = true, _Key = key, Label = group })
				previousGroup = group
			end
			table.insert(result, entry)
		end
		return result
	end
	local list: any = nil

	local listOptions = {}
	for key, value in pairs(o) do listOptions[key] = value end
	listOptions.Items = {}
	listOptions.Key = function(item: any) return item._Key or item.Id end
	listOptions.Title = o.Title or o.Name or "Timeline"
	listOptions.EmptyText = o.EmptyText or "No events"
	listOptions.Persist = false
	listOptions.Callback = function(value: any, oldValue: any, changed: any)
		if not refreshing then selectedEventId = value end
		call(o.Callback, value, oldValue, changed)
	end
	listOptions.OnActivate = function(_row: any, item: any, _index: number, key: any)
		if not item._TimelineHeader then
			selectedEventId = item.Id
			list:Set(key)
			call(o.OnActivate, item, key)
		end
	end
	listOptions.GetTitle = function(item: any)
		if item._TimelineHeader then return item.Label end
		return "[" .. tostring(item.Timestamp) .. "] " .. item.Title
	end
	listOptions.GetDetail = function(item: any)
		if item._TimelineHeader then return "" end
		return if item.Detail ~= "" then item.Detail else item.Text
	end
	listOptions.Render = function(row: any, item: any, index: number, selected: boolean)
		if item._TimelineHeader then
			row.Primary.TextColor3 = row.Theme.colors.textMuted
			row.Secondary.Visible = false
			row.Root.Active = false
		else
			row.Root.Active = true
			row.Primary.TextColor3 = typeColor(row.Theme, item.Type)
			if type(o.Render) == "function" then call(o.Render, row, item, index, selected) end
		end
	end
	list = Controls.ListView(section, listOptions)
	local listSet = list.Set
	function list:Set(value: any)
		for _, item in ipairs(self:GetItems()) do
			if item._TimelineHeader and item._Key == value then
				error("Timeline headers cannot be selected", 2)
			end
		end
		return listSet(self, value)
	end
	local originalDestroy = list.Destroy
	local searchControl: any = nil
	local typeControl: any = nil
	local syncTypeOptions: any = nil
	local function refresh(follow: boolean?, followId: any?)
		if list._destroyed then return end
		local rows = flatVisible()
		refreshing = true
		list:SetItems(rows)
		refreshing = false
		if selectedEventId ~= nil then
			for _, row in ipairs(rows) do
				if not row._TimelineHeader and row.Id == selectedEventId then
					list:Set(selectedEventId)
					break
				end
			end
		end
		if follow and autoFollow and followId ~= nil then
			for index, row in ipairs(rows) do
				if not row._TimelineHeader and row.Id == followId then
					list:ScrollTo(index, "end")
					break
				end
			end
		end
	end
	local function commit(entry: any, follow: boolean?)
		table.insert(entries, entry)
		if #entries > maxEntries then table.remove(entries, 1) end
		learnType(entry.Type)
		if syncTypeOptions then syncTypeOptions() end
		refresh(follow, entry.Id)
	end
	local function append(value: any)
		local candidateId = nextId + 1
		local entry = normalizeEntry(value, candidateId)
		for _, existing in ipairs(entries) do assert(existing.Id ~= entry.Id, "Duplicate Timeline Id: " .. tostring(entry.Id)) end
		for _, existing in ipairs(pending) do assert(existing.Id ~= entry.Id, "Duplicate Timeline Id: " .. tostring(entry.Id)) end
		nextId = candidateId
		if paused then
			table.insert(pending, entry)
			if #pending > maxPending then table.remove(pending, 1) end
		else
			commit(entry, true)
		end
		return list
	end
	if o.Searchable ~= false and o.Search ~= false and o.ShowSearch ~= false then
		searchControl = Controls.Textbox(section, {
			Id = list.Id .. "-query", Title = o.SearchTitle or "Search", Placeholder = o.SearchPlaceholder or "Filter events",
			Default = query, Persist = false, Callback = function(value: string) query = value; refresh(false) end,
		})
	end
	if searchControl then
		local searchBox = searchControl.Root:FindFirstChildWhichIsA("TextBox")
		if searchBox then list._maid:GiveTask(searchBox:GetPropertyChangedSignal("Text"):Connect(function() query = searchBox.Text; refresh(false) end)) end
	end
	local syncingTypes = false
	syncTypeOptions = function()
		if not typeControl then return end
		syncingTypes = true
		typeControl:SetOptions(availableTypes)
		if not typeFilterActive then typeControl:Set(availableTypes) end
		syncingTypes = false
	end
	if o.TypeChips ~= false and o.ShowTypeChips ~= false and o.ShowTypes ~= false then
		typeControl = Controls.Chips(section, {
			Id = list.Id .. "-types", Title = o.TypesTitle or "Types", Options = availableTypes, MultiSelect = true,
			Default = if initialTypes ~= nil then initialTypes else availableTypes, Persist = false,
			Callback = function(value: { string })
				selectedTypes = {}
				for _, entryType in ipairs(value) do selectedTypes[normalizeType(entryType)] = true end
				if not syncingTypes then typeFilterActive = true end
				refresh(false)
			end,
		})
	end
	function list:Append(entry: any) return append(entry) end
	function list:Add(entry: any) return append(entry) end
	function list:Clear() table.clear(entries); table.clear(pending); selectedEventId = nil; refresh(false); return self end
	function list:SetEntries(source: any)
		assert(type(source) == "table", "Timeline entries must be an array")
		local prepared, seen, candidateId = {}, {}, nextId
		for _, value in ipairs(source) do
			candidateId += 1
			local entry = normalizeEntry(value, candidateId)
			assert(not seen[entry.Id], "Duplicate Timeline Id: " .. tostring(entry.Id))
			seen[entry.Id] = true
			table.insert(prepared, entry)
		end
		while #prepared > maxEntries do table.remove(prepared, 1) end
		entries, pending, nextId = prepared, {}, candidateId
		for _, entry in ipairs(prepared) do learnType(entry.Type) end
		syncTypeOptions()
		refresh(false)
		return self
	end
	function list:GetEntries() local result = {}; for index, entry in ipairs(entries) do result[index] = copyEntry(entry) end; return result end
	function list:SetQuery(value: any) query = tostring(value or ""); if searchControl then searchControl:Set(query) else refresh(false) end; return self end
	function list:SetTypes(value: any)
		assert(type(value) == "table", "Timeline Types must be an array")
		local normalized = {}
		for _, entryType in ipairs(value) do
			entryType = normalizeType(entryType)
			table.insert(normalized, entryType)
			learnType(entryType)
		end
		typeFilterActive = true
		if typeControl then
			syncTypeOptions()
			typeControl:Set(normalized)
		else
			selectedTypes = {}
			for _, entryType in ipairs(normalized) do selectedTypes[entryType] = true end
			refresh(false)
		end
		return self
	end
	function list:GetTypes() local result = {}; for entryType in pairs(selectedTypes) do table.insert(result, entryType) end; table.sort(result); return result end
	function list:SetPaused(value: boolean)
		local nextPaused = value == true
		if paused and not nextPaused then
			paused = false
			local lastEntry = pending[#pending]
			for _, entry in ipairs(pending) do commit(entry, false) end
			table.clear(pending)
			if autoFollow and lastEntry ~= nil then refresh(true, lastEntry.Id) end
		else paused = nextPaused end
		return self
	end
	function list:IsPaused(): boolean return paused end
	function list:SetAutoFollow(value: boolean) autoFollow = value == true; return self end
	function list:GetAutoFollow(): boolean return autoFollow end
	function list:GetVisibleEntries() local result = {}; for index, entry in ipairs(visibleEvents()) do result[index] = copyEntry(entry) end; return result end
	function list:ScrollToEvent(id: any, alignment: string?)
		for index, row in ipairs(flatVisible()) do if not row._TimelineHeader and row.Id == id then return self:ScrollTo(index, alignment) end end
		error("Unknown visible Timeline Id: " .. tostring(id), 2)
	end
	function list:Destroy()
		if self._destroyed then return end
		if searchControl then searchControl:Destroy() end
		if typeControl then typeControl:Destroy() end
		originalDestroy(self)
	end
	list.Unload = list.Destroy
	list.Search = searchControl
	list.TypeChips = typeControl
	list.MaxEntries = maxEntries
	list.MaxPendingEntries = maxPending
	refresh(false)
	return list
end

Controls.EventFeed = Controls.Timeline

Controls.ConsoleViewer = Controls.LogViewer

function Controls.TreeView(section: any, o: any)
	assert(type(o) == "table", "TreeView requires options")

	local function scalarKey(value: any, label: string): string
		local kind = type(value)
		assert(kind == "string" or kind == "number" or kind == "boolean", label .. " must be a string, number, or boolean")
		local text = tostring(value)
		return kind .. ":" .. tostring(#text) .. ":" .. text
	end

	local function nodeKey(node: any): string
		assert(type(node) == "table", "TreeView nodes must be tables")
		local value = if node.Id ~= nil then node.Id else node.Key
		assert(value ~= nil, "TreeView nodes require an Id or Key")
		return scalarKey(value, "TreeView node Id/Key")
	end

	local function readChildren(node: any): { any }
		local children = node.Children
		if type(children) == "function" then
			children = children(node)
		end
		if children == nil then
			return {}
		end
		assert(type(children) == "table", "TreeView Children must be an array or synchronous provider")
		return children
	end

	local roots: { any } = {}
	local recordsByPath: { [string]: any } = {}
	local childrenByPath: { [string]: { string } } = {}
	local expanded: { [string]: boolean } = {}
	local visible: { any } = {}

	local function normalize(source: any): ({ any }, { [string]: any }, { [string]: { string } })
		assert(type(source) == "table", "TreeView Nodes must be an array")
		local nextRoots, nextRecords, nextChildren = {}, {}, {}
		local ancestors = {}
		local function visit(nodes: { any }, parentPath: string?, depth: number): { string }
			local childPaths, siblingKeys = {}, {}
			for index, node in ipairs(nodes) do
				assert(type(node) == "table", "TreeView nodes must be tables")
				assert(not ancestors[node], "TreeView rejects ancestor cycles")
				local key = nodeKey(node)
				assert(not siblingKeys[key], "Duplicate TreeView sibling key: " .. tostring(if node.Id ~= nil then node.Id else node.Key))
				siblingKeys[key] = true
				local path = if parentPath then parentPath .. "/" .. key else "root/" .. key
				assert(nextRecords[path] == nil, "Duplicate TreeView path: " .. path)
				ancestors[node] = true
				local childNodes = readChildren(node)
				local record = {
					Path = path,
					Node = node,
					Depth = depth,
					ParentPath = parentPath,
					HasChildren = #childNodes > 0,
					Title = tostring(node.Title or node.Name or node.Id or node.Key),
				}
				nextRecords[path] = record
				local descendants = visit(childNodes, path, depth + 1)
				nextChildren[path] = descendants
				ancestors[node] = nil
				table.insert(childPaths, path)
				if parentPath == nil then
					table.insert(nextRoots, path)
				end
			end
			return childPaths
		end
		visit(source, nil, 0)
		return nextRoots, nextRecords, nextChildren
	end

	local initialRoots, initialRecords, initialChildren = normalize(o.Nodes or {})
	roots, recordsByPath, childrenByPath = initialRoots, initialRecords, initialChildren
	if type(o.Expanded) == "table" then
		for key, value in pairs(o.Expanded) do
			local path = if type(key) == "number" then value else key
			if value == true or type(key) == "number" then
				assert(type(path) == "string", "TreeView Expanded paths must be strings")
				if recordsByPath[path] then
					expanded[path] = true
				end
			end
		end
	end
	for path, record in pairs(recordsByPath) do
		if record.Node.Expanded == true and record.HasChildren then
			expanded[path] = true
		end
	end

	local function rebuildVisible()
		local nextVisible = {}
		local function append(paths: { string })
			for _, path in ipairs(paths) do
				local record = recordsByPath[path]
				record.Expanded = expanded[path] == true
				table.insert(nextVisible, record)
				if record.Expanded then
					append(childrenByPath[path])
				end
			end
		end
		append(roots)
		visible = nextVisible
	end
	rebuildVisible()

	local listOptions = {}
	for key, value in pairs(o) do
		listOptions[key] = value
	end
	listOptions.Items = visible
	listOptions.Key = "Path"
	listOptions.GetTitle = function(record: any)
		return record.Title
	end
	listOptions.GetDetail = nil
	listOptions.OnSelect = nil
	listOptions.Default = nil
	listOptions.Selected = nil
	local customRender = o.Render
	listOptions.Render = function(context: any, record: any, index: number, selected: boolean)
		local indent = 12 + record.Depth * math.max(12, tonumber(o.Indent) or 18)
		local disclosure = context.Disclosure
		if disclosure == nil then
			disclosure = Factory.text(
				context.Button,
				"",
				context.Theme.typography.caption * context.Theme.textScale,
				context.Theme.colors.textMuted,
				{
					Position = UDim2.fromOffset(12, 0),
					Size = UDim2.fromOffset(16, 1),
					TextXAlignment = Enum.TextXAlignment.Center,
					theme = context.Theme,
				}
			)
			context.Disclosure = disclosure
		end
		disclosure.Position = UDim2.fromOffset(indent, 0)
		disclosure.Size = UDim2.fromOffset(16, context.Button.AbsoluteSize.Y)
		disclosure.Text = if record.HasChildren then (if record.Expanded then "−" else "+") else ""
		disclosure.Visible = record.HasChildren
		context.Primary.Position = UDim2.fromOffset(indent + 20, 0)
		context.Primary.Size = UDim2.new(1, -(indent + 28), 1, 0)
		context.TreeNode = record.Node
		context.TreeRecord = record
		context.Depth = record.Depth
		context.Path = record.Path
		context.HasChildren = record.HasChildren
		context.Expanded = record.Expanded
		if type(customRender) == "function" then
			call(customRender, context, record.Node, record, index, selected)
		end
	end

	local h: any = nil
	listOptions.Callback = function(path: any, oldPath: any, changed: any)
		local record = recordsByPath[path]
		local oldRecord = recordsByPath[oldPath]
		call(o.Callback, if record then record.Node else nil, if oldRecord then oldRecord.Node else nil, changed, path, oldPath)
		if type(o.OnSelect) == "function" then
			call(o.OnSelect, if record then record.Node else nil, record, path)
		end
	end
	listOptions.OnActivate = function(_context: any, record: any)
		if record.HasChildren then
			h:Toggle(record.Path)
			if o.SelectOnToggle == true then
				h:Set(record.Path, { Source = "user" })
			end
		else
			h:Set(record.Path, { Source = "user" })
		end
	end
	h = Controls.ListView(section, listOptions)

	local function applyVisible()
		rebuildVisible()
		h:SetItems(visible)
	end
	local function requirePath(path: any): any
		assert(type(path) == "string" and recordsByPath[path] ~= nil, "Unknown TreeView path: " .. tostring(path))
		return recordsByPath[path]
	end
	local defaultPath = if type(o.Default) == "string" then o.Default else if type(o.Selected) == "string" then o.Selected else nil
	if defaultPath ~= nil then
		requirePath(defaultPath)
		h:Set(defaultPath)
	end

	function h:SetNodes(nodes: any)
		local nextRoots, nextRecords, nextChildren = normalize(nodes)
		local nextExpanded = {}
		for path, _ in pairs(expanded) do
			if nextRecords[path] then
				nextExpanded[path] = true
			end
		end
		for path, record in pairs(nextRecords) do
			if record.Node.Expanded == true and record.HasChildren then
				nextExpanded[path] = true
			end
		end
		roots, recordsByPath, childrenByPath, expanded = nextRoots, nextRecords, nextChildren, nextExpanded
		applyVisible()
		return self
	end
	function h:GetNodes()
		local nodes = {}
		for _, path in ipairs(roots) do
			table.insert(nodes, recordsByPath[path].Node)
		end
		return nodes
	end
	function h:GetVisibleNodes()
		return table.clone(visible)
	end
	function h:RefreshTree()
		applyVisible()
		return self
	end
	function h:Expand(path: string)
		local record = requirePath(path)
		if record.HasChildren and not expanded[path] then
			expanded[path] = true
			applyVisible()
		end
		return self
	end
	function h:Collapse(path: string)
		requirePath(path)
		if expanded[path] then
			expanded[path] = nil
			applyVisible()
		end
		return self
	end
	function h:Toggle(path: string)
		local record = requirePath(path)
		if record.HasChildren then
			if expanded[path] then
				expanded[path] = nil
			else
				expanded[path] = true
			end
			applyVisible()
		end
		return self
	end
	function h:ExpandAll()
		for path, record in pairs(recordsByPath) do
			if record.HasChildren then
				expanded[path] = true
			end
		end
		applyVisible()
		return self
	end
	function h:CollapseAll()
		table.clear(expanded)
		applyVisible()
		return self
	end
	function h:IsExpanded(path: string): boolean
		requirePath(path)
		return expanded[path] == true
	end
	function h:Select(path: string)
		requirePath(path)
		assert(table.find(visible, recordsByPath[path]) ~= nil, "Cannot select a hidden TreeView node")
		h:Set(path)
		return self
	end
	function h:GetSelected()
		local path = h:Get()
		local record = recordsByPath[path]
		return if record then record.Node else nil, record, path
	end
	return h
end

function Controls.DataGrid(section: any, o: any)
	assert(type(o) == "table", "DataGrid requires options")
	local rows = table.clone(o.Rows or o.Items or {})
	local columns = {}
	local contentWidth = 0
	local version = 0
	local sortId: string? = nil
	local sortDirection: string? = nil

	local function prepareColumns(source: any)
		assert(type(source) == "table" and #source > 0, "DataGrid Columns must be a non-empty array")
		local prepared, seen, width = {}, {}, 0
		for index, column in ipairs(source) do
			assert(type(column) == "table", "DataGrid column " .. tostring(index) .. " must be a table")
			local columnId = tostring(column.Id or column.Key or column.Field or index)
			assert(not seen[columnId], "Duplicate DataGrid column: " .. columnId)
			seen[columnId] = true
			local copy = {}
			for key, value in pairs(column) do
				copy[key] = value
			end
			copy.Id = columnId
			copy.Width = math.max(64, tonumber(column.Width) or 140)
			table.insert(prepared, copy)
			width += copy.Width
		end
		return prepared, width
	end
	columns, contentWidth = prepareColumns(o.Columns)

	local function valueFor(row: any, column: any, rowIndex: number): any
		if type(column.Value) == "function" then
			return column.Value(row, rowIndex, column)
		end
		local field = column.Field or column.Key or column.Id
		if type(row) == "table" then
			return row[field]
		end
		return nil
	end
	local function sortedRows(): { any }
		local result = table.clone(rows)
		if sortId == nil or sortDirection == nil then
			return result
		end
		local column = nil
		for _, candidate in ipairs(columns) do
			if candidate.Id == sortId then
				column = candidate
				break
			end
		end
		if column == nil then
			return result
		end
		local order = {}
		for index, row in ipairs(result) do
			order[row] = index
		end
		table.sort(result, function(left, right)
			local leftValue = valueFor(left, column, order[left] or 0)
			local rightValue = valueFor(right, column, order[right] or 0)
			if type(column.Compare) == "function" then
				local firstValue, secondValue = leftValue, rightValue
				local firstRow, secondRow = left, right
				if sortDirection == "desc" then
					firstValue, secondValue, firstRow, secondRow = rightValue, leftValue, right, left
				end
				local ok, before = pcall(column.Compare, firstValue, secondValue, firstRow, secondRow)
				if ok then
					if before == true then return true end
					local reverseOk, after = pcall(column.Compare, secondValue, firstValue, secondRow, firstRow)
					if reverseOk then
						return if after == true then false else (order[left] or 0) < (order[right] or 0)
					end
				end
			end
			if leftValue == rightValue then
				return (order[left] or 0) < (order[right] or 0)
			end
			if leftValue == nil then
				return sortDirection == "desc"
			elseif rightValue == nil then
				return sortDirection ~= "desc"
			end
			local leftKey, rightKey = leftValue, rightValue
			if type(leftValue) ~= "number" or type(rightValue) ~= "number" then
				leftKey, rightKey = string.lower(tostring(leftValue)), string.lower(tostring(rightValue))
			end
			if leftKey == rightKey then return (order[left] or 0) < (order[right] or 0) end
			return if sortDirection == "desc" then rightKey < leftKey else leftKey < rightKey
		end)
		return result
	end

	local listOptions = {}
	for key, value in pairs(o) do
		listOptions[key] = value
	end
	listOptions.Provider = nil
	listOptions.Items = rows
	listOptions.Rows = nil
	listOptions.ContentWidth = contentWidth
	listOptions.HeaderHeight = math.max(64, tonumber(o.HeaderHeight) or 64)
	listOptions.RowHeight = o.RowHeight or 38
	listOptions.EmptyText = o.EmptyText or "No rows"
	local callerRender = o.RenderCell
	listOptions.Render = function(rowContext: any, item: any, rowIndex: number, selected: boolean)
		rowContext.Primary.Visible = false
		rowContext.Secondary.Visible = false
		if rowContext.GridVersion ~= version then
			if rowContext.GridContainer then
				rowContext.GridContainer:Destroy()
			end
			local container = Factory.make("Frame", {
				Name = "DataGridCells",
				BackgroundTransparency = 1,
				Size = UDim2.fromScale(1, 1),
			}, rowContext.Root) :: Frame
			rowContext.GridContainer = container
			rowContext.GridCells = {}
			rowContext.GridVersion = version
			local x = 0
			for columnIndex, column in ipairs(columns) do
				local cell = Factory.text(
					container,
					"",
					rowContext.Theme.typography.body * rowContext.Theme.textScale,
					rowContext.Theme.colors.text,
					{
						Name = "Cell_" .. column.Id,
						Position = UDim2.fromOffset(x + 10, 0),
						Size = UDim2.new(0, column.Width - 20, 1, 0),
						TextXAlignment = column.Align or Enum.TextXAlignment.Left,
						theme = rowContext.Theme,
					}
				)
				if columnIndex < #columns then
					Factory.make("Frame", {
						BackgroundColor3 = rowContext.Theme.colors.border,
						BorderSizePixel = 0,
						Position = UDim2.fromOffset(x + column.Width - 1, 6),
						Size = UDim2.new(0, 1, 1, -12),
					}, container)
				end
				rowContext.GridCells[column.Id] = cell
				x += column.Width
			end
		end
		for _, column in ipairs(columns) do
			local cell = rowContext.GridCells[column.Id]
			local value = valueFor(item, column, rowIndex)
			cell.Text = tostring(if value == nil then column.EmptyText or "" else value)
			cell.TextColor3 = if selected
				then rowContext.Theme.states.selected.text
				else rowContext.Theme.colors.text
			cell.TextSize = rowContext.Theme.typography.body * rowContext.Theme.textScale
			if type(callerRender) == "function" then
				call(callerRender, cell, value, item, rowIndex, column, selected, rowContext)
			end
		end
	end

	local list = Controls.ListView(section, listOptions)
	local listSetItems = list.SetItems
	local headerRoot = list.HeaderRoot
	assert(headerRoot ~= nil, "DataGrid requires a header surface")
	local headerMaid = Maid.new()
	list._maid:GiveTask(headerMaid)
	local headerInner: Frame? = nil
	local headerButtons = {}

	local function rebuildHeader()
		headerMaid:Clean()
		table.clear(headerButtons)
		headerInner = Factory.make("Frame", {
			Name = "DataGridHeaderInner",
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(contentWidth, headerRoot.AbsoluteSize.Y),
		}, headerRoot) :: Frame
		headerMaid:GiveTask(headerInner)
		local x = 0
		for _, column in ipairs(columns) do
			local columnValue = column
			local sortable = columnValue.Sortable ~= false
			local titleText = tostring(columnValue.Title or columnValue.Name or columnValue.Id)
			if sortId == columnValue.Id and sortDirection then
				titleText ..= if sortDirection == "asc" then "  ↑" else "  ↓"
			end
			local button = Factory.button(headerInner, titleText, list._context.Theme, {
				Name = "Header_" .. columnValue.Id,
				Position = UDim2.fromOffset(x, 0),
				Size = UDim2.fromOffset(columnValue.Width, math.max(30, headerRoot.AbsoluteSize.Y)),
				TextXAlignment = columnValue.Align or Enum.TextXAlignment.Left,
			})
			Factory.setInteractive(button, sortable, list._context.Theme)
			headerButtons[columnValue.Id] = button
			if sortable then
				headerMaid:GiveTask(button.Activated:Connect(function()
					local nextDirection: string
					if sortId == columnValue.Id then
						nextDirection = if sortDirection == "asc" then "desc" else "asc"
					else
						nextDirection = "asc"
					end
					list:SetSort(columnValue.Id, nextDirection)
				end))
			end
			x += columnValue.Width
		end
	end

	function list:SetRows(nextRows: any)
		assert(type(nextRows) == "table", "DataGrid Rows must be an array")
		local previousRows = rows
		rows = table.clone(nextRows)
		local ok, updateError = pcall(listSetItems, self, sortedRows())
		if not ok then
			rows = previousRows
			error(updateError, 2)
		end
		return self
	end
	list.SetItems = list.SetRows
	function list:GetRows()
		return table.clone(rows)
	end
	function list:SetColumns(nextColumns: any)
		columns, contentWidth = prepareColumns(nextColumns)
		version += 1
		self:SetContentWidth(contentWidth)
		if sortId then
			local known = false
			for _, column in ipairs(columns) do
				known = known or column.Id == sortId
			end
			if not known then
				sortId, sortDirection = nil, nil
			end
		end
		rebuildHeader()
		listSetItems(self, sortedRows())
		return self
	end
	function list:GetColumns()
		return table.clone(columns)
	end
	function list:SetSort(columnId: string, direction: string?)
		assert(direction == nil or direction == "asc" or direction == "desc", "DataGrid sort must be asc, desc, or nil")
		local known = false
		for _, column in ipairs(columns) do
			if column.Id == columnId then
				known = column.Sortable ~= false
				break
			end
		end
		assert(known, "Unknown or unsortable DataGrid column: " .. tostring(columnId))
		sortId, sortDirection = if direction then columnId else nil, direction
		listSetItems(self, sortedRows())
		rebuildHeader()
		return self
	end
	function list:GetSort()
		return sortId, sortDirection
	end
	function list:ClearSort()
		sortId, sortDirection = nil, nil
		listSetItems(self, rows)
		rebuildHeader()
		return self
	end
	function list:ScrollToColumn(columnId: string)
		local x = 0
		for _, column in ipairs(columns) do
			if column.Id == columnId then
				local maximum = math.max(0, contentWidth - self.Scroller.AbsoluteSize.X)
				self.Scroller.CanvasPosition = Vector2.new(math.clamp(x, 0, maximum), self.Scroller.CanvasPosition.Y)
				if headerInner then
					headerInner.Position = UDim2.fromOffset(-self.Scroller.CanvasPosition.X, 0)
				end
				return self
			end
			x += column.Width
		end
		error("Unknown DataGrid column: " .. tostring(columnId), 2)
	end
	list._maid:GiveTask(list.Scroller:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
		if headerInner then
			headerInner.Position = UDim2.fromOffset(-list.Scroller.CanvasPosition.X, 0)
		end
	end))
	if list._context.ThemeChanged then
		list._maid:GiveTask(list._context.ThemeChanged:Connect(function()
			version += 1
			rebuildHeader()
			list:Refresh()
		end))
	end
	rebuildHeader()
	attachAsyncProvider(list, o, function(nextRows)
		list:SetRows(nextRows)
	end)
	return list
end

function Controls.PlayerList(section: any, o: any)
	assert(type(o) == "table", "PlayerList requires options")
	local playersService = section._context.Runtime.services.Players
	local query = tostring(o.Query or "")
	local filter = o.Filter
	local list: any = nil
	local refreshPlayers: (() -> ())? = nil
	local characterRemoving = setmetatable({}, { __mode = "k" })
	local departed = setmetatable({}, { __mode = "k" })

	local function property(object: any, name: string, fallback: any): any
		local ok, value = pcall(function()
			return object[name]
		end)
		return if ok and value ~= nil then value else fallback
	end
	local function playerKey(player: any): string
		local userId = property(player, "UserId", nil)
		if userId ~= nil then
			return "player:" .. tostring(userId)
		end
		return "player-name:" .. tostring(property(player, "Name", player))
	end
	local function localPlayer(): any
		if playersService == nil then
			return nil
		end
		return property(playersService, "LocalPlayer", nil)
	end
	local function allPlayers(): { any }
		if playersService == nil then
			return {}
		end
		local ok, result = pcall(function()
			return playersService:GetPlayers()
		end)
		if not ok or type(result) ~= "table" then
			return {}
		end
		local current = {}
		for _, player in ipairs(result) do
			if not departed[player] then
				table.insert(current, player)
			end
		end
		return current
	end
	local function teamName(player: any): string
		local team = property(player, "Team", nil)
		if team ~= nil then
			return tostring(property(team, "Name", team))
		end
		return tostring(o.NoTeamText or "No team")
	end
	local function statusText(player: any): string
		if type(o.GetStatus) == "function" then
			local ok, result = pcall(o.GetStatus, player)
			if ok and result ~= nil then
				return tostring(result)
			end
		end
		local explicit = property(player, "Status", nil)
		if explicit ~= nil then
			return tostring(explicit)
		end
		if characterRemoving[player] then
			return tostring(o.RemovingText or "Respawning")
		end
		return if property(player, "Character", nil) ~= nil
			then tostring(o.ActiveText or "In game")
			else tostring(o.LoadingText or "Loading")
	end
	local function matches(player: any): boolean
		local needle = string.lower(query)
		if needle ~= "" then
			local searchable = table.concat({
				tostring(property(player, "DisplayName", "")),
				tostring(property(player, "Name", "")),
				tostring(property(player, "UserId", "")),
				teamName(player),
				statusText(player),
			}, " ")
			if string.find(string.lower(searchable), needle, 1, true) == nil then
				return false
			end
		end
		if type(filter) == "function" then
			local ok, accepted = pcall(filter, player, query)
			if not ok then
				warn("PotassiumUI PlayerList filter failed: " .. tostring(accepted))
				return false
			end
			return accepted == true
		end
		return true
	end
	local function records(): { any }
		local localValue = localPlayer()
		local result = {}
		for _, player in ipairs(allPlayers()) do
			if matches(player) then
				local name = tostring(property(player, "Name", "Unknown"))
				local displayName = tostring(property(player, "DisplayName", name))
				local isLocal = player == localValue
					or (
						localValue ~= nil
						and property(player, "UserId", nil) == property(localValue, "UserId", nil)
					)
				local team = teamName(player)
				local status = statusText(player)
				table.insert(result, {
					Id = playerKey(player),
					Player = player,
					UserId = property(player, "UserId", nil),
					Name = name,
					DisplayName = displayName,
					Title = displayName .. (if isLocal then tostring(o.LocalSuffix or " (You)") else ""),
					Detail = "@" .. name .. " · " .. team .. " · " .. status,
					Team = team,
					Status = status,
					IsLocal = isLocal,
				})
			end
		end
		table.sort(result, function(left, right)
			if type(o.Sort) == "function" then
				local ok, before = pcall(o.Sort, left.Player, right.Player)
				if ok then
					return before == true
				end
			end
			if left.IsLocal ~= right.IsLocal then
				return left.IsLocal
			end
			local leftName, rightName = string.lower(left.DisplayName), string.lower(right.DisplayName)
			if leftName == rightName then
				return tostring(left.Id) < tostring(right.Id)
			end
			return leftName < rightName
		end)
		return result
	end
	local function selectionKey(value: any): any
		if property(value, "UserId", nil) ~= nil then
			return playerKey(value)
		end
		return value
	end

	local searchControl: any = nil
	if o.Searchable ~= false then
		searchControl = Controls.Textbox(section, {
			Id = tostring(o.Id or "players") .. "-search",
			Title = tostring(o.SearchTitle or "Search players"),
			Default = query,
			MaxLength = o.SearchMaxLength or 80,
			Persist = false,
			Callback = function(value: any)
				query = tostring(value)
				call(o.OnSearch, query)
				if refreshPlayers then
					refreshPlayers()
				end
			end,
		})
	end

	local listOptions = {}
	for key, value in pairs(o) do
		listOptions[key] = value
	end
	listOptions.Items = records()
	listOptions.Key = "Id"
	listOptions.EmptyText = o.EmptyText or (if playersService then "No matching players" else "Players unavailable")
	listOptions.Callback = nil
	listOptions.Render = function(row: any, record: any, index: number, selected: boolean)
		row.Root:SetAttribute("PlayerUserId", record.UserId)
		row.Root:SetAttribute("PlayerName", record.Name)
		row.Root:SetAttribute("PlayerTeam", record.Team)
		row.Root:SetAttribute("PlayerStatus", record.Status)
		row.Root:SetAttribute("LocalPlayer", record.IsLocal)
		if type(o.Render) == "function" then
			call(o.Render, row, record.Player, index, selected, record)
		end
	end
	listOptions.OnSelect = function(selectedRecords: any, indices: any, keysValue: any)
		if o.MultiSelect == true then
			local selectedPlayers = {}
			for _, record in ipairs(selectedRecords) do
				table.insert(selectedPlayers, record.Player)
			end
			call(o.OnSelect or o.Callback, selectedPlayers, indices, keysValue)
		else
			call(
				o.OnSelect or o.Callback,
				if selectedRecords then selectedRecords.Player else nil,
				indices,
				keysValue
			)
		end
	end
	local initialSelection = if o.Default ~= nil then o.Default else o.Selected
	if initialSelection ~= nil then
		if o.MultiSelect == true then
			local defaults = {}
			for _, value in ipairs(initialSelection) do
				table.insert(defaults, selectionKey(value))
			end
			listOptions.Default = defaults
			listOptions.Selected = nil
		else
			listOptions.Default = selectionKey(initialSelection)
			listOptions.Selected = nil
		end
	end

	local created, listOrError = pcall(Controls.ListView, section, listOptions)
	if not created then
		if searchControl then
			searchControl:Destroy()
		end
		error(listOrError, 2)
	end
	list = listOrError
	if searchControl then
		list._maid:GiveTask(searchControl)
	end

	local observers = {}
	local function connect(maid: any, signal: any, callback: (...any) -> ())
		if signal == nil then
			return
		end
		local ok, connection = pcall(function()
			return signal:Connect(callback)
		end)
		if ok and connection ~= nil then
			maid:GiveTask(connection)
		end
	end
	local function watch(player: any)
		if observers[player] then
			return
		end
		local observer = Maid.new()
		observers[player] = observer
		local function refresh()
			if refreshPlayers then
				refreshPlayers()
			end
		end
		local function bindTeam()
			local teamObserver = Maid.new()
			observer:Set("team-name", teamObserver)
			local team = property(player, "Team", nil)
			if team == nil then
				return
			end
			local ok, signal = pcall(function()
				return team:GetPropertyChangedSignal("Name")
			end)
			if ok then
				connect(teamObserver, signal, refresh)
			end
		end
		for _, propertyName in ipairs({ "Name", "DisplayName", "TeamColor", "Neutral", "Status" }) do
			local ok, signal = pcall(function()
				return player:GetPropertyChangedSignal(propertyName)
			end)
			if ok then
				connect(observer, signal, refresh)
			end
		end
		local teamOk, teamSignal = pcall(function()
			return player:GetPropertyChangedSignal("Team")
		end)
		if teamOk then
			connect(observer, teamSignal, function()
				bindTeam()
				refresh()
			end)
		end
		bindTeam()
		connect(observer, property(player, "CharacterAdded", nil), function()
			characterRemoving[player] = nil
			refresh()
		end)
		connect(observer, property(player, "CharacterRemoving", nil), function()
			characterRemoving[player] = true
			refresh()
		end)
	end
	local function reconcileObservers(players: { any })
		local current = {}
		for _, player in ipairs(players) do
			current[player] = true
			watch(player)
		end
		for player, observer in pairs(observers) do
			if not current[player] then
				observer:Destroy()
				observers[player] = nil
			end
		end
	end
	refreshPlayers = function()
		if list._destroyed then
			return
		end
		local current = allPlayers()
		reconcileObservers(current)
		list:SetItems(records())
	end
	list._maid:GiveTask(function()
		for player, observer in pairs(observers) do
			observer:Destroy()
			observers[player] = nil
		end
	end)
	if playersService ~= nil then
		connect(list._maid, property(playersService, "PlayerAdded", nil), function(player: any)
			departed[player] = nil
			watch(player)
			refreshPlayers()
		end)
		connect(list._maid, property(playersService, "PlayerRemoving", nil), function(player: any)
			departed[player] = true
			local observer = observers[player]
			if observer then
				observer:Destroy()
				observers[player] = nil
			end
			refreshPlayers()
		end)
	end

	function list:RefreshPlayers()
		refreshPlayers()
		return self
	end
	function list:SetQuery(value: any)
		if searchControl then
			searchControl:Set(tostring(value))
		else
			query = tostring(value)
			refreshPlayers()
		end
		return self
	end
	function list:GetQuery(): string
		return query
	end
	function list:SetFilter(nextFilter: any)
		assert(nextFilter == nil or type(nextFilter) == "function", "PlayerList filter must be a function or nil")
		filter = nextFilter
		refreshPlayers()
		return self
	end
	function list:GetPlayers()
		local result = {}
		for _, record in ipairs(self:GetItems()) do
			table.insert(result, record.Player)
		end
		return result
	end
	function list:GetAllPlayers()
		return allPlayers()
	end
	function list:GetSelectedPlayer()
		if o.MultiSelect == true then
			local selectedRecords, indices, keysValue = self:GetSelected()
			local selectedPlayers = {}
			for _, record in ipairs(selectedRecords) do
				table.insert(selectedPlayers, record.Player)
			end
			return selectedPlayers, indices, keysValue
		end
		local record, index, key = self:GetSelected()
		return if record then record.Player else nil, index, key
	end
	function list:SetSelectedPlayer(value: any)
		if o.MultiSelect == true then
			local selectedKeys = {}
			for _, player in ipairs(value) do
				table.insert(selectedKeys, selectionKey(player))
			end
			return self:SetSelected(selectedKeys)
		end
		return self:SetSelected(selectionKey(value))
	end
	function list:GetSearchControl()
		return searchControl
	end

	refreshPlayers()
	return list
end

function Controls.Progressbar(section: any, o: any, defaultArg: any, callback: any)
	o = positional(o, nil, defaultArg, callback)
	local h = base(section, o, "Progressbar", Util.clamp(o.Default or 0, 0, 1), Store.Validators.number(0, 1))
	label(h, tostring(o.Title or o.Name or "Progress"))
	local track = Factory.make("Frame", {
		BackgroundColor3 = h._context.Theme.colors.border,
		BorderSizePixel = 0,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, 0, 0.7, 0),
		Size = UDim2.new((100 - metric(h._context, "labelWidth")) / 100, 0, 0, metric(h._context, "borderWidth") * 8),
	}, h.Root) :: Frame
	local fill = Factory.make("Frame", {
		BackgroundColor3 = h._context.Theme.states.selected.background,
		BorderSizePixel = 0,
		Size = UDim2.fromScale(0, 1),
	}, track) :: Frame
	Factory.corner(track, 4)
	Factory.corner(fill, 4)
	local valueLabel = Factory.text(
		h.Root,
		"0%",
		h._context.Theme.typography.caption * h._context.Theme.textScale,
		h._context.Theme.colors.textMuted,
		{
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, 0, 0, 0),
			Size = UDim2.new((100 - metric(h._context, "labelWidth")) / 100, 0, 0, 18),
			TextXAlignment = Enum.TextXAlignment.Right,
		}
	)
	function h:_render(v: number)
		local theme = h._context.Theme
		track.BackgroundColor3 = theme.colors.border
		fill.BackgroundColor3 = theme.states.selected.background
		fill.Size = UDim2.fromScale(v, 1)
		valueLabel.Text = string.format("%d%%", math.floor(v * 100 + 0.5))
		valueLabel.TextColor3 = theme.colors.textMuted
		valueLabel.TextSize = theme.typography.caption * theme.textScale
	end
	h:_render(h:Get())
	themeConnection(h)
	return h
end
function Controls.Space(section: any, o: any)
	if type(o) ~= "table" then
		o = { Size = o }
	end
	return static(section, o, o.Height or o.Size or 8)
end
function Controls.Image(section: any, o: any, height: any)
	if type(o) ~= "table" then
		o = { Height = if type(height) == "number" then height else nil }
	end
	local h = static(section, o, o.Height or 120)
	local t = h._context.Theme
	h.Root.BackgroundTransparency = 0
	h.Root.BackgroundColor3 = t.colors.surfaceRaised
	Factory.corner(h.Root, t.radius.sm)
	local alt = Factory.text(
		h.Root,
		tostring(o.Alt or "Image unavailable"),
		t.typography.body * t.textScale,
		t.colors.textMuted,
		{ Size = UDim2.fromScale(1, 1), TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Center }
	)
	local image = Factory.make(
		"ImageLabel",
		{ BackgroundTransparency = 1, ScaleType = Enum.ScaleType.Fit, Size = UDim2.fromScale(1, 1), Visible = false },
		h.Root
	) :: ImageLabel
	local policy = h._context.AssetPolicy
	local declaration = o.Asset
	if policy == nil or type(policy.Admit) ~= "function" or type(policy.Resolve) ~= "function" or type(policy.ReleaseOwner) ~= "function" then
		h.Error = { code = "asset_policy_unavailable", message = "Image rendering requires the context asset policy." }
	elseif type(declaration) ~= "table" then
		h.Error = { code = "invalid_asset", message = "Image requires an explicit tagged Asset declaration." }
	else
		local admitted, admitError = policy:Admit(declaration, "$.Image.Asset", h)
		if admitted == nil then
			h.Error = admitError
		elseif admitted.kind ~= "image" then
			policy:ReleaseOwner(h)
			h.Error = {
				code = "invalid_image_asset_kind",
				message = "Image requires an admitted Asset declaration with kind 'image'.",
			}
		else
			local resolved, resolveError = policy:Resolve(admitted, h._context.Runtime, "$.Image.Asset")
			if resolved == nil then
				policy:ReleaseOwner(h)
				h.Error = resolveError
			else
				h._maid:GiveTask(function()
					policy:ReleaseOwner(h)
				end)
				if resolved ~= "" then
					image.Image = resolved
					image.Visible, alt.Visible = true, false
				else
					-- Offline builtin/fallback assets are semantic; retain the deterministic local placeholder.
					h.Root:SetAttribute("AssetFallback", admitted.source.value)
				end
				if admitted.scaleType ~= nil then image.ScaleType = Enum.ScaleType[admitted.scaleType] end
				if admitted.rectOffset ~= nil then image.ImageRectOffset = admitted.rectOffset end
				if admitted.rectSize ~= nil then image.ImageRectSize = admitted.rectSize end
			end
		end
	end
	function h:GetError()
		return self.Error
	end
	local rootThemeTransition = registerThemeBinding(h, h.Root, {
		BackgroundColor3 = "colors.surfaceRaised",
	})
	local altThemeTransition = registerThemeBinding(h, alt, {
		TextColor3 = "colors.textMuted",
	})
	bindTheme(h, function(theme)
		if not rootThemeTransition then h.Root.BackgroundColor3 = theme.colors.surfaceRaised end
		if not altThemeTransition then alt.TextColor3 = theme.colors.textMuted end
		alt.TextSize = theme.typography.body * theme.textScale
	end)
	return h
end
local function exclusiveSelection(section: any, o: any, name: string, segmented: boolean): any
	assert(type(o) == "table", name .. " requires options")

	local function optionValue(option: any): any
		local value = if type(option) == "table"
			then (if option.Id ~= nil then option.Id elseif option.Key ~= nil then option.Key else option.Value)
			else option
		local valueType = type(value)
		assert(
			valueType == "string" or valueType == "number" or valueType == "boolean",
			name .. " option keys must be strings, numbers, or booleans"
		)
		return value
	end
	local function optionKey(value: any): string
		local text, valueType = tostring(value), type(value)
		return valueType .. ":" .. tostring(#text) .. ":" .. text
	end
	local function selectionKey(value: any): string
		return optionKey(if type(value) == "table" then optionValue(value) else value)
	end

	local function prepare(source: any): { any }
		assert(type(source) == "table", name .. " Options must be an array")
		local prepared, keys = {}, {}
		for index, option in ipairs(source) do
			local value = optionValue(option)
			local key = optionKey(value)
			assert(not keys[key], "Duplicate " .. name .. " option key: " .. tostring(value))
			keys[key] = true
			table.insert(prepared, {
				Key = key,
				Value = value,
				Title = tostring(if type(option) == "table" then option.Title or option.Name or value else value),
				Disabled = type(option) == "table" and option.Disabled == true,
				Option = option,
			})
		end
		return prepared
	end

	local options = prepare(o.Options or o.Items or {})
	local selected = if o.Default ~= nil then o.Default else o.Selected
	if type(selected) == "table" then
		selected = optionValue(selected)
	end
	local known = {}
	for _, option in ipairs(options) do
		known[option.Key] = option
	end
	if selected ~= nil then
		assert(known[selectionKey(selected)] ~= nil, name .. " Default/Selected must identify an option")
	end

	local h = base(section, o, name, selected, function(value: any): (boolean, string?)
		if value == nil then
			return true, nil
		end
		return known[selectionKey(value)] ~= nil, "value is not an available option"
	end, nil)
	h._optionsList = options
	h._optionByKey = known
	h._buttons = {}
	local storeSet = h.Set
	function h:Set(value: any, options: any?)
		if value ~= nil then
			local option = self._optionByKey[selectionKey(value)]
			assert(option ~= nil, "Unknown " .. name .. " option: " .. tostring(value))
			assert(not option.Disabled, "Cannot select a disabled " .. name .. " option")
			value = option.Value
		end
		return storeSet(self, value, options)
	end

	h._segmented = segmented
	local titleHeight = 20
	local gap = 4
	local rowHeight = 32
	local choices = Factory.make("Frame", {
		Name = "Options",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(0, titleHeight),
		Size = UDim2.new(1, 0, 0, 0),
	}, h.Root) :: Frame
	label(h, tostring(o.Title or o.Name or name))
	h._title.Size = UDim2.new(1, 0, 0, titleHeight)

	local function layoutMetadata()
		local count = #h._optionsList
		local columns: number
		if segmented then
			columns = if o.Wrap == true then math.max(1, math.floor(tonumber(o.Columns) or 3)) else math.max(1, count)
		else
			columns = math.max(1, math.floor(tonumber(o.Columns) or 1))
		end
		local rows = math.max(1, math.ceil(count / columns))
		return columns, rows
	end
	local function resize()
		local columns, rows = layoutMetadata()
		local height = titleHeight + rows * rowHeight + math.max(0, rows - 1) * gap
		h.Root.Size = UDim2.new(1, 0, 0, height)
		choices.Size = UDim2.new(1, 0, 0, height - titleHeight)
		choices:SetAttribute("SelectionColumns", columns)
		choices:SetAttribute("SelectionRows", rows)
		choices:SetAttribute("SelectionWrap", segmented and o.Wrap == true)
		choices:SetAttribute("SelectionLayout", if segmented then "segmented" else "radio")
		return columns
	end
	local function render(value: any)
		for _, option in ipairs(h._optionsList) do
			local button = h._buttons[option.Key]
			if button then
				local state = if h._locked or option.Disabled
					then "disabled"
					elseif value == option.Value then "selected"
					else "default"
				Factory.setButtonState(button, state, h._context.Theme)
				Factory.setInteractive(button, active(h) and not option.Disabled, h._context.Theme)
			end
		end
	end
	function h:_render(value: any)
		render(value)
	end

	local function rebuild()
		local optionMaid = Maid.new()
		h._maid:Set("selection-options", optionMaid)
		h._buttons = {}
		for _, child in ipairs(choices:GetChildren()) do
			child:Destroy()
		end
		local columns = resize()
		Factory.grid(
			choices,
			UDim2.new(1 / columns, -gap * (columns - 1) / columns, 0, rowHeight),
			UDim2.fromOffset(gap, gap),
			columns
		)
		for index, option in ipairs(h._optionsList) do
			local button = Factory.button(choices, option.Title, h._context.Theme, {
				Role = "segment",
				Name = "Option_" .. Util.sanitizeId(option.Key),
				LayoutOrder = index,
				TextXAlignment = if segmented then Enum.TextXAlignment.Center else Enum.TextXAlignment.Left,
			})
			button:SetAttribute("OptionKey", option.Key)
			button:SetAttribute("OptionValue", tostring(option.Value))
			h._buttons[option.Key] = button
			optionMaid:GiveTask(button.Activated:Connect(function()
				if active(h) and not option.Disabled then
					h:Set(option.Value, { Source = "user" })
					selectionHaptic(h)
				end
			end))
			bindPillFocus(section, h, optionMaid, h.Id .. ".option." .. Util.sanitizeId(option.Key), button)
		end
		render(h:Get())
	end

	function h:SetOptions(source: any)
		local nextOptions = prepare(source)
		local nextKnown = {}
		for _, option in ipairs(nextOptions) do
			nextKnown[option.Key] = option
		end
		local current = self:Get()
		options, known = nextOptions, nextKnown
		self._optionsList, self._optionByKey = nextOptions, nextKnown
		rebuild()
		if current ~= nil and nextKnown[selectionKey(current)] == nil then
			self:Set(nil)
		end
		return self
	end
	function h:GetOptions()
		local result = {}
		for index, option in ipairs(self._optionsList) do
			result[index] = option.Option
		end
		return result
	end
	function h:Select(value: any)
		self:Set(value)
		return self
	end
	function h:GetSelectedOption()
		local value = self:Get()
		local option = value ~= nil and self._optionByKey[selectionKey(value)] or nil
		return if option then option.Option else nil
	end
	rebuild()
	installPillFocus(h, function()
		return h._optionsList
	end)
	themeConnection(h)
	return h
end

function Controls.RadioGroup(section: any, o: any)
	return exclusiveSelection(section, o, "RadioGroup", false)
end

function Controls.SegmentedControl(section: any, o: any)
	return exclusiveSelection(section, o, "SegmentedControl", true)
end

local function pillScalar(value: any, name: string): any
	local scalar = if type(value) == "table"
		then (if value.Id ~= nil then value.Id elseif value.Key ~= nil then value.Key else value.Value)
		else value
	assert(type(scalar) == "string" or type(scalar) == "number" or type(scalar) == "boolean", name .. " values must be scalar")
	return scalar
end
local function pillKey(value: any): string
	local text = tostring(value)
	return type(value) .. ":" .. tostring(#text) .. ":" .. text
end
local function wrappedPills(h: any, title: string): Frame
	label(h, title)
	h._title.Size = UDim2.new(1, 0, 0, 20)
	local choices = Factory.make("Frame", { Name = "Pills", BackgroundTransparency = 1, Position = UDim2.fromOffset(0, 22), Size = UDim2.new(1, 0, 0, 0) }, h.Root) :: Frame
	local layout = Factory.list(choices, 4, true)
	layout.Wraps = true
	choices:SetAttribute("PillWrap", true)
	choices:SetAttribute("PillLayout", "wrapped")
	local function resize()
		local content = layout.AbsoluteContentSize
		choices.Size = UDim2.new(1, 0, 0, content.Y)
		h.Root.Size = UDim2.new(1, 0, 0, 22 + content.Y)
	end
	h._maid:GiveTask(layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(resize))
	return choices
end
local function tagItem(item: any): any
	local value = pillScalar(item, "Tags")
	return { Key = pillKey(value), Value = value, Title = tostring(if type(item) == "table" then item.Title or item.Name or value else item), Disabled = type(item) == "table" and item.Disabled == true, Item = item }
end
local function prepareTags(source: any, duplicates: boolean, max: number?): { any }
	assert(type(source) == "table", "Tags Items must be an array")
	local result, counts = {}, {}
	for _, sourceItem in ipairs(source) do
		local item = tagItem(sourceItem)
		local count = (counts[item.Key] or 0) + 1
		assert(duplicates or count == 1, "Duplicate tag: " .. tostring(item.Value))
		counts[item.Key] = count
		item.ValueKey = item.Key
		if duplicates then item.Key ..= ":" .. tostring(count) end
		table.insert(result, item)
	end
	assert(max == nil or #result <= max, "Tags exceed Max")
	return result
end
local function tagValues(items: { any }): { any }
	local result = {}
	for index, item in ipairs(items) do result[index] = item.Value end
	return result
end
local function tagSources(items: { any }): { any }
	local result = {}
	for index, item in ipairs(items) do result[index] = item.Item end
	return result
end
function Controls.Tags(section: any, o: any): any
	assert(type(o) == "table", "Tags requires options")
	local max, duplicates = o.Max, o.AllowDuplicates == true
	assert(max == nil or (type(max) == "number" and max >= 0 and max % 1 == 0), "Tags Max must be a non-negative integer")
	local initial = prepareTags(o.Items or o.Default or {}, duplicates, max)
	local h = base(section, o, "Tags", tagValues(initial), function(value: any): (boolean, string?)
		if type(value) ~= "table" then return false, "value must be an array" end
		local seen, count = {}, 0
		for _, entry in ipairs(value) do
			if type(entry) ~= "string" and type(entry) ~= "number" and type(entry) ~= "boolean" then return false, "tag values must be scalar" end
			local key = pillKey(entry)
			if not duplicates and seen[key] then return false, "duplicate tag" end
			seen[key], count = true, count + 1
		end
		return max == nil or count <= max, if max ~= nil and count > max then "too many tags" else nil
	end)
	h._items, h._buttons, h._removable = initial, {}, o.Removable ~= false
	local choices = wrappedPills(h, tostring(o.Title or o.Name or "Tags"))
	h._choices = choices
	local function render()
		for _, item in ipairs(h._items) do
			local button = h._buttons[item.Key]
			if button then
				local disabled = h._locked or item.Disabled or not h._removable
				Factory.setButtonState(button, if disabled then "disabled" else "selected", h._context.Theme)
				Factory.setInteractive(button, active(h) and not item.Disabled and h._removable, h._context.Theme)
			end
		end
	end
	local function rebuild()
		if h._destroyed then return end
		h._rebuildingPills = true
		local pillMaid = Maid.new()
		h._maid:Set("tag-pills", pillMaid)
		h._buttons = {}
		for _, child in ipairs(choices:GetChildren()) do if not child:IsA("UIListLayout") then child:Destroy() end end
		choices:SetAttribute("PillCount", #h._items)
		for index, item in ipairs(h._items) do
			local text = item.Title .. if h._removable then " ×" else ""
			local button = Factory.button(choices, text, h._context.Theme, {
				Role = "segment", Name = "Tag_" .. Util.sanitizeId(item.Key), LayoutOrder = index,
				Size = UDim2.fromOffset(math.max(54, #text * 7 + 12), 28),
			})
			button:SetAttribute("PillKey", item.Key)
			h._buttons[item.Key] = button
			pillMaid:GiveTask(button.Activated:Connect(function()
				if active(h) and h._removable and not item.Disabled then
					h:Remove(item.Value, { Source = "user" })
					selectionHaptic(h)
				end
			end))
			bindPillFocus(section, h, pillMaid, h.Id .. ".tag." .. Util.sanitizeId(item.Key), button)
		end
		h._rebuildingPills = false
		restorePillFocus(h, h._items, "pill_rebuild")
		render()
	end
	local storeSet = h.Set
	function h:_render(value: any)
		local matches = #value == #self._items
		if matches then
			for index, entry in ipairs(value) do
				if self._items[index].Value ~= entry then matches = false; break end
			end
		end
		if matches then render(); return end
		local available = {}
		for _, item in ipairs(self._items) do
			local queue = available[item.ValueKey]
			if queue == nil then
				queue = {}
				available[item.ValueKey] = queue
			end
			table.insert(queue, item.Item)
		end
		local source = {}
		for _, entry in ipairs(value) do
			local queue = available[pillKey(entry)]
			table.insert(source, if queue and #queue > 0 then table.remove(queue, 1) else entry)
		end
		self._items = prepareTags(source, duplicates, max)
		rebuild()
	end
	function h:SetItems(source: any, options: any?)
		local items = prepareTags(source, duplicates, max)
		local previousItems = self._items
		self._items = items
		local ok, err = pcall(storeSet, self, tagValues(items), options)
		if not ok then
			self._items = previousItems
			error(err, 0)
		end
		rebuild()
		return self
	end
	function h:GetItems() return tagSources(self._items) end
	function h:Has(value: any): boolean
		local key = pillKey(pillScalar(value, "Tags"))
		for _, item in ipairs(self._items) do if item.ValueKey == key then return true end end
		return false
	end
	function h:Add(value: any, options: any?)
		local item = tagItem(value)
		if (not duplicates and self:Has(item.Value)) or (max ~= nil and #self._items >= max) then return self end
		local items = table.clone(self._items)
		table.insert(items, item)
		self:SetItems(tagSources(items), options)
		call(o.OnAdd, item.Value, item.Item)
		return self
	end
	function h:Remove(value: any, options: any?)
		local key, source, removed = pillKey(pillScalar(value, "Tags")), {}, nil
		for _, item in ipairs(self._items) do
			if removed == nil and item.ValueKey == key then removed = item else table.insert(source, item.Item) end
		end
		if removed then
			self:SetItems(source, options)
			call(o.OnRemove, removed.Value, removed.Item)
		end
		return self
	end
	function h:Toggle(value: any, options: any?)
		return if self:Has(value) then self:Remove(value, options) else self:Add(value, options)
	end
	function h:Clear(options: any?) return self:SetItems({}, options) end
	h:_render(h:Get())
	if next(h._buttons) == nil then rebuild() end
	installPillFocus(h, function()
		return h._items
	end)
	themeConnection(h)
	return h
end
local function prepareChips(source: any): ({ any }, { [string]: any })
	assert(type(source) == "table", "Chips Options must be an array")
	local result, known = {}, {}
	for _, sourceOption in ipairs(source) do
		local value, key = pillScalar(sourceOption, "Chips"), nil
		key = pillKey(value)
		assert(known[key] == nil, "Duplicate Chips option: " .. tostring(value))
		local option = { Key = key, Value = value, Title = tostring(if type(sourceOption) == "table" then sourceOption.Title or sourceOption.Name or value else sourceOption), Disabled = type(sourceOption) == "table" and sourceOption.Disabled == true, Option = sourceOption }
		known[key] = option
		table.insert(result, option)
	end
	return result, known
end
function Controls.Chips(section: any, o: any): any
	assert(type(o) == "table", "Chips requires options")
	local multi, max = o.MultiSelect == true, o.MaxSelections
	assert(max == nil or (type(max) == "number" and max >= 0 and max % 1 == 0), "Chips MaxSelections must be a non-negative integer")
	local options, known = prepareChips(o.Options or o.Items or {})
	local liveKnown = known
	local default = if o.Default ~= nil then o.Default elseif o.Selected ~= nil then o.Selected elseif multi then {} else nil
	if multi then
		assert(type(default) == "table", "MultiSelect Chips Default must be an array")
		local normalized = {}
		for _, value in ipairs(default) do table.insert(normalized, pillScalar(value, "Chips")) end
		default = normalized
	elseif type(default) == "table" then
		default = pillScalar(default, "Chips")
	end
	local function validate(value: any): (boolean, string?)
		if multi and type(value) ~= "table" then return false, "value must be an array" end
		local values, seen, count = if multi then value else { value }, {}, 0
		for _, selectedValue in ipairs(values) do
			if selectedValue ~= nil then
				local option = liveKnown[pillKey(selectedValue)]
				if not option then return false, "value is not an available option" end
				if option.Disabled then return false, "cannot select a disabled option" end
				if seen[option.Key] then return false, "duplicate selection" end
				seen[option.Key], count = true, count + 1
			end
		end
		return max == nil or count <= max, if max ~= nil and count > max then "too many selections" else nil
	end
	assert(select(1, validate(default)), "Chips Default/Selected must identify enabled options and obey MaxSelections")
	local h = base(section, o, "Chips", default, validate)
	h._optionsList, h._optionByKey, h._buttons = options, known, {}
	local choices = wrappedPills(h, tostring(o.Title or o.Name or "Chips"))
	h._choices = choices
	local function isSelected(value: any, key: string): boolean
		if multi then for _, entry in ipairs(value) do if pillKey(entry) == key then return true end end return false end
		return value ~= nil and pillKey(value) == key
	end
	local function render(value: any)
		for _, option in ipairs(h._optionsList) do
			local button = h._buttons[option.Key]
			if button then
				Factory.setButtonState(button, if h._locked or option.Disabled then "disabled" elseif isSelected(value, option.Key) then "selected" else "default", h._context.Theme)
				Factory.setInteractive(button, active(h) and not option.Disabled, h._context.Theme)
			end
		end
	end
	function h:_render(value: any)
		render(value)
	end
	local function rebuild()
		h._rebuildingPills = true
		local pillMaid = Maid.new()
		h._maid:Set("chip-pills", pillMaid)
		h._buttons = {}
		for _, child in ipairs(choices:GetChildren()) do if not child:IsA("UIListLayout") then child:Destroy() end end
		choices:SetAttribute("PillCount", #h._optionsList)
		for index, option in ipairs(h._optionsList) do
			local button = Factory.button(choices, option.Title, h._context.Theme, {
				Role = "segment", Name = "Chip_" .. Util.sanitizeId(option.Key), LayoutOrder = index,
				Size = UDim2.fromOffset(math.max(48, #option.Title * 7 + 16), 28),
			})
			button:SetAttribute("PillKey", option.Key)
			h._buttons[option.Key] = button
			pillMaid:GiveTask(button.Activated:Connect(function()
				if active(h) and not option.Disabled then
					local selected = isSelected(h:Get(), option.Key)
					if not multi or selected or max == nil or #h:Get() < max then
						h:Toggle(option.Value, { Source = "user" })
						selectionHaptic(h)
					end
				end
			end))
			bindPillFocus(section, h, pillMaid, h.Id .. ".chip." .. Util.sanitizeId(option.Key), button)
		end
		h._rebuildingPills = false
		restorePillFocus(h, h._optionsList, "pill_rebuild")
		render(h:Get())
	end
	local storeSet = h.Set
	function h:Set(value: any, mutationOptions: any?)
		if not multi and value ~= nil then value = pillScalar(value, "Chips") end
		return storeSet(self, value, mutationOptions)
	end
	function h:SetOptions(source: any)
		local nextOptions, nextKnown = prepareChips(source)
		local current, nextValue = self:Get(), self:Get()
		if multi then
			nextValue = {}
			for _, value in ipairs(current) do
				local option = nextKnown[pillKey(value)]
				if option and not option.Disabled then table.insert(nextValue, value) end
			end
		elseif current ~= nil and (not nextKnown[pillKey(current)] or nextKnown[pillKey(current)].Disabled) then
			nextValue = nil
		end
		local oldOptions, oldKnown, oldLive = self._optionsList, self._optionByKey, liveKnown
		self._optionsList, self._optionByKey, liveKnown = nextOptions, nextKnown, nextKnown
		local ok, err = pcall(function() self:Set(nextValue) end)
		if not ok then
			self._optionsList, self._optionByKey, liveKnown = oldOptions, oldKnown, oldLive
			error(err, 0)
		end
		options, known = nextOptions, nextKnown
		rebuild()
		return self
	end
	function h:GetOptions()
		local result = {}
		for index, option in ipairs(self._optionsList) do result[index] = option.Option end
		return result
	end
	function h:Select(value: any, mutationOptions: any?)
		value = pillScalar(value, "Chips")
		local option = self._optionByKey[pillKey(value)]
		assert(option ~= nil, "Unknown Chips option: " .. tostring(value))
		assert(not option.Disabled, "Cannot select a disabled Chips option")
		if multi then
			local current = self:Get()
			if isSelected(current, option.Key) or (max ~= nil and #current >= max) then return self end
			local nextValue = table.clone(current)
			table.insert(nextValue, option.Value)
			self:Set(nextValue, mutationOptions)
		else
			self:Set(option.Value, mutationOptions)
		end
		return self
	end
	function h:Deselect(value: any, mutationOptions: any?)
		value = pillScalar(value, "Chips")
		if multi then
			local result = {}
			for _, entry in ipairs(self:Get()) do if pillKey(entry) ~= pillKey(value) then table.insert(result, entry) end end
			self:Set(result, mutationOptions)
		elseif self:Get() ~= nil and pillKey(self:Get()) == pillKey(value) then
			self:Set(nil, mutationOptions)
		end
		return self
	end
	function h:Toggle(value: any, mutationOptions: any?)
		value = pillScalar(value, "Chips")
		return if isSelected(self:Get(), pillKey(value)) then self:Deselect(value, mutationOptions) else self:Select(value, mutationOptions)
	end
	function h:Clear(mutationOptions: any?) return self:Set(if multi then {} else nil, mutationOptions) end
	function h:GetSelectedOptions()
		local result = {}
		local values = if multi then self:Get() else { self:Get() }
		for _, value in ipairs(values) do
			local option = self._optionByKey[pillKey(value)]
			if option then table.insert(result, option.Option) end
		end
		return result
	end
	rebuild()
	installPillFocus(h, function()
		return h._optionsList
	end)
	themeConnection(h)
	if h._context.ThemeChanged then h._maid:GiveTask(h._context.ThemeChanged:Connect(function() render(h:Get()) end)) end
	return h
end
local function finite(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

local function sparklineSamples(source: any, maxSamples: number): { any }
	assert(type(source) == "table", "Sparkline samples must be an array")
	local result = {}
	for index, sample in ipairs(source) do
		local value = if type(sample) == "table" then sample.Value else sample
		assert(finite(value), "Sparkline sample " .. tostring(index) .. " must be finite")
		if type(sample) == "table" then
			assert(sample.Timestamp == nil or finite(sample.Timestamp), "Sparkline sample Timestamp must be finite")
			assert(sample.Label == nil or type(sample.Label) == "string", "Sparkline sample Label must be a string")
		end
		table.insert(result, { Value = value, Timestamp = if type(sample) == "table" then sample.Timestamp else nil, Label = if type(sample) == "table" then sample.Label else nil })
	end
	local first = math.max(1, #result - maxSamples + 1)
	local bounded = {}
	for index = first, #result do table.insert(bounded, result[index]) end
	return bounded
end

function Controls.Sparkline(section: any, o: any): any
	assert(type(o) == "table", "Sparkline requires options")
	local requestedMaxSamples = tonumber(o.MaxSamples) or 120
	local requestedMaxPending = tonumber(o.MaxPending) or requestedMaxSamples
	local height = math.floor(tonumber(o.Height) or 112)
	assert(finite(requestedMaxSamples) and requestedMaxSamples >= 2, "Sparkline MaxSamples must be at least 2")
	assert(finite(requestedMaxPending) and requestedMaxPending >= 0, "Sparkline MaxPending must be non-negative")
	local maxSamples = math.min(512, math.floor(requestedMaxSamples))
	local maxPending = math.min(512, math.floor(requestedMaxPending))
	assert(finite(height) and height >= 48, "Sparkline Height must be at least 48")
	assert(o.Width == nil or (finite(o.Width) and o.Width > 0), "Sparkline Width must be positive and finite")
	local fixedMin, fixedMax = o.Min, o.Max
	assert((fixedMin == nil) == (fixedMax == nil), "Sparkline Min and Max must be provided together")
	if fixedMin ~= nil then assert(finite(fixedMin) and finite(fixedMax) and fixedMin < fixedMax, "Sparkline range must be finite and increasing") end
	local thresholds = o.Thresholds or {}
	assert(type(thresholds) == "table" and #thresholds <= 16, "Sparkline Thresholds must contain at most 16 entries")
	local function normalizeThresholds(source: any): { any }
		assert(type(source) == "table" and #source <= 16, "Sparkline Thresholds must contain at most 16 entries")
		local result = {}
		for index, entry in ipairs(source) do
			local value = if type(entry) == "table" then entry.Value else entry
			assert(finite(value), "Sparkline threshold " .. tostring(index) .. " must be finite")
			if type(entry) == "table" then assert(entry.Label == nil or type(entry.Label) == "string", "Sparkline threshold Label must be a string") end
			table.insert(result, { Value = value, Label = if type(entry) == "table" then entry.Label else nil, Color = if type(entry) == "table" then entry.Color else nil })
		end
		return result
	end
	local initialSamples, initialThresholds = sparklineSamples(o.Samples or o.Default or {}, maxSamples), normalizeThresholds(thresholds)
	local h = static(section, o, height)
	h.Id = id(section, o, "Sparkline")
	h.MaxSamples, h.MaxPending = maxSamples, maxPending
	h._samples, h._pending, h._thresholds = initialSamples, {}, initialThresholds
	h._paused, h._fixedMin, h._fixedMax = false, fixedMin, fixedMax
	h.Root.Name = "Sparkline"
	h.Root:SetAttribute("SparklineMaxSamples", maxSamples)
	local title = Factory.text(h.Root, tostring(o.Title or o.Name or "Sparkline"), h._context.Theme.typography.caption * h._context.Theme.textScale, h._context.Theme.colors.text, { Size = UDim2.new(0.55, 0, 0, 18) })
	local statsLabel = Factory.text(h.Root, "", h._context.Theme.typography.caption * h._context.Theme.textScale, h._context.Theme.colors.textMuted, { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 0), Size = UDim2.new(0.45, 0, 0, 18), TextXAlignment = Enum.TextXAlignment.Right })
	local plot = Factory.make("Frame", { Name = "Plot", BackgroundColor3 = h._context.Theme.colors.surfaceRaised, BorderSizePixel = 0, Position = UDim2.fromOffset(0, 22), Size = UDim2.new(1, 0, 1, -26), ClipsDescendants = true }, h.Root) :: Frame
	Factory.corner(plot, h._context.Theme.radius.sm)
	local fill = Factory.make("Frame", { Name = "Fill", BackgroundColor3 = h._context.Theme.states.selected.background, BackgroundTransparency = 0.86, BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 1), Size = UDim2.fromScale(0, 0), Visible = o.Fill == true }, plot) :: Frame
	local baseline = Factory.make("Frame", { Name = "Baseline", BackgroundColor3 = h._context.Theme.colors.border, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 1), Visible = o.Baseline ~= false }, plot) :: Frame
	local segments, thresholdLines, thresholdLabels, markers = {}, {}, {}, {}
	for index = 1, maxSamples - 1 do
		segments[index] = Factory.make("Frame", { Name = "Segment_" .. tostring(index), AnchorPoint = Vector2.new(0, 0.5), BackgroundColor3 = h._context.Theme.states.selected.background, BorderSizePixel = 0, Visible = false, ZIndex = 2 }, plot) :: Frame
	end
	for index = 1, 16 do
		thresholdLines[index] = Factory.make("Frame", { Name = "Threshold_" .. tostring(index), BackgroundColor3 = h._context.Theme.states.danger.text, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 1), Visible = false }, plot) :: Frame
		thresholdLabels[index] = Factory.text(plot, "", h._context.Theme.typography.caption * h._context.Theme.textScale, h._context.Theme.colors.textMuted, { Name = "ThresholdLabel_" .. tostring(index), BackgroundTransparency = 1, Size = UDim2.fromOffset(100, 14), Visible = false, ZIndex = 3 }) :: TextLabel
	end
	for index = 1, 3 do
		markers[index] = Factory.text(plot, "", h._context.Theme.typography.caption * h._context.Theme.textScale, h._context.Theme.colors.textMuted, { Name = "Marker_" .. tostring(index), BackgroundTransparency = 1, Size = UDim2.fromOffset(100, 14), Visible = false, ZIndex = 3 }) :: TextLabel
	end
	h._segments, h._thresholdLines, h._thresholdLabels, h._markers = segments, thresholdLines, thresholdLabels, markers
	local function range()
		if h._fixedMin ~= nil then return h._fixedMin, h._fixedMax end
		if #h._samples == 0 then return 0, 1 end
		local minimum, maximum = h._samples[1].Value, h._samples[1].Value
		for _, sample in ipairs(h._samples) do minimum, maximum = math.min(minimum, sample.Value), math.max(maximum, sample.Value) end
		if minimum == maximum then minimum, maximum = minimum - 0.5, maximum + 0.5 end
		return minimum, maximum
	end
	local function render()
		if h._destroyed then return end
		local theme, minimum, maximum = h._context.Theme, range()
		local width, plotHeight = math.max(1, plot.AbsoluteSize.X), math.max(1, plot.AbsoluteSize.Y)
		title.TextColor3, title.TextSize = theme.colors.text, theme.typography.caption * theme.textScale
		statsLabel.TextColor3, statsLabel.TextSize = theme.colors.textMuted, theme.typography.caption * theme.textScale
		plot.BackgroundColor3, fill.BackgroundColor3, baseline.BackgroundColor3 = theme.colors.surfaceRaised, theme.states.selected.background, theme.colors.border
		local function y(value: number): number return (1 - Util.clamp((value - minimum) / (maximum - minimum), 0, 1)) * plotHeight end
		baseline.Position = UDim2.fromOffset(0, y(if minimum <= 0 and maximum >= 0 then 0 else minimum))
		for index, segment in ipairs(segments) do
			local a, b = h._samples[index], h._samples[index + 1]
			segment.Visible = a ~= nil and b ~= nil
			if a and b then
				local x1, x2, y1, y2 = (index - 1) * width / math.max(1, #h._samples - 1), index * width / math.max(1, #h._samples - 1), y(a.Value), y(b.Value)
				local dx, dy, length = x2 - x1, y2 - y1, math.sqrt((x2 - x1) ^ 2 + (y2 - y1) ^ 2)
				segment.Position, segment.Size, segment.Rotation = UDim2.fromOffset(x1, y1), UDim2.fromOffset(math.max(1, length), 2), math.deg(math.atan2(dy, dx))
				segment.BackgroundColor3 = theme.states.selected.background
			end
		end
		for index, line in ipairs(thresholdLines) do
			local threshold, thresholdLabel = h._thresholds[index], thresholdLabels[index]
			line.Visible = threshold ~= nil and threshold.Value >= minimum and threshold.Value <= maximum
			thresholdLabel.Visible = line.Visible
			if threshold then
				local color = if typeof(threshold.Color) == "Color3" then threshold.Color else theme.states.danger.text
				line.Position, line.BackgroundColor3 = UDim2.fromOffset(0, y(threshold.Value)), color
				thresholdLabel.Text, thresholdLabel.Position, thresholdLabel.TextColor3, thresholdLabel.TextSize = threshold.Label or string.format("%.3g", threshold.Value), UDim2.fromOffset(2, math.max(0, y(threshold.Value) - 7)), color, theme.typography.caption * theme.textScale
			end
		end
		local stats = h:GetStats()
		statsLabel.Text = if stats.count == 0 then "No samples" else string.format("min %.3g  max %.3g  last %.3g", stats.min, stats.max, stats.latest)
		local markerData = if stats.count == 0 then {} else { { stats.min, "min" }, { stats.max, "max" }, { stats.latest, "last" } }
		for index, marker in ipairs(markers) do
			local entry = markerData[index]
			marker.Visible = entry ~= nil
			if entry then marker.Text, marker.Position, marker.TextColor3 = entry[2] .. " " .. string.format("%.3g", entry[1]), UDim2.fromOffset(math.max(0, width - 100), math.max(0, y(entry[1]) - 7)), theme.colors.textMuted end
		end
		fill.Size = UDim2.fromOffset(width, if #h._samples > 0 then math.max(0, plotHeight - y(h._samples[#h._samples].Value)) else 0)
	end
	function h:SetSamples(source: any)
		local nextSamples = sparklineSamples(source, maxSamples)
		if self._paused then
			self._pending = nextSamples
			while #self._pending > maxPending do table.remove(self._pending, 1) end
		else
			self._samples = nextSamples
			render()
		end
		return self
	end
	function h:GetSamples(): { any }
		local result = {}
		for index, sample in ipairs(self._samples) do result[index] = table.clone(sample) end
		return result
	end
	function h:Append(sample: any)
		local nextSamples = sparklineSamples({ sample }, maxSamples)
		if self._paused then
			if maxPending > 0 then table.insert(self._pending, nextSamples[1]) end
			while #self._pending > maxPending do table.remove(self._pending, 1) end
			return self
		end
		table.insert(self._samples, nextSamples[1])
		while #self._samples > maxSamples do table.remove(self._samples, 1) end
		render()
		return self
	end
	h.Add = h.Append
	function h:Clear() self._samples, self._pending = {}, {}; render(); return self end
	function h:SetRange(minimum: any, maximum: any)
		if type(minimum) == "table" then maximum, minimum = minimum.Max, minimum.Min end
		assert((minimum == nil) == (maximum == nil), "Sparkline Min and Max must be provided together")
		if minimum ~= nil then assert(finite(minimum) and finite(maximum) and minimum < maximum, "Sparkline range must be finite and increasing") end
		self._fixedMin, self._fixedMax = minimum, maximum
		render()
		return self
	end
	function h:GetRange(): any local minimum, maximum = range(); return { Min = minimum, Max = maximum, Auto = self._fixedMin == nil } end
	function h:SetThresholds(source: any) self._thresholds = normalizeThresholds(source); render(); return self end
	function h:GetThresholds(): { any }
		local result = {}
		for index, threshold in ipairs(self._thresholds) do result[index] = table.clone(threshold) end
		return result
	end
	function h:SetPaused(paused: boolean)
		paused = paused == true
		if self._paused and not paused then
			for _, sample in ipairs(self._pending) do table.insert(self._samples, sample) end
			while #self._samples > maxSamples do table.remove(self._samples, 1) end
			self._pending = {}
			render()
		end
		self._paused = paused
		return self
	end
	function h:IsPaused(): boolean return self._paused end
	function h:GetStats(): any
		local count, total, minimum, maximum, latest = #self._samples, 0, nil, nil, nil
		for _, sample in ipairs(self._samples) do total, minimum, maximum, latest = total + sample.Value, if minimum == nil then sample.Value else math.min(minimum, sample.Value), if maximum == nil then sample.Value else math.max(maximum, sample.Value), sample.Value end
		return { count = count, min = minimum, max = maximum, average = if count > 0 then total / count else nil, latest = latest }
	end
	h:GetStats()
	h._maid:GiveTask(plot:GetPropertyChangedSignal("AbsoluteSize"):Connect(render))
	bindTheme(h, render)
	render()
	return h
end

Controls.MiniGraph = Controls.Sparkline
DataControls.install(Controls)
return Controls

end

__modules["components/DataControls"] = function()
--!strict

local TableModel = __require("models/TableModel")

local DataControls = {}

local function ring(capacity: number)
	return { capacity = capacity, values = table.create(capacity), first = 1, count = 0 }
end

local function push(buffer: any, value: any)
	local slot = (buffer.first + buffer.count - 1) % buffer.capacity + 1
	if buffer.count < buffer.capacity then
		buffer.values[slot] = value
		buffer.count += 1
	else
		buffer.values[slot] = value
		buffer.first = buffer.first % buffer.capacity + 1
	end
end

local function snapshot(buffer: any): { any }
	local result = table.create(buffer.count)
	for index = 1, buffer.count do
		result[index] = buffer.values[(buffer.first + index - 2) % buffer.capacity + 1]
	end
	return result
end

function DataControls.install(Controls: any)
	if Controls._dataControlsInstalled then return Controls end
	Controls._dataControlsInstalled = true
	local originalDataGrid = Controls.DataGrid

	Controls.DataGrid = function(section: any, options: any)
		assert(type(options) == "table", "DataGrid requires options")
		local model = TableModel.new(options)
		local gridOptions = table.clone(options)
		gridOptions.Key = function(row: any, _index: number)
			return model:GetRowKey(row)
		end
		gridOptions.Rows = model:GetVisibleRows()
		gridOptions.Items = nil
		gridOptions.LoadImmediately = false
		local grid = originalDataGrid(section, gridOptions)
		grid.Model = model
		grid.Scroller:SetAttribute("VirtualCellLimit", 128 * #gridOptions.Columns)
		local baseSetRows, baseSetSort, baseClearSort, baseSetColumns, baseSetSelected, baseDestroy = grid.SetRows, grid.SetSort, grid.ClearSort, grid.SetColumns, grid.SetSelected, grid.Destroy
		local applying = false
		local function syncSelection(value: any)
			if applying or model._destroyed then return end
			local selected = {}
			if grid:IsMultiSelect() then
				for _, key in ipairs(value) do selected[key] = true end
			elseif value ~= nil then
				selected[value] = true
			end
			local visible = {}
			for _, key in ipairs(model:GetVisibleRowKeys()) do visible[key] = true end
			for _, key in ipairs(model:GetSelected()) do
				if visible[key] and not selected[key] then model:SetSelected(key, false) end
			end
			for key in pairs(selected) do model:SetSelected(key, true) end
		end
		grid._maid:GiveTask(grid._context.Store:Subscribe(grid.Id, syncSelection))
		if options.Selection == nil then syncSelection(grid:Get()) end
		local initialSortId, initialSortDirection = model:GetSort()
		if initialSortId ~= nil and initialSortDirection ~= nil then
			baseSetSort(grid, initialSortId, initialSortDirection)
		end
		local function applyView()
			baseSetRows(grid, model:GetVisibleRows())
			local visibleByKey = {}
			for _, key in ipairs(model:GetVisibleRowKeys()) do
				visibleByKey[key] = true
			end
			local selected = {}
			for _, key in ipairs(model:GetSelected()) do
				if visibleByKey[key] then
					selected[#selected + 1] = key
				end
			end
			if grid:IsMultiSelect() then
				baseSetSelected(grid, selected)
			else
				baseSetSelected(grid, selected[1])
			end
			grid.Scroller:SetAttribute("VirtualCells", grid:GetPoolSize() * #gridOptions.Columns)
			return grid
		end
		local function apply()
			local previous = applying
			applying = true
			local ok, result = pcall(applyView)
			applying = previous
			if not ok then error(result, 2) end
			return grid
		end
		function grid:SetRows(rows: any)
			model:SetRows(rows)
			return apply()
		end
		grid.SetItems = grid.SetRows
		function grid:SetColumns(columns: any)
			local staged = TableModel.new({
				Rows = model:GetRows(),
				Columns = columns,
				RowKey = model._rowKey,
				MultiSelect = model._multiSelect,
				PageSize = model._pageSize,
			})
			staged._query, staged._filter = model._query, model._filter
			staged._sortId, staged._sortDirection = model._sortId, model._sortDirection
			staged._page, staged._pageSize = model._page, model._pageSize
			local stagedOk, stagedError = pcall(staged._rebuild, staged)
			staged:Destroy()
			if not stagedOk then error(stagedError, 2) end

			local previousModelColumns, previousBaseColumns = gridOptions.Columns, grid:GetColumns()
			local baseOk, baseError = pcall(baseSetColumns, grid, columns)
			if not baseOk then
				pcall(baseSetColumns, grid, previousBaseColumns)
				error(baseError, 2)
			end
			local modelOk, modelError = pcall(model.SetColumns, model, columns)
			if not modelOk then
				pcall(baseSetColumns, grid, previousBaseColumns)
				pcall(model.SetColumns, model, previousModelColumns)
				error(modelError, 2)
			end
			gridOptions.Columns = columns
			grid.Scroller:SetAttribute("VirtualCellLimit", 128 * #columns)
			local applied, applyError = pcall(apply)
			if not applied then
				gridOptions.Columns = previousModelColumns
				pcall(model.SetColumns, model, previousModelColumns)
				pcall(baseSetColumns, grid, previousBaseColumns)
				pcall(apply)
				error(applyError, 2)
			end
			return grid
		end
		function grid:SetQuery(query: any) model:SetQuery(query) return apply() end
		function grid:SetFilter(filter: any) model:SetFilter(filter) return apply() end
		function grid:SetPagination(page: any, pageSize: any?) model:SetPagination(page, pageSize) return apply() end
		function grid:GetPagination() return model:GetPagination() end
		function grid:SetGroupBy(columnId: any) model:SetGroupBy(columnId) return apply() end
		function grid:GetGroups() return model:GetGroups() end
		function grid:SetRowSelected(key: any, selected: boolean?)
			model:SetSelected(key, selected)
			return apply()
		end
		function grid:GetSelectedRowKeys() return model:GetSelected() end
		function grid:SetSort(columnId: string, direction: string?)
			model:SetSort(columnId, direction)
			baseSetSort(grid, columnId, direction)
			return apply()
		end
		function grid:GetSort() return model:GetSort() end
		function grid:ClearSort()
			model:SetSort(nil, nil)
			baseClearSort(grid)
			return apply()
		end
		function grid:EditCell(key: any, columnId: any, value: any): boolean
			local edited = model:Edit(key, columnId, value)
			if edited then apply() end
			return edited
		end
		function grid:RefreshRemote(provider: any)
			return model:Refresh(function(generation: number)
				local rows = provider(generation)
				task.defer(function()
					if not model._destroyed and model._generation == generation then apply() end
				end)
				return rows
			end)
		end
		function grid:CancelRemote() model:CancelRemote() return self end
		function grid:Destroy()
			model:Destroy()
			return baseDestroy(self)
		end
		apply()
		if type(options.Provider) == "function" and options.LoadImmediately ~= false then grid:Refresh() end
		return grid
	end

	function Controls.Chart(section: any, options: any)
		assert(type(options) == "table", "Chart requires options")
		local requestedSamples = tonumber(options.MaxSamples) or 256
		assert(requestedSamples == requestedSamples and requestedSamples ~= math.huge and requestedSamples ~= -math.huge, "Chart MaxSamples must be finite")
		local maxSamples = math.max(2, math.min(512, math.floor(requestedSamples)))
		local maxSeries = math.max(1, math.min(16, math.floor(tonumber(options.MaxSeries) or 16)))
		local kind = options.Kind or "line"
		assert(kind == "line" or kind == "area" or kind == "bar", "Chart Kind must be line, area, or bar")
		assert((options.Min == nil) == (options.Max == nil), "Chart Min and Max must be provided together")
		if options.Min ~= nil then
			assert(type(options.Min) == "number" and type(options.Max) == "number" and options.Min < options.Max, "Chart range must increase")
		end
		local function sampleValue(sample: any): number
			local value = if type(sample) == "table" then sample.Value else sample
			assert(type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge, "Chart samples must be finite")
			return value
		end
		local series, seriesById = {}, {}
		for index, descriptor in ipairs(options.Series or {}) do
			assert(index <= maxSeries, "Chart Series exceeds MaxSeries")
			local id = tostring(descriptor.Id or descriptor.Name or index)
			assert(seriesById[id] == nil, "Duplicate Chart series: " .. id)
			local buffer = ring(maxSamples)
			for _, sample in ipairs(descriptor.Samples or {}) do sampleValue(sample); push(buffer, sample) end
			local entry = { Id = id, Buffer = buffer, Color = descriptor.Color }
			series[index], seriesById[id] = entry, entry
		end
		if #series == 0 then
			local entry = { Id = "default", Buffer = ring(maxSamples), Color = nil }
			series[1], seriesById.default = entry, entry
		end
		local first = series[1]
		local sparkOptions = table.clone(options)
		sparkOptions.Samples, sparkOptions.MaxSamples, sparkOptions.Fill = snapshot(first.Buffer), maxSamples, false
		local chart = Controls.Sparkline(section, sparkOptions)
		chart.Root.Name = "Chart"
		chart.Root:SetAttribute("ChartKind", kind)
		chart.Root:SetAttribute("ChartSeriesLimit", maxSamples)
		chart.Root:SetAttribute("ChartGeometryLimit", #series * (maxSamples - 1))
		chart._series = series
		local plot = chart.Root:FindFirstChild("Plot") :: Frame
		for seriesIndex, entry in ipairs(series) do
			entry.Segments, entry.Fills, entry.Bars = table.create(maxSamples - 1), table.create(maxSamples - 1), table.create(maxSamples)
			for sampleIndex = 1, maxSamples - 1 do
				local segment = Instance.new("Frame")
				segment.Name = "Series_" .. tostring(seriesIndex) .. "_Segment_" .. tostring(sampleIndex)
				segment.AnchorPoint, segment.BorderSizePixel, segment.Visible, segment.ZIndex = Vector2.new(0, 0.5), 0, false, 4 + seriesIndex
				segment.Parent = plot
				entry.Segments[sampleIndex] = segment
				local fill = Instance.new("Frame")
				fill.Name = "Series_" .. tostring(seriesIndex) .. "_Area_" .. tostring(sampleIndex)
				fill.AnchorPoint, fill.BorderSizePixel, fill.Visible, fill.ZIndex = Vector2.new(0, 1), 0, false, 3 + seriesIndex
				fill.Parent = plot
				entry.Fills[sampleIndex] = fill
			end
			for sampleIndex = 1, maxSamples do
				local bar = Instance.new("Frame")
				bar.Name = "Series_" .. tostring(seriesIndex) .. "_Bar_" .. tostring(sampleIndex)
				bar.AnchorPoint, bar.BorderSizePixel, bar.Visible, bar.ZIndex = Vector2.new(0.5, 1), 0, false, 3 + seriesIndex
				bar.Parent = plot
				entry.Bars[sampleIndex] = bar
			end
		end
		local pending = false
		local function render()
			pending = false
			if chart._destroyed then return end
			local minimum, maximum = options.Min, options.Max
			local autoRange = minimum == nil
			local samplesBySeries = table.create(#series)
			local barSlotCount = 0
			for seriesIndex, entry in ipairs(series) do
				local samples = snapshot(entry.Buffer)
				samplesBySeries[seriesIndex] = samples
				barSlotCount = math.max(barSlotCount, #samples)
				if autoRange then
					for _, sample in ipairs(samples) do
						local value = sampleValue(sample)
						minimum = if minimum == nil then value else math.min(minimum, value)
						maximum = if maximum == nil then value else math.max(maximum, value)
					end
				end
			end
			if minimum == nil then minimum, maximum = 0, 1 end
			if minimum == maximum then minimum, maximum = minimum - 0.5, maximum + 0.5 end
			chart._fixedMin, chart._fixedMax = minimum, maximum
			chart:SetSamples(samplesBySeries[1])
			for _, segment in ipairs(chart._segments) do segment.Visible = false end
			local width, height = math.max(1, plot.AbsoluteSize.X), math.max(1, plot.AbsoluteSize.Y)
			local baseline = (1 - math.clamp((0 - minimum) / (maximum - minimum), 0, 1)) * height
			local function y(value: number): number
				return (1 - math.clamp((value - minimum) / (maximum - minimum), 0, 1)) * height
			end
			for seriesIndex, entry in ipairs(series) do
				local samples, color = samplesBySeries[seriesIndex], if typeof(entry.Color) == "Color3" then entry.Color else chart._context.Theme.states.selected.background
				for sampleIndex = 1, maxSamples - 1 do
					local segment, fill = entry.Segments[sampleIndex], entry.Fills[sampleIndex]
					local a, b = samples[sampleIndex], samples[sampleIndex + 1]
					segment.Visible, fill.Visible = kind ~= "bar" and a ~= nil and b ~= nil, kind == "area" and a ~= nil and b ~= nil
					if a and b then
						local x1, x2, y1, y2 = (sampleIndex - 1) * width / math.max(1, #samples - 1), sampleIndex * width / math.max(1, #samples - 1), y(sampleValue(a)), y(sampleValue(b))
						local dx, dy = x2 - x1, y2 - y1
						segment.Position, segment.Size, segment.Rotation, segment.BackgroundColor3 = UDim2.fromOffset(x1, y1), UDim2.fromOffset(math.max(1, math.sqrt(dx ^ 2 + dy ^ 2)), 2), math.deg(math.atan2(dy, dx)), color
						fill.Position, fill.Size, fill.BackgroundColor3, fill.BackgroundTransparency = UDim2.fromOffset(x1, baseline), UDim2.fromOffset(math.max(1, x2 - x1), math.max(0, baseline - (y1 + y2) / 2)), color, 0.82
					end
				end
				for sampleIndex, bar in ipairs(entry.Bars) do
					local sample = samples[sampleIndex]
					bar.Visible = kind == "bar" and sample ~= nil
					if sample then
						local top = y(sampleValue(sample))
						local slotWidth = width / math.max(1, barSlotCount)
						local groupWidth = slotWidth / #series
						local x = (sampleIndex - 1) * slotWidth + (seriesIndex - 0.5) * groupWidth
						bar.Position, bar.Size, bar.BackgroundColor3 = UDim2.fromOffset(x, baseline), UDim2.fromOffset(math.max(1, groupWidth - 2), math.max(1, math.abs(baseline - top))), color
						if top > baseline then bar.AnchorPoint, bar.Position = Vector2.new(0.5, 0), UDim2.fromOffset(x, baseline) else bar.AnchorPoint = Vector2.new(0.5, 1) end
					end
				end
			end
		end
		chart._maid:GiveTask(plot:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			if not pending then pending = true task.defer(render) end
		end))
		if chart._context.ThemeChanged then
			chart._maid:GiveTask(chart._context.ThemeChanged:Connect(render))
		end
		function chart:Append(sample: any, seriesId: any)
			sampleValue(sample)
			local entry = seriesById[tostring(seriesId or first.Id)]
			assert(entry ~= nil, "Unknown Chart series: " .. tostring(seriesId))
			push(entry.Buffer, sample)
			if not pending then pending = true task.defer(render) end
			return self
		end
		chart.Add = chart.Append
		function chart:SetSeriesSamples(seriesId: any, samples: any)
			assert(type(samples) == "table", "Chart samples must be an array")
			local entry = seriesById[tostring(seriesId or first.Id)]
			assert(entry ~= nil, "Unknown Chart series: " .. tostring(seriesId))
			local buffer = ring(maxSamples)
			for _, sample in ipairs(samples) do sampleValue(sample); push(buffer, sample) end
			entry.Buffer = buffer
			render()
			return self
		end
		function chart:GetSeriesSamples(seriesId: any): { any }
			local entry = seriesById[tostring(seriesId or first.Id)]
			assert(entry ~= nil, "Unknown Chart series")
			return snapshot(entry.Buffer)
		end
		function chart:GetSeriesCount(): number return #series end
		render()
		return chart
	end
	return Controls
end

return DataControls

end

__modules["components/ModernControls"] = function()
--!strict

local AsyncProvider = __require("core/AsyncProvider")
local Store = __require("core/Store")
local StructuredError = __require("core/StructuredError")
local Controls = __require("components/Controls")
local Signal = __require("core/Signal")

local ModernControls = {}

-- These are deliberately declarative: ControlHost owns the mounted lifecycle while
-- Store/InputRouter/EditSession remain the sole sources of mutable control state.
local KINDS = table.freeze({
	NumberInput = true, TextInput = true, TextArea = true, PasswordInput = true,
	SearchInput = true, DatePicker = true, TimePicker = true, DateRangePicker = true,
	Combobox = true, ListBox = true, Toggle = true, Radio = true, Segmented = true,
	Slider = true, ColorPicker = true, Keybind = true, FormActions = true,
	DataGrid = true, Chart = true, CodeEditor = true, KeyValueEditor = true,
	VectorEditor = true, GradientEditor = true, Button = true, Stat = true,
})

local EDITOR_KINDS = table.freeze({
	CodeEditor = true, KeyValueEditor = true, VectorEditor = true, GradientEditor = true,
})

local INPUT_KINDS = table.freeze({
	NumberInput = true, TextInput = true, TextArea = true, PasswordInput = true,
	SearchInput = true, DatePicker = true, TimePicker = true, DateRangePicker = true,
	Combobox = true, ListBox = true, Toggle = true, Radio = true, Segmented = true,
	Slider = true, ColorPicker = true, Keybind = true,
})

local function fail(code: string, message: string, operation: string): any
	return StructuredError.from(code, message, { domain = "modernControls", operation = operation })
end

local function dateRangeValue(value: any): boolean
	return type(value) == "table" and type(rawget(value, "start")) == "string" and type(rawget(value, "end")) == "string"
end

local function displayValue(value: any): string
	if dateRangeValue(value) then return value.start .. " - " .. value["end"] end
	return tostring(value or "")
end

local function stateOf(descriptor: any): any
	return if type(descriptor.state) == "table" then descriptor.state else {}
end

local function defaultFor(descriptor: any): any
	local state = stateOf(descriptor)
	if state.value ~= nil then return state.value end
	if state.default ~= nil then return state.default end
	if descriptor.default ~= nil then return descriptor.default end
	if descriptor.kind == "Stat" then return descriptor.value end
	if descriptor.kind == "DateRangePicker" then
		return { start = descriptor.start or "", ["end"] = descriptor["end"] or "" }
	end
	if descriptor.kind == "Toggle" then return false end
	if descriptor.kind == "ListBox" or descriptor.kind == "Combobox" then return {} end
	if descriptor.kind == "Radio" or descriptor.kind == "Segmented" then return descriptor.value or (descriptor.items and descriptor.items[1]) or "" end
	return ""
end

local function validator(kind: string, descriptor: any): (any) -> (boolean, string?)
	if kind == "NumberInput" or kind == "Slider" then return Store.Validators.number(descriptor.min, descriptor.max) end
	if kind == "Toggle" then return Store.Validators.boolean end
	if kind == "DateRangePicker" then
		return function(value: any): (boolean, string?)
			return dateRangeValue(value), "date range must contain string start and end values"
		end
	end
	if kind == "Keybind" then
		return function(value: any): (boolean, string?)
			local mode = if type(value) == "table" then value.mode else descriptor.mode
			if mode ~= "Toggle" and mode ~= "Hold" and mode ~= "Always" then
				return false, "keybind mode must be Toggle, Hold, or Always"
			end
			local key = if type(value) == "table" then value.keyCode else value
			return Store.Validators.keybind(key)
		end
	end
	return function(_value: any): (boolean, string?) return true, nil end
end

local function normalize(kind: string, descriptor: any): (any) -> any
	if kind == "Keybind" then
		return function(value: any): any
			local source = if type(value) == "table" then value else { keyCode = value }
			return { keyCode = source.keyCode or Enum.KeyCode.Unknown, mode = source.mode or descriptor.mode or "Toggle" }
		end
	end
	if kind == "DateRangePicker" then
		return function(value: any): any
			return { start = value.start, ["end"] = value["end"] }
		end
	end
	if kind == "ListBox" then
		return function(value: any): any
			if type(value) == "table" then return value end
			return { value }
		end
	end
	return function(value: any): any return value end
end

local function accessibilityOf(descriptor: any): any
	local a = if type(descriptor.accessibility) == "table" then descriptor.accessibility else {}
	return table.freeze({
		label = a.label or descriptor.title or descriptor.id,
		description = a.description or descriptor.description,
		role = a.role or string.lower(descriptor.kind),
		readOnly = a.readOnly == true or descriptor.readOnly == true,
		disabled = a.disabled == true or descriptor.disabled == true,
	})
end

local function attributeCompatible(value: any): boolean
	local kind = typeof(value)
	return value == nil or kind == "boolean" or kind == "number" or kind == "string"
		or kind == "UDim" or kind == "UDim2" or kind == "BrickColor" or kind == "Color3"
		or kind == "Vector2" or kind == "Vector3" or kind == "CFrame"
end

local function copyComposition(value: any): any
	local copy = {}
	for key, entry in pairs(value) do copy[key] = entry end
	return copy
end

local function composition(descriptor: any, valueId: string): any
	local localization = if type(descriptor.localization) == "table" then descriptor.localization else {}
	local value = table.freeze({ storeId = valueId, readOnly = accessibilityOf(descriptor).readOnly, disabled = accessibilityOf(descriptor).disabled })
	return table.freeze({
		kind = descriptor.kind,
		id = descriptor.id,
		title = localization.title or descriptor.title,
		description = localization.description or descriptor.description,
		accessibility = accessibilityOf(descriptor),
		value = value,
		preset = if descriptor.kind == "ListBox" then (descriptor.preset or "ListBox") else nil,
		items = descriptor.items,
	})
end


local function localized(descriptor: any, services: any, field: string): any
	local localization = descriptor.localization
	local fallback = descriptor[field]
	if type(localization) ~= "table" then return fallback end
	local key = localization[field .. "Key"] or localization[field]
	if type(key) ~= "string" then return fallback end
	local service = services.Localization
	if service ~= nil and type(service.HasTranslation) == "function" and service:HasTranslation(key) then
		return service:Translate(key, { Default = fallback })
	end
	return key
end

local function applyDirection(gui: any, direction: string)
	if gui == nil then return end
	gui:SetAttribute("Direction", direction)
	gui:SetAttribute("LayoutDirection", direction)
	if gui:IsA("TextBox") or gui:IsA("TextButton") or gui:IsA("TextLabel") then
		gui.TextXAlignment = if direction == "RTL" then Enum.TextXAlignment.Right else Enum.TextXAlignment.Left
	end
end

local function applyDirectionTree(root: any, direction: string)
	if root == nil then return end
	applyDirection(root, direction)
	for _, descendant in ipairs(root:GetDescendants()) do
		applyDirection(descendant, direction)
	end
end

local function actionSpec(value: any, name: string): any
	if type(value) ~= "table" then return nil end
	if value.kind == name or value.type == name then return value end
	local action = value[name]
	if action == nil and #value > 0 then
		for _, candidate in ipairs(value) do
			if type(candidate) == "table" and (candidate.kind == name or candidate.type == name) then return candidate end
		end
	end
	return action
end

local function dispatch(descriptor: any, services: any, name: string): (boolean, any?)
	local actions = descriptor.actions
	if name ~= nil and type(actions) == "table" and actions[name] ~= nil then actions = actions[name] end
	local command = actionSpec(actions, "command")
	if command == nil and type(actions) == "table" and actions.commandId ~= nil then command = actions end
	if command ~= nil then
		local id = if type(command) == "table" then command.commandId or command.id or command.command else command
		local args = if type(command) == "table" then command.args else nil
		if type(id) ~= "string" or services.Commands == nil then return false, fail("command_unavailable", "Portable command action is unavailable", "dispatch") end
		return services.Commands:Execute(id, args)
	end
	local navigation = actionSpec(actions, "navigate") or actionSpec(actions, "navigation")
	if navigation == nil and type(actions) == "table" and actions.routeId ~= nil then navigation = actions end
	if navigation ~= nil then
		local route = if type(navigation) == "table" then navigation.routeId or navigation.route or navigation.id else navigation
		local params = if type(navigation) == "table" then navigation.params else nil
		if type(route) ~= "string" or services.Navigation == nil then return false, fail("navigation_unavailable", "Portable navigation action is unavailable", "dispatch") end
		local navigate = if type(navigation) == "table" and navigation.mode == "replace" then services.Navigation.Replace else services.Navigation.Navigate
		if type(navigate) ~= "function" then return false, fail("navigation_unavailable", "Portable navigation action is unavailable", "dispatch") end
		local snapshot, routeError = navigate(services.Navigation, route, params, "modern-control:" .. descriptor.id)
		return snapshot ~= nil, routeError
	end
	local trusted = actionSpec(actions, "trusted")
	if trusted ~= nil then
		local id = if type(trusted) == "table" then trusted.id or trusted.action else trusted
		local args = if type(trusted) == "table" then trusted.args else nil
		if type(id) ~= "string" or services.TrustedActions == nil then return false, fail("trusted_action_unavailable", "Trusted action is unavailable", "dispatch") end
		return services.TrustedActions:Execute(id, args, descriptor)
	end
	return true, nil
end

local function legacyColumn(column: any): any
	if type(column) ~= "table" then return column end
	local normalized = table.clone(column)
	normalized.Id = column.id or column.Id
	normalized.Title = column.title or column.Title
	normalized.Name = column.name or column.Name
	normalized.Key = column.key or column.Key
	normalized.Field = column.field or column.Field
	normalized.Value = column.value or column.Value
	normalized.Compare = column.compare or column.Compare
	normalized.Width = column.width or column.Width
	return normalized
end

local function legacySample(sample: any): any
	if type(sample) ~= "table" then return sample end
	local normalized = table.clone(sample)
	normalized.Value = sample.value or sample.Value
	return normalized
end

local function legacySeries(series: any): any
	if type(series) ~= "table" then return series end
	local normalized = table.clone(series)
	normalized.Id = series.id or series.Id
	normalized.Name = series.name or series.Name
	normalized.Color = series.color or series.Color
	if type(series.samples) == "table" then
		normalized.Samples = table.create(#series.samples)
		for index, sample in ipairs(series.samples) do normalized.Samples[index] = legacySample(sample) end
	elseif type(series.Samples) == "table" then
		normalized.Samples = table.create(#series.Samples)
		for index, sample in ipairs(series.Samples) do normalized.Samples[index] = legacySample(sample) end
	end
	return normalized
end

local function dataOptions(descriptor: any): any
	if descriptor.kind == "DataGrid" then
		local columns = if type(descriptor.columns) == "table" then table.create(#descriptor.columns) else descriptor.columns
		if type(columns) == "table" then
			for index, column in ipairs(descriptor.columns) do columns[index] = legacyColumn(column) end
		end
		return {
			Id = descriptor.id, Title = descriptor.title, Rows = descriptor.rows or {}, Columns = columns,
			MultiSelect = descriptor.multiSelect, Query = descriptor.query, Sort = descriptor.sort,
			Page = descriptor.page, PageSize = descriptor.pageSize, GroupBy = descriptor.groupBy,
			Selection = descriptor.selection,
		}
	end
	local series = if type(descriptor.series) == "table" then table.create(#descriptor.series) else descriptor.series
	if type(series) == "table" then
		for index, entry in ipairs(descriptor.series) do series[index] = legacySeries(entry) end
	end
	return {
		Id = descriptor.id, Title = descriptor.title, Series = series, Kind = descriptor.chartKind,
		MaxSamples = descriptor.maxSamples, MaxSeries = descriptor.maxSeries, Min = descriptor.min, Max = descriptor.max,
		Thresholds = descriptor.thresholds, Height = descriptor.height, Width = descriptor.width,
	}
end
local function renderGuiObject(descriptor: any, stage: any, actual: any): any?
	local target = stage.target
	if typeof(target) ~= "Instance" or not target:IsA("GuiObject") then return nil end
	local textEntry = descriptor.kind == "NumberInput" or descriptor.kind == "TextInput" or descriptor.kind == "TextArea"
		or descriptor.kind == "PasswordInput" or descriptor.kind == "SearchInput" or descriptor.kind == "DatePicker"
		or descriptor.kind == "TimePicker" or descriptor.kind == "DateRangePicker" or EDITOR_KINDS[descriptor.kind]
	local action = not textEntry
	local className = if textEntry then "TextBox" elseif action then "TextButton" else "Frame"
	local control = Instance.new(className)
	control.Name = "PotassiumControl_" .. descriptor.id
	control.BackgroundTransparency = if className == "Frame" then 0.15 else 0
	control.BackgroundColor3 = Color3.fromRGB(37, 42, 52)
	control.BorderSizePixel = 0
	control.Size = UDim2.new(1, 0, 0, if descriptor.kind == "TextArea" then 96 else 32)
	control.LayoutOrder = stage.generation
	control.Active = true
	if control:IsA("TextBox") then
		control.ClearTextOnFocus = false
		control.MultiLine = descriptor.kind == "TextArea" or EDITOR_KINDS[descriptor.kind] ~= nil
		control.PlaceholderText = descriptor.placeholder or descriptor.title or descriptor.kind
		control.Text = ""
		control.TextColor3 = Color3.fromRGB(240, 240, 245)
		control.TextXAlignment = Enum.TextXAlignment.Left
	elseif control:IsA("TextButton") then
		control.Text = descriptor.title or descriptor.kind
		control.TextColor3 = Color3.fromRGB(240, 240, 245)
	else
		local label = Instance.new("TextLabel")
		label.Name = "Label"
		label.BackgroundTransparency = 1
		label.Size = UDim2.fromScale(1, 1)
		label.Text = descriptor.title or descriptor.kind
		label.TextColor3 = Color3.fromRGB(240, 240, 245)
		label.TextXAlignment = Enum.TextXAlignment.Left
		label.Parent = control
		actual.label = label
		actual.instances += 1
	end
	control.Parent = target
	stage.maid:GiveTask(control)
	actual.instances += 1
	actual.guiObject = control
	return control
end

local function renderDataControl(descriptor: any, services: any, stage: any, actual: any): any?
	if descriptor.kind ~= "DataGrid" and descriptor.kind ~= "Chart" then return nil end
	local controls, context = services.DataControls, services.Context
	if controls == nil or context == nil or typeof(stage.target) ~= "Instance" then return nil end
	local order = 0
	local section = {
		_context = context,
		_content = stage.target,
		_nextOrder = function()
			order += 1
			return stage.generation * 1000 + order
		end,
		_fullId = function(_: any, localId: string)
			return localId
		end,
		_controls = {},
		_registerControl = function(self: any, handle: any)
			table.insert(self._controls, handle)
			return handle
		end,
		_focus = function()
			return nil
		end,
	}
	local control = if descriptor.kind == "DataGrid" then controls.DataGrid(section, dataOptions(descriptor)) else controls.Chart(section, dataOptions(descriptor))
	stage.maid:GiveTask(control)
	actual.guiObject, actual.dataControl = control.Root, control
	actual.instances += 1 + #control.Root:GetDescendants()
	if descriptor.kind == "DataGrid" then
		if descriptor.query ~= nil then control:SetQuery(descriptor.query) end
		if descriptor.sort ~= nil then control:SetSort(descriptor.sort.columnId or descriptor.sort.id, descriptor.sort.direction) end
		if descriptor.page ~= nil or descriptor.pageSize ~= nil then control:SetPagination(descriptor.page or 1, descriptor.pageSize) end
		if descriptor.groupBy ~= nil then control:SetGroupBy(descriptor.groupBy) end
		if descriptor.selection ~= nil then
			for _, key in ipairs(descriptor.selection) do control:SetRowSelected(key, true) end
		end
	end
	return control
end

local function bindKeybind(descriptor: any, services: any, maid: any, valueId: string, actual: any?)
	local router = services.InputRouter
	if descriptor.kind ~= "Keybind" or router == nil then return end
	local activationId = "modern-control-" .. valueId
	local held = false
	local toggled = false
	local registeredKey: any = nil
	local holdCancel: (() -> ())? = nil
	local function visibility(): string
		local object = if actual then actual.guiObject else nil
		local ancestor: Instance? = if typeof(object) == "Instance" then object else nil
		while ancestor do
			if ancestor:IsA("GuiObject") and not ancestor.Visible then return "hidden" end
			if ancestor:IsA("LayerCollector") and not ancestor.Enabled then return "hidden" end
			ancestor = ancestor.Parent
		end
		return "shown"
	end
	local function eligibility(): any
		local accessible = accessibilityOf(descriptor)
		return {
			disabled = accessible.disabled,
			readOnly = accessible.readOnly,
			visibility = visibility(),
			allowWhileTextEntry = false,
		}
	end
	local function releaseHold()
		if holdCancel then
			holdCancel()
			holdCancel = nil
		end
		if held then
			held = false
			local value = services.Store:Get(valueId)
			if type(value) == "table" and type(descriptor.onActivation) == "function" then
				pcall(descriptor.onActivation, false, value)
			end
		end
	end
	local function activate(isEnding: boolean?)
		local accessible = accessibilityOf(descriptor)
		if accessible.disabled or accessible.readOnly or visibility() ~= "shown" then return false end
		local value = services.Store:Get(valueId)
		if type(value) ~= "table" then return false end
		local mode = value.mode
		if mode == "Toggle" and not isEnding then toggled = not toggled end
		if mode == "Hold" then
			if isEnding then
				releaseHold()
				return true
			end
			local threshold = tonumber(descriptor.holdThreshold) or 0
			if threshold > 0 then
				holdCancel = router:ScheduleHold(activationId, threshold, function()
					holdCancel = nil
					local allowed = router:CanInteract(eligibility())
					if not allowed then return end
					held = true
					if type(descriptor.onActivation) == "function" then descriptor.onActivation(true, value) end
					if services.Haptics then services.Haptics:Play("confirm", function() return router:CanInteract(eligibility()) end) end
				end, eligibility())
				return true
			end
			held = true
		end
		local active = mode == "Always" or toggled or held
		if type(descriptor.onActivation) == "function" then descriptor.onActivation(active, value) end
		if active and services.Haptics then services.Haptics:Play("confirm", function() return router:CanInteract(eligibility()) end) end
		return true
	end
	local function register()
		releaseHold()
		if registeredKey ~= nil then router:UnregisterShortcut(activationId); registeredKey = nil end
		local value = services.Store:Get(valueId)
		local key = if type(value) == "table" then value.keyCode else nil
		if visibility() == "shown" and typeof(key) == "EnumItem" and key ~= Enum.KeyCode.Unknown then
			registeredKey = key
			router:RegisterShortcut(activationId, {
				keys = { key },
				allowWhileTextEntry = false,
				eligibility = eligibility(),
				onEnded = function(input: InputObject)
					if input.KeyCode == registeredKey then activate(true) end
				end,
			}, function() return activate(false) end)
		end
	end
	register()
	maid:GiveTask(services.Store:Subscribe(valueId, function() register() end))

	local watched = {}
	local ancestor: Instance? = if actual and typeof(actual.guiObject) == "Instance" then actual.guiObject else nil
	while ancestor do
		if ancestor:IsA("GuiObject") then
			table.insert(watched, ancestor:GetPropertyChangedSignal("Visible"):Connect(register))
		elseif ancestor:IsA("LayerCollector") then
			table.insert(watched, ancestor:GetPropertyChangedSignal("Enabled"):Connect(register))
		end
		ancestor = ancestor.Parent
	end
	for _, connection in ipairs(watched) do maid:GiveTask(connection) end
	maid:GiveTask(function()
		releaseHold()
		router:UnregisterShortcut(activationId)
	end)
	if actual then actual.connections += 2 + #watched end
end

local function bindCapture(descriptor: any, services: any, maid: any, valueId: string, actual: any)
	if descriptor.kind ~= "Keybind" or services.InputRouter == nil then return end
	local captureRelease: (() -> ())? = nil
	local function stopCapture()
		if actual.capturing ~= true then return end
		actual.capturing = false
		local release = captureRelease
		captureRelease = nil
		if release then release() end
	end
	actual.capture = function(): boolean
		if accessibilityOf(descriptor).disabled or accessibilityOf(descriptor).readOnly then return false end
		stopCapture()
		actual.capturing = true
		captureRelease = services.InputRouter:BeginCapture(actual, function(input: InputObject)
			if input.KeyCode == Enum.KeyCode.Delete or input.KeyCode == Enum.KeyCode.Backspace then
				stopCapture()
				local value = services.Store:Get(valueId)
				services.Store:Set(valueId, { keyCode = Enum.KeyCode.Unknown, mode = if type(value) == "table" then value.mode else descriptor.mode or "Toggle" }, "user")
				return true
			end
			local key = input.KeyCode
			if key == Enum.KeyCode.Unknown and input.UserInputType == Enum.UserInputType.Touch then key = Enum.KeyCode.ButtonA end
			if key ~= Enum.KeyCode.Unknown then
				stopCapture()
				local value = services.Store:Get(valueId)
				services.Store:Set(valueId, { keyCode = key, mode = if type(value) == "table" then value.mode else descriptor.mode or "Toggle" }, "user")
			end
			return true
		end, function()
			actual.capturing = false
			captureRelease = nil
		end)
		return true
	end
	maid:GiveTask(stopCapture)
end
local function attachFocusContract(result: any, actual: any, services: any, stage: any, delegate: any)
	if delegate ~= nil and type(delegate.Focus) == "function" and type(delegate.ObserveFocusChanged) == "function" then
		function result:Focus(reason: string?): boolean
			return delegate:Focus(reason)
		end
		function result:ObserveFocusChanged(callback: (focused: boolean, reason: string) -> ())
			return delegate:ObserveFocusChanged(callback)
		end
		return
	end

	local object = actual.guiObject
	local manager = services.Context and services.Context.FocusManager
	if object == nil or manager == nil or type(manager.Register) ~= "function" or type(manager.SetFocused) ~= "function" then
		return
	end
	local changed = Signal.new()
	local focused = false
	local function publish(nextFocused: boolean, reason: string)
		if focused == nextFocused then return end
		focused = nextFocused
		changed:Fire(nextFocused, reason)
	end
	local focusId = "modern-control:" .. tostring(stage.generation) .. ":" .. tostring(result.composition.id)
	object.Selectable = true
	manager:Register(focusId, object, {
		order = stage.generation,
		onFocusChanged = publish,
	})
	stage.maid:GiveTask(changed)
	stage.maid:GiveTask(function()
		manager:Unregister(focusId)
	end)
	function result:Focus(reason: string?): boolean
		return manager:SetFocused(object, reason or "control")
	end
	function result:ObserveFocusChanged(callback: (focused: boolean, reason: string) -> ())
		assert(type(callback) == "function", "Focus observer must be a function")
		return changed:Connect(callback)
	end
end

function ModernControls.new(services: any): any
	assert(type(services) == "table" and services.Store ~= nil, "ModernControls requires Store")
	local storeIds: { [string]: string } = {}
	local storeOwners: { [string]: string } = {}
	local function storeId(id: string): string
		local assigned = storeIds[id]
		if assigned ~= nil then return assigned end
		local base = string.lower(string.gsub(id, ":", "-"))
		base = string.gsub(base, "%-+", "-")
		base = string.gsub(base, "[%-%._]+$", "")
		local suffix = 1
		local candidate = string.gsub(string.sub(base, 1, 80), "[%-%._]+$", "")
		while storeOwners[candidate] ~= nil and storeOwners[candidate] ~= id do
			suffix += 1
			local marker = "-" .. tostring(suffix)
			candidate = string.sub(base, 1, 80 - #marker) .. marker
		end
		storeIds[id], storeOwners[candidate] = candidate, id
		return candidate
	end
	local function render(descriptor: any, stage: any): (any?, any?)
		if KINDS[descriptor.kind] ~= true then return nil, fail("unknown_modern_kind", "Unknown modern control kind", "render") end
		local valueId = storeId(descriptor.id)
		local accessible = accessibilityOf(descriptor)
		local previousIdentity = stage.identity
		local identity = {}
		if type(previousIdentity) == "table" then
			for key, value in pairs(previousIdentity) do identity[key] = value end
		end
		local token = {}
		local registeredStore = false
		local replaceDefinition = false
		local usesStore = INPUT_KINDS[descriptor.kind] == true
		local usesEdit = EDITOR_KINDS[descriptor.kind] == true
		if (not usesStore and identity.storeId ~= nil) or (not usesEdit and identity.editId ~= nil) then identity = {} end
		local definition = {
			id = valueId, default = defaultFor(descriptor), validate = validator(descriptor.kind, descriptor),
			normalize = normalize(descriptor.kind, descriptor),
		}
		local stagingDefinition = type(stage.publicationQueue) == "table"
		local definitionCheckpoint: any = nil
		local previousOwner = if type(previousIdentity) == "table" then previousIdentity.owner else nil
		if usesStore and identity.storeId ~= valueId then
			local registerOptions = if stagingDefinition then { deferPending = true } else nil
			local ok, registerError = services.Store:Register(definition, registerOptions)
			if not ok then return nil, registerError end
			identity.storeId, identity.stagedDefinition = valueId, stagingDefinition
			registeredStore = true
		elseif usesStore and identity.storeId == valueId then
			replaceDefinition = true
		end
		if usesStore then
			stage.maid:GiveTask(function()
				if (registeredStore and (identity.owner == token or identity.owner == nil)) or (replaceDefinition and identity.owner == token) then
					services.Store:Unregister(valueId, { silent = identity.stagedDefinition == true and identity.committed ~= true })
				end
			end)
		end
		local actual = { instances = 0, connections = 0, workers = 0, tasks = 0, virtualCells = 0 }
		local result = { composition = composition(descriptor, valueId), actual = actual, _identity = identity }
		if registeredStore and stagingDefinition then
			table.insert(stage.publicationQueue, function()
				local changedByTransaction = type(stage.storeChanges) == "table" and stage.storeChanges[valueId] ~= nil
				services.Store:CommitStagedDefinition(valueId, { discardPending = changedByTransaction })
				identity.committed = true
			end)
		end
		local function setDisplay(value: any)
			local gui = actual.guiObject
			if gui == nil then return end
			local chrome = actual.chrome
			local label = if chrome and chrome.label ~= nil then chrome.label else result.composition.title or descriptor.kind
			local display = if chrome and chrome.value ~= nil then chrome.value else displayValue(value)
			if gui:IsA("TextBox") then gui.Text = tostring(display) end
			if gui:IsA("TextButton") then gui.Text = tostring(label) .. ": " .. tostring(display) end
			if actual.label ~= nil then
				actual.label.Text = if chrome ~= nil then tostring(label) else tostring(label) .. ": " .. tostring(display)
			end
		end
		local concrete = renderDataControl(descriptor, services, stage, actual)
		local statControl: any = nil
		if descriptor.kind == "Stat" then
			local initial = defaultFor(descriptor)
			if type(initial) ~= "number" then return nil, fail("invalid_stat_value", "Stat value must be a number", "render") end
			if services.Context == nil or typeof(stage.target) ~= "Instance" or not stage.target:IsA("GuiObject") then
				return nil, fail("missing_stat_context", "Stat rendering requires a GUI target and control context", "render")
			end
			local delegatedSection = {
				_context = services.Context,
				_content = stage.target,
				_nextOrder = function() return stage.generation end,
				_registerControl = function() end,
				_focus = function() end,
			}
			statControl = Controls.Stat(delegatedSection, {
				Id = descriptor.id, Title = localized(descriptor, services, "title") or descriptor.kind, Value = initial,
				Height = descriptor.height, Delta = descriptor.delta, Baseline = descriptor.baseline,
				BaselineValue = descriptor.baselineValue, NumberMotion = descriptor.numberMotion,
				Format = descriptor.format, Precision = descriptor.precision, Callback = descriptor.onChange,
			})
			stage.maid:GiveTask(statControl)
			actual.guiObject, actual.statControl, actual.instances = statControl.Root, statControl, 1 + #statControl.Root:GetDescendants()
		elseif concrete == nil then
			renderGuiObject(descriptor, stage, actual)
		end
		attachFocusContract(result, actual, services, stage, concrete or statControl)
		if concrete ~= nil then
			result.GetDataControl = function() return concrete end
			if descriptor.kind == "DataGrid" then
				result.SetRows = function(rows: any) return concrete:SetRows(rows) end
				result.SetColumns = function(columns: any) return concrete:SetColumns(columns) end
				result.SetQuery = function(query: any) return concrete:SetQuery(query) end
				result.SetPagination = function(page: any, pageSize: any?) return concrete:SetPagination(page, pageSize) end
				result.SetGroupBy = function(groupBy: any) return concrete:SetGroupBy(groupBy) end
				result.SetRowSelected = function(key: any, selected: boolean?) return concrete:SetRowSelected(key, selected) end
			else
				result.Append = function(sample: any, seriesId: any?) return concrete:Append(sample, seriesId) end
				result.SetSeriesSamples = function(seriesId: any, samples: any) return concrete:SetSeriesSamples(seriesId, samples) end
				result.GetSeriesSamples = function(seriesId: any?) return concrete:GetSeriesSamples(seriesId) end
			end
		end
		local function refreshLocalization()
			local title, description = localized(descriptor, services, "title"), localized(descriptor, services, "description")
			local nextComposition = copyComposition(result.composition)
			nextComposition.kind, nextComposition.id, nextComposition.title, nextComposition.description =
				descriptor.kind, descriptor.id, title, description
			nextComposition.accessibility = accessible
			nextComposition.value = table.freeze({ storeId = valueId, readOnly = accessible.readOnly, disabled = accessible.disabled })
			nextComposition.preset = if descriptor.kind == "ListBox" then (descriptor.preset or "ListBox") else nil
			nextComposition.items = descriptor.items
			nextComposition.data = if descriptor.kind == "DataGrid" or descriptor.kind == "Chart" then dataOptions(descriptor) else nil
			if actual.resource ~= nil then
				nextComposition.items = actual.resource.value
				nextComposition.provider = actual.resource.state
				nextComposition.generation = actual.resource.generation
			end
			result.composition = table.freeze(nextComposition)
			local gui = actual.guiObject
			if usesStore then
				setDisplay(services.Store:Get(valueId))
			elseif actual.chrome == nil then
				if gui and gui:IsA("TextButton") then gui.Text = title or descriptor.kind end
				if actual.label then actual.label.Text = title or descriptor.kind end
			elseif actual.resource ~= nil then
				setDisplay(actual.resource.value)
			end
			if gui then applyDirectionTree(gui, if services.Localization then services.Localization:GetDirection() else "LTR") end
			stage.UpdateSnapshot(result.composition, actual)
		end
		refreshLocalization()
		if services.Localization and services.Localization.LocaleChanged then
			stage.maid:GiveTask(services.Localization.LocaleChanged:Connect(refreshLocalization))
			actual.connections += 1
		end
		if type(descriptor.bindings) == "table" and usesStore and services.Dependencies ~= nil then
			for index, binding in ipairs(descriptor.bindings) do
				if type(binding) == "table" and type(binding.sources) == "table" and #binding.sources > 0 then
					local sources = table.create(#binding.sources)
					for sourceIndex, source in ipairs(binding.sources) do sources[sourceIndex] = storeId(source) end
					local bindingHandle, bindingError = services.Dependencies:Bind(valueId, "descriptor-" .. tostring(index), sources, function(...)
						local values = { ... }
						local nextValue = if binding.mode == "all" then values elseif binding.mode == "first" or binding.mode == nil then values[1] else values[#values]
						services.Store:Set(valueId, nextValue)
					end)
					if bindingHandle == nil then return nil, bindingError end
					stage.maid:GiveTask(bindingHandle)
					actual.connections += #sources
				end
			end
		end
		if descriptor.kind == "Stat" then
			result.GetValue = function() return statControl:Get() end
			result.ValueSnapshot = function() return statControl:ValueSnapshot() end
			result.SetValue = function(value: any, options: any?)
				if type(value) ~= "number" then return false, fail("invalid_stat_value", "Stat value must be a number", "set") end
				statControl:Set(value, options)
				return true, nil
			end
			result.Reset = function(options: any?) statControl:Reset(options); return true, nil end
			result.ResetBaseline = function(value: any?) 
				if value ~= nil and type(value) ~= "number" then return false, fail("invalid_stat_baseline", "Stat baseline must be a number", "resetBaseline") end
				statControl:ResetBaseline(value)
				return true, nil
			end
			result.GetDeltaSnapshot = function() return statControl:GetDeltaSnapshot() end
			result.Observe = function(callback: any, options: any?)
				if type(callback) ~= "function" then return nil, fail("invalid_observer", "Observer must be a function", "observe") end
				return statControl:Observe(callback, options), nil
			end
		end
		if usesStore then
			result.GetValue = function() return services.Store:Get(valueId) end
			result.SetValue = function(value: any, options: any?)
				if accessible.disabled or accessible.readOnly then return false, fail("read_only", "Control value cannot be changed", "set") end
				local source = if type(options) == "table" and options.Source ~= nil then options.Source else "program"
				local function commit() return services.Store:Set(valueId, value, source) end
				if type(options) == "table" and options.Silent == true then return services.Store:SuppressDefinitionCallback(commit) end
				return commit()
			end
			result.ValueSnapshot = function() return table.freeze({ id = descriptor.id, value = services.Store:Get(valueId) }) end
			result.Observe = function(callback: any, options: any?)
				if type(callback) ~= "function" then return nil, fail("invalid_observer", "Observer must be a function", "observe") end
				local connection, observeError = services.Store:Subscribe(valueId, callback)
				if connection == nil then return nil, observeError end
				if type(options) == "table" and options.EmitInitial == true then callback(services.Store:Get(valueId), nil, valueId, "program") end
				return connection, nil
			end
			result.Reset = function(options: any?) return result.SetValue(defaultFor(descriptor), options) end
			local value = services.Store:Get(valueId)
			setDisplay(value)
			stage.maid:GiveTask(services.Store:Subscribe(valueId, function(nextValue: any)
				setDisplay(nextValue)
			end))
			actual.connections += 1
		end
		if EDITOR_KINDS[descriptor.kind] and services.EditSession ~= nil and type(services.EditSession.End) == "function" then
			local editId = "modern-edit-" .. valueId
			local registeredEdit = false
			if identity.editId ~= editId then
				local _, editError = services.EditSession:Begin(editId, defaultFor(descriptor), { validate = descriptor.validate, commit = descriptor.commit })
				if editError then return nil, editError end
				identity.editId = editId
				registeredEdit = true
			end
			stage.maid:GiveTask(function()
				if (registeredEdit and (identity.owner == token or identity.owner == nil)) or (not registeredEdit and identity.owner == token) then
					services.EditSession:End(editId)
				end
			end)
			result.EditId = editId
			result.GetValue = function()
				local snapshot = services.EditSession:Get(editId)
				return if snapshot ~= nil then snapshot.draft else nil
			end
			result.SetValue = function(value: any)
				if accessible.disabled or accessible.readOnly then return false, fail("read_only", "Control value cannot be changed", "set") end
				return services.EditSession:Update(editId, value)
			end
		end
		result.ConfigureChrome = function(chrome: any): (boolean, any?)
			for key, value in pairs(chrome) do
				if not attributeCompatible(value) then
					return false, fail("invalid_chrome_attribute", "Chrome " .. key .. " is not attribute-compatible", "configureChrome")
				end
			end
			local gui = actual.guiObject
			if gui ~= nil then
				local attributes = {
					{ "PotassiumChromeLabel", chrome.label },
					{ "PotassiumChromeValue", chrome.value },
					{ "PotassiumChromeAddonRail", chrome.addonRail },
					{ "PotassiumChromeDanger", chrome.danger },
					{ "PotassiumChromeTrailing", chrome.trailing },
				}
				for _, attribute in ipairs(attributes) do
					local wrote, writeError = pcall(gui.SetAttribute, gui, attribute[1], attribute[2])
					if not wrote then
						return false, fail("chrome_attribute_failed", "Could not set " .. attribute[1] .. ": " .. tostring(writeError), "configureChrome")
					end
				end
			end
			local label = chrome.label or descriptor.title or descriptor.kind
			if actual.label ~= nil then actual.label.Text = tostring(label) end
			if gui ~= nil and gui:IsA("TextBox") and chrome.value ~= nil then gui.Text = tostring(chrome.value) end
			if gui ~= nil and gui:IsA("TextButton") then
				gui.Text = if chrome.value ~= nil then tostring(label) .. ": " .. tostring(chrome.value) else tostring(label)
			end
			actual.chrome = chrome
			local nextComposition = copyComposition(result.composition)
			nextComposition.chrome = chrome
			result.composition = table.freeze(nextComposition)
			stage.UpdateSnapshot(result.composition, actual)
			return true, nil
		end
		if descriptor.kind == "Keybind" then
			result.GetMode = function()
				local value = services.Store:Get(valueId)
				return if type(value) == "table" then value.mode else nil
			end
			result.SetMode = function(mode: any)
				if accessible.disabled or accessible.readOnly then return false, fail("read_only", "Keybind mode cannot be changed", "setMode") end
				if mode ~= "Toggle" and mode ~= "Hold" and mode ~= "Always" then return false, fail("invalid_keybind_mode", "Mode must be Toggle, Hold, or Always", "setMode") end
				local value = services.Store:Get(valueId)
				local keyCode = if type(value) == "table" then value.keyCode else Enum.KeyCode.Unknown
				return services.Store:Set(valueId, { keyCode = keyCode, mode = mode })
			end
		end
		result.Activate = function()
			if accessible.disabled or accessible.readOnly then return false, fail("read_only", "Control cannot be activated", "activate") end
			if descriptor.kind == "Stat" then return false, fail("read_only", "Stat controls cannot be activated", "activate") end
			local changed, changeError, didSelect = true, nil, false
			if descriptor.kind == "Toggle" then
				changed, changeError = services.Store:Set(valueId, services.Store:Get(valueId) ~= true, "user")
			elseif descriptor.kind == "Slider" or descriptor.kind == "NumberInput" then
				local value = services.Store:Get(valueId)
				changed, changeError = services.Store:Set(valueId, (type(value) == "number" and value or 0) + (descriptor.step or 1), "user")
			elseif descriptor.kind == "Combobox" or descriptor.kind == "ListBox" or descriptor.kind == "Radio" or descriptor.kind == "Segmented" then
				local items = descriptor.items or {}
				if (descriptor.kind == "Combobox" or descriptor.kind == "ListBox") and type(actual.resource) == "table" and type(actual.resource.value) == "table" then
					items = actual.resource.value
				end
				local item = items[1]
				if item ~= nil and usesStore then
					local selectedValue = if type(item) == "table" and type(descriptor.stableKey) == "string" then item[descriptor.stableKey] else item
					changed, changeError = services.Store:Set(valueId, selectedValue, "user")
					didSelect = changed
				end
			end
			if not changed then return false, changeError end
			if didSelect
				and (descriptor.kind == "Combobox" or descriptor.kind == "ListBox" or descriptor.kind == "Radio" or descriptor.kind == "Segmented")
				and services.Haptics and type(services.Haptics.Pulse) == "function" then
				services.Haptics:Pulse("selection", function()
					return not accessible.disabled and not accessible.readOnly
				end)
			end
			return dispatch(descriptor, services, "activate")
		end
		if actual.guiObject and actual.guiObject:IsA("TextBox") and (usesStore or identity.editId ~= nil) then
			stage.maid:GiveTask(actual.guiObject.FocusLost:Connect(function()
				if accessible.disabled or accessible.readOnly then return end
				local text = actual.guiObject.Text
				if descriptor.kind == "DateRangePicker" then
					local divider = string.find(text, " - ", 1, true)
					if divider == nil then return end
					result.SetValue({ start = string.sub(text, 1, divider - 1), ["end"] = string.sub(text, divider + 3) }, { Source = "user" })
				else
					result.SetValue(if descriptor.kind == "NumberInput" then tonumber(text) or text else text, { Source = "user" })
				end
			end))
			actual.connections += 1
		elseif actual.guiObject and actual.guiObject:IsA("TextButton") then
			stage.maid:GiveTask(actual.guiObject.Activated:Connect(function()
				if descriptor.kind == "Keybind" and result.Capture ~= nil then result.Capture() else result.Activate() end
			end))
			actual.connections += 1
		end
		if descriptor.kind == "FormActions" then
			local edits = services.EditSession
			if edits == nil or type(edits.Get) ~= "function" or type(edits.Commit) ~= "function" or type(edits.Revert) ~= "function" then
				return nil, fail("edit_session_unavailable", "FormActions requires EditSession", "render")
			end
			local form, formError = edits:Get(descriptor.formId)
			if form == nil then return nil, formError end
			result.FormId, actual.form = descriptor.formId, form
			result.GetForm = function() return edits:Get(descriptor.formId) end
			result.Submit = function()
				if accessible.disabled or accessible.readOnly then return false, fail("read_only", "Form cannot be submitted", "submit") end
				local committed, commitError = edits:Commit(descriptor.formId)
				if not committed then return false, commitError end
				if services.Commands ~= nil then return services.Commands:Execute(descriptor.submitAction, { formId = descriptor.formId }) end
				return true, nil
			end
			result.Reset = function()
				if accessible.disabled or accessible.readOnly then return false, fail("read_only", "Form cannot be reset", "reset") end
				local reverted, revertError = edits:Revert(descriptor.formId)
				if not reverted then return false, revertError end
				if services.Commands ~= nil then return services.Commands:Execute(descriptor.resetAction, { formId = descriptor.formId }) end
				return true, nil
			end
			result.Activate = result.Submit
		end
		if type(descriptor.providerId) == "string" then
			local resources = services.Resources
			if resources == nil or type(resources.Get) ~= "function" or type(resources.Observe) ~= "function" then
				return nil, fail("resource_controller_unavailable", "providerId requires ResourceController", "render")
			end
			local resource, resourceError = resources:Get(descriptor.providerId)
			if resource == nil then return nil, resourceError end
			local function apply(snapshot: any)
				actual.resource = snapshot
				local nextComposition = copyComposition(result.composition)
				nextComposition.items = snapshot.value
				nextComposition.provider = snapshot.state
				nextComposition.generation = snapshot.generation
				result.composition = table.freeze(nextComposition)
				setDisplay(snapshot.value)
				stage.UpdateSnapshot(result.composition, actual)
			end
			apply(resource)
			local observation, observeError = resources:Observe(descriptor.providerId, apply, { EmitInitial = false })
			if observation == nil then return nil, observeError end
			stage.maid:GiveTask(observation)
			result.Refresh = function() return resources:Refresh(descriptor.providerId) end
			result.CancelRefresh = function() return resources:Cancel(descriptor.providerId) end
			result.GetProviderState = function() return resources:Get(descriptor.providerId) end
		end
		bindKeybind(descriptor, services, stage.maid, valueId, actual)
		bindCapture(descriptor, services, stage.maid, valueId, actual)
		if actual.capture ~= nil then result.Capture = actual.capture end
		result._preflightIdentity = function(changes: any): (boolean, any?)
			if not replaceDefinition then return true, nil end
			if type(services.Store.ValidateDefinitionReplacement) ~= "function" then
				return false, fail("store_preflight_unavailable", "Store replacement preflight is unavailable", "preflightIdentity")
			end
			local prospective = if type(changes) == "table" then rawget(changes, valueId) else nil
			return services.Store:ValidateDefinitionReplacement(valueId, definition, prospective, prospective ~= nil)
		end
		result._adoptIdentity = function(): (boolean, any?)
			if replaceDefinition then
				if stagingDefinition then
					local checkpoint, checkpointError = services.Store:_CaptureDefinition(valueId)
					if checkpoint == nil then return false, checkpointError end
					definitionCheckpoint = checkpoint
				end
				local replaceOptions = if type(stage.publicationQueue) == "table" then { deferNotifications = true, notifications = stage.publicationQueue } else nil
				local replaced, replaceError = services.Store:ReplaceDefinition(valueId, definition, replaceOptions)
				if not replaced then return false, replaceError end
				if stagingDefinition then
					table.insert(stage.publicationQueue, function() definitionCheckpoint = nil end)
				end
			end
			if type(previousIdentity) == "table"
				and ((identity.storeId ~= nil and identity.storeId == previousIdentity.storeId)
					or (identity.editId ~= nil and identity.editId == previousIdentity.editId)) then
				previousIdentity.owner = token
			end
			identity.owner = token
			return true, nil
		end
		result._rollbackIdentity = function(): (boolean, any?)
			if definitionCheckpoint ~= nil then
				local restored, restoreError = services.Store:_RestoreDefinition(valueId, definitionCheckpoint)
				if not restored then return false, restoreError end
				definitionCheckpoint = nil
			end
			if type(previousIdentity) == "table" then previousIdentity.owner = previousOwner end
			identity.owner = nil
			return true, nil
		end
		return result, nil
	end
	local renderers = {}
	for kind in pairs(KINDS) do renderers[kind] = render end
	return table.freeze({ Render = render, Renderers = table.freeze(renderers), Kinds = KINDS })
end

return table.freeze(ModernControls)

end

__modules["components/OldschoolPrimitives"] = function()
--!strict

local Maid = __require("core/Maid")
local SchemaCodec = __require("customization/SchemaCodec")
local StructuredError = __require("core/StructuredError")

local OldschoolPrimitives = {}

local function fail(code: string, message: string): any
	return StructuredError.from(code, message, { domain = "oldschoolPrimitives", operation = "addonRail" })
end

local AddonHandle = {}
AddonHandle.__index = AddonHandle
function AddonHandle:GetSnapshot()
	return table.freeze({ id = self._id, generation = self._generation, state = self._destroyed and "destroyed" or "mounted", descriptor = self._descriptor })
end
function AddonHandle:Destroy(): boolean
	if self._destroyed then return true end
	self._destroyed = true
	self._rail._addons[self._id] = nil
	self._maid:Destroy()
	return true
end
AddonHandle.Unmount = AddonHandle.Destroy

local AddonRail = {}
AddonRail.__index = AddonRail
function AddonRail.new(options: any): (any?, any?)
	if type(options) ~= "table" or type(options.ownerId) ~= "string" then return nil, fail("invalid_addon_rail", "AddonRail requires ownerId") end
	return setmetatable({ _ownerId = options.ownerId, _addons = {}, _destroyed = false, _generation = 0, _renderer = options.renderer }, AddonRail), nil
end
function AddonRail:Mount(descriptor: any): (any?, any?)
	if self._destroyed then return nil, fail("destroyed_addon_rail", "AddonRail has been destroyed") end
	local codec = SchemaCodec.new()
	local portable, scanError = codec:PreScanPortable(descriptor, "addonRail")
	if not portable then return nil, scanError end
	if type(descriptor) ~= "table" or type(rawget(descriptor, "id")) ~= "string" or type(rawget(descriptor, "kind")) ~= "string" then
		return nil, fail("invalid_addon_descriptor", "Addon descriptor requires id and kind")
	end
	if self._addons[descriptor.id] ~= nil then return nil, fail("duplicate_addon_id", "Addon id is already mounted") end
	local normalized, normalizeError = codec:Normalize(descriptor)
	if normalized == nil then return nil, normalizeError end
	local maid = Maid.new()
	if type(self._renderer) == "function" then
		local ok, result = pcall(self._renderer, normalized, maid)
		if not ok or result == false then maid:Destroy(); return nil, fail("addon_stage_failed", "Addon could not be staged") end
		if type(result) == "table" and result.Destroy then maid:GiveTask(result) end
	end
	if self._destroyed then
		maid:Destroy()
		return nil, fail("destroyed_addon_rail", "AddonRail has been destroyed")
	end
	if self._addons[normalized.id] ~= nil then
		maid:Destroy()
		return nil, fail("duplicate_addon_id", "Addon id is already mounted")
	end
	self._generation += 1
	local handle = setmetatable({ _rail = self, _id = normalized.id, _descriptor = normalized, _generation = self._generation, _maid = maid, _destroyed = false }, AddonHandle)
	self._addons[normalized.id] = handle
	return handle, nil
end
function AddonRail:GetSnapshot()
	local addons = {}
	for id, addon in pairs(self._addons) do addons[id] = addon:GetSnapshot() end
	return table.freeze({ ownerId = self._ownerId, destroyed = self._destroyed, addons = table.freeze(addons) })
end
function AddonRail:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	for _, addon in pairs(self._addons) do addon:Destroy() end
	self._addons = {}
end


-- Legacy contributions intentionally remain isolated from modern state/rendering.
-- They are mounted by ControlHost as opaque, portable descriptors so 0.1 callers
-- keep their behavior without becoming an alternate mutable control system.
function OldschoolPrimitives.RenderLegacy(descriptor: any, stage: any): (any?, any?)
	if type(descriptor) ~= "table" or descriptor.kind ~= "legacy" then
		return nil, fail("invalid_legacy_control", "Legacy renderer requires a legacy descriptor")
	end
	local codec = SchemaCodec.new()
	local portable, portableError = codec:PreScanPortable(descriptor, "legacyControl")
	if not portable then
		return nil, portableError
	end
	local legacy = descriptor.legacy
	if type(legacy) ~= "table" then
		return nil, fail("invalid_legacy_control", "Legacy descriptor requires a portable legacy payload")
	end
	return {
		composition = table.freeze({
			kind = "legacy",
			id = descriptor.id,
			title = descriptor.title,
			legacy = legacy,
			readOnly = descriptor.readOnly == true,
			disabled = descriptor.disabled == true,
		}),
		actual = { instances = 0, connections = 0, workers = 0, tasks = 0, virtualCells = 0 },
	}, nil
end
OldschoolPrimitives.AddonRail = AddonRail
return table.freeze(OldschoolPrimitives)

end

__modules["core/AdaptiveController"] = function()
--!strict

local Signal = __require("core/Signal")
local StructuredError = __require("core/StructuredError")

local AdaptiveController = {}
AdaptiveController.__index = AdaptiveController

local function failure(code: string, message: string, operation: string): any
	return StructuredError.from(code, message, { domain = "adaptive", operation = operation })
end

local function freeze(value: any, depth: number?): any
	local currentDepth = depth or 0
	if type(value) ~= "table" then
		return value
	end
	if currentDepth >= 6 then
		return "<bounded>"
	end
	local result = {}
	local count = 0
	for key, item in pairs(value) do
		count += 1
		if count > 96 then
			break
		end
		if type(key) == "string" or type(key) == "number" then
			result[key] = freeze(item, currentDepth + 1)
		end
	end
	return table.freeze(result)
end

local function finite(value: any, fallback: number): number
	return if type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge then value else fallback
end

local function normalizePolicy(input: any): any
	local source = if type(input) == "table" then input else {}
	local capabilities = if type(source.capabilities) == "table" then source.capabilities else {}
	return table.freeze({
		logicalSize = freeze(source.logicalSize or { x = 0, y = 0 }),
		orientation = if source.orientation == "portrait" then "portrait" else "landscape",
		safeInsets = freeze(source.safeInsets or {}),
		workArea = freeze(source.workArea or {}),
		virtualKeyboardOcclusion = freeze(source.virtualKeyboardOcclusion or {}),
		deviceClass = if source.deviceClass == "phone" then "phone" else if source.deviceClass == "tablet" then "tablet" else "desktop",
		capabilities = table.freeze({
			mouse = capabilities.mouse == true,
			touch = capabilities.touch == true,
			keyboard = capabilities.keyboard == true,
			gamepad = capabilities.gamepad == true,
		}),
		modality = if type(source.modality) == "string" then source.modality else "mouse",
		textScale = math.max(0.5, math.min(3, finite(source.textScale, 1))),
		reducedMotion = source.reducedMotion == true,
		reduceSensory = source.reduceSensory == true or source.reducedSensory == true,
		lowPower = source.lowPower == true,
		navigationPresentation = if source.navigationPresentation == "rail" then "rail" else if source.navigationPresentation == "tabs" then "tabs" else "sidebar",
		popupPolicy = if source.popupPolicy == "bottom-sheet" then "bottom-sheet" else if source.popupPolicy == "full-screen" then "full-screen" else "popup",
	})
end

function AdaptiveController.new(initialPolicy: any?): any
	return setmetatable({
		_policy = normalizePolicy(initialPolicy),
		_revision = 0,
		_signal = Signal.new(),
		_destroyed = false,
		_pending = nil,
		_dirty = false,
		_flushGeneration = 0,
		_generation = 0,
		_retained = table.freeze({}),
	}, AdaptiveController)
end

function AdaptiveController:GetSnapshot(): any
	return table.freeze({
		policy = self._policy,
		route = self._retained.route,
		focus = self._retained.focus,
		selection = self._retained.selection,
		scroll = self._retained.scroll,
		draft = self._retained.draft,
		revision = self._revision,
	})
end

function AdaptiveController:_publish()
	self._signal:Fire(self:GetSnapshot())
end

function AdaptiveController:_scheduleFlush()
	if self._dirty then
		return
	end
	self._dirty = true
	local owner = self
	local scheduledGeneration = self._generation
	task.defer(function()
		if owner._destroyed then
			return
		end
		if scheduledGeneration ~= owner._generation then
			owner._dirty = false
			owner:_scheduleFlush()
			return
		end
		owner._dirty = false
		local pending = owner._pending
		owner._pending = nil
		if pending == nil then
			return
		end
		owner._policy = pending.policy
		owner._retained = pending.retained
		owner._revision += 1
		owner:_publish()
	end)
end

function AdaptiveController:Transition(nextPolicy: any, retainedState: any?): (any?, any?)
	if self._destroyed then
		return nil, failure("destroyed", "AdaptiveController is destroyed", "transition")
	end
	local retained = if type(retainedState) == "table" then retainedState else {}
	local baseRetained = if self._pending ~= nil then self._pending.retained else self._retained
	self._generation += 1
	self._pending = {
		policy = normalizePolicy(nextPolicy),
		retained = freeze({
			route = if retained.route ~= nil then retained.route else baseRetained.route,
			focus = if retained.focus ~= nil then retained.focus else baseRetained.focus,
			selection = if retained.selection ~= nil then retained.selection else baseRetained.selection,
			scroll = if retained.scroll ~= nil then retained.scroll else baseRetained.scroll,
			draft = if retained.draft ~= nil then retained.draft else baseRetained.draft,
		}),
	}
	self:_scheduleFlush()
	return self:GetSnapshot(), nil
end

function AdaptiveController:Observe(callback: (any) -> (), options: any?): any
	assert(type(callback) == "function", "Adaptive observer callback is required")
	local connection = self._signal:Connect(callback)
	if type(options) == "table" and options.EmitInitial == true then
		callback(self:GetSnapshot())
	end
	return connection
end

function AdaptiveController:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	self._generation += 1
	self._pending = nil
	self._signal:Destroy()
end

return AdaptiveController

end

__modules["core/AsyncProvider"] = function()
--!strict

export type CancelSignal = {
	Cancelled: boolean,
	ThrowIfCancelled: (self: CancelSignal) -> (),
	OnCancel: (self: CancelSignal, callback: () -> ()) -> (() -> ()),
}

export type State = "idle" | "loading" | "ready" | "empty" | "error" | "cancelled"

export type Options = {
	Provider: (signal: CancelSignal) -> { any },
	RefreshInterval: number?,
	Timeout: number?,
	RetryCount: number?,
	RetryDelay: number?,
	LoadImmediately: boolean?,
	ClearOnError: boolean?,
	Apply: (items: { any }) -> (),
	OnStateChanged: ((state: State, message: string?) -> ())?,
}

export type Controller = {
	Refresh: (self: Controller) -> Controller,
	CancelRefresh: (self: Controller) -> Controller,
	Cancel: (self: Controller) -> Controller,
	SetProvider: (self: Controller, provider: (signal: CancelSignal) -> { any }) -> Controller,
	Destroy: (self: Controller) -> (),
}

local AsyncProvider = {}
AsyncProvider.__index = AsyncProvider

local function cancelledError(): string
	return "AsyncProvider request cancelled"
end

local function newSignal(): CancelSignal
	local callbacks = {}
	local signal: any = { Cancelled = false }
	function signal:ThrowIfCancelled()
		if self.Cancelled then
			error(cancelledError(), 2)
		end
	end
	function signal:OnCancel(callback: () -> ())
		assert(type(callback) == "function", "AsyncProvider cancellation callback must be a function")
		if self.Cancelled then
			callback()
			return function() end
		end
		local entry = { callback = callback }
		table.insert(callbacks, entry)
		local connected = true
		return function()
			if not connected then
				return
			end
			connected = false
			entry.callback = nil
			local index = table.find(callbacks, entry)
			if index then
				table.remove(callbacks, index)
			end
		end
	end
	(signal :: any)._cancel = function()
		if signal.Cancelled then
			return
		end
		signal.Cancelled = true
		local pending = callbacks
		callbacks = {}
		for _, entry in ipairs(pending) do
			local callback = entry.callback
			entry.callback = nil
			if callback then pcall(callback) end
		end
	end
	return signal :: CancelSignal
end

local function waitCancellable(seconds: number, signal: CancelSignal): boolean
	local elapsed = 0
	while elapsed < seconds and not signal.Cancelled do
		local step = math.min(0.05, seconds - elapsed)
		task.wait(step)
		elapsed += step
	end
	return not signal.Cancelled
end

local function ownsRequest(self: any, generation: number, signal: CancelSignal): boolean
	return not self._destroyed and self._generation == generation and self._signal == signal
end

local function finishRequest(self: any, generation: number, signal: CancelSignal, state: State, message: string?)
	if not ownsRequest(self, generation, signal) then
		return
	end
	self._signal = nil
	self:_setState(state, message)
end


function AsyncProvider.new(options: Options): Controller
	assert(type(options) == "table" and type(options.Provider) == "function", "AsyncProvider requires Provider")
	assert(type(options.Apply) == "function", "AsyncProvider requires Apply")
	local self: any = setmetatable({}, AsyncProvider)
	self._provider = options.Provider
	self._apply = options.Apply
	self._onStateChanged = options.OnStateChanged
	self._timeout = math.max(0, tonumber(options.Timeout) or 15)
	self._retryCount = math.max(0, math.floor(tonumber(options.RetryCount) or 0))
	self._retryDelay = math.max(0, tonumber(options.RetryDelay) or 0.5)
	self._interval = tonumber(options.RefreshInterval)
	if self._interval ~= nil then
		self._interval = math.max(0.05, self._interval)
	end
	self._clearOnError = options.ClearOnError == true
	self._state = "idle"
	self._generation = 0
	self._signal = nil
	self._destroyed = false
	self._timeouts = {}

	if self._interval then
		self._schedulerSignal = newSignal()
		self._scheduler = task.spawn(function()
			while not self._destroyed do
				if not waitCancellable(self._interval, self._schedulerSignal) or self._destroyed then
					break
				end
				self:Refresh()
			end
		end)
	end
	if options.LoadImmediately ~= false then
		self:Refresh()
	end
	return self
end

function AsyncProvider:_setState(state: State, message: string?)
	if self._destroyed then
		return
	end
	self._state = state
	if self._onStateChanged then
		self._onStateChanged(state, message)
	end
end

function AsyncProvider:CancelRefresh(): Controller
	local signal = self._signal
	if signal then
		self._signal = nil
		self._generation += 1
		local generation = self._generation
		local cancelSignal = (signal :: any)._cancel
		cancelSignal()
		if not self._destroyed and self._generation == generation and self._signal == nil then
			self:_setState("cancelled")
		end
	end
	return self
end

function AsyncProvider:Cancel(): Controller
	return self:CancelRefresh()
end
function AsyncProvider:Refresh(): Controller
	if self._destroyed then
		return self
	end
	local cancelledGeneration = self._generation + (if self._signal ~= nil then 1 else 0)
	self:CancelRefresh()
	if self._destroyed or self._generation ~= cancelledGeneration then
		return self
	end
	self._generation += 1
	local generation = self._generation
	local signal = newSignal()
	self._signal = signal
	self:_setState("loading")
	task.spawn(function()
		local attempt = 0
		while ownsRequest(self, generation, signal) do
			attempt += 1
			local timedOut = false
			local timeoutThread: thread? = nil
			if self._timeout > 0 then
				timeoutThread = task.delay(self._timeout, function()
					if ownsRequest(self, generation, signal) and not signal.Cancelled then
						timedOut = true
						local cancelTimedOutSignal = (signal :: any)._cancel
						cancelTimedOutSignal()
					end
				end)
				self._timeouts[timeoutThread] = true
			end
			local ok, result = pcall(self._provider, signal)
			if timeoutThread then
				task.cancel(timeoutThread)
				self._timeouts[timeoutThread] = nil
			end
			if not ownsRequest(self, generation, signal) then
				return
			end
			if signal.Cancelled then
				if not timedOut then
					finishRequest(self, generation, signal, "cancelled", nil)
					return
				end
				if attempt > self._retryCount then
					if self._clearOnError then
						if not ownsRequest(self, generation, signal) then
							return
						end
						pcall(self._apply, {})
						if not ownsRequest(self, generation, signal) then
							return
						end
					end
					finishRequest(self, generation, signal, "error", "Timed out")
					return
				end
				signal = newSignal()
				self._signal = signal
				if not waitCancellable(self._retryDelay, signal) then
					return
				end
				if not ownsRequest(self, generation, signal) then
					return
				end
			else
				if ok and type(result) == "table" then
					if not ownsRequest(self, generation, signal) then
						return
					end
					local applied, applyError = pcall(self._apply, result)
					if not ownsRequest(self, generation, signal) then
						return
					end
					if applied then
						finishRequest(self, generation, signal, if #result == 0 then "empty" else "ready", nil)
						return
					end
					ok, result = false, applyError
				elseif ok then
					ok, result = false, "AsyncProvider must return an array"
				end
				if attempt > self._retryCount then
					if self._clearOnError then
						if not ownsRequest(self, generation, signal) then
							return
						end
						pcall(self._apply, {})
						if not ownsRequest(self, generation, signal) then
							return
						end
					end
					finishRequest(self, generation, signal, "error", tostring(result))
					return
				end
				if not waitCancellable(self._retryDelay, signal) then
					return
				end
				if not ownsRequest(self, generation, signal) then
					return
				end
			end
		end
	end)
	return self
end

function AsyncProvider:GetProviderState(): State
	return self._state
end

function AsyncProvider:SetProvider(provider: (signal: CancelSignal) -> { any }): Controller
	assert(type(provider) == "function", "AsyncProvider Provider must be a function")
	self._provider = provider
	return self:Refresh()
end

function AsyncProvider:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	if self._schedulerSignal then
		local cancelSchedulerSignal = (self._schedulerSignal :: any)._cancel
		cancelSchedulerSignal()
	end
	if self._signal then
		local cancelActiveSignal = (self._signal :: any)._cancel
		cancelActiveSignal()
		self._signal = nil
	end
	self._generation += 1
	if self._scheduler then
		pcall(task.cancel, self._scheduler)
	end
	for timeoutThread in pairs(self._timeouts) do
		pcall(task.cancel, timeoutThread)
	end
	table.clear(self._timeouts)
end

return AsyncProvider

end

__modules["core/BudgetLedger"] = function()
--!strict

local StructuredError = __require("core/StructuredError")

type StructuredErrorValue = StructuredError.StructuredError

export type CostVector = {
	instances: number, descendants: number, gradients: number, strokes: number, images: number,
	sounds: number, animations: number, particles: number, materialNodes: number, slots: number,
	layoutNodes: number, virtualRows: number, virtualCells: number, connections: number,
	workers: number, tasks: number, retainedItems: number, perRowInstances: number,
	updatesPerSecond: number, logicalBlurRequests: number,
}

export type Reservation = {
	transactionId: string,
	ownerId: string,
	generation: number,
	reserved: CostVector,
	actual: CostVector,
}

export type Snapshot = {
	limits: CostVector,
	reserved: CostVector,
	actual: CostVector,
	reservationCount: number,
	maxReservations: number,
	reservations: { Reservation },
}

export type Options = {
	limits: { [string]: any }?,
	maxReservations: number?,
	diagnostics: any?,
}

export type BudgetLedger = {
	Reserve: (self: BudgetLedger, transactionId: any, ownerId: any, generation: any, cost: any) -> (boolean, StructuredErrorValue?),
	Reconcile: (self: BudgetLedger, transactionId: any, ownerId: any, generation: any, actual: any) -> (boolean, StructuredErrorValue?),
	Release: (self: BudgetLedger, transactionId: any, ownerId: any, generation: any) -> (boolean, StructuredErrorValue?),
	ReleaseOwner: (self: BudgetLedger, ownerId: any, generation: any?) -> (number, StructuredErrorValue?),
	GetSnapshot: (self: BudgetLedger) -> Snapshot,
}

local BudgetLedger = {}
BudgetLedger.__index = BudgetLedger

local DIMENSIONS = table.freeze({
	"instances", "descendants", "gradients", "strokes", "images", "sounds", "animations", "particles",
	"materialNodes", "slots", "layoutNodes", "virtualRows", "virtualCells", "connections", "workers", "tasks",
	"retainedItems", "perRowInstances", "updatesPerSecond", "logicalBlurRequests",
})

local KNOWN = table.freeze({
	instances = true, descendants = true, gradients = true, strokes = true, images = true, sounds = true, animations = true,
	particles = true, materialNodes = true, slots = true, layoutNodes = true, virtualRows = true, virtualCells = true,
	connections = true, workers = true, tasks = true, retainedItems = true, perRowInstances = true,
	updatesPerSecond = true, logicalBlurRequests = true,
})

local DEFAULT_LIMIT = 10_000
local DEFAULT_MAX_RESERVATIONS = 256
local MAX_RESERVATIONS = 1_024

local function finiteInteger(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge and value >= 0 and value == math.floor(value)
end

local function identifier(value: any, field: string): (string?, StructuredErrorValue?)
	if type(value) ~= "string" or #value == 0 or #value > 129 or string.match(value, "^[A-Za-z][A-Za-z0-9._:-]*$") == nil then
		return nil, StructuredError.from("invalid_budget_" .. field, "Budget " .. field .. " must be a bounded identifier", {
			domain = "budget", operation = "validate", details = { field = field },
		})
	end
	return value, nil
end

local function generationValue(value: any): (number?, StructuredErrorValue?)
	if not finiteInteger(value) then
		return nil, StructuredError.from("invalid_budget_generation", "Budget generation must be a finite nonnegative integer", {
			domain = "budget", operation = "validate",
		})
	end
	return value, nil
end

local function empty(): CostVector
	local result: { [string]: number } = {}
	for _, dimension in ipairs(DIMENSIONS) do result[dimension] = 0 end
	return result :: CostVector
end

local function copy(vector: CostVector): CostVector
	local result = empty()
	for _, dimension in ipairs(DIMENSIONS) do result[dimension] = vector[dimension] end
	return table.freeze(result) :: any
end

local function validateVector(value: any, field: string, defaults: CostVector?): (CostVector?, StructuredErrorValue?)
	if value ~= nil and type(value) ~= "table" then
		return nil, StructuredError.from("invalid_budget_" .. field, "Budget " .. field .. " must be a table", { domain = "budget", operation = "validate" })
	end
	local source = value or {}
	for name in pairs(source) do
		if KNOWN[name] ~= true then
			return nil, StructuredError.from("unknown_budget_dimension", "Budget vector contains an unknown dimension", {
				domain = "budget", operation = "validate", details = { field = field, dimension = name },
			})
		end
	end
	local result = empty()
	for _, dimension in ipairs(DIMENSIONS) do
		local numberValue = source[dimension]
		if numberValue == nil then numberValue = if defaults ~= nil then defaults[dimension] else 0 end
		if not finiteInteger(numberValue) then
			return nil, StructuredError.from("invalid_budget_dimension", "Budget dimensions must be finite nonnegative integers", {
				domain = "budget", operation = "validate", details = { field = field, dimension = dimension },
			})
		end
		result[dimension] = numberValue
	end
	return table.freeze(result) :: any, nil
end

local function key(transactionId: string, ownerId: string, generation: number): string
	return transactionId .. "\0" .. ownerId .. "\0" .. tostring(generation)
end

local function context(transactionId: string, ownerId: string): StructuredError.Context
	return { domain = "budget", transactionId = transactionId, ownerId = ownerId }
end

local function fail(code: string, message: string, transactionId: string, ownerId: string, details: any?): StructuredErrorValue
	local errorContext = context(transactionId, ownerId)
	errorContext.details = details
	return StructuredError.from(code, message, errorContext)
end

local function publish(self: any, transactionId: string?, ownerId: string?)
	local diagnostics = self._diagnostics
	if type(diagnostics) ~= "table" or type(diagnostics.Publish) ~= "function" then return end
	pcall(function()
		diagnostics:Publish("budget", self:GetSnapshot(), { transactionId = transactionId, ownerId = ownerId })
	end)
end

local function recordSnapshot(record: any): Reservation
	return table.freeze({
		transactionId = record.transactionId,
		ownerId = record.ownerId,
		generation = record.generation,
		reserved = copy(record.reserved),
		actual = copy(record.actual),
	}) :: any
end

function BudgetLedger.new(options: Options?): (BudgetLedger?, StructuredErrorValue?)
	local resolved = options or {}
	if type(resolved) ~= "table" then
		return nil, StructuredError.from("invalid_budget_options", "Budget options must be a table", { domain = "budget", operation = "create" })
	end
	local defaults = empty()
	for _, dimension in ipairs(DIMENSIONS) do defaults[dimension] = DEFAULT_LIMIT end
	local limits, limitsError = validateVector(resolved.limits, "limits", defaults)
	if limits == nil then return nil, limitsError end
	local maxReservations = if resolved.maxReservations == nil then DEFAULT_MAX_RESERVATIONS else resolved.maxReservations
	if not finiteInteger(maxReservations) or maxReservations < 1 or maxReservations > MAX_RESERVATIONS then
		return nil, StructuredError.from("invalid_budget_max_reservations", "Budget maxReservations must be a bounded positive integer", { domain = "budget", operation = "create" })
	end
	return setmetatable({
		_limits = limits,
		_reserved = empty(),
		_actual = empty(),
		_records = {},
		_count = 0,
		_maxReservations = maxReservations,
		_diagnostics = resolved.diagnostics,
	}, BudgetLedger) :: any, nil
end

function BudgetLedger:Reserve(transactionId: any, ownerId: any, generation: any, cost: any): (boolean, StructuredErrorValue?)
	local transaction, transactionError = identifier(transactionId, "transaction_id")
	if transaction == nil then return false, transactionError end
	local owner, ownerError = identifier(ownerId, "owner_id")
	if owner == nil then return false, ownerError end
	local validGeneration, generationError = generationValue(generation)
	if validGeneration == nil then return false, generationError end
	local requested, costError = validateVector(cost, "reservation")
	if requested == nil then return false, costError end
	local recordKey = key(transaction, owner, validGeneration)
	if self._records[recordKey] ~= nil then
		return false, fail("budget_reservation_exists", "A reservation already exists for this transaction, owner, and generation", transaction, owner)
	end
	if self._count >= self._maxReservations then
		return false, fail("budget_reservation_limit", "Budget reservation capacity has been reached", transaction, owner, { maxReservations = self._maxReservations })
	end
	for _, dimension in ipairs(DIMENSIONS) do
		if self._reserved[dimension] + requested[dimension] > self._limits[dimension] then
			return false, fail("budget_exceeded", "Budget reservation would exceed the configured limit", transaction, owner, {
				dimension = dimension, limit = self._limits[dimension], reserved = self._reserved[dimension], requested = requested[dimension],
			})
		end
	end
	-- Every denial above precedes this accounting mutation.
	for _, dimension in ipairs(DIMENSIONS) do self._reserved[dimension] += requested[dimension] end
	self._records[recordKey] = { transactionId = transaction, ownerId = owner, generation = validGeneration, reserved = requested, actual = empty() }
	self._count += 1
	publish(self, transaction, owner)
	return true, nil
end

function BudgetLedger:Reconcile(transactionId: any, ownerId: any, generation: any, actual: any): (boolean, StructuredErrorValue?)
	local transaction, transactionError = identifier(transactionId, "transaction_id")
	if transaction == nil then return false, transactionError end
	local owner, ownerError = identifier(ownerId, "owner_id")
	if owner == nil then return false, ownerError end
	local validGeneration, generationError = generationValue(generation)
	if validGeneration == nil then return false, generationError end
	local nextActual, actualError = validateVector(actual, "actual")
	if nextActual == nil then return false, actualError end
	local record = self._records[key(transaction, owner, validGeneration)]
	if record == nil then return false, fail("unknown_budget_reservation", "No reservation exists for this transaction, owner, and generation", transaction, owner) end
	for _, dimension in ipairs(DIMENSIONS) do
		if nextActual[dimension] > record.reserved[dimension] then
			return false, fail("budget_reconcile_exceeds_reservation", "Actual usage cannot exceed its reservation", transaction, owner, {
				dimension = dimension, reserved = record.reserved[dimension], actual = nextActual[dimension],
			})
		end
		local projected = self._actual[dimension] - record.actual[dimension] + nextActual[dimension]
		if projected > self._limits[dimension] then
			return false, fail("budget_reconcile_exceeds_limit", "Actual usage cannot exceed the configured limit", transaction, owner, { dimension = dimension })
		end
	end
	for _, dimension in ipairs(DIMENSIONS) do
		self._actual[dimension] = self._actual[dimension] - record.actual[dimension] + nextActual[dimension]
	end
	record.actual = nextActual
	publish(self, transaction, owner)
	return true, nil
end

function BudgetLedger:Release(transactionId: any, ownerId: any, generation: any): (boolean, StructuredErrorValue?)
	local transaction, transactionError = identifier(transactionId, "transaction_id")
	if transaction == nil then return false, transactionError end
	local owner, ownerError = identifier(ownerId, "owner_id")
	if owner == nil then return false, ownerError end
	local validGeneration, generationError = generationValue(generation)
	if validGeneration == nil then return false, generationError end
	local recordKey = key(transaction, owner, validGeneration)
	local record = self._records[recordKey]
	if record == nil then return true, nil end
	for _, dimension in ipairs(DIMENSIONS) do
		self._reserved[dimension] -= record.reserved[dimension]
		self._actual[dimension] -= record.actual[dimension]
	end
	self._records[recordKey] = nil
	self._count -= 1
	publish(self, transaction, owner)
	return true, nil
end

function BudgetLedger:ReleaseOwner(ownerId: any, generation: any?): (number, StructuredErrorValue?)
	local owner, ownerError = identifier(ownerId, "owner_id")
	if owner == nil then return 0, ownerError end
	local selectedGeneration: number? = nil
	if generation ~= nil then
		local generationError: StructuredErrorValue?
		selectedGeneration, generationError = generationValue(generation)
		if selectedGeneration == nil then return 0, generationError end
	end
	local released = 0
	for recordKey, record in pairs(self._records) do
		if record.ownerId == owner and (selectedGeneration == nil or record.generation == selectedGeneration) then
			for _, dimension in ipairs(DIMENSIONS) do
				self._reserved[dimension] -= record.reserved[dimension]
				self._actual[dimension] -= record.actual[dimension]
			end
			self._records[recordKey] = nil
			self._count -= 1
			released += 1
		end
	end
	if released > 0 then publish(self, nil, owner) end
	return released, nil
end

function BudgetLedger:GetSnapshot(): Snapshot
	local reservations = {}
	for _, record in pairs(self._records) do table.insert(reservations, recordSnapshot(record)) end
	table.sort(reservations, function(left, right)
		if left.transactionId ~= right.transactionId then return left.transactionId < right.transactionId end
		if left.ownerId ~= right.ownerId then return left.ownerId < right.ownerId end
		return left.generation < right.generation
	end)
	return table.freeze({
		limits = copy(self._limits), reserved = copy(self._reserved), actual = copy(self._actual),
		reservationCount = self._count, maxReservations = self._maxReservations, reservations = table.freeze(reservations),
	}) :: any
end

return BudgetLedger

end

__modules["core/Capability"] = function()
--!strict

local StructuredError = __require("core/StructuredError")

type StructuredErrorValue = StructuredError.StructuredError

export type Name =
	"gethui"
	| "clipboardRead"
	| "clipboardWrite"
	| "httpRequest"
	| "storage"
	| "atomicReplace"
	| "journal"
	| "json"
	| "base64"
	| "image"
	| "localAssets"
	| "avatars"
	| "haptics"
	| "coreGui"
	| "playerGui"

export type Snapshot = {
	gethui: boolean,
	clipboardRead: boolean,
	clipboardWrite: boolean,
	httpRequest: boolean,
	storage: boolean,
	atomicReplace: boolean,
	journal: boolean,
	json: boolean,
	base64: boolean,
	image: boolean,
	localAssets: boolean,
	avatars: boolean,
	haptics: boolean,
	coreGui: boolean,
	playerGui: boolean,
}

export type Capability = {
	GetSnapshot: (self: Capability) -> Snapshot,
	Supports: (self: Capability, name: any) -> (boolean?, StructuredErrorValue?),
	Require: (self: Capability, name: any) -> (boolean, StructuredErrorValue?),
}

local Capability = {}
Capability.__index = Capability

local NAMES = table.freeze({
	"gethui", "clipboardRead", "clipboardWrite", "journal", "httpRequest", "storage", "atomicReplace",
	"json", "base64", "image", "localAssets", "avatars", "haptics", "coreGui", "playerGui",
})

local KNOWN = table.freeze({
	gethui = true,
	clipboardRead = true,
	clipboardWrite = true,
	journal = true,
	httpRequest = true,
	storage = true,
	atomicReplace = true,
	json = true,
	base64 = true,
	image = true,
	localAssets = true,
	avatars = true,
	haptics = true,
	coreGui = true,
	playerGui = true,
})

local function invalidName(name: any): StructuredErrorValue
	return StructuredError.from("unknown_capability", "Capability is not part of the closed capability snapshot", {
		domain = "capability",
		operation = "supports",
		details = { name = name },
	})
end

local function read(runtime: any, name: string): boolean
	if type(runtime) ~= "table" then
		return false
	end
	local capabilities = runtime.capabilities
	return type(capabilities) == "table" and capabilities[name] == true
end

function Capability.detect(runtime: any, overrides: any?): Capability
	local overrideValues = if type(overrides) == "table" then overrides else {}
	local snapshot: { [string]: boolean } = {}
	for _, name in ipairs(NAMES) do
		local overridden = overrideValues[name]
		snapshot[name] = if type(overridden) == "boolean" then overridden else read(runtime, name)
	end
	return setmetatable({ _snapshot = table.freeze(snapshot) }, Capability) :: any
end

Capability.new = Capability.detect

function Capability:GetSnapshot(): Snapshot
	return self._snapshot
end

function Capability:Supports(name: any): (boolean?, StructuredErrorValue?)
	if type(name) ~= "string" or KNOWN[name] ~= true then
		return nil, invalidName(name)
	end
	return self._snapshot[name], nil
end

function Capability:Require(name: any): (boolean, StructuredErrorValue?)
	local supported, capabilityError = self:Supports(name)
	if supported == nil then
		return false, capabilityError
	end
	if not supported then
		return false, StructuredError.from("capability_unavailable", "Required runtime capability is unavailable", {
			domain = "capability",
			operation = "require",
			details = { name = name },
		})
	end
	return true, nil
end

return Capability

end

__modules["core/DependencyGraph"] = function()
--!strict

local DependencyGraph = {}
DependencyGraph.__index = DependencyGraph

local Binding = {}
Binding.__index = Binding

local function failure(code: string, message: string)
	return { code = code, message = message }
end

local function copySources(sources: { string }): ({ string }?, any?)
	if type(sources) ~= "table" or #sources == 0 then
		return nil, failure("invalid_dependencies", "Dependencies require at least one control or id")
	end
	local result = {}
	local seen = {}
	for index, source in ipairs(sources) do
		if type(source) ~= "string" or source == "" then
			return nil,
				failure("invalid_dependency", "Dependency " .. tostring(index) .. " requires a non-empty control id")
		end
		if not seen[source] then
			seen[source] = true
			table.insert(result, source)
		end
	end
	return result, nil
end

function DependencyGraph.new(store: any): any
	assert(store ~= nil, "DependencyGraph requires a Store")
	local self = setmetatable({
		_store = store,
		_bindings = {} :: { [string]: { [string]: any } },
		_sourceBindings = {} :: { [string]: { [any]: true } },
		_dirtyBindings = {} :: { [any]: true },
		_draining = false,
		_destroyed = false,
		_unregisterConnection = nil,
		_changedConnection = nil,
	}, DependencyGraph)
	self._changedConnection = store.Changed:Connect(function(id: string)
		self:_enqueueSource(id)
	end)
	self._unregisterConnection = store.Unregistered:Connect(function(id: string)
		self:RemoveNode(id)
	end)
	return self
end

function DependencyGraph:_neighbors(node: string, replacingTarget: string, replacingKey: string): { string }
	local neighbors = {}
	for key, binding in pairs(self._bindings[node] or {}) do
		if not (node == replacingTarget and key == replacingKey) and binding.Connected then
			for _, source in ipairs(binding._sources) do
				neighbors[source] = true
			end
		end
	end
	local result = {}
	for source in pairs(neighbors) do
		table.insert(result, source)
	end
	table.sort(result)
	return result
end

function DependencyGraph:_reaches(start: string, goal: string, replacingTarget: string, replacingKey: string): boolean
	local pending = { start }
	local visited = {}
	while #pending > 0 do
		local node = table.remove(pending) :: string
		if node == goal then
			return true
		end
		if not visited[node] then
			visited[node] = true
			for _, nextNode in ipairs(self:_neighbors(node, replacingTarget, replacingKey)) do
				table.insert(pending, nextNode)
			end
		end
	end
	return false
end

function DependencyGraph:_addSources(binding: any)
	for _, source in ipairs(binding._sources) do
		local bindings = self._sourceBindings[source]
		if bindings == nil then
			bindings = {}
			self._sourceBindings[source] = bindings
		end
		bindings[binding] = true
	end
end

function DependencyGraph:_removeSources(binding: any)
	for _, source in ipairs(binding._sources) do
		local bindings = self._sourceBindings[source]
		if bindings then
			bindings[binding] = nil
			if next(bindings) == nil then
				self._sourceBindings[source] = nil
			end
		end
	end
	self._dirtyBindings[binding] = nil
end

function DependencyGraph:_sortDirtyBindings(): { any }
	local snapshot = {}
	for binding in pairs(self._dirtyBindings) do
		self._dirtyBindings[binding] = nil
		local targetBindings = self._bindings[binding._target]
		if binding.Connected and targetBindings and targetBindings[binding._key] == binding then
			table.insert(snapshot, binding)
		end
	end
	table.sort(snapshot, function(left, right)
		return left._target < right._target or (left._target == right._target and left._key < right._key)
	end)

	local included = {}
	local indegree = {}
	local dependents = {}
	for _, binding in ipairs(snapshot) do
		included[binding] = true
		indegree[binding] = 0
		dependents[binding] = {}
	end
	for _, binding in ipairs(snapshot) do
		for _, source in ipairs(binding._sources) do
			for _, producer in pairs(self._bindings[source] or {}) do
				if included[producer] then
					indegree[binding] += 1
					table.insert(dependents[producer], binding)
				end
			end
		end
	end

	local ready = {}
	for _, binding in ipairs(snapshot) do
		if indegree[binding] == 0 then
			table.insert(ready, binding)
		end
	end
	local ordered = {}
	while #ready > 0 do
		table.sort(ready, function(left, right)
			return left._target < right._target or (left._target == right._target and left._key < right._key)
		end)
		local binding = table.remove(ready, 1)
		table.insert(ordered, binding)
		for _, dependent in ipairs(dependents[binding]) do
			indegree[dependent] -= 1
			if indegree[dependent] == 0 then
				table.insert(ready, dependent)
			end
		end
	end
	return ordered
end

function DependencyGraph:_drain(): (boolean, any?)
	if self._draining then
		return true, nil
	end
	self._draining = true
	local passes = 0
	while next(self._dirtyBindings) ~= nil do
		passes += 1
		if passes > 1024 then
			self._draining = false
			return false,
				failure(
					"dependency_propagation_unstable",
					"Dependency propagation did not stabilize after 1024 topological passes"
				)
		end
		for _, binding in ipairs(self:_sortDirtyBindings()) do
			local ok, evaluationError = binding:_evaluate()
			if not ok then
				warn(evaluationError.message)
			end
		end
	end
	self._draining = false
	return true, nil
end

function DependencyGraph:_enqueueSource(source: string)
	for binding in pairs(self._sourceBindings[source] or {}) do
		if binding.Connected then
			self._dirtyBindings[binding] = true
		end
	end
	local drained, drainError = self:_drain()
	if not drained then
		warn(drainError.message)
	end
end

function DependencyGraph:_remove(binding: any)
	self:_removeSources(binding)
	local targetBindings = self._bindings[binding._target]
	if targetBindings and targetBindings[binding._key] == binding then
		targetBindings[binding._key] = nil
		if next(targetBindings) == nil then
			self._bindings[binding._target] = nil
		end
	end
end

function Binding:Disconnect()
	if not self.Connected then
		return
	end
	self.Connected = false
	self._owner:_remove(self)
end

Binding.Destroy = Binding.Disconnect

function Binding:_evaluate(): (boolean, any?)
	if not self.Connected then
		return true, nil
	end
	local values = table.create(#self._sources)
	for index, source in ipairs(self._sources) do
		local value, getError = self._owner._store:Get(source)
		if getError then
			return false, getError
		end
		values[index] = value
	end
	local ok, evaluationError = pcall(self._evaluateCallback, table.unpack(values, 1, #self._sources))
	if not ok then
		return false,
			failure(
				"dependency_evaluation_failed",
				"Dependency evaluation for " .. self._target .. " failed: " .. tostring(evaluationError)
			)
	end
	return true, nil
end

function DependencyGraph:RemoveNode(id: string)
	if self._destroyed then
		return
	end
	local bindings = {}
	for target, targetBindings in pairs(self._bindings) do
		for key, binding in pairs(targetBindings) do
			local matches = target == id
			if not matches then
				for _, source in ipairs(binding._sources) do
					if source == id then
						matches = true
						break
					end
				end
			end
			if matches then
				table.insert(bindings, { target = target, key = key, binding = binding })
			end
		end
	end
	table.sort(bindings, function(left, right)
		return left.target < right.target or (left.target == right.target and left.key < right.key)
	end)
	for _, entry in ipairs(bindings) do
		entry.binding:Disconnect()
	end
end

function DependencyGraph:Bind(
	target: string,
	key: string,
	sources: { string },
	evaluate: (...any) -> ()
): (any?, any?)
	if self._destroyed then
		return nil, failure("destroyed", "DependencyGraph has been destroyed")
	end
	if type(target) ~= "string" or target == "" then
		return nil, failure("invalid_target", "Dependency target requires a non-empty id")
	end
	if type(key) ~= "string" or key == "" then
		return nil, failure("invalid_binding_key", "Dependency binding requires a non-empty key")
	end
	if type(evaluate) ~= "function" then
		return nil, failure("invalid_evaluator", "Dependency evaluator must be a function")
	end
	local normalized, sourceError = copySources(sources)
	if normalized == nil then
		return nil, sourceError
	end
	for _, source in ipairs(normalized) do
		local _, getError = self._store:Get(source)
		if getError then
			return nil, getError
		end
		if self:_reaches(source, target, target, key) then
			return nil,
				failure(
					"dependency_cycle",
					"Dependency cycle rejected: " .. target .. " depends on " .. source
				)
		end
	end

	local targetBindings = self._bindings[target] or {}
	local previous = targetBindings[key]
	local binding = setmetatable({
		Connected = true,
		_owner = self,
		_target = target,
		_key = key,
		_sources = normalized,
		_evaluateCallback = evaluate,
	}, Binding)
	local evaluated, evaluationError = binding:_evaluate()
	if not evaluated then
		binding:Disconnect()
		return nil, evaluationError
	end
	if self._destroyed then
		binding:Disconnect()
		return nil, failure("destroyed", "DependencyGraph was destroyed during evaluation")
	end
	if (self._bindings[target] or {})[key] ~= previous then
		binding:Disconnect()
		return nil, failure("stale_binding", "Dependency binding changed during evaluation")
	end
	for _, source in ipairs(normalized) do
		local _, getError = self._store:Get(source)
		if getError then
			binding:Disconnect()
			return nil, getError
		end
	end
	if self._bindings[target] == nil then
		self._bindings[target] = targetBindings
	end
	targetBindings[key] = binding
	self:_addSources(binding)
	if previous then
		previous:Disconnect()
	end
	local drained, drainError = self:_drain()
	if not drained then
		warn(drainError.message)
	end
	return binding, nil
end

function DependencyGraph:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	if self._unregisterConnection then
		self._unregisterConnection:Disconnect()
		self._unregisterConnection = nil
	end
	if self._changedConnection then
		self._changedConnection:Disconnect()
		self._changedConnection = nil
	end
	local bindings = {}
	for _, targetBindings in pairs(self._bindings) do
		for _, binding in pairs(targetBindings) do
			table.insert(bindings, binding)
		end
	end
	for _, binding in ipairs(bindings) do
		binding:Disconnect()
	end
	table.clear(self._bindings)
	table.clear(self._sourceBindings)
	table.clear(self._dirtyBindings)
end

return DependencyGraph

end

__modules["core/Diagnostics"] = function()
--!strict

local Signal = __require("core/Signal")
local StructuredError = __require("core/StructuredError")

type StructuredErrorValue = StructuredError.StructuredError

export type RecordOptions = {
	severity: "debug" | "info" | "warn" | "error"?,
	transactionId: string?,
	ownerId: string?,
}

export type PublishOptions = {
	transactionId: string?,
	ownerId: string?,
}

export type SubscribeOptions = {
	emitInitial: boolean?,
}

export type Event = {
	sequence: number,
	domain: string,
	kind: string,
	severity: "debug" | "info" | "warn" | "error",
	timestamp: number,
	transactionId: string?,
	ownerId: string?,
	details: any?,
	error: StructuredErrorValue?,
}

export type DomainSnapshot = {
	revision: number,
	timestamp: number,
	transactionId: string?,
	ownerId: string?,
	value: any,
}

export type Snapshot = {
	revision: number,
	nextSequence: number,
	dropped: number,
	destroyed: boolean,
	events: { Event },
	domains: { [string]: DomainSnapshot },
}

export type Diagnostics = {
	Record: (self: Diagnostics, domain: any, kind: any, details: any?, errorValue: any?, options: RecordOptions?) -> (boolean, StructuredErrorValue?),
	Publish: (self: Diagnostics, domain: any, value: any, options: PublishOptions?) -> (boolean, StructuredErrorValue?),
	GetSnapshot: (self: Diagnostics) -> Snapshot,
	GetDomainSnapshot: (self: Diagnostics, domain: any) -> (DomainSnapshot?, StructuredErrorValue?),
	Subscribe: (self: Diagnostics, callback: (Snapshot) -> (), options: SubscribeOptions?) -> (Signal.Connection?, StructuredErrorValue?),
	Destroy: (self: Diagnostics) -> (),
	IsDestroyed: (self: Diagnostics) -> boolean,
}

export type Options = {
	clock: (() -> number)?,
	maxEvents: number?,
	maxDomains: number?,
}

local Diagnostics = {}
Diagnostics.__index = Diagnostics

local DEFAULT_MAX_EVENTS = 128
local DEFAULT_MAX_DOMAINS = 32
local MAX_EVENTS = 512
local MAX_DOMAINS = 128

local function finiteNumber(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

local function boundedInteger(value: any, default: number, maximum: number): number
	if not finiteNumber(value) then
		return default
	end
	return math.clamp(math.floor(value), 1, maximum)
end

local function identifier(value: any, field: string): (string?, StructuredErrorValue?)
	if type(value) ~= "string" or #value == 0 or #value > 129 then
		return nil, StructuredError.from("invalid_diagnostic_" .. field, "Diagnostic " .. field .. " must be a bounded identifier", {
			domain = "diagnostics",
		})
	end
	if string.match(value, "^[A-Za-z][A-Za-z0-9._:-]*$") == nil then
		return nil, StructuredError.from("invalid_diagnostic_" .. field, "Diagnostic " .. field .. " contains unsupported characters", {
			domain = "diagnostics",
		})
	end
	return value, nil
end

local function optionalIdentifier(value: any, field: string): (string?, StructuredErrorValue?)
	if value == nil then
		return nil, nil
	end
	return identifier(value, field)
end

local function severity(value: any): ("debug" | "info" | "warn" | "error"?, StructuredErrorValue?)
	if value == nil then
		return "info", nil
	end
	if value == "debug" or value == "info" or value == "warn" or value == "error" then
		return value, nil
	end
	return nil, StructuredError.from("invalid_diagnostic_severity", "Diagnostic severity must be debug, info, warn, or error", {
		domain = "diagnostics",
	})
end

local function now(self: any): number
	local ok, value = pcall(self._clock)
	if finiteNumber(value) then
		return value
	end
	return 0
end

local function copyEvent(event: Event): Event
	return table.freeze({
		sequence = event.sequence,
		domain = event.domain,
		kind = event.kind,
		severity = event.severity,
		timestamp = event.timestamp,
		transactionId = event.transactionId,
		ownerId = event.ownerId,
		details = if event.details == nil then nil else StructuredError.sanitize(event.details),
		error = if event.error == nil then nil else StructuredError.copy(event.error),
	}) :: any
end

local function copyDomainSnapshot(snapshot: DomainSnapshot): DomainSnapshot
	return table.freeze({
		revision = snapshot.revision,
		timestamp = snapshot.timestamp,
		transactionId = snapshot.transactionId,
		ownerId = snapshot.ownerId,
		value = StructuredError.sanitize(snapshot.value),
	}) :: any
end

function Diagnostics.new(options: Options?): Diagnostics
	local resolved = options or {}
	return setmetatable({
		_clock = if type(resolved.clock) == "function" then resolved.clock else os.clock,
		_maxEvents = boundedInteger(resolved.maxEvents, DEFAULT_MAX_EVENTS, MAX_EVENTS),
		_maxDomains = boundedInteger(resolved.maxDomains, DEFAULT_MAX_DOMAINS, MAX_DOMAINS),
		_events = {} :: { Event },
		_eventHead = 1,
		_eventCount = 0,
		_domains = {} :: { [string]: DomainSnapshot },
		_domainCount = 0,
		_nextSequence = 1,
		_revision = 0,
		_dropped = 0,
		_destroyed = false,
		_changed = Signal.new(),
	}, Diagnostics) :: any
end

function Diagnostics:_emit()
	if not self._destroyed then
		self._changed:Fire(self:GetSnapshot())
	end
end

function Diagnostics:_append(event: Event)
	local index
	if self._eventCount == self._maxEvents then
		index = self._eventHead
		self._eventHead = (self._eventHead % self._maxEvents) + 1
		self._dropped += 1
	else
		index = ((self._eventHead + self._eventCount - 1) % self._maxEvents) + 1
		self._eventCount += 1
	end
	self._events[index] = event
end

function Diagnostics:Record(domain: any, kind: any, details: any?, errorValue: any?, options: RecordOptions?): (boolean, StructuredErrorValue?)
	if self._destroyed then
		return false, StructuredError.from("destroyed", "Diagnostics has been destroyed", { domain = "diagnostics" })
	end
	local validDomain, domainError = identifier(domain, "domain")
	if validDomain == nil then return false, domainError end
	local validKind, kindError = identifier(kind, "kind")
	if validKind == nil then return false, kindError end
	local resolved = options or {}
	local validSeverity, severityError = severity(resolved.severity)
	if validSeverity == nil then return false, severityError end
	local transactionId, transactionError = optionalIdentifier(resolved.transactionId, "transaction_id")
	if transactionError ~= nil then return false, transactionError end
	local ownerId, ownerError = optionalIdentifier(resolved.ownerId, "owner_id")
	if ownerError ~= nil then return false, ownerError end

	local event = {
		sequence = self._nextSequence,
		domain = validDomain,
		kind = validKind,
		severity = validSeverity,
		timestamp = now(self),
		transactionId = transactionId,
		ownerId = ownerId,
		details = if details == nil then nil else StructuredError.sanitize(details),
		error = if errorValue == nil then nil else StructuredError.copy(errorValue),
	}
	self._nextSequence += 1
	self._revision += 1
	self:_append(table.freeze(event) :: any)
	self:_emit()
	return true, nil
end

function Diagnostics:Publish(domain: any, value: any, options: PublishOptions?): (boolean, StructuredErrorValue?)
	if self._destroyed then
		return false, StructuredError.from("destroyed", "Diagnostics has been destroyed", { domain = "diagnostics" })
	end
	local validDomain, domainError = identifier(domain, "domain")
	if validDomain == nil then return false, domainError end
	local resolved = options or {}
	local transactionId, transactionError = optionalIdentifier(resolved.transactionId, "transaction_id")
	if transactionError ~= nil then return false, transactionError end
	local ownerId, ownerError = optionalIdentifier(resolved.ownerId, "owner_id")
	if ownerError ~= nil then return false, ownerError end
	if self._domains[validDomain] == nil then
		if self._domainCount >= self._maxDomains then
			return false, StructuredError.from("diagnostic_domain_limit", "Diagnostics domain limit has been reached", {
				domain = "diagnostics",
				details = { maxDomains = self._maxDomains },
			})
		end
		self._domainCount += 1
	end
	self._revision += 1
	self._domains[validDomain] = table.freeze({
		revision = self._revision,
		timestamp = now(self),
		transactionId = transactionId,
		ownerId = ownerId,
		value = StructuredError.sanitize(value),
	}) :: any
	self:_emit()
	return true, nil
end

function Diagnostics:GetSnapshot(): Snapshot
	local events = {}
	for offset = 0, self._eventCount - 1 do
		local index = ((self._eventHead + offset - 1) % self._maxEvents) + 1
		events[offset + 1] = copyEvent(self._events[index])
	end
	local domains = {}
	local names = {}
	for name in pairs(self._domains) do
		table.insert(names, name)
	end
	table.sort(names)
	for _, name in ipairs(names) do
		domains[name] = copyDomainSnapshot(self._domains[name])
	end
	return table.freeze({
		revision = self._revision,
		nextSequence = self._nextSequence,
		dropped = self._dropped,
		destroyed = self._destroyed,
		events = table.freeze(events),
		domains = table.freeze(domains),
	}) :: any
end

function Diagnostics:GetDomainSnapshot(domain: any): (DomainSnapshot?, StructuredErrorValue?)
	local validDomain, domainError = identifier(domain, "domain")
	if validDomain == nil then return nil, domainError end
	local snapshot = self._domains[validDomain]
	if snapshot == nil then
		return nil, StructuredError.from("unknown_diagnostic_domain", "No diagnostic snapshot exists for the requested domain", {
			domain = "diagnostics",
			details = { domain = validDomain },
		})
	end
	return copyDomainSnapshot(snapshot), nil
end

function Diagnostics:Subscribe(callback: (Snapshot) -> (), options: SubscribeOptions?): (Signal.Connection?, StructuredErrorValue?)
	if self._destroyed then
		return nil, StructuredError.from("destroyed", "Diagnostics has been destroyed", { domain = "diagnostics" })
	end
	if type(callback) ~= "function" then
		return nil, StructuredError.from("invalid_diagnostic_callback", "Diagnostics callback must be a function", { domain = "diagnostics" })
	end
	local connection = self._changed:Connect(callback)
	if options ~= nil and options.emitInitial == true then
		local ok, callbackError = xpcall(callback, debug.traceback, self:GetSnapshot())
		if not ok then
			warn("PotassiumUI Diagnostics callback failed:\n" .. tostring(callbackError))
		end
	end
	return connection, nil
end

function Diagnostics:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	self._events = {}
	self._domains = {}
	self._eventCount = 0
	self._domainCount = 0
	self._changed:Destroy()
end

function Diagnostics:IsDestroyed(): boolean
	return self._destroyed
end

return Diagnostics

end

__modules["core/EditSession"] = function()
--!strict

local Signal = __require("core/Signal")
local StructuredError = __require("core/StructuredError")

export type EditSnapshot = {
	id: string,
	generation: number,
	draft: any,
	original: any,
	validation: any,
	submitting: boolean,
	revision: number,
}

local EditSession = {}
EditSession.__index = EditSession

local MAX_COPY_DEPTH = 64
local MAX_COPY_ENTRIES = 4096

local function copy(value: any, depth: number?, seen: { [table]: boolean }?): any
	local currentDepth = depth or 0
	local visited = seen or {}
	if type(value) ~= "table" then
		return value
	end
	if currentDepth >= MAX_COPY_DEPTH then
		error("edit value exceeds maximum depth")
	end
	if visited[value] then
		error("edit value contains a cycle")
	end
	visited[value] = true
	local result = {}
	local count = 0
	for key, item in pairs(value) do
		count += 1
		if count > MAX_COPY_ENTRIES then
			error("edit value exceeds maximum entries")
		end
		if type(key) ~= "string" and type(key) ~= "number" then
			error("edit value contains an unsupported key")
		end
		result[key] = copy(item, currentDepth + 1, visited)
	end
	visited[value] = nil
	return table.freeze(result)
end

local function errorValue(code: string, message: string, operation: string, details: any?): any
	return StructuredError.from(code, message, {
		domain = "edit",
		operation = operation,
		details = details,
	})
end

local function copyValue(value: any, operation: string): (any?, any?)
	local ok, copied = pcall(copy, value)
	if ok then
		return copied, nil
	end
	return nil, errorValue("edit_value_rejected", tostring(copied), operation)
end

local function isCurrent(self: any, id: string, entry: any, generation: number): boolean
	return not self._destroyed and self._entries[id] == entry and entry.generation == generation
end

local function staleEditError(id: string): any
	return errorValue("stale_edit", "Edit changed or ended while committing", "commit", { id = id })
end


local function makeSnapshot(entry: any): EditSnapshot
	return table.freeze({
		id = entry.id,
		generation = entry.generation,
		draft = copy(entry.draft),
		original = copy(entry.original),
		validation = copy(entry.validation),
		submitting = entry.submitting,
		revision = entry.revision,
	})
end

function EditSession.new(): any
	return setmetatable({
		_entries = {},
		_destroyed = false,
	}, EditSession)
end

function EditSession:_publish(entry: any)
	entry.signal:Fire(makeSnapshot(entry))
end

function EditSession:Begin(id: string, initial: any, options: any?): (EditSnapshot?, any?)
	if self._destroyed then
		return nil, errorValue("destroyed", "EditSession is destroyed", "begin")
	end
	if type(id) ~= "string" or id == "" or self._entries[id] then
		return nil, errorValue("invalid_edit", "Edit id must be unique and nonempty", "begin", { id = id })
	end

	local sourceOptions = {}
	if type(options) == "table" then
		sourceOptions = options
	end
	local original, copyError = copyValue(initial, "begin")
	if copyError then
		return nil, copyError
	end
	local store = sourceOptions.store
	local storeId = sourceOptions.storeId or id
	if store ~= nil and type(store.Get) ~= "function" then
		return nil, errorValue("invalid_store", "EditSession store must expose Get", "begin")
	end
	if store ~= nil and initial == nil then
		local storeValue, storeError = store:Get(storeId)
		if storeError then
			return nil, storeError
		end
		original, copyError = copyValue(storeValue, "begin")
		if copyError then
			return nil, copyError
		end
	end
	local entry = {
		id = id,
		original = original,
		draft = copy(original),
		validation = nil,
		generation = 0,
		revision = 0,
		submitting = false,
		signal = Signal.new(),
		validator = sourceOptions.validate,
		committer = sourceOptions.commit,
		store = store,
		storeId = storeId,
		source = sourceOptions.source or "user",
	}
	self._entries[id] = entry
	return makeSnapshot(entry), nil
end

function EditSession:Get(id: string): (EditSnapshot?, any?)
	local entry = self._entries[id]
	if not entry then
		return nil, errorValue("unknown_edit", "Edit id is not active", "get", { id = id })
	end
	return makeSnapshot(entry), nil
end

function EditSession:Observe(id: string, callback: (EditSnapshot) -> (), options: any?): (any?, any?)
	local entry = self._entries[id]
	if not entry or type(callback) ~= "function" then
		return nil, errorValue("invalid_observation", "Known edit id and callback are required", "observe", { id = id })
	end
	local connection = entry.signal:Connect(callback)
	if type(options) == "table" and options.EmitInitial == true then
		callback(makeSnapshot(entry))
	end
	return connection, nil
end

function EditSession:Update(id: string, draft: any): (EditSnapshot?, any?)
	local entry = self._entries[id]
	if not entry then
		return nil, errorValue("unknown_edit", "Edit id is not active", "update", { id = id })
	end
	local copiedDraft, copyError = copyValue(draft, "update")
	if copyError then
		return nil, copyError
	end
	if entry.submitting then
		entry.generation += 1
		entry.submitting = false
	end
	entry.draft = copiedDraft
	entry.validation = nil
	entry.revision += 1
	self:_publish(entry)
	return makeSnapshot(entry), nil
end

function EditSession:Validate(id: string): (any?, any?)
	local entry = self._entries[id]
	if not entry then
		return nil, errorValue("unknown_edit", "Edit id is not active", "validate", { id = id })
	end
	local generation, revision = entry.generation, entry.revision
	if type(entry.validator) ~= "function" then
		entry.validation = table.freeze({ valid = true })
	else
		local draft, copyError = copyValue(entry.draft, "validate")
		if copyError then
			return nil, copyError
		end
		local ok, value = xpcall(entry.validator, debug.traceback, draft)
		if not isCurrent(self, id, entry, generation) or entry.revision ~= revision then
			return nil, errorValue("stale_edit", "Edit changed or ended while validating", "validate", { id = id })
		end
		if ok then
			local validation, validationCopyError = copyValue(value or { valid = true }, "validate")
			if validationCopyError then
				return nil, validationCopyError
			end
			entry.validation = validation
		else
			entry.validation = table.freeze({ valid = false, error = tostring(value) })
		end
	end
	entry.revision += 1
	self:_publish(entry)
	return copy(entry.validation), nil
end

function EditSession:Commit(id: string, options: any?): (number?, any?)
	local entry = self._entries[id]
	if not entry then
		return nil, errorValue("unknown_edit", "Edit id is not active", "commit", { id = id })
	end
	local validationGeneration = entry.generation
	local validationRevision = entry.revision
	local validation, validationError = self:Validate(id)
	if validationError then
		return nil, validationError
	end
	if not isCurrent(self, id, entry, validationGeneration) or entry.revision ~= validationRevision + 1 then
		return nil, staleEditError(id)
	end
	if type(validation) == "table" and validation.valid == false then
		return nil, errorValue("validation_failed", "Draft validation failed", "commit", { id = id, validation = validation })
	end

	local draft = copy(entry.draft)
	entry.generation += 1
	local generation = entry.generation
	entry.submitting = true
	self:_publish(entry)
	if not isCurrent(self, id, entry, generation) then
		return nil, staleEditError(id)
	end

	local committer = entry.committer
	local source = entry.source
	if type(options) == "table" then
		if type(options.commit) == "function" then
			committer = options.commit
		end
		if options.source ~= nil then
			source = options.source
		end
	end
	if type(committer) ~= "function" then
		if type(entry.store) == "table" and type(entry.store.Set) == "function" then
			local stored, storeError = entry.store:Set(entry.storeId, draft, source)
			if not stored then
				if isCurrent(self, id, entry, generation) then
					entry.submitting = false
					entry.validation = table.freeze({ valid = false, error = storeError })
					entry.revision += 1
					self:_publish(entry)
				end
				return nil, storeError
			end
			if not isCurrent(self, id, entry, generation) then
				return nil, staleEditError(id)
			end
		end
		entry.submitting = false
		entry.original = copy(draft)
		entry.revision += 1
		self:_publish(entry)
		return generation, nil
	end

	task.spawn(function()
		local context = table.freeze({
			id = id,
			generation = generation,
			IsCancelled = function(): boolean
				return not isCurrent(self, id, entry, generation)
			end,
		})
		local ok, result = xpcall(committer, debug.traceback, draft, context)
		if context.IsCancelled() then
			return
		end
		if ok then
			local committedValue = if result == nil then draft else result
			local committedCopy, copyError = copyValue(committedValue, "commit")
			if copyError then
				entry.submitting = false
				entry.validation = table.freeze({ valid = false, error = copyError })
			elseif type(entry.store) == "table" and type(entry.store.Set) == "function" then
				local stored, storeError = entry.store:Set(entry.storeId, committedCopy, source)
				if not stored then
					if not isCurrent(self, id, entry, generation) then
						return
					end
					entry.submitting = false
					entry.validation = table.freeze({ valid = false, error = storeError })
				elseif not isCurrent(self, id, entry, generation) then
					if not self._destroyed and self._entries[id] == entry and not entry.submitting then
						entry.original = committedCopy
						entry.validation = nil
						entry.revision += 1
						self:_publish(entry)
					end
					return
				else
					entry.submitting = false
					entry.original = committedCopy
					entry.draft = copy(committedCopy)
					entry.validation = table.freeze({ valid = true })
				end
			else
				entry.submitting = false
				entry.original = committedCopy
				entry.draft = copy(committedCopy)
				entry.validation = table.freeze({ valid = true })
			end
		else
			entry.submitting = false
			entry.validation = table.freeze({ valid = false, error = tostring(result) })
		end
		if not isCurrent(self, id, entry, generation) then
			return
		end
		entry.revision += 1
		self:_publish(entry)
	end)
	return generation, nil
end

function EditSession:Revert(id: string): (EditSnapshot?, any?)
	local entry = self._entries[id]
	if not entry then
		return nil, errorValue("unknown_edit", "Edit id is not active", "revert", { id = id })
	end
	if entry.submitting then
		entry.generation += 1
		entry.submitting = false
	end
	entry.draft = copy(entry.original)
	entry.validation = nil
	entry.revision += 1
	self:_publish(entry)
	return makeSnapshot(entry), nil
end

function EditSession:End(id: string): (boolean, any?)
	local entry = self._entries[id]
	if entry == nil then
		return false, errorValue("unknown_edit", "Edit id is not active", "end", { id = id })
	end
	if entry.submitting then
		entry.generation += 1
		entry.submitting = false
	end
	entry.signal:Destroy()
	self._entries[id] = nil
	return true, nil
end

function EditSession:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	for _, entry in pairs(self._entries) do
		if entry.submitting then
			entry.generation += 1
		end
		entry.signal:Destroy()
	end
	table.clear(self._entries)
end

return EditSession

end

__modules["core/ExtensionHost"] = function()
--!strict

local StructuredError = __require("core/StructuredError")
type StructuredErrorValue = StructuredError.StructuredError

export type PackState = "staged" | "installed" | "draining" | "uninstalled"
export type ExtensionHost = any
local ExtensionHost = {}
ExtensionHost.__index = ExtensionHost

local MAX_PACKS, MAX_CONTRIBUTIONS = 128, 256
local LOCAL, NAMESPACED = "^[A-Za-z][A-Za-z0-9._-]*$", "^[A-Za-z][A-Za-z0-9._-]*:[A-Za-z][A-Za-z0-9._-]*$"

local function fail(code: string, message: string, operation: string, ownerId: string?, details: any?): StructuredErrorValue
	return StructuredError.from(code, message, { domain = "extension_host", operation = operation, ownerId = ownerId, details = details })
end
local function localId(value: any): string?
	if type(value) ~= "string" or #value > 64 or string.match(value, LOCAL) == nil then return nil end
	if string.sub(value, 1, 5) == "host." or string.sub(value, 1, 7) == "system." or string.sub(value, 1, 7) == "legacy." then return nil end
	return value
end
local function packId(value: any): string?
	return if type(value) == "string" and #value <= 129 and string.match(value, NAMESPACED) ~= nil then value else nil
end
local function positive(value: any, maximum: number): boolean
	return type(value) == "number" and value == math.floor(value) and value >= 1 and value <= maximum
end

local function portable(value: any, state: any?, depth: number?): (any?, string?)
	local s = state or { seen = {}, nodes = 0, entries = 0, bytes = 0 }
	local d = depth or 0
	local kind = type(value)
	if kind == "nil" or kind == "boolean" then return value, nil end
	if kind == "number" then
		if value ~= value or value == math.huge or value == -math.huge then return nil, "nonfinite" end
		return value, nil
	end
	if kind == "string" then s.bytes += #value if #value > 8192 or s.bytes > 1048576 then return nil, "string_limit" end return value, nil end
	if kind ~= "table" or getmetatable(value) ~= nil then return nil, "nonportable" end
	if d >= 32 or s.seen[value] then return nil, if s.seen[value] then "cycle" else "depth_limit" end
	s.nodes += 1 if s.nodes > 4096 then return nil, "node_limit" end
	s.seen[value] = true
	local keys, count = {}, 0
	for key in next, value do
		count += 1
		if count > 512 or (type(key) ~= "string" and type(key) ~= "number") or (type(key) == "string" and #key > 128) then s.seen[value] = nil return nil, "table_limit" end
		table.insert(keys, key)
	end
	s.entries += count if s.entries > 16384 then s.seen[value] = nil return nil, "entry_limit" end
	table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
	local output = {}
	for _, key in ipairs(keys) do
		local copied, reason = portable(value[key], s, d + 1)
		if reason ~= nil then s.seen[value] = nil return nil, reason end
		output[key] = copied
	end
	s.seen[value] = nil
	return table.freeze(output), nil
end

local function snapshot(record: any): any
	local contributions = {}
	for id, value in pairs(record.contributions) do contributions[id] = value end
	return table.freeze({ id = record.id, manifest = record.manifest, state = record.state, pinnedVersion = record.pinnedVersion, installedAt = record.installedAt, liveMounts = record.liveMounts, contributions = table.freeze(contributions), diagnostics = record.diagnostics, generation = record.generation })
end
local function publish(self: any, kind: string, record: any)
	if type(self._diagnostics) ~= "table" then return end
	pcall(function()
		self._diagnostics:Record("extension_host", kind, { id = record.id, state = record.state, generation = record.generation, liveMounts = record.liveMounts }, nil, { ownerId = record.id })
		self._diagnostics:Publish("extension_host", self:GetSnapshot(), { ownerId = record.id })
	end)
end
local function ownerToken(self: any, value: any): (any?, any?, StructuredErrorValue?)
	if type(value) ~= "table" or value._host ~= self or value._released then return nil, nil, fail("invalid_owner_token", "Owner token is not live for this ExtensionHost", "owner") end
	if value._owner ~= nil then
		if value._owner._released then return nil, nil, fail("invalid_owner_token", "Owner scope is not live", "owner") end
		return value._owner, value, nil
	end
	return value, nil, nil
end
local function uninstall(self: any, record: any)
	if record.state == "uninstalled" then return end
	record.state, record.contributions, record._trusted = "uninstalled", {}, {}
	record.generation += 1
	if type(self._budget) == "table" and type(self._budget.ReleaseOwner) == "function" then pcall(function() self._budget:ReleaseOwner(record.id) end) end
	publish(self, "uninstalled", record)
end

function ExtensionHost.new(options: any?): (any?, StructuredErrorValue?)
	local resolved = options or {}
	if type(resolved) ~= "table" then return nil, fail("invalid_extension_host_options", "ExtensionHost options must be a table", "create") end
	local maxPacks, maxContributions = resolved.maxPacks or MAX_PACKS, resolved.maxContributionsPerPack or MAX_CONTRIBUTIONS
	if not positive(maxPacks, MAX_PACKS) or not positive(maxContributions, MAX_CONTRIBUTIONS) then return nil, fail("invalid_extension_host_limits", "ExtensionHost limits must be bounded positive integers", "create") end
	return setmetatable({ _packs = {}, _count = 0, _owners = {}, _maxPacks = maxPacks, _maxContributions = maxContributions, _diagnostics = resolved.diagnostics, _budget = resolved.budgetLedger, _capability = resolved.capability, _clock = if type(resolved.clock) == "function" then resolved.clock else os.clock, _destroyed = false }, ExtensionHost), nil
end

function ExtensionHost:CreateOwner(value: any): (any?, StructuredErrorValue?)
	if self._destroyed then return nil, fail("destroyed", "ExtensionHost has been destroyed", "create_owner") end
	local id = localId(value)
	if id == nil then return nil, fail("invalid_owner_id", "Owner id must be a LocalId", "create_owner") end
	if self._owners[id] ~= nil then return nil, fail("duplicate_owner", "Owner id is already registered", "create_owner", id) end
	local owner = { _host = self, _id = id, _released = false, _scopes = {}, _mounts = {} }
	function owner:Release(): boolean
		if self._released then return false end
		self._released = true
		for scope in pairs(self._scopes) do scope:Release() end
		for mount in pairs(self._mounts) do mount:Unmount() end
		if self._host._owners[self._id] == self then self._host._owners[self._id] = nil end
		return true
	end
	self._owners[id] = owner
	return owner, nil
end
function ExtensionHost:CreateScope(owner: any): (any?, StructuredErrorValue?)
	local token, _, tokenError = ownerToken(self, owner)
	if token == nil then return nil, tokenError end
	local scope = { _host = self, _owner = token, _released = false, _mounts = {} }
	function scope:Release(): boolean
		if self._released then return false end
		self._released = true
		for mount in pairs(self._mounts) do mount:Unmount() end
		self._owner._scopes[self] = nil
		return true
	end
	token._scopes[scope] = true
	return scope, nil
end

function ExtensionHost:Stage(manifest: any, contributionList: any?, options: any?): (any?, StructuredErrorValue?)
	if self._destroyed then return nil, fail("destroyed", "ExtensionHost has been destroyed", "stage") end
	local safeManifest, manifestReason = portable(manifest)
	if safeManifest == nil or type(safeManifest) ~= "table" then return nil, fail("portable_input_limit", "Manifest is not bounded portable data", "stage", nil, { reason = manifestReason }) end
	local id = packId(safeManifest.id)
	if id == nil then return nil, fail("invalid_pack_id", "Manifest id must be a NamespacedId", "stage") end
	local prior = self._packs[id]
	local replacing = type(options) == "table" and options._replaceExisting == true
	if prior ~= nil and prior.state ~= "uninstalled" and (not replacing or prior.state ~= "installed" or prior.liveMounts ~= 0) then return nil, fail("duplicate_pack", "Pack is already staged or installed", "stage", id) end
	if prior == nil and self._count >= self._maxPacks then return nil, fail("pack_limit", "Pack capacity has been reached", "stage") end
	if contributionList ~= nil and type(contributionList) ~= "table" then return nil, fail("invalid_contributions", "Contributions must be a list", "stage", id) end
	local list = contributionList or {}
	local length, entries = #list, 0
	for key in pairs(list) do
		if type(key) ~= "number" or key % 1 ~= 0 or key < 1 or key > length then return nil, fail("invalid_contributions", "Contributions must be a dense list", "stage", id) end
		entries += 1
	end
	if entries ~= length then return nil, fail("invalid_contributions", "Contributions must be a dense list", "stage", id) end
	local contributions, count = {}, 0
	for _, raw in ipairs(contributionList or {}) do
		local contribution, reason = portable(raw)
		if contribution == nil or type(contribution) ~= "table" or packId(contribution.id) == nil or type(contribution.kind) ~= "string" then return nil, fail("invalid_contribution", "Contribution must be a portable descriptor", "stage", id, { reason = reason }) end
		if contributions[contribution.id] ~= nil then return nil, fail("duplicate_contribution", "Contribution ids must be unique", "stage", id) end
		count += 1 if count > self._maxContributions then return nil, fail("contribution_limit", "Contribution capacity has been reached", "stage", id) end
		contributions[contribution.id] = contribution
	end
	local record = { id = id, manifest = safeManifest, state = "staged" :: PackState, pinnedVersion = safeManifest.version, installedAt = nil, liveMounts = 0, contributions = contributions, _trusted = {}, diagnostics = table.freeze({}), generation = if prior == nil then 1 else prior.generation + 1 }
	self._packs[id] = record
	if prior == nil then self._count += 1 end
	publish(self, "staged", record)
	return snapshot(record), nil
end
function ExtensionHost:Discard(value: any): (boolean, StructuredErrorValue?)
	if self._destroyed then return false, fail("destroyed", "ExtensionHost has been destroyed", "discard") end
	local id = packId(value)
	local record = if id ~= nil then self._packs[id] else nil
	if record == nil or record.state ~= "staged" then
		return false, fail("invalid_pack_transition", "Only staged packs may be discarded", "discard", id)
	end
	self._packs[id] = nil
	self._count -= 1
	if type(self._budget) == "table" and type(self._budget.ReleaseOwner) == "function" then
		pcall(function() self._budget:ReleaseOwner(record.id) end)
	end
	record.state, record.contributions, record._trusted = "uninstalled", {}, {}
	record.generation += 1
	publish(self, "uninstalled", record)
	return true, nil
end

function ExtensionHost:Install(value: any): (boolean, StructuredErrorValue?)
	local id = packId(value); local record = if id ~= nil then self._packs[id] else nil
	if record == nil or record.state ~= "staged" then return false, fail("invalid_pack_transition", "Only staged packs may be installed", "install", id) end
	local ok, installedAt = pcall(self._clock)
	record.state, record.installedAt, record.generation = "installed", if ok and type(installedAt) == "number" then installedAt else 0, record.generation + 1
	publish(self, "installed", record)
	return true, nil
end
function ExtensionHost:Upgrade(manifest: any, contributions: any?, _: any?): (any?, StructuredErrorValue?)
	local staged, stageError = self:Stage(manifest, contributions, { _replaceExisting = true })
	if staged == nil then return nil, stageError end
	local installed, installError = self:Install(staged.id)
	if not installed then return nil, installError end
	return self:GetPackSnapshot(staged.id)
end
function ExtensionHost:Drain(value: any): (boolean, StructuredErrorValue?)
	local id = packId(value); local record = if id ~= nil then self._packs[id] else nil
	if record == nil then return false, fail("unknown_pack", "Pack does not exist", "drain") end
	if record.state == "uninstalled" then return true, nil end
	if record.state ~= "installed" and record.state ~= "draining" then return false, fail("invalid_pack_transition", "Only installed packs may drain", "drain", id) end
	if record.state == "installed" then record.state, record.generation = "draining", record.generation + 1; publish(self, "draining", record) end
	if record.liveMounts == 0 then uninstall(self, record) end
	return true, nil
end
ExtensionHost.Uninstall = ExtensionHost.Drain

function ExtensionHost:Mount(value: any, owner: any): (any?, StructuredErrorValue?)
	local id = packId(value); local record = if id ~= nil then self._packs[id] else nil
	if record == nil or record.state ~= "installed" then return nil, fail("pack_not_mountable", "Only installed packs may mount", "mount", id) end
	local token, scope, tokenError = ownerToken(self, owner)
	if token == nil then return nil, tokenError end
	record.liveMounts += 1
	local mount = { _host = self, _record = record, _owner = token, _scope = scope, _released = false, generation = record.generation }
	function mount:Unmount(): boolean
		if self._released then return false end
		self._released = true; self._owner._mounts[self] = nil
		if self._scope ~= nil then self._scope._mounts[self] = nil end
		if self._record.liveMounts > 0 then self._record.liveMounts -= 1 end
		if self._record.state == "draining" and self._record.liveMounts == 0 then uninstall(self._host, self._record) else publish(self._host, "unmounted", self._record) end
		return true
	end
	mount.Destroy = mount.Unmount; token._mounts[mount] = true
	if scope ~= nil then scope._mounts[mount] = true end
	publish(self, "mounted", record)
	return mount, nil
end

function ExtensionHost:AddContribution(value: any, raw: any, owner: any?): (boolean, StructuredErrorValue?)
	local id = packId(value); local record = if id ~= nil then self._packs[id] else nil
	if record == nil or record.state ~= "staged" then return false, fail("invalid_pack_transition", "Contributions may change only while staged", "add_contribution", id) end
	if owner ~= nil then local token, _, tokenError = ownerToken(self, owner); if token == nil then return false, tokenError end end
	local contribution, reason = portable(raw)
	if contribution == nil or type(contribution) ~= "table" or packId(contribution.id) == nil or type(contribution.kind) ~= "string" then return false, fail("invalid_contribution", "Contribution must be portable", "add_contribution", id, { reason = reason }) end
	if record.contributions[contribution.id] ~= nil then return false, fail("duplicate_contribution", "Contribution id is already owned", "add_contribution", id) end
	local count = 0; for _ in pairs(record.contributions) do count += 1 end
	if count >= self._maxContributions then return false, fail("contribution_limit", "Contribution capacity has been reached", "add_contribution", id) end
	record.contributions[contribution.id], record.generation = contribution, record.generation + 1
	publish(self, "contribution_added", record); return true, nil
end
function ExtensionHost:RemoveContribution(value: any, contributionId: any, owner: any?): (boolean, StructuredErrorValue?)
	local id, cid = packId(value), packId(contributionId); local record = if id ~= nil then self._packs[id] else nil
	if record == nil or record.state ~= "staged" then return false, fail("invalid_pack_transition", "Contributions may change only while staged", "remove_contribution", id) end
	if owner ~= nil then local token, _, tokenError = ownerToken(self, owner); if token == nil then return false, tokenError end end
	if cid == nil or record.contributions[cid] == nil then return false, fail("unknown_contribution", "Contribution is not owned", "remove_contribution", id) end
	record.contributions[cid], record._trusted[cid], record.generation = nil, nil, record.generation + 1
	publish(self, "contribution_removed", record); return true, nil
end
function ExtensionHost:RegisterTrustedControl(value: any, contribution: any, factory: any, owner: any?): (boolean, StructuredErrorValue?)
	if type(factory) ~= "function" then return false, fail("invalid_control_factory", "Legacy control factory must be trusted function", "register_trusted_control") end
	if type(contribution) ~= "table" or contribution.kind ~= "control" then return false, fail("invalid_contribution", "Trusted control requires a control descriptor", "register_trusted_control") end
	local added, addError = self:AddContribution(value, contribution, owner)
	if not added then return false, addError end
	local id, cid = packId(value), packId(contribution.id); local record = if id ~= nil then self._packs[id] else nil
	if record == nil or cid == nil then return false, fail("unknown_pack", "Pack does not exist", "register_trusted_control") end
	record._trusted[cid] = factory
	return true, nil
end
function ExtensionHost:InvokeTrustedControl(value: any, contributionId: any, section: any, options: any?): (any?, StructuredErrorValue?)
	local id, cid = packId(value), packId(contributionId); local record = if id ~= nil then self._packs[id] else nil
	if record == nil or record.state ~= "installed" or cid == nil then return nil, fail("pack_not_mountable", "Trusted control requires installed pack", "invoke_trusted_control", id) end
	local factory = record._trusted[cid]
	if type(factory) ~= "function" then return nil, fail("unresolved_callback", "Trusted control callback is not registered", "invoke_trusted_control", id) end
	local ok, result = pcall(factory, section, options)
	if not ok then return nil, fail("legacy_control_failed", "Legacy control factory failed", "invoke_trusted_control", id, { controlId = cid }) end
	return result, nil
end
function ExtensionHost:GetPackSnapshot(value: any): (any?, StructuredErrorValue?)
	local id = packId(value); local record = if id ~= nil then self._packs[id] else nil
	if record == nil then return nil, fail("unknown_pack", "Pack does not exist", "get_snapshot") end
	return snapshot(record), nil
end
function ExtensionHost:GetSnapshot(): any
	local packs = {}; for id, record in pairs(self._packs) do packs[id] = snapshot(record) end
	return table.freeze({ destroyed = self._destroyed, packCount = self._count, packs = table.freeze(packs) })
end
function ExtensionHost:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	for _, record in pairs(self._packs) do uninstall(self, record) end
	for _, owner in pairs(self._owners) do owner:Release() end
end

return ExtensionHost

end

__modules["core/FocusManager"] = function()
--!strict

export type Direction = "Left" | "Right" | "Up" | "Down"

export type FocusOptions = {
	order: number,
	group: string?,
	owner: any?,
	eligible: ((object: GuiObject) -> boolean)?,
	onFocusChanged: ((focused: boolean, reason: string) -> ())?,
}

type FocusEntry = {
	connections: { RBXScriptConnection },
	eligible: ((object: GuiObject) -> boolean)?,
	group: string,
	id: string,
	object: GuiObject,
	owner: any?,
	onFocusChanged: ((focused: boolean, reason: string) -> ())?,
	order: number,
}

type ModalFocus = {
	id: string,
	owner: any?,
	previous: GuiObject?,
	scope: GuiObject?,
}

export type FocusManager = {
	Register: (self: FocusManager, id: string, object: GuiObject, options: FocusOptions) -> (),
	Unregister: (self: FocusManager, id: string) -> (),
	SetInitialFocus: (self: FocusManager, group: string?) -> GuiObject?,
	FocusDirectional: (self: FocusManager, direction: Direction) -> GuiObject?,
	SetFocused: (self: FocusManager, object: GuiObject?, reason: string?) -> boolean,
	IsEligible: (self: FocusManager, object: GuiObject) -> boolean,
	SetEligibilityGate: (self: FocusManager, gate: ((object: GuiObject, entry: any?) -> boolean)?) -> (),
	PushModal: (self: FocusManager, id: string, initialFocus: GuiObject?, owner: any?) -> (),
	PopModal: (self: FocusManager, id: string) -> (),
	CloseOwned: (self: FocusManager, owner: any, reason: string?) -> (),
	Destroy: (self: FocusManager) -> (),
}

local FocusManager = {}
FocusManager.__index = FocusManager

local function addToMaid(maid: any, task: any)
	if maid == nil then
		return
	end
	if type(maid.GiveTask) == "function" then
		maid:GiveTask(task)
	elseif type(maid.Add) == "function" then
		maid:Add(task)
	end
end

local function isGamepad(inputType: Enum.UserInputType): boolean
	return inputType.Name:match("^Gamepad") ~= nil
end

function FocusManager.new(runtime: any, maid: any): FocusManager
	local services = if runtime and runtime.services then runtime.services else {}
	local guiService = services.GuiService or game:GetService("GuiService")
	local userInputService = services.UserInputService or game:GetService("UserInputService")
	local self = setmetatable({
		_connections = {} :: { RBXScriptConnection },
		_destroyed = false,
		_entries = {} :: { [string]: FocusEntry },
		_compositionOrders = {},
		_compositionBaselines = {},
		_eligibilityGate = nil :: ((object: GuiObject, entry: FocusEntry?) -> boolean)?,
		_focused = nil :: GuiObject?,
		_guiService = guiService,
		_lastInputType = userInputService:GetLastInputType(),
		_modals = {} :: { ModalFocus },
		_userInputService = userInputService,
	}, FocusManager)
	table.insert(
		self._connections,
		userInputService.LastInputTypeChanged:Connect(function(inputType)
			self._lastInputType = inputType
			if isGamepad(inputType) and self._focused and self:_isEligible(self._focused) then
				guiService.SelectedObject = self._focused
			end
		end)
	)
	table.insert(
		self._connections,
		guiService:GetPropertyChangedSignal("SelectedObject"):Connect(function()
			local selected = guiService.SelectedObject
			if selected and self:_entryFor(selected) then
				if not self:SetFocused(selected, "selection") and self._focused then
					guiService.SelectedObject = self._focused
				end
			elseif selected ~= self._focused then
				if self._modals[#self._modals] then
					if not self._focused or not self:_isEligible(self._focused) then
						self:SetInitialFocus()
					end
					guiService.SelectedObject = self._focused
				else
					self:SetFocused(nil, "selection")
				end
			end
		end)
	)
	addToMaid(maid, function()
		self:Destroy()
	end)
	return self
end

function FocusManager:_entryFor(object: GuiObject): FocusEntry?
	for _, entry in self._entries do
		if entry.object == object then
			return entry
		end
	end
	return nil
end

function FocusManager:_isEligible(object: GuiObject, knownEntry: FocusEntry?): boolean
	local entry = knownEntry or self:_entryFor(object)
	if not object.Parent or not object.Visible or not object.Selectable then
		return false
	end
	local modal = self._modals[#self._modals]
	if modal then
		local inScope = entry ~= nil and entry.group == modal.id
		local ancestor: Instance? = object
		while not inScope and ancestor do
			if ancestor == modal.scope then
				inScope = true
				break
			end
			ancestor = ancestor.Parent
		end
		if not inScope then return false end
	end
	if object:GetAttribute("PotassiumPresenceGated") == true then
		return false
	end
	local ancestor: Instance? = object.Parent
	while ancestor do
		if ancestor:GetAttribute("PotassiumPresenceGated") == true then return false end
		if ancestor:IsA("GuiObject") and not ancestor.Visible then return false end
		if ancestor:IsA("LayerCollector") and not ancestor.Enabled then return false end
		ancestor = ancestor.Parent
	end
	if entry and entry.eligible and entry.eligible(object) ~= true then return false end
	if self._eligibilityGate and self._eligibilityGate(object, entry) ~= true then return false end
	return true
end

function FocusManager:IsEligible(object: GuiObject): boolean
	return not self._destroyed and self:_isEligible(object)
end

function FocusManager:SetEligibilityGate(gate: ((object: GuiObject, entry: any?) -> boolean)?)
	assert(not self._destroyed, "FocusManager is destroyed")
	assert(gate == nil or type(gate) == "function", "Focus eligibility gate must be a function or nil")
	self._eligibilityGate = gate
	if self._focused and not self:_isEligible(self._focused) then
		self:SetFocused(nil, "eligibility")
	end
end

function FocusManager:_notify(entry: FocusEntry?, focused: boolean, reason: string)
	if entry and entry.onFocusChanged then
		entry.onFocusChanged(focused, reason)
	end
end

function FocusManager:_eligibleEntries(group: string?): { FocusEntry }
	local entries = {}
	for _, entry in self._entries do
		if (group == nil or entry.group == group) and self:_isEligible(entry.object, entry) then
			table.insert(entries, entry)
		end
	end
	table.sort(entries, function(left, right)
		if left.order == right.order then
			return left.id < right.id
		end
		return left.order < right.order
	end)
	return entries
end

function FocusManager:Register(id: string, object: GuiObject, options: FocusOptions)
	assert(not self._destroyed, "FocusManager is destroyed")
	assert(id ~= "", "Focus id must not be empty")
	assert(self._entries[id] == nil, `Duplicate focus id: {id}`)
	assert(options.order ~= nil, "Focus registration requires explicit order")

	local entry: FocusEntry = {
		connections = {},
		eligible = options.eligible,
		group = options.group or "default",
		id = id,
		object = object,
		owner = options.owner,
		onFocusChanged = options.onFocusChanged,
		order = options.order,
	}
	self._entries[id] = entry

	table.insert(
		entry.connections,
		object.Destroying:Connect(function()
			self:Unregister(id)
		end)
	)
	table.insert(
		entry.connections,
		object.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.Touch then
				self:SetFocused(object, "touch")
			end
		end)
	)
end

function FocusManager:Unregister(id: string)
	local entry = self._entries[id]
	if not entry then
		return
	end
	self._entries[id] = nil
	for _, baseline in pairs(self._compositionBaselines) do baseline[id] = nil end
	for _, connection in entry.connections do
		connection:Disconnect()
	end
	if self._focused == entry.object then
		self:_notify(entry, false, "unregister")
		self._focused = nil
		if self._guiService.SelectedObject == entry.object then
			self._guiService.SelectedObject = nil
		end
	end
end

function FocusManager:SetFocused(object: GuiObject?, reason: string?): boolean
	if self._destroyed then
		return false
	end
	if object and not self:_isEligible(object) then
		return false
	end
	if object and not self:_entryFor(object) then
		return false
	end
	if self._focused == object then
		return true
	end

	local previous = self._focused
	self._focused = object
	self:_notify(if previous then self:_entryFor(previous) else nil, false, reason or "programmatic")
	self:_notify(if object then self:_entryFor(object) else nil, true, reason or "programmatic")
	if isGamepad(self._lastInputType) then
		self._guiService.SelectedObject = object
	end
	return true
end

function FocusManager:SetInitialFocus(group: string?): GuiObject?
	local entries = self:_eligibleEntries(group)
	if #entries == 0 then
		self:SetFocused(nil, "initial")
		return nil
	end
	local object = entries[1].object
	if self:SetFocused(object, "initial") then
		return object
	end
	return nil
end

function FocusManager:FocusDirectional(direction: Direction): GuiObject?
	local current = self._focused
	if not current or not self:_isEligible(current) then
		return self:SetInitialFocus()
	end
	local currentEntry = self:_entryFor(current)
	if not currentEntry then
		return self:SetInitialFocus()
	end

	local origin = current.AbsolutePosition + current.AbsoluteSize / 2
	local best: FocusEntry? = nil
	local bestScore = math.huge
	for _, candidate in self:_eligibleEntries(currentEntry.group) do
		if candidate.object ~= current then
			local center = candidate.object.AbsolutePosition + candidate.object.AbsoluteSize / 2
			local delta = center - origin
			local primary: number
			local cross: number
			if direction == "Left" then
				primary, cross = -delta.X, math.abs(delta.Y)
			elseif direction == "Right" then
				primary, cross = delta.X, math.abs(delta.Y)
			elseif direction == "Up" then
				primary, cross = -delta.Y, math.abs(delta.X)
			else
				primary, cross = delta.Y, math.abs(delta.X)
			end
			if primary > 0 then
				local score = primary * primary + cross * cross * 2
				if score < bestScore or (score == bestScore and best and candidate.order < best.order) then
					best = candidate
					bestScore = score
				end
			end
		end
	end
	if best and self:SetFocused(best.object, "directional") then
		return best.object
	end
	return nil
end

function FocusManager:ApplyCompositionOrder(parentId: any, snapshot: any, projection: any): (boolean, any?)
	if self._destroyed then return false, "FocusManager is destroyed" end
	if type(parentId) ~= "string" or type(snapshot) ~= "table" or type(projection) ~= "table" then return false, "Composition order snapshot and projection are required" end
	for id, order in pairs(projection) do
		if type(id) ~= "string" or type(order) ~= "number" or order < 1 or order == math.huge or order ~= math.floor(order) then return false, "Composition focus projection is invalid" end
	end
	local applied = {}
	local baseline = self._compositionBaselines[parentId] or {}
	for id, order in pairs(projection) do
		local entry = self._entries[id]
		if entry ~= nil then
			if baseline[id] == nil then baseline[id] = entry.order end
			entry.order = order
			applied[id] = order
		end
	end
	self._compositionBaselines[parentId] = baseline
	self._compositionOrders[parentId] = table.freeze({ snapshot = snapshot, layout = table.freeze(applied) })
	return true, nil
end
function FocusManager:GetCompositionOrderSnapshot(parentId: any): any return self._compositionOrders and self._compositionOrders[parentId] or nil end
function FocusManager:ClearCompositionOrder(parentId: any): boolean
	if type(parentId) ~= "string" then return false end
	local baseline = self._compositionBaselines[parentId]
	if baseline then
		for id, order in pairs(baseline) do
			local entry = self._entries[id]
			if entry then entry.order = order end
		end
	end
	self._compositionBaselines[parentId] = nil
	self._compositionOrders[parentId] = nil
	return true
end

function FocusManager:PushModal(id: string, initialFocus: GuiObject?, owner: any?)
	assert(not self._destroyed, "FocusManager is destroyed")
	assert(id ~= "", "Modal id must not be empty")
	for _, modal in self._modals do assert(modal.id ~= id, `Duplicate modal id: {id}`) end
	local scope: GuiObject? = nil
	local ancestor: Instance? = initialFocus
	while ancestor do
		if ancestor:IsA("GuiButton") and ancestor.Modal then
			scope = ancestor
			break
		end
		ancestor = ancestor.Parent
	end
	table.insert(self._modals, { id = id, owner = owner, previous = self._focused, scope = scope })
	if initialFocus == nil or not self:SetFocused(initialFocus, "modal") then
		self:SetFocused(nil, "modal")
		self:SetInitialFocus(id)
	end
end

function FocusManager:PopModal(id: string)
	for index = #self._modals, 1, -1 do
		local modal = self._modals[index]
		if modal.id == id then
			table.remove(self._modals, index)
			if index ~= #self._modals + 1 then
				return
			end
			if modal.previous and self:_isEligible(modal.previous) then
				self:SetFocused(modal.previous, "modalRestore")
			else
				self:SetInitialFocus()
			end
			return
		end
	end
end

function FocusManager:CloseOwned(owner: any, reason: string?)
	if self._destroyed or owner == nil then return end
	local restore: GuiObject? = nil
	for index = #self._modals, 1, -1 do
		local modal = self._modals[index]
		if modal.owner == owner then
			table.remove(self._modals, index)
			if index == #self._modals + 1 then restore = modal.previous end
		end
	end
	if self._focused then
		local focusedEntry = self:_entryFor(self._focused)
		if focusedEntry and focusedEntry.owner == owner then self:SetFocused(nil, reason or "ownerClose") end
	end
	if restore and self:_isEligible(restore) then
		self:SetFocused(restore, reason or "ownerClose")
	elseif self._focused == nil then
		self:SetInitialFocus()
	end
end

function FocusManager:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	for _, connection in self._connections do connection:Disconnect() end
	table.clear(self._connections)
	table.clear(self._compositionBaselines)
	table.clear(self._compositionOrders)
	local ids = {}
	for id in self._entries do table.insert(ids, id) end
	for _, id in ids do self:Unregister(id) end
	table.clear(self._modals)
end

return FocusManager

end

__modules["core/Fonts"] = function()
--!strict

local OfflineAssets = __require("customization/OfflineAssets")

export type StructuredError = { code: string, message: string }
export type FontInput = Font | Enum.Font | string

local Fonts = {}
local Registry = {}
Registry.__index = Registry

local builtins = table.freeze({
	Default = Enum.Font.BuilderSans, Bold = Enum.Font.BuilderSansBold, Proxima = Enum.Font.SourceSans,
	Proggy = Enum.Font.Code, Minecraft = Enum.Font.Antique, JetBrains = Enum.Font.RobotoMono,
	Pixel = Enum.Font.Arcade, Fortnite = Enum.Font.LuckiestGuy,
})

local offlineEnums = {}
for _, font in pairs(builtins) do
	table.insert(offlineEnums, font)
end
for _, font in pairs(OfflineAssets.Snapshot().fonts) do
	table.insert(offlineEnums, font)
end

local function enumEquivalent(value: Font): Enum.Font?
	for _, enumFont in ipairs(offlineEnums) do
		if value == Font.fromEnum(enumFont) then
			return enumFont
		end
	end
	return nil
end

local function failure(code: string, message: string): (nil, StructuredError)
	return nil, { code = code, message = message }
end

local function nameOf(name: any): (string?, StructuredError?)
	if type(name) ~= "string" or #name == 0 or #name > 256 then return failure("invalid_font_name", "Font name must be a bounded non-empty string") end
	return name, nil
end

local function fromValue(value: any): (Font?, Enum.Font?, StructuredError?)
	if typeof(value) == "Font" then
		local enumFont = enumEquivalent(value)
		if enumFont ~= nil then return value, enumFont, nil end
		return nil, nil, { code = "invalid_font", message = "Raw fonts must match an offline Enum.Font fallback" }
	end
	if typeof(value) == "EnumItem" and value.EnumType == Enum.Font then return Font.fromEnum(value), value :: Enum.Font, nil end
	return nil, nil, { code = "invalid_font", message = "Custom fonts must be Font or Enum.Font values" }
end

function Registry:Register(name: any, value: any): (Font?, StructuredError?)
	local normalized, nameError = nameOf(name)
	if normalized == nil then return nil, nameError end
	if self._destroyed then return failure("font_registry_destroyed", "Font registry is destroyed") end
	if builtins[normalized] ~= nil then return failure("builtin_font_name", "Built-in font names cannot be replaced") end
	if self._customCount >= 16 and self._records[normalized] == nil then return failure("font_limit", "A font registry can contain at most 16 custom fonts") end
	local face, legacy, fontError = fromValue(value)
	if face == nil then return nil, fontError end
	self._records[normalized] = table.freeze({ face = face, legacy = legacy })
	if self._custom[normalized] == nil then self._custom[normalized] = true; self._customCount += 1 end
	return face, nil
end

function Registry:Resolve(value: any): (Font?, StructuredError?)
	if typeof(value) == "Font" then
		local face, _, fontErr = fromValue(value)
		return face, fontErr
	end
	if typeof(value) == "EnumItem" and value.EnumType == Enum.Font then return Font.fromEnum(value), nil end
	if type(value) == "table" and self._policy ~= nil then
		local admitted, err = self._policy:Admit(value, "$.font")
		if admitted == nil then return nil, err end
		if admitted.kind ~= "font" then return failure("invalid_font", "Asset declaration must be a font") end
		local resolved, resolveErr = self._policy:Resolve(admitted, nil, "$.font")
		if resolved == nil then return nil, resolveErr end
		local fallback = OfflineAssets.Get("fonts", admitted.source.value) or OfflineAssets.Get("fonts", "default")
		return Font.fromEnum(fallback), nil
	end
	if type(value) == "string" then
		local builtin = builtins[value]
		if builtin ~= nil then return Font.fromEnum(builtin), nil end
		local record = self._records[value]
		if record ~= nil then return record.face, nil end
		return failure("unknown_font", "Unknown registered font: " .. value)
	end
	return failure("invalid_font", "Font must be a registered name, Font, Enum.Font, or font declaration")
end

function Registry:Legacy(value: any): Enum.Font?
	if typeof(value) == "EnumItem" and value.EnumType == Enum.Font then return value :: Enum.Font end
	if type(value) == "string" then
		local builtin = builtins[value]
		if builtin ~= nil then return builtin end
		local record = self._records[value]
		return if record ~= nil then record.legacy else nil
	end
	return nil
end

function Registry:Has(name: any): boolean
	return type(name) == "string" and (builtins[name] ~= nil or self._records[name] ~= nil)
end
function Registry:Get(name: any): Font?
	local face = self:Resolve(name)
	return face
end
function Registry:List(): { string }
	local names = {}
	for name in pairs(builtins) do table.insert(names, name) end
	for name in pairs(self._records) do table.insert(names, name) end
	table.sort(names)
	return names
end
function Registry:GetSnapshot(): any
	local names = self:List()
	return table.freeze({ customCount = self._customCount, customLimit = 16, names = table.freeze(names) })
end
function Registry:Destroy()
	self._destroyed = true
	table.clear(self._records)
	table.clear(self._custom)
	self._customCount = 0
end

function Fonts.new(assetPolicy: any?): any
	local registry: any = setmetatable({ _policy = assetPolicy, _records = {}, _custom = {}, _customCount = 0, _destroyed = false }, Registry)
	return registry
end
Fonts.New = Fonts.new
Fonts.BuiltIns = builtins

-- Compatibility remains additive. New Library instances must use Fonts.new().
local compatibility = Fonts.new()
for _, method in ipairs({ "Register", "Resolve", "Legacy", "Has", "Get", "List", "GetSnapshot", "Destroy" }) do
	(Fonts :: any)[method] = function(first: any, ...: any)
		if first == Fonts then return (compatibility :: any)[method](compatibility, ...) end
		return (compatibility :: any)[method](compatibility, first, ...)
	end
end

return Fonts

end

__modules["core/ImageCrossfade"] = function()
--!strict

export type ImageCrossfade = {
	Set: (self: ImageCrossfade, resolvedSource: string?, transparency: number?, options: { Transition: string?, Preset: string? }?) -> (),
	SetZIndex: (self: ImageCrossfade, zIndex: number) -> (),
	GetState: (self: ImageCrossfade) -> { Source: string?, Transparency: number, ZIndex: number },
	GetDiagnostics: (self: ImageCrossfade) -> { slots: number, generation: number, activeSlot: number, destroyed: boolean },
	Destroy: (self: ImageCrossfade) -> (),
}

local ImageCrossfade = {}
ImageCrossfade.__index = ImageCrossfade

local function addToMaid(maid: any, task: any)
	if maid == nil then
		return
	end
	if type(maid.GiveTask) == "function" then
		maid:GiveTask(task)
	elseif type(maid.Add) == "function" then
		maid:Add(task)
	end
end

local function applyProperties(target: Instance, properties: { [string]: any }?)
	if properties == nil then
		return
	end
	for property, value in pairs(properties) do
		(target :: any)[property] = value
	end
end

local function validTransparency(value: any): boolean
	return type(value) == "number" and value == value and value >= 0 and value <= 1
end

local function resolveOptions(options: any): (string, string)
	if options == nil then
		return "none", "standard"
	end
	assert(type(options) == "table", "ImageCrossfade options must be a table")
	for key in pairs(options) do
		assert(key == "Transition" or key == "Preset", "Unknown ImageCrossfade option: " .. tostring(key))
	end
	local transition = options.Transition or "none"
	assert(transition == "none" or transition == "crossfade", "ImageCrossfade Transition must be none or crossfade")
	local preset = options.Preset or "standard"
	assert(type(preset) == "string" and preset ~= "", "ImageCrossfade Preset must be a non-empty string")
	return transition, preset
end

function ImageCrossfade.new(motion: any, maid: any, parent: Instance, defaultProps: { [string]: any }?): ImageCrossfade
	assert(
		type(motion) == "table" and type(motion.Animate) == "function" and type(motion.GetMotionPreset) == "function",
		"ImageCrossfade requires Motion"
	)
	assert(typeof(parent) == "Instance", "ImageCrossfade requires a parent Instance")
	assert(defaultProps == nil or type(defaultProps) == "table", "ImageCrossfade default properties must be a table")

	local first = Instance.new("ImageLabel")
	local second = Instance.new("ImageLabel")
	applyProperties(first, defaultProps)
	applyProperties(second, defaultProps)
	for _, slot in ipairs({ first, second }) do
		slot.BackgroundTransparency = 1
		slot.BorderSizePixel = 0
		slot.ImageTransparency = 1
		slot.Visible = false
		slot.Parent = parent
	end

	local defaultTransparency = if defaultProps and validTransparency(defaultProps.ImageTransparency)
		then defaultProps.ImageTransparency
		else 0

	local self = setmetatable({
		_motion = motion,
		_slots = { first, second },
		_active = 1,
		_handles = { nil, nil },
		_generation = 0,
		_source = nil :: string?,
		_transparency = defaultTransparency,
		_zIndex = first.ZIndex,
		_destroyed = false,
	}, ImageCrossfade)
	addToMaid(maid, function()
		self:Destroy()
	end)
	return self :: any
end

function ImageCrossfade:_cancelSlots(reason: string, expectedGeneration: number?): boolean
	for index = 1, 2 do
		if expectedGeneration ~= nil and expectedGeneration ~= self._generation then
			return false
		end
		local handle = self._handles[index]
		if handle ~= nil then
			handle:Cancel(reason)
			if self._handles[index] == handle then
				self._handles[index] = nil
			end
		end
	end
	return expectedGeneration == nil or expectedGeneration == self._generation
end

function ImageCrossfade:Set(resolvedSource: string?, transparency: number?, options: { Transition: string?, Preset: string? }?)
	assert(resolvedSource == nil or type(resolvedSource) == "string", "ImageCrossfade source must be a resolved string or nil")
	local targetTransparency = if transparency == nil then self._transparency else transparency
	assert(validTransparency(targetTransparency), "ImageCrossfade transparency must be a finite value from 0 to 1")
	local transition, preset = resolveOptions(options)
	assert(self._motion:GetMotionPreset(preset) ~= nil, "Unknown ImageCrossfade motion preset: " .. preset)
	if self._destroyed then
		return
	end

	self._generation += 1
	local generation = self._generation
	if not self:_cancelSlots("retargeted", generation) then
		return
	end
	self._source = resolvedSource
	self._transparency = targetTransparency

	if resolvedSource == nil or resolvedSource == "" then
		for _, slot in ipairs(self._slots) do
			slot.Image = ""
			slot.ImageTransparency = 1
			slot.Visible = false
		end
		return
	end

	local active = self._slots[self._active]
	if transition == "none" then
		local slot = active
		if slot.Image ~= resolvedSource then
			self._active = if self._slots[1].ImageTransparency >= self._slots[2].ImageTransparency then 1 else 2
			slot = self._slots[self._active]
		end
		slot.Image = resolvedSource
		slot.ImageTransparency = targetTransparency
		slot.Visible = true
		for index, other in ipairs(self._slots) do
			if other ~= slot then
				other.ImageTransparency = 1
				other.Visible = false
				self._handles[index] = nil
			end
		end
		return
	end

	local nextIndex = if self._slots[1].ImageTransparency >= self._slots[2].ImageTransparency then 1 else 2
	local nextSlot = self._slots[nextIndex]
	local previousIndex = if nextIndex == 1 then 2 else 1
	local previousSlot = self._slots[previousIndex]
	self._active = nextIndex
	nextSlot.Image = resolvedSource
	nextSlot.ImageTransparency = 1
	nextSlot.Visible = true
	previousSlot.Visible = previousSlot.Image ~= ""

	local incoming = self._motion:Animate(nextSlot, { ImageTransparency = targetTransparency }, preset)
	if generation ~= self._generation then
		incoming:Cancel("retargeted")
		return
	end
	self._handles[nextIndex] = incoming

	local outgoing = self._motion:Animate(previousSlot, { ImageTransparency = 1 }, preset)
	if generation ~= self._generation then
		incoming:Cancel("retargeted")
		outgoing:Cancel("retargeted")
		return
	end
	self._handles[previousIndex] = outgoing
	incoming:OnCompleted(function(state: string)
		if generation ~= self._generation or self._handles[nextIndex] ~= incoming then
			return
		end
		self._handles[nextIndex] = nil
		if state == "Completed" or state == "Skipped" then
			previousSlot.Visible = false
		end
	end)
	outgoing:OnCompleted(function()
		if generation == self._generation and self._handles[previousIndex] == outgoing then
			self._handles[previousIndex] = nil
		end
	end)
end

function ImageCrossfade:SetZIndex(zIndex: number)
	assert(type(zIndex) == "number" and zIndex == zIndex, "ImageCrossfade ZIndex must be a number")
	self._zIndex = zIndex
	for _, slot in ipairs(self._slots) do
		slot.ZIndex = zIndex
	end
end

function ImageCrossfade:GetState(): { Source: string?, Transparency: number, ZIndex: number }
	return {
		Source = self._source,
		Transparency = self._transparency,
		ZIndex = self._zIndex,
	}
end

function ImageCrossfade:GetDiagnostics(): { slots: number, generation: number, activeSlot: number, destroyed: boolean }
	return {
		slots = 2,
		generation = self._generation,
		activeSlot = self._active,
		destroyed = self._destroyed,
	}
end

function ImageCrossfade:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	self._generation += 1
	self:_cancelSlots("destroyed")
	for _, slot in ipairs(self._slots) do
		slot:Destroy()
	end
end

return ImageCrossfade

end

__modules["core/InputRouter"] = function()
--!strict

local Signal = __require("core/Signal")

export type Eligibility = {
	body: boolean?,
	visibility: "shown" | "minimized" | "hidden"?,
	disabled: boolean?,
	readOnly: boolean?,
	modalId: string?,
	allowWhenModal: boolean?,
	allowWhileTextEntry: boolean?,
}

export type Shortcut = {
	keys: { Enum.KeyCode },
	allowWhileTextEntry: boolean?,
	priority: number?,
	eligibility: Eligibility?,
	onEnded: ((input: InputObject) -> ())?,
}

type ShortcutEntry = { shortcut: Shortcut, callback: (input: InputObject) -> boolean? }
type DragSession = {
	input: InputObject,
	onMove: (position: Vector2, delta: Vector2) -> (),
	onEnd: (position: Vector2) -> (),
	lastPosition: Vector2,
}
type ModalEntry = { id: string, owner: any }
type HoldRecord = { generation: number }
type CaptureEntry = {
	owner: any,
	callback: (input: InputObject) -> boolean?,
	onReleased: (() -> ())?,
}

export type InputRouter = {
	InputBegan: any,
	InputEnded: any,
	BeginCapture: (self: InputRouter, owner: any, callback: (input: InputObject) -> boolean?, onReleased: (() -> ())?) -> (() -> ()),
	RegisterMenuKey: (self: InputRouter, keyCode: Enum.KeyCode, callback: (input: InputObject) -> boolean?) -> (),
	UnregisterMenuKey: (self: InputRouter, keyCode: Enum.KeyCode) -> (),
	RegisterShortcut: (self: InputRouter, id: string, shortcut: Shortcut, callback: (input: InputObject) -> boolean?) -> (),
	UnregisterShortcut: (self: InputRouter, id: string) -> (),
	BeginPointerDrag: (self: InputRouter, input: InputObject, onMove: (position: Vector2, delta: Vector2) -> (), onEnd: (position: Vector2) -> ()) -> (),
	EndPointerDrag: (self: InputRouter, input: InputObject?) -> (),
	RegisterBackHandler: (self: InputRouter, id: string, callback: () -> boolean?, priority: number?) -> (),
	UnregisterBackHandler: (self: InputRouter, id: string) -> (),
	PushModal: (self: InputRouter, id: string, owner: any) -> (),
	PopModal: (self: InputRouter, id: string) -> (),
	SetTextEntryActive: (self: InputRouter, active: boolean) -> (),
	SetSurfaceVisibility: (self: InputRouter, visibility: string) -> (),
	CanInteract: (self: InputRouter, eligibility: Eligibility?) -> (boolean, string?),
	GetDiagnosticSnapshot: (self: InputRouter) -> any,
	GetEligibilitySnapshot: (self: InputRouter) -> any,
	CancelHold: (self: InputRouter, id: string) -> (),
	SetGameInput: (self: InputRouter, enabled: boolean) -> (boolean, any?),
	Destroy: (self: InputRouter) -> (),
}

local InputRouter = {}
InputRouter.__index = InputRouter

local BACK_ACTION_PREFIX = "UI.Back."
local GAME_INPUT_ACTION_PREFIX = "UI.GameInput."

local MAX_ACTIVE_HOLDS = 128
local EMPTY_ELIGIBILITY = table.freeze({} :: Eligibility)


local function activeHoldCount(holds: { [any]: any }): number
	local count = 0
	for _ in pairs(holds) do
		count += 1
	end
	return count
end

local function addToMaid(maid: any, taskValue: any)
	if maid == nil then return end
	if type(maid.GiveTask) == "function" then maid:GiveTask(taskValue) elseif type(maid.Add) == "function" then maid:Add(taskValue) end
end

local function unbindAction(service: any, actionName: string): boolean
	if service == nil or type(service.UnbindAction) ~= "function" then
		return false
	end
	return pcall(service.UnbindAction, service, actionName)
end

local function isPointer(input: InputObject): boolean
	return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
end

local function pointerPosition(input: InputObject): Vector2
	return Vector2.new(input.Position.X, input.Position.Y)
end

local function orderedHandlers(handlers: { [string]: { callback: () -> boolean?, priority: number } }): { { callback: () -> boolean?, priority: number, id: string } }
	local result = {}
	for id, entry in handlers do table.insert(result, { id = id, callback = entry.callback, priority = entry.priority }) end
	table.sort(result, function(left, right) return if left.priority == right.priority then left.id < right.id else left.priority > right.priority end)
	return result
end

local function finiteDelay(value: number): number
	if value ~= value or value == math.huge or value == -math.huge then return 0 end
	return math.max(0, value)
end

function InputRouter.new(runtime: any, maid: any): InputRouter
	local services = if type(runtime) == "table" and type(runtime.services) == "table" then runtime.services else {}
	local contextActionService = services.ContextActionService
	local userInputService = services.UserInputService
	local contextId = if type(runtime) == "table" and runtime.contextId ~= nil then tostring(runtime.contextId) else tostring({})
	local self = setmetatable({
		_backActionName = BACK_ACTION_PREFIX .. contextId,
		_backActionBound = false,
		_gameInputActionName = GAME_INPUT_ACTION_PREFIX .. contextId,
		_gameInputActionBound = false,
		_holdGeneration = 0,
		_holds = {} :: { [string]: HoldRecord },
		_gameInputEnabled = true,
		_backHandlers = {} :: { [string]: { callback: () -> boolean?, priority: number } },
		_capture = nil :: CaptureEntry?,
		_connections = {} :: { RBXScriptConnection },
		_contextActionService = contextActionService,
		_destroyed = false,
		_dragSession = nil :: DragSession?,
		_menuKeys = {} :: { [Enum.KeyCode]: (input: InputObject) -> boolean? },
		_modals = {} :: { ModalEntry },
		_shortcuts = {} :: { [string]: ShortcutEntry },
		_surfaceVisibility = "shown",
		_suppressedEnds = {} :: { [Enum.KeyCode]: boolean | ((input: InputObject) -> ()) },
		_textEntryOverride = false,
		_userInputService = userInputService,
		InputBegan = Signal.new(),
		InputEnded = Signal.new(),
	}, InputRouter)

	if userInputService ~= nil then
		if userInputService.InputBegan then table.insert(self._connections, userInputService.InputBegan:Connect(function(input, gameProcessed)
			if self._destroyed then return end
			if self:_onInputBegan(input, gameProcessed) then
				self.InputBegan:Fire(input, gameProcessed)
			end
		end)) end
		if userInputService.InputChanged then table.insert(self._connections, userInputService.InputChanged:Connect(function(input) self:_onInputChanged(input) end)) end
		if userInputService.InputEnded then table.insert(self._connections, userInputService.InputEnded:Connect(function(input, gameProcessed)
			if self._destroyed then return end
			if self:_onInputEnded(input, gameProcessed) then
				self.InputEnded:Fire(input)
			end
		end)) end
	end
	addToMaid(maid, function() self:Destroy() end)
	return self
end

function InputRouter:_textEntryConsumes(): boolean
	if self._textEntryOverride then return true end
	local service = self._userInputService
	if service == nil or type(service.GetFocusedTextBox) ~= "function" then return false end
	local ok, focused = pcall(service.GetFocusedTextBox, service)
	return ok and focused ~= nil
end

local function canInteract(self: InputRouter, eligibility: Eligibility?, allowWhileTextEntry: boolean?): (boolean, string?)
	if self._destroyed then return false, "destroyed" end
	local source = if type(eligibility) == "table" then eligibility else EMPTY_ELIGIBILITY
	local visibility = source.visibility or self._surfaceVisibility
	if source.body ~= false and visibility ~= "shown" then return false, visibility == "minimized" and "minimized" or "hidden" end
	if source.disabled == true then return false, "disabled" end
	if source.readOnly == true then return false, "read_only" end
	local activeModal = self._modals[#self._modals]
	if activeModal ~= nil and source.allowWhenModal ~= true and source.modalId ~= activeModal.id then return false, "modal_blocked" end
	if self:_textEntryConsumes() and source.allowWhileTextEntry ~= true and allowWhileTextEntry ~= true then return false, "text_entry" end
	return true, nil
end

function InputRouter:CanInteract(eligibility: Eligibility?): (boolean, string?)
	return canInteract(self, eligibility, false)
end

function InputRouter:GetEligibilitySnapshot(): any
	return table.freeze({ visibility = self._surfaceVisibility, modalId = if self._modals[#self._modals] then self._modals[#self._modals].id else nil, textEntry = self:_textEntryConsumes(), destroyed = self._destroyed })
end
function InputRouter:_syncBackActionBinding()
	if self._destroyed then
		return
	end
	local shouldBind = next(self._backHandlers) ~= nil or #self._modals > 0
	if shouldBind == self._backActionBound then
		return
	end
	local service = self._contextActionService
	if shouldBind then
		if service == nil or type(service.BindActionAtPriority) ~= "function" then
			return
		end
		local ok = pcall(function()
			service:BindActionAtPriority(self._backActionName, function(_actionName, inputState, _inputObject)
				if inputState ~= Enum.UserInputState.Begin then return Enum.ContextActionResult.Pass end
				if self._capture ~= nil then return Enum.ContextActionResult.Pass end
				return if self:_routeBack() then Enum.ContextActionResult.Sink else Enum.ContextActionResult.Pass
			end, false, 3000, Enum.KeyCode.Escape, Enum.KeyCode.ButtonB)
		end)
		self._backActionBound = ok
	else
		if unbindAction(service, self._backActionName) then
			self._backActionBound = false
		end
	end
end


function InputRouter:GetDiagnosticSnapshot(): any
	return table.freeze({
		shortcuts = activeHoldCount(self._shortcuts),
		menuKeys = activeHoldCount(self._menuKeys),
		modals = #self._modals,
		backHandlers = activeHoldCount(self._backHandlers),
		backActionBound = self._backActionBound,
		gameInput = self._gameInputEnabled,
		generation = self._holdGeneration,
		destroyed = self._destroyed,
	})
end
function InputRouter:_routeModal(method: string, input: InputObject): boolean
	local modal = self._modals[#self._modals]
	if modal == nil then return false end
	local handler = modal.owner[method]
	if type(handler) ~= "function" then return false end
	local ok, consumed = pcall(handler, modal.owner, input)
	return ok and consumed == true
end

function InputRouter:_routeBack(): boolean
	if self._destroyed then return false end
	local modal = self._modals[#self._modals]
	if modal then
		local handler = modal.owner.OnBack
		if type(handler) == "function" then pcall(handler, modal.owner) end
		return true
	end
	for _, entry in orderedHandlers(self._backHandlers) do
		local ok, consumed = pcall(entry.callback)
		if ok and consumed == true then return true end
	end
	return false
end

function InputRouter:_onInputBegan(input: InputObject, gameProcessed: boolean): boolean
	if self._destroyed then return false end
	local capture = self._capture
	if capture ~= nil then
		if not isPointer(input) then
			self._suppressedEnds[input.KeyCode] = self._suppressedEnds[input.KeyCode] or true
		end
		local ok = pcall(capture.callback, input)
		if not ok and self._capture == capture then self:_releaseCapture(capture) end
		return false
	end
	if isPointer(input) then
		if self._modals[#self._modals] then
			self:_routeModal("OnPointerBegan", input)
			return false
		end
		return not gameProcessed
	end
	if gameProcessed then
		self._suppressedEnds[input.KeyCode] = true
		return false
	end
	if self._modals[#self._modals] then
		self:_routeModal("OnInputBegan", input)
		self._suppressedEnds[input.KeyCode] = true
		return false
	end
	local menu = self._menuKeys[input.KeyCode]
	if menu and self:CanInteract({ body = false, allowWhileTextEntry = false }) then
		local ok, consumed = pcall(menu, input)
		if ok and consumed == true then
			self._suppressedEnds[input.KeyCode] = true
			return false
		end
	end
	local matches = {}
	for id, entry in self._shortcuts do
		local triggered = false
		for _, key in entry.shortcut.keys do
			if key == input.KeyCode then
				triggered = true
				break
			end
		end
		if triggered and canInteract(self, entry.shortcut.eligibility, entry.shortcut.allowWhileTextEntry) then
			local allDown = true
			for _, key in entry.shortcut.keys do
				if key ~= input.KeyCode and not self:_isKeyDown(key) then
					allDown = false
					break
				end
			end
			if allDown then table.insert(matches, { id = id, entry = entry }) end
		end
	end
	table.sort(matches, function(left, right)
		local leftPriority, rightPriority = left.entry.shortcut.priority or 0, right.entry.shortcut.priority or 0
		return if leftPriority == rightPriority then left.id < right.id else leftPriority > rightPriority
	end)
	for _, match in matches do
		local ok, consumed = pcall(match.entry.callback, input)
		if ok and consumed == true then
			self._suppressedEnds[input.KeyCode] = match.entry.shortcut.onEnded or true
			return false
		end
	end
	return true
end

function InputRouter:_isKeyDown(key: Enum.KeyCode): boolean
	local service = self._userInputService
	if service == nil or type(service.IsKeyDown) ~= "function" then return false end
	local ok, down = pcall(service.IsKeyDown, service, key)
	return ok and down == true
end

function InputRouter:_onInputChanged(input: InputObject)
	local drag = self._dragSession
	if drag == nil then return end
	local mouseDrag = drag.input.UserInputType == Enum.UserInputType.MouseButton1
	if input ~= drag.input and (not mouseDrag or input.UserInputType ~= Enum.UserInputType.MouseMovement) then return end
	local position = pointerPosition(input)
	local delta = position - drag.lastPosition
	drag.lastPosition = position
	pcall(drag.onMove, position, delta)
end

function InputRouter:_onInputEnded(input: InputObject, gameProcessed: boolean): boolean
	local drag = self._dragSession
	if drag then
		local mouseDrag = drag.input.UserInputType == Enum.UserInputType.MouseButton1
		if input == drag.input or (mouseDrag and input.UserInputType == Enum.UserInputType.MouseButton1) then self:EndPointerDrag(input) end
	end
	local suppressed = self._suppressedEnds[input.KeyCode]
	if suppressed then
		self._suppressedEnds[input.KeyCode] = nil
		if type(suppressed) == "function" then
			pcall(suppressed, input)
		end
		return false
	end
	if gameProcessed then return false end
	if self._modals[#self._modals] then
		self:_routeModal("OnInputEnded", input)
		return false
	end
	return true
end

function InputRouter:_releaseCapture(capture: CaptureEntry)
	if self._capture ~= capture then return end
	self._capture = nil
	if capture.onReleased then pcall(capture.onReleased) end
end

function InputRouter:BeginCapture(owner: any, callback: (input: InputObject) -> boolean?, onReleased: (() -> ())?): (() -> ())
	assert(not self._destroyed and owner ~= nil and type(callback) == "function", "Capture owner and callback are required")
	local previous = self._capture
	if previous ~= nil then self:_releaseCapture(previous) end
	local capture: CaptureEntry = { owner = owner, callback = callback, onReleased = onReleased }
	self._capture = capture
	return function()
		self:_releaseCapture(capture)
	end
end

function InputRouter:RegisterMenuKey(keyCode: Enum.KeyCode, callback: (input: InputObject) -> boolean?)
	assert(not self._destroyed, "InputRouter is destroyed")
	assert(self._menuKeys[keyCode] == nil, "Menu key is already registered")
	self._menuKeys[keyCode] = callback
end
function InputRouter:UnregisterMenuKey(keyCode: Enum.KeyCode) self._menuKeys[keyCode] = nil end

function InputRouter:RegisterShortcut(id: string, shortcut: Shortcut, callback: (input: InputObject) -> boolean?)
	assert(not self._destroyed, "InputRouter is destroyed")
	assert(id ~= "" and #shortcut.keys > 0, "Shortcut id and keys are required")
	assert(self._shortcuts[id] == nil, `Duplicate shortcut id: {id}`)
	self._shortcuts[id] = { shortcut = shortcut, callback = callback }
end
function InputRouter:UnregisterShortcut(id: string) self._shortcuts[id] = nil end

function InputRouter:BeginPointerDrag(input: InputObject, onMove: (position: Vector2, delta: Vector2) -> (), onEnd: (position: Vector2) -> ())
	assert(not self._destroyed, "InputRouter is destroyed")
	assert(isPointer(input), "Pointer drag requires mouse button or touch input")
	self:EndPointerDrag()
	self._dragSession = { input = input, onMove = onMove, onEnd = onEnd, lastPosition = pointerPosition(input) }
end

function InputRouter:EndPointerDrag(input: InputObject?)
	local drag = self._dragSession
	if drag == nil then return end
	local mouseDrag = drag.input.UserInputType == Enum.UserInputType.MouseButton1
	if input and input ~= drag.input and (not mouseDrag or input.UserInputType ~= Enum.UserInputType.MouseButton1) then return end
	self._dragSession = nil
	pcall(drag.onEnd, if input then pointerPosition(input) else drag.lastPosition)
end

function InputRouter:RegisterBackHandler(id: string, callback: () -> boolean?, priority: number?)
	assert(not self._destroyed and id ~= "", "Back handler id is required")
	assert(self._backHandlers[id] == nil, `Duplicate back handler id: {id}`)
	self._backHandlers[id] = { callback = callback, priority = priority or 0 }
	self:_syncBackActionBinding()
end
function InputRouter:UnregisterBackHandler(id: string)
	self._backHandlers[id] = nil
	self:_syncBackActionBinding()
end

function InputRouter:PushModal(id: string, owner: any)
	assert(not self._destroyed and id ~= "", "Modal id is required")
	for _, modal in self._modals do assert(modal.id ~= id, `Duplicate modal id: {id}`) end
	table.insert(self._modals, { id = id, owner = owner })
	self:_syncBackActionBinding()
end
function InputRouter:PopModal(id: string)
	for index = #self._modals, 1, -1 do
		if self._modals[index].id == id then
			table.remove(self._modals, index)
			self:_syncBackActionBinding()
			return
		end
	end
end

function InputRouter:SetTextEntryActive(active: boolean) self._textEntryOverride = active == true end
function InputRouter:SetSurfaceVisibility(visibility: string)
	assert(visibility == "shown" or visibility == "minimized" or visibility == "hidden", "Visibility must be shown, minimized, or hidden")
	self._surfaceVisibility = visibility
	if visibility ~= "shown" then self:EndPointerDrag() end
end

function InputRouter:ScheduleHold(id: string, delaySeconds: number, callback: () -> (), eligibility: Eligibility?): (() -> ())
	assert(not self._destroyed and id ~= "" and type(callback) == "function", "Hold id and callback are required")
	if self._holds[id] == nil and activeHoldCount(self._holds) >= MAX_ACTIVE_HOLDS then
		return function() end
	end
	self:CancelHold(id)
	self._holdGeneration += 1
	local generation = self._holdGeneration
	self._holds[id] = { generation = generation }
	local owner = self
	task.delay(finiteDelay(delaySeconds), function()
		if owner._destroyed then return end
		local current = owner._holds[id]
		if current == nil or current.generation ~= generation then return end
		owner._holds[id] = nil
		local eligible = owner:CanInteract(eligibility)
		if eligible then pcall(callback) end
	end)
	return function()
		local current = owner._holds[id]
		if current ~= nil and current.generation == generation then owner:CancelHold(id) end
	end
end

function InputRouter:CancelHold(id: string)
	self._holds[id] = nil
end

function InputRouter:SetGameInput(enabled: boolean): (boolean, any?)
	assert(type(enabled) == "boolean", "Game input policy must be a boolean")
	if self._destroyed then return false, { code = "destroyed", message = "InputRouter is destroyed" } end
	local service = self._contextActionService
	if service == nil or type(service.UnbindAction) ~= "function" then self._gameInputEnabled = enabled; return true, nil end
	if self._gameInputActionBound and not unbindAction(service, self._gameInputActionName) then
		return false, { code = "game_input_unbind_failed", message = "Could not release the existing game input action" }
	end
	self._gameInputActionBound = false
	if not enabled then
		if type(service.BindActionAtPriority) ~= "function" then return false, { code = "game_input_unavailable", message = "ContextActionService binding is unavailable" } end
		local ok, reason = pcall(function()
			service:BindActionAtPriority(self._gameInputActionName, function() return Enum.ContextActionResult.Sink end, false, 4000,
				Enum.PlayerActions.CharacterForward, Enum.PlayerActions.CharacterBackward, Enum.PlayerActions.CharacterLeft, Enum.PlayerActions.CharacterRight,
				Enum.PlayerActions.CharacterJump, Enum.UserInputType.MouseMovement, Enum.UserInputType.MouseButton2, Enum.UserInputType.MouseWheel,
				Enum.KeyCode.Thumbstick1, Enum.KeyCode.Thumbstick2, Enum.KeyCode.ButtonL2, Enum.KeyCode.ButtonR2)
		end)
		if not ok then self._gameInputEnabled = true; return false, { code = "game_input_bind_failed", message = tostring(reason) } end
		self._gameInputActionBound = true
	end
	self._gameInputEnabled = enabled
	return true, nil
end

function InputRouter:Destroy()
	local wasDestroyed = self._destroyed
	self._destroyed = true
	local service = self._contextActionService
	if self._backActionBound and unbindAction(service, self._backActionName) then
		self._backActionBound = false
	end
	if self._gameInputActionBound and unbindAction(service, self._gameInputActionName) then
		self._gameInputActionBound = false
	end
	if wasDestroyed then return end
	self:EndPointerDrag()
	for _, connection in self._connections do connection:Disconnect() end
	table.clear(self._connections); table.clear(self._backHandlers); table.clear(self._holds); table.clear(self._suppressedEnds)
	if self._capture then self:_releaseCapture(self._capture) end
	table.clear(self._menuKeys); table.clear(self._modals); table.clear(self._shortcuts)
	self.InputBegan:Destroy(); self.InputEnded:Destroy()
end

return InputRouter

end

__modules["core/Maid"] = function()
--!strict

export type CleanupTask =
	RBXScriptConnection
	| Instance
	| thread
	| (() -> ())
	| { Destroy: (self: any) -> () }
	| { Disconnect: (self: any) -> () }
	| { Cancel: (self: any) -> () }

export type Maid = {
	GiveTask: (self: Maid, task: CleanupTask) -> CleanupTask,
	Set: (self: Maid, key: any, task: CleanupTask?) -> CleanupTask?,
	Remove: (self: Maid, key: any) -> CleanupTask?,
	Clean: (self: Maid) -> (),
	Destroy: (self: Maid) -> (),
	IsDestroyed: (self: Maid) -> boolean,
}

local Maid = {}
Maid.__index = Maid

local function cleanTask(taskValue: CleanupTask)
	local valueType = typeof(taskValue)
	if valueType == "RBXScriptConnection" then
		(taskValue :: RBXScriptConnection):Disconnect()
		return
	end
	if valueType == "Instance" then
		(taskValue :: Instance):Destroy()
		return
	end
	if valueType == "thread" then
		pcall(task.cancel, taskValue :: thread)
		return
	end
	if valueType == "function" then
		(taskValue :: () -> ())()
		return
	end

	local object = taskValue :: any
	if type(object) == "table" or type(object) == "userdata" then
		if type(object.Destroy) == "function" then
			object:Destroy()
		elseif type(object.Disconnect) == "function" then
			object:Disconnect()
		elseif type(object.Cancel) == "function" then
			object:Cancel()
		end
	end
end

function Maid.new(): Maid
	return setmetatable({
		_tasks = {} :: { [any]: CleanupTask },
		_destroyed = false,
	}, Maid) :: any
end

function Maid:GiveTask(taskValue: CleanupTask): CleanupTask
	assert(not self._destroyed, "Cannot add a task to a destroyed Maid")
	local key = taskValue
	self:Set(key, taskValue)
	return taskValue
end

function Maid:Set(key: any, taskValue: CleanupTask?): CleanupTask?
	if self._destroyed then
		if taskValue ~= nil then
			pcall(cleanTask, taskValue)
		end
		return nil
	end

	local oldTask = self._tasks[key]
	if oldTask == taskValue then
		return oldTask
	end
	self._tasks[key] = taskValue
	if oldTask ~= nil then
		pcall(cleanTask, oldTask)
	end
	return oldTask
end

function Maid:Remove(key: any): CleanupTask?
	return self:Set(key, nil)
end

function Maid:Clean()
	if self._destroyed then
		return
	end

	local tasks = self._tasks
	self._tasks = {}
	for _, taskValue in pairs(tasks) do
		pcall(cleanTask, taskValue)
	end
end

function Maid:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	local tasks = self._tasks
	self._tasks = {}
	for _, taskValue in pairs(tasks) do
		pcall(cleanTask, taskValue)
	end
end

function Maid:IsDestroyed(): boolean
	return self._destroyed
end

return Maid

end

__modules["core/MigrationRegistry"] = function()
--!strict

local StructuredError = __require("core/StructuredError")

type StructuredErrorValue = StructuredError.StructuredError
export type MigrationRegistry = {
	RegisterDeclaration: (self: MigrationRegistry, declaration: any) -> (boolean, StructuredErrorValue?),
	RegisterOwnedDeclarations: (self: MigrationRegistry, owner: any, declarations: any) -> (boolean, StructuredErrorValue?),
	RemoveOwnedDeclarations: (self: MigrationRegistry, owner: any) -> (boolean, StructuredErrorValue?),
	RegisterImplementation: (self: MigrationRegistry, step: any) -> (boolean, StructuredErrorValue?),
	ResolveChain: (self: MigrationRegistry, axis: any, fromVersion: any, toVersion: any) -> (any?, StructuredErrorValue?),
	Apply: (self: MigrationRegistry, axis: any, fromVersion: any, toVersion: any, value: any) -> (any?, StructuredErrorValue?),
	Rollback: (self: MigrationRegistry, chain: any, value: any) -> (any?, StructuredErrorValue?),
	GetSnapshot: (self: MigrationRegistry) -> any,
}

local MigrationRegistry = {}
MigrationRegistry.__index = MigrationRegistry

local AXES = table.freeze({ apiVersion = true, extensionApiVersion = true, skinSchemaVersion = true, skinContentVersion = true, menuSchemaVersion = true, workspaceSchemaVersion = true, packageVersion = true, adapterSchemaVersion = true })
local MAX_DECLARATIONS = 256
local MAX_IMPLEMENTATIONS = 256
local LOCAL_PATTERN = "^[A-Za-z][A-Za-z0-9._-]*$"
local NAMESPACED_PATTERN = "^[A-Za-z][A-Za-z0-9._-]*:[A-Za-z][A-Za-z0-9._-]*$"
local MAX_CHAIN_SEARCH_STATES = MAX_DECLARATIONS

local function fail(code: string, message: string, operation: string, details: any?): StructuredErrorValue
	return StructuredError.from(code, message, { domain = "migration", operation = operation, details = details })
end

local function localId(value: any): string?
	if type(value) ~= "string" or #value > 64 or string.match(value, LOCAL_PATTERN) == nil then return nil end
	if string.sub(value, 1, 5) == "host." or string.sub(value, 1, 7) == "system." or string.sub(value, 1, 7) == "legacy." then return nil end
	return value
end

local function namespacedId(value: any): string?
	if type(value) == "string" and #value <= 129 and string.match(value, NAMESPACED_PATTERN) ~= nil then return value end
	return nil
end

local function version(value: any): (any?, StructuredErrorValue?)
	if type(value) ~= "table" or getmetatable(value) ~= nil then return nil, fail("invalid_version", "Version must be a plain table", "validate") end
	for key in pairs(value) do if key ~= "major" and key ~= "minor" and key ~= "patch" then return nil, fail("invalid_version", "Version contains an unknown field", "validate") end end
	local major, minor, patch = value.major, value.minor, value.patch
	for _, field in ipairs({ "major", "minor", "patch" }) do
		local component = value[field]
		if type(component) ~= "number" or component ~= component or component == math.huge or component < 0 or component ~= math.floor(component) then
			return nil, fail("invalid_version", "Version components must be finite nonnegative integers", "validate")
		end
	end
	return table.freeze({ major = major, minor = minor, patch = patch }), nil
end

local function compare(left: any, right: any): number
	if left.major ~= right.major then return if left.major < right.major then -1 else 1 end
	if left.minor ~= right.minor then return if left.minor < right.minor then -1 else 1 end
	if left.patch ~= right.patch then return if left.patch < right.patch then -1 else 1 end
	return 0
end

local function key(value: any): string return tostring(value.major) .. "." .. tostring(value.minor) .. "." .. tostring(value.patch) end

local function copy(value: any, seen: any, depth: number): (any?, string?)
	local kind = type(value)
	if kind == "nil" or kind == "boolean" then return value, nil end
	if kind == "number" then if value ~= value or value == math.huge or value == -math.huge then return nil, "nonfinite" end return value, nil end
	if kind == "string" then if #value > 8192 then return nil, "string_limit" end return value, nil end
	if kind ~= "table" or getmetatable(value) ~= nil then return nil, "nonportable" end
	if depth >= 32 or seen[value] then return nil, if seen[value] then "cycle" else "depth_limit" end
	seen[value] = true
	local result, count = {}, 0
	for k, v in next, value do
		count += 1
		if count > 512 or (type(k) ~= "string" and type(k) ~= "number") then seen[value] = nil return nil, "invalid_table" end
		local copied, reason = copy(v, seen, depth + 1)
		if reason ~= nil then seen[value] = nil return nil, reason end
		result[k] = copied
	end
	seen[value] = nil
	return table.freeze(result), nil
end

local function portable(value: any): (any?, string?) return copy(value, {}, 0) end

local function declarationSnapshot(declaration: any): any
	return table.freeze({ id = declaration.id, axis = declaration.axis, from = declaration.from, to = declaration.to, implementationId = declaration.implementationId, reversible = declaration.reversible, preservesUnknown = declaration.preservesUnknown })
end

local function normalizeDeclaration(raw: any, operation: string): (any?, StructuredErrorValue?)
	local declaration, reason = portable(raw)
	if declaration == nil or type(declaration) ~= "table" then return nil, fail("invalid_migration_declaration", "Migration declaration must be portable", operation, { reason = reason }) end
	for field in pairs(declaration) do if field ~= "id" and field ~= "axis" and field ~= "from" and field ~= "to" and field ~= "implementationId" and field ~= "reversible" and field ~= "preservesUnknown" then return nil, fail("invalid_migration_declaration", "Migration declaration contains an unknown field", operation) end end
	local id, implementationId = localId(declaration.id), namespacedId(declaration.implementationId)
	local from, fromError = version(declaration.from)
	if from == nil then return nil, fromError end
	local to, toError = version(declaration.to)
	if to == nil then return nil, toError end
	if id == nil or AXES[declaration.axis] ~= true or implementationId == nil or type(declaration.reversible) ~= "boolean" or declaration.preservesUnknown ~= "semantic" or compare(from, to) >= 0 then return nil, fail("invalid_migration_declaration", "Migration declaration has invalid id, axis, version range, or policy", operation) end
	return { id = id, axis = declaration.axis, from = from, to = to, implementationId = implementationId, reversible = declaration.reversible, preservesUnknown = "semantic" }, nil
end

local function denseArray(value: any): boolean
	if type(value) ~= "table" or getmetatable(value) ~= nil then return false end
	local length = #value
	for index = 1, length do if rawget(value, index) == nil then return false end end
	for index in pairs(value) do if type(index) ~= "number" or index < 1 or index > length or index ~= math.floor(index) then return false end end
	return true
end

function MigrationRegistry.new(options: any?): (MigrationRegistry?, StructuredErrorValue?)
	local resolved = options or {}
	if type(resolved) ~= "table" then return nil, fail("invalid_migration_options", "MigrationRegistry options must be a table", "create") end
	local maxDeclarations = resolved.maxDeclarations or MAX_DECLARATIONS
	local maxImplementations = resolved.maxImplementations or MAX_IMPLEMENTATIONS
	if type(maxDeclarations) ~= "number" or maxDeclarations < 1 or maxDeclarations > MAX_DECLARATIONS or maxDeclarations ~= math.floor(maxDeclarations) or type(maxImplementations) ~= "number" or maxImplementations < 1 or maxImplementations > MAX_IMPLEMENTATIONS or maxImplementations ~= math.floor(maxImplementations) then return nil, fail("invalid_migration_limits", "Migration limits must be bounded positive integers", "create") end
	return setmetatable({ _declarations = {}, _implementations = {}, _ownedDeclarations = {}, _declarationCount = 0, _implementationCount = 0, _maxDeclarations = maxDeclarations, _maxImplementations = maxImplementations, _diagnostics = resolved.diagnostics }, MigrationRegistry) :: any, nil
end

function MigrationRegistry:RegisterDeclaration(raw: any): (boolean, StructuredErrorValue?)
	local declaration, declarationError = normalizeDeclaration(raw, "register_declaration")
	if declaration == nil then return false, declarationError end
	if self._declarations[declaration.id] ~= nil then return false, fail("duplicate_migration_declaration", "Migration declaration id already exists", "register_declaration") end
	if self._declarationCount >= self._maxDeclarations then return false, fail("migration_declaration_limit", "Migration declaration capacity reached", "register_declaration") end
	self._declarations[declaration.id] = declaration
	self._declarationCount += 1
	return true, nil
end

function MigrationRegistry:RegisterOwnedDeclarations(rawOwner: any, rawDeclarations: any): (boolean, StructuredErrorValue?)
	local owner = namespacedId(rawOwner)
	if owner == nil then return false, fail("invalid_migration_owner", "Migration declaration owner must be a namespaced id", "register_owned_declarations") end
	if not denseArray(rawDeclarations) then return false, fail("invalid_migration_declarations", "Migration declarations must be a dense plain array", "register_owned_declarations") end
	if self._ownedDeclarations[owner] ~= nil then return false, fail("duplicate_migration_owner", "Migration declaration owner is already registered", "register_owned_declarations") end
	local declarations, ids = {}, {}
	for index, raw in ipairs(rawDeclarations) do
		local declaration, declarationError = normalizeDeclaration(raw, "register_owned_declarations")
		if declaration == nil then return false, declarationError end
		if ids[declaration.id] or self._declarations[declaration.id] ~= nil then return false, fail("duplicate_migration_declaration", "Migration declaration id already exists", "register_owned_declarations", { index = index, id = declaration.id }) end
		ids[declaration.id] = true
		declarations[index] = declaration
	end
	if self._declarationCount + #declarations > self._maxDeclarations then return false, fail("migration_declaration_limit", "Migration declaration capacity reached", "register_owned_declarations") end
	self._ownedDeclarations[owner] = ids
	for _, declaration in ipairs(declarations) do
		self._declarations[declaration.id] = declaration
		self._declarationCount += 1
	end
	return true, nil
end

function MigrationRegistry:RemoveOwnedDeclarations(rawOwner: any): (boolean, StructuredErrorValue?)
	local owner = namespacedId(rawOwner)
	if owner == nil then return false, fail("invalid_migration_owner", "Migration declaration owner must be a namespaced id", "remove_owned_declarations") end
	local ids = self._ownedDeclarations[owner]
	if ids == nil then return true, nil end
	for id in pairs(ids) do
		if self._declarations[id] ~= nil then
			self._declarations[id] = nil
			self._declarationCount -= 1
		end
		if self._implementations[id] ~= nil then
			self._implementations[id] = nil
			self._implementationCount -= 1
		end
	end
	self._ownedDeclarations[owner] = nil
	return true, nil
end

function MigrationRegistry:RegisterImplementation(step: any): (boolean, StructuredErrorValue?)
	if type(step) ~= "table" or getmetatable(step) ~= nil then return false, fail("invalid_migration_step", "Migration step must be a host-only plain table", "register_implementation") end
	for field in pairs(step) do if field ~= "id" and field ~= "declarationId" and field ~= "implementationId" and field ~= "apply" and field ~= "rollback" then return false, fail("invalid_migration_step", "Migration step contains an unknown field", "register_implementation") end end
	local id, declarationId, implementationId = localId(step.id), localId(step.declarationId), namespacedId(step.implementationId)
	if id == nil or declarationId == nil or implementationId == nil or type(step.apply) ~= "function" or (step.rollback ~= nil and type(step.rollback) ~= "function") then return false, fail("invalid_migration_step", "Migration step fields are invalid", "register_implementation") end
	local declaration = self._declarations[declarationId]
	if declaration == nil or declaration.implementationId ~= implementationId then return false, fail("unresolved_implementation", "Migration step does not match a registered declaration", "register_implementation") end
	if declaration.reversible and type(step.rollback) ~= "function" then return false, fail("missing_migration_rollback", "Reversible migration requires a rollback function", "register_implementation") end
	if self._implementations[declarationId] ~= nil then return false, fail("duplicate_migration_implementation", "Implementation already registered for declaration", "register_implementation") end
	if self._implementationCount >= self._maxImplementations then return false, fail("migration_implementation_limit", "Migration implementation capacity reached", "register_implementation") end
	self._implementations[declarationId] = { id = id, declarationId = declarationId, implementationId = implementationId, apply = step.apply, rollback = step.rollback }
	self._implementationCount += 1
	return true, nil
end

function MigrationRegistry:ResolveChain(axis: any, rawFrom: any, rawTo: any): (any?, StructuredErrorValue?)
	if AXES[axis] ~= true then return nil, fail("unknown_migration_axis", "Migration axis is not supported", "resolve") end
	local from, fromError = version(rawFrom)
	if from == nil then return nil, fromError end
	local to, toError = version(rawTo)
	if to == nil then return nil, toError end
	if compare(from, to) > 0 then return nil, fail("reverse_migration_resolution", "ResolveChain only resolves ascending migration chains", "resolve") end
	if compare(from, to) == 0 then return table.freeze({ axis = axis, from = from, to = to, steps = table.freeze({}) }), nil end
	local targetKey = key(to)
	local candidatesByFrom: { [string]: { any } } = {}
	for _, declaration in pairs(self._declarations) do
		if declaration.axis == axis and compare(declaration.to, to) <= 0 and self._implementations[declaration.id] ~= nil then
			local fromKey = key(declaration.from)
			local candidates = candidatesByFrom[fromKey]
			if candidates == nil then
				candidates = {}
				candidatesByFrom[fromKey] = candidates
			end
			table.insert(candidates, declaration)
		end
	end
	for _, candidates in pairs(candidatesByFrom) do
		table.sort(candidates, function(a, b)
			local comparison = compare(a.to, b.to)
			return if comparison ~= 0 then comparison < 0 else a.id < b.id
		end)
	end
	local states, active, deadEnds = 0, {}, {}
	local search: (any, { any }) -> { any }?
	search = function(cursor: any, steps: { any }): { any }?
		local cursorKey = key(cursor)
		if cursorKey == targetKey then return steps end
		if active[cursorKey] or deadEnds[cursorKey] or states >= MAX_CHAIN_SEARCH_STATES then return nil end
		states += 1
		active[cursorKey] = true
		for _, candidate in ipairs(candidatesByFrom[cursorKey] or {}) do
			if not active[key(candidate.to)] then
				table.insert(steps, declarationSnapshot(candidate))
				local resolved = search(candidate.to, steps)
				if resolved ~= nil then
					active[cursorKey] = nil
					return resolved
				end
				table.remove(steps)
			end
		end
		active[cursorKey] = nil
		deadEnds[cursorKey] = true
		return nil
	end
	local steps = search(from, {})
	if steps == nil then return nil, fail("unresolved_migration_chain", "No deterministic complete migration chain exists", "resolve", { axis = axis, from = key(from), to = targetKey }) end
	return table.freeze({ axis = axis, from = from, to = to, steps = table.freeze(steps) }), nil
end

function MigrationRegistry:Apply(axis: any, fromVersion: any, toVersion: any, value: any): (any?, StructuredErrorValue?)
	local chain, chainError = self:ResolveChain(axis, fromVersion, toVersion)
	if chain == nil then return nil, chainError end
	local current, reason = portable(value)
	if current == nil then return nil, fail("portable_input_limit", "Migration input must be portable", "apply", { reason = reason }) end
	for _, declaration in ipairs(chain.steps) do
		local implementation = self._implementations[declaration.id]
		if implementation == nil then return nil, fail("unresolved_implementation", "Migration implementation was removed during apply", "apply", { declarationId = declaration.id }) end
		local ok, output = pcall(implementation.apply, current)
		if not ok then return nil, fail("migration_apply_failed", "Migration implementation failed", "apply", { declarationId = declaration.id }) end
		local copied, outputReason = portable(output)
		if copied == nil then return nil, fail("migration_nonportable_output", "Migration implementation returned nonportable data", "apply", { declarationId = declaration.id, reason = outputReason }) end
		current = copied
	end
	return current, nil
end

function MigrationRegistry:Rollback(chain: any, value: any): (any?, StructuredErrorValue?)
	if type(chain) ~= "table" or not denseArray(chain.steps) then return nil, fail("invalid_migration_chain", "Chain must be produced by ResolveChain", "rollback") end
	for _, declaration in ipairs(chain.steps) do
		if type(declaration) ~= "table" or localId(declaration.id) == nil then
			return nil, fail("invalid_migration_chain", "Chain contains an invalid migration step", "rollback")
		end
	end
	local current, reason = portable(value)
	if current == nil then return nil, fail("portable_input_limit", "Migration input must be portable", "rollback", { reason = reason }) end
	for index = #chain.steps, 1, -1 do
		local declaration = chain.steps[index]
		local implementation = self._implementations[declaration.id]
		if implementation == nil or type(implementation.rollback) ~= "function" then return nil, fail("migration_not_reversible", "Migration chain cannot be rolled back", "rollback", { declarationId = declaration.id }) end
		local ok, output = pcall(implementation.rollback, current)
		if not ok then return nil, fail("migration_rollback_failed", "Migration rollback failed", "rollback", { declarationId = declaration.id }) end
		local copied, outputReason = portable(output)
		if copied == nil then return nil, fail("migration_nonportable_output", "Migration rollback returned nonportable data", "rollback", { declarationId = declaration.id, reason = outputReason }) end
		current = copied
	end
	return current, nil
end

function MigrationRegistry:GetSnapshot(): any
	local declarations = {}
	for id, declaration in pairs(self._declarations) do declarations[id] = declarationSnapshot(declaration) end
	return table.freeze({ declarationCount = self._declarationCount, implementationCount = self._implementationCount, declarations = table.freeze(declarations) })
end

return MigrationRegistry

end

__modules["core/Motion"] = function()
--!strict

export type MotionState = "Running" | "Completed" | "Cancelled" | "Skipped"
export type MotionConnection = {
	Connected: boolean,
	Disconnect: (self: MotionConnection) -> (),
}

export type MotionHandle = {
	Cancel: (self: MotionHandle, reason: string?) -> boolean,
	Finish: (self: MotionHandle) -> boolean,
	IsRunning: (self: MotionHandle) -> boolean,
	OnCompleted: (self: MotionHandle, callback: (state: MotionState, reason: string?) -> ()) -> MotionConnection,
}

export type MotionPreset = {
	Duration: number,
	EasingStyle: Enum.EasingStyle,
	EasingDirection: Enum.EasingDirection,
}

export type AnimateOptions = {
	Preset: string?,
	Duration: number?,
	EasingStyle: Enum.EasingStyle | string?,
	EasingDirection: Enum.EasingDirection | string?,
}

export type Motion = {
	Animate: (
		self: Motion,
		instance: Instance,
		properties: { [string]: any },
		presetOrOptions: string | AnimateOptions?
	) -> MotionHandle,
	Tween: (
		self: Motion,
		instance: Instance,
		properties: { [string]: any },
		duration: number?,
		easing: TweenInfo | Enum.EasingStyle | string?
	) -> Tween?,
	Cancel: (self: Motion, instance: Instance) -> (),
	SetReducedMotion: (self: Motion, reduced: boolean) -> (),
	SetMotionPreset: (self: Motion, name: string, options: AnimateOptions) -> MotionPreset,
	GetMotionPreset: (self: Motion, name: string) -> MotionPreset?,
	ListMotionPresets: (self: Motion) -> { string },
	Destroy: (self: Motion) -> (),
	Presets: { [string]: MotionPreset },
	AnimateBatch: (
		self: Motion,
		entries: { { instance: Instance, properties: { [string]: any }, presetOrOptions: string | AnimateOptions? } },
		presetOrOptions: string | AnimateOptions?
	) -> { MotionHandle },
}

type MotionRecord = {
	instance: Instance?,
	tween: Tween?,
	completedConnection: RBXScriptConnection?,
	goals: { [string]: any }?,
	handle: any?,
	terminal: boolean,
}

local PRESETS = table.freeze({
	instant = table.freeze({
		Duration = 0,
		EasingStyle = Enum.EasingStyle.Quad,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	micro = table.freeze({
		Duration = 0.10,
		EasingStyle = Enum.EasingStyle.Quad,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	quick = table.freeze({
		Duration = 0.12,
		EasingStyle = Enum.EasingStyle.Quart,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	state = table.freeze({
		Duration = 0.14,
		EasingStyle = Enum.EasingStyle.Sine,
		EasingDirection = Enum.EasingDirection.InOut,
	}),
	standard = table.freeze({
		Duration = 0.18,
		EasingStyle = Enum.EasingStyle.Quart,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	enter = table.freeze({
		Duration = 0.18,
		EasingStyle = Enum.EasingStyle.Quart,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	exit = table.freeze({
		Duration = 0.12,
		EasingStyle = Enum.EasingStyle.Quart,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	multiDropdownEnter = table.freeze({
		Duration = 0.20,
		EasingStyle = Enum.EasingStyle.Exponential,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	multiDropdownExit = table.freeze({
		Duration = 0.16,
		EasingStyle = Enum.EasingStyle.Exponential,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	move = table.freeze({
		Duration = 0.22,
		EasingStyle = Enum.EasingStyle.Quart,
		EasingDirection = Enum.EasingDirection.InOut,
	}),
	expressive = table.freeze({
		Duration = 0.26,
		EasingStyle = Enum.EasingStyle.Quart,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	rayfieldHover = table.freeze({
		Duration = 0.25,
		EasingStyle = Enum.EasingStyle.Quint,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	rayfieldHide = table.freeze({
		Duration = 0.35,
		EasingStyle = Enum.EasingStyle.Exponential,
		EasingDirection = Enum.EasingDirection.InOut,
	}),
	rayfieldOption = table.freeze({
		Duration = 0.3,
		EasingStyle = Enum.EasingStyle.Exponential,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	rayfieldPanel = table.freeze({
		Duration = 0.4,
		EasingStyle = Enum.EasingStyle.Quint,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	rayfieldControl = table.freeze({
		Duration = 0.45,
		EasingStyle = Enum.EasingStyle.Exponential,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	rayfieldTheme = table.freeze({
		Duration = 0.5,
		EasingStyle = Enum.EasingStyle.Quint,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	rayfieldToggle = table.freeze({
		Duration = 0.6,
		EasingStyle = Enum.EasingStyle.Exponential,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	rayfieldChevron = table.freeze({
		Duration = 0.7,
		EasingStyle = Enum.EasingStyle.Exponential,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	rayfieldExit = table.freeze({
		Duration = 0.9,
		EasingStyle = Enum.EasingStyle.Exponential,
		EasingDirection = Enum.EasingDirection.Out,
	}),
	rayfieldWindow = table.freeze({
		Duration = 1,
		EasingStyle = Enum.EasingStyle.Exponential,
		EasingDirection = Enum.EasingDirection.InOut,
	}),
})

local Motion = {}
Motion.__index = Motion
Motion.Presets = PRESETS

local Handle = {}
Handle.__index = Handle

local CompletionConnection = {}
CompletionConnection.__index = CompletionConnection

function CompletionConnection:Disconnect()
	if not self.Connected then
		return
	end
	self.Connected = false
	local handle = self._handle
	if handle ~= nil then
		handle._completionCallbacks[self._id] = nil
		self._handle = nil
	end
	self._callback = nil
end

local function invokeCompletion(callback: (state: MotionState, reason: string?) -> (), state: MotionState, reason: string?)
	local ok, err = xpcall(callback, debug.traceback, state, reason)
	if not ok then
		warn("PotassiumUI Motion completion callback failed:\n" .. tostring(err))
	end
end

local function addToMaid(maid: any, task: any)
	if maid == nil then
		return
	end

	if type(maid.GiveTask) == "function" then
		maid:GiveTask(task)
	elseif type(maid.Add) == "function" then
		maid:Add(task)
	end
end

local function fail(code: string, message: string): never
	error({ code = code, message = message }, 3)
end

local function finiteNonNegative(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge and value >= 0
end

local function resolveStyle(value: any): Enum.EasingStyle
	if typeof(value) == "EnumItem" and (value :: EnumItem).EnumType == Enum.EasingStyle then
		return value :: Enum.EasingStyle
	end
	if type(value) == "string" then
		local style = Enum.EasingStyle[value]
		if style then
			return style
		end
	end
	fail("invalid_easing_style", "EasingStyle must be an Enum.EasingStyle or a valid EasingStyle name.")
end

local function resolveDirection(value: any): Enum.EasingDirection
	if typeof(value) == "EnumItem" and (value :: EnumItem).EnumType == Enum.EasingDirection then
		return value :: Enum.EasingDirection
	end
	if type(value) == "string" then
		local direction = Enum.EasingDirection[value]
		if direction then
			return direction
		end
	end
	fail("invalid_easing_direction", "EasingDirection must be an Enum.EasingDirection or a valid EasingDirection name.")
end


local function copyGoals(properties: { [string]: any }): { [string]: any }
	local goals = {}
	for property, value in pairs(properties) do
		goals[property] = value
	end
	return goals
end

local function newHandle(state: MotionState, reason: string?): any
	return setmetatable({
		_state = state,
		_reason = reason,
		_motion = nil,
		_record = nil,
		_completionCallbacks = {} :: { [number]: any },
		_nextCompletionId = 0,
	}, Handle)
end

local function skippedHandle(reason: string): MotionHandle
	return newHandle("Skipped", reason) :: MotionHandle
end

function Handle:Cancel(reason: string?): boolean
	local motion = self._motion
	local record = self._record
	if motion == nil or record == nil then
		return false
	end
	return motion:_terminalize(record, "Cancelled", reason or "cancelled", false)
end

function Handle:Finish(): boolean
	local motion = self._motion
	local record = self._record
	if motion == nil or record == nil then
		return false
	end
	return motion:_terminalize(record, "Completed", "finished", true)
end

function Handle:IsRunning(): boolean
	return self._state == "Running"
end

function Handle:OnCompleted(callback: (state: MotionState, reason: string?) -> ()): MotionConnection
	assert(type(callback) == "function", "MotionHandle:OnCompleted requires a callback")
	local state = self._state :: MotionState
	if state ~= "Running" then
		invokeCompletion(callback, state, self._reason)
		return setmetatable({
			Connected = false,
			_handle = nil,
			_id = 0,
		}, CompletionConnection) :: any
	end

	self._nextCompletionId += 1
	local connection = setmetatable({
		Connected = true,
		_handle = self,
		_id = self._nextCompletionId,
		_callback = callback,
	}, CompletionConnection)
	self._completionCallbacks[connection._id] = connection
	return connection :: any
end

function Handle:_complete(state: MotionState, reason: string?)
	local callbacks = self._completionCallbacks
	self._completionCallbacks = {}
	for _, connection in pairs(callbacks) do
		if connection.Connected then
			local callback = connection._callback
			connection:Disconnect()
			invokeCompletion(callback, state, reason)
		end
	end
end

function Motion.new(
	runtime: any,
	maid: any,
	options: { reducedMotion: boolean?, defaultDuration: number?, presets: { [string]: AnimateOptions }? }?
): Motion
	if options and options.defaultDuration ~= nil and not finiteNonNegative(options.defaultDuration) then
		fail("invalid_default_duration", "defaultDuration must be a finite number greater than or equal to zero.")
	end

	if options and options.reducedMotion ~= nil and type(options.reducedMotion) ~= "boolean" then
		fail("invalid_reduced_motion", "reducedMotion must be a boolean.")
	end

	local services = if runtime and runtime.services then runtime.services else {}
	local presets = {}
	for name, preset in pairs(PRESETS) do
		presets[name] = table.freeze({
			Duration = preset.Duration,
			EasingStyle = preset.EasingStyle,
			EasingDirection = preset.EasingDirection,
		})
	end
	local self = setmetatable({
		_defaultDuration = if options and options.defaultDuration ~= nil
			then options.defaultDuration
			else PRESETS.standard.Duration,
		_destroyed = false,
		_reducedMotion = options and options.reducedMotion == true,
		_records = {} :: { [Instance]: MotionRecord },
		_tweenService = services.TweenService,
		_generations = setmetatable({} :: { [Instance]: number }, { __mode = "k" }),
		Presets = presets,
	}, Motion)

	if options and options.presets then
		assert(type(options.presets) == "table", "Motion presets must be a table.")
		for name, presetOptions in pairs(options.presets) do
			self:SetMotionPreset(name, presetOptions)
		end
	end

	addToMaid(maid, function()
		self:Destroy()
	end)

	return self
end

function Motion:_terminalize(record: MotionRecord, state: MotionState, reason: string, applyGoals: boolean): boolean
	if record.terminal then
		return false
	end

	local instance = record.instance
	if instance == nil or self._records[instance] ~= record then
		return false
	end

	record.terminal = true
	self._records[instance] = nil

	local connection = record.completedConnection
	record.completedConnection = nil
	if connection then
		connection:Disconnect()
	end

	local tween = record.tween
	record.tween = nil
	if tween and reason ~= "completed" then
		tween:Cancel()
	end

	if applyGoals then
		local goals = record.goals
		if goals then
			for property, value in pairs(goals) do
				(instance :: any)[property] = value
			end
		end
	end

	local handle = record.handle
	record.instance = nil
	record.goals = nil
	record.handle = nil
	if handle then
		handle._state = state
		handle._reason = reason
		handle._motion = nil
		handle._record = nil
	end
	if handle then
		handle:_complete(state, reason)
	end

	return true
end

function Motion:Cancel(instance: Instance)
	local record = self._records[instance]
	if record then
		self:_terminalize(record, "Cancelled", "cancelled", false)
	end
end

function Motion:GetMotionPreset(name: string): MotionPreset?
	if type(name) ~= "string" or name == "" then
		fail("invalid_motion_preset", "Preset name must be a non-empty string.")
	end
	local preset = self.Presets[name]
	if preset == nil then
		return nil
	end
	return {
		Duration = preset.Duration,
		EasingStyle = preset.EasingStyle,
		EasingDirection = preset.EasingDirection,
	}
end

function Motion:ListMotionPresets(): { string }
	local names = {}
	for name in pairs(self.Presets) do
		table.insert(names, name)
	end
	table.sort(names)
	return names
end

function Motion:SetMotionPreset(name: string, options: AnimateOptions): MotionPreset
	if self._destroyed then
		fail("motion_destroyed", "Cannot configure presets after Motion is destroyed.")
	end
	if type(name) ~= "string" or name == "" then
		fail("invalid_motion_preset", "Preset name must be a non-empty string.")
	end
	if type(options) ~= "table" then
		fail("invalid_motion_options", "Motion preset options must be a table.")
	end
	for key in pairs(options) do
		if key ~= "Preset" and key ~= "Duration" and key ~= "EasingStyle" and key ~= "EasingDirection" then
			fail("invalid_motion_option", "Unknown motion option: " .. tostring(key))
		end
	end
	local base = self.Presets[name] or self.Presets.standard
	if options.Preset ~= nil then
		if type(options.Preset) ~= "string" then
			fail("invalid_motion_preset", "Preset must be a preset name.")
		end
		base = self.Presets[options.Preset]
		if base == nil then
			fail("unknown_motion_preset", "Unknown motion preset: " .. options.Preset)
		end
	end
	local duration = if options.Duration == nil then base.Duration else options.Duration
	if not finiteNonNegative(duration) or duration > 1 then
		fail("invalid_motion_duration", "Duration must be a finite number between zero and one second.")
	end
	local style = if options.EasingStyle == nil then base.EasingStyle else resolveStyle(options.EasingStyle)
	local direction = if options.EasingDirection == nil
		then base.EasingDirection
		else resolveDirection(options.EasingDirection)
	local preset = table.freeze({
		Duration = duration,
		EasingStyle = style,
		EasingDirection = direction,
	})
	self.Presets[name] = preset
	return {
		Duration = preset.Duration,
		EasingStyle = preset.EasingStyle,
		EasingDirection = preset.EasingDirection,
	}
end

function Motion:_resolveOptions(presetOrOptions: string | AnimateOptions?): MotionPreset
	local preset = self.Presets.standard
	local options: AnimateOptions? = nil

	if presetOrOptions ~= nil then
		if type(presetOrOptions) == "string" then
			preset = self.Presets[presetOrOptions]
			if preset == nil then
				fail("unknown_motion_preset", "Unknown motion preset: " .. presetOrOptions)
			end
		elseif type(presetOrOptions) == "table" then
			options = presetOrOptions
			for key in pairs(options) do
				if key ~= "Preset" and key ~= "Duration" and key ~= "EasingStyle" and key ~= "EasingDirection" then
					fail("invalid_motion_option", "Unknown motion option: " .. tostring(key))
				end
			end
			if options.Preset ~= nil then
				if type(options.Preset) ~= "string" then
					fail("invalid_motion_preset", "Preset must be a preset name.")
				end
				preset = self.Presets[options.Preset]
				if preset == nil then
					fail("unknown_motion_preset", "Unknown motion preset: " .. options.Preset)
				end
			end
		else
			fail("invalid_motion_options", "presetOrOptions must be a preset name or options table.")
		end
	end

	local duration = preset.Duration
	local style = preset.EasingStyle
	local direction = preset.EasingDirection
	if options then
		if options.Duration ~= nil then
			if not finiteNonNegative(options.Duration) or options.Duration > 1 then
				fail("invalid_motion_duration", "Duration must be a finite number between zero and one second.")
			end
			duration = options.Duration
		end
		if options.EasingStyle ~= nil then
			style = resolveStyle(options.EasingStyle)
		end
		if options.EasingDirection ~= nil then
			direction = resolveDirection(options.EasingDirection)
		end
	end

	return { Duration = duration, EasingStyle = style, EasingDirection = direction }
end

function Motion:_publishTween(instance: Instance, goals: { [string]: any }, info: TweenInfo): MotionHandle
	local tween = self._tweenService:Create(instance, info, goals)
	local generation = (self._generations[instance] or 0) + 1
	self._generations[instance] = generation
	self:Cancel(instance)
	if self._generations[instance] ~= generation then
		tween:Cancel()
		return skippedHandle("superseded")
	end
	if self._destroyed then
		tween:Cancel()
		return skippedHandle("destroyed")
	end
	if self._reducedMotion then
		tween:Cancel()
		for property, value in pairs(goals) do
			(instance :: any)[property] = value
		end
		return skippedHandle("reduced-motion")
	end

	local record: MotionRecord = {
		instance = instance,
		tween = tween,
		completedConnection = nil,
		goals = goals,
		handle = nil,
		terminal = false,
	}
	local handle = newHandle("Running", nil)
	handle._motion = self
	handle._record = record
	record.handle = handle
	self._records[instance] = record
	record.completedConnection = tween.Completed:Connect(function(playbackState)
		if playbackState == Enum.PlaybackState.Completed then
			self:_terminalize(record, "Completed", "completed", false)
		else
			self:_terminalize(record, "Cancelled", "cancelled", false)
		end
	end)
	tween:Play()

	return handle
end

function Motion:Animate(
	instance: Instance,
	properties: { [string]: any },
	presetOrOptions: string | AnimateOptions?
): MotionHandle
	if self._destroyed then
		return skippedHandle("destroyed")
	end
	if typeof(instance) ~= "Instance" then
		fail("invalid_motion_instance", "Animate requires an Instance.")
	end
	if type(properties) ~= "table" then
		fail("invalid_motion_properties", "Animate properties must be a table.")
	end

	local resolved = self:_resolveOptions(presetOrOptions)
	local goals = copyGoals(properties)

	if self._reducedMotion or resolved.Duration == 0 then
		local validationTween = self._tweenService:Create(
			instance,
			TweenInfo.new(resolved.Duration, resolved.EasingStyle, resolved.EasingDirection),
			goals
		)
		validationTween:Destroy()
		local generation = (self._generations[instance] or 0) + 1
		self._generations[instance] = generation
		self:Cancel(instance)
		if self._generations[instance] ~= generation then
			return skippedHandle("superseded")
		end
		if self._destroyed then
			return skippedHandle("destroyed")
		end
		for property, value in pairs(goals) do
			(instance :: any)[property] = value
		end
		return skippedHandle(if self._reducedMotion then "reduced-motion" else "instant")
	end

	return self:_publishTween(
		instance,
		goals,
		TweenInfo.new(resolved.Duration, resolved.EasingStyle, resolved.EasingDirection)
	)
end

function Motion:AnimateBatch(
	entries: { { instance: Instance, properties: { [string]: any }, presetOrOptions: string | AnimateOptions? } },
	presetOrOptions: string | AnimateOptions?
): { MotionHandle }
	if type(entries) ~= "table" then
		fail("invalid_motion_batch", "AnimateBatch requires an array of animation entries.")
	end
	local handles = {}
	for index, entry in ipairs(entries) do
		if type(entry) ~= "table" then
			fail("invalid_motion_batch", "Batch entry " .. tostring(index) .. " must be a table.")
		end
		table.insert(handles, self:Animate(entry.instance, entry.properties, entry.presetOrOptions or presetOrOptions))
	end
	return handles
end

function Motion:Tween(
	instance: Instance,
	properties: { [string]: any },
	duration: number?,
	easing: TweenInfo | Enum.EasingStyle | string?
): Tween?
	if typeof(easing) == "TweenInfo" then
		if self._destroyed then
			return nil
		end
		if typeof(instance) ~= "Instance" then
			fail("invalid_motion_instance", "Animate requires an Instance.")
		end
		if type(properties) ~= "table" then
			fail("invalid_motion_properties", "Animate properties must be a table.")
		end

		local info = easing :: TweenInfo
		local goals = copyGoals(properties)
		if self._reducedMotion or info.Time == 0 then
			local validationTween = self._tweenService:Create(instance, info, goals)
			validationTween:Destroy()
			local generation = (self._generations[instance] or 0) + 1
			self._generations[instance] = generation
			self:Cancel(instance)
			if self._generations[instance] ~= generation or self._destroyed then
				return nil
			end
			for property, value in pairs(goals) do
				(instance :: any)[property] = value
			end
			return nil
		end

		local handle = self:_publishTween(instance, goals, info)
		local record = (handle :: any)._record
		return if record then record.tween else nil
	end

	local handle = self:Animate(instance, properties, {
		Duration = if duration == nil then self._defaultDuration else duration,
		EasingStyle = if easing == nil then Enum.EasingStyle.Quart else easing,
		EasingDirection = Enum.EasingDirection.Out,
	})
	local record = (handle :: any)._record
	return if record then record.tween else nil
end

function Motion:SetReducedMotion(reduced: boolean)
	if self._destroyed then
		return
	end
	if type(reduced) ~= "boolean" then
		fail("invalid_reduced_motion", "reduced must be a boolean.")
	end
	if self._reducedMotion == reduced then
		return
	end

	self._reducedMotion = reduced
	if reduced then
		local pending = {}
		for _, record in pairs(self._records) do
			table.insert(pending, record)
		end
		for _, record in ipairs(pending) do
			self:_terminalize(record, "Skipped", "reduced-motion", true)
		end
	end
end

function Motion:Destroy()
	if self._destroyed then
		return
	end

	self._destroyed = true
	local pending = {}
	for _, record in pairs(self._records) do
		table.insert(pending, record)
	end
	for _, record in ipairs(pending) do
		self:_terminalize(record, "Cancelled", "destroyed", false)
	end
end

return Motion

end

__modules["core/NavigationModel"] = function()
--!strict

local Signal = __require("core/Signal")
local StructuredError = __require("core/StructuredError")

local NavigationModel = {}
NavigationModel.__index = NavigationModel
local function error(code: string, message: string, operation: string, details: any?): any return StructuredError.from(code, message, { domain = "route", operation = operation, details = details }) end
local function frozenStack(stack: { any }): { any } local result = {}; for index, route in ipairs(stack) do result[index] = table.freeze({ id = route.id, params = route.params, source = route.source, generation = route.generation }) end; return table.freeze(result) end
function NavigationModel.new(): any return setmetatable({ _routes = {}, _stack = {}, _generation = 0, _cancelledGeneration = nil, _signal = Signal.new(), _destroyed = false }, NavigationModel) end
function NavigationModel:GetSnapshot(): any
	local selected = self._stack[#self._stack]
	return table.freeze({ stack = frozenStack(self._stack), selectedRoute = if selected then selected.id else nil, source = if selected then selected.source else nil, generation = self._generation, revision = self._generation })
end
function NavigationModel:_publish() self._signal:Fire(self:GetSnapshot()) end
function NavigationModel:Register(id: string, definition: any?): (boolean, any?)
	if self._destroyed then return false, error("destroyed", "NavigationModel is destroyed", "register") end
	if type(id) ~= "string" or id == "" or self._routes[id] then return false, error("invalid_route", "Route id must be unique and nonempty", "register", { id = id }) end
	self._routes[id] = table.freeze({ id = id, definition = definition }); return true, nil
end
function NavigationModel:_commit(id: string, params: any, source: any, replace: boolean): (any?, any?)
	if self._destroyed or not self._routes[id] then return nil, error("unknown_route", "Route id is not registered", if replace then "replace" else "navigate", { id = id }) end
	self._generation += 1
	local generation = self._generation
	self._cancelledGeneration = nil
	local route = { id = id, params = params, source = type(source) == "string" and source or "programmatic", generation = generation }
	if replace and #self._stack > 0 then self._stack[#self._stack] = route else table.insert(self._stack, route) end
	local definition = self._routes[id].definition
	self:_publish()
	if not self._destroyed and self._generation == generation and type(definition) == "table" and type(definition.onNavigate) == "function" then
		task.spawn(function()
			local context = table.freeze({
				id = id,
				params = params,
				generation = generation,
				IsCancelled = function()
					return self._destroyed or self._generation ~= generation or self._cancelledGeneration == generation
				end,
			})
			pcall(definition.onNavigate, context)
		end)
	end
	return self:GetSnapshot(), nil
end
function NavigationModel:Navigate(id: string, params: any?, source: any?): (any?, any?) return self:_commit(id, params, source, false) end
function NavigationModel:Replace(id: string, params: any?, source: any?): (any?, any?) return self:_commit(id, params, source, true) end
function NavigationModel:Back(source: any?): (any?, any?)
	if self._destroyed then return nil, error("destroyed", "NavigationModel is destroyed", "back") end
	if #self._stack <= 1 then return self:GetSnapshot(), nil end
	self._generation += 1
	self._cancelledGeneration = nil
	table.remove(self._stack)
	self._stack[#self._stack].source = type(source) == "string" and source or "back"
	self._stack[#self._stack].generation = self._generation
	self:_publish()
	return self:GetSnapshot(), nil
end
function NavigationModel:Cancel(): boolean
	if self._destroyed or self._generation == 0 then return false end
	self._cancelledGeneration = self._generation
	return true
end
function NavigationModel:Observe(callback: (any) -> (), options: any?): any
	assert(type(callback) == "function", "Navigation observer callback is required")
	local connection = self._signal:Connect(callback); if type(options) == "table" and options.EmitInitial == true then callback(self:GetSnapshot()) end; return connection
end
function NavigationModel:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	self._cancelledGeneration = nil
	table.clear(self._routes)
	table.clear(self._stack)
	self._signal:Destroy()
end
return NavigationModel

end

__modules["core/OrderingModel"] = function()
--!strict

local Signal = __require("core/Signal")
local StructuredError = __require("core/StructuredError")

local OrderingModel = {}
OrderingModel.__index = OrderingModel
local MAX_SIBLINGS = 256

local function fail(code: string, message: string, operation: string, details: any?): any
	return StructuredError.from(code, message, { domain = "ordering", operation = operation, details = details })
end

local function validId(value: any): boolean
	return type(value) == "string" and #value > 0 and #value <= 129
end

local function checkedIds(ids: any): (any?, any?)
	if type(ids) ~= "table" then return nil, fail("invalid_order_ids", "Order ids must be a dense array", "set") end
	if #ids > MAX_SIBLINGS then return nil, fail("order_sibling_limit", "Order cannot exceed 256 siblings", "set") end
	local copy, seen = {}, {}
	for index = 1, #ids do
		local id = rawget(ids, index)
		if not validId(id) or seen[id] then return nil, fail("invalid_order_ids", "Order ids must be unique nonempty strings", "set", { index = index }) end
		copy[index], seen[id] = id, true
	end
	for key in pairs(ids) do if type(key) ~= "number" or key < 1 or key > #ids or key ~= math.floor(key) then return nil, fail("invalid_order_ids", "Order ids must be a dense array", "set") end end
	return copy, nil
end

local function same(left: any, right: any): boolean
	if #left ~= #right then return false end
	for index, id in ipairs(left) do if right[index] ~= id then return false end end
	return true
end

function OrderingModel.new(parentId: any, ids: any?): (any?, any?)
	if not validId(parentId) then return nil, fail("invalid_order_parent", "Order parentId must be a nonempty string", "create") end
	local initial, initialError = checkedIds(ids or {})
	if initial == nil then return nil, initialError end
	return setmetatable({ _parentId = parentId, _ids = initial, _revision = 0, _signal = Signal.new(), _destroyed = false }, OrderingModel), nil
end

function OrderingModel:GetSnapshot(): any
	local ids = table.create(#self._ids)
	for index, id in ipairs(self._ids) do ids[index] = id end
	return table.freeze({ parentId = self._parentId, revision = self._revision, ids = table.freeze(ids) })
end

function OrderingModel:ProjectLayoutOrders(): any
	local projection = {}
	for index, id in ipairs(self._ids) do projection[id] = index end
	return table.freeze(projection)
end

function OrderingModel:ProjectLayoutOrdersFor(ids: any): any
	local projection = {}
	for index, id in ipairs(ids or {}) do projection[id] = index end
	return table.freeze(projection)
end

function OrderingModel:GetLayoutOrder(id: any): (number?, any?)
	if not validId(id) then return nil, fail("invalid_order_id", "Order id must be a nonempty string", "project") end
	for index, candidate in ipairs(self._ids) do if candidate == id then return index, nil end end
	return nil, fail("unknown_order_id", "Order id is not a sibling", "project", { id = id })
end

function OrderingModel:_commit(nextIds: any): (any?, any?)
	if self._destroyed then return nil, fail("destroyed_ordering", "OrderingModel has been destroyed", "move") end
	if same(self._ids, nextIds) then return self:GetSnapshot(), nil end
	self._ids = nextIds
	self._revision += 1
	local snapshot = self:GetSnapshot()
	self._signal:Fire(snapshot)
	return snapshot, nil
end

function OrderingModel:Set(ids: any): (any?, any?)
	if self._destroyed then return nil, fail("destroyed_ordering", "OrderingModel has been destroyed", "set") end
	local nextIds, idsError = checkedIds(ids)
	if nextIds == nil then return nil, idsError end
	return self:_commit(nextIds)
end

-- A staged order is intentionally inert: callers can preflight every consumer
-- before a revision or observer ever sees the candidate order.
function OrderingModel:Stage(ids: any): (any?, any?)
	if self._destroyed then return nil, fail("destroyed_ordering", "OrderingModel has been destroyed", "stage") end
	local nextIds, idsError = checkedIds(ids)
	if nextIds == nil then return nil, idsError end
	local baseIds = table.create(#self._ids)
	for index, id in ipairs(self._ids) do baseIds[index] = id end
	return table.freeze({
		model = self,
		ids = table.freeze(nextIds),
		changed = not same(self._ids, nextIds),
		baseRevision = self._revision,
		baseIds = table.freeze(baseIds),
	}), nil
end

function OrderingModel:StageMove(id: any, index: any): (any?, any?)
	if self._destroyed then return nil, fail("destroyed_ordering", "OrderingModel has been destroyed", "stageMove") end
	if not validId(id) or type(index) ~= "number" or index ~= math.floor(index) then
		return nil, fail("invalid_order_move", "Move requires a sibling id and integer index", "stageMove")
	end
	local source: number? = nil
	for candidateIndex, candidate in ipairs(self._ids) do
		if candidate == id then
			source = candidateIndex
			break
		end
	end
	if source == nil then return nil, fail("unknown_order_id", "Order id is not a sibling", "stageMove", { id = id }) end
	if index < 1 or index > #self._ids then
		return nil, fail("invalid_order_index", "Move index is outside sibling bounds", "stageMove", { index = index })
	end
	local nextIds = table.create(#self._ids)
	for _, candidate in ipairs(self._ids) do
		if candidate ~= id then table.insert(nextIds, candidate) end
	end
	table.insert(nextIds, index, id)
	return self:Stage(nextIds)
end

local function validateStaged(self: any, staged: any, operation: string): any?
	if type(staged) ~= "table"
		or staged.model ~= self
		or type(staged.ids) ~= "table"
		or type(staged.baseIds) ~= "table"
		or type(staged.baseRevision) ~= "number"
		or type(staged.changed) ~= "boolean"
	then
		return fail("invalid_staged_order", "Order stage belongs to a different model", operation)
	end
	if self._destroyed then return fail("destroyed_ordering", "OrderingModel has been destroyed", operation) end
	if staged.baseRevision ~= self._revision or not same(staged.baseIds, self._ids) then
		return fail("stale_order_stage", "Order stage was superseded before commit", operation)
	end
	return nil
end

function OrderingModel:GetStagedSnapshot(staged: any): (any?, any?)
	local stageError = validateStaged(self, staged, "stage")
	if stageError then return nil, stageError end
	local ids = table.create(#staged.ids)
	for index, id in ipairs(staged.ids) do ids[index] = id end
	return table.freeze({ parentId = self._parentId, revision = staged.baseRevision + (if staged.changed then 1 else 0), ids = table.freeze(ids) }), nil
end

function OrderingModel:CommitStaged(staged: any): (any?, any?)
	local snapshot, snapshotError = self:GetStagedSnapshot(staged)
	if snapshot == nil then return nil, snapshotError end
	if not staged.changed then return snapshot, nil end
	local ids = table.create(#staged.ids)
	for index, id in ipairs(staged.ids) do ids[index] = id end
	return self:_commit(ids)
end

function OrderingModel:RollbackStaged(staged: any): (any?, any?)
	if type(staged) ~= "table"
		or staged.model ~= self
		or type(staged.ids) ~= "table"
		or type(staged.baseIds) ~= "table"
		or type(staged.baseRevision) ~= "number"
		or type(staged.changed) ~= "boolean"
	then
		return nil, fail("invalid_staged_order", "Order stage belongs to a different model", "rollback")
	end
	if self._destroyed then return nil, fail("destroyed_ordering", "OrderingModel has been destroyed", "rollback") end
	if not staged.changed then
		if staged.baseRevision ~= self._revision or not same(staged.baseIds, self._ids) then
			return nil, fail("stale_order_stage", "Order stage was superseded before rollback", "rollback")
		end
		return self:GetSnapshot(), nil
	end
	if self._revision ~= staged.baseRevision + 1 or not same(staged.ids, self._ids) then
		return nil, fail("stale_order_stage", "Order stage was superseded before rollback", "rollback")
	end
	local ids = table.create(#staged.baseIds)
	for index, id in ipairs(staged.baseIds) do ids[index] = id end
	return self:_commit(ids)
end

function OrderingModel:Move(id: any, index: any): (any?, any?)
	if self._destroyed then return nil, fail("destroyed_ordering", "OrderingModel has been destroyed", "move") end
	if not validId(id) or type(index) ~= "number" or index ~= math.floor(index) then return nil, fail("invalid_order_move", "Move requires a sibling id and integer index", "move") end
	local source: number? = nil
	for candidateIndex, candidate in ipairs(self._ids) do if candidate == id then source = candidateIndex break end end
	if source == nil then return nil, fail("unknown_order_id", "Order id is not a sibling", "move", { id = id }) end
	if index < 1 or index > #self._ids then return nil, fail("invalid_order_index", "Move index is outside sibling bounds", "move", { index = index }) end
	if source == index then return self:GetSnapshot(), nil end
	local nextIds = table.create(#self._ids)
	for _, candidate in ipairs(self._ids) do if candidate ~= id then table.insert(nextIds, candidate) end end
	table.insert(nextIds, index, id)
	return self:_commit(nextIds)
end

function OrderingModel:MoveBefore(id: any, beforeId: any): (any?, any?)
	if not validId(beforeId) then return nil, fail("invalid_order_move", "MoveBefore requires a sibling anchor", "moveBefore") end
	local index: number? = nil
	for candidateIndex, candidate in ipairs(self._ids) do if candidate == beforeId then index = candidateIndex break end end
	if index == nil then return nil, fail("unknown_order_id", "Order anchor is not a sibling", "moveBefore", { id = beforeId }) end
	local source: number? = nil; for candidateIndex, candidate in ipairs(self._ids) do if candidate == id then source = candidateIndex break end end
	if source and source < index then index -= 1 end
	return self:Move(id, index)
end

function OrderingModel:MoveAfter(id: any, afterId: any): (any?, any?)
	if not validId(afterId) then return nil, fail("invalid_order_move", "MoveAfter requires a sibling anchor", "moveAfter") end
	local index: number? = nil
	for candidateIndex, candidate in ipairs(self._ids) do if candidate == afterId then index = candidateIndex break end end
	if index == nil then return nil, fail("unknown_order_id", "Order anchor is not a sibling", "moveAfter", { id = afterId }) end
	local source: number? = nil; for candidateIndex, candidate in ipairs(self._ids) do if candidate == id then source = candidateIndex break end end
	if source and source <= index then index -= 1 end
	return self:Move(id, index + 1)
end

function OrderingModel:MoveFirst(id: any): (any?, any?) return self:Move(id, 1) end
function OrderingModel:MoveLast(id: any): (any?, any?) return self:Move(id, #self._ids) end
function OrderingModel:Observe(callback: any, options: any?): any
	if type(callback) ~= "function" then error("Ordering observer callback is required") end
	local connection = self._signal:Connect(callback)
	if type(options) == "table" and options.EmitInitial == true then callback(self:GetSnapshot()) end
	return connection
end
function OrderingModel:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	table.clear(self._ids)
	self._signal:Destroy()
end

return OrderingModel

end

__modules["core/Persistence"] = function()
--!strict

local Util = __require("core/Util")

export type PersistenceError = {
	code: string,
	message: string,
}

export type PersistenceOptions = {
	folder: string?,
	extension: string?,
	schemaVersion: number?,
	libraryVersion: string?,
	debounceSeconds: number?,
	migrate: ((config: { [string]: any }, fromVersion: number, toVersion: number) -> { [string]: any }?)?,
	suppressCallbacksDuringLoad: boolean?,
	replayCallbacksDuringTrustedRestore: boolean?,
	RestoreCallback: ((config: { [string]: any }, generation: number) -> ())?,
	restoreCallback: ((config: { [string]: any }, generation: number) -> ())?,
	base64: boolean?,
	storage: { [string]: any }?,
}
type Store = { [string]: any }
type Runtime = { [string]: any }
type Storage = { [string]: any }
type Connection = { Disconnect: (self: Connection) -> () }

type Persistence = {
	Save: (self: Persistence, profileName: string?) -> (boolean, { [string]: any } | PersistenceError),
	Load: (self: Persistence, profileName: string?) -> (boolean, { [string]: any } | PersistenceError),
	Delete: (self: Persistence, profileName: string?) -> (boolean, boolean | PersistenceError),
	List: (self: Persistence) -> (boolean, { string } | PersistenceError),
	Export: (self: Persistence, profileName: string?) -> (boolean, string | PersistenceError),
	Import: (
		self: Persistence,
		profileName: string,
		encoded: string
	) -> (boolean, { [string]: any } | PersistenceError),
	SetFolder: (self: Persistence, folder: string) -> (boolean, string | PersistenceError),
	SetAutoLoad: (self: Persistence, profileName: string?) -> (boolean, string | PersistenceError),
	GetAutoLoad: (self: Persistence) -> (boolean, string | PersistenceError),
	ClearAutoLoad: (self: Persistence) -> (boolean, boolean | PersistenceError),
	LoadAuto: (self: Persistence) -> (boolean, { [string]: any } | PersistenceError),
	SetAutosave: (self: Persistence, enabled: boolean, profileName: string?) -> (boolean, boolean | PersistenceError),
	SaveWorkspace: (self: Persistence, name: string, snapshot: { [string]: any }) -> (boolean, { [string]: any } | PersistenceError),
	LoadWorkspace: (self: Persistence, name: string) -> (boolean, { [string]: any } | PersistenceError),
	DeleteWorkspace: (self: Persistence, name: string) -> (boolean, boolean | PersistenceError),
	ListWorkspaces: (self: Persistence) -> (boolean, { string } | PersistenceError),
	SaveInternal: (self: Persistence, name: string, snapshot: { [string]: any }) -> (boolean, { [string]: any } | PersistenceError),
	LoadInternal: (self: Persistence, name: string) -> (boolean, { [string]: any } | PersistenceError),
	Destroy: (self: Persistence) -> (boolean, boolean | PersistenceError),
}
local Persistence = {}
Persistence.__index = Persistence

-- Persistence limits apply before untrusted data reaches runtime adapters.
local MAX_ENCODED_INPUT_BYTES = 256 * 1024
local MAX_BASE64_DECODED_BYTES = 192 * 1024
local MAX_DECODED_TABLE_DEPTH = 32
local MAX_DECODED_TABLE_NODES = 4096
local MAX_DECODED_TABLE_ENTRIES = 8192
local MAX_DECODED_STRING_BYTES = 256 * 1024

local DEFAULT_FOLDER = "PotassiumUI"
local DEFAULT_EXTENSION = ".json"
local DEFAULT_PROFILE = "default"
local DEFAULT_SCHEMA_VERSION = 1
local DEFAULT_DEBOUNCE_SECONDS = 1
local AUTOLOAD_FILENAME = "._autoload.json"
local AUTOLOAD_SCHEMA_VERSION = 1

local INTERNAL_PREFIX = ".__internal-"
local WORKSPACE_PREFIX = "__workspace-"

local function errorResult(code: string, message: string): PersistenceError
	return { code = code, message = message }
end

local function call(target: any, methodName: string, ...: any): (boolean, any, any)
	if type(target) ~= "table" then
		return false, "adapter is unavailable", nil
	end

	local method = target[methodName]
	if type(method) ~= "function" then
		return false, "adapter method is unavailable", nil
	end

	return pcall(method, target, ...)
end

local function callFirst(target: any, names: { string }, ...: any): (boolean, any, boolean, any)
	for _, name in ipairs(names) do
		if type(target) == "table" and type(target[name]) == "function" then
			local ok, value, reason = call(target, name, ...)
			return ok, value, true, reason
		end
	end
	return false, "adapter method is unavailable", false, nil
end

local function callMutationFirst(target: any, names: { string }, ...: any): (boolean, any, boolean)
	local invoked, result, available, reason = callFirst(target, names, ...)
	if not available then
		return false, result, false
	end
	if not invoked then
		return false, result, true
	end
	if result == false then
		return false, reason, true
	end
	return true, result, true
end

local function sanitizeProfile(profileName: string?): (boolean, string | PersistenceError)
	local name = profileName or DEFAULT_PROFILE
	if type(name) ~= "string" then
		return false, errorResult("INVALID_PROFILE", "Profile names must be strings.")
	end

	name = string.gsub(name, "^%s+", "")
	name = string.gsub(name, "%s+$", "")
	if #name == 0 or #name > 64 or name == "." or name == ".." or not string.match(name, "^[%w][%w _%-]*$") then
		return false,
			errorResult(
				"INVALID_PROFILE",
				"Profile names may contain only letters, numbers, spaces, underscores, and hyphens."
			)
	end

	return true, name
end

local function sanitizeFolder(folder: any): (boolean, string | PersistenceError)
	if type(folder) ~= "string" then
		return false, errorResult("INVALID_FOLDER", "Persistence folder must be a relative path string.")
	end
	if #folder == 0 or #folder > 128 or string.find(folder, "[%z\1-\31\127]") then
		return false, errorResult("INVALID_FOLDER", "Persistence folder must be a short safe relative path.")
	end
	if string.sub(folder, 1, 1) == "/" or string.find(folder, "\\", 1, true) or string.match(folder, "^%a:") then
		return false, errorResult("INVALID_FOLDER", "Persistence folder must be a relative path.")
	end
	for segment in string.gmatch(folder, "[^/]+") do
		if segment == "." or segment == ".." or not string.match(segment, "^[%w][%w _%-]*$") then
			return false, errorResult("INVALID_FOLDER", "Persistence folder contains an unsafe path segment.")
		end
	end
	if string.find(folder, "//", 1, true) or string.sub(folder, -1) == "/" then
		return false, errorResult("INVALID_FOLDER", "Persistence folder contains an unsafe path separator.")
	end
	return true, folder
end

local function sanitizeExtension(extension: any): (boolean, string | PersistenceError)
	if type(extension) ~= "string" or #extension < 2 or #extension > 16 or not string.match(extension, "^%.[%w]+$") then
		return false, errorResult("INVALID_EXTENSION", "Persistence extension must be a short dot-prefixed alphanumeric suffix.")
	end
	return true, extension
end

local function validateDecodedTable(root: any): (boolean, PersistenceError?)
	if type(root) ~= "table" then
		return false, errorResult("DECODE_FAILED", "Persistence data is not valid JSON.")
	end
	local nodes, entries, stringBytes = 0, 0, 0
	local visited = {}
	local function scan(value: any, depth: number): boolean
		local valueType = type(value)
		if valueType == "string" then
			stringBytes += #value
			return stringBytes <= MAX_DECODED_STRING_BYTES
		end
		if valueType ~= "table" then return true end
		if depth > MAX_DECODED_TABLE_DEPTH or visited[value] then return false end
		visited[value] = true
		nodes += 1
		if nodes > MAX_DECODED_TABLE_NODES then return false end
		for key, nested in pairs(value) do
			entries += 1
			if entries > MAX_DECODED_TABLE_ENTRIES or not scan(key, depth + 1) or not scan(nested, depth + 1) then
				return false
			end
		end
		return true
	end
	if not scan(root, 0) then
		return false, errorResult("PAYLOAD_LIMIT_EXCEEDED", "Persistence data exceeds safe structural limits.")
	end
	return true
end

local function normalizePath(folder: string, filename: string): string
	if string.sub(folder, -1) == "/" or string.sub(folder, -1) == "\\" then
		return folder .. filename
	end
	return folder .. "/" .. filename
end

local function decodeBase64(value: string): string?
	local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	if #value % 4 ~= 0 or string.find(value, "[^" .. alphabet .. "=]") then
		return nil
	end
	local padding = if string.sub(value, -2) == "==" then 2 else if string.sub(value, -1) == "=" then 1 else 0
	local firstPadding = string.find(value, "=", 1, true)
	if firstPadding and firstPadding ~= #value - padding + 1 then
		return nil
	end
	local chunks = table.create(#value / 4)
	for index = 1, #value, 4 do
		local first = string.find(alphabet, string.sub(value, index, index), 1, true)
		local second = string.find(alphabet, string.sub(value, index + 1, index + 1), 1, true)
		local thirdIndex = if string.sub(value, index + 2, index + 2) == "=" then 1 else string.find(alphabet, string.sub(value, index + 2, index + 2), 1, true)
		local fourthIndex = if string.sub(value, index + 3, index + 3) == "=" then 1 else string.find(alphabet, string.sub(value, index + 3, index + 3), 1, true)
		if not first or not second or not thirdIndex or not fourthIndex then return nil end
		local value24 = ((first - 1) * 262144) + ((second - 1) * 4096) + ((thirdIndex - 1) * 64) + (fourthIndex - 1)
		local bytes = string.char(math.floor(value24 / 65536) % 256)
		if index + 2 <= #value - padding then bytes ..= string.char(math.floor(value24 / 256) % 256) end
		if index + 3 <= #value - padding then bytes ..= string.char(value24 % 256) end
		chunks[(index + 3) / 4] = bytes
	end
	return table.concat(chunks)
end

local function encodeBase64(value: string): string
	local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local bits = string.gsub(value, ".", function(character)
		local number = string.byte(character)
		local binary = ""
		for power = 8, 1, -1 do
			binary ..= if number % 2 ^ power - number % 2 ^ (power - 1) > 0 then "1" else "0"
		end
		return binary
	end) .. "0000"

	return (
		string.gsub(bits, "%d%d%d?%d?%d?%d?", function(chunk)
			if #chunk < 6 then
				return ""
			end
			local number = 0
			for index = 1, 6 do
				if string.sub(chunk, index, index) == "1" then
					number += 2 ^ (6 - index)
				end
			end
			return string.sub(alphabet, number + 1, number + 1)
		end) .. ({ "", "==", "=" })[#value % 3 + 1]
	)
end

function Persistence.new(store: Store, runtime: Runtime, options: PersistenceOptions?): Persistence
	assert(type(store) == "table", "Persistence.new requires a Store table")
	assert(type(runtime) == "table", "Persistence.new requires a runtime table")

	local opts = options or {}
	local folderValid, folder = sanitizeFolder(if opts.folder ~= nil then opts.folder else DEFAULT_FOLDER)
	if not folderValid then error((folder :: PersistenceError).message, 2) end
	local extensionValid, extension = sanitizeExtension(if opts.extension ~= nil then opts.extension else DEFAULT_EXTENSION)
	if not extensionValid then error((extension :: PersistenceError).message, 2) end
	local storage = opts.storage or runtime.storage or (runtime.capabilities and runtime.capabilities.storage)
	local self = setmetatable({
		_store = store,
		_runtime = runtime,
		_storage = storage,
		_folder = folder :: string,
		_extension = extension :: string,
		_schemaVersion = opts.schemaVersion or DEFAULT_SCHEMA_VERSION,
		_libraryVersion = opts.libraryVersion or "unknown",
		_debounceSeconds = math.max(0, opts.debounceSeconds or DEFAULT_DEBOUNCE_SECONDS),
		_migrate = opts.migrate,
		_suppressCallbacks = opts.replayCallbacksDuringTrustedRestore ~= true,
		_base64 = opts.base64 == true,
		_autosave = false,
		_autosaveProfile = DEFAULT_PROFILE,
		_dirty = false,
		_destroyed = false,
		_workspaceMemory = {},
		_generation = 0,
		_subscription = nil :: Connection | (() -> ()) | nil,
		_hydrating = false,
		_restoreCallback = opts.RestoreCallback or opts.restoreCallback,
		_restoreGeneration = 0,
	}, Persistence)

	return self
end
function Persistence:SetFolder(folder: string): (boolean, string | PersistenceError)
	if self._destroyed then
		return false, errorResult("DESTROYED", "Persistence has been destroyed.")
	end
	local valid, sanitized = sanitizeFolder(folder)
	if not valid then
		return false, sanitized
	end
	if self._folder ~= sanitized then table.clear(self._workspaceMemory) end
	self._folder = sanitized :: string
	return true, self._folder
end

function Persistence:_storageError(operation: string, reason: any): PersistenceError
	local normalizedOperation = string.gsub(string.upper(operation), "%s+", "_")
	return errorResult(
		"STORAGE_" .. normalizedOperation,
		"Unable to " .. operation .. " persistence data: " .. tostring(reason)
	)
end

function Persistence:_ensureFolder(): (boolean, PersistenceError?)
	local storage = self._storage
	if type(storage) ~= "table" then
		return false, errorResult("STORAGE_UNAVAILABLE", "No injected runtime storage adapter is available.")
	end

	local existsOk, exists, hasExists =
		callFirst(storage, { "isFolder", "IsFolder", "folderExists", "FolderExists" }, self._folder)
	if hasExists and existsOk and exists == true then
		return true
	end

	local created, reason, available = callMutationFirst(
		storage,
		{ "makeFolder", "MakeFolder", "createFolder", "CreateFolder", "mkdir", "Mkdir" },
		self._folder
	)
	if not available then
		if hasExists and existsOk then
			return false, self:_storageError("create folder", "storage adapter cannot create folders")
		end
		return true
	end
	if not created then
		local verified, present =
			callFirst(storage, { "isFolder", "IsFolder", "folderExists", "FolderExists" }, self._folder)
		if not (verified and present == true) then
			return false, self:_storageError("create folder", reason)
		end
	end
	return true
end

function Persistence:_path(profileName: string): string
	return normalizePath(self._folder, profileName .. self._extension)
end

function Persistence:_autoloadPath(): string
	return normalizePath(self._folder, AUTOLOAD_FILENAME)
end

function Persistence:_snapshot(): (boolean, { [string]: any } | PersistenceError)
	local store = self._store
	local ok, values, available = callFirst(store, { "Snapshot", "GetSnapshot", "GetValues", "Serialize" })
	if available then
		if not ok or type(values) ~= "table" then
			return false, errorResult("SNAPSHOT_FAILED", "Store could not provide a persistence snapshot.")
		end
		return true, values
	end
	if type(store.values) == "table" then
		return true, store.values
	end
	return false, errorResult("SNAPSHOT_UNAVAILABLE", "Store does not expose a snapshot method.")
end

function Persistence:_encode(config: { [string]: any }): (boolean, string | PersistenceError)
	local runtime = self._runtime
	local ok, encoded, available =
		callFirst(runtime, { "jsonEncode", "JSONEncode", "encodeJSON", "EncodeJSON" }, config)
	if not available or not ok or type(encoded) ~= "string" then
		return false, errorResult("ENCODE_FAILED", "Runtime JSON encoding failed.")
	end
	if self._base64 then
		local base64Ok, base64, base64Available =
			callFirst(runtime, { "base64Encode", "Base64Encode", "encodeBase64", "EncodeBase64" }, encoded)
		if base64Available and base64Ok and type(base64) == "string" then
			return true, base64
		end
		return true, encodeBase64(encoded)
	end
	return true, encoded
end

function Persistence:_decode(encoded: string): (boolean, { [string]: any } | PersistenceError)
	if type(encoded) ~= "string" or #encoded > MAX_ENCODED_INPUT_BYTES then
		return false, errorResult("PAYLOAD_LIMIT_EXCEEDED", "Persistence data exceeds the encoded input limit.")
	end
	local payload = encoded
	if self._base64 then
		if math.floor(#payload / 4) * 3 > MAX_BASE64_DECODED_BYTES then
			return false, errorResult("PAYLOAD_LIMIT_EXCEEDED", "Persistence data exceeds the Base64 decoded input limit.")
		end
		local base64Ok, base64, base64Available =
			callFirst(self._runtime, { "base64Decode", "Base64Decode", "decodeBase64", "DecodeBase64" }, payload)
		if base64Available then
			if not base64Ok or type(base64) ~= "string" then
				return false, errorResult("DECODE_FAILED", "Runtime Base64 decoding failed.")
			end
			payload = base64
		else
			local decoded = decodeBase64(payload)
			if not decoded then
				return false, errorResult("DECODE_FAILED", "Persistence data is not valid Base64.")
			end
			payload = decoded
		end
		if #payload > MAX_BASE64_DECODED_BYTES then
			return false, errorResult("PAYLOAD_LIMIT_EXCEEDED", "Persistence data exceeds the Base64 decoded input limit.")
		end
	end

	local ok, config, available =
		callFirst(self._runtime, { "jsonDecode", "JSONDecode", "decodeJSON", "DecodeJSON" }, payload)
	if not available or not ok or type(config) ~= "table" then
		return false, errorResult("DECODE_FAILED", "Persistence data is not valid JSON.")
	end
	local safe, safetyError = validateDecodedTable(config)
	if not safe then
		return false, safetyError :: PersistenceError
	end
	return true, config
end

function Persistence:_write(path: string, contents: string): (boolean, PersistenceError?)
	local folderOk, folderError = self:_ensureFolder()
	if not folderOk then
		return false, folderError
	end

	local storage = self._storage
	local tempPath = path .. ".tmp"
	local wroteTemp, writeReason, writeAvailable =
		callMutationFirst(storage, { "write", "Write", "writeFile", "WriteFile" }, tempPath, contents)
	if not writeAvailable then
		return false, errorResult("STORAGE_UNAVAILABLE", "Storage adapter does not support writes.")
	end
	if not wroteTemp then
		return false, self:_storageError("write", writeReason)
	end

	local replaced, replaceReason, replaceAvailable =
		callMutationFirst(storage, { "replace", "Replace", "rename", "Rename", "move", "Move" }, tempPath, path)
	if replaceAvailable then
		if replaced then
			return true
		end
		callMutationFirst(storage, { "delete", "Delete", "deleteFile", "DeleteFile" }, tempPath)
		return false, self:_storageError("replace", replaceReason)
	end

	local wrote, directReason =
		callMutationFirst(storage, { "write", "Write", "writeFile", "WriteFile" }, path, contents)
	callMutationFirst(storage, { "delete", "Delete", "deleteFile", "DeleteFile" }, tempPath)
	if not wrote then
		return false, self:_storageError("write", directReason)
	end
	return true
end

function Persistence:_read(path: string): (boolean, string | PersistenceError)
	local ok, contents, available, reason = callFirst(self._storage, { "read", "Read", "readFile", "ReadFile" }, path)
	if not available then
		return false, errorResult("STORAGE_UNAVAILABLE", "Storage adapter does not support reads.")
	end
	if not ok then
		return false, self:_storageError("read", contents)
	end
	if type(contents) ~= "string" then
		return false, self:_storageError("read", reason)
	end
	return true, contents
end

function Persistence:_encodeAutoload(profileName: string): (boolean, string | PersistenceError)
	local ok, encoded, available = callFirst(
		self._runtime,
		{ "jsonEncode", "JSONEncode", "encodeJSON", "EncodeJSON" },
		{
			version = AUTOLOAD_SCHEMA_VERSION,
			profile = profileName,
		}
	)
	if not available or not ok or type(encoded) ~= "string" then
		return false, errorResult("AUTOLOAD_ENCODE_FAILED", "Runtime JSON encoding failed for the autoload selector.")
	end
	return true, encoded
end

function Persistence:_decodeAutoload(contents: string): (boolean, string | PersistenceError)
	if type(contents) ~= "string" or #contents > MAX_ENCODED_INPUT_BYTES then
		return false, errorResult("PAYLOAD_LIMIT_EXCEEDED", "Autoload selector exceeds the encoded input limit.")
	end
	local ok, selector, available =
		callFirst(self._runtime, { "jsonDecode", "JSONDecode", "decodeJSON", "DecodeJSON" }, contents)
	if not available or not ok or type(selector) ~= "table" then
		return false, errorResult("INVALID_AUTOLOAD", "Autoload selector is not valid JSON.")
	end
	local safe, safetyError = validateDecodedTable(selector)
	if not safe then
		return false, safetyError :: PersistenceError
	end
	if selector.version ~= AUTOLOAD_SCHEMA_VERSION then
		return false, errorResult("INVALID_AUTOLOAD", "Autoload selector has an unsupported schema version.")
	end
	local valid, profile = sanitizeProfile(selector.profile)
	if not valid then
		return false, errorResult("INVALID_AUTOLOAD", "Autoload selector contains an invalid profile.")
	end
	return true, profile
end

function Persistence:_config(): (boolean, { [string]: any } | PersistenceError)
	local ok, values = self:_snapshot()
	if not ok then
		return false, values
	end
	return true,
		{
			schemaVersion = self._schemaVersion,
			libraryVersion = self._libraryVersion,
			savedAt = os.time(),
			values = values,
		}
end

function Persistence:SetAutoLoad(profileName: string?): (boolean, string | PersistenceError)
	if self._destroyed then
		return false, errorResult("DESTROYED", "Persistence has been destroyed.")
	end
	local valid, profile = sanitizeProfile(profileName)
	if not valid then
		return false, profile
	end
	local encodedOk, encoded = self:_encodeAutoload(profile)
	if not encodedOk then
		return false, encoded
	end
	local wrote, writeError = self:_write(self:_autoloadPath(), encoded)
	if not wrote then
		return false, writeError :: PersistenceError
	end
	return true, profile
end

function Persistence:GetAutoLoad(): (boolean, string | PersistenceError)
	if self._destroyed then
		return false, errorResult("DESTROYED", "Persistence has been destroyed.")
	end
	local existsOk, exists, hasExists =
		callFirst(self._storage, { "isFile", "IsFile", "fileExists", "FileExists" }, self:_autoloadPath())
	if hasExists then
		if not existsOk then
			return false, self:_storageError("read autoload selector", exists)
		end
		if exists ~= true then
			return false, errorResult("AUTOLOAD_NOT_SET", "No autoload profile has been selected.")
		end
	end
	local readOk, contents = self:_read(self:_autoloadPath())
	if not readOk then
		return false, contents
	end
	return self:_decodeAutoload(contents)
end

function Persistence:ClearAutoLoad(): (boolean, boolean | PersistenceError)
	if self._destroyed then
		return false, errorResult("DESTROYED", "Persistence has been destroyed.")
	end
	local existsOk, exists, hasExists =
		callFirst(self._storage, { "isFile", "IsFile", "fileExists", "FileExists" }, self:_autoloadPath())
	if hasExists then
		if not existsOk then
			return false, self:_storageError("read autoload selector", exists)
		end
		if exists ~= true then
			return true, false
		end
	end
	local deleted, reason, available =
		callMutationFirst(self._storage, { "delete", "Delete", "deleteFile", "DeleteFile" }, self:_autoloadPath())
	if not available then
		return false, errorResult("STORAGE_UNAVAILABLE", "Storage adapter does not support deletes.")
	end
	if not deleted then
		return false, self:_storageError("delete autoload selector", reason)
	end
	return true, true
end

function Persistence:LoadAuto(): (boolean, { [string]: any } | PersistenceError)
	if self._destroyed then
		return false, errorResult("DESTROYED", "Persistence has been destroyed.")
	end
	local selected, profile = self:GetAutoLoad()
	if not selected then
		return false, profile
	end
	return self:Load(profile)
end

function Persistence:Export(profileName: string?): (boolean, string | PersistenceError)
	if self._destroyed then
		return false, errorResult("DESTROYED", "Persistence has been destroyed.")
	end
	local valid, profile = sanitizeProfile(profileName)
	if not valid then
		return false, profile
	end
	if profileName ~= nil then
		local readOk, contents = self:_read(self:_path(profile :: string))
		if not readOk then
			return false, contents
		end
		return true, contents :: string
	end
	local configOk, config = self:_config()
	if not configOk then
		return false, config
	end
	return self:_encode(config)
end

function Persistence:Save(profileName: string?): (boolean, { [string]: any } | PersistenceError)
	if self._destroyed then
		return false, errorResult("DESTROYED", "Persistence has been destroyed.")
	end
	local valid, profile = sanitizeProfile(profileName)
	if not valid then
		return false, profile
	end
	local configOk, config = self:_config()
	if not configOk then
		return false, config
	end
	local encodedOk, encoded = self:_encode(config)
	if not encodedOk then
		return false, encoded
	end
	local wrote, writeError = self:_write(self:_path(profile), encoded)
	if not wrote then
		return false, writeError :: PersistenceError
	end
	if profile == self._autosaveProfile then
		self._dirty = false
	end
	return true, config
end

function Persistence:_validateConfig(config: { [string]: any }): (boolean, { [string]: any } | PersistenceError)
	if
		type(config.schemaVersion) ~= "number"
		or type(config.libraryVersion) ~= "string"
		or type(config.savedAt) ~= "number"
		or type(config.values) ~= "table"
	then
		return false, errorResult("INVALID_CONFIG", "Persistence data has an invalid schema.")
	end
	if config.schemaVersion > self._schemaVersion then
		return false, errorResult("UNSUPPORTED_SCHEMA", "Persistence data was created by a newer schema version.")
	end
	if config.schemaVersion < self._schemaVersion and self._migrate then
		local migrated, result = pcall(self._migrate, config, config.schemaVersion, self._schemaVersion)
		if not migrated or type(result) ~= "table" then
			return false, errorResult("MIGRATION_FAILED", "Persistence migration failed.")
		end
		config = result
	end
	if type(config.values) ~= "table" then
		return false, errorResult("INVALID_CONFIG", "Persistence values must be a table.")
	end
	return true, config
end

function Persistence:_hydrate(config: { [string]: any }): (boolean, { [string]: any } | PersistenceError)
	local valid, checked = self:_validateConfig(config)
	if not valid then
		return false, checked
	end
	local values = checked.values
	local store = self._store
	self._restoreGeneration += 1
	local generation = self._restoreGeneration
	local dirtyBeforeHydration = self._dirty
	self._hydrating = true
	local ok, result, available = callFirst(store, { "Hydrate", "LoadSnapshot", "SetValues", "Deserialize" }, values, {
		suppressCallbacks = self._suppressCallbacks,
		SuppressDefinitionCallback = self._suppressCallbacks,
		source = "load",
		generation = generation,
	})
	self._hydrating = false
	self._dirty = dirtyBeforeHydration
	if not available then
		return false, errorResult("HYDRATION_UNAVAILABLE", "Store does not expose a hydration method.")
	end
	if not ok or result == false then
		return false, errorResult("HYDRATION_FAILED", "Store rejected persisted values.")
	end
	if type(self._restoreCallback) == "function" then
		local callbackOk, callbackError = pcall(self._restoreCallback, checked, generation)
		if not callbackOk then
			return false, errorResult("RESTORE_CALLBACK_FAILED", "RestoreCallback failed: " .. tostring(callbackError))
		end
	end
	return true, checked
end

function Persistence:Load(profileName: string?): (boolean, { [string]: any } | PersistenceError)
	if self._destroyed then
		return false, errorResult("DESTROYED", "Persistence has been destroyed.")
	end
	local valid, profile = sanitizeProfile(profileName)
	if not valid then
		return false, profile
	end
	local readOk, contents = self:_read(self:_path(profile))
	if not readOk then
		return false, contents
	end
	local decodedOk, config = self:_decode(contents)
	if not decodedOk then
		return false, config
	end
	return self:_hydrate(config)
end

function Persistence:Import(profileName: string, encoded: string): (boolean, { [string]: any } | PersistenceError)
	if self._destroyed then
		return false, errorResult("DESTROYED", "Persistence has been destroyed.")
	end
	local valid, profile = sanitizeProfile(profileName)
	if not valid then
		return false, profile
	end
	if type(encoded) ~= "string" then
		return false, errorResult("INVALID_IMPORT", "Imported persistence data must be a string.")
	end
	local decodedOk, config = self:_decode(encoded)
	if not decodedOk then
		return false, config
	end
	local path = self:_path(profile)
	local hadPrevious, previous = self:_read(path)
	local wrote, writeError = self:_write(path, encoded)
	if not wrote then
		return false, writeError :: PersistenceError
	end
	local hydrated, result = self:_hydrate(config)
	if not hydrated then
		if hadPrevious and type(previous) == "string" then
			self:_write(path, previous)
		else
			callMutationFirst(self._storage, { "delete", "Delete", "deleteFile", "DeleteFile" }, path)
		end
		return false, result
	end
	return true, result
end

function Persistence:Delete(profileName: string?): (boolean, boolean | PersistenceError)
	if self._destroyed then
		return false, errorResult("DESTROYED", "Persistence has been destroyed.")
	end
	local valid, profile = sanitizeProfile(profileName)
	if not valid then
		return false, profile
	end
	local ok, reason, available =
		callMutationFirst(self._storage, { "delete", "Delete", "deleteFile", "DeleteFile" }, self:_path(profile))
	if not available then
		return false, errorResult("STORAGE_UNAVAILABLE", "Storage adapter does not support deletes.")
	end
	if not ok then
		return false, self:_storageError("delete", reason)
	end
	return true, true
end

function Persistence:List(): (boolean, { string } | PersistenceError)
	if self._destroyed then
		return false, errorResult("DESTROYED", "Persistence has been destroyed.")
	end
	local ok, files, available, reason =
		callFirst(self._storage, { "list", "List", "listFiles", "ListFiles" }, self._folder)
	if not available then
		return false, errorResult("STORAGE_UNAVAILABLE", "Storage adapter does not support listing files.")
	end
	if not ok then
		return false, self:_storageError("list", files)
	end
	if type(files) ~= "table" then
		return false, self:_storageError("list", reason)
	end
	local profiles = {}
	for _, path in ipairs(files) do
		if type(path) == "string" then
			local filename = string.match(path, "([^/\\]+)$") or path
			if string.sub(filename, -#self._extension) == self._extension then
				local profile = string.sub(filename, 1, #filename - #self._extension)
				local valid = sanitizeProfile(profile)
				if valid then
					table.insert(profiles, profile)
				end
			end
		end
	end
	table.sort(profiles)
	return true, profiles
end

function Persistence:Flush(): (boolean, { [string]: any } | PersistenceError)
	if self._destroyed then
		return true, { flushed = false }
	end
	if not self._dirty then
		return true, { flushed = false }
	end
	return self:Save(self._autosaveProfile)
end

function Persistence:SetAutosave(enabled: boolean, profileName: string?): (boolean, boolean | PersistenceError)
	if self._destroyed then
		return false, errorResult("DESTROYED", "Persistence has been destroyed.")
	end
	if type(enabled) ~= "boolean" then
		return false, errorResult("INVALID_AUTOSAVE", "Autosave state must be a boolean.")
	end
	local valid, profile = sanitizeProfile(profileName)
	if not valid then
		return false, profile
	end

	if self._subscription then
		if type(self._subscription) == "function" then
			pcall(self._subscription)
		else
			pcall(function()
				self._subscription:Disconnect()
			end)
		end
		self._subscription = nil
	end
	self._autosave = enabled
	self._autosaveProfile = profile
	self._generation += 1

	if not enabled then
		return true, false
	end

	local function changed()
		if self._destroyed or not self._autosave or self._hydrating then
			return
		end
		self._dirty = true
		self._generation += 1
		local generation = self._generation
		local delayFunction = self._runtime.delay or task.delay
		local scheduled = pcall(delayFunction, self._debounceSeconds, function()
			if not self._destroyed and self._autosave and self._dirty and generation == self._generation then
				self:Flush()
			end
		end)
		if not scheduled then
			self:Flush()
		end
	end

	local changedSignal = self._store.Changed
	if changedSignal == nil then
		self._autosave = false
		return false, errorResult("AUTOSAVE_UNAVAILABLE", "Store does not expose a change signal.")
	end
	local ok, subscription = pcall(function()
		return changedSignal:Connect(changed)
	end)
	if not ok or (type(subscription) ~= "function" and type(subscription) ~= "table") then
		self._autosave = false
		return false, errorResult("AUTOSAVE_UNAVAILABLE", "Store returned an invalid change subscription.")
	end
	self._subscription = subscription

	return true, true
end

local function workspaceProfile(name: string): (boolean, string | PersistenceError)
	local valid, sanitized = sanitizeProfile(name)
	if not valid then return false, sanitized end
	if string.sub(sanitized :: string, 1, 2) == "__" then
		return false, errorResult("RESERVED_WORKSPACE", "Workspace names beginning with '__' are reserved.")
	end
	return true, WORKSPACE_PREFIX .. (sanitized :: string)
end

local function internalProfile(name: string): (boolean, string | PersistenceError)
	if name ~= "command-palette-history" then
		return false, errorResult("INVALID_INTERNAL_NAMESPACE", "Unknown internal persistence namespace.")
	end
	return true, INTERNAL_PREFIX .. name
end

function Persistence:SaveWorkspace(name: string, snapshot: { [string]: any }): (boolean, { [string]: any } | PersistenceError)
	if self._destroyed then return false, errorResult("DESTROYED", "Persistence has been destroyed.") end
	local valid, profile = workspaceProfile(name)
	if not valid or type(snapshot) ~= "table" then
		return false, if valid then errorResult("INVALID_WORKSPACE", "Workspace snapshot must be a table.") else profile
	end
	local storedSnapshot = Util.deepCopy(snapshot)
	local encodedOk, encoded = self:_encode({ schemaVersion = self._schemaVersion, libraryVersion = self._libraryVersion, savedAt = os.time(), values = storedSnapshot })
	if not encodedOk then return false, encoded end
	self._workspaceMemory[profile] = storedSnapshot
	local wrote = self:_write(self:_path(profile), encoded)
	if not wrote then return true, snapshot end
	return true, snapshot
end

function Persistence:SaveInternal(name: string, snapshot: { [string]: any }): (boolean, { [string]: any } | PersistenceError)
	if self._destroyed then return false, errorResult("DESTROYED", "Persistence has been destroyed.") end
	local valid, profile = internalProfile(name)
	if not valid or type(snapshot) ~= "table" then
		return false, if valid then errorResult("INVALID_INTERNAL_SNAPSHOT", "Internal persistence snapshot must be a table.") else profile
	end
	local encodedOk, encoded = self:_encode({ schemaVersion = self._schemaVersion, libraryVersion = self._libraryVersion, savedAt = os.time(), values = snapshot })
	if not encodedOk then return false, encoded end
	local wrote, writeError = self:_write(self:_path(profile), encoded)
	if not wrote then return false, writeError end
	return true, snapshot
end

function Persistence:LoadInternal(name: string): (boolean, { [string]: any } | PersistenceError)
	if self._destroyed then return false, errorResult("DESTROYED", "Persistence has been destroyed.") end
	local valid, profile = internalProfile(name)
	if not valid then return false, profile end
	local readOk, contents = self:_read(self:_path(profile))
	if not readOk then return false, errorResult("INTERNAL_NOT_FOUND", "Internal persistence data was not found.") end
	local decodedOk, config = self:_decode(contents)
	if not decodedOk or type(config.values) ~= "table" then
		return false, errorResult("INVALID_INTERNAL_SNAPSHOT", "Internal persistence data is invalid.")
	end
	return true, config.values
end

function Persistence:LoadWorkspace(name: string): (boolean, { [string]: any } | PersistenceError)
	if self._destroyed then return false, errorResult("DESTROYED", "Persistence has been destroyed.") end
	local valid, profile = workspaceProfile(name)
	if not valid then return false, profile end
	local readOk, contents = self:_read(self:_path(profile))
	if readOk then
		local decodedOk, config = self:_decode(contents)
		if decodedOk and type(config.values) == "table" then
			self._workspaceMemory[profile] = Util.deepCopy(config.values)
			return true, config.values
		end
	end
	local memory = self._workspaceMemory[profile]
	if type(memory) == "table" then return true, Util.deepCopy(memory) end
	return false, errorResult("WORKSPACE_NOT_FOUND", "Workspace was not found.")
end

function Persistence:DeleteWorkspace(name: string): (boolean, boolean | PersistenceError)
	if self._destroyed then return false, errorResult("DESTROYED", "Persistence has been destroyed.") end
	local valid, profile = workspaceProfile(name)
	if not valid then return false, profile end
	local existed = self._workspaceMemory[profile] ~= nil
	local deleted, deleteReason, deleteAvailable = callMutationFirst(self._storage, { "delete", "Delete", "deleteFile", "DeleteFile" }, self:_path(profile))
	if deleteAvailable then
		if not deleted then
			return false, self:_storageError("delete", deleteReason)
		end
		existed = true
	end
	self._workspaceMemory[profile] = nil
	return true, existed
end

function Persistence:ListWorkspaces(): (boolean, { string } | PersistenceError)
	if self._destroyed then return false, errorResult("DESTROYED", "Persistence has been destroyed.") end
	local names, seen = {}, {}
	for profile in pairs(self._workspaceMemory) do
		if string.sub(profile, 1, #WORKSPACE_PREFIX) == WORKSPACE_PREFIX then
			local name = string.sub(profile, #WORKSPACE_PREFIX + 1)
			table.insert(names, name)
			seen[profile] = true
		end
	end
	local listed, files, available, reason =
		callFirst(self._storage, { "list", "List", "listFiles", "ListFiles" }, self._folder)
	if not available then
		return false, errorResult("STORAGE_UNAVAILABLE", "Storage adapter does not support listing files.")
	end
	if not listed or type(files) ~= "table" then
		return false, self:_storageError("list", if listed then reason else files)
	end
	for _, path in ipairs(files) do
		if type(path) == "string" then
			local filename = string.match(path, "([^/\\]+)$") or path
			if string.sub(filename, -#self._extension) == self._extension then
				local profile = string.sub(filename, 1, #filename - #self._extension)
				if string.sub(profile, 1, #WORKSPACE_PREFIX) == WORKSPACE_PREFIX and not seen[profile] then
					local name = string.sub(profile, #WORKSPACE_PREFIX + 1)
					local valid = sanitizeProfile(name)
					if valid then
						table.insert(names, name)
						seen[profile] = true
					end
				end
			end
		end
	end
	table.sort(names)
	return true, names
end
function Persistence:Destroy(): (boolean, boolean | PersistenceError)
	if self._destroyed then
		return true, false
	end
	local flushed, result = self:Flush()
	self:SetAutosave(false, self._autosaveProfile)
	self._destroyed = true
	table.clear(self._workspaceMemory)
	if not flushed then
		return false, result
	end
	return true, true
end

return Persistence

end

__modules["core/Presence"] = function()
--!strict

export type Presence = {
	Enter: (self: Presence, seedProps: { [string]: any }, finalProps: { [string]: any }, preset: string?) -> any,
	Exit: (self: Presence, finalProps: { [string]: any }, preset: string?, finalize: (() -> ())?) -> any,
	Cancel: (self: Presence, reason: string?) -> (),
	Destroy: (self: Presence) -> (),
}

local Presence = {}
Presence.__index = Presence

local function applyProperties(target: Instance, properties: { [string]: any })
	for property, value in pairs(properties) do
		(target :: any)[property] = value
	end
end

local function addToMaid(maid: any, task: any)
	if maid == nil then
		return
	end
	if type(maid.GiveTask) == "function" then
		maid:GiveTask(task)
	elseif type(maid.Add) == "function" then
		maid:Add(task)
	end
end

function Presence.new(motion: any, maid: any, target: Instance): Presence
	assert(type(motion) == "table" and type(motion.Animate) == "function", "Presence requires Motion")
	assert(typeof(target) == "Instance", "Presence requires an Instance target")
	local self = setmetatable({
		_motion = motion,
		_target = target,
		_handle = nil,
		_generation = 0,
		_destroyed = false,
	}, Presence)
	addToMaid(maid, function()
		self:Destroy()
	end)
	return self :: any
end

function Presence:Cancel(reason: string?)
	self._generation += 1
	local handle = self._handle
	self._handle = nil
	if handle ~= nil then
		handle:Cancel(reason or "cancelled")
	end
end

function Presence:Enter(seedProps: { [string]: any }, finalProps: { [string]: any }, preset: string?): any
	assert(type(seedProps) == "table" and type(finalProps) == "table", "Presence Enter properties must be tables")
	if self._destroyed then
		return nil
	end
	local generation = self._generation + 1
	self:Cancel("retargeted")
	if self._generation ~= generation or self._destroyed then
		return nil
	end
	applyProperties(self._target, seedProps)
	if self._generation ~= generation or self._destroyed then
		return nil
	end
	local handle = self._motion:Animate(self._target, finalProps, preset or "enter")
	if self._generation ~= generation or self._destroyed then
		handle:Cancel("retargeted")
		return handle
	end
	self._handle = handle
	handle:OnCompleted(function()
		if self._generation == generation and self._handle == handle then
			self._handle = nil
		end
	end)
	return handle
end

function Presence:Exit(finalProps: { [string]: any }, preset: string?, finalize: (() -> ())?): any
	assert(type(finalProps) == "table", "Presence Exit properties must be a table")
	assert(finalize == nil or type(finalize) == "function", "Presence finalize must be a function")
	if self._destroyed then
		return nil
	end
	local generation = self._generation + 1
	self:Cancel("retargeted")
	if self._generation ~= generation or self._destroyed then
		return nil
	end
	local handle = self._motion:Animate(self._target, finalProps, preset or "exit")
	if self._generation ~= generation or self._destroyed then
		handle:Cancel("retargeted")
		return handle
	end
	self._handle = handle
	handle:OnCompleted(function(state: string)
		if self._generation ~= generation or self._handle ~= handle then
			return
		end
		self._handle = nil
		if (state == "Completed" or state == "Skipped") and finalize ~= nil then
			finalize()
		end
	end)
	return handle
end

function Presence:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	self:Cancel("destroyed")
end

return Presence

end

__modules["core/ResourceController"] = function()
--!strict

local Signal = __require("core/Signal")
local StructuredError = __require("core/StructuredError")

export type ResourceSnapshot = {
	id: string,
	state: "idle" | "loading" | "ready" | "empty" | "error" | "stale",
	generation: number,
	value: any?,
	error: StructuredError.StructuredError?,
	updatedAt: number?,
}

export type ResourceController = {
	Create: (self: ResourceController, id: string, provider: (context: any) -> any) -> (ResourceSnapshot?, StructuredError.StructuredError?),
	Get: (self: ResourceController, id: string) -> (ResourceSnapshot?, StructuredError.StructuredError?),
	Observe: (self: ResourceController, id: string, callback: (ResourceSnapshot) -> (), options: any?) -> (any?, StructuredError.StructuredError?),
	Refresh: (self: ResourceController, id: string, options: any?) -> (number?, StructuredError.StructuredError?),
	Cancel: (self: ResourceController, id: string) -> (boolean, StructuredError.StructuredError?),
	Destroy: (self: ResourceController) -> (),
}

type Entry = { provider: (context: any) -> any, snapshot: ResourceSnapshot, signal: any, cancelledGeneration: number? }

local ResourceController = {}
ResourceController.__index = ResourceController

local function failure(code: string, message: string, operation: string, details: any?): StructuredError.StructuredError
	return StructuredError.from(code, message, { domain = "resource", operation = operation, details = details })
end

local function clone(value: any, depth: number?, seen: any?): any
	depth = depth or 0
	seen = seen or {}
	if type(value) ~= "table" then return value end
	if depth >= 8 or seen[value] then return "<bounded>" end
	seen[value] = true
	local result = {}
	local count = 0
	for key, item in pairs(value) do
		count += 1
		if count > 128 then break end
		if type(key) == "string" or type(key) == "number" then result[key] = clone(item, depth + 1, seen) end
	end
	seen[value] = nil
	return table.freeze(result)
end

local function snapshot(entry: Entry): ResourceSnapshot
	return clone(entry.snapshot)
end

function ResourceController.new(clock: (() -> number)?): ResourceController
	return setmetatable({ _clock = clock or os.clock, _destroyed = false, _entries = {} :: { [string]: Entry } }, ResourceController) :: any
end

function ResourceController:_publish(entry: Entry)
	entry.signal:Fire(snapshot(entry))
end

function ResourceController:Create(id: string, provider: (context: any) -> any): (ResourceSnapshot?, StructuredError.StructuredError?)
	if self._destroyed then return nil, failure("destroyed", "ResourceController is destroyed", "create") end
	if type(id) ~= "string" or id == "" or type(provider) ~= "function" then return nil, failure("invalid_resource", "Resource id and provider are required", "create") end
	if self._entries[id] then return nil, failure("duplicate_resource", "Resource id is already registered", "create", { id = id }) end
	local entry: Entry = { provider = provider, cancelledGeneration = nil, signal = Signal.new(), snapshot = table.freeze({ id = id, state = "idle", generation = 0 }) }
	self._entries[id] = entry
	return snapshot(entry), nil
end

function ResourceController:Get(id: string): (ResourceSnapshot?, StructuredError.StructuredError?)
	local entry = self._entries[id]
	if not entry then return nil, failure("unknown_resource", "Resource id is not registered", "get", { id = id }) end
	return snapshot(entry), nil
end

function ResourceController:Observe(id: string, callback: (ResourceSnapshot) -> (), options: any?): (any?, StructuredError.StructuredError?)
	local entry = self._entries[id]
	if not entry or type(callback) ~= "function" then return nil, failure("invalid_observation", "Known resource id and callback are required", "observe", { id = id }) end
	local connection = entry.signal:Connect(callback)
	if type(options) == "table" and options.EmitInitial == true then callback(snapshot(entry)) end
	return connection, nil
end

function ResourceController:Refresh(id: string, options: any?): (number?, StructuredError.StructuredError?)
	local entry = self._entries[id]
	if self._destroyed or not entry then return nil, failure("unknown_resource", "Resource id is not registered", "refresh", { id = id }) end
	local generation = entry.snapshot.generation + 1
	entry.cancelledGeneration = nil
	entry.snapshot = table.freeze({ id = id, state = "loading", generation = generation, value = entry.snapshot.value, updatedAt = self._clock() })
	self:_publish(entry)
	local context = table.freeze({
		id = id,
		generation = generation,
		options = clone(options),
		IsCancelled = function(): boolean
			return self._destroyed or entry.cancelledGeneration == generation or entry.snapshot.generation ~= generation
		end,
	})
	task.spawn(function()
		local ok, result = xpcall(entry.provider, debug.traceback, context)
		if context.IsCancelled() then
			if entry.cancelledGeneration == generation then
				entry.cancelledGeneration = nil
			end
			return
		end
		if not ok then
			entry.snapshot = table.freeze({ id = id, state = "error", generation = generation, error = failure("provider_failed", tostring(result), "refresh", { id = id }), updatedAt = self._clock() })
		elseif result == nil then
			entry.snapshot = table.freeze({ id = id, state = "empty", generation = generation, updatedAt = self._clock() })
		else
			entry.snapshot = table.freeze({ id = id, state = "ready", generation = generation, value = clone(result), updatedAt = self._clock() })
		end
		self:_publish(entry)
		if entry.cancelledGeneration == generation then
			entry.cancelledGeneration = nil
		end
	end)
	return generation, nil
end

function ResourceController:Cancel(id: string): (boolean, StructuredError.StructuredError?)
	local entry = self._entries[id]
	if not entry then return false, failure("unknown_resource", "Resource id is not registered", "cancel", { id = id }) end
	local generation = entry.snapshot.generation
	if entry.snapshot.state ~= "loading" then return false, nil end
	entry.cancelledGeneration = generation
	entry.snapshot = table.freeze({ id = id, state = "stale", generation = generation, value = entry.snapshot.value, updatedAt = self._clock() })
	self:_publish(entry)
	return true, nil
end

function ResourceController:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	for _, entry in pairs(self._entries) do entry.cancelledGeneration = nil; entry.signal:Destroy() end
	table.clear(self._entries)
end

return ResourceController

end

__modules["core/Runtime"] = function()
--!strict

local Util = __require("core/Util")

export type StructuredError = { code: string, message: string }
export type Adapter = { [string]: any }
-- Explicit caller-mode local file source contract. Runtime never discovers it.
-- A provider may return a structured failure as its second result.
export type LocalAssetsAdapter = {
	fromFile: (path: string) -> (any?, StructuredError?),
}
-- Legacy file resolver, used only when AssetPolicy explicitly permits fallback.
export type ImageAdapter = {
	fromFile: (path: string) -> (any?, StructuredError?),
}
-- Explicit synchronous avatar source contract used by AssetPolicy.
export type AvatarAdapter = {
	Resolve: (self: AvatarAdapter, subject: string) -> (any?, StructuredError?),
}
export type ResolveOptions = {
	contextId: string?,
	mountParent: Instance?,
	services: { [string]: any }?,
	capabilities: { [string]: any }?,
	storage: Adapter?,
	clipboard: Adapter?,
	http: Adapter?,
	base64: Adapter?,
	image: ImageAdapter?,
	localAssets: LocalAssetsAdapter?,
	avatars: AvatarAdapter?,
	haptics: Adapter?,
}
export type Runtime = {
	contextId: string,
	services: { [string]: any },
	mountParent: Instance?,
	capabilities: { [string]: any },
	storage: Adapter?,
	clipboard: Adapter?,
	http: Adapter?,
	base64: Adapter?,
	image: ImageAdapter?,
	localAssets: LocalAssetsAdapter?,
	avatars: AvatarAdapter?,
	haptics: Adapter?,
	jsonEncode: (self: Runtime, value: any) -> (string?, StructuredError?),
	jsonDecode: (self: Runtime, value: string) -> (any, StructuredError?),
	CreateScreenGui: (self: Runtime, properties: { [string]: any }?) -> (ScreenGui?, StructuredError?),
	Destroy: (self: Runtime) -> (),
}

local Runtime = {}
Runtime.__index = Runtime

local nextContextId = 0

local MAX_SCREEN_GUIS = 16

local function adapterMethod(adapter: any, method: string): boolean
	return type(adapter) == "table" and type(adapter[method]) == "function"
end

local function failure(code: string, message: string): StructuredError
	return { code = code, message = message }
end

local function opaqueId(httpService: any, fallback: string): string
	if httpService ~= nil and type(httpService.GenerateGUID) == "function" then
		local ok, generated = pcall(httpService.GenerateGUID, httpService, false)
		if ok and type(generated) == "string" and generated ~= "" then
			return generated
		end
	end
	return "UI-" .. fallback
end

local function environment(): { [string]: any }
	local ok, scoped = pcall(function()
		return getfenv()
	end)
	if ok and type(scoped) == "table" then
		return scoped
	end
	local globalOk, global = pcall(function()
		return getgenv()
	end)
	if globalOk and type(global) == "table" then
		return global
	end
	return _G
end

local function lookup(name: string): any
	local scoped = environment()
	local ok, value = pcall(function()
		return scoped[name]
	end)
	if ok and value ~= nil then
		return value
	end
	local globalOk, global = pcall(function()
		return getgenv()
	end)
	if globalOk and type(global) == "table" then
		return global[name]
	end
	return nil
end

local function tryService(gameObject: any, serviceName: string): any
	if gameObject == nil or type(gameObject.GetService) ~= "function" then
		return nil
	end
	local ok, service = pcall(function()
		return gameObject:GetService(serviceName)
	end)
	return if ok then service else nil
end

local function tryGetHui(): Instance?
	local getter = lookup("gethui")
	if type(getter) ~= "function" then
		return nil
	end
	local ok, parent = pcall(getter)
	if ok and typeof(parent) == "Instance" then
		return parent
	end
	return nil
end

local function playerGui(players: any): Instance?
	if players == nil then
		return nil
	end
	local player = players.LocalPlayer
	if player == nil then
		return nil
	end
	local found = player:FindFirstChildOfClass("PlayerGui")
	return if found ~= nil then found else nil
end

local function resolveMountParents(options: ResolveOptions, services: { [string]: any }): { Instance }
	local parents = {}
	local seen = {}
	local function add(parent: any)
		if typeof(parent) == "Instance" and seen[parent] == nil then
			seen[parent] = true
			table.insert(parents, parent)
		end
	end
	add(options.mountParent)
	add(tryGetHui())
	add(services.CoreGui)
	add(playerGui(services.Players))
	return parents
end

local function functionLookup(name: string): ((...any) -> any)?
	local value = lookup(name)
	return if type(value) == "function" then value else nil
end

local function makeStorage(): any?
	local isFile = functionLookup("isfile")
	local readFile = functionLookup("readfile")
	local writeFile = functionLookup("writefile")
	local deleteFile = functionLookup("delfile")
	local listFiles = functionLookup("listfiles")
	local isFolder = functionLookup("isfolder")
	local makeFolder = functionLookup("makefolder")
	local renameFile = functionLookup("renamefile")
	if
		isFile == nil
		and readFile == nil
		and writeFile == nil
		and deleteFile == nil
		and listFiles == nil
		and isFolder == nil
		and makeFolder == nil
	then
		return nil
	end

	local function pathArgument(first: any, second: any): any
		return if type(first) == "table" then second else first
	end
	local function writeArguments(first: any, second: any, third: any): (any, any)
		if type(first) == "table" then
			return second, third
		end
		return first, second
	end
	local adapter = {}
	if isFile ~= nil then
		adapter.isFile = function(first: any, second: any): (boolean?, any?)
			local ok, result = pcall(isFile, pathArgument(first, second))
			return (if ok then result else nil), (if ok then nil else result)
		end
		adapter.isfile = adapter.isFile
	end
	if readFile ~= nil then
		adapter.read = function(first: any, second: any): (string?, any?)
			local ok, result = pcall(readFile, pathArgument(first, second))
			return (if ok then result else nil), (if ok then nil else result)
		end
		adapter.readFile = adapter.read
		adapter.readfile = adapter.read
	end
	if writeFile ~= nil then
		adapter.write = function(first: any, second: any, third: any): (boolean, any?)
			local path, content = writeArguments(first, second, third)
			local ok, result = pcall(writeFile, path, content)
			return ok, if ok then nil else result
		end
		adapter.writeFile = adapter.write
		adapter.writefile = adapter.write
	end
	if deleteFile ~= nil then
		adapter.delete = function(first: any, second: any): (boolean, any?)
			local ok, result = pcall(deleteFile, pathArgument(first, second))
			return ok, if ok then nil else result
		end
		adapter.deleteFile = adapter.delete
		adapter.delfile = adapter.delete
	end
	if listFiles ~= nil then
		adapter.list = function(first: any, second: any): ({ string }?, any?)
			local ok, result = pcall(listFiles, pathArgument(first, second))
			return (if ok then result else nil), (if ok then nil else result)
		end
		adapter.listFiles = adapter.list
		adapter.listfiles = adapter.list
	end
	if isFolder ~= nil then
		adapter.isFolder = function(first: any, second: any): (boolean?, any?)
			local ok, result = pcall(isFolder, pathArgument(first, second))
			return (if ok then result else nil), (if ok then nil else result)
		end
		adapter.isfolder = adapter.isFolder
	end
	if makeFolder ~= nil then
		adapter.makeFolder = function(first: any, second: any): (boolean, any?)
			local ok, result = pcall(makeFolder, pathArgument(first, second))
			return ok, if ok then nil else result
		end
		adapter.makefolder = adapter.makeFolder
	end
	if renameFile ~= nil then
		adapter.rename = function(first: any, second: any, third: any): (boolean, any?)
			local source, destination = writeArguments(first, second, third)
			local ok, result = pcall(renameFile, source, destination)
			return ok, if ok then nil else result
		end
		adapter.move = adapter.rename
		adapter.replace = adapter.rename
	end
	if renameFile ~= nil and writeFile ~= nil then
		adapter.atomicReplace = function(first: any, second: any, third: any): (boolean, any?)
			local path, content = writeArguments(first, second, third)
			local temporaryPath = path .. ".potassium.tmp"
			local wrote, writeError = pcall(writeFile, temporaryPath, content)
			if not wrote then
				return false, writeError
			end
			local renamed, renameError = pcall(renameFile, temporaryPath, path)
			return renamed, if renamed then nil else renameError
		end
	end
	return adapter
end

local function makeClipboard(): any?
	local read = functionLookup("getclipboard")
	local write = functionLookup("setclipboard")
	if read == nil and write == nil then
		return nil
	end
	return {
		read = if read ~= nil
			then function(): (string?, any?)
				local ok, result = pcall(read)
				return (if ok then result else nil), (if ok then nil else result)
			end
			else nil,
		write = if write ~= nil
			then function(first: any, second: any): (boolean, any?)
				local value = if type(first) == "table" then second else first
				local ok, result = pcall(write, value)
				return ok, if ok then nil else result
			end
			else nil,
	}
end
local function makeHttp(): any?
	local request = functionLookup("request") or functionLookup("http_request")
	if request == nil then
		local syn = lookup("syn")
		if type(syn) == "table" and type(syn.request) == "function" then
			request = syn.request
		end
	end
	if request == nil then
		return nil
	end
	return {
		request = function(first: any, second: any): (any, any?)
			local options = if type(first) == "table" then second else first
			local ok, result = pcall(request :: any, options)
			return (if ok then result else nil), (if ok then nil else result)
		end,
	}
end

local function makeBase64(): any?
	local crypt = lookup("crypt")
	if type(crypt) ~= "table" or type(crypt.base64) ~= "table" then
		return nil
	end
	local encode = crypt.base64.encode
	local decode = crypt.base64.decode
	if type(encode) ~= "function" and type(decode) ~= "function" then
		return nil
	end
	return { encode = encode, decode = decode }
end


function Runtime.resolve(options: ResolveOptions?): (Runtime?, StructuredError?)
	local resolvedOptions = options or {}
	local gameObject = lookup("game")
	local injectedServices = resolvedOptions.services or {}
	local services = {
		Players = injectedServices.Players or tryService(gameObject, "Players"),
		CoreGui = injectedServices.CoreGui or tryService(gameObject, "CoreGui"),
		UserInputService = injectedServices.UserInputService or tryService(gameObject, "UserInputService"),
		ContextActionService = injectedServices.ContextActionService or tryService(gameObject, "ContextActionService"),
		GuiService = injectedServices.GuiService or tryService(gameObject, "GuiService"),
		TweenService = injectedServices.TweenService or tryService(gameObject, "TweenService"),
		TextService = injectedServices.TextService or tryService(gameObject, "TextService"),
		HttpService = injectedServices.HttpService or tryService(gameObject, "HttpService"),
		RunService = injectedServices.RunService or tryService(gameObject, "RunService"),
		VirtualUser = injectedServices.VirtualUser or tryService(gameObject, "VirtualUser"),
		Workspace = injectedServices.Workspace or tryService(gameObject, "Workspace"),
		Lighting = injectedServices.Lighting or tryService(gameObject, "Lighting"),
	}
	for name, service in pairs(injectedServices) do
		services[name] = service
	end

	local storage = resolvedOptions.storage or makeStorage()
	local clipboard = resolvedOptions.clipboard or makeClipboard()
	local http = resolvedOptions.http or makeHttp()
	local base64 = resolvedOptions.base64 or makeBase64()
	local image = resolvedOptions.image
	-- Content-bearing adapters are opt-in. Runtime never discovers an asset,
	-- avatar, or haptic provider and never makes a network request for them.
	local localAssets = resolvedOptions.localAssets
	local avatars = resolvedOptions.avatars
	local haptics = resolvedOptions.haptics
	nextContextId += 1
	local requestedId = resolvedOptions.contextId
	local contextId = if requestedId ~= nil
		then Util.sanitizeId(requestedId) .. "-" .. tostring(nextContextId)
		else opaqueId(services.HttpService, tostring(nextContextId))
	local capabilities = {
		gethui = type(lookup("gethui")) == "function",
		clipboardRead = clipboard ~= nil and type(clipboard.read) == "function",
		clipboardWrite = clipboard ~= nil and type(clipboard.write) == "function",
		httpRequest = http ~= nil and type(http.request) == "function",
		storage = storage ~= nil,
		atomicReplace = storage ~= nil and type(storage.atomicReplace) == "function",
		json = services.HttpService ~= nil,
		image = adapterMethod(image, "fromFile"),
		localAssets = adapterMethod(localAssets, "fromFile"),
		avatars = adapterMethod(avatars, "Resolve"),
		haptics = adapterMethod(haptics, "Create"),
		coreGui = services.CoreGui ~= nil,
		playerGui = playerGui(services.Players) ~= nil,
	}
	for name, enabled in pairs(resolvedOptions.capabilities or {}) do
		capabilities[name] = enabled
	end

	local mountParents = resolveMountParents(resolvedOptions, services)
	return setmetatable({
		contextId = contextId,
		services = services,
		mountParent = mountParents[1],
		_mountParents = mountParents,
		capabilities = capabilities,
		storage = storage,
		clipboard = clipboard,
		http = http,
		base64 = base64,
		image = image,
		localAssets = localAssets,
		avatars = avatars,
		haptics = haptics,
		_screenGuiSequence = 0,
		_screenGuis = {},
	}, Runtime),
		nil
end

function Runtime:jsonEncode(value: any): (string?, StructuredError?)
	local httpService = self.services.HttpService
	if httpService == nil then
		return nil, failure("json_unavailable", "HttpService JSON encoding is unavailable")
	end
	local ok, result = pcall(function()
		return httpService:JSONEncode(value)
	end)
	if not ok then
		return nil, failure("json_encode_failed", tostring(result))
	end
	return result, nil
end

function Runtime:jsonDecode(value: string): (any, StructuredError?)
	local httpService = self.services.HttpService
	if httpService == nil then
		return nil, failure("json_unavailable", "HttpService JSON decoding is unavailable")
	end
	local ok, result = pcall(function()
		return httpService:JSONDecode(value)
	end)
	if not ok then
		return nil, failure("json_decode_failed", tostring(result))
	end
	return result, nil
end

function Runtime:CreateScreenGui(properties: { [string]: any }?): (ScreenGui?, StructuredError?)
	if self._destroyed then return nil, failure("destroyed", "Runtime has been destroyed") end
	if self.mountParent == nil and #self._mountParents == 0 then return nil, failure("missing_mount_parent", "No GUI mount parent is available") end
	local liveCount = 0
	for _ in pairs(self._screenGuis) do liveCount += 1 end
	if liveCount >= MAX_SCREEN_GUIS then return nil, failure("screen_gui_limit", "Runtime can own at most 16 live ScreenGuis") end
	self._screenGuiSequence += 1
	local gui = Instance.new("ScreenGui")
	gui.Name = opaqueId(self.services.HttpService, self.contextId .. "-" .. tostring(self._screenGuiSequence))
	gui.ResetOnSpawn = false
	gui.IgnoreGuiInset = false
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	local ok, errorValue = Util.applyProperties(gui, properties or {})
	if not ok then gui:Destroy() return nil, errorValue end
	local parentOk = false
	local parentError: any = "No GUI mount parent accepted the ScreenGui"
	local attempted = {}
	local function tryParent(parent: any)
		if parentOk or typeof(parent) ~= "Instance" or attempted[parent] then
			return
		end
		attempted[parent] = true
		local ok, reason = pcall(function() gui.Parent = parent end)
		if ok and gui.Parent == parent then
			parentOk = true
			self.mountParent = parent
		elseif ok then
			parentError = "Parent assignment did not retain the ScreenGui"
		else
			parentError = reason
		end
	end
	tryParent(self.mountParent)
	for _, parent in ipairs(self._mountParents) do
		tryParent(parent)
	end
	if not parentOk then gui:Destroy() return nil, failure("mount_failed", "Could not mount ScreenGui: " .. tostring(parentError)) end
	local connection: RBXScriptConnection? = nil
	connection = gui.Destroying:Connect(function()
		local tracked = self._screenGuis[gui]
		self._screenGuis[gui] = nil
		if tracked ~= nil then tracked:Disconnect() end
	end)
	self._screenGuis[gui] = connection
	return gui, nil
end

function Runtime:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	local owned = {}
	for gui in pairs(self._screenGuis) do table.insert(owned, gui) end
	for _, gui in ipairs(owned) do gui:Destroy() end
	table.clear(self._screenGuis)
end

return Runtime

end

__modules["core/RuntimeFreeHost"] = function()
--!strict

local Host = {}
Host.__index = Host

local function errorResult(code: string, message: string)
	return { code = code, message = message }
end

local function option(options: any, upper: string, lower: string): any
	if type(options) ~= "table" then
		return nil
	end
	if options[lower] ~= nil then
		return options[lower]
	end
	return options[upper]
end

local function injectedServices(options: any): any
	local services = option(options, "Services", "services")
	return if type(services) == "table" then services else {}
end

local function getService(name: string): any
	local ok, service = pcall(function()
		return game:GetService(name)
	end)
	return if ok then service else nil
end

local function globalFunction(name: string): ((...any) -> any)?
	local environmentOk, environment = pcall(function()
		return getgenv()
	end)
	if environmentOk and type(environment) == "table" and type(environment[name]) == "function" then
		return environment[name]
	end
	local value = _G[name]
	return if type(value) == "function" then value else nil
end

local function sanitizeSegment(value: any): (string?, any?)
	if type(value) ~= "string" or value == "" then
		return nil, errorResult("invalid_profile_path", "Profile folder and name must be non-empty strings")
	end
	local sanitized = string.gsub(value, "[^%w%-%_]", "_")
	if sanitized == "" then
		return nil, errorResult("invalid_profile_path", "Profile folder and name must contain usable characters")
	end
	return sanitized, nil
end

local function profilePath(folder: any, name: any): (string?, any?)
	local safeFolder, folderError = sanitizeSegment(folder)
	if safeFolder == nil then
		return nil, folderError
	end
	local safeName, nameError = sanitizeSegment(name)
	if safeName == nil then
		return nil, nameError
	end
	return "Potassium/" .. safeFolder .. "/" .. safeName .. ".json", nil
end

function Host.new(options: any?): (any?, any?)
	if options ~= nil and type(options) ~= "table" then
		return nil, errorResult("invalid_host_options", "Host options must be a table when provided")
	end
	options = options or {}
	return setmetatable({
		_mountParent = option(options, "MountParent", "mountParent"),
		_services = injectedServices(options),
		_storage = option(options, "Storage", "storage"),
		_screenGui = nil,
		_connections = {},
		_tweens = {},
		_destroyed = false,
	}, Host), nil
end

function Host:_httpService(): any
	return self._services.HttpService or getService("HttpService")
end

function Host:_userInputService(): any
	return self._services.UserInputService or getService("UserInputService")
end

function Host:_tryParent(gui: ScreenGui, parent: any): boolean
	if typeof(parent) ~= "Instance" then
		return false
	end
	local ok = pcall(function()
		gui.Parent = parent
	end)
	return ok and gui.Parent == parent
end

function Host:CreateScreenGui(displayOrder: number?): (ScreenGui?, any?)
	if self._destroyed then
		return nil, errorResult("host_destroyed", "Cannot create a ScreenGui after the host is destroyed")
	end
	if self._screenGui ~= nil then
		if displayOrder ~= nil then
			self._screenGui.DisplayOrder = displayOrder
		end
		return self._screenGui, nil
	end

	local guiName = "Potassium"
	local httpService = self:_httpService()
	if httpService ~= nil and type(httpService.GenerateGUID) == "function" then
		local generatedOk, generated = pcall(httpService.GenerateGUID, httpService, false)
		if generatedOk and type(generated) == "string" and generated ~= "" then
			guiName = generated
		end
	end

	local createdOk, gui = pcall(function()
		local screenGui = Instance.new("ScreenGui")
		screenGui.Name = guiName
		screenGui.ResetOnSpawn = false
		screenGui.IgnoreGuiInset = false
		screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
		screenGui.DisplayOrder = displayOrder or 0
		return screenGui
	end)
	if not createdOk or gui == nil then
		return nil, errorResult("screen_gui_failed", "Could not create ScreenGui: " .. tostring(gui))
	end

	if self:_tryParent(gui, self._mountParent) then
		self._screenGui = gui
		return gui, nil
	end
	local getHui = globalFunction("gethui")
	if getHui ~= nil then
		local huiOk, hui = pcall(getHui)
		if huiOk and self:_tryParent(gui, hui) then
			self._screenGui = gui
			return gui, nil
		end
	end
	if self:_tryParent(gui, self._services.CoreGui or getService("CoreGui")) then
		self._screenGui = gui
		return gui, nil
	end
	local players = self._services.Players or getService("Players")
	if players ~= nil then
		local playerGuiOk, playerGui = pcall(function()
			local player = players.LocalPlayer
			return if player ~= nil then player:FindFirstChildOfClass("PlayerGui") else nil
		end)
		if playerGuiOk and self:_tryParent(gui, playerGui) then
			self._screenGui = gui
			return gui, nil
		end
	end

	pcall(function()
		gui:Destroy()
	end)
	return nil, errorResult("mount_failed", "Could not mount ScreenGui")
end

function Host:ConnectMenuKey(keyCode: Enum.KeyCode, callback: () -> (), options: any?): (RBXScriptConnection?, any?)
	if self._destroyed then
		return nil, errorResult("host_destroyed", "Cannot connect a menu key after the host is destroyed")
	end
	if typeof(keyCode) ~= "EnumItem" or keyCode.EnumType ~= Enum.KeyCode or type(callback) ~= "function" then
		return nil, errorResult("invalid_menu_key", "A keyboard KeyCode and callback are required")
	end
	local userInputService = self:_userInputService()
	if userInputService == nil or userInputService.InputBegan == nil then
		return nil, errorResult("user_input_unavailable", "UserInputService is unavailable")
	end
	local allowFocusedTextBox = if type(options) == "table" then options.AllowFocusedTextBox else nil
	if allowFocusedTextBox ~= nil and type(allowFocusedTextBox) ~= "function" then
		return nil, errorResult("invalid_menu_key", "AllowFocusedTextBox must be a function")
	end
	local connectedOk, connection = pcall(function()
		return userInputService.InputBegan:Connect(function(input: InputObject, processed: boolean)
			if self._destroyed then return end
			local focusedOk, focusedTextBox = pcall(userInputService.GetFocusedTextBox, userInputService)
			local focusedAllowed = focusedOk
				and focusedTextBox ~= nil
				and allowFocusedTextBox ~= nil
				and allowFocusedTextBox(focusedTextBox) == true
			if (processed and not focusedAllowed) or (focusedOk and focusedTextBox ~= nil and not focusedAllowed) then
				return
			end
			if input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == keyCode then
				pcall(callback)
			end
		end)
	end)
	if not connectedOk or connection == nil then
		return nil, errorResult("menu_key_failed", "Could not connect menu key: " .. tostring(connection))
	end
	table.insert(self._connections, connection)
	return connection, nil
end

function Host:_storageAdapter(): (any?, any?)
	if type(self._storage) == "table" then
		if type(self._storage.read) == "function" and type(self._storage.write) == "function" then
			return self._storage, nil
		end
		return nil, errorResult("storage_unavailable", "Injected storage must provide read and write functions")
	end
	local readFile = globalFunction("readfile")
	local writeFile = globalFunction("writefile")
	if readFile == nil or writeFile == nil then
		return nil, errorResult("storage_unavailable", "Profile storage is unavailable")
	end
	local makeFolder = globalFunction("makefolder")
	local isFolder = globalFunction("isfolder")
	local isFile = globalFunction("isfile")
	return {
		read = function(_: any, path: string)
			return readFile(path)
		end,
		write = function(_: any, path: string, data: string)
			return writeFile(path, data)
		end,
		isFile = if isFile == nil then nil else function(_: any, path: string)
			return isFile(path)
		end,
		makeFolder = if makeFolder == nil then nil else function(_: any, path: string)
			return makeFolder(path)
		end,
		isFolder = if isFolder == nil then nil else function(_: any, path: string)
			return isFolder(path)
		end,
	}, nil
end

function Host:LoadProfile(folder: string, name: string): (table?, any?)
	if self._destroyed then
		return nil, errorResult("host_destroyed", "Cannot load a profile after the host is destroyed")
	end
	local path, pathError = profilePath(folder, name)
	if path == nil then
		return nil, pathError
	end
	local storage, storageError = self:_storageAdapter()
	if storage == nil then
		return nil, storageError
	end
	if type(storage.isFile) == "function" then
		local existsOk, exists = pcall(storage.isFile, storage, path)
		if not existsOk then
			return nil, errorResult("profile_read_failed", "Could not inspect profile: " .. tostring(exists))
		end
		if exists == false then
			return {}, nil
		end
	end
	local readOk, raw = pcall(storage.read, storage, path)
	if not readOk then
		return nil, errorResult("profile_read_failed", "Could not read profile: " .. tostring(raw))
	end
	if raw == nil then
		return {}, nil
	end
	if type(raw) ~= "string" then
		return nil, errorResult("profile_malformed", "Profile data must be JSON text")
	end
	if #raw > 262144 then
		return nil, errorResult("profile_too_large", "Profile JSON exceeds 256 KiB")
	end
	local httpService = self:_httpService()
	if httpService == nil or type(httpService.JSONDecode) ~= "function" then
		return nil, errorResult("http_unavailable", "HttpService JSON decoding is unavailable")
	end
	local decodedOk, decoded = pcall(httpService.JSONDecode, httpService, raw)
	if not decodedOk or type(decoded) ~= "table" then
		return nil, errorResult("profile_malformed", "Profile JSON must decode to a table")
	end
	return decoded, nil
end

function Host:SaveProfile(folder: string, name: string, data: table): (boolean, any?)
	if self._destroyed then
		return false, errorResult("host_destroyed", "Cannot save a profile after the host is destroyed")
	end
	local path, pathError = profilePath(folder, name)
	if path == nil then
		return false, pathError
	end
	if type(data) ~= "table" then
		return false, errorResult("invalid_profile_data", "Profile data must be a table")
	end
	local httpService = self:_httpService()
	if httpService == nil or type(httpService.JSONEncode) ~= "function" then
		return false, errorResult("http_unavailable", "HttpService JSON encoding is unavailable")
	end
	local encodedOk, encoded = pcall(httpService.JSONEncode, httpService, data)
	if not encodedOk or type(encoded) ~= "string" then
		return false, errorResult("profile_encode_failed", "Could not encode profile JSON")
	end
	if #encoded > 262144 then
		return false, errorResult("profile_too_large", "Profile JSON exceeds 256 KiB")
	end
	local storage, storageError = self:_storageAdapter()
	if storage == nil then
		return false, storageError
	end
	if type(storage.makeFolder) == "function" then
		local rootExists = false
		if type(storage.isFolder) == "function" then
			local checked, exists = pcall(storage.isFolder, storage, "Potassium")
			rootExists = checked and exists == true
		end
		if not rootExists then
			pcall(storage.makeFolder, storage, "Potassium")
		end
		local safeFolder = string.match(path, "^Potassium/(.-)/")
		local folderPath = "Potassium/" .. (safeFolder or "")
		local folderExists = false
		if type(storage.isFolder) == "function" then
			local checked, exists = pcall(storage.isFolder, storage, folderPath)
			folderExists = checked and exists == true
		end
		if not folderExists then
			pcall(storage.makeFolder, storage, folderPath)
		end
	end
	local writeOk, writeResult = pcall(storage.write, storage, path, encoded)
	if not writeOk or writeResult == false then
		return false, errorResult("profile_write_failed", "Could not save profile")
	end
	return true, nil
end


function Host:CancelTween(instance: Instance)
	local record = self._tweens[instance]
	if record == nil then return end
	self._tweens[instance] = nil
	if record.Connection ~= nil then
		record.Connection:Disconnect()
		record.Connection = nil
	end
	if record.DestroyingConnection ~= nil then
		record.DestroyingConnection:Disconnect()
		record.DestroyingConnection = nil
	end
	pcall(record.Tween.Cancel, record.Tween)
end

function Host:Tween(instance: Instance, info: TweenInfo, properties: table): (Tween?, any?)
	if self._destroyed then
		return nil, errorResult("host_destroyed", "Cannot animate after the host is destroyed")
	end
	if typeof(instance) ~= "Instance" or typeof(info) ~= "TweenInfo" or type(properties) ~= "table" then
		return nil, errorResult("invalid_tween", "Tween requires an Instance, TweenInfo, and property table")
	end
	local tweenService = self._services.TweenService or getService("TweenService")
	if tweenService == nil or type(tweenService.Create) ~= "function" then
		return nil, errorResult("tween_unavailable", "TweenService is unavailable")
	end
	self:CancelTween(instance)
	local createdOk, tween = pcall(tweenService.Create, tweenService, instance, info, properties)
	if not createdOk or tween == nil then
		return nil, errorResult("tween_creation_failed", "Could not create tween: " .. tostring(tween))
	end
	local record: any = { Tween = tween, Connection = nil, DestroyingConnection = nil }
	record.Connection = tween.Completed:Connect(function()
		if self._tweens[instance] == record then
			self._tweens[instance] = nil
		end
		if record.Connection ~= nil then
			record.Connection:Disconnect()
			record.Connection = nil
		end
		if record.DestroyingConnection ~= nil then
			record.DestroyingConnection:Disconnect()
			record.DestroyingConnection = nil
		end
	end)
	self._tweens[instance] = record
	record.DestroyingConnection = instance.Destroying:Connect(function()
		if self._tweens[instance] == record then
			self:CancelTween(instance)
		end
	end)
	tween:Play()
	return tween, nil
end

function Host:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	for instance in pairs(self._tweens) do
		self:CancelTween(instance)
	end
	for _, connection in ipairs(self._connections) do
		pcall(function()
			connection:Disconnect()
		end)
	end
	table.clear(self._connections)
	if self._screenGui ~= nil then
		pcall(function()
			self._screenGui:Destroy()
		end)
		self._screenGui = nil
	end
end

return Host

end

__modules["core/Signal"] = function()
--!strict

export type Connection = {
	Connected: boolean,
	Disconnect: (self: Connection) -> (),
}

export type Signal<T...> = {
	Connect: (self: Signal<T...>, callback: (T...) -> ()) -> Connection,
	Once: (self: Signal<T...>, callback: (T...) -> ()) -> Connection,
	Fire: (self: Signal<T...>, T...) -> (),
	Destroy: (self: Signal<T...>) -> (),
	DisconnectAll: (self: Signal<T...>) -> (),
}

local Signal = {}
Signal.__index = Signal

local Connection = {}
Connection.__index = Connection

function Connection:Disconnect()
	if not self.Connected then
		return
	end
	self.Connected = false
	local signal = self._signal
	if signal ~= nil then
		signal._connections[self._id] = nil
		self._signal = nil
	end
	self._callback = nil
end

local function invoke(callback: (...any) -> (), ...: any)
	local ok, err = xpcall(callback, debug.traceback, ...)
	if not ok then
		warn("PotassiumUI Signal callback failed:\n" .. tostring(err))
	end
end

function Signal.new<T...>(): Signal<T...>
	return setmetatable({
		_connections = {} :: { [number]: any },
		_nextId = 0,
		_destroyed = false,
	}, Signal) :: any
end

function Signal:Connect(callback: (...any) -> ()): Connection
	assert(type(callback) == "function", "Signal callback must be a function")
	assert(not self._destroyed, "Cannot connect to a destroyed Signal")

	self._nextId += 1
	local connection = setmetatable({
		Connected = true,
		_id = self._nextId,
		_signal = self,
		_callback = callback,
		_once = false,
	}, Connection)
	self._connections[connection._id] = connection
	return connection
end

function Signal:Once(callback: (...any) -> ()): Connection
	local connection = self:Connect(callback)
	connection._once = true
	return connection
end

function Signal:Fire(...: any)
	if self._destroyed then
		return
	end

	local pending = {}
	for _, connection in pairs(self._connections) do
		table.insert(pending, connection)
	end
	table.sort(pending, function(left, right)
		return left._id < right._id
	end)

	for _, connection in ipairs(pending) do
		if connection.Connected then
			local callback = connection._callback
			if connection._once then
				connection:Disconnect()
			end
			invoke(callback, ...)
		end
	end
end

function Signal:DisconnectAll()
	local connections = self._connections
	self._connections = {}
	for _, connection in pairs(connections) do
		connection.Connected = false
		connection._signal = nil
		connection._callback = nil
	end
end

function Signal:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	self:DisconnectAll()
end

return Signal

end

__modules["core/Store"] = function()
--!strict

local Signal = __require("core/Signal")
local Util = __require("core/Util")

export type StructuredError = { code: string, message: string }
export type MutationSource = "user" | "program" | "load" | "migration" | "schema-update"
export type Validator = (value: any) -> (boolean, string?)
export type Normalizer = (value: any) -> any
export type Definition = {
	id: string,
	default: any,
	validate: Validator?,
	normalize: Normalizer?,
	onChange: ((newValue: any, oldValue: any, id: string, source: MutationSource?) -> ())?,
	persist: boolean?,
}
export type Subscription = { Disconnect: (self: Subscription) -> (), Connected: boolean }

local Store = {}
Store.__index = Store

local function failure(code: string, message: string): StructuredError
	return { code = code, message = message }
end

local SOURCES = table.freeze({
	user = true,
	program = true,
	load = true,
	migration = true,
	["schema-update"] = true,
})

local function mutationSource(value: any): (MutationSource?, StructuredError?)
	local source = if value == nil then "program" else value
	if SOURCES[source] ~= true then
		return nil, failure("invalid_source", "Store source must be user, program, load, migration, or schema-update")
	end
	return source :: MutationSource, nil
end

local function invoke(callback: ((...any) -> ())?, ...: any): (boolean, any?)
	return Util.safeCallback(callback, ...)
end

local function shallowCopy(value: any): any
	return Util.deepCopy(value)
end

local function rangeValidator(value: any): (boolean, string?)
	if type(value) ~= "table" or type(value.min) ~= "number" or type(value.max) ~= "number" then
		return false, "range must contain numeric min and max values"
	end
	return true, nil
end

local function normalizeRange(value: any): any
	local copied = shallowCopy(value)
	if copied.min > copied.max then
		copied.min, copied.max = copied.max, copied.min
	end
	return copied
end

Store.Validators = {
	boolean = function(value: any): (boolean, string?)
		return type(value) == "boolean", "value must be a boolean"
	end,
	number = function(minimum: number?, maximum: number?): Validator
		return function(value: any): (boolean, string?)
			if type(value) ~= "number" then
				return false, "value must be a number"
			end
			if minimum ~= nil and value < minimum then
				return false, "value is below its minimum"
			end
			if maximum ~= nil and value > maximum then
				return false, "value exceeds its maximum"
			end
			return true, nil
		end
	end,
	string = function(maximumLength: number?): Validator
		return function(value: any): (boolean, string?)
			if type(value) ~= "string" then
				return false, "value must be a string"
			end
			if maximumLength ~= nil and #value > maximumLength then
				return false, "value exceeds its maximum length"
			end
			return true, nil
		end
	end,
	enum = function(allowed: { any }): Validator
		return function(value: any): (boolean, string?)
			for _, permitted in ipairs(allowed) do
				if value == permitted then
					return true, nil
				end
			end
			return false, "value is not an allowed option"
		end
	end,
	range = rangeValidator,
	color = function(value: any): (boolean, string?)
		if typeof(value) == "Color3" then
			return true, nil
		end
		if
			type(value) == "table"
			and type(value.r) == "number"
			and type(value.g) == "number"
			and type(value.b) == "number"
		then
			return true, nil
		end
		return false, "color must be a Color3 or an rgb table"
	end,
	keybind = function(value: any): (boolean, string?)
		local valueType = typeof(value)
		if valueType == "EnumItem" or type(value) == "string" then
			return true, nil
		end
		if type(value) == "table" and (typeof(value.keyCode) == "EnumItem" or type(value.keyCode) == "string") then
			return true, nil
		end
		return false, "keybind must be an EnumItem, string, or keybind table"
	end,
}

Store.Normalizers = {
	range = normalizeRange,
	color = function(value: any): any
		if typeof(value) == "Color3" then
			return value
		end
		return {
			r = Util.clamp(value.r, 0, 1),
			g = Util.clamp(value.g, 0, 1),
			b = Util.clamp(value.b, 0, 1),
			a = if type(value.a) == "number" then Util.clamp(value.a, 0, 1) else 1,
		}
	end,
	keybind = function(value: any): any
		return shallowCopy(value)
	end,
}

function Store.new(
	definitions: { Definition }?,
	options: { onCallbackError: ((StructuredError, string) -> ())? }?
): (any?, StructuredError?)
	if definitions ~= nil and type(definitions) ~= "table" then
		return nil, failure("invalid_definitions", "Store definitions must be an array")
	end
	local self = setmetatable({
		_definitions = {} :: { [string]: Definition },
		_values = {} :: { [string]: any },
		_signals = {} :: { [string]: any },
		_pendingRestores = {} :: { any },
		_pendingRestoreBytes = 0,
		_pendingRestoreInsertion = 0,
		_restoreGeneration = 0,
		_dispatchDepth = 0,
		_mutationQueue = {} :: { () -> () },
		_drainingMutations = false,
		_destroyed = false,
		_onCallbackError = if options then options.onCallbackError else nil,
		_suppressDefinitionCallbacks = 0,
		Changed = Signal.new(),
		Unregistered = Signal.new(),
		Diagnostic = Signal.new(),
	}, Store)

	for index, definition in ipairs(definitions or {}) do
		local ok, errorValue = self:Register(definition)
		if not ok then
			self:Destroy()
			return nil, failure(errorValue.code, "Definition " .. tostring(index) .. ": " .. errorValue.message)
		end
	end
	return self, nil
end

function Store:Register(definition: Definition, options: any?): (boolean, StructuredError?)
	if self._destroyed then
		return false, failure("destroyed", "Store has been destroyed")
	end
	if type(definition) ~= "table" or type(definition.id) ~= "string" or definition.id == "" then
		return false, failure("invalid_definition", "Definition requires a non-empty id")
	end
	if definition.id ~= Util.sanitizeId(definition.id) then
		return false, failure("unstable_id", "Definition id must be a sanitized stable string: " .. definition.id)
	end
	if self._definitions[definition.id] ~= nil then
		return false, failure("duplicate_id", "Duplicate store id: " .. definition.id)
	end

	local initial = shallowCopy(definition.default)
	if definition.normalize ~= nil then
		local normalizedOk, normalized = pcall(definition.normalize, initial)
		if not normalizedOk then
			return false, failure("normalizer_failed", "Default normalizer failed for " .. definition.id)
		end
		initial = normalized
	end
	if definition.validate ~= nil then
		local validOk, valid, reason = pcall(definition.validate, initial)
		if not validOk or not valid then
			return false,
				failure(
					"invalid_default",
					"Default for " .. definition.id .. ": " .. tostring(reason or "validator failed")
				)
		end
	end
	self._definitions[definition.id] = definition
	self._values[definition.id] = shallowCopy(initial)
	self._signals[definition.id] = Signal.new()
	if not (type(options) == "table" and options.deferPending == true) then self:_consumePending(definition.id) end
	return true, nil
end

local function valuesEqual(left: any, right: any, seen: any?): boolean
	if left == right then
		return true
	end
	if type(left) ~= "table" or type(right) ~= "table" then
		return false
	end
	local visited = seen or {}
	if visited[left] == right then
		return true
	end
	visited[left] = right
	for key, value in pairs(left) do
		if not valuesEqual(value, right[key], visited) then
			return false
		end
	end
	for key in pairs(right) do
		if left[key] == nil then
			return false
		end
	end
	return true
end

function Store:ReplaceDefinition(id: string, definition: Definition, options: any?): (boolean, StructuredError?)
	if self._destroyed then
		return false, failure("destroyed", "Store has been destroyed")
	end
	if type(id) ~= "string" or id == "" or id ~= Util.sanitizeId(id) then
		return false, failure("unstable_id", "Store id must be a sanitized stable string")
	end
	local existing = self._definitions[id]
	if existing == nil then
		return false, failure("unknown_id", "Unknown store id: " .. id)
	end
	if type(definition) ~= "table" or definition.id ~= id then
		return false, failure("invalid_definition", "Replacement definition id must match the existing store id")
	end

	local replacement = {
		id = id,
		default = definition.default,
		validate = definition.validate,
		normalize = definition.normalize,
		onChange = if definition.onChange ~= nil then definition.onChange else existing.onChange,
		persist = if definition.persist ~= nil then definition.persist else existing.persist,
	}
	local function prepare(value: any, failureCode: string): (boolean, any)
		local prepared = shallowCopy(value)
		if replacement.normalize ~= nil then
			local normalizedOk, normalized = pcall(replacement.normalize, prepared)
			if not normalizedOk then
				return false, failure("normalizer_failed", "Replacement normalizer failed for " .. id)
			end
			prepared = normalized
		end
		if replacement.validate ~= nil then
			local validOk, valid, reason = pcall(replacement.validate, prepared)
			if not validOk or not valid then
				return false, failure(failureCode, "Replacement value for " .. id .. ": " .. tostring(reason or "validator failed"))
			end
		end
		return true, prepared
	end

	local defaultOk, preparedDefault = prepare(replacement.default, "invalid_default")
	if not defaultOk then
		return false, preparedDefault
	end
	local currentOk, preparedCurrent = prepare(self._values[id], "invalid_value")
	local nextValue = if currentOk then preparedCurrent else preparedDefault
	local oldValue = self._values[id]

	self._definitions[id] = replacement
	self._values[id] = shallowCopy(nextValue)
	if not valuesEqual(oldValue, nextValue) then
		if type(options) == "table" and options.deferNotifications == true and type(options.notifications) == "table" then
			table.insert(options.notifications, function() self:_emit(id, nextValue, oldValue, "schema-update") end)
		else
			self:_emit(id, nextValue, oldValue, "schema-update")
		end
	end
	return true, nil
end

function Store:ValidateDefinitionReplacement(id: string, definition: Definition, value: any?, hasValue: boolean?): (boolean, StructuredError?)
	if self._destroyed then return false, failure("destroyed", "Store has been destroyed") end
	if type(id) ~= "string" or id == "" or id ~= Util.sanitizeId(id) then
		return false, failure("unstable_id", "Store id must be a sanitized stable string")
	end
	if self._definitions[id] == nil then return false, failure("unknown_id", "Unknown store id: " .. id) end
	if type(definition) ~= "table" or definition.id ~= id then
		return false, failure("invalid_definition", "Replacement definition id must match the existing store id")
	end
	local function validate(candidate: any, failureCode: string): (boolean, StructuredError?)
		local prepared = shallowCopy(candidate)
		if definition.normalize ~= nil then
			local normalizedOk, normalized = pcall(definition.normalize, prepared)
			if not normalizedOk then return false, failure("normalizer_failed", "Replacement normalizer failed for " .. id) end
			prepared = normalized
		end
		if definition.validate ~= nil then
			local validOk, valid, reason = pcall(definition.validate, prepared)
			if not validOk or not valid then return false, failure(failureCode, "Replacement value for " .. id .. ": " .. tostring(reason or "validator failed")) end
		end
		return true, nil
	end
	local defaultOk, defaultError = validate(definition.default, "invalid_default")
	if not defaultOk then return false, defaultError end
	if hasValue then return validate(value, "invalid_value") end
	return true, nil
end

function Store:_CaptureDefinition(id: string): (any?, StructuredError?)
	if self._destroyed then return nil, failure("destroyed", "Store has been destroyed") end
	local definition, signal = self._definitions[id], self._signals[id]
	if definition == nil or signal == nil then return nil, failure("unknown_id", "Unknown store id: " .. tostring(id)) end
	return {
		owner = self,
		id = id,
		definition = definition,
		value = shallowCopy(self._values[id]),
		signal = signal,
	}, nil
end

function Store:_RestoreDefinition(id: string, checkpoint: any): (boolean, StructuredError?)
	if self._destroyed then return false, failure("destroyed", "Store has been destroyed") end
	if type(checkpoint) ~= "table" or checkpoint.owner ~= self or checkpoint.id ~= id then
		return false, failure("invalid_definition_checkpoint", "Definition checkpoint belongs to another Store or id")
	end
	if checkpoint.signal == nil or self._signals[id] ~= checkpoint.signal or self._definitions[id] == nil then
		return false, failure("stale_definition_checkpoint", "Definition signal was removed or replaced before rollback")
	end
	self._definitions[id] = checkpoint.definition
	self._values[id] = shallowCopy(checkpoint.value)
	return true, nil
end

function Store:Unregister(id: string, options: any?): (boolean, StructuredError?)
	if self._destroyed then return false, failure("destroyed", "Store has been destroyed") end
	local signal = self._signals[id]
	if signal == nil then return false, failure("unknown_id", "Unknown store id: " .. id) end
	signal:Destroy()
	self._signals[id] = nil
	self._values[id] = nil
	self._definitions[id] = nil
	if not (type(options) == "table" and options.silent == true) then self.Unregistered:Fire(id) end
	return true, nil
end

function Store:CommitStagedDefinition(id: string, options: any?): (boolean, StructuredError?)
	if self._destroyed then return false, failure("destroyed", "Store has been destroyed") end
	if type(id) ~= "string" or self._definitions[id] == nil then return false, failure("unknown_id", "Unknown store id: " .. tostring(id)) end
	if type(options) == "table" and options.discardPending == true then
		for index = #self._pendingRestores, 1, -1 do
			if self._pendingRestores[index].id == id then self:_discardPending(index, "superseded") end
		end
	else
		self:_consumePending(id)
	end
	return true, nil
end

function Store:_reportCallbackError(id: string, err: any)
	local callbackError = failure("callback_failed", "Callback for " .. id .. " failed: " .. tostring(err))
	invoke(self._onCallbackError, callbackError, id)
end

function Store:_drainMutations()
	if self._drainingMutations or self._dispatchDepth ~= 0 then
		return
	end
	self._drainingMutations = true
	while self._dispatchDepth == 0 and #self._mutationQueue > 0 do
		local mutation = table.remove(self._mutationQueue, 1)
		mutation()
	end
	self._drainingMutations = false
end

function Store:_beginDispatch()
	self._dispatchDepth += 1
end

function Store:_endDispatch()
	self._dispatchDepth -= 1
	if self._dispatchDepth == 0 then
		self:_drainMutations()
	end
end

function Store:_emitCaptured(notification: any)
	local emittedValue = shallowCopy(notification.value)
	local emittedOldValue = shallowCopy(notification.oldValue)
	notification.signal:Fire(emittedValue, emittedOldValue, notification.id, notification.source)
	self.Changed:Fire(notification.id, emittedValue, emittedOldValue, notification.source)
	if not self._destroyed and self._suppressDefinitionCallbacks == 0 and not notification.suppressDefinitionCallback then
		local callbackOk, callbackError = invoke(
			notification.onChange,
			emittedValue,
			shallowCopy(notification.oldValue),
			notification.id,
			notification.source
		)
		if not callbackOk then
			self:_reportCallbackError(notification.id, callbackError)
		end
	end
end

function Store:_publishNotifications(notifications: { any })
	self:_beginDispatch()
	for _, notification in ipairs(notifications) do
		self:_emitCaptured(notification)
	end
	self:_endDispatch()
end

function Store:_emit(id: string, newValue: any, oldValue: any, source: MutationSource, suppressDefinitionCallback: boolean?)
	local signal = self._signals[id]
	local definition = self._definitions[id]
	if signal == nil or definition == nil then
		return
	end
	self:_publishNotifications({
		{
			id = id,
			value = newValue,
			oldValue = oldValue,
			signal = signal,
			onChange = definition.onChange,
			source = source,
			suppressDefinitionCallback = suppressDefinitionCallback,
		},
	})
end

function Store:SuppressDefinitionCallback(callback: (() -> any)?): any
	if type(callback) ~= "function" then
		return failure("invalid_callback", "SuppressDefinitionCallback requires a callback")
	end
	self._suppressDefinitionCallbacks += 1
	local results = table.pack(xpcall(callback, debug.traceback))
	self._suppressDefinitionCallbacks -= 1
	if not results[1] then
		error(results[2], 0)
	end
	return table.unpack(results, 2, results.n)
end

function Store:_prepare(id: string, value: any): (boolean, any)
	local definition = self._definitions[id]
	if definition == nil then
		return false, failure("unknown_id", "Unknown store id: " .. id)
	end
	local normalized = shallowCopy(value)
	if definition.normalize ~= nil then
		local ok, result = pcall(definition.normalize, normalized)
		if not ok then
			return false, failure("normalizer_failed", "Normalizer failed for " .. id)
		end
		normalized = result
	end
	if definition.validate ~= nil then
		local ok, valid, reason = pcall(definition.validate, normalized)
		if not ok or not valid then
			return false,
				failure("invalid_value", "Invalid value for " .. id .. ": " .. tostring(reason or "validator failed"))
		end
	end
	return true, normalized
end

function Store:_commitSet(id: string, prepared: any, source: MutationSource)
	if self._destroyed or self._definitions[id] == nil then
		return
	end
	local oldValue = self._values[id]
	if valuesEqual(oldValue, prepared) then return end
	self._values[id] = shallowCopy(prepared)
	if self._dispatchDepth > 0 then
		local suppressDefinitionCallback = self._suppressDefinitionCallbacks > 0
		table.insert(self._mutationQueue, function()
			self:_emit(id, prepared, oldValue, source, suppressDefinitionCallback)
		end)
	else
		self:_emit(id, prepared, oldValue, source)
	end
end

function Store:Set(id: string, value: any, sourceValue: any?): (boolean, StructuredError?)
	if self._destroyed then
		return false, failure("destroyed", "Store has been destroyed")
	end
	local source, sourceError = mutationSource(sourceValue)
	if source == nil then
		return false, sourceError
	end
	local ok, prepared = self:_prepare(id, value)
	if not ok then
		return false, prepared
	end
	self:_commitSet(id, prepared, source)
	return true, nil
end

function Store:Get(id: string): (any, StructuredError?)
	local value = self._values[id]
	if value == nil and self._definitions[id] == nil then
		return nil, failure("unknown_id", "Unknown store id: " .. id)
	end
	return shallowCopy(value), nil
end

function Store:List(): { string }
	local ids = {}
	for id in pairs(self._definitions) do
		table.insert(ids, id)
	end
	table.sort(ids)
	return table.freeze(ids)
end

function Store:Reset(id: string, source: any?): (boolean, StructuredError?)
	local definition = self._definitions[id]
	if definition == nil then
		return false, failure("unknown_id", "Unknown store id: " .. id)
	end
	return self:Set(id, definition.default, source)
end

function Store:ResetAll(source: any?): (boolean, StructuredError?)
	for id, definition in pairs(self._definitions) do
		local ok, errorValue = self:Set(id, definition.default, source)
		if not ok then
			return false, errorValue
		end
	end
	return true, nil
end

function Store:Subscribe(
	id: string,
	callback: (newValue: any, oldValue: any, id: string, source: MutationSource) -> ()
): (Subscription?, StructuredError?)
	if self._destroyed then
		return nil, failure("destroyed", "Store has been destroyed")
	end
	local signal = self._signals[id]
	if signal == nil then
		return nil, failure("unknown_id", "Unknown store id: " .. id)
	end
	if type(callback) ~= "function" then
		return nil, failure("invalid_callback", "Store subscriber must be a function")
	end
	return signal:Connect(callback), nil
end

local MAX_SNAPSHOT_DEPTH = 16
local TYPE_TAG = "__potassiumType"

local function isFiniteNumber(value: number): boolean
	return value == value and value ~= math.huge and value ~= -math.huge
end

local function hasExactFields(value: { [any]: any }, fields: { string }): boolean
	local expected = {}
	for _, field in ipairs(fields) do
		expected[field] = true
		if value[field] == nil then
			return false
		end
	end
	for key in pairs(value) do
		if type(key) ~= "string" or expected[key] ~= true then
			return false
		end
	end
	return true
end

local function encodeSnapshotKey(key: any): (boolean, any)
	if type(key) == "string" then
		return true, { kind = "string", value = key }
	end
	if type(key) == "number" and isFiniteNumber(key) then
		return true, { kind = "number", value = key }
	end
	return false, failure("unsupported_snapshot_key", "Snapshot table keys must be finite numbers or strings")
end

local function decodeSnapshotKey(value: any): (boolean, any)
	if type(value) ~= "table" or not hasExactFields(value, { "kind", "value" }) then
		return false, failure("malformed_snapshot_envelope", "Snapshot table entry has an invalid key")
	end
	if value.kind == "string" and type(value.value) == "string" then
		return true, value.value
	end
	if value.kind == "number" and type(value.value) == "number" and isFiniteNumber(value.value) then
		return true, value.value
	end
	return false, failure("malformed_snapshot_envelope", "Snapshot table entry has an invalid key")
end

local function encodeSnapshotValue(value: any, depth: number, seen: { [any]: boolean }): (boolean, any)
	if depth > MAX_SNAPSHOT_DEPTH then
		return false,
			failure(
				"snapshot_too_deep",
				"Snapshot values may not exceed " .. tostring(MAX_SNAPSHOT_DEPTH) .. " nested tables"
			)
	end
	local valueType = typeof(value)
	if valueType == "Color3" then
		return true, { [TYPE_TAG] = "Color3", r = value.R, g = value.G, b = value.B, a = 1 }
	end
	if valueType == "Vector2" then
		if not isFiniteNumber(value.X) or not isFiniteNumber(value.Y) then
			return false, failure("unsupported_snapshot_value", "Vector2 snapshot components must be finite")
		end
		return true, { [TYPE_TAG] = "Vector2", x = value.X, y = value.Y }
	end
	if valueType == "EnumItem" then
		local enumTypeName = tostring(value.EnumType)
		enumTypeName = string.match(enumTypeName, "^Enum%.(.+)$") or enumTypeName
		if enumTypeName == "" then
			return false, failure("unsupported_snapshot_value", "EnumItem has an unavailable enum type")
		end
		return true, { [TYPE_TAG] = "EnumItem", enumType = enumTypeName, name = value.Name }
	end
	if valueType == "Font" then
		return true,
			{
				[TYPE_TAG] = "Font",
				family = value.Family,
				weight = value.Weight.Name,
				style = value.Style.Name,
			}
	end
	if type(value) ~= "table" then
		if valueType == "nil" or valueType == "boolean" or valueType == "string" then
			return true, value
		end
		if valueType == "number" and isFiniteNumber(value) then
			return true, value
		end
		return false, failure("unsupported_snapshot_value", "Cannot persist " .. valueType)
	end
	if seen[value] then
		return false, failure("snapshot_cycle", "Snapshot values cannot contain cyclic tables")
	end
	seen[value] = true
	local entries = {}
	for key, nestedValue in pairs(value) do
		local keyOk, encodedKey = encodeSnapshotKey(key)
		if not keyOk then
			seen[value] = nil
			return false, encodedKey
		end
		local valueOk, encodedValue = encodeSnapshotValue(nestedValue, depth + 1, seen)
		if not valueOk then
			seen[value] = nil
			return false, encodedValue
		end
		table.insert(entries, { key = encodedKey, value = encodedValue })
	end
	seen[value] = nil
	return true, { [TYPE_TAG] = "Table", entries = entries }
end

local function decodeSnapshotValue(value: any, depth: number, seen: { [any]: boolean }): (boolean, any)
	if depth > MAX_SNAPSHOT_DEPTH then
		return false,
			failure(
				"snapshot_too_deep",
				"Snapshot values may not exceed " .. tostring(MAX_SNAPSHOT_DEPTH) .. " nested tables"
			)
	end
	local valueType = typeof(value)
	if type(value) ~= "table" then
		if valueType == "nil" or valueType == "boolean" or valueType == "string" then
			return true, value
		end
		if valueType == "number" and isFiniteNumber(value) then
			return true, value
		end
		return false, failure("malformed_snapshot_envelope", "Snapshot contains an unsupported value")
	end
	if seen[value] then
		return false, failure("snapshot_cycle", "Snapshot values cannot contain cyclic tables")
	end
	seen[value] = true
	local tag = value[TYPE_TAG]
	if tag == "Color3" then
		if
			not hasExactFields(value, { TYPE_TAG, "r", "g", "b", "a" })
			or type(value.r) ~= "number"
			or type(value.g) ~= "number"
			or type(value.b) ~= "number"
			or type(value.a) ~= "number"
			or not isFiniteNumber(value.r)
			or not isFiniteNumber(value.g)
			or not isFiniteNumber(value.b)
			or not isFiniteNumber(value.a)
			or value.r < 0
			or value.r > 1
			or value.g < 0
			or value.g > 1
			or value.b < 0
			or value.b > 1
			or value.a < 0
			or value.a > 1
		then
			seen[value] = nil
			return false, failure("malformed_snapshot_tag", "Color3 snapshot tag has invalid channels")
		end
		seen[value] = nil
		return true, Color3.new(value.r, value.g, value.b)
	end
	if tag == "Vector2" then
		if
			not hasExactFields(value, { TYPE_TAG, "x", "y" })
			or type(value.x) ~= "number"
			or type(value.y) ~= "number"
			or not isFiniteNumber(value.x)
			or not isFiniteNumber(value.y)
		then
			seen[value] = nil
			return false, failure("malformed_snapshot_tag", "Vector2 snapshot tag has invalid components")
		end
		seen[value] = nil
		return true, Vector2.new(value.x, value.y)
	end
	if tag == "EnumItem" then
		if
			not hasExactFields(value, { TYPE_TAG, "enumType", "name" })
			or type(value.enumType) ~= "string"
			or type(value.name) ~= "string"
		then
			seen[value] = nil
			return false, failure("malformed_snapshot_tag", "EnumItem snapshot tag is missing enumType or name")
		end
		local ok, item = pcall(function()
			return (Enum :: any)[value.enumType][value.name]
		end)
		seen[value] = nil
		if not ok or typeof(item) ~= "EnumItem" then
			return false, failure("malformed_snapshot_tag", "EnumItem snapshot tag names an unavailable enum item")
		end
		return true, item
	end
	if tag == "Font" then
		if
			not hasExactFields(value, { TYPE_TAG, "family", "weight", "style" })
			or type(value.family) ~= "string"
			or type(value.weight) ~= "string"
			or type(value.style) ~= "string"
		then
			seen[value] = nil
			return false, failure("malformed_snapshot_tag", "Font snapshot tag is invalid")
		end
		local ok, font = pcall(function()
			return Font.new(value.family, (Enum.FontWeight :: any)[value.weight], (Enum.FontStyle :: any)[value.style])
		end)
		seen[value] = nil
		if not ok or typeof(font) ~= "Font" then
			return false, failure("malformed_snapshot_tag", "Font snapshot tag names an unavailable font")
		end
		return true, font
	end
	if tag ~= "Table" or not hasExactFields(value, { TYPE_TAG, "entries" }) or type(value.entries) ~= "table" then
		seen[value] = nil
		return false, failure("malformed_snapshot_envelope", "Snapshot table must use a recognized envelope")
	end
	local copied = {}
	local decodedKeys = {}
	local entryCount = #value.entries
	for entryIndex, entry in pairs(value.entries) do
		if
			type(entryIndex) ~= "number"
			or entryIndex % 1 ~= 0
			or entryIndex < 1
			or entryIndex > entryCount
			or type(entry) ~= "table"
			or not hasExactFields(entry, { "key", "value" })
		then
			seen[value] = nil
			return false, failure("malformed_snapshot_envelope", "Snapshot table has an invalid entry")
		end
		local keyOk, decodedKey = decodeSnapshotKey(entry.key)
		if not keyOk then
			seen[value] = nil
			return false, decodedKey
		end
		if decodedKeys[decodedKey] then
			seen[value] = nil
			return false, failure("malformed_snapshot_envelope", "Snapshot table contains duplicate keys")
		end
		local valueOk, decodedValue = decodeSnapshotValue(entry.value, depth + 1, seen)
		if not valueOk then
			seen[value] = nil
			return false, decodedValue
		end
		decodedKeys[decodedKey] = true
		copied[decodedKey] = decodedValue
	end
	for entryIndex = 1, entryCount do
		if value.entries[entryIndex] == nil then
			seen[value] = nil
			return false, failure("malformed_snapshot_envelope", "Snapshot table entries must be a dense array")
		end
	end
	seen[value] = nil
	return true, copied
end

function Store:Snapshot(): ({ [string]: any }?, StructuredError?)
	local snapshot = {}
	for id, value in pairs(self._values) do
		local definition = self._definitions[id]
		if definition == nil or definition.persist ~= false then
			local ok, encoded = encodeSnapshotValue(value, 0, {})
			if not ok then
				return nil, encoded
			end
			snapshot[id] = encoded
		end
	end
	return snapshot, nil
end

function Store:_diagnose(code: string, id: string, generation: number, reason: string)
	self.Diagnostic:Fire(table.freeze({ code = code, id = id, generation = generation, reason = reason }))
end

function Store:_discardPending(index: number, reason: string)
	local record = self._pendingRestores[index]
	if record == nil then
		return
	end
	self._pendingRestoreBytes -= record.bytes
	table.remove(self._pendingRestores, index)
	self:_diagnose("pending_restore_discarded", record.id, record.generation, reason)
end

function Store:_queuePendingRestore(id: string, value: any, generation: number, bytes: number, suppressDefinitionCallback: boolean)
	self._pendingRestoreInsertion += 1
	table.insert(self._pendingRestores, {
		id = id,
		value = value,
		generation = generation,
		insertion = self._pendingRestoreInsertion,
		bytes = bytes,
		suppressDefinitionCallback = suppressDefinitionCallback,
	})
	self._pendingRestoreBytes += bytes
	while #self._pendingRestores > 128 or self._pendingRestoreBytes > 65536 do
		local oldest = 1
		for index = 2, #self._pendingRestores do
			local candidate = self._pendingRestores[index]
			local selected = self._pendingRestores[oldest]
			if candidate.generation < selected.generation
				or (candidate.generation == selected.generation and candidate.insertion < selected.insertion)
			then
				oldest = index
			end
		end
		self:_discardPending(oldest, "capacity")
	end
end

function Store:_consumePending(id: string)
	local selectedIndex: number? = nil
	for index, record in ipairs(self._pendingRestores) do
		if record.id == id and (selectedIndex == nil
			or record.generation > self._pendingRestores[selectedIndex].generation
			or (record.generation == self._pendingRestores[selectedIndex].generation and record.insertion > self._pendingRestores[selectedIndex].insertion))
		then
			selectedIndex = index
		end
	end
	if selectedIndex == nil then return end
	local selected = self._pendingRestores[selectedIndex]
	-- Consume an id as one atomic logical record: stale generations must never
	-- survive an unregister/register cycle to overwrite the selected restore.
	for index = #self._pendingRestores, 1, -1 do
		local record = self._pendingRestores[index]
		if record.id == id then
			self:_discardPending(index, if index == selectedIndex then "consumed" else "superseded")
		end
	end
	local definition = self._definitions[id]
	if definition == nil or definition.persist == false then
		self:_diagnose("pending_restore_discarded", id, selected.generation, "persist_disabled")
		return
	end
	local prepared, normalized = self:_prepare(id, selected.value)
	if not prepared then
		self:_diagnose("pending_restore_discarded", id, selected.generation, "invalid_value")
		return
	end
	local function apply()
		self:_commitSet(id, normalized, "load")
	end
	if selected.suppressDefinitionCallback then self:SuppressDefinitionCallback(apply) else apply() end
end

local function snapshotBytes(value: any, remaining: number): number
	if type(value) ~= "table" then
		return if type(value) == "string" then #value else #tostring(value)
	end
	local bytes = 2
	for key, nested in pairs(value) do
		bytes += snapshotBytes(key, remaining - bytes) + snapshotBytes(nested, remaining - bytes) + 2
		if bytes > remaining then break end
	end
	return bytes
end

function Store:Hydrate(snapshot: { [string]: any }, options: any?): (boolean, StructuredError?)
	if self._destroyed then
		return false, failure("destroyed", "Store has been destroyed")
	end
	if type(snapshot) ~= "table" then
		return false, failure("invalid_snapshot", "Snapshot must be a table")
	end
	local generation = if type(options) == "table" and type(options.generation) == "number" then options.generation else self._restoreGeneration + 1
	if generation % 1 ~= 0 or generation < 1 then
		return false, failure("invalid_generation", "Restore generation must be a positive integer")
	end
	if generation <= self._restoreGeneration then
		return true, nil
	end
	local prepared = {}
	local preparedIds = {}
	local pending = {}
	local diagnostics = {}
	local aggregateBytes = 0
	for id, value in pairs(snapshot) do
		if type(id) ~= "string" then
			return false, failure("invalid_snapshot", "Snapshot ids must be strings")
		end
		local decodedOk, decoded = decodeSnapshotValue(value, 0, {})
		if not decodedOk then
			return false, decoded
		end
		local definition = self._definitions[id]
		if definition ~= nil then
			if definition.persist == false then
				table.insert(diagnostics, { code = "restore_discarded", id = id, reason = "persist_disabled" })
			else
				local ok, normalized = self:_prepare(id, decoded)
				if not ok then
					return false, normalized
				end
				prepared[id] = normalized
				table.insert(preparedIds, id)
			end
		else
			if #pending >= 128 then
				return false, failure("pending_restore_limit", "Pending restore data may contain at most 128 records")
			end
			local bytes = #id + snapshotBytes(value, 65536 - aggregateBytes - #id)
			aggregateBytes += bytes
			if aggregateBytes > 65536 then
				return false, failure("pending_restore_too_large", "Pending restore data exceeds 64 KiB")
			end
			table.insert(pending, { id = id, value = decoded, bytes = bytes })
		end
	end
	table.sort(preparedIds)
	local notifications = {}
	for _, id in ipairs(preparedIds) do
		local definition = self._definitions[id]
		local signal = self._signals[id]
		if definition == nil or signal == nil then
			return false, failure("unknown_id", "Store definition was removed during hydration")
		end
		local value = prepared[id]
		table.insert(notifications, {
			id = id,
			value = value,
			oldValue = self._values[id],
			signal = signal,
			onChange = definition.onChange,
			source = "load",
		})
	end
	-- Commit the whole snapshot before publishing any observer-visible effect.
	for _, notification in ipairs(notifications) do
		self._values[notification.id] = shallowCopy(notification.value)
	end
	for _, record in ipairs(self._pendingRestores) do
		table.insert(diagnostics, {
			code = "pending_restore_discarded",
			id = record.id,
			reason = "superseded_snapshot",
			generation = record.generation,
		})
	end
	table.clear(self._pendingRestores)
	self._pendingRestoreBytes = 0
	local suppressDefinition = type(options) == "table" and (options.suppressCallbacks == true or options.SuppressDefinitionCallback == true)
	for _, record in ipairs(pending) do
		self._pendingRestoreInsertion += 1
		table.insert(self._pendingRestores, {
			id = record.id,
			value = record.value,
			generation = generation,
			insertion = self._pendingRestoreInsertion,
			bytes = record.bytes,
			suppressDefinitionCallback = suppressDefinition,
		})
		self._pendingRestoreBytes += record.bytes
	end
	self._restoreGeneration = generation
	local function publish()
		self:_publishNotifications(notifications)
	end
	if suppressDefinition then
		self:SuppressDefinitionCallback(publish)
	else
		publish()
	end
	for _, diagnostic in ipairs(diagnostics) do
		self:_diagnose(diagnostic.code, diagnostic.id, diagnostic.generation or generation, diagnostic.reason)
	end
	return true, nil
end

function Store:PrepareTransaction(changes: any, options: any?): (any?, StructuredError?)
	if type(changes) ~= "table" then
		return nil, failure("invalid_transaction", "Transaction changes must be a table")
	end
	local source, sourceError = mutationSource(if type(options) == "table" then options.source else nil)
	if source == nil then
		return nil, sourceError
	end
	local values, definitions, oldValues, ids = {}, {}, {}, {}
	for id, value in pairs(changes) do
		local ok, prepared = self:_prepare(id, value)
		if not ok then
			return nil, prepared
		end
		values[id], definitions[id], oldValues[id] = prepared, self._definitions[id], shallowCopy(self._values[id])
		table.insert(ids, id)
	end
	table.sort(ids)
	return { state = "prepared", source = source, values = values, definitions = definitions, oldValues = oldValues, ids = ids }, nil
end

function Store:ReserveTransaction(participant: any): (boolean, StructuredError?)
	if type(participant) ~= "table" or participant.state ~= "prepared" then
		return false, failure("invalid_transaction", "Transaction must be prepared before reservation")
	end
	participant.state = "reserved"
	return true, nil
end

function Store:StageTransaction(participant: any): (boolean, StructuredError?)
	if type(participant) ~= "table" or participant.state ~= "reserved" then
		return false, failure("invalid_transaction", "Transaction must be reserved before staging")
	end
	participant.state = "staged"
	return true, nil
end

function Store:CommitTransaction(participant: any, options: any?): (boolean, StructuredError?)
	if type(participant) ~= "table" or participant.state ~= "staged" then
		return false, failure("invalid_transaction", "Transaction must be staged before commit")
	end
	if self._destroyed then return false, failure("destroyed", "Store has been destroyed") end
	for _, id in ipairs(participant.ids or {}) do
		if self._signals[id] == nil or self._definitions[id] == nil then
			return false, failure("stale_transaction", "A transaction definition was removed before commit")
		end
		local ok, prepared = self:_prepare(id, participant.values[id])
		if not ok then return false, prepared end
		participant.values[id] = prepared
		participant.definitions[id] = self._definitions[id]
	end
	local notifications = {}
	for _, id in ipairs(participant.ids or {}) do
		local value, oldValue = participant.values[id], self._values[id]
		participant.oldValues[id] = shallowCopy(oldValue)
		self._values[id] = shallowCopy(value)
		if not valuesEqual(oldValue, value) then
			table.insert(notifications, {
				id = id,
				value = value,
				oldValue = oldValue,
				signal = self._signals[id],
				onChange = participant.definitions[id].onChange,
				source = participant.source,
			})
		end
	end
	participant.state, participant.notifications = "committed", notifications
	if type(options) == "table" and options.deferNotifications == true then return true, nil end
	return self:PublishTransaction(participant)
end

function Store:PublishTransaction(participant: any): (boolean, StructuredError?)
	if type(participant) ~= "table" or participant.state ~= "committed" then
		return false, failure("invalid_transaction", "Only a committed transaction can publish notifications")
	end
	local function publish()
		if participant.state ~= "committed" then return end
		local notifications = participant.notifications or {}
		participant.notifications = nil
		participant.state = "published"
		self:_publishNotifications(notifications)
	end
	if self._dispatchDepth > 0 then
		table.insert(self._mutationQueue, publish)
	else
		publish()
	end
	return true, nil
end

function Store:AbortTransaction(participant: any): boolean
	if type(participant) ~= "table" or participant.state == "published" or participant.state == "aborted" then
		return false
	end
	if participant.state == "committed" then
		for _, id in ipairs(participant.ids or {}) do
			if self._definitions[id] ~= participant.definitions[id] or not valuesEqual(self._values[id], participant.values[id]) then
				return false
			end
		end
		for _, id in ipairs(participant.ids or {}) do
			self._values[id] = shallowCopy(participant.oldValues[id])
		end
	end
	participant.state = "aborted"
	participant.notifications = nil
	table.clear(participant.values)
	table.clear(participant.definitions)
	table.clear(participant.oldValues)
	table.clear(participant.ids)
	return true
end

function Store:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	for _, signal in pairs(self._signals) do
		signal:Destroy()
	end
	self.Changed:Destroy()
	self.Unregistered:Destroy()
	self.Diagnostic:Destroy()
	table.clear(self._signals)
	table.clear(self._values)
	table.clear(self._definitions)
	table.clear(self._pendingRestores)
	table.clear(self._mutationQueue)
	self._pendingRestoreBytes = 0
end

return Store

end

__modules["core/StructuredError"] = function()
--!strict

export type Context = {
	domain: string?,
	operation: string?,
	transactionId: string?,
	ownerId: string?,
	path: string?,
	retryable: boolean?,
	details: any?,
}

export type StructuredError = {
	code: string,
	message: string,
	domain: string?,
	operation: string?,
	transactionId: string?,
	ownerId: string?,
	path: string?,
	retryable: boolean?,
	details: any?,
}

local StructuredError = {}

local MAX_CODE_BYTES = 128
local MAX_MESSAGE_BYTES = 1_024
local MAX_IDENTIFIER_BYTES = 129
local MAX_PATH_BYTES = 512
local MAX_DETAILS_DEPTH = 8
local MAX_DETAILS_NODES = 128
local MAX_DETAILS_ENTRIES = 64
local MAX_DETAILS_STRING_BYTES = 8_192
local MAX_DETAILS_VALUE_BYTES = 512

local SENSITIVE_KEY = {
	authorization = true,
	cookie = true,
	credential = true,
	password = true,
	secret = true,
	session = true,
	token = true,
}

local function finiteNumber(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

local function boundedString(value: any, fallback: string, maximumLength: number): string
	if type(value) ~= "string" or #value == 0 then
		return fallback
	end
	return string.sub(value, 1, maximumLength)
end

local function identifier(value: any): string?
	if type(value) ~= "string" or #value == 0 or #value > MAX_IDENTIFIER_BYTES then
		return nil
	end
	if string.match(value, "^[A-Za-z][A-Za-z0-9._:-]*$") == nil then
		return nil
	end
	return value
end

local function redactedKey(key: string): boolean
	local lowered = string.lower(key)
	for fragment in pairs(SENSITIVE_KEY) do
		if string.find(lowered, fragment, 1, true) ~= nil then
			return true
		end
	end
	return false
end

type CopyState = {
	nodes: number,
	entries: number,
	stringBytes: number,
	seen: { [table]: boolean },
}

local function sanitize(value: any, state: CopyState, depth: number, redact: boolean): any
	local valueType = type(value)
	if valueType == "nil" or valueType == "boolean" then
		return value
	end
	if valueType == "number" then
		return if finiteNumber(value) then value else "<nonfinite-number>"
	end
	if valueType == "string" then
		local remaining = math.max(MAX_DETAILS_STRING_BYTES - state.stringBytes, 0)
		local maximum = math.min(MAX_DETAILS_VALUE_BYTES, remaining)
		state.stringBytes += math.min(#value, maximum)
		return string.sub(value, 1, maximum)
	end
	if valueType ~= "table" then
		return "<unsupported:" .. valueType .. ">"
	end
	if getmetatable(value) ~= nil then
		return "<table-with-metatable>"
	end
	if depth >= MAX_DETAILS_DEPTH then
		return "<depth-limit>"
	end
	if state.nodes >= MAX_DETAILS_NODES then
		return "<node-limit>"
	end
	if state.seen[value] then
		return "<cycle>"
	end

	state.nodes += 1
	state.seen[value] = true
	-- Refuse oversized maps before descending so diagnostics cannot turn a hostile
	-- payload into an unbounded copy or iteration.
	local numericKeys = {}
	local stringKeys = {}
	local tableEntries = 0
	for key in pairs(value) do
		if type(key) == "number" and finiteNumber(key) then
			table.insert(numericKeys, key)
		elseif type(key) == "string" and #key <= 128 then
			table.insert(stringKeys, key)
		else
			state.seen[value] = nil
			return "<unsupported-key>"
		end
		tableEntries += 1
		if tableEntries > MAX_DETAILS_ENTRIES or state.entries + tableEntries > MAX_DETAILS_ENTRIES then
			state.seen[value] = nil
			return "<entry-limit>"
		end
	end
	table.sort(numericKeys)
	table.sort(stringKeys)

	local result = {}
	local function append(key: string | number)
		if state.entries >= MAX_DETAILS_ENTRIES then
			return
		end
		state.entries += 1
		if redact and type(key) == "string" and redactedKey(key) then
			result[key] = "<redacted>"
		else
			result[key] = sanitize(value[key], state, depth + 1, redact)
		end
	end

	for _, key in ipairs(numericKeys) do
		append(key)
	end
	for _, key in ipairs(stringKeys) do
		append(key)
	end
	state.seen[value] = nil
	return table.freeze(result)
end

function StructuredError.sanitize(value: any): any
	return sanitize(value, {
		nodes = 0,
		entries = 0,
		stringBytes = 0,
		seen = {},
	}, 0, true)
end

function StructuredError.new(input: any): StructuredError
	local source = if type(input) == "table" then input else {}
	local result: { [string]: any } = {
		code = boundedString(rawget(source, "code"), "invalid_error", MAX_CODE_BYTES),
		message = boundedString(rawget(source, "message"), "An unspecified error occurred", MAX_MESSAGE_BYTES),
	}
	local domain = identifier(rawget(source, "domain"))
	local operation = identifier(rawget(source, "operation"))
	local transactionId = identifier(rawget(source, "transactionId"))
	local ownerId = identifier(rawget(source, "ownerId"))
	if domain ~= nil then result.domain = domain end
	if operation ~= nil then result.operation = operation end
	if transactionId ~= nil then result.transactionId = transactionId end
	if ownerId ~= nil then result.ownerId = ownerId end
	local path = rawget(source, "path")
	if type(path) == "string" and #path > 0 then
		result.path = string.sub(path, 1, MAX_PATH_BYTES)
	end
	local retryable = rawget(source, "retryable")
	if type(retryable) == "boolean" then
		result.retryable = retryable
	end
	local details = rawget(source, "details")
	if details ~= nil then
		result.details = StructuredError.sanitize(details)
	end
	return table.freeze(result) :: any
end

function StructuredError.from(code: any, message: any, context: Context?): StructuredError
	local input = if type(context) == "table" then context else {}
	return StructuredError.new({
		code = code,
		message = message,
		domain = rawget(input, "domain"),
		operation = rawget(input, "operation"),
		transactionId = rawget(input, "transactionId"),
		ownerId = rawget(input, "ownerId"),
		path = rawget(input, "path"),
		retryable = rawget(input, "retryable"),
		details = rawget(input, "details"),
	})
end

function StructuredError.is(value: any): boolean
	if type(value) ~= "table" then return false end
	local code, message = rawget(value, "code"), rawget(value, "message")
	return type(code) == "string" and #code > 0
		and type(message) == "string" and #message > 0
end

function StructuredError.copy(value: any): StructuredError
	if not StructuredError.is(value) then
		return StructuredError.new({
			code = "invalid_error",
			message = "Value is not a structured error",
		})
	end
	return StructuredError.new(value)
end

return StructuredError

end

