local function invalid(message: string): (boolean, StructuredError)
	return false, { code = "invalid_theme", message = message }
end
local function isFiniteNumber(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

local function isFont(value: any): boolean
	return typeof(value) == "EnumItem" and value.EnumType == Enum.Font
end

local function isFontFace(value: any): boolean
	return typeof(value) == "Font"
end

Theme.fonts = {} :: { [string]: Enum.Font }
for _, name in ipairs(Fonts.List()) do
	local legacy = Fonts.Legacy(name)
	if legacy ~= nil then
		Theme.fonts[name] = legacy
	end
end
local function validateGroup(group: string, value: any): (boolean, StructuredError?)
	if type(value) ~= "table" then
		return invalid(group .. " must be a table")
	end
	local reference = if group == "spacingBase"
		then dark.spacing
		elseif group == "metricsBase" then dark.metrics
		else (dark :: any)[group]
	for token, tokenValue in pairs(value) do
		if reference[token] == nil then
			return invalid("Unknown " .. group .. " token: " .. tostring(token))
		end
		if group == "colors" then
			if typeof(tokenValue) ~= "Color3" then
				return invalid("colors." .. token .. " must be a Color3")
			end
		elseif group == "states" then
			if type(tokenValue) ~= "table" then
				return invalid("states." .. token .. " must be a table")
			end
			for stateToken, stateValue in pairs(tokenValue) do
				if reference[token][stateToken] == nil then
					return invalid("Unknown states." .. token .. " token: " .. tostring(stateToken))
				end
				if typeof(stateValue) ~= "Color3" then
					return invalid("states." .. token .. "." .. stateToken .. " must be a Color3")
				end
			end
		elseif group == "effects" then
			if token == "shadowColor" or token == "glowColor" then
				if typeof(tokenValue) ~= "Color3" then
					return invalid("effects." .. token .. " must be a Color3")
				end
			elseif token == "glowStyle" then
				if tokenValue ~= "soft" and tokenValue ~= "edge" then
					return invalid("effects.glowStyle must be soft or edge")
				end
			elseif token == "shadowOffset" then
				if typeof(tokenValue) ~= "Vector2"
					or not isFiniteNumber(tokenValue.X) or not isFiniteNumber(tokenValue.Y)
				then
					return invalid("effects.shadowOffset must be a finite Vector2")
				end
			elseif token == "shadowSpread" then
				if not isFiniteNumber(tokenValue) or tokenValue < 0 or tokenValue > 32 then
					return invalid("effects.shadowSpread must be between 0 and 32")
				end
			elseif token == "glowSpread" then
				if not isFiniteNumber(tokenValue) or tokenValue < 0 or tokenValue > 24 then
					return invalid("effects.glowSpread must be between 0 and 24")
				end
			elseif token == "glowThickness" then
				if not isFiniteNumber(tokenValue) or tokenValue < 1 or tokenValue > 4 or tokenValue % 1 ~= 0 then
					return invalid("effects.glowThickness must be an integer between 1 and 4")
				end
			elseif token == "glowEdgeLength" then
				if not isFiniteNumber(tokenValue) or tokenValue < 0.2 or tokenValue > 0.9 then
					return invalid("effects.glowEdgeLength must be between 0.2 and 0.9")
				end
			elseif not isFiniteNumber(tokenValue) or tokenValue < 0 or tokenValue > 1 then
				return invalid("effects." .. token .. " must be between 0 and 1")
			end
		else
			if not isFiniteNumber(tokenValue) then
				return invalid(group .. "." .. token .. " must be a finite number")
			end
			if (group == "metrics" or group == "metricsBase") and token == "tabTransitionDistance" then
				if tokenValue < 0 or tokenValue > 32 then
					return invalid(group .. ".tabTransitionDistance must be between 0 and 32")
				end
			elseif tokenValue < 0 or (group == "typography" and tokenValue == 0) then
				return invalid(group .. "." .. token .. " is outside its supported range")
			end
		end
	end
	return true, nil
end
local shadowOptionKeys = {
	Amount = "shadow",
	amount = "shadow",
	Shadow = "shadow",
	shadow = "shadow",
	Color = "shadowColor",
	color = "shadowColor",
	ShadowColor = "shadowColor",
	shadowColor = "shadowColor",
