	AccentGlow = "accentGlow",
	accentGlow = "accentGlow",
}

function Theme.withShadow(effects: any, options: any): (any?, StructuredError?)
	local configured = if type(options) == "number" then { shadow = options } else options
	if type(configured) ~= "table" then
		return nil, { code = "invalid_shadow_options", message = "Shadow must be a number or options table" }
	end
	local nextEffects = Util.deepCopy(effects)
	for key, value in pairs(configured) do
		local token = shadowOptionKeys[key]
		if token == nil then
			return nil, { code = "invalid_shadow_options", message = "Unknown shadow option: " .. tostring(key) }
		end
		if token == "shadowColor" then
			if typeof(value) ~= "Color3" then
				return nil, { code = "invalid_shadow", message = tostring(key) .. " must be a Color3" }
			end
		elseif token == "shadowOffset" then
			if typeof(value) ~= "Vector2" or not isFiniteNumber(value.X) or not isFiniteNumber(value.Y) then
				return nil, { code = "invalid_shadow", message = tostring(key) .. " must be a finite Vector2" }
			end
		elseif not isFiniteNumber(value) then
			return nil, { code = "invalid_shadow", message = tostring(key) .. " must be a finite number" }
		elseif token == "shadowSpread" and (value < 0 or value > 32) then
			return nil, { code = "invalid_shadow", message = tostring(key) .. " must be between 0 and 32" }
		elseif token ~= "shadowSpread" and (value < 0 or value > 1) then
			return nil, { code = "invalid_shadow", message = tostring(key) .. " must be between 0 and 1" }
		end
		nextEffects[token] = value
	end
	return nextEffects, nil
end

local glowOptionKeys = {
	Amount = "glow",
	amount = "glow",
	Glow = "glow",
