function Theme.withGlow(effects: any, options: any): (any?, StructuredError?)
	local configured = if type(options) == "number" then { glow = options } else options
	if type(configured) ~= "table" then
		return nil, { code = "invalid_glow_options", message = "Glow must be a number or options table" }
	end
	local nextEffects = Util.deepCopy(effects)
	for key, value in pairs(configured) do
		local token = glowOptionKeys[key]
		if token == nil then
			return nil, { code = "invalid_glow_options", message = "Unknown glow option: " .. tostring(key) }
		end
		if token == "glowColor" then
			if typeof(value) ~= "Color3" then
				return nil, { code = "invalid_glow", message = tostring(key) .. " must be a Color3" }
			end
		elseif token == "glowStyle" then
			if value ~= "soft" and value ~= "edge" then
				return nil, { code = "invalid_glow", message = tostring(key) .. " must be soft or edge" }
			end
		elseif not isFiniteNumber(value) then
			return nil, { code = "invalid_glow", message = tostring(key) .. " must be a finite number" }
		elseif token == "glowSpread" and (value < 0 or value > 24) then
			return nil, { code = "invalid_glow", message = tostring(key) .. " must be between 0 and 24" }
		elseif token == "glowEdgeLength" and (value < 0.2 or value > 0.9) then
			return nil, { code = "invalid_glow", message = tostring(key) .. " must be between 0.2 and 0.9" }
		elseif token == "glowThickness" and (value < 1 or value > 4 or value % 1 ~= 0) then
			return nil, { code = "invalid_glow", message = tostring(key) .. " must be an integer between 1 and 4" }
		elseif (token == "glow" or token == "glowSoftness") and (value < 0 or value > 1) then
			return nil, { code = "invalid_glow", message = tostring(key) .. " must be between 0 and 1" }
		end
		nextEffects[token] = value
	end
	return nextEffects, nil
end


function Theme.validate(overrides: any, fontRegistry: any?): (boolean, StructuredError?)
	if overrides == nil then
		return true, nil
	end
	if type(overrides) ~= "table" then
		return invalid("Theme overrides must be a table")
	end
	for key, value in pairs(overrides) do
		if key == "variant" then
			if value ~= "dark" and value ~= "light" then
				return invalid("variant must be dark or light")
			end
		elseif key == "density" then
			if not isFiniteNumber(value) or value < 0.75 or value > 1.5 then
				return invalid("density must be between 0.75 and 1.5")
			end
		elseif key == "textScale" then
			if not isFiniteNumber(value) or value < 0.75 or value > 2 then
				return invalid("textScale must be between 0.75 and 2")
			end
		elseif key == "reducedMotion" then
			if type(value) ~= "boolean" then
				return invalid("reducedMotion must be a boolean")
			end
		elseif key == "font" then
			local registry = if type(fontRegistry) == "table" then fontRegistry else Fonts
			if not isFont(value) and (type(value) ~= "string" or type(registry.Has) ~= "function" or not registry:Has(value)) then
				return invalid("font must be an Enum.Font or registered font name")
			end
		elseif key == "fontFace" then
			local registry = if type(fontRegistry) == "table" then fontRegistry else Fonts
			if not isFontFace(value) and (type(value) ~= "string" or type(registry.Has) ~= "function" or not registry:Has(value)) then
				return invalid("fontFace must be a Font or registered font name")
			end
		elseif key == "opacity" then
			if not isFiniteNumber(value) or value < 0 or value > 1 then
				return invalid("opacity must be between 0 and 1")
			end
		elseif key == "rowLines" or key == "checkboxStyle" then
			if type(value) ~= "boolean" then
				return invalid(key .. " must be a boolean")
			end
		elseif key == "layout" then
			if value ~= "side" and value ~= "top" then
				return invalid("layout must be side or top")
			end
		elseif key == "sectionStyle" then
			if value ~= "flat" and value ~= "surface" then
				return invalid("sectionStyle must be flat or surface")
			end
		elseif key == "accentA" or key == "accentB" then
			if typeof(value) ~= "Color3" then
				return invalid(key .. " must be a Color3")
			end
		elseif knownGroups[key] then
			local valid, groupError = validateGroup(key, value)
			if not valid then
				return false, groupError
			end
		else
			return invalid("Unknown theme token group: " .. tostring(key))
		end
	end
	return true, nil
end

export type ThemeProvenance = { [string]: "explicit" | "default" | "derived" }
export type ContrastRow = { role: string, foreground: Color3, background: Color3, ratio: number, required: number, pass: boolean }
export type ThemeDetail = {
	theme: ThemeData,
	provenance: ThemeProvenance,
	contrast: { pass: boolean, rows: { ContrastRow } },
}

local function freezeDeep(value: any): any
	if type(value) ~= "table" then
		return value
	end
	local copy = {}
	for key, child in pairs(value) do
		copy[key] = freezeDeep(child)
	end
	return table.freeze(copy)
end

local function channel(value: number): number
	return if value <= 0.04045 then value / 12.92 else ((value + 0.055) / 1.055) ^ 2.4
end

local function contrastRatio(first: Color3, second: Color3): number
	local firstLum = 0.2126 * channel(first.R) + 0.7152 * channel(first.G) + 0.0722 * channel(first.B)
	local secondLum = 0.2126 * channel(second.R) + 0.7152 * channel(second.G) + 0.0722 * channel(second.B)
	if firstLum < secondLum then
		firstLum, secondLum = secondLum, firstLum
	end
	return (firstLum + 0.05) / (secondLum + 0.05)
end

local function blend(from: Color3, to: Color3, amount: number): Color3
	return from:Lerp(to, math.clamp(amount, 0, 1))
end

local function deriveColor(surface: Color3, content: Color3, amount: number): Color3
	return blend(surface, content, amount)
end

local function provenanceFor(overrides: any, group: string, token: string): "explicit" | "default"
	return if type(overrides) == "table" and type(overrides[group]) == "table" and overrides[group][token] ~= nil
		then "explicit"
		else "default"
end

local function applySemanticDerivations(resolved: ThemeData, overrides: any, provenance: ThemeProvenance)
	local colors = resolved.colors
	local explicitColors = if type(overrides) == "table" and type(overrides.colors) == "table" then overrides.colors else {}
	local darkSurface = contrastRatio(colors.surface, Color3.new(1, 1, 1)) > contrastRatio(colors.surface, Color3.new(0, 0, 0))
	local toward = colors.text
	local function derive(name: string, value: Color3)
		if explicitColors[name] == nil then
			colors[name] = value
			provenance["colors." .. name] = "derived"
		end
	end
	derive("border", deriveColor(colors.surface, toward, if darkSurface then 0.08 else 0.145))
	derive("borderStrong", deriveColor(colors.surface, toward, 0.42))
	derive("focus", deriveColor(colors.background, resolved.accentA, 0.88))
	derive("textDisabled", deriveColor(colors.background, colors.textMuted, 0.58))
	local explicitStates = if type(overrides) == "table" and type(overrides.states) == "table" then overrides.states else {}
	local function deriveState(state: string, role: string, value: Color3)
		local stateOverrides = explicitStates[state]
		if type(stateOverrides) ~= "table" or stateOverrides[role] == nil then
			resolved.states[state][role] = value
			provenance["states." .. state .. "." .. role] = "derived"
		end
	end
	deriveState("hover", "background", deriveColor(resolved.states.default.background, colors.text, if darkSurface then 0.10 else 0.06))
	deriveState("hover", "border", colors.borderStrong)
	deriveState("disabled", "background", deriveColor(colors.background, colors.surface, 0.45))
	deriveState("disabled", "text", colors.textDisabled)
	deriveState("disabled", "border", colors.border)
end

local function contrastMetadata(theme: ThemeData): { pass: boolean, rows: { ContrastRow } }
	local colors, states = theme.colors, theme.states
	local rows = {
		{ role = "text/background", foreground = colors.text, background = colors.background, required = 4.5 },
		{ role = "text/surface", foreground = colors.text, background = colors.surface, required = 4.5 },
		{ role = "textMuted/background", foreground = colors.textMuted, background = colors.background, required = 4.5 },
		{ role = "textMuted/surface", foreground = colors.textMuted, background = colors.surface, required = 4.5 },
		{ role = "textMuted/default.background", foreground = colors.textMuted, background = states.default.background, required = 4.5 },
		{ role = "default.text/default.background", foreground = states.default.text, background = states.default.background, required = 4.5 },
		{ role = "hover.text/hover.background", foreground = states.hover.text, background = states.hover.background, required = 4.5 },
		{ role = "pressed.text/pressed.background", foreground = states.pressed.text, background = states.pressed.background, required = 4.5 },
		{ role = "selected.text/selected.background", foreground = states.selected.text, background = states.selected.background, required = 4.5 },
		{ role = "danger.text/danger.background", foreground = states.danger.text, background = states.danger.background, required = 4.5 },
		{ role = "info.text/info.background", foreground = states.info.text, background = states.info.background, required = 4.5 },
		{ role = "warning.text/warning.background", foreground = states.warning.text, background = states.warning.background, required = 4.5 },
		{ role = "success.text/success.background", foreground = states.success.text, background = states.success.background, required = 4.5 },
		{ role = "info/surface", foreground = colors.info, background = colors.surface, required = 4.5 },
		{ role = "warning/surface", foreground = colors.warning, background = colors.surface, required = 4.5 },
		{ role = "success/surface", foreground = colors.success, background = colors.surface, required = 4.5 },
		{ role = "danger/surface", foreground = colors.danger, background = colors.surface, required = 4.5 },
		{ role = "focus/background", foreground = colors.focus, background = colors.background, required = 3 },
		{ role = "focus/surface", foreground = colors.focus, background = colors.surface, required = 3 },
	}
	local passes = true
	for _, row in ipairs(rows) do
		row.ratio = contrastRatio(row.foreground, row.background)
		row.pass = row.ratio >= row.required
		passes = passes and row.pass
	end
	return { pass = passes, rows = rows :: any }
end

function Theme.resolveDetailed(overrides: any, fontRegistry: any?): (ThemeDetail?, StructuredError?)
	local ok, errorValue = Theme.validate(overrides, fontRegistry)
	if not ok then
		return nil, errorValue
	end
	local normalized = Util.deepCopy(overrides or {})
	local registry = if type(fontRegistry) == "table" then fontRegistry else Fonts
	if type(normalized.font) == "string" then
		local face, faceError = Theme.resolveFontFace(normalized.font, registry)
		if face == nil then return nil, faceError end
		local legacy = Theme.resolveFont(normalized.font, registry)
		normalized.font = legacy
		if normalized.fontFace == nil then normalized.fontFace = face end
	end
	if type(normalized.fontFace) == "string" then
		local face, faceError = Theme.resolveFontFace(normalized.fontFace, registry)
		if face == nil then return nil, faceError end
		normalized.fontFace = face
	end
	local selected = if normalized.variant == "light" then light else dark
	local resolved = Util.deepMerge(selected, normalized) :: ThemeData
	local baseSpacing = Util.deepMerge(selected.spacingBase, normalized.spacingBase or normalized.spacing or {})
	resolved.spacingBase = baseSpacing
	for key, value in pairs(baseSpacing) do resolved.spacing[key] = math.max(0, math.floor(value * resolved.density + 0.5)) end
	local baseMetrics = Util.deepMerge(selected.metrics, normalized.metricsBase or normalized.metrics or {})
	resolved.metricsBase = baseMetrics
	for key, value in pairs(baseMetrics) do resolved.metrics[key] = math.max(0, math.floor(value * resolved.density + 0.5)) end
	resolved.metrics.hitTargetMin = math.max(28, resolved.metrics.hitTargetMin)
	for _, key in ipairs({ "tabHeight", "sectionHeader", "controlHeight", "compactControlHeight", "inputHeight" }) do
		resolved.metrics[key] = math.max(44, resolved.metrics[key])
	end
	resolved.metrics.compactBarHeight = math.max(44, resolved.metrics.compactBarHeight)
	resolved.metrics.searchHeight = math.max(34, resolved.metrics.searchHeight)
	local provenance: ThemeProvenance = {}
	for key in pairs(selected) do
		if type(selected[key]) ~= "table" then
			provenance[key] = if normalized[key] ~= nil then "explicit" else "default"
		end
	end
	for group in pairs(knownGroups) do
		local source = (selected :: any)[group]
		if type(source) == "table" then
			for token, tokenValue in pairs(source) do
				if type(tokenValue) == "table" then
					for nested in pairs(tokenValue) do
						local supplied = type(normalized[group]) == "table"
							and type(normalized[group][token]) == "table"
							and normalized[group][token][nested] ~= nil
						provenance[group .. "." .. token .. "." .. nested] = if supplied then "explicit" else "default"
					end
				else
					provenance[group .. "." .. token] = provenanceFor(normalized, group, token)
				end
			end
		end
	end
	applySemanticDerivations(resolved, normalized, provenance)
	local contrast = contrastMetadata(resolved)
	if not contrast.pass then
		local failed: any = nil
		for _, row in ipairs(contrast.rows) do if not row.pass then failed = row; break end end
		return nil, {
			code = "insufficient_contrast",
			message = "Theme contrast failed for " .. tostring(failed and failed.role or "semantic role"),
			details = failed,
		}
	end
	local detail: ThemeDetail = {
		theme = resolved,
		provenance = provenance,
		contrast = contrast,
	}
	return freezeDeep(detail), nil
end

function Theme.resolve(overrides: any, fontRegistry: any?): (ThemeData?, StructuredError?)
	local detail, resolveError = Theme.resolveDetailed(overrides, fontRegistry)
	if detail == nil then return nil, resolveError end
	return Util.deepCopy(detail.theme), nil
end

function Theme.resolveFont(value: any, fontRegistry: any?): (Enum.Font?, StructuredError?)
	if isFont(value) then
		return value, nil
	end
	local registry = if type(fontRegistry) == "table" then fontRegistry else Fonts
	if type(registry.Legacy) == "function" then
		local legacy = registry:Legacy(value)
		if legacy ~= nil then return legacy, nil end
	end
	return nil, {
		code = "unknown_font",
		message = "Unknown legacy font: " .. tostring(value),
	}
end

function Theme.resolveFontFace(value: any, fontRegistry: any?): (Font?, StructuredError?)
	local registry = if type(fontRegistry) == "table" then fontRegistry else Fonts
	if type(registry.Resolve) ~= "function" then
		return nil, { code = "font_registry_unavailable", message = "Theme font registry cannot resolve fonts" }
	end
	return registry:Resolve(value)
end

function Theme.metric(theme: any, name: string): number
	assert(type(theme) == "table" and type(theme.metrics) == "table", "Theme.metric requires a resolved theme")
	local value = theme.metrics[name]
	assert(type(value) == "number", "Unknown theme metric: " .. tostring(name))
	return value
end

function Theme.metrics(theme: any): { [string]: number }
	assert(type(theme) == "table" and type(theme.metrics) == "table", "Theme.metrics requires a resolved theme")
	return Util.deepCopy(theme.metrics)
end

local function preset(accentA: Color3, accentB: Color3): ThemeData
	return Util.deepMerge(dark, {
		accentA = accentA,
		accentB = accentB,
		colors = {
			focus = accentA,
		},
		states = {
			selected = {
				border = accentB,
			},
		},
	}) :: ThemeData
end

