local function tokenAt(theme: any, path: string): any
	local value = theme
	for _, segment in ipairs(string.split(path, ".")) do
		if type(value) ~= "table" then return nil end
		value = value[segment]
	end
	return value
end

local function transitionable(path: string, value: any): boolean
	if typeof(value) == "Color3" then return true end
	return type(value) == "number" and (
		string.sub(path, 1, 7) == "spacing"
		or string.sub(path, 1, 7) == "metrics"
		or string.sub(path, 1, 6) == "radius"
		or string.sub(path, 1, 10) == "typography"
		or string.sub(path, 1, 7) == "effects"
		or path == "opacity" or path == "density" or path == "textScale"
	)
end

function Theme.compileTransitionPlan(options: any?, motion: any?): (any?, StructuredError?)
	if options ~= nil and type(options) ~= "table" then return nil, { code = "invalid_theme_transition", message = "Theme transition options must be a table" } end
	local input = options or {}
	local plan = {}
	for key in pairs(input) do
		if key ~= "Preset" and key ~= "Animate" and key ~= "Duration" and key ~= "EasingStyle" and key ~= "EasingDirection" then
			return nil, { code = "invalid_theme_transition", message = "Unknown theme transition option: " .. tostring(key) }
		end
	end
	if input.Animate ~= nil and type(input.Animate) ~= "boolean" then return nil, { code = "invalid_theme_transition", message = "Animate must be a boolean" } end
	if input.Preset ~= nil then
		if type(input.Preset) ~= "string" or input.Preset == "" then
			return nil, { code = "invalid_theme_transition", message = "Preset must be a non-empty motion preset name" }
		end
		if motion ~= nil and motion:GetMotionPreset(input.Preset) == nil then
			return nil, { code = "invalid_theme_transition", message = "Unknown motion preset: " .. input.Preset }
		end
	end
	if input.Duration ~= nil and (not isFiniteNumber(input.Duration) or input.Duration < 0 or input.Duration > 1) then
		return nil, { code = "invalid_theme_transition", message = "Duration must be a finite number between zero and one second" }
	end
	for _, key in ipairs({ "EasingStyle", "EasingDirection" }) do
		local value = input[key]
		if value ~= nil then
			local enumType = if key == "EasingStyle" then Enum.EasingStyle else Enum.EasingDirection
			local valid = typeof(value) == "EnumItem" and value.EnumType == enumType
			if type(value) == "string" then
				local found, item = pcall(function() return enumType[value] end)
				valid = found and item ~= nil
			end
			if not valid then
				return nil, { code = "invalid_theme_transition", message = key .. " must name a valid " .. key }
			end
		end
	end
	for _, key in ipairs({ "Preset", "Duration", "EasingStyle", "EasingDirection" }) do
		if input[key] ~= nil then plan[key] = input[key] end
	end
	if input.Animate == false then plan.Duration = 0; plan.Animate = false end
	return table.freeze(plan), nil
end

local ThemeTransition = {}
ThemeTransition.__index = ThemeTransition

function ThemeTransition:Register(binding: any)
	assert(type(binding) == "table" and typeof(binding.instance) == "Instance", "Theme transition bindings require an instance")
	assert(type(binding.tokens) == "table", "Theme transition bindings require a property-to-token map")
	assert(not self._destroyed, "Cannot register bindings after theme transitions are destroyed")
	table.insert(self._bindings, binding)
	return binding
end

function ThemeTransition:Unregister(binding: any)
	for index, candidate in ipairs(self._bindings) do
		if candidate == binding then
			table.remove(self._bindings, index)
			local handle = self._handles[binding]
			self._handles[binding] = nil
			if handle ~= nil then handle:Cancel("unregistered") end
			return
		end
	end
end

function ThemeTransition:Transition(target: any, options: any?): any
	if self._destroyed then return { generation = self._generation, completed = true } end
	local detail: ThemeDetail?
	if type(target) == "table" and type(target.theme) == "table" and type(target.provenance) == "table" then
		detail = target
	else
		local resolved, resolveError = Theme.resolveDetailed(target, self._owner.Fonts)
		assert(resolved ~= nil, resolveError and resolveError.message or "Invalid transition theme")
		detail = resolved
	end
	local actual = detail :: ThemeDetail
	self._generation += 1
	local generation = self._generation
	local previous = self._handles
	self._handles = {}
	for _, handle in pairs(previous) do handle:Cancel("retargeted") end
	if generation ~= self._generation or self._destroyed then
		return { generation = generation, completed = true }
	end
	local owner = self._owner
	local animate = type(options) ~= "table" or options.Animate ~= false
	local motionOptions: any = options
	if type(options) == "table" then
		motionOptions = {}
		for _, key in ipairs({ "Preset", "Duration", "EasingStyle", "EasingDirection" }) do
			if options[key] ~= nil then motionOptions[key] = options[key] end
		end
	end
	owner.Theme = actual.theme -- Canonical target; the presentation is intentionally owner-local.
	owner.PresentedTheme = actual.theme
	local entries = {}
	for _, binding in ipairs(self._bindings) do
		local instance = binding.instance
		local visible = binding.visible == nil or binding.visible(instance) ~= false
		if generation ~= self._generation or self._destroyed then
			return { generation = generation, completed = true }
		end
		if visible and instance.Parent ~= nil then
			local goals = {}
			for property, path in pairs(binding.tokens) do
				local targetValue = tokenAt(actual.theme, path)
				if transitionable(path, targetValue) then goals[property] = targetValue else instance[property] = targetValue end
				if generation ~= self._generation or self._destroyed then
					return { generation = generation, completed = true }
				end
			end
			if next(goals) ~= nil then table.insert(entries, { binding = binding, instance = instance, properties = goals, presetOrOptions = motionOptions }) end
		end
	end
	if not animate or #entries == 0 or actual.theme.reducedMotion or self._motion == nil then
		for _, entry in ipairs(entries) do
			for property, value in pairs(entry.properties) do
				entry.instance[property] = value
				if generation ~= self._generation or self._destroyed then
					return { generation = generation, completed = true }
				end
			end
		end
		return { generation = generation, completed = true }
	end
	local handles = {}
	for _, entry in ipairs(entries) do
		local handle = self._motion:Animate(entry.instance, entry.properties, entry.presetOrOptions or "standard")
		if generation ~= self._generation or self._destroyed then
			handle:Cancel("retargeted")
			return { generation = generation, completed = true, handles = handles }
		end
		self._handles[entry.binding] = handle
		table.insert(handles, handle)
	end
	local remaining = #handles
	local result = { generation = generation, completed = remaining == 0, handles = handles }
	for index, handle in ipairs(handles) do
		local binding = entries[index].binding
		handle:OnCompleted(function()
			if self._handles[binding] == handle then self._handles[binding] = nil end
			remaining -= 1
			if remaining == 0 then result.completed = true end
		end)
	end
	return result
end
ThemeTransition.Apply = ThemeTransition.Transition

function ThemeTransition:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	self._generation += 1
	table.clear(self._bindings)
	local handles = self._handles
	self._handles = {}
	for _, handle in pairs(handles) do handle:Cancel("destroyed") end
end

function Theme.newTransitionCoordinator(owner: any, motion: any)
	assert(type(owner) == "table", "Theme.newTransitionCoordinator requires an owner")
	return setmetatable({ _owner = owner, _motion = motion, _bindings = {}, _handles = {}, _generation = 0, _destroyed = false }, ThemeTransition)
end
Theme.CreateTransitionCoordinator = Theme.newTransitionCoordinator
Theme.createTransitionCoordinator = Theme.newTransitionCoordinator

Theme.presets = presets

function Theme.applyPreset(name: any, base: any?, fontRegistry: any?): (ThemeData?, StructuredError?)
	local selected = if type(name) == "string" then presets[name] else nil
	if selected == nil then
		return nil, {
			code = "unknown_preset",
			message = "Unknown theme preset: " .. tostring(name),
		}
	end
	local valid, baseError = Theme.validate(base, fontRegistry)
	if not valid then
		return nil, baseError
	end
	return Theme.resolve(Util.deepMerge(selected, base or {}), fontRegistry)
end

Theme.dark = Util.deepCopy(dark)
Theme.light = Util.deepCopy(light)
Theme.default = Util.deepCopy(dark)

return Theme

end

__modules["core/Util"] = function()
--!strict

export type StructuredError = { code: string, message: string }

local Util = {}

function Util.clamp(value: number, minimum: number, maximum: number): number
	assert(minimum <= maximum, "minimum must not exceed maximum")
	return math.max(minimum, math.min(maximum, value))
end

function Util.roundToStep(value: number, step: number, origin: number?): number
	assert(step > 0, "step must be greater than zero")
	local base = origin or 0
	return base + math.floor((value - base) / step + 0.5) * step
end

function Util.deepCopy<T>(value: T, seen: { [any]: any }?): T
	if type(value) ~= "table" then
		return value
	end
	local copied = seen or {}
	if copied[value] ~= nil then
		return copied[value]
	end
	local result = {}
	copied[value] = result
	for key, nestedValue in pairs(value :: any) do
		result[Util.deepCopy(key, copied)] = Util.deepCopy(nestedValue, copied)
	end
	return result :: any
end

function Util.deepMerge<T>(base: T, override: any): T
	local result = Util.deepCopy(base)
	if type(override) ~= "table" then
		return result
	end
	for key, overrideValue in pairs(override) do
		local baseValue = (result :: any)[key]
		if type(baseValue) == "table" and type(overrideValue) == "table" then
			(result :: any)[key] = Util.deepMerge(baseValue, overrideValue)
		else
			(result :: any)[key] = Util.deepCopy(overrideValue)
		end
	end
	return result
end

local function sanitize(value: any, fallback: string, maximumLength: number): string
	local text = tostring(value or "")
	text = string.lower(text)
	text = string.gsub(text, "[^%w_%-%.]+", "-")
	text = string.gsub(text, "%-+", "-")
	text = string.gsub(text, "^[%-%._]+", "")
	text = string.gsub(text, "[%-%._]+$", "")
	text = string.sub(text, 1, maximumLength)
	if text == "" then
		return fallback
	end
	return text
end

function Util.sanitizeId(value: any, fallback: string?): string
	return sanitize(value, fallback or "control", 80)
end

function Util.sanitizeProfileName(value: any, fallback: string?): string
	return sanitize(value, fallback or "default", 48)
end

function Util.create(className: string, properties: { [string]: any }?, parent: Instance?): Instance
	local instance = Instance.new(className)
	if properties ~= nil then
		Util.applyProperties(instance, properties)
	end
	if parent ~= nil then
		instance.Parent = parent
	end
	return instance
end

function Util.applyProperties(instance: Instance, properties: { [string]: any }): (boolean, StructuredError?)
	for property, value in pairs(properties) do
		local ok, err = pcall(function()
			(instance :: any)[property] = value
		end)
		if not ok then
			return false,
				{
					code = "invalid_property",
					message = string.format("Could not set %s on %s: %s", property, instance.ClassName, tostring(err)),
				}
		end
	end
	return true, nil
end

function Util.corner(parent: Instance, radius: UDim?): UICorner
	return Util.create("UICorner", {
		CornerRadius = radius or UDim.new(0, 6),
	}, parent) :: UICorner
end

function Util.stroke(parent: Instance, color: Color3?, thickness: number?, transparency: number?): UIStroke
	return Util.create("UIStroke", {
		Color = color or Color3.fromRGB(128, 128, 128),
		Thickness = thickness or 1,
		Transparency = transparency or 0,
	}, parent) :: UIStroke
end

function Util.padding(parent: Instance, paddingValue: UDim?): UIPadding
	local value = paddingValue or UDim.new(0, 8)
	return Util.create("UIPadding", {
		PaddingTop = value,
		PaddingRight = value,
		PaddingBottom = value,
		PaddingLeft = value,
	}, parent) :: UIPadding
end

function Util.arrayEquals<T>(left: { T }, right: { T }): boolean
	if #left ~= #right then
		return false
	end
	for index, value in ipairs(left) do
		if value ~= right[index] then
			return false
		end
	end
	return true
end

function Util.safeCallback(callback: ((...any) -> ())?, ...: any): (boolean, any?)
	if callback == nil then
		return true, nil
	end
	return xpcall(callback, debug.traceback, ...)
end

return Util

end

__modules["core/WorkspaceManager"] = function()
--!strict

local StructuredError = __require("core/StructuredError")
local LegacyWorkspaceAdapter = __require("adapters/LegacyWorkspaceAdapter")

local WorkspaceManager = {}
WorkspaceManager.__index = WorkspaceManager

local EMPTY_BASELINE_HASH = "empty"
local V3_FORMAT = "potassium-ui-workspace"
local V3_WIRE_VERSION = 3
local VISIBILITY = { shown = true, minimized = true, hidden = true }

local function failure(code: string, message: string, operation: string, details: any?): any
	return StructuredError.from(code, message, { domain = "workspace", operation = operation, details = details })
end

local function copy(value: any, depth: number?, seen: any?): any
	depth, seen = depth or 0, seen or {}
	local kind = type(value)
	if kind ~= "table" then
		if kind ~= "nil" and kind ~= "boolean" and kind ~= "number" and kind ~= "string" then error("workspace value type is invalid") end
		if kind == "number" and (value ~= value or value == math.huge or value == -math.huge) then error("workspace number must be finite") end
		return value
	end
	if getmetatable(value) ~= nil or depth >= 12 or seen[value] then error("invalid workspace structure") end
	seen[value] = true
	local result, count = {}, 0
	for key, item in pairs(value) do
		count += 1
		if count > 512 then error("workspace too large") end
		if type(key) ~= "string" and type(key) ~= "number" then error("invalid workspace key") end
		result[key] = copy(item, depth + 1, seen)
	end
	seen[value] = nil
	return result
end

local function freezeCopy(value: any): any
	local function freeze(item: any): any
		if type(item) ~= "table" then return item end
		for key, child in pairs(item) do item[key] = freeze(child) end
		return table.freeze(item)
	end
	return freeze(copy(value))
end

local function digest(value: any): string
	local function encode(item: any): string
		local kind = type(item)
		if kind ~= "table" then return kind .. ":" .. tostring(item) end
		local keys = {}
		for key in pairs(item) do table.insert(keys, key) end
		table.sort(keys, function(left, right)
			local leftKind, rightKind = type(left), type(right)
			if leftKind ~= rightKind then return leftKind < rightKind end
			return if leftKind == "number" then left < right else left < right
		end)
		local output = "{"
		for _, key in ipairs(keys) do output ..= encode(key) .. "=" .. encode(item[key]) .. ";" end
		return output .. "}"
	end
	local encoded = encode(value)
	local hash = 2166136261
	for index = 1, #encoded do
		hash = bit32.bxor(hash, string.byte(encoded, index))
		hash = (hash * 16777619) % 4294967296
	end
	return string.format("%08x", hash)
end

local function orderedWindows(windows: any): { any }
	if type(windows) ~= "table" then error("workspace payload.windows must be a table") end
	local result, keys = {}, {}
	for key in pairs(windows) do table.insert(keys, key) end
	table.sort(keys, function(left, right) return tostring(left) < tostring(right) end)
	for _, key in ipairs(keys) do table.insert(result, windows[key]) end
	return result
end

local function normalizeWindow(value: any, v2: boolean): any
	if type(value) ~= "table" then error("workspace window must be a table") end
	if type(value.id) ~= "string" or value.id == "" then error("workspace window id is required") end
	local hasOpen, hasVisibility = value.open ~= nil, value.visibility ~= nil
	if hasOpen and hasVisibility then error("workspace window cannot mix open and visibility") end
	local visibility: string
	if v2 then
		if hasVisibility then error("Workspace V2 cannot declare visibility") end
		if hasOpen and type(value.open) ~= "boolean" then error("workspace open must be boolean") end
		visibility = if value.open == false then "hidden" else "shown"
	else
		if hasOpen then error("Workspace V3 writes visibility, not open") end
		if type(value.visibility) ~= "string" or not VISIBILITY[value.visibility] then error("workspace visibility must be shown, minimized, or hidden") end
		visibility = value.visibility
	end
	local result = copy(value)
	result.open = nil
	result.visibility = visibility
	return result
end

local function normalize(document: any): (any?, any?)
	local ok, result = pcall(function()
		if type(document) ~= "table" or document.format ~= V3_FORMAT then error("workspace format is invalid") end
		if document.wireVersion ~= 2 and document.wireVersion ~= V3_WIRE_VERSION then error("workspace wireVersion must be 2 or 3") end
		if type(document.workspaceSchemaVersion) ~= "string" or type(document.payload) ~= "table" or type(document.unknownNamespaces) ~= "table" then error("workspace shape is invalid") end
		local isV2 = document.wireVersion == 2
		if isV2 and document.workspaceSchemaVersion ~= "2.0" then error("Workspace V2 schema version must be 2.0") end
		if not isV2 and document.workspaceSchemaVersion ~= "3" then error("Workspace V3 schema version must be 3") end
		local sourcePayload = copy(document.payload)
		local sourceUnknownNamespaces = copy(document.unknownNamespaces)
		if isV2 and document.contentHash ~= nil then
			local v2Hash = digest({ workspaceSchemaVersion = document.workspaceSchemaVersion, payload = sourcePayload, unknownNamespaces = sourceUnknownNamespaces })
			if document.contentHash ~= v2Hash then error("Workspace V2 contentHash does not match payload") end
		end
		local payload = sourcePayload
		local normalizedWindows = {}
		for _, window in ipairs(orderedWindows(payload.windows)) do
			local normalizedWindow = normalizeWindow(window, isV2)
			if normalizedWindows[normalizedWindow.id] ~= nil then error("workspace window ids must be unique") end
			normalizedWindows[normalizedWindow.id] = normalizedWindow
		end
		payload.windows = normalizedWindows
		local unknownNamespaces = copy(document.unknownNamespaces)
		local canonical = {
			format = V3_FORMAT,
			wireVersion = V3_WIRE_VERSION,
			workspaceSchemaVersion = if isV2 then "3" else document.workspaceSchemaVersion,
			payload = payload,
			unknownNamespaces = unknownNamespaces,
		}
		canonical.contentHash = digest({ workspaceSchemaVersion = canonical.workspaceSchemaVersion, payload = canonical.payload, unknownNamespaces = canonical.unknownNamespaces })
		if not isV2 and document.contentHash ~= nil and document.contentHash ~= canonical.contentHash then error("Workspace contentHash does not match normalized payload") end
		return freezeCopy(canonical)
	end)
	if not ok then return nil, failure("invalid_workspace", tostring(result), "normalize") end
	return result, nil
end

function WorkspaceManager.NormalizeDocument(document: any): (any?, any?)
	return normalize(document)
end

function WorkspaceManager.MigrateV2(document: any): (any?, any?)
	if type(document) ~= "table" or document.wireVersion ~= 2 then
		return nil, failure("invalid_workspace", "MigrateV2 requires a Workspace V2 document", "migrateV2")
	end
	return normalize(document)
end

function WorkspaceManager.NormalizeNamedWorkspace(namedWorkspace: any): (any?, any?)
	local v2, adapterError = LegacyWorkspaceAdapter.MigrateNamed(namedWorkspace)
	if not v2 then return nil, adapterError end
	return normalize(v2)
end

function WorkspaceManager.new(persistence: any, capability: any?): any
	return setmetatable({
		_persistence = persistence or {},
		_capability = capability,
		_workspace = nil,
		_lastHash = nil,
		_loadedHash = nil,
		_preLoadHash = nil,
		_transaction = 0,
		_compositionOrders = {},
		_compositionOrderProjector = nil,
		_destroyed = false,
	}, WorkspaceManager)
end
function WorkspaceManager:ApplyCompositionOrder(parentId: any, snapshot: any, projection: any): boolean
	if type(parentId) ~= "string" or type(snapshot) ~= "table" or type(projection) ~= "table" then return false end
	local ok, copied = pcall(copy, { snapshot = snapshot, projection = projection })
	if not ok then return false end
	self._compositionOrders[parentId] = copied
	return true
end

function WorkspaceManager:GetCompositionOrderSnapshot(): any
	return freezeCopy(self._compositionOrders)
end
function WorkspaceManager:ClearCompositionOrder(parentId: any): boolean
	if type(parentId) ~= "string" then return false end
	self._compositionOrders[parentId] = nil
	return true
end

function WorkspaceManager:SetCompositionOrderProjector(projector: any)
	self._compositionOrderProjector = projector
end

function WorkspaceManager:SetCompositionOrderSnapshot(snapshot: any): (boolean, any?)
	if type(snapshot) ~= "table" then return false, failure("invalid_composition_order", "Composition order snapshot must be a table", "setCompositionOrderSnapshot") end
	for parentId, order in pairs(snapshot) do
		if type(parentId) ~= "string" or type(order) ~= "table" or type(order.snapshot) ~= "table" or type(order.projection) ~= "table" then
			return false, failure("invalid_composition_order", "Composition orders require parent ids, snapshots, and projections", "setCompositionOrderSnapshot")
		end
	end
	local ok, copied = pcall(copy, snapshot)
	if not ok then return false, failure("invalid_composition_order", tostring(copied), "setCompositionOrderSnapshot") end
	self._compositionOrders = copied
	return true, nil
end

function WorkspaceManager:RestoreCompositionOrders(parentsToClear: any?): (boolean, any?)
	if type(self._compositionOrderProjector) ~= "function" then return true, nil end
	local failures = {}
	local function project(parentId: any, snapshot: any, projection: any, clearing: boolean)
		local ok, applied, applyError = pcall(self._compositionOrderProjector, parentId, snapshot, projection)
		if not ok or applied == false then
			table.insert(failures, {
				parentId = parentId,
				operation = if clearing then "clear" else "restore",
				error = tostring(if ok then applyError else applied),
			})
		end
	end
	if type(parentsToClear) == "table" then
		for parentId, selected in pairs(parentsToClear) do
			if selected and self._compositionOrders[parentId] == nil then project(parentId, nil, nil, true) end
		end
	end
	for parentId, order in pairs(self._compositionOrders) do
		project(parentId, order.snapshot, order.projection, false)
	end
	if #failures > 0 then
		return false, failure("workspace_order_apply_failed", "Could not restore composition order", "restoreCompositionOrders", { failures = failures })
	end
	return true, nil
end

function WorkspaceManager:GetSnapshot(): any
	return if self._workspace == nil then nil else freezeCopy(self._workspace)
end

function WorkspaceManager:_normalizeInput(document: any, named: boolean): (any?, any?)
	if named then return WorkspaceManager.NormalizeNamedWorkspace(document) end
	return normalize(document)
end

function WorkspaceManager:LoadDocument(document: any): (any?, any?)
	if self._destroyed then return nil, failure("destroyed", "WorkspaceManager is destroyed", "loadDocument") end
	local normalized, normalizeError = self:_normalizeInput(document, false)
	if not normalized then return nil, normalizeError end
	self._preLoadHash, self._loadedHash = self._loadedHash, normalized.contentHash
	return freezeCopy(normalized), nil
end

function WorkspaceManager:LoadNamedWorkspace(namedWorkspace: any): (any?, any?)
	if self._destroyed then return nil, failure("destroyed", "WorkspaceManager is destroyed", "loadNamedWorkspace") end
	local normalized, normalizeError = self:_normalizeInput(namedWorkspace, true)
	if not normalized then return nil, normalizeError end
	self._preLoadHash, self._loadedHash = self._loadedHash, normalized.contentHash
	return freezeCopy(normalized), nil
end

-- Old document input remains a read-compatible alias. Named V1 inputs must use LoadNamedWorkspace.
WorkspaceManager.Load = WorkspaceManager.LoadDocument
WorkspaceManager.LoadWorkspaceDocument = WorkspaceManager.LoadDocument
WorkspaceManager.LoadNamed = WorkspaceManager.LoadNamedWorkspace

function WorkspaceManager:_supports(name: string): boolean
	if self._capability and type(self._capability.Supports) == "function" then return self._capability:Supports(name) == true end
	return self._persistence[name] == true
end

function WorkspaceManager:SaveDocument(document: any, options: any?): (any?, any?)
	if self._destroyed then return nil, failure("destroyed", "WorkspaceManager is destroyed", "saveDocument") end
	local normalized, normalizeError = normalize(document)
	if not normalized then return nil, normalizeError end
	local durable = type(options) == "table" and options.durablyAtomic == true
	local atomic, journal = self:_supports("atomicReplace"), self:_supports("journal")
	if durable and not atomic and not journal then return nil, failure("durable_storage_unsupported", "Atomic durability requires atomicReplace or journal capability", "saveDocument") end
	if not (durable and atomic) and type(self._persistence.write) ~= "function" then return nil, failure("storage_unavailable", "Persistence write transport is unavailable", "saveDocument") end
	self._transaction += 1
	local transactionId = "workspace-" .. tostring(self._transaction)
	local previousHash, targetHash = self._lastHash or self._loadedHash or EMPTY_BASELINE_HASH, normalized.contentHash
	if durable and atomic then
		local ok, writeError = pcall(self._persistence.atomicReplace, self._persistence, normalized, transactionId)
		if not ok or writeError == false then return nil, failure("persistence_failed", tostring(writeError), "saveDocument", { transactionId = transactionId }) end
	elseif durable and journal then
		local record = { transactionId = transactionId, previousHash = previousHash, targetHash = targetHash, state = "pending" }
		local staged, stageError = pcall(self._persistence.writeJournal, self._persistence, record)
		if not staged or stageError == false then return nil, failure("persistence_failed", tostring(stageError), "saveDocument", { transactionId = transactionId }) end
		local written, writeError = pcall(self._persistence.write, self._persistence, normalized)
		if not written or writeError == false then return nil, failure("persistence_failed", tostring(writeError), "saveDocument", { transactionId = transactionId }) end
		pcall(self._persistence.writeJournal, self._persistence, { transactionId = transactionId, previousHash = previousHash, targetHash = targetHash, state = "written" })
	else
		local written, writeError = pcall(self._persistence.write, self._persistence, normalized)
		self._workspace, self._lastHash = normalized, targetHash
		if not written or writeError == false then
			if journal and type(self._persistence.writeJournal) == "function" then pcall(self._persistence.writeJournal, self._persistence, { transactionId = transactionId, previousHash = previousHash, targetHash = targetHash, state = "pending" }) end
			return freezeCopy(self._workspace), failure("persistence_pending", "Workspace committed in memory; persistence recovery is pending", "saveDocument", { transactionId = transactionId })
		end
		return freezeCopy(self._workspace), nil
	end
	self._workspace, self._lastHash = normalized, targetHash
	return freezeCopy(self._workspace), nil
end

function WorkspaceManager:SaveNamedWorkspace(namedWorkspace: any, options: any?): (any?, any?)
	local normalized, normalizeError = WorkspaceManager.NormalizeNamedWorkspace(namedWorkspace)
	if not normalized then return nil, normalizeError end
	return self:SaveDocument(normalized, options)
end

WorkspaceManager.Save = WorkspaceManager.SaveDocument
WorkspaceManager.SaveWorkspaceDocument = WorkspaceManager.SaveDocument
WorkspaceManager.SaveNamed = WorkspaceManager.SaveNamedWorkspace

-- Applies all structural state before visibility. Every mutation after capture has
-- one compensation route: restore structural window snapshots, restore and project
-- the old composition order, then restore visibility last.
function WorkspaceManager:ApplyDocument(document: any, resolveWindow: (string) -> any): (boolean, any?)
	if self._destroyed then return false, failure("destroyed", "WorkspaceManager is destroyed", "applyDocument") end
	if type(resolveWindow) ~= "function" then return false, failure("invalid_resolver", "Workspace application requires a window resolver", "applyDocument") end
	local normalized, normalizeError = normalize(document)
	if not normalized then return false, normalizeError end

	local priorWorkspace, priorHash = self._workspace, self._lastHash
	local applyingLoadedDocument = self._loadedHash == normalized.contentHash
	local loadedHashBeforeLoad = if applyingLoadedDocument then self._preLoadHash else self._loadedHash
	local preLoadHashBeforeLoad = if applyingLoadedDocument then nil else self._preLoadHash
	local function restoreLoadedBaseline()
		self._loadedHash, self._preLoadHash = loadedHashBeforeLoad, preLoadHashBeforeLoad
	end
	local targets, captured = {}, {}
	local requestedOrder = {}
	if type(normalized.payload.windowOrder) == "table" then
		for index, id in ipairs(normalized.payload.windowOrder) do
			if type(id) == "string" and requestedOrder[id] == nil then requestedOrder[id] = index end
		end
	end
	for id, state in pairs(normalized.payload.windows) do
		local window = resolveWindow(id)
		if window == nil then
			restoreLoadedBaseline()
			return false, failure("missing_window", "Workspace references a window that is not available", "applyDocument", { id = id })
		end
		if type(window.GetVisibilitySnapshot) ~= "function" or type(window.SetVisibility) ~= "function"
			or type(window.GetWorkspaceSnapshot) ~= "function" or type(window.ApplyWorkspaceSnapshot) ~= "function"
		then
			restoreLoadedBaseline()
			return false, failure("invalid_window", "Resolved window lacks transactional workspace APIs", "applyDocument", { id = id })
		end
		table.insert(targets, { id = id, state = state, window = window, stackOrder = requestedOrder[id] })
	end
	table.sort(targets, function(left, right)
		if left.stackOrder ~= nil and right.stackOrder ~= nil then return left.stackOrder < right.stackOrder end
		if left.stackOrder ~= nil then return true end
		if right.stackOrder ~= nil then return false end
		return left.id < right.id
	end)
	local fullStackSnapshot = nil
	for _, target in ipairs(targets) do
		local snapshotOk, snapshot = pcall(target.window.GetWorkspaceSnapshot, target.window)
		local visibilityOk, visibility = pcall(target.window.GetVisibilitySnapshot, target.window)
		local stackOk, stackIndex = true, nil
		if type(target.window.GetStackingIndex) == "function" then
			stackOk, stackIndex = pcall(target.window.GetStackingIndex, target.window)
		end
		if fullStackSnapshot == nil and type(target.window.GetStackingSnapshot) == "function" then
			local capturedStack, stackSnapshot = pcall(target.window.GetStackingSnapshot, target.window)
			if capturedStack then fullStackSnapshot = stackSnapshot end
		end
		if not snapshotOk or not visibilityOk or not stackOk or type(visibility) ~= "table" or not VISIBILITY[visibility.visibility] then
			restoreLoadedBaseline()
			return false, failure("workspace_capture_failed", "Could not capture prior window state", "applyDocument", { id = target.id })
		end
		table.insert(captured, { window = target.window, snapshot = snapshot, visibility = visibility.visibility, stackIndex = stackIndex })
	end
	local priorOrders = self:GetCompositionOrderSnapshot()
	local projectedParents = {}
	if type(normalized.payload.order) == "table" then
		for parentId in pairs(normalized.payload.order) do projectedParents[parentId] = true end
	end
	local function compensate(): { any }
		local unrecovered = {}
		local function record(target: any, operation: string, ok: boolean, result: any)
			if not ok or result == false then
				table.insert(unrecovered, { target = target, operation = operation, error = tostring(result) })
			end
		end
		for index = #captured, 1, -1 do
			local rollback = captured[index]
			local ok, result = pcall(rollback.window.ApplyWorkspaceSnapshot, rollback.window, rollback.snapshot)
			record(rollback.window._id or tostring(index), "restore_workspace", ok, result)
		end
		if fullStackSnapshot ~= nil then
			for _, rollback in ipairs(captured) do
				if type(rollback.window.RestoreStackingSnapshot) == "function" then
					local ok, result = pcall(rollback.window.RestoreStackingSnapshot, rollback.window, fullStackSnapshot)
					record(rollback.window._id or "stack", "restore_stacking", ok, result)
					break
				end
			end
		end
		local copiedOrders, restoredOrders = pcall(copy, priorOrders)
		if copiedOrders then
			self._compositionOrders = restoredOrders
			local restored, restoreError = self:RestoreCompositionOrders(projectedParents)
			if not restored then
				for _, item in ipairs((restoreError.details and restoreError.details.failures) or {}) do
					table.insert(unrecovered, { target = item.parentId, operation = "restore_order_" .. item.operation, error = item.error })
				end
			end
		else
			record("composition_orders", "restore_order_snapshot", false, restoredOrders)
		end
		for index = #captured, 1, -1 do
			local rollback = captured[index]
			local ok, result = pcall(rollback.window.SetVisibility, rollback.window, rollback.visibility, "workspaceRollback")
			record(rollback.window._id or tostring(index), "restore_visibility", ok, result)
		end
		self._workspace, self._lastHash = priorWorkspace, priorHash
		restoreLoadedBaseline()
		return unrecovered
	end
	local function abort(code: string, message: any, details: any?): (boolean, any?)
		local unrecovered = compensate()
		if #unrecovered > 0 then
			return false, failure("rollback_failed", "Could not fully compensate rejected workspace", "applyDocument", {
				initiating = { code = code, message = tostring(message), details = details },
				unrecovered = unrecovered,
			})
		end
		return false, failure(code, tostring(message), "applyDocument", details)
	end

	for _, target in ipairs(targets) do
		local applied, applyError = pcall(target.window.ApplyWorkspaceSnapshot, target.window, target.state)
		if not applied or applyError == false then
			return abort("workspace_apply_failed", if applied then "Window rejected workspace snapshot" else applyError, { id = target.id })
		end
	end
	if type(normalized.payload.order) == "table" then
		local ordered, orderError = self:SetCompositionOrderSnapshot(normalized.payload.order)
		if not ordered then return abort("workspace_order_apply_failed", orderError, nil) end
	end
	for _, target in ipairs(targets) do
		if target.stackOrder ~= nil and type(target.window.BringToFront) == "function" then
			local stacked, stackError = pcall(target.window.BringToFront, target.window)
			if not stacked or stackError == false then
				return abort("workspace_stack_apply_failed", if stacked then "Window rejected stack restoration" else stackError, { id = target.id })
			end
		end
	end
	local ordersApplied, ordersError = self:RestoreCompositionOrders(priorOrders)
	if not ordersApplied then return abort("workspace_order_apply_failed", ordersError, nil) end
	for _, target in ipairs(targets) do
		local visible, visibilityError = pcall(target.window.SetVisibility, target.window, target.state.visibility, "workspace")
		if not visible or visibilityError == false then
			return abort("workspace_apply_failed", if visible then "Window rejected visibility transition" else visibilityError, { id = target.id })
		end
	end
	self._workspace, self._lastHash, self._loadedHash, self._preLoadHash = normalized, normalized.contentHash, nil, nil
	return true, nil
end

function WorkspaceManager:ApplyNamedWorkspace(namedWorkspace: any, resolveWindow: (string) -> any): (boolean, any?)
	local normalized, normalizeError = WorkspaceManager.NormalizeNamedWorkspace(namedWorkspace)
	if not normalized then return false, normalizeError end
	return self:ApplyDocument(normalized, resolveWindow)
end

function WorkspaceManager:Recover(): (boolean, any?)
	if not self:_supports("journal") or type(self._persistence.readJournal) ~= "function" then return false, nil end
	local current = self._lastHash or self._loadedHash or EMPTY_BASELINE_HASH
	if type(self._persistence.read) == "function" then
		local readOk, document = pcall(self._persistence.read, self._persistence)
		if not readOk then return false, failure("recovery_conflict", "Persisted workspace could not be read during recovery", "recover") end
		if document == nil then current = EMPTY_BASELINE_HASH else
			local normalized, normalizeError = normalize(document)
			if not normalized then return false, failure("recovery_conflict", "Persisted workspace is not a valid recovery candidate", "recover", { cause = normalizeError }) end
			current = normalized.contentHash
		end
	end
	local ok, record = pcall(self._persistence.readJournal, self._persistence)
	if not ok or type(record) ~= "table" or record.state ~= "pending" then return false, nil end
	if type(record.previousHash) ~= "string" or type(record.targetHash) ~= "string" or record.previousHash == record.targetHash then return false, failure("invalid_recovery_journal", "Recovery journal hashes are invalid", "recover", { transactionId = record.transactionId }) end
	local state = if current == record.targetHash then "recovered" elseif current == record.previousHash then "compensating" else nil
	if not state then return false, failure("recovery_conflict", "Persisted workspace hash does not match either journal recovery hash", "recover", { transactionId = record.transactionId, currentHash = current, previousHash = record.previousHash, targetHash = record.targetHash }) end
	if type(self._persistence.writeJournal) == "function" then pcall(self._persistence.writeJournal, self._persistence, { transactionId = record.transactionId, previousHash = record.previousHash, targetHash = record.targetHash, state = state }) end
	return true, nil
end

function WorkspaceManager:Destroy()
	if self._destroyed then return end
	self._destroyed = true
end

return WorkspaceManager

end

__modules["customization/AssetPolicy"] = function()
--!strict

local StructuredError = __require("core/StructuredError")
local OfflineAssets = __require("customization/OfflineAssets")

export type StructuredErrorValue = StructuredError.StructuredError
export type AssetPolicy = {
	Admit: (self: AssetPolicy, asset: any, path: string?, owner: any?) -> (any?, StructuredErrorValue?),
	ReleaseOwner: (self: AssetPolicy, owner: any) -> (),
	Resolve: (self: AssetPolicy, admitted: any, runtime: any, path: string?) -> (string?, StructuredErrorValue?),
	OfflineName: (self: AssetPolicy, admitted: any, path: string?) -> (string?, StructuredErrorValue?),
	GetSnapshot: (self: AssetPolicy) -> any,
	GetMode: (self: AssetPolicy) -> string,
}

local AssetPolicy = {}
AssetPolicy.__index = AssetPolicy

local MAX_ASSETS, MAX_REFERENCE_LENGTH = 64, 256
local DEFAULT_ASSET_ROOT = "assets"
local KINDS = { image = true, icon = true, font = true, avatar = true }
local TAGS = { builtin = true, content = true, file = true, avatar = true }

local ASSET_FIELDS = table.freeze({
	image = table.freeze({ kind = true, source = true, fallback = true, scaleType = true, rectOffset = true, rectSize = true }),
	icon = table.freeze({ kind = true, source = true, fallback = true, scaleType = true, rectOffset = true, rectSize = true }),
	font = table.freeze({ kind = true, source = true, fallback = true }),
	avatar = table.freeze({ kind = true, source = true, fallback = true }),
})

local function failure(code: string, message: string, path: string?, operation: string?): StructuredErrorValue
	return StructuredError.from(code, message, { domain = "assetPolicy", operation = operation or "admit", path = path })
end

local function freeze(value: any): any
	if type(value) ~= "table" then return value end
	local copy = {}
	for key, item in pairs(value) do copy[key] = freeze(item) end
	return table.freeze(copy)
end

local function closed(value: any, fields: { [string]: boolean }, path: string): StructuredErrorValue?
	if type(value) ~= "table" then return failure("invalid_asset", "Asset declarations must be tables", path) end
	for key in pairs(value) do
		if type(key) ~= "string" or not fields[key] then return failure("unknown_asset_field", "Asset declaration contains an unknown field", path) end
	end
	return nil
end

local function reference(value: any, path: string): (string?, StructuredErrorValue?)
	if type(value) ~= "string" or #value == 0 or #value > MAX_REFERENCE_LENGTH then
		return nil, failure("invalid_asset_reference", "Asset references must be non-empty bounded strings", path)
	end
	return value, nil
end

local function safeRelative(value: string): boolean
	if string.find(value, "[%z\1-\31\127]") ~= nil
		or string.find(value, "\\", 1, true) ~= nil
		or string.find(value, "//", 1, true) ~= nil
		or string.sub(value, 1, 1) == "/"
		or string.sub(value, -1) == "/"
		or string.match(value, "^[A-Za-z]:") ~= nil
	then
		return false
	end
	for segment in string.gmatch(value, "[^/]+") do
		if segment == "" or segment == "." or segment == ".." then return false end
	end
	return true
end

local function assetRoot(value: any): (string?, StructuredErrorValue?)
	local root, rootErr = reference(value, "$.options.assetRoot")
	if root == nil then return nil, rootErr end
	if not safeRelative(root) then
		return nil, failure("invalid_asset_root", "Asset root must be a normalized relative path", "$.options.assetRoot", "create")
	end
	return root, nil
end

local function registeredAssets(value: any): ({ [string]: boolean }?, StructuredErrorValue?)
	if value == nil then return table.freeze({}), nil end
	if type(value) ~= "table" then
		return nil, failure("invalid_registered_assets", "Registered assets must be a table of opaque keys", "$.options.registeredAssets", "create")
	end
	local registered = {}
	for key, allowed in pairs(value) do
		if type(key) ~= "string" or #key == 0 or #key > MAX_REFERENCE_LENGTH
			or string.find(key, "[%z\1-\31\127]") ~= nil
			or string.find(key, "/", 1, true) ~= nil
			or string.find(key, "\\", 1, true) ~= nil
			or allowed ~= true
		then
			return nil, failure("invalid_registered_asset", "Registered asset keys must be opaque allowed strings", "$.options.registeredAssets", "create")
		end
		registered[key] = true
	end
	return table.freeze(registered), nil
end

local function fileReference(value: string, root: string, registered: { [string]: boolean }, path: string): (string?, StructuredErrorValue?)
	if registered[value] == true then return value, nil end
	if not safeRelative(value) or string.sub(value, 1, #root + 1) ~= root .. "/" then
		return nil, failure("invalid_asset_reference", "File references must be normalized paths beneath the configured asset root or registered opaque keys", path)
	end
	return value, nil
end
local function contentId(value: string): boolean

	return string.match(value, "^rbxassetid://[0-9]+$") ~= nil or string.match(value, "^rbxasset://[A-Za-z0-9_./%-]+$") ~= nil
end

local function adapterResult(result: any, adapterFailure: any, path: string): (string?, StructuredErrorValue?)
	if result ~= nil then
		if type(result) ~= "string" or #result == 0 or #result > MAX_REFERENCE_LENGTH or not contentId(result) then
			return nil, failure("invalid_adapter_result", "Asset adapters must return bounded content ids", path, "resolve")
		end
		return result, nil
	end
	if StructuredError.is(adapterFailure) then
		return nil, StructuredError.copy(adapterFailure)
	end
	return nil, failure("invalid_adapter_result", "Asset adapters must return bounded content ids", path, "resolve")
end

local function adapterAvailable(adapter: any, method: string): boolean
	return type(adapter) == "table" and type(adapter[method]) == "function"
end

local function callAdapter(adapter: any, method: string, value: string, path: string, useSelf: boolean?): (string?, StructuredErrorValue?)
	if not adapterAvailable(adapter, method) then
		return nil, failure("asset_adapter_unavailable", "The declared asset adapter is not injected", path, "resolve")
	end
	local ok, result, adapterFailure
	if useSelf then
		ok, result, adapterFailure = pcall(adapter[method], adapter, value)
	else
		ok, result, adapterFailure = pcall(adapter[method], value)
	end
	if not ok then
		return nil, failure("asset_adapter_failed", "The declared asset adapter failed", path, "resolve")
	end
	return adapterResult(result, adapterFailure, path)
end

local function requireCapability(capability: any, name: string, path: string): (boolean, StructuredErrorValue?)
	if type(capability) ~= "table" or type(capability.Require) ~= "function" then
		return false, failure("capability_unavailable", "Required runtime capability is unavailable", path, "resolve")
	end
	local allowed, capabilityErr = capability:Require(name)
	if allowed then return true, nil end
	if StructuredError.is(capabilityErr) then return false, StructuredError.copy(capabilityErr) end
	return false, failure("capability_unavailable", "Required runtime capability is unavailable", path, "resolve")
end

function AssetPolicy.new(options: any?): (AssetPolicy?, StructuredErrorValue?)
	local input = if options == nil then {} else options
	if type(input) ~= "table" then return nil, failure("invalid_asset_policy_options", "Asset policy options must be a table", "$.options", "create") end
	local optionsErr = closed(input, {
		mode = true,
		maxAssets = true,
		allowImageFallback = true,
		assetRoot = true,
		registeredAssets = true,
		capability = true,
	}, "$.options")
	if optionsErr then return nil, optionsErr end
	local configuredMode = rawget(input, "mode")
	local mode = if configuredMode == nil then "neutral" else configuredMode
	if mode ~= "neutral" and mode ~= "caller" then return nil, failure("invalid_asset_mode", "Asset policy mode must be neutral or caller", "$.options.mode", "create") end
	local configuredLimit = rawget(input, "maxAssets")
	local maxAssets = if configuredLimit == nil then MAX_ASSETS else configuredLimit
	if type(maxAssets) ~= "number" or maxAssets ~= math.floor(maxAssets) or maxAssets < 1 or maxAssets > MAX_ASSETS then
		return nil, failure("invalid_asset_limit", "Asset limit must be an integer from 1 to 64", "$.options.maxAssets", "create")
	end
	local allowImageFallback = rawget(input, "allowImageFallback") or false
	if type(allowImageFallback) ~= "boolean" then
		return nil, failure("invalid_asset_image_fallback", "Image fallback permission must be a boolean", "$.options.allowImageFallback", "create")
	end
	local configuredRoot = rawget(input, "assetRoot")
	local root, rootErr = assetRoot(if configuredRoot == nil then DEFAULT_ASSET_ROOT else configuredRoot)
	if root == nil then return nil, rootErr end
	local registered, registeredErr = registeredAssets(rawget(input, "registeredAssets"))
	if registered == nil then return nil, registeredErr end
	return setmetatable({
		_mode = mode,
		_maxAssets = maxAssets,
		_allowImageFallback = allowImageFallback,
		_assetRoot = root,
		_registeredAssets = registered,
		_capability = rawget(input, "capability"),
		_catalog = OfflineAssets,
		_admitted = {},
		_owners = {},
		_admittedCount = 0,
		_destroyed = false,
	}, AssetPolicy) :: any, nil
end

function AssetPolicy:GetMode(): string
	return self._mode
end

function AssetPolicy:Admit(asset: any, path: string?, owner: any?): (any?, StructuredErrorValue?)
	if self._destroyed then return nil, failure("destroyed_asset_policy", "Asset policy has been destroyed", path or "$.asset", "admit") end
	local assetPath = path or "$.asset"
	if type(asset) ~= "table" then return nil, failure("invalid_asset", "Asset declarations must be tables", assetPath) end
	local kind = rawget(asset, "kind")
	if type(kind) ~= "string" or not KINDS[kind] then return nil, failure("unsupported_asset_kind", "Asset kind must be image, icon, font, or avatar", assetPath .. ".kind") end
	local err = closed(asset, ASSET_FIELDS[kind], assetPath)
	if err then return nil, err end
	local source = rawget(asset, "source")
	if source == nil then return nil, failure("missing_asset_source", "Asset declarations require an explicit tagged source", assetPath .. ".source") end
	local sourceErr = closed(source, { tag = true, value = true }, assetPath .. ".source")
	if sourceErr then return nil, sourceErr end
	local tag = rawget(source, "tag")
	if type(tag) ~= "string" or not TAGS[tag] then return nil, failure("invalid_asset_source", "Asset source tag is not supported", assetPath .. ".source.tag") end
	local value, valueErr = reference(rawget(source, "value"), assetPath .. ".source.value")
	if value == nil then return nil, valueErr end
	if tag == "file" then
		local normalized, normalizedErr = fileReference(value, self._assetRoot, self._registeredAssets, assetPath .. ".source.value")
		if normalized == nil then return nil, normalizedErr end
		value = normalized
	end
	if tag == "builtin" and self._catalog.Get(kind .. "s", value) == nil then return nil, failure("unknown_offline_asset", "Unknown offline asset reference", assetPath .. ".source.value") end
	if tag == "content" and (kind ~= "image" and kind ~= "icon" or not contentId(value)) then return nil, failure("invalid_asset_content", "Content sources must be valid image or icon content ids", assetPath .. ".source.value") end
	if tag == "avatar" and kind ~= "avatar" then return nil, failure("invalid_asset_source", "Avatar sources are only valid for avatar assets", assetPath .. ".source.tag") end
	if tag == "file" and kind ~= "image" and kind ~= "icon" then return nil, failure("invalid_asset_source", "File sources are only valid for image or icon assets", assetPath .. ".source.tag") end
	local fallback = rawget(asset, "fallback")
	local fallbackName: string? = nil
	if fallback ~= nil then
		local fallbackErr = closed(fallback, { onUnavailable = true, builtin = true }, assetPath .. ".fallback")
		if fallbackErr then return nil, fallbackErr end
		if rawget(fallback, "onUnavailable") ~= "fallback" then return nil, failure("invalid_asset_fallback", "Fallback must explicitly use onUnavailable='fallback'", assetPath .. ".fallback.onUnavailable") end
		local name, nameErr = reference(rawget(fallback, "builtin"), assetPath .. ".fallback.builtin")
		if name == nil then return nil, nameErr end
		if self._catalog.Get(kind .. "s", name) == nil then return nil, failure("unknown_offline_asset", "Unknown offline fallback", assetPath .. ".fallback.builtin") end
		fallbackName = name
	end
	if rawget(asset, "scaleType") ~= nil and rawget(asset, "scaleType") ~= "Stretch" and rawget(asset, "scaleType") ~= "Slice" and rawget(asset, "scaleType") ~= "Fit" and rawget(asset, "scaleType") ~= "Crop" and rawget(asset, "scaleType") ~= "Tile" then return nil, failure("invalid_asset_scale_type", "Image scaleType is unsupported", assetPath .. ".scaleType") end
	for _, field in ipairs({ "rectOffset", "rectSize" }) do if rawget(asset, field) ~= nil and typeof(rawget(asset, field)) ~= "Vector2" then return nil, failure("invalid_asset_rect", "Image rect fields must be Vector2 values", assetPath .. "." .. field) end end
	local scaleType = rawget(asset, "scaleType")
	local rectOffset, rectSize = rawget(asset, "rectOffset"), rawget(asset, "rectSize")
	local admissionKey = table.concat({
		kind, tag, value, fallbackName or "", tostring(scaleType or ""),
		if rectOffset ~= nil then tostring(rectOffset.X) .. "," .. tostring(rectOffset.Y) else "",
		if rectSize ~= nil then tostring(rectSize.X) .. "," .. tostring(rectSize.Y) else "",
	}, "|")
	if owner ~= nil then
		local ownerAssets = self._owners[owner]
		if ownerAssets == nil or ownerAssets[admissionKey] ~= true then
			local references = self._admitted[admissionKey] or 0
			if references == 0 and self._admittedCount >= self._maxAssets then
				return nil, failure("asset_limit", "Asset policy declaration limit reached", assetPath, "admit")
			end
			if ownerAssets == nil then
				ownerAssets = {}
				self._owners[owner] = ownerAssets
			end
			ownerAssets[admissionKey] = true
			self._admitted[admissionKey] = references + 1
			if references == 0 then
				self._admittedCount += 1
			end
		end
	end
	return freeze({ kind = kind, source = { tag = tag, value = value }, fallback = fallback, scaleType = scaleType, rectOffset = rectOffset, rectSize = rectSize }), nil
end
function AssetPolicy:ReleaseOwner(owner: any)
	local ownerAssets = self._owners[owner]
	if ownerAssets == nil then return end
	for admissionKey in pairs(ownerAssets) do
		local references = (self._admitted[admissionKey] or 1) - 1
		if references <= 0 then
			self._admitted[admissionKey] = nil
			self._admittedCount -= 1
		else
			self._admitted[admissionKey] = references
		end
	end
	self._owners[owner] = nil
end

local function offlineName(catalog: any, value: any, path: string): (string?, StructuredErrorValue?)
	local name = if value.source.tag == "builtin" then value.source.value else if value.fallback ~= nil then value.fallback.builtin else nil
	if name == nil then return nil, failure("asset_unavailable", "Asset declarations require an offline fallback", path, "resolve") end
	local offline = catalog.Get(value.kind .. "s", name)
	if type(offline) == "string" then return offline, nil end
	return name, nil
end

function AssetPolicy:OfflineName(admitted: any, path: string?): (string?, StructuredErrorValue?)
	local assetPath = path or "$.asset"
	local value, err = self:Admit(admitted, assetPath)
	if value == nil then return nil, err end
	return offlineName(self._catalog, value, assetPath)
end

function AssetPolicy:Resolve(admitted: any, runtime: any, path: string?): (string?, StructuredErrorValue?)
	local resolvedPath = path or "$.asset"
	local value, err = self:Admit(admitted, resolvedPath)
	if value == nil then return nil, err end
	local tag, source = value.source.tag, value.source.value
	if self._mode == "neutral" then
		-- Neutral resolution is semantic only; it deliberately never inspects runtime.
		local offline, offlineErr = offlineName(self._catalog, value, resolvedPath)
		if offline == nil then return nil, offlineErr end
		return "", nil
	end
	if tag == "content" then return source, nil end
	if tag == "builtin" then return "", nil end
	if tag == "file" then
		-- Select one injected provider before invocation. A provider failure or
		-- invalid result never authorizes trying another provider.
		local localAssets = if type(runtime) == "table" then runtime.localAssets else nil
		local image = if type(runtime) == "table" then runtime.image else nil
		local adapter, capabilityName
		if adapterAvailable(localAssets, "fromFile") then
			adapter, capabilityName = localAssets, "localAssets"
		elseif self._allowImageFallback and adapterAvailable(image, "fromFile") then
			adapter, capabilityName = image, "image"
		end
		if adapter == nil then
			if value.fallback ~= nil then return "", nil end
			return nil, failure("asset_adapter_unavailable", "The declared asset adapter is not injected", resolvedPath, "resolve")
		end
		local allowed, capabilityErr = requireCapability(self._capability, capabilityName, resolvedPath)
		if not allowed then return nil, capabilityErr end
		local result, adapterErr = callAdapter(adapter, "fromFile", source, resolvedPath)
		if result ~= nil then return result, nil end
		if value.fallback ~= nil then return "", nil end
		return nil, adapterErr
	end
	if tag == "avatar" then
		local avatars = if type(runtime) == "table" then runtime.avatars else nil
		local allowed, capabilityErr = requireCapability(self._capability, "avatars", resolvedPath)
		if not allowed then return nil, capabilityErr end
		local result, adapterErr = callAdapter(avatars, "Resolve", source, resolvedPath, true)
		if result ~= nil then return result, nil end
		if value.fallback ~= nil then return "", nil end
		return nil, adapterErr
	end
	return nil, failure("invalid_asset_source", "Asset source tag is not supported", resolvedPath .. ".source.tag", "resolve")
end

function AssetPolicy:GetSnapshot(): any
	return freeze({
		mode = self._mode,
		maxAssets = self._maxAssets,
		allowImageFallback = self._allowImageFallback,
		assetRoot = self._assetRoot,
		maxContentLength = MAX_REFERENCE_LENGTH,
		kinds = { "image", "icon", "font", "avatar" },
		catalog = self._catalog.Snapshot(),
	})
end
function AssetPolicy:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	table.clear(self._admitted)
	table.clear(self._owners)
	self._admittedCount = 0
end

return AssetPolicy

end

__modules["customization/ControlHost"] = function()
--!strict

local Maid = __require("core/Maid")
local StructuredError = __require("core/StructuredError")
local ControlDescriptors = __require("models/ControlDescriptors")
local CompositionDescriptors = __require("models/CompositionDescriptors")

local ControlHost = {}
ControlHost.__index = ControlHost
local COST_KEYS = {
	instances = true, descendants = true, gradients = true, strokes = true, images = true, sounds = true,
	animations = true, particles = true, materialNodes = true, slots = true, layoutNodes = true,
	virtualRows = true, virtualCells = true, connections = true, workers = true, tasks = true,
	retainedItems = true, perRowInstances = true, updatesPerSecond = true, logicalBlurRequests = true,
}

local function costVector(value: any): any
	local result = {}
	for key, amount in pairs(value or {}) do
		if COST_KEYS[key] and type(amount) == "number" then result[key] = amount end
	end
	return result
end

local function fail(code: string, message: string, operation: string): any
	return StructuredError.from(code, message, { domain = "controlHost", operation = operation })
end
local function transaction(self: any): string
	self._transaction += 1
	return self._ownerId .. ".control." .. tostring(self._transaction)
end
local function reservationFor(descriptor: any): any
	local cost = {}
	if type(descriptor.cost) == "table" then
		for key, value in pairs(descriptor.cost) do cost[key] = value end
	end
	-- Modern renderers retain at least one GuiObject whenever a concrete target exists.
	cost.connections = math.max(cost.connections or 0, 8)
	cost.instances = math.max(cost.instances or 0, 16)
	if descriptor.kind == "Keybind" then cost.connections = math.max(cost.connections, 32) end
	cost.descendants = math.max(cost.descendants or 0, 16)
	if descriptor.kind == "Chart" then
		local seriesCount = math.max(1, #(descriptor.series or {}))
		local maxSamples = math.min(512, math.max(2, tonumber(descriptor.maxSamples) or 512))
		cost.instances = math.max(cost.instances, 32 + seriesCount * (maxSamples * 2 + 16))
		cost.descendants = math.max(cost.descendants, cost.instances)
		cost.connections = math.max(cost.connections, 32)
	elseif descriptor.kind == "DataGrid" then
		local pool = math.min(128, #(descriptor.rows or {}))
		local columns = math.max(1, #(descriptor.columns or {}))
		cost.instances = math.max(cost.instances, 32 + pool * (columns + 4))
		cost.descendants = math.max(cost.descendants, cost.instances)
		cost.connections = math.max(cost.connections, 32)
		cost.virtualRows = math.max(cost.virtualRows or 0, pool)
		cost.virtualCells = math.max(cost.virtualCells or 0, pool * columns)
	end
	return cost
end
local function publish(self: any)
	if self._diagnostics and type(self._diagnostics.Publish) == "function" then
		pcall(function()
			self._diagnostics:Publish("controls", self:GetSnapshot(), { ownerId = self._ownerId })
		end)
	end
end
local function snapshotActual(actual: any): any
	local copy = {}
	for key, value in pairs(actual or {}) do
		if typeof(value) ~= "Instance" then copy[key] = value end
	end
	return table.freeze(copy)
end

local function copySnapshot(handle: any): any
	return table.freeze({
		id = handle._id, ownerId = handle._host._ownerId, generation = handle._generation,
		state = handle._destroyed and "destroyed" or "mounted", revision = handle._revision,
		composition = handle._composition, chrome = handle._chrome, actual = snapshotActual(handle._actual),
	})
end
local function stage(self: any, descriptor: any, tx: string, generation: number, identity: any?, target: any?, publicationQueue: any?, storeChanges: any?): (any?, any?)
	local renderer = self._renderers[descriptor.kind]
	local child = Maid.new()
	local staged = {
		maid = child, descriptor = descriptor, composition = table.freeze({}), actual = {}, api = {},
		identity = nil, preflightIdentity = nil, adoptIdentity = nil, rollbackIdentity = nil, configureChrome = nil, handle = nil,
	}
	local function updateSnapshot(composition: any, actual: any?)
		if type(composition) == "table" then
			staged.composition = if table.isfrozen(composition) then composition else table.freeze(composition)
		end
		if type(actual) == "table" then staged.actual = costVector(actual) end
		if staged.handle ~= nil and not staged.handle._destroyed and staged.handle._generation == generation then
			staged.handle._composition = staged.composition
			staged.handle._actual = staged.actual
			staged.handle._revision += 1
			publish(self)
		end
	end
	if renderer ~= nil then
		local ok, result, err = pcall(renderer, descriptor, {
			ownerId = self._ownerId, transactionId = tx, generation = generation, maid = child, target = target,
			identity = identity, publicationQueue = publicationQueue, storeChanges = storeChanges, UpdateSnapshot = updateSnapshot,
		})
		if not ok then child:Destroy(); return nil, fail("control_stage_failed", tostring(result), "stage") end
		if result == nil then child:Destroy(); return nil, err or fail("control_stage_failed", "Control renderer did not stage a result", "stage") end
		if type(result) == "table" then
			if result.Destroy ~= nil then child:GiveTask(result) end
			if type(result.composition) == "table" then updateSnapshot(result.composition, result.actual) end
			if type(result.actual) == "table" then staged.actual = costVector(result.actual) end
			staged.identity = result._identity
			staged.preflightIdentity = result._preflightIdentity
			staged.adoptIdentity = result._adoptIdentity
			staged.rollbackIdentity = result._rollbackIdentity
			if type(result.ConfigureChrome) == "function" then staged.configureChrome = result.ConfigureChrome end
			for key, value in pairs(result) do
				if key ~= "composition" and key ~= "actual" and key ~= "Destroy" and key ~= "ConfigureChrome" and string.sub(key, 1, 1) ~= "_" then
					staged.api[key] = value
				end
			end
		end
	end
	return staged, nil
end

local Handle = {}
Handle.__index = Handle
function Handle:GetSnapshot() return copySnapshot(self) end
function Handle:Mount(slot: any, contribution: any): (any?, any?)
	if self._destroyed then return nil, fail("destroyed_handle", "ControlHandle has been destroyed", "mount") end
	if type(slot) ~= "table" or type(slot.Mount) ~= "function" then return nil, fail("invalid_slot_handle", "Mount requires a SlotHandle", "mount") end
	return slot:Mount(contribution or self._descriptor)
end
function Handle:Update(descriptor: any): (boolean, any?) return self._host:_replace(self, descriptor, false) end
function Handle:Replace(descriptor: any): (boolean, any?) return self._host:_replace(self, descriptor, true) end
function Handle:ConfigureChrome(chrome: any): (boolean, any?)
	if self._destroyed then return false, fail("destroyed_handle", "ControlHandle has been destroyed", "configureChrome") end
	if type(chrome) ~= "table" then return false, fail("invalid_chrome", "Chrome must be a table", "configureChrome") end
	for key, value in pairs(chrome) do
		if key ~= "label" and key ~= "value" and key ~= "addonRail" and key ~= "danger" and key ~= "trailing" then
			return false, fail("unknown_chrome_field", "Chrome contains an unknown field", "configureChrome")
		end
		if key == "danger" and type(value) ~= "boolean" then return false, fail("invalid_chrome", "danger must be boolean", "configureChrome") end
	end
	-- Preflight and copy occur before the nonfailing reference assignment.
	local codec = __require("customization/SchemaCodec").new()
	local ok, scanError = codec:PreScanPortable(chrome, "chrome")
	if not ok then return false, scanError end
	local nextChrome, normalizeError = codec:Normalize(chrome)
	if nextChrome == nil then return false, normalizeError end
	if self._configureChrome ~= nil then
		local applied, applyResult, applyError = pcall(self._configureChrome, nextChrome)
		if not applied then return false, fail("chrome_apply_failed", tostring(applyResult), "configureChrome") end
		if applyResult == false then return false, applyError or fail("chrome_apply_failed", "Renderer rejected chrome configuration", "configureChrome") end
	end
	self._chrome = nextChrome
	self._revision += 1
	publish(self._host)
	return true, nil
end
function Handle:Unmount(): boolean
	if self._destroyed then return true end
	self._destroyed = true
	self._maid:Destroy()
	if self._host._handles[self._id] == self then self._host._handles[self._id] = nil end
	if self._host._budget then
		self._host._budget:Release(self._transactionId, self._host._ownerId, self._generation)
	end
	publish(self._host)
	return true
end
Handle.Destroy = Handle.Unmount

function ControlHost.new(options: any): (any?, any?)
	if type(options) ~= "table" or type(options.ownerId) ~= "string" then return nil, fail("invalid_control_host", "ControlHost requires ownerId", "create") end
	return setmetatable({
		_ownerId = options.ownerId,
		_target = options.target,
		_renderers = options.renderers or {},
		_budget = options.budget,
		_diagnostics = options.diagnostics,
		_handles = {},
		_transaction = 0,
		_compositionOrders = {},
		_compositionControls = {},
		_compositionOwners = {},
		_destroyed = false,
	}, ControlHost), nil
end
function ControlHost:RegisterRenderer(kind: any, renderer: any): (boolean, any?)
	if self._destroyed then return false, fail("destroyed_host", "ControlHost has been destroyed", "register") end
	if type(kind) ~= "string" or type(renderer) ~= "function" then return false, fail("invalid_renderer", "Renderer requires a kind and function", "register") end
	self._renderers[kind] = renderer
	return true, nil
end
function ControlHost:Mount(descriptor: any): (any?, any?)
	if self._destroyed then return nil, fail("destroyed_host", "ControlHost has been destroyed", "mount") end
	local parsed, parseError = ControlDescriptors.Validate(descriptor)
	if parsed == nil then return nil, parseError end
	if self._handles[parsed.id] ~= nil then return nil, fail("duplicate_control_id", "Control id is already mounted", "mount") end
	local tx, generation = transaction(self), 1
	local reservedCost = reservationFor(parsed)
	if self._budget then
		local reserved, reserveError = self._budget:Reserve(tx, self._ownerId, generation, reservedCost)
		if not reserved then return nil, reserveError end
	end
	local staged, stageError = stage(self, parsed, tx, generation, nil, self._target)
	if staged == nil then
		if self._budget then self._budget:Release(tx, self._ownerId, generation) end
		return nil, stageError
	end
	if self._budget then
		local reconciled, reconcileError = self._budget:Reconcile(tx, self._ownerId, generation, staged.actual)
		if not reconciled then staged.maid:Destroy(); self._budget:Release(tx, self._ownerId, generation); return nil, reconcileError end
	end
	local handle = setmetatable({
		_host = self, _id = parsed.id, _generation = generation, _revision = 1, _descriptor = parsed,
		_chrome = table.freeze({}), _composition = staged.composition, _actual = staged.actual, _maid = staged.maid,
		_transactionId = tx, _destroyed = false, _identity = staged.identity, _configureChrome = staged.configureChrome, _apiKeys = {},
	}, Handle)
	staged.handle = handle
	if staged.adoptIdentity ~= nil then
		local adopted, adoptionResult, adoptionError = pcall(staged.adoptIdentity)
		if not adopted or adoptionResult == false then
			staged.maid:Destroy()
			if self._budget then self._budget:Release(tx, self._ownerId, generation) end
			return nil, if not adopted then fail("identity_adoption_failed", tostring(adoptionResult), "mount") else adoptionError or fail("identity_adoption_failed", "Renderer rejected identity adoption", "mount")
		end
	end
	for key, value in pairs(staged.api) do handle[key] = value; handle._apiKeys[key] = true end
	self._handles[parsed.id] = handle
	publish(self)
	return handle, nil
end
function ControlHost:_replace(handle: any, descriptor: any, _replace: boolean): (boolean, any?)
	if handle._destroyed then return false, fail("destroyed_handle", "ControlHandle has been destroyed", "update") end
	local parsed, parseError = ControlDescriptors.Validate(descriptor)
	if parsed == nil then return false, parseError end
	if parsed.id ~= handle._id then return false, fail("control_id_immutable", "Control updates cannot change id", "update") end
	local tx, generation = transaction(self), handle._generation + 1
	local reservedCost = reservationFor(parsed)
	if self._budget then
		local reserved, reserveError = self._budget:Reserve(tx, self._ownerId, generation, reservedCost)
		if not reserved then return false, reserveError end
	end
	local staged, stageError = stage(self, parsed, tx, generation, handle._identity, self._target)
	if staged == nil then
		if self._budget then self._budget:Release(tx, self._ownerId, generation) end
		return false, stageError
	end
	if self._budget then
		local reconciled, reconcileError = self._budget:Reconcile(tx, self._ownerId, generation, staged.actual)
		if not reconciled then staged.maid:Destroy(); self._budget:Release(tx, self._ownerId, generation); return false, reconcileError end
	end
	if staged.configureChrome ~= nil then
		local applied, applyResult, applyError = pcall(staged.configureChrome, handle._chrome)
		if not applied or applyResult == false then
			staged.maid:Destroy()
			if self._budget then self._budget:Release(tx, self._ownerId, generation) end
			return false, if not applied then fail("chrome_apply_failed", tostring(applyResult), "update") else applyError or fail("chrome_apply_failed", "Renderer rejected chrome configuration", "update")
		end
	end
	local oldMaid, oldTx, oldGeneration = handle._maid, handle._transactionId, handle._generation
	if staged.adoptIdentity ~= nil then
		local adopted, adoptionResult, adoptionError = pcall(staged.adoptIdentity)
		if not adopted or adoptionResult == false then
			staged.maid:Destroy()
			if self._budget then self._budget:Release(tx, self._ownerId, generation) end
			return false, if not adopted then fail("identity_adoption_failed", tostring(adoptionResult), "update") else adoptionError or fail("identity_adoption_failed", "Renderer rejected identity adoption", "update")
		end
	end
	handle._descriptor, handle._maid, handle._composition, handle._actual, handle._transactionId, handle._generation, handle._identity, handle._configureChrome =
		parsed, staged.maid, staged.composition, staged.actual, tx, generation, staged.identity, staged.configureChrome
	for key in pairs(handle._apiKeys) do handle[key] = nil end
	handle._apiKeys = {}
	for key, value in pairs(staged.api) do handle[key] = value; handle._apiKeys[key] = true end
	handle._revision += 1
	staged.handle = handle
	publish(self)
	task.defer(function()
		oldMaid:Destroy()
		if self._budget then self._budget:Release(oldTx, self._ownerId, oldGeneration) end
	end)
	return true, nil
end
local FLOW_FIELDS = table.freeze({ "wrap", "gap", "minItemWidth", "maxColumns", "align", "flex", "weight" })

function ControlHost:LowerComposition(descriptor: any): (any?, any?)
	if self._destroyed then return nil, fail("destroyed_host", "ControlHost has been destroyed", "lower") end
	local parsed, parseError = CompositionDescriptors.Validate(descriptor)
	if parsed == nil then return nil, parseError end
	local controls = {}
	local function lowerNode(node: any): (any?, any?)
		if CompositionDescriptors.IsContainer(node) then
			local children = {}
			for index, child in ipairs(node.children) do
				local lowered, lowerError = lowerNode(child)
				if lowered == nil then return nil, lowerError end
				children[index] = lowered
			end
			local lowered = {
				kind = node.kind, id = node.id, children = table.freeze(children), role = node.role,
				accessibility = node.accessibility, materialRole = node.materialRole, cost = node.cost,
				slots = node.slots, localization = node.localization, extensions = node.extensions,
			}
			if node.kind == "row" or node.kind == "column" then
				for _, field in ipairs(FLOW_FIELDS) do lowered[field] = node[field] end
			end
			return table.freeze(lowered), nil
		end
		if CompositionDescriptors.IsContent(node) then
			local lowered = {
				kind = node.kind, id = node.id, value = node.value, label = node.label, icon = node.icon, image = node.image,
				tone = node.tone, role = node.role, accessibility = node.accessibility, materialRole = node.materialRole,
				cost = node.cost, localization = node.localization, extensions = node.extensions,
			}
			if node.kind ~= "callout" and node.kind ~= "empty-state" then lowered.text = node.text end
			for _, field in ipairs({ "heading", "text", "actionBar" }) do
				if node[field] ~= nil and (field ~= "text" or node.kind == "callout" or node.kind == "empty-state") then
					local child, childError = lowerNode(node[field])
					if child == nil then return nil, childError end
					lowered[field] = child
				end
			end
			return table.freeze(lowered), nil
		end
		local control, controlError = ControlDescriptors.Validate(node)
		if control == nil then return nil, controlError end
		if controls[control.id] ~= nil then return nil, fail("duplicate_control_id", "Composition control ids must be unique", "lower") end
		controls[control.id] = control
		return table.freeze({ kind = "control", id = control.id, descriptor = control }), nil
	end
	local composition, lowerError = lowerNode(parsed)
	if composition == nil then return nil, lowerError end
	return table.freeze({ root = composition, controls = table.freeze(controls) }), nil
end

-- Public composition participant seam.  Preparation and staging retain no live
-- handle mutation; CommitComposition only swaps already-staged handle state.
function ControlHost:PrepareComposition(plan: any): (any?, any?)
	if self._destroyed or type(plan) ~= "table" then return nil, fail("invalid_composition_plan", "Control composition plan is required", "prepareComposition") end
	local lowered, lowerError = self:LowerComposition(plan.descriptor)
	if lowered == nil then return nil, lowerError end
	local records, present = {}, {}
	for id, descriptor in pairs(lowered.controls) do
		present[id] = true
		local existing = self._handles[id]
		local owner = self._compositionOwners[id]
		if owner ~= nil and owner ~= plan.id then
			for _, record in ipairs(records) do if self._budget then self._budget:Release(record.tx, self._ownerId, record.generation) end end
			return nil, fail("composition_control_conflict", "Control id is owned by another composition", "prepareComposition")
		end
		local tx, generation = transaction(self), if existing then existing._generation + 1 else 1
		local reserved = reservationFor(descriptor)
		if self._budget then
			local ok, reserveError = self._budget:Reserve(tx, self._ownerId, generation, reserved)
			if not ok then
				for _, record in ipairs(records) do self._budget:Release(record.tx, self._ownerId, record.generation) end
				return nil, reserveError
			end
		end
		table.insert(records, { id = id, descriptor = descriptor, existing = existing, tx = tx, generation = generation,
			target = type(plan.layoutFrames) == "table" and plan.layoutFrames[type(plan.layoutIds) == "table" and plan.layoutIds[id] or id] or self._target })
	end
	local removed = {}
	for id in pairs(self._compositionControls[plan.id] or {}) do
		if not present[id] and self._compositionOwners[id] == plan.id and self._handles[id] ~= nil then table.insert(removed, self._handles[id]) end
	end
	return { state = "prepared", plan = plan, records = records, present = present, removed = removed, publicationQueue = {} }, nil
end
function ControlHost:StageComposition(token: any): (boolean, any?)
	if type(token) ~= "table" or token.state ~= "prepared" then return false, fail("invalid_composition_transaction", "Composition transaction must be prepared", "stageComposition") end
	for _, record in ipairs(token.records) do
		local staged, stageError = stage(self, record.descriptor, record.tx, record.generation, record.existing and record.existing._identity, record.target, token.publicationQueue, token.plan.storeChanges)
		if staged == nil then self:AbortComposition(token); return false, stageError end
		if self._budget then
			local ok, reconcileError = self._budget:Reconcile(record.tx, self._ownerId, record.generation, staged.actual)
			if not ok then staged.maid:Destroy(); self:AbortComposition(token); return false, reconcileError end
		end
		if staged.configureChrome and record.existing then
			local ok, result, applyError = pcall(staged.configureChrome, record.existing._chrome)
			if not ok or result == false then staged.maid:Destroy(); self:AbortComposition(token); return false, if not ok then fail("chrome_apply_failed", tostring(result), "stageComposition") else applyError end
		end
		record.staged = staged
	end
	token.state = "staged"
	return true, nil
end

function ControlHost:PreflightCompositionTransaction(token: any, transaction: any): (boolean, any?)
	if type(token) ~= "table" or token.state ~= "staged" or type(transaction) ~= "table" then
		return false, fail("invalid_composition_transaction", "Staged control and Store transactions are required", "preflightCompositionTransaction")
	end
	for _, record in ipairs(token.records) do
		if record.staged.preflightIdentity ~= nil then
			local accepted, result, identityError = pcall(record.staged.preflightIdentity, transaction.values or {})
			if not accepted or result == false then
				return false, if not accepted then fail("identity_preflight_failed", tostring(result), "preflightCompositionTransaction") else identityError or fail("identity_preflight_failed", "Renderer rejected identity preflight", "preflightCompositionTransaction")
			end
		end
	end
	return true, nil
end

function ControlHost:FinalizeComposition(token: any): boolean
	if type(token) ~= "table" or token.state ~= "committed" then return false end
	token.state = "finalized"
	for _, publishNotification in ipairs(token.publicationQueue or {}) do pcall(publishNotification) end
	table.clear(token.publicationQueue)
	for _, old in ipairs(token.retire or {}) do
		task.defer(function()
			old.maid:Destroy()
			if self._budget then self._budget:Release(old.tx, self._ownerId, old.generation) end
		end)
	end
	token.retire, token.previousOwners, token.previousControls, token.previousOrders = nil, nil, nil, nil
	for _, record in ipairs(token.records) do record.prior = nil end
	publish(self)
	return true
end
function ControlHost:CommitComposition(token: any): (boolean, any?)
	if type(token) ~= "table" or token.state ~= "staged" then return false, fail("invalid_composition_transaction", "Composition transaction must be staged", "commitComposition") end
	-- Controls are rendered directly into the detached LayoutEngine frames, which
	-- are published by the layout participant as the common composition root.
	-- All potentially rejecting identity work runs before any host table swap.
	token.previousOwners = table.clone(self._compositionOwners)
	token.previousControls = self._compositionControls[token.plan.id]
	token.previousOrders = table.clone(self._compositionOrders)
	for _, record in ipairs(token.records) do
		if record.existing then record.prior = table.clone(record.existing) end
	end
	for _, record in ipairs(token.records) do
		if record.staged.adoptIdentity then
			record.adoptionAttempted = true
			local ok, result, adoptionError = pcall(record.staged.adoptIdentity)
			if not ok or result == false then return false, if not ok then fail("identity_adoption_failed", tostring(result), "commitComposition") else adoptionError or fail("identity_adoption_failed", "Renderer rejected identity adoption", "commitComposition") end
		end
	end
	local retire = {}
	for _, record in ipairs(token.records) do
		local staged, handle = record.staged, record.existing
		if handle == nil then
			handle = setmetatable({ _host = self, _id = record.id, _generation = record.generation, _revision = 1, _descriptor = record.descriptor,
				_chrome = table.freeze({}), _composition = staged.composition, _actual = staged.actual, _maid = staged.maid,
				_transactionId = record.tx, _destroyed = false, _identity = staged.identity, _configureChrome = staged.configureChrome, _apiKeys = {} }, Handle)
			for key, value in pairs(staged.api) do handle[key] = value; handle._apiKeys[key] = true end
			self._handles[record.id] = handle
		else
			table.insert(retire, { maid = handle._maid, tx = handle._transactionId, generation = handle._generation })
			handle._descriptor, handle._maid, handle._composition, handle._actual, handle._transactionId, handle._generation, handle._identity, handle._configureChrome = record.descriptor, staged.maid, staged.composition, staged.actual, record.tx, record.generation, staged.identity, staged.configureChrome
			for key in pairs(handle._apiKeys) do handle[key] = nil end
			handle._apiKeys = {}
			for key, value in pairs(staged.api) do handle[key] = value; handle._apiKeys[key] = true end
			handle._revision += 1
		end
		staged.handle = handle
		record.handle = handle
	end
	for _, handle in ipairs(token.removed) do
		if self._handles[handle._id] == handle and self._compositionOwners[handle._id] == token.plan.id then
			table.insert(retire, { maid = handle._maid, tx = handle._transactionId, generation = handle._generation })
			handle._destroyed, self._handles[handle._id], self._compositionOwners[handle._id] = true, nil, nil
		end
	end
	for _, record in ipairs(token.records) do self._compositionOwners[record.id] = token.plan.id end
	self._compositionControls[token.plan.id] = token.present
	token.state = "committed"
	token.retire = retire
	return true, nil
end
function ControlHost:AbortComposition(token: any): boolean
	if type(token) ~= "table" or token.state == "finalized" or token.state == "aborted" then return false end
	local restored = true
	for index = #(token.records or {}), 1, -1 do
		local record = token.records[index]
		if record.staged then
			record.staged.handle = nil
			if record.adoptionAttempted and record.staged.rollbackIdentity then
				local ok, result = pcall(record.staged.rollbackIdentity)
				if not ok or result == false then restored = false end
			end
		end
		if record.prior then
			table.clear(record.existing)
			for key, value in pairs(record.prior) do record.existing[key] = value end
			self._handles[record.id] = record.existing
		elseif record.handle then
			record.handle._destroyed = true
			if self._handles[record.id] == record.handle then self._handles[record.id] = nil end
		end
		if record.staged then record.staged.maid:Destroy(); record.staged = nil end
		if self._budget then self._budget:Release(record.tx, self._ownerId, record.generation) end
	end
	if token.state == "committed" then
		for _, handle in ipairs(token.removed) do
			handle._destroyed = false
			self._handles[handle._id] = handle
		end
	end
	if token.previousOwners then
		self._compositionOwners = token.previousOwners
		self._compositionControls[token.plan.id] = token.previousControls
		self._compositionOrders = token.previousOrders
	end
	if token.root then token.root:Destroy(); token.root = nil end
	table.clear(token.publicationQueue or {})
	token.retire, token.previousOwners, token.previousControls, token.previousOrders = nil, nil, nil, nil
	token.state = "aborted"
	return restored
end

function ControlHost:ApplyCompositionOrder(parentId: any, snapshot: any, projection: any): (boolean, any?)
	if self._destroyed then return false, fail("destroyed_host", "ControlHost has been destroyed", "applyCompositionOrder") end
	if type(parentId) ~= "string" or type(snapshot) ~= "table" or type(projection) ~= "table" then return false, fail("invalid_composition_order", "Composition order snapshot and projection are required", "applyCompositionOrder") end
	local orders = {}
	for id, order in pairs(projection) do
		if type(id) ~= "string" or type(order) ~= "number" or order < 1 or order ~= math.floor(order) then return false, fail("invalid_composition_order", "Composition order projection is invalid", "applyCompositionOrder") end
		local handle = self._handles[id]
		if handle ~= nil then orders[id] = order end
	end
	self._compositionOrders = self._compositionOrders or {}
	self._compositionOrders[parentId] = table.freeze({ snapshot = snapshot, layout = table.freeze(orders) })
	return true, nil
end
function ControlHost:GetCompositionOrderSnapshot(parentId: any): any return self._compositionOrders and self._compositionOrders[parentId] or nil end

function ControlHost:GetSnapshot()
	local handles = {}
	for id, handle in pairs(self._handles) do handles[id] = copySnapshot(handle) end
	return table.freeze({ ownerId = self._ownerId, destroyed = self._destroyed, controls = table.freeze(handles) })
end
function ControlHost:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	local handles = {}
	for _, handle in pairs(self._handles) do table.insert(handles, handle) end
	for _, handle in ipairs(handles) do handle:Unmount() end
	self._handles = {}
	publish(self)
end

return ControlHost

end

__modules["customization/LayoutEngine"] = function()
--!strict

local Maid = __require("core/Maid")
local LayoutSpec = __require("customization/LayoutSpec")
local StructuredError = __require("core/StructuredError")
local FlowGroup = __require("layout/FlowGroup")

local LayoutEngine = {}
LayoutEngine.__index = LayoutEngine

local function fail(code: string, message: string, operation: string?): any
	return StructuredError.from(code, message, { domain = "layoutEngine", operation = operation or "apply" })
end

local function numberProperty(node: any, name: string, fallback: number): number
	local value = rawget(node, name)
	return if type(value) == "number" and value == value and value >= 0 and value ~= math.huge then value else fallback
end

local function collect(node: any, out: any)
	out[node.id] = table.freeze({ id = node.id, kind = node.kind })
	for _, child in ipairs(rawget(node, "children") or {}) do collect(child, out) end
end

local SHELL_SEMANTIC_IDS = { header = true, navigation = true, body = true, status = true, footer = true }
local function shellMetrics(node: any): any
	local metrics = { header = false, status = false, footer = false, auxiliaryCount = 0 }
	for _, child in ipairs(rawget(node, "children") or {}) do
		if child.id == "header" then metrics.header = true
		elseif child.id == "status" then metrics.status = true
		elseif child.id == "footer" then metrics.footer = true
		elseif not SHELL_SEMANTIC_IDS[child.id] then metrics.auxiliaryCount += 1 end
	end
	metrics.auxiliaryHeight = metrics.auxiliaryCount * 32
	metrics.contentTop = (if metrics.header then 56 else 0) + metrics.auxiliaryHeight
	metrics.contentBottom = (if metrics.status then 24 else 0) + (if metrics.footer then 24 else 0)
	return metrics
end

local function shellPlacement(frame: Frame, id: string, metrics: any, auxiliaryIndex: number?)
	if id == "header" then frame.Position, frame.Size = UDim2.fromOffset(0, 0), UDim2.new(1, 0, 0, 56)
	elseif id == "navigation" then frame.Position, frame.Size = UDim2.fromOffset(0, metrics.contentTop), UDim2.new(0, 208, 1, -metrics.contentTop)
	elseif id == "body" then frame.Position, frame.Size = UDim2.fromOffset(208, metrics.contentTop), UDim2.new(1, -208, 1, -(metrics.contentTop + metrics.contentBottom))
	elseif id == "status" then frame.AnchorPoint, frame.Position, frame.Size = Vector2.new(0, 1), UDim2.new(0, 208, 1, -(if metrics.footer then 24 else 0)), UDim2.new(1, -208, 0, 24)
	elseif id == "footer" then frame.AnchorPoint, frame.Position, frame.Size = Vector2.new(0, 1), UDim2.new(0, 208, 1, 0), UDim2.new(1, -208, 0, 24)
	else frame.Position, frame.Size = UDim2.fromOffset(0, (if metrics.header then 56 else 0) + (math.max(1, auxiliaryIndex or 1) - 1) * 32), UDim2.new(1, 0, 0, 32) end
end

local function splitChildSize(parent: any, node: any): UDim2?
	if parent == nil or parent.kind ~= "split" then return nil end
	local children, total = rawget(parent, "children") or {}, 0
	for _, child in ipairs(children) do total += numberProperty(child, "weight", 1) end
	local weight = numberProperty(node, "weight", 1)
	if total == 0 then total, weight = #children, 1 end
	local share, gap = weight / total, math.floor(numberProperty(parent, "gap", 8))
	local gapOffset = (math.max(0, #children - 1) * gap) * share
	return if rawget(parent, "direction") == "vertical" then UDim2.new(1, 0, share, -gapOffset) else UDim2.new(share, -gapOffset, 1, 0)
end

local function alignment(value: any): Enum.HorizontalAlignment
	if value == "center" then return Enum.HorizontalAlignment.Center end
	if value == "end" then return Enum.HorizontalAlignment.Right end
	return Enum.HorizontalAlignment.Left
end

local capabilityProjection: any
local function capabilityProjection(node: any, capabilitiesById: any): any
	local projection = {}
	for _, child in ipairs(rawget(node, "children") or {}) do
		local capabilities = (capabilitiesById and capabilitiesById[child.id]) or {}
		projection[child.id] = if table.isfrozen(capabilities) then capabilities else table.freeze(table.clone(capabilities))
	end
	return table.freeze(projection)
end

local function installFlow(frame: Frame, node: any, maid: any, actual: any)
	local kind = node.kind
	if kind ~= "stack" and kind ~= "split" and kind ~= "grid" and kind ~= "adaptive" and kind ~= "row" and kind ~= "column" then return end
	local grid = kind == "grid" or ((kind == "row" or kind == "column") and rawget(node, "wrap") == true)
	local layout = Instance.new(if grid then "UIGridLayout" else "UIListLayout")
	layout.Name = "PotassiumLayoutFlow"
	layout.SortOrder = Enum.SortOrder.LayoutOrder
	local gap = math.floor(numberProperty(node, "gap", 8))
	if layout:IsA("UIGridLayout") then
		layout.CellPadding = UDim2.fromOffset(gap, gap)
		layout.CellSize = UDim2.new(0.5, -math.ceil(gap / 2), 0, math.floor(numberProperty(node, "rowHeight", 32)))
		layout.FillDirection = if kind == "column" then Enum.FillDirection.Vertical else Enum.FillDirection.Horizontal
		local maximum = math.floor(numberProperty(node, "maxColumns", 0))
		layout.FillDirectionMaxCells = if kind == "column" and maximum > 0 then math.max(1, math.ceil(#((rawget(node, "children") or {})) / maximum)) else maximum
		layout.HorizontalAlignment = alignment(rawget(node, "align"))
	else
		local horizontal = if kind == "row" then true elseif kind == "column" then false elseif kind == "split" then rawget(node, "direction") ~= "vertical" else rawget(node, "direction") == "horizontal"
		layout.FillDirection = if horizontal then Enum.FillDirection.Horizontal else Enum.FillDirection.Vertical
		layout.Padding = UDim.new(0, gap)
		if kind == "adaptive" then
			local breakpoint = numberProperty(node, "breakpoint", 560)
			local function updateAdaptiveFlow()
				local compact = frame.AbsoluteSize.X > 0 and frame.AbsoluteSize.X < breakpoint
				layout.FillDirection = if compact then Enum.FillDirection.Vertical else if horizontal then Enum.FillDirection.Horizontal else Enum.FillDirection.Vertical
				frame:SetAttribute("PotassiumAdaptiveCompact", compact)
			end
			updateAdaptiveFlow()
			maid:GiveTask(frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(updateAdaptiveFlow))
		end
	end
	layout.Parent = frame
	maid:GiveTask(layout)
	actual.instances += 1
	if kind == "row" or kind == "column" then
		actual._flows[node.id] = table.freeze({ id = node.id, frame = frame, layout = layout, node = node, capabilities = capabilityProjection(node, actual._capabilities) })
	end
end
local function flowMinimum(node: any, capabilitiesById: any): number
	local minimum = numberProperty(node, "minItemWidth", 160)
	for _, child in ipairs(rawget(node, "children") or {}) do
		local capabilities = capabilitiesById[child.id] or {}
		if type(capabilities.minWidth) == "number" then minimum = math.max(minimum, capabilities.minWidth) end
	end
	return minimum
end
local function flowRequiresFullWidth(node: any, capabilitiesById: any, width: number): boolean
	for _, child in ipairs(rawget(node, "children") or {}) do
		local capabilities = capabilitiesById[child.id] or {}
		if capabilities.fullWidth == true or (capabilities.compact == true and width < numberProperty(node, "minItemWidth", 160)) then return true end
	end
	return false
end

local function publicActual(actual: any): any
	local copy = {}
	for key, value in pairs(actual or {}) do if string.sub(key, 1, 1) ~= "_" and typeof(value) ~= "Instance" then copy[key] = value end end
	return table.freeze(copy)
end

local function snapshot(self: any): any
	return table.freeze({ ownerId = self._ownerId, generation = self._generation, revision = self._revision, destroyed = self._destroyed, layout = self._layout, nodes = self._nodes, actual = publicActual(self._actual) })
end

local function renderNode(node: any, parent: any, parentKind: string?, parentNode: any?, shell: any?, maid: any, actual: any, auxiliaryIndex: number?)
	local frame = Instance.new("Frame")
	frame.Name = "PotassiumLayout_" .. node.id
	frame.BackgroundTransparency, frame.BorderSizePixel = 1, 0
	frame.Size = splitChildSize(parentNode, node) or UDim2.fromScale(1, 1)
	frame.LayoutOrder = math.floor(numberProperty(node, "order", actual.layoutNodes))
	frame:SetAttribute("PotassiumLayoutNode", node.id)
	frame:SetAttribute("PotassiumLayoutKind", node.kind)
	frame.Parent = parent
	actual._frames[node.id] = frame
	maid:GiveTask(frame)
	actual.instances += 1
	actual.layoutNodes += 1
	if parentKind == "shell" then shellPlacement(frame, node.id, shell, auxiliaryIndex) end
	if node.kind == "section" or node.kind == "group" then frame.AutomaticSize, frame.Size = Enum.AutomaticSize.Y, UDim2.new(1, 0, 0, 0)
	elseif node.kind == "scroll" then
		frame.ClipsDescendants = true
		frame:SetAttribute("PotassiumScrollable", true)
	elseif node.kind == "overlay" then frame.ZIndex = 10
	elseif node.kind == "dataRegion" then frame:SetAttribute("PotassiumDataRegion", true) end
	installFlow(frame, node, maid, actual)
	if node.kind == "slot" then actual.slots[node.id], actual._slotTargets[node.id] = table.freeze({ id = node.id, role = node.id }), { target = frame } end
	local metrics = if node.kind == "shell" then shellMetrics(node) else nil
	local nextAuxiliaryIndex = 0
	for _, child in ipairs(rawget(node, "children") or {}) do
		local childAuxiliaryIndex: number? = nil
		if node.kind == "shell" and not SHELL_SEMANTIC_IDS[child.id] then nextAuxiliaryIndex += 1; childAuxiliaryIndex = nextAuxiliaryIndex end
		renderNode(child, frame, node.kind, node, metrics, maid, actual, childAuxiliaryIndex)
	end
end

local function stageLayout(self: any, root: any, maid: any, capabilities: any?): (any?, any?)
	local target = self._target
	if typeof(target) ~= "Instance" or not target:IsA("GuiObject") then return { instances = 0, layoutNodes = 0, slots = table.freeze({}), _slotTargets = {}, _flows = {}, _frames = {}, _capabilities = capabilities or {} }, nil end
	local stage = Instance.new("Frame")
	stage.Name, stage.BackgroundTransparency, stage.BorderSizePixel, stage.Size = "PotassiumLayoutStage", 1, 0, UDim2.fromScale(1, 1)
	maid:GiveTask(stage)
	local actual = { instances = 1, layoutNodes = 0, slots = {}, _slotTargets = {}, _flows = {}, _frames = {}, _capabilities = capabilities or {} }
	local ok, renderError = pcall(renderNode, root, stage, nil, nil, nil, maid, actual)
	if not ok then return nil, fail("layout_stage_failed", tostring(renderError)) end
	actual.guiObject, actual.slots = stage, table.freeze(actual.slots)
	return actual, nil
end

function LayoutEngine.new(options: any): (any?, any?)
	if type(options) ~= "table" or type(options.ownerId) ~= "string" then return nil, fail("invalid_layout_engine", "LayoutEngine requires ownerId", "create") end
	return setmetatable({ _ownerId = options.ownerId, _budget = options.budget, _diagnostics = options.diagnostics, _target = options.target, _slotHost = options.slotHost, _layout = nil, _nodes = table.freeze({}), _actual = table.freeze({}), _maid = Maid.new(), _generation = 0, _revision = 0, _destroyed = false, _reflowDirty = false, _reflowTask = false, _compositionOrders = {} }, LayoutEngine), nil
end

function LayoutEngine:_reflow()
	if self._destroyed then return end
	for _, flow in pairs(self._actual._flows or {}) do
		local layout = flow.layout
		if layout and layout:IsA("UIGridLayout") then
			local node, width, gap = flow.node, flow.frame.AbsoluteSize.X, math.floor(numberProperty(flow.node, "gap", 8))
			local capabilities = flow.capabilities or table.freeze({})
			local minimum = flowMinimum(node, capabilities)
			local columns = math.max(1, math.floor((math.max(0, width) + gap) / (minimum + gap)))
			local maximum = math.floor(numberProperty(node, "maxColumns", 0))
			local singleColumn = flowRequiresFullWidth(node, capabilities, width)
			for _, child in ipairs(rawget(node, "children") or {}) do
				if (capabilities[child.id] or {}).canWrap == false then singleColumn = true break end
			end
			if singleColumn then columns = 1 elseif maximum > 0 then columns = math.min(columns, maximum) end
			local cellWidth = math.max(0, (width - gap * (columns - 1)) / columns)
			-- Vertical grids fill rows before columns.  Convert the requested
			-- column cap into a row cap so MaxColumns is honored in either flow.
			if node.kind == "column" then
				layout.FillDirectionMaxCells = if singleColumn then math.max(1, #((rawget(node, "children") or {})) ) elseif maximum > 0 then math.max(1, math.ceil(#((rawget(node, "children") or {})) / maximum)) else 0
			else
				layout.FillDirectionMaxCells = columns
			end
			layout.CellSize = UDim2.fromOffset(cellWidth, math.floor(numberProperty(node, "rowHeight", 32)))
	end
	end
end

function LayoutEngine:RequestReflow(_: any?): boolean
	if self._destroyed or self._reflowDirty then return false end
	self._reflowDirty = true
	local generation = self._generation
	local actual = self._actual
	self._reflowTask = true
	task.defer(function()
		if self._destroyed or self._generation ~= generation or self._actual ~= actual then
			-- Only the callback for the current generation may clear its gate.
			return
		end
		self._reflowDirty, self._reflowTask = false, false
		self:_reflow()
	end)
	return true
end

function LayoutEngine:RegisterFlowGroup(nodeId: any): (any?, any?)
	if self._destroyed then return nil, fail("destroyed_layout_engine", "LayoutEngine has been destroyed", "flow") end
	if type(nodeId) ~= "string" or (self._actual._flows or {})[nodeId] == nil then return nil, fail("unknown_flow_group", "Flow node is not realized", "flow") end
	return FlowGroup.new(self, nodeId)
end

function LayoutEngine:GetFlowSnapshot(nodeId: any): any
	local flow = (self._actual._flows or {})[nodeId]
	if flow == nil then return table.freeze({ id = nodeId, realized = false }) end
	return table.freeze({ id = nodeId, realized = true, generation = self._generation, wrap = rawget(flow.node, "wrap") == true, gap = numberProperty(flow.node, "gap", 8), minItemWidth = rawget(flow.node, "minItemWidth"), maxColumns = rawget(flow.node, "maxColumns"), align = rawget(flow.node, "align") or "start", capabilities = flow.capabilities or table.freeze({}) })
end

function LayoutEngine:Apply(specification: any): (boolean, any?)
	if self._destroyed then return false, fail("destroyed_layout_engine", "LayoutEngine has been destroyed") end
	local parsed, parseError = LayoutSpec.Parse(specification); if parsed == nil then return false, parseError end
	local nodes = {}; collect(parsed.root, nodes); nodes = table.freeze(nodes)
	local nextGeneration, tx, nodeCount, flowCount = self._generation + 1, self._ownerId .. ".layout." .. tostring(self._generation + 1), 0, 0
	for _, node in pairs(nodes) do nodeCount += 1; if node.kind == "stack" or node.kind == "split" or node.kind == "grid" or node.kind == "adaptive" or node.kind == "row" or node.kind == "column" then flowCount += 1 end end
	local reservation = { layoutNodes = nodeCount, instances = nodeCount + flowCount + 1, connections = flowCount, tasks = 1 }
	if self._budget then local reserved, reserveError = self._budget:Reserve(tx, self._ownerId, nextGeneration, reservation); if not reserved then return false, reserveError end end
	local staged = Maid.new()
	local actual, stageError = stageLayout(self, parsed.root, staged)

	if actual == nil then staged:Destroy(); if self._budget then self._budget:Release(tx, self._ownerId, nextGeneration) end; return false, stageError end
	if self._budget then
		local reconciled, reconcileError = self._budget:Reconcile(tx, self._ownerId, nextGeneration, { instances = actual.instances or 0, layoutNodes = actual.layoutNodes or 0, connections = flowCount, tasks = 1 })
		if not reconciled then staged:Destroy(); self._budget:Release(tx, self._ownerId, nextGeneration); return false, reconcileError end
	end
	local previousSlots = nil
	if self._slotHost ~= nil then
		if type(self._slotHost.ReplaceLayoutSlots) ~= "function" then staged:Destroy(); if self._budget then self._budget:Release(tx, self._ownerId, nextGeneration) end; return false, fail("slot_host_unavailable", "LayoutEngine requires a compatible SlotHost") end
		local replaceError; previousSlots, replaceError = self._slotHost:ReplaceLayoutSlots(self._ownerId, actual._slotTargets)
		if previousSlots == nil then staged:Destroy(); if self._budget then self._budget:Release(tx, self._ownerId, nextGeneration) end; return false, replaceError end
	end
	local parentOk, parentError = pcall(function() if actual.guiObject then actual.guiObject.Parent = self._target end end)
	if not parentOk then if self._slotHost ~= nil then self._slotHost:ReplaceLayoutSlots(self._ownerId, previousSlots or {}) end; staged:Destroy(); if self._budget then self._budget:Release(tx, self._ownerId, nextGeneration) end; return false, fail("layout_publish_failed", tostring(parentError)) end
	local oldMaid, oldTx, oldGeneration = self._maid, self._transactionId, self._generation
	self._layout, self._nodes, self._actual, self._maid, self._generation, self._revision, self._transactionId = parsed, nodes, table.freeze(actual), staged, nextGeneration, self._revision + 1, tx
	self._compositionOrders, self._compositionBaselines = {}, {}
	self._reflowDirty, self._reflowTask = false, false
	for _, flow in pairs(actual._flows) do staged:GiveTask(flow.frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() self:RequestReflow(flow.id) end)) end
	self:RequestReflow()
	if self._diagnostics and type(self._diagnostics.Publish) == "function" then pcall(function() self._diagnostics:Publish("layout", self:GetSnapshot(), { ownerId = self._ownerId, transactionId = tx }) end) end
	if oldMaid then task.defer(function() oldMaid:Destroy(); if self._budget and oldTx then self._budget:Release(oldTx, self._ownerId, oldGeneration) end end) end
	return true, nil
end

local function compositionFrame(frames: any, id: string, layoutIds: any?): any
	local frame = frames and frames[id]
	if frame ~= nil then return frame end
	local layoutId = type(layoutIds) == "table" and layoutIds[id] or nil
	return if layoutId ~= nil and frames ~= nil then frames[layoutId] else nil
end
function LayoutEngine:ApplyCompositionOrder(parentId: any, snapshot: any, projection: any): (boolean, any?)
	if self._destroyed then return false, fail("destroyed_layout_engine", "LayoutEngine has been destroyed", "applyCompositionOrder") end
	if type(parentId) ~= "string" or type(snapshot) ~= "table" or type(projection) ~= "table" then return false, fail("invalid_composition_order", "Composition order snapshot and projection are required", "applyCompositionOrder") end
	local copied = {}
	for id, order in pairs(projection) do
		if type(id) ~= "string" or type(order) ~= "number" or order ~= math.floor(order) or order < 1 then return false, fail("invalid_composition_order", "Composition layout projection must map ids to positive integer orders", "applyCompositionOrder") end
		copied[id] = order
	end
	local frames = {}
	for id, order in pairs(copied) do
		local frame = compositionFrame(self._actual._frames, id, self._compositionLayoutIds)
		if frame == nil then return false, fail("unresolved_composition_order", "Composition order id is not realized by the layout", "applyCompositionOrder") end
		table.insert(frames, { frame = frame, order = order })
	end
	self._compositionBaselines = self._compositionBaselines or {}
	local baseline = self._compositionBaselines[parentId] or {}
	for _, entry in ipairs(frames) do
		if baseline[entry.frame] == nil then baseline[entry.frame] = entry.frame.LayoutOrder end
	end
	self._compositionBaselines[parentId] = baseline
	for _, entry in ipairs(frames) do entry.frame.LayoutOrder = entry.order end
	self._compositionOrders[parentId] = table.freeze({ generation = self._generation, snapshot = snapshot, layout = table.freeze(copied) })
	self:RequestReflow(parentId)
	return true, nil
end
function LayoutEngine:GetCompositionOrderSnapshot(parentId: any): any return self._compositionOrders[parentId] end
function LayoutEngine:ClearCompositionOrder(parentId: any): boolean
	if type(parentId) ~= "string" then return false end
	local baseline = self._compositionBaselines and self._compositionBaselines[parentId]
	if baseline then
		for frame, order in pairs(baseline) do frame.LayoutOrder = order end
		self._compositionBaselines[parentId] = nil
		self:RequestReflow(parentId)
	end
	self._compositionOrders[parentId] = nil
	return true
end
function LayoutEngine:PrepareComposition(plan: any): (any?, any?)
	if self._destroyed or type(plan) ~= "table" then return nil, fail("invalid_composition_plan", "Layout composition plan is required", "prepareComposition") end
	if plan.layout == nil then return { state = "prepared", layout = nil }, nil end
	local parsed, parseError = LayoutSpec.Parse(plan.layout)
	if parsed == nil then return nil, parseError end
	local capabilities = {}
	local function collectControls(node: any)
		if type(node) ~= "table" then return end
		if type(node.layout) == "table" and type(node.id) == "string" then
			local layoutId = type(plan.layoutIds) == "table" and plan.layoutIds[node.id] or node.id
			capabilities[layoutId] = node.layout
		end
		for _, child in ipairs(node.children or {}) do collectControls(child) end
	end
	collectControls(plan.descriptor)
	return { state = "prepared", layout = parsed, capabilities = table.freeze(capabilities), plan = plan, layoutIds = plan.layoutIds }, nil
end

function LayoutEngine:StageComposition(token: any): (boolean, any?)
	if type(token) ~= "table" or token.state ~= "prepared" then return false, fail("invalid_composition_transaction", "Layout composition transaction must be prepared", "stageComposition") end
	if token.layout ~= nil then
		local nodes = {}; collect(token.layout.root, nodes)
		local flowCount, nodeCount = 0, 0
		for _, node in pairs(nodes) do
			nodeCount += 1
			if node.kind == "stack" or node.kind == "split" or node.kind == "grid" or node.kind == "adaptive" or node.kind == "row" or node.kind == "column" then flowCount += 1 end
		end
		token.generation, token.tx = self._generation + 1, self._ownerId .. ".layout." .. tostring(self._generation + 1)
		if self._budget then
			local reserved, reserveError = self._budget:Reserve(token.tx, self._ownerId, token.generation, { layoutNodes = nodeCount, instances = nodeCount + flowCount + 1, connections = flowCount, tasks = 1 })
			if not reserved then return false, reserveError end
		end
		local maid = Maid.new()
		local actual, stageError = stageLayout(self, token.layout.root, maid, token.capabilities)
		if actual == nil then maid:Destroy(); if self._budget then self._budget:Release(token.tx, self._ownerId, token.generation) end; return false, stageError end
		if self._slotHost ~= nil then
			if type(self._slotHost.ValidateLayoutSlots) ~= "function" then maid:Destroy(); if self._budget then self._budget:Release(token.tx, self._ownerId, token.generation) end; return false, fail("slot_host_unavailable", "LayoutEngine requires layout-slot preflight support", "stageComposition") end
			local validated, validationError = self._slotHost:ValidateLayoutSlots(self._ownerId, actual._slotTargets)
			if validated == nil then maid:Destroy(); if self._budget then self._budget:Release(token.tx, self._ownerId, token.generation) end; return false, validationError end
		end
		if self._budget then
			local reconciled, reconcileError = self._budget:Reconcile(token.tx, self._ownerId, token.generation, { instances = actual.instances or 0, layoutNodes = actual.layoutNodes or 0, connections = flowCount, tasks = 1 })
			if not reconciled then maid:Destroy(); self._budget:Release(token.tx, self._ownerId, token.generation); return false, reconcileError end
		end
		token.maid, token.actual, token.nodes = maid, actual, table.freeze(nodes)
		token.plan.layoutFrames, token.plan.layoutSlotTargets = actual._frames, actual._slotTargets
	end
	token.state = "staged"
	return true, nil
end

function LayoutEngine:PreflightCompositionOrder(token: any, parentId: any, _: any, projection: any): (boolean, any?)
	if type(token) == "string" then
		projection, parentId, token = _, token, nil
	end
	if type(parentId) ~= "string" or type(projection) ~= "table" then return false, fail("invalid_composition_order", "A layout order is required", "preflightCompositionOrder") end
	if token ~= nil and (type(token) ~= "table" or token.state ~= "staged") then return false, fail("invalid_composition_transaction", "Composition transaction must be staged", "preflightCompositionOrder") end
	local actual, assignments = (token and token.actual) or self._actual, {}
	for id, order in pairs(projection) do
		local frame = compositionFrame(actual._frames, id, (token and token.layoutIds) or self._compositionLayoutIds)
		if type(id) ~= "string" or type(order) ~= "number" or order ~= math.floor(order) or order < 1 or frame == nil then return false, fail("unresolved_composition_order", "Composition order id is not realized by the layout", "preflightCompositionOrder") end
		table.insert(assignments, { frame = frame, order = order })
	end
	return true, nil
end

function LayoutEngine:CommitComposition(token: any): (boolean, any?)
	if type(token) ~= "table" or token.state ~= "staged" then return false, fail("invalid_composition_transaction", "Layout composition transaction must be staged", "commitComposition") end
	if token.actual ~= nil then
		local actual = token.actual
		if self._slotHost ~= nil then
			if type(self._slotHost.ReplaceLayoutSlots) ~= "function" then return false, fail("slot_host_unavailable", "LayoutEngine requires a compatible SlotHost", "commitComposition") end
			token.slotTransaction = {}
			local previousSlots, slotError = self._slotHost:ReplaceLayoutSlots(self._ownerId, actual._slotTargets, token.slotTransaction)
			if previousSlots == nil then return false, slotError end
		end
		local ok, parentError = pcall(function() if actual.guiObject then actual.guiObject.Parent = self._target end end)
		if not ok then
			if token.slotTransaction and token.slotTransaction.rollback then token.slotTransaction.rollback(); token.slotTransaction = nil end
			return false, fail("layout_publish_failed", tostring(parentError), "commitComposition")
		end
		token.previous = {
			layout = self._layout, nodes = self._nodes, actual = self._actual, maid = self._maid,
			generation = self._generation, revision = self._revision, tx = self._transactionId,
			layoutIds = self._compositionLayoutIds, orders = table.clone(self._compositionOrders), baselines = self._compositionBaselines,
		}
		self._layout, self._nodes, self._actual, self._maid, self._generation, self._revision, self._transactionId = token.layout, token.nodes, table.freeze(actual), token.maid, token.generation, self._revision + 1, token.tx
		self._compositionLayoutIds = token.layoutIds
		self._compositionBaselines = {}
		self._reflowDirty, self._reflowTask = false, false
		for _, flow in pairs(actual._flows) do token.maid:GiveTask(flow.frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() self:RequestReflow(flow.id) end)) end
		self:RequestReflow()
	end
	token.state = "committed"
	return true, nil
end

function LayoutEngine:FinalizeComposition(token: any): boolean
	if type(token) ~= "table" or token.state ~= "committed" then return false end
	token.state = "finalized"
	if token.slotTransaction and token.slotTransaction.finalize then token.slotTransaction.finalize() end
	local old = token.previous
	if old then
		task.defer(function()
			old.maid:Destroy()
			if self._budget and old.tx then self._budget:Release(old.tx, self._ownerId, old.generation) end
		end)
	end
	token.previous, token.slotTransaction = nil, nil
	return true
end

function LayoutEngine:AbortComposition(token: any): boolean
	if type(token) ~= "table" or token.state == "finalized" or token.state == "aborted" then return false end
	if token.slotTransaction and token.slotTransaction.rollback then token.slotTransaction.rollback() end
	local old = token.previous
	if old then
		self._layout, self._nodes, self._actual, self._maid, self._generation, self._revision, self._transactionId =
			old.layout, old.nodes, old.actual, old.maid, old.generation, old.revision, old.tx
		self._compositionLayoutIds, self._compositionOrders = old.layoutIds, old.orders
		self._compositionBaselines = old.baselines
		self._reflowDirty, self._reflowTask = false, false
		self:RequestReflow()
	end
	if token.maid then token.maid:Destroy() end
	if self._budget and token.tx and token.generation then self._budget:Release(token.tx, self._ownerId, token.generation) end
	token.previous, token.slotTransaction = nil, nil
	token.state = "aborted"
	return true
end

function LayoutEngine:GetSnapshot(): any return snapshot(self) end
function LayoutEngine:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	self._generation += 1
	self._maid:Destroy()
	if self._slotHost and type(self._slotHost.ReplaceLayoutSlots) == "function" then self._slotHost:ReplaceLayoutSlots(self._ownerId, {}) end
	if self._budget and self._transactionId then self._budget:Release(self._transactionId, self._ownerId, self._generation - 1) end
end

return LayoutEngine


end

__modules["customization/LayoutSpec"] = function()
--!strict

local SchemaCodec = __require("customization/SchemaCodec")
local StructuredError = __require("core/StructuredError")

local LayoutSpec = {}
local KINDS = { shell = true, routeStack = true, split = true, stack = true, grid = true, row = true, column = true, section = true, group = true, scroll = true, overlay = true, slot = true, dataRegion = true, adaptive = true }
local MAX_NODES, MAX_CHILDREN, MAX_DEPTH = 256, 32, 16

local TOP_LEVEL_FIELDS = { kind = true, id = true, root = true }
local COMMON_NODE_FIELDS = { id = true, kind = true, order = true, weight = true }
local NODE_FIELDS = {
	shell = { children = true },
	routeStack = { children = true },
	split = { children = true, direction = true, gap = true },
	stack = { children = true, direction = true, gap = true },
	grid = { children = true, gap = true, rowHeight = true },
	row = { children = true, wrap = true, gap = true, minItemWidth = true, maxColumns = true, align = true, flex = true, weight = true },
	column = { children = true, wrap = true, gap = true, minItemWidth = true, maxColumns = true, align = true, flex = true, weight = true },
	group = { children = true },
	section = { children = true },
	scroll = { children = true },
	overlay = { children = true },
	slot = {},
	dataRegion = { children = true },
	adaptive = { children = true, direction = true, gap = true, breakpoint = true },
}
for _, fields in pairs(NODE_FIELDS) do
	for name in pairs(COMMON_NODE_FIELDS) do fields[name] = true end
end

local function closed(value: any, fields: { [string]: boolean }, path: string): any?
	for key in pairs(value) do
		if type(key) ~= "string" or not fields[key] then
			return StructuredError.from("unknown_layout_field", "Layout contains an unknown field", {
				domain = "layoutSpec",
				operation = "validate",
				path = path .. "." .. tostring(key),
			})
		end
	end
	return nil
end

local function isFinite(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

local function validateNumberField(node: any, name: string, path: string): any?
	local value = rawget(node, name)
	if value ~= nil and not isFinite(value) then
		return StructuredError.from("invalid_layout_field", "Layout numeric fields must be finite numbers", {
			domain = "layoutSpec",
			operation = "validate",
			path = path .. "." .. name,
		})
	end
	return nil
end

local function fail(code: string, message: string, path: string): any
	return StructuredError.from(code, message, { domain = "layoutSpec", operation = "validate", path = path })
end

local function validateFlow(node: any, path: string): any?
	for _, name in ipairs({ "gap", "flex", "weight" }) do
		local value = rawget(node, name)
		if value ~= nil and (not isFinite(value) or value < 0) then return fail("invalid_layout_field", "Flow gap, flex, and weight must be finite nonnegative numbers", path .. "." .. name) end
	end
	local minItemWidth = rawget(node, "minItemWidth")
	if minItemWidth ~= nil and (not isFinite(minItemWidth) or minItemWidth <= 0) then return fail("invalid_layout_field", "Flow minItemWidth must be a finite positive number", path .. ".minItemWidth") end
	local maxColumns = rawget(node, "maxColumns")
	if maxColumns ~= nil and (not isFinite(maxColumns) or maxColumns < 1 or maxColumns ~= math.floor(maxColumns)) then return fail("invalid_layout_field", "Flow maxColumns must be a positive integer", path .. ".maxColumns") end
	local wrap = rawget(node, "wrap")
	if wrap ~= nil and type(wrap) ~= "boolean" then return fail("invalid_layout_field", "Flow wrap must be a boolean", path .. ".wrap") end
	local align = rawget(node, "align")
	if align ~= nil and align ~= "start" and align ~= "center" and align ~= "end" then return fail("invalid_layout_field", "Flow align must be start, center, or end", path .. ".align") end
	return nil
end

local SHELL_SEMANTIC_IDS = { header = true, navigation = true, body = true, status = true, footer = true }

local function validateShellChildren(children: any, path: string): any?
	local regions = {}
	for index, child in ipairs(children) do
		if type(child) == "table" then
			local id = rawget(child, "id")
			if type(id) == "string" and SHELL_SEMANTIC_IDS[id] then
				if regions[id] then
					return fail("duplicate_shell_region", "Shell semantic child ids must be unique", path .. "[" .. tostring(index) .. "].id")
				end
				regions[id] = true
			end
		end
	end
	return nil
end

local function denseArray(value: any): boolean
	if type(value) ~= "table" then return false end
	local length = #value
	for index = 1, length do
		if rawget(value, index) == nil then return false end
	end
	for key in pairs(value) do
		if type(key) ~= "number" or key < 1 or key > length or key ~= math.floor(key) then return false end
	end
	return true
end
local function validateNode(codec: any, node: any, path: string, depth: number, state: any): any
	if depth > MAX_DEPTH then return fail("layout_depth_limit", "Layout exceeds maximum depth", path) end
	if type(node) ~= "table" then return fail("invalid_layout_node", "Layout nodes must be tables", path) end
	state.count += 1; if state.count > MAX_NODES then return fail("layout_node_limit", "Layout exceeds maximum node count", path) end
	local id, idError = codec:ParseLocalId(rawget(node, "id"), path .. ".id"); if id == nil then return idError end
	if state.ids[id] then return fail("duplicate_layout_id", "Layout node ids must be unique", path .. ".id") end
	state.ids[id] = true
	local kind = rawget(node, "kind"); if type(kind) ~= "string" or not KINDS[kind] then return fail("invalid_layout_kind", "Layout node kind is unsupported", path .. ".kind") end
	local closedError = closed(node, NODE_FIELDS[kind], path); if closedError then return closedError end
	for _, name in ipairs({ "order", "weight", "gap", "rowHeight", "breakpoint" }) do
		local fieldError = validateNumberField(node, name, path)
		if fieldError then return fieldError end
	end
	local gap = rawget(node, "gap")
	if gap ~= nil and gap < 0 then return fail("invalid_layout_field", "Layout gap must be nonnegative", path .. ".gap") end
	local direction = rawget(node, "direction")
	if direction ~= nil and direction ~= "horizontal" and direction ~= "vertical" then
		return fail("invalid_layout_field", "Layout direction must be horizontal or vertical", path .. ".direction")
	end
	if kind == "row" or kind == "column" then
		local flowError = validateFlow(node, path)
		if flowError then return flowError end
	end
	local children = rawget(node, "children")
	if kind == "slot" then
		if children ~= nil then return fail("invalid_layout_children", "Slot nodes cannot have children", path .. ".children") end
	elseif children ~= nil then
		if not denseArray(children) or #children > MAX_CHILDREN then return fail("invalid_layout_children", "Layout children must be a bounded dense array", path .. ".children") end
		if kind == "shell" then
			local shellError = validateShellChildren(children, path .. ".children")
			if shellError then return shellError end
		end
		for index, child in ipairs(children) do
			local childError = validateNode(codec, child, path .. ".children[" .. tostring(index) .. "]", depth + 1, state)
			if childError then return childError end
		end
	end
	return nil
end
function LayoutSpec.Parse(value: any): (any?, any?)
	local codec = SchemaCodec.new(); local portable, scanError = codec:PreScanPortable(value, "layout")
	if not portable then return nil, scanError end
	if type(value) ~= "table" then return nil, fail("invalid_layout", "Layout must be a table", "layout") end
	local closedError = closed(value, TOP_LEVEL_FIELDS, "layout"); if closedError then return nil, closedError end
	if rawget(value, "kind") ~= "layout" then return nil, fail("invalid_layout_kind", "Layout kind must be layout", "layout.kind") end
	local id, idError = codec:ParseNamespacedId(rawget(value, "id"), "layout.id"); if id == nil then return nil, idError end
	local root = rawget(value, "root"); local nodeError = validateNode(codec, root, "layout.root", 1, { count = 0, ids = {} }); if nodeError then return nil, nodeError end
	local normalized, normalizeError = codec:Normalize(value); if normalized == nil then return nil, normalizeError end
	return normalized, nil
end
function LayoutSpec.Stock(id: string?): any
	return table.freeze({ kind = "layout", id = id or "stock:shell", root = {
		kind = "shell", id = "shell", children = {
			{ kind = "slot", id = "header" }, { kind = "slot", id = "navigation" },
			{ kind = "routeStack", id = "body", children = { { kind = "slot", id = "content" } } },
			{ kind = "slot", id = "status" }, { kind = "slot", id = "footer" },
		},
	} })
end
return table.freeze(LayoutSpec)

end

__modules["customization/MaterialRenderer"] = function()
--!strict

local StructuredError = __require("core/StructuredError")
local DefaultMaid = __require("core/Maid")
local DefaultFactory = __require("ui/Factory")
local AssetPolicy = __require("customization/AssetPolicy")

export type StructuredErrorValue = StructuredError.StructuredError
export type MaterialHandle = {
	Update: (self: MaterialHandle, material: any) -> (boolean, StructuredErrorValue?),
	Replace: (self: MaterialHandle, material: any) -> (boolean, StructuredErrorValue?),
	Destroy: (self: MaterialHandle) -> (),
	GetSnapshot: (self: MaterialHandle) -> any,
}
export type MaterialRenderer = {
	Render: (self: MaterialRenderer, parent: any, compiled: any, role: any, options: any?) -> (MaterialHandle?, StructuredErrorValue?),
	Destroy: (self: MaterialRenderer) -> (),
	GetSnapshot: (self: MaterialRenderer) -> any,
}

local MaterialRenderer = {}
MaterialRenderer.__index = MaterialRenderer

local MAX_NODES = 32
local MAX_KEYPOINTS = 8
local MAX_IMAGES = 8
local MAX_ROLE_LENGTH = 96

local function failure(code: string, message: string, operation: string, path: string?, details: any?): StructuredErrorValue
	return StructuredError.from(code, message, { domain = "materialRenderer", operation = operation, path = path, details = details })
end

local function freeze(value: any): any
	if type(value) ~= "table" then return value end
	local result = {}
	for key, item in pairs(value) do result[key] = freeze(item) end
	return table.freeze(result)
end

local function emptyCost(): any
	return {
		instances = 0, descendants = 0, gradients = 0, strokes = 0, images = 0, sounds = 0, animations = 0,
		particles = 0, materialNodes = 0, slots = 0, layoutNodes = 0, virtualRows = 0, virtualCells = 0,
		connections = 0, workers = 0, tasks = 0, retainedItems = 0, perRowInstances = 0, updatesPerSecond = 0,
		logicalBlurRequests = 0,
	}
end

local function increment(cost: any, className: string)
	cost.instances += 1
	cost.descendants += 1
	if className == "UIGradient" then cost.gradients += 1 end
	if className == "UIStroke" then cost.strokes += 1 end
	if className == "ImageLabel" then cost.images += 1 end
end

local function publish(self: any, event: string, details: any)
	local diagnostics = self._diagnostics
	if type(diagnostics) == "table" and type(diagnostics.Publish) == "function" then
		pcall(function()
			diagnostics:Publish("materialRenderer", freeze({ event = event, details = details }), self._diagnosticOptions)
		end)
	end
end

local function validParent(parent: any): boolean
	return typeof(parent) == "Instance" and parent:IsA("GuiObject")
end

local function validRole(role: any): boolean
	return type(role) == "string" and #role > 0 and #role <= MAX_ROLE_LENGTH and string.match(role, "^[A-Za-z][A-Za-z0-9._:-]*$") ~= nil
end

local function isFinite(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

-- Compiled skins are portable, so colors cross the compiler/renderer boundary as
-- canonical #RRGGBB strings. Keep Color3 support for direct host-side rendering.
local function color(value: any, path: string): (Color3?, StructuredErrorValue?)
	if typeof(value) == "Color3" then return value, nil end
	if type(value) == "string" and #value == 7 and string.sub(value, 1, 1) == "#" then
		local hex = string.sub(value, 2)
		if string.match(hex, "^[%x]+$") ~= nil then
			local packed = tonumber(hex, 16)
			if packed ~= nil then
				return Color3.fromRGB(math.floor(packed / 65536) % 256, math.floor(packed / 256) % 256, packed % 256), nil
			end
		end
	end
	return nil, failure("invalid_material_color", "Material colors must be Color3 values or portable #RRGGBB strings", "preflight", path)
end

local function number(value: any, minimum: number, maximum: number, path: string): (number?, StructuredErrorValue?)
	if not isFinite(value) or value < minimum or value > maximum then return nil, failure("invalid_material_number", "Material number is out of bounds", "preflight", path, { minimum = minimum, maximum = maximum }) end
	return value, nil
end

local function stringField(value: any, path: string): (string?, StructuredErrorValue?)
	if type(value) ~= "string" or #value == 0 or #value > 96 then return nil, failure("invalid_material_field", "Material field must be a bounded string", "preflight", path) end
	return value, nil
end

local function closed(value: any, fields: { [string]: boolean }, path: string): StructuredErrorValue?
	if type(value) ~= "table" then
		return failure("invalid_material", "Material values must be tables", "preflight", path)
	end
	for key in pairs(value) do
		if type(key) ~= "string" or not fields[key] then
			return failure("unknown_material_field", "Material contains an unknown field", "preflight", path .. "." .. tostring(key))
		end
	end
	return nil
end

local MATERIAL_FIELDS = table.freeze({ nodes = true })
local NODE_FIELDS = table.freeze({
	surface = table.freeze({ kind = true, color = true, transparency = true }),
	border = table.freeze({ kind = true, color = true, thickness = true, transparency = true }),
	corner = table.freeze({ kind = true, radius = true }),
	gradient = table.freeze({ kind = true, colors = true, rotation = true }),
	image = table.freeze({ kind = true, asset = true }),
})
local KEYPOINT_FIELDS = table.freeze({ time = true, color = true })

local function denseArray(value: any): boolean
	if type(value) ~= "table" then return false end
	local length = #value
	for index = 1, length do
		if rawget(value, index) == nil then return false end
	end
	for key in pairs(value) do
		if type(key) ~= "number" or key < 1 or key > length or key ~= math.floor(key) then return false end
	end
	return true
end

local function make(self: any, className: string, properties: any, parent: Instance?): (Instance?, StructuredErrorValue?)
	local factory = self._factory
	local ok, instance = pcall(function()
		if type(factory) == "table" and type(factory.make) == "function" then return factory.make(className, properties, parent) end
		return DefaultFactory.make(className, properties, parent)
	end)
	if not ok or typeof(instance) ~= "Instance" then return nil, failure("material_allocation_failed", "Factory could not allocate a material primitive", "stage", "$.material", { className = className }) end
	return instance, nil
end
local function primitiveCost(nodes: { any }): any
	local cost = emptyCost()
	-- The detached staging frame is an owned UI instance too, and therefore belongs in
	-- the reservation upper bound before any allocation occurs.
	increment(cost, "Frame")
	for _, node in ipairs(nodes) do
		cost.materialNodes += 1
		increment(cost, node.className)
	end
	return freeze(cost)
end

-- The renderer accepts only a closed portable material wrapper.
local function parseMaterial(self: any, material: any, path: string, owner: any?): ({ any }?, StructuredErrorValue?)
	local rawNodes
	if type(material) == "table" and rawget(material, "kind") ~= nil then
		rawNodes = { material }
	else
		local wrapperErr = closed(material, MATERIAL_FIELDS, path)
		if wrapperErr ~= nil then return nil, wrapperErr end
		rawNodes = rawget(material, "nodes")
	end
	if not denseArray(rawNodes) or #rawNodes == 0 or #rawNodes > MAX_NODES then return nil, failure("material_node_limit", "Material nodes must be a bounded dense array", "preflight", path .. ".nodes", { limit = MAX_NODES }) end
	local nodes, imageCount = {}, 0
	local policyLimit = MAX_IMAGES
	if type(self._assetPolicy.GetSnapshot) == "function" then
		local snapshot = self._assetPolicy:GetSnapshot()
		if type(snapshot) == "table" and type(snapshot.maxAssets) == "number" then policyLimit = math.min(policyLimit, snapshot.maxAssets) end
	end
	for index, raw in ipairs(rawNodes) do
		if type(raw) ~= "table" then return nil, failure("invalid_material_node", "Material nodes must be tables", "preflight", path .. ".nodes[" .. index .. "]") end
		local kind, kindErr = stringField(rawget(raw, "kind"), path .. ".nodes[" .. index .. "].kind")
		if kind == nil then return nil, kindErr end
		local nodeFields = NODE_FIELDS[kind]
		if nodeFields == nil then return nil, failure("unsupported_material_node", "Material node kind is not supported", "preflight", path .. ".nodes[" .. index .. "].kind", { kind = kind }) end
		local nodeSchemaErr = closed(raw, nodeFields, path .. ".nodes[" .. index .. "]")
		if nodeSchemaErr ~= nil then return nil, nodeSchemaErr end
		local node: any = { kind = kind }
		if kind == "surface" then
			local fill, err = color(rawget(raw, "color"), path .. ".nodes[" .. index .. "].color")
			if fill == nil then return nil, err end
			local transparency, transErr = number(rawget(raw, "transparency") or 0, 0, 1, path .. ".nodes[" .. index .. "].transparency")
			if transparency == nil then return nil, transErr end
			node.className, node.properties = "Frame", { Name = "PotassiumMaterialSurface", BackgroundColor3 = fill, BackgroundTransparency = transparency, BorderSizePixel = 0, Active = false, Size = UDim2.fromScale(1, 1) }
		elseif kind == "border" then
			local strokeColor, err = color(rawget(raw, "color"), path .. ".nodes[" .. index .. "].color")
			if strokeColor == nil then return nil, err end
			local thickness, thickErr = number(rawget(raw, "thickness") or 1, 0, 32, path .. ".nodes[" .. index .. "].thickness")
			if thickness == nil then return nil, thickErr end
			local transparency, transErr = number(rawget(raw, "transparency") or 0, 0, 1, path .. ".nodes[" .. index .. "].transparency")
			if transparency == nil then return nil, transErr end
			node.className, node.properties = "UIStroke", { Name = "PotassiumMaterialBorder", Color = strokeColor, Thickness = thickness, Transparency = transparency, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }
		elseif kind == "corner" then
			local radius, radiusErr = number(rawget(raw, "radius") or 0, 0, 512, path .. ".nodes[" .. index .. "].radius")
			if radius == nil then return nil, radiusErr end
			node.className, node.properties = "UICorner", { Name = "PotassiumMaterialCorner", CornerRadius = UDim.new(0, radius) }
		elseif kind == "gradient" then
			local colors = rawget(raw, "colors")
			if not denseArray(colors) or #colors < 2 or #colors > MAX_KEYPOINTS then return nil, failure("invalid_gradient", "Gradients need bounded dense color keypoints", "preflight", path .. ".nodes[" .. index .. "].colors") end
			local keypoints = {}
			for pointIndex, point in ipairs(colors) do
				local pointSchemaErr = closed(point, KEYPOINT_FIELDS, path .. ".nodes[" .. index .. "].colors[" .. pointIndex .. "]")
				if pointSchemaErr ~= nil then return nil, pointSchemaErr end
				local time, timeErr = number(rawget(point, "time"), 0, 1, path .. ".nodes[" .. index .. "].colors[" .. pointIndex .. "].time")
				if time == nil then return nil, timeErr end
				if pointIndex > 1 and time <= keypoints[pointIndex - 1].Time then return nil, failure("invalid_gradient", "Gradient times must be strictly increasing", "preflight", path) end
				local pointColor, colorErr = color(rawget(point, "color"), path .. ".nodes[" .. index .. "].colors[" .. pointIndex .. "].color")
				if pointColor == nil then return nil, colorErr end
				keypoints[pointIndex] = ColorSequenceKeypoint.new(time, pointColor)
			end
			if keypoints[1].Time ~= 0 or keypoints[#keypoints].Time ~= 1 then return nil, failure("invalid_gradient_endpoints", "Gradient keypoints must begin at time 0 and end at time 1", "preflight", path .. ".nodes[" .. index .. "].colors") end
			local rotation, rotationErr = number(rawget(raw, "rotation") or 0, -360, 360, path .. ".nodes[" .. index .. "].rotation")
			if rotation == nil then return nil, rotationErr end
			node.className, node.properties = "UIGradient", { Name = "PotassiumMaterialGradient", Color = ColorSequence.new(keypoints), Rotation = rotation }
		else
			imageCount += 1
			if imageCount > policyLimit then return nil, failure("material_image_limit", "Material image count exceeds the configured limit", "preflight", path, { limit = policyLimit }) end
			local admitted, assetErr = self._assetPolicy:Admit(rawget(raw, "asset"), path .. ".nodes[" .. index .. "].asset", owner)
			if admitted == nil then return nil, assetErr end
			if admitted.kind ~= "image" then return nil, failure("material_image_kind", "Material image nodes require an asset with kind='image'", "preflight", path .. ".nodes[" .. index .. "].asset.kind", { kind = admitted.kind }) end
			node.asset = admitted
			node.className, node.properties = "ImageLabel", { Name = "PotassiumMaterialImage", BackgroundTransparency = 1, ScaleType = if admitted.scaleType ~= nil then Enum.ScaleType[admitted.scaleType] else Enum.ScaleType.Stretch, ImageRectOffset = admitted.rectOffset, ImageRectSize = admitted.rectSize, Active = false, Size = UDim2.fromScale(1, 1) }
		end
		table.insert(nodes, node)
	end
	return nodes, nil
end

function MaterialRenderer.new(options: any?): (MaterialRenderer?, StructuredErrorValue?)
	local resolved = if options == nil then {} else options
	if type(resolved) ~= "table" then return nil, failure("invalid_renderer_options", "Renderer options must be a table", "create", "$.options") end
	local ledger = rawget(resolved, "budgetLedger")
	if type(ledger) ~= "table" or type(ledger.Reserve) ~= "function" or type(ledger.Reconcile) ~= "function" or type(ledger.Release) ~= "function" then
		return nil, failure("invalid_budget_ledger", "Renderer requires an injected BudgetLedger", "create", "$.options.budgetLedger")
	end
	local ownerId = rawget(resolved, "ownerId")
	if not validRole(ownerId) then return nil, failure("invalid_renderer_owner", "Renderer ownerId must be a bounded identifier", "create", "$.options.ownerId") end
	local policy = rawget(resolved, "assetPolicy")
	if policy == nil then
		local policyErr: StructuredErrorValue?
		policy, policyErr = AssetPolicy.new(rawget(resolved, "assetPolicyOptions"))
		if policy == nil then return nil, policyErr end
	end
	if type(policy) ~= "table" or type(policy.Admit) ~= "function" or type(policy.Resolve) ~= "function" then return nil, failure("invalid_asset_policy", "Renderer requires an AssetPolicy", "create", "$.options.assetPolicy") end
	return setmetatable({ _factory = rawget(resolved, "factory") or DefaultFactory, _runtime = rawget(resolved, "runtime"), _maidFactory = rawget(resolved, "maidFactory") or DefaultMaid, _ledger = ledger, _assetPolicy = policy, _diagnostics = rawget(resolved, "diagnostics"), _diagnosticOptions = rawget(resolved, "diagnosticOptions"), _ownerId = ownerId, _generation = 0, _handles = {}, _destroyed = false }, MaterialRenderer) :: any, nil
end

function MaterialRenderer:_stage(parent: any, material: any, role: any): (any?, StructuredErrorValue?)
	if self._destroyed then return nil, failure("renderer_destroyed", "Material renderer has been destroyed", "render") end
	if not validParent(parent) then return nil, failure("invalid_material_parent", "Material parent must be a GuiObject", "preflight", "$.parent") end
	if not validRole(role) then return nil, failure("invalid_material_role", "Material role must be a bounded identifier", "preflight", "$.role") end
	local generation = self._generation + 1
	local transactionId = self._ownerId .. ".material." .. tostring(generation)
	local nodes, nodeErr = parseMaterial(self, material, "$.material", transactionId)
	if nodes == nil then
		if type(self._assetPolicy.ReleaseOwner) == "function" then self._assetPolicy:ReleaseOwner(transactionId) end
		return nil, nodeErr
	end
	local reserved, reserveErr = self._ledger:Reserve(transactionId, self._ownerId, generation, primitiveCost(nodes))
	if not reserved then
		if type(self._assetPolicy.ReleaseOwner) == "function" then self._assetPolicy:ReleaseOwner(transactionId) end
		return nil, reserveErr
	end
	local maidOk, maid = pcall(function() return self._maidFactory.new() end)
	if not maidOk or type(maid) ~= "table" or type(maid.GiveTask) ~= "function" or type(maid.Destroy) ~= "function" then
		self._ledger:Release(transactionId, self._ownerId, generation)
		if type(self._assetPolicy.ReleaseOwner) == "function" then self._assetPolicy:ReleaseOwner(transactionId) end
		return nil, failure("material_maid_failed", "Renderer could not create a child Maid", "stage")
	end
	local stage, stageErr = make(self, "Frame", { Name = "PotassiumMaterialStage", BackgroundTransparency = 1, BorderSizePixel = 0, Active = false, Size = UDim2.fromScale(1, 1) }, nil)
	if stage == nil then
		maid:Destroy()
		self._ledger:Release(transactionId, self._ownerId, generation)
		if type(self._assetPolicy.ReleaseOwner) == "function" then self._assetPolicy:ReleaseOwner(transactionId) end
		return nil, stageErr
	end
	maid:GiveTask(stage)
	local actual = emptyCost()
	increment(actual, "Frame")
	for _, node in ipairs(nodes) do
		local properties = {}
		for key, value in pairs(node.properties) do properties[key] = value end
		if node.asset ~= nil then
			local content, resolveErr = self._assetPolicy:Resolve(node.asset, self._runtime, "$.material.image")
			if content == nil then
				maid:Destroy()
				self._ledger:Release(transactionId, self._ownerId, generation)
				if type(self._assetPolicy.ReleaseOwner) == "function" then self._assetPolicy:ReleaseOwner(transactionId) end
				return nil, resolveErr
			end
			if content ~= "" then properties.Image = content end
		end
		local instance, allocationErr = make(self, node.className, properties, stage)
			if instance == nil then
				maid:Destroy()
				self._ledger:Release(transactionId, self._ownerId, generation)
				if type(self._assetPolicy.ReleaseOwner) == "function" then self._assetPolicy:ReleaseOwner(transactionId) end
				return nil, allocationErr
			end
		increment(actual, node.className)
	end
	actual.materialNodes = #nodes
	return { parent = parent, stage = stage, maid = maid, transactionId = transactionId, generation = generation, cost = freeze(actual), role = role }, nil
end

function MaterialRenderer:_install(existing: any?, parent: any, material: any, role: any): (any?, StructuredErrorValue?)
	local staged, stageErr = self:_stage(parent, material, role)
	if staged == nil then return nil, stageErr end
	local reconciled, reconcileErr = self._ledger:Reconcile(staged.transactionId, self._ownerId, staged.generation, staged.cost)
	if not reconciled then
		staged.maid:Destroy()
		self._ledger:Release(staged.transactionId, self._ownerId, staged.generation)
		if type(self._assetPolicy.ReleaseOwner) == "function" then self._assetPolicy:ReleaseOwner(staged.transactionId) end
		publish(self, "reconcileFailed", { role = role, generation = staged.generation, code = if reconcileErr ~= nil then reconcileErr.code else "unknown" })
		return nil, reconcileErr or failure("material_reconcile_failed", "Material accounting could not be reconciled", "commit")
	end
	local parentOk = pcall(function() staged.stage.Parent = parent end)
	if not parentOk then
		staged.maid:Destroy()
		self._ledger:Release(staged.transactionId, self._ownerId, staged.generation)
		if type(self._assetPolicy.ReleaseOwner) == "function" then self._assetPolicy:ReleaseOwner(staged.transactionId) end
		return nil, failure("material_commit_failed", "Material could not be mounted", "commit", "$.parent")
	end
	local handle: any = existing or {}
	handle._renderer, handle._active, handle._destroyed = self, staged, false
	self._handles[handle] = true
	self._generation = staged.generation
	publish(self, "committed", { role = role, generation = staged.generation, reconciled = true })
	return handle, nil
end

function MaterialRenderer:Render(parent: any, compiled: any, role: any, _options: any?): (MaterialHandle?, StructuredErrorValue?)
	if type(compiled) ~= "table" then return nil, failure("invalid_compiled_skin", "Compiled skin must be a table", "render", "$.compiled") end
	local roles = rawget(compiled, "materialRoles")
	if type(roles) ~= "table" then return nil, failure("invalid_compiled_skin", "Compiled skin has no material roles", "render", "$.compiled.materialRoles") end
	if not validRole(role) then return nil, failure("invalid_material_role", "Material role must be a bounded identifier", "render", "$.role") end
	local material = rawget(roles, role)
	if material == nil then return nil, failure("unknown_material_role", "Compiled skin does not define the requested material role", "render", "$.role") end
	local handle, installErr = self:_install(nil, parent, material, role)
	if handle == nil then return nil, installErr end
	local function update(selfHandle: any, nextMaterial: any): (boolean, StructuredErrorValue?)
		if selfHandle._destroyed then return false, failure("material_destroyed", "Material handle has been destroyed", "update") end
		local prior = selfHandle._active
		local staged, stagedErr = selfHandle._renderer:_stage(prior.parent, nextMaterial, prior.role)
		if staged == nil then return false, stagedErr end
		local reconciled, reconcileErr = selfHandle._renderer._ledger:Reconcile(staged.transactionId, selfHandle._renderer._ownerId, staged.generation, staged.cost)
		if not reconciled then
			staged.maid:Destroy()
			selfHandle._renderer._ledger:Release(staged.transactionId, selfHandle._renderer._ownerId, staged.generation)
			if type(selfHandle._renderer._assetPolicy.ReleaseOwner) == "function" then selfHandle._renderer._assetPolicy:ReleaseOwner(staged.transactionId) end
			publish(selfHandle._renderer, "reconcileFailed", { role = prior.role, generation = staged.generation, code = if reconcileErr ~= nil then reconcileErr.code else "unknown" })
			return false, reconcileErr or failure("material_reconcile_failed", "Material accounting could not be reconciled", "update")
		end
		local parentOk = pcall(function() staged.stage.Parent = prior.parent end)
		if not parentOk then
			staged.maid:Destroy()
			selfHandle._renderer._ledger:Release(staged.transactionId, selfHandle._renderer._ownerId, staged.generation)
			if type(selfHandle._renderer._assetPolicy.ReleaseOwner) == "function" then selfHandle._renderer._assetPolicy:ReleaseOwner(staged.transactionId) end
			return false, failure("material_update_failed", "Material update could not be mounted", "update", "$.parent")
		end
		selfHandle._active = staged
		selfHandle._renderer._generation = staged.generation
		publish(selfHandle._renderer, "updated", { role = prior.role, generation = staged.generation, reconciled = true })
		prior.maid:Destroy()
		selfHandle._renderer._ledger:Release(prior.transactionId, selfHandle._renderer._ownerId, prior.generation)
		if type(selfHandle._renderer._assetPolicy.ReleaseOwner) == "function" then selfHandle._renderer._assetPolicy:ReleaseOwner(prior.transactionId) end
		return true, nil
	end
	local function destroy(selfHandle: any)
		if selfHandle._destroyed then return end
		selfHandle._destroyed = true
		selfHandle._renderer._handles[selfHandle] = nil
		local active = selfHandle._active
		selfHandle._active = nil
		if active ~= nil then
			active.maid:Destroy()
			selfHandle._renderer._ledger:Release(active.transactionId, selfHandle._renderer._ownerId, active.generation)
			if type(selfHandle._renderer._assetPolicy.ReleaseOwner) == "function" then selfHandle._renderer._assetPolicy:ReleaseOwner(active.transactionId) end
		end
	end
	function handle:Update(nextMaterial: any): (boolean, StructuredErrorValue?) return update(self, nextMaterial) end
	function handle:Replace(nextMaterial: any): (boolean, StructuredErrorValue?) return update(self, nextMaterial) end
	function handle:Destroy() destroy(self) end
	function handle:GetSnapshot(): any
		local active = self._active
		return freeze({ destroyed = self._destroyed, role = if active ~= nil then active.role else nil, generation = if active ~= nil then active.generation else nil, cost = if active ~= nil then active.cost else emptyCost() })
	end
	return handle, nil
end

function MaterialRenderer:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	for handle in pairs(self._handles) do handle:Destroy() end
	self._handles = {}
end
function MaterialRenderer:GetSnapshot(): any
	local count = 0
	for _ in pairs(self._handles) do count += 1 end
	local assetSnapshot = if type(self._assetPolicy.GetSnapshot) == "function" then self._assetPolicy:GetSnapshot() else nil
	return freeze({ destroyed = self._destroyed, ownerId = self._ownerId, generation = self._generation, activeHandles = count, assetPolicy = assetSnapshot })
end

return MaterialRenderer

end

__modules["customization/MenuSchema"] = function()
--!strict

local SchemaCodec = __require("customization/SchemaCodec")
local StructuredError = __require("core/StructuredError")

local MenuSchema = {}
MenuSchema.__index = MenuSchema

local function failure(code: string, message: string, operation: string, details: any?): any
	return StructuredError.from(code, message, { domain = "menuSchema", operation = operation, details = details })
end

local function frozenArray(values: { any }): { any }
	return table.freeze(values)
end

local function denseArray(value: any): boolean
	if type(value) ~= "table" then return false end
	local length, count = #value, 0
	for key in pairs(value) do
		if type(key) ~= "number" or key % 1 ~= 0 or key < 1 or key > length then return false end
		count += 1
	end
	return count == length
end

local function closed(value: any, allowed: { [string]: boolean }, path: string): any?
	for key in pairs(value) do
		if type(key) ~= "string" or not allowed[key] then
			return failure("unknown_menu_field", "Menu declaration contains an unknown field", "parse", { path = path, field = key })
		end
	end
	return nil
end

local function parseDeclarations(self: any, values: any, name: string): (any?, any?)
	if not denseArray(values) then
		return nil, failure("invalid_menu", "Menu " .. name .. " must be dense arrays", "parse")
	end
	local declarations, ids = {}, {}
	for index, raw in ipairs(values) do
		if type(raw) ~= "table" then
			return nil, failure("invalid_" .. name, "Menu " .. name .. " declaration must be a table", "parse", { index = index })
		end
		local shapeError = closed(raw, { id = true, definition = true }, "menu." .. name .. "[" .. tostring(index) .. "]")
		if shapeError ~= nil then return nil, shapeError end
		local id, idError = self._codec:ParseNamespacedId(raw.id, "menu." .. name .. "[" .. tostring(index) .. "].id")
		if id == nil then return nil, idError end
		if ids[id] then
			return nil, failure("duplicate_" .. name, "Menu " .. name .. " ids must be unique", "parse", { id = id })
		end
		ids[id] = true
		local definition, definitionError = self._codec:DeepCopy(raw.definition or {})
		if definition == nil then return nil, definitionError end
		table.insert(declarations, table.freeze({ id = id, definition = definition }))
	end
	return frozenArray(declarations), nil
end

local function preflight(target: any, method: string, value: any): (boolean, any?)
	local named = target["Preflight" .. method]
	if type(named) == "function" then return named(target, value) end
	if type(target.CanRegister) == "function" then return target:CanRegister(value) end
	return true, nil
end

local function rollback(installs: { any })
	for index = #installs, 1, -1 do
		pcall(installs[index])
	end
end

local function register(target: any, method: string, ...: any): (any?, any?)
	local ok, result, err = pcall(target[method], target, ...)
	if not ok then
		return nil, failure("menu_registration_failed", "Menu declaration could not be registered", "install", { method = method, reason = result })
	end
	return result, err
end

function MenuSchema.new(codec: any?): any
	return setmetatable({ _codec = codec or SchemaCodec.new() }, MenuSchema)
end

function MenuSchema:Parse(document: any): (any?, any?)
	local portable, portableError = self._codec:PreScanPortable(document, "menu")
	if not portable then return nil, portableError end
	if type(document) ~= "table" then return nil, failure("invalid_menu", "Menu schema must be a table", "parse") end
	for key in pairs(document) do
		if key ~= "menuSchemaVersion" and key ~= "id" and key ~= "resources" and key ~= "forms" and key ~= "routes" and key ~= "actions" and key ~= "runtimeBindings" then
			return nil, failure("unknown_menu_field", "Menu schema contains an unknown field", "parse", { field = key })
		end
	end
	local version, versionError = self._codec:ParseVersion(document.menuSchemaVersion, "menu.menuSchemaVersion")
	if version == nil then return nil, versionError end
	local id, idError = self._codec:ParseLocalId(document.id, "menu.id")
	if id == nil then return nil, idError end
	if not denseArray(document.resources) or not denseArray(document.forms) or not denseArray(document.routes) or not denseArray(document.actions) or not denseArray(document.runtimeBindings) then
		return nil, failure("invalid_menu", "Menu schema requires dense resource, form, route, action, and runtime binding arrays", "parse")
	end
	local resources, resourceError = parseDeclarations(self, document.resources, "resources")
	if resources == nil then return nil, resourceError end
	local forms, formError = parseDeclarations(self, document.forms, "forms")
	if forms == nil then return nil, formError end
	local routes, routeIds = {}, {}
	for index, raw in ipairs(document.routes) do
		if type(raw) ~= "table" then return nil, failure("invalid_route", "Menu route must be a table", "parse", { index = index }) end
		local shapeError = closed(raw, { id = true, title = true, definition = true }, "menu.routes[" .. tostring(index) .. "]")
		if shapeError ~= nil then return nil, shapeError end
		local routeId, routeError = self._codec:ParseNamespacedId(raw.id, "menu.routes[" .. tostring(index) .. "].id")
		if routeId == nil then return nil, routeError end
		if routeIds[routeId] then return nil, failure("duplicate_route", "Menu route ids must be unique", "parse", { id = routeId }) end
		routeIds[routeId] = true
		if raw.title ~= nil and type(raw.title) ~= "string" then return nil, failure("invalid_route", "Menu route title must be a string", "parse", { id = routeId }) end
		local definition, definitionError = self._codec:DeepCopy(raw.definition or {})
		if definition == nil then return nil, definitionError end
		table.insert(routes, table.freeze({ id = routeId, title = raw.title, definition = definition }))
	end
	local actions, actionIds = {}, {}
	for index, raw in ipairs(document.actions) do
		local action, actionError = self._codec:ParseActionDescriptor(raw, "portable")
		if action == nil then return nil, actionError end
		if action.confirmation ~= nil then
			if type(action.confirmation) ~= "table" then return nil, failure("invalid_action_confirmation", "Command action confirmation must be a table", "parse", { id = action.id }) end
			for key, value in pairs(action.confirmation) do
				if (key ~= "title" and key ~= "text" and key ~= "confirm" and key ~= "cancel") or type(value) ~= "string" then
					return nil, failure("invalid_action_confirmation", "Command action confirmation only supports string title, text, confirm, and cancel fields", "parse", { id = action.id, field = key })
				end
			end
		end
		if actionIds[action.id] then return nil, failure("duplicate_action", "Menu action ids must be unique", "parse", { id = action.id, index = index }) end
		actionIds[action.id] = true
		if action.kind == "navigation" and not routeIds[action.routeId] then return nil, failure("unknown_route", "Navigation action references an undeclared route", "parse", { id = action.id, routeId = action.routeId }) end
		table.insert(actions, action)
	end
	local runtimeBindings, bindingKeys = {}, {}
	local resourceIds, formIds = {}, {}
	for _, resource in ipairs(resources) do resourceIds[resource.id] = true end
	for _, form in ipairs(forms) do formIds[form.id] = true end
	for index, raw in ipairs(document.runtimeBindings) do
		local binding, bindingError = self._codec:ParseBindingSpec(raw)
		if binding == nil then return nil, bindingError end
		if (binding.source == "resource" and not resourceIds[binding.id]) or (binding.source == "form" and not formIds[binding.id]) or (binding.source == "route" and not routeIds[binding.id]) then
			return nil, failure("unknown_runtime_binding", "Runtime binding references an undeclared menu declaration", "parse", { index = index, source = binding.source, id = binding.id })
		end
		local bindingKey = binding.source .. ":" .. binding.id
		if bindingKeys[bindingKey] then return nil, failure("duplicate_runtime_binding", "Runtime bindings must be unique per source and id", "parse", { source = binding.source, id = binding.id }) end
		bindingKeys[bindingKey] = true
		table.insert(runtimeBindings, binding)
	end
	return table.freeze({
		menuSchemaVersion = version,
		id = id,
		resources = resources,
		forms = forms,
		routes = frozenArray(routes),
		actions = frozenArray(actions),
		runtimeBindings = frozenArray(runtimeBindings),
	}), nil
end

function MenuSchema:Install(document: any, navigation: any, commands: any, services: any?): (any?, any?)
	local schema, schemaError = self:Parse(document)
	if schema == nil then return nil, schemaError end
	if type(navigation) ~= "table" or type(navigation.Register) ~= "function" then
		return nil, failure("navigation_unavailable", "Menu schema requires a navigation model", "install")
	end
	if #schema.actions > 0 and (type(commands) ~= "table" or type(commands.RegisterCommand) ~= "function" or type(commands.ExecuteCommand) ~= "function" or type(commands.UnregisterCommand) ~= "function") then
		return nil, failure("commands_unavailable", "Menu schema actions require a command registry", "install")
	end
	if #schema.resources > 0 or #schema.forms > 0 or #schema.runtimeBindings > 0 then
		if type(services) ~= "table"
			or type(services.RegisterResource) ~= "function" or type(services.UnregisterResource) ~= "function"
			or type(services.RegisterForm) ~= "function" or type(services.UnregisterForm) ~= "function"
			or type(services.RegisterRuntimeBinding) ~= "function" or type(services.UnregisterRuntimeBinding) ~= "function" then
			return nil, failure("services_unavailable", "Menu schema declarations require UI services", "install")
		end
	end

	local registeredCommands = {}
	if type(commands) == "table" and type(commands.ListCommands) == "function" then
		for _, command in ipairs(commands:ListCommands()) do registeredCommands[command.Id] = command end
	end
	for _, resource in ipairs(schema.resources) do
		local allowed, preflightError = preflight(services, "RegisterResource", resource)
		if not allowed then return nil, preflightError end
	end
	for _, form in ipairs(schema.forms) do
		local allowed, preflightError = preflight(services, "RegisterForm", form)
		if not allowed then return nil, preflightError end
	end
	for _, binding in ipairs(schema.runtimeBindings) do
		local allowed, preflightError = preflight(services, "RegisterRuntimeBinding", binding)
		if not allowed then return nil, preflightError end
	end
	for _, route in ipairs(schema.routes) do
		if type(navigation._routes) == "table" and navigation._routes[route.id] ~= nil then
			return nil, failure("route_conflict", "Menu route is already registered", "install", { id = route.id })
		end
		local allowed, preflightError = preflight(navigation, "Register", route)
		if not allowed then return nil, preflightError end
	end
	for _, action in ipairs(schema.actions) do
		if registeredCommands[action.id] then return nil, failure("action_conflict", "Menu action is already registered", "install", { id = action.id }) end
		if action.kind == "command" and type(commands.ListCommands) == "function" and not registeredCommands[action.commandId] then
			return nil, failure("unknown_command", "Menu action references an unregistered command", "install", { id = action.id, commandId = action.commandId })
		end
		local allowed, preflightError = preflight(commands, "RegisterCommand", action)
		if not allowed then return nil, preflightError end
		registeredCommands[action.id] = true
	end

	local installs = {}
	for _, resource in ipairs(schema.resources) do
		local registered, registerError = register(services, "RegisterResource", resource)
		if not registered then rollback(installs); return nil, registerError end
		table.insert(installs, function() services:UnregisterResource(resource.id) end)
	end
	for _, form in ipairs(schema.forms) do
		local registered, registerError = register(services, "RegisterForm", form)
		if not registered then rollback(installs); return nil, registerError end
		table.insert(installs, function() services:UnregisterForm(form.id) end)
	end
	for _, binding in ipairs(schema.runtimeBindings) do
		local registered, registerError = register(services, "RegisterRuntimeBinding", binding)
		if not registered then rollback(installs); return nil, registerError end
		table.insert(installs, function() services:UnregisterRuntimeBinding(binding.source, binding.id) end)
	end
	for _, route in ipairs(schema.routes) do
		local registered, registerError = register(navigation, "Register", route.id, route.definition)
		if not registered then rollback(installs); return nil, registerError end
		table.insert(installs, function()
			if type(navigation.Unregister) == "function" then navigation:Unregister(route.id)
			elseif type(navigation._routes) == "table" then navigation._routes[route.id] = nil end
		end)
	end
	for _, action in ipairs(schema.actions) do
		local definition: any = { Id = action.id, Title = action.id }
		if action.kind == "command" then
			local target = registeredCommands[action.commandId]
			if type(target) == "table" then definition.Parameters = target.Parameters end
			definition.Confirmation = action.confirmation
		end
		if action.kind == "navigation" then
			definition.Execute = function(args: any)
				if action.mode == "replace" then return navigation:Replace(action.routeId, args, "menu-schema") end
				return navigation:Navigate(action.routeId, args, "menu-schema")
			end
		else
			definition.Execute = function(args: any)
				if action.confirmation == nil then return commands:ExecuteCommand(action.commandId, args) end
				local library = if type(services) == "table" then services._library else nil
				local presentation = if type(library) == "table" then library.Presentation else nil
				if type(presentation) ~= "table" or type(presentation.ConfirmRisk) ~= "function" then
					return false, failure("confirmation_unavailable", "Command action confirmation requires presentation services", "execute", { id = action.id })
				end
				local confirmation = {}
				for key, value in pairs(action.confirmation) do confirmation[key] = value end
				confirmation.Id = "menu-action:" .. action.id
				confirmation.onConfirm = function() commands:ExecuteCommand(action.commandId, args) end
				local confirmed, confirmationError = pcall(function() return presentation:ConfirmRisk(confirmation) end)
				if not confirmed then return false, failure("confirmation_unavailable", "Command action confirmation could not be presented", "execute", { id = action.id, reason = confirmationError }) end
				return true
			end
		end
		local registered, registerError = register(commands, "RegisterCommand", definition)
		if not registered then rollback(installs); return nil, registerError end
		table.insert(installs, function() commands:UnregisterCommand(action.id) end)
	end
	return schema, nil
end

return MenuSchema

end

__modules["customization/OfflineAssets"] = function()
--!strict

-- Semantic fallbacks only. These names intentionally resolve to procedural Icons or
-- Enum.Font values; this catalog never carries a content reference.
local OfflineAssets = {}

local catalog = table.freeze({
	icons = table.freeze({ default = "help", image = "image", avatar = "user", unavailable = "warning" }),
	fonts = table.freeze({ default = Enum.Font.BuilderSans, bold = Enum.Font.BuilderSansBold, mono = Enum.Font.Code }),
	images = table.freeze({ default = false, unavailable = false }),
	avatars = table.freeze({ default = false, unavailable = false }),
})

function OfflineAssets.Get(kind: any, name: any): any
	if type(kind) ~= "string" or type(name) ~= "string" then return nil end
	local group = (catalog :: any)[kind]
	return if type(group) == "table" then group[name] else nil
end

function OfflineAssets.Snapshot(): any
	return catalog
end

return table.freeze(OfflineAssets)

end

__modules["customization/PackManager"] = function()
--!strict

local StructuredError = __require("core/StructuredError")
local SchemaCodec = __require("customization/SchemaCodec")
local ControlDescriptors = __require("models/ControlDescriptors")
local CompositionDescriptors = __require("models/CompositionDescriptors")

local PackManager = {}
PackManager.__index = PackManager

local MANIFEST_FIELDS = { id = true, version = true, apiVersion = true, extensionApiVersion = true, dependencies = true, optionalDependencies = true, capabilities = true, artifactHash = true, contributions = true, migrations = true, extensions = true }
local SOURCE_FIELDS = { manifest = true, contributions = true }
local DEPENDENCY_FIELDS = { id = true, version = true }
local DEFAULT_VERSION = table.freeze({ major = 1, minor = 0, patch = 0 })

local function fail(code: string, message: string, operation: string, details: any?): any
	return StructuredError.from(code, message, { domain = "pack_manager", operation = operation, details = details })
end

local function closed(value: any, allowed: {[string]: boolean}, code: string, operation: string): any?
	if type(value) ~= "table" then return fail(code, "Descriptor must be a table", operation) end
	for key in pairs(value) do
		if type(key) ~= "string" or not allowed[key] then return fail("unknown_" .. code .. "_field", "Descriptor contains an unknown field", operation, { field = key }) end
	end
	return nil
end

local function denseArray(value: any): boolean
	if type(value) ~= "table" then return false end
	local length = #value
	for index = 1, length do if rawget(value, index) == nil then return false end end
	for key in pairs(value) do if type(key) ~= "number" or key < 1 or key > length or key ~= math.floor(key) then return false end end
	return true
end

local function compatible(required: any, available: any): boolean
	return required.major == available.major and (required.minor < available.minor or required.minor == available.minor and required.patch <= available.patch)
end

local function cleanupAll(installs: { any })
	for index = #installs, 1, -1 do pcall(installs[index]) end
end

local function validateContribution(self: any, raw: any): (any?, any?)
	local contribution, contributionError = self._codec:ParseContributionDescriptor(raw)
	if contribution == nil then return nil, contributionError end
	if contribution.kind == "control" then
		local _, descriptorError = ControlDescriptors.ValidatePortable(contribution.definition)
		if descriptorError ~= nil then return nil, descriptorError end
	elseif contribution.kind == "content" or contribution.kind == "container" then
		local descriptor, descriptorError = CompositionDescriptors.Validate(contribution.definition)
		if descriptor == nil then return nil, descriptorError end
		if (contribution.kind == "content" and not CompositionDescriptors.IsContent(descriptor)) or (contribution.kind == "container" and not CompositionDescriptors.IsContainer(descriptor)) then
			return nil, fail("contribution_kind_mismatch", "Contribution kind does not match its descriptor", "validate")
		end
	end
	return contribution, nil
end

local function capabilitySet(value: any): {[string]: boolean}
	local result = {}
	if type(value) ~= "table" then return result end
	for key, enabled in pairs(value) do
		if type(key) == "string" then result[key] = enabled == true else result[enabled] = true end
	end
	return result
end

function PackManager.new(options: any): (any?, any?)
	if type(options) ~= "table" or type(options.extensionHost) ~= "table" then return nil, fail("invalid_pack_manager", "PackManager requires an ExtensionHost", "create") end
	if type(options.extensionHost.Stage) ~= "function" or type(options.extensionHost.Install) ~= "function" then return nil, fail("invalid_pack_manager", "PackManager requires the ExtensionHost mutation facade", "create") end
	local codec = options.codec or SchemaCodec.new()
	local apiVersion, apiError = codec:ParseVersion(options.apiVersion or DEFAULT_VERSION, "host.apiVersion")
	if apiVersion == nil then return nil, apiError end
	local extensionApiVersion, extensionError = codec:ParseVersion(options.extensionApiVersion or DEFAULT_VERSION, "host.extensionApiVersion")
	if extensionApiVersion == nil then return nil, extensionError end
	return setmetatable({
		_host = options.extensionHost, _codec = codec, _diagnostics = options.diagnostics,
		_apiVersion = apiVersion, _extensionApiVersion = extensionApiVersion,
		_capabilities = capabilitySet(options.capabilities), _extensions = capabilitySet(options.extensions),
		_migrations = options.migrationRegistry, _hosts = {}, _installs = {}, _packs = {},
	}, PackManager), nil
end

function PackManager:SetHosts(hosts: any): (boolean, any?)
	if type(hosts) ~= "table" then return false, fail("invalid_contribution_hosts", "Contribution hosts must be a table", "set_hosts") end
	for kind, host in pairs(hosts) do
		if type(kind) ~= "string" or type(host) ~= "table" or type(host.Install) ~= "function" or type(host.Uninstall) ~= "function" then
			return false, fail("invalid_contribution_host", "Each contribution host requires Install and Uninstall methods", "set_hosts", { kind = kind })
		end
	end
	self._hosts = hosts
	return true, nil
end

function PackManager:_validateVersion(axis: string, required: any, available: any): any?
	if compatible(required, available) then return nil end
	local migrations = self._migrations
	if type(migrations) == "table" and type(migrations.ResolveChain) == "function" then
		local chain = migrations:ResolveChain(axis, available, required)
		if chain ~= nil then return nil end
	end
	return fail("incompatible_" .. axis, "Pack requires an incompatible " .. axis, "validate", { required = required, available = available })
end

function PackManager:_validateDependencies(values: any, optional: boolean): any?
	if values == nil then return nil end
	if not denseArray(values) then return fail("invalid_dependency", "Dependencies must be dense arrays", "validate") end
	for index, dependency in ipairs(values) do
		local shapeError = closed(dependency, DEPENDENCY_FIELDS, "dependency", "validate")
		if shapeError ~= nil then return shapeError end
		local dependencyId, dependencyError = self._codec:ParseNamespacedId(rawget(dependency, "id"), "manifest.dependencies[" .. tostring(index) .. "].id")
		if dependencyId == nil then return dependencyError end
		local snapshot = self._host:GetPackSnapshot(dependencyId)
		if snapshot == nil or snapshot.state ~= "installed" then
			if not optional then return fail("missing_dependency", "Required dependency is not installed", "validate", { id = dependencyId }) end
		else
			local requiredVersion = rawget(dependency, "version")
			if requiredVersion ~= nil then
				local parsedVersion, versionError = self._codec:ParseVersion(requiredVersion, "manifest.dependencies[" .. tostring(index) .. "].version")
				if parsedVersion == nil then return versionError end
				local installedVersion, installedError = self._codec:ParseVersion(snapshot.manifest.version, "installed.manifest.version")
				if installedVersion == nil then return installedError end
				if not compatible(parsedVersion, installedVersion) then return fail("incompatible_dependency", "Installed dependency does not satisfy the required version", "validate", { id = dependencyId }) end
			end
		end
	end
	return nil
end

function PackManager:Validate(source: any): (any?, any?)
	local scanned, scanError = self._codec:PreScanPortable(source, "extension-pack")
	if not scanned then return nil, scanError end
	if type(source) ~= "table" then return nil, fail("invalid_pack_source", "Pack source must be a table", "validate") end
	local manifest = rawget(source, "manifest") or source
	if rawget(source, "manifest") ~= nil then
		local sourceError = closed(source, SOURCE_FIELDS, "pack_source", "validate")
		if sourceError ~= nil then return nil, sourceError end
	end
	local shapeError = closed(manifest, MANIFEST_FIELDS, "manifest", "validate")
	if shapeError ~= nil then return nil, shapeError end
	local id, idError = self._codec:ParseNamespacedId(rawget(manifest, "id"), "manifest.id")
	if id == nil then return nil, idError end
	local version, versionError = self._codec:ParseVersion(rawget(manifest, "version"), "manifest.version")
	if version == nil then return nil, versionError end
	for field, hostVersion in pairs({ apiVersion = self._apiVersion, extensionApiVersion = self._extensionApiVersion }) do
		local rawVersion = rawget(manifest, field)
		if rawVersion ~= nil then
			local required, requiredError = self._codec:ParseVersion(rawVersion, "manifest." .. field)
			if required == nil then return nil, requiredError end
			local compatibilityError = self:_validateVersion(field, required, hostVersion)
			if compatibilityError ~= nil then return nil, compatibilityError end
		end
	end
	if rawget(manifest, "artifactHash") ~= nil and (type(manifest.artifactHash) ~= "string" or string.match(manifest.artifactHash, "^[a-f0-9]+$") == nil) then return nil, fail("invalid_artifact_hash", "artifactHash must be a lowercase hexadecimal digest", "validate") end
	for _, field in ipairs({ "capabilities", "extensions" }) do
		local values = rawget(manifest, field)
		if values ~= nil then
			if not denseArray(values) then return nil, fail("invalid_" .. field, field .. " must be a dense array", "validate") end
			local available = if field == "capabilities" then self._capabilities else self._extensions
			for index, required in ipairs(values) do
				if type(required) ~= "string" or not available[required] then return nil, fail("unsupported_" .. field, "Pack requires an unavailable " .. string.sub(field, 1, -2), "validate", { index = index, value = required }) end
			end
		end
	end
	local normalizedMigrations = {}
	local migrations = rawget(manifest, "migrations")
	if migrations ~= nil and not denseArray(migrations) then return nil, fail("invalid_migrations", "Migrations must be a dense array", "validate") end
	for index, migration in ipairs(migrations or {}) do
		local parsedMigration, migrationError = self._codec:ParseMigrationDeclaration(migration)
		if parsedMigration == nil then return nil, migrationError end
		normalizedMigrations[index] = parsedMigration
	end
	local dependencyError = self:_validateDependencies(rawget(manifest, "dependencies") or {}, false)
	if dependencyError ~= nil then return nil, dependencyError end
	local optionalError = self:_validateDependencies(rawget(manifest, "optionalDependencies"), true)
	if optionalError ~= nil then return nil, optionalError end
	local contributions = rawget(source, "contributions") or rawget(manifest, "contributions") or {}
	if not denseArray(contributions) then return nil, fail("invalid_contributions", "Contributions must be a dense array", "validate") end
	local normalizedContributions, ids, availableContributions = {}, {}, {}
	for index, raw in ipairs(contributions) do
		local contribution, contributionError = validateContribution(self, raw)
		if contribution == nil then return nil, contributionError end
		if ids[contribution.id] then return nil, fail("duplicate_contribution", "Contribution ids must be unique", "validate") end
		ids[contribution.id] = true; normalizedContributions[index] = contribution
		if contribution.kind ~= "reference" then availableContributions[contribution.id] = contribution.kind end
	end
	local hostSnapshot = self._host:GetSnapshot()
	if type(hostSnapshot) == "table" and type(hostSnapshot.packs) == "table" then
		for _, packSnapshot in pairs(hostSnapshot.packs) do
			if type(packSnapshot) == "table" and packSnapshot.state == "installed" and type(packSnapshot.contributions) == "table" then
				for contributionId, contribution in pairs(packSnapshot.contributions) do if type(contribution) == "table" and contribution.kind ~= "reference" then availableContributions[contributionId] = contribution.kind end end
			end
		end
	end
	for _, contribution in ipairs(normalizedContributions) do
		if contribution.kind == "reference" then
			local targetKind = availableContributions[contribution.target]
			if targetKind == nil then return nil, fail("unresolved_contribution_reference", "Reference contribution target is unavailable", "validate", { id = contribution.id, target = contribution.target }) end
			if targetKind ~= contribution.expectedKind then return nil, fail("contribution_reference_kind_mismatch", "Reference contribution target does not match expectedKind", "validate", { id = contribution.id, target = contribution.target, expectedKind = contribution.expectedKind, actualKind = targetKind }) end
		elseif self._hosts[contribution.kind] == nil then
			return nil, fail("contribution_host_unavailable", "No subsystem host is installed for contribution kind", "validate", { id = contribution.id, kind = contribution.kind })
		end
	end
	local normalizedManifest, normalizeError = self._codec:Normalize(manifest)
	if normalizedManifest == nil then return nil, normalizeError end
	return table.freeze({ manifest = normalizedManifest, contributions = table.freeze(normalizedContributions), migrations = table.freeze(normalizedMigrations) }), nil
end

function PackManager:_contributionIndex(pack: any): {[string]: any}
	local contributions = {}
	local hostSnapshot = self._host:GetSnapshot()
	if type(hostSnapshot) == "table" and type(hostSnapshot.packs) == "table" then
		for _, packSnapshot in pairs(hostSnapshot.packs) do
			if type(packSnapshot) == "table" and packSnapshot.state == "installed" and type(packSnapshot.contributions) == "table" then
				for id, contribution in pairs(packSnapshot.contributions) do
					if type(contribution) == "table" and contribution.kind ~= "reference" then contributions[id] = contribution end
				end
			end
		end
	end
	for _, contribution in ipairs(pack.contributions) do
		if contribution.kind ~= "reference" then contributions[contribution.id] = contribution end
	end
	return contributions
end

function PackManager:_dispatch(pack: any): (any?, any?)
	local installs, contributions = {}, self:_contributionIndex(pack)
	for _, contribution in ipairs(pack.contributions) do
		local target = if contribution.kind == "reference" then contributions[contribution.target] else nil
		local kind = if target ~= nil then contribution.expectedKind else contribution.kind
		local adapter = self._hosts[kind]
		if adapter == nil then cleanupAll(installs); return nil, fail("contribution_host_unavailable", "No subsystem host is installed for contribution kind", "install", { id = contribution.id, kind = kind }) end
			local resolved = target or contribution
			local ok, installed, installError = pcall(adapter.Install, adapter, resolved, pack.manifest, if target ~= nil then contribution else nil)
			if not ok then cleanupAll(installs); return nil, fail("contribution_install_failed", "Contribution host raised an error during installation", "install", { id = contribution.id, reason = installed }) end
			if installed == nil or installed == false then cleanupAll(installs); return nil, installError or fail("contribution_install_failed", "Contribution host rejected installation", "install", { id = contribution.id }) end
			table.insert(installs, function()
				if type(installed) == "function" then installed() else adapter:Uninstall(resolved, installed, pack.manifest, if target ~= nil then contribution else nil) end
			end)
	end
	return installs, nil
end

function PackManager:_registerMigrations(pack: any): any?
	if #pack.migrations == 0 then return nil end
	local migrations = self._migrations
	if type(migrations) ~= "table" or type(migrations.RegisterOwnedDeclarations) ~= "function" then
		return fail("migration_registry_unavailable", "Migration declarations require the MigrationRegistry ownership facade", "install")
	end
	local registered, registrationError = migrations:RegisterOwnedDeclarations(pack.manifest.id, pack.migrations)
	if not registered then return registrationError or fail("migration_registration_failed", "Migration declarations could not be registered", "install") end
	return nil
end

function PackManager:_removeMigrations(id: any): any?
	local migrations = self._migrations
	if type(migrations) == "table" and type(migrations.RemoveOwnedDeclarations) == "function" then
		local removed, removalError = migrations:RemoveOwnedDeclarations(id)
		if not removed then return removalError or fail("migration_removal_failed", "Migration declarations could not be removed", "remove") end
	end
	return nil
end

function PackManager:Install(source: any): (any?, any?)
	local pack, validateError = self:Validate(source)
	if pack == nil then return nil, validateError end
	local staged, stageError = self._host:Stage(pack.manifest, pack.contributions)
	if staged == nil then return nil, stageError end
	local installs, dispatchError = self:_dispatch(pack)
	if installs == nil then
		if type(self._host.Discard) == "function" then self._host:Discard(staged.id) end
		return nil, dispatchError
	end
	local migrationError = self:_registerMigrations(pack)
	if migrationError ~= nil then
		cleanupAll(installs)
		if type(self._host.Discard) == "function" then self._host:Discard(staged.id) end
		return nil, migrationError
	end
	local installed, installError = self._host:Install(staged.id)
	if not installed then
		cleanupAll(installs)
		self:_removeMigrations(pack.manifest.id)
		if type(self._host.Discard) == "function" then self._host:Discard(staged.id) end
		return nil, installError
	end
	self._installs[staged.id] = installs
	self._packs[staged.id] = pack
	return self._host:GetPackSnapshot(staged.id)
end

function PackManager:Upgrade(source: any): (any?, any?)
	local pack, validateError = self:Validate(source)
	if pack == nil then return nil, validateError end
	local current = self._host:GetPackSnapshot(pack.manifest.id)
	if current ~= nil and current.state ~= "uninstalled" and (current.state ~= "installed" or current.liveMounts ~= 0) then
		return nil, fail("duplicate_pack", "Pack is already staged or installed with live mounts", "upgrade", { id = pack.manifest.id })
	end
	local prior, priorPack = self._installs[pack.manifest.id], self._packs[pack.manifest.id]
	if prior ~= nil then cleanupAll(prior) end
	if priorPack ~= nil then
		local removalError = self:_removeMigrations(pack.manifest.id)
		if removalError ~= nil then
			local restored = self:_dispatch(priorPack)
			if restored ~= nil then self._installs[pack.manifest.id] = restored end
			return nil, removalError
		end
	end
	local function restorePrior()
		if priorPack ~= nil then
			self:_registerMigrations(priorPack)
			local restored = self:_dispatch(priorPack)
			if restored ~= nil then self._installs[pack.manifest.id] = restored end
		end
	end
	local installs, dispatchError = self:_dispatch(pack)
	if installs == nil then
		restorePrior()
		return nil, dispatchError
	end
	local migrationError = self:_registerMigrations(pack)
	if migrationError ~= nil then
		cleanupAll(installs)
		restorePrior()
		return nil, migrationError
	end
	local upgraded, upgradeError = self._host:Upgrade(pack.manifest, pack.contributions)
	if upgraded == nil then
		cleanupAll(installs)
		self:_removeMigrations(pack.manifest.id)
		restorePrior()
		return nil, upgradeError
	end
	self._installs[pack.manifest.id] = installs
	self._packs[pack.manifest.id] = pack
	return upgraded, nil
end

function PackManager:_release(id: any)
	local installs = self._installs[id]
	if installs ~= nil then
		cleanupAll(installs)
		self._installs[id] = nil
		self._packs[id] = nil
	end
	self:_removeMigrations(id)
end

function PackManager:Drain(id: any): (boolean, any?)
	local drained, drainError = self._host:Drain(id)
	if drained then
		local snapshot = self._host:GetPackSnapshot(id)
		if snapshot ~= nil and snapshot.state == "uninstalled" then self:_release(id) end
	end
	return drained, drainError
end
function PackManager:Uninstall(id: any): (boolean, any?) return self:Drain(id) end
function PackManager:Mount(id: any, owner: any): (any?, any?)
	local mount, mountError = self._host:Mount(id, owner)
	if mount == nil then return nil, mountError end
	local manager, unmount = self, mount.Unmount
	function mount:Unmount(): boolean
		local unmounted = unmount(self)
		local snapshot = manager._host:GetPackSnapshot(id)
		if snapshot ~= nil and snapshot.state == "uninstalled" then manager:_release(id) end
		return unmounted
	end
	mount.Destroy = mount.Unmount
	local wrapper = { generation = mount.generation }
	function wrapper:Unmount(): boolean return mount:Unmount() end
	wrapper.Destroy = wrapper.Unmount
	return wrapper, nil
end
function PackManager:GetSnapshot(id: any): (any?, any?) return self._host:GetPackSnapshot(id) end
function PackManager:List(): any return self._host:GetSnapshot() end

return PackManager

end

__modules["customization/RecipeResolver"] = function()
--!strict

local StructuredError = __require("core/StructuredError")
local SchemaCodec = __require("customization/SchemaCodec")

export type StructuredErrorValue = StructuredError.StructuredError
export type Resolver = {
	Resolve: (self: Resolver, recipes: any, environment: any) -> (any?, StructuredErrorValue?),
}

local RecipeResolver = {}
RecipeResolver.__index = RecipeResolver

local MAX_RECIPES = 256
local MAX_RESOLUTION_DEPTH = 16

local function failure(code: string, message: string, path: string?, details: any?): StructuredErrorValue
	return StructuredError.from(code, message, {
		domain = "recipeResolver",
		operation = "resolve",
		path = path,
		details = details,
	})
end

local function sortedStringKeys(value: table, path: string): ({ string }?, StructuredErrorValue?)
	local result = {}
	local key = next(value, nil)
	while key ~= nil do
		if type(key) ~= "string" then
			return nil, failure("invalid_recipe_map", "Recipe maps must use string keys", path)
		end
		table.insert(result, key)
		key = next(value, key)
	end
	table.sort(result)
	return result, nil
end

local function closed(value: any, allowed: { [string]: boolean }, required: { [string]: boolean }, path: string): StructuredErrorValue?
	if type(value) ~= "table" then return failure("invalid_recipe", "Recipe must be a table", path) end
	local key = next(value, nil)
	while key ~= nil do
		if type(key) ~= "string" or not allowed[key] then
			return failure("unknown_recipe_field", "Recipe contains an unknown field", path)
		end
		key = next(value, key)
	end
	for field in pairs(required) do
		if rawget(value, field) == nil then return failure("missing_recipe_field", "Recipe is missing a required field", path .. "." .. field) end
	end
	return nil
end

local function scalar(value: any): boolean
	local valueType = type(value)
	return valueType == "nil" or valueType == "boolean" or (valueType == "number" and value == value and value ~= math.huge and value ~= -math.huge) or valueType == "string"
end

local function resolveReference(environment: any, mapName: string, id: any, path: string): (any?, StructuredErrorValue?)
	if type(id) ~= "string" then return nil, failure("invalid_recipe_reference", "Recipe reference must be a string", path) end
	local values = rawget(environment, mapName)
	if type(values) ~= "table" then return nil, failure("invalid_recipe_environment", "Recipe environment is invalid", path) end
	local resolved = rawget(values, id)
	if resolved == nil then return nil, failure("unresolved_recipe_reference", "Recipe reference could not be resolved", path, { reference = id, source = mapName }) end
	return resolved, nil
end

local function publish(self: any, event: string, details: any)
	local diagnostics = self._diagnostics
	if diagnostics ~= nil and type(diagnostics.Publish) == "function" then
		pcall(function()
			diagnostics:Publish("recipeResolver", table.freeze({ event = event, details = table.freeze(details) }), self._diagnosticOptions)
		end)
	end
end

function RecipeResolver.new(options: any?): Resolver
	local resolved = if type(options) == "table" then options else {}
	return setmetatable({
		_codec = rawget(resolved, "codec") or SchemaCodec.new(),
		_diagnostics = rawget(resolved, "diagnostics"),
		_diagnosticOptions = rawget(resolved, "diagnosticOptions"),
	}, RecipeResolver) :: any
end

function RecipeResolver:Resolve(recipes: any, environment: any): (any?, StructuredErrorValue?)
	local codec = self._codec
	local ok, scanErr = codec:PreScanPortable(recipes, "$.recipes")
	if not ok then return nil, scanErr end
	ok, scanErr = codec:PreScanPortable(environment, "$.environment")
	if not ok then return nil, scanErr end
	if type(recipes) ~= "table" or type(environment) ~= "table" then
		return nil, failure("invalid_recipe_input", "Recipes and environment must be portable tables")
	end
	local recipeKeys, keyErr = sortedStringKeys(recipes, "$.recipes")
	if recipeKeys == nil then return nil, keyErr end
	if #recipeKeys > MAX_RECIPES then return nil, failure("recipe_limit", "Recipe count exceeds the limit", "$.recipes", { limit = MAX_RECIPES }) end

	local state: { [string]: "resolving" | "resolved" } = {}
	local values: { [string]: any } = {}
	local resolveRecipe: (id: string, depth: number) -> (any?, StructuredErrorValue?)
	local function resolveValue(value: any, path: string, depth: number): (any?, StructuredErrorValue?)
		if depth > MAX_RESOLUTION_DEPTH then return nil, failure("recipe_depth_limit", "Recipe resolution exceeds the maximum depth", path, { limit = MAX_RESOLUTION_DEPTH }) end
		if scalar(value) then return value, nil end
		if type(value) ~= "table" then return nil, failure("invalid_recipe", "Recipe values must be declarative", path) end
		local kind = rawget(value, "kind")
		if kind == "literal" then
			local err = closed(value, { kind = true, value = true }, { kind = true, value = true }, path)
			if err then return nil, err end
			if not scalar(rawget(value, "value")) then return nil, failure("invalid_recipe_literal", "Recipe literals must be scalar values", path .. ".value") end
			return rawget(value, "value"), nil
		elseif kind == "token" or kind == "metric" then
			local err = closed(value, { kind = true, id = true }, { kind = true, id = true }, path)
			if err then return nil, err end
			return resolveReference(environment, if kind == "token" then "tokens" else "metrics", rawget(value, "id"), path .. ".id")
		elseif kind == "role" then
			local err = closed(value, { kind = true, id = true }, { kind = true, id = true }, path)
			if err then return nil, err end
			local roleId, roleIdErr = codec:ParseLocalId(rawget(value, "id"), path .. ".id")
			if roleId == nil then return nil, roleIdErr end
			local recipeId, roleErr = resolveReference(environment, "roles", roleId, path .. ".id")
			if recipeId == nil then return nil, roleErr end
			local parsedRecipeId, recipeIdErr = codec:ParseLocalId(recipeId, path .. ".id")
			if parsedRecipeId == nil then return nil, recipeIdErr end
			if rawget(recipes, parsedRecipeId) == nil then
				return nil, failure("unresolved_recipe_reference", "Role references an unknown recipe", path .. ".id", { role = roleId, recipe = parsedRecipeId })
			end
			return resolveRecipe(parsedRecipeId, depth + 1)
		elseif kind == "recipe" then
			local err = closed(value, { kind = true, id = true }, { kind = true, id = true }, path)
			if err then return nil, err end
			local id = rawget(value, "id")
			if type(id) ~= "string" or rawget(recipes, id) == nil then return nil, failure("unresolved_recipe_reference", "Recipe reference could not be resolved", path .. ".id", { reference = id }) end
			return resolveRecipe(id, depth + 1)
		elseif kind == "list" then
			local err = closed(value, { kind = true, values = true }, { kind = true, values = true }, path)
			if err then return nil, err end
			local source = rawget(value, "values")
			if type(source) ~= "table" then return nil, failure("invalid_recipe", "Recipe list values must be a table", path .. ".values") end
			local result = {}
			for index = 1, #source do
				local resolved, resolveErr = resolveValue(rawget(source, index), path .. ".values[" .. tostring(index) .. "]", depth + 1)
				if resolveErr then return nil, resolveErr end
				result[index] = resolved
			end
			local count = 0
			for key in pairs(source) do
				if type(key) ~= "number" or key % 1 ~= 0 or key < 1 or key > #source then
					return nil, failure("invalid_recipe", "Recipe lists must be dense arrays", path .. ".values")
				end
				count += 1
			end
			if count ~= #source then return nil, failure("invalid_recipe", "Recipe lists must be dense arrays", path .. ".values") end
			return table.freeze(result), nil
		elseif kind == "object" then
			local err = closed(value, { kind = true, fields = true }, { kind = true, fields = true }, path)
			if err then return nil, err end
			local fields = rawget(value, "fields")
			if type(fields) ~= "table" then return nil, failure("invalid_recipe", "Recipe object fields must be a table", path .. ".fields") end
			local keys, fieldsErr = sortedStringKeys(fields, path .. ".fields")
			if keys == nil then return nil, fieldsErr end
			local result = {}
			for _, key in keys do
				local resolved, resolveErr = resolveValue(rawget(fields, key), path .. ".fields." .. key, depth + 1)
				if resolveErr then return nil, resolveErr end
				result[key] = resolved
			end
			return table.freeze(result), nil
		end
		return nil, failure("invalid_recipe_kind", "Recipe kind is invalid", path .. ".kind")
	end
	resolveRecipe = function(id: string, depth: number): (any?, StructuredErrorValue?)
		if state[id] == "resolving" then return nil, failure("recipe_cycle", "Recipes cannot contain cyclic references", "$.recipes." .. id) end
		if state[id] == "resolved" then return values[id], nil end
		state[id] = "resolving"
		local resolved, resolveErr = resolveValue(rawget(recipes, id), "$.recipes." .. id, depth)
		if resolveErr then state[id] = nil return nil, resolveErr end
		state[id] = "resolved"
		values[id] = resolved
		return resolved, nil
	end
	for _, id in recipeKeys do
		local _, resolveErr = resolveRecipe(id, 0)
		if resolveErr then return nil, resolveErr end
	end
	local result = table.freeze(values)
	publish(self, "resolved", { recipes = #recipeKeys })
	return result, nil
end

return RecipeResolver

end

__modules["customization/SchemaCodec"] = function()
--!strict

local StructuredError = __require("core/StructuredError")

export type StructuredErrorValue = StructuredError.StructuredError
export type ScanCounters = {
	depth: number,
	nodes: number,
	entries: number,
	stringBytes: number,
}
export type Codec = {
	PreScanPortable: (self: Codec, value: any, path: string?) -> (boolean, StructuredErrorValue?),
	DeepCopy: (self: Codec, value: any) -> (any?, StructuredErrorValue?),
	Normalize: (self: Codec, value: any) -> (any?, StructuredErrorValue?),
	Hash: (self: Codec, value: any) -> (string?, StructuredErrorValue?),
	ParseLocalId: (self: Codec, value: any, path: string?) -> (string?, StructuredErrorValue?),
	ParseNamespacedId: (self: Codec, value: any, path: string?) -> (string?, StructuredErrorValue?),
	ParseVersion: (self: Codec, value: any, path: string?) -> (any?, StructuredErrorValue?),
	ParseContributionDescriptor: (self: Codec, value: any) -> (any?, StructuredErrorValue?),
	ParseMigrationDeclaration: (self: Codec, value: any) -> (any?, StructuredErrorValue?),
	ParseActionDescriptor: (self: Codec, value: any, source: string?) -> (any?, StructuredErrorValue?),
	ParseBindingSpec: (self: Codec, value: any) -> (any?, StructuredErrorValue?),
}

local SchemaCodec = {}
SchemaCodec.__index = SchemaCodec

local MAX_DEPTH = 32
local MAX_NODES = 4096
local MAX_TABLE_ENTRIES = 512
local MAX_KEY_BYTES = 128
local MAX_STRING_BYTES = 8192
local MAX_TOTAL_STRING_BYTES = 1048576
local MAX_TOTAL_ENTRIES = 16384

local RESERVED_PREFIXES = { "host.", "system.", "legacy." }
local VERSION_AXES = {
	apiVersion = true,
	extensionApiVersion = true,
	skinSchemaVersion = true,
	skinContentVersion = true,
	menuSchemaVersion = true,
	workspaceSchemaVersion = true,
	packageVersion = true,
	adapterSchemaVersion = true,
}
local CONTRIBUTION_KINDS = { skin = true, menu = true, layout = true, control = true, content = true, container = true }
local REFERENCE_KINDS = CONTRIBUTION_KINDS
local ACTION_MODES = { push = true, replace = true }
local BINDING_SOURCES = { store = true, resource = true, route = true, form = true }
local BINDING_MODES = { oneWay = true, twoWay = true }
local BINDING_UPDATES = { user = true, program = true, load = true, migration = true, ["schema-update"] = true }

type ScanState = {
	depth: number,
	nodes: number,
	entries: number,
	stringBytes: number,
	active: { [table]: boolean },
}

local function finiteNumber(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end
local function validUtf8(value: string): boolean
	return utf8.len(value) ~= nil
end


local function failure(code: string, message: string, path: string?, details: any?): StructuredErrorValue
	return StructuredError.from(code, message, {
		domain = "schemaCodec",
		operation = "validate",
		path = path,
		details = details,
	})
end

local function childPath(parent: string, key: any): string
	if type(key) == "string" and string.match(key, "^[A-Za-z_][A-Za-z0-9_]*$") then
		return parent .. "." .. key
	end
	return parent .. "[" .. string.format("%q", tostring(key)) .. "]"
end

local function sortedKeys(value: table): ({ number }, { string }, StructuredErrorValue?)
	local numericKeys = {}
	local stringKeys = {}
	local key = next(value, nil)
	while key ~= nil do
		local keyType = type(key)
		if keyType == "number" then
			if not finiteNumber(key) then
				return numericKeys, stringKeys, failure("portable_input_type", "Portable table keys must be finite numbers or strings")
			end
			table.insert(numericKeys, key)
		elseif keyType == "string" then
			if #key > MAX_KEY_BYTES then
				return numericKeys, stringKeys, failure("portable_input_limit", "Portable table key exceeds the byte limit")
			end
			if not validUtf8(key) then
				return numericKeys, stringKeys, failure("portable_input_type", "Portable table keys must be UTF-8 strings")
			end
			table.insert(stringKeys, key)
		else
			return numericKeys, stringKeys, failure("portable_input_type", "Portable table keys must be finite numbers or strings")
		end
		key = next(value, key)
	end
	table.sort(numericKeys)
	table.sort(stringKeys)
	return numericKeys, stringKeys, nil
end

local function scan(value: any, state: ScanState, depth: number, path: string): StructuredErrorValue?
	if depth > MAX_DEPTH then
		return failure("portable_input_limit", "Portable input exceeds the maximum depth", path, { limit = MAX_DEPTH })
	end
	state.depth = math.max(state.depth, depth)
	local kind = type(value)
	if kind == "nil" or kind == "boolean" then return nil end
	if kind == "number" then
		if finiteNumber(value) then return nil end
		return failure("portable_input_type", "Portable input cannot contain non-finite numbers", path)
	end
	if kind == "string" then
		if #value > MAX_STRING_BYTES then
			return failure("portable_input_limit", "Portable string exceeds the byte limit", path, { limit = MAX_STRING_BYTES })
		end
		if not validUtf8(value) then
			return failure("portable_input_type", "Portable input strings must be UTF-8", path)
		end
		state.stringBytes += #value
		if state.stringBytes > MAX_TOTAL_STRING_BYTES then
			return failure("portable_input_limit", "Portable input exceeds the total string byte limit", path, { limit = MAX_TOTAL_STRING_BYTES })
		end
		return nil
	end
	if kind ~= "table" then
		return failure("portable_input_type", "Portable input contains an unsupported value type", path, { valueType = kind })
	end
	if getmetatable(value) ~= nil then
		return failure("portable_input_type", "Portable input cannot contain tables with metatables", path)
	end
	if state.active[value] then
		return failure("portable_input_cycle", "Portable input cannot contain cycles", path)
	end
	state.nodes += 1
	if state.nodes > MAX_NODES then
		return failure("portable_input_limit", "Portable input exceeds the table node limit", path, { limit = MAX_NODES })
	end
	state.active[value] = true
	local entries = 0
	local key = next(value, nil)
	while key ~= nil do
		entries += 1
		state.entries += 1
		if entries > MAX_TABLE_ENTRIES then
			state.active[value] = nil
			return failure("portable_input_limit", "Portable table exceeds the entry limit", path, { limit = MAX_TABLE_ENTRIES })
		end
		if state.entries > MAX_TOTAL_ENTRIES then
			state.active[value] = nil
			return failure("portable_input_limit", "Portable input exceeds the total entry limit", path, { limit = MAX_TOTAL_ENTRIES })
		end
		if type(key) == "string" and #key > MAX_KEY_BYTES then
			state.active[value] = nil
			return failure("portable_input_limit", "Portable table key exceeds the byte limit", childPath(path, key), { limit = MAX_KEY_BYTES })
		end
		if type(key) == "string" and not validUtf8(key) then
			state.active[value] = nil
			return failure("portable_input_type", "Portable table keys must be UTF-8 strings", path)
		end
		if type(key) == "string" then
			state.stringBytes += #key
			if state.stringBytes > MAX_TOTAL_STRING_BYTES then
				state.active[value] = nil
				return failure("portable_input_limit", "Portable input exceeds the total string byte limit", childPath(path, key), { limit = MAX_TOTAL_STRING_BYTES })
			end
		end
		if type(key) ~= "string" and (type(key) ~= "number" or not finiteNumber(key)) then
			state.active[value] = nil
			return failure("portable_input_type", "Portable table keys must be finite numbers or strings", path)
		end
		local result = scan(rawget(value, key), state, depth + 1, childPath(path, key))
		if result ~= nil then
			state.active[value] = nil
			return result
		end
		key = next(value, key)
	end
	state.active[value] = nil
	return nil
end

local function deepCopy(value: any): any
	if type(value) ~= "table" then return value end
	local numericKeys, stringKeys = sortedKeys(value)
	local result = {}
	for _, key in numericKeys do result[key] = deepCopy(rawget(value, key)) end
	for _, key in stringKeys do result[key] = deepCopy(rawget(value, key)) end
	return table.freeze(result)
end

local function frozenResult(source: any, fields: { [string]: any }): any
	local extensions = rawget(source, "extensions")
	if extensions ~= nil then fields.extensions = deepCopy(extensions) end
	return table.freeze(fields)
end

local function closed(value: any, allowed: { [string]: boolean }, required: { [string]: boolean }, path: string): StructuredErrorValue?
	if type(value) ~= "table" then return failure("invalid_schema", "Schema value must be a table", path) end
	local key = next(value, nil)
	while key ~= nil do
		if type(key) ~= "string" or (key ~= "extensions" and not allowed[key]) then
			return failure("unknown_schema_field", "Schema contains an unknown field", childPath(path, key))
		end
		key = next(value, key)
	end
	for name in pairs(required) do
		if rawget(value, name) == nil then return failure("missing_schema_field", "Schema is missing a required field", childPath(path, name)) end
	end
	return nil
end

local function localId(value: any, path: string): (string?, StructuredErrorValue?)
	if type(value) ~= "string" or #value == 0 or #value > 64 or string.match(value, "^[A-Za-z][A-Za-z0-9._-]*$") == nil then
		return nil, failure("invalid_local_id", "LocalId must be canonical ASCII and 1 through 64 bytes", path)
	end
	for _, prefix in RESERVED_PREFIXES do
		if string.sub(value, 1, #prefix) == prefix then return nil, failure("invalid_local_id", "LocalId uses a reserved prefix", path) end
	end
	return value, nil
end

local function namespacedId(value: any, path: string): (string?, StructuredErrorValue?)
	if type(value) ~= "string" or #value > 129 then return nil, failure("invalid_namespaced_id", "NamespacedId must be at most 129 bytes", path) end
	local first = string.find(value, ":", 1, true)
	if first == nil or string.find(value, ":", first + 1, true) ~= nil then return nil, failure("invalid_namespaced_id", "NamespacedId must contain exactly one colon", path) end
	local namespace, localPart = string.sub(value, 1, first - 1), string.sub(value, first + 1)
	local namespaceId, namespaceErr = localId(namespace, path)
	if namespaceId == nil then return nil, namespaceErr end
	local localIdValue, localErr = localId(localPart, path)
	if localIdValue == nil then return nil, localErr end
	return value, nil
end


local function validateExtensions(value: any, path: string): StructuredErrorValue?
	if value == nil then return nil end
	if type(value) ~= "table" then return failure("invalid_extensions", "Extensions must be a table", path) end
	local key = next(value, nil)
	while key ~= nil do
		local namespace, namespaceErr = namespacedId(key, childPath(path, key))
		if namespace == nil then return namespaceErr end
		if type(rawget(value, key)) ~= "table" then
			return failure("invalid_extensions", "Each extension value must be a declarative table", childPath(path, key))
		end
		key = next(value, key)
	end
	return nil
end

local function version(value: any, path: string): (any?, StructuredErrorValue?)
	local err = closed(value, { major = true, minor = true, patch = true }, { major = true, minor = true, patch = true }, path)
	if err then return nil, err end
	local result = {}
	for _, field in { "major", "minor", "patch" } do
		local component = rawget(value, field)
		if not finiteNumber(component) or component < 0 or component ~= math.floor(component) then
			return nil, failure("invalid_version", "Version components must be nonnegative integers", childPath(path, field))
		end
		result[field] = component
	end
	return frozenResult(value, result), nil
end

local function encode(value: any, chunks: { string })
	local kind = type(value)
	if kind == "nil" then table.insert(chunks, "n;")
	elseif kind == "boolean" then table.insert(chunks, if value then "b1;" else "b0;")
	elseif kind == "number" then table.insert(chunks, "d" .. string.format("%.17g", value) .. ";")
	elseif kind == "string" then table.insert(chunks, "s" .. tostring(#value) .. ":" .. value)
	else
		local numericKeys, stringKeys = sortedKeys(value)
		table.insert(chunks, "{")
		for _, key in numericKeys do encode(key, chunks); encode(rawget(value, key), chunks) end
		for _, key in stringKeys do encode(key, chunks); encode(rawget(value, key), chunks) end
		table.insert(chunks, "}")
	end
end

local function fnv(bytes: string, seed: number): string
	local hash = seed
	for index = 1, #bytes do hash = (bit32.bxor(hash, string.byte(bytes, index)) * 16777619) % 4294967296 end
	return string.format("%08x", hash)
end

local function publish(self: any, counters: ScanCounters)
	local diagnostics = self._diagnostics
	if diagnostics ~= nil and type(diagnostics.Publish) == "function" then
		pcall(function()
			diagnostics:Publish("schemaCodec", table.freeze({ preScan = table.freeze({ depth = counters.depth, nodes = counters.nodes, entries = counters.entries, stringBytes = counters.stringBytes }) }), self._diagnosticOptions)
		end)
	end
end

function SchemaCodec.new(options: any?): Codec
	local resolved = if type(options) == "table" then options else {}
	return setmetatable({
		_diagnostics = rawget(resolved, "diagnostics"),
		_diagnosticOptions = rawget(resolved, "diagnosticOptions"),
	}, SchemaCodec) :: any
end

function SchemaCodec:PreScanPortable(value: any, path: string?): (boolean, StructuredErrorValue?)
	local state: ScanState = { depth = 0, nodes = 0, entries = 0, stringBytes = 0, active = {} }
	local err = scan(value, state, 0, path or "$")
	publish(self, { depth = state.depth, nodes = state.nodes, entries = state.entries, stringBytes = state.stringBytes })
	return err == nil, err
end

function SchemaCodec:DeepCopy(value: any): (any?, StructuredErrorValue?)
	local ok, err = self:PreScanPortable(value)
	if not ok then return nil, err end
	return deepCopy(value), nil
end

function SchemaCodec:Normalize(value: any): (any?, StructuredErrorValue?)
	return self:DeepCopy(value)
end

function SchemaCodec:Hash(value: any): (string?, StructuredErrorValue?)
	local portable, err = self:PreScanPortable(value)
	if not portable then return nil, err end
	local chunks = {}
	encode(value, chunks)
	local bytes = table.concat(chunks)
	return "fnv1a32x2:" .. fnv(bytes, 2166136261) .. fnv(bytes, 2246822519), nil
end

function SchemaCodec:ParseLocalId(value: any, path: string?): (string?, StructuredErrorValue?) return localId(value, path or "$") end
function SchemaCodec:ParseNamespacedId(value: any, path: string?): (string?, StructuredErrorValue?) return namespacedId(value, path or "$") end
function SchemaCodec:ParseVersion(value: any, path: string?): (any?, StructuredErrorValue?)
	local ok, err = self:PreScanPortable(value, path)
	if not ok then return nil, err end
	return version(value, path or "$")
end

function SchemaCodec:ParseContributionDescriptor(value: any): (any?, StructuredErrorValue?)
	local ok, err = self:PreScanPortable(value)
	if not ok then return nil, err end
	if type(value) ~= "table" then return nil, failure("invalid_schema", "ContributionDescriptor must be a table", "$") end
	local kind = rawget(value, "kind")
	local allowed = if kind == "reference" then { kind = true, id = true, target = true, expectedKind = true } else { kind = true, id = true, definition = true }
	local required = if kind == "reference" then { kind = true, id = true, target = true, expectedKind = true } else { kind = true, id = true, definition = true }
	err = closed(value, allowed, required, "$")
	if err then return nil, err end
	local extensionsErr = validateExtensions(rawget(value, "extensions"), "$.extensions")
	if extensionsErr then return nil, extensionsErr end
	if kind ~= "reference" and not CONTRIBUTION_KINDS[kind] then return nil, failure("invalid_contribution_kind", "ContributionDescriptor kind is invalid", "$.kind") end
	local id, idErr = namespacedId(rawget(value, "id"), "$.id"); if not id then return nil, idErr end
	if kind == "reference" then
		local target, targetErr = namespacedId(rawget(value, "target"), "$.target"); if not target then return nil, targetErr end
		if not REFERENCE_KINDS[rawget(value, "expectedKind")] then return nil, failure("invalid_contribution_kind", "Reference expectedKind is invalid", "$.expectedKind") end
		return frozenResult(value, { kind = kind, id = id, target = target, expectedKind = rawget(value, "expectedKind") }), nil
	end
	if type(rawget(value, "definition")) ~= "table" then return nil, failure("invalid_contribution_definition", "Contribution definition must be a portable table", "$.definition") end
	return frozenResult(value, { kind = kind, id = id, definition = deepCopy(rawget(value, "definition")) }), nil
end

function SchemaCodec:ParseMigrationDeclaration(value: any): (any?, StructuredErrorValue?)
	local ok, err = self:PreScanPortable(value); if not ok then return nil, err end
	err = closed(value, { id = true, axis = true, from = true, to = true, implementationId = true, reversible = true, preservesUnknown = true }, { id = true, axis = true, from = true, to = true, implementationId = true, reversible = true, preservesUnknown = true }, "$"); if err then return nil, err end
	local extensionsErr = validateExtensions(rawget(value, "extensions"), "$.extensions"); if extensionsErr then return nil, extensionsErr end
	local id, idErr = localId(rawget(value, "id"), "$.id"); if not id then return nil, idErr end
	if not VERSION_AXES[rawget(value, "axis")] then return nil, failure("invalid_version_axis", "Migration axis is invalid", "$.axis") end
	local from, fromErr = version(rawget(value, "from"), "$.from"); if not from then return nil, fromErr end
	local to, toErr = version(rawget(value, "to"), "$.to"); if not to then return nil, toErr end
	local implementationId, implementationErr = namespacedId(rawget(value, "implementationId"), "$.implementationId"); if not implementationId then return nil, implementationErr end
	if type(rawget(value, "reversible")) ~= "boolean" or rawget(value, "preservesUnknown") ~= "semantic" then return nil, failure("invalid_migration_declaration", "Migration declaration has invalid fixed fields", "$") end
	return frozenResult(value, { id = id, axis = rawget(value, "axis"), from = from, to = to, implementationId = implementationId, reversible = rawget(value, "reversible"), preservesUnknown = "semantic" }), nil
end
function SchemaCodec:ParseActionDescriptor(value: any, source: string?): (any?, StructuredErrorValue?)
	local ok, err = self:PreScanPortable(value)
	if not ok then return nil, err end
	if type(value) ~= "table" then return nil, failure("invalid_schema", "ActionDescriptor must be a table", "$") end
	local kind = rawget(value, "kind")
	local allowed = if kind == "command" then { kind = true, id = true, commandId = true, confirmation = true } elseif kind == "navigation" then { kind = true, id = true, routeId = true, mode = true } elseif kind == "trusted-callback" then { kind = true, id = true, callbackHandle = true, confirmation = true } else {}
	local required = if kind == "command" then { kind = true, id = true, commandId = true } elseif kind == "navigation" then { kind = true, id = true, routeId = true, mode = true } elseif kind == "trusted-callback" then { kind = true, id = true, callbackHandle = true } else {}
	err = closed(value, allowed, required, "$")
	if err then return nil, err end
	local extensionsErr = validateExtensions(rawget(value, "extensions"), "$.extensions")
	if extensionsErr then return nil, extensionsErr end
	if kind == "trusted-callback" then return nil, failure(if source == "trusted" then "unresolved_callback" else "portable_source_forbidden", "Trusted callbacks cannot be portable", "$.kind") end
	local id, idErr = localId(rawget(value, "id"), "$.id")
	if not id then return nil, idErr end
	if kind == "command" then
		local commandId, commandErr = namespacedId(rawget(value, "commandId"), "$.commandId")
		if not commandId then return nil, commandErr end
		return frozenResult(value, { kind = kind, id = id, commandId = commandId, confirmation = deepCopy(rawget(value, "confirmation")) }), nil
	end
	if kind == "navigation" then
		local routeId, routeErr = namespacedId(rawget(value, "routeId"), "$.routeId")
		if not routeId then return nil, routeErr end
		if not ACTION_MODES[rawget(value, "mode")] then return nil, failure("invalid_action_mode", "Navigation mode is invalid", "$.mode") end
		return frozenResult(value, { kind = kind, id = id, routeId = routeId, mode = rawget(value, "mode") }), nil
	end
	return nil, failure("invalid_action_kind", "ActionDescriptor kind is invalid", "$.kind")
end

function SchemaCodec:ParseBindingSpec(value: any): (any?, StructuredErrorValue?)
	local ok, err = self:PreScanPortable(value); if not ok then return nil, err end
	err = closed(value, { source = true, id = true, mode = true, update = true }, { source = true, id = true, mode = true, update = true }, "$"); if err then return nil, err end
	local extensionsErr = validateExtensions(rawget(value, "extensions"), "$.extensions"); if extensionsErr then return nil, extensionsErr end
	if not BINDING_SOURCES[rawget(value, "source")] or not BINDING_MODES[rawget(value, "mode")] or not BINDING_UPDATES[rawget(value, "update")] then return nil, failure("invalid_binding_spec", "BindingSpec contains an invalid literal", "$") end
	local id, idErr = namespacedId(rawget(value, "id"), "$.id"); if not id then return nil, idErr end
	return frozenResult(value, { source = rawget(value, "source"), id = id, mode = rawget(value, "mode"), update = rawget(value, "update") }), nil
end

return SchemaCodec

end

__modules["customization/SkinCompiler"] = function()
--!strict

local StructuredError = __require("core/StructuredError")
local SchemaCodec = __require("customization/SchemaCodec")
local RecipeResolver = __require("customization/RecipeResolver")
local Theme = __require("core/Theme")

export type StructuredErrorValue = StructuredError.StructuredError
export type SkinRegistration = {
	Unregister: (self: SkinRegistration) -> boolean,
}
export type SkinCompiler = {
	Register: (self: SkinCompiler, definition: any) -> (boolean, StructuredErrorValue?),
	RegisterOwned: (self: SkinCompiler, definition: any, owner: any) -> (SkinRegistration?, StructuredErrorValue?),
	Unregister: (self: SkinCompiler, id: string) -> (boolean, StructuredErrorValue?),
	Get: (self: SkinCompiler, id: string) -> (any?, StructuredErrorValue?),
	Compile: (self: SkinCompiler, source: any, context: any?) -> (any?, StructuredErrorValue?),
}

local SkinCompiler = {}
SkinCompiler.__index = SkinCompiler

local MAX_SKINS = 128
local MAX_INHERITANCE_DEPTH = 16
local MAX_MAP_ENTRIES = 256


-- Colors in portable skins are opaque #RRGGBB strings; runtime Color3 values
-- are deliberately decoded only by the material renderer.
local function portableColor(value: any): boolean
	return type(value) == "string" and #value == 7 and string.sub(value, 1, 1) == "#" and string.match(string.sub(value, 2), "^[%x]+$") ~= nil
end
local function failure(code: string, message: string, path: string?, details: any?): StructuredErrorValue
	return StructuredError.from(code, message, {
		domain = "skinCompiler",
		operation = "compile",
		path = path,
		details = details,
	})
end

local function closed(value: any, allowed: { [string]: boolean }, required: { [string]: boolean }, path: string): StructuredErrorValue?
	if type(value) ~= "table" then return failure("invalid_skin_definition", "Skin definition must be a table", path) end
	local key = next(value, nil)
	while key ~= nil do
		if type(key) ~= "string" or not allowed[key] then return failure("unknown_skin_field", "Skin definition contains an unknown field", path) end
		key = next(value, key)
	end
	for field in pairs(required) do
		if rawget(value, field) == nil then return failure("missing_skin_field", "Skin definition is missing a required field", path .. "." .. field) end
	end
	return nil
end

local function sortedKeys(value: table, path: string): ({ string }?, StructuredErrorValue?)
	local keys = {}
	local key = next(value, nil)
	while key ~= nil do
		if type(key) ~= "string" then return nil, failure("invalid_skin_map", "Skin maps must use string keys", path) end
		table.insert(keys, key)
		key = next(value, key)
	end
	table.sort(keys)
	if #keys > MAX_MAP_ENTRIES then return nil, failure("skin_limit", "Skin map exceeds the entry limit", path, { limit = MAX_MAP_ENTRIES }) end
	return keys, nil
end

local function scalar(value: any): boolean
	local kind = type(value)
	return kind == "nil" or kind == "boolean" or kind == "string" or (kind == "number" and value == value and value ~= math.huge and value ~= -math.huge)
end

local function frozenMap(values: { [string]: any }): any
	return table.freeze(values)
end

local function merge(parent: any, child: any): any
	local result = {}
	if type(parent) == "table" then for key, value in pairs(parent) do result[key] = value end end
	if type(child) == "table" then for key, value in pairs(child) do result[key] = value end end
	return table.freeze(result)
end

local function publish(self: any, event: string, details: any)
	local diagnostics = self._diagnostics
	if diagnostics ~= nil and type(diagnostics.Publish) == "function" then
		pcall(function()
			diagnostics:Publish("skinCompiler", table.freeze({ event = event, details = table.freeze(details) }), self._diagnosticOptions)
		end)
	end
end
local function validateRoleReferences(codec: any, recipes: any, roles: any, value: any, path: string, active: { [string]: boolean }, validated: { [string]: boolean }): StructuredErrorValue?
	if type(value) ~= "table" then return nil end
	local kind = rawget(value, "kind")
	if kind == "role" then
		local roleId, roleErr = codec:ParseLocalId(rawget(value, "id"), path .. ".id")
		if roleId == nil then return roleErr end
		local recipeId = rawget(roles, roleId)
		if recipeId == nil then return failure("unresolved_material_role", "Role recipe references an unknown material role", path .. ".id", { role = roleId }) end
		if rawget(recipes, recipeId) == nil then return failure("unresolved_material_role", "Material role references an unknown recipe", path .. ".id", { role = roleId, recipe = recipeId }) end
		if active[recipeId] then return failure("recipe_cycle", "Role recipes cannot contain cyclic references", path .. ".id", { recipe = recipeId }) end
		if validated[recipeId] then return nil end
		active[recipeId] = true
		local nestedErr = validateRoleReferences(codec, recipes, roles, rawget(recipes, recipeId), path .. ".role." .. roleId, active, validated)
		active[recipeId] = nil
		if nestedErr == nil then validated[recipeId] = true end
		return nestedErr
	end
	local children = if kind == "list" then rawget(value, "values") elseif kind == "object" then rawget(value, "fields") else nil
	if type(children) ~= "table" then return nil end
	for key, child in pairs(children) do
		local childErr = validateRoleReferences(codec, recipes, roles, child, path .. "." .. tostring(key), active, validated)
		if childErr ~= nil then return childErr end
	end
	return nil
end


function SkinCompiler.new(options: any?): SkinCompiler
	local resolved = if type(options) == "table" then options else {}
	local codec = rawget(resolved, "codec") or SchemaCodec.new()
	return setmetatable({
		_codec = codec,
		_recipeResolver = rawget(resolved, "recipeResolver") or RecipeResolver.new({ codec = codec, diagnostics = rawget(resolved, "diagnostics"), diagnosticOptions = rawget(resolved, "diagnosticOptions") }),
		_diagnostics = rawget(resolved, "diagnostics"),
		_diagnosticOptions = rawget(resolved, "diagnosticOptions"),
		_skins = {},
		_skinOwnership = {},
		_skinCount = 0,
	}, SkinCompiler)
end

function SkinCompiler:_parseMap(value: any, path: string, validator: (any, string) -> (any?, StructuredErrorValue?)): (any?, StructuredErrorValue?)
	if value == nil then return table.freeze({}), nil end
	if type(value) ~= "table" then return nil, failure("invalid_skin_map", "Skin map must be a table", path) end
	local keys, keysErr = sortedKeys(value, path)
	if keys == nil then return nil, keysErr end
	local result = {}
	for _, key in keys do
		local id, idErr = self._codec:ParseLocalId(key, path .. "." .. key)
		if id == nil then return nil, idErr end
		local parsed, parseErr = validator(rawget(value, key), path .. "." .. key)
		if parseErr then return nil, parseErr end
		result[id] = parsed
	end
	return frozenMap(result), nil
end

function SkinCompiler:_parseDefinition(value: any, path: string): (any?, StructuredErrorValue?)
	local ok, scanErr = self._codec:PreScanPortable(value, path)
	if not ok then return nil, scanErr end
	local err = closed(value, {
		id = true, schemaVersion = true, contentVersion = true, inherits = true,
		semanticTokens = true, materialRoles = true, metrics = true, recipes = true, variants = true,
	}, { id = true, schemaVersion = true, contentVersion = true }, path)
	if err then return nil, err end
	local id, idErr = self._codec:ParseNamespacedId(rawget(value, "id"), path .. ".id")
	if id == nil then return nil, idErr end
	local schemaVersion, schemaErr = self._codec:ParseVersion(rawget(value, "schemaVersion"), path .. ".schemaVersion")
	if schemaVersion == nil then return nil, schemaErr end
	local contentVersion, contentErr = self._codec:ParseVersion(rawget(value, "contentVersion"), path .. ".contentVersion")
	if contentVersion == nil then return nil, contentErr end
	local inherits = rawget(value, "inherits")
	if inherits ~= nil then
		inherits, idErr = self._codec:ParseNamespacedId(inherits, path .. ".inherits")
		if inherits == nil then return nil, idErr end
	end
	local tokens, tokensErr = self:_parseMap(rawget(value, "semanticTokens"), path .. ".semanticTokens", function(token, tokenPath)
		if not scalar(token) then return nil, failure("invalid_semantic_token", "Semantic tokens must be scalar declarative values", tokenPath) end
		if string.match(tokenPath, "%.color%.[^.]+$") ~= nil and not portableColor(token) then
			return nil, failure("invalid_portable_color", "Color tokens must use portable #RRGGBB strings", tokenPath)
		end
		return token, nil
	end)
	if tokens == nil then return nil, tokensErr end
	local metrics, metricsErr = self:_parseMap(rawget(value, "metrics"), path .. ".metrics", function(metric, metricPath)
		if type(metric) ~= "number" or metric ~= metric or metric == math.huge or metric == -math.huge then return nil, failure("invalid_metric", "Metrics must be finite numbers", metricPath) end
		return metric, nil
	end)
	if metrics == nil then return nil, metricsErr end
	local roles, rolesErr = self:_parseMap(rawget(value, "materialRoles"), path .. ".materialRoles", function(role, rolePath)
		local recipeId, recipeErr = self._codec:ParseLocalId(role, rolePath)
		if recipeId == nil then return nil, recipeErr end
		return recipeId, nil
	end)
	if roles == nil then return nil, rolesErr end
	local recipes, recipesErr = self:_parseMap(rawget(value, "recipes"), path .. ".recipes", function(recipe, recipePath)
		if type(recipe) ~= "table" then return nil, failure("invalid_recipe", "Recipes must be declarative tables", recipePath) end
		local normalized, normalizeErr = self._codec:Normalize(recipe)
		if normalized == nil then return nil, normalizeErr end
		return normalized, nil
	end)
	if recipes == nil then return nil, recipesErr end
	local variants, variantsErr = self:_parseMap(rawget(value, "variants"), path .. ".variants", function(variant, variantPath)
		local variantErr = closed(variant, { semanticTokens = true, materialRoles = true, metrics = true, recipes = true }, {}, variantPath)
		if variantErr then return nil, variantErr end
		local variantTokens, tokenErr = self:_parseMap(rawget(variant, "semanticTokens"), variantPath .. ".semanticTokens", function(token, tokenPath)
			if not scalar(token) then return nil, failure("invalid_semantic_token", "Semantic tokens must be scalar declarative values", tokenPath) end
			if string.match(tokenPath, "%.color%.[^.]+$") ~= nil and not portableColor(token) then
				return nil, failure("invalid_portable_color", "Color tokens must use portable #RRGGBB strings", tokenPath)
			end
			return token, nil
		end)
		if variantTokens == nil then return nil, tokenErr end
		local variantMetrics, metricErr = self:_parseMap(rawget(variant, "metrics"), variantPath .. ".metrics", function(metric, metricPath)
			if type(metric) ~= "number" or metric ~= metric or metric == math.huge or metric == -math.huge then return nil, failure("invalid_metric", "Metrics must be finite numbers", metricPath) end
			return metric, nil
		end)
		if variantMetrics == nil then return nil, metricErr end
		local variantRoles, roleErr = self:_parseMap(rawget(variant, "materialRoles"), variantPath .. ".materialRoles", function(role, rolePath)
			local recipeId, recipeErr = self._codec:ParseLocalId(role, rolePath)
			if recipeId == nil then return nil, recipeErr end
			return recipeId, nil
		end)
		if variantRoles == nil then return nil, roleErr end
		local variantRecipes, recipeErr = self:_parseMap(rawget(variant, "recipes"), variantPath .. ".recipes", function(recipe, recipePath)
			if type(recipe) ~= "table" then return nil, failure("invalid_recipe", "Recipes must be declarative tables", recipePath) end
			return self._codec:Normalize(recipe)
		end)
		if variantRecipes == nil then return nil, recipeErr end
		return table.freeze({ semanticTokens = variantTokens, metrics = variantMetrics, materialRoles = variantRoles, recipes = variantRecipes }), nil
	end)
	if variants == nil then return nil, variantsErr end
	return table.freeze({ id = id, schemaVersion = schemaVersion, contentVersion = contentVersion, inherits = inherits, semanticTokens = tokens, metrics = metrics, materialRoles = roles, recipes = recipes, variants = variants }), nil
end

local function validateRegistration(self: any, parsed: any): StructuredErrorValue?
	if parsed.inherits ~= nil then return nil end
	local validated = {}
	for recipeId, recipe in pairs(parsed.recipes) do
		if not validated[recipeId] then
			local roleErr = validateRoleReferences(self._codec, parsed.recipes, parsed.materialRoles, recipe, "$.recipes." .. recipeId, { [recipeId] = true }, validated)
			if roleErr ~= nil then return roleErr end
			validated[recipeId] = true
		end
	end
	return nil
end

function SkinCompiler:_removeOwned(id: string, owner: any, token: any): boolean
	local ownership = rawget(self._skinOwnership, id)
	if type(ownership) ~= "table" or ownership.owner ~= owner or ownership.token ~= token then return false end
	self._skins[id] = nil
	self._skinOwnership[id] = nil
	self._skinCount -= 1
	publish(self, "unregistered", { id = id })
	return true
end

function SkinCompiler:_register(parsed: any, owner: any): (SkinRegistration?, StructuredErrorValue?)
	local existing = rawget(self._skins, parsed.id)
	if existing ~= nil then
		local ownership = rawget(self._skinOwnership, parsed.id)
		if type(ownership) ~= "table" or ownership.owner ~= owner then
			return nil, failure("skin_owner_collision", "Skin id is already owned by another registration", "$.id", { id = parsed.id })
		end
	elseif self._skinCount >= MAX_SKINS then
		return nil, failure("skin_registry_limit", "Skin registry exceeds the limit", "$.id", { limit = MAX_SKINS })
	end
	local token = {}
	if existing == nil then self._skinCount += 1 end
	self._skins[parsed.id] = parsed
	self._skinOwnership[parsed.id] = { owner = owner, token = token }
	publish(self, "registered", { id = parsed.id })
	local compiler = self
	local released = false
	local registration = {}
	function registration:Unregister(): boolean
		if released then return false end
		released = true
		return compiler:_removeOwned(parsed.id, owner, token)
	end
	return registration :: SkinRegistration, nil
end

function SkinCompiler:Register(definition: any): (boolean, StructuredErrorValue?)
	local parsed, parseErr = self:_parseDefinition(definition, "$")
	if parsed == nil then return false, parseErr end
	local roleErr = validateRegistration(self, parsed)
	if roleErr ~= nil then return false, roleErr end
	local registration, registerErr = self:_register(parsed, nil)
	if registration == nil then return false, registerErr end
	return true, nil
end

function SkinCompiler:RegisterOwned(definition: any, rawOwner: any): (SkinRegistration?, StructuredErrorValue?)
	local owner, ownerErr = self._codec:ParseNamespacedId(rawOwner, "$.owner")
	if owner == nil then return nil, ownerErr end
	local parsed, parseErr = self:_parseDefinition(definition, "$")
	if parsed == nil then return nil, parseErr end
	local roleErr = validateRegistration(self, parsed)
	if roleErr ~= nil then return nil, roleErr end
	return self:_register(parsed, owner)
end

function SkinCompiler:Unregister(id: string): (boolean, StructuredErrorValue?)
	local validId, idErr = self._codec:ParseNamespacedId(id, "$.id")
	if validId == nil then return false, idErr end
	local ownership = rawget(self._skinOwnership, validId)
	if type(ownership) ~= "table" then return false, failure("unknown_skin", "Skin is not registered", "$.id", { id = validId }) end
	if ownership.owner ~= nil then return false, failure("skin_owner_mismatch", "Skin is owned by an extension registration", "$.id", { id = validId }) end
	if not self:_removeOwned(validId, nil, ownership.token) then return false, failure("unknown_skin", "Skin is not registered", "$.id", { id = validId }) end
	return true, nil
end

function SkinCompiler:Get(id: string): (any?, StructuredErrorValue?)
	local validId, idErr = self._codec:ParseNamespacedId(id, "$.id")
	if validId == nil then return nil, idErr end
	local definition = rawget(self._skins, validId)
	if definition == nil then return nil, failure("unknown_skin", "Skin is not registered", "$.id", { id = validId }) end
	return definition, nil
end

function SkinCompiler:Compile(source: any, context: any?): (any?, StructuredErrorValue?)
	local sourceDefinition: any
	if type(source) == "string" then
		local sourceId, sourceErr = self._codec:ParseNamespacedId(source, "$.source")
		if sourceId == nil then return nil, sourceErr end
		sourceDefinition = rawget(self._skins, sourceId)
		if sourceDefinition == nil then return nil, failure("unknown_skin", "Skin is not registered", "$.source", { id = sourceId }) end
	else
		local parseErr: StructuredErrorValue?
		sourceDefinition, parseErr = self:_parseDefinition(source, "$.source")
		if sourceDefinition == nil then return nil, parseErr end
	end
	local resolvedContext = if context == nil then {} else context
	if type(resolvedContext) ~= "table" then return nil, failure("invalid_skin_context", "Skin context must be a table", "$.context") end
	local contextForScan = { variant = rawget(resolvedContext, "variant") }
	local ok, scanErr = self._codec:PreScanPortable(contextForScan, "$.context")
	if not ok then return nil, scanErr end
	local contextErr = closed(resolvedContext, { variant = true, theme = true }, {}, "$.context")
	if contextErr then return nil, contextErr end
	local themeMetadata = nil
	local suppliedTheme = rawget(resolvedContext, "theme")
	if suppliedTheme ~= nil then
		if type(suppliedTheme) ~= "table" then return nil, failure("invalid_theme_metadata", "Theme context must be a resolved theme or Theme.resolveDetailed result", "$.context.theme") end
		local themeInput = if type(rawget(suppliedTheme, "theme")) == "table" then rawget(suppliedTheme, "theme") else suppliedTheme
		local detail, themeError = Theme.resolveDetailed(themeInput)
		if detail == nil then return nil, failure("invalid_theme_metadata", tostring(themeError and themeError.message), "$.context.theme") end
		themeMetadata = detail
	end
	local variant = rawget(resolvedContext, "variant")
	if variant ~= nil then
		local variantErr: StructuredErrorValue?
		variant, variantErr = self._codec:ParseLocalId(variant, "$.context.variant")
		if variant == nil then return nil, variantErr end
	end
	local lineage = {}
	local active: { [string]: boolean } = {}
	local function visit(definition: any, depth: number): StructuredErrorValue?
		if depth > MAX_INHERITANCE_DEPTH then return failure("inheritance_depth_limit", "Skin inheritance exceeds the maximum depth", "$.source.inherits", { limit = MAX_INHERITANCE_DEPTH }) end
		if active[definition.id] then return failure("skin_inheritance_cycle", "Skin inheritance cannot contain a cycle", "$.source.inherits", { id = definition.id }) end
		active[definition.id] = true
		if definition.inherits ~= nil then
			local parent = rawget(self._skins, definition.inherits)
			if parent == nil then return failure("unresolved_skin_inheritance", "Inherited skin is not registered", "$.source.inherits", { id = definition.inherits }) end
			local parentErr = visit(parent, depth + 1)
			if parentErr then return parentErr end
		end
		active[definition.id] = nil
		table.insert(lineage, definition)
		return nil
	end
	local inheritanceErr = visit(sourceDefinition, 0)
	if inheritanceErr then return nil, inheritanceErr end
	local tokens, metrics, roles, recipes = table.freeze({}), table.freeze({}), table.freeze({}), table.freeze({})
	local variantFound = variant == nil
	local resolvedInheritance = {}
	for _, definition in lineage do
		tokens = merge(tokens, definition.semanticTokens)
		metrics = merge(metrics, definition.metrics)
		roles = merge(roles, definition.materialRoles)
		recipes = merge(recipes, definition.recipes)
		table.insert(resolvedInheritance, definition.id)
		if variant ~= nil then
			local patch = rawget(definition.variants, variant)
			if patch ~= nil then
				variantFound = true
				tokens = merge(tokens, patch.semanticTokens)
				metrics = merge(metrics, patch.metrics)
				roles = merge(roles, patch.materialRoles)
				recipes = merge(recipes, patch.recipes)
			end
		end
	end
	local validated = {}
	for recipeId, recipe in pairs(recipes) do
		if not validated[recipeId] then
			local roleErr = validateRoleReferences(self._codec, recipes, roles, recipe, "$.recipes." .. recipeId, { [recipeId] = true }, validated)
			if roleErr ~= nil then return nil, roleErr end
			validated[recipeId] = true
		end
	end
	if not variantFound then return nil, failure("unknown_skin_variant", "Requested skin variant is not defined by the resolved inheritance chain", "$.context.variant", { variant = variant }) end
	local resolvedRecipes, recipeErr = self._recipeResolver:Resolve(recipes, { tokens = tokens, metrics = metrics, roles = roles })
	if resolvedRecipes == nil then return nil, recipeErr end
	local resolvedRoles = {}
	for role, recipeId in pairs(roles) do
		local recipe = rawget(resolvedRecipes, recipeId)
		if recipe == nil then return nil, failure("unresolved_material_role", "Material role references an unknown recipe", "$.materialRoles." .. role, { recipe = recipeId }) end
		resolvedRoles[role] = recipe
	end
	resolvedRoles = table.freeze(resolvedRoles)
	local normalizedDefinition = table.freeze({ semanticTokens = tokens, metrics = metrics, materialRoles = roles, recipes = recipes })
	local hash, hashErr = self._codec:Hash({ definition = normalizedDefinition, contentVersion = sourceDefinition.contentVersion, inheritance = resolvedInheritance, variant = variant })
	if hash == nil then return nil, hashErr end
	local plan = table.freeze({
		id = sourceDefinition.id,
		version = sourceDefinition.contentVersion,
		semanticTokens = tokens,
		metrics = metrics,
		materialRoles = resolvedRoles,
		recipes = resolvedRecipes,
		inheritance = table.freeze(resolvedInheritance),
		variant = variant,
		hash = hash,
		themeMetadata = themeMetadata,
	})
	publish(self, "compiled", { id = plan.id, inheritanceDepth = #lineage - 1, variant = variant or "" })
	return plan, nil
end

return SkinCompiler

end

__modules["customization/SlotHost"] = function()
--!strict

local Maid = __require("core/Maid")
local SchemaCodec = __require("customization/SchemaCodec")
local StructuredError = __require("core/StructuredError")

local SlotHost = {}
SlotHost.__index = SlotHost

local function fail(code: string, message: string, operation: string): any
	return StructuredError.from(code, message, { domain = "slotHost", operation = operation })
end
local function publicActual(actual: any): any
	local copy = {}
	for key, value in pairs(actual or {}) do
		if typeof(value) ~= "Instance" then copy[key] = value end
	end
	return table.freeze(copy)
end

local function denseArray(value: any): boolean
	if type(value) ~= "table" then return false end
	local length = #value
	for index = 1, length do
		if rawget(value, index) == nil then return false end
	end
	for key in pairs(value) do
		if type(key) ~= "number" or key < 1 or key > length or key ~= math.floor(key) then return false end
	end
	return true
end
local function snapshot(handle: any): any
	return table.freeze({ id = handle._id, slotId = handle._slotId, ownerId = handle._ownerId,
		generation = handle._generation, state = handle._destroyed and "unmounted" or "mounted",
		bounds = handle._host:_bounds(handle._slotId), revision = handle._revision, actual = publicActual(handle._actual) })
end
local function renderDefault(self: any, definition: any, contribution: any, maid: any): (any?, any?)
	local target = definition.target
	if typeof(target) ~= "Instance" or not target:IsA("GuiObject") then return true, { instances = 0 } end
	local frame = Instance.new("Frame")
	frame.Name = "PotassiumSlotContribution"
	frame.BackgroundTransparency = 1
	frame.BorderSizePixel = 0
	frame.Size = UDim2.fromScale(1, 1)
	frame.Parent = target
	maid:GiveTask(frame)
	local label = Instance.new("TextLabel")
	label.Name = "Content"
	label.BackgroundTransparency = 1
	label.Size = UDim2.fromScale(1, 1)
	local value = contribution.value
	if value == nil then value = contribution.text or contribution.title or contribution.label or contribution.kind or "" end
	label.Text = tostring(value)
	label.Parent = frame
	maid:GiveTask(label)
	local function applyDirection()
		local direction = "LTR"
		local localization = self._localization
		if type(localization) == "table" and type(localization.GetDirection) == "function" then
			local ok, resolved = pcall(function() return localization:GetDirection() end)
			if ok and (resolved == "LTR" or resolved == "RTL") then direction = resolved end
		end
		frame:SetAttribute("LayoutDirection", direction)
		label:SetAttribute("LayoutDirection", direction)
		label.TextXAlignment = if direction == "RTL" then Enum.TextXAlignment.Right else Enum.TextXAlignment.Left
	end
	applyDirection()
	local localization = self._localization
	if type(localization) == "table" and localization.LocaleChanged ~= nil and type(localization.LocaleChanged.Connect) == "function" then
		maid:GiveTask(localization.LocaleChanged:Connect(applyDirection))
	end
	return true, { instances = 2, guiObject = frame }
end
local function stageRender(self: any, definition: any, contribution: any, maid: any): (any?, any?)
	local renderer = self._renderer
	local ok, result, actual
	if type(renderer) == "function" then
		ok, result, actual = pcall(renderer, definition, contribution, maid)
	else
		ok, result, actual = pcall(renderDefault, self, definition, contribution, maid)
	end
	if not ok or result == false then return nil, fail("slot_stage_failed", "Slot contribution could not be staged", "mount") end
	if type(result) == "table" and result.Destroy then maid:GiveTask(result) end
	return actual or (if type(result) == "table" then result else {}), nil
end

local function detachedRoot(definition: any): (GuiObject?, any?)
	local target = definition.target
	if typeof(target) ~= "Instance" or not target:IsA("GuiObject") then
		return nil, fail("slot_stage_failed", "Slot contribution target is unavailable", "mount")
	end
	local ok, root = pcall(function()
		local frame = Instance.new("Frame")
		frame.Name = "PotassiumSlotStage"
		frame.BackgroundTransparency = 1
		frame.BorderSizePixel = 0
		frame.Size = UDim2.fromScale(1, 1)
		frame.Visible = false
		return frame
	end)
	if not ok or typeof(root) ~= "Instance" or not root:IsA("GuiObject") then
		return nil, fail("slot_stage_failed", "Slot contribution could not create a detached stage", "mount")
	end
	return root, nil
end

local function stagedDefinition(definition: any, root: GuiObject): any
	local copy = {}
	for key, value in pairs(definition) do copy[key] = value end
	copy.target = root
	return copy
end
local Handle = {}
Handle.__index = Handle
function Handle:GetSnapshot() return snapshot(self) end
function Handle:Mount(contribution: any): (any?, any?) return self:Replace(contribution) end
function Handle:Update(contribution: any): (any?, any?) return self._host:_swap(self, contribution) end
function Handle:Replace(contribution: any): (any?, any?) return self._host:_swap(self, contribution) end
function Handle:Unmount(): boolean
	if self._destroyed then return true end
	self._destroyed = true
	self._maid:Destroy()
	if self._mountToken then self._mountToken:Unmount() end
	if self._host._handles[self._slotId] == self then self._host._handles[self._slotId] = nil end
	return true
end
Handle.Destroy = Handle.Unmount

function SlotHost.new(options: any): (any?, any?)
	if type(options) ~= "table" or type(options.ownerId) ~= "string" or type(options.slots) ~= "table" then
		return nil, fail("invalid_slot_host", "SlotHost requires ownerId and catalogued slots", "create")
	end
	local codec = SchemaCodec.new()
	local catalog = {}
	for slotId, definition in pairs(options.slots) do
		local parsed, parseError = codec:ParseLocalId(slotId, "slots")
		if parsed == nil then return nil, parseError end
		if type(definition) ~= "table" then return nil, fail("invalid_slot_catalog", "Slot definitions must be tables", "create") end
		catalog[parsed] = definition
	end
	return setmetatable({ _ownerId = options.ownerId, _slots = catalog, _layoutSlots = {}, _handles = {}, _renderer = options.renderer,
		_localization = options.localization, _extensionHost = options.extensionHost, _packId = options.packId, _ownerToken = options.ownerToken, _destroyed = false }, SlotHost), nil
end
-- Replaces the layout-owned portion of the slot catalogue atomically. Layout
-- engines stage every target before calling this, so mounts never observe a
-- partially-applied shell.
function SlotHost:ValidateLayoutSlots(ownerId: any, slots: any): (any?, any?)
	if self._destroyed then return nil, fail("destroyed_slot_host", "SlotHost has been destroyed", "validateLayoutSlots") end
	if type(ownerId) ~= "string" or ownerId == "" or type(slots) ~= "table" then
		return nil, fail("invalid_layout_slots", "Layout slot owner and definitions are required", "validateLayoutSlots")
	end
	local codec = SchemaCodec.new()
	local nextSlots = {}
	for slotId, definition in pairs(slots) do
		local parsed, parseError = codec:ParseLocalId(slotId, "layoutSlots")
		if parsed == nil then return nil, parseError end
		if type(definition) ~= "table" or typeof(definition.target) ~= "Instance" or not definition.target:IsA("GuiObject") then
			return nil, fail("invalid_layout_slots", "Layout slot targets must be GuiObjects", "validateLayoutSlots")
		end
		if self._slots[parsed] ~= nil and self._layoutSlots[parsed] ~= ownerId then
			return nil, fail("layout_slot_conflict", "Layout slot conflicts with an existing catalogue entry", "validateLayoutSlots")
		end
		nextSlots[parsed] = definition
	end
	return nextSlots, nil
end

function SlotHost:ReplaceLayoutSlots(ownerId: any, slots: any, transaction: any?): (any?, any?)
	local nextSlots, validationError = self:ValidateLayoutSlots(ownerId, slots)
	if nextSlots == nil then return nil, validationError end
	local previous = {}
	for slotId, slotOwner in pairs(self._layoutSlots) do
		if slotOwner == ownerId then previous[slotId] = self._slots[slotId] end
	end

	-- A retained slot keeps its public handle, contribution, and extension token.
	-- Render it against the new detached layout target before publishing any
	-- catalogue mutation, so a failed replacement leaves every live mount intact.
	local stagedRetained = {}
	local function discardRetained()
		for _, record in ipairs(stagedRetained) do record.maid:Destroy() end
	end
	for slotId, definition in pairs(nextSlots) do
		local handle = self._handles[slotId]
		if handle ~= nil and self._layoutSlots[slotId] == ownerId then
			local maid = Maid.new()
			local actual, renderError = stageRender(self, definition, handle._contribution, maid)
			if actual == nil then
				maid:Destroy()
				discardRetained()
				return nil, renderError
			end
			table.insert(stagedRetained, { slotId = slotId, handle = handle, maid = maid, actual = actual, prior = table.clone(handle) })
		end
	end
	local removed = {}

	for slotId in pairs(previous) do
		if nextSlots[slotId] == nil then
			local handle = self._handles[slotId]
			if handle ~= nil then
				table.insert(removed, handle)
				handle._destroyed, self._handles[slotId] = true, nil
			end
			self._slots[slotId], self._layoutSlots[slotId] = nil, nil
		end
	end
	for slotId, definition in pairs(nextSlots) do
		self._slots[slotId], self._layoutSlots[slotId] = definition, ownerId
	end
	for _, record in ipairs(stagedRetained) do
		local handle = record.handle
		handle._maid, handle._actual, handle._generation, handle._revision =
			record.maid, record.actual, handle._generation + 1, handle._revision + 1
	end
	local settled = false
	local function finalize()
		if settled then return end
		settled = true
		for _, record in ipairs(stagedRetained) do
			local old = record.prior._maid
			task.defer(function() old:Destroy() end)
		end
		for _, handle in ipairs(removed) do
			handle._maid:Destroy()
			if handle._mountToken then handle._mountToken:Unmount() end
		end
	end
	local function rollback()
		if settled then return false end
		settled = true
		for slotId in pairs(nextSlots) do self._slots[slotId], self._layoutSlots[slotId] = nil, nil end
		for slotId, definition in pairs(previous) do self._slots[slotId], self._layoutSlots[slotId] = definition, ownerId end
		for _, record in ipairs(stagedRetained) do
			table.clear(record.handle)
			for key, value in pairs(record.prior) do record.handle[key] = value end
			record.maid:Destroy()
		end
		for _, handle in ipairs(removed) do
			handle._destroyed, self._handles[handle._slotId] = false, handle
		end
		return true
	end
	if transaction ~= nil then
		transaction.rollback, transaction.finalize = rollback, finalize
	else
		finalize()
	end
	return previous, nil
end
function SlotHost:_bounds(slotId: string): any
	local definition = self._slots[slotId]
	local getter = definition and definition.getBounds
	if type(getter) == "function" then
		local ok, value = pcall(getter)
		if ok and type(value) == "table" then return if table.isfrozen(value) then value else table.freeze(value) end
	end
	return table.freeze({ x = 0, y = 0, width = 0, height = 0 })
end
function SlotHost:GetSlot(slotId: any): (any?, any?)
	if self._destroyed then return nil, fail("destroyed_slot_host", "SlotHost has been destroyed", "getSlot") end
	if type(slotId) ~= "string" or self._slots[slotId] == nil then return nil, fail("unknown_slot", "Slot is not catalogued", "getSlot") end
	return self._slots[slotId], nil
end
function SlotHost:Mount(slotId: any, contribution: any): (any?, any?)
	if self._destroyed then return nil, fail("destroyed_slot_host", "SlotHost has been destroyed", "mount") end
	local definition, definitionError = self:GetSlot(slotId)
	if definition == nil then return nil, definitionError end
	if self._handles[slotId] ~= nil then return self._handles[slotId]:Replace(contribution) end
	local codec = SchemaCodec.new()
	local portable, scanError = codec:PreScanPortable(contribution, "slot")
	if not portable then return nil, scanError end
	local normalized, normalizeError = codec:Normalize(contribution)
	if normalized == nil then return nil, normalizeError end
	local mountToken = nil
	if self._extensionHost and self._packId and self._ownerToken then
		mountToken, normalizeError = self._extensionHost:Mount(self._packId, self._ownerToken)
		if mountToken == nil then return nil, normalizeError end
	end
	local maid = Maid.new()
	local actual, renderError = stageRender(self, definition, normalized, maid)
	if actual == nil then
		maid:Destroy()
		if mountToken then mountToken:Unmount() end
		return nil, renderError
	end
	local handle = setmetatable({ _host = self, _slotId = slotId, _id = self._ownerId .. ":" .. slotId,
		_ownerId = self._ownerId, _generation = 1, _revision = 1, _contribution = normalized, _maid = maid,
		_mountToken = mountToken, _actual = actual, _destroyed = false }, Handle)
	self._handles[slotId] = handle -- all staging completed before publication
	return handle, nil
end
function SlotHost:_swap(handle: any, contribution: any): (any?, any?)
	if handle._destroyed then return nil, fail("destroyed_handle", "SlotHandle has been destroyed", "replace") end
	local codec = SchemaCodec.new(); local portable, scanError = codec:PreScanPortable(contribution, "slot")
	if not portable then return nil, scanError end
	local normalized, normalizeError = codec:Normalize(contribution); if normalized == nil then return nil, normalizeError end
	local staged = Maid.new(); local definition = self._slots[handle._slotId]
	local actual, renderError = stageRender(self, definition, normalized, staged)
	if actual == nil then staged:Destroy(); return nil, renderError end
	local old = handle._maid
	handle._maid, handle._contribution, handle._actual, handle._generation, handle._revision =
		staged, normalized, actual, handle._generation + 1, handle._revision + 1
	task.defer(function() old:Destroy() end)
	return handle, nil
end

-- Builds an isolated replacement batch.  Nothing in this helper is live until
-- publishStaged slots its detached roots into their targets.
local function discardStaged(records: any)
	for _, record in ipairs(records) do
		record.maid:Destroy()
		if record.mountToken then record.mountToken:Unmount() end
	end
end
local function stageSlots(self: any, slotIds: any, contributions: any, operation: string, requireSlots: boolean, definitions: any?): (any?, any?)
	if self._destroyed then return nil, fail("destroyed_slot_host", "SlotHost has been destroyed", operation) end
	if not denseArray(slotIds) or (requireSlots and #slotIds == 0) then
		return nil, fail("invalid_slot_batch", "Slot ids must be a non-empty dense array", operation)
	end
	if type(contributions) ~= "table" then return nil, fail("invalid_slot_batch", "Slot contributions must be a table", operation) end
	local catalogue = definitions or self._slots
	local selected, requested = {}, {}
	for _, slotId in ipairs(slotIds) do
		if type(slotId) ~= "string" or catalogue[slotId] == nil or selected[slotId] then
			return nil, fail("invalid_slot_batch", "Slot ids must be unique catalogued strings", operation)
		end
		selected[slotId] = true
		table.insert(requested, slotId)
	end
	for slotId in pairs(contributions) do
		if type(slotId) ~= "string" or not selected[slotId] then
			return nil, fail("invalid_slot_batch", "Slot contributions must target the requested slots", operation)
		end
	end

	local records, omitted = {}, {}
	for _, slotId in ipairs(requested) do
		local contribution = rawget(contributions, slotId)
		if contribution == nil then
			omitted[slotId] = true
		else
			local codec = SchemaCodec.new()
			local portable, scanError = codec:PreScanPortable(contribution, "slot")
			if not portable then discardStaged(records); return nil, scanError end
			local normalized, normalizeError = codec:Normalize(contribution)
			if normalized == nil then discardStaged(records); return nil, normalizeError end
			local existing = self._handles[slotId]
			local mountToken = nil
			if existing == nil and self._extensionHost and self._packId and self._ownerToken then
				mountToken, normalizeError = self._extensionHost:Mount(self._packId, self._ownerToken)
				if mountToken == nil then discardStaged(records); return nil, normalizeError end
			end
			local root, rootError = detachedRoot(catalogue[slotId])
			if root == nil then
				if mountToken then mountToken:Unmount() end
				discardStaged(records)
				return nil, rootError
			end
			local maid = Maid.new()
			maid:GiveTask(root)
			local actual, renderError = stageRender(self, stagedDefinition(catalogue[slotId], root), normalized, maid)
			if actual == nil then
				maid:Destroy()
				if mountToken then mountToken:Unmount() end
				discardStaged(records)
				return nil, renderError
			end
			table.insert(records, {
				slotId = slotId, existing = existing, normalized = normalized, maid = maid, actual = actual,
				mountToken = mountToken, root = root, target = catalogue[slotId].target,
			})
		end
	end
	return { requested = requested, omitted = omitted, records = records }, nil
end
local function publishStaged(self: any, staged: any)
	for _, record in ipairs(staged.records) do
		record.root.Parent = record.target
		record.root.Visible = true
	end
	staged.removed = {}
	for _, record in ipairs(staged.records) do
		local handle = record.existing
		record.prior = if handle ~= nil then table.clone(handle) else nil
		if handle == nil then
			handle = setmetatable({ _host = self, _slotId = record.slotId, _id = self._ownerId .. ":" .. record.slotId,
				_ownerId = self._ownerId, _generation = 1, _revision = 1, _contribution = record.normalized, _maid = record.maid,
				_mountToken = record.mountToken, _actual = record.actual, _destroyed = false }, Handle)
			self._handles[record.slotId] = handle
		else
			record.retiredMaid = handle._maid
			handle._maid, handle._contribution, handle._actual, handle._generation, handle._revision =
				record.maid, record.normalized, record.actual, handle._generation + 1, handle._revision + 1
		end
		record.handle = handle
	end
	for _, slotId in ipairs(staged.requested) do
		if staged.omitted[slotId] then
			local handle = self._handles[slotId]
			if handle ~= nil then
				table.insert(staged.removed, handle)
				handle._destroyed, self._handles[slotId] = true, nil
			end
		end
	end
end
local function finalizeStaged(staged: any)
	for _, record in ipairs(staged.records) do
		if record.retiredMaid then
			local old = record.retiredMaid
			task.defer(function() old:Destroy() end)
		end
		record.prior, record.retiredMaid = nil, nil
	end
	for _, handle in ipairs(staged.removed or {}) do
		handle._maid:Destroy()
		if handle._mountToken then handle._mountToken:Unmount() end
	end
end
local function rollbackStaged(self: any, staged: any)
	for _, record in ipairs(staged.records) do
		if record.prior then
			table.clear(record.existing)
			for key, value in pairs(record.prior) do record.existing[key] = value end
			self._handles[record.slotId] = record.existing
		elseif record.handle then
			record.handle._destroyed = true
			if self._handles[record.slotId] == record.handle then self._handles[record.slotId] = nil end
		end
	end
	for _, handle in ipairs(staged.removed or {}) do
		handle._destroyed, self._handles[handle._slotId] = false, handle
	end
	discardStaged(staged.records)
end

-- Replaces a bounded slot set by sharing the composition staging and publishing
-- path, so unrelated mounts remain untouched.
function SlotHost:ReplaceSlots(slotIds: any, contributions: any): (boolean, any?)
	local staged, stageError = stageSlots(self, slotIds, contributions, "replaceSlots", true)
	if staged == nil then return false, stageError end
	local published, publishError = pcall(publishStaged, self, staged)
	if not published then rollbackStaged(self, staged); return false, fail("slot_publish_failed", tostring(publishError), "replaceSlots") end
	finalizeStaged(staged)
	return true, nil
end

-- Coordinator-visible transaction seam. Slot contributions are optional in a
-- composition plan; an empty contribution set remains a valid no-op participant.
function SlotHost:PrepareComposition(plan: any): (any?, any?)
	if self._destroyed or type(plan) ~= "table" then return nil, fail("invalid_composition_plan", "Slot composition plan is required", "prepareComposition") end
	local contributions = plan.slots
	if contributions ~= nil and type(contributions) ~= "table" then return nil, fail("invalid_composition_slots", "Composition slots must be a table", "prepareComposition") end
	return { state = "prepared", contributions = contributions or {}, plan = plan }, nil
end
function SlotHost:StageComposition(token: any): (boolean, any?)
	if type(token) ~= "table" or token.state ~= "prepared" then return false, fail("invalid_composition_transaction", "Composition transaction must be prepared", "stageComposition") end
	local ids = {}
	for slotId in pairs(token.contributions) do
		if type(slotId) ~= "string" then return false, fail("invalid_composition_slots", "Composition slot ids must be strings", "stageComposition") end
		table.insert(ids, slotId)
	end
	table.sort(ids)
	local catalogue = self._slots
	if type(token.plan.layoutSlotTargets) == "table" then
		catalogue = {}
		for id, definition in pairs(self._slots) do catalogue[id] = definition end
		for id, definition in pairs(token.plan.layoutSlotTargets) do catalogue[id] = definition end
	end
	local staged, stageError = stageSlots(self, ids, token.contributions, "stageComposition", false, catalogue)
	if staged == nil then return false, stageError end
	token.staged = staged
	token.state = "staged"
	return true, nil
end
function SlotHost:CommitComposition(token: any): (boolean, any?)
	if type(token) ~= "table" or token.state ~= "staged" then return false, fail("invalid_composition_transaction", "Composition transaction must be staged", "commitComposition") end
	local published, publishError = pcall(publishStaged, self, token.staged)
	if not published then return false, fail("slot_publish_failed", tostring(publishError), "commitComposition") end
	token.state = "committed"
	return true, nil
end
function SlotHost:FinalizeComposition(token: any): boolean
	if type(token) ~= "table" or token.state ~= "committed" then return false end
	finalizeStaged(token.staged)
	token.staged = nil
	token.state = "finalized"
	return true
end
function SlotHost:AbortComposition(token: any): boolean
	if type(token) ~= "table" or token.state == "finalized" or token.state == "aborted" then return false end
	if token.staged then
		rollbackStaged(self, token.staged)
		token.staged = nil
	end
	token.state = "aborted"
	return true
end

function SlotHost:GetSnapshot()
	local slots = {}; for id, handle in pairs(self._handles) do slots[id] = snapshot(handle) end
	return table.freeze({ ownerId = self._ownerId, destroyed = self._destroyed, slots = table.freeze(slots) })
end
function SlotHost:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	for _, handle in pairs(self._handles) do handle:Unmount() end
	self._handles = {}
end
return SlotHost

end

__modules["init"] = function()
--!strict

local RuntimeFreeLibrary = __require("RuntimeFreeLibrary")

local Library: any = table.clone(RuntimeFreeLibrary)
local advancedLibrary: any = nil

local framework: any = table.clone(RuntimeFreeLibrary.Framework)
framework.AdvancedEntry = "new"
Library.Framework = table.freeze(framework)

local function advanced(): any
	if advancedLibrary == nil then
		advancedLibrary = __require("AdvancedLibrary")
	end
	return advancedLibrary
end

function Library.new(options: any?)
	return advanced().new(options)
end

setmetatable(Library, {
	__call = function(_, options: any)
		local context, errorValue = Library.new(options)
		if context == nil then
			error((errorValue and errorValue.message) or "Could not create PotassiumUI", 2)
		end
		return context
	end,
	__index = function(_, key: any)
		if key == "bootstrapLite" then
			return nil
		end
		return advanced()[key]
	end,
})

return Library

end

__modules["layout/FlowGroup"] = function()
--!strict

local StructuredError = __require("core/StructuredError")

local FlowGroup = {}
FlowGroup.__index = FlowGroup

local function fail(code: string, message: string): any
	return StructuredError.from(code, message, { domain = "flowGroup", operation = "create" })
end

function FlowGroup.new(engine: any, nodeId: any): (any?, any?)
	if type(engine) ~= "table" or type(engine.RegisterFlowGroup) ~= "function" then return nil, fail("invalid_flow_engine", "FlowGroup requires a LayoutEngine provider") end
	if type(nodeId) ~= "string" or #nodeId == 0 then return nil, fail("invalid_flow_id", "FlowGroup requires a node id") end
	return setmetatable({ _engine = engine, _nodeId = nodeId, _destroyed = false }, FlowGroup), nil
end

function FlowGroup:RequestReflow(): boolean
	if self._destroyed then return false end
	return self._engine:RequestReflow(self._nodeId)
end

function FlowGroup:GetSnapshot(): any
	if self._destroyed then return table.freeze({ id = self._nodeId, destroyed = true }) end
	return self._engine:GetFlowSnapshot(self._nodeId)
end

function FlowGroup:Destroy()
	self._destroyed = true
end

return FlowGroup

end

__modules["models/CompositionDescriptors"] = function()
--!strict

local SchemaCodec = __require("customization/SchemaCodec")
local StructuredError = __require("core/StructuredError")

local CompositionDescriptors = {}

local CONTAINERS = { stack = true, row = true, column = true, card = true, toolbar = true, ["action-bar"] = true }
local CONTENT = { heading = true, text = true, badge = true, status = true, icon = true, avatar = true, separator = true, callout = true, ["empty-state"] = true, stat = true }
local LEAVES = { heading = true, text = true, badge = true, status = true, icon = true, avatar = true, separator = true, stat = true }

local function fail(code: string, message: string, path: string): any
	return StructuredError.from(code, message, { domain = "composition_descriptors", operation = "validate", path = path })
end

local function hasOnly(value: any, allowed: {[string]: boolean}, path: string): any?
	for key in next, value do
		if type(key) ~= "string" or not allowed[key] then return fail("unknown_descriptor_field", "Descriptor contains an unknown field", path .. "." .. tostring(key)) end
	end
	return nil
end

local COMMON = { id = true, kind = true, role = true, accessibility = true, localization = true, materialRole = true, cost = true, extensions = true }
local CONTAINER_FIELDS = { id = true, kind = true, children = true, slots = true, title = true, icon = true, role = true, accessibility = true, localization = true, materialRole = true, cost = true, extensions = true }
local FLOW_FIELDS = { wrap = true, gap = true, minItemWidth = true, maxColumns = true, align = true, flex = true, weight = true }
local ROW_COLUMN_FIELDS = { id = true, kind = true, children = true, slots = true, title = true, icon = true, role = true, accessibility = true, localization = true, materialRole = true, cost = true, extensions = true, wrap = true, gap = true, minItemWidth = true, maxColumns = true, align = true, flex = true, weight = true }
local CONTENT_FIELDS = {
	id = true, kind = true, role = true, accessibility = true, localization = true, materialRole = true, cost = true, extensions = true,
	value = true, label = true, icon = true, image = true, tone = true, text = true, heading = true, actionBar = true,
}
local ALIGN = { start = true, center = true, ["end"] = true }

local function finite(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

local function validateFlow(value: any, path: string): any?
	for name in pairs(FLOW_FIELDS) do
		local field = rawget(value, name)
		if field ~= nil then
			if name == "wrap" and type(field) ~= "boolean" then return fail("invalid_flow_field", "Flow wrap must be a boolean", path .. ".wrap") end
			if (name == "gap" or name == "flex" or name == "weight") and (not finite(field) or field < 0) then return fail("invalid_flow_field", "Flow gap, flex, and weight must be finite nonnegative numbers", path .. "." .. name) end
			if name == "minItemWidth" and (not finite(field) or field <= 0) then return fail("invalid_flow_field", "Flow minItemWidth must be a finite positive number", path .. ".minItemWidth") end
			if name == "maxColumns" and (not finite(field) or field < 1 or field ~= math.floor(field)) then return fail("invalid_flow_field", "Flow maxColumns must be a positive integer", path .. ".maxColumns") end
			if name == "align" and (type(field) ~= "string" or ALIGN[field] ~= true) then return fail("invalid_flow_field", "Flow align must be start, center, or end", path .. ".align") end
		end
	end
	return nil
end
local function denseArray(value: any): boolean
	if type(value) ~= "table" then return false end
	local length = #value
	for index = 1, length do
		if rawget(value, index) == nil then return false end
	end
	for key in pairs(value) do
		if type(key) ~= "number" or key < 1 or key > length or key ~= math.floor(key) then return false end
	end
	return true
end


local function validateNode(value: any, codec: any, path: string, seen: {[string]: boolean}): (any?, any?)
	if type(value) ~= "table" then return nil, fail("invalid_composition_descriptor", "Composition node must be a table", path) end
	local kind = rawget(value, "kind")
	local id, idError = codec:ParseNamespacedId(rawget(value, "id"), path .. ".id")
	if id == nil then return nil, idError end
	if seen[id] then return nil, fail("duplicate_composition_id", "Composition node ids must be unique", path .. ".id") end
	seen[id] = true
	if CONTAINERS[kind] then
		local fieldError = hasOnly(value, if kind == "row" or kind == "column" then ROW_COLUMN_FIELDS else CONTAINER_FIELDS, path)
		if fieldError then return nil, fieldError end
		if kind == "row" or kind == "column" then
			local flowError = validateFlow(value, path)
			if flowError then return nil, flowError end
		end
		if not denseArray(rawget(value, "children")) then return nil, fail("invalid_children", "Containers require a dense children array", path .. ".children") end
		for index, child in ipairs(value.children) do
			local parsed, childError = validateNode(child, codec, path .. ".children." .. tostring(index), seen)
			if parsed == nil then return nil, childError end
		end
		return value, nil
	end
	if CONTENT[kind] then
		local fieldError = hasOnly(value, CONTENT_FIELDS, path)
		if fieldError then return nil, fieldError end
		if LEAVES[kind] and (rawget(value, "heading") ~= nil or rawget(value, "actionBar") ~= nil) then return nil, fail("invalid_content_children", "Leaf content cannot contain children", path) end
		if kind == "callout" or kind == "empty-state" then
			for _, field in ipairs({ "heading", "text", "actionBar" }) do
				local child = rawget(value, field)
				if child ~= nil then
					local parsed, childError = validateNode(child, codec, path .. "." .. field, seen)
					if parsed == nil then return nil, childError end
					if field == "actionBar" and parsed.kind ~= "action-bar" then return nil, fail("invalid_content_children", "actionBar must be an action-bar container", path .. ".actionBar") end
				end
			end
		end
		return value, nil
	end
	if type(kind) == "string" then
		return value, nil -- ControlDescriptor validation, including its variant fields, is owned by ControlHost.
	end
	return nil, fail("unknown_composition_kind", "Composition kind is not supported", path .. ".kind")
end

function CompositionDescriptors.Validate(value: any): (any?, any?)
	local codec = SchemaCodec.new()
	local scanned, scanError = codec:PreScanPortable(value, "composition")
	if not scanned then return nil, scanError end
	local parsed, parseError = validateNode(value, codec, "composition", {})
	if parsed == nil then return nil, parseError end
	return codec:Normalize(parsed)
end

function CompositionDescriptors.IsContainer(value: any): boolean return type(value) == "table" and CONTAINERS[rawget(value, "kind")] == true end
function CompositionDescriptors.IsContent(value: any): boolean return type(value) == "table" and CONTENT[rawget(value, "kind")] == true end

return table.freeze(CompositionDescriptors)

end

__modules["models/ControlDescriptors"] = function()
--!strict

local SchemaCodec = __require("customization/SchemaCodec")
local StructuredError = __require("core/StructuredError")
local LayoutCapabilities = __require("models/LayoutCapabilities")


export type Descriptor = { [string]: any }

local ControlDescriptors = {}

local COMMON = {
	id = true, kind = true, schemaVersion = true, title = true, description = true,
	accessibility = true, localization = true, state = true, bindings = true,
	actions = true, layout = true, extensions = true, cost = true, disabled = true, readOnly = true,
}
local COMMON_TYPES = {
	schemaVersion = "table", title = "string", description = "string", accessibility = "table", localization = "table",
	state = "table", bindings = "table", actions = "table", layout = "table", extensions = "table", cost = "table",
	disabled = "boolean", readOnly = "boolean",
}


local VARIANTS = {
	NumberInput = { min = "number", max = "number", step = "number", precision = "number", format = "string" },
	TextInput = { maxBytes = "number", placeholder = "string" },
	TextArea = { rows = "number", maxBytes = "number" },
	PasswordInput = { revealPolicy = "string" },
	SearchInput = { queryId = "string", debounceMs = "number" },
	DatePicker = {}, TimePicker = {}, DateRangePicker = { start = "string", ["end"] = "string" },
	Combobox = { items = "table", providerId = "string", stableKey = "string" },
	ListBox = { items = "table", providerId = "string", stableKey = "string", preset = "string" },
	Toggle = {}, Radio = { items = "table", value = "string" }, Segmented = { items = "table", value = "string" }, Slider = { min = "number", max = "number", step = "number", precision = "number" },
	ColorPicker = {}, Keybind = { mode = "string" },
	FormActions = { formId = "string", submitAction = "string", resetAction = "string" },
	DataGrid = { rows = "table", columns = "table", query = "string", sort = "table", page = "number", pageSize = "number", groupBy = "string", selection = "table", multiSelect = "boolean" },
	Chart = { series = "table", chartKind = "string", maxSamples = "number", maxSeries = "number", min = "number", max = "number", thresholds = "table", height = "number", width = "number" },
	CodeEditor = { language = "string", noEval = "boolean" },
	KeyValueEditor = {}, VectorEditor = {}, GradientEditor = {}, Button = {},
	Stat = { value = "number", label = "string", trend = "number", suffix = "string", tone = "string", precision = "number" },
	legacy = { legacy = "table" },
}

local KINDS = {}
for kind in pairs(VARIANTS) do KINDS[kind] = true end

local function fail(code: string, message: string, path: string?): any
	return StructuredError.from(code, message, { domain = "controlDescriptors", operation = "validate", path = path })
end

local ARRAY_LIMITS = {
	bindings = 64,
	items = 512,
	rows = 4096,
	columns = 128,
	selection = 4096,
	series = 64,
	thresholds = 128,
	samples = 4096,
	sources = 16,
}

local DATA_GRID_ARRAY_FIELDS = table.freeze({ "rows", "selection" })
local CHART_ARRAY_FIELDS = table.freeze({ "series", "thresholds" })

local PORTABLE_ACTION_SLOTS = table.freeze({ activate = true })
local PORTABLE_COMMAND_FIELDS = table.freeze({ kind = true, commandId = true, args = true })
local PORTABLE_NAVIGATION_FIELDS = table.freeze({ kind = true, routeId = true, params = true, mode = true })

local function validatePortableAction(value: any, path: string, codec: any): any
	if type(value) ~= "table" then
		return fail("invalid_portable_action", "Portable actions must be tables", path)
	end
	local kind = rawget(value, "kind")
	local fields = if kind == "command" then PORTABLE_COMMAND_FIELDS elseif kind == "navigate" then PORTABLE_NAVIGATION_FIELDS else nil
	if fields == nil then
		return fail("invalid_portable_action", "Portable actions must use the command or navigate form", path .. ".kind")
	end
	for key in pairs(value) do
		if type(key) ~= "string" or fields[key] ~= true then
			return fail("unknown_portable_action_field", "Portable action contains an unknown field", path .. "." .. tostring(key))
		end
	end
	if kind == "command" then
		local commandId, commandError = codec:ParseNamespacedId(rawget(value, "commandId"), path .. ".commandId")
		if commandId == nil then return commandError end
		if rawget(value, "args") ~= nil and type(rawget(value, "args")) ~= "table" then
			return fail("invalid_portable_action", "Portable command args must be a table", path .. ".args")
		end
	else
		local routeId, routeError = codec:ParseNamespacedId(rawget(value, "routeId"), path .. ".routeId")
		if routeId == nil then return routeError end
		if rawget(value, "params") ~= nil and type(rawget(value, "params")) ~= "table" then
			return fail("invalid_portable_action", "Portable navigation params must be a table", path .. ".params")
		end
		local mode = rawget(value, "mode")
		if mode ~= nil and mode ~= "push" and mode ~= "replace" then
			return fail("invalid_portable_action", "Portable navigation mode must be push or replace", path .. ".mode")
		end
	end
	return nil
end

local function validatePortableActions(value: any, codec: any): any
	if value == nil then return nil end
	if type(value) ~= "table" then
		return fail("invalid_portable_action", "ControlDescriptor actions must be a table", "control.actions")
	end
	if rawget(value, "kind") ~= nil then
		return validatePortableAction(value, "control.actions", codec)
	end
	for slot, action in pairs(value) do
		if type(slot) ~= "string" or PORTABLE_ACTION_SLOTS[slot] ~= true then
			return fail("unknown_portable_action_slot", "ControlDescriptor actions contains an unknown action slot", "control.actions." .. tostring(slot))
		end
		local actionError = validatePortableAction(action, "control.actions." .. slot, codec)
		if actionError ~= nil then return actionError end
	end
	return nil
end

local function denseArray(value: any, maximum: number): (boolean, number)
	if type(value) ~= "table" then return false, 0 end
	local count, largest = 0, 0
	for key in pairs(value) do
		if type(key) ~= "number" or key < 1 or key % 1 ~= 0 or key > maximum then return false, 0 end
		count += 1
		if key > largest then largest = key end
	end
	return count == largest, count
end

local function validateArray(value: any, field: string, required: boolean?): any
	local dense, count = denseArray(value, ARRAY_LIMITS[field])
	if not dense or (required and count == 0) then
		return fail("invalid_control_field", "ControlDescriptor " .. field .. " must be a bounded" .. (required and " non-empty" or "") .. " dense array", "control." .. field)
	end
	return nil
end

local function finiteNumber(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

local function validateColumn(column: any, index: number): any
	if type(column) ~= "table" then
		return fail("invalid_control_field", "DataGrid columns must contain tables", "control.columns." .. tostring(index))
	end
	return nil
end

local function validateSample(sample: any, path: string): any
	if finiteNumber(sample) then return nil end
	if type(sample) == "table" then
		local value = if sample.value ~= nil then sample.value else sample.Value
		if finiteNumber(value) then return nil end
	end
	return fail("invalid_control_field", "Chart samples must be finite numbers or tables with a finite value", path)
end

local function closed(value: any, kind: string): any
	if type(value) ~= "table" then return fail("invalid_control_descriptor", "ControlDescriptor must be a table") end
	local variant = VARIANTS[kind]
	for key, field in pairs(value) do
		if type(key) ~= "string" then return fail("invalid_control_descriptor", "ControlDescriptor keys must be strings") end
		local expected = variant[key]
		if not COMMON[key] and expected == nil then
			return fail("unknown_control_field", "ControlDescriptor contains an unknown field", "control." .. key)
		end
		if expected ~= nil and type(field) ~= expected then
			return fail("invalid_control_field", "ControlDescriptor field has an invalid type", "control." .. key)
		end
		local commonExpected = COMMON_TYPES[key]
		if commonExpected ~= nil and type(field) ~= commonExpected then
			return fail("invalid_control_field", "ControlDescriptor common field has an invalid type", "control." .. key)
		end
	end
	if kind == "FormActions" and (type(value.formId) ~= "string" or type(value.submitAction) ~= "string" or type(value.resetAction) ~= "string") then
		return fail("invalid_control_field", "FormActions requires formId, submitAction, and resetAction", "control")
	end
	if (kind == "Combobox" or kind == "ListBox") and value.providerId ~= nil and #value.providerId == 0 then
		return fail("invalid_control_field", "providerId must not be empty", "control.providerId")
	end
	if value.bindings ~= nil then
		local bindingsError = validateArray(value.bindings, "bindings")
		if bindingsError ~= nil then return bindingsError end
		for _, binding in ipairs(value.bindings) do
			if type(binding) == "table" and binding.sources ~= nil then
				local sourcesError = validateArray(binding.sources, "sources", true)
				if sourcesError ~= nil then return sourcesError end
			end
		end
	end
	if value.items ~= nil then
		local itemsError = validateArray(value.items, "items", kind == "Radio" or kind == "Segmented")
		if itemsError ~= nil then return itemsError end
	end
	if kind == "DateRangePicker" and ((value.start == nil) ~= (value["end"] == nil)) then
		return fail("invalid_control_field", "DateRangePicker start and end must be supplied together", "control.start")
	end
	if kind == "DataGrid" then
		local columnsError = validateArray(value.columns, "columns", true)
		if columnsError ~= nil then return columnsError end
		for index, column in ipairs(value.columns) do
			local columnError = validateColumn(column, index)
			if columnError ~= nil then return columnError end
		end
		for _, field in ipairs(DATA_GRID_ARRAY_FIELDS) do
			if value[field] ~= nil then
				local arrayError = validateArray(value[field], field)
				if arrayError ~= nil then return arrayError end
			end
		end
	end
	if kind == "Chart" then
		for _, field in ipairs(CHART_ARRAY_FIELDS) do
			if value[field] ~= nil then
				local arrayError = validateArray(value[field], field)
				if arrayError ~= nil then return arrayError end
			end
		end
		if type(value.series) == "table" then
			for seriesIndex, series in ipairs(value.series) do
				if type(series) ~= "table" then
					return fail("invalid_control_field", "Chart series must contain tables", "control.series." .. tostring(seriesIndex))
				end
				local samples = if series.samples ~= nil then series.samples else series.Samples
				if samples ~= nil then
					local samplesError = validateArray(samples, "samples")
					if samplesError ~= nil then return samplesError end
					for sampleIndex, sample in ipairs(samples) do
						local sampleError = validateSample(sample, "control.series." .. tostring(seriesIndex) .. ".samples." .. tostring(sampleIndex))
						if sampleError ~= nil then return sampleError end
					end
				end
			end
		end
	end
	if kind == "Chart" and value.chartKind ~= nil and value.chartKind ~= "line" and value.chartKind ~= "area" and value.chartKind ~= "bar" then
		return fail("invalid_control_field", "Chart chartKind must be line, area, or bar", "control.chartKind")
	end
	if kind == "Chart" and ((value.min == nil) ~= (value.max == nil) or (value.min ~= nil and value.min >= value.max)) then
		return fail("invalid_control_field", "Chart min and max must be supplied together in increasing order", "control.min")
	end
	if kind == "Stat" then
		if value.value == nil or not finiteNumber(value.value) then
			return fail("invalid_control_field", "Stat requires a finite numeric value", "control.value")
		end
		if value.trend ~= nil and not finiteNumber(value.trend) then
			return fail("invalid_control_field", "Stat trend must be a finite number", "control.trend")
		end
		if value.precision ~= nil and (not finiteNumber(value.precision) or value.precision < 0 or value.precision ~= math.floor(value.precision)) then
			return fail("invalid_control_field", "Stat precision must be a nonnegative integer", "control.precision")
		end
	end
	if value.layout ~= nil then
		local _, layoutError = LayoutCapabilities.Validate(value.layout, "control.layout")
		if layoutError ~= nil then return layoutError end
	end
	return nil
end
function ControlDescriptors.Validate(value: any, portable: boolean?): (any?, any?)
	local codec = SchemaCodec.new()
	local scanned, scanError = codec:PreScanPortable(value, "control")
	if not scanned then return nil, scanError end
	if type(value) ~= "table" then return nil, fail("invalid_control_descriptor", "ControlDescriptor must be a table", "control") end
	local kind = rawget(value, "kind")
	if type(kind) ~= "string" or KINDS[kind] ~= true then
		return nil, fail("unknown_control_kind", "ControlDescriptor kind is not supported", "control.kind")
	end
	local shapeError = closed(value, kind)
	if shapeError ~= nil then return nil, shapeError end
	if portable then
		local actionError = validatePortableActions(rawget(value, "actions"), codec)
		if actionError ~= nil then return nil, actionError end
	end
	local id, idError = codec:ParseNamespacedId(rawget(value, "id"), "control.id")
	if id == nil then return nil, idError end

	local version = rawget(value, "schemaVersion")
	if version ~= nil then
		local _, versionError = codec:ParseVersion(version, "control.schemaVersion")
		if versionError ~= nil then return nil, versionError end
	end
	local normalized, normalizeError = codec:Normalize(value)
	if normalized == nil then return nil, normalizeError end
	return normalized, nil
end

function ControlDescriptors.ValidatePortable(value: any): (any?, any?)
	return ControlDescriptors.Validate(value, true)
end


function ControlDescriptors.Hash(value: any): (string?, any?)
	local descriptor, descriptorError = ControlDescriptors.Validate(value)
	if descriptor == nil then return nil, descriptorError end
	return SchemaCodec.new():Hash(descriptor)
end

function ControlDescriptors.IsDescriptor(value: any): boolean
	return type(value) == "table" and type(rawget(value, "id")) == "string" and type(rawget(value, "kind")) == "string"
end

return table.freeze(ControlDescriptors)

end

__modules["models/LayoutCapabilities"] = function()
--!strict

local StructuredError = __require("core/StructuredError")

local LayoutCapabilities = {}
local FIELDS = table.freeze({ compact = true, fullWidth = true, minWidth = true, canWrap = true })

local function fail(message: string, path: string): any
	return StructuredError.from("invalid_layout_capability", message, {
		domain = "layoutCapabilities",
		operation = "validate",
		path = path,
	})
end

local function finite(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

function LayoutCapabilities.Validate(value: any, path: string?): (any?, any?)
	local location = path or "layout"
	if value == nil then return table.freeze({}), nil end
	if type(value) ~= "table" then return nil, fail("Layout capabilities must be a table", location) end
	for key, field in pairs(value) do
		if type(key) ~= "string" or FIELDS[key] ~= true then return nil, fail("Layout capabilities contain an unknown field", location .. "." .. tostring(key)) end
		if (key == "compact" or key == "fullWidth" or key == "canWrap") and type(field) ~= "boolean" then
			return nil, fail("Layout boolean capabilities must be booleans", location .. "." .. key)
		end
		if key == "minWidth" and (not finite(field) or field <= 0) then
			return nil, fail("Layout minWidth must be a finite positive number", location .. ".minWidth")
		end
	end
	local normalized = {}
	for key in pairs(FIELDS) do
		local field = rawget(value, key)
		if field ~= nil then normalized[key] = field end
	end
	return table.freeze(normalized), nil
end

return table.freeze(LayoutCapabilities)

end

__modules["models/TableModel"] = function()
--!strict

export type RowKey = string | number | boolean

local TableModel = {}
TableModel.__index = TableModel

local function cloneArray(source: { any }): { any }
	local result = table.create(#source)
	for index, value in ipairs(source) do
		result[index] = value
	end
	return result
end

local function normalizeKey(value: any, index: number): RowKey
	if value == nil then
		return index
	end
	local kind = type(value)
	assert(kind == "string" or kind == "number" or kind == "boolean", "TableModel row keys must be strings, numbers, or booleans")
	return value
end

local function normalizedCompare(left: any, right: any, compare: any): number
	if left == right then
		return 0
	end
	if type(compare) == "function" then
		local leftBefore = select(2, pcall(compare, left, right))
		local rightBefore = select(2, pcall(compare, right, left))
		if leftBefore == true and rightBefore ~= true then return -1 end
		if rightBefore == true and leftBefore ~= true then return 1 end
	end
	if left == nil then return 1 end
	if right == nil then return -1 end
	if type(left) == "number" and type(right) == "number" then
		return if left < right then -1 else 1
	end
	local normalizedLeft, normalizedRight = string.lower(tostring(left)), string.lower(tostring(right))
	if normalizedLeft == normalizedRight then return 0 end
	return if normalizedLeft < normalizedRight then -1 else 1
end

local function columnFor(columns: { any }, columnId: string): any
	for _, column in ipairs(columns) do
		if tostring(column.Id or column.Key or column.Field) == columnId then
			return column
		end
	end
	return nil
end

function TableModel.new(options: any)
	assert(type(options) == "table", "TableModel requires options")
	local self: any = setmetatable({}, TableModel)
	self._rowKey = options.RowKey or options.Key or "Id"
	self._columns = options.Columns or {}
	self._rows = {}
	self._keyIndex = {}
	self._view = {}
	self._viewKeys = {}
	self._selected = {}
	self._multiSelect = options.MultiSelect == true
	self._query = ""
	self._filter = nil
	self._sortId = nil
	self._sortDirection = nil
	self._groupBy = nil
	self._page = 1
	self._pageSize = math.max(0, math.floor(tonumber(options.PageSize) or 0))
	self._generation = 0
	self._destroyed = false
	self._onEdit = options.OnEdit
	self:SetRows(options.Rows or options.Items or {})
	if options.Query ~= nil then self:SetQuery(options.Query) end
	if options.Sort ~= nil then
		assert(type(options.Sort) == "table", "TableModel Sort must be { ColumnId, Direction } or { columnId, direction }")
		local columnId = options.Sort.ColumnId or options.Sort.columnId or options.Sort.Id or options.Sort.id or options.Sort[1]
		local direction = options.Sort.Direction or options.Sort.direction or options.Sort[2]
		self:SetSort(columnId, direction)
	end
	if options.GroupBy ~= nil then self:SetGroupBy(options.GroupBy) end
	if options.Selection ~= nil then
		assert(type(options.Selection) == "table", "TableModel Selection must be an array of row keys")
		for _, key in ipairs(options.Selection) do self:SetSelected(key, true) end
	end
	if options.Page ~= nil then self:SetPagination(options.Page) end
	return self
end

function TableModel:_keyFor(row: any, index: number): RowKey
	local key = nil
	if type(self._rowKey) == "function" then
		key = self._rowKey(row, index)
	elseif type(row) == "table" then
		key = row[self._rowKey]
	end
	return normalizeKey(key, index)
end

function TableModel:_valueFor(row: any, columnId: string): any
	if type(row) ~= "table" then
		return nil
	end
	for _, column in ipairs(self._columns) do
		if tostring(column.Id or column.Key or column.Field) == columnId then
			if type(column.Value) == "function" then
				return column.Value(row, column)
			end
			return row[column.Field or column.Key or column.Id]
		end
	end
	return row[columnId]
end
function TableModel:_rebuild()
	local entries = table.create(#self._rows)
	local query = string.lower(self._query)
	for index, row in ipairs(self._rows) do
		local include = true
		if query ~= "" then
			include = false
			for _, column in ipairs(self._columns) do
				local value = self:_valueFor(row, tostring(column.Id or column.Key or column.Field))
				if value ~= nil and string.find(string.lower(tostring(value)), query, 1, true) then
					include = true
					break
				end
			end
		end
		local key = self._keys[index]
		if include and self._filter then
			include = self._filter(row, index, key) == true
		end
		if include then
			table.insert(entries, { Row = row, Key = key, Index = index })
		end
	end
	if self._sortId and self._sortDirection then
		local sortId, direction = self._sortId, self._sortDirection
		local column = columnFor(self._columns, sortId)
		local compare = if column then column.Compare else nil
		table.sort(entries, function(left, right)
			local order = normalizedCompare(self:_valueFor(left.Row, sortId), self:_valueFor(right.Row, sortId), compare)
			if order == 0 then return left.Index < right.Index end
			return if direction == "desc" then order > 0 else order < 0
		end)
	end
	local first, last = 1, #entries
	if self._pageSize > 0 then
		first = (self._page - 1) * self._pageSize + 1
		last = math.min(#entries, first + self._pageSize - 1)
	end
	local view, viewKeys = table.create(math.max(0, last - first + 1)), table.create(math.max(0, last - first + 1))
	for index = first, last do
		local entry = entries[index]
		if entry then
			table.insert(view, entry.Row)
			table.insert(viewKeys, entry.Key)
		end
	end
	self._view, self._viewKeys = view, viewKeys
end

function TableModel:SetRows(rows: any)
	assert(type(rows) == "table", "TableModel Rows must be an array")
	local keys, index = {}, {}
	for rowIndex, row in ipairs(rows) do
		local key = self:_keyFor(row, rowIndex)
		assert(index[key] == nil, "Duplicate TableModel row key: " .. tostring(key))
		keys[rowIndex], index[key] = key, rowIndex
	end
	self._rows, self._keys, self._keyIndex = cloneArray(rows), keys, index
	for key in pairs(self._selected) do
		if index[key] == nil then self._selected[key] = nil end
	end
	self:_rebuild()
	return self
end

function TableModel:GetRows(): { any } return cloneArray(self._rows) end
function TableModel:GetVisibleRows(): { any } return cloneArray(self._view) end
function TableModel:GetVisibleRowKeys(): { RowKey } return cloneArray(self._viewKeys) end
function TableModel:GetRow(key: RowKey): any
	local index = self._keyIndex[key]
	return if index then self._rows[index] else nil
end
function TableModel:GetRowIndex(key: RowKey): number? return self._keyIndex[key] end
function TableModel:GetRowKey(row: any, index: number?): RowKey
	if index ~= nil and self._rows[index] == row then
		return self._keys[index]
	end
	for sourceIndex, candidate in ipairs(self._rows) do
		if candidate == row then return self._keys[sourceIndex] end
	end
	error("Unknown TableModel row", 2)
end
function TableModel:SetQuery(query: any)
	self._query = tostring(query or "")
	self._page = 1
	self:_rebuild()
	return self
end
function TableModel:GetQuery(): string return self._query end
function TableModel:SetFilter(filter: any)
	assert(filter == nil or type(filter) == "function", "TableModel Filter must be a function or nil")
	self._filter, self._page = filter, 1
	self:_rebuild()
	return self
end
function TableModel:SetSort(columnId: any, direction: any)
	assert(direction == nil or direction == "asc" or direction == "desc", "TableModel sort must be asc, desc, or nil")
	self._sortId, self._sortDirection = if direction then tostring(columnId) else nil, direction
	self:_rebuild()
	return self
end
function TableModel:GetSort(): (string?, string?) return self._sortId, self._sortDirection end
function TableModel:SetPagination(page: any, pageSize: any?)
	if pageSize ~= nil then self._pageSize = math.max(0, math.floor(tonumber(pageSize) or 0)) end
	self._page = math.max(1, math.floor(tonumber(page) or 1))
	self:_rebuild()
	return self
end
function TableModel:SetColumns(columns: any)
	assert(type(columns) == "table", "TableModel Columns must be an array")
	self._columns = columns
	self:_rebuild()
	return self
end
function TableModel:GetPagination(): any return { Page = self._page, PageSize = self._pageSize, Total = #self._rows, Visible = #self._view } end
function TableModel:SetGroupBy(columnId: any)
	self._groupBy = if columnId == nil then nil else tostring(columnId)
	return self
end
function TableModel:GetGroups(): { any }
	local groups, byKey = {}, {}
	if self._groupBy == nil then return groups end
	for _, row in ipairs(self._view) do
		local value = self:_valueFor(row, self._groupBy)
		local key = tostring(value)
		local group = byKey[key]
		if not group then
			group = { Key = value, Rows = {} }
			byKey[key] = group
			table.insert(groups, group)
		end
		table.insert(group.Rows, row)
	end
	return groups
end
function TableModel:SetSelected(key: RowKey, selected: boolean?)
	assert(self._keyIndex[key] ~= nil, "Unknown TableModel row key: " .. tostring(key))
	if selected == false then
		self._selected[key] = nil
	else
		if not self._multiSelect then table.clear(self._selected) end
		self._selected[key] = true
	end
	return self
end
function TableModel:GetSelected(): { RowKey }
	local result = {}
	for _, key in ipairs(self._keys) do if self._selected[key] then table.insert(result, key) end end
	return result
end
function TableModel:Edit(key: RowKey, columnId: any, value: any): boolean
	local rowIndex = self._keyIndex[key]
	local row = if rowIndex then self._rows[rowIndex] else nil
	assert(type(row) == "table", "Unknown TableModel row key: " .. tostring(key))
	local field = tostring(columnId)
	for _, column in ipairs(self._columns) do
		if tostring(column.Id or column.Key or column.Field) == field then field = column.Field or column.Key or column.Id break end
	end
	local previous = row[field]
	row[field] = value
	local nextKey = self:_keyFor(row, rowIndex)
	if nextKey ~= key and self._keyIndex[nextKey] ~= nil then
		row[field] = previous
		return false
	end
	local ok, accepted = true, true
	if type(self._onEdit) == "function" then
		ok, accepted = pcall(self._onEdit, row, field, value, previous, key)
	end
	if not ok or accepted == false then
		row[field] = previous
		return false
	end
	nextKey = self:_keyFor(row, rowIndex)
	if nextKey ~= key and self._keyIndex[nextKey] ~= nil then
		row[field] = previous
		return false
	end
	if nextKey ~= key then
		self._keys[rowIndex], self._keyIndex[key], self._keyIndex[nextKey] = nextKey, nil, rowIndex
		if self._selected[key] then
			self._selected[key], self._selected[nextKey] = nil, true
		end
	end
	self:_rebuild()
	return true
end
function TableModel:ApplyRemote(rows: any, generation: number): boolean
	if self._destroyed or generation ~= self._generation then return false end
	self:SetRows(rows)
	return true
end
function TableModel:Refresh(provider: any)
	assert(type(provider) == "function", "TableModel Provider must be a function")
	self._generation += 1
	local generation = self._generation
	task.spawn(function()
		local ok, rows = pcall(provider, generation)
		if ok and type(rows) == "table" then self:ApplyRemote(rows, generation) end
	end)
	return generation
end
function TableModel:CancelRemote() self._generation += 1 return self end
function TableModel:Destroy()
	self._destroyed = true
	self:CancelRemote()
	table.clear(self._rows)
	table.clear(self._view)
	table.clear(self._viewKeys)
	table.clear(self._keys)
	table.clear(self._keyIndex)
	table.clear(self._selected)
end

return TableModel

end

__modules["RuntimeFreeLibrary"] = function()
--!strict

local RuntimeFreeWindow = __require("ui/RuntimeFreeWindow")

local Library = {}

Library.Framework = table.freeze({
	Name = "Potassium UI",
	BrandName = "Fluxcore",
	Brand = table.freeze({
		name = "Fluxcore",
		icon = "iongate",
		iconSize = 32,
		gameTitleSource = "Window.Title",
	}),
	Version = "1.0.0",
	ApiVersion = 1,
	Style = "runtime-free-violet-workshop",
	LayoutMode = "auto",
	CanonicalEntry = "bootstrap",
	RuntimeMode = "runtime-free",
	PersistenceDefault = false,
	WorldBlurDefault = false,
	MenuKeyDefault = false,
	DefaultWindowSize = Vector2.new(600, 400),
	NavigationBreakpoint = 540,
	SidebarWidth = 130,
	InteractionHeight = 44,
	ThemeMetrics = table.freeze({
		sidebarWidth = 130,
		sidebarPadding = 7,
		contentPadding = 9,
		pageGap = 8,
		sectionPadding = 10,
		searchWidth = 190,
		iconSize = 20,
	}),
	Presentation = table.freeze({
		shellRadius = 14,
		sectionRadius = 10,
		shellTransparency = 0.126,
		selectedTabAccentMix = 0.10,
		localGlass = true,
		localShadow = true,
		localGlow = true,
		worldBlur = false,
		minimizePillSize = Vector2.new(185, 50),
		minimizeStretchSize = Vector2.new(185, 70),
		minimizeStretchTopInset = 0,
		restoreStretchWidthDelta = -8,
		restoreStretchHeightDelta = 20,
		restoreStretchYOffset = 10,
		minimizeTopInset = 20,
	}),
	Motion = table.freeze({
		shellReveal = 0.40,
		tabEmphasis = 0.40,
		pageFadeOut = 0.12,
		pageEnter = 0.22,
		pageFadeIn = 0.14,
		pageSettle = 0.16,
		railStretch = 0.28,
		railSettle = 0.22,
		minimizeChromeFade = 0.18,
		minimizeMorph = 0.35,
		minimizeStretch = 0.26,
		minimizeSettle = 0.18,
		minimizeInteractive = 0.38,
		minimizeFaceIn = 0.20,
		restoreFaceOut = 0.15,
		restoreChrome = 0.28,
		restoreStretch = 0.28,
		restoreSettle = 0.18,
		restoreComplete = 0.60,
		toggleState = 0.60,
	}),
	LoadModes = table.freeze({ "ModuleScript", "Bundle" }),
	Controls = table.freeze({
		multiSelect = true,
		toggleOptions = true,
	}),
})

local function errorResult(code: string, message: string)
	return { code = code, message = message }
end

local function shallowCopy(source: any): any
	local result = {}
	for key, value in pairs(source or {}) do
		result[key] = value
	end
	return result
end

function Library.bootstrap(options: any?)
	if options ~= nil and type(options) ~= "table" then
		return nil, nil, errorResult("invalid_framework_options", "Framework options must be a table")
	end
	local input = options or {}
	local libraryInput = if input.Library ~= nil then input.Library else input.library
	local windowInput = if input.Window ~= nil then input.Window else input.window
	if libraryInput ~= nil and type(libraryInput) ~= "table" then
		return nil, nil, errorResult("invalid_library_options", "Framework Library options must be a table")
	end
	if windowInput ~= nil and type(windowInput) ~= "table" then
		return nil, nil, errorResult("invalid_window_options", "Framework Window options must be a table")
	end

	local libraryOptions = shallowCopy(libraryInput)
	local windowOptions = shallowCopy(windowInput)
	local function windowDefault(upper: string, lower: string, value: any)
		if windowOptions[upper] == nil and windowOptions[lower] == nil then
			windowOptions[upper] = value
		end
	end
	windowDefault("Id", "id", "main")
	windowDefault("Title", "title", "Game")
	windowDefault("Size", "size", Library.Framework.DefaultWindowSize)
	windowDefault("LayoutMode", "layoutMode", Library.Framework.LayoutMode)
	windowDefault("NavigationBreakpoint", "navigationBreakpoint", Library.Framework.NavigationBreakpoint)
	windowDefault("StartOpen", "startOpen", true)
	windowDefault("Minimizable", "minimizable", true)
	windowDefault("Resizable", "resizable", false)

	local ui, window, bootstrapError = RuntimeFreeWindow.create({
		Library = libraryOptions,
		Window = windowOptions,
	})
	if ui == nil or window == nil then
		return nil, nil, bootstrapError or errorResult("window_creation_failed", "Runtime-free window construction failed")
	end
	return ui, window, nil
end

return Library

end

__modules["services/AntiAfk"] = function()
--!strict

local Maid = __require("core/Maid")

export type StructuredError = { code: string, message: string }
export type Options = {
	Enabled: boolean?,
	Movement: boolean?,
	Interval: number?,
	IsAutomationActive: (() -> boolean)?,
}
export type Snapshot = {
	Enabled: boolean,
	Movement: boolean,
	Interval: number,
	Origin: Vector3?,
	LastError: StructuredError?,
	Destroyed: boolean,
}

local DEFAULT_INTERVAL = 600
local MOVEMENT_DISTANCE = 0.65
local MAX_ORIGIN_DISTANCE = 3

local AntiAfk = {}
AntiAfk.__index = AntiAfk

local function failure(code: string, message: string): StructuredError
	return { code = code, message = message }
end

local function finitePositive(value: any): boolean
	return type(value) == "number" and value == value and value > 0 and value < math.huge
end

function AntiAfk.new(runtime: any, options: Options?)
	assert(type(runtime) == "table", "AntiAfk requires a runtime")
	assert(type(runtime.services) == "table", "AntiAfk requires runtime.services")

	local self = setmetatable({
		_players = runtime.services.Players,
		_virtualUser = runtime.services.VirtualUser,
		_workspace = runtime.services.Workspace,
		_maid = Maid.new(),
		_enabled = false,
		_movement = false,
		_interval = DEFAULT_INTERVAL,
		_isAutomationActive = nil :: (() -> boolean)?,
		_origin = nil :: Vector3?,
		_movementSign = 1,
		_generation = 0,
		_lastError = nil :: StructuredError?,
		_destroyed = false,
		_player = nil :: any,
	}, AntiAfk)

	if options ~= nil then
		self:Configure(options)
	end
	return self
end

function AntiAfk:_setError(code: string, message: string): StructuredError
	local error = failure(code, message)
	self._lastError = error
	return error
end

function AntiAfk:_clearError()
	self._lastError = nil
end

function AntiAfk:_localPlayer(): any
	if self._players == nil then
		return nil
	end
	local ok, player = pcall(function()
		return self._players.LocalPlayer
	end)
	return if ok then player else nil
end

function AntiAfk:_clearOrigin()
	self._origin = nil
	self._movementSign = 1
end

function AntiAfk:_bindLocalPlayer()
	local player = self:_localPlayer()
	if player == self._player then
		return
	end
	self._player = player
	self._maid:Remove("player")
	self:_clearOrigin()
	if player == nil then
		return
	end

	local playerMaid = Maid.new()
	self._maid:Set("player", playerMaid)
	if player.Idled and type(player.Idled.Connect) == "function" then
		playerMaid:GiveTask(player.Idled:Connect(function()
			if self._enabled and not self._destroyed then
				self:_pulse()
			end
		end))
	end
	if player.CharacterAdded and type(player.CharacterAdded.Connect) == "function" then
		playerMaid:GiveTask(player.CharacterAdded:Connect(function()
			self:_clearOrigin()
		end))
	end
	if player.CharacterRemoving and type(player.CharacterRemoving.Connect) == "function" then
		playerMaid:GiveTask(player.CharacterRemoving:Connect(function()
			self:_clearOrigin()
		end))
	end
end

function AntiAfk:_rootPart(): BasePart?
	local player = self:_localPlayer()
	if player == nil then
		return nil
	end
	local character = player.Character
	if character == nil then
		return nil
	end
	local root = character:FindFirstChild("HumanoidRootPart")
	return if root ~= nil and root:IsA("BasePart") then root else nil
end

function AntiAfk:_automationIsActive(): boolean
	local callback = self._isAutomationActive
	if callback == nil then
		return false
	end
	local ok, active = pcall(callback)
	if not ok then
		self:_setError("automation_check_failed", "IsAutomationActive failed; movement was skipped.")
		return true
	end
	return active == true
end

function AntiAfk:_move()
	local generation = self._generation
	if not self._movement or self:_automationIsActive() then
		return
	end
	if self._destroyed or not self._enabled or not self._movement or generation ~= self._generation then
		return
	end
	local root = self:_rootPart()
	if root == nil then
		return
	end
	if self._origin == nil then
		self._origin = root.Position
	end
	if (root.Position - self._origin).Magnitude > MAX_ORIGIN_DISTANCE then
		return
	end

	local target = self._origin + Vector3.new(MOVEMENT_DISTANCE * self._movementSign, 0, 0)
	local ok = pcall(function()
		root.CFrame = CFrame.new(target) * (root.CFrame - root.CFrame.Position)
	end)
	if not ok then
		self:_setError("movement_failed", "Could not pulse the character movement.")
		return
	end
	self._movementSign = -self._movementSign
end

function AntiAfk:_pulse(): boolean
	if self._destroyed or not self._enabled then
		return false
	end
	self:_bindLocalPlayer()
	local virtualUser = self._virtualUser
	local workspace = self._workspace
	if virtualUser == nil then
		self:_setError("virtual_user_unavailable", "VirtualUser is unavailable in this runtime.")
		self:_move()
		return false
	end
	if workspace == nil then
		self:_setError("workspace_unavailable", "Workspace is unavailable in this runtime.")
		self:_move()
		return false
	end

	local ok, result = pcall(function()
		local camera = workspace.CurrentCamera
		if camera == nil then
			error("CurrentCamera is unavailable")
		end
		virtualUser:CaptureController()
		virtualUser:Button2Down(Vector2.new(0, 0), camera.CFrame)
		virtualUser:Button2Up(Vector2.new(0, 0), camera.CFrame)
	end)
	if not ok then
		self:_setError("virtual_user_pulse_failed", "Could not send the anti-AFK input pulse: " .. tostring(result))
		self:_move()
		return false
	end
	self:_clearError()
	self:_move()
	return true
end

function AntiAfk:_startWorker()
	self._generation += 1
	local generation = self._generation
	local worker = task.spawn(function()
		while not self._destroyed and self._enabled and generation == self._generation do
			task.wait(self._interval)
			if not self._destroyed and self._enabled and generation == self._generation then
				self:_pulse()
			end
		end
	end)
	self._maid:Set("worker", worker)
end

function AntiAfk:Configure(options: Options): (boolean, StructuredError?)
	if self._destroyed then
		return false, self:_setError("destroyed", "AntiAfk has been destroyed.")
	end
	if type(options) ~= "table" then
		return false, self:_setError("invalid_options", "Options must be a table.")
	end
	if options.Enabled ~= nil and type(options.Enabled) ~= "boolean" then
		return false, self:_setError("invalid_enabled", "Enabled must be a boolean.")
	end
	if options.Movement ~= nil and type(options.Movement) ~= "boolean" then
		return false, self:_setError("invalid_movement", "Movement must be a boolean.")
	end
	if options.Interval ~= nil and not finitePositive(options.Interval) then
		return false, self:_setError("invalid_interval", "Interval must be a finite number greater than zero.")
	end
	if options.IsAutomationActive ~= nil and type(options.IsAutomationActive) ~= "function" then
		return false, self:_setError("invalid_automation_callback", "IsAutomationActive must be a function.")
	end

	local enabled = if options.Enabled == nil then self._enabled else options.Enabled
	local movement = if options.Movement == nil then self._movement else options.Movement
	if self._movement ~= movement and not movement then
		self:_clearOrigin()
	end
	self._movement = movement
	self._interval = if options.Interval == nil then self._interval else options.Interval
	self._isAutomationActive = if options.IsAutomationActive == nil
		then self._isAutomationActive
		else options.IsAutomationActive
	self:_clearError()
	if enabled ~= self._enabled then
		return self:SetEnabled(enabled)
	end
	if self._enabled and options.Interval ~= nil then
		self:_startWorker()
	end
	return true, nil
end

function AntiAfk:SetEnabled(enabled: boolean): (boolean, StructuredError?)
	if self._destroyed then
		return false, self:_setError("destroyed", "AntiAfk has been destroyed.")
	end
	if type(enabled) ~= "boolean" then
		return false, self:_setError("invalid_enabled", "Enabled must be a boolean.")
	end
	if enabled == self._enabled then
		return true, nil
	end

	self._enabled = enabled
	self._generation += 1
	self._maid:Remove("worker")
	self._maid:Remove("player")
	self._player = nil
	if not enabled then
		self:_clearOrigin()
		self:_clearError()
		return true, nil
	end
	self:_bindLocalPlayer()

	self:_pulse()
	self:_startWorker()
	return true, nil
end

function AntiAfk:Snapshot(): Snapshot
	return {
		Enabled = self._enabled,
		Movement = self._movement,
		Interval = self._interval,
		Origin = self._origin,
		LastError = self._lastError,
		Destroyed = self._destroyed,
	}
end

function AntiAfk:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	self._enabled = false
	self._generation += 1
	self:_clearOrigin()
	self._maid:Destroy()
end

return AntiAfk

end

__modules["services/BackdropGlass"] = function()
--!strict

export type Snapshot = {
	name: string,
	size: number,
	currentSize: number,
	targetSize: number,
	enabled: boolean,
	owners: number,
	tweening: boolean,
	lastDuration: number,
	effect: BlurEffect?,
	actualBlurEffects: number,
	coordinatorOwners: number,
}

local BackdropGlass = {}
BackdropGlass.__index = BackdropGlass
local BUDGET_TRANSACTION_PREFIX = "backdrop-glass.service-"
local BUDGET_OWNER_PREFIX = "blur-request-"
local nextBudgetServiceId = 0
local MAX_LOGICAL_REQUESTS = 256
local MAX_COORDINATOR_REQUESTS = 1_024


-- Lighting is the runtime-wide authority for a real BlurEffect. Weak keys ensure
-- coordinators cannot retain a runtime after its Lighting service disappears.
local coordinators = setmetatable({}, { __mode = "k" }) :: { [any]: any }

local function finite(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

local function easing(value: any, fallback: Enum.EasingStyle): Enum.EasingStyle?
	if value == nil then return fallback end
	if typeof(value) == "EnumItem" and value.EnumType == Enum.EasingStyle then return value end
	if type(value) == "string" then
		local ok, resolved = pcall(function() return Enum.EasingStyle[value] end)
		if ok then return resolved end
	end
	return nil
end

local function direction(value: any, fallback: Enum.EasingDirection): Enum.EasingDirection?
	if value == nil then return fallback end
	if typeof(value) == "EnumItem" and value.EnumType == Enum.EasingDirection then return value end
	if type(value) == "string" then
		local ok, resolved = pcall(function() return Enum.EasingDirection[value] end)
		if ok then return resolved end
	end
	return nil
end

local function coordinatorSnapshot(coordinator: any)
	local maximum, owners = 0, 0
	for _, request in pairs(coordinator.requests) do
		owners += 1
		maximum = math.max(maximum, request.size)
	end
	return maximum, owners
end

local function ensureEffect(coordinator: any, target: number): BlurEffect?
	if target <= 0 or typeof(coordinator.lighting) ~= "Instance" then return coordinator.effect end
	if coordinator.effect == nil or coordinator.effect.Parent == nil then
		local effect = Instance.new("BlurEffect")
		effect.Name = "PotassiumWorldBlur"
		effect.Size = 0
		effect.Enabled = true
		effect.Parent = coordinator.lighting
		coordinator.effect = effect
	end
	return coordinator.effect
end

local function apply(coordinator: any, options: any?)
	if coordinator.tween ~= nil then
		local previous = coordinator.tween
		coordinator.tween = nil
		previous:Cancel()
	end
	local target, owners = coordinatorSnapshot(coordinator)
	local configured = options or {}
	local duration = if configured.ReducedMotion == true then 0 else (configured.Duration or 0)
	local style = easing(configured.EasingStyle, Enum.EasingStyle.Quart)
	local easingDirection = direction(configured.EasingDirection, Enum.EasingDirection.Out)
	local effect = ensureEffect(coordinator, target)
	coordinator.targetSize = target
	coordinator.lastDuration = duration
	coordinator.ownerCount = owners
	if effect == nil then return end
	if target > 0 then
		effect.Enabled = true
	elseif duration == 0 then
		effect.Enabled = false
	else
		effect.Enabled = effect.Size > 0
	end
	if duration == 0 or coordinator.tweenService == nil then
		if target == 0 and owners == 0 then
			effect:Destroy()
			coordinator.effect = nil
			return
		end
		effect.Size = target
		if target == 0 then effect.Enabled = false end
		return
	end
	local tween = coordinator.tweenService:Create(effect, TweenInfo.new(duration, style :: Enum.EasingStyle, easingDirection :: Enum.EasingDirection), { Size = target })
	coordinator.tween = tween
	tween.Completed:Connect(function()
		if coordinator.tween == tween then
			coordinator.tween = nil
			effect.Size = target
			if target == 0 then
				effect.Enabled = false
				if owners == 0 then
					effect:Destroy()
					if coordinator.effect == effect then
						coordinator.effect = nil
					end
				end
			end
		end
	end)
	tween:Play()
end

local function getCoordinator(runtime: any): any
	local lighting = runtime.services and runtime.services.Lighting
	if lighting ~= nil then
		local existing = coordinators[lighting]
		if existing ~= nil then return existing end
		local created = {
			lighting = lighting,
			tweenService = runtime.services and runtime.services.TweenService,
			requests = {},
			requestCount = 0,
			effect = nil,
			tween = nil,
			targetSize = 0,
			lastDuration = 0,
			ownerCount = 0,
		}
		coordinators[lighting] = created
		return created
	end
	return {
		lighting = nil,
		tweenService = runtime.services and runtime.services.TweenService,
		requests = {}, requestCount = 0, effect = nil, tween = nil, targetSize = 0, lastDuration = 0, ownerCount = 0,
	}
end

function BackdropGlass.new(runtime: any, budgetLedger: any?)
	assert(type(runtime) == "table", "BackdropGlass requires a Runtime")
	if budgetLedger ~= nil then
		assert(
			type(budgetLedger) == "table"
				and type(budgetLedger.Reserve) == "function"
				and type(budgetLedger.Reconcile) == "function"
				and type(budgetLedger.Release) == "function",
			"BackdropGlass requires a valid BudgetLedger"
		)
	end
	nextBudgetServiceId += 1
	return setmetatable({
		_coordinator = getCoordinator(runtime),
		_requests = {},
		_requestCount = 0,
		_budgetLedger = budgetLedger,
		_budgetTransactionId = BUDGET_TRANSACTION_PREFIX .. tostring(nextBudgetServiceId),
		_nextBudgetRequestId = 0,
		_destroyed = false,
	}, BackdropGlass)
end

function BackdropGlass:Validate(amount: any, options: any?): (boolean, any?)
	if self._destroyed then return false, { code = "destroyed", message = "World blur service has been destroyed" } end
	if not finite(amount) or amount < 0 or amount > 32 then return false, { code = "invalid_blur", message = "World blur must be a number from 0 to 32" } end
	if options ~= nil and type(options) ~= "table" then return false, { code = "invalid_world_blur_options", message = "World blur options must be a table" } end
	local configured = options or {}
	local duration = if configured.Duration == nil then 0 else configured.Duration
	if not finite(duration) or duration < 0 or duration > 2 then return false, { code = "invalid_world_blur_duration", message = "World blur Duration must be a number from 0 to 2" } end
	if easing(configured.EasingStyle, Enum.EasingStyle.Quart) == nil or direction(configured.EasingDirection, Enum.EasingDirection.Out) == nil then
		return false, { code = "invalid_world_blur_easing", message = "World blur easing must use Enum.EasingStyle and Enum.EasingDirection values" }
	end
	return true, nil
end

function BackdropGlass:Set(owner: any, amount: any, options: any?): (boolean, any?)
	if self._destroyed then return false, { code = "destroyed", message = "World blur service has been destroyed" } end
	if owner == nil then return false, { code = "invalid_world_blur_owner", message = "World blur owner is required" } end
	local configured = if options == nil then {} else options
	local valid, validationError = self:Validate(amount, configured)
	if not valid then return false, validationError end
	local request = self._requests[owner]
	if amount == 0 then
		if request ~= nil then
			local budgetLedger = self._budgetLedger
			if budgetLedger ~= nil then
				local released, releaseError = budgetLedger:Release(self._budgetTransactionId, request.budgetOwnerId, 0)
				if not released then return false, releaseError end
			end
			self._requests[owner] = nil
			self._coordinator.requests[request] = nil
			self._requestCount -= 1
			self._coordinator.requestCount -= 1
		end
	else
		if request == nil then
			if self._requestCount >= MAX_LOGICAL_REQUESTS then
				return false, { code = "logical_blur_request_limit", message = "World blur logical request limit has been reached" }
			end
			if self._coordinator.requestCount >= MAX_COORDINATOR_REQUESTS then
				return false, { code = "coordinator_blur_request_limit", message = "World blur coordinator request limit has been reached" }
			end
			local budgetLedger = self._budgetLedger
			local budgetOwnerId: string? = nil
			if budgetLedger ~= nil then
				self._nextBudgetRequestId += 1
				budgetOwnerId = BUDGET_OWNER_PREFIX .. tostring(self._nextBudgetRequestId)
				local reserved, reserveError = budgetLedger:Reserve(self._budgetTransactionId, budgetOwnerId, 0, {
					logicalBlurRequests = 1,
				})
				if not reserved then return false, reserveError end
			end
			request = { budgetOwnerId = budgetOwnerId }
			self._requests[owner] = request
			self._coordinator.requests[request] = request
			self._requestCount += 1
			self._coordinator.requestCount += 1
			if budgetLedger ~= nil then
				local reconciled, reconcileError = budgetLedger:Reconcile(self._budgetTransactionId, budgetOwnerId, 0, {
					logicalBlurRequests = 1,
				})
				if not reconciled then
					self._requests[owner] = nil
					self._coordinator.requests[request] = nil
					self._requestCount -= 1
					self._coordinator.requestCount -= 1
					budgetLedger:Release(self._budgetTransactionId, budgetOwnerId, 0)
					return false, reconcileError
				end
			end
		end
		request.size = amount
		request.options = configured
	end
	apply(self._coordinator, configured)
	return true, nil
end

function BackdropGlass:Release(owner: any, options: any?): (boolean, any?)
	if self._destroyed then return false, { code = "destroyed", message = "World blur service has been destroyed" } end
	if owner == nil then return false, { code = "invalid_world_blur_owner", message = "World blur owner is required" } end
	return self:Set(owner, 0, options)
end

function BackdropGlass:Snapshot(): Snapshot
	local target, owners = coordinatorSnapshot(self._coordinator)
	local localOwners = 0
	for _ in pairs(self._requests) do localOwners += 1 end
	local effect = self._coordinator.effect
	return {
		name = if effect ~= nil then effect.Name else "PotassiumWorldBlur",
		size = target,
		currentSize = if effect ~= nil then effect.Size else 0,
		targetSize = target,
		enabled = effect ~= nil and effect.Enabled,
		owners = localOwners,
		tweening = self._coordinator.tween ~= nil,
		lastDuration = self._coordinator.lastDuration,
		effect = effect,
		actualBlurEffects = if effect ~= nil and effect.Parent ~= nil then 1 else 0,
		coordinatorOwners = owners,
	}
end

function BackdropGlass:GetCoordinatorSnapshot()
	local target, owners = coordinatorSnapshot(self._coordinator)
	local effect = self._coordinator.effect
	return table.freeze({
		targetSize = target,
		owners = owners,
		actualBlurEffects = if effect ~= nil and effect.Parent ~= nil then 1 else 0,
		effect = effect,
	})
end

function BackdropGlass:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	for _, request in pairs(self._requests) do
		local budgetLedger = self._budgetLedger
		if budgetLedger ~= nil then
			budgetLedger:Release(self._budgetTransactionId, request.budgetOwnerId, 0)
		end
		self._coordinator.requests[request] = nil
		self._coordinator.requestCount -= 1
	end
	table.clear(self._requests)
	self._requestCount = 0
	apply(self._coordinator, { Duration = 0 })
end

return BackdropGlass

end

__modules["services/BackgroundEffects"] = function()
--!strict

local Maid = __require("core/Maid")
local Factory = __require("ui/Factory")
local ImageCrossfade = __require("core/ImageCrossfade")
local AssetPolicy = __require("customization/AssetPolicy")


export type StructuredError = { code: string, message: string }
export type EffectName = "Off" | "Snow" | "Matrix" | "Rain" | "Aurora" | "Dust"

type Particle = {
	object: GuiObject,
	x: number,
	y: number,
	speed: number,
	drift: number,
	phase: number,
	baseTransparency: number,
	gradient: UIGradient?,
}

type Prepared = { state: { Effect: EffectName, Color: Color3?, Image: { Source: string?, Transparency: number }? }, options: { [string]: any } }

local BackgroundEffects = {}
BackgroundEffects.__index = BackgroundEffects

local EFFECT_COUNTS: { [EffectName]: number } = { Off = 0, Snow = 30, Matrix = 36, Rain = 32, Aurora = 4, Dust = 24 }
local EFFECT_NAMES = { "Off", "Snow", "Matrix", "Rain", "Aurora", "Dust" }
BackgroundEffects.Names = EFFECT_NAMES
local STEP_SECONDS = 0.12
local DEFAULT_OPTIONS = { Intensity = 1, Speed = 1, Density = 1, Direction = Vector2.new(0, 1), Seed = 0, Paused = false, Transition = "none", Preset = "standard" }

local function failure(code: string, message: string): StructuredError
	return { code = code, message = message }
end

local function clone(value: any): any
	if type(value) ~= "table" then return value end
	local result = {}
	for key, item in pairs(value) do result[key] = clone(item) end
	return result
end

local function effectName(value: any): EffectName?
	if EFFECT_COUNTS[value :: any] ~= nil then return value :: EffectName end
	return nil
end

local function themeColor(context: any): Color3
	local theme = context.Theme
	if theme and typeof(theme.accentA) == "Color3" then return theme.accentA end
	if theme and theme.colors and typeof(theme.colors.focus) == "Color3" then return theme.colors.focus end
	return Color3.new(1, 1, 1)
end

local function reducedMotion(context: any): boolean
	local theme = context.Theme
	return theme ~= nil and theme.reducedMotion == true
end

local function resolveImage(context: any, policy: any, source: any, owner: any): (string?, StructuredError?)
	if type(policy) ~= "table" or type(policy.Admit) ~= "function" or type(policy.Resolve) ~= "function" then
		return nil, failure("invalid_asset_policy", "Background effects require an AssetPolicy.")
	end
	local admitted, admissionError = policy:Admit(source, "$.background.image", owner)
	if admitted == nil then return nil, admissionError end
	if admitted.kind ~= "image" then return nil, failure("invalid_image", "Background image declarations must use kind='image'.") end
	local resolved, resolveError = policy:Resolve(admitted, context.Runtime, "$.background.image")
	if resolved == nil then return nil, resolveError end
	return resolved, nil
end

local function validNumber(value: any, minimum: number, maximum: number): boolean
	return type(value) == "number" and value == value and value >= minimum and value <= maximum
end

local function finiteNumber(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

local function validateOptions(input: any, current: { [string]: any }): ({ [string]: any }?, StructuredError?)
	if input ~= nil and type(input) ~= "table" then return nil, failure("invalid_options", "Background options must be a table.") end
	local options = clone(current)
	if input == nil then return options, nil end
	for key, value in pairs(input) do
		if key == "Intensity" then
			if not validNumber(value, 0, 1) then return nil, failure("invalid_intensity", "Intensity must be a number from 0 to 1.") end
		elseif key == "Speed" then
			if not validNumber(value, 0, 4) then return nil, failure("invalid_speed", "Speed must be a number from 0 to 4.") end
		elseif key == "Density" then
			if not validNumber(value, 0, 1) then return nil, failure("invalid_density", "Density must be a number from 0 to 1.") end
		elseif key == "Direction" then
			if typeof(value) ~= "Vector2" or not finiteNumber(value.X) or not finiteNumber(value.Y) then return nil, failure("invalid_direction", "Direction must be a finite Vector2.") end
		elseif key == "Seed" then
			if type(value) ~= "number" or value ~= value or value % 1 ~= 0 then return nil, failure("invalid_seed", "Seed must be an integer.") end
		elseif key == "Paused" then
			if type(value) ~= "boolean" then return nil, failure("invalid_paused", "Paused must be a boolean.") end
		elseif key == "Transition" then
			if value ~= "none" and value ~= "crossfade" then return nil, failure("invalid_transition", "Transition must be none or crossfade.") end
		elseif key == "Preset" then
			if type(value) ~= "string" or value == "" then return nil, failure("invalid_preset", "Preset must be a non-empty string.") end
		else
			return nil, failure("unknown_option", "Unknown background option: " .. tostring(key))
		end
		options[key] = value
	end
	return options, nil
end

function BackgroundEffects.new(context: any)
	assert(type(context) == "table" and typeof(context.Root) == "Instance", "BackgroundEffects requires a UI context")
	local baseZ = if context.Theme and context.Theme.zIndex and type(context.Theme.zIndex.base) == "number" then context.Theme.zIndex.base else 1
	local layer = Factory.make("Frame", { Name = "PotassiumBackgroundEffects", Active = false, BackgroundTransparency = 1, BorderSizePixel = 0, ClipsDescendants = true, Size = UDim2.fromScale(1, 1), ZIndex = baseZ + 1 }, context.Root) :: Frame
	local particles = Factory.make("Frame", { Name = "Particles", Active = false, BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), ZIndex = baseZ + 2 }, layer) :: Frame
	local maid = Maid.new()
	local policy = context.AssetPolicy or context.assetPolicy
	if policy == nil then policy = AssetPolicy.new() end
	local image = ImageCrossfade.new(context.Motion, maid, layer, { Name = "Image", Active = false, ScaleType = Enum.ScaleType.Crop, Size = UDim2.fromScale(1, 1), ZIndex = baseZ + 1 })
	local self = setmetatable({
		_context = context, _assetPolicy = policy, _imageOwner = nil, _resolvedImage = nil, _maid = maid, _layer = layer, _particlesRoot = particles, _image = image,
		_pools = {} :: { [EffectName]: { Particle } }, _containers = {} :: { [EffectName]: CanvasGroup },
		_effect = "Off" :: EffectName, _color = themeColor(context), _usesThemeColor = true,
		_state = { Effect = "Off" :: EffectName, Color = nil :: Color3?, Image = nil :: { Source: string?, Transparency: number }? },
		_options = clone(DEFAULT_OPTIONS), _visible = true, _lowPower = false, _generation = 0,
		_workerToken = 0, _workerActive = false, _workerStarts = 0, _workerStops = 0, _stepCount = 0,
		_effectHandles = { nil, nil }, _activeContainer = nil :: CanvasGroup?, _destroyed = false,
		_presets = {},
	}, BackgroundEffects)
	maid:GiveTask(layer)
	self:_installBuiltins()
	if context.ThemeChanged and type(context.ThemeChanged.Connect) == "function" then
		maid:GiveTask(context.ThemeChanged:Connect(function()
			if self._destroyed then return end
			local theme = context.Theme or {}
			local z = if theme.zIndex and type(theme.zIndex.base) == "number" then theme.zIndex.base else 1
			layer.ZIndex, particles.ZIndex = z + 1, z + 2
			image:SetZIndex(z + 1)
			for _, container in pairs(self._containers) do container.ZIndex = z + 2 end
			if self._usesThemeColor then self._color = themeColor(context); self:_applyColor() end
			self:_updateRunning()
		end))
	end
	return self
end

function BackgroundEffects:_installBuiltins()
	self._presets.none = { State = { Effect = "Off" }, Options = {} }
	self._presets.quiet = { State = { Effect = "Dust" }, Options = { Intensity = 0.3, Speed = 0.35, Density = 0.3 } }
	self._presets.ambient = { State = { Effect = "Aurora" }, Options = { Intensity = 0.55, Speed = 0.35, Density = 1 } }
	self._presets.cinematic = { State = { Effect = "Rain" }, Options = { Intensity = 0.75, Speed = 1.2, Density = 0.75, Transition = "crossfade" } }
	self._presets.terminal = { State = { Effect = "Matrix" }, Options = { Intensity = 0.8, Speed = 0.8, Density = 0.85 } }
	self._presets.seasonal = { State = { Effect = "Snow" }, Options = { Intensity = 0.8, Speed = 0.65, Density = 0.9 } }
end

function BackgroundEffects:_container(effect: EffectName): CanvasGroup?
	if effect == "Off" then return nil end
	local existing = self._containers[effect]
	if existing ~= nil then return existing end
	local container = Factory.make("CanvasGroup", { Name = effect, Active = false, BackgroundTransparency = 1, BorderSizePixel = 0, GroupTransparency = 1, Size = UDim2.fromScale(1, 1), Visible = false, ZIndex = self._particlesRoot.ZIndex }, self._particlesRoot) :: CanvasGroup
	self._containers[effect] = container
	self:_warmPool(effect, container)
	return container
end

function BackgroundEffects:_warmPool(effect: EffectName, container: CanvasGroup)
	if self._pools[effect] ~= nil then return end
	local pool = {} :: { Particle }
	local count = EFFECT_COUNTS[effect]
	for index = 1, count do
		local x, y, phase = (index * 37 % 97) / 97, (index * 53 % 101) / 101, (index * 29 % 89) / 89
		local object: GuiObject
		local gradient: UIGradient? = nil
		if effect == "Matrix" then
			object = Factory.make("TextLabel", { Active = false, BackgroundTransparency = 1, BorderSizePixel = 0, Font = Enum.Font.Code, Size = UDim2.fromOffset(12, 16), Text = string.char(0x30 + index % 10), TextSize = 13, TextTransparency = 0.24 + index % 4 * 0.12, TextXAlignment = Enum.TextXAlignment.Center, TextYAlignment = Enum.TextYAlignment.Center, ZIndex = container.ZIndex }, container) :: TextLabel
		elseif effect == "Aurora" then
			object = Factory.make("Frame", { Active = false, BackgroundTransparency = 0.72, BorderSizePixel = 0, Size = UDim2.fromScale(0.62, 0.38), ZIndex = container.ZIndex }, container) :: Frame
			Factory.corner(object, 999)
			gradient = Factory.make("UIGradient", { Color = ColorSequence.new(self._color, self._color:Lerp(Color3.new(1, 1, 1), 0.3)), Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.15), NumberSequenceKeypoint.new(1, 1) }), Rotation = index * 43 }, object) :: UIGradient
		elseif effect == "Snow" or effect == "Dust" then
			object = Factory.make("Frame", { Active = false, BackgroundTransparency = if effect == "Snow" then 0.22 + index % 4 * 0.12 else 0.5 + index % 3 * 0.12, BorderSizePixel = 0, Size = UDim2.fromOffset(if effect == "Snow" then 2 + index % 4 else 1 + index % 2, if effect == "Snow" then 2 + index % 4 else 1 + index % 2), ZIndex = container.ZIndex }, container) :: Frame
			Factory.corner(object, 999)
		else
			object = Factory.make("Frame", { Active = false, BackgroundTransparency = 0.42 + index % 3 * 0.12, BorderSizePixel = 0, Size = UDim2.fromOffset(1 + index % 2, 12 + index % 12), ZIndex = container.ZIndex }, container) :: Frame
		end
		object.Position = UDim2.fromScale(x, y)
		local baseTransparency = if object:IsA("TextLabel") then (object :: TextLabel).TextTransparency else (object :: Frame).BackgroundTransparency
		if object:IsA("TextLabel") then (object :: TextLabel).TextColor3 = self._color else (object :: Frame).BackgroundColor3 = self._color end
		pool[index] = { object = object, x = x, y = y, speed = if effect == "Snow" then 0.012 + phase * 0.018 elseif effect == "Matrix" then 0.045 + phase * 0.04 elseif effect == "Aurora" then 0.006 + phase * 0.01 elseif effect == "Dust" then 0.008 + phase * 0.012 else 0.075 + phase * 0.065, drift = if effect == "Snow" then 0.01 + phase * 0.014 elseif effect == "Rain" then -0.025 elseif effect == "Aurora" then 0.004 + phase * 0.006 else 0, phase = phase, baseTransparency = baseTransparency, gradient = gradient }
	end
	self._pools[effect] = pool
end

function BackgroundEffects:_applyColor()
	for _, pool in pairs(self._pools) do
		for _, particle in ipairs(pool) do
			if particle.object:IsA("TextLabel") then (particle.object :: TextLabel).TextColor3 = self._color else (particle.object :: Frame).BackgroundColor3 = self._color end
			if particle.gradient then particle.gradient.Color = ColorSequence.new(self._color, self._color:Lerp(Color3.new(1, 1, 1), 0.3)) end
		end
	end
end

function BackgroundEffects:_applyPool()
	local pool = self._pools[self._effect]
	if pool == nil then return end
	local active = math.floor(#pool * self._options.Density + 0.00001)
	for index, particle in ipairs(pool) do
		local transparency = 1 - (1 - particle.baseTransparency) * self._options.Intensity
		if particle.object:IsA("TextLabel") then (particle.object :: TextLabel).TextTransparency = transparency else (particle.object :: Frame).BackgroundTransparency = transparency end
		particle.object.Visible = index <= active and self._options.Intensity > 0
	end
end

function BackgroundEffects:_resetPool(effect: EffectName, seed: number)
	local pool = self._pools[effect]
	if pool == nil then return end
	for index, particle in ipairs(pool) do
		local offset = seed + index
		particle.x = (offset * 37 % 97) / 97
		particle.y = (offset * 53 % 101) / 101
		particle.object.Position = UDim2.fromScale(particle.x, particle.y)
	end
end

function BackgroundEffects:_shouldRun(): boolean
	return not self._destroyed and self._visible and not self._lowPower and not reducedMotion(self._context) and not self._options.Paused and self._effect ~= "Off" and self._options.Speed > 0 and self._options.Intensity > 0 and self._options.Density > 0
end

function BackgroundEffects:_stopWorker()
	if self._workerActive then self._workerStops += 1 end
	self._workerToken += 1
	self._workerActive = false
	self._maid:Set("worker", nil)
end

function BackgroundEffects:_updateRunning()
	if not self:_shouldRun() then self:_stopWorker(); return end
	if self._workerActive then return end
	self._workerToken += 1
	local token = self._workerToken
	self._workerActive = true
	self._workerStarts += 1
	local worker = task.spawn(function()
		while not self._destroyed and token == self._workerToken and self:_shouldRun() do
			self:_step()
			task.wait(STEP_SECONDS)
		end
		if token == self._workerToken then self._workerActive = false; self._maid:Remove("worker") end
	end)
	self._maid:Set("worker", worker)
end

function BackgroundEffects:_step()
	local pool = self._pools[self._effect]
	if pool == nil then return end
	local direction = self._options.Direction
	local speedScale = self._options.Speed
	for _, particle in ipairs(pool) do
		if particle.object.Visible then
			particle.y += (particle.speed * direction.Y + particle.drift * direction.X) * speedScale
			particle.x += (particle.drift * direction.Y + particle.speed * direction.X * 0.18) * speedScale
			if particle.y > 1.12 then particle.y = -0.10; particle.x = (particle.x + particle.phase + 0.17) % 1 elseif particle.y < -0.12 then particle.y = 1.10 end
			if particle.x > 1.12 then particle.x = -0.10 elseif particle.x < -0.12 then particle.x = 1.10 end
			particle.object.Position = UDim2.fromScale(particle.x, particle.y)
		end
	end
	self._stepCount += 1
end

function BackgroundEffects:Prepare(state: any, options: any?): (Prepared?, StructuredError?)
	if self._destroyed then return nil, failure("destroyed", "Background effects have been destroyed.") end
	if type(state) ~= "table" then return nil, failure("invalid_state", "Background state must be a table.") end
	for key in pairs(state) do if key ~= "Effect" and key ~= "Color" and key ~= "Image" then return nil, failure("unknown_state_key", "Unknown background state key: " .. tostring(key)) end end
	local nextEffect = if state.Effect == nil then self._effect else effectName(state.Effect)
	if nextEffect == nil then return nil, failure("invalid_effect", "Effect must be Off, Snow, Matrix, Rain, Aurora, or Dust.") end
	local nextColor = if state.Color == nil then self._state.Color else state.Color
	if nextColor ~= nil and typeof(nextColor) ~= "Color3" then return nil, failure("invalid_color", "Background color must be a Color3.") end
	local nextImage = self._state.Image and clone(self._state.Image) or nil
	local nextResolvedImage = self._resolvedImage and clone(self._resolvedImage) or nil
	local nextImageOwner, candidateOwner, replacesImage = self._imageOwner, nil, false
	if state.Image ~= nil then
		replacesImage = true
		if type(state.Image) ~= "table" then return nil, failure("invalid_image", "Image must be a table.") end
		for key in pairs(state.Image) do if key ~= "Source" and key ~= "Transparency" then return nil, failure("unknown_image_key", "Unknown image key: " .. tostring(key)) end end
		local transparency = if state.Image.Transparency == nil then 0 else state.Image.Transparency
		if not validNumber(transparency, 0, 1) then return nil, failure("invalid_transparency", "Image transparency must be a number from 0 to 1.") end
		if state.Image.Source == nil then
			nextImage, nextResolvedImage, nextImageOwner = nil, nil, nil
		else
			candidateOwner = {}
			local source, imageError = resolveImage(self._context, self._assetPolicy, state.Image.Source, candidateOwner)
			if source == nil then
				if type(self._assetPolicy.ReleaseOwner) == "function" then self._assetPolicy:ReleaseOwner(candidateOwner) end
				return nil, imageError
			end
			nextImage = { Source = clone(state.Image.Source), Transparency = transparency }
			nextResolvedImage = if source == "" then nil else { Source = source, Transparency = transparency }
			nextImageOwner = candidateOwner
		end
	end
	local nextOptions, optionsError = validateOptions(options, self._options)
	if nextOptions == nil then
		if candidateOwner ~= nil and type(self._assetPolicy.ReleaseOwner) == "function" then self._assetPolicy:ReleaseOwner(candidateOwner) end
		return nil, optionsError
	end
	local motion = self._context.Motion
	if motion ~= nil and motion:GetMotionPreset(nextOptions.Preset) == nil then
		if candidateOwner ~= nil and type(self._assetPolicy.ReleaseOwner) == "function" then self._assetPolicy:ReleaseOwner(candidateOwner) end
		return nil, failure("unknown_motion_preset", "Unknown motion preset: " .. nextOptions.Preset)
	end
	return { lifecycle = "prepared", state = { Effect = nextEffect, Color = nextColor, Image = nextImage }, resolvedImage = nextResolvedImage, options = nextOptions, imageOwner = nextImageOwner, candidateOwner = candidateOwner, replacesImage = replacesImage }, nil
end

function BackgroundEffects:_showEffect(effect: EffectName, transition: string)
	self._generation += 1
	local generation = self._generation
	for index = 1, 2 do
		local handle = self._effectHandles[index]
		if handle then handle:Cancel("retargeted"); self._effectHandles[index] = nil end
	end
	local incoming = self:_container(effect)
	local outgoing = self._activeContainer
	for _, container in pairs(self._containers) do
		if container ~= incoming and container ~= outgoing then
			container.GroupTransparency = 1
			container.Visible = false
		end
	end
	local immediate = transition == "none" or reducedMotion(self._context) or self._context.Motion == nil
	if incoming == nil then
		if outgoing == nil then self._activeContainer = nil; return end
		if immediate then
			outgoing.GroupTransparency = 1
			outgoing.Visible = false
			self._activeContainer = nil
			return
		end
		outgoing.Visible = true
		self._activeContainer = outgoing
		local leaving = self._context.Motion:Animate(outgoing, { GroupTransparency = 1 }, self._options.Preset)
		self._effectHandles[2] = leaving
		leaving:OnCompleted(function(state: string)
			if generation == self._generation and self._effectHandles[2] == leaving then
				self._effectHandles[2] = nil
				if state == "Completed" or state == "Skipped" then
					outgoing.Visible = false
					if self._activeContainer == outgoing then self._activeContainer = nil end
				end
			end
		end)
		return
	end
	incoming.Visible = true
	if incoming == outgoing then
		incoming.GroupTransparency = 0
		self._activeContainer = incoming
		return
	end
	self._activeContainer = incoming
	if immediate then
		incoming.GroupTransparency = 0
		if outgoing then outgoing.GroupTransparency = 1; outgoing.Visible = false end
		return
	end
	incoming.GroupTransparency = 1
	local entering = self._context.Motion:Animate(incoming, { GroupTransparency = 0 }, self._options.Preset)
	self._effectHandles[1] = entering
	entering:OnCompleted(function()
		if generation == self._generation and self._effectHandles[1] == entering then self._effectHandles[1] = nil end
	end)
	if outgoing then
		outgoing.Visible = true
		local leaving = self._context.Motion:Animate(outgoing, { GroupTransparency = 1 }, self._options.Preset)
		self._effectHandles[2] = leaving
		leaving:OnCompleted(function(state: string)
			if generation == self._generation and self._effectHandles[2] == leaving then
				self._effectHandles[2] = nil
				if state == "Completed" or state == "Skipped" then outgoing.Visible = false end
			end
		end)
	end
end

function BackgroundEffects:AbortPrepared(prepared: any): boolean
	if type(prepared) ~= "table" or prepared.lifecycle ~= "prepared" then return false end
	local candidateOwner = prepared.candidateOwner
	if candidateOwner ~= nil and candidateOwner ~= self._imageOwner and type(self._assetPolicy.ReleaseOwner) == "function" then
		self._assetPolicy:ReleaseOwner(candidateOwner)
		prepared.candidateOwner = nil
	end
	prepared.lifecycle = "aborted"
	return true
end

function BackgroundEffects:CommitPrepared(prepared: any): (boolean, StructuredError?)
	if self._destroyed or type(prepared) ~= "table" or prepared.lifecycle ~= "prepared" or type(prepared.state) ~= "table" or type(prepared.options) ~= "table" then
		self:AbortPrepared(prepared)
		return false, failure("invalid_prepared_state", "Prepared background state is invalid.")
	end
	local previousEffect = self._effect
	local previousSeed = self._options.Seed
	self._effect, self._state, self._resolvedImage, self._options = prepared.state.Effect, prepared.state, prepared.resolvedImage, prepared.options
	self._usesThemeColor = prepared.state.Color == nil
	self._color = prepared.state.Color or themeColor(self._context)
	self:_applyColor()
	if self._effect ~= "Off" then
		self:_container(self._effect)
		if previousEffect ~= self._effect or previousSeed ~= self._options.Seed then self:_resetPool(self._effect, self._options.Seed) end
		self:_applyPool()
	end
	self:_showEffect(self._effect, self._options.Transition)
	local imageState = prepared.resolvedImage
	self._image:Set(if imageState then imageState.Source else nil, if imageState then imageState.Transparency else 0, { Transition = self._options.Transition, Preset = self._options.Preset })
	if prepared.replacesImage then
		local previousOwner = self._imageOwner
		self._imageOwner = prepared.imageOwner
		prepared.candidateOwner = nil
		if previousOwner ~= nil and previousOwner ~= self._imageOwner and type(self._assetPolicy.ReleaseOwner) == "function" then self._assetPolicy:ReleaseOwner(previousOwner) end
	end
	prepared.lifecycle = "committed"
	self:_updateRunning()
	return true, nil
end

function BackgroundEffects:Set(state: any, options: any?): (boolean, StructuredError?)
	local prepared, prepareError = self:Prepare(state, options)
	if prepared == nil then return false, prepareError end
	return self:CommitPrepared(prepared)
end

function BackgroundEffects:Get(): { state: any, options: any }
	return { state = clone(self._state), options = clone(self._options) }
end
BackgroundEffects.GetState = BackgroundEffects.Get
BackgroundEffects.Snapshot = BackgroundEffects.Get

function BackgroundEffects:GetDiagnostics(): { [string]: any }
	local capacity, active = 0, 0
	local capacities = {}
	for effect, pool in pairs(self._pools) do
		capacity += #pool; capacities[effect] = #pool
		if effect == self._effect then for _, particle in ipairs(pool) do if particle.object.Visible then active += 1 end end end
	end
	return { poolCapacity = capacity, poolCapacities = capacities, activeParticles = active, imageLayers = 2, workerActive = self._workerActive, workerStarts = self._workerStarts, workerStops = self._workerStops, generation = self._generation, stepCount = self._stepCount, visible = self._visible, lowPower = self._lowPower, reducedMotion = reducedMotion(self._context), paused = self._options.Paused, effect = self._effect }
end

function BackgroundEffects:ValidateImage(source: any, transparency: any?): (boolean, StructuredError?)
	if source == nil then return true, nil end
	if transparency ~= nil and not validNumber(transparency, 0, 1) then return false, failure("invalid_transparency", "Image transparency must be a number from 0 to 1.") end
	local owner = {}
	local resolved, imageError = resolveImage(self._context, self._assetPolicy, source, owner)
	if type(self._assetPolicy.ReleaseOwner) == "function" then self._assetPolicy:ReleaseOwner(owner) end
	return resolved ~= nil, imageError
end

function BackgroundEffects:SetEffect(name: any, options: any?): (boolean, StructuredError?)
	return self:Set({ Effect = name }, options)
end
function BackgroundEffects:GetEffect(): EffectName return self._effect end
function BackgroundEffects:SetColor(color: any): (boolean, StructuredError?) return self:Set({ Color = color }) end
function BackgroundEffects:SetImage(source: any, transparency: any?, options: any?): (boolean, StructuredError?) return self:Set({ Image = if source == nil then { Source = nil } else { Source = source, Transparency = transparency } }, options) end
function BackgroundEffects:SetPaused(paused: any): (boolean, StructuredError?) return self:Set({}, { Paused = paused }) end

function BackgroundEffects:SetLowPower(enabled: any): boolean
	if self._destroyed then return false end
	self._lowPower = enabled == true; self:_updateRunning(); return true
end
function BackgroundEffects:SetVisible(visible: any): boolean
	if self._destroyed then return false end
	self._visible = visible == true; self._layer.Visible = self._visible; self:_updateRunning(); return true
end

function BackgroundEffects:RegisterPreset(name: any, definition: any): (boolean, StructuredError?)
	if type(name) ~= "string" or name == "" then return false, failure("invalid_preset_name", "Preset name must be a non-empty string.") end
	if type(definition) ~= "table" or type(definition.State) ~= "table" or (definition.Options ~= nil and type(definition.Options) ~= "table") then return false, failure("invalid_preset", "Preset must contain State and optional Options tables.") end
	local prepared, presetError = self:Prepare(definition.State, definition.Options)
	if prepared == nil then return false, presetError end
	if prepared.candidateOwner ~= nil and type(self._assetPolicy.ReleaseOwner) == "function" then self._assetPolicy:ReleaseOwner(prepared.candidateOwner) end
	self._presets[name] = { State = clone(definition.State), Options = clone(definition.Options or {}) }
	return true, nil
end
function BackgroundEffects:UnregisterPreset(name: any): boolean
	if type(name) ~= "string" or self._presets[name] == nil then return false end
	self._presets[name] = nil; return true
end
function BackgroundEffects:ApplyPreset(name: any): (boolean, StructuredError?)
	local preset = self._presets[name]
	if preset == nil then return false, failure("unknown_preset", "Unknown background preset: " .. tostring(name)) end
	return self:Set(clone(preset.State), clone(preset.Options))
end
function BackgroundEffects:ListPresets(): { string }
	local names = {}; for name in pairs(self._presets) do table.insert(names, name) end; table.sort(names); return names
end

function BackgroundEffects:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	self:_stopWorker()
	self._generation += 1
	for index = 1, 2 do local handle = self._effectHandles[index]; if handle then handle:Cancel("destroyed") end end
	if self._imageOwner ~= nil and type(self._assetPolicy.ReleaseOwner) == "function" then self._assetPolicy:ReleaseOwner(self._imageOwner); self._imageOwner = nil end
	self._maid:Destroy()
	table.clear(self._pools); table.clear(self._containers)
end
BackgroundEffects.Unload = BackgroundEffects.Destroy
BackgroundEffects.__call = function() return EFFECT_NAMES end

return BackgroundEffects

end

__modules["services/CommandPalette"] = function()
--!strict

local Maid = __require("core/Maid")
local Factory = __require("ui/Factory")
local Controls = __require("components/Controls")

local CommandPalette = {}
CommandPalette.__index = CommandPalette

local MAX_RESULTS = 100
local DEFAULT_HISTORY_LIMIT = 50
local DEFAULT_SHORTCUT = { keys = { Enum.KeyCode.LeftControl, Enum.KeyCode.LeftShift, Enum.KeyCode.P }, allowWhileTextEntry = false }
local HISTORY_NAMESPACE = "command-palette-history"


local function contains(point: Vector2, object: GuiObject): boolean
	local position, size = object.AbsolutePosition, object.AbsoluteSize
	return point.X >= position.X and point.X <= position.X + size.X and point.Y >= position.Y and point.Y <= position.Y + size.Y
end

local function resultError(code: string, message: string): any
	return { code = code, message = message }
end

local function clone(value: any): any
	if type(value) ~= "table" then return value end
	local output = {}
	for key, item in pairs(value) do output[key] = clone(item) end
	return output
end

local function normalizeWords(value: any): { string }
	local words = {}
	for word in string.gmatch(string.lower(tostring(value or "")), "[%w_%-]+") do table.insert(words, word) end
	return words
end

local function subsequence(needle: string, haystack: string): boolean
	local at = 1
	for index = 1, #haystack do
		if string.sub(haystack, index, index) == string.sub(needle, at, at) then
			at += 1
			if at > #needle then return true end
		end
	end
	return #needle == 0
end

local function fieldRank(query: string, field: string): number?
	if query == "" then return 0 end
	local lower = string.lower(field)
	if lower == query then return 0 end
	if string.sub(lower, 1, #query) == query then return 1 end
	for _, word in ipairs(normalizeWords(lower)) do
		if string.sub(word, 1, #query) == query then return 2 end
	end
	if string.find(lower, query, 1, true) then return 3 end
	if subsequence(query, lower) then return 4 end
	return nil
end

local function commandRank(command: any, query: string): number?
	local title = fieldRank(query, command.Title)
	if title ~= nil then return title end
	local words = table.concat(command.Keywords or {}, " ") .. " " .. tostring(command.Description or "")
	local secondary = fieldRank(query, words)
	return if secondary ~= nil then secondary + 5 else nil
end

local function enabled(command: any): boolean
	if command.Enabled == nil then return true end
	if type(command.Enabled) == "function" then
		local ok, value = pcall(command.Enabled)
		return ok and value == true
	end
	return command.Enabled == true
end

local function normalizeDefinition(definition: any): (any?, any?)
	if type(definition) ~= "table" then return nil, resultError("invalid_command", "Command definition must be a table") end
	if type(definition.Id) ~= "string" or definition.Id == "" then return nil, resultError("invalid_id", "Command Id must be a non-empty string") end
	if type(definition.Title) ~= "string" or definition.Title == "" then return nil, resultError("invalid_title", "Command Title must be a non-empty string") end
	if type(definition.Execute) ~= "function" then return nil, resultError("invalid_execute", "Command Execute must be a function") end
	if definition.Parameters ~= nil and type(definition.Parameters) ~= "table" then
		return nil, resultError("invalid_parameters", "Parameters must be an array")
	end
	local definitionCopy = clone(definition)
	definitionCopy.Keywords = definitionCopy.Keywords or {}
	definitionCopy.Parameters = definitionCopy.Parameters or {}
	for index, parameter in ipairs(definitionCopy.Parameters) do
		if type(parameter) ~= "table" or type(parameter.Id or parameter.Name) ~= "string" then
			return nil, resultError("invalid_parameter", "Parameter " .. tostring(index) .. " needs Id or Name")
		end
		parameter.Id = parameter.Id or parameter.Name
		parameter.Type = parameter.Type or "string"
		if parameter.Type ~= "string" and parameter.Type ~= "number" and parameter.Type ~= "boolean" and parameter.Type ~= "enum" then
			return nil, resultError("invalid_parameter_type", "Unsupported parameter type")
		end
		if parameter.Type == "enum" and type(parameter.Choices) ~= "table" then
			return nil, resultError("invalid_choices", "Enum parameter needs Choices")
		end
	end
	return definitionCopy, nil
end

local function validateArgs(command: any, supplied: any): (boolean, any)
	if supplied ~= nil and type(supplied) ~= "table" then return false, resultError("invalid_args", "Arguments must be a table") end
	local args = {}
	for _, parameter in ipairs(command.Parameters) do
		local value = if supplied then supplied[parameter.Id] else nil
		if value == nil then value = clone(parameter.Default) end
		if value == nil and parameter.Required == true then
			return false, resultError("required_parameter", parameter.Id .. " is required")
		end
		if value ~= nil then
			if parameter.Type == "number" then
				if type(value) == "string" then value = tonumber(value) end
				if type(value) ~= "number" then return false, resultError("invalid_parameter", parameter.Id .. " must be a number") end
			elseif parameter.Type == "boolean" then
				if type(value) == "string" then
					if string.lower(value) == "true" then value = true elseif string.lower(value) == "false" then value = false end
				end
				if type(value) ~= "boolean" then return false, resultError("invalid_parameter", parameter.Id .. " must be a boolean") end
			elseif parameter.Type == "string" and type(value) ~= "string" then
				return false, resultError("invalid_parameter", parameter.Id .. " must be a string")
			elseif parameter.Type == "enum" then
				local found = false
				for _, choice in ipairs(parameter.Choices) do
					local candidate = if type(choice) == "table" then choice.Value else choice
					if candidate == value then found = true break end
				end
				if not found then return false, resultError("invalid_parameter", parameter.Id .. " is not an allowed choice") end
			end
			if type(parameter.Validate) == "function" then
				local ok, valid, message = pcall(parameter.Validate, value, args)
				if not ok or valid == false then return false, resultError("invalid_parameter", tostring(message or parameter.Id .. " is invalid")) end
			end
			args[parameter.Id] = value
		end
	end
	return true, args
end

local function historyRecord(id: any, timestamp: any, success: any): any?
	if type(id) ~= "string" or id == "" or type(timestamp) ~= "number" or type(success) ~= "boolean" then return nil end
	return { id = id, timestamp = timestamp, success = success }
end

local function sanitizeHistory(history: any): { any }
	local sanitized = {}
	if type(history) ~= "table" then return sanitized end
	for _, entry in ipairs(history) do
		if type(entry) == "table" then
			local record = historyRecord(entry.id, entry.timestamp, entry.success)
			if record then table.insert(sanitized, record) end
		end
		if #sanitized >= DEFAULT_HISTORY_LIMIT then break end
	end
	return sanitized
end

function CommandPalette.new(context: any)
	local self = setmetatable({
		_context = context,
		_commands = {},
		_history = {},
		_handles = {},
		_destroyed = false,
		_sequence = 0,
	}, CommandPalette)
	local loaded, snapshot = context.Persistence:LoadInternal(HISTORY_NAMESPACE)
	if loaded and type(snapshot) == "table" and type(snapshot.history) == "table" then
		self._history = sanitizeHistory(snapshot.history)
		context.Persistence:SaveInternal(HISTORY_NAMESPACE, { history = self._history })
	end
	context.Maid:GiveTask(function() self:Destroy() end)
	return self
end

function CommandPalette:RegisterCommand(definition: any): (boolean, any?)
	if self._destroyed then return false, resultError("destroyed", "Command palette is destroyed") end
	local command, errorValue = normalizeDefinition(definition)
	if not command then return false, errorValue end
	if self._commands[command.Id] then return false, resultError("duplicate_id", "A command with this Id already exists") end
	self._commands[command.Id] = command
	self:_refreshHandles()
	return true, command
end

function CommandPalette:RegisterNavigationCommand(definition: any): (boolean, any?)
	if type(definition) ~= "table" or type(definition.RouteId) ~= "string" or definition.RouteId == "" then
		return false, resultError("invalid_route", "Navigation command requires RouteId")
	end
	local routeId, mode = definition.RouteId, definition.Mode
	local command = clone(definition)
	command.Execute = function(args: any)
		if mode == "replace" then
			return self._context.Routes:Replace(routeId, args, "command-palette")
		end
		return self._context.Routes:Navigate(routeId, args, "command-palette")
	end
	command.RouteId, command.Mode = nil, nil
	return self:RegisterCommand(command)
end

function CommandPalette:UnregisterCommand(id: string): boolean
	if self._commands[id] == nil then return false end
	self._commands[id] = nil
	self:_refreshHandles()
	return true
end

function CommandPalette:ListCommands(): { any }
	local commands = {}
	for _, command in pairs(self._commands) do table.insert(commands, clone(command)) end
	table.sort(commands, function(left, right) return left.Id < right.Id end)
	return commands
end

function CommandPalette:_record(command: any, success: boolean)
	table.insert(self._history, 1, historyRecord(command.Id, os.time(), success))
	while #self._history > DEFAULT_HISTORY_LIMIT do table.remove(self._history) end
	self._context.Persistence:SaveInternal(HISTORY_NAMESPACE, { history = self._history })
end

function CommandPalette:ClearHistory(): boolean
	self._history = {}
	self._context.Persistence:SaveInternal(HISTORY_NAMESPACE, { history = self._history })
	self:_refreshHandles()
	return true
end

function CommandPalette:ExecuteCommand(id: string, supplied: any): (boolean, any?)
	local command = self._commands[id]
	if not command then return false, resultError("unknown_command", "Command is not registered") end
	if not enabled(command) then return false, resultError("disabled", "Command is disabled") end
	local valid, args = validateArgs(command, supplied)
	if not valid then return false, args end
	local ok, value = pcall(command.Execute, args, { Library = self._context, Command = clone(command) })
	self:_record(command, ok)
	if not ok then return false, resultError("execution_failed", tostring(value)) end
	return true, value
end

function CommandPalette:_results(query: string): { any }
	local entries = {}
	local recent = {}
	for index, item in ipairs(self._history) do if recent[item.id] == nil then recent[item.id] = index end end
	for _, command in pairs(self._commands) do
		if enabled(command) then
			local rank = commandRank(command, string.lower(query))
			if rank ~= nil then
				local recentIndex = recent[command.Id]
				local boostedRank = rank - (if recentIndex ~= nil then 2 else 0)
				table.insert(entries, { command = command, rank = boostedRank, recent = recentIndex or math.huge })
			end
	end
	end
	table.sort(entries, function(left, right)
		if left.rank ~= right.rank then return left.rank < right.rank end
		if left.recent ~= right.recent then return left.recent < right.recent end
		local lo, ro = left.command.Order or 0, right.command.Order or 0
		if lo ~= ro then return lo < ro end
		if left.command.Title ~= right.command.Title then return left.command.Title < right.command.Title end
		return left.command.Id < right.command.Id
	end)
	local output = {}
	for index = 1, math.min(#entries, MAX_RESULTS) do table.insert(output, clone(entries[index].command)) end
	return output
end

function CommandPalette:_refreshHandles()
	for handle in pairs(self._handles) do handle:_refresh() end
end

function CommandPalette:CreateCommandPalette(options: any): any
	assert(not self._destroyed, "Command palette is destroyed")
	options = options or {}
	local service = self
	self._sequence += 1
	local context, theme, maid = self._context, self._context.Theme, Maid.new()
	local id = "command-palette-" .. tostring(self._sequence)
	local overlay = Factory.make("TextButton", { Name = "CommandPaletteOverlay", Active = true, AutoButtonColor = false, BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.35, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Text = "", Visible = false, ZIndex = theme.zIndex.modal }, context.Modal)
	local panel = Factory.make("Frame", { Name = "CommandPalette", Active = true, AnchorPoint = Vector2.new(0.5, 0.15), Position = UDim2.fromScale(0.5, 0.15), Size = UDim2.fromOffset(620, 430), BackgroundColor3 = theme.colors.surfaceRaised, BorderSizePixel = 0, ZIndex = theme.zIndex.modal + 1 }, overlay)
	Factory.corner(panel, theme.radius.lg)
	Factory.surface(panel, theme, "surface", { popup = true, glass = true })
	Factory.windowShadow(panel, theme)
	Factory.padding(panel, theme.spacing.md)
	local content = Factory.make("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = theme.zIndex.modal + 2 }, panel)
	local order = 0
	local section = { _context = context, _content = content, _persistControls = false }
	function section:_fullId(localId: string): string return id .. "." .. localId end
	function section:_nextOrder(): number order += 1 return order end
	function section:_registerControl(control: any) maid:GiveTask(control) end
	function section:_focus(focusId: string, object: GuiObject, childMaid: any?)
		context.FocusManager:Register(focusId, object, { order = order, group = id })
		local focusMaid = childMaid or maid
		focusMaid:GiveTask(function() context.FocusManager:Unregister(focusId) end)
	end
	local handle: any = { Root = overlay, _maid = maid, _open = false, _destroyed = false, _query = "", _results = {}, _selected = 1, _stage = "results", _args = {}, _running = false, _error = nil, _id = id, _session = 0 }
	local query = Controls.Textbox(section, { Id = "query", Title = "", Default = "", Height = 50, MaxLength = 256, Searchable = false, _inline = false, _parent = content, Callback = function(value: string) handle:SetQuery(value) end })
	query.Root.Position, query.Root.Size = UDim2.fromOffset(0, 0), UDim2.new(1, 0, 0, 50)
	local queryBox = query.Root:FindFirstChildWhichIsA("TextBox") :: TextBox
	local list = Controls.ListView(section, { Id = "results", Title = "Commands", Items = {}, Height = 310, RowHeight = 48, Persist = false, Searchable = false, EmptyText = "No matching commands", Key = "Id", GetTitle = function(item: any) return item.Title end, GetDetail = function(item: any) return (item.Category and item.Category .. " · " or "") .. tostring(item.Description or item.Shortcut or "") end, OnSelect = function(_item: any, index: number?) if index then handle._selected = index end end, OnActivate = function(_row: any, _item: any, index: number?) if index then handle:SelectIndex(index); handle:Submit() end end })
	list.Root.Position, list.Root.Size = UDim2.fromOffset(0, 58), UDim2.new(1, 0, 1, -58)
	handle.QueryBox, handle.ResultList = query, list
	local status = Factory.text(content, "", theme.typography.caption * theme.textScale, theme.states.danger.text, {
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 4, 1, -2),
		Size = UDim2.new(1, -8, 0, 20),
		TextXAlignment = Enum.TextXAlignment.Left,
		Visible = false,
		theme = theme,
	})
	local parameterText = Factory.text(content, "", theme.typography.body * theme.textScale, theme.colors.text, {
		Position = UDim2.fromOffset(4, 58),
		Size = UDim2.new(1, -8, 1, -86),
		TextWrapped = true,
		TextYAlignment = Enum.TextYAlignment.Top,
		Visible = false,
		theme = theme,
	})
	local parameterControls = {}
	local parameterTextBoxes: { TextBox } = {}
	local function releaseParameterFocus()
		for _, textBox in ipairs(parameterTextBoxes) do
			textBox:ReleaseFocus()
		end
	end
	local function focusFirstParameter()
		if not handle._open then return end
		for _, textBox in ipairs(parameterTextBoxes) do
			if context.FocusManager:SetFocused(textBox, "commandPaletteParameters") then
				textBox:CaptureFocus()
				return
			end
		end
	end
	local function focusQuery()
		if not handle._open then return end
		if context.FocusManager:SetFocused(queryBox, "commandPaletteQuery") then
			queryBox:CaptureFocus()
		end
	end
	local function focusParameterDirection(direction: "Up" | "Down")
		local focused = context.FocusManager:FocusDirectional(direction)
		if focused and focused:IsA("TextBox") then
			(focused :: TextBox):CaptureFocus()
		end
	end
	local function showParameters(command: any)
		releaseParameterFocus()
		for _, control in ipairs(parameterControls) do control:Destroy() end
		table.clear(parameterControls)
		table.clear(parameterTextBoxes)
		for index, parameter in ipairs(command.Parameters) do
			local control = Controls.Textbox(section, {
				Id = "parameter-" .. parameter.Id,
				Title = parameter.Id .. " (" .. parameter.Type .. ")",
				Default = tostring(if handle._args[parameter.Id] == nil then "" else handle._args[parameter.Id]),
				Height = 44,
				MaxLength = 256,
				Searchable = false,
				_parent = content,
				Callback = function(value: string) handle:SetParameter(parameter.Id, value) end,
			})
			control.Root.Position = UDim2.fromOffset(0, 58 + (index - 1) * 48)
			control.Root.Size = UDim2.new(1, 0, 0, 44)
			table.insert(parameterControls, control)
			table.insert(parameterTextBoxes, control._focusObject :: TextBox)
		end
	end
	function handle:_refresh()
		if self._destroyed then return end
		self._results = service:_results(self._query)
		if self._selected > #self._results then self._selected = math.max(1, #self._results) end
		list:SetItems(self._results)
		if self._results[self._selected] then list:SetSelected(self._results[self._selected].Id) end
		status.Text = self._error or ""
		status.Visible = self._error ~= nil
		query.Root.Visible = self._stage == "results"
		local selected = self._results[self._selected]
		local rows = {}
		if selected and self._stage == "parameters" then
			table.insert(rows, selected.Title)
			for _, parameter in ipairs(selected.Parameters) do
				table.insert(rows, tostring(parameter.Id) .. " (" .. parameter.Type .. "): " .. tostring(self._args[parameter.Id] or ""))
			end
		end
		parameterText.Text = table.concat(rows, "\n")
		parameterText.Visible = false
		list.Root.Visible = self._stage == "results"
		for _, control in ipairs(parameterControls) do control.Root.Visible = self._stage == "parameters" end
	end
	function handle:Open()
		if self._destroyed or self._open then return self end
		self._open = true
		self._session += 1
		overlay.Visible = true
		self:_refresh()
		context.InputRouter:PushModal(id, self)
		if self._stage == "parameters" then
			context.FocusManager:PushModal(id, parameterTextBoxes[1])
			focusFirstParameter()
		else
			context.FocusManager:PushModal(id, queryBox)
			focusQuery()
		end
		return self
	end
	function handle:Close()
		if not self._open then return self end
		self._session += 1
		releaseParameterFocus()
		self._open = false; self._stage = "results"; self._error = nil; overlay.Visible = false; context.InputRouter:PopModal(id); context.FocusManager:PopModal(id); queryBox:ReleaseFocus(); return self
	end
	function handle:Toggle() if self._open then return self:Close() else return self:Open() end end
	function handle:SetQuery(value: any) self._query = tostring(value or ""); if query:Get() ~= self._query then query:Set(self._query) end; self:_refresh(); return self end
	function handle:GetQuery(): string return self._query end
	function handle:GetResults(): { any } return clone(self._results) end
	function handle:SelectIndex(index: number) if index >= 1 and index <= #self._results then self._selected = index; list:SetSelected(self._results[index].Id); list:ScrollTo(index, "center") end return self end
	function handle:_submitArgs()
		local selected = self._results[self._selected]
		if not selected then return false, resultError("no_selection", "No command is selected") end
		local ok, args = validateArgs(selected, self._args)
		if not ok then self._error = args.message; self:_refresh(); return false, args end
		self._running = true
		local session = self._session
		task.spawn(function()
			local success, value = service:ExecuteCommand(selected.Id, args)
			self._running = false
			if self._destroyed or self._session ~= session then return end
			if success then self._stage = "success"; self._error = nil; self:Close() else self._stage = "error"; self._error = value.message end
			self:_refresh()
		end)
		return true, nil
	end
	function handle:Submit(supplied: any?)
		if self._running then return false, resultError("running", "Command is running") end
		local selected = self._results[self._selected]
		if not selected then return false, resultError("no_selection", "No command is selected") end
		if type(supplied) == "table" then self._args = clone(supplied) end
		if self._stage == "results" and #selected.Parameters > 0 and supplied == nil then
			self._stage = "parameters"; self._args = {}
			for _, parameter in ipairs(selected.Parameters) do self._args[parameter.Id] = clone(parameter.Default) end
			showParameters(selected)
			self:_refresh()
			focusFirstParameter()
			return true, "parameters"
		end
		return self:_submitArgs()
	end
	function handle:SetParameter(parameterId: string, value: any)
		self._args[parameterId] = value
		self:_refresh()
		return self
	end
	function handle:ClearHistory()
		service:ClearHistory()
		return self
	end
	function handle:GetState(): any return { Open = self._open, Stage = self._stage, Running = self._running, Error = self._error, SelectedIndex = self._selected, Args = clone(self._args) } end
	function handle:GetHistory(): { any } return clone(service._history) end
	function handle:Back()
		if self._stage == "parameters" or self._stage == "error" then
			releaseParameterFocus()
			self._stage = "results"; self._error = nil; self:_refresh(); focusQuery()
			return true
		end
		self:Close()
		return true
	end
	function handle:OnBack() self:Back() end
	function handle:OnPointerBegan(_: any, input: InputObject): boolean
		if not contains(input.Position, panel) then
			self:Close()
		end
		return true
	end
	function handle:OnInputBegan(input: InputObject): boolean
		if input.KeyCode == Enum.KeyCode.Return or input.KeyCode == Enum.KeyCode.KeypadEnter then self:Submit(); return true end
		if self._stage == "parameters" then
			if input.KeyCode == Enum.KeyCode.Up or input.KeyCode == Enum.KeyCode.DPadUp then focusParameterDirection("Up"); return true end
			if input.KeyCode == Enum.KeyCode.Down or input.KeyCode == Enum.KeyCode.DPadDown then focusParameterDirection("Down"); return true end
			return false
		end
		if self._stage == "results" then
			if input.KeyCode == Enum.KeyCode.Up or input.KeyCode == Enum.KeyCode.DPadUp then self:SelectIndex(math.max(1, self._selected - 1)); return true end
			if input.KeyCode == Enum.KeyCode.Down or input.KeyCode == Enum.KeyCode.DPadDown then self:SelectIndex(math.min(#self._results, self._selected + 1)); return true end
		end
		return false
	end
	function handle:Destroy()
		if self._destroyed then return end
		self._destroyed = true; self:Close(); service._handles[self] = nil; maid:Destroy(); overlay:Destroy()
	end
	local shortcutId = id .. ".shortcut"
	context.InputRouter:RegisterShortcut(shortcutId, options.Shortcut or DEFAULT_SHORTCUT, function() handle:Toggle(); return true end)
	maid:GiveTask(function() context.InputRouter:UnregisterShortcut(shortcutId) end)
	service._handles[handle] = true
	handle:_refresh()
	return handle
end

function CommandPalette:ToggleCommandPalette()
	if not self._defaultHandle or self._defaultHandle._destroyed then self._defaultHandle = self:CreateCommandPalette({}) end
	return self._defaultHandle:Toggle()
end

function CommandPalette:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	for handle in pairs(self._handles) do handle:Destroy() end
	table.clear(self._commands); table.clear(self._handles)
end

return CommandPalette

end

__modules["services/DeveloperInspector"] = function()
--!strict

local Maid = __require("core/Maid")

local DeveloperInspector = {}
DeveloperInspector.__index = DeveloperInspector

local DOMAINS = {
	"Store", "Controls", "Windows", "Focus", "InputRouter", "Presentation", "Forms", "Commands",
	"AsyncProviders", "Localization", "Theme", "Config", "Performance",
}
local SECRET_KEYS = { "secret", "token", "password", "authorization", "cookie", "credential", "apikey", "api_key", "api-key" }
local MAX_DEPTH, MAX_ITEMS = 6, 128

local function failure(code: string, message: string)
	return { code = code, message = message }
end

local function orderedKeys(value: { [any]: any }): { any }
	local keys = {}
	for key in pairs(value) do table.insert(keys, key) end
	table.sort(keys, function(a, b)
		local left, right = tostring(a), tostring(b)
		if left == right then return type(a) < type(b) end
		return left < right
	end)
	return keys
end

local function safeInstance(value: Instance)
	local path = {}
	local current: Instance? = value
	for _ = 1, 8 do
		if current == nil then break end
		table.insert(path, 1, current.Name)
		current = current.Parent
	end
	return { __type = "Instance", class = value.ClassName, name = value.Name, path = table.concat(path, ".") }
end

local function isSecretKey(keyName: string?): boolean
	if keyName == nil then return false end
	local lower = string.lower(keyName)
	for _, needle in ipairs(SECRET_KEYS) do
		if string.find(lower, needle, 1, true) then return true end
	end
	return false
end

local function sanitize(value: any, depth: number?, seen: { [any]: boolean }?, keyName: string?): any
	depth, seen = depth or 0, seen or {}
	if isSecretKey(keyName) then return "[REDACTED]" end
	local kind = typeof(value)
	if kind == "nil" or kind == "boolean" or kind == "string" then return value end
	if kind == "number" then return if value == value and value ~= math.huge and value ~= -math.huge then value else "[NON_FINITE]" end
	if kind == "Color3" or kind == "Vector2" or kind == "Vector3" or kind == "UDim2" or kind == "CFrame" or kind == "EnumItem" then
		return { __type = kind, value = tostring(value) }
	end
	if type(value) == "function" or type(value) == "thread" or type(value) == "userdata" then return "[" .. type(value) .. "]" end
	if type(value) ~= "table" then return "[" .. kind .. "]" end
	if depth >= MAX_DEPTH then return "[MAX_DEPTH]" end
	if seen[value] then return "[CYCLE]" end
	seen[value] = true
	local output, count = {}, 0
	for _, key in ipairs(orderedKeys(value)) do
		count += 1
		if count > MAX_ITEMS then output.__truncated = true break end
		local name = tostring(key)
		output[name] = sanitize(value[key], depth + 1, seen, name)
	end
	seen[value] = nil
	return output
end

local function count(value: any): number
	local total = 0
	if type(value) == "table" then for _ in pairs(value) do total += 1 end end
	return total
end

local function compact(value: any): string
	local safe = sanitize(value)
	if type(safe) == "table" then return "{" .. tostring(count(safe)) .. "}" end
	return tostring(safe)
end

local function equal(left: any, right: any): boolean
	if left == right then return true end
	if type(left) ~= "table" or type(right) ~= "table" then return false end
	for key, value in pairs(left) do
		if not equal(value, right[key]) then return false end
	end
	for key in pairs(right) do
		if left[key] == nil then return false end
	end
	return true
end

local function allControls(context: any): { any }
	local result, seen = {}, {}
	for _, window in ipairs(context._windows) do
		for _, tab in ipairs(window._tabs or {}) do
			for _, section in ipairs(tab._sections or {}) do
				for _, control in ipairs(section._controls or {}) do
					if not seen[control] then seen[control] = true; table.insert(result, control) end
				end
			end
		end
	end
	table.sort(result, function(a, b) return tostring(a.Id) < tostring(b.Id) end)
	return result
end

function DeveloperInspector.new(context: any, options: any?): any
	options = options or {}
	local self = setmetatable({
		_context = context, _options = options, _maid = Maid.new(), _destroyed = false,
		_visible = if options.Visible ~= nil then options.Visible == true else options.Open ~= false,
		_allowActions = options.AllowActions == true, _query = "", _domain = tostring(options.Domain or "Store"),
		_snapshots = {}, _dirty = {}, _forms = {}, _window = nil, _grid = nil, _domainControl = nil,
	}, DeveloperInspector)
	for form in pairs(context._forms or {}) do self._forms[form] = true end
	for _, domain in ipairs(DOMAINS) do self._dirty[domain] = true end
	if context.Store and context.Store.Changed then
		self._maid:GiveTask(context.Store.Changed:Connect(function() self._dirty.Store, self._dirty.Config = true, true end))
	end
	if context.ThemeChanged then self._maid:GiveTask(context.ThemeChanged:Connect(function() self._dirty.Theme = true end)) end
	if options.Window ~= false then self:_createUi() end
	return self
end

function DeveloperInspector:_snapshotStore()
	local rows = {}
	for _, id in ipairs(orderedKeys(self._context.Store._definitions)) do
		local definition = self._context.Store._definitions[id]
		table.insert(rows, { id = id, persist = definition.persist ~= false, value = sanitize(self._context.Store._values[id], nil, nil, id), default = sanitize(definition.default, nil, nil, id) })
	end
	return { count = #rows, rows = rows }
end

function DeveloperInspector:_snapshotControls()
	local rows = {}
	for _, control in ipairs(allControls(self._context)) do
		table.insert(rows, { id = tostring(control.Id), type = tostring(control.ControlType), visible = control._visible ~= false, locked = control._locked == true, destroyed = control._destroyed == true })
	end
	return { count = #rows, rows = rows }
end

function DeveloperInspector:_snapshotWindows()
	local rows = {}
	for _, window in ipairs(self._context._windows) do
		if not window._destroyed then
			local tabs, sections, panels = {}, 0, {}
			for _, tab in ipairs(window._tabs or {}) do table.insert(tabs, tab._id); sections += #(tab._sections or {}) end
			for _, panel in ipairs(window._floatingPanels or {}) do table.insert(panels, { id = panel._id, visible = panel._frame.Visible }) end
			table.sort(tabs)
			table.insert(rows, { id = window._id, title = window._title and window._title.Text or window._id, open = window:IsOpen(), dock = window:GetDockState(), tabs = tabs, sections = sections, panels = panels })
		end
	end
	table.sort(rows, function(a, b) return a.id < b.id end)
	return { count = #rows, rows = rows }
end

function DeveloperInspector:_snapshotFocus()
	local focus = self._context.FocusManager
	local rows = {}
	for _, id in ipairs(orderedKeys(focus._entries)) do
		local entry = focus._entries[id]
		table.insert(rows, { id = id, group = entry.group, order = entry.order, object = sanitize(entry.object) })
	end
	return { count = #rows, current = sanitize(focus._focused), modalStack = sanitize(focus._modals), rows = rows }
end

function DeveloperInspector:_snapshotInput()
	local input = self._context.InputRouter
	local eligibility = input:GetEligibilitySnapshot()
	local diagnostic = input:GetDiagnosticSnapshot()
	return {
		shortcuts = diagnostic.shortcuts,
		menuKeys = diagnostic.menuKeys,
		modals = diagnostic.modals,
		backHandlers = diagnostic.backHandlers,
		textEntry = eligibility.textEntry,
		gameInput = diagnostic.gameInput,
	}
end

function DeveloperInspector:_snapshotPresentation()
	local p = self._context.Presentation
	return { search = count(p._searchEntries), tooltips = count(p._tooltipRegistrations), keybinds = count(p._keybinds), notifications = count(p._notifications), dialogs = count(p._dialogs) }
end

function DeveloperInspector:_snapshotForms()
	local rows, seen = {}, {}
	for form in pairs(self._context._forms or {}) do self._forms[form] = true end
	for form in pairs(self._forms) do
		if not form._destroyed and not seen[form] then
			seen[form] = true
			table.insert(rows, sanitize(form:GetState()))
		end
	end
	table.sort(rows, function(a, b) return compact(a) < compact(b) end)
	return { count = #rows, rows = rows }
end

function DeveloperInspector:_snapshotCommands()
	local commands = self._context.CommandPalette:ListCommands()
	return { count = #commands, commands = sanitize(commands), history = sanitize(self._context.CommandPalette._history) }
end

function DeveloperInspector:_snapshotAsyncProviders()
	local rows = {}
	for _, control in ipairs(allControls(self._context)) do
		if type(control.GetProviderState) == "function" then
			table.insert(rows, { id = control.Id, state = control:GetProviderState() })
		end
	end
	return { count = #rows, rows = rows }
end

function DeveloperInspector:_snapshotLocalization()
	local service = self._context.Localization
	return { locale = service:GetLocale(), direction = service:GetDirection(), locales = service:ListLocales() }
end

function DeveloperInspector:_snapshotTheme()
	local draft = nil
	for editor in pairs(self._context._themeEditors or {}) do
		if not editor._destroyed and type(editor.GetDraft) == "function" then
			draft = editor:GetDraft()
			break
		end
	end
	return { current = sanitize(self._context.Theme), draft = sanitize(draft) }
end

function DeveloperInspector:_snapshotConfig()
	local rows = {}
	for _, id in ipairs(orderedKeys(self._context.Store._definitions)) do
		local d, value = self._context.Store._definitions[id], self._context.Store._values[id]
		if d.persist ~= false then
			local current, default = sanitize(value, nil, nil, id), sanitize(d.default, nil, nil, id)
			if not equal(current, default) then table.insert(rows, { id = id, current = current, default = default }) end
		end
	end
	return { changed = #rows, diff = rows, profile = self._context._defaultProfile }
end

function DeveloperInspector:_snapshotPerformance()
	local instances = 0
	for _ in ipairs(self._context.Root:GetDescendants()) do instances += 1 end
	local controls, providers = allControls(self._context), 0
	for _, control in ipairs(controls) do if type(control.GetProviderState) == "function" then providers += 1 end end
	local input = self._context.InputRouter:GetDiagnosticSnapshot()
	return {
		instances = instances,
		windows = #self._context._windows,
		controls = #controls,
		focusEntries = count(self._context.FocusManager._entries),
		shortcuts = input.shortcuts,
		providers = providers,
	}
end

function DeveloperInspector:_capture(domain: string): any
	local capturers = {
		Store = self._snapshotStore, Controls = self._snapshotControls, Windows = self._snapshotWindows, Focus = self._snapshotFocus,
		InputRouter = self._snapshotInput, Presentation = self._snapshotPresentation, Forms = self._snapshotForms, Commands = self._snapshotCommands,
		AsyncProviders = self._snapshotAsyncProviders, Localization = self._snapshotLocalization, Theme = self._snapshotTheme, Config = self._snapshotConfig, Performance = self._snapshotPerformance,
	}
	local capture = capturers[domain]
	if capture == nil then return nil end
	return capture(self)
end

function DeveloperInspector:Refresh(domain: string?): any
	assert(not self._destroyed, "DeveloperInspector is destroyed")
	if domain ~= nil and domain ~= "" then
		assert(table.find(DOMAINS, domain), "Unknown inspector domain: " .. tostring(domain))
		self._snapshots[domain], self._dirty[domain] = self:_capture(domain), false
		self:_render()
		return sanitize(self._snapshots[domain])
	end
	for _, name in ipairs(DOMAINS) do self._snapshots[name], self._dirty[name] = self:_capture(name), false end
	self:_render()
	return self:GetSnapshot()
end

function DeveloperInspector:GetSnapshot(domain: string?): any
	if domain then
		assert(table.find(DOMAINS, domain), "Unknown inspector domain: " .. tostring(domain))
		if self._snapshots[domain] == nil then self:Refresh(domain) end
		return sanitize(self._snapshots[domain])
	end
	local output = {}
	for _, name in ipairs(DOMAINS) do if self._snapshots[name] == nil then self:Refresh(name) end; output[name] = sanitize(self._snapshots[name]) end
	return output
end

function DeveloperInspector:GetDomains(): { string } return table.clone(DOMAINS) end
function DeveloperInspector:SetQuery(query: any): any self._query = string.lower(tostring(query or "")); self:_render(); return self end
function DeveloperInspector:GetQuery(): string return self._query end
function DeveloperInspector:SetVisible(visible: boolean): any self._visible = visible == true; if self._window then self._window:SetOpen(self._visible) end; return self end
function DeveloperInspector:SelectDomain(domain: string): any assert(table.find(DOMAINS, domain), "Unknown inspector domain: " .. tostring(domain)); self._domain = domain; if self._snapshots[domain] == nil or self._dirty[domain] then self:Refresh(domain) else self:_render() end; return self end

function DeveloperInspector:Export(format: string?): any
	local snapshot = self:GetSnapshot()
	if format == nil or format == "table" then return snapshot end
	assert(format == "json", "Export format must be table or json")
	return self._context.Runtime:jsonEncode(snapshot)
end

function DeveloperInspector:Copy(): (boolean, any?)
	local encoded, encodeError = self:Export("json")
	if encoded == nil then return false, encodeError end
	local clipboard = self._context.Runtime.clipboard
	if clipboard == nil or type(clipboard.write) ~= "function" then return false, failure("clipboard_unavailable", "Clipboard writing is unavailable") end
	local ok, err = pcall(clipboard.write, clipboard, encoded)
	return ok, if ok then nil else failure("clipboard_failed", tostring(err))
end

function DeveloperInspector:FocusControl(id: string): (boolean, any?)
	if not self._allowActions then return false, failure("actions_disabled", "Inspector actions are disabled") end
	for _, control in ipairs(allControls(self._context)) do
		if control.Id == id and type(control.Focus) == "function" then
			control:Focus("inspector")
			return true, nil
		end
	end
	return false, failure("unknown_control", "No focusable control exists for " .. tostring(id))
end
function DeveloperInspector:ResetStoreField(id: string): (boolean, any?)
	if not self._allowActions then return false, failure("actions_disabled", "Inspector actions are disabled") end
	return self._context.Store:Reset(id)
end
function DeveloperInspector:ClearHistory(): (boolean, any?)
	if not self._allowActions then return false, failure("actions_disabled", "Inspector actions are disabled") end
	return self._context.CommandPalette:ClearHistory(), nil
end

function DeveloperInspector:ClearLogs(): (boolean, any?)
	if not self._allowActions then return false, failure("actions_disabled", "Inspector actions are disabled") end
	local cleared = 0
	for _, control in ipairs(allControls(self._context)) do
		if tostring(control.ControlType) == "LogViewer" and type(control.Clear) == "function" then
			control:Clear()
			cleared += 1
		end
	end
	return true, { cleared = cleared }
end

function DeveloperInspector:_createUi()
	local window = self._context:CreateWindow({ Id = "developer-inspector", Title = "Developer Inspector", Open = self._visible, Size = Vector2.new(820, 580) })
	local tab = window:Tab({ Id = "inspector", Title = "Inspector" })
	local section = tab:Section({ Id = "inspect", Title = "Runtime" })
	self._window = window
	self._domainControl = section:SegmentedControl({ Id = "domain", Title = "Domain", Items = DOMAINS, Default = self._domain, Persist = false, Callback = function(value: any) self:SelectDomain(tostring(value)) end })
	section:Textbox({ Id = "query", Title = "Filter", Default = "", Persist = false, Callback = function(value: any) self:SetQuery(value) end })
	section:Button({ Id = "refresh", Title = "Refresh", Persist = false, Callback = function() self:Refresh(self._domain) end })
	self._grid = section:DataGrid({ Id = "details", Title = "Details", Persist = false, Height = 300, RowHeight = 34, Columns = { { Id = "key", Title = "Key", Width = 240 }, { Id = "value", Title = "Value", Width = 500 } }, Rows = {} })
	self:Refresh(self._domain)
end

function DeveloperInspector:_render()
	if self._grid == nil then return end
	local snapshot = self._snapshots[self._domain] or self:_capture(self._domain)
	local rows = {}
	for _, key in ipairs(orderedKeys(snapshot)) do
		local value = compact(snapshot[key])
		if self._query == "" or string.find(string.lower(tostring(key) .. " " .. value), self._query, 1, true) then table.insert(rows, { key = tostring(key), value = value }) end
	end
	self._grid:SetRows(rows)
end

function DeveloperInspector:RegisterForm(form: any)
	if form ~= nil then self._forms[form] = true; self._dirty.Forms = true end
	return form
end
function DeveloperInspector:UnregisterForm(form: any) self._forms[form] = nil; self._dirty.Forms = true end

function DeveloperInspector:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	if self._context._developerInspectors then self._context._developerInspectors[self] = nil end
	if self._context.Maid then self._context.Maid:Remove(self) end
	if self._window then self._window:Destroy() end
	table.clear(self._forms); table.clear(self._snapshots); self._maid:Destroy()
end

return DeveloperInspector

end

__modules["services/FormState"] = function()
--!strict

local Maid = __require("core/Maid")
local Signal = __require("core/Signal")

local FormState = {}
FormState.__index = FormState

local function copy(value: any): any
	if type(value) ~= "table" then return value end
	local result = {}
	for key, item in pairs(value) do result[key] = copy(item) end
	return result
end

local function equal(a: any, b: any): boolean
	if type(a) ~= type(b) then return false end
	if type(a) ~= "table" then return a == b end
	for key, value in pairs(a) do if not equal(value, b[key]) then return false end end
	for key in pairs(b) do if a[key] == nil then return false end end
	return true
end

local function resultOf(value: any, ok: any, message: any): (string, string?)
	if value == true or value == nil then return "success", nil end
	if type(value) == "string" then return "error", value end
	if type(value) == "table" then
		local status = value.Status or value.status or "error"
		return status, value.Message or value.message
	end
	if value == false then return "error", if type(message) == "string" then message else "Invalid value" end
	return "error", tostring(message or "Invalid value")
end

local function list(value: any): { any }
	if type(value) == "function" then return { value } end
	if type(value) == "table" then return value end
	return {}
end

local function observeBlur(control: any, callback: () -> ())
	if type(control.ObserveFocusChanged) ~= "function" then return nil end
	return control:ObserveFocusChanged(function(focused: any)
		if focused == false then callback() end
	end)
end

local function focusControl(control: any)
	if type(control.Focus) == "function" then control:Focus("validation") end
end


FormState.Validators = {
	required = function(message: string?)
		return function(value: any)
			return not (value == nil or value == "" or (type(value) == "table" and next(value) == nil)), message or "Required"
		end
	end,
	minLength = function(minimum: number, message: string?)
		return function(value: any) return type(value) == "string" and #value >= minimum, message or "Must be at least " .. minimum .. " characters" end
	end,
	maxLength = function(maximum: number, message: string?)
		return function(value: any) return type(value) == "string" and #value <= maximum, message or "Must be at most " .. maximum .. " characters" end
	end,
	min = function(minimum: number, message: string?)
		return function(value: any) return type(value) == "number" and value >= minimum, message or "Must be at least " .. minimum end
	end,
	max = function(maximum: number, message: string?)
		return function(value: any) return type(value) == "number" and value <= maximum, message or "Must be at most " .. maximum end
	end,
	pattern = function(pattern: string, message: string?)
		return function(value: any) return type(value) == "string" and string.match(value, pattern) ~= nil, message or "Invalid format" end
	end,
	equals = function(field: any, message: string?)
		local key = if type(field) == "table" then field.Id else field
		return function(value: any, values: any) return value == values[key], message or "Must match " .. tostring(key) end
	end,
	oneOf = function(values: { any }, message: string?)
		return function(value: any)
			for _, allowed in ipairs(values) do if value == allowed then return true end end
			return false, message or "Invalid option"
		end
	end,
}

function FormState.new(library: any, options: any?): any
	options = options or {}
	local self = setmetatable({
		_library = library, _store = library.Store, _focus = library.FocusManager, _edits = library.Edits, _fields = {}, _order = {}, _maid = Maid.new(),
		_changed = Signal.new(), _destroyed = false, _submitting = false, _submitToken = 0,
		_options = options,
	}, FormState)
	return self
end

function FormState:_emit(field: any)
	if field.control and type(field.control.SetFieldState) == "function" then field.control:SetFieldState(copy(field.state)) end
	self._changed:Fire(field.id, copy(field.state), self:GetState())
end

function FormState:GetFields(): { any }
	local result = {}
	for _, id in ipairs(self._order) do if self._fields[id] then table.insert(result, self:GetField(id)) end end
	return result
end
function FormState:GetField(id: any): any
	local field = self._fields[type(id) == "table" and id.Id or id]
	return field and copy(field.state) or nil
end
function FormState:GetState(): any
	local fields = {}; local valid = true; local pending = false
	for _, id in ipairs(self._order) do local state = self:GetField(id); if state then fields[id] = state; valid = valid and state.status ~= "error"; pending = pending or state.pending end end
	return { fields = fields, valid = valid and not pending, pending = pending, submitting = self._submitting }
end
function FormState:GetValues(): any
	local values = {}; for _, id in ipairs(self._order) do if self._fields[id] then values[id] = self:GetValue(id) end end; return values
end
function FormState:GetValue(id: any): any
	local key = type(id) == "table" and id.Id or id
	local field = self._fields[key]
	local value = self._store:Get(if field then field.storeId else key)
	return value
end
function FormState:Subscribe(callback: any): any
	assert(type(callback) == "function", "Subscribe requires callback")
	return self._changed:Connect(callback)
end

function FormState:BeginEdit(id: string, initial: any, options: any?): (any?, any?)
	assert(not self._destroyed, "Form is destroyed")
	if self._edits == nil then
		return nil, { code = "edits_unavailable", message = "Edit sessions are unavailable" }
	end
	return self._edits:Begin(id, initial, options)
end

function FormState:RegisterField(control: any, options: any?): any
	assert(not self._destroyed, "Form is destroyed")
	assert(type(control) == "table" and type(control.Id) == "string" and type(control.Get) == "function" and type(control.Set) == "function", "RegisterField requires a value control")
	options = options or {}
	local id = options.Id or control.Id
	self:UnregisterField(id)
	local initial = copy(if options.Initial ~= nil then options.Initial else control:Get())
	local field = { id = id, storeId = control.Id, control = control, options = options, token = 0, maid = Maid.new(), state = { value = copy(control:Get()), initial = initial, dirty = false, touched = false, pending = false, status = "idle", message = nil, errors = {} } }
	self._fields[id] = field; table.insert(self._order, id)
	field.maid:GiveTask(self._store:Subscribe(field.storeId, function(value: any)
		if self._destroyed or self._fields[id] ~= field then return end
		field.token += 1
		field.state.pending = false
		field.state.value = copy(value); field.state.dirty = not equal(value, field.state.initial)
		self:_emit(field)
		if self._submitting then
			self:Validate()
		elseif options.ValidateOn == "change" or options.ValidateOnChange == true or options.Trigger == "change" then
			self:ValidateField(id, "change")
		end
	end))
	local blurConnection = observeBlur(control, function()
		if self._fields[id] == field then
			field.state.touched = true
			self:_emit(field)
			if options.ValidateOn == "blur" or options.ValidateOnBlur == true or options.Trigger == "blur" then
				self:ValidateField(id, "blur")
			end
		end
	end)
	if blurConnection ~= nil then field.maid:GiveTask(blurConnection) end
	field.maid:GiveTask(function() if type(control.SetFieldState) == "function" then control:SetFieldState({ status = "idle" }) end end)
	self:_emit(field)
	return self:GetField(id)
end

function FormState:UnregisterField(id: any): boolean
	local key = type(id) == "table" and id.Id or id; local field = self._fields[key]
	if not field then return false end
	field.token += 1; field.maid:Destroy(); self._fields[key] = nil
	for index, item in ipairs(self._order) do if item == key then table.remove(self._order, index); break end end
	return true
end

function FormState:ValidateField(id: any, trigger: string?): any
	local key = type(id) == "table" and id.Id or id; local field = self._fields[key]
	if not field or self._destroyed or self._resetting then return nil end
	trigger = trigger or "manual"; local configured = field.options.ValidateOn or field.options.Trigger
	if trigger ~= "manual" and configured and configured ~= trigger and trigger ~= "submit" then return self:GetField(key) end
	field.token += 1; local token = field.token
	local fieldValue, values = field.control:Get(), self:GetValues()
	field.state.pending = true; field.state.status = "idle"; field.state.message = nil; field.state.errors = {}; self:_emit(field)
	local validators = list(field.options.Validators or field.options.Validator)
	task.spawn(function()
		local errors = {}; local status = "success"; local message: string? = nil
		for _, validator in ipairs(validators) do
			if self._destroyed or self._fields[key] ~= field or field.token ~= token then return end
			local ok, value, extra = pcall(validator, fieldValue, values, self)
			if not ok then value, extra = false, tostring(value) end
			local nextStatus, nextMessage = resultOf(value, nil, extra)
			if nextStatus ~= "success" then table.insert(errors, nextMessage or "Invalid value"); status, message = nextStatus, nextMessage; if nextStatus == "error" then break end end
		end
		if self._destroyed or self._fields[key] ~= field or field.token ~= token then return end
		field.state.pending = false; field.state.status = status; field.state.message = message; field.state.errors = errors; self:_emit(field)
	end)
	return self:GetField(key)
end
function FormState:Validate(): any
	for _, id in ipairs(self._order) do self:ValidateField(id, "submit") end
	return self:GetState()
end
function FormState:FocusFirstError(): any
	for _, id in ipairs(self._order) do
		local field = self._fields[id]
		if field and field.state.status == "error" then
			focusControl(field.control)
			return field.control
		end
	end
	return nil
end
function FormState:Submit(): boolean
	if self._destroyed or self._submitting then return false end
	self._submitting = true
	self._submitToken += 1
	local token = self._submitToken
	self:Validate()
	self._changed:Fire(nil, nil, self:GetState())
	task.spawn(function()
		while not self._destroyed and self._submitToken == token do
			local pending = false
			for _, id in ipairs(self._order) do
				local field = self._fields[id]
				if field and field.state.pending then pending = true; break end
			end
			if not pending then break end
			task.wait()
		end
		if self._destroyed or self._submitToken ~= token then return end
		for _, id in ipairs(self._order) do
			local field = self._fields[id]
			if field and field.state.status == "error" then
				self:FocusFirstError()
				self._submitting = false
				self._changed:Fire(nil, nil, self:GetState())
				return
			end
		end
		local callback = self._options.OnSubmit
		if type(callback) == "function" then pcall(callback, self:GetValues(), self, { Cancelled = function() return self._destroyed or self._submitToken ~= token end }) end
		if not self._destroyed and self._submitToken == token then self._submitting = false; self._changed:Fire(nil, nil, self:GetState()) end
	end)
	return true
end
function FormState:SetValue(id: any, value: any): any local field = self._fields[type(id) == "table" and id.Id or id]; if field then field.control:Set(value) end; return self end
function FormState:SetTouched(id: any, value: boolean): any local field = self._fields[type(id) == "table" and id.Id or id]; if field then field.state.touched = value == true; self:_emit(field) end; return self end
function FormState:SetDirty(id: any, value: boolean): any local field = self._fields[type(id) == "table" and id.Id or id]; if field then field.state.dirty = value == true; self:_emit(field) end; return self end
function FormState:Reset(): any
	self._submitToken += 1
	self._submitting = false
	self._resetting = true
	for _, id in ipairs(self._order) do local field = self._fields[id]; if field then field.token += 1; field.control:Set(copy(field.state.initial)); field.state.value = copy(field.state.initial); field.state.dirty = false; field.state.touched = false; field.state.pending = false; field.state.status = "idle"; field.state.message = nil; field.state.errors = {}; self:_emit(field) end end
	self._resetting = false
	return self
end
function FormState:Destroy()
	if self._destroyed then return end
	self._destroyed = true; self._submitToken += 1
	local library = self._library
	self._library = nil
	if library ~= nil then
		library._forms[self] = nil
		for inspector in pairs(library._developerInspectors or {}) do
			inspector:UnregisterForm(self)
		end
		if library.Maid ~= nil then library.Maid:Remove(self) end
	end
	for _, id in ipairs(copy(self._order)) do self:UnregisterField(id) end
	self._changed:Destroy(); self._maid:Destroy()
end

return FormState

end

__modules["services/Haptics"] = function()
--!strict

local Maid = __require("core/Maid")

export type Action = "selection" | "confirm" | "warning" | "notification"
export type Snapshot = {
	enabled: boolean,
	available: boolean,
	destroyed: boolean,
	poolSize: number,
	recentPulses: number,
}
export type Haptics = {
	SetEnabled: (self: Haptics, enabled: boolean) -> (),
	IsEnabled: (self: Haptics) -> boolean,
	RegisterEffect: (self: Haptics, action: Action, effect: any) -> (boolean, string?),
	Pulse: (self: Haptics, action: Action, eligibility: any?) -> boolean,
	Play: (self: Haptics, action: Action, eligibility: any?) -> boolean,
	GetSnapshot: (self: Haptics) -> Snapshot,
	Destroy: (self: Haptics) -> (),
}

local Haptics = {}
Haptics.__index = Haptics

local ACTIONS = table.freeze({ selection = true, confirm = true, warning = true, notification = true })
local MAX_EFFECTS = 8
local MAX_POOL = 4
local MAX_PULSES_PER_SECOND = 10

local function addToMaid(maid: any, taskValue: any)
	if type(maid) == "table" and type(maid.GiveTask) == "function" then
		maid:GiveTask(taskValue)
	end
end

local function supports(capability: any): boolean
	if type(capability) ~= "table" then return false end
	if type(capability.Supports) == "function" then
		local available = capability:Supports("haptics")
		return available == true
	end
	return type(capability.GetSnapshot) == "function" and capability:GetSnapshot().haptics == true
end

local function sensoryDisabled(adaptive: any): boolean
	if type(adaptive) ~= "table" or type(adaptive.GetSnapshot) ~= "function" then return false end
	local snapshot = adaptive:GetSnapshot()
	local policy = if type(snapshot) == "table" and type(snapshot.policy) == "table" then snapshot.policy else {}
	return policy.lowPower == true or policy.reduceSensory == true or policy.reducedSensory == true
end

local function invoke(adapter: any, name: string, ...: any): boolean
	if type(adapter) ~= "table" then return false end
	local method = adapter[name]
	if type(method) ~= "function" then return false end
	local ok, result = pcall(method, adapter, ...)
	return ok and result ~= false
end

function Haptics.new(runtime: any, capability: any, adaptive: any, parentMaid: any, options: any?): Haptics
	local settings = if type(options) == "table" then options else {}
	local self = setmetatable({
		_adapter = if type(runtime) == "table" then runtime.haptics else nil,
		_adaptive = adaptive,
		_capability = capability,
		_destroyed = false,
		_enabled = settings.enabled == true,
		_effects = {
			selection = settings.selection,
			confirm = settings.confirm,
			warning = settings.warning,
			notification = settings.notification,
		},
		_maid = Maid.new(),
		_pool = {},
		_pulseTimes = {},
		_poolCursor = 0,
	}, Haptics)
	addToMaid(parentMaid, function() self:Destroy() end)
	return self
end

function Haptics:SetEnabled(enabled: boolean)
	self._enabled = enabled == true
end

function Haptics:IsEnabled(): boolean
	return not self._destroyed and self._enabled and supports(self._capability) and not sensoryDisabled(self._adaptive)
end

function Haptics:RegisterEffect(action: Action, effect: any): (boolean, string?)
	if self._destroyed then return false, "destroyed" end
	if ACTIONS[action] ~= true then return false, "unknown_action" end
	if self._effects[action] == nil then
		local count = 0
		for _ in pairs(self._effects) do count += 1 end
		if count >= MAX_EFFECTS then return false, "effect_limit" end
	end
	self._effects[action] = effect
	return true, nil
end

function Haptics:_eligible(eligibility: any): boolean
	if type(eligibility) == "function" then
		local ok, allowed = pcall(eligibility)
		return ok and allowed == true
	end
	if type(eligibility) == "table" and type(eligibility.router) == "table" and type(eligibility.router.CanInteract) == "function" then
		local ok, allowed = pcall(eligibility.router.CanInteract, eligibility.router, eligibility)
		return ok and allowed == true
	end
	return type(eligibility) ~= "table" or (eligibility.disabled ~= true and eligibility.readOnly ~= true and eligibility.visibility ~= "hidden" and eligibility.visibility ~= "minimized")
end

function Haptics:_admitPulse(): number?
	local now = os.clock()
	local times = self._pulseTimes
	local kept = 0
	for _, time in ipairs(times) do
		if now - time < 1 then kept += 1; times[kept] = time end
	end
	for index = kept + 1, #times do times[index] = nil end
	if kept >= MAX_PULSES_PER_SECOND then return nil end
	local index = kept + 1
	times[index] = now
	return index
end

function Haptics:_rollbackPulse(index: number)
	if self._pulseTimes[index] ~= nil then
		table.remove(self._pulseTimes, index)
	end
end

function Haptics:_nextHandle(effect: any): any
	local adapter = self._adapter
	if type(adapter) ~= "table" or type(adapter.Create) ~= "function" then return nil end
	if #self._pool < MAX_POOL then
		local ok, handle = pcall(adapter.Create, adapter, effect)
		if ok and handle ~= nil then
			if self._destroyed then
				invoke(adapter, "Destroy", handle)
				return nil
			end
			table.insert(self._pool, handle)
			self._maid:GiveTask(function() invoke(adapter, "Destroy", handle) end)
			return handle
		end
	end
	if #self._pool == 0 then return nil end
	self._poolCursor = (self._poolCursor % #self._pool) + 1
	return self._pool[self._poolCursor]
end

function Haptics:Pulse(action: Action, eligibility: any?): boolean
	if ACTIONS[action] ~= true or not self:IsEnabled() or not self:_eligible(eligibility) then return false end
	if not self:IsEnabled() then return false end
	local adapter, effect = self._adapter, self._effects[action]
	if type(adapter) ~= "table" or type(adapter.Pulse) ~= "function" then return false end
	local admission = self:_admitPulse()
	if admission == nil then return false end
	local handle = self:_nextHandle(effect)
	if not self:IsEnabled() then
		self:_rollbackPulse(admission)
		return false
	end
	if handle ~= nil and invoke(adapter, "Pulse", handle, effect) then return true end
	if not self:IsEnabled() then
		self:_rollbackPulse(admission)
		return false
	end
	if invoke(adapter, "Pulse", effect) then return true end
	self:_rollbackPulse(admission)
	return false
end

-- Compatibility for integrations that have not yet migrated to Pulse.
function Haptics:Play(action: Action, eligibility: any?): boolean
	return self:Pulse(action, eligibility)
end

function Haptics:GetSnapshot(): Snapshot
	return {
		enabled = self._enabled,
		available = self:IsEnabled(),
		destroyed = self._destroyed,
		poolSize = #self._pool,
		recentPulses = #self._pulseTimes,
	}
end

function Haptics:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	self._maid:Destroy()
	table.clear(self._effects)
	table.clear(self._pool)
	table.clear(self._pulseTimes)
end

return Haptics

end

__modules["services/Localization"] = function()
--!strict

local Maid = __require("core/Maid")
local Signal = __require("core/Signal")
local Util = __require("core/Util")

local Localization = {}
Localization.__index = Localization

local RTL_LANGUAGES = { ar = true, he = true, fa = true, ur = true }
local PLURAL_KEYS = { zero = true, one = true, two = true, few = true, many = true, other = true }


local function canonical(locale: any): string?
	if type(locale) ~= "string" or locale == "" then return nil end
	local parts = string.split(locale:gsub("_", "-"), "-")
	if #parts == 0 or parts[1] == "" then return nil end
	parts[1] = string.lower(parts[1])
	for index = 2, #parts do
		if #parts[index] == 2 then parts[index] = string.upper(parts[index]) else parts[index] = string.lower(parts[index]) end
	end
	return table.concat(parts, "-")
end

local function resolvePath(messages: any, key: string): any
	local value = messages
	for _, segment in ipairs(string.split(key, ".")) do
		if type(value) ~= "table" then return nil end
		value = value[segment]
	end
	return value
end

local function integerCount(count: any): number
	local number = tonumber(count) or 0
	return math.abs(number)
end

local function category(language: string, count: any): string
	local n = integerCount(count)
	local i = math.floor(n)
	local v = n ~= i
	if language == "fr" then return if (n == 0 or n == 1) then "one" else "other" end
	if language == "ru" and not v then
		local mod10, mod100 = i % 10, i % 100
		if mod10 == 1 and mod100 ~= 11 then return "one" end
		if mod10 >= 2 and mod10 <= 4 and not (mod100 >= 12 and mod100 <= 14) then return "few" end
		if mod10 == 0 or (mod10 >= 5 and mod10 <= 9) or (mod100 >= 11 and mod100 <= 14) then return "many" end
		return "other"
	end
	if language == "ar" and not v then
		if i == 0 then return "zero" end
		if i == 1 then return "one" end
		if i == 2 then return "two" end
		local mod100 = i % 100
		if mod100 >= 3 and mod100 <= 10 then return "few" end
		if mod100 >= 11 and mod100 <= 99 then return "many" end
		return "other"
	end
	return if n == 1 then "one" else "other"
end

local function interpolate(text: string, params: any, count: any): string
	local values = type(params) == "table" and params or {}
	return string.gsub(text, "{([%w_%-%.]+)}", function(name)
		local value = if name == "count" and count ~= nil then count else values[name]
		return if value == nil then "{" .. name .. "}" else tostring(value)
	end)
end

local function renderMessage(message: any, params: any, count: any, locale: string): string?
	if type(message) == "function" then
		local ok, value = pcall(message, params or {}, count, locale)
		if not ok then return nil end
		message = value
	end
	if type(message) == "table" then
		local language = string.match(locale, "^[^-]+") or "en"
		message = message[category(language, count)] or message.other
	end
	if type(message) ~= "string" then return nil end
	return interpolate(message, params, count)
end

local function validateLiteralMap(map: { [any]: any })
	for source, message in pairs(map) do
		assert(type(source) == "string" and source ~= "", "Literal translation source must be a non-empty string")
		if type(message) == "table" then
			local hasCategory = false
			for name, text in pairs(message) do
				assert(PLURAL_KEYS[name] == true, "Literal plural category is invalid")
				assert(type(text) == "string", "Literal plural translation must be a string")
				hasCategory = true
			end
			assert(hasCategory, "Literal plural translation must not be empty")
		else
			assert(type(message) == "string", "Literal translation must be a string or plural map")
		end
	end
end

local function injectedPlayerLocale(context: any): any
	if type(context) ~= "table" then return nil end
	local player = context.Player or context.player
	if type(player) == "table" then return player.LocaleId or player.localeId or player.Locale or player.locale end
	return context.PlayerLocale or context.playerLocale
end

function Localization.new(context: any, options: any?)
	options = options or {}
	local defaultLocale = canonical(options.DefaultLocale or options.defaultLocale or "en") or "en"
	local automatic = options.AutomaticPlayerLocale == true or options.automaticPlayerLocale == true or options.UsePlayerLocale == true or options.usePlayerLocale == true
	local automaticLocale = if automatic then injectedPlayerLocale(context) else nil
	local explicitLocale = options.Locale ~= nil or options.locale ~= nil
	local self = setmetatable({
		_context = context,
		_locales = {},
		_literalLocales = {},
		_literalTranslator = nil,
		_locale = canonical(options.Locale or options.locale or automaticLocale) or defaultLocale,
		_defaultLocale = defaultLocale,
		_fallbackLocale = canonical(options.FallbackLocale or options.fallbackLocale),
		_onMissing = options.OnMissing or options.onMissing,
		_automaticPlayerLocale = automatic,
		_explicitLocale = explicitLocale,
		_maid = Maid.new(),
		_destroyed = false,
		LocaleChanged = Signal.new(),
		LiteralChanged = Signal.new(),
	}, Localization)
	self._maid:GiveTask(self.LocaleChanged)
	self._maid:GiveTask(self.LiteralChanged)
	return self
end
function Localization:AttachContext(context: any)
	self:_assertLive()
	self._context = context
	if not self._automaticPlayerLocale or self._explicitLocale then return self end
	local locale = canonical(injectedPlayerLocale(context))
	if locale ~= nil and locale ~= self._locale then
		self._locale = locale
		self.LocaleChanged:Fire(locale)
		self.LiteralChanged:Fire(locale)
	end
	return self
end

function Localization:_assertLive()
	assert(not self._destroyed, "Localization is destroyed")
end

function Localization:RegisterLocale(locale: any, messages: any, options: any?)
	self:_assertLive()
	local name = canonical(locale)
	assert(name ~= nil, "Locale must be a non-empty string")
	assert(type(messages) == "table", "Locale messages must be a table")
	options = options or {}
	self._locales[name] = { messages = Util.deepCopy(messages), options = Util.deepCopy(options) }
	if options.Default == true then self._defaultLocale = name end
	if options.Fallback == true then self._fallbackLocale = name end
	return self
end

function Localization:UnregisterLocale(locale: any): boolean
	self:_assertLive()
	local name = canonical(locale)
	if name == nil or self._locales[name] == nil then return false end
	self._locales[name] = nil
	if self._locale == name then self:SetLocale(self._defaultLocale) end
	return true
end

function Localization:SetLocale(locale: any): boolean
	self:_assertLive()
	local name = canonical(locale)
	assert(name ~= nil, "Locale must be a non-empty string")
	self._explicitLocale = true
	if self._locale == name then return false end
	local previous = self._locale
	self._locale = name
	self.LocaleChanged:Fire(name, previous, self:GetDirection())
	return true
end

function Localization:GetLocale(): string return self._locale end
function Localization:ListLocales(): { string }
	self:_assertLive()
	local result = {}
	for name in pairs(self._locales) do table.insert(result, name) end
	table.sort(result)
	return result
end

function Localization:RegisterLiteralTranslations(locale: any, map: any)
	self:_assertLive()
	local name = canonical(locale)
	assert(name ~= nil, "Literal translation locale must be a non-empty string")
	assert(type(map) == "table", "Literal translations must be a table")
	validateLiteralMap(map)
	self._literalLocales[name] = Util.deepCopy(map)
	self.LiteralChanged:Fire(name)
	return self
end

function Localization:SetLiteralTranslator(translator: any)
	self:_assertLive()
	assert(translator == nil or type(translator) == "function", "Literal translator must be a function or nil")
	if self._literalTranslator == translator then return self end
	self._literalTranslator = translator
	self.LiteralChanged:Fire()
	return self
end

function Localization:_literalMessage(locale: string, source: string, params: any, count: any): string?
	local translations = self._literalLocales[locale]
	if translations == nil then return nil end
	return renderMessage(translations[source], params, count, locale)
end

function Localization:_keyedLiteralMessage(locale: string, source: string, params: any, count: any): string?
	local entry = self._locales[locale]
	if entry == nil then return nil end
	return renderMessage(resolvePath(entry.messages, source), params, count, locale)
end

function Localization:_candidates(): { string }
	local names, seen = {}, {}
	local function add(name: string?)
		if name and not seen[name] then seen[name] = true; table.insert(names, name) end
	end
	add(self._locale)
	local language = string.match(self._locale, "^[^-]+")
	add(language)
	add(self._fallbackLocale)
	add(self._defaultLocale)
	add("en")
	return names
end

function Localization:HasTranslation(key: any): boolean
	self:_assertLive()
	if type(key) ~= "string" or key == "" then return false end
	for _, locale in ipairs(self:_candidates()) do
		local entry = self._locales[locale]
		if entry and resolvePath(entry.messages, key) ~= nil then return true end
	end
	return false
end

function Localization:Translate(key: any, params: any?, count: any?): string
	self:_assertLive()
	assert(type(key) == "string" and key ~= "", "Translation key must be a non-empty string")
	local message = nil
	local matchedLocale = self._locale
	for _, locale in ipairs(self:_candidates()) do
		local entry = self._locales[locale]
		local found = if entry then resolvePath(entry.messages, key) else nil
		if found ~= nil then
			message = found
			matchedLocale = locale
			break
		end
	end
	if message == nil then
		local fallback = if type(params) == "table" then params.Default else nil
		if type(self._onMissing) == "function" then
			local ok, value = pcall(self._onMissing, key, self._locale)
			if ok and value ~= nil then fallback = value end
		end
		return tostring(fallback or key)
	end
	if type(message) == "function" then
		local ok, value = pcall(message, params or {}, count, matchedLocale)
		if ok then message = value else message = nil end
	end
	if type(message) == "table" then
		local language = string.match(matchedLocale, "^[^-]+") or "en"
		message = message[category(language, count)] or message.other
	end
	if type(message) ~= "string" then return key end
	return interpolate(message, params, count)
end
Localization.T = Localization.Translate

function Localization:TranslateLiteral(source: any, params: any?, count: any?): string
	self:_assertLive()
	assert(type(source) == "string" and source ~= "", "Literal source must be a non-empty string")

	local translator = self._literalTranslator
	if translator ~= nil then
		local context = { params = params, count = count }
		local ok, translated = pcall(translator, source, self._locale, context)
		if ok and translated ~= nil then
			local rendered = renderMessage(translated, params, count, self._locale)
			if rendered ~= nil then return rendered end
		end
	end

	local translated = self:_literalMessage(self._locale, source, params, count)
	if translated ~= nil then return translated end
	translated = self:_keyedLiteralMessage(self._locale, source, params, count)
	if translated ~= nil then return translated end

	local fallback = self._fallbackLocale or self._defaultLocale
	if fallback ~= self._locale then
		translated = self:_literalMessage(fallback, source, params, count)
		if translated ~= nil then return translated end
		translated = self:_keyedLiteralMessage(fallback, source, params, count)
		if translated ~= nil then return translated end
	end
	return interpolate(source, params, count)
end

function Localization:GetDirection(): string
	local language = string.match(self._locale, "^[^-]+") or "en"
	return if RTL_LANGUAGES[language] then "RTL" else "LTR"
end

function Localization:CreateLocalizedText(key: any, params: any?)
	self:_assertLive()
	assert(type(key) == "string" and key ~= "", "Translation key must be a non-empty string")
	local owner, changed, maid = self, Signal.new(), Maid.new()
	local handle = { _key = key, _params = type(params) == "table" and Util.deepCopy(params) or {}, _destroyed = false, Changed = changed }
	local function value() return owner:Translate(handle._key, handle._params, handle._params.count) end
	function handle:Get(): string return value() end
	function handle:SetParams(nextParams: any)
		if self._destroyed then return self end
		self._params = type(nextParams) == "table" and Util.deepCopy(nextParams) or {}
		changed:Fire(value())
		return self
	end
	function handle:Subscribe(callback: any)
		assert(type(callback) == "function", "Localized text subscriber must be a function")
		local connection = changed:Connect(callback)
		return connection
	end
	function handle:Destroy()
		if self._destroyed then return end
		self._destroyed = true
		maid:Destroy()
		changed:Destroy()
	end
	maid:GiveTask(changed)
	maid:GiveTask(owner.LocaleChanged:Connect(function() if not handle._destroyed then changed:Fire(value()) end end))
	return handle
end

function Localization:CreateLocalizedLiteralText(source: any, params: any?)
	self:_assertLive()
	assert(type(source) == "string" and source ~= "", "Literal source must be a non-empty string")
	local owner, changed, maid = self, Signal.new(), Maid.new()
	local handle = { _source = source, _params = type(params) == "table" and Util.deepCopy(params) or {}, _destroyed = false, Changed = changed }
	local function value() return owner:TranslateLiteral(handle._source, handle._params, handle._params.count) end
	local function refresh()
		if not handle._destroyed then changed:Fire(value()) end
	end
	function handle:Get(): string return value() end
	function handle:SetParams(nextParams: any)
		if self._destroyed then return self end
		self._params = type(nextParams) == "table" and Util.deepCopy(nextParams) or {}
		refresh()
		return self
	end
	function handle:Subscribe(callback: any)
		assert(type(callback) == "function", "Localized literal text subscriber must be a function")
		return changed:Connect(callback)
	end
	function handle:Destroy()
		if self._destroyed then return end
		self._destroyed = true
		maid:Destroy()
		changed:Destroy()
	end
	maid:GiveTask(changed)
	maid:GiveTask(owner.LocaleChanged:Connect(refresh))
	maid:GiveTask(owner.LiteralChanged:Connect(refresh))
	return handle
end
Localization.CreateLiteralText = Localization.CreateLocalizedLiteralText

function Localization:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	self._maid:Destroy()
	table.clear(self._locales)
	table.clear(self._literalLocales)
	self._literalTranslator = nil
end

return Localization

end

__modules["services/Presentation"] = function()
--!strict

local Maid = __require("core/Maid")
local Presence = __require("core/Presence")
local Factory = __require("ui/Factory")

local Presentation = {}
Presentation.__index = Presentation

local LEVELS = {
	info = { label = "INFO", icon = "i" },
	success = { label = "COMPLETE", icon = "✓" },
	warning = { label = "WARNING", icon = "!" },
	error = { label = "ERROR", icon = "×" },
}

local function scaled(theme: any, value: number): number
	return math.floor(value * theme.textScale + 0.5)
end
local function popupBackground(theme: any): Color3
	local effects = theme.effects or {}
	local glass = math.clamp(tonumber(effects.glass) or 0, 0, 1)
	local tint = math.clamp(tonumber(effects.glassTint) or 0, 0, 1)
	return theme.colors.popup:Lerp(theme.accentA, glass * tint * 0.12)
end
local function applyPopupStroke(stroke: UIStroke, theme: any): UIStroke
	stroke.Color = theme.colors.borderStrong:Lerp(theme.accentA, 0.52)
	stroke.Thickness = theme.metrics.borderWidth
	stroke.Transparency = 0.78
	return stroke
end
local function popupStroke(parent: Instance, theme: any): UIStroke
	return applyPopupStroke(Factory.stroke(parent, theme.colors.borderStrong), theme)
end
local function contains(point: Vector2, object: GuiObject): boolean
	local position, size = object.AbsolutePosition, object.AbsoluteSize
	return point.X >= position.X and point.X <= position.X + size.X and point.Y >= position.Y and point.Y <= position.Y + size.Y
end

local function focus(context: any, maid: any, id: string, object: GuiObject, order: number)
	context.FocusManager:Register(id, object, { order = order, group = id })
	maid:GiveTask(function()
		context.FocusManager:Unregister(id)
	end)
end

local function presenceOptions(motion: any, options: any, defaultEnter: string?, defaultExit: string?): any?
	local option = if type(options) == "table" then options.Presence else nil
	if option == nil and defaultEnter ~= nil then
		return table.freeze({ Enter = defaultEnter, Exit = defaultExit or "exit" })
	end
	if option == nil or option == false then
		return nil
	end

	local enter: any
	local exit: any
	if option == true then
		enter, exit = defaultEnter or "enter", defaultExit or "exit"
	elseif type(option) == "string" then
		enter, exit = option, "exit"
	elseif type(option) == "table" then
		enter = if option.Enter == nil then "enter" else option.Enter
		exit = if option.Exit == nil then "exit" else option.Exit
	else
		error("Presence must be false, true, a preset string, or { Enter, Exit }", 3)
	end

	assert(type(enter) == "string" and enter ~= "", "Presence.Enter must be a non-empty string")
	assert(type(exit) == "string" and exit ~= "", "Presence.Exit must be a non-empty string")
	assert(motion and type(motion.GetMotionPreset) == "function", "Presentation requires a Motion preset catalog")
	assert(motion:GetMotionPreset(enter) ~= nil, ("Unknown Presence.Enter motion preset %q"):format(enter))
	assert(motion:GetMotionPreset(exit) ~= nil, ("Unknown Presence.Exit motion preset %q"):format(exit))
	return table.freeze({ Enter = enter, Exit = exit })
end

function Presentation.new(context: any)
	local self = setmetatable({
		_context = context,
		_maid = Maid.new(),
		_boxes = {},
		_dialogIds = {},
		_progressOverlays = {},
		_dialogs = {},
		_destroyed = false,
		_keybinds = {},
		_notifications = {},
		_searchEntries = {},
		_overlays = {},
		_notificationOrder = {},
		_notificationSequence = 0,
		_tooltips = {},
		_tooltipRegistrations = {},
		_watermark = nil,
		_hotkeyConfig = {
			Title = "ACTIVE KEYBINDS",
			Position = UDim2.new(1, -296, 1, -16),
			AnchorPoint = Vector2.new(1, 1),
			Visible = false,
		},
		_hotkeyList = nil,
		_surfaces = {},
		_ownedSurfaces = {},
		_ownerSequence = 0,
		_avatarCache = {},
		_avatarOwners = {},
		_avatarPending = {},
		_avatarQueue = {},
		_avatarInflight = 0,
		_avatarWaiters = 0,
		_avatarGeneration = 0,
		_avatarStamp = 1,
		_toastSequence = 0,
		_toastOrder = { top = {}, bottom = {} },
		_toastHosts = {},
		_changelogs = {},
		_exiting = {},
	}, Presentation)
	self:_ensureToastStack()
	if context.ThemeChanged and type(context.ThemeChanged.Connect) == "function" then
		self._maid:GiveTask(context.ThemeChanged:Connect(function()
			for _, entry in pairs(self._overlays) do
				entry.applyTheme()
			end
			for _, apply in pairs(self._surfaces) do
				apply()
			end
		end))
	end
	return self
end
function Presentation:_theme(): any
	return self._context.Theme
end
function Presentation:_themeFor(options: any): any
	if type(options) == "table" and type(options.ThemeProvider) == "function" then
		local ok, provided = pcall(options.ThemeProvider)
		if ok and type(provided) == "table" then
			return provided
		end
	end
	if type(options) == "table" and type(options.Theme) == "table" then
		return options.Theme
	end
	return self:_theme()
end
function Presentation:_trackOwned(owner: any, handle: any)
	if owner == nil then
		return handle
	end
	local owned = self._ownedSurfaces[owner]
	if not owned then
		owned = {}
		self._ownedSurfaces[owner] = owned
	end
	owned[handle] = true
	return handle
end

function Presentation:_releaseOwned(owner: any, handle: any)
	local owned = owner and self._ownedSurfaces[owner]
	if not owned then
		return
	end
	owned[handle] = nil
	if next(owned) == nil then
		self._ownedSurfaces[owner] = nil
	end
end

function Presentation:CreateOwnerToken(label: any?)
	self._ownerSequence += 1
	return table.freeze({
		PresentationOwner = true,
		Id = tostring(label or "owner") .. ":" .. tostring(self._ownerSequence),
	})
end

function Presentation:CloseOwnedSurfaces(owner: any, reason: any?)
	local owned = self._ownedSurfaces[owner]
	if not owned then
		return 0
	end
	local handles = {}
	for handle in pairs(owned) do
		table.insert(handles, handle)
	end
	local closed = 0
	for index = #handles, 1, -1 do
		local handle = handles[index]
		if type(handle.Close) == "function" then
			handle:Close(reason)
			closed += 1
		end
	end
	return closed
end

function Presentation:_removeSurface(key: any)
	self._surfaces[key] = nil
end

function Presentation:_admitAvatar(subject: any, owner: any): (any?, string?)
	local value = tostring(subject)
	if value == "" or #value > 256 then return nil, nil end
	local policy = self._context.AssetPolicy
	if type(policy) ~= "table" or type(policy.Admit) ~= "function" or type(policy.Resolve) ~= "function" or type(policy.ReleaseOwner) ~= "function" then return nil, nil end
	local admitted = policy:Admit({
		kind = "avatar",
		source = { tag = "avatar", value = value },
		fallback = { onUnavailable = "fallback", builtin = "unavailable" },
	}, "$.toast.avatar", owner)
	if admitted == nil then return nil, nil end
	return admitted, value
end

function Presentation:_releaseAvatarOwner(key: string)
	local owner = self._avatarOwners[key]
	if owner == nil then return end
	self._avatarOwners[key] = nil
	local policy = self._context.AssetPolicy
	if type(policy) == "table" and type(policy.ReleaseOwner) == "function" then
		policy:ReleaseOwner(owner)
	end
end

function Presentation:_touchAvatar(key: string, value: string)
	self._avatarCache[key] = { value = value, stamp = self._avatarStamp }
	self._avatarStamp += 1
	local count, oldestKey, oldestStamp = 0, nil, math.huge
	for candidate, entry in pairs(self._avatarCache) do
		count += 1
		if entry.stamp < oldestStamp then oldestKey, oldestStamp = candidate, entry.stamp end
	end
	if count > 32 and oldestKey then
		self._avatarCache[oldestKey] = nil
		self:_releaseAvatarOwner(oldestKey)
	end
end

function Presentation:_cancelAvatarRequest(request: any)
	local cancel = request.cancel
	if type(cancel) == "function" then pcall(cancel) end
	request.cancel = nil
end

function Presentation:_drainAvatarQueue()
	while not self._destroyed and self._avatarInflight < 8 and #self._avatarQueue > 0 do
		local request = table.remove(self._avatarQueue, 1)
		if self._avatarPending[request.key] == request then
			self._avatarInflight += 1
			request.started = true
			local generation = self._avatarGeneration
			local policy = self._context.AssetPolicy
			local resolved: any = nil
			if type(policy) == "table" and type(policy.Resolve) == "function" then
				local ok, result = pcall(policy.Resolve, policy, request.admitted, self._context.Runtime, "$.toast.avatar")
				if ok then resolved = result end
			end
			if self._avatarInflight > 0 then self._avatarInflight -= 1 end
			if not self._destroyed and self._avatarGeneration == generation and self._avatarPending[request.key] == request then
				self._avatarPending[request.key] = nil
				local result = if type(resolved) == "string" and #resolved > 0 and #resolved <= 256 then resolved else nil
				if result then
					self:_touchAvatar(request.key, result)
				else
					self:_releaseAvatarOwner(request.key)
				end
				self._avatarWaiters -= #request.callbacks
				for _, callback in ipairs(request.callbacks) do
					pcall(callback, result)
				end
			end
		end
	end
end

function Presentation:ResolveAvatar(subject: any, callback: ((any) -> ())?)
	if self._destroyed then return nil end
	local key = tostring(subject)
	if key == "" or #key > 256 then
		if callback then callback(nil) end
		return nil
	end
	local cached = self._avatarCache[key]
	if cached then
		cached.stamp = self._avatarStamp
		self._avatarStamp += 1
		if callback then callback(cached.value) end
		return cached.value
	end
	local request = self._avatarPending[key]
	if request then
		if callback and #request.callbacks < 16 and self._avatarWaiters < 128 then
			table.insert(request.callbacks, callback)
			self._avatarWaiters += 1
		elseif callback then
			callback(nil)
		end
		return nil
	end
	local pendingCount = 0
	for _ in pairs(self._avatarPending) do pendingCount += 1 end
	if pendingCount >= 32 or (callback and self._avatarWaiters >= 128) then
		if callback then callback(nil) end
		return nil
	end
	local owner = {}
	local admitted, admittedKey = self:_admitAvatar(key, owner)
	if admitted == nil or admittedKey == nil then
		if callback then callback(nil) end
		return nil
	end
	self._avatarOwners[admittedKey] = owner
	request = { key = admittedKey, admitted = admitted, callbacks = if callback then { callback } else {} }
	self._avatarPending[admittedKey] = request
	self._avatarWaiters += #request.callbacks
	table.insert(self._avatarQueue, request)
	self:_drainAvatarQueue()
	return nil
end

function Presentation:_mountOverlay(id: string, kind: string, handle: any, applyTheme: () -> (), refresh: (() -> ())?)
	local previous = self._overlays[id]
	if previous and previous.handle ~= handle then
		self:_unmountOverlay(id, previous.handle)
	end
	self._overlays[id] = {
		id = id,
		kind = kind,
		handle = handle,
		applyTheme = applyTheme,
		refresh = refresh,
	}
end

function Presentation:_refreshOverlay(id: string)
	local entry = self._overlays[id]
	if entry and entry.refresh then
		entry.refresh()
	end
end

function Presentation:_unmountOverlay(id: string, expectedHandle: any?)
	local entry = self._overlays[id]
	if not entry or (expectedHandle ~= nil and entry.handle ~= expectedHandle) then
		return false
	end
	self._overlays[id] = nil
	return true
end

function Presentation:_animate(instance: Instance, properties: { [string]: any }, preset: string?)
	local motion = self._context.Motion
	if motion and type(motion.Animate) == "function" then
		return motion:Animate(instance, properties, preset or "quick")
	end
	if motion and type(motion.Tween) == "function" then
		return motion:Tween(instance, properties, 0.18)
	end
	for property, value in pairs(properties) do
		(instance :: any)[property] = value
	end
	return nil
end

function Presentation:_enterPresence(config: any?, target: GuiObject, finalTransparency: number): any?
	if not config then
		return nil
	end
	local presence = Presence.new(self._context.Motion, nil, target)
	if target:IsA("CanvasGroup") then
		target.GroupTransparency = 1
		presence:Enter({ GroupTransparency = 1 }, { GroupTransparency = 0 }, config.Enter)
	else
		presence:Enter({ BackgroundTransparency = 1 }, { BackgroundTransparency = finalTransparency }, config.Enter)
	end
	return presence
end

function Presentation:_disableInteraction(root: Instance)
	local function disable(instance: Instance)
		if instance:IsA("TextBox") then
			instance:ReleaseFocus()
			instance.TextEditable = false
		end
		if instance:IsA("ScrollingFrame") then
			instance.Active = false
			instance.ScrollingEnabled = false
		end
		if instance:IsA("GuiObject") then
			instance.Active = false
			instance.Selectable = false
		end
		if instance:IsA("TextButton") then
			instance.Modal = false
		end
	end
	disable(root)
	for _, descendant in ipairs(root:GetDescendants()) do
		disable(descendant)
	end
end

function Presentation:_exitPresence(
	config: any?,
	root: GuiObject,
	liveMaid: any,
	finalize: () -> (),
	entering: any?,
	visual: GuiObject?
)
	if entering then
		entering:Cancel("closed")
	end
	self:_disableInteraction(root)
	liveMaid:Destroy()
	if not config then
		finalize()
		return
	end
	local exitMaid = Maid.new()
	local entry = { maid = exitMaid, finish = nil }
	self._exiting[root] = entry
	local function finish()
		if self._exiting[root] ~= entry then
			return
		end
		self._exiting[root] = nil
		exitMaid:Destroy()
		finalize()
	end
	entry.finish = finish
	local target = visual or root
	local presence = Presence.new(self._context.Motion, exitMaid, target)
	if target:IsA("CanvasGroup") then
		presence:Exit({ GroupTransparency = 1 }, config.Exit, finish)
	else
		presence:Exit({ BackgroundTransparency = 1 }, config.Exit, finish)
	end
end
function Presentation:_ensureToastStack()
	if self._toastStack then return end
	local existing = self._context.Toast:FindFirstChild("PotassiumToastLayout")
	if existing then
		self._toastStack = existing
	else
		self._toastStack = Factory.list(self._context.Toast, self:_theme().spacing.sm)
		self._toastStack.Name = "PotassiumToastLayout"
	end
end

function Presentation:_toastHost(edge: string): Frame
	local host = self._toastHosts[edge]
	if host then return host end
	local theme = self:_theme()
	host = Factory.make("Frame", {
		AnchorPoint = Vector2.new(1, if edge == "top" then 0 else 1),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Position = UDim2.new(1, -16, if edge == "top" then 0 else 1, if edge == "top" then 16 else -16),
		Size = UDim2.new(1, -32, 0, 0),
		ZIndex = theme.zIndex.toast,
	}, self._context.Toast) :: Frame
	host.Name = if edge == "top" then "PotassiumToastTopHost" else "PotassiumToastBottomHost"
	local layout = Factory.list(host, theme.spacing.sm)
	layout.HorizontalAlignment = Enum.HorizontalAlignment.Right
	if edge == "bottom" then
		layout.VerticalAlignment = Enum.VerticalAlignment.Bottom
	end
	self._toastHosts[edge] = host
	return host
end

function Presentation:ShowToast(options: any)
	assert(type(options) == "table", "ShowToast requires options")
	local allowed = { Title = true, Subtitle = true, Text = true, Duration = true, Position = true, Edge = true, Icon = true, AvatarUserId = true, SubtitlePosition = true, MinWidth = true, Owner = true, owner = true, OnClose = true, Theme = true, ThemeProvider = true, ThemeChanged = true }
	for key in pairs(options) do assert(allowed[key] == true, "Unknown toast option " .. tostring(key)) end
	local edge = if options.Position == "top" or options.Edge == "top" then "top" else "bottom"
	local order = self._toastOrder[edge]
	while #order >= 6 do order[1]:Close("capacity") end
	self._toastSequence += 1
	local context, theme, maid = self._context, self:_themeFor(options), Maid.new()
	local host = self:_toastHost(edge)
	local slot = Factory.make("Frame", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		Size = UDim2.fromOffset(0, 0),
		ZIndex = theme.zIndex.toast,
	}, host) :: Frame
	slot.Name = "PotassiumToastSlot"
	slot:SetAttribute("RayfieldMotionSlot", "grow:0.6:Exponential:Out")
	local frame = Factory.make("CanvasGroup", {
		Active = true, AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = theme.colors.surfaceRaised, BackgroundTransparency = 1, BorderSizePixel = 0,
		Selectable = true, Size = UDim2.new(1, 0, 0, 0), ZIndex = theme.zIndex.toast,
	}, slot) :: CanvasGroup
	frame.Name = "PotassiumToastBody"
	frame:SetAttribute("RayfieldMotionEntry", "swipe:360:0.6:Exponential:Out")
	frame:SetAttribute("RayfieldMotionExit", "width:-60:slot-collapse:0.6:Exponential:Out")
	frame:SetAttribute("AccessibilityRole", "alert")
	local frameCorner = Factory.corner(frame, theme.radius.md)
	Factory.surface(frame, theme, "raised", { popup = true, border = false, glass = true })
	Factory.windowShadow(frame, theme)
	local frameStroke = popupStroke(frame, theme)
	local surfaceFill = Factory.make("Frame", {
		Name = "PotassiumRayfieldFill",
		Active = false,
		BackgroundColor3 = popupBackground(theme),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1),
		ZIndex = theme.zIndex.toast,
	}, frame) :: Frame
	Factory.corner(surfaceFill, theme.radius.md)
	local framePadding = Factory.padding(frame, theme.spacing.md)
	local content = Factory.make("Frame", { AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Size = UDim2.new(1, -36, 0, 0), ZIndex = theme.zIndex.toast + 1 }, frame)
	local contentLayout = Factory.list(content, theme.spacing.sm, true)
	local visual = Factory.make("Frame", { BackgroundTransparency = 1, Size = UDim2.fromOffset(28, 28), Visible = false, ZIndex = theme.zIndex.toast + 1 }, content)
	local iconSlot = Factory.make("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Visible = false, ZIndex = theme.zIndex.toast + 2 }, visual)
	local avatar = Factory.make("ImageLabel", { BackgroundTransparency = 1, Image = "", Size = UDim2.fromScale(1, 1), Visible = false, ZIndex = theme.zIndex.toast + 2 }, visual) :: ImageLabel
	local avatarCorner = Factory.corner(avatar, theme.radius.sm)
	local copy = Factory.make("Frame", { AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Size = UDim2.new(1, -36, 0, 0), ZIndex = theme.zIndex.toast + 1 }, content)
	local copyLayout = Factory.list(copy, theme.spacing.xs)
	local heading = Factory.text(copy, "", scaled(theme, theme.typography.caption), theme.colors.text, { AutomaticSize = Enum.AutomaticSize.Y, theme = theme, fontRole = "strong", typographyRole = "caption", Size = UDim2.new(1, 0, 0, 0), TextWrapped = true, TextYAlignment = Enum.TextYAlignment.Top, ZIndex = theme.zIndex.toast + 1 })
	local subtitle = Factory.text(copy, "", scaled(theme, theme.typography.body), theme.colors.textMuted, { AutomaticSize = Enum.AutomaticSize.Y, theme = theme, typographyRole = "body", Size = UDim2.new(1, 0, 0, 0), TextWrapped = true, TextYAlignment = Enum.TextYAlignment.Top, ZIndex = theme.zIndex.toast + 1 })
	heading:SetAttribute("RayfieldMotionContent", "icon:0.05:0.3:Exponential:Out")
	subtitle:SetAttribute("RayfieldMotionContent", "description:0.10:0.3:Exponential:Out")
	local close = Factory.button(frame, "×", theme, { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 0), Size = UDim2.fromOffset(32, 32), ZIndex = theme.zIndex.toast + 2 })
	local handle = { Root = frame, _closed = false, _paused = false, _timer = 0, _remaining = 3, _owner = options.Owner or options.owner, _avatarStamp = 0, _generation = 0, _slot = slot }
	local reducedMotion = context.ReducedMotion == true or (context.Motion and context.Motion.ReducedMotion == true)
	local function animateRayfield(target: Instance, properties: { [string]: any }, duration: number)
		if reducedMotion then
			for property, value in pairs(properties) do
				(target :: any)[property] = value
			end
			return nil
		end
		return context.Motion:Animate(target, properties, {
			Duration = duration,
			EasingStyle = Enum.EasingStyle.Exponential,
			EasingDirection = Enum.EasingDirection.Out,
		})
	end
	local function text(value: any): string
		local source = tostring(value or "")
		if source == "" then return "" end
		local localization = context.Localization
		if type(localization) == "table" and type(localization.TranslateLiteral) == "function" then return localization:TranslateLiteral(source) end
		return source
	end
	local function schedule()
		if handle._timerTask then
			pcall(task.cancel, handle._timerTask)
			handle._timerTask = nil
		end
		handle._timer += 1
		local timer = handle._timer
		if handle._closed or handle._paused then return end
		handle._timerTask = task.delay(handle._remaining, function()
			if not handle._closed and not handle._paused and handle._timer == timer then
				handle._timerTask = nil
				handle:Close("timeout")
			end
		end)
	end
	local function layout()
		local workWidth = math.max(0, context.Root.AbsoluteSize.X - 32)
		frame.Size = UDim2.fromOffset(math.min(math.max(180, handle._minWidth), workWidth), 0)
	end
	local function apply(patch: any, reset: boolean)
		if not handle._paused and handle._deadline then handle._remaining = math.max(0.05, handle._deadline - os.clock()) end
		handle._title = text(if patch.Title ~= nil then patch.Title else handle._title or "")
		handle._subtitle = text(if patch.Subtitle ~= nil then patch.Subtitle else patch.Text or handle._subtitle or "")
		heading.Text, subtitle.Text = handle._title, handle._subtitle
		subtitle.Visible = handle._subtitle ~= ""
		local position = patch.SubtitlePosition or handle._subtitlePosition or "below"
		assert(position == "above" or position == "below", "SubtitlePosition must be 'above' or 'below'")
		handle._subtitlePosition = position
		heading.LayoutOrder, subtitle.LayoutOrder = if position == "above" then 2 else 1, if position == "above" then 1 else 2
		local minimum = tonumber(patch.MinWidth or handle._minWidth or 0) or 0
		handle._minWidth = math.max(0, minimum)
		layout()
		frame:SetAttribute("AccessibilityLabel", handle._title .. (if handle._subtitle ~= "" then ". " .. handle._subtitle else ""))
		frame:SetAttribute("AccessibilityAnnouncement", frame:GetAttribute("AccessibilityLabel"))
		local icon = if patch.Icon ~= nil then patch.Icon else handle._icon
		handle._icon = icon
		iconSlot:ClearAllChildren()
		iconSlot.Visible, avatar.Visible = false, false
		if icon ~= nil and type(context.Icons) == "table" and type(context.Icons.Render) == "function" then
			local ok = pcall(context.Icons.Render, context.Icons, iconSlot, icon, theme, 20, { ZIndex = theme.zIndex.toast + 3 })
			iconSlot.Visible = ok
		end
		local avatarUserId = if patch.AvatarUserId ~= nil then patch.AvatarUserId else handle._avatarUserId
		handle._avatarUserId = avatarUserId
		handle._avatarStamp += 1
		local avatarStamp = handle._avatarStamp
		visual.Visible = iconSlot.Visible
		if avatarUserId ~= nil then
			self:ResolveAvatar(avatarUserId, function(image)
				if not handle._closed and handle._avatarStamp == avatarStamp then
					if type(image) == "string" then
						avatar.Image, avatar.Visible, iconSlot.Visible, visual.Visible = image, true, false, true
					else
						avatar.Image, avatar.Visible, visual.Visible = "", false, iconSlot.Visible
					end
				end
			end)
		end
		if reset or patch.Duration ~= nil then
			local contentLength = #handle._title + #handle._subtitle
			handle._remaining = math.clamp(tonumber(patch.Duration) or (3 + math.ceil(contentLength / 70)), 3, 9)
		end
		handle._deadline = os.clock() + handle._remaining
		schedule()
	end
	local function applyTheme()
		theme = self:_themeFor(options)
		surfaceFill.BackgroundColor3 = popupBackground(theme)
		frame.ZIndex = theme.zIndex.toast
		frameCorner.CornerRadius = UDim.new(0, theme.radius.md)
		applyPopupStroke(frameStroke, theme)
		avatarCorner.CornerRadius = UDim.new(0, theme.radius.sm)
		local inset = UDim.new(0, theme.spacing.md)
		framePadding.PaddingTop, framePadding.PaddingRight, framePadding.PaddingBottom, framePadding.PaddingLeft = inset, inset, inset, inset
		contentLayout.Padding = UDim.new(0, theme.spacing.sm)
		local hostLayout = host:FindFirstChildWhichIsA("UIListLayout")
		if hostLayout then hostLayout.Padding = UDim.new(0, theme.spacing.sm) end
		copyLayout.Padding = UDim.new(0, theme.spacing.xs)
		heading.TextColor3, subtitle.TextColor3 = theme.colors.text, theme.colors.textMuted
		Factory.applyTypography(heading, theme, "caption")
		Factory.applyTypography(subtitle, theme, "body")
		Factory.setButtonState(close, "default", theme)
	end
	local function bindThemeChanged(signal: any)
		maid:Remove("theme-change")
		if signal and type(signal.Connect) == "function" then maid:Set("theme-change", signal:Connect(applyTheme)) end
	end
	function handle:Update(patch: any)
		assert(type(patch) == "table", "Toast Update requires a table")
		for key in pairs(patch) do assert(allowed[key] == true, "Unknown toast option " .. tostring(key)) end
		if patch.Theme ~= nil then options.Theme = patch.Theme end
		if patch.ThemeProvider ~= nil then options.ThemeProvider = patch.ThemeProvider end
		if patch.ThemeChanged ~= nil then options.ThemeChanged = patch.ThemeChanged; bindThemeChanged(options.ThemeChanged) end
		if not self._closed then applyTheme(); apply(patch, patch.Duration ~= nil) end
		return self
	end
	function handle:IsOpen() return not self._closed end
	function handle:Pause()
		if not self._closed and not self._paused then
			self._remaining = math.max(0, self._deadline - os.clock())
			self._paused = true
			if self._timerTask then
				pcall(task.cancel, self._timerTask)
				self._timerTask = nil
			end
			self._timer += 1
		end
		return self
	end
	function handle:Resume() if not self._closed and self._paused then self._paused = false; self._deadline = os.clock() + self._remaining; schedule() end; return self end
	function handle:Close(reason: any?)
		if self._closed then return end
		self._closed = true
		self._generation += 1
		maid:Remove("toast-entry")
		maid:Remove("toast-heading-entry")
		maid:Remove("toast-subtitle-entry")
		if self._timerTask then
			pcall(task.cancel, self._timerTask)
			self._timerTask = nil
		end
		self._timer += 1
		for index, candidate in ipairs(order) do if candidate == self then table.remove(order, index); break end end
		self._presentation:_releaseOwned(self._owner, self)
		self._presentation:_removeSurface(self)
		if type(options.OnClose) == "function" then pcall(options.OnClose, reason) end
		self._presentation:_disableInteraction(frame)
		local exitSize = frame.AbsoluteSize
		frame.AutomaticSize = Enum.AutomaticSize.None
		frame.Size = UDim2.fromOffset(exitSize.X, exitSize.Y)
		local function finalize()
			if self._finalized then return end
			self._finalized = true
			self._presentation._exiting[frame] = nil
			maid:Destroy()
			slot:Destroy()
		end
		self._presentation._exiting[frame] = { finish = finalize }
		if self._presentation._destroyed then
			finalize()
			return
		end
		local slotMotion = animateRayfield(slot, { Size = UDim2.fromOffset(0, 0) }, 0.6)
		animateRayfield(frame, {
			GroupTransparency = 1,
			Size = UDim2.fromOffset(math.max(0, exitSize.X - 60), exitSize.Y),
		}, 0.6)
		if slotMotion then
			slotMotion:OnCompleted(function()
				if self._closed then finalize() end
			end)
		else
			finalize()
		end
	end
	handle.Destroy, handle._presentation = handle.Close, self
	maid:GiveTask(close.Activated:Connect(function() handle:Close("dismiss") end))
	maid:GiveTask(frame.MouseEnter:Connect(function() handle:Pause() end)); maid:GiveTask(frame.MouseLeave:Connect(function() handle:Resume() end))
	maid:GiveTask(frame.SelectionGained:Connect(function() handle:Pause() end)); maid:GiveTask(frame.SelectionLost:Connect(function() handle:Resume() end))
	maid:GiveTask(context.Root:GetPropertyChangedSignal("AbsoluteSize"):Connect(layout))
	self._surfaces[handle] = applyTheme
	bindThemeChanged(options.ThemeChanged)
	table.insert(order, handle); self:_trackOwned(handle._owner, handle); applyTheme(); apply(options, true)
	if type(context.Haptics) == "table" and type(context.Haptics.Pulse) == "function" then context.Haptics:Pulse("notification") end
	local entryGeneration = handle._generation
	local function finishEntry()
		if handle._closed or handle._generation ~= entryGeneration then return end
		local targetSize = frame.AbsoluteSize
		slot.Size = UDim2.fromOffset(0, 0)
		frame.Position = UDim2.fromOffset(360, 0)
		visual.Position = UDim2.fromOffset(12, 0)
		surfaceFill.BackgroundTransparency = 1
		frameStroke.Transparency = 1
		heading.TextTransparency, subtitle.TextTransparency = 1, 1
		if reducedMotion then
			slot.Size = UDim2.fromOffset(targetSize.X, targetSize.Y)
			frame.Position = UDim2.fromOffset(0, 0)
			surfaceFill.BackgroundTransparency = 0
			visual.Position = UDim2.fromOffset(0, 0)
			frameStroke.Transparency = 0.78
			heading.TextTransparency, subtitle.TextTransparency = 0, 0
			return
		end
		animateRayfield(slot, { Size = UDim2.fromOffset(targetSize.X, targetSize.Y) }, 0.6)
		animateRayfield(frame, { Position = UDim2.fromOffset(0, 0) }, 0.6)
		animateRayfield(surfaceFill, { BackgroundTransparency = 0 }, 0.4)
		animateRayfield(frameStroke, { Transparency = 0.78 }, 0.4)
		maid:Set("toast-heading-entry", task.delay(0.05, function()
			if not handle._closed and handle._generation == entryGeneration then
				animateRayfield(visual, { Position = UDim2.fromOffset(0, 0) }, 0.3)
				animateRayfield(heading, { TextTransparency = 0 }, 0.3)
			end
		end))
		maid:Set("toast-subtitle-entry", task.delay(0.10, function()
			if not handle._closed and handle._generation == entryGeneration then
				animateRayfield(subtitle, { TextTransparency = 0 }, 0.3)
			end
		end))
	end
	if reducedMotion then
		finishEntry()
	else
		maid:Set("toast-entry", task.defer(finishEntry))
	end
	return handle
end

function Presentation:ShowChangelog(options: any)
	assert(type(options) == "table", "ShowChangelog requires options")
	local sourceItems = options.Entries or options.entries or options.Items or options.items or {}
	assert(type(sourceItems) == "table", "ShowChangelog Entries must be a table")
	local items = {}
	for index = 1, math.min(#sourceItems, 500) do
		local item = sourceItems[index]
		if type(item) == "string" then
			items[#items + 1] = { Title = item, Subtitle = "" }
		elseif type(item) == "table" then
			items[#items + 1] = { Title = tostring(item.Title or item.title or ""), Subtitle = tostring(item.Subtitle or item.Text or item.text or ""), Action = item.Action, ActionId = item.ActionId or item.actionId }
		end
	end
	local context, theme, maid = self._context, self:_themeFor(options), Maid.new()
	local id = context:_id(options.Id or "changelog")
	local overlay = Factory.make("TextButton", { Active = true, AutoButtonColor = false, BackgroundColor3 = theme.colors.overlay, BackgroundTransparency = 0.38, BorderSizePixel = 0, Modal = true, Selectable = true, Size = UDim2.fromScale(1, 1), Text = "", ZIndex = theme.zIndex.modal }, context.Modal) :: TextButton
	overlay:SetAttribute("AccessibilityRole", "dialog")
	overlay:SetAttribute("AccessibilityAnnouncement", tostring(options.Title or "Changelog opened"))
	local panel = Factory.make("Frame", { AnchorPoint = Vector2.new(.5, .5), BackgroundColor3 = theme.colors.surface, BorderSizePixel = 0, Position = UDim2.fromScale(.5, .5), Size = UDim2.fromOffset(560, 460), ZIndex = theme.zIndex.modal + 1 }, overlay)
	local panelCorner = Factory.corner(panel, theme.radius.lg)
	Factory.surface(panel, theme, "surface", { popup = true, border = false, glass = true })
	Factory.windowShadow(panel, theme)
	local panelStroke = popupStroke(panel, theme)
	local title = Factory.text(panel, tostring(options.Title or "What's new"), scaled(theme, theme.typography.title), theme.colors.text, { Position = UDim2.fromOffset(20, 16), Size = UDim2.new(1, -80, 0, 32), theme = theme, fontRole = "strong", typographyRole = "title", TextWrapped = true, ZIndex = theme.zIndex.modal + 2 })
	local close = Factory.button(panel, "×", theme, { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -16, 0, 12), Size = UDim2.fromOffset(36, 36), ZIndex = theme.zIndex.modal + 3 })
	local scroll = Factory.make("ScrollingFrame", { Active = true, BackgroundTransparency = 1, BorderSizePixel = 0, CanvasSize = UDim2.new(), Position = UDim2.fromOffset(20, 62), ScrollBarThickness = 6, Size = UDim2.new(1, -40, 1, -82), ZIndex = theme.zIndex.modal + 2 }, panel) :: ScrollingFrame
	local rowHeight = math.clamp(scaled(theme, 72), 56, 104)
	local pool = {}
	for index = 1, math.min(24, math.max(1, #items)) do
		local row = Factory.make("TextButton", { Active = true, AutoButtonColor = false, BackgroundTransparency = 1, BorderSizePixel = 0, Position = UDim2.fromOffset(0, 0), Selectable = true, Size = UDim2.new(1, -8, 0, rowHeight - 4), Text = "", ZIndex = theme.zIndex.modal + 3 }, scroll) :: TextButton
		row:SetAttribute("AccessibilityRole", "button")
		local heading = Factory.text(row, "", scaled(theme, theme.typography.body), theme.colors.text, { theme = theme, fontRole = "strong", typographyRole = "body", Position = UDim2.fromOffset(0, 0), Size = UDim2.new(1, 0, 0, math.floor(rowHeight * .34)), TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = theme.zIndex.modal + 4 })
		local copy = Factory.text(row, "", scaled(theme, theme.typography.caption), theme.colors.textMuted, { theme = theme, typographyRole = "caption", Position = UDim2.fromOffset(0, math.floor(rowHeight * .36)), Size = UDim2.new(1, 0, 0, math.floor(rowHeight * .6)), TextTruncate = Enum.TextTruncate.AtEnd, TextWrapped = true, TextYAlignment = Enum.TextYAlignment.Top, ZIndex = theme.zIndex.modal + 4 })
		local slot = { row = row, heading = heading, copy = copy, item = nil }
		maid:GiveTask(row.Activated:Connect(function() local item = slot.item; if item and type(item.Action) == "function" then item.Action(item) end end))
		pool[index] = slot
	end
	local function refresh()
		local first = math.max(1, math.floor(scroll.CanvasPosition.Y / rowHeight) + 1)
		for offset, slot in ipairs(pool) do
			local item, itemIndex = items[first + offset - 1], first + offset - 1
			slot.row.Visible, slot.item = item ~= nil, item
			if item then
				slot.row.Position = UDim2.fromOffset(0, (itemIndex - 1) * rowHeight)
				slot.heading.Text, slot.copy.Text = item.Title, item.Subtitle
				slot.row:SetAttribute("AccessibilityLabel", item.Title)
				slot.row:SetAttribute("ActionId", item.ActionId or "")
			end
		end
	end
	local function reflow()
		local work = context.Root.AbsoluteSize
		panel.Size = UDim2.fromOffset(math.min(560, math.max(0, work.X - 32)), math.min(460, math.max(0, work.Y - 32)))
		scroll.CanvasSize = UDim2.fromOffset(0, #items * rowHeight)
	end
	local function applyTheme()
		theme = self:_themeFor(options)
		rowHeight = math.clamp(scaled(theme, 72), 56, 104)
		overlay.BackgroundColor3, overlay.ZIndex = theme.colors.overlay, theme.zIndex.modal
		panel.BackgroundColor3, panel.ZIndex = popupBackground(theme), theme.zIndex.modal + 1
		panelCorner.CornerRadius = UDim.new(0, theme.radius.lg)
		applyPopupStroke(panelStroke, theme)
		title.TextColor3, title.ZIndex = theme.colors.text, theme.zIndex.modal + 2
		Factory.applyTypography(title, theme, "title")
		close.ZIndex = theme.zIndex.modal + 3
		Factory.setButtonState(close, "default", theme)
		scroll.ZIndex = theme.zIndex.modal + 2
		for _, itemSlot in ipairs(pool) do
			itemSlot.row.Size = UDim2.new(1, -8, 0, rowHeight - 4)
			itemSlot.row.ZIndex = theme.zIndex.modal + 3
			itemSlot.heading.TextColor3, itemSlot.copy.TextColor3 = theme.colors.text, theme.colors.textMuted
			itemSlot.heading.ZIndex, itemSlot.copy.ZIndex = theme.zIndex.modal + 4, theme.zIndex.modal + 4
			Factory.applyTypography(itemSlot.heading, theme, "body")
			Factory.applyTypography(itemSlot.copy, theme, "caption")
		end
		reflow()
		refresh()
	end
	local handle = { Root = overlay, _closed = false, _owner = options.Owner or options.owner }
	function handle:IsOpen() return not self._closed end
	function handle:Close(reason: any?)
		if self._closed then return end
		self._closed = true
		context.InputRouter:PopModal(id); context.FocusManager:PopModal(id)
		self._presentation:_releaseOwned(self._owner, self); self._presentation._changelogs[self] = nil
		self._presentation:_removeSurface(self)
		if type(options.OnClose) == "function" then pcall(options.OnClose, reason) end
		maid:Destroy(); overlay:Destroy()
	end
	handle.Destroy, handle._presentation = handle.Close, self
	maid:GiveTask(close.Activated:Connect(function() handle:Close("dismiss") end))
	maid:GiveTask(scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(refresh))
	maid:GiveTask(context.Root:GetPropertyChangedSignal("AbsoluteSize"):Connect(reflow))
	focus(context, maid, id .. ".close", close, 1); context.InputRouter:PushModal(id, handle); context.FocusManager:PushModal(id, close)
	self._surfaces[handle] = applyTheme
	if options.ThemeChanged and type(options.ThemeChanged.Connect) == "function" then
		maid:GiveTask(options.ThemeChanged:Connect(applyTheme))
	end
	self._changelogs[handle] = true; self:_trackOwned(handle._owner, handle); applyTheme()
	return handle
end


function Presentation:Notify(options: any)
	if type(options) == "string" then
		options = { Text = options }
	end
	assert(type(options) == "table", "Notify requires options")
	local presenceConfig = presenceOptions(self._context.Motion, options, "rayfieldToggle", "rayfieldExit")
	local level = tostring(options.Type or options.Level or "info")
	assert(LEVELS[level], "Unknown notification type")
	local id = if options.Id ~= nil then "notification:" .. tostring(options.Id) else nil
	if id then
		local existing = self._overlays[id]
		if existing and existing.handle:IsOpen() then
			existing.handle:Update(options)
			return existing.handle
		end
	end
	while #self._notificationOrder >= 6 do
		local victim = self._notificationOrder[1]
		for _, candidate in ipairs(self._notificationOrder) do
			if not candidate._persistent then
				victim = candidate
				break
			end
		end
		victim:Close()
	end
	self._notificationSequence += 1
	id = id or "notification:anonymous:" .. tostring(self._notificationSequence)
	local context, theme, maid = self._context, self:_theme(), Maid.new()
	local reducedMotion = context.ReducedMotion == true or (context.Motion and context.Motion.ReducedMotion == true)
	local slot = Factory.make("Frame", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		Size = UDim2.fromOffset(0, 0),
		ZIndex = theme.zIndex.toast,
	}, context.Toast) :: Frame
	slot.Name = "PotassiumNotificationSlot"
	slot:SetAttribute("RayfieldMotionSlot", "grow:0.6:Exponential:Out")
	local frame = Factory.make("CanvasGroup", {
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = theme.colors.surfaceRaised,
		BackgroundTransparency = 1,
		GroupTransparency = 0,
		Size = UDim2.new(1, 0, 0, 0),
		ZIndex = theme.zIndex.toast,
	}, slot) :: CanvasGroup
	frame.Name = "PotassiumNotificationBody"
	frame:SetAttribute("RayfieldMotionEntry", "swipe:360:0.6:Exponential:Out")
	frame:SetAttribute("RayfieldMotionExit", "width:-90:slot-collapse:0.9:Exponential:Out")
	Factory.corner(frame, theme.radius.md)
	Factory.surface(frame, theme, "raised", { popup = true, border = false, glass = true })
	Factory.windowShadow(frame, theme)
	local stroke = popupStroke(frame, theme)
	local surfaceFill = Factory.make("Frame", {
		Name = "PotassiumRayfieldFill",
		Active = false,
		BackgroundColor3 = popupBackground(theme),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1),
		ZIndex = theme.zIndex.toast,
	}, frame) :: Frame
	Factory.corner(surfaceFill, theme.radius.md)
	Factory.padding(frame, theme.spacing.md)
	Factory.list(frame, theme.spacing.xs)
	local heading = Factory.text(frame, "", scaled(theme, theme.typography.caption), theme.colors.text, {
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Size = UDim2.new(1, -48, 0, 0),
		theme = theme,
		fontRole = "strong",
		typographyRole = "caption",
		TextWrapped = true,
		TextYAlignment = Enum.TextYAlignment.Top,
		ZIndex = theme.zIndex.toast + 1,
	})
	local bodyScroll = Factory.make("ScrollingFrame", {
		Active = true,
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		LayoutOrder = 2,
		ScrollBarThickness = 4,
		Size = UDim2.new(1, -8, 0, 44),
		ZIndex = theme.zIndex.toast + 1,
	}, frame) :: ScrollingFrame
	local body = Factory.text(bodyScroll, "", scaled(theme, theme.typography.body), theme.colors.textMuted, {
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, -8, 0, 0),
		TextWrapped = true,
		TextYAlignment = Enum.TextYAlignment.Top,
		ZIndex = theme.zIndex.toast + 1,
	})
	heading:SetAttribute("RayfieldMotionContent", "icon:0.05:0.3:Exponential:Out")
	body:SetAttribute("RayfieldMotionContent", "description:0.10:0.3:Exponential:Out")
	local function fitBody()
		local maximum = math.max(80, math.min(220, context.Root.AbsoluteSize.Y * 0.35))
		local desired = math.max(24, math.min(maximum, body.TextBounds.Y + 8))
		bodyScroll.Size = UDim2.new(1, -8, 0, desired)
		bodyScroll.ScrollingEnabled = body.TextBounds.Y + 8 > desired
	end
	maid:GiveTask(body:GetPropertyChangedSignal("TextBounds"):Connect(fitBody))
	maid:GiveTask(context.Root:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitBody))
	task.defer(fitBody)
	local close = Factory.button(frame, "×", theme, {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 0, 0, 0),
		Size = UDim2.fromOffset(44, 44),
		TextSize = scaled(theme, theme.typography.title),
		ZIndex = theme.zIndex.toast + 2,
	})
	local handle = {
		Root = frame,
		_closed = false,
		_paused = false,
		_persistent = false,
		_remaining = 4,
		_deadline = 0,
		_maid = maid,
		_owner = options.Owner or options.owner,
		_generation = 0,
		_slot = slot,
	}
	local function animateRayfield(target: Instance, properties: { [string]: any }, duration: number)
		if reducedMotion then
			for property, value in pairs(properties) do
				(target :: any)[property] = value
			end
			return nil
		end
		return context.Motion:Animate(target, properties, {
			Duration = duration,
			EasingStyle = Enum.EasingStyle.Exponential,
			EasingDirection = Enum.EasingDirection.Out,
		})
	end
	local progress: Frame? = nil
	local progressFill: Frame? = nil
	local function cancelTimer()
		maid:Remove("timeout")
	end
	local function schedule()
		cancelTimer()
		if handle._closed or handle._paused or handle._persistent then
			return
		end
		handle._deadline = os.clock() + handle._remaining
		maid:Set(
			"timeout",
			task.delay(handle._remaining, function()
				if not handle._closed and not handle._paused and not handle._persistent then
					handle:Close()
				end
			end)
		)
	end
	local function localized(key: any, params: any, fallback: any): any
		local service = context.Localization
		if key ~= nil and service and type(service.Translate) == "function" then
			local values = type(params) == "table" and table.clone(params) or {}
			if values.Default == nil then values.Default = fallback end
			return service:Translate(key, values, values.count)
		end
		return fallback
	end
	local function apply(patch: any, resetDuration: boolean)
		if not resetDuration and not handle._paused and not handle._persistent and handle._deadline > 0 then
			handle._remaining = math.max(0.05, handle._deadline - os.clock())
		end
		local nextLevel = tostring(patch.Type or patch.Level or level)
		assert(LEVELS[nextLevel], "Unknown notification type")
		level = nextLevel
		local title = patch.Title
		if title == nil then
			title = handle._title
		end
		handle._title = title
		if patch.TitleKey ~= nil then handle._titleKey, handle._titleParams = patch.TitleKey, patch.Params or patch.TitleParams end
		if patch.TextKey ~= nil then handle._textKey, handle._textParams = patch.TextKey, patch.Params or patch.TextParams end
		title = localized(handle._titleKey, handle._titleParams, title)
		handle._title = title
		if patch.Text ~= nil or patch.Content ~= nil then
			handle._text = tostring(patch.Text or patch.Content)
		end
		handle._text = tostring(localized(handle._textKey, handle._textParams, handle._text or ""))
		heading.Text = LEVELS[level].icon
			.. "  "
			.. LEVELS[level].label
			.. (if title ~= nil and tostring(title) ~= "" then "  ·  " .. tostring(title) else "")
		body.Text = handle._text or ""
		local direction = if context.Localization then context.Localization:GetDirection() else "LTR"
		heading.TextXAlignment = if direction == "RTL" then Enum.TextXAlignment.Right else Enum.TextXAlignment.Left
		body.TextXAlignment = if direction == "RTL" then Enum.TextXAlignment.Right else Enum.TextXAlignment.Left
		frame:SetAttribute("LayoutDirection", direction)
		if patch.Persistent ~= nil then
			handle._persistent = patch.Persistent == true
		end
		if resetDuration and patch.Duration ~= nil then
			handle._remaining = math.max(0.5, tonumber(patch.Duration) or 4)
		end
		if patch.Progress ~= nil or patch._clearProgress then
			local value = if patch._clearProgress then nil else math.clamp(tonumber(patch.Progress) or 0, 0, 1)
			if value ~= nil and not progress then
				progress = Factory.make("Frame", {
					BackgroundColor3 = theme.colors.border,
					BorderSizePixel = 0,
					LayoutOrder = 3,
					Size = UDim2.new(1, -8, 0, 3),
					ZIndex = theme.zIndex.toast + 1,
				}, frame)
				progressFill = Factory.make("Frame", {
					BackgroundColor3 = theme.colors.text,
					BorderSizePixel = 0,
					Size = UDim2.new(0, 0, 1, 0),
					ZIndex = theme.zIndex.toast + 2,
				}, progress)
			end
			if progress and progressFill then
				progress.Visible = value ~= nil
				if value ~= nil then
					progressFill.Size = UDim2.new(value, 0, 1, 0)
				end
			end
		end
		schedule()
	end
	function handle:IsOpen()
		return not self._closed
	end
	function handle:Update(patch: any)
		assert(type(patch) == "table", "Notification Update requires a table")
		if not self._closed then
			apply(patch, patch.Duration ~= nil)
		end
		return self
	end
	function handle:SetProgress(value: number?)
		return self:Update(if value == nil then { _clearProgress = true } else { Progress = value })
	end
	function handle:Pause()
		if not self._closed and not self._paused then
			self._paused = true
			if not self._persistent then
				self._remaining = math.max(0, self._deadline - os.clock())
			end
			cancelTimer()
		end
		return self
	end
	function handle:Resume()
		if not self._closed and self._paused then
			self._paused = false
			schedule()
		end
		return self
	end
	function handle:Close()
		if self._closed then
			return
		end
		self._closed = true
		self._generation += 1
		cancelTimer()
		maid:Remove("notification-entry")
		maid:Remove("notification-heading-entry")
		maid:Remove("notification-body-entry")
		self._presentation:_unmountOverlay(self._id, self)
		for index, candidate in ipairs(self._presentation._notificationOrder) do
			if candidate == self then
				table.remove(self._presentation._notificationOrder, index)
				break
			end
		end
		self._presentation._notifications[self] = nil
		self._presentation:_releaseOwned(self._owner, self)
		if type(self._onClose) == "function" then
			pcall(self._onClose)
		end
		self._presentation:_disableInteraction(frame)
		local function finalize()
			if self._finalized then return end
			self._finalized = true
			self._presentation._exiting[frame] = nil
			maid:Destroy()
			slot:Destroy()
		end
		self._presentation._exiting[frame] = { finish = finalize }
		if not presenceConfig or self._presentation._destroyed then
			finalize()
			return
		end
		local exitSize = frame.AbsoluteSize
		frame.AutomaticSize = Enum.AutomaticSize.None
		frame.Size = UDim2.fromOffset(exitSize.X, exitSize.Y)
		local slotMotion = animateRayfield(slot, { Size = UDim2.fromOffset(0, 0) }, 0.9)
		animateRayfield(frame, {
			GroupTransparency = 1,
			Size = UDim2.fromOffset(math.max(0, exitSize.X - 90), exitSize.Y),
		}, 0.9)
		if slotMotion then
			slotMotion:OnCompleted(function()
				if self._closed then finalize() end
			end)
		else
			finalize()
		end
	end
	handle.Destroy = handle.Close
	handle._presentation, handle._id, handle._onClose = self, id, options.OnClose
	maid:GiveTask(close.Activated:Connect(function()
		handle:Close()
	end))
	if context.LocaleChanged and type(context.LocaleChanged.Connect) == "function" then
		maid:GiveTask(context.LocaleChanged:Connect(function()
			if not handle._closed and (handle._titleKey ~= nil or handle._textKey ~= nil) then
				handle:Update({ TitleKey = handle._titleKey, TextKey = handle._textKey, TitleParams = handle._titleParams, TextParams = handle._textParams })
			end
		end))
	end
	maid:GiveTask(frame.MouseEnter:Connect(function()
		handle:Pause()
	end))
	maid:GiveTask(frame.MouseLeave:Connect(function()
		handle:Resume()
	end))
	maid:GiveTask(frame.SelectionGained:Connect(function()
		handle:Pause()
	end))
	maid:GiveTask(frame.SelectionLost:Connect(function()
		handle:Resume()
	end))
	apply({
		Title = options.Title,
		Text = options.Text or options.Content or options.Title or "",
		TitleKey = options.TitleKey,
		TextKey = options.TextKey,
		TitleParams = options.TitleParams or options.Params,
		TextParams = options.TextParams or options.Params,
		Persistent = options.Persistent,
		Progress = options.Progress,
		Duration = options.Duration,
	}, options.Duration ~= nil)
	if type(context.Haptics) == "table" and type(context.Haptics.Pulse) == "function" then
		context.Haptics:Pulse(if level == "warning" then "warning" else "notification")
	end
	self._notifications[handle] = true
	table.insert(self._notificationOrder, handle)
	self:_trackOwned(handle._owner, handle)
	self:_mountOverlay(id, "notification", handle, function()
		local nextTheme = self:_theme()
		surfaceFill.BackgroundColor3 = popupBackground(nextTheme)
		applyPopupStroke(stroke, nextTheme)
		heading.TextColor3, body.TextColor3 = nextTheme.colors.text, nextTheme.colors.textMuted
		Factory.applyTypography(heading, nextTheme, "caption")
		Factory.applyTypography(body, nextTheme, "body")
		frame.ZIndex = nextTheme.zIndex.toast
		if progress then
			progress.BackgroundColor3 = nextTheme.colors.border
		end
		if progressFill then
			progressFill.BackgroundColor3 = nextTheme.colors.text
		end
		Factory.setButtonState(close, "default", nextTheme)
	end)
	local entryGeneration = handle._generation
	local function enter()
		if handle._closed or handle._generation ~= entryGeneration then return end
		frame.Size = UDim2.fromOffset(math.max(0, context.Toast.AbsoluteSize.X), 0)
		local targetSize = frame.AbsoluteSize
		slot.Size = UDim2.fromOffset(0, 0)
		frame.Position = UDim2.fromOffset(360, 0)
		surfaceFill.BackgroundTransparency = 1
		stroke.Transparency = 1
		heading.TextTransparency, body.TextTransparency = 1, 1
		if not presenceConfig or reducedMotion then
			slot.Size = UDim2.fromOffset(targetSize.X, targetSize.Y)
			frame.Position = UDim2.fromOffset(0, 0)
			surfaceFill.BackgroundTransparency = 0
			stroke.Transparency = 0.78
			heading.TextTransparency, body.TextTransparency = 0, 0
			return
		end
		animateRayfield(slot, { Size = UDim2.fromOffset(targetSize.X, targetSize.Y) }, 0.6)
		animateRayfield(frame, { Position = UDim2.fromOffset(0, 0) }, 0.6)
		animateRayfield(surfaceFill, { BackgroundTransparency = 0 }, 0.4)
		animateRayfield(stroke, { Transparency = 0.78 }, 0.4)
		maid:Set("notification-heading-entry", task.delay(0.05, function()
			if not handle._closed and handle._generation == entryGeneration then
				animateRayfield(heading, { TextTransparency = 0 }, 0.3)
			end
		end))
		maid:Set("notification-body-entry", task.delay(0.10, function()
			if not handle._closed and handle._generation == entryGeneration then
				animateRayfield(body, { TextTransparency = 0 }, 0.3)
			end
		end))
	end
	if not presenceConfig or reducedMotion then
		enter()
	else
		maid:Set("notification-entry", task.defer(enter))
	end
	return handle
end

function Presentation:Dialog(options: any)
	assert(type(options) == "table", "Dialog requires options")
	local presenceConfig = presenceOptions(self._context.Motion, options)
	options.Title = options.Title or options.title
	options.Text = options.Text or options.text
	options.ConfirmText = options.ConfirmText or options.confirm
	options.CancelText = options.CancelText or options.cancel
	options.Id = options.Id or options.id
	local context, theme, maid = self._context, self:_themeFor(options), Maid.new()
	local baseId = self._context:_id(options.Id or "dialog")
	local id, suffix = baseId, 2
	while self._dialogIds[id] do
		id = baseId .. "-" .. tostring(suffix)
		suffix += 1
	end
	self._dialogIds[id] = true
	local overlay = Factory.make("TextButton", {
		Active = true,
		AutoButtonColor = false,
		BackgroundColor3 = theme.colors.overlay,
		BackgroundTransparency = 0.38,
		BorderSizePixel = 0,
		Modal = true,
		Selectable = true,
		Size = UDim2.fromScale(1, 1),
		Text = "",
		ZIndex = theme.zIndex.modal,
	}, context.Modal) :: TextButton
	local panel = Factory.make("CanvasGroup", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		BackgroundColor3 = theme.colors.surface,
		BorderSizePixel = 0,
		GroupTransparency = if presenceConfig then 1 else 0,
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(480, 320),
		ZIndex = theme.zIndex.modal + 1,
	}, overlay) :: CanvasGroup
	Factory.corner(panel, theme.radius.lg)
	Factory.surface(panel, theme, "surface", { popup = true, border = false, glass = true })
	Factory.windowShadow(panel, theme)
	local stroke = popupStroke(panel, theme)
	local title = Factory.text(
		panel,
		tostring(options.Title or "Confirm"),
		scaled(theme, theme.typography.title),
		theme.colors.text,
		{
			Position = UDim2.fromOffset(20, 16),
			Size = UDim2.new(1, -40, 0, 28),
			theme = theme,
			fontRole = "strong",
			typographyRole = "title",
			TextTruncate = Enum.TextTruncate.None,
			TextWrapped = true,
			TextYAlignment = Enum.TextYAlignment.Top,
			ZIndex = theme.zIndex.modal + 2,
		}
	)
	local scroll = Factory.make("ScrollingFrame", {
		Active = true,
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		Position = UDim2.fromOffset(20, 54),
		ScrollBarImageColor3 = theme.colors.borderStrong,
		ScrollBarThickness = 6,
		Size = UDim2.new(1, -40, 1, -126),
		ZIndex = theme.zIndex.modal + 2,
	}, panel) :: ScrollingFrame
	local copy = Factory.text(
		scroll,
		tostring(options.Text or options.Content or ""),
		scaled(theme, theme.typography.body),
		theme.colors.textMuted,
		{
			AutomaticSize = Enum.AutomaticSize.Y,
			Size = UDim2.new(1, -8, 0, 0),
			TextTruncate = Enum.TextTruncate.None,
			TextWrapped = true,
			TextYAlignment = Enum.TextYAlignment.Top,
			ZIndex = theme.zIndex.modal + 3,
			theme = theme,
			typographyRole = "body",
		}
	)
	local cancel = Factory.button(panel, tostring(options.CancelText or "Cancel"), theme, {
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 20, 1, -16),
		Size = UDim2.new(0.5, -24, 0, 44),
		ZIndex = theme.zIndex.modal + 3,
	})
	local accept = Factory.button(panel, tostring(options.ConfirmText or "Confirm"), theme, {
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.new(1, -20, 1, -16),
		Size = UDim2.new(0.5, -24, 0, 44),
		ZIndex = theme.zIndex.modal + 3,
	})
	local handle = { Root = overlay, _closed = false, _maid = maid, _owner = options.Owner or options.owner }
	handle._presentation = self
	local function fit()
		local viewport = context.Root.AbsoluteSize
		panel.Size = UDim2.fromOffset(
			math.max(280, math.min(520, viewport.X - 32)),
			math.max(220, math.min(560, viewport.Y - 32))
		)
	end
	function handle:Close(result: any, suppressCallback: boolean?)
		if self._closed then
			return
		end
		self._closed = true
		self._presentation:_releaseOwned(self._owner, self)
		context.InputRouter:PopModal(id)
		context.FocusManager:PopModal(id)
		self._presentation:_exitPresence(presenceConfig, overlay, maid, function()
			overlay:Destroy()
		end, self._presence, panel)
		if not suppressCallback then
			if type(options.Callback) == "function" then
				options.Callback(result)
			end
			if result == true and type(options.onConfirm) == "function" then
				options.onConfirm()
			end
			if result ~= true and type(options.onCancel) == "function" then
				options.onCancel()
			end
		end
	end
	function handle:Destroy()
		self:Close(false, true)
	end
	handle.OnBack = function()
		handle:Close(false)
	end
	handle.OnPointerBegan = function(_: any, input: InputObject)
		if not contains(input.Position, panel) then
			handle:Close(false)
		end
		return true
	end
	maid:GiveTask(cancel.Activated:Connect(function()
		handle:Close(false)
	end))
	maid:GiveTask(accept.Activated:Connect(function()
		handle:Close(true)
	end))
	maid:GiveTask(context.Root:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit))
	focus(context, maid, id .. ".cancel", cancel, 1)
	focus(context, maid, id .. ".accept", accept, 2)
	fit()
	context.InputRouter:PushModal(id, handle)
	context.FocusManager:PushModal(id, accept)
	self._dialogs[handle] = true
	self._surfaces[handle] = function()
		local nextTheme = self:_themeFor(options)
		overlay.BackgroundColor3 = nextTheme.colors.overlay
		panel.BackgroundColor3 = popupBackground(nextTheme)
		applyPopupStroke(stroke, nextTheme)
		title.TextColor3 = nextTheme.colors.text
		copy.TextColor3 = nextTheme.colors.textMuted
		scroll.ScrollBarImageColor3 = nextTheme.colors.borderStrong
		Factory.applyTypography(title, nextTheme, "title")
		Factory.applyTypography(copy, nextTheme, "body")
		overlay.ZIndex, panel.ZIndex = nextTheme.zIndex.modal, nextTheme.zIndex.modal + 1
		local corner = panel:FindFirstChildOfClass("UICorner")
		if corner then
			corner.CornerRadius = UDim.new(0, nextTheme.radius.lg)
		end
		Factory.setButtonState(cancel, "default", nextTheme)
		Factory.setButtonState(accept, "default", nextTheme)
	end
	if options.ThemeChanged and type(options.ThemeChanged.Connect) == "function" then
		maid:GiveTask(options.ThemeChanged:Connect(function()
			local apply = self._surfaces[handle]
			if apply then
				apply()
			end
		end))
	end
	if presenceConfig then
		handle._presence = self:_enterPresence(presenceConfig, panel, 0)
	end
	self:_trackOwned(handle._owner, handle)
	maid:GiveTask(function()
		self:_removeSurface(handle)
		self._dialogIds[id] = nil
		self._dialogs[handle] = nil
	end)
	return handle
end
local function validateProgressOverlayOptions(options: any)
	assert(type(options) == "table", "ShowProgressOverlay requires options")
	assert(options.Id == nil or (type(options.Id) == "string" and options.Id ~= ""), "ShowProgressOverlay Id must be a non-empty string")
	assert(options.Title == nil or type(options.Title) == "string", "ShowProgressOverlay Title must be a string")
	assert(options.Text == nil or type(options.Text) == "string", "ShowProgressOverlay Text must be a string")
	assert(options.Dismissible == nil or type(options.Dismissible) == "boolean", "ShowProgressOverlay Dismissible must be a boolean")
	if options.Progress ~= nil then
		assert(
			type(options.Progress) == "number"
				and options.Progress == options.Progress
				and options.Progress ~= math.huge
				and options.Progress ~= -math.huge
				and options.Progress >= 0
				and options.Progress <= 1,
			"ShowProgressOverlay Progress must be a finite number from 0 to 1"
		)
	end
end

function Presentation:ShowProgressOverlay(options: any)
	validateProgressOverlayOptions(options)
	local presenceConfig = presenceOptions(self._context.Motion, options)
	local context = self._context
	local overlayId = context:_id(options.Id or "progress")
	local registryId = "progress:" .. overlayId
	local modalId = registryId
	local existing = self._progressOverlays[overlayId]
	if existing and existing:IsOpen() then
		existing:Update(options)
		return existing
	end

	local theme, maid = self:_themeFor(options), Maid.new()
	local overlay = Factory.make("TextButton", {
		Active = true,
		AutoButtonColor = false,
		BackgroundColor3 = theme.colors.overlay,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Modal = true,
		Selectable = true,
		Size = UDim2.fromScale(1, 1),
		Text = "",
		ZIndex = theme.zIndex.modal,
	}, context.Modal) :: TextButton
	overlay.Name = "PotassiumProgressOverlay"
	local panel = Factory.make("CanvasGroup", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		BackgroundColor3 = theme.colors.surface,
		BorderSizePixel = 0,
		GroupTransparency = if presenceConfig then 1 else 0,
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(420, 192),
		ZIndex = theme.zIndex.modal + 1,
	}, overlay) :: CanvasGroup
	Factory.corner(panel, theme.radius.lg)
	Factory.surface(panel, theme, "surface", { popup = true, border = false, glass = true })
	Factory.windowShadow(panel, theme)
	local stroke = popupStroke(panel, theme)
	local title = Factory.text(panel, "", scaled(theme, theme.typography.title), theme.colors.text, {
		Position = UDim2.fromOffset(20, 16),
		Size = UDim2.new(1, -40, 0, 28),
		theme = theme,
		fontRole = "strong",
		typographyRole = "title",
		TextTruncate = Enum.TextTruncate.AtEnd,
		TextYAlignment = Enum.TextYAlignment.Top,
		ZIndex = theme.zIndex.modal + 2,
	})
	local copy = Factory.text(panel, "", scaled(theme, theme.typography.body), theme.colors.textMuted, {
		Position = UDim2.fromOffset(20, 56),
		Size = UDim2.new(1, -40, 0, 48),
		TextTruncate = Enum.TextTruncate.AtEnd,
		TextWrapped = true,
		TextYAlignment = Enum.TextYAlignment.Top,
		ZIndex = theme.zIndex.modal + 2,
		theme = theme,
		typographyRole = "body",
	})
	local track = Factory.make("Frame", {
		BackgroundColor3 = theme.colors.border,
		BorderSizePixel = 0,
		Position = UDim2.new(0, 20, 1, -40),
		Size = UDim2.new(1, -40, 0, 6),
		ZIndex = theme.zIndex.modal + 2,
	}, panel) :: Frame
	Factory.corner(track, 3)
	local fill = Factory.make("Frame", {
		BackgroundColor3 = theme.colors.text,
		BorderSizePixel = 0,
		Size = UDim2.new(),
		ZIndex = theme.zIndex.modal + 3,
	}, track) :: Frame
	Factory.corner(fill, 3)
	local close = Factory.button(panel, "×", theme, {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -12, 0, 10),
		Size = UDim2.fromOffset(36, 36),
		TextSize = scaled(theme, theme.typography.title),
		ZIndex = theme.zIndex.modal + 3,
	})
	local handle = {
		Root = overlay,
		_closed = false,
		_maid = maid,
		_state = {
			Id = overlayId,
			Title = options.Title,
			Text = options.Text,
			Progress = options.Progress,
			Dismissible = options.Dismissible == true,
		},
	}
	handle._presentation = self
	local surfaceFocusId = modalId .. ":surface"
	local dismissFocusId = modalId .. ":dismiss"
	local surfaceRegistered, dismissRegistered = false, false
	local inputPushed, focusPushed = false, false
	local function unregisterFocus()
		if dismissRegistered then
			dismissRegistered = false
			context.FocusManager:Unregister(dismissFocusId)
		end
		if surfaceRegistered then
			surfaceRegistered = false
			context.FocusManager:Unregister(surfaceFocusId)
		end
	end
	local function popModals()
		if focusPushed then
			focusPushed = false
			context.FocusManager:PopModal(modalId)
		end
		if inputPushed then
			inputPushed = false
			context.InputRouter:PopModal(modalId)
		end
	end
	local function layout()
		local viewport = context.Root.AbsoluteSize
		local panelWidth = math.max(1, math.min(scaled(theme, 420), viewport.X - scaled(theme, 24)))
		local panelHeightLimit = math.max(1, viewport.Y - scaled(theme, 24))
		local inset = scaled(theme, 20)
		local titleHeight = math.max(scaled(theme, 28), title.TextBounds.Y)
		local closeSize = scaled(theme, 36)
		local titleReserve = if handle._state.Dismissible then closeSize + scaled(theme, 8) else 0
		local titleWidth = panelWidth - inset * 2 - titleReserve
		title.Position = UDim2.fromOffset(inset, scaled(theme, 16))
		title.Size = UDim2.fromOffset(math.max(1, titleWidth), titleHeight)
		close.Position = UDim2.new(1, -scaled(theme, 12), 0, scaled(theme, 10))
		close.Size = UDim2.fromOffset(closeSize, closeSize)
		local spacing = scaled(theme, 12)
		local copyY = scaled(theme, 16) + titleHeight + spacing
		local trackHeight = scaled(theme, 6)
		local fixedHeight = copyY + spacing + trackHeight + inset
		local copyHeight = math.max(scaled(theme, 24), math.min(copy.TextBounds.Y, math.max(1, panelHeightLimit - fixedHeight)))
		local panelHeight = math.max(1, math.min(panelHeightLimit, fixedHeight + copyHeight))
		panel.Size = UDim2.fromOffset(panelWidth, panelHeight)
		copy.Position = UDim2.fromOffset(inset, copyY)
		copy.Size = UDim2.fromOffset(math.max(1, panelWidth - inset * 2), copyHeight)
		track.Position = UDim2.fromOffset(inset, panelHeight - inset - trackHeight)
		track.Size = UDim2.fromOffset(math.max(1, panelWidth - inset * 2), trackHeight)
	end
	local function apply(patch: any)
		if patch.Title ~= nil then handle._state.Title = patch.Title end
		if patch.Text ~= nil then handle._state.Text = patch.Text end
		if patch.Progress ~= nil then handle._state.Progress = patch.Progress end
		local wasDismissible = handle._state.Dismissible
		if patch.Dismissible ~= nil then handle._state.Dismissible = patch.Dismissible end
		local becameDismissible = handle._state.Dismissible and not wasDismissible
		local becameNonDismissible = wasDismissible and not handle._state.Dismissible
		title.Text = handle._state.Title or "Progress"
		copy.Text = handle._state.Text or ""
		fill.Size = UDim2.fromScale(handle._state.Progress or 0, 1)
		close.Visible = handle._state.Dismissible
		layout()
		if focusPushed then
			if becameDismissible then
				context.FocusManager:SetFocused(close, "progressDismissible")
			elseif becameNonDismissible then
				context.FocusManager:SetFocused(overlay, "progressNonDismissible")
			end
		end
	end
	function handle:Update(patch: any)
		assert(type(patch) == "table", "ShowProgressOverlay Update requires options")
		validateProgressOverlayOptions({
			Id = patch.Id,
			Title = patch.Title,
			Text = patch.Text,
			Progress = patch.Progress,
			Dismissible = patch.Dismissible,
		})
		if patch.Id ~= nil then
			assert(context:_id(patch.Id) == self._state.Id, "ShowProgressOverlay Id cannot change")
		end
		if self._closed then return self end
		apply(patch)
		return self
	end
	function handle:SetTitle(value: string)
		return self:Update({ Title = value })
	end
	function handle:SetText(value: string)
		return self:Update({ Text = value })
	end
	function handle:SetProgress(value: number)
		return self:Update({ Progress = value })
	end
	function handle:GetState()
		return table.clone(self._state)
	end
	function handle:IsOpen()
		return not self._closed
	end
	function handle:Close()
		if self._closed then
			return self
		end
		self._closed = true
		self._presentation:_exitPresence(presenceConfig, overlay, maid, function()
			overlay:Destroy()
		end, self._presence, panel)
		return self
	end
	handle.Destroy = handle.Close
	handle.Unload = handle.Close
	handle.OnBack = function()
		if handle._state.Dismissible then
			handle:Close()
		end
		return true
	end
	handle.OnPointerBegan = function(_: any, input: InputObject)
		if handle._state.Dismissible and not contains(input.Position, panel) then
			handle:Close()
		end
		return true
	end
	maid:GiveTask(close.Activated:Connect(function()
		if handle._state.Dismissible then
			handle:Close()
		end
	end))
	maid:GiveTask(context.Root:GetPropertyChangedSignal("AbsoluteSize"):Connect(layout))
	maid:GiveTask(title:GetPropertyChangedSignal("TextBounds"):Connect(layout))
	maid:GiveTask(copy:GetPropertyChangedSignal("TextBounds"):Connect(layout))
	maid:GiveTask(function()
		popModals()
		unregisterFocus()
		self._progressOverlays[handle._state.Id] = nil
		self:_unmountOverlay(registryId, handle)
	end)
	self._progressOverlays[overlayId] = handle
	self:_mountOverlay(registryId, "progress", handle, function()
		theme = self:_themeFor(options)
		overlay.BackgroundColor3 = theme.colors.overlay
		panel.BackgroundColor3 = popupBackground(theme)
		applyPopupStroke(stroke, theme)
		title.TextColor3, copy.TextColor3 = theme.colors.text, theme.colors.textMuted
		track.BackgroundColor3, fill.BackgroundColor3 = theme.colors.border, theme.colors.text
		Factory.applyTypography(title, theme, "title")
		Factory.applyTypography(copy, theme, "body")
		Factory.applyTypography(close, theme, "title")
		close.ZIndex = theme.zIndex.modal + 3
		local corner = panel:FindFirstChildOfClass("UICorner")
		if corner then corner.CornerRadius = UDim.new(0, theme.radius.lg) end
		Factory.setButtonState(close, "default", theme)
		layout()
	end)
	apply(options)
	local opened, openError = pcall(function()
		context.FocusManager:Register(surfaceFocusId, overlay, { order = 1, group = modalId })
		surfaceRegistered = true
		context.FocusManager:Register(dismissFocusId, close, { order = 2, group = modalId })
		dismissRegistered = true
		context.InputRouter:PushModal(modalId, handle)
		inputPushed = true
		context.FocusManager:PushModal(modalId, if handle._state.Dismissible then close else overlay)
		focusPushed = true
	end)
	if not opened then
		maid:Destroy()
		overlay:Destroy()
		error(openError, 0)
	end
	task.defer(function()
		if not handle._closed then
			layout()
		end
	end)
	if presenceConfig then
		handle._presence = self:_enterPresence(presenceConfig, panel, 0)
	else
		local motion = self:_animate(overlay, { BackgroundTransparency = 0.36 })
		if motion then maid:GiveTask(motion) end
	end
	return handle
end

function Presentation:ConfirmRisk(options: any)
	assert(type(options) == "table", "ConfirmRisk requires options")
	options.Id = options.Id or "risk"
	options.Title = options.Title or "Confirm action"
	options.ConfirmText = options.ConfirmText or "Proceed"
	return self:Dialog(options)
end

function Presentation:CreateBox(options: any)
	assert(type(options) == "table", "CreateBox requires options")
	options.Title = options.Title or options.title
	options.Text = options.Text or options.text
	options.Stat = options.Stat or options.stat
	options.Progress = if options.Progress ~= nil then options.Progress else options.progress
	options.Position = options.Position or options.position
	if typeof(options.Position) == "Vector2" then
		options.Position = UDim2.fromOffset(options.Position.X, options.Position.Y)
	end
	if options.Size == nil and type(options.width) == "number" then
		options.Size = UDim2.fromOffset(options.width, tonumber(options.height) or 86)
	end
	local context, theme, maid = self._context, self:_theme(), Maid.new()
	local position = options.Position
	if position == nil then
		local nextY = 16
		for box in pairs(self._boxes) do
			if box.Root and box.Root.Parent then
				nextY = math.max(nextY, box.Root.AbsolutePosition.Y + box.Root.AbsoluteSize.Y + 12)
			end
		end
		position = UDim2.fromOffset(16, nextY)
	end

	local explicitSize = options.Size ~= nil
	local frame = Factory.make("Frame", {
		BackgroundColor3 = theme.colors.surfaceRaised,
		BorderSizePixel = 0,
		Position = position,
		Size = options.Size or UDim2.fromOffset(280, 86),
		ZIndex = theme.zIndex.sticky,
	}, context.Root) :: Frame
	Factory.corner(frame, theme.radius.md)
	Factory.surface(frame, theme, "raised", { popup = true, border = false, glass = true })
	Factory.windowShadow(frame, theme)
	local stroke = popupStroke(frame, theme)
	local dragger = Factory.make("TextButton", {
		Active = true,
		AutoButtonColor = false,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Selectable = true,
		Size = UDim2.new(1, 0, 0, 44),
		Text = "",
		ZIndex = theme.zIndex.sticky + 2,
	}, frame) :: TextButton
	local title = Factory.text(
		frame,
		tostring(options.Title or "STATUS"),
		scaled(theme, theme.typography.caption),
		theme.colors.text,
		{
			Position = UDim2.fromOffset(12, 7),
			Size = UDim2.new(1, -24, 0, 22),
			theme = theme,
			fontRole = "strong",
			typographyRole = "caption",
			ZIndex = theme.zIndex.sticky + 1,
		}
	)
	local content = Factory.make("ScrollingFrame", {
		Active = true,
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		Position = UDim2.fromOffset(12, 44),
		ScrollBarImageColor3 = theme.colors.borderStrong,
		ScrollBarThickness = 5,
		Size = UDim2.new(1, -24, 1, -56),
		ZIndex = theme.zIndex.sticky + 1,
	}, frame) :: ScrollingFrame
	local layout = Factory.list(content, theme.spacing.xs)
	local primaryText = Factory.text(
		content,
		tostring(options.Text or ""),
		scaled(theme, theme.typography.body),
		theme.colors.textMuted,
		{
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = 1,
			Size = UDim2.new(1, -4, 0, 0),
			TextTruncate = Enum.TextTruncate.None,
			TextWrapped = true,
			TextYAlignment = Enum.TextYAlignment.Top,
			Visible = options.Text ~= nil,
			theme = theme,
			typographyRole = "body",
		}
	)
	local initialStat = if options.Stat ~= nil
		then options.Stat
		elseif options.Progress ~= nil then string.format(
			"%d%%",
			math.floor(math.clamp(tonumber(options.Progress) or 0, 0, 1) * 100 + 0.5)
		)
		else ""
	local primaryStat =
		Factory.text(content, tostring(initialStat), scaled(theme, theme.typography.caption), theme.colors.textMuted, {
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = 2,
			Size = UDim2.new(1, -4, 0, 0),
			TextTruncate = Enum.TextTruncate.None,
			TextWrapped = true,
			Visible = options.Stat ~= nil or options.Progress ~= nil,
			theme = theme,
			typographyRole = "caption",
		})
	local primaryBar = Factory.make("Frame", {
		BackgroundColor3 = theme.colors.border,
		BorderSizePixel = 0,
		LayoutOrder = 3,
		Size = UDim2.new(1, -4, 0, 4),
		Visible = options.Progress ~= nil,
	}, content) :: Frame
	local primaryFill = Factory.make("Frame", {
		BackgroundColor3 = theme.colors.text,
		BorderSizePixel = 0,
		Size = UDim2.fromScale(math.clamp(tonumber(options.Progress) or 0, 0, 1), 1),
	}, primaryBar) :: Frame
	local handle = { Root = frame, _destroyed = false }
	local automaticProgressStat = options.Stat == nil
	local rows = {} :: { any }
	local nextOrder = 4
	local dynamicRows = {} :: { any }

	local function clamp(next: Vector2)
		local viewport, size = context.Root.AbsoluteSize, frame.AbsoluteSize
		frame.Position = UDim2.fromOffset(
			math.clamp(next.X, 0, math.max(0, viewport.X - size.X)),
			math.clamp(next.Y, 0, math.max(0, viewport.Y - size.Y))
		)
	end
	local function resize()
		local viewport = context.Root.AbsoluteSize
		if not explicitSize then
			local maximum = if viewport.Y > 0 then math.max(0, math.min(360, viewport.Y - 16)) else 360
			local minimum = math.min(86, maximum)
			local width = if viewport.X > 0 then math.max(0, math.min(280, viewport.X - 16)) else 280
			frame.Size = UDim2.fromOffset(width, math.clamp(50 + layout.AbsoluteContentSize.Y, minimum, maximum))
		elseif viewport.X > 0 and viewport.Y > 0 then
			local size = frame.AbsoluteSize
			if size.X > viewport.X - 16 or size.Y > viewport.Y - 16 then
				frame.Size = UDim2.fromOffset(
					math.max(0, math.min(size.X, viewport.X - 16)),
					math.max(0, math.min(size.Y, viewport.Y - 16))
				)
			end
		end
		clamp(frame.AbsolutePosition)
	end
	local function isEffectivelyVisible(object: GuiObject): boolean
		local ancestor: Instance? = object
		while ancestor do
			if ancestor:IsA("GuiObject") and not ancestor.Visible then
				return false
			end
			if ancestor:IsA("LayerCollector") and not ancestor.Enabled then
				return false
			end
			ancestor = ancestor.Parent
		end
		return true
	end
	local function updateDynamicRows()
		if not isEffectivelyVisible(frame) then
			return
		end
		for _, row in ipairs(dynamicRows) do
			if not row._removed then
				local ok, nextValue = pcall(row._value)
				if ok then
					row:Set(nextValue)
				end
			end
		end
	end
	local settingVisibility = false
	local function refreshDynamicTask()
		maid:Remove("dynamicRows")
		if #dynamicRows > 0 then
			maid:Set(
				"dynamicRows",
				task.spawn(function()
					while not handle._destroyed and #dynamicRows > 0 do
						updateDynamicRows()
						task.wait(0.5)
					end
				end)
			)
		end
	end
	local function appendTextRow(value: any, color: any, textSize: number)
		local rowMaid = Maid.new()
		local label =
			Factory.text(content, "", textSize, if typeof(color) == "Color3" then color else theme.colors.textMuted, {
				AutomaticSize = Enum.AutomaticSize.Y,
				LayoutOrder = nextOrder,
				Size = UDim2.new(1, -4, 0, 0),
				TextTruncate = Enum.TextTruncate.None,
				TextWrapped = true,
				TextYAlignment = Enum.TextYAlignment.Top,
			})
		nextOrder += 1
		local row = {
			Root = label,
			_body = textSize == scaled(theme, theme.typography.body),
			_color = if typeof(color) == "Color3" then color else nil,
			_maid = rowMaid,
		}
		function row:Set(nextValue: any)
			label.Text = tostring(nextValue)
		end
		function row:Destroy()
			if self._removed then
				return
			end
			self._removed = true
			rowMaid:Destroy()
			label:Destroy()
		end
		row:Set(value)
		table.insert(rows, row)
		return row
	end
	local function appendBarRow(value: any, color: any)
		local rowMaid = Maid.new()
		local root = Factory.make("Frame", {
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			LayoutOrder = nextOrder,
			Size = UDim2.new(1, -4, 0, 26),
		}, content) :: Frame
		nextOrder += 1
		local label = Factory.text(
			root,
			"",
			scaled(theme, theme.typography.caption),
			if typeof(color) == "Color3" then color else theme.colors.textMuted,
			{ Size = UDim2.new(1, 0, 0, 16), TextYAlignment = Enum.TextYAlignment.Top }
		)
		local track = Factory.make("Frame", {
			BackgroundColor3 = theme.colors.border,
			BorderSizePixel = 0,
			Position = UDim2.new(0, 0, 1, -4),
			Size = UDim2.new(1, 0, 0, 4),
		}, root) :: Frame
		local fill = Factory.make("Frame", {
			BackgroundColor3 = if typeof(color) == "Color3" then color else theme.colors.text,
			BorderSizePixel = 0,
			Size = UDim2.new(),
		}, track) :: Frame
		local row = {
			Root = root,
			_color = if typeof(color) == "Color3" then color else nil,
			_maid = rowMaid,
			_label = label,
			_track = track,
			_fill = fill,
		}
		function row:Set(nextValue: any)
			local normalized = math.clamp(tonumber(nextValue) or 0, 0, 1)
			label.Text = string.format("%d%%", math.floor(normalized * 100 + 0.5))
			fill.Size = UDim2.fromScale(normalized, 1)
		end
		function row:Destroy()
			if self._removed then
				return
			end
			self._removed = true
			rowMaid:Destroy()
			root:Destroy()
		end
		row:Set(value)
		table.insert(rows, row)
		return row
	end
	local function appendDynamic(value: any, row: any)
		if type(value) == "function" then
			row._value = value
			table.insert(dynamicRows, row)
			updateDynamicRows()
			refreshDynamicTask()
		end
		return handle
	end
	function handle:SetText(value: any)
		primaryText.Text, primaryText.Visible = tostring(value), true
		return self
	end
	function handle:SetTitle(value: any)
		title.Text = tostring(value)
		return self
	end
	function handle:SetStat(value: any)
		primaryStat.Text, primaryStat.Visible = tostring(value), true
		return self
	end
	function handle:SetProgress(value: any)
		primaryBar.Visible = value ~= nil
		local normalized = math.clamp(tonumber(value) or 0, 0, 1)
		primaryFill.Size = UDim2.fromScale(normalized, 1)
		if automaticProgressStat and value ~= nil then
			primaryStat.Text, primaryStat.Visible = string.format("%d%%", math.floor(normalized * 100 + 0.5)), true
		end
		return self
	end
	function handle:SetVisible(value: boolean)
		settingVisibility = true
		frame.Visible = value == true
		settingVisibility = false
		if frame.Visible then
			updateDynamicRows()
			resize()
		end
		return self
	end
	function handle:Clear()
		primaryText.Text, primaryText.Visible = "", false
		primaryStat.Text, primaryStat.Visible = "", false
		primaryBar.Visible = false
		for _, row in ipairs(rows) do
			row:Destroy()
		end
		table.clear(rows)
		table.clear(dynamicRows)
		refreshDynamicTask()
		resize()
		return self
	end
	function handle:Text(value: any, color: any)
		return appendDynamic(
			value,
			appendTextRow(if type(value) == "function" then "" else value, color, scaled(theme, theme.typography.body))
		)
	end
	function handle:Stat(value: any, colorOrDetail: any)
		local color = if typeof(colorOrDetail) == "Color3" then colorOrDetail else nil
		local function render(nextValue: any): any
			if colorOrDetail ~= nil and color == nil then
				return tostring(nextValue) .. ": " .. tostring(colorOrDetail)
			end
			return nextValue
		end
		local row = appendTextRow(
			if type(value) == "function" then "" else render(value),
			color,
			scaled(theme, theme.typography.caption)
		)
		if type(value) == "function" then
			row._value = function()
				return render(value())
			end
			table.insert(dynamicRows, row)
			updateDynamicRows()
			refreshDynamicTask()
		end
		return self
	end
	function handle:Bar(value: any, color: any)
		return appendDynamic(value, appendBarRow(if type(value) == "function" then 0 else value, color))
	end
	function handle:Destroy()
		if self._destroyed then
			return
		end
		self._destroyed = true
		maid:Destroy()
		frame:Destroy()
	end
	handle.Remove = handle.Destroy
	handle.Unload = handle.Destroy
	maid:GiveTask(dragger.InputBegan:Connect(function(input)
		if
			input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch
		then
			local current = frame.AbsolutePosition
			context.InputRouter:BeginPointerDrag(input, function(_, delta)
				current += delta
				clamp(current)
			end, function() end)
		end
	end))
	maid:GiveTask(layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(resize))
	maid:GiveTask(context.Root:GetPropertyChangedSignal("AbsoluteSize"):Connect(resize))
	local ancestor: Instance? = frame
	while ancestor do
		if ancestor:IsA("GuiObject") then
			maid:GiveTask(ancestor:GetPropertyChangedSignal("Visible"):Connect(function()
				if not settingVisibility and isEffectivelyVisible(frame) then
					updateDynamicRows()
				end
			end))
		elseif ancestor:IsA("LayerCollector") then
			maid:GiveTask(ancestor:GetPropertyChangedSignal("Enabled"):Connect(function()
				if isEffectivelyVisible(frame) then
					updateDynamicRows()
				end
			end))
		end
		ancestor = ancestor.Parent
	end
	self._boxes[handle] = true
	maid:GiveTask(function()
		self._boxes[handle] = nil
		self:_removeSurface(handle)
	end)
	self._surfaces[handle] = function()
		local nextTheme = self:_theme()
		frame.BackgroundColor3 = popupBackground(nextTheme)
		applyPopupStroke(stroke, nextTheme)
		title.TextColor3 = nextTheme.colors.text
		Factory.applyTypography(title, nextTheme, "caption")
		primaryText.TextColor3, primaryStat.TextColor3 = nextTheme.colors.textMuted, nextTheme.colors.textMuted
		Factory.applyTypography(primaryText, nextTheme, "body")
		Factory.applyTypography(primaryStat, nextTheme, "caption")
		primaryBar.BackgroundColor3, primaryFill.BackgroundColor3 = nextTheme.colors.border, nextTheme.colors.text
		content.ScrollBarImageColor3 = nextTheme.colors.borderStrong
		layout.Padding = UDim.new(0, nextTheme.spacing.xs)
		for _, row in ipairs(rows) do
			if row.Root and row.Root.Parent then
				if row._label then
					Factory.applyTypography(row._label, nextTheme, "caption")
					row._label.TextColor3 = row._color or nextTheme.colors.textMuted
					row._track.BackgroundColor3 = nextTheme.colors.border
					row._fill.BackgroundColor3 = row._color or nextTheme.colors.text
				else
					Factory.applyTypography(row.Root, nextTheme, if row._body then "body" else "caption")
					row.Root.TextColor3 = row._color or nextTheme.colors.textMuted
				end
			end
		end
		frame.ZIndex = nextTheme.zIndex.sticky
		local corner = frame:FindFirstChildOfClass("UICorner")
		if corner then
			corner.CornerRadius = UDim.new(0, nextTheme.radius.md)
		end
		resize()
	end
	task.defer(resize)
	return handle
end
function Presentation:ShowTooltip(options: any)
	assert(type(options) == "table", "ShowTooltip requires options")
	local presenceConfig = presenceOptions(self._context.Motion, options)
	local context, theme, maid = self._context, self:_themeFor(options), Maid.new()
	local target = options.Target
	assert(typeof(target) == "Instance" and target:IsA("GuiObject"), "Tooltip requires GuiObject Target")
	local frame = Factory.make("CanvasGroup", {
		AutomaticSize = Enum.AutomaticSize.XY,
		BackgroundColor3 = theme.colors.surfaceRaised,
		BorderSizePixel = 0,
		GroupTransparency = if presenceConfig then 1 else 0,
		Position = UDim2.fromOffset(0, 0),
		ZIndex = theme.zIndex.tooltip,
	}, context.Portal) :: CanvasGroup
	Factory.corner(frame, theme.radius.sm)
	Factory.surface(frame, theme, "raised", { popup = true, border = false, glass = true })
	Factory.windowShadow(frame, theme)
	local stroke = popupStroke(frame, theme)
	Factory.padding(frame, theme.spacing.sm)
	local text = Factory.text(frame, tostring(options.Text or ""), scaled(theme, theme.typography.caption), theme.colors.text, {
		AutomaticSize = Enum.AutomaticSize.XY,
		Size = UDim2.fromOffset(240, 0),
		TextTruncate = Enum.TextTruncate.None,
		TextWrapped = true,
	})
	local handle = { Root = frame, _closed = false }
	handle._presentation = self
	local function place()
		local p, s, viewport = target.AbsolutePosition, target.AbsoluteSize, context.Root.AbsoluteSize
		frame.Position = UDim2.fromOffset(
			math.clamp(p.X, 8, math.max(8, viewport.X - frame.AbsoluteSize.X - 8)),
			math.clamp(p.Y + s.Y + 8, 8, math.max(8, viewport.Y - frame.AbsoluteSize.Y - 8))
		)
	end
	function handle:Close()
		if self._closed then
			return
		end
		self._closed = true
		self._presentation:_exitPresence(presenceConfig, frame, maid, function()
			frame:Destroy()
		end, self._presence)
	end
	handle.Destroy = handle.Close
	maid:GiveTask(context.Root:GetPropertyChangedSignal("AbsoluteSize"):Connect(place))
	maid:GiveTask(target:GetPropertyChangedSignal("AbsolutePosition"):Connect(place))
	self._tooltips[handle] = true
	maid:GiveTask(function()
		self._tooltips[handle] = nil
		self:_removeSurface(handle)
	end)
	self._surfaces[handle] = function()
		local nextTheme = self:_themeFor(options)
		frame.BackgroundColor3 = popupBackground(nextTheme)
		applyPopupStroke(stroke, nextTheme)
		text.TextColor3 = nextTheme.colors.text
		Factory.applyTypography(text, nextTheme, "caption")
		frame.ZIndex = nextTheme.zIndex.tooltip
		local corner = frame:FindFirstChildOfClass("UICorner")
		if corner then
			corner.CornerRadius = UDim.new(0, nextTheme.radius.sm)
		end
	end
	if options.ThemeChanged and type(options.ThemeChanged.Connect) == "function" then
		maid:GiveTask(options.ThemeChanged:Connect(function()
			local apply = self._surfaces[handle]
			if apply then
				apply()
			end
		end))
	end
	if presenceConfig then
		handle._presence = self:_enterPresence(presenceConfig, frame, 0)
	end
	task.defer(place)
	return handle
end

function Presentation:RegisterTooltip(target: GuiObject, text: any, themeProvider: any?, themeChanged: any?)
	assert(typeof(target) == "Instance" and target:IsA("GuiObject"), "RegisterTooltip requires GuiObject target")
	self:UnregisterTooltip(target)
	local maid, shown = Maid.new(), nil
	local function close()
		maid:Remove("autoClose")
		if shown then
			shown:Close()
			shown = nil
		end
	end
	maid:GiveTask(close)
	local function open(autoClose: boolean?)
		close()
		if not self._destroyed then
			shown = self:ShowTooltip({
				Target = target,
				Text = text,
				ThemeProvider = themeProvider,
				ThemeChanged = themeChanged,
			})
			if autoClose then
				maid:Set("autoClose", task.delay(3, close))
			end
		end
	end
	maid:GiveTask(target.MouseEnter:Connect(function()
		open(false)
	end))
	maid:GiveTask(target.MouseLeave:Connect(close))
	maid:GiveTask(target.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.Touch or input.KeyCode == Enum.KeyCode.ButtonA then
			open(true)
		end
	end))
	maid:GiveTask(target.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.Touch or input.KeyCode == Enum.KeyCode.ButtonA then
			close()
		end
	end))
	maid:GiveTask(target.SelectionLost:Connect(close))
	maid:GiveTask(target.Destroying:Connect(function()
		self:UnregisterTooltip(target)
	end))
	self._tooltipRegistrations[target] = maid
	return target
end

function Presentation:UnregisterTooltip(target: GuiObject)
	local maid = self._tooltipRegistrations[target]
	if maid then
		self._tooltipRegistrations[target] = nil
		maid:Destroy()
	end
end

function Presentation:RegisterSearch(entry: any)
	assert(
		type(entry) == "table" and type(entry.id) == "string" and type(entry.activate) == "function",
		"Search entry requires id and activate"
	)
	self._searchEntries[entry.id] = entry
	return entry.id
end
function Presentation:UnregisterSearch(id: string)
	self._searchEntries[id] = nil
end
function Presentation:_refreshHotkeyList()
	self:_refreshOverlay("hotkey-list")
end

function Presentation:RegisterKeybind(id: string, shortcut: any, callback: any, options: any)
	assert(
		type(id) == "string" and id ~= "" and type(shortcut) == "table" and type(callback) == "function",
		"Keybind requires id, shortcut and callback"
	)
	self:UnregisterKeybind(id)
	local registration = table.clone(shortcut)
	if type(options) == "table" and type(options.OnEnded) == "function" then
		registration.onEnded = options.OnEnded
	end
	self._context.InputRouter:RegisterShortcut(id, registration, callback)
	self._keybinds[id] = { shortcut = shortcut, options = options or {} }
	self:_refreshHotkeyList()
	return id
end

function Presentation:UnregisterKeybind(id: string)
	if self._keybinds[id] then
		self._context.InputRouter:UnregisterShortcut(id)
		self._keybinds[id] = nil
		self:_refreshHotkeyList()
	end
end
function Presentation:RegisterSpotlightShortcut(id: string, shortcut: any, window: any, options: any)
	assert(type(id) == "string" and id ~= "", "Spotlight shortcut requires id")
	return self:RegisterKeybind(id, shortcut, function()
		if self._destroyed then
			return false
		end
		self:OpenSpotlight(window or self._context._activeWindow)
		return true
	end, options)
end

function Presentation:ConfigureKeybindOverlay(options: any?)
	options = options or {}
	local config = self._hotkeyConfig
	for _, key in ipairs({ "Title", "Position", "AnchorPoint", "Visible" }) do
		if options[key] ~= nil then
			config[key] = options[key]
		end
	end
	local current = self._hotkeyList
	if current then
		current.Root.Position, current.Root.AnchorPoint, current.Root.Visible =
			config.Position, config.AnchorPoint, config.Visible
		current._title.Text = tostring(config.Title)
		self:_refreshHotkeyList()
		return current
	end
	local context, theme, maid = self._context, self:_theme(), Maid.new()
	local frame = Factory.make("Frame", {
		BackgroundColor3 = theme.colors.surfaceRaised,
		BorderSizePixel = 0,
		Position = config.Position,
		AnchorPoint = config.AnchorPoint,
		Size = UDim2.fromOffset(280, 64),
		Visible = config.Visible,
		ZIndex = theme.zIndex.sticky,
	}, context.Portal) :: Frame
	Factory.corner(frame, theme.radius.md)
	Factory.surface(frame, theme, "raised", { popup = true, border = false, glass = true })
	Factory.windowShadow(frame, theme)
	local stroke = popupStroke(frame, theme)
	Factory.padding(frame, theme.spacing.sm)
	local layout = Factory.list(frame, theme.spacing.xs)
	local title =
		Factory.text(frame, tostring(config.Title), scaled(theme, theme.typography.caption), theme.colors.text, {
			AutomaticSize = Enum.AutomaticSize.Y,
			theme = theme,
			fontRole = "strong",
			typographyRole = "caption",
			Size = UDim2.new(1, 0, 0, 0),
			LayoutOrder = 1,
		})
	local rows = Factory.make("Frame", {
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		LayoutOrder = 2,
		Size = UDim2.new(1, 0, 0, 0),
	}, frame)
	Factory.list(rows, theme.spacing.xs)
	local handle = { Root = frame, _destroyed = false, _title = title }
	local function refresh()
		if handle._destroyed then
			return
		end
		for _, child in ipairs(rows:GetChildren()) do
			if child:IsA("GuiObject") then
				child:Destroy()
			end
		end
		local entries = {}
		for id, entry in pairs(self._keybinds) do
			if entry.options.Hidden ~= true then
				table.insert(
					entries,
					{ id = id, entry = entry, label = tostring(entry.options.Label or entry.options.Mode or id) }
				)
			end
		end
		table.sort(entries, function(a, b)
			local ao, bo = tonumber(a.entry.options.Order) or math.huge, tonumber(b.entry.options.Order) or math.huge
			if ao ~= bo then
				return ao < bo
			end
			if a.label ~= b.label then
				return a.label < b.label
			end
			return a.id < b.id
		end)
		local shown = math.min(#entries, 24)
		if shown == 0 then
			Factory.text(
				rows,
				"No active keybinds",
				scaled(self:_theme(), self:_theme().typography.caption),
				self:_theme().colors.textMuted,
				{ AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.new(1, 0, 0, 0) }
			)
		end
		for index = 1, shown do
			local item = entries[index]
			local keys = {}
			for _, key in ipairs(item.entry.shortcut.keys or {}) do
				table.insert(keys, key.Name)
			end
			local active = false
			if type(item.entry.options.IsActive) == "function" then
				local activeOk, activeValue = pcall(item.entry.options.IsActive)
				active = activeOk and activeValue == true
			end
			local rowText = (if active then "●  " else "○  ") .. table.concat(keys, " + ") .. "  " .. item.label
			Factory.text(
				rows,
				rowText,
				scaled(self:_theme(), self:_theme().typography.caption),
				if active then self:_theme().accentA else self:_theme().colors.textMuted,
				{ AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.new(1, 0, 0, 0) }
			)
		end
		local overflow = if #entries > shown then 1 else 0
		if overflow == 1 then
			Factory.text(
				rows,
				"+" .. tostring(#entries - shown) .. " more",
				scaled(self:_theme(), self:_theme().typography.caption),
				self:_theme().colors.textMuted,
				{ AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.new(1, 0, 0, 0) }
			)
		end
		frame.Size = UDim2.fromOffset(280, math.min(560, 42 + math.max(1, shown + overflow) * 20))
	end
	function handle:SetVisible(active: boolean)
		config.Visible = active
		frame.Visible = active
		return self
	end
	function handle:SetPosition(position: UDim2)
		config.Position = position
		frame.Position = position
		return self
	end
	function handle:Refresh()
		refresh()
		return self
	end
	function handle:Destroy()
		if self._destroyed then
			return
		end
		self._destroyed = true
		Presentation._unmountOverlay(self._presentation, "hotkey-list", self)
		maid:Destroy()
		frame:Destroy()
		if self._presentation._hotkeyList == self then
			self._presentation._hotkeyList = nil
		end
	end
	handle._presentation = self
	self._hotkeyList = handle
	self:_mountOverlay("hotkey-list", "hotkey-list", handle, function()
		local nextTheme = self:_theme()
		frame.BackgroundColor3, title.TextColor3 = popupBackground(nextTheme), nextTheme.colors.text
		applyPopupStroke(stroke, nextTheme)
		Factory.applyTypography(title, nextTheme, "caption")
		frame.ZIndex, layout.Padding = nextTheme.zIndex.sticky, UDim.new(0, nextTheme.spacing.xs)
		refresh()
	end, refresh)
	refresh()
	return handle
end

function Presentation:SetKeybindOverlayVisible(active: boolean)
	return self:SetKeybindOverlay(active)
end
function Presentation:SetKeybindOverlay(active: boolean)
	if not active and not self._hotkeyList then
		self._hotkeyConfig.Visible = false
		return nil
	end
	return self:ConfigureKeybindOverlay({ Visible = active })
end

function Presentation:CreateWatermark(options: any)
	if type(options) == "string" then
		options = { Text = options }
	end
	options = options or {}
	local presenceConfig = presenceOptions(self._context.Motion, options)
	local existing = self._watermark
	if existing and not existing._destroyed then
		existing:SetText(options.Text or existing._text)
		if options.Detail ~= nil then
			existing:SetDetail(options.Detail)
		end
		if options.Position ~= nil then
			existing:SetPosition(options.Position)
		end
		if options.AnchorPoint ~= nil then
			existing:SetAnchorPoint(options.AnchorPoint)
		end
		if options.Visible ~= nil then
			existing:SetVisible(options.Visible)
		end
		return existing
	end
	local context, theme, maid = self._context, self:_theme(), Maid.new()
	local frame = Factory.make("CanvasGroup", {
		AutomaticSize = Enum.AutomaticSize.XY,
		BackgroundColor3 = theme.colors.surfaceRaised,
		BackgroundTransparency = 0,
		BorderSizePixel = 0,
		GroupTransparency = if presenceConfig then 1 else 0,
		Position = options.Position or UDim2.fromOffset(16, 16),
		AnchorPoint = options.AnchorPoint or Vector2.new(),
		Visible = options.Visible ~= false,
		ZIndex = theme.zIndex.sticky,
	}, context.Portal) :: CanvasGroup
	Factory.corner(frame, theme.radius.sm)
	Factory.surface(frame, theme, "raised", { popup = true, border = false, glass = true })
	Factory.windowShadow(frame, theme)
	local stroke = popupStroke(frame, theme)
	Factory.padding(frame, theme.spacing.sm)
	local rowLayout = Factory.list(frame, theme.spacing.xs, true)
	local text = Factory.text(
		frame,
		tostring(options.Text or "Potassium"),
		scaled(theme, theme.typography.caption),
		theme.colors.text,
		{
			AutomaticSize = Enum.AutomaticSize.X,
			theme = theme,
			fontRole = "strong",
			typographyRole = "caption",
			LayoutOrder = 1,
			Size = UDim2.fromOffset(0, 18),
		}
	)
	local detail = Factory.text(
		frame,
		if options.Detail == nil then "" else tostring(options.Detail),
		scaled(theme, theme.typography.caption),
		theme.colors.textMuted,
		{
			AutomaticSize = Enum.AutomaticSize.X,
			LayoutOrder = 2,
			Size = UDim2.fromOffset(0, 18),
			theme = theme,
			typographyRole = "caption",
		}
	)
	local handle =
		{ Root = frame, _destroyed = false, _text = tostring(options.Text or "Potassium"), _detail = options.Detail }
	local function clamp()
		local size, viewport = frame.AbsoluteSize, context.Root.AbsoluteSize
		local x, y = frame.Position.X.Offset, frame.Position.Y.Offset
		if frame.Position.X.Scale == 0 and frame.Position.Y.Scale == 0 then
			frame.Position = UDim2.fromOffset(
				math.clamp(x, 0, math.max(0, viewport.X - size.X)),
				math.clamp(y, 0, math.max(0, viewport.Y - size.Y))
			)
		end
	end
	function handle:SetText(value: any)
		local nextValue = tostring(value)
		if self._text ~= nextValue then
			self._text = nextValue
			text.Text = nextValue
		end
		return self
	end
	function handle:SetDetail(value: any?)
		local nextValue = if value == nil then nil else tostring(value)
		local nextText = nextValue or ""
		local nextVisible = nextValue ~= nil
		if self._detail ~= nextValue or detail.Text ~= nextText or detail.Visible ~= nextVisible then
			self._detail = nextValue
			detail.Text = nextText
			detail.Visible = nextVisible
		end
		return self
	end
	function handle:SetVisible(active: boolean)
		if frame.Visible ~= active then
			frame.Visible = active
		end
		return self
	end
	function handle:SetPosition(position: UDim2)
		if frame.Position ~= position then
			frame.Position = position
			clamp()
		end
		return self
	end
	function handle:SetAnchorPoint(anchorPoint: Vector2)
		frame.AnchorPoint = anchorPoint
		return self
	end
	function handle:Destroy()
		if self._destroyed then
			return
		end
		self._destroyed = true
		self._presentation:_unmountOverlay("watermark", self)
		if self._presentation._watermark == self then
			self._presentation._watermark = nil
		end
		self._presentation:_exitPresence(presenceConfig, frame, maid, function()
			frame:Destroy()
		end, self._presence)
	end
	handle._presentation = self
	self._watermark = handle
	detail.Visible = options.Detail ~= nil
	maid:GiveTask(context.Root:GetPropertyChangedSignal("AbsoluteSize"):Connect(clamp))
	self:_mountOverlay("watermark", "watermark", handle, function()
		local nextTheme = self:_theme()
		frame.BackgroundColor3, text.TextColor3, detail.TextColor3 =
			popupBackground(nextTheme), nextTheme.colors.text, nextTheme.colors.textMuted
		applyPopupStroke(stroke, nextTheme)
		Factory.applyTypography(text, nextTheme, "caption")
		Factory.applyTypography(detail, nextTheme, "caption")
		frame.ZIndex = nextTheme.zIndex.sticky
		rowLayout.Padding = UDim.new(0, nextTheme.spacing.xs)
	end)
	clamp()
	if presenceConfig then
		handle._presence = self:_enterPresence(presenceConfig, frame, 0)
	else
		local motion = self:_animate(frame, { BackgroundTransparency = 0 })
		if motion then
			maid:GiveTask(motion)
		end
	end
	return handle
end
function Presentation:OpenSpotlight(window: any, options: any?)
	options = options or {}
	local presenceConfig = presenceOptions(self._context.Motion, options)
	if self._spotlight then
		self._spotlight:Close()
		return nil
	end
	local context, theme, id, maid = self._context, self:_themeFor(options), self._context:_id("spotlight"), Maid.new()
	local anchor = if window then window._searchButton else nil
	local anchorWasVisible = if anchor then anchor.Visible else nil
	local pointerCatcher = Factory.make("TextButton", {
		Name = "PotassiumSpotlightPointerCatcher",
		Active = true,
		AutoButtonColor = false,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1),
		Text = "",
		ZIndex = theme.zIndex.modal - 1,
	}, context.Portal) :: TextButton
	maid:GiveTask(pointerCatcher)
	local panel = Factory.make("CanvasGroup", {
		Active = true,
		BackgroundColor3 = popupBackground(theme),
		BorderSizePixel = 0,
		GroupTransparency = if presenceConfig then 1 else 0,
		Position = UDim2.fromOffset(12, 12),
		Size = UDim2.fromOffset(280, 44),
		ZIndex = theme.zIndex.modal,
	}, context.Portal) :: CanvasGroup
	Factory.corner(panel, theme.radius.md)
	Factory.surface(panel, theme, "surface", { popup = true, border = false, glass = true })
	Factory.windowShadow(panel, theme)
	local stroke = popupStroke(panel, theme)
	local query = Factory.make("TextBox", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		ClearTextOnFocus = false,
		PlaceholderText = "Search features…",
		PlaceholderColor3 = theme.colors.textMuted,
		Text = "",
		TextColor3 = theme.colors.text,
		TextSize = scaled(theme, theme.typography.body),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		Position = UDim2.fromOffset(12, 0),
		Size = UDim2.new(1, -24, 0, 44),
		ZIndex = theme.zIndex.modal + 1,
	}, panel) :: TextBox
	Factory.applyTypography(query, theme, "body")
	local divider = Factory.make("Frame", {
		Active = false,
		BackgroundColor3 = theme.colors.border,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(8, 44),
		Size = UDim2.new(1, -16, 0, 1),
		Visible = false,
		ZIndex = theme.zIndex.modal + 1,
	}, panel) :: Frame
	local results = Factory.make("ScrollingFrame", {
		Active = true,
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		Position = UDim2.fromOffset(4, 49),
		ScrollBarImageColor3 = theme.colors.borderStrong,
		ScrollBarThickness = 2,
		Size = UDim2.new(1, -8, 1, -53),
		Visible = false,
		ZIndex = theme.zIndex.modal + 1,
	}, panel) :: ScrollingFrame
	Factory.list(results, theme.spacing.xs)
	local selected, filtered, visibleContentHeight, fit, handle = 1, {}, 0, nil, {
		Root = panel,
		_closed = false,
		_maid = maid,
		_owner = if window then window._presentationOwner else nil,
	}
	local renderMaid = Maid.new()
	maid:GiveTask(renderMaid)
	local function allEntries()
		local output = {}
		for _, entry in pairs(self._searchEntries) do
			table.insert(output, entry)
		end
		if window and window._tabs then
			for _, tab in ipairs(window._tabs) do
				local tabTitle = tostring(tab._label or tab._id or "Tab")
				table.insert(output, {
					id = "tab." .. tostring(tab._id or tabTitle),
					title = tabTitle,
					description = "",
					keywords = tabTitle,
					activate = function()
						tab:_select()
						window:SetOpen(true)
					end,
					owner = window,
				})
			end
		end
		table.sort(output, function(a, b)
			return tostring(a.title) < tostring(b.title)
		end)
		return output
	end
	local function activate()
		local entry = filtered[selected]
		if entry then
			handle:Close()
			entry.activate()
		end
	end
	local function render()
		renderMaid:Clean()
		for _, child in ipairs(results:GetChildren()) do
			if child:IsA("GuiObject") then
				child:Destroy()
			end
		end
		filtered = {}
		local firstVisibleRowsHeight, visibleRowCount = 0, 0
		local needle = string.lower(string.match(query.Text, "^%s*(.-)%s*$") or "")
		if needle == "" then
			selected = 1
			results.Visible = false
			divider.Visible = false
			visibleContentHeight = 0
			if fit then fit() end
			return
		end
		results.Visible = true
		divider.Visible = true
		for _, entry in ipairs(allEntries()) do
			local haystack = string.lower(
				tostring(entry.title)
					.. " "
					.. tostring(entry.description or "")
					.. " "
					.. tostring(entry.keywords or "")
			)
			if string.find(haystack, needle, 1, true) then
				table.insert(filtered, entry)
			end
		end
		selected = math.clamp(selected, 1, math.max(1, #filtered))
		if #filtered == 0 then
			Factory.text(
				results,
				"No features found.",
				scaled(theme, theme.typography.body),
				theme.colors.textMuted,
				{ LayoutOrder = 1, Size = UDim2.new(1, 0, 0, 36), TextWrapped = true }
			)
			visibleContentHeight = 36
			if fit then fit() end
			return
		end
		for index, entry in ipairs(filtered) do
			local hasDescription = entry.description ~= nil and entry.description ~= ""
			local rowHeight = if hasDescription then 44 else 36
			local label = tostring(entry.title) .. if hasDescription then "\n" .. tostring(entry.description) else ""
			local button = Factory.button(results, "", theme, {
				Role = "ghost",
				AnimatePress = false,
				LayoutOrder = index,
				Size = UDim2.new(1, 0, 0, rowHeight),
				TextXAlignment = Enum.TextXAlignment.Left,
				ZIndex = theme.zIndex.modal + 2,
			})
			local rowContent = Factory.buttonContent(button, label, theme, {
				Insets = { left = 10, right = 8 },
				TextXAlignment = Enum.TextXAlignment.Left,
			})
			renderMaid:GiveTask(rowContent)
			local accentRail = Factory.make("Frame", {
				Active = false,
				AnchorPoint = Vector2.new(0, 0.5),
				BackgroundColor3 = theme.accentA,
				BorderSizePixel = 0,
				Position = UDim2.new(0, 2, 0.5, 0),
				Size = UDim2.fromOffset(2, math.min(18, rowHeight - 8)),
				Visible = index == selected,
				ZIndex = theme.zIndex.modal + 3,
			}, button) :: Frame
			Factory.corner(accentRail, 2)
			if index == selected and Factory.setButtonState then
				Factory.setButtonState(button, "selected", theme)
			end
			if index <= 3 then
				if visibleRowCount > 0 then firstVisibleRowsHeight += theme.spacing.xs end
				visibleRowCount += 1
				firstVisibleRowsHeight += rowHeight
			end
			renderMaid:GiveTask(button.Activated:Connect(function()
				selected = index
				activate()
			end))
		end
		visibleContentHeight = math.max(36, firstVisibleRowsHeight)
		if fit then fit() end
	end
	fit = function()
		local viewport = context.Root.AbsoluteSize
		local inset = 12
		local left, top = inset, inset
		local right, bottom = math.max(left + 1, viewport.X - inset), math.max(top + 1, viewport.Y - inset)
		local frame = if window then window._frame else nil
		if frame and frame.Parent then
			local framePosition, frameSize = frame.AbsolutePosition, frame.AbsoluteSize
			left = math.max(left, framePosition.X + inset)
			top = math.max(top, framePosition.Y + inset)
			right = math.max(left + 1, math.min(right, framePosition.X + frameSize.X - inset))
			bottom = math.max(top + 1, math.min(bottom, framePosition.Y + frameSize.Y - inset))
		end
		local anchorPosition = if anchor and anchor.Parent then anchor.AbsolutePosition else Vector2.new(left, top)
		local anchorSize = if anchor and anchor.Parent then anchor.AbsoluteSize else Vector2.new(220, 34)
		local availableWidth = math.max(1, right - left)
		local desiredWidth = math.min(300, math.max(280, anchorSize.X + 90))
		local width = math.min(desiredWidth, availableWidth)
		local x = left + math.floor((availableWidth - width) / 2)
		local desiredHeight = 44 + if visibleContentHeight > 0 then visibleContentHeight + 9 else 0
		local below = bottom - anchorPosition.Y
		local above = anchorPosition.Y + anchorSize.Y - top
		local openBelow = below >= math.min(desiredHeight, 120) or below >= above
		local availableHeight = math.max(1, if openBelow then below else above)
		local height = math.min(desiredHeight, availableHeight)
		local y = if openBelow then anchorPosition.Y else math.max(top, anchorPosition.Y + anchorSize.Y - height)
		panel.Size = UDim2.fromOffset(width, height)
		panel.Position = UDim2.fromOffset(x, y)
	end
	function handle:Close()
		if self._closed then
			return
		end
		self._closed = true
		if anchor and anchor.Parent then
			anchor.Visible = anchorWasVisible
		end
		context.InputRouter:PopModal(id)
		context.FocusManager:PopModal(id)
		self._presentation:_releaseOwned(self._owner, self)
		if self._presentation._spotlight == self then
			self._presentation._spotlight = nil
		end
		self._presentation:_exitPresence(presenceConfig, panel, maid, function()
			panel:Destroy()
		end, self._presence)
	end
	handle._presentation = self
	handle.Destroy = handle.Close
	handle.OnBack = function()
		handle:Close()
	end
	maid:GiveTask(pointerCatcher.Activated:Connect(function()
		handle:Close()
	end))
	maid:GiveTask(query:GetPropertyChangedSignal("Text"):Connect(function()
		selected = 1
		render()
	end))
	maid:GiveTask(query.InputBegan:Connect(function(input)
		if input.KeyCode == Enum.KeyCode.Down or input.KeyCode == Enum.KeyCode.DPadDown then
			selected = math.min(#filtered, selected + 1)
			render()
		elseif input.KeyCode == Enum.KeyCode.Up or input.KeyCode == Enum.KeyCode.DPadUp then
			selected = math.max(1, selected - 1)
			render()
		elseif
			input.KeyCode == Enum.KeyCode.Return
			or input.KeyCode == Enum.KeyCode.KeypadEnter
			or input.KeyCode == Enum.KeyCode.ButtonA
		then
			activate()
		elseif input.KeyCode == Enum.KeyCode.Escape or input.KeyCode == Enum.KeyCode.ButtonB then
			handle:Close()
		end
	end))
	maid:GiveTask(context.Root:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit))
	if anchor then
		maid:GiveTask(anchor:GetPropertyChangedSignal("AbsolutePosition"):Connect(fit))
		maid:GiveTask(anchor:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit))
		anchor.Visible = false
	end
	if window and window._frame then
		maid:GiveTask(window._frame:GetPropertyChangedSignal("AbsolutePosition"):Connect(fit))
		maid:GiveTask(window._frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit))
	end
	focus(context, maid, id .. ".query", query, 1)
	fit()
	render()
	context.InputRouter:PushModal(id, handle)
	context.FocusManager:PushModal(id, query)
	task.defer(function()
		if not handle._closed then
			query:CaptureFocus()
		end
	end)
	self._spotlight = handle
	self:_trackOwned(handle._owner, handle)
	self._surfaces[handle] = function()
		local nextTheme = self:_theme()
		panel.BackgroundColor3 = popupBackground(nextTheme)
		applyPopupStroke(stroke, nextTheme)
		query.BackgroundTransparency = 1
		query.TextColor3 = nextTheme.colors.text
		query.PlaceholderColor3 = nextTheme.colors.textMuted
		divider.BackgroundColor3 = nextTheme.colors.border
		results.ScrollBarImageColor3 = nextTheme.colors.borderStrong
		theme = nextTheme
		Factory.applyTypography(query, nextTheme, "body")
		pointerCatcher.ZIndex, panel.ZIndex, query.ZIndex, divider.ZIndex, results.ZIndex =
			nextTheme.zIndex.modal - 1, nextTheme.zIndex.modal, nextTheme.zIndex.modal + 1, nextTheme.zIndex.modal + 1, nextTheme.zIndex.modal + 1
		local corner = panel:FindFirstChildOfClass("UICorner")
		if corner then
			corner.CornerRadius = UDim.new(0, nextTheme.radius.md)
		end
		render()
	end
	maid:GiveTask(function()
		self:_removeSurface(handle)
	end)
	if presenceConfig then
		handle._presence = self:_enterPresence(presenceConfig, panel, 0)
	end
	return handle
end

function Presentation:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	self._avatarGeneration += 1
	for _, request in pairs(self._avatarPending) do
		request.cancelled = true
		pcall(function()
			self:_cancelAvatarRequest(request)
		end)
		table.clear(request.callbacks)
	end
	table.clear(self._avatarPending)
	table.clear(self._avatarQueue)
	local avatarOwnerKeys = {}
	for key in pairs(self._avatarOwners) do
		table.insert(avatarOwnerKeys, key)
	end
	for _, key in ipairs(avatarOwnerKeys) do
		self:_releaseAvatarOwner(key)
	end
	table.clear(self._avatarOwners)
	table.clear(self._avatarCache)
	self._avatarInflight = 0
	self._avatarWaiters = 0

	for _, order in pairs(self._toastOrder) do
		for index = #order, 1, -1 do
			local handle = order[index]
			pcall(function()
				handle:Close("destroyed")
			end)
		end
	end
	for handle in pairs(self._changelogs) do
		pcall(function()
			handle:Close("destroyed")
		end)
	end
	for id in pairs(self._keybinds) do
		pcall(function()
			self:UnregisterKeybind(id)
		end)
	end
	for handle in pairs(self._dialogs) do
		pcall(function()
			handle:Destroy()
		end)
	end
	for _, handle in pairs(table.clone(self._progressOverlays)) do
		pcall(function()
			handle:Destroy()
		end)
	end
	for handle in pairs(self._notifications) do
		pcall(function()
			handle:Close()
		end)
	end
	for handle in pairs(self._boxes) do
		pcall(function()
			handle:Destroy()
		end)
	end
	for handle in pairs(self._tooltips) do
		pcall(function()
			handle:Close()
		end)
	end
	for target in pairs(self._tooltipRegistrations) do
		pcall(function()
			self:UnregisterTooltip(target)
		end)
	end
	if self._spotlight then
		pcall(function()
			self._spotlight:Close()
		end)
	end
	if self._hotkeyList then
		pcall(function()
			self._hotkeyList:Destroy()
		end)
	end
	if self._watermark then
		pcall(function()
			self._watermark:Destroy()
		end)
	end
	for _, entry in pairs(table.clone(self._exiting)) do
		pcall(entry.finish)
	end
	for _, host in pairs(self._toastHosts) do
		pcall(function()
			host:Destroy()
		end)
	end

	table.clear(self._boxes)
	table.clear(self._dialogIds)
	table.clear(self._progressOverlays)
	table.clear(self._dialogs)
	table.clear(self._keybinds)
	table.clear(self._notifications)
	table.clear(self._searchEntries)
	table.clear(self._overlays)
	table.clear(self._notificationOrder)
	table.clear(self._tooltips)
	table.clear(self._tooltipRegistrations)
	table.clear(self._surfaces)
	table.clear(self._ownedSurfaces)
	table.clear(self._toastOrder)
	table.clear(self._toastHosts)
	table.clear(self._changelogs)
	table.clear(self._exiting)
	self._spotlight = nil
	self._hotkeyList = nil
	self._watermark = nil
	self._toastStack = nil
	self._maid:Destroy()
end
return Presentation

end

__modules["services/ThemeEditor"] = function()
--!strict

local Maid = __require("core/Maid")
local Theme = __require("core/Theme")
local Util = __require("core/Util")

local ThemeEditor = {}
ThemeEditor.__index = ThemeEditor

local memoryPresets: { [string]: any } = {}

local function failure(code: string, message: string)
	return { code = code, message = message }
end

local function colorChannel(value: number): number
	if value <= 0.04045 then return value / 12.92 end
	return ((value + 0.055) / 1.055) ^ 2.4
end

local function luminance(color: Color3): number
	return 0.2126 * colorChannel(color.R) + 0.7152 * colorChannel(color.G) + 0.0722 * colorChannel(color.B)
end

local function ratio(first: Color3, second: Color3): number
	local a, b = luminance(first), luminance(second)
	if a < b then a, b = b, a end
	return (a + 0.05) / (b + 0.05)
end

local function sanitizeName(name: any): (string?, any?)
	if type(name) ~= "string" then return nil, failure("invalid_preset_name", "Preset names must be strings") end
	name = string.gsub(name, "^%s+", "")
	name = string.gsub(name, "%s+$", "")
	name = string.sub(name, 1, 64)
	if name == "" or not string.match(name, "^[%w][%w _%-]*$") then
		return nil, failure("invalid_preset_name", "Preset names may contain letters, numbers, spaces, underscores, and hyphens")
	end
	return name, nil
end

local function setPath(target: any, path: string, value: any): (boolean, any?)
	if type(path) ~= "string" or path == "" then return false, failure("invalid_path", "Token path must be a non-empty string") end
	local cursor = target
	local parts = string.split(path, ".")
	for index = 1, #parts - 1 do
		local part = parts[index]
		if part == "" then return false, failure("invalid_path", "Token path contains an empty segment") end
		if type(cursor[part]) ~= "table" then cursor[part] = {} end
		cursor = cursor[part]
	end
	if parts[#parts] == "" then return false, failure("invalid_path", "Token path contains an empty segment") end
	cursor[parts[#parts]] = value
	return true, nil
end

local function encodeValue(value: any): any
	if typeof(value) == "Color3" then return { __themeEditorType = "Color3", r = value.R, g = value.G, b = value.B } end
	if typeof(value) == "Vector2" then return { __themeEditorType = "Vector2", x = value.X, y = value.Y } end
	if typeof(value) == "Font" then
		return { __themeEditorType = "Font", family = value.Family, weight = value.Weight.Name, style = value.Style.Name }
	end
	if typeof(value) == "EnumItem" then
		local enumName = string.match(tostring(value.EnumType), "^Enum%.(.+)$") or tostring(value.EnumType)
		return { __themeEditorType = "Enum", enum = enumName, name = value.Name }
	end
	if type(value) ~= "table" then return value end
	local result = {}
	for key, entry in pairs(value) do result[key] = encodeValue(entry) end
	return result
end

local function decodeValue(value: any): any
	if type(value) ~= "table" then return value end
	if value.__themeEditorType == "Color3" and type(value.r) == "number" and type(value.g) == "number" and type(value.b) == "number" then
		return Color3.new(value.r, value.g, value.b)
	end
	if value.__themeEditorType == "Vector2" and type(value.x) == "number" and type(value.y) == "number" then
		return Vector2.new(value.x, value.y)
	end
	if value.__themeEditorType == "Font" and type(value.family) == "string" and type(value.weight) == "string" and type(value.style) == "string" then
		return Font.new(value.family, Enum.FontWeight[value.weight], Enum.FontStyle[value.style])
	end
	if value.__themeEditorType == "Enum" and type(value.enum) == "string" and type(value.name) == "string" then
		local enumType = Enum[value.enum]
		return if enumType then enumType[value.name] else nil
	end
	local result = {}
	for key, entry in pairs(value) do result[key] = decodeValue(entry) end
	return result
end

function ThemeEditor.new(library: any, options: any)
	options = options or {}
	local preview = options.Preview or options.preview or options.PreviewTarget or options.previewTarget
	local commitTarget = options.Target or options.target or preview or library
	local source = if preview and preview.Theme then preview.Theme else library.Theme
	local baselineDetail, baselineError = Theme.resolveDetailed(source, library.Fonts)
	assert(baselineDetail ~= nil, (baselineError and baselineError.message) or "Theme editor requires a valid theme")
	local baseline = baselineDetail.theme
	local previewBaseline = nil
	if preview and preview.Theme then
		local previewDetail, previewError = Theme.resolveDetailed(preview.Theme, library.Fonts)
		assert(previewDetail ~= nil, (previewError and previewError.message) or "Theme editor preview requires a valid theme")
		previewBaseline = previewDetail.theme
	end
	local self = setmetatable({
		Library = library,
		Preview = preview,
		Target = commitTarget,
		RequireContrast = options.RequireContrast == true or options.requireContrast == true,
		Draft = Util.deepCopy(baseline),
		Original = Util.deepCopy(baseline),
		Detail = baselineDetail,
		PreviewOriginal = if previewBaseline then Util.deepCopy(previewBaseline) else nil,
		Maid = Maid.new(),
		Controls = {},
		_destroyed = false,
		_syncing = false,
		_hasApplied = false,
		_previewDirty = false,
		_presetPrefix = options.PresetPrefix or "theme-editor-",
	}, ThemeEditor)
	self:_build(options)
	return self
end
function ThemeEditor:_validate(value: any): (any?, any?)
	local detail, resolveError = Theme.resolveDetailed(value, self.Library.Fonts)
	if detail == nil then return nil, resolveError end
	local valid, validationError = Theme.validate(value, self.Library.Fonts)
	if not valid then return nil, validationError end
	self.Detail = detail
	return Util.deepCopy(detail.theme), nil
end

function ThemeEditor:_preview(): (boolean, any?)
	local resolved, themeError = self:_validate(self.Draft)
	if resolved == nil then return false, themeError end
	self.Draft = Util.deepCopy(resolved)
	if self.Preview then
		local result, applyError = self.Preview:ApplyTheme(resolved)
		if result == false or result == nil then return false, applyError end
		self._previewDirty = true
	end
	return true, nil
end

function ThemeEditor:_syncControls()
	self._syncing = true
	for path, control in pairs(self.Controls) do
		local cursor = self.Draft
		for part in string.gmatch(path, "[^%.]+") do cursor = cursor and cursor[part] end
		if control and type(control.Set) == "function" then control:Set(cursor) end
	end
	self._syncing = false
end

function ThemeEditor:SetToken(path: string, value: any): (boolean, any?)
	if self._destroyed then return false, failure("destroyed", "Theme editor has been destroyed") end
	local nextDraft = Util.deepCopy(self.Draft)
	local set, setError = setPath(nextDraft, path, value)
	if not set then return false, setError end
	local before, beforeDetail = self.Draft, self.Detail
	local resolved, themeError = self:_validate(nextDraft)
	if resolved == nil then return false, themeError end
	self.Draft = resolved
	local previewed, previewError = self:_preview()
	if not previewed then
		self.Draft, self.Detail = before, beforeDetail
		return false, previewError
	end
	self:_syncControls()
	return true, nil
end

function ThemeEditor:GetDraft()
	return Util.deepCopy(self.Draft)
end

function ThemeEditor:ResetDraft()
	if self._destroyed then return false, failure("destroyed", "Theme editor has been destroyed") end
	local before, beforeDetail = self.Draft, self.Detail
	self.Draft = Util.deepCopy(self.Original)
	local ok, err = self:_preview()
	if ok then self:_syncControls() else self.Draft, self.Detail = before, beforeDetail end
	return ok, err
end

function ThemeEditor:CheckContrast()
	local detail, detailError = Theme.resolveDetailed(self.Draft, self.Library.Fonts)
	if detail == nil then return { pass = false, rows = {}, error = detailError } end
	self.Detail = detail
	return {
		pass = detail.contrast.pass,
		rows = Util.deepCopy(detail.contrast.rows),
		provenance = Util.deepCopy(detail.provenance),
	}
end

function ThemeEditor:GetTokenProvenance(path: string): string?
	local detail = self.Detail
	return if detail and detail.provenance then detail.provenance[path] else nil
end

function ThemeEditor:Apply()
	if self._destroyed then return false, failure("destroyed", "Theme editor has been destroyed") end
	local resolved, themeError = self:_validate(self.Draft)
	if resolved == nil then return false, themeError end
	local report = self:CheckContrast()
	if self.RequireContrast and not report.pass then return false, failure("contrast_failed", "Theme does not meet required WCAG contrast") end
	local applied, applyError = self.Target:ApplyTheme(resolved)
	if applied == false or applied == nil then return false, applyError end
	self._hasApplied = true
	self._previewDirty = false
	self.Draft, self.Original = Util.deepCopy(resolved), Util.deepCopy(resolved)
	if self.Preview then self.PreviewOriginal = Util.deepCopy(resolved) end
	return true, report
end

function ThemeEditor:Revert()
	if self._destroyed then return false, failure("destroyed", "Theme editor has been destroyed") end
	local restore = if self.Preview then (self.PreviewOriginal or self.Original) else nil
	if restore then
		local applied, applyError = self.Preview:ApplyTheme(restore)
		if applied == false or applied == nil then return false, applyError end
	end
	self.Draft = Util.deepCopy(self.Original)
	self._previewDirty = false
	self:_syncControls()
	return true, nil
end

function ThemeEditor:Export(format: any): (any?, any?)
	local resolved, themeError = self:_validate(self.Draft)
	if resolved == nil then return nil, themeError end
	if format == nil or format == "table" then return Util.deepCopy(resolved), nil end
	if format ~= "json" then return nil, failure("invalid_export_format", "Export format must be table or json") end
	return self.Library.Runtime:jsonEncode(encodeValue(resolved))
end

function ThemeEditor:Import(payload: any): (boolean, any?)
	if self._destroyed then return false, failure("destroyed", "Theme editor has been destroyed") end
	local decoded = payload
	if type(payload) == "string" then
		local json, decodeError = self.Library.Runtime:jsonDecode(payload)
		if json == nil then return false, decodeError end
		local decodedOk, decodedValue = pcall(decodeValue, json)
		if not decodedOk then return false, failure("invalid_import", "Imported theme contains an invalid typed value") end
		decoded = decodedValue
	end
	if type(decoded) ~= "table" then return false, failure("invalid_import", "Imported theme must be a table or JSON object") end
	local before, beforeDetail = self.Draft, self.Detail
	local resolved, themeError = self:_validate(decoded)
	if resolved == nil then return false, themeError end
	self.Draft = Util.deepCopy(resolved)
	local previewed, previewError = self:_preview()
	if not previewed then self.Draft, self.Detail = before, beforeDetail; return false, previewError end
	self:_syncControls()
	return true, nil
end

function ThemeEditor:_presetKey(name: string): string return self._presetPrefix .. name end
function ThemeEditor:_storage()
	return (self.Library.Persistence and self.Library.Persistence._storage) or self.Library.Runtime.storage
end

function ThemeEditor:SavePreset(name: any): (boolean, any?)
	local safe, nameError = sanitizeName(name)
	if safe == nil then return false, nameError end

	local exported, exportError = self:Export("json")
	if exported == nil then return false, exportError end
	memoryPresets[self:_presetKey(safe)] = exported
	local storage = self:_storage()
	if storage and type(storage.write) == "function" then pcall(storage.write, storage, "PotassiumUI/" .. self:_presetKey(safe) .. ".json", exported) end
	return true, safe
end
function ThemeEditor:LoadPreset(name: any): (boolean, any?)
	local safe, nameError = sanitizeName(name)
	if safe == nil then return false, nameError end
	local payload = memoryPresets[self:_presetKey(safe)]
	local storage = self:_storage()
	if payload == nil and storage and type(storage.read) == "function" then
		local ok, value = pcall(storage.read, storage, "PotassiumUI/" .. self:_presetKey(safe) .. ".json")
		if ok and type(value) == "string" then payload = value; memoryPresets[self:_presetKey(safe)] = value end
	end
	if payload == nil then return false, failure("preset_not_found", "Theme preset was not found") end
	return self:Import(payload)
end
function ThemeEditor:DeletePreset(name: any): (boolean, any?)
	local safe, nameError = sanitizeName(name)
	if safe == nil then return false, nameError end
	memoryPresets[self:_presetKey(safe)] = nil
	local storage = self:_storage()
	if storage and type(storage.delete) == "function" then pcall(storage.delete, storage, "PotassiumUI/" .. self:_presetKey(safe) .. ".json") end
	return true, nil
end
function ThemeEditor:ListPresets()
	local names, seen = {}, {}
	for key in pairs(memoryPresets) do
		if string.sub(key, 1, #self._presetPrefix) == self._presetPrefix then
			local name = string.sub(key, #self._presetPrefix + 1)
			seen[name] = true
			table.insert(names, name)
		end
	end
	table.sort(names)
	return names
end
function ThemeEditor:SetVisible(visible: boolean)
	if self.Window then self.Window:SetOpen(visible == true) end
	return self
end

function ThemeEditor:_build(options: any)
	if options.Window == false or options.window == false then return end
	local window = options.Window or options.window
	if window == true then window = nil end
	if window == nil then
		window = self.Library:CreateWindow({ Id = options.Id or "theme-editor", Title = options.Title or "Theme Editor", Size = options.Size or Vector2.new(760, 620), StartOpen = options.Open ~= false, MenuKey = options.MenuKey or Enum.KeyCode.RightShift })
		self._ownsWindow = true
	end
	self.Window = window
	local tab = window:Tab({ Id = "theme-editor", Title = "Theme Editor", Icon = "settings" })
	self.Tab = tab
	local appearance = tab:Section({ Id = "appearance", Title = "Appearance", Side = "Left", PersistControls = false })
	local behavior = tab:Section({ Id = "behavior", Title = "Behavior", Side = "Right", PersistControls = false })
	local function bind(section: any, method: string, path: string, config: any)
		config.Callback = function(value: any) if not self._syncing then self:SetToken(path, value) end end
		local control = section[method](section, config)
		self.Controls[path] = control
		return control
	end
	bind(appearance, "Colorpicker", "accentA", { Id = "editor-accent-a", Title = "Primary accent", Default = self.Draft.accentA })
	bind(appearance, "Slider", "opacity", { Id = "editor-opacity", Title = "Opacity", Min = 0.2, Max = 1, Step = 0.01, Default = self.Draft.opacity })
	bind(appearance, "Slider", "radius.md", { Id = "editor-rounding", Title = "Rounding", Min = 0, Max = 24, Default = self.Draft.radius.md })
	bind(appearance, "Colorpicker", "colors.background", { Id = "editor-background", Title = "Background", Default = self.Draft.colors.background })
	bind(appearance, "Colorpicker", "colors.text", { Id = "editor-text", Title = "Text", Default = self.Draft.colors.text })
	bind(appearance, "Colorpicker", "colors.textMuted", { Id = "editor-muted-text", Title = "Muted text", Default = self.Draft.colors.textMuted })
	bind(appearance, "Slider", "density", { Id = "editor-density", Title = "Density", Min = 0.7, Max = 1.4, Step = 0.05, Default = self.Draft.density })
	bind(appearance, "Slider", "textScale", { Id = "editor-text-scale", Title = "Text scale", Min = 0.8, Max = 1.4, Step = 0.05, Default = self.Draft.textScale })
	local fonts = self.Library.Fonts
	local fontControl = appearance:Dropdown({
		Id = "editor-font",
		Title = "Font",
		Choices = function() return fonts:List() end,
		Default = "Default",
		Callback = function(value: any)
			if self._syncing then return end
			local face = fonts:Resolve(value)
			if face == nil then return end
			local nextDraft = Util.deepCopy(self.Draft)
			nextDraft.fontFace = face
			nextDraft.font = fonts:Legacy(value)
			local before, beforeDetail = self.Draft, self.Detail
			local resolved = self:_validate(nextDraft)
			if resolved then
				self.Draft = resolved
				local previewed = self:_preview()
				if not previewed then self.Draft, self.Detail = before, beforeDetail end
			end
		end,
	})
	self.FontControl = fontControl
	bind(behavior, "Dropdown", "variant", { Id = "editor-variant", Title = "Variant", Choices = { "dark", "light" }, Default = self.Draft.variant })
	bind(behavior, "Toggle", "reducedMotion", { Id = "editor-reduced-motion", Title = "Reduced motion", Default = self.Draft.reducedMotion })
	bind(behavior, "Toggle", "rowLines", { Id = "editor-row-lines", Title = "Row lines", Default = self.Draft.rowLines })
	bind(behavior, "Toggle", "checkboxStyle", { Id = "editor-checkbox-style", Title = "Checkbox style", Default = self.Draft.checkboxStyle })
	bind(behavior, "Slider", "effects.glass", { Id = "editor-glass", Title = "Glass", Min = 0, Max = 1, Default = self.Draft.effects.glass })
	bind(behavior, "Slider", "effects.glow", { Id = "editor-glow", Title = "Glow", Min = 0, Max = 1, Default = self.Draft.effects.glow })
	behavior:Button({ Id = "editor-apply", Title = "Apply", Callback = function() self:Apply() end })
	behavior:Button({ Id = "editor-revert", Title = "Revert", Callback = function() self:Revert() end })
	self:_syncControls()
	behavior:Label({
		Id = "editor-contrast",
		Title = function()
			local report = self:CheckContrast()
			local lines, sources = {}, { explicit = 0, default = 0, derived = 0 }
			for _, source in pairs(report.provenance or {}) do sources[source] = (sources[source] or 0) + 1 end
			table.insert(lines, string.format("Tokens: %d explicit · %d default · %d derived", sources.explicit, sources.default, sources.derived))
			for _, row in ipairs(report.rows) do
				table.insert(lines, string.format("%s: %.2f:1 %s (%.1f:1 required)", row.role, row.ratio, if row.pass then "PASS" else "FAIL", row.required))
			end
			return table.concat(lines, "\n")
		end,
		Wrap = true,
	})
end

function ThemeEditor:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	if (not self._hasApplied or self._previewDirty) and self.Preview and self.PreviewOriginal then
		pcall(function() self.Preview:ApplyTheme(self.PreviewOriginal) end)
	end
	local library = self.Library
	if library ~= nil then
		library._themeEditors[self] = nil
		if library.Maid ~= nil then library.Maid:Remove(self) end
	end
	self.Maid:Destroy()
	if self._ownsWindow and self.Window then self.Window:Destroy() end
end

return ThemeEditor

end

__modules["ui/Factory"] = function()
--!strict

local Icons = __require("ui/Icons")
local defaultIcons = Icons.new()

local Factory = {}

export type ButtonState = "default" | "hover" | "pressed" | "focused" | "selected" | "disabled" | "danger"
export type StyleRole = "navigation" | "control" | "search" | "segment" | "ghost"

type ButtonRecord = {
	theme: any,
	role: StyleRole,
	logical: ButtonState,
	hovered: boolean,
	pressed: boolean,
	focused: boolean,
	enabled: boolean,
	stroke: UIStroke,
	scale: UIScale,
	animatePress: boolean,
	tweens: { [Instance]: Tween },
	initialized: boolean,
	connections: { RBXScriptConnection },
	cleaned: boolean,
	content: any?,
}

local records: { [TextButton]: ButtonRecord } = setmetatable({}, { __mode = "k" }) :: any
local contents: { [TextButton]: any } = setmetatable({}, { __mode = "k" }) :: any

local validStates: { [string]: boolean } = {
	default = true,
	hover = true,
	pressed = true,
	focused = true,
	selected = true,
	disabled = true,
	danger = true,
}

local validRoles: { [string]: boolean } = {
	navigation = true,
	control = true,
	segment = true,
	search = true,
	ghost = true,
}

local function fail(message: string): never
	error("Potassium Factory: " .. message, 3)
end

local function applyProperties(instance: Instance, properties: { [string]: any }?)
	if properties == nil then
		return
	end
	for property, value in pairs(properties) do
		local ok, err = pcall(function()
			(instance :: any)[property] = value
		end)
		if not ok then
			fail(string.format("cannot set property %q on %s: %s", property, instance.ClassName, tostring(err)))
		end
	end
end

local function applyThemeFont(properties: { [string]: any }, theme: any?, fallback: Enum.Font)
	if properties.Font == nil then
		properties.Font = if type(theme) == "table" and theme.font ~= nil then theme.font else fallback
	end
	if properties.FontFace == nil and type(theme) == "table" and typeof(theme.fontFace) == "Font" then
		properties.FontFace = theme.fontFace
	end
end

local function applyRoleFont(object: TextLabel | TextButton | TextBox, theme: any, role: string?)
	local font = theme.font
	if role == "strong" then
		if font == Enum.Font.BuilderSans then
			font = Enum.Font.BuilderSansBold
		elseif font == Enum.Font.Gotham then
			font = Enum.Font.GothamBold
		end
	elseif role == "medium" then
		if font == Enum.Font.BuilderSans then
			font = Enum.Font.BuilderSansMedium
		elseif font == Enum.Font.Gotham then
			font = Enum.Font.GothamMedium
		end
	end
	object.Font = font
	local face = theme.fontFace
	if typeof(face) == "Font" and role ~= nil then
		local weight = if role == "strong" then Enum.FontWeight.Bold elseif role == "medium" then Enum.FontWeight.Medium else nil
		if weight ~= nil then
			local ok, weighted = pcall(function()
				return Font.new(face.Family, weight, face.Style)
			end)
			if ok then face = weighted end
		end
	end
	if typeof(face) == "Font" then
		pcall(function()
			object.FontFace = face
		end)
	end
end
function Factory.applyTypography(object: TextLabel | TextButton | TextBox, theme: any, role: string?)
	assert(type(theme) == "table" and type(theme.typography) == "table", "Potassium Factory: typography requires a resolved theme")
	applyRoleFont(object, theme, object:GetAttribute("PotassiumFontRole"))
	local strokeTransparency = theme.typography.textStrokeTransparency
	if type(strokeTransparency) == "number" then
		object.TextStrokeColor3 = if type(theme.effects) == "table" and typeof(theme.effects.shadowColor) == "Color3"
			then theme.effects.shadowColor
			else Color3.new(0, 0, 0)
		object.TextStrokeTransparency = strokeTransparency
	end
	local selectedRole = role or object:GetAttribute("PotassiumTypographyRole")
	if type(selectedRole) ~= "string" or theme.typography[selectedRole] == nil then return end
	local lineName = "line" .. string.upper(string.sub(selectedRole, 1, 1)) .. string.sub(selectedRole, 2)
	local size, line = theme.typography[selectedRole], theme.typography[lineName]
	object:SetAttribute("PotassiumTypographyRole", selectedRole)
	object.TextSize = size * (theme.textScale or 1)
	if type(line) == "number" and size > 0 then object.LineHeight = line / size end
end


function Factory.applyProperties(instance: Instance, properties: { [string]: any }): Instance
	assert(typeof(instance) == "Instance", "Potassium Factory: applyProperties requires an Instance")
	assert(type(properties) == "table", "Potassium Factory: applyProperties requires a property table")
	applyProperties(instance, properties)
	return instance
end

function Factory.make(className: string, props: { [string]: any }?, parent: Instance?): Instance
	assert(type(className) == "string" and className ~= "", "Potassium Factory: make requires a class name")
	local instance = Instance.new(className)
	applyProperties(instance, props)
	if parent ~= nil then
		instance.Parent = parent
	end
	return instance
end

function Factory.corner(parent: Instance, radius: number?): UICorner
	assert(typeof(parent) == "Instance", "Potassium Factory: corner requires a parent Instance")
	local value = radius or 6
	assert(type(value) == "number" and value >= 0, "Potassium Factory: corner radius must be non-negative")
	return Factory.make("UICorner", { CornerRadius = UDim.new(0, value) }, parent) :: UICorner
end

function Factory.stroke(parent: Instance, color: Color3, thickness: number?): UIStroke
	assert(typeof(parent) == "Instance", "Potassium Factory: stroke requires a parent Instance")
	assert(typeof(color) == "Color3", "Potassium Factory: stroke color must be Color3")
	local width = thickness or 1
	assert(type(width) == "number" and width >= 0, "Potassium Factory: stroke thickness must be non-negative")
	return Factory.make(
		"UIStroke",
		{ Color = color, Thickness = width, ApplyStrokeMode = Enum.ApplyStrokeMode.Border },
		parent
	) :: UIStroke
end

export type SurfaceLevel = "background" | "surface" | "raised"
export type SurfaceHandle = {
	Apply: (self: SurfaceHandle, theme: any, level: SurfaceLevel?) -> (),
	Destroy: (self: SurfaceHandle) -> (),
}

local surfaceMaximum = { background = 0.30, surface = 0.26, raised = 0.20 }

function Factory.surface(parent: GuiObject, theme: any, level: SurfaceLevel, options: { [string]: any }?): SurfaceHandle
	assert(typeof(parent) == "Instance" and parent:IsA("GuiObject"), "Potassium Factory: surface requires a GuiObject")
	assert(surfaceMaximum[level] ~= nil, "Potassium Factory: unknown surface level " .. tostring(level))

	local role = if options and options.role ~= nil
		then options.role
		elseif options and options.Role ~= nil then options.Role
		else "control"
	assert(validRoles[role], "Potassium Factory: unknown surface role " .. tostring(role))
	local useBorder = (options == nil or options.border ~= false) and role ~= "navigation" and role ~= "ghost"
	local border: UIStroke? = nil
	if useBorder then
		local existingBorder = parent:FindFirstChild("PotassiumSurfaceBorder")
		if existingBorder ~= nil and not existingBorder:IsA("UIStroke") then
			fail("PotassiumSurfaceBorder must be a UIStroke")
		end
		if existingBorder == nil then
			border = Factory.make("UIStroke", {
				Name = "PotassiumSurfaceBorder",
				Thickness = 1,
				ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
			}, parent) :: UIStroke
		else
			border = existingBorder
		end
	end

	local shell = options ~= nil and options.windowShell == true
	local popout = options ~= nil and (options.popup == true or options.popout == true)
	local glassSurface = shell or options == nil or options.glass ~= false
	local glassDecorations = shell or (options ~= nil and options.glassDecorations == true)
	local destroyed = false
	local sheenLayer: Frame? = nil
	local sheen: UIGradient? = nil
	local innerHighlight: UIStroke? = nil
	local tintLayer: Frame? = nil
	local tintGradient: UIGradient? = nil
	local edgeLight: Frame? = nil

	local handle: any = {}
	function handle:Apply(nextTheme: any, nextLevel: SurfaceLevel?)
		if destroyed then
			return
		end
		local activeLevel = nextLevel or level
		local maximum = surfaceMaximum[activeLevel]
		if maximum == nil then
			fail("unknown surface level " .. tostring(activeLevel))
		end
		local opacity = math.clamp(tonumber(nextTheme.opacity) or 1, 0, 1)
		local glass = if glassSurface
			then math.clamp(tonumber(nextTheme.effects and nextTheme.effects.glass) or 0, 0, 1)
			else 0
		local tint = math.clamp(tonumber(nextTheme.effects and nextTheme.effects.glassTint) or 0, 0, 1)
		local borderAmount = math.clamp(tonumber(nextTheme.effects and nextTheme.effects.glassBorder) or 0, 0, 1)
		local frost = math.clamp(tonumber(nextTheme.effects and nextTheme.effects.glassFrost) or 0, 0, 1)
		local colorKey = if popout
			then "popup"
			elseif activeLevel == "background" then "background"
			elseif activeLevel == "raised" then "surfaceRaised"
			else "surface"
		local borderKey = if activeLevel == "background" then "borderStrong" else "border"
		local baseColor = nextTheme.colors[colorKey]
		parent.BackgroundColor3 = if glass > 0
			then baseColor:Lerp(nextTheme.accentA, glass * tint * 0.12)
			else baseColor
		parent.BackgroundTransparency = if role == "ghost"
			then 1
			else math.clamp(1 - opacity * (1 - glass * maximum), 0, 1)
		if border ~= nil then
			border.Color = if popout
				then nextTheme.colors.borderStrong:Lerp(nextTheme.accentA, 0.52)
				elseif glass > 0 then nextTheme.colors[borderKey]:Lerp(nextTheme.colors.text, glass * borderAmount * 0.16)
				else nextTheme.colors[borderKey]
			border.Thickness = nextTheme.metrics.borderWidth
			border.Transparency = if popout
				then 0.78
				elseif glass > 0 then math.clamp(0.9 - glass * borderAmount * 0.45, 0.35, 0.92)
				elseif role == "segment" then 0.35
				else 0.55
		end

		local frostStrength = glass * tint * frost
		if glassDecorations and frostStrength > 0 and tintLayer == nil then
			tintLayer = Factory.make("Frame", {
				Name = "PotassiumGlassTintLayer",
				BackgroundColor3 = nextTheme.colors.surfaceRaised,
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Active = false,
				Size = UDim2.fromScale(1, 1),
				ZIndex = parent.ZIndex,
			}, parent) :: Frame
			Factory.corner(tintLayer, nextTheme.radius.lg)
			tintGradient = Factory.make("UIGradient", {
				Name = "PotassiumGlassTintGradient",
				Rotation = 32,
			}, tintLayer) :: UIGradient
			edgeLight = Factory.make("Frame", {
				Name = "PotassiumGlassEdgeLight",
				BackgroundColor3 = nextTheme.colors.text,
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Active = false,
				Position = UDim2.fromOffset(1, 0),
				Size = UDim2.new(1, -2, 0, 1),
				ZIndex = parent.ZIndex + 1,
			}, parent) :: Frame
		end
		if tintLayer ~= nil then
			local frosted = frostStrength > 0
			tintLayer.Visible = frosted
			tintLayer.Active = false
			tintLayer.Size = UDim2.fromScale(1, 1)
			tintLayer.ZIndex = parent.ZIndex
			tintLayer.BackgroundColor3 = if popout
				then baseColor:Lerp(nextTheme.accentA, 0.05)
				else baseColor:Lerp(nextTheme.colors.surfaceRaised, 0.42)
			tintLayer.BackgroundTransparency = math.clamp(0.94 - frostStrength * 1.55, 0.58, 0.98)
			local corner = tintLayer:FindFirstChildOfClass("UICorner")
			if corner then corner.CornerRadius = UDim.new(0, nextTheme.radius.lg) end
		end
		if tintGradient ~= nil then
			local frosted = frostStrength > 0
			tintGradient.Enabled = frosted
			tintGradient.Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, baseColor:Lerp(nextTheme.accentA, 0.12)),
				ColorSequenceKeypoint.new(0.48, nextTheme.colors.surfaceRaised:Lerp(nextTheme.accentA, 0.06)),
				ColorSequenceKeypoint.new(1, baseColor:Lerp(nextTheme.accentB, 0.09)),
			})
			tintGradient.Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, math.clamp(0.12 - frostStrength * 0.28, 0.04, 0.18)),
				NumberSequenceKeypoint.new(0.46, math.clamp(0.38 - frostStrength * 0.45, 0.18, 0.42)),
				NumberSequenceKeypoint.new(0.72, math.clamp(0.18 - frostStrength * 0.32, 0.06, 0.24)),
				NumberSequenceKeypoint.new(1, math.clamp(0.42 - frostStrength * 0.5, 0.2, 0.46)),
			})
		end
		if edgeLight ~= nil then
			local frosted = frostStrength > 0
			edgeLight.Visible = frosted
			edgeLight.Active = false
			edgeLight.BackgroundColor3 = nextTheme.colors.text:Lerp(nextTheme.accentA, 0.08)
			edgeLight.BackgroundTransparency = math.clamp(0.94 - frostStrength * 0.72, 0.78, 0.98)
			edgeLight.ZIndex = parent.ZIndex + 1
		end

		if glassDecorations and glass > 0 and sheenLayer == nil then
			sheenLayer = Factory.make("Frame", {
				Name = "PotassiumGlassSheenLayer",
				BackgroundColor3 = nextTheme.colors.text,
				BackgroundTransparency = 0,
				BorderSizePixel = 0,
				Active = false,
				Size = UDim2.new(1, 0, 0.42, 0),
				ZIndex = parent.ZIndex,
			}, parent) :: Frame
			Factory.corner(sheenLayer, nextTheme.radius.lg)
			sheen = Factory.make("UIGradient", {
				Name = "PotassiumGlassSheen",
				Rotation = 90,
			}, sheenLayer) :: UIGradient
			innerHighlight = Factory.make("UIStroke", {
				Name = "PotassiumGlassInnerHighlight",
				Thickness = 1,
				ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
			}, parent) :: UIStroke
		end
		if sheenLayer ~= nil then
			sheenLayer.Visible = glass > 0
			sheenLayer.BackgroundColor3 = nextTheme.colors.text
			sheenLayer.Size = UDim2.new(1, 0, 0.42, 0)
			sheenLayer.ZIndex = parent.ZIndex
			local corner = sheenLayer:FindFirstChildOfClass("UICorner")
			if corner then corner.CornerRadius = UDim.new(0, nextTheme.radius.lg) end
		end
		if sheen ~= nil then
			sheen.Enabled = glass > 0
			sheen.Color = ColorSequence.new(nextTheme.colors.text, baseColor)
			sheen.Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, math.clamp(0.93 - glass * tint * 0.1, 0.82, 0.98)),
				NumberSequenceKeypoint.new(0.45, 0.975),
				NumberSequenceKeypoint.new(1, 1),
			})
		end
		if innerHighlight ~= nil then
			innerHighlight.Enabled = glass > 0
			innerHighlight.Color = nextTheme.colors.text
			innerHighlight.Transparency = math.clamp(0.98 - glass * borderAmount * 0.18, 0.72, 1)
		end
	end
	function handle:Destroy()
		if destroyed then
			return
		end
		destroyed = true
		if sheenLayer then
			sheenLayer:Destroy()
		end
		if innerHighlight then
			innerHighlight:Destroy()
		end
		if tintLayer then
			tintLayer:Destroy()
		end
		if edgeLight then
			edgeLight:Destroy()
		end
		if border then
			border:Destroy()
		end
	end
	handle:Apply(theme, level)
	return handle :: SurfaceHandle
end

export type WindowShadowHandle = {
	Apply: (self: WindowShadowHandle, theme: any) -> (),
	Destroy: (self: WindowShadowHandle) -> (),
}

local SHADOW_LAYERS = {
	{ name = "Contact", spread = 4 / 32, offset = 3 / 20, opacity = 0.24, stroke = 0.12 },
	{ name = "Ambient", spread = 16 / 32, offset = 10 / 20, opacity = 0.13, stroke = 0.08 },
	{ name = "Far", spread = 1, offset = 1, opacity = 0.065, stroke = 0.04 },
}

function Factory.windowShadow(frame: GuiObject, theme: any): WindowShadowHandle
	assert(typeof(frame) == "Instance" and frame:IsA("GuiObject"), "Potassium Factory: windowShadow requires a GuiObject")

	local destroyed = false
	local currentTheme = theme
	local root: Frame? = nil
	local rootScale: UIScale? = nil
	local layers: { [string]: Frame } = {}
	local accentLayer: Frame? = nil
	local connections: { RBXScriptConnection } = {}

	local function clearVisuals()
		if root ~= nil then
			root:Destroy()
		end
		root, rootScale, accentLayer = nil, nil, nil
		table.clear(layers)
	end

	local function syncFrame()
		if root == nil then
			return
		end
		root.AnchorPoint = frame.AnchorPoint
		root.Position = frame.Position
		root.Size = frame.Size
		root.Visible = frame.Visible
		root.ZIndex = math.max(0, frame.ZIndex - 4)
		if root.Parent ~= frame.Parent then
			root.Parent = frame.Parent
		end
		local sourceScale = frame:FindFirstChildOfClass("UIScale")
		if rootScale ~= nil then
			rootScale.Scale = if sourceScale ~= nil then sourceScale.Scale else 1
		end
	end

	local function makeLayer(name: string): Frame
		local layer = Factory.make("Frame", {
			Name = "PotassiumWindowShadow" .. name,
			Active = false,
			Selectable = false,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ClipsDescendants = false,
		}, root) :: Frame
		layer:SetAttribute("PotassiumShadowRole", name)
		Factory.corner(layer, 0)
		Factory.make("UIStroke", {
			Name = "PotassiumShadowSoftEdge",
			ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
			LineJoinMode = Enum.LineJoinMode.Round,
			Transparency = 1,
		}, layer)
		return layer
	end

	local function ensureVisuals()
		if root ~= nil then
			return
		end
		root = Factory.make("Frame", {
			Name = "PotassiumWindowShadow",
			Active = false,
			Selectable = false,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ClipsDescendants = false,
		}) :: Frame
		rootScale = Factory.make("UIScale", { Scale = 1 }, root) :: UIScale
		for _, specification in ipairs(SHADOW_LAYERS) do
			layers[specification.name] = makeLayer(specification.name)
		end
		syncFrame()
	end

	local handle: any = {}
	function handle:Apply(nextTheme: any)
		if destroyed then
			return
		end
		currentTheme = nextTheme
		local effects = nextTheme.effects or {}
		local amount = math.clamp(tonumber(effects.shadow) or 0, 0, 1)
		if amount <= 0 then
			clearVisuals()
			return
		end
		ensureVisuals()
		syncFrame()

		local maximumSpread = math.clamp(tonumber(effects.shadowSpread) or 32, 0, 32)
		local maximumOffset = if typeof(effects.shadowOffset) == "Vector2"
			then effects.shadowOffset
			else Vector2.new(0, 20)
		local shadowColor = if typeof(effects.shadowColor) == "Color3"
			then effects.shadowColor
			else Color3.fromRGB(0, 0, 0)
		local targetCorner = frame:FindFirstChildOfClass("UICorner")
		local radius = if targetCorner ~= nil
			then math.max(0, targetCorner.CornerRadius.Offset)
			else math.max(0, tonumber(nextTheme.radius and nextTheme.radius.lg) or 0)
		for index, specification in ipairs(SHADOW_LAYERS) do
			local layer = layers[specification.name]
			local spread = maximumSpread * specification.spread
			local offset = maximumOffset * specification.offset
			layer.Position = UDim2.fromOffset(-spread + offset.X, -spread + offset.Y)
			layer.Size = UDim2.new(1, spread * 2, 1, spread * 2)
			layer.ZIndex = math.max(0, frame.ZIndex - index)
			layer.BackgroundColor3 = shadowColor
			layer.BackgroundTransparency = 1 - amount * specification.opacity
			layer:SetAttribute("PotassiumShadowSpread", spread)
			layer:SetAttribute("PotassiumShadowOffsetX", offset.X)
			layer:SetAttribute("PotassiumShadowOffsetY", offset.Y)
			local corner = layer:FindFirstChildOfClass("UICorner")
			if corner ~= nil then
				corner.CornerRadius = UDim.new(0, radius + spread)
			end
			local stroke = layer:FindFirstChild("PotassiumShadowSoftEdge")
			if stroke ~= nil and stroke:IsA("UIStroke") then
				stroke.Color = shadowColor
				stroke.Thickness = math.max(1, spread * 0.35)
				stroke.Transparency = 1 - amount * specification.stroke
			end
		end

		local accentGlow = math.clamp(tonumber(effects.accentGlow) or 0, 0, 1)
		if accentGlow > 0 and accentLayer == nil then
			accentLayer = makeLayer("AccentGlow")
		elseif accentGlow <= 0 and accentLayer ~= nil then
			accentLayer:Destroy()
			accentLayer = nil
		end
		if accentLayer ~= nil then
			local spread = math.min(maximumSpread, math.max(4, maximumSpread * 0.5))
			accentLayer.Position = UDim2.fromOffset(-spread, -spread)
			accentLayer.Size = UDim2.new(1, spread * 2, 1, spread * 2)
			accentLayer.ZIndex = math.max(0, frame.ZIndex - 4)
			accentLayer.BackgroundColor3 = nextTheme.accentA
			accentLayer.BackgroundTransparency = 1 - accentGlow * 0.055
			accentLayer:SetAttribute("PotassiumShadowSpread", spread)
			accentLayer:SetAttribute("PotassiumShadowOffsetX", 0)
			accentLayer:SetAttribute("PotassiumShadowOffsetY", 0)
			local corner = accentLayer:FindFirstChildOfClass("UICorner")
			if corner ~= nil then
				corner.CornerRadius = UDim.new(0, radius + spread)
			end
			local stroke = accentLayer:FindFirstChild("PotassiumShadowSoftEdge")
			if stroke ~= nil and stroke:IsA("UIStroke") then
				stroke.Color = nextTheme.accentA
				stroke.Thickness = math.max(1, spread * 0.4)
				stroke.Transparency = 1 - accentGlow * 0.1
			end
		end
	end

	function handle:Destroy()
		if destroyed then
			return
		end
		destroyed = true
		for _, connection in ipairs(connections) do
			connection:Disconnect()
		end
		table.clear(connections)
		clearVisuals()
	end

	table.insert(connections, frame.Destroying:Connect(function()
		handle:Destroy()
	end))
	for _, property in ipairs({ "AnchorPoint", "Position", "Size", "Visible", "ZIndex", "Parent" }) do
		table.insert(connections, frame:GetPropertyChangedSignal(property):Connect(syncFrame))
	end
	local sourceScale = frame:FindFirstChildOfClass("UIScale")
	if sourceScale ~= nil then
		table.insert(connections, sourceScale:GetPropertyChangedSignal("Scale"):Connect(syncFrame))
	end
	handle:Apply(currentTheme)
	return handle :: WindowShadowHandle
end

export type WindowGlowSnapshot = {
	glow: number,
	glowColor: Color3,
	glowSpread: number,
	glowSoftness: number,
	glowStyle: "soft" | "edge",
	glowEdgeLength: number,
	glowThickness: number,
	style: "soft" | "edge",
	edgeLength: number,
	layers: number,
	roles: { string },
	edgeRoles: { string },
	spreads: { number },
	transparencies: { number },
	railLengths: { number },
	haloTransparencies: { number },
	zIndex: number?,
}

export type WindowGlowHandle = {
	Apply: (self: WindowGlowHandle, theme: any) -> (),
	Snapshot: (self: WindowGlowHandle) -> WindowGlowSnapshot,
	Destroy: (self: WindowGlowHandle) -> (),
}

local SOFT_GLOW_LAYERS = {
	{ name = "Inner", ratio = 2 / 24, opacity = 0.18, backgroundBlend = 0.02 },
	{ name = "Near", ratio = 4 / 24, opacity = 0.145, backgroundBlend = 0.05 },
	{ name = "MidInner", ratio = 7 / 24, opacity = 0.11, backgroundBlend = 0.08 },
	{ name = "Mid", ratio = 10 / 24, opacity = 0.08, backgroundBlend = 0.12 },
	{ name = "MidOuter", ratio = 14 / 24, opacity = 0.055, backgroundBlend = 0.16 },
	{ name = "Far", ratio = 18 / 24, opacity = 0.034, backgroundBlend = 0.2 },
	{ name = "Outer", ratio = 1, opacity = 0.016, backgroundBlend = 0.24 },
}

local COMPACT_GLOW_LAYERS = {
	{ name = "Inner", ratio = 2 / 24, opacity = 0.16, backgroundBlend = 0.04 },
	{ name = "Mid", ratio = 10 / 24, opacity = 0.07, backgroundBlend = 0.13 },
	{ name = "Outer", ratio = 1, opacity = 0.018, backgroundBlend = 0.22 },
}

local EDGE_RAILS = {
	{ name = "TopRail", side = "top", horizontal = true },
	{ name = "RightRail", side = "right", horizontal = false },
	{ name = "BottomRail", side = "bottom", horizontal = true },
	{ name = "LeftRail", side = "left", horizontal = false },
}

local EDGE_HALO_BANDS = {
	{ name = "Inner", ratio = 0.2, opacity = 0.18 },
	{ name = "Mid", ratio = 0.4, opacity = 0.08 },
	{ name = "Outer", ratio = 0.7, opacity = 0.026 },
}

local EDGE_GRADIENT_FADE_BOTH = NumberSequence.new({
	NumberSequenceKeypoint.new(0, 1),
	NumberSequenceKeypoint.new(0.12, 0.32),
	NumberSequenceKeypoint.new(0.26, 0),
	NumberSequenceKeypoint.new(0.74, 0),
	NumberSequenceKeypoint.new(0.88, 0.32),
	NumberSequenceKeypoint.new(1, 1),
})
local EDGE_GRADIENT_TO_CORNER = NumberSequence.new({
	NumberSequenceKeypoint.new(0, 1),
	NumberSequenceKeypoint.new(0.14, 0.3),
	NumberSequenceKeypoint.new(0.3, 0),
	NumberSequenceKeypoint.new(1, 0),
})
local EDGE_GRADIENT_FROM_CORNER = NumberSequence.new({
	NumberSequenceKeypoint.new(0, 0),
	NumberSequenceKeypoint.new(0.7, 0),
	NumberSequenceKeypoint.new(0.86, 0.3),
	NumberSequenceKeypoint.new(1, 1),
})

local function applyExpandedGeometry(object: GuiObject, spread: number)
	object.Position = UDim2.fromOffset(-spread, -spread)
	object.Size = UDim2.new(1, spread * 2, 1, spread * 2)
end

local function glowLayerSpread(maximumSpread: number, ratio: number, softness: number): number
	local exponent = if softness >= 0.5
		then 1 + (1 - softness) * 0.7
		else 1.35 + (0.5 - softness) * 0.6
	return maximumSpread * ratio ^ exponent
end

local function edgeRailStart(side: string, edgeLength: number): number
	if side == "top" or side == "left" then
		return 1 - edgeLength
	end
	return 0
end

local function applyEdgeGeometry(object: Frame, side: string, edgeLength: number, thickness: number, halo: boolean)
	local start = edgeRailStart(side, edgeLength)
	if side == "top" then
		object.Position = UDim2.new(start, 0, 0, if halo then -thickness else 0)
		object.Size = UDim2.new(edgeLength, 0, 0, thickness)
	elseif side == "bottom" then
		object.Position = UDim2.new(start, 0, 1, if halo then 0 else -thickness)
		object.Size = UDim2.new(edgeLength, 0, 0, thickness)
	elseif side == "left" then
		object.Position = UDim2.new(0, if halo then -thickness else 0, start, 0)
		object.Size = UDim2.new(0, thickness, edgeLength, 0)
	else
		object.Position = UDim2.new(1, if halo then 0 else -thickness, start, 0)
		object.Size = UDim2.new(0, thickness, edgeLength, 0)
	end
end
function Factory.windowGlow(frame: GuiObject, theme: any): WindowGlowHandle
	assert(typeof(frame) == "Instance" and frame:IsA("GuiObject"), "Potassium Factory: windowGlow requires a GuiObject")

	local destroyed = false
	local currentTheme = theme
	local currentSpecifications: { any } = SOFT_GLOW_LAYERS
	local visualBucket: string? = nil
	local root: Frame? = nil
	local rootScale: UIScale? = nil
	local layers: { [string]: Frame } = {}
	local roleOrder: { string } = {}
	local edgeRoles: { string } = {}
	local connections: { RBXScriptConnection } = {}
	local scaleConnection: RBXScriptConnection? = nil

	local function clearVisuals()
		if root ~= nil then
			root:Destroy()
		end
		root, rootScale, visualBucket = nil, nil, nil
		table.clear(layers)
		table.clear(roleOrder)
		table.clear(edgeRoles)
	end

	local function syncScale()
		local sourceScale = frame:FindFirstChildOfClass("UIScale")
		if rootScale ~= nil then
			rootScale.Scale = if sourceScale ~= nil then sourceScale.Scale else 1
		end
	end

	local function refreshScaleConnection()
		if scaleConnection ~= nil then
			scaleConnection:Disconnect()
			scaleConnection = nil
		end
		local sourceScale = frame:FindFirstChildOfClass("UIScale")
		if sourceScale ~= nil then
			scaleConnection = sourceScale:GetPropertyChangedSignal("Scale"):Connect(syncScale)
		end
		syncScale()
	end

	local function syncFrame()
		if root == nil then
			return
		end
		root.AnchorPoint = frame.AnchorPoint
		root.Position = frame.Position
		root.Size = frame.Size
		root.Visible = frame.Visible
		root.ZIndex = math.max(0, frame.ZIndex - 1)
		for _, object in pairs(layers) do
			object.ZIndex = root.ZIndex
		end
		if root.Parent ~= frame.Parent then
			root.Parent = frame.Parent
		end
		syncScale()
	end

	local function makeLayer(name: string): Frame
		local object = Factory.make("Frame", {
			Name = "PotassiumWindowGlow" .. name,
			Active = false,
			Selectable = false,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ClipsDescendants = false,
		}, root) :: Frame
		object:SetAttribute("PotassiumGlowRole", name)
		layers[name] = object
		table.insert(roleOrder, name)
		return object
	end

	local function makeEdgeGradient(object: Frame, side: string)
		local horizontal = side == "top" or side == "bottom"
		local transparency = if side == "top" or side == "left"
			then EDGE_GRADIENT_TO_CORNER
			else EDGE_GRADIENT_FROM_CORNER
		Factory.make("UIGradient", {
			Name = "PotassiumGlowEndpointFade",
			Rotation = if horizontal then 0 else 90,
			Transparency = transparency,
		}, object)
	end

	local function makeRoot(bucket: string, layerCount: number)
		visualBucket = bucket
		root = Factory.make("Frame", {
			Name = "PotassiumWindowGlow",
			Active = false,
			Selectable = false,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ClipsDescendants = false,
		}) :: Frame
		root:SetAttribute("PotassiumGlowLayers", layerCount)
		root:SetAttribute("PotassiumGlowSoftnessBucket", bucket)
		root:SetAttribute("PotassiumGlowStyle", if bucket == "edge" then "edge" else "soft")
		rootScale = Factory.make("UIScale", { Scale = 1 }, root) :: UIScale
	end

	local function ensureSoftVisuals(bucket: string, specifications: { any })
		if root ~= nil and visualBucket == bucket then
			return
		end
		clearVisuals()
		currentSpecifications = specifications
		makeRoot(bucket, #specifications)
		for index = #specifications, 1, -1 do
			local specification = specifications[index]
			local object = makeLayer(specification.name)
			Factory.corner(object, 0)
		end
		table.clear(roleOrder)
		for _, specification in ipairs(specifications) do
			table.insert(roleOrder, specification.name)
		end
		local inner = layers[specifications[1].name]
		Factory.make("UIStroke", {
			Name = "PotassiumGlowInnerEdge",
			ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
			LineJoinMode = Enum.LineJoinMode.Round,
			Thickness = 1,
			Transparency = 1,
		}, inner)
		syncFrame()
	end

	local function ensureEdgeVisuals()
		if root ~= nil and visualBucket == "edge" then
			return
		end
		clearVisuals()
		currentSpecifications = {}
		makeRoot("edge", 17)
		local core = makeLayer("Core")
		Factory.corner(core, 0)
		Factory.make("UIStroke", {
			Name = "PotassiumGlowCoreBorder",
			ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
			LineJoinMode = Enum.LineJoinMode.Round,
			Thickness = 1,
			Transparency = 1,
		}, core)
		for _, rail in ipairs(EDGE_RAILS) do
			local railObject = makeLayer(rail.name)
			table.insert(edgeRoles, rail.name)
			makeEdgeGradient(railObject, rail.side)
			for _, band in ipairs(EDGE_HALO_BANDS) do
				local haloName = string.gsub(rail.name, "Rail$", "Halo" .. band.name)
				local halo = makeLayer(haloName)
				makeEdgeGradient(halo, rail.side)
			end
		end
		syncFrame()
	end

	local handle: any = {}
	function handle:Apply(nextTheme: any)
		if destroyed then
			return
		end
		currentTheme = nextTheme
		local effects = nextTheme.effects or {}
		local amount = math.clamp(tonumber(effects.glow) or 0, 0, 1)
		if amount <= 0 then
			clearVisuals()
			return
		end
		local softness = math.clamp(tonumber(effects.glowSoftness) or 0.65, 0, 1)
		local style = if effects.glowStyle == "edge" then "edge" else "soft"
		local maximumSpread = math.clamp(tonumber(effects.glowSpread) or 12, 0, 24)
		local edgeLength = math.clamp(tonumber(effects.glowEdgeLength) or 0.55, 0.2, 0.9)
		local edgeThickness = math.clamp(math.floor(tonumber(effects.glowThickness) or 1), 1, 4)
		local color = if typeof(effects.glowColor) == "Color3" then effects.glowColor else nextTheme.accentA
		local radius = math.max(0, tonumber(nextTheme.radius and nextTheme.radius.lg) or 0)
		if style == "edge" then
			ensureEdgeVisuals()
			syncFrame()
			local core = layers.Core
			core.Position = UDim2.fromScale(0, 0)
			core.Size = UDim2.fromScale(1, 1)
			core:SetAttribute("PotassiumGlowSpread", 0)
			local coreCorner = core:FindFirstChildOfClass("UICorner")
			if coreCorner ~= nil then
				coreCorner.CornerRadius = UDim.new(0, radius)
			end
			local coreStroke = core:FindFirstChild("PotassiumGlowCoreBorder")
			local coreTransparency = 1 - amount * 0.28
			if coreStroke ~= nil and coreStroke:IsA("UIStroke") then
				coreStroke.Color = color
				coreStroke.Transparency = coreTransparency
				coreStroke.Thickness = edgeThickness
			end
			core:SetAttribute("PotassiumGlowTransparency", coreTransparency)
			local thicknessFactor = 0.72 + softness * 0.28
			local opacityFactor = 0.68 + softness * 0.32
			for _, rail in ipairs(EDGE_RAILS) do
				local railObject = layers[rail.name]
				applyEdgeGeometry(railObject, rail.side, edgeLength, edgeThickness, false)
				railObject.BackgroundColor3 = color
				railObject.BackgroundTransparency = 1 - amount * 0.82
				railObject:SetAttribute("PotassiumGlowSpread", 0)
				railObject:SetAttribute("PotassiumGlowTransparency", railObject.BackgroundTransparency)
				railObject:SetAttribute("PotassiumGlowEdgeLength", edgeLength)
				railObject:SetAttribute("PotassiumGlowRailThickness", edgeThickness)
				for _, band in ipairs(EDGE_HALO_BANDS) do
					local haloName = string.gsub(rail.name, "Rail$", "Halo" .. band.name)
					local halo = layers[haloName]
					local thickness = maximumSpread * band.ratio * thicknessFactor
					local transparency = 1 - amount * band.opacity * opacityFactor
					applyEdgeGeometry(halo, rail.side, edgeLength, thickness, true)
					halo.BackgroundColor3 = color
					halo.BackgroundTransparency = transparency
					halo:SetAttribute("PotassiumGlowSpread", thickness)
					halo:SetAttribute("PotassiumGlowTransparency", transparency)
					halo:SetAttribute("PotassiumGlowEdgeLength", edgeLength)
				end
			end
			return
		end

		local bucket = if softness >= 0.5 then "soft" else "compact"
		local specifications = if bucket == "soft" then SOFT_GLOW_LAYERS else COMPACT_GLOW_LAYERS
		ensureSoftVisuals(bucket, specifications)
		syncFrame()
		local background = if nextTheme.colors and typeof(nextTheme.colors.background) == "Color3"
			then nextTheme.colors.background
			else color
		for _, specification in ipairs(specifications) do
			local object = layers[specification.name]
			local spread = glowLayerSpread(maximumSpread, specification.ratio, softness)
			local transparency = 1 - amount * specification.opacity
			applyExpandedGeometry(object, spread)
			object.ZIndex = math.max(0, frame.ZIndex - 1)
			object.BackgroundColor3 = color:Lerp(background, specification.backgroundBlend)
			object.BackgroundTransparency = transparency
			object:SetAttribute("PotassiumGlowSpread", spread)
			object:SetAttribute("PotassiumGlowTransparency", transparency)
			local corner = object:FindFirstChildOfClass("UICorner")
			if corner ~= nil then
				corner.CornerRadius = UDim.new(0, radius + spread)
			end
		end
		local innerEdge = layers[specifications[1].name]:FindFirstChild("PotassiumGlowInnerEdge")
		if innerEdge ~= nil and innerEdge:IsA("UIStroke") then
			innerEdge.Color = color:Lerp(background, 0.04)
			innerEdge.Transparency = 1 - amount * 0.11
		end
	end

	function handle:Snapshot(): WindowGlowSnapshot
		local effects = currentTheme.effects or {}
		local style = if effects.glowStyle == "edge" then "edge" else "soft"
		local edgeLength = math.clamp(tonumber(effects.glowEdgeLength) or 0.55, 0.2, 0.9)
		local roles = {}
		local spreads = {}
		local transparencies = {}
		local railLengths = {}
		local haloTransparencies = {}
		if root ~= nil then
			for _, role in ipairs(roleOrder) do
				local object = layers[role]
				table.insert(roles, role)
				table.insert(spreads, object:GetAttribute("PotassiumGlowSpread") or 0)
				table.insert(transparencies, object:GetAttribute("PotassiumGlowTransparency") or object.BackgroundTransparency)
				if string.find(role, "Rail$", 1) ~= nil then
					table.insert(railLengths, object:GetAttribute("PotassiumGlowEdgeLength"))
				elseif string.find(role, "Halo", 1, true) ~= nil then
					table.insert(haloTransparencies, object.BackgroundTransparency)
				end
			end
		end
		return {
			glow = math.clamp(tonumber(effects.glow) or 0, 0, 1),
			glowColor = if typeof(effects.glowColor) == "Color3" then effects.glowColor else currentTheme.accentA,
			glowSpread = math.clamp(tonumber(effects.glowSpread) or 12, 0, 24),
			glowSoftness = math.clamp(tonumber(effects.glowSoftness) or 0.65, 0, 1),
			glowStyle = style,
			glowEdgeLength = edgeLength,
			glowThickness = math.clamp(math.floor(tonumber(effects.glowThickness) or 1), 1, 4),
			style = style,
			edgeLength = edgeLength,
			layers = #roles,
			roles = roles,
			edgeRoles = table.clone(edgeRoles),
			spreads = spreads,
			transparencies = transparencies,
			railLengths = railLengths,
			haloTransparencies = haloTransparencies,
			zIndex = if root ~= nil then root.ZIndex else nil,
		}
	end

	function handle:Destroy()
		if destroyed then
			return
		end
		destroyed = true
		if scaleConnection ~= nil then
			scaleConnection:Disconnect()
			scaleConnection = nil
		end
		for _, connection in ipairs(connections) do
			connection:Disconnect()
		end
		table.clear(connections)
		clearVisuals()
	end

	table.insert(connections, frame.Destroying:Connect(function()
		handle:Destroy()
	end))

	for _, property in ipairs({ "AnchorPoint", "Position", "Size", "Visible", "ZIndex", "Parent" }) do
		table.insert(connections, frame:GetPropertyChangedSignal(property):Connect(syncFrame))
	end
	table.insert(connections, frame.ChildAdded:Connect(function(child)
		if child:IsA("UIScale") then
			refreshScaleConnection()
		end
	end))
	table.insert(connections, frame.ChildRemoved:Connect(function(child)
		if child:IsA("UIScale") then
			refreshScaleConnection()
		end
	end))
	refreshScaleConnection()
	handle:Apply(currentTheme)
	return handle :: WindowGlowHandle
end

function Factory.padding(parent: Instance, value: number | UDim): UIPadding
	assert(typeof(parent) == "Instance", "Potassium Factory: padding requires a parent Instance")
	local inset = if typeof(value) == "UDim" then value else UDim.new(0, value)
	if typeof(value) ~= "UDim" then
		assert(type(value) == "number" and value >= 0, "Potassium Factory: padding must be non-negative")
	end
	return Factory.make("UIPadding", {
		PaddingTop = inset,
		PaddingRight = inset,
		PaddingBottom = inset,
		PaddingLeft = inset,
	}, parent) :: UIPadding
end

function Factory.list(parent: Instance, padding: number?, horizontal: boolean?): UIListLayout
	local gap = padding or 0
	assert(type(gap) == "number" and gap >= 0, "Potassium Factory: list padding must be non-negative")
	return Factory.make("UIListLayout", {
		FillDirection = if horizontal then Enum.FillDirection.Horizontal else Enum.FillDirection.Vertical,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, gap),
		HorizontalAlignment = Enum.HorizontalAlignment.Left,
		VerticalAlignment = Enum.VerticalAlignment.Top,
	}, parent) :: UIListLayout
end

function Factory.grid(
	parent: Instance,
	cellSize: UDim2,
	cellPadding: UDim2?,
	fillDirectionMaxCells: number?
): UIGridLayout
	assert(typeof(cellSize) == "UDim2", "Potassium Factory: grid cellSize must be UDim2")
	local columns = fillDirectionMaxCells or 1
	assert(
		type(columns) == "number" and columns >= 1 and columns % 1 == 0,
		"Potassium Factory: grid column count must be a positive integer"
	)
	return Factory.make("UIGridLayout", {
		CellSize = cellSize,
		CellPadding = cellPadding or UDim2.new(),
		FillDirectionMaxCells = columns,
		SortOrder = Enum.SortOrder.LayoutOrder,
		HorizontalAlignment = Enum.HorizontalAlignment.Left,
		VerticalAlignment = Enum.VerticalAlignment.Top,
	}, parent) :: UIGridLayout
end

function Factory.text(parent: Instance, text: string, size: number, color: Color3, props: { [string]: any }?): TextLabel
	assert(type(text) == "string", "Potassium Factory: text must be a string")
	assert(type(size) == "number" and size > 0, "Potassium Factory: text size must be positive")
	local merged: { [string]: any } = {
		BackgroundTransparency = 1,
		Text = text,
		TextColor3 = color,
		TextSize = size,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}
	local theme = if props ~= nil then props.theme else nil
	local fontRole = if props ~= nil then props.fontRole else nil
	local typographyRole = if props ~= nil then props.typographyRole else nil
	if typographyRole == nil and type(theme) == "table" and type(theme.typography) == "table" then
		for _, role in ipairs({ "caption", "body", "label", "title", "heading" }) do
			if math.abs(size - theme.typography[role] * (theme.textScale or 1)) < 0.01 then
				typographyRole = role
				break
			end
		end
	end
	for key, value in pairs(props or {}) do
		if key ~= "theme" and key ~= "fontRole" and key ~= "typographyRole" then
			merged[key] = value
		end
	end
	if merged.LineHeight == nil and typographyRole ~= nil and type(theme) == "table" then
		local line = theme.typography["line" .. string.upper(string.sub(typographyRole, 1, 1)) .. string.sub(typographyRole, 2)]
		local base = theme.typography[typographyRole]
		if type(line) == "number" and type(base) == "number" and base > 0 then merged.LineHeight = line / base end
	end
	applyThemeFont(merged, theme, Enum.Font.BuilderSans)
	local label = Factory.make("TextLabel", merged) :: TextLabel
	if type(theme) == "table" then
		label:SetAttribute("PotassiumFontRole", fontRole or "regular")
		Factory.applyTypography(label, theme, typographyRole)
	end
	label.Parent = parent
	return label
end

function Factory.wrappedText(
	parent: Instance,
	text: string,
	size: number,
	color: Color3,
	props: { [string]: any }?
): TextLabel
	local merged: { [string]: any } = {}
	for key, value in pairs(props or {}) do
		merged[key] = value
	end
	merged.TextWrapped = true
	merged.TextTruncate = Enum.TextTruncate.None
	return Factory.text(parent, text, size, color, merged)
end

function Factory.automaticText(
	parent: Instance,
	text: string,
	size: number,
	color: Color3,
	props: { [string]: any }?
): TextLabel
	local merged: { [string]: any } = {}
	for key, value in pairs(props or {}) do
		merged[key] = value
	end
	if merged.AutomaticSize == nil then
		merged.AutomaticSize = Enum.AutomaticSize.Y
	end
	if merged.TextWrapped == nil then
		merged.TextWrapped = true
		merged.TextTruncate = Enum.TextTruncate.None
	end
	return Factory.text(parent, text, size, color, merged)
end

export type ButtonContentHandle = {
	Root: Frame,
	Label: TextLabel,
	IconSlot: Frame?,
	Icon: Frame?,
	Apply: (self: ButtonContentHandle, theme: any?, options: { [string]: any }?) -> (),
	SetText: (self: ButtonContentHandle, text: string) -> (),
	Destroy: (self: ButtonContentHandle) -> (),
}

local function composedInsets(value: any): (number, number, number, number)
	if type(value) == "number" then
		return value, value, value, value
	end
	if typeof(value) == "Vector2" then
		return value.X, value.Y, value.X, value.Y
	end
	if type(value) == "table" then
		return value.left or value.Left or 0,
			value.top or value.Top or 0,
			value.right or value.Right or 0,
			value.bottom or value.Bottom or 0
	end
	return 0, 0, 0, 0
end

local function recolorComposedIcon(icon: Frame?, color: Color3)
	if icon == nil then
		return
	end
	for _, object in ipairs(icon:GetDescendants()) do
		if object:IsA("Frame") and object.BackgroundTransparency < 1 then
			object.BackgroundColor3 = color
		elseif object:IsA("UIStroke") then
			object.Color = color
		elseif object:IsA("ImageLabel") then
			object.ImageColor3 = color
		end
	end
end

function Factory.buttonContent(
	button: TextButton,
	text: string,
	theme: any,
	options: { [string]: any }?
): ButtonContentHandle
	assert(typeof(button) == "Instance" and button:IsA("TextButton"), "Potassium Factory: buttonContent requires a TextButton")
	assert(type(text) == "string", "Potassium Factory: buttonContent text must be a string")
	assert(type(theme) == "table", "Potassium Factory: buttonContent requires a resolved theme")
	local previous = contents[button]
	if previous ~= nil then
		previous:Destroy()
	end
	local config = options or {}
	local root = Factory.make("Frame", {
		Name = "PotassiumButtonContent",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		Active = false,
		Size = UDim2.fromScale(1, 1),
		ZIndex = button.ZIndex + 1,
	}, button) :: Frame
	local label = Factory.text(root, text, button.TextSize, button.TextColor3, {
		Name = "Label",
		Active = false,
		Size = UDim2.fromScale(1, 1),
		TextXAlignment = config.TextXAlignment or config.textXAlignment or button.TextXAlignment,
		TextYAlignment = config.TextYAlignment or config.textYAlignment or button.TextYAlignment,
		TextTruncate = Enum.TextTruncate.AtEnd,
		ZIndex = root.ZIndex,
		theme = theme,
	})
	local handle: any = {
		Root = root,
		Label = label,
		IconSlot = nil,
		Icon = nil,
		_button = button,
		_theme = theme,
		_options = config,
		_text = text,
		_connections = {},
		_destroyed = false,
	}
	local function syncVisual()
		if handle._destroyed then
			return
		end
		if button.Text ~= "" then
			button.Text = ""
		end
		label.TextColor3 = button.TextColor3
		label.TextTransparency = button.TextTransparency
		label.TextSize = button.TextSize
		label.Font = button.Font
		pcall(function()
			label.FontFace = button.FontFace
		end)
		root.ZIndex = button.ZIndex + 1
		label.ZIndex = root.ZIndex
		recolorComposedIcon(handle.Icon, button.TextColor3)
	end
	handle._syncVisual = syncVisual
	local function rebuild()
		if handle._destroyed then
			return
		end
		local activeTheme = handle._theme
		local active = handle._options
		local left, top, right, bottom = composedInsets(active.Insets or active.insets or active.Inset or active.inset)
		local iconName = active.Icon or active.icon
		local iconRegistry = active.Icons or active.icons or defaultIcons
		local iconPosition = active.IconPosition or active.iconPosition or "left"
		local iconOnRight = iconPosition == "right"
		local hasIcon = iconName ~= nil and iconName ~= ""
		local iconSize = math.clamp(
			tonumber(active.IconSize or active.iconSize)
				or tonumber(activeTheme.metrics and activeTheme.metrics.iconSize)
				or 16,
			16,
			24
		)
		local gap = math.max(
			0,
			tonumber(active.Gap or active.gap)
				or tonumber(activeTheme.metrics and activeTheme.metrics.iconTextGap)
				or 8
		)
		local alignment = active.Alignment or active.alignment or (if handle._text == "" then "center" else "left")
		root.Position = UDim2.fromOffset(left, top)
		root.Size = UDim2.new(1, -(left + right), 1, -(top + bottom))
		root.ClipsDescendants = true
		if handle.IconSlot ~= nil then
			handle.IconSlot:Destroy()
			handle.IconSlot, handle.Icon = nil, nil
		end
		local labelOffset, labelTrailing = 0, 0
		if hasIcon then
			local slot = Factory.make("Frame", {
				Name = "IconSlot",
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				ClipsDescendants = true,
				Active = false,
				AnchorPoint = if alignment == "center"
					then Vector2.new(0.5, 0.5)
					elseif iconOnRight then Vector2.new(1, 0.5)
					else Vector2.new(0, 0.5),
				Position = if alignment == "center"
					then UDim2.fromScale(0.5, 0.5)
					elseif iconOnRight then UDim2.new(1, 0, 0.5, 0)
					else UDim2.fromScale(0, 0.5),
				Size = UDim2.fromOffset(iconSize, iconSize),
				ZIndex = root.ZIndex,
			}, root) :: Frame
			handle.IconSlot = slot
			handle.Icon = iconRegistry.Render(slot, iconName, activeTheme, iconSize, {
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5),
				Size = UDim2.fromOffset(iconSize, iconSize),
				Active = false,
				ZIndex = root.ZIndex,
			})
			if alignment ~= "center" then
				if iconOnRight then
					labelTrailing = iconSize + gap
				else
					labelOffset = iconSize + gap
				end
			end
		end
		label.Visible = handle._text ~= ""
		label.Text = handle._text
		label.Position = UDim2.fromOffset(labelOffset, 0)
		label.Size = UDim2.new(1, -(labelOffset + labelTrailing), 1, 0)
		label.TextXAlignment = active.TextXAlignment or active.textXAlignment or button.TextXAlignment
		label.TextYAlignment = active.TextYAlignment or active.textYAlignment or button.TextYAlignment
		syncVisual()
	end
	function handle:Apply(nextTheme: any?, nextOptions: { [string]: any }?)
		if self._destroyed then
			return
		end
		if nextTheme ~= nil then
			self._theme = nextTheme
		end
		if nextOptions ~= nil then
			self._options = nextOptions
		end
		rebuild()
	end
	function handle:SetText(nextText: string)
		assert(type(nextText) == "string", "Potassium Factory: button content text must be a string")
		self._text = nextText
		rebuild()
	end
	function handle:Destroy()
		if self._destroyed then
			return
		end
		self._destroyed = true
		for _, connection in ipairs(self._connections) do
			connection:Disconnect()
		end
		table.clear(self._connections)
		if contents[button] == self then
			contents[button] = nil
		end
		if root.Parent ~= nil then
			root:Destroy()
		end
	end
	for _, property in ipairs({ "Text", "TextColor3", "TextTransparency", "TextSize", "Font", "FontFace", "ZIndex" }) do
		table.insert(handle._connections, button:GetPropertyChangedSignal(property):Connect(syncVisual))
	end
	table.insert(handle._connections, button.Destroying:Connect(function()
		handle:Destroy()
	end))
	contents[button] = handle
	button.Text = ""
	rebuild()
	local record = records[button]
	if record ~= nil then
		record.content = handle
	end
	return handle :: ButtonContentHandle
end

Factory.composedButtonContent = Factory.buttonContent

local function cancelButtonTweens(record: ButtonRecord)
	for instance, tween in pairs(record.tweens) do
		tween:Cancel()
		record.tweens[instance] = nil
	end
end

local function transition(record: ButtonRecord, instance: Instance, properties: { [string]: any }, _preset: string, immediate: boolean)
	local active = record.tweens[instance]
	if active then
		active:Cancel()
		record.tweens[instance] = nil
	end
	if immediate or record.theme.reducedMotion == true then
		for property, value in pairs(properties) do
			(instance :: any)[property] = value
		end
		return
	end
	local tween = game:GetService("TweenService"):Create(
		instance,
		TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
		properties
	)
	record.tweens[instance] = tween
	tween.Completed:Connect(function()
		if record.tweens[instance] == tween then
			record.tweens[instance] = nil
		end
	end)
	tween:Play()
end

local function presenceGated(object: GuiObject): boolean
	local current: Instance? = object
	while current do
		if current:GetAttribute("PotassiumPresenceGated") == true then
			return true
		end
		current = current.Parent
	end
	return false
end
function Factory.setPresenceInteractive(object: GuiObject, interactive: boolean)
	assert(typeof(object) == "Instance" and object:IsA("GuiObject"), "Potassium Factory: presence interaction requires a GuiObject")
	if presenceGated(object) then
		object:SetAttribute("PotassiumPresenceActive", interactive)
		object:SetAttribute("PotassiumPresenceSelectable", interactive)
		object.Active = false
		object.Selectable = false
	else
		object.Active = interactive
		object.Selectable = interactive
	end
end


local function render(button: TextButton, record: ButtonRecord)
	local theme = record.theme
	local logical = record.logical
	local role = record.role
	local disabled = not record.enabled or logical == "disabled"
	local state = if disabled
		then "disabled"
		elseif logical == "selected" or logical == "danger" then logical
		else "default"
	local tokens = theme.states[state] or theme.states.default
	button.LineHeight = theme.typography.lineBody / theme.typography.body
	local hoverTokens = theme.states.hover or tokens
	local pressedTokens = theme.states.pressed or hoverTokens
	local surface = button:GetAttribute("PotassiumSurfaceColor")
	local transparentBase = role == "navigation" or role == "ghost"
	local backgroundColor = if typeof(surface) == "Color3" then surface else tokens.background
	local backgroundTransparency = if transparentBase and state == "default" and not record.hovered and not record.pressed
		then 1
		else 0
	local textColor = tokens.text
	local strokeColor = tokens.border
	local strokeThickness = theme.metrics.borderWidth
	local strokeTransparency = if role == "control" or role == "search"
		then 0.55
		elseif role == "segment" and state == "selected" then 0.25
		else 1

	Factory.setPresenceInteractive(button, not disabled)
	local navigationLevel = button:GetAttribute("PotassiumNavigationLevel")
	local fontRole = if state == "selected" then "strong" elseif navigationLevel == "subtab" then nil else "medium"
	button:SetAttribute("PotassiumFontRole", fontRole)
	Factory.applyTypography(button, theme, if navigationLevel == "subtab" then "caption" else "body")
	local corner = button:FindFirstChildOfClass("UICorner")
	if corner then
		corner.CornerRadius = UDim.new(0, theme.radius.md)
	end

	if not disabled and logical == "default" and record.hovered then
		if typeof(surface) ~= "Color3" then
			backgroundColor = hoverTokens.background
		end
		backgroundTransparency = 0
		textColor = hoverTokens.text
		strokeColor = hoverTokens.border
	end
	if not disabled and record.pressed then
		if logical == "default" then
			if typeof(surface) ~= "Color3" then
				backgroundColor = pressedTokens.background
			end
			textColor = pressedTokens.text
		end
		backgroundTransparency = 0
		strokeColor = pressedTokens.border
	end
	if role == "navigation" and state == "selected" then
		backgroundColor = if typeof(surface) == "Color3" then surface else theme.colors.surfaceRaised
		backgroundTransparency = 0
		textColor = theme.colors.text
		strokeColor = theme.colors.border
		strokeTransparency = 1
	end
	local glass = math.clamp(tonumber(theme.effects and theme.effects.glass) or 0, 0, 1)
	if backgroundTransparency < 1 and glass > 0 then
		local glassTransparency = glass * (if role == "navigation" then 0.18 else 0.24)
		if record.hovered or record.pressed then
			glassTransparency *= 0.55
		end
		backgroundTransparency = math.max(backgroundTransparency, glassTransparency)
	end
	if record.focused and not disabled then
		strokeColor = theme.colors.focus
		strokeThickness = math.max(2, theme.metrics.borderWidth)
		strokeTransparency = 0
	end

	local immediate = not record.initialized or disabled
	transition(record, button, {
		BackgroundColor3 = backgroundColor,
		BackgroundTransparency = backgroundTransparency,
		TextColor3 = textColor,
	}, "state", immediate)
	transition(record, record.stroke, {
		Color = strokeColor,
		Transparency = strokeTransparency,
		Thickness = strokeThickness,
	}, "state", immediate)
	transition(
		record,
		record.scale,
		{ Scale = if record.animatePress and record.pressed and not disabled then 0.98 else 1 },
		"micro",
		immediate or not record.animatePress
	)
	record.initialized = true
	button:SetAttribute("PotassiumButtonState", logical)
	button:SetAttribute("PotassiumButtonRole", role)
	if record.content ~= nil and not record.content._destroyed then
		record.content._theme = theme
		if record.content._syncVisual then
			record.content._syncVisual()
		end
	end
end

local function clean(button: TextButton)
	local record = records[button]
	if record == nil or record.cleaned then
		return
	end
	record.cleaned = true
	cancelButtonTweens(record)
	for _, connection in ipairs(record.connections) do
		connection:Disconnect()
	end
	table.clear(record.connections)
	if record.content ~= nil then
		record.content:Destroy()
		record.content = nil
	end
	if record.scale.Parent ~= nil then
		record.scale:Destroy()
	end
	records[button] = nil
end

function Factory.setButtonState(button: TextButton, state: ButtonState, theme: any?): TextButton
	local record = records[button]
	assert(record ~= nil, "Potassium Factory: setButtonState requires a Factory.button")
	assert(validStates[state], "Potassium Factory: unknown button state " .. tostring(state))
	if theme ~= nil then
		record.theme = theme
	end
	record.hovered = false
	record.pressed = false
	record.focused = false
	if state == "hover" then
		record.logical = "default"
		record.hovered = true
	elseif state == "pressed" then
		record.logical = "default"
		record.pressed = true
	elseif state == "focused" then
		record.logical = "default"
		record.focused = true
	else
		record.logical = state
	end
	if state == "disabled" then
		record.enabled = false
		record.hovered = false
		record.pressed = false
		record.focused = false
	elseif not record.enabled then
		record.enabled = true
	end
	render(button, record)
	return button
end

function Factory.setInteractive(button: TextButton, enabled: boolean, theme: any?): TextButton
	local record = records[button]
	assert(record ~= nil, "Potassium Factory: setInteractive requires a Factory.button")
	assert(type(enabled) == "boolean", "Potassium Factory: enabled must be boolean")
	if theme ~= nil then
		record.theme = theme
	end
	record.enabled = enabled
	if not enabled then
		record.hovered = false
		record.pressed = false
		record.focused = false
	end
	render(button, record)
	return button
end

function Factory.setButtonSurface(button: TextButton, color: Color3?): TextButton
	local record = records[button]
	assert(record ~= nil, "Potassium Factory: setButtonSurface requires a Factory.button")
	assert(color == nil or typeof(color) == "Color3", "Potassium Factory: surface color must be Color3 or nil")
	button:SetAttribute("PotassiumSurfaceColor", color)
	render(button, record)
	return button
end
function Factory.setButtonRole(button: TextButton, role: StyleRole, theme: any?): TextButton
	local record = records[button]
	assert(record ~= nil, "Potassium Factory: setButtonRole requires a Factory.button")
	assert(validRoles[role], "Potassium Factory: unknown button role " .. tostring(role))
	if theme ~= nil then
		record.theme = theme
	end
	record.role = role
	render(button, record)
	return button
end

function Factory.getButtonRole(button: TextButton): StyleRole
	local record = records[button]
	assert(record ~= nil, "Potassium Factory: getButtonRole requires a Factory.button")
	return record.role
end

function Factory.plainButton(parent: Instance, text: string, theme: any, props: { [string]: any }?): TextButton
	local merged: { [string]: any } = {
		AutoButtonColor = false,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Text = text,
		TextColor3 = theme.colors.text,
		TextSize = theme.typography.body * theme.textScale,
		LineHeight = theme.typography.lineBody / theme.typography.body,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Selectable = true,
		Size = UDim2.new(1, 0, 0, theme.metrics.compactControlHeight),
	}
	for key, value in pairs(props or {}) do
		merged[key] = value
	end
	applyThemeFont(merged, theme, Enum.Font.BuilderSansMedium)
	return Factory.make("TextButton", merged, parent) :: TextButton
end

function Factory.button(parent: Instance, text: string, theme: any, props: { [string]: any }?): TextButton
	assert(
		type(theme) == "table" and type(theme.states) == "table",
		"Potassium Factory: button requires a resolved theme"
	)
	local role = if props and props.Role ~= nil then props.Role elseif props and props.role ~= nil then props.role else "control"
	assert(validRoles[role], "Potassium Factory: unknown button role " .. tostring(role))
	local merged: { [string]: any } = {
		AutoButtonColor = false,
		BackgroundColor3 = theme.states.default.background,
		BorderSizePixel = 0,
		Text = text,
		TextColor3 = theme.states.default.text,
		TextSize = theme.typography.body * theme.textScale,
		LineHeight = theme.typography.lineBody / theme.typography.body,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Selectable = true,
		Size = UDim2.new(1, 0, 0, theme.metrics.compactControlHeight),
	}
	for key, value in pairs(props or {}) do
		if key ~= "Role" and key ~= "role" and key ~= "AnimatePress" and key ~= "animatePress" then
			merged[key] = value
		end
	end
	applyThemeFont(merged, theme, Enum.Font.BuilderSansMedium)
	local button = Factory.make("TextButton", merged, parent) :: TextButton
	Factory.corner(button, theme.radius.md)
	local stroke = Factory.stroke(button, theme.states.default.border, theme.metrics.borderWidth)
	stroke.Name = "PotassiumButtonStroke"
	local scale = Factory.make("UIScale", { Scale = 1 }, button) :: UIScale
	local record: ButtonRecord = {
		theme = theme,
		role = role,
		logical = "default",
		hovered = false,
		pressed = false,
		focused = false,
		enabled = true,
		stroke = stroke,
		scale = scale,
		animatePress = if props and props.AnimatePress ~= nil
			then props.AnimatePress ~= false
			elseif props and props.animatePress ~= nil then props.animatePress ~= false
			else role ~= "navigation" and role ~= "search",
		tweens = {},
		initialized = false,
		connections = {},
		cleaned = false,
		content = nil,
	}
	button:SetAttribute("PotassiumAnimatePress", record.animatePress)
	records[button] = record
	local function connect(signal: RBXScriptSignal, callback: (...any) -> ())
		table.insert(record.connections, signal:Connect(callback))
	end
	connect(button.MouseEnter, function()
		record.hovered = true
		render(button, record)
	end)
	connect(button.MouseLeave, function()
		record.hovered = false
		record.pressed = false
		render(button, record)
	end)
	connect(button.InputBegan, function(input)
		if
			record.enabled
			and (
				input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.Touch
			)
		then
			record.pressed = true
			render(button, record)
		end
	end)
	connect(button.InputEnded, function(input)
		if
			input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch
		then
			record.pressed = false
			render(button, record)
		end
	end)
	connect(button.SelectionGained, function()
		record.focused = true
		render(button, record)
	end)
	connect(button.SelectionLost, function()
		record.focused = false
		render(button, record)
	end)
	connect(button.Destroying, function()
		clean(button)
	end)
	connect(button.AncestryChanged, function(_, nextParent)
		if nextParent == nil and button.Parent == nil then
			clean(button)
		end
	end)
	render(button, record)
	return button
end

function Factory.focusRing(object: GuiObject, theme: any): UIStroke
	local existing = object:FindFirstChild("PotassiumButtonStroke")
	if existing and existing:IsA("UIStroke") then
		return existing
	end
	local stroke = Factory.stroke(object, theme.colors.focus, 2)
	stroke.Name = "PotassiumFocusRing"
	stroke.Transparency = 1
	return stroke
end

local function insetValues(insets: any): (number, number, number, number)
	if type(insets) == "number" then
		return insets, insets, insets, insets
	end
	if typeof(insets) == "Vector2" then
		return insets.X, insets.Y, insets.X, insets.Y
	end
	if type(insets) == "table" then
		return insets.left or insets.Left or 0,
			insets.top or insets.Top or 0,
			insets.right or insets.Right or 0,
			insets.bottom or insets.Bottom or 0
	end
	return 0, 0, 0, 0
end

function Factory.popupPosition(anchor: GuiObject, popupSize: Vector2, viewport: GuiObject?, insets: any?): UDim2
	assert(
		typeof(anchor) == "Instance" and anchor:IsA("GuiObject"),
		"Potassium Factory: popup anchor must be a GuiObject"
	)
	assert(typeof(popupSize) == "Vector2", "Potassium Factory: popup size must be Vector2")
	local host = viewport or anchor:FindFirstAncestorOfClass("ScreenGui")
	local origin = Vector2.zero
	local size = if host and host:IsA("GuiObject")
		then host.AbsoluteSize
		else workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or popupSize
	if host and host:IsA("GuiObject") then
		origin = host.AbsolutePosition
	end
	local left, top, right, bottom = insetValues(insets)
	local minX, minY = origin.X + left, origin.Y + top
	local maxX = math.max(minX, origin.X + size.X - right - popupSize.X)
	local maxY = math.max(minY, origin.Y + size.Y - bottom - popupSize.Y)
	local below = anchor.AbsolutePosition.Y + anchor.AbsoluteSize.Y + 4
	local above = anchor.AbsolutePosition.Y - popupSize.Y - 4
	local y = if below <= maxY then below elseif above >= minY then above else math.clamp(below, minY, maxY)
	local x = math.clamp(anchor.AbsolutePosition.X, minX, maxX)
	return UDim2.fromOffset(x, y)
end

function Factory.placePopup(popup: GuiObject, anchor: GuiObject, viewport: GuiObject?, insets: any?): UDim2
	assert(typeof(popup) == "Instance" and popup:IsA("GuiObject"), "Potassium Factory: popup must be a GuiObject")
	local popupSize = popup.AbsoluteSize
	if popupSize.X <= 0 or popupSize.Y <= 0 then
		popupSize = Vector2.new(popup.Size.X.Offset, popup.Size.Y.Offset)
	end
	local position = Factory.popupPosition(anchor, popupSize, viewport, insets)
	popup.Position = position
	return position
end

return Factory

end

