local function normalize(name: any): string?
	if type(name) ~= "string" or name == "" then
		return nil
	end
	local normalized = string.lower(string.gsub(name, "[%s%-]", ""))
	return aliases[normalized] or normalized
end

local function make(className: string, parent: Instance, props: Properties): Instance
	local instance = Instance.new(className)
	for property, value in pairs(props) do
		(instance :: any)[property] = value
	end
	instance.Parent = parent
	return instance
end

local function colorFrom(theme: any, props: Properties?): Color3
	if props then
		if typeof(props.Color3) == "Color3" then
			return props.Color3
		end
		if typeof(props.Color) == "Color3" then
			return props.Color
		end
		if typeof(props.color) == "Color3" then
			return props.color
		end
	end
	if type(theme) == "table" then
		if type(theme.colors) == "table" and typeof(theme.colors.text) == "Color3" then
			return theme.colors.text
		end
		if typeof(theme.accentA) == "Color3" then
			return theme.accentA
		end
	end
	return Color3.fromRGB(235, 235, 235)
end

local function line(
	parent: Instance,
	color: Color3,
	x: number,
	y: number,
	width: number,
	rotation: number?,
	thickness: number?
): Frame
	local strokeWidth = math.clamp(thickness or 1.5, 1.25, 1.75)
	local frame = make("Frame", parent, {
		BackgroundColor3 = color,
		BackgroundTransparency = 0,
		BorderSizePixel = 0,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(x / 24, y / 24),
		Size = UDim2.fromScale(width / 24, strokeWidth / 24),
		Rotation = rotation or 0,
	}) :: Frame
	frame:SetAttribute("IconPrimitive", "stroke")
	frame:SetAttribute("IconStrokeWidth", strokeWidth)
	make("UICorner", frame, { CornerRadius = UDim.new(1, 0) })
	return frame
end

local function round(frame: Frame, radius: number)
	make("UICorner", frame, { CornerRadius = UDim.new(0, radius) })
end

local function outlined(
	parent: Instance,
	color: Color3,
	x: number,
	y: number,
	width: number,
	height: number,
	radius: number?
): Frame
	local frame = make("Frame", parent, {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(x / 24, y / 24),
		Size = UDim2.fromOffset(width, height),
	}) :: Frame
	make("UIStroke", frame, { Color = color, Thickness = 1.5, ApplyStrokeMode = Enum.ApplyStrokeMode.Border })
	round(frame, radius or math.floor(math.min(width, height) / 2))
	frame:SetAttribute("IconPrimitive", "outline")
	return frame
end

local function dot(parent: Instance, color: Color3, x: number, y: number, size: number): Frame
	local frame = make("Frame", parent, {
		BackgroundColor3 = color,
		BackgroundTransparency = 0,
		BorderSizePixel = 0,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(x / 24, y / 24),
		Size = UDim2.fromOffset(size, size),
	}) :: Frame
	round(frame, size)
	frame:SetAttribute("IconPrimitive", "dot")
	return frame
end

local ION_GATE_ACCENT = Color3.fromRGB(78, 127, 252)
local ION_GATE_ACCENT_DEEP = Color3.fromRGB(55, 95, 219)

local function brandPart(instance: Frame, role: string, name: string): Frame
	instance.Name = name
	instance:SetAttribute("BrandRole", role)
	return instance
end

local function renderIonGate(parent: Instance, foreground: Color3)
	local accent = ION_GATE_ACCENT
	local deep = ION_GATE_ACCENT_DEEP
	brandPart(line(parent, accent, 4.3, 7.5, 3.6, -66, 1.8), "accent", "ArcTopLeftOuter")
	brandPart(line(parent, accent, 7.1, 4.7, 4.8, -30, 1.8), "accent", "ArcTopLeftInner")
	brandPart(line(parent, accent, 16.9, 4.7, 4.8, 30, 1.8), "accent", "ArcTopRightInner")
	brandPart(line(parent, accent, 19.7, 7.5, 3.6, 66, 1.8), "accent", "ArcTopRightOuter")
	brandPart(line(parent, deep, 19.8, 16.4, 3.8, -68, 1.8), "accentDeep", "ArcBottomRightOuter")
	brandPart(line(parent, deep, 16.9, 19.3, 4.8, -30, 1.8), "accentDeep", "ArcBottomRightInner")
	brandPart(line(parent, deep, 7.1, 19.3, 4.8, 30, 1.8), "accentDeep", "ArcBottomLeftInner")
	brandPart(line(parent, deep, 4.2, 16.4, 3.8, 68, 1.8), "accentDeep", "ArcBottomLeftOuter")
	brandPart(line(parent, accent, 9.8, 6.2, 4.8, -24, 1.5), "accent", "ApertureTopLeft")
	brandPart(line(parent, accent, 14.2, 6.2, 4.8, 24, 1.5), "accent", "ApertureTopRight")
	brandPart(line(parent, deep, 9.8, 17.8, 4.8, 24, 1.5), "accentDeep", "ApertureBottomLeft")
	brandPart(line(parent, deep, 14.2, 17.8, 4.8, -24, 1.5), "accentDeep", "ApertureBottomRight")
	brandPart(line(parent, foreground, 8.2, 9.7, 5.2, 45, 2.25), "foreground", "GateLeftUpper")
	brandPart(line(parent, foreground, 8.2, 14.3, 5.2, -45, 2.25), "foreground", "GateLeftLower")
	brandPart(line(parent, foreground, 15.8, 9.7, 5.2, -45, 2.25), "foreground", "GateRightUpper")
	brandPart(line(parent, foreground, 15.8, 14.3, 5.2, 45, 2.25), "foreground", "GateRightLower")
	brandPart(dot(parent, Color3.fromRGB(15, 16, 20), 12, 12, 6), "coreSurface", "CoreSurface")
	brandPart(dot(parent, accent, 12, 12, 4.5), "accent", "CoreRing")
	brandPart(dot(parent, foreground, 12, 12, 2), "foreground", "Core")
end

local function chevron(parent: Instance, color: Color3, direction: string)
	if direction == "arrowdown" or direction == "chevrondown" then
		line(parent, color, 9.5, 11.5, 7, 45)
		line(parent, color, 14.5, 11.5, 7, -45)
	elseif direction == "arrowup" or direction == "chevronup" then
		line(parent, color, 9.5, 12.5, 7, -45)
		line(parent, color, 14.5, 12.5, 7, 45)
	elseif direction == "arrowleft" or direction == "chevronleft" then
		line(parent, color, 11.5, 9.5, 7, -45)
		line(parent, color, 11.5, 14.5, 7, 45)
	else
		line(parent, color, 12.5, 9.5, 7, 45)
		line(parent, color, 12.5, 14.5, 7, -45)
	end
end

local function renderFamily(parent: Instance, family: string, color: Color3)
	if family == "check" or family == "checkcircle" then
		if family == "checkcircle" then
			outlined(parent, color, 12, 12, 18, 18)
		end
		line(parent, color, 8, 13, 6, 45)
		line(parent, color, 14, 10, 11, -45)
	elseif family == "close" then
		line(parent, color, 12, 12, 17, 45)
		line(parent, color, 12, 12, 17, -45)
	elseif family == "plus" or family == "minus" then
		line(parent, color, 12, 12, 16)
		if family == "plus" then
			line(parent, color, 12, 12, 16, 90)
		end
	elseif string.sub(family, 1, 7) == "chevron" or string.sub(family, 1, 5) == "arrow" then
		chevron(parent, color, family)
		if string.sub(family, 1, 5) == "arrow" then
			local vertical = family == "arrowup" or family == "arrowdown"
			line(parent, color, 12, 12, 15, if vertical then 90 else 0)
		end
	elseif family == "search" then
		local lens = outlined(parent, color, 9.5, 9.5, 12.5, 12.5)
		lens.Name = "SearchLens"
		local handle = line(parent, color, 16.5, 16.5, 7.5, 45, 2.25)
		handle.Name = "SearchHandle"
	elseif family == "eye" then
		line(parent, color, 6.5, 10, 6.5, -38)
		line(parent, color, 12, 7.5, 6)
		line(parent, color, 17.5, 10, 6.5, 38)
		line(parent, color, 6.5, 14, 6.5, 38)
		line(parent, color, 12, 16.5, 6)
		line(parent, color, 17.5, 14, 6.5, -38)
		outlined(parent, color, 12, 12, 7, 7)
		dot(parent, color, 12, 12, 2)
	elseif family == "iongate" then
		renderIonGate(parent, color)
	elseif family == "settings" then
		for i = 0, 5 do
			local angle = i * math.pi / 3
			line(parent, color, 12 + math.cos(angle) * 7.5, 12 + math.sin(angle) * 7.5, 4.5, i * 60)
		end
