		local renewalCore = outlined(parent, color, 12, 12, 4, 4, 1)
		renewalCore.Name = "RenewalCore"
		renewalCore.Rotation = 45
	elseif family == "farm" then
		local cropStem = line(parent, color, 12, 14, 12, 90)
		cropStem.Name = "CropStem"
		local leftLeaf = outlined(parent, color, 8.5, 10.5, 8, 5, 3)
		leftLeaf.Name = "CropLeafLeft"
		leftLeaf.Rotation = 28
		local rightLeaf = outlined(parent, color, 15.5, 8.5, 8, 5, 3)
		rightLeaf.Name = "CropLeafRight"
		rightLeaf.Rotation = -28
		local soil = line(parent, color, 12, 20, 17)
		soil.Name = "FarmSoil"
		local leftFurrow = line(parent, color, 8.5, 22, 5, 8)
		leftFurrow.Name = "FarmFurrowLeft"
		local rightFurrow = line(parent, color, 15.5, 22, 5, -8)
		rightFurrow.Name = "FarmFurrowRight"
	elseif family == "godmode" then
		local shieldTopLeft = line(parent, color, 9.2, 6.1, 6.3, -24)
		shieldTopLeft.Name = "GodmodeShieldTopLeft"
		local shieldTopRight = line(parent, color, 14.8, 6.1, 6.3, 24)
		shieldTopRight.Name = "GodmodeShieldTopRight"
		local shieldLeft = line(parent, color, 6.6, 10.7, 6.6, 86)
		shieldLeft.Name = "GodmodeShieldLeft"
		local shieldRight = line(parent, color, 17.4, 10.7, 6.6, -86)
		shieldRight.Name = "GodmodeShieldRight"
		local shieldBottomLeft = line(parent, color, 9.4, 17, 8, 48)
		shieldBottomLeft.Name = "GodmodeShieldBottomLeft"
		local shieldBottomRight = line(parent, color, 14.6, 17, 8, -48)
		shieldBottomRight.Name = "GodmodeShieldBottomRight"
		local protectionCheckLeft = line(parent, color, 9.4, 12.2, 4.2, 45)
		protectionCheckLeft.Name = "GodmodeCheckLeft"
		local protectionCheckRight = line(parent, color, 13.4, 10.5, 7.5, -45)
		protectionCheckRight.Name = "GodmodeCheckRight"
	elseif family == "fuse" then
		local topSource = dot(parent, color, 5.5, 7.5, 4.5)
		topSource.Name = "FuseSourceTop"
		local bottomSource = dot(parent, color, 5.5, 16.5, 4.5)
		bottomSource.Name = "FuseSourceBottom"
		local topConduit = line(parent, color, 9.8, 9.6, 7.5, 34)
		topConduit.Name = "FuseConduitTop"
		local bottomConduit = line(parent, color, 9.8, 14.4, 7.5, -34)
		bottomConduit.Name = "FuseConduitBottom"
		local outputConduit = line(parent, color, 14.8, 12, 5.5)
		outputConduit.Name = "FuseOutputConduit"
		local result = outlined(parent, color, 19.5, 12, 6, 6, 3)
		result.Name = "FuseResult"
		local resultCore = dot(parent, color, 19.5, 12, 2.5)
		resultCore.Name = "FuseResultCore"
	else
		-- A deterministic neutral mark is preferable to a missing glyph or tofu.
		outlined(parent, color, 12, 12, 17, 17, 3)
		line(parent, color, 8, 8, 9)
		line(parent, color, 16, 16, 9)
	end
end

local MAX_ICON_NAME_LENGTH = 96
local MAX_CUSTOM_ALIASES = 64

local function iconKey(name: any): string?
	if type(name) ~= "string" or name == "" or #name > MAX_ICON_NAME_LENGTH then return nil end
	local key = string.lower(string.gsub(name, "[^%w_]", ""))
	if key == "" or #key > MAX_ICON_NAME_LENGTH then return nil end
	return key
end

local function createRoot(parent: Instance, name: any, size: number, props: Properties?): Frame
	local root = Instance.new("Frame")
	root.Name = "Icon_" .. tostring(name)
	root.BackgroundTransparency = 1
	root.BorderSizePixel = 0
	root.ClipsDescendants = true
	root.Size = UDim2.fromOffset(size, size)
	root.Active = false
	if props then
		for property, value in pairs(props) do
			if property ~= "Color" and property ~= "Color3" and property ~= "color" then
				(root :: any)[property] = value
			end
		end
	end
	root.Parent = parent
	return root
end

local function renderBuiltin(parent: Instance, name: any, theme: any, size: number, props: Properties?): Frame
	local normalized = normalize(name)
	local family = if normalized then families[normalized] else nil
	local root = createRoot(parent, name, size, props)
	root:SetAttribute("IconFamily", family or "generic")
	root:SetAttribute("IconFallback", family == nil)
	local canvas = Instance.new("Frame")
	canvas.Name = "IconCanvas"
	canvas.BackgroundTransparency = 1
	canvas.BorderSizePixel = 0
	canvas.ClipsDescendants = true
	canvas.AnchorPoint = Vector2.new(0.5, 0.5)
	canvas.Position = UDim2.fromScale(0.5, 0.5)
	canvas.Size = UDim2.fromOffset(48, 48)
	canvas.Active = false
	canvas.Parent = root
	local canvasScale = Instance.new("UIScale")
	canvasScale.Name = "Downsample"
	canvasScale.Scale = size / 48
	canvasScale.Parent = canvas
	local geometry = Instance.new("Frame")
	geometry.Name = "SupersampledGeometry"
	geometry.BackgroundTransparency = 1
	geometry.BorderSizePixel = 0
	geometry.AnchorPoint = Vector2.new(0.5, 0.5)
	geometry.Position = UDim2.fromScale(0.5, 0.5)
	geometry.Size = UDim2.fromOffset(24, 24)
	geometry.Active = false
	geometry.Parent = canvas
	local geometryScale = Instance.new("UIScale")
	geometryScale.Name = "Supersample"
	geometryScale.Scale = 2
	geometryScale.Parent = geometry
	renderFamily(geometry, family or "generic", colorFrom(theme, props))
	return root
end

export type Registry = {
	Get: (self: Registry, name: any) -> string,
	Has: (self: Registry, name: any) -> boolean,
	List: (self: Registry) -> { string },
	Render: (self: Registry, parent: Instance, name: any, theme: any, size: number?, props: Properties?) -> Frame,
	Register: (self: Registry, name: any, definition: any) -> (boolean, any?),
	RegisterIconAsset: (self: Registry, name: any, source: any) -> (boolean, any?),
	RegisterIconReference: (self: Registry, name: any, target: any) -> (boolean, any?),
	Unregister: (self: Registry, name: any) -> boolean,
	RegisterAlias: (self: Registry, alias: any, target: any) -> (boolean, any?),
	UnregisterAlias: (self: Registry, alias: any) -> boolean,
}

local Registry = {}
Registry.__index = Registry

local function registryError(code: string, message: string): any
	return { code = code, message = message }
end

local function definitionFor(registry: any, key: string): any?
	return registry._icons[key]
end

local function resolve(registry: any, name: any): (string?, any?)
	local key = iconKey(name)
	if key == nil then
		return nil, nil
	end
	local seen: { [string]: boolean } = {}
	while key ~= nil do
		if seen[key] then
			return nil, registryError("icon_alias_cycle", "Icon alias cycle detected")
		end
		seen[key] = true
		local definition = definitionFor(registry, key)
		if definition ~= nil then
			if definition.Type == "reference" then
				key = definition.Name
			else
				return key, definition
			end
		else
			key = registry._aliases[key]
		end
	end
	return nil, nil
end


local function prospectiveReferenceError(registry: any, key: string, target: string): any?
	local cursor: string? = target
	local seen: { [string]: boolean } = { [key] = true }
	while cursor ~= nil do
		if seen[cursor] then
			return registryError("icon_reference_cycle", "Icon reference would create a cycle")
		end
		seen[cursor] = true
		local definition = definitionFor(registry, cursor)
		if definition ~= nil then
			if definition.Type == "reference" then
				cursor = definition.Name
			else
				return nil
			end
		else
			cursor = registry._aliases[cursor]
			if cursor == nil then
				return registryError("unknown_icon_reference", "Reference target is not registered")
			end
		end
	end
	return registryError("unknown_icon_reference", "Reference target is not registered")
end

local function containsUntrustedDefinitionValue(value: any): boolean
	local pending = { { value = value, depth = 0 } }
	local visited, cursor = {}, 1
	while cursor <= #pending do
		local entry = pending[cursor]
		cursor += 1
		if entry.depth > 8 or cursor > 128 then return true end
		local current = entry.value
		if typeof(current) == "Instance" then return true end
		if type(current) == "table" and not visited[current] then
			visited[current] = true
			for key, nested in pairs(current) do
				if #pending >= 128 then return true end
				if type(key) == "string" and (string.lower(key) == "code" or string.lower(key) == "sourcecode" or string.lower(key) == "renderer") and type(nested) == "string" then return true end
				table.insert(pending, { value = nested, depth = entry.depth + 1 })
			end
		end
	end
	return false
end

local function releaseMount(registry: any, root: Frame)
	local mount = registry._mounts[root]
	if mount == nil then
		return
	end
	registry._mounts[root] = nil
	if mount.Connection ~= nil then
		mount.Connection:Disconnect()
	end
	pcall(mount.Cleanup, root)
end

local function ownMount(registry: any, root: Frame, cleanup: (Frame) -> ())
	local connection = root.Destroying:Connect(function()
		releaseMount(registry, root)
	end)
	registry._mounts[root] = { Cleanup = cleanup, Connection = connection }
end

local DEFINITION_FIELDS = table.freeze({
	procedural = table.freeze({ Type = true, Renderer = true, Cleanup = true, Replace = true }),
	image = table.freeze({ Type = true, Asset = true, Source = true, Replace = true }),
	reference = table.freeze({ Type = true, Name = true, Replace = true }),
})

local function definitionSchemaError(definition: any): any?
	local kind = rawget(definition, "Type")
	local fields = if type(kind) == "string" then DEFINITION_FIELDS[kind] else nil
	if fields == nil then return registryError("invalid_icon_definition", "Icon Type must be procedural, image, or reference") end
	for key in pairs(definition) do
		if type(key) ~= "string" or not fields[key] then return registryError("unknown_icon_definition_field", "Icon definition contains an unknown field") end
	end
	return nil
end

local function releaseDefinitionAsset(registry: any, definition: any)
	local owner = type(definition) == "table" and definition._assetOwner or nil
	if owner ~= nil then
		registry._assetPolicy:ReleaseOwner(owner)
	end
end

local function validateDefinition(registry: any, definition: any, prospectiveKey: string?): (any?, any?)
	if type(definition) ~= "table" then return nil, registryError("invalid_icon_definition", "Icon definition must be a table") end
	local schemaError = definitionSchemaError(definition)
	if schemaError ~= nil then return nil, schemaError end
	if containsUntrustedDefinitionValue(definition) then return nil, registryError("untrusted_icon_definition", "Icon definitions cannot contain code strings or Instances") end
	local kind = definition.Type
	if kind == "procedural" then
		if type(definition.Renderer) ~= "function" then
			return nil, registryError("invalid_icon_definition", "Procedural icons require a trusted Renderer function")
		end
		if definition.Cleanup ~= nil and type(definition.Cleanup) ~= "function" then
			return nil, registryError("invalid_icon_definition", "Procedural icon Cleanup must be a function")
		end
		return { Type = kind, Renderer = definition.Renderer, Cleanup = definition.Cleanup }, nil
	elseif kind == "image" then
		if type(registry._assetPolicy.ReleaseOwner) ~= "function" then
			return nil, registryError("asset_policy_unavailable", "Image icons require an asset policy with owner release support")
		end
		local declaration = definition.Asset or definition.Source
		local assetOwner = {}
		local admitted, assetError = registry._assetPolicy:Admit(declaration, "$.icon", assetOwner)
		if admitted == nil then
			return nil, assetError
		end
		if admitted.kind ~= "icon" and admitted.kind ~= "image" then
			registry._assetPolicy:ReleaseOwner(assetOwner)
			return nil, registryError("invalid_icon_definition", "Image icons require an icon or image asset declaration")
		end
		return { Type = kind, Asset = admitted, _assetOwner = assetOwner }, nil
	elseif kind == "reference" then
		local target = iconKey(definition.Name)
		if target == nil then
			return nil, registryError("invalid_icon_definition", "Reference icons require a valid Name")
		end
		if prospectiveKey ~= nil then
			local referenceError = prospectiveReferenceError(registry, prospectiveKey, target)
			if referenceError ~= nil then
				return nil, referenceError
			end
		elseif resolve(registry, target) == nil then
			return nil, registryError("unknown_icon_reference", "Reference target is not registered")
		end
		return { Type = kind, Name = target }, nil
	end
	return nil, registryError("invalid_icon_definition", "Icon Type must be procedural, image, or reference")
end

function Registry:Get(name: any): string
	local key, definition = resolve(self, name)
	if key == nil or definition == nil then
		return ""
	end
	if definition.Type == "builtin" then
		return legacyText[definition.Family] or "*"
	end
	return ""
end

function Registry:Has(name: any): boolean
	local key = resolve(self, name)
	return key ~= nil
end

function Registry:List(): { string }
	local seen, result = {}, {}
	for name, definition in pairs(self._icons) do
		local listed = if definition.Type == "builtin" then definition.Family else (definition.DisplayName or name)
		if not seen[listed] then
			seen[listed] = true
			table.insert(result, listed)
		end
	end
	table.sort(result)
	return result
end

function Registry:Render(parent: Instance, name: any, theme: any, size: number?, props: Properties?): Frame
	assert(typeof(parent) == "Instance", "Potassium Icons: Render requires a parent Instance")
	local pixelSize = size or 20
	assert(type(pixelSize) == "number" and pixelSize >= 14 and pixelSize <= 24, "Potassium Icons: size must be 14-24")
	local key, definition = resolve(self, name)
	if key == nil or definition == nil then
		return renderBuiltin(parent, name, theme, pixelSize, props)
	end
	if definition.Type == "builtin" then
		return renderBuiltin(parent, key, theme, pixelSize, props)
	end
	if definition.Type == "image" then
		local source = self._assetPolicy:Resolve(definition.Asset, self._runtime, "$.icon")
		if source == nil or source == "" then
			local semantic = "help"
			if type(self._assetPolicy.OfflineName) == "function" then
				semantic = self._assetPolicy:OfflineName(definition.Asset, "$.icon") or semantic
			elseif type(definition.Asset) == "table" then
				local assetSource = definition.Asset.source
				semantic = if type(assetSource) == "table" and assetSource.tag == "builtin" then assetSource.value else if type(definition.Asset.fallback) == "table" then definition.Asset.fallback.builtin else semantic
			end
			return renderBuiltin(parent, semantic, theme, pixelSize, props)
		end
		local root = createRoot(parent, key, pixelSize, props)
		root:SetAttribute("IconFamily", definition.DisplayName or key)
		root:SetAttribute("IconName", definition.DisplayName or key)
		root:SetAttribute("IconFallback", false)
		local image = Instance.new("ImageLabel")
		image.Parent = root
		image.Name = "IconImage"
		image.BackgroundTransparency = 1
		image.Image = source
		image.Size = UDim2.fromScale(1, 1)
		image.ScaleType = if definition.Asset.scaleType ~= nil then Enum.ScaleType[definition.Asset.scaleType] else Enum.ScaleType.Fit
		if definition.Asset.rectOffset ~= nil then image.ImageRectOffset = definition.Asset.rectOffset end
		if definition.Asset.rectSize ~= nil then image.ImageRectSize = definition.Asset.rectSize end
		image.ImageColor3 = colorFrom(theme, props)
		return root
	end
	local function semanticProps(value: Properties?): Properties?
		if value == nil then
			return nil
		end
		local semantic: Properties = {}
		for property, propertyValue in pairs(value) do
			if property == "Color" or property == "Color3" or property == "color" then
				semantic[property] = propertyValue
			end
		end
		return semantic
	end
	local staging = Instance.new("Frame")
	staging.Name = "PotassiumIconStaging"
	staging.BackgroundTransparency = 1
	staging.Size = UDim2.fromOffset(pixelSize, pixelSize)
	local root: Frame? = nil
	local ok = xpcall(function()
		local rendered = definition.Renderer(staging, theme, pixelSize, semanticProps(props))
		if rendered ~= nil then
			if typeof(rendered) ~= "Instance" or not rendered:IsA("Frame") then
				error("Procedural icon renderer returned an invalid root", 0)
			end
			if rendered ~= staging then
				if staging:IsDescendantOf(rendered) then
					error("Procedural icon renderer returned a staging ancestor", 0)
				end
				if not rendered:IsDescendantOf(staging) then
					rendered.Parent = staging
				end
			end
		end
		if #staging:GetDescendants() > 40 then
			error("Procedural icon renderer exceeded the 40 descendant budget", 0)
		end
		root = createRoot(parent, key, pixelSize, props)
		root:SetAttribute("IconFamily", definition.DisplayName or key)
		root:SetAttribute("IconName", definition.DisplayName or key)
		root:SetAttribute("IconFallback", false)
		local canvas = Instance.new("Frame")
		canvas.Name = "IconCanvas"
		canvas.BackgroundTransparency = 1
		canvas.BorderSizePixel = 0
		canvas.ClipsDescendants = true
		canvas.Active = false
		canvas.AnchorPoint = Vector2.new(0.5, 0.5)
		canvas.Position = UDim2.fromScale(0.5, 0.5)
		canvas.Size = UDim2.fromOffset(pixelSize, pixelSize)
		canvas.Parent = root
		for _, child in ipairs(staging:GetChildren()) do
			child.Parent = canvas
		end
		staging:Destroy()
		if definition.Cleanup ~= nil then
			ownMount(self, root, definition.Cleanup)
		end
	end, debug.traceback)
	if not ok or root == nil then
		if definition.Cleanup ~= nil then
			pcall(definition.Cleanup, root or staging)
		end
		if root ~= nil then
			pcall(function()
				root:Destroy()
			end)
		end
		pcall(function()
			staging:Destroy()
		end)
		return renderBuiltin(parent, name, theme, pixelSize, props)
	end
	return root
end

function Registry:Register(name: any, definition: any): (boolean, any?)
	if self._destroyed then
		return false, registryError("icon_registry_destroyed", "Icon registry is destroyed")
	end
	local key = iconKey(name)
	if key == nil then
		return false, registryError("invalid_icon_name", "Icon name must contain letters, numbers, or underscores")
	end
	if type(definition) ~= "table" then
		return false, registryError("invalid_icon_definition", "Icon definition must be a table")
	end
	local existing = self._icons[key]
	if self._aliases[key] ~= nil then
		return false, registryError("duplicate_icon", "Icon name is already used by an alias")
	end
	if existing ~= nil and (existing.Type == "builtin" or definition.Replace ~= true) then
		return false, registryError("duplicate_icon", "Icon is already registered")
	end
	if definition.Type == "procedural" and self._assetPolicy:GetMode() == "neutral" then
		return false, registryError("offline_icon_only", "Neutral mode permits only the built-in procedural icon catalog")
	end
	if self._customCount >= 32 and self._custom[key] == nil then
		return false, registryError("icon_limit", "An icon registry can contain at most 32 custom icons")
	end
	local normalized, validationError = validateDefinition(self, definition, key)
	if normalized == nil then
		return false, validationError
	end
	normalized.DisplayName = name
	if existing ~= nil then
		releaseDefinitionAsset(self, existing)
	end
	self._icons[key] = normalized
	if self._custom[key] == nil then
		self._custom[key] = true
		self._customCount += 1
	end
	return true, nil
end

function Registry:RegisterIconAsset(name: any, asset: any): (boolean, any?)
	return self:Register(name, { Type = "image", Asset = asset })
end

function Registry:RegisterIconReference(name: any, target: any): (boolean, any?)
	return self:Register(name, { Type = "reference", Name = target })
end

function Registry:Unregister(name: any): boolean
	local key = iconKey(name)
	if key == nil then
		return false
	end
	local definition = self._icons[key]
	if definition == nil or definition.Type == "builtin" then
		return false
	end
	releaseDefinitionAsset(self, definition)
	self._icons[key] = self._builtins[key]
	if self._custom[key] then
		self._custom[key] = nil
		self._customCount -= 1
	end
	return true
end

function Registry:RegisterAlias(alias: any, target: any): (boolean, any?)
	local aliasKey, targetKey = iconKey(alias), iconKey(target)
	if aliasKey == nil or targetKey == nil then return false, registryError("invalid_icon_alias", "Alias and target must be valid icon names") end
	if self._destroyed then return false, registryError("icon_registry_destroyed", "Icon registry is destroyed") end
	if self._icons[aliasKey] ~= nil or self._aliases[aliasKey] ~= nil then return false, registryError("duplicate_icon_alias", "Icon alias is already registered") end
	if resolve(self, targetKey) == nil then return false, registryError("unknown_icon_alias_target", "Icon alias target is not registered") end
	local cursor, seen = targetKey, { [aliasKey] = true }
	while cursor ~= nil do
		if seen[cursor] then return false, registryError("icon_alias_cycle", "Icon alias would create a cycle") end
		seen[cursor] = true
		cursor = self._aliases[cursor]
	end
	if self._customAliasCount >= MAX_CUSTOM_ALIASES then return false, registryError("icon_alias_limit", "An icon registry can contain at most 64 custom aliases") end
	self._aliases[aliasKey] = targetKey
	self._customAliasCount += 1
	return true, nil
end

function Registry:UnregisterAlias(alias: any): boolean
	local key = iconKey(alias)
	if key == nil or self._builtinAliases[key] ~= nil or self._aliases[key] == nil then return false end
	self._aliases[key] = nil
	self._customAliasCount -= 1
	return true
end

function Registry:Destroy()
	if self._destroyed then return end
	self._destroyed = true
	local roots = {}
	for root in pairs(self._mounts) do table.insert(roots, root) end
	for _, root in ipairs(roots) do releaseMount(self, root) end
	for _, definition in pairs(self._icons) do
		releaseDefinitionAsset(self, definition)
	end
	table.clear(self._icons)
	table.clear(self._builtins)
	table.clear(self._aliases)
	table.clear(self._builtinAliases)
	table.clear(self._custom)
	self._customCount = 0
	self._customAliasCount = 0
end


function Icons.new(runtime: any?, assetPolicy: any?): Registry
	local builtins, iconAliases, builtinAliases = {}, {}, {}
	for name, family in pairs(families) do
		builtins[name] = { Type = "builtin", Family = family }
	end
	local icons = {}
	for name, definition in pairs(builtins) do
		icons[name] = definition
	end
	for alias, target in pairs(aliases) do
		iconAliases[alias] = target
		builtinAliases[alias] = true
	end
	local policy = assetPolicy or (if type(runtime) == "table" then runtime.assetPolicy else nil)
	if policy == nil then
		policy = AssetPolicy.new()
	end
	local registry: any = setmetatable({
		_icons = icons,
		_builtins = builtins,
		_aliases = iconAliases,
		_builtinAliases = builtinAliases,
		_mounts = {},
		_runtime = runtime,
		_assetPolicy = policy,
		_custom = {},
		_customCount = 0,
		_customAliasCount = 0,
	}, Registry)
	registry.Get = function(first: any, second: any?)
		return Registry.Get(registry, if first == registry then second else first)
	end
	registry.Has = function(first: any, second: any?)
		return Registry.Has(registry, if first == registry then second else first)
	end
	registry.List = function(_first: any?)
		return Registry.List(registry)
	end
	registry.Render = function(first: any, ...: any)
		if first == registry then
			return Registry.Render(registry, ...)
		end
		return Registry.Render(registry, first, ...)
	end
	registry.Register = function(first: any, second: any, third: any?)
		if first == registry then
			return Registry.Register(registry, second, third)
		end
		return Registry.Register(registry, first, second)
	end
	registry.RegisterIconAsset = function(first: any, second: any, third: any?)
		if first == registry then
			return Registry.RegisterIconAsset(registry, second, third)
		end
		return Registry.RegisterIconAsset(registry, first, second)
	end
	registry.RegisterIconReference = function(first: any, second: any, third: any?)
		if first == registry then
			return Registry.RegisterIconReference(registry, second, third)
		end
		return Registry.RegisterIconReference(registry, first, second)
	end
	registry.Unregister = function(first: any, second: any?)
		return Registry.Unregister(registry, if first == registry then second else first)
	end
	registry.RegisterAlias = function(first: any, second: any, third: any?)
		if first == registry then
			return Registry.RegisterAlias(registry, second, third)
		end
		return Registry.RegisterAlias(registry, first, second)
	end
	registry.UnregisterAlias = function(first: any, second: any?)
		return Registry.UnregisterAlias(registry, if first == registry then second else first)
	end
	registry.Destroy = function(_first: any?)
		Registry.Destroy(registry)
	end
	return registry
end

Icons.New = Icons.new

return Icons

end

