local function addCorner(parent: Instance, radius: number, name: string): UICorner
	local value = Instance.new("UICorner")
	value.Name = name
	value.CornerRadius = UDim.new(0, radius)
	value.Parent = parent
	return value
end

local function copyArray(source: any): { any }
	local result = {}
	if type(source) == "table" then
		for index, value in ipairs(source) do
			result[index] = value
		end
	end
	return result
end


local function hasChoice(choices: { any }, value: any): boolean
	for _, choice in ipairs(choices) do
		if choice == value then return true end
	end
	return false
end

local function multiSummary(values: { any }, total: number): string
	if #values == 0 then return "None" end
	if total > 0 and #values == total then return "All" end
	return tostring(#values) .. " / " .. tostring(total)
end

local function addStroke(parent: Instance, color: Color3, name: string): UIStroke
	local value = Instance.new("UIStroke")
	value.Name = name
	value.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	value.LineJoinMode = Enum.LineJoinMode.Round
	value.Thickness = 1
	value.Color = color
	value.Parent = parent
	return value
end

local function applyTextRendering(object: any)
	object.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
	object.TextStrokeTransparency = 1
end

local function createWindowEffects(ui: any, frame: GuiObject): (Frame, Frame)
	local shadowRoot = Instance.new("Frame")
	shadowRoot.Name = "WindowShadow"
	shadowRoot.Active = false
	shadowRoot.BackgroundTransparency = 1
	shadowRoot.BorderSizePixel = 0
	shadowRoot.ClipsDescendants = false
	shadowRoot.ZIndex = 1
	shadowRoot.Parent = frame.Parent
	ui._effectLayers = {}
	for _, specification in ipairs(SHADOW_LAYERS) do
		local spread = SHADOW_SPREAD * specification.spread
		local offset = SHADOW_OFFSET * specification.offset
		local layer = Instance.new("Frame")
		layer.Name = "Shadow" .. specification.name
		layer.Active = false
		layer.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
		layer.BackgroundTransparency = 1 - SHADOW_AMOUNT * specification.opacity
		layer.BorderSizePixel = 0
		layer.ClipsDescendants = false
		layer.Position = UDim2.fromOffset(-spread + offset.X, -spread + offset.Y)
		layer.Size = UDim2.new(1, spread * 2, 1, spread * 2)
		layer.ZIndex = 1
		layer.Parent = shadowRoot
		addCorner(layer, SHELL_RADIUS + spread, "ShadowCorner")
		local stroke = addStroke(layer, Color3.fromRGB(0, 0, 0), "ShadowSoftEdge")
		stroke.Thickness = math.max(1, spread * 0.35)
		stroke.Transparency = 1 - SHADOW_AMOUNT * specification.stroke
		table.insert(ui._effectLayers, { Root = layer, Stroke = stroke, BackgroundTransparency = layer.BackgroundTransparency, StrokeTransparency = stroke.Transparency })
	end
	local glowRoot = Instance.new("Frame")
	glowRoot.Name = "WindowGlow"
	glowRoot.Active = false
	glowRoot.BackgroundTransparency = 1
	glowRoot.BorderSizePixel = 0
	glowRoot.ClipsDescendants = false
	glowRoot.ZIndex = 2
	glowRoot.Parent = frame.Parent
	ui._glowLayers = {}
	for _, specification in ipairs(GLOW_LAYERS) do
		local layer = Instance.new("Frame")
		layer.Name = "Glow" .. specification.name
		layer.Active = false
		layer.BackgroundColor3 = ui._palette.Accent
		layer.BackgroundTransparency = 1 - specification.opacity
		layer.BorderSizePixel = 0
		layer.ClipsDescendants = false
		layer.Position = UDim2.fromOffset(-specification.spread, -specification.spread)
		layer.Size = UDim2.new(1, specification.spread * 2, 1, specification.spread * 2)
		layer.ZIndex = 2
		layer.Parent = glowRoot
		addCorner(layer, SHELL_RADIUS + specification.spread, "GlowCorner")
		local stroke = addStroke(layer, ui._palette.Accent, "GlowSoftEdge")
		stroke.Thickness = math.max(1, specification.spread * 0.4)
		stroke.Transparency = 1 - specification.stroke
		local record = { Root = layer, Stroke = stroke, BackgroundTransparency = layer.BackgroundTransparency, StrokeTransparency = stroke.Transparency }
		table.insert(ui._glowLayers, record)
		table.insert(ui._effectLayers, record)
	end
	local function sync()
		for _, effectRoot in ipairs({ shadowRoot, glowRoot }) do
			effectRoot.AnchorPoint = frame.AnchorPoint
			effectRoot.Position = frame.Position
			effectRoot.Size = frame.Size
			effectRoot.Visible = frame.Visible
		end
	end
	sync()
	for _, property in ipairs({ "Position", "Size", "Visible" }) do
		local connection = frame:GetPropertyChangedSignal(property):Connect(sync)
		table.insert(ui._connections, connection)
	end
	return shadowRoot, glowRoot
end

local function toneColor(palette: any, tone: any): Color3
	local colors = if palette == LIGHT then LIGHT_TONE_COLORS else TONE_COLORS
	return colors[tone] or palette.Muted
end

local function toneSurface(palette: any, tone: any): Color3
	local signal = if tone == nil or tone == "neutral" then nil else toneColor(palette, tone)
	return if signal == nil then palette.Toast else palette.Toast:Lerp(signal, 0.18)
end

local function recolorIcon(root: Instance?, color: Color3)
	if root == nil then return end
	for _, descendant in ipairs(root:GetDescendants()) do
		if descendant:IsA("Frame") and descendant.BackgroundTransparency < 1 then
			descendant.BackgroundColor3 = color
		elseif descendant:IsA("UIStroke") then
			descendant.Color = color
		elseif descendant:IsA("ImageLabel") then
			descendant.ImageColor3 = color
		elseif descendant:IsA("TextLabel") then
			descendant.TextColor3 = color
		end
	end
end

local function recolorBrandIcon(root: Instance?, palette: any)
	if root == nil then return end
	for _, descendant in ipairs(root:GetDescendants()) do
		if descendant:IsA("Frame") then
			local role = descendant:GetAttribute("BrandRole")
			if role == "accent" then
				descendant.BackgroundColor3 = Color3.fromRGB(78, 127, 252)
			elseif role == "accentDeep" then
				descendant.BackgroundColor3 = Color3.fromRGB(55, 95, 219)
			elseif role == "foreground" then
				descendant.BackgroundColor3 = palette.Text
			elseif role == "coreSurface" then
				descendant.BackgroundColor3 = palette.Shell
			end
		end
	end
end

local function resizeBrandIcon(root: Frame, size: number)
	root.Size = UDim2.fromOffset(size, size)
	local downsample = root:FindFirstChild("Downsample", true)
	if downsample ~= nil and downsample:IsA("UIScale") then
		downsample.Scale = size / 48
	end
end

local function errorResult(code: string, message: string): any return { code = code, message = message } end
local function option(source: any, upper: string, lower: string, fallback: any): any
	if type(source) == "table" then if source[upper] ~= nil then return source[upper] end; if source[lower] ~= nil then return source[lower] end end
	return fallback
end
local function runtimeGuiService(runtimeOptions: any): any
	local services = option(runtimeOptions, "Services", "services", {})
	if type(services) == "table" and services.GuiService ~= nil then
		return services.GuiService
	end
	local ok, guiService = pcall(function()
		return game:GetService("GuiService")
	end)
	return if ok then guiService else nil
end
local function text(options: any, fallback: string): string return tostring(option(options, "Text", "text", option(options, "Title", "title", option(options, "Name", "name", fallback)))) end
local function connect(ui: any, signal: RBXScriptSignal, callback: () -> (), owner: { any }?)
	local c = signal:Connect(callback)
	table.insert(ui._connections, c)
	if owner ~= nil then table.insert(owner, c) end
	return c
end
local function frameSize(value: any): UDim2
	if value == nil then return UDim2.fromOffset(600, 400) end
	if typeof(value) == "Vector2" then return UDim2.fromOffset(value.X, value.Y) end
	if typeof(value) == "UDim2" then return value end
	error("Window.Size must be a Vector2 or UDim2")
end
local function restoreStretchSize(size: UDim2): UDim2
	return UDim2.new(size.X.Scale, math.max(1, size.X.Offset - 8), size.Y.Scale, size.Y.Offset + 20)
end
local function restoreStretchPosition(position: UDim2): UDim2
	return UDim2.new(position.X.Scale, position.X.Offset, position.Y.Scale, position.Y.Offset + 10)
end
local function windowWidth(ui: any): number
	local root = ui.Root
	local width = if root.Size.X.Scale == 0 and root.Size.X.Offset > 0 then root.Size.X.Offset else root.AbsoluteSize.X
	return if width > 0 then width else 600
end

local function searchRestWidth(ui: any): number
	return math.clamp(SEARCH_MIN_WIDTH + windowWidth(ui) - DEFAULT_WINDOW_WIDTH, SEARCH_MIN_WIDTH, SEARCH_MAX_WIDTH)
end

local function searchWidth(ui: any): number
	local restWidth = searchRestWidth(ui)
	if not ui._searchFocused then
		return restWidth
	end
	local widthBeforeHeaderActions = windowWidth(ui) - 2 * (CLOSE_WIDTH + MINIMIZE_WIDTH + SEARCH_ACTIONS_CLEARANCE)
	return math.min(restWidth + SEARCH_FOCUS_EXPANSION, SEARCH_FOCUS_MAX_WIDTH, math.max(restWidth, widthBeforeHeaderActions))
end

local function searchResultsWidth(ui: any): number
	return searchWidth(ui) + SEARCH_RESULTS_EXTRA_WIDTH
end

local function searchHostPosition(ui: any, width: number): UDim2
	return UDim2.fromOffset(math.round((windowWidth(ui) - width) / 2), HEADER_CENTER_Y)
end

local function searchResultsPosition(ui: any, y: number): UDim2
	return UDim2.fromOffset(math.round((windowWidth(ui) - searchResultsWidth(ui)) / 2), y)
end

local function layoutSearchGeometry(ui: any, searchVisible: boolean, applyHostSize: boolean): number
	local width = searchWidth(ui)
	ui._searchHost.Visible = searchVisible
	ui._searchHost.Position = searchHostPosition(ui, width)
	if applyHostSize then
		ui:_tween(ui._searchHost, INSTANT_MOTION, { Size = UDim2.fromOffset(width, SEARCH_HEIGHT) })
	end
	local titleWidth = math.max(
		0,
		math.floor(
			if searchVisible
				then windowWidth(ui) / 2 - (width / 2 + 62)
				else windowWidth(ui) - (54 + CLOSE_WIDTH + MINIMIZE_WIDTH)
		)
	)
	if ui._title ~= nil then
		ui._title.Position = UDim2.fromOffset(54, 4)
		ui._title.Size = UDim2.fromOffset(titleWidth, 18)
	end
	if ui._gameTitle ~= nil then
		ui._gameTitle.Position = UDim2.fromOffset(54, 22)
		ui._gameTitle.Size = UDim2.fromOffset(titleWidth, 14)
	end
	if ui._searchResults ~= nil then
		ui._searchResults.Position = searchResultsPosition(ui, ui._searchResults.Position.Y.Offset)
		ui._searchResults.Size = UDim2.fromOffset(searchResultsWidth(ui), ui._searchResults.Size.Y.Offset)
		if not searchVisible then
			ui._searchResults.Visible = false
		end
	end
	return width
end

local function isCompact(ui: any): boolean
	return windowWidth(ui) < COMPACT_BREAKPOINT
end

local function layoutChrome(ui: any)
	if ui._header == nil or ui._tabsFrame == nil or ui._pages == nil then
		return
	end
	local compact = isCompact(ui)
	ui._header.Size = UDim2.new(1, 0, 0, HEADER_HEIGHT)
	if ui._searchHost ~= nil and ui._search ~= nil then
		layoutSearchGeometry(ui, not compact and windowWidth(ui) >= 580, true)
	end
	if compact then
		ui._tabsFrame.Position = UDim2.fromOffset(0, HEADER_HEIGHT)
		ui._tabsFrame.Size = UDim2.new(1, 0, 0, TAB_HEIGHT)
		ui._pages.Position = UDim2.fromOffset(0, HEADER_HEIGHT + TAB_HEIGHT)
		ui._pages.Size = UDim2.new(1, 0, 1, -(HEADER_HEIGHT + TAB_HEIGHT))
		ui._tabsFrame.ScrollingDirection = Enum.ScrollingDirection.X
		ui._tabsFrame.CanvasSize = UDim2.fromOffset(#(ui.Window and ui.Window._tabs or {}) * SIDEBAR_WIDTH, 0)
	else
		ui._tabsFrame.Position = UDim2.fromOffset(0, HEADER_HEIGHT)
		ui._tabsFrame.Size = UDim2.new(0, SIDEBAR_WIDTH, 1, -HEADER_HEIGHT)
		ui._pages.Position = UDim2.fromOffset(SIDEBAR_WIDTH, HEADER_HEIGHT)
		ui._pages.Size = UDim2.new(1, -SIDEBAR_WIDTH, 1, -HEADER_HEIGHT)
		ui._tabsFrame.ScrollingDirection = Enum.ScrollingDirection.Y
		ui._tabsFrame.CanvasSize = UDim2.fromOffset(0, 14 + #(ui.Window and ui.Window._tabs or {}) * (TAB_HEIGHT + CONTROL_GAP))
	end
	if ui._tabTopDivider ~= nil and ui._tabSideDivider ~= nil then
		ui._tabTopDivider.Position = UDim2.fromOffset(0, HEADER_HEIGHT)
		ui._tabTopDivider.Size = if compact then UDim2.new(1, 0, 0, 1) else UDim2.fromOffset(SIDEBAR_WIDTH, 1)
		ui._tabSideDivider.Visible = not compact
		ui._tabSideDivider.Position = UDim2.fromOffset(SIDEBAR_WIDTH - 1, HEADER_HEIGHT)
		ui._tabSideDivider.Size = UDim2.new(0, 1, 1, -HEADER_HEIGHT)
	end
	for index, tab in ipairs(ui.Window and ui.Window._tabs or {}) do
		if compact then
			tab.Root.Position = UDim2.fromOffset((index - 1) * SIDEBAR_WIDTH, 0)
			tab.Root.Size = UDim2.fromOffset(SIDEBAR_WIDTH, TAB_HEIGHT)
		else
			tab.Root.Position = UDim2.fromOffset(7, 7 + (index - 1) * (TAB_HEIGHT + CONTROL_GAP))
			tab.Root.Size = UDim2.new(1, -14, 0, TAB_HEIGHT)
		end
	end
	if ui._tabRail ~= nil and ui.Window ~= nil and ui.Window._selected ~= nil then
		local selectedIndex = ui.Window._selected._index
		ui._tabRail.AnchorPoint = Vector2.new(0, 0)
		ui._tabRail.Size = UDim2.fromOffset(2, 24)
		ui._tabRail.Position = if compact
			then UDim2.fromOffset((selectedIndex - 1) * SIDEBAR_WIDTH, 10)
			else UDim2.fromOffset(7, 17 + (selectedIndex - 1) * (TAB_HEIGHT + CONTROL_GAP))
	end
	if ui._toast ~= nil then
		ui._toast.Size = UDim2.fromOffset(math.max(0, math.min(300, windowWidth(ui) - 24)), CONTROL_HEIGHT)
	end
end

local function layoutTab(tab: any)
	local compact = isCompact(tab._ui)
	local leftY, rightY = BODY_PADDING, BODY_PADDING
	local pageWidth = math.round(tab.Page.AbsoluteSize.X)
	if pageWidth <= 0 then pageWidth = math.max(0, math.round(windowWidth(tab._ui) - SIDEBAR_WIDTH)) end
	local split = math.floor(pageWidth / 2)
	local leftWidth = math.max(0, split - (BODY_PADDING + 4))
	local rightX = split + 4
	local rightWidth = math.max(0, pageWidth - rightX - BODY_PADDING)
	for _, section in ipairs(tab._sections) do
		if compact then
			local y = math.max(leftY, rightY)
			section.Root.Position = UDim2.new(0, BODY_PADDING, 0, y)
			section.Root.Size = UDim2.new(1, -(BODY_PADDING * 2), 0, section._height)
			leftY = y + section._height + SECTION_GAP
			rightY = leftY
		elseif section._side == "Full" then
			local y = math.max(leftY, rightY)
			section.Root.Position = UDim2.new(0, BODY_PADDING, 0, y)
			section.Root.Size = UDim2.new(1, -(BODY_PADDING * 2), 0, section._height)
			leftY = y + section._height + SECTION_GAP
			rightY = leftY
		elseif section._side == "Right" then
			section.Root.Position = UDim2.fromOffset(rightX, rightY)
			section.Root.Size = UDim2.fromOffset(rightWidth, section._height)
			rightY += section._height + SECTION_GAP
		else
			section.Root.Position = UDim2.fromOffset(BODY_PADDING, leftY)
			section.Root.Size = UDim2.fromOffset(leftWidth, section._height)
			leftY += section._height + SECTION_GAP
		end
	end
	tab.Page.CanvasSize = UDim2.fromOffset(0, math.max(leftY, rightY) + BODY_PADDING)
end

local function layoutSection(section: any)
	local y = SECTION_HEADER_HEIGHT
	for _, control in ipairs(section._controls) do
		local visible = not control._destroyed and control._visible and control._searchVisible ~= false
		control.Root.Visible = visible
		if visible then
			control.Root.Position = UDim2.fromOffset(8, y)
			control.Root.Size = UDim2.new(1, -16, 0, CONTROL_HEIGHT)
			y += CONTROL_HEIGHT + CONTROL_GAP
		end
	end
	section._nextY = y
	section._height = y + 4
	layoutTab(section._tab)
end

local function makeControl(section: any, options: any, kind: string): any
	options = if type(options) == "table" then options else {}
	local multiRequested = kind == "Dropdown" and option(options, "Multi", "multi", false) == true
	local attachedOptions = if kind == "Toggle" then option(options, "Options", "options", nil) else nil
	if attachedOptions ~= nil and type(attachedOptions) ~= "table" then
		return nil, errorResult("invalid_toggle_options", "Toggle Options must be a table")
	end
	local multiChoices, multiSelection = {}, {}
	local maxSelections = option(options, "MaxSelections", "maxSelections", nil)
	if multiRequested then
		local sourceChoices = option(options, "Choices", "choices", option(options, "Options", "options", {}))
		if type(sourceChoices) ~= "table" then return nil, errorResult("invalid_multi_choices", "Multi-select Choices must be an array") end
		for _, choice in ipairs(sourceChoices) do
			if not hasChoice(multiChoices, choice) then table.insert(multiChoices, choice) end
		end
		if maxSelections ~= nil and (type(maxSelections) ~= "number" or maxSelections < 1 or maxSelections % 1 ~= 0) then
			return nil, errorResult("invalid_max_selections", "MaxSelections must be a positive integer")
		end
		local default = option(options, "Default", "default", option(options, "Value", "value", {}))
		if type(default) ~= "table" then return nil, errorResult("invalid_multi_value", "Multi-select Default must be an array") end
		local count = 0
		for key in pairs(default) do
			if type(key) ~= "number" or key < 1 or key % 1 ~= 0 then return nil, errorResult("invalid_multi_value", "Multi-select Default must be an array") end
			count = math.max(count, key)
		end
		if maxSelections ~= nil and count > maxSelections then return nil, errorResult("max_selections_exceeded", "Multi-select Default exceeds MaxSelections") end
		for index = 1, count do
			local choice = default[index]
			if choice == nil then return nil, errorResult("invalid_multi_value", "Multi-select Default must be an array") end
			if not hasChoice(multiChoices, choice) then return nil, errorResult("unknown_choice", "Multi-select Default contains an unknown choice") end
			if hasChoice(multiSelection, choice) then return nil, errorResult("duplicate_choice", "Multi-select Default contains a duplicate choice") end
			table.insert(multiSelection, choice)
		end
	end
	local label = if kind == "KeyValue"
		then tostring(option(options, "Label", "label", text(options, kind)))
		else text(options, kind)
	local root: any = Instance.new(if kind == "Label" then "TextLabel" else "TextButton")
	root.Name = kind
	root.Size = UDim2.new(1, -16, 0, CONTROL_HEIGHT)
	root.BorderSizePixel = 0
	root.Font = Enum.Font.BuilderSansMedium
	root.FontFace = FONT_MEDIUM
	root.TextSize = 14
	root.TextXAlignment = Enum.TextXAlignment.Left
	root.TextYAlignment = Enum.TextYAlignment.Center
	applyTextRendering(root)
	root.TextTruncate = Enum.TextTruncate.AtEnd
	root.Parent = section.Root
	addCorner(root, CONTROL_RADIUS, "ControlCorner")
	local controlStroke = addStroke(root, section._ui._palette.Border, "ControlStroke")
	local divider = Instance.new("Frame")
	divider.Name = "RowDivider"
	divider.BackgroundColor3 = section._ui._palette.Border
	divider.BorderSizePixel = 0
	divider.Position = UDim2.new(0, 10, 1, -1)
	divider.Size = UDim2.new(1, -20, 0, 1)
	divider.ZIndex = root.ZIndex + 1
	divider.Parent = root
	local dividerGradient = Instance.new("UIGradient")
	dividerGradient.Name = "DividerFade"
	dividerGradient.Transparency = CENTER_FADE_TRANSPARENCY
	dividerGradient.Parent = divider
	local buttonSurface, buttonLabel, inlineLabel = nil, nil, nil
	if kind == "Button" then
		root.Text = ""
		root.TextXAlignment = Enum.TextXAlignment.Center
		buttonSurface = Instance.new("Frame")
		buttonSurface.Name = "ButtonSurface"
		buttonSurface.AnchorPoint = Vector2.new(0, 0.5)
		buttonSurface.BackgroundColor3 = section._ui._palette.Control
		buttonSurface.BorderSizePixel = 0
		buttonSurface.Position = UDim2.new(0, 2, 0.5, 0)
		buttonSurface.Size = UDim2.new(1, -4, 0, 34)
		buttonSurface.ZIndex = root.ZIndex
		buttonSurface.Parent = root
		addCorner(buttonSurface, CONTROL_RADIUS, "ButtonSurfaceCorner")
		controlStroke.Parent = buttonSurface
		buttonLabel = Instance.new("TextLabel")
		buttonLabel.Name = "ButtonLabel"
		buttonLabel.BackgroundTransparency = 1
		buttonLabel.Size = UDim2.fromScale(1, 1)
		buttonLabel.Font = Enum.Font.BuilderSansBold
		buttonLabel.FontFace = FONT_SEMIBOLD
		buttonLabel.TextSize = 14
		buttonLabel.TextTruncate = Enum.TextTruncate.AtEnd
		buttonLabel.TextXAlignment = Enum.TextXAlignment.Center
		buttonLabel.TextYAlignment = Enum.TextYAlignment.Center
		buttonLabel.ZIndex = root.ZIndex + 1
		applyTextRendering(buttonLabel)
		buttonLabel.Parent = buttonSurface
	end
	if kind ~= "Button" and not multiRequested then
		root.Text = ""
		inlineLabel = Instance.new("TextLabel")
		inlineLabel.Name = "InlineLabel"
		inlineLabel.Active = false
		inlineLabel.BackgroundTransparency = 1
		inlineLabel.Position = UDim2.fromOffset(CONTROL_TEXT_INSET, CONTROL_TEXT_Y)
		inlineLabel.Size = UDim2.new(
			1,
			if kind == "Toggle"
				then -(CONTROL_TEXT_INSET + if attachedOptions ~= nil then 98 else 58)
				else -(CONTROL_TEXT_INSET + 2),
			1,
			0
		)
		inlineLabel.Font = Enum.Font.BuilderSansMedium
		inlineLabel.FontFace = FONT_MEDIUM
		inlineLabel.TextSize = 14
		inlineLabel.TextTruncate = Enum.TextTruncate.AtEnd
		inlineLabel.TextXAlignment = Enum.TextXAlignment.Left
		inlineLabel.TextYAlignment = Enum.TextYAlignment.Center
		inlineLabel.ZIndex = root.ZIndex + 1
		applyTextRendering(inlineLabel)
		inlineLabel.Parent = root
	end
	local toggleTarget, toggleTrack, toggleGlow, toggleThumbCarrier, toggleThumb, toggleThumbStroke, toggleTrackStroke, toggleScale, optionsTarget, optionsIcon = nil, nil, nil, nil, nil, nil, nil, nil, nil, nil
	if kind == "Toggle" then
		toggleTarget = Instance.new("TextButton")
		toggleTarget.Name = "SwitchTarget"
		toggleTarget.AnchorPoint = Vector2.new(1, 0.5)
		toggleTarget.AutoButtonColor = false
		toggleTarget.BackgroundTransparency = 1
		toggleTarget.BorderSizePixel = 0
		toggleTarget.Position = UDim2.new(1, -8, 0.5, 0)
		toggleTarget.Size = UDim2.fromOffset(44, 44)
		toggleTarget.Text = ""
		toggleTarget.ZIndex = root.ZIndex + 2
		toggleTarget.Parent = root
		toggleTrack = Instance.new("Frame")
		toggleTrack.Name = "ToggleTrack"
		toggleTrack.AnchorPoint = Vector2.new(0.5, 0.5)
		toggleTrack.BackgroundColor3 = section._ui._palette.Control
		toggleTrack.BorderSizePixel = 0
		toggleTrack.Position = UDim2.fromScale(0.5, 0.5)
		toggleTrack.Size = UDim2.fromOffset(32, 18)
		toggleTrack.ZIndex = toggleTarget.ZIndex + 1
		toggleTrack.Parent = toggleTarget
		addCorner(toggleTrack, 9, "ToggleTrackCorner")
		toggleTrackStroke = addStroke(toggleTrack, section._ui._palette.Muted, "ToggleTrackStroke")
		toggleTrackStroke.Transparency = 0.85
		toggleTrackStroke:SetAttribute("RayfieldMotionGhostDuration", 0.25)
		toggleGlow = Instance.new("Frame")
		toggleGlow.Name = "ToggleGlow"
		toggleGlow.AnchorPoint = Vector2.new(0.5, 0.5)
		toggleGlow.BackgroundColor3 = section._ui._palette.Accent
		toggleGlow.BackgroundTransparency = 1
		toggleGlow.BorderSizePixel = 0
		toggleGlow.Position = UDim2.fromOffset(9, 9)
		toggleGlow.Size = UDim2.fromOffset(20, 20)
		toggleGlow.ZIndex = toggleTrack.ZIndex + 1
		toggleGlow.Parent = toggleTrack
		addCorner(toggleGlow, 10, "ToggleGlowCorner")
		toggleThumbCarrier = Instance.new("Frame")
		toggleThumbCarrier.Name = "ToggleThumbCarrier"
		toggleThumbCarrier.AnchorPoint = Vector2.new(0.5, 0.5)
		toggleThumbCarrier.BackgroundTransparency = 1
		toggleThumbCarrier.BorderSizePixel = 0
		toggleThumbCarrier.Position = UDim2.fromOffset(9, 9)
		toggleThumbCarrier.Size = UDim2.fromOffset(12, 12)
		toggleThumbCarrier.ZIndex = toggleTrack.ZIndex + 2
		toggleThumbCarrier.Parent = toggleTrack
		toggleThumb = Instance.new("Frame")
		toggleThumb.Name = "ToggleThumb"
		toggleThumb.AnchorPoint = Vector2.new(0.5, 0.5)
		toggleThumb.BackgroundColor3 = section._ui._palette.Muted
		toggleThumb.BackgroundTransparency = 0.2
		toggleThumb.BorderSizePixel = 0
		toggleThumb.Position = UDim2.fromScale(0.5, 0.5)
		toggleThumb.Size = UDim2.fromOffset(12, 12)
		toggleThumb.ZIndex = toggleThumbCarrier.ZIndex + 1
		toggleThumb.Parent = toggleThumbCarrier
		addCorner(toggleThumb, 6, "ToggleThumbCorner")
		toggleThumbStroke = addStroke(toggleThumb, section._ui._palette.Muted, "ToggleThumbStroke")
		toggleThumbStroke.Transparency = 0.7
		toggleScale = Instance.new("UIScale")
		toggleScale.Name = "ToggleScale"
		toggleScale.Scale = 1
		toggleScale:SetAttribute("RayfieldMotionDuration", 0.6)
		toggleScale:SetAttribute("RayfieldMotionEasingStyle", "Exponential")
		toggleScale:SetAttribute("RayfieldMotionRestoreDelay", 0.11)
		toggleScale:SetAttribute("RayfieldMotionRestoreDuration", 0.25)
		toggleScale.Parent = toggleTrack
	end
	if attachedOptions ~= nil then
		optionsTarget = Instance.new("TextButton")
		optionsTarget.Name = "OptionsTrigger"
		optionsTarget.Active = true
		optionsTarget.AutoButtonColor = false
		optionsTarget.AnchorPoint = Vector2.new(1, 0.5)
		optionsTarget.BackgroundTransparency = 1
		optionsTarget.BorderSizePixel = 0
		optionsTarget.Position = UDim2.new(1, -56, 0.5, 0)
		optionsTarget.Size = UDim2.fromOffset(34, 34)
		optionsTarget.Text = ""
		optionsTarget.ZIndex = root.ZIndex + 2
		optionsTarget:SetAttribute("AccessibleName", tostring(option(attachedOptions, "Title", "title", label .. " Options")))
		optionsTarget:SetAttribute("AccessibleRole", "button")
		optionsTarget:SetAttribute("OpenDirection", "right")
		optionsTarget.Parent = root
		optionsIcon = section._ui.Icons.Render(optionsTarget, "more", nil, 16, {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Color3 = section._ui._palette.Muted,
			ZIndex = optionsTarget.ZIndex + 1,
		})
	end
	local multiLabel, multiTrigger, multiSummaryLabel, multiTriggerStroke = nil, nil, nil, nil
	if multiRequested then
		root.Text = ""
		multiLabel = Instance.new("TextLabel")
		multiLabel.Name = "MultiLabel"
		multiLabel.BackgroundTransparency = 1
		multiLabel.Position = UDim2.fromOffset(CONTROL_TEXT_INSET, CONTROL_TEXT_Y)
		multiLabel.Size = UDim2.new(1, -(MULTI_TRIGGER_WIDTH + CONTROL_TEXT_INSET + 10), 1, 0)
		multiLabel.Font = Enum.Font.BuilderSansMedium
		multiLabel.FontFace = FONT_MEDIUM
		multiLabel.TextSize = 14
		multiLabel.TextTruncate = Enum.TextTruncate.AtEnd
		multiLabel.TextXAlignment = Enum.TextXAlignment.Left
		multiLabel.TextYAlignment = Enum.TextYAlignment.Center
		multiLabel.ZIndex = root.ZIndex + 1
		applyTextRendering(multiLabel)
		multiLabel.Parent = root
		multiTrigger = Instance.new("Frame")
		multiTrigger.Name = "MultiTrigger"
		multiTrigger.AnchorPoint = Vector2.new(1, 0.5)
		multiTrigger.BackgroundColor3 = section._ui._palette.Control
		multiTrigger.BorderSizePixel = 0
		multiTrigger.Position = UDim2.new(1, -2, 0.5, 0)
		multiTrigger.Size = UDim2.fromOffset(MULTI_TRIGGER_WIDTH, MULTI_TRIGGER_HEIGHT)
		multiTrigger.ZIndex = root.ZIndex + 1
		multiTrigger.Parent = root
		addCorner(multiTrigger, CONTROL_RADIUS, "MultiTriggerCorner")
		multiTriggerStroke = addStroke(multiTrigger, section._ui._palette.Border, "MultiTriggerStroke")
		multiTriggerStroke.Transparency = 0.68
		multiSummaryLabel = Instance.new("TextLabel")
		multiSummaryLabel.Name = "MultiSummary"
		multiSummaryLabel.BackgroundTransparency = 1
		multiSummaryLabel.Position = UDim2.fromOffset(10, CONTROL_TEXT_Y)
		multiSummaryLabel.Size = UDim2.new(1, -38, 1, 0)
		multiSummaryLabel.Font = Enum.Font.BuilderSansMedium
		multiSummaryLabel.FontFace = FONT_MEDIUM
		multiSummaryLabel.TextSize = 14
		multiSummaryLabel.TextTruncate = Enum.TextTruncate.AtEnd
		multiSummaryLabel.TextXAlignment = Enum.TextXAlignment.Left
		multiSummaryLabel.TextYAlignment = Enum.TextYAlignment.Center
		multiSummaryLabel.ZIndex = multiTrigger.ZIndex + 1
		applyTextRendering(multiSummaryLabel)
		multiSummaryLabel.Parent = multiTrigger
	end
	local dropdownChevron = nil
	if kind == "Dropdown" then
		local chevronParent = if multiRequested then multiTrigger else root
		dropdownChevron = section._ui.Icons.Render(chevronParent, "chevrondown", nil, 16, {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(1, -18, 0.5, 1),
			Color3 = section._ui._palette.Muted,
			ZIndex = chevronParent.ZIndex + 2,
		})
		dropdownChevron:SetAttribute("RayfieldMotionDuration", 0.2)
		dropdownChevron:SetAttribute("RayfieldMotionEasingStyle", "Exponential")
	end
	local control: any = {
		_toggleTarget = toggleTarget,
		Root = root,
		Value = if multiRequested then copyArray(multiSelection) else option(options, "Default", "default", option(options, "Value", "value", if kind == "Toggle" then false else nil)),
		_locked = false,
		_visible = true,
		_destroyed = false,
		_connections = {},
		_callback = option(options, "Callback", "callback", nil),
		_kind = kind,
		_label = label,
		_persist = (kind == "Toggle" or kind == "Dropdown") and option(options, "Persist", "persist", true) ~= false,
		_id = option(options, "Id", "id", nil),
		_ui = section._ui,
		_section = section,
		_searchVisible = true,
		_divider = divider,
		_dividerGradient = dividerGradient,
		_scale = toggleScale,
		_toggleTrack = toggleTrack,
		_toggleThumbCarrier = toggleThumbCarrier,
		_stateGeneration = 0,
		_toggleGlow = toggleGlow,
		_toggleThumb = toggleThumb,
		_toggleThumbStroke = toggleThumbStroke,
		_toggleTrackStroke = toggleTrackStroke,
		_attachedOptions = attachedOptions,
		_optionsTarget = optionsTarget,
		_optionsIcon = optionsIcon,
		_optionsControl = nil,
		_chevron = dropdownChevron,
		_multiLabel = multiLabel,
		_multiTrigger = multiTrigger,
		_multiSummaryLabel = multiSummaryLabel,
		_multiTriggerStroke = multiTriggerStroke,
		_buttonSurface = buttonSurface,
		_buttonLabel = buttonLabel,
		_inlineLabel = inlineLabel,
		_primary = kind == "Button" and option(options, "Primary", "primary", false) == true,
		_multi = multiRequested,
		_maxSelections = maxSelections,
		_selection = {},
		_pressGeneration = 0,
	}
	if kind == "Dropdown" then
		control.Choices = if multiRequested
			then copyArray(multiChoices)
			else copyArray(option(options, "Choices", "choices", option(options, "Options", "options", {})))
		if control._multi then
			control._selection = copyArray(multiSelection)
			control.Value = copyArray(multiSelection)
		end
	end
	function control:_render(animate: boolean?)
		if control._destroyed then
			return
		end
		if kind == "Toggle" then
			control._inlineLabel.Text = control._label
		elseif kind == "Dropdown" and control._multi then
			control._multiLabel.Text = control._label
			control._multiSummaryLabel.Text = multiSummary(control._selection, #control.Choices)
		elseif kind == "Dropdown" then
			control._inlineLabel.Text = control._label .. ": " .. (if control.Value == nil then "-" else tostring(control.Value))
		elseif kind == "KeyValue" then
			control._inlineLabel.Text = control._label .. ": " .. (if control.Value == nil then "-" else tostring(control.Value))
		elseif kind == "Button" then
			control._buttonLabel.Text = control._label
		else
			control._inlineLabel.Text = control._label
		end
		if kind == "Toggle" then
			root.Active = false
			root.AutoButtonColor = false
			control._toggleTarget.Active = not control._locked
		elseif kind ~= "Label" then
			root.Active = not control._locked
			root.AutoButtonColor = kind ~= "Button" and not control._locked and not control._multi
		end
		local palette = control._ui._palette
		local selected = kind == "Toggle" and control.Value == true
		local primaryButton = kind == "Button" and control._primary
		local background = if primaryButton and not control._locked then palette.Accent else palette.Control
		local backgroundTransparency = if kind == "Label" or control._multi
			then 1
			elseif control._locked
			then 0.18
			else 0
		local strokeColor = palette.Border
		local strokeTransparency = if kind == "Label" or control._multi
			then 1
			elseif control._locked
			then 0.75
			elseif kind == "Button"
			then if primaryButton then 0.18 else 0.38
			else 0.68
		local backgroundTarget = if kind == "Button" then control._buttonSurface else root
		if animate == true and kind == "Dropdown" then
			control._ui:_tween(backgroundTarget, RAYFIELD_DROPDOWN_MOTION, { BackgroundColor3 = background, BackgroundTransparency = backgroundTransparency })
			control._ui:_tween(controlStroke, RAYFIELD_DROPDOWN_MOTION, { Color = strokeColor, Transparency = strokeTransparency })
		else
			control._ui:_tween(backgroundTarget, INSTANT_MOTION, { BackgroundColor3 = background, BackgroundTransparency = backgroundTransparency })
			control._ui:_tween(controlStroke, INSTANT_MOTION, { Color = strokeColor, Transparency = strokeTransparency })
		end
		if kind == "Button" then
			root.BackgroundTransparency = 1
		end
		if control._multiTrigger ~= nil then
			local triggerTransparency = if control._locked then 0.18 else 0
			if animate == true then
				control._ui:_tween(control._multiTrigger, RAYFIELD_DROPDOWN_MOTION, { BackgroundColor3 = palette.Control, BackgroundTransparency = triggerTransparency })
				control._ui:_tween(control._multiTriggerStroke, RAYFIELD_DROPDOWN_MOTION, { Color = palette.Border, Transparency = if control._locked then 0.75 else 0.68 })
			else
				control._ui:_tween(control._multiTrigger, INSTANT_MOTION, { BackgroundColor3 = palette.Control, BackgroundTransparency = triggerTransparency })
				control._ui:_tween(control._multiTriggerStroke, INSTANT_MOTION, { Color = palette.Border, Transparency = if control._locked then 0.75 else 0.68 })
			end
			control._multiLabel.TextColor3 = if control._locked then palette.Disabled else palette.Text
			control._multiSummaryLabel.TextColor3 = if control._locked then palette.Disabled else palette.Muted
		end
		if control._toggleTrack ~= nil and control._toggleThumb ~= nil then
			local trackColor = if selected then palette.Accent else palette.Control
			local thumbColor = if selected then palette.Text else palette.Muted
			local thumbPosition = UDim2.fromOffset(if selected then 23 else 9, 9)
			local thumbTransparency = if selected then 0 else 0.2
			local thumbStrokeColor = if selected then palette.Text else palette.Muted
			local thumbStrokeTransparency = if selected then 0.45 else 0.7
			local glowTransparency = if selected then 0.72 else 1
			local trackTransparency = if control._locked then 0.35 else 0
			control._stateGeneration += 1
			if animate == true then
				local stateGeneration = control._stateGeneration
				control._ui:_tween(control._toggleTrack, RAYFIELD_TOGGLE_MOTION, { BackgroundColor3 = trackColor, BackgroundTransparency = trackTransparency })
				control._ui:_tween(control._toggleThumbCarrier, RAYFIELD_TOGGLE_MOTION, { Position = thumbPosition })
				control._ui:_tween(control._toggleThumb, RAYFIELD_TOGGLE_STRETCH, { BackgroundColor3 = thumbColor, BackgroundTransparency = thumbTransparency, Size = UDim2.fromOffset(16, 12) })
				control._ui:_tween(control._toggleThumbStroke, RAYFIELD_TOGGLE_STRETCH, { Color = thumbStrokeColor, Transparency = thumbStrokeTransparency })
				control._ui:_tween(control._toggleGlow, RAYFIELD_TOGGLE_MOTION, { BackgroundColor3 = palette.Accent, BackgroundTransparency = glowTransparency, Position = thumbPosition })
				task.delay(0.12, function()
					if control._destroyed or control._ui._destroyed or stateGeneration ~= control._stateGeneration then return end
					control._ui:_tween(control._toggleThumb, RAYFIELD_TOGGLE_UNSTRETCH, { Size = UDim2.fromOffset(12, 12) })
				end)
			else
				control._ui:_tween(control._toggleTrack, INSTANT_MOTION, { BackgroundColor3 = trackColor, BackgroundTransparency = trackTransparency })
