				control._ui:_tween(control._toggleThumb, INSTANT_MOTION, { BackgroundColor3 = thumbColor, BackgroundTransparency = thumbTransparency, Size = UDim2.fromOffset(12, 12) })
				control._ui:_tween(control._toggleThumbStroke, INSTANT_MOTION, { Color = thumbStrokeColor, Transparency = thumbStrokeTransparency })
				control._ui:_tween(control._toggleGlow, INSTANT_MOTION, { BackgroundColor3 = palette.Accent, BackgroundTransparency = glowTransparency, Position = thumbPosition })
