	function control:_press()
		control._pressGeneration += 1
		local generation = control._pressGeneration
		if kind == "Toggle" and control._scale ~= nil then
			control._pressing = true
			control._ui:_tween(control._scale, RAYFIELD_TOGGLE_MOTION, { Scale = 0.8125 })
