				then palette.Accent:Lerp(palette.Shell, 0.12)
				else palette.ControlSelected
			control._ui:_tween(control._buttonSurface, RAYFIELD_CONTROL_PRESS, { BackgroundColor3 = pressedColor })
			control._ui:_tween(controlStroke, RAYFIELD_CONTROL_PRESS, { Color = if control._primary then palette.Border else palette.Accent, Transparency = 0.18 })
			task.delay(0.08, function()
				if control._destroyed or control._ui._destroyed or generation ~= control._pressGeneration then return end
