				restingColor = if control._primary and not control._locked then currentPalette.Accent else currentPalette.Control
				control._ui:_tween(control._buttonSurface, RAYFIELD_CONTROL_PRESS, { BackgroundColor3 = restingColor })
				control._ui:_tween(controlStroke, RAYFIELD_CONTROL_PRESS, {
					Color = currentPalette.Border,
					Transparency = if control._locked then 0.75 elseif control._primary then 0.18 else 0.38,
				})
			end)
		end
	end
	function control:Get()
		return if control._multi then copyArray(control._selection) else control.Value
	end
	control.GetValue = control.Get
	function control:Snapshot()
		return table.freeze({ Value = if control._multi then table.freeze(copyArray(control._selection)) else control.Value })
	end
	function control:_validateSelection(value: any): ({ any }?, any?)
		if type(value) ~= "table" then return nil, errorResult("invalid_multi_value", "Multi-select value must be an array") end
		local count = 0
		for key in pairs(value) do
			if type(key) ~= "number" or key < 1 or key % 1 ~= 0 then return nil, errorResult("invalid_multi_value", "Multi-select value must be an array") end
			count = math.max(count, key)
		end
		for index = 1, count do if value[index] == nil then return nil, errorResult("invalid_multi_value", "Multi-select value must be an array") end end
		if control._maxSelections ~= nil and count > control._maxSelections then return nil, errorResult("max_selections_exceeded", "Multi-select value exceeds MaxSelections") end
