		for index = 1, count do
			local choice = value[index]
			if not hasChoice(control.Choices, choice) then return nil, errorResult("unknown_choice", "Multi-select value contains an unknown choice") end
			if hasChoice(nextSelection, choice) then return nil, errorResult("duplicate_choice", "Multi-select value contains a duplicate choice") end
