		local callbackValue = value
		if control._multi then
			local nextSelection, selectionError = control:_validateSelection(value)
			if nextSelection == nil then return nil, selectionError end
			control._selection = nextSelection
			control.Value = copyArray(nextSelection)
			callbackValue = copyArray(nextSelection)
