		if kind == "Dropdown" and control._ui._dropdownPopup.Control == control then control._ui:_closeDropdownPopup() end
		if control._ownerToggle ~= nil then control._ownerToggle:_render() end
		return control
	end
	function control:IsOpen(): boolean
		return kind == "Dropdown" and control._ui._dropdownPopup.Control == control
	end
