		if control._destroyed then return control end
		control._locked = locked == true
		if control._locked then control:Close() end
		if control._optionsControl ~= nil then control._optionsControl:SetLocked(control._locked) end
		control:_render()
		return control
	end
	function control:SetVisible(visible: boolean)
		if control._destroyed then return control end
		control._visible = visible ~= false
