		layoutSection(section)
		return control
	end
	function control:SetText(value: any)
		if control._destroyed then return control end
		control._label = tostring(value)
		control:_render()
		if kind == "Dropdown" and control._ui._dropdownPopup.Control == control then control._ui:_renderDropdownPopup() end
		if type(control._ui._renderSearchResults) == "function" then control._ui:_renderSearchResults() end
		return control
	end
	function control:Activate()
