			if connectionIndex ~= nil then table.remove(control._ui._connections, connectionIndex) end
		end
		table.clear(control._connections)
		local sectionIndex = table.find(section._controls, control)
		if sectionIndex ~= nil then table.remove(section._controls, sectionIndex) end
		local controlIndex = table.find(control._ui._controls, control)
		if controlIndex ~= nil then table.remove(control._ui._controls, controlIndex) end
