end
local function makeSection(tab: any, options: any): any
	options = if type(options) == "table" then options else {}
	local root = Instance.new("Frame")
	root.Name = "Section"
	root.BorderSizePixel = 0
	root.BackgroundTransparency = 0.02
	root.Parent = tab.Page
	addCorner(root, SECTION_RADIUS, "SectionCorner")
	local sectionStroke = addStroke(root, tab._ui._palette.Border, "SectionStroke")
	sectionStroke.Transparency = 0.18
	local iconName = option(options, "Icon", "icon", nil)
	local sectionIcon = nil
	if iconName ~= nil then
		sectionIcon = tab._ui.Icons.Render(root, iconName, nil, 16, {
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 10, 0, SECTION_HEADER_HEIGHT / 2),
			Color3 = tab._ui._palette.Text,
			ZIndex = root.ZIndex + 2,
		})
	end
	local title = Instance.new("TextLabel")
	title.Name = "Title"
	title.BackgroundTransparency = 1
	title.Position = UDim2.fromOffset(if sectionIcon ~= nil then 34 else 10, 0)
	title.Size = UDim2.new(1, if sectionIcon ~= nil then -44 else -20, 0, SECTION_HEADER_HEIGHT)
	title.Font = Enum.Font.BuilderSansBold
	title.FontFace = FONT_SEMIBOLD
	title.TextSize = 14
	title.TextXAlignment = Enum.TextXAlignment.Left
	title.TextYAlignment = Enum.TextYAlignment.Center
	title.ZIndex = root.ZIndex + 2
	applyTextRendering(title)
	title.Text = text(options, "Section")
	title.Parent = root
	local headerDivider = Instance.new("Frame")
	headerDivider.Name = "HeaderDivider"
	headerDivider.BackgroundColor3 = tab._ui._palette.Border
	headerDivider.BorderSizePixel = 0
	headerDivider.Position = UDim2.new(0, 10, 0, SECTION_HEADER_HEIGHT - 1)
	headerDivider.Size = UDim2.new(1, -20, 0, 1)
	headerDivider.ZIndex = root.ZIndex + 1
	headerDivider.Parent = root
	local headerDividerGradient = Instance.new("UIGradient")
	headerDividerGradient.Name = "DividerFade"
	headerDividerGradient.Transparency = CENTER_FADE_TRANSPARENCY
	headerDividerGradient.Parent = headerDivider
	local side = tostring(option(options, "Side", "side", "Left")); if side ~= "Right" and side ~= "Full" then side = "Left" end
	local section: any = {
		Root = root,
		_tab = tab,
		_ui = tab._ui,
		_side = side,
		_nextY = SECTION_HEADER_HEIGHT,
		_height = SECTION_HEADER_HEIGHT + 4,
		_controls = {},
		_title = title,
		_icon = sectionIcon,
		_divider = headerDivider,
		_dividerGradient = headerDividerGradient,
		_stroke = sectionStroke,
	}
	function section:Toggle(o: any)
		local control, controlError = makeControl(section, o, "Toggle")
		if control == nil or control._attachedOptions == nil then return control, controlError end
		local optionsConfig = {}
		for key, value in pairs(control._attachedOptions) do optionsConfig[key] = value end
		optionsConfig.Multi = true
		if optionsConfig.Title == nil and optionsConfig.title == nil then optionsConfig.Title = control._label .. " Options" end
		local optionsControl, optionsError = makeControl(section, optionsConfig, "Dropdown")
		if optionsControl == nil then
			control:Destroy()
			return nil, optionsError
		end
		local sectionIndex = table.find(section._controls, optionsControl)
		if sectionIndex ~= nil then table.remove(section._controls, sectionIndex) end
		optionsControl.Root.Visible = false
		optionsControl.Root.Size = UDim2.fromOffset(0, 0)
		optionsControl._embedded = true
		optionsControl._popupAnchor = control._optionsTarget
		optionsControl._popupDirection = "right"
		optionsControl._ownerToggle = control
		control._optionsControl = optionsControl
		control.Options = optionsControl
		if type(section._ui._renderSearchResults) == "function" then section._ui:_renderSearchResults() end
		connect(section._ui, control._optionsTarget.Activated, function()
			if control._destroyed or control._locked or not control._visible then return end
			if optionsControl:IsOpen() then optionsControl:Close() else optionsControl:Open() end
			control:_render()
		end, control._connections)
		connect(section._ui, control._optionsTarget:GetPropertyChangedSignal("AbsolutePosition"), function()
			if section._ui._dropdownPopup.Control == optionsControl and type(section._ui._repositionDropdownPopup) == "function" then section._ui:_repositionDropdownPopup() end
		end, control._connections)
		connect(section._ui, control._optionsTarget:GetPropertyChangedSignal("AbsoluteSize"), function()
			if section._ui._dropdownPopup.Control == optionsControl and type(section._ui._repositionDropdownPopup) == "function" then section._ui:_repositionDropdownPopup() end
		end, control._connections)
		control:_render()
		layoutSection(section)
		return control
	end
	function section:Dropdown(o: any) return makeControl(section, o, "Dropdown") end
	function section:Button(o: any) return makeControl(section, o, "Button") end
	function section:MultiDropdown(o: any)
		local options = {}
		if type(o) == "table" then for key, value in pairs(o) do options[key] = value end end
		options.Multi = true
		return makeControl(section, options, "Dropdown")
	end
	function section:KeyValue(o: any) return makeControl(section, o, "KeyValue") end
	function section:Label(o: any) return makeControl(section, o, "Label") end
	table.insert(tab._sections, section)
	table.insert(tab._ui._sections, section)
	root.BackgroundColor3 = tab._ui._palette.Section
	title.TextColor3 = tab._ui._palette.Text
	layoutTab(tab)
	return section
end

