	if type(libraryOptions) ~= "table" then return nil, nil, errorResult("invalid_library_options", "Framework Library options must be a table") end
	if type(windowOptions) ~= "table" then return nil, nil, errorResult("invalid_window_options", "Framework Window options must be a table") end
