				if instance:IsA("TextLabel") or instance:IsA("TextButton") or instance:IsA("TextBox") then
					captureFadeProperty(instance, properties, "TextTransparency")
					captureFadeProperty(instance, properties, "TextStrokeTransparency")
				end
				if instance:IsA("ImageLabel") or instance:IsA("ImageButton") then
					captureFadeProperty(instance, properties, "ImageTransparency")
				end
				if instance:IsA("UIStroke") then captureFadeProperty(instance, properties, "Transparency") end
				if instance:IsA("CanvasGroup") then captureFadeProperty(instance, properties, "GroupTransparency") end
				if instance:IsA("ScrollingFrame") then captureFadeProperty(instance, properties, "ScrollBarImageTransparency") end
				if next(properties) ~= nil then
					table.insert(snapshot, { Instance = instance, Properties = properties })
				end
			end
			for _, descendant in ipairs(page:GetDescendants()) do capture(descendant) end
			return snapshot
		end
		local function applyPageFade(snapshot: any, fade: boolean | number, tweenInfo: TweenInfo?)
			local alpha = if type(fade) == "number" then fade elseif fade then 1 else 0
			for _, record in ipairs(snapshot or {}) do
				local properties = {}
				for property, value in pairs(record.Properties) do properties[property] = if alpha == 1 then 1 else value + (1 - value) * alpha end
				ui:_tween(record.Instance, tweenInfo or INSTANT_MOTION, properties)
			end
		end
