		local function restoreDropdownPopupFade(popup: any)
			if popup.Fade ~= nil then
				applyPageFade(popup.Fade, false, nil)
				popup.Fade = nil
			end
		end
		local function settleDropdownPopup(popup: any, width: number, height: number)
			-- Cancel geometry ownership before restoring descendant opacity.
			ui:_tween(popup.Root, INSTANT_MOTION, {
				BackgroundTransparency = 0,
				Size = UDim2.fromOffset(width, height),
			})
			ui:_tween(popup.Shadow, INSTANT_MOTION, {
				BackgroundTransparency = 0.72,
				Size = UDim2.fromOffset(width, height),
			})
			restoreDropdownPopupFade(popup)
			popup.EnterAnimating = false
		end
		local function disconnectDropdownPopupRows(popup: any)
			for _, connection in ipairs(popup.RowConnections) do
				pcall(function()
					connection:Disconnect()
				end)
			end
			table.clear(popup.RowConnections)
		end
		local function clearDropdownPopupRows(popup: any)
			restoreDropdownPopupFade(popup)
			disconnectDropdownPopupRows(popup)
			table.clear(popup.RowChoices)
			for _, child in ipairs(popup.Rows:GetChildren()) do
				if child ~= popup.Layout then
					child:Destroy()
				end
			end
		end
		function ui:_closeDropdownPopup()
			local popup = ui._dropdownPopup
			local owner = popup.Control
			if owner == nil then
				return
			end
			popup.Control = nil
			if owner._ownerToggle ~= nil then owner._ownerToggle:_render() end
			popup.Generation += 1
			local generation = popup.Generation
			popup.EnterPending = false
			popup.EnterAnimating = false
			popup.Dismiss.Visible = false
			pcall(function()
				popup.Search:ReleaseFocus()
			end)
			if owner._multi == true then
				popup.ExitPending = true
				disconnectDropdownPopupRows(popup)
				popup.Root.Active = false
				popup.Rows.Active = false
				popup.Search.Active = false
				popup.Search.Selectable = false
				popup.Search.TextEditable = false
				for _, child in ipairs(popup.Rows:GetChildren()) do
					if child:IsA("GuiButton") then
						child.Active = false
						child.Selectable = false
					end
				end
				popup.Fade = popup.Fade or capturePageFade(popup.Root)
				ui:_tween(popup.Root, MULTI_DROPDOWN_EXIT, {
					BackgroundTransparency = 1,
					Size = UDim2.fromOffset(popup.Root.Size.X.Offset, 0),
				})
				applyPageFade(popup.Fade, true, MULTI_DROPDOWN_EXIT)
				ui:_tween(popup.Shadow, MULTI_DROPDOWN_EXIT, {
					BackgroundTransparency = 1,
					Size = UDim2.fromOffset(popup.Shadow.Size.X.Offset, 0),
				})
				if owner._chevron ~= nil then
					owner._chevron:SetAttribute("RayfieldMotionDuration", MULTI_DROPDOWN_EXIT.Time)
					ui:_tween(owner._chevron, MULTI_DROPDOWN_EXIT, { Rotation = 0 })
				end
				task.delay(MULTI_DROPDOWN_EXIT.Time, function()
					if ui._destroyed or popup.Generation ~= generation or popup.Control ~= nil then
						return
					end
					popup.ExitPending = false
					popup.Root.Visible = false
					popup.Shadow.Visible = false
					ui:_tween(popup.Root, INSTANT_MOTION, {
						BackgroundTransparency = 1,
						Size = UDim2.fromOffset(popup.Root.Size.X.Offset, 0),
					})
					ui:_tween(popup.Shadow, INSTANT_MOTION, {
						BackgroundTransparency = 1,
						Size = UDim2.fromOffset(popup.Shadow.Size.X.Offset, 0),
					})
					clearDropdownPopupRows(popup)
					if popup.Search.Text ~= "" then
						popup.Search.Text = ""
					end
				end)
				return
			end

			popup.ExitPending = false
			settleDropdownPopup(popup, popup.Root.Size.X.Offset, popup.Root.Size.Y.Offset)
			clearDropdownPopupRows(popup)
			if popup.Search.Text ~= "" then
				popup.Search.Text = ""
			end
			popup.Root.Active = false
			popup.Root.Visible = false
			popup.Shadow.Visible = false
			if owner._chevron ~= nil then
				ui:_tween(owner._chevron, RAYFIELD_DROPDOWN_CHEVRON, { Rotation = 0 })
			end
		end
		function ui:_renderDropdownPopup()
			local popup = ui._dropdownPopup
			local control = popup.Control
			local owner = control and control._ownerToggle
			local ownerBlocked = owner ~= nil and (owner._destroyed or owner._locked or not owner._visible or owner._searchVisible == false)
			local windowBlocked = control == nil or ui.Window == nil or ui.Window._minimized or ui.Window._minimizeAnimating or control._section._tab ~= ui.Window._selected
			if windowBlocked or ownerBlocked or control._destroyed or control._locked or not control._visible or control._searchVisible == false or #control.Choices == 0 or not ui._open then
				ui:_closeDropdownPopup()
				return
			end
			ui:_tween(popup.Root, INSTANT_MOTION, {
				BackgroundTransparency = popup.Root.BackgroundTransparency,
				Size = popup.Root.Size,
			})
			ui:_tween(popup.Shadow, INSTANT_MOTION, {
				BackgroundTransparency = popup.Shadow.BackgroundTransparency,
				Size = popup.Shadow.Size,
			})
			restoreDropdownPopupFade(popup)
			popup.EnterAnimating = false
			local multi = control._multi == true
			local opensRight = control._popupDirection == "right"
			local popupParent = if opensRight then gui else root
			if popup.Root.Parent ~= popupParent then
				popup.Dismiss.Parent = popupParent
				popup.Shadow.Parent = popupParent
				popup.Root.Parent = popupParent
			end
			popup.Root:SetAttribute("OpenDirection", if opensRight then "right" else "contained")
			local popupBounds = if opensRight then pixelGrid.AbsoluteSize else root.AbsoluteSize
			local popupOrigin = if opensRight then pixelGrid.AbsolutePosition else root.AbsolutePosition
			local animatePresence = multi and popup.EnterPending == true
			local resumePresence = animatePresence and popup.ResumePresence == true
			local selectedCount = if multi then #control._selection else 0
			local limitReached = multi and control._maxSelections ~= nil and selectedCount >= control._maxSelections
			local showSearch = multi and #control.Choices >= MULTI_SEARCH_THRESHOLD
			local query = if showSearch then string.lower(popup.Search.Text) else ""
			local visibleChoices = {}
			for _, choice in ipairs(control.Choices) do
				if query == "" or string.find(string.lower(tostring(choice)), query, 1, true) ~= nil then
					table.insert(visibleChoices, choice)
				end
			end
			popup.Root.BackgroundColor3 = ui._palette.Popup
			popup.Stroke.Color = ui._palette.Border
			ui:_tween(popup.Stroke, INSTANT_MOTION, { Transparency = 0.48 })
			popup.Rows.ScrollBarImageColor3 = ui._palette.Muted
			popup.Header.Visible = multi
			popup.Title.Text = control._label
			popup.Title.TextColor3 = ui._palette.Text
			popup.Count.Text = tostring(selectedCount) .. " / " .. tostring(#control.Choices)
			popup.Count.TextColor3 = ui._palette.Muted
			popup.HeaderDivider.BackgroundColor3 = ui._palette.Border
			popup.SearchHost.Visible = showSearch
			popup.SearchStroke.Color = ui._palette.Border
			popup.SearchStroke.Transparency = 0.68
			popup.Search.TextColor3 = ui._palette.Text
			popup.Search.PlaceholderColor3 = ui._palette.Muted
			local focusedChoice = nil
			local focusedIndex = nil
			local guiService = ui._guiService
			if guiService ~= nil then
				local selectedOk, selectedObject = pcall(function()
					return guiService.SelectedObject
				end)
				local focusedRow = if selectedOk and selectedObject ~= nil then popup.RowChoices[selectedObject] else nil
				if focusedRow ~= nil then
					focusedChoice = focusedRow.Choice
					focusedIndex = focusedRow.Index
				end
			end
			local canvasPosition = popup.Rows.CanvasPosition
			clearDropdownPopupRows(popup)
			local rowHeight = if multi then (if control._maxSelections == 1 then 44 else 34) else 32
			local rowGap = 3
			local headerHeight = if multi then MULTI_HEADER_HEIGHT else 0
			local searchHeight = if showSearch then MULTI_SEARCH_HEIGHT + 8 else 0
			local beforeRows = headerHeight + searchHeight
			local popupVerticalPadding = if multi then 12 else 8
			local resultCount = math.max(1, #visibleChoices)
			local desiredRows = math.min(if opensRight then 7 else 6, resultCount)
			local popupAnchor = control._popupAnchor or control.Root
			local localPosition = popupAnchor.AbsolutePosition - popupOrigin
			local baseWidth = math.min(if multi then MULTI_POPUP_WIDTH else 260, math.max(0, popupBounds.X - 16))
			local rightStart = localPosition.X + popupAnchor.AbsoluteSize.X + 4
			local availableRight = math.max(0, popupBounds.X - 8 - rightStart)
			local width = if opensRight then math.min(baseWidth, availableRight) else baseWidth
			local desiredRowsHeight = desiredRows * rowHeight + math.max(0, desiredRows - 1) * rowGap
			local desiredHeight = beforeRows + desiredRowsHeight + popupVerticalPadding
			local belowY = localPosition.Y + popupAnchor.AbsoluteSize.Y + 4
			local belowSpace = popupBounds.Y - 8 - belowY
			local aboveSpace = localPosition.Y - 12
			local opensAbove = belowSpace < desiredHeight and aboveSpace > belowSpace
			local availableSpace = math.max(0, if opensAbove then aboveSpace else belowSpace)
			local fixedHeight = beforeRows + popupVerticalPadding
			local fittingRows = math.floor((availableSpace - fixedHeight + rowGap) / (rowHeight + rowGap))
			local visibleRows = math.max(1, math.min(desiredRows, fittingRows))
			local rowsHeight = visibleRows * rowHeight + math.max(0, visibleRows - 1) * rowGap
			local height = beforeRows + rowsHeight + popupVerticalPadding
			popup.TargetWidth = width
			popup.TargetHeight = height
			local rowsViewportInset = if opensRight then 2 else 0
			local maxX = math.max(8, popupBounds.X - width - 8)
			local maxY = math.max(8, popupBounds.Y - height - 8)
			local desiredX = if opensRight
				then localPosition.X + popupAnchor.AbsoluteSize.X + 4
				elseif multi
				then localPosition.X + popupAnchor.AbsoluteSize.X - width
				else localPosition.X
			local x = if opensRight then desiredX else math.clamp(desiredX, 8, maxX)
			local y = if opensAbove then localPosition.Y - height - 4 else belowY
			local popupPosition = UDim2.fromOffset(x, math.clamp(y, 8, maxY))
			popup.Root.Position = popupPosition
			popup.Shadow.Position = popupPosition + UDim2.fromOffset(0, 6)
			if animatePresence then
				if resumePresence then
					popup.Root.Size = UDim2.fromOffset(width, math.min(height, popup.Root.Size.Y.Offset))
					popup.Shadow.Size = UDim2.fromOffset(width, math.min(height, popup.Shadow.Size.Y.Offset))
				else
					popup.Root.BackgroundTransparency = 1
					popup.Root.Size = UDim2.fromOffset(width, 0)
					popup.Shadow.BackgroundTransparency = 1
					popup.Shadow.Size = UDim2.fromOffset(width, 0)
				end
			else
				popup.Root.BackgroundTransparency = 0
				popup.Root.Size = UDim2.fromOffset(width, height)
				popup.Shadow.BackgroundTransparency = 0.72
				popup.Shadow.Size = UDim2.fromOffset(width, height)
			end
			popup.Rows.Position = UDim2.fromOffset(4, beforeRows + 4)
			popup.Rows.Size = UDim2.new(1, -8, 0, rowsHeight + rowsViewportInset)
			local previousRow: TextButton? = nil
			local restoredRow: TextButton? = nil
			local nearestRow: TextButton? = nil
			local nearestDistance = math.huge
			for visibleIndex, choice in ipairs(visibleChoices) do
				local selected = if multi then control:IsSelected(choice) else control.Value == choice
				local enabled = not multi or selected or not limitReached or control._maxSelections == 1
				local row = Instance.new("TextButton")
				row.Name = "Choice"
				row.Active = enabled
				row.AutoButtonColor = false
				row.BackgroundColor3 = if multi and selected then ui._palette.Accent elseif selected then ui._palette.ControlSelected else ui._palette.Control
				row.BackgroundTransparency = if multi then (if selected then 0.92 else 1) else 0
				row.BorderSizePixel = 0
				row.Font = Enum.Font.BuilderSansMedium
				row.FontFace = FONT_MEDIUM
				row.Selectable = enabled
				row.Text = if multi then "" else tostring(choice)
				row.TextColor3 = if enabled then ui._palette.Text else ui._palette.Disabled
				row.TextSize = 13
				row.TextTruncate = Enum.TextTruncate.AtEnd
				row.TextXAlignment = Enum.TextXAlignment.Left
				row.Size = UDim2.new(1, 0, 0, rowHeight)
				row.ZIndex = 44
				row.Parent = popup.Rows
				addCorner(row, 7, "ChoiceCorner")
				if not multi then
					local rowPadding = Instance.new("UIPadding")
					rowPadding.Name = "ChoicePadding"
					rowPadding.PaddingLeft = UDim.new(0, 8)
					rowPadding.PaddingRight = UDim.new(0, 8)
					rowPadding.Parent = row
				end
				if previousRow ~= nil then
					previousRow.NextSelectionDown = row
					row.NextSelectionUp = previousRow
				end
				previousRow = row
				popup.RowChoices[row] = { Choice = choice, Index = visibleIndex }
				if enabled and focusedIndex ~= nil then
					if focusedChoice == choice then
						restoredRow = row
					end
					local distance = math.abs(visibleIndex - focusedIndex)
					if distance < nearestDistance then
						nearestRow = row
						nearestDistance = distance
					end
				end
				if multi then
					local checkbox = Instance.new("Frame")
					checkbox.Name = "Checkbox"
					checkbox.AnchorPoint = Vector2.new(0, 0.5)
					checkbox.BackgroundColor3 = if selected then ui._palette.Accent else ui._palette.Popup
					checkbox.BackgroundTransparency = if selected then 0 else 1
					checkbox.BorderSizePixel = 0
					checkbox.Position = UDim2.new(0, 8, 0.5, 0)
					checkbox.Size = UDim2.fromOffset(16, 16)
					checkbox.ZIndex = 45
					checkbox.Parent = row
					addCorner(checkbox, 4, "CheckboxCorner")
					local checkboxStroke = addStroke(checkbox, if selected then ui._palette.Accent else ui._palette.Border, "CheckboxStroke")
					checkboxStroke.Transparency = if enabled then 0.28 else 0.74
					local check = ui.Icons.Render(checkbox, "check", nil, 14, {
						AnchorPoint = Vector2.new(0.5, 0.5),
						Position = UDim2.fromScale(0.5, 0.5),
						Color3 = ui._palette.Text,
						ZIndex = 46,
					})
					check.Visible = selected
					local choiceLabel = Instance.new("TextLabel")
					choiceLabel.Name = "ChoiceLabel"
					choiceLabel.BackgroundTransparency = 1
					choiceLabel.Position = UDim2.fromOffset(34, 0)
					choiceLabel.Size = UDim2.new(1, -42, 1, 0)
					choiceLabel.Font = Enum.Font.BuilderSansMedium
					choiceLabel.FontFace = FONT_MEDIUM
					choiceLabel.Text = tostring(choice)
					choiceLabel.TextColor3 = if enabled then (if selected then ui._palette.Accent else ui._palette.Text) else ui._palette.Disabled
					choiceLabel.TextSize = 12
					choiceLabel.TextTruncate = Enum.TextTruncate.AtEnd
					choiceLabel.TextXAlignment = Enum.TextXAlignment.Left
					choiceLabel.ZIndex = 45
					choiceLabel.Parent = row
					applyTextRendering(choiceLabel)
				else
					local check = ui.Icons.Render(row, "check", nil, 14, {
						AnchorPoint = Vector2.new(0.5, 0.5),
						Position = UDim2.new(1, -14, 0.5, 0),
						Color3 = ui._palette.Accent,
						ZIndex = 45,
					})
					check.Visible = selected
				end
				local connection = row.Activated:Connect(function()
					if popup.Control ~= control or not enabled then return end
					if multi then
						if control._maxSelections == 1 and not selected then
							control:Set({ choice })
						else
							control:ToggleChoice(choice)
						end
					else
						ui:_closeDropdownPopup()
						control:Set(choice)
					end
				end)
				table.insert(popup.RowConnections, connection)
			end
			if #visibleChoices == 0 then
				local empty = Instance.new("TextLabel")
				empty.Name = "Empty"
				empty.BackgroundTransparency = 1
				empty.Font = Enum.Font.BuilderSans
				empty.FontFace = FONT_REGULAR
				empty.Text = "No results"
				empty.TextColor3 = ui._palette.Muted
				empty.TextSize = 11
				empty.Size = UDim2.new(1, 0, 0, rowHeight)
				empty.ZIndex = 44
				empty.Parent = popup.Rows
				applyTextRendering(empty)
			end
			local renderedRows = math.max(1, #visibleChoices)
			popup.Rows.CanvasSize = UDim2.fromOffset(0, renderedRows * rowHeight + math.max(0, renderedRows - 1) * rowGap)
			popup.Root.Active = true
			popup.Rows.Active = true
			popup.Search.Active = showSearch
			popup.Search.Selectable = showSearch
			popup.Search.TextEditable = showSearch
			popup.Root.Visible = true
			popup.Shadow.Visible = not opensRight
			popup.Dismiss.Visible = true
			popup.Rows.CanvasPosition = canvasPosition
			if guiService ~= nil and focusedIndex ~= nil then
				pcall(function()
					guiService.SelectedObject = restoredRow or nearestRow
				end)
			end
			if control._ownerToggle ~= nil then control._ownerToggle:_render() end
			if animatePresence then
				popup.EnterAnimating = true
				popup.EnterTweenWidth = width
				popup.EnterPending = false
				popup.ResumePresence = false
				popup.Fade = capturePageFade(popup.Root)
				applyPageFade(popup.Fade, popup.Root.BackgroundTransparency, nil)
				ui:_tween(popup.Root, MULTI_DROPDOWN_ENTER, {
					BackgroundTransparency = 0,
					Size = UDim2.fromOffset(width, height),
				})
				applyPageFade(popup.Fade, false, MULTI_DROPDOWN_ENTER)
				if not opensRight then
					ui:_tween(popup.Shadow, MULTI_DROPDOWN_ENTER, {
						BackgroundTransparency = 0.72,
						Size = UDim2.fromOffset(width, height),
					})
				end
				local settleGeneration = popup.Generation
				task.delay(MULTI_DROPDOWN_ENTER.Time, function()
					if ui._destroyed or popup.Generation ~= settleGeneration or popup.Control ~= control or not popup.EnterAnimating then return end
					settleDropdownPopup(popup, popup.TargetWidth, popup.TargetHeight)
					if opensRight then ui:_repositionDropdownPopup() end
				end)
			end
		end
		function ui:_repositionDropdownPopup()
			local popup = ui._dropdownPopup
			local control = popup.Control
			if control == nil or control._popupDirection ~= "right" or not popup.Root.Visible then return end
			local bounds, origin = pixelGrid.AbsoluteSize, pixelGrid.AbsolutePosition
			local anchor = control._popupAnchor or control.Root
			local localPosition = anchor.AbsolutePosition - origin
			local baseWidth = math.min(if control._multi then MULTI_POPUP_WIDTH else 260, math.max(0, bounds.X - 16))
			local rightStart = localPosition.X + anchor.AbsoluteSize.X + 4
			local availableRight = math.max(0, bounds.X - 8 - rightStart)
			local width = math.min(baseWidth, availableRight)
			local height = popup.TargetHeight
			if type(height) ~= "number" or height <= 0 then return end
			local belowY = localPosition.Y + anchor.AbsoluteSize.Y + 4
			local belowSpace = bounds.Y - 8 - belowY
			local aboveSpace = localPosition.Y - 12
			local opensAbove = belowSpace < height and aboveSpace > belowSpace
			if popup.EnterAnimating and width ~= popup.EnterTweenWidth then
				settleDropdownPopup(popup, width, height)
			end
			local x = rightStart
			local desiredY = if opensAbove then localPosition.Y - height - 4 else belowY
			local y = math.clamp(desiredY, 8, math.max(8, bounds.Y - height - 8))
			local position = UDim2.fromOffset(x, y)
			popup.TargetWidth = width
			popup.Root.Position = position
			popup.Root.Size = UDim2.fromOffset(width, popup.Root.Size.Y.Offset)
			popup.Shadow.Position = position + UDim2.fromOffset(0, 6)
			popup.Shadow.Size = UDim2.fromOffset(width, popup.Shadow.Size.Y.Offset)
		end
		function ui:_openDropdownPopup(control: any)
			local windowBlocked = ui.Window == nil
				or ui.Window._minimized
				or ui.Window._minimizeAnimating
				or control._section._tab ~= ui.Window._selected
			local owner = control._ownerToggle
			local ownerBlocked = owner ~= nil and (owner._destroyed or owner._locked or not owner._visible or owner._searchVisible == false)
			if ui._destroyed
				or not ui._open
				or control._destroyed
				or control._locked
				or not control._visible
				or control._searchVisible == false
				or ownerBlocked
				or windowBlocked
			then
				return control
			end
			if #control.Choices == 0 then
				ui:_closeDropdownPopup()
				return control
			end
			local popup = ui._dropdownPopup
			if popup.Control == control then
				return control
			end
			ui:_closeDropdownPopup()
			local interruptedExit = popup.ExitPending == true
			popup.Generation += 1
			popup.ExitPending = false
			if popup.Search.Text ~= "" then
				popup.Search.Text = ""
			end
			popup.Rows.CanvasPosition = Vector2.zero
			popup.EnterPending = control._multi == true
			popup.ResumePresence = control._multi == true and interruptedExit
			popup.Control = control
			control:_render(true)
			if control._chevron ~= nil then
				if control._multi then
					control._chevron:SetAttribute("RayfieldMotionDuration", MULTI_DROPDOWN_ENTER.Time)
				end
				ui:_tween(
					control._chevron,
					if control._multi then MULTI_DROPDOWN_ENTER else RAYFIELD_DROPDOWN_CHEVRON,
					{ Rotation = 180 }
				)
			end
			ui:_renderDropdownPopup()
			return control
		end
