		minimizedStatus.ConnectorBands = {}
		minimizedStatus.ConnectorImageAsset = nil
		minimizedStatus.RenderConnectorTexture = nil
		do
			local textureScale = 4
			local textureSize = Vector2.new(
				MINIMIZED_STATUS_CONNECTOR_SIZE.X * textureScale,
				MINIMIZED_STATUS_CONNECTOR_SIZE.Y * textureScale
			)
			local assetOk, editableImage = pcall(function()
				return game:GetService("AssetService"):CreateEditableImage({ Size = textureSize })
			end)
			if assetOk and editableImage ~= nil then
				local contentOk = pcall(function()
					minimizedStatus.ConnectorSurface.ImageContent = Content.fromObject(editableImage)
				end)
				if contentOk then
					minimizedStatus.ConnectorImageAsset = editableImage
					minimizedStatus.RenderConnectorTexture = function()
						local shell = ui._palette.Shell
						local border = ui._palette.Border
						if minimizedStatus.ConnectorTextureShell == shell and minimizedStatus.ConnectorTextureBorder == border then return end
						local shellRed, shellGreen, shellBlue = math.round(shell.R * 255), math.round(shell.G * 255), math.round(shell.B * 255)
						local borderRed, borderGreen, borderBlue = math.round(border.R * 255), math.round(border.G * 255), math.round(border.B * 255)
						local shellAlpha = 1 - SHELL_GLASS_TRANSPARENCY
						local borderAlpha = 0.65
						local pixels = buffer.create(textureSize.X * textureSize.Y * 4)
						for pixelY = 0, textureSize.Y - 1 do
							local y = (pixelY + 0.5) / textureScale
							local halfWidth
							local isCurve = y > MINIMIZED_STATUS_CONNECTOR_OVERLAP
								and y < MINIMIZED_STATUS_CONNECTOR_SIZE.Y - MINIMIZED_STATUS_CONNECTOR_OVERLAP
							if isCurve then
								local t = (y - MINIMIZED_STATUS_CONNECTOR_OVERLAP) / MINIMIZED_STATUS_GAP
								local distanceFromCenter = math.abs((t * 2) - 1)
								halfWidth = (20 + (14 * (distanceFromCenter ^ 1.6))) / 2
							else
								halfWidth = MINIMIZED_STATUS_CONNECTOR_SIZE.X / 2
							end
							for pixelX = 0, textureSize.X - 1 do
								local x = (pixelX + 0.5) / textureScale
								local insideDistance = halfWidth - math.abs(x - (MINIMIZED_STATUS_CONNECTOR_SIZE.X / 2))
								local coverage = math.clamp((insideDistance * textureScale) + 0.5, 0, 1)
								local outlineMix = if isCurve then math.clamp(((0.85 - insideDistance) * textureScale) + 0.5, 0, 1) else 0
								local red = math.round(shellRed + ((borderRed - shellRed) * outlineMix))
								local green = math.round(shellGreen + ((borderGreen - shellGreen) * outlineMix))
								local blue = math.round(shellBlue + ((borderBlue - shellBlue) * outlineMix))
								local alpha = math.round(255 * coverage * (shellAlpha + ((borderAlpha - shellAlpha) * outlineMix)))
								local offset = ((pixelY * textureSize.X) + pixelX) * 4
								buffer.writeu8(pixels, offset, red)
								buffer.writeu8(pixels, offset + 1, green)
								buffer.writeu8(pixels, offset + 2, blue)
								buffer.writeu8(pixels, offset + 3, alpha)
							end
						end
						editableImage:WritePixelsBuffer(Vector2.zero, textureSize, pixels)
						minimizedStatus.ConnectorTextureShell = shell
						minimizedStatus.ConnectorTextureBorder = border
					end
					minimizedStatus.RenderConnectorTexture()
				else
					editableImage:Destroy()
				end
			end
			if minimizedStatus.ConnectorImageAsset == nil then
				minimizedStatus.ConnectorSurface.Visible = false
				for row = 0, MINIMIZED_STATUS_GAP - 1 do
					local distanceFromCenter = math.abs((((row + 0.5) / MINIMIZED_STATUS_GAP) * 2) - 1)
					local width = 20 + (14 * (distanceFromCenter ^ 1.6))
