			ui:_tween(minimizedStatus.Title, RAYFIELD_COLLAPSED_FACE_IN, { TextTransparency = 0 })
			ui:_tween(minimizedStatus.Detail, RAYFIELD_COLLAPSED_FACE_IN, { TextTransparency = 0 })
