				minimizedStatus.Root.Visible = false
				return
			end
			local position, size = minimizedStatusGeometry(false)
			local foldedPosition = UDim2.fromOffset(position.X.Offset, MINIMIZED_STATUS_RETRACT_Y)
			local connectorBottom = math.ceil(minimizedStatus.Root.AbsolutePosition.Y + MINIMIZED_STATUS_FOLLOW_OVERLAP)
			local connectorTop = math.floor(root.AbsolutePosition.Y + root.AbsoluteSize.Y - MINIMIZED_STATUS_FOLLOW_OVERLAP)
			minimizedStatus.Connector.AnchorPoint = Vector2.new(0.5, 1)
			minimizedStatus.Connector.Position = UDim2.new(0.5, 0, 0, connectorBottom)
			minimizedStatus.Connector.Size = UDim2.fromOffset(MINIMIZED_STATUS_CONNECTOR_SIZE.X, math.max(0, connectorBottom - connectorTop))
