		function ui:_tween(instance: Instance, info: TweenInfo, properties: table)
			local tween = nil
			if info.Time == 0 then
				-- A zero-duration Roblox tween still writes on the next frame.
				host:CancelTween(instance)
			else
				tween = host:Tween(instance, info, properties)
			end
			if tween == nil then
				for property, value in pairs(properties) do
					pcall(function() (instance :: any)[property] = value end)
				end
			end
			return tween
		end
		local function restoreActivePageFades()
			for _, field in ipairs({ "_outgoingFade", "_incomingFade" }) do
				local snapshot = window[field]
				if snapshot ~= nil then
					applyPageFade(snapshot, false, nil)
					window[field] = nil
				end
			end
		end
		local function captureChromeFade(): any
			local snapshot = capturePageFade(root)
			local filtered = {}
			for _, record in ipairs(snapshot) do
				local instance = record.Instance
				local keep = instance == shellStroke or instance == glassInnerHighlight
					or instance == collapsedFace or instance:IsDescendantOf(collapsedFace)
					or instance == glassTint or instance:IsDescendantOf(glassTint)
					or instance == glassSheen or instance:IsDescendantOf(glassSheen)
					or instance == dropdownPopup or instance:IsDescendantOf(dropdownPopup)
					or instance == dropdownShadow
				if not keep then table.insert(filtered, record) end
			end
			return filtered
		end
		local function setWindowEffectsHidden(hidden: boolean, tweenInfo: TweenInfo?)
			for _, effect in ipairs(ui._effectLayers or {}) do
				local rootTransparency = if hidden then 1 else effect.BackgroundTransparency
				local strokeTransparency = if hidden then 1 else effect.StrokeTransparency
				ui:_tween(effect.Root, tweenInfo or INSTANT_MOTION, { BackgroundTransparency = rootTransparency })
				ui:_tween(effect.Stroke, tweenInfo or INSTANT_MOTION, { Transparency = strokeTransparency })
			end
		end
		local function settleShellVisibility()
			ui._visibilityGeneration += 1
			ui:_tween(root, INSTANT_MOTION, { BackgroundTransparency = SHELL_GLASS_TRANSPARENCY })
			ui:_tween(shellStroke, INSTANT_MOTION, { Transparency = 0 })
		end
		local function setMainChromeVisible(visible: boolean)
			header.Visible = visible
			tabs.Visible = visible
			pages.Visible = visible
			tabTopDivider.Visible = visible
			if visible then
				layoutChrome(ui)
			else
				tabSideDivider.Visible = false
			end
			if not visible then
				searchResults.Visible = false
				toast.Visible = false
			end
		end
		local function settleWindowMorph()
			local minimized = window._minimized
			local size = if minimized then COLLAPSED_SIZE else window._restoreSize or UDim2.fromOffset(600, 400)
			local position = if minimized then COLLAPSED_POSITION else window._restorePosition or UDim2.fromScale(0.5, 0.5)
			ui._revealTargetPosition = nil
			settleShellVisibility()
			ui:_tween(root, INSTANT_MOTION, { Size = size, Position = snapWindowPosition(position, size) })
			ui:_tween(shellCorner, INSTANT_MOTION, { CornerRadius = if minimized then UDim.new(1, 0) else UDim.new(0, SHELL_RADIUS) })
			applyPageFade(window._chromeFade, minimized, nil)
			applyPageFade(window._collapsedFade, not minimized, nil)
			collapsedFace.Visible = minimized
			collapsedInteract.Visible = minimized
			window._minimizeAnimating = false
			setMainChromeVisible(not minimized)
			setWindowEffectsHidden(minimized, nil)
			if not minimized then
				window._restorePosition = root.Position
				window._chromeFade = nil
				for _, candidate in ipairs(window._tabs) do layoutTab(candidate) end
			end
