		local function renderTab(tab: any, selected: boolean, animate: boolean?)
			local backgroundColor = if selected
				then ui._palette.Accent:Lerp(ui._palette.Selected, 0.90)
				else ui._palette.Selected
			local backgroundTransparency = if selected then 0 else 1
			local labelColor = if selected then ui._palette.Text else ui._palette.Muted
			local motion = if animate == true then RAYFIELD_TAB_MOTION else INSTANT_MOTION
			ui:_tween(tab.Root, motion, {
				BackgroundColor3 = backgroundColor,
				BackgroundTransparency = backgroundTransparency,
			})
			ui:_tween(tab._labelObject, motion, { TextColor3 = labelColor })
			if tab._iconGlow ~= nil then
				local outerTransparency = if selected then 0.93 else 1
				local coreTransparency = if selected then 0.84 else 1
				local strokeTransparency = if selected then 0.68 else 1
				local glowScale = if selected then 1 else 0.78
				tab._iconGlow.BackgroundColor3 = ui._palette.Accent
				tab._iconGlowCore.BackgroundColor3 = ui._palette.Accent
				tab._iconGlowStroke.Color = ui._palette.Accent
				ui:_tween(tab._iconGlow, motion, { BackgroundTransparency = outerTransparency })
				ui:_tween(tab._iconGlowCore, motion, { BackgroundTransparency = coreTransparency })
				ui:_tween(tab._iconGlowStroke, motion, { Transparency = strokeTransparency })
				ui:_tween(tab._iconGlowScale, motion, { Scale = glowScale })
			end
			tab.Page.ScrollBarImageColor3 = ui._palette.Accent
			local iconColor = if selected then ui._palette.Accent else ui._palette.Text:Lerp(ui._palette.Muted, 0.45)
			recolorIcon(tab._icon, iconColor)
		end
		local searchTargets = {}
		function ui:_renderSearchResults()
			if ui._destroyed then return end
			local query = string.lower(search.Text)
			query = string.gsub(query, "^%s+", "")
			query = string.gsub(query, "%s+$", "")
			table.clear(searchTargets)
			local count = 0
			if query ~= "" then
				for _, control in ipairs(ui._controls) do
					if not control._destroyed and not control._embedded then
						local id = if type(control._id) == "string" then control._id else ""
						local summary = if control._kind == "Dropdown" and control._multi then multiSummary(control._selection, #control.Choices) elseif control._kind == "Dropdown" then (if control.Value == nil then "-" else tostring(control.Value)) else ""
						local haystack = string.lower(control._label .. " " .. summary .. " " .. id)
						if string.find(haystack, query, 1, true) ~= nil then
							count += 1
							searchTargets[count] = control
							if count >= SEARCH_RESULT_LIMIT then break end
						end
					end
				end
			end
			for index, row in ipairs(searchRows) do
				local target = searchTargets[index]
				row.Visible = target ~= nil
				if target ~= nil then
					local tabLabel = target._section._tab._label
					row.Text = target._label .. "  ·  " .. tabLabel
					row.BackgroundColor3 = ui._palette.Control
					row.BackgroundTransparency = 0
					row.TextColor3 = ui._palette.Text
				else
					row.Text = ""
				end
			end
			ui._searchResultCount = count
			ui._searchGeneration = (ui._searchGeneration or 0) + 1
			local generation = ui._searchGeneration
			local resultsWidth = searchResultsWidth(ui)
			local shouldShow = searchHost.Visible and query ~= "" and count > 0
			local targetSize = UDim2.fromOffset(resultsWidth, if count > 0 then count * SEARCH_RESULT_HEIGHT + 8 else 0)
			if shouldShow then
				if not searchResults.Visible then
					searchResults.Visible = true
					searchResultsStroke.Transparency = 1
					searchResults.Position = searchResultsPosition(ui, HEADER_HEIGHT - 8)
					searchResults.Size = UDim2.fromOffset(resultsWidth, 0)
				end
				searchResults:SetAttribute("RayfieldMotionEnterDuration", 0.4)
				ui:_tween(searchResults, RAYFIELD_SEARCH_MOTION, {
					BackgroundTransparency = 0,
					Position = searchResultsPosition(ui, HEADER_HEIGHT + 4),
					Size = targetSize,
				})
				ui:_tween(searchResultsStroke, RAYFIELD_SEARCH_MOTION, { Transparency = 0 })
			elseif searchResults.Visible then
				searchResults:SetAttribute("RayfieldMotionExitDuration", 0.22)
				ui:_tween(searchResults, RAYFIELD_SEARCH_EXIT, {
					BackgroundTransparency = 1,
					Position = searchResultsPosition(ui, HEADER_HEIGHT - 6),
					Size = UDim2.fromOffset(resultsWidth, 0),
				})
				ui:_tween(searchResultsStroke, RAYFIELD_SEARCH_EXIT, { Transparency = 1 })
				task.delay(0.22, function()
					if ui._destroyed or generation ~= ui._searchGeneration then return end
					searchResults.Visible = false
				end)
			else
				searchResults.Size = UDim2.fromOffset(resultsWidth, 0)
			end
		end
		for index, row in ipairs(searchRows) do
			connect(ui, row.Activated, function()
				local target = searchTargets[index]
				if target == nil or target._destroyed then return end
				local targetTab = target._section._tab
				window:_select(targetTab)
				targetTab.Page.CanvasPosition = Vector2.new(
					0,
					math.max(0, target._section.Root.Position.Y.Offset + target.Root.Position.Y.Offset - BODY_PADDING)
				)
				search.Text = ""
				search:ReleaseFocus()
				ui:_renderSearchResults()
			end)
		end
		searchHost:SetAttribute("RayfieldMotionDuration", 0.4)
		searchHost:SetAttribute("RayfieldMotionEasingStyle", "Quint")
		connect(ui, search:GetPropertyChangedSignal("Text"), function() ui:_renderSearchResults() end)
		connect(ui, search.Focused, function()
			ui._searchFocused = true
			local width = layoutSearchGeometry(ui, searchHost.Visible, false)
			ui:_tween(searchHost, RAYFIELD_SEARCH_MOTION, { Size = UDim2.fromOffset(width, SEARCH_HEIGHT) })
			ui:_tween(searchStroke, RAYFIELD_SEARCH_MOTION, { Color = ui._palette.Accent })
		end)
		connect(ui, search.FocusLost, function()
			ui._searchFocused = false
			local width = layoutSearchGeometry(ui, searchHost.Visible, false)
			ui:_tween(searchHost, RAYFIELD_SEARCH_MOTION, { Size = UDim2.fromOffset(width, SEARCH_HEIGHT) })
			ui:_tween(searchStroke, RAYFIELD_SEARCH_MOTION, { Color = ui._palette.Border })
			if search.Text == "" then ui:_renderSearchResults() end
		end)
		connect(ui, root:GetPropertyChangedSignal("AbsoluteSize"), function()
			layoutChrome(ui)
			for _, candidate in ipairs(window._tabs) do
				layoutTab(candidate)
			end
			if ui._dropdownPopup.Control ~= nil then ui:_renderDropdownPopup() end
		end)
		connect(ui, root:GetPropertyChangedSignal("AbsolutePosition"), function()
			local owner = ui._dropdownPopup.Control
			if owner ~= nil and owner._popupDirection == "right" then ui:_repositionDropdownPopup() end
		end)
		function ui:_ensureProfile()
			if ui._profileLoaded or ui._persistence == nil then return true, nil end
			local stored, loadError = host:LoadProfile(ui._profileFolder, ui._configName)
			if stored == nil then
				ui._profileError = loadError
				return false, loadError
			end
			ui._storedValues = stored
			ui._profileLoaded = true
			ui._profileError = nil
			return true, nil
		end
		function ui:_saveControl(control: any)
			if ui._persistence == nil or not control._persist or type(control._id) ~= "string" or control._id == "" then return true, nil end
			local ready, readyError = ui:_ensureProfile()
			if not ready then return false, readyError end
			ui._storedValues[control._id] = if control._multi then copyArray(control._selection) else control.Value
			return host:SaveProfile(ui._profileFolder, ui._configName, ui._storedValues)
		end
		function ui:_restoreControl(control: any)
			if ui._persistence == nil or not control._persist or type(control._id) ~= "string" or control._id == "" then return true, nil end
			local ready, readyError = ui:_ensureProfile()
			if not ready then return false, readyError end
			local value = ui._storedValues[control._id]
			if value == nil then return true, nil end
			if control._kind == "Toggle" and type(value) ~= "boolean" then return true, nil end
			if control._kind == "Dropdown" then
				if control._multi then
					if type(value) ~= "table" then return true, nil end
					local restored = {}
					for _, choice in ipairs(value) do
						if hasChoice(control.Choices, choice) and not hasChoice(restored, choice) and (control._maxSelections == nil or #restored < control._maxSelections) then table.insert(restored, choice) end
					end
					control:Set(restored, { Silent = true })
					return true, nil
				elseif not hasChoice(control.Choices, value) then return true, nil end
			end
			control:Set(value, { Silent = true })
			return true, nil
		end
		ui._persistence = option(libraryOptions, "Persistence", "persistence", option(input, "Persistence", "persistence", nil))
		ui._profileFolder = tostring(option(ui._persistence, "Folder", "folder", "Potassium"))
		ui._configName = tostring(option(libraryOptions, "ConfigName", "configName", option(windowOptions, "Id", "id", "main")))
		function ui:SetOpen(open: boolean)
			if ui._destroyed then return nil, errorResult("ui_destroyed", "UI has been destroyed") end
			local nextOpen = open == true
			if ui._visibilityInitialized and ui._open == nextOpen then return ui end
			local shouldAnimate = nextOpen and (not ui._visibilityInitialized or not ui._open)
			ui._visibilityGeneration += 1
			local visibilityGeneration = ui._visibilityGeneration
			ui._visibilityInitialized = true
			ui._open = nextOpen
			if not nextOpen then
				settleShellVisibility()
				if ui._revealTargetPosition ~= nil then
					root.Position = snapWindowPosition(ui._revealTargetPosition, root.Size)
				end
				ui._revealTargetPosition = nil
				ui:_closeDropdownPopup()
				dragging = false
				if window._minimized or window._minimizeAnimating then
					window._minimizeGeneration += 1
					settleWindowMorph()
				end
				hideMinimizedStatus(true)
				root.Visible = false
			else
				local targetPosition = root.Position
				if shouldAnimate then
					ui._revealTargetPosition = targetPosition
					root.BackgroundTransparency = 1
					shellStroke.Transparency = 1
					for _, effect in ipairs(ui._effectLayers or {}) do
						effect.Root.BackgroundTransparency = 1
						effect.Stroke.Transparency = 1
					end
					root.Position = UDim2.new(targetPosition.X.Scale, targetPosition.X.Offset, targetPosition.Y.Scale, targetPosition.Y.Offset + 8)
				end
				root.Visible = true
				if window._minimized then showMinimizedStatus() end
				if shouldAnimate then
					ui:_tween(root, RAYFIELD_CHROME_REVEAL, {
						BackgroundTransparency = SHELL_GLASS_TRANSPARENCY,
						Position = targetPosition,
					})
					ui:_tween(shellStroke, RAYFIELD_CHROME_REVEAL, { Transparency = 0 })
					for _, effect in ipairs(ui._effectLayers or {}) do
						ui:_tween(effect.Root, RAYFIELD_CHROME_REVEAL, { BackgroundTransparency = effect.BackgroundTransparency })
						ui:_tween(effect.Stroke, RAYFIELD_CHROME_REVEAL, { Transparency = effect.StrokeTransparency })
					end
					task.delay(RAYFIELD_CHROME_REVEAL.Time + 0.01, function()
						if ui._destroyed or ui._visibilityGeneration ~= visibilityGeneration or not ui._open or window._minimized or not root.Visible then return end
						root.Position = snapWindowPosition(ui._revealTargetPosition or root.Position, root.Size)
						ui._revealTargetPosition = nil
					end)
				else
					settleShellVisibility()
					setWindowEffectsHidden(false, nil)
				end
			end
			return ui
		end
		function ui:Show() return ui:SetOpen(true) end
		function ui:Hide() return ui:SetOpen(false) end
		function ui:Toggle() return ui:SetOpen(not ui._open) end
		function ui:IsOpen() return ui._open end
		function ui:ApplyTheme(theme: any)
			local variant = if type(theme) == "table" then option(theme, "Variant", "variant", nil) else theme
			local palette = nil
			if variant == "Light" or variant == "light" then
				palette = LIGHT
			elseif variant == "Dark" or variant == "dark" or variant == "Potassium" or variant == "potassium" then
				palette = DARK
			end
			if palette == nil then return false, errorResult("invalid_theme", "Theme must be Potassium, Dark, or Light") end
			ui._palette = palette
			root.BackgroundColor3 = palette.Shell
			applyGlass(palette)
			header.BackgroundColor3 = palette.Header
			tabs.BackgroundColor3 = palette.Tabs
			title.TextColor3 = palette.Text
			gameTitleLabel.TextColor3 = palette.Muted
			close.TextColor3 = palette.Text
			minimize.TextColor3 = palette.Text
			collapsedTitle.TextColor3 = palette.Text
			collapsedSubtitle.TextColor3 = palette.Muted
			if brandIconName == DEFAULT_BRAND_ICON then
				recolorBrandIcon(headerLogo, palette)
				recolorBrandIcon(collapsedIcon, palette)
			else
				recolorIcon(headerLogo, palette.Text)
				recolorIcon(collapsedIcon, palette.Text)
			end
			shellStroke.Color = palette.Border
			window._railGeneration += 1
			host:CancelTween(tabRail)
			slimeGradient.Transparency = RAIL_SOLID_TRANSPARENCY
			for _, glow in ipairs(ui._glowLayers or {}) do
				glow.Root.BackgroundColor3 = palette.Accent
				glow.Stroke.Color = palette.Accent
			end
			tabTopDivider.BackgroundColor3 = palette.Border
			tabSideDivider.BackgroundColor3 = palette.Border
			tabRail.BackgroundColor3 = palette.Accent
			toast.BackgroundColor3 = toneSurface(palette, ui._toastTone)
			toast.TextColor3 = palette.Text
			toastStroke.Color = if ui._toastTone == nil or ui._toastTone == "neutral" then palette.Border else toneColor(palette, ui._toastTone)
			searchHost.BackgroundColor3 = palette.Control
			search.TextColor3 = palette.Text
			search.PlaceholderColor3 = palette.Muted
			recolorIcon(searchIcon, palette.Text:Lerp(palette.Muted, 0.35))
			ui:_tween(searchStroke, INSTANT_MOTION, { Color = if ui._searchFocused then palette.Accent else palette.Border })
			searchResults.BackgroundColor3 = palette.Section
			searchResultsStroke.Color = palette.Border
			for _, row in ipairs(searchRows) do
				row.BackgroundColor3 = palette.Control
				row.TextColor3 = palette.Text
			end
			for _, tab in ipairs(window._tabs) do
				renderTab(tab, tab == window._selected)
			end
			for _, section in ipairs(ui._sections) do
				section.Root.BackgroundColor3 = palette.Section
				section._title.TextColor3 = palette.Text
				section._stroke.Color = palette.Border
				section._divider.BackgroundColor3 = palette.Border
				recolorIcon(section._icon, palette.Text)
			end
			for _, control in ipairs(ui._controls) do control:_render() end
			if minimizedStatus.Root.Visible then renderMinimizedStatus(false) end
			if ui._dropdownPopup.Control ~= nil then ui:_renderDropdownPopup() end
			ui:_renderSearchResults()
			layoutChrome(ui)
			return true, nil
		end
		function ui:TransitionTheme(theme: any) return ui:ApplyTheme(theme) end
		function ui:GetTheme() return if ui._palette == LIGHT then "Light" else "Dark" end
		function ui:SaveConfig(profile: any?)
			if ui._persistence == nil then return true, nil end
			local values = {}
			for _, c in ipairs(ui._controls) do if not c._destroyed and c._persist and type(c._id) == "string" and c._id ~= "" then values[c._id] = if c._multi then copyArray(c._selection) else c.Value end end
			if next(values) == nil then return true, nil end
			ui._storedValues = values
			return host:SaveProfile(ui._profileFolder, tostring(profile or ui._configName), values)
		end
		function ui:LoadConfig(profile: any?)
			if ui._persistence == nil then return true, nil end
			local hasParticipant = false
			for _, c in ipairs(ui._controls) do if not c._destroyed and c._persist and type(c._id) == "string" and c._id ~= "" then hasParticipant = true; break end end
			if not hasParticipant then return true, nil end
			local values, loadError = host:LoadProfile(ui._profileFolder, tostring(profile or ui._configName))
			if values == nil then return false, loadError end
			ui._storedValues = values
			ui._profileLoaded = true
			for _, c in ipairs(ui._controls) do if not c._destroyed then ui:_restoreControl(c) end end
			return true, nil
		end
		function window:Minimize()
			if ui._destroyed or window._minimizeAnimating or window._minimized or not ui._open then return window end
			window._minimizeAnimating = true
			ui:_closeDropdownPopup()
			window._minimized = true
			window._minimizeGeneration += 1
			local generation = window._minimizeGeneration
			dragging = false
			settleShellVisibility()
			restoreActivePageFades()
			if search.Text ~= "" or searchResults.Visible then
				search.Text = ""
				pcall(function() search:ReleaseFocus() end)
				ui:_renderSearchResults()
				searchResults.Visible = false
			end
			window._restorePosition = snapWindowPosition(ui._revealTargetPosition or root.Position, root.Size)
			ui._revealTargetPosition = nil
			window._restoreSize = root.Size
			window._chromeFade = captureChromeFade()
			applyPageFade(window._chromeFade, true, RAYFIELD_COLLAPSE_CHROME)
			setWindowEffectsHidden(true, RAYFIELD_COLLAPSE_CHROME)
			collapsedInteract.Visible = false
			if window._collapsedFade == nil then
				window._collapsedFade = capturePageFade(collapsedFace)
				applyPageFade(window._collapsedFade, true, nil)
			end
			ui:_tween(root, RAYFIELD_COLLAPSE_STRETCH, {
				Position = snapWindowPosition(COLLAPSED_STRETCH_POSITION, COLLAPSED_STRETCH_SIZE),
				Size = COLLAPSED_STRETCH_SIZE,
			})
			ui:_tween(shellCorner, RAYFIELD_COLLAPSE_CORNER, { CornerRadius = UDim.new(1, 0) })
			task.delay(0.20, function()
				if ui._destroyed or not ui._open or not root.Visible or window._minimizeGeneration ~= generation or not window._minimized then return end
				ui:_tween(root, RAYFIELD_COLLAPSE_HOP, {
					Position = snapWindowPosition(COLLAPSED_HOP_POSITION, COLLAPSED_SIZE),
					Size = COLLAPSED_SIZE,
				})
			end)
			task.delay(0.18, function()
				if ui._destroyed or not ui._open or not root.Visible or window._minimizeGeneration ~= generation or not window._minimized then return end
				setMainChromeVisible(false)
				collapsedFace.Visible = true
				applyPageFade(window._collapsedFade, false, RAYFIELD_COLLAPSED_FACE_IN)
			end)
			task.delay(0.30, function()
				if ui._destroyed or not ui._open or not root.Visible or window._minimizeGeneration ~= generation or not window._minimized then return end
				ui:_tween(root, RAYFIELD_COLLAPSE_SETTLE, {
					Position = snapWindowPosition(COLLAPSED_POSITION, COLLAPSED_SIZE),
					Size = COLLAPSED_SIZE,
				})
				showMinimizedStatus()
			end)
			task.delay(0.52, function()
				if ui._destroyed or not ui._open or not root.Visible or window._minimizeGeneration ~= generation or not window._minimized then return end
				settleWindowMorph()
			end)
			return window
		end
		function window:Restore()
			if ui._destroyed or window._minimizeAnimating or not window._minimized then return window end
			window._minimizeAnimating = true
			window._minimized = false
			window._minimizeGeneration += 1
			local generation = window._minimizeGeneration
			settleShellVisibility()
			collapsedInteract.Visible = false
			local statusWasVisible = minimizedStatus.Root.Visible
			if statusWasVisible then
				ui:_tween(root, RAYFIELD_RESTORE_CATCH, {
					Position = snapWindowPosition(COLLAPSED_HOP_POSITION, COLLAPSED_SIZE),
					Size = COLLAPSED_SIZE,
				})
			end
			hideMinimizedStatus()
			local restoreDelay = if statusWasVisible then MINIMIZED_STATUS_OUT.Time else 0
			local restoreSize = window._restoreSize or UDim2.fromOffset(600, 400)
			window._restorePosition = snapWindowPosition(
				window._restorePosition or UDim2.fromScale(0.5, 0.5),
				restoreSize
			)
			task.delay(restoreDelay, function()
				if ui._destroyed or window._minimizeGeneration ~= generation or window._minimized then return end
				applyPageFade(window._collapsedFade, true, RAYFIELD_COLLAPSED_FACE_OUT)
				ui:_tween(root, RAYFIELD_RESTORE_STRETCH, {
					Position = restoreStretchPosition(window._restorePosition),
					Size = restoreStretchSize(restoreSize),
				})
				ui:_tween(shellCorner, RAYFIELD_COLLAPSE_CORNER, { CornerRadius = UDim.new(0, SHELL_RADIUS) })
			end)
			task.delay(restoreDelay + 0.20, function()
				if ui._destroyed or window._minimizeGeneration ~= generation or window._minimized then return end
				local currentRestoreSize = window._restoreSize or UDim2.fromOffset(600, 400)
				window._restorePosition = snapWindowPosition(
					window._restorePosition or UDim2.fromScale(0.5, 0.5),
					currentRestoreSize
				)
				ui:_tween(root, RAYFIELD_RESTORE_SETTLE, {
					Position = window._restorePosition,
					Size = currentRestoreSize,
				})
			end)
			task.delay(restoreDelay + 0.22, function()
				if ui._destroyed or window._minimizeGeneration ~= generation or window._minimized then return end
				setMainChromeVisible(true)
				applyPageFade(window._chromeFade, false, RAYFIELD_RESTORE_CHROME)
				setWindowEffectsHidden(false, RAYFIELD_RESTORE_CHROME)
			end)
			task.delay(restoreDelay + 0.38, function()
				if ui._destroyed or window._minimizeGeneration ~= generation or window._minimized then return end
				collapsedFace.Visible = false
			end)
			task.delay(restoreDelay + 0.60, function()
				if ui._destroyed or window._minimizeGeneration ~= generation or window._minimized then return end
				settleWindowMorph()
			end)
			return window
		end
		function window:ToggleMinimize()
			if window._minimized then return window:Restore() end
			return window:Minimize()
		end
		function window:SetMinimized(value: boolean)
			if value == true then return window:Minimize() end
			return window:Restore()
		end
		function window:IsMinimized() return window._minimized end
		function window:GetMouseOverride() return false end
		function window:SetMouseOverride(_: any) return window end
		function window:SetVisibility(visible: any)
			if type(visible) == "string" then
				if visible == "minimized" then
					ui:Show()
					return window:Minimize()
				elseif visible == "shown" then
					ui:Show()
					if window._minimized then return window:Restore() end
				else
					ui:Hide()
				end
			elseif visible == true then
				ui:Show()
				if window._minimized then return window:Restore() end
			else
				ui:Hide()
			end
			return window
		end
		function window:SetOpen(open: boolean)
			if open then return window:Show() end
			return window:Hide()
		end
		function window:Show()
			ui:Show()
			if window._minimized then return window:Restore() end
			return window
		end
		function window:Hide() ui:Hide(); return window end
		function window:Toggle()
			if ui:IsOpen() then return window:Hide() end
			return window:Show()
		end
		function window:IsOpen() return ui:IsOpen() end
		function window:SetSize(value: any)
			local sizeOk, sizeOrError = pcall(frameSize, value)
			if not sizeOk then return nil, errorResult("invalid_window_size", tostring(sizeOrError)) end
			if window._minimized then
				window._restoreSize = sizeOrError
				window._restorePosition = snapWindowPosition(
					window._restorePosition or UDim2.fromScale(0.5, 0.5),
					window._restoreSize
				)
			elseif window._minimizeAnimating then
				-- An explicit resize takes over from the restore choreography.
				window._restoreSize = sizeOrError
				window._minimizeGeneration += 1
				settleWindowMorph()
			else
				root.Size = sizeOrError
				root.Position = snapWindowPosition(root.Position, root.Size)
				layoutChrome(ui)
				for _, candidate in ipairs(window._tabs) do layoutTab(candidate) end
			end
			local popupOwner = ui._dropdownPopup.Control
			if not window._minimized and popupOwner ~= nil and popupOwner._popupDirection == "right" then ui:_repositionDropdownPopup() end
			return window
		end
		function window:SetPos(value: any)
			local position = nil
			if typeof(value) == "Vector2" then position = UDim2.fromOffset(value.X, value.Y)
			elseif typeof(value) == "UDim2" then position = value
			else return nil, errorResult("invalid_window_position", "Window position must be a Vector2 or UDim2") end
			local restoring = window._minimizeAnimating and not window._minimized
			local targetSize = if window._minimized or restoring then window._restoreSize or UDim2.fromOffset(600, 400) else root.Size
			position = snapWindowPosition(position, targetSize)
			if window._minimized then
				window._restorePosition = position
			elseif restoring then
				window._restorePosition = position
				window._minimizeGeneration += 1
				settleWindowMorph()
			else
				settleShellVisibility()
				ui._revealTargetPosition = nil
				root.Position = position
			end
			local popupOwner = ui._dropdownPopup.Control
			if not window._minimized and popupOwner ~= nil and popupOwner._popupDirection == "right" then ui:_repositionDropdownPopup() end
			return window
		end
		function window:Center()
			return window:SetPos(UDim2.fromScale(0.5, 0.5))
		end
		function window:SetMinimizedStatus(definition: any)
			if ui._destroyed then return nil, errorResult("ui_destroyed", "UI has been destroyed") end
			if definition == nil or definition == false then
				minimizedStatus.Value = { text = "", detail = "", tone = "neutral", lines = {} }
				hideMinimizedStatus(true)
				return window
			end
			local textValue = if type(definition) == "string" then definition else if type(definition) == "table" then option(definition, "Text", "text", nil) else nil
			local detailValue = if type(definition) == "table" then option(definition, "Detail", "detail", "") else ""
			local toneValue = if type(definition) == "table" then option(definition, "Tone", "tone", "neutral") else "neutral"
			local linesValue = if type(definition) == "table" then option(definition, "Lines", "lines", {}) else {}
			if type(textValue) ~= "string" or textValue == "" then return nil, errorResult("invalid_minimized_status", "Minimized status Text must be a non-empty string") end
			if type(detailValue) ~= "string" then return nil, errorResult("invalid_minimized_status", "Minimized status Detail must be a string") end
			if toneValue ~= "neutral" and toneValue ~= "success" and toneValue ~= "info" and toneValue ~= "warning" and toneValue ~= "danger" then
				return nil, errorResult("invalid_minimized_status", "Minimized status Tone is unsupported")
			end
			if type(linesValue) ~= "table" then return nil, errorResult("invalid_minimized_status", "Minimized status Lines must be an array") end
			local lines = {}
			for index, line in ipairs(linesValue) do
				if index > 4 then break end
				if type(line) ~= "string" then return nil, errorResult("invalid_minimized_status", "Minimized status Lines must contain strings") end
