				iconGlowStroke.Thickness = 1
				iconGlowStroke.Transparency = 1
				iconGlowCore = Instance.new("Frame")
				iconGlowCore.Name = "Core"
				iconGlowCore.AnchorPoint = Vector2.new(0.5, 0.5)
				iconGlowCore.BackgroundColor3 = ui._palette.Accent
				iconGlowCore.BackgroundTransparency = 1
				iconGlowCore.BorderSizePixel = 0
				iconGlowCore.Position = UDim2.fromScale(0.5, 0.5)
				iconGlowCore.Size = UDim2.fromOffset(22, 22)
				iconGlowCore.ZIndex = iconGlow.ZIndex
				iconGlowCore.Parent = iconGlow
