			page.ZIndex = 1
			page.Parent = pages
			local tab: any = { Root = button, Page = page, _ui = ui, _sections = {}, _icon = tabIcon, _iconGlow = iconGlow, _iconGlowCore = iconGlowCore, _iconGlowStroke = iconGlowStroke, _iconGlowScale = iconGlowScale, _label = tabLabel, _labelObject = tabLabelObject, _index = #window._tabs + 1 }
			function window:_select(target: any)
