				local pageSwapGeneration = window._pageSwapGeneration
				window._railGeneration += 1
				local railGeneration = window._railGeneration
				for _, candidate in ipairs(window._tabs) do
					renderTab(candidate, candidate == target, animate)
				end
				restoreActivePageFades()
				if not pageAnimate then
					for _, candidate in ipairs(window._tabs) do
						candidate.Page.Visible = candidate == target
						ui:_tween(candidate.Page, INSTANT_MOTION, { Position = UDim2.new() })
						candidate.Page.ZIndex = if candidate == target then 3 else 1
