		ui._notificationGeneration = 0
		function ui:Notify(notification: any)
			if ui._destroyed then return nil, errorResult("ui_destroyed", "UI has been destroyed") end
			local titleText = if type(notification) == "table" then tostring(option(notification, "Title", "title", "")) else ""
			local bodyText = if type(notification) == "table"
				then tostring(option(notification, "Content", "content", option(notification, "Text", "text", "")))
				else tostring(notification or "")
			local tone = if type(notification) == "table"
				then tostring(option(notification, "Type", "type", option(notification, "Level", "level", "neutral")))
				else "neutral"
			if tone ~= "success" and tone ~= "info" and tone ~= "warning" and tone ~= "danger" then tone = "neutral" end
			local message = if titleText ~= "" and bodyText ~= "" then titleText .. ": " .. bodyText elseif titleText ~= "" then titleText else bodyText
			if ui._notificationThread ~= nil then
				pcall(task.cancel, ui._notificationThread)
				ui._notificationThread = nil
			end
			ui._notificationGeneration += 1
			local generation = ui._notificationGeneration
			ui._toastTone = tone
			toast.Text = message
			toast.BackgroundColor3 = toneSurface(ui._palette, tone)
			toast.TextColor3 = ui._palette.Text
			toastStroke.Color = if tone == "neutral" then ui._palette.Border else toneColor(ui._palette, tone)
			toast:SetAttribute("RayfieldMotionDuration", 0.6)
			toast:SetAttribute("RayfieldMotionEasingStyle", "Exponential")
			toast.Visible = message ~= ""
