				toast.BackgroundTransparency = 1
				toast.Position = UDim2.new(1, -12, 1, 4)
				toastStroke.Transparency = 1
				ui:_tween(toast, RAYFIELD_TOAST_MOTION, {
					BackgroundTransparency = 0,
					Position = UDim2.new(1, -12, 1, -12),
				})
				ui:_tween(toastStroke, RAYFIELD_TOAST_MOTION, { Transparency = 0 })
			end
			local duration = if type(notification) == "table" then tonumber(option(notification, "Duration", "duration", 0)) or 0 else 0
			if duration > 0 then
				ui._notificationThread = task.delay(duration, function()
					if not ui._destroyed and ui._notificationGeneration == generation then
