			ui._destroyed = true
			ui._open = false
			for _, control in ipairs(ui._controls) do
				control._destroyed = true
				control._callback = nil
				table.clear(control._connections)
			end
			table.clear(ui._controls)
			for _, section in ipairs(ui._sections) do table.clear(section._controls) end
			dragging = false
			ui._notificationGeneration += 1
			if ui._notificationThread ~= nil then
				pcall(task.cancel, ui._notificationThread)
				ui._notificationThread = nil
			end
			ui._closeHandler = nil
			for _, c in ipairs(ui._connections) do pcall(function() c:Disconnect() end) end
			table.clear(ui._connections)
