		end
		ui.Unload = ui.Destroy
		connect(ui, close.Activated, function() ui:Close() end)
		connect(ui, minimize.Activated, function() window:ToggleMinimize() end)
		connect(ui, collapsedInteract.Activated, function() window:Restore() end)
		local menuKey = option(windowOptions, "MenuKey", "menuKey", option(libraryOptions, "MenuKey", "menuKey", nil))
		host:ConnectMenuKey(Enum.KeyCode.Escape, function()
			if ui._destroyed then return end
			if ui._dropdownPopup.Control ~= nil then
				ui:_closeDropdownPopup()
			elseif menuKey == Enum.KeyCode.Escape then
				ui:Toggle()
			end
		end, {
			AllowFocusedTextBox = function(focusedTextBox: any): boolean
				return focusedTextBox == dropdownSearch
			end,
		})
		if menuKey ~= nil and menuKey ~= Enum.KeyCode.Escape then local _, menuError = host:ConnectMenuKey(menuKey, function() if not ui._destroyed then ui:Toggle() end end); if menuError ~= nil then error(menuError.message or "Could not connect menu key") end end
