	if not ok then
		for _, c in ipairs(ui._connections) do c:Disconnect() end
		if iconRegistry ~= nil then iconRegistry:Destroy() end
		if host ~= nil then host:Destroy() end
		return nil, nil, errorResult("lite_window_creation_failed", tostring(failure))
	end
	return ui, ui.Window, nil
end

return RuntimeFreeWindow

end

__modules["ui/Window"] = function()
--!strict

local Maid = __require("core/Maid")
local Signal = __require("core/Signal")
local Theme = __require("core/Theme")
local Util = __require("core/Util")
local Factory = __require("ui/Factory")
local Controls = __require("components/Controls")
local Presence = __require("core/Presence")
local ImageCrossfade = __require("core/ImageCrossfade")
local SchemaCodec = __require("customization/SchemaCodec")
local SlotHost = __require("customization/SlotHost")

local RAYFIELD_TAB_SELECTED = {
	Duration = 0.4,
	EasingStyle = Enum.EasingStyle.Quint,
	EasingDirection = Enum.EasingDirection.Out,
}
local RAYFIELD_INDICATOR_SWEEP = {
	Duration = 0.7,
	EasingStyle = Enum.EasingStyle.Quint,
	EasingDirection = Enum.EasingDirection.Out,
}
local RAYFIELD_WINDOW = {
	Duration = 1,
	EasingStyle = Enum.EasingStyle.Exponential,
	EasingDirection = Enum.EasingDirection.InOut,
}
local RAYFIELD_CHROME_HIDE = {
	Duration = 0.18,
	EasingStyle = Enum.EasingStyle.Quint,
	EasingDirection = Enum.EasingDirection.Out,
}
local RAYFIELD_CHROME_RESTORE = {
	Duration = 0.28,
	EasingStyle = Enum.EasingStyle.Exponential,
	EasingDirection = Enum.EasingDirection.Out,
}

local WINDOW_VISUAL_CENTER = UDim2.fromScale(0.5, 0.5)

local function windowVisualPosition(yOffset: number?): UDim2
	return UDim2.new(0.5, 0, 0.5, yOffset or 0)
end
local function publicBounds(object: GuiObject?): any
	if object == nil then return table.freeze({ x = 0, y = 0, width = 0, height = 0 }) end
	local position, size = object.AbsolutePosition, object.AbsoluteSize
	return table.freeze({ x = position.X, y = position.Y, width = size.X, height = size.Y })
end

local function setGuiSubtreeInteractionEnabled(root: GuiObject, enabled: boolean)
	local objects = { root }
	for _, descendant in ipairs(root:GetDescendants()) do
		if descendant:IsA("GuiObject") then
			table.insert(objects, descendant)
		end
	end
	for _, object in ipairs(objects) do
		if not enabled then
			if object:GetAttribute("PotassiumPresenceActive") == nil then
				object:SetAttribute("PotassiumPresenceActive", object.Active)
			end
			if object:GetAttribute("PotassiumPresenceSelectable") == nil then
				object:SetAttribute("PotassiumPresenceSelectable", object.Selectable)
			end
			object.Active = false
			object.Selectable = false
		else
			local priorActive = object:GetAttribute("PotassiumPresenceActive")
			if priorActive ~= nil then
				object.Active = priorActive == true
				object:SetAttribute("PotassiumPresenceActive", nil)
			end
			local priorSelectable = object:GetAttribute("PotassiumPresenceSelectable")
			if priorSelectable ~= nil then
				object.Selectable = priorSelectable == true
				object:SetAttribute("PotassiumPresenceSelectable", nil)
			end
		end
	end
end

local function option(options: any, upper: string, lower: string, default: any): any
	local value = options[upper]
	if value == nil then
		value = options[lower]
	end
	return if value == nil then default else value
end

local function localContext(context: any, theme: any): any
	local proxy = {
		_globalContext = context,
		Theme = theme,
		ThemeChanged = Signal.new(),
	}
	return setmetatable(proxy, { __index = context })
end

local function report(window: any, title: string, text: any, level: string?)
	local notify = window._globalContext.Notify
	if type(notify) == "function" then
		notify(window._globalContext, { Title = title, Text = tostring(text), Type = level or "info" })
	end
end

local function resultMessage(errorValue: any): string
	return if type(errorValue) == "table" and errorValue.message
		then tostring(errorValue.message)
		else tostring(errorValue)
end

local function applyFont(object: TextLabel | TextButton | TextBox, theme: any)
	Factory.applyTypography(object, theme)
end

local function recolorIcon(icon: Frame, color: Color3)
	for _, object in ipairs(icon:GetDescendants()) do
		if object:IsA("Frame") and object.BackgroundTransparency < 1 then
			object.BackgroundColor3 = color
		elseif object:IsA("ImageLabel") or object:IsA("ImageButton") then
			object.ImageColor3 = color
		elseif object:IsA("UIStroke") then
			object.Color = color
		end
	end
end
local function asKeyCode(value: any): Enum.KeyCode
	if typeof(value) == "EnumItem" and value.EnumType == Enum.KeyCode then
		return value
	end
	if type(value) == "string" then
		local needle = string.lower(value)
		for _, keyCode in ipairs(Enum.KeyCode:GetEnumItems()) do
			if string.lower(keyCode.Name) == needle then
				return keyCode
			end
		end
	end
	error("Invalid menu key: " .. tostring(value), 3)
end

local function asSize(value: any): UDim2
	if typeof(value) == "Vector2" then
		return UDim2.fromOffset(value.X, value.Y)
	end
	if typeof(value) == "UDim2" then
		return value
	end
	error("Window size must be Vector2 or UDim2", 3)
end

local function asPosition(value: any): UDim2
	if typeof(value) == "Vector2" then
		return UDim2.fromOffset(value.X, value.Y)
	end
	if typeof(value) == "UDim2" then
		return value
	end
	error("Window position must be Vector2 or UDim2", 3)
end
local function encodeUDim2(value: UDim2): any
	return {
		xScale = value.X.Scale,
		xOffset = value.X.Offset,
		yScale = value.Y.Scale,
		yOffset = value.Y.Offset,
	}
end

local function decodeUDim2(value: any): UDim2?
	if type(value) ~= "table" then return nil end
	local xScale, xOffset, yScale, yOffset = value.xScale, value.xOffset, value.yScale, value.yOffset
	if type(xScale) ~= "number" or type(xOffset) ~= "number" or type(yScale) ~= "number" or type(yOffset) ~= "number" then
		return nil
	end
	return UDim2.new(xScale, xOffset, yScale, yOffset)
end

local function freezeWorkspace(value: any): any
	if type(value) ~= "table" then return value end
	if table.isfrozen(value) then return value end
	for key, child in pairs(value) do value[key] = freezeWorkspace(child) end
	return table.freeze(value)
end
local function releaseWindowImageOwner(window: any, surface: string)
	local policy = window._context.AssetPolicy
	local owner = window._imageOwners[surface]
	if owner ~= nil and type(policy) == "table" and type(policy.ReleaseOwner) == "function" then
		policy:ReleaseOwner(owner)
	end
end

local function resolveWindowImage(window: any, declaration: any, assetPath: string, owner: any): (string?, any?)
	local policy = window._context.AssetPolicy
	if type(policy) ~= "table" or type(policy.Admit) ~= "function" or type(policy.Resolve) ~= "function" then
		return nil, { code = "invalid_asset_policy", message = "Window images require an AssetPolicy" }
	end
	local admitted, admissionError = policy:Admit(declaration, assetPath, owner)
	if admitted == nil then
		return nil, admissionError
	end
	if admitted.kind ~= "image" then
		if type(policy.ReleaseOwner) == "function" then policy:ReleaseOwner(owner) end
		return nil, { code = "invalid_image", message = "Window image declarations must use kind='image'" }
	end
	local resolved, resolveError = policy:Resolve(admitted, window._context.Runtime, assetPath)
	if resolved == nil then
		if type(policy.ReleaseOwner) == "function" then policy:ReleaseOwner(owner) end
		return nil, resolveError
	end
	return resolved, admitted
end

local function restorePillPosition(window: any, viewport: Vector2, width: number, height: number, stackIndex: number): UDim2
	local configured = option(window._restorePillConfig or {}, "Position", "position", "bottom-right")
	if typeof(configured) == "UDim2" then
		return UDim2.fromOffset(
			math.clamp(configured.X.Scale * viewport.X + configured.X.Offset, 0, math.max(0, viewport.X - width)),
			math.clamp(configured.Y.Scale * viewport.Y + configured.Y.Offset + (stackIndex - 1) * (height + 8), 0, math.max(0, viewport.Y - height))
		)
	end
	local position = string.lower(tostring(configured))
	local left = position == "top-left" or position == "bottom-left"
	local top = position == "top-left" or position == "top-right"
	if position ~= "top-left" and position ~= "top-right" and position ~= "bottom-left" and position ~= "bottom-right" then
		position, left, top = "bottom-right", false, false
	end
	local x = if left then 16 else viewport.X - width - 16
	local y = if top then 16 + (stackIndex - 1) * (height + 8) else viewport.Y - height * stackIndex - 16 - 8 * (stackIndex - 1)
	return UDim2.fromOffset(math.clamp(x, 0, math.max(0, viewport.X - width)), math.clamp(y, 0, math.max(0, viewport.Y - height)))
end

local function reflowRestorePills(context: any)
	local candidates = {}
	for _, window in ipairs(context._windows or {}) do
		if window._restorePill then window._restorePill.Visible = false end
		if not window._destroyed and window._restorePill and window._restorePillEnabled and window._visibility == "hidden" then
			table.insert(candidates, window)
		end
	end
	table.sort(candidates, function(a, b) return a._id < b._id end)
	local camera = workspace.CurrentCamera
	local viewport = if camera then camera.ViewportSize else Vector2.new(1280, 720)
	local stackIndices = {}
	for index, window in ipairs(candidates) do
		local pill = window._restorePill
		local direct = index <= 3
		pill.Visible = direct
		if direct then
			local configured = option(window._restorePillConfig or {}, "Position", "position", "bottom-right")
			local key = if typeof(configured) == "UDim2" then tostring(configured) else string.lower(tostring(configured))
			stackIndices[key] = (stackIndices[key] or 0) + 1
			local width, height = math.max(44, pill.AbsoluteSize.X), math.max(44, pill.AbsoluteSize.Y)
			pill.Position = restorePillPosition(window, viewport, width, height, stackIndices[key])
		end
	end
	local manager = context._restoreSurface
	if #candidates > 3 then
		if manager == nil then
			local switcher = Factory.button(context.Root, "", candidates[1]._context.Theme, {
				Role = "ghost", Size = UDim2.fromOffset(144, 44), ZIndex = candidates[1]._context.Theme.zIndex.popup + 20,
			})
			switcher.Name = "PotassiumRestoreSwitcher"
			switcher:SetAttribute("AccessibleRole", "button")
			switcher:SetAttribute("AccessibleDescription", "Restore an additional hidden window")
			manager = { switcher = switcher }
			manager.connection = switcher.Activated:Connect(function()
				local queue = {}
				for _, window in ipairs(context._windows or {}) do
					if not window._destroyed and window._restorePillEnabled and window._visibility == "hidden" then table.insert(queue, window) end
				end
				table.sort(queue, function(a, b) return a._id < b._id end)
				local nextWindow = queue[4]
				if nextWindow then nextWindow:Restore() end
			end)
			if context._maid then
				context._maid:GiveTask(switcher)
				context._maid:GiveTask(manager.connection)
			end
			context._restoreSurface = manager
		end
		local switcher = manager.switcher
		switcher.Visible = true
		switcher.Text = "Restore windows (" .. tostring(#candidates - 3) .. ")"
		switcher:SetAttribute("AccessibleName", switcher.Text)
		local width, height = math.max(44, switcher.AbsoluteSize.X), math.max(44, switcher.AbsoluteSize.Y)
		switcher.Position = UDim2.fromOffset(
			math.clamp(viewport.X - width - 16, 0, math.max(0, viewport.X - width)),
			math.clamp(viewport.Y - height * 4 - 40, 0, math.max(0, viewport.Y - height))
		)
	elseif manager ~= nil then
		manager.switcher.Visible = false
	end

end


local Window = {}
