local EDGE, TITLE_REACH = 8, 44
local MIN_SIZE = Vector2.new(320, 280)
local menuOwners = setmetatable({}, { __mode = "k" }) :: { [any]: { [Enum.KeyCode]: { any } } }

local function getViewport(): Vector2
	local camera = workspace.CurrentCamera
	return if camera then camera.ViewportSize else Vector2.new(1280, 720)
end

local DOCK_EDGES = {
	left = true,
	right = true,
	top = true,
	bottom = true,
	["top-left"] = true,
	["top-right"] = true,
	["bottom-left"] = true,
	["bottom-right"] = true,
}

local function state(theme: any, name: string): any
	return theme.states[name] or theme.states.default
end

local function metric(theme: any, name: string): number
	return Theme.metric(theme, name)
end

local function paintButton(button: TextButton, theme: any, selected: boolean)
	local logical = if selected then "selected" else "default"
	if Factory.setButtonState then
		Factory.setButtonState(button, logical, theme)
		Factory.setButtonSurface(button, nil)
	else
		local visual = state(theme, logical)
		button.BackgroundColor3 = if selected then theme.colors.surfaceRaised else visual.background
		button.TextColor3 = visual.text
	end
	local indicator = button:FindFirstChild("PotassiumSelectionIndicator")
	if indicator and indicator:IsA("Frame") then
		indicator.BackgroundColor3 = theme.accentA
		indicator.Visible = selected
	end
	button:SetAttribute("LogicalState", logical)
	button:SetAttribute("Selected", selected)
end

local function paintNavigationButton(tab: any, button: TextButton, selected: boolean, immediate: boolean)
	local oldBackground, oldText = button.BackgroundColor3, button.TextColor3
	paintButton(button, tab._context.Theme, selected)
	button:SetAttribute("RayfieldMotionSelected", selected)
	if immediate or tab._context.Theme.reducedMotion then
		return
	end
	local targetBackground, targetText = button.BackgroundColor3, button.TextColor3
	button.BackgroundColor3, button.TextColor3 = oldBackground, oldText
	tab._context.Motion:Animate(button, {
		BackgroundColor3 = targetBackground,
		TextColor3 = targetText,
	}, RAYFIELD_TAB_SELECTED)
end

local function animateNavigationHover(tab: any, button: TextButton, hovered: boolean)
	if tab._destroyed or tab._context.Theme.reducedMotion or button:GetAttribute("Selected") == true then
		return
	end
	local oldBackground, oldText = button.BackgroundColor3, button.TextColor3
	if Factory.setButtonState then
		Factory.setButtonState(button, if hovered then "hover" else "default", tab._context.Theme)
		Factory.setButtonSurface(button, nil)
	end
	local targetBackground, targetText = button.BackgroundColor3, button.TextColor3
	button.BackgroundColor3, button.TextColor3 = oldBackground, oldText
	button:SetAttribute("RayfieldMotionHover", hovered)
	tab._context.Motion:Animate(button, {
		BackgroundColor3 = targetBackground,
		TextColor3 = targetText,
	}, "rayfieldHover")
end

local function setSelectionIndicator(tab: any, selected: boolean, immediate: boolean, branchSelected: boolean?)
	for _, button in ipairs({ tab._wideButton, tab._compactButton, tab._subtabButton }) do
		if button ~= nil then
			local active = if button == tab._subtabButton then selected else branchSelected == true
			local indicator = button:FindFirstChild("PotassiumSelectionIndicator")
			if indicator and indicator:IsA("Frame") then
				local gradient = indicator:FindFirstChild("RayfieldIndicatorSweep")
				tab._context.Motion:Cancel(indicator)
				if gradient and gradient:IsA("UIGradient") then tab._context.Motion:Cancel(gradient) end
				local width = math.max(2, metric(tab._context.Theme, "borderWidth") * 2)
				if not active then
					indicator.Visible = false
					indicator.Size = UDim2.new(0, width, 0.35, 0)
					indicator.BackgroundTransparency = 1
					if gradient and gradient:IsA("UIGradient") then gradient.Rotation = -270 end
				elseif immediate or tab._context.Theme.reducedMotion then
					indicator.Visible = true
					indicator.Size = UDim2.new(0, width, 0.55, 0)
					indicator.BackgroundTransparency = 0
					if gradient and gradient:IsA("UIGradient") then gradient.Rotation = 90 end
				else
					indicator.Visible = true
					indicator.Size = UDim2.new(0, width, 0.35, 0)
					indicator.BackgroundTransparency = 1
					if gradient and gradient:IsA("UIGradient") then
						gradient.Rotation = -270
						gradient:SetAttribute("RayfieldMotionIndicatorSweep", true)
						tab._context.Motion:Animate(gradient, { Rotation = 90 }, RAYFIELD_INDICATOR_SWEEP)
					end
					tab._context.Motion:Animate(indicator, {
						Size = UDim2.new(0, width, 0.55, 0),
						BackgroundTransparency = 0,
					}, RAYFIELD_TAB_SELECTED)
				end
			end
		end
	end
end

local function addMenuOwner(window: any, key: Enum.KeyCode)
	local router = window._context.InputRouter
	local byKey = menuOwners[router]
	if not byKey then
		byKey = {}
		menuOwners[router] = byKey
	end
	local owners = byKey[key]
	if not owners then
		owners = {}
		byKey[key] = owners
		router:RegisterMenuKey(key, function()
			for index = #owners, 1, -1 do
				local owner = owners[index]
				if owner._destroyed then
					table.remove(owners, index)
				else
					owner:Toggle()
					return true
				end
			end
			return false
		end)
	end
	table.insert(owners, window)
end

local function removeMenuOwner(window: any, key: Enum.KeyCode)
	local router, byKey = window._context.InputRouter, menuOwners[window._context.InputRouter]
	if not byKey or not byKey[key] then
		return
	end
	local owners = byKey[key]
	for index = #owners, 1, -1 do
		if owners[index] == window then
			table.remove(owners, index)
		end
	end
	if #owners == 0 then
		router:UnregisterMenuKey(key)
		byKey[key] = nil
	end
end

function Section:_nextOrder(): number
	self._order += 1
	return self._order
end
function Section:_fullId(localId: string): string
	if string.sub(localId, 1, 11) == "pui-global-" then
		return localId
	end
	if string.sub(localId, 1, #self._window._id + 1) == self._window._id .. "." then
		return localId
	end
	return self._window._id .. "." .. self._tab._id .. "." .. self._id .. "." .. localId
end
function Section:_registerControl(handle: any): any
	table.insert(self._controls, handle)
	handle._maid:GiveTask(function()
		if not self._destroyed then
			local index = table.find(self._controls, handle)
			if index then table.remove(self._controls, index) end
		end
	end)
	self._window:_queueRevealElement(self._tab, handle.Root)
	return handle
end
function Section:_focus(id: string, object: GuiObject, owner: any?, ringObject: GuiObject?)
	local focusId, ring = self:_fullId(id), Factory.focusRing(ringObject or object, self._context.Theme)
	local order = self._focusOrders[focusId]
	if order == nil then
		self._focusOrder += 1
		order = self._focusOrder
		self._focusOrders[focusId] = order
	end
	local cleanupOwner = owner or self._maid
	self._context.FocusManager:Register(focusId, object, {
		order = order,
		group = self._window._focusGroup,
		owner = self._window,
		eligible = function()
			return self._window._visibility == "shown"
		end,
		onFocusChanged = function(focused)
			if focused then
				self._window._focusedId = focusId
				self._window._focusRevision += 1
			elseif self._window._focusedId == focusId then
				self._window._focusedId = nil
				self._window._focusRevision += 1
			end
			self._context.Motion:Animate(ring, { Transparency = if focused then 0 else 1 }, "quick")
		end,
	})
	self._window._focusTargets[focusId] = object
	cleanupOwner:GiveTask(function()
		self._context.FocusManager:Unregister(focusId)
		if self._window._focusTargets[focusId] == object then self._window._focusTargets[focusId] = nil end
	end)
end
