function Section:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	for _, control in ipairs(self._controls) do
		if type(control.Destroy) == "function" then
			control:Destroy()
		end
	end
	self._maid:Destroy()
	self._root:Destroy()
	if not self._tab._destroyed then
		for index = #self._tab._sections, 1, -1 do
			if self._tab._sections[index] == self then
				table.remove(self._tab._sections, index)
				break
			end
		end
	end
end
Section.Unload = Section.Destroy

local function closeSectionControls(section: any)
	for _, control in ipairs(section._controls) do
		if type(control.Close) == "function" then pcall(control.Close, control) end
	end
end

function Tab:_select(options: any?)
	if self._destroyed then
		return self
	end
	if options ~= nil then
		assert(type(options) == "table", "Tab Select options must be a table")
	end
	local current = self._window._selected
	local reselect = current == self
	local transition = self._window._tabTransition
	local direction = "auto"
	if transition.style == "slide" then
		direction = if options and options.Direction ~= nil
			then options.Direction
			else if options and options.direction ~= nil then options.direction else "auto"
		assert(direction == "left" or direction == "right" or direction == "auto", "Tab Select Direction must be left, right, or auto")
	end
	local immediate = reselect
		or current == nil
		or transition.style == "none"
		or self._context.Theme.reducedMotion
		or (options and (options.Animate == false or options.animate == false))
	local targetOffset = 0
	if not immediate and transition.style == "slide" then
		if direction == "left" then
			targetOffset = -transition.distance
		elseif direction == "right" then
			targetOffset = transition.distance
		else
			local selectedIndex = table.find(self._window._tabs, self) or 0
			local currentIndex = table.find(self._window._tabs, current) or 0
			targetOffset = if selectedIndex < currentIndex then -transition.distance else transition.distance
		end
	end
	if not reselect and current ~= nil then
		for _, section in ipairs(current._sections) do closeSectionControls(section) end
	end
	local familyRoot = self._parent or self
	for _, tab in ipairs(self._window._tabs) do
		local selected = tab == self
		local branchSelected = tab == familyRoot
		tab._context.Motion:Cancel(tab._pageHost)
		tab._context.Motion:Cancel(tab._page)
		if not selected then
			tab._pageHost.Visible = false
			tab._page.Visible = false
			tab._pageHost.GroupTransparency = 0
			tab._page.Position = UDim2.fromOffset(0, 0)
		end
		paintNavigationButton(tab, tab._wideButton, branchSelected, immediate or not selected)
		paintNavigationButton(tab, tab._compactButton, branchSelected, immediate or not selected)
		if tab._subtabButton then
			paintNavigationButton(tab, tab._subtabButton, selected, immediate or not selected)
		end
		setSelectionIndicator(tab, selected, immediate or not selected, branchSelected)
	end
	self._window:_updateSubtabContext(self)
	self._pageHost.Visible = true
	self._page.Visible = true
	if immediate then
		self._pageHost.GroupTransparency = 0
		self._page.Position = UDim2.fromOffset(0, 0)
	elseif transition.style == "rise" then
		self._pageHost.GroupTransparency = 1
		self._page.Position = UDim2.fromOffset(0, transition.distance)
		self._context.Motion:Animate(self._pageHost, { GroupTransparency = 0 }, transition.preset)
		self._context.Motion:Animate(self._page, { Position = UDim2.fromOffset(0, 0) }, transition.preset)
	else
		self._pageHost.GroupTransparency = 0
		self._page.Position = UDim2.fromOffset(targetOffset, 0)
		self._context.Motion:Animate(self._page, { Position = UDim2.fromOffset(0, 0) }, transition.preset)
	end
	self._window._selected = self
	if not options or options._routeManaged ~= true then
		self._window:_commitRoute(self._id, nil, "tab", false)
	end
	if self._window._visibility == "shown" then
		self._context.FocusManager:SetInitialFocus(self._window._focusGroup)
	end
	return self
end

function Tab:Select(options: any?)
	return self:_select(options)
end
function Tab:Sub(options: any, icon: any)

	if type(options) ~= "table" then
		options = { Title = options, Icon = icon }
	end
	return self._window:_createTab(options, self)
end

function Tab:Mount(slotId: any, contribution: any): (any?, any?)
	return self._window:Mount(slotId, contribution)
end
function Tab:Section(options: any, side: any, description: any)
	if type(options) ~= "table" then
		options = { Title = options, Side = side, Description = description }
	end
	local placement = options.Side or options.Position or "Full"
	assert(
		placement == "Left" or placement == "Right" or placement == "Full",
		"Section placement must be Left, Right, or Full"
	)
	local explicitStyle = options.Style ~= nil or options.style ~= nil
	local sectionStyle = if explicitStyle then (options.Style or options.style) else self._context.Theme.sectionStyle
	assert(sectionStyle == "flat" or sectionStyle == "surface", "Section Style must be flat or surface")
	local sectionId = self._context:_id(options.Id or options.Title or options.Name or "section")
	for _, existing in ipairs(self._sections) do
		assert(existing._id ~= sectionId, "Duplicate section id: " .. sectionId)
	end
	local theme = self._context.Theme
	local parent = if placement == "Left" then self._left elseif placement == "Right" then self._right else self._full
	local root = Factory.make("Frame", {
		BackgroundColor3 = theme.colors.surface,
		BackgroundTransparency = if sectionStyle == "flat" then 1 else 0,
		BorderSizePixel = 0,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, 0, 0, 0),
		LayoutOrder = #self._sections + 1,
	}, parent) :: Frame
	Factory.corner(root, theme.radius.md)
	local surface = Factory.surface(root, theme, "surface", {
		role = if sectionStyle == "flat" then "ghost" else "control",
		border = sectionStyle == "surface",
	})
	local padding = Factory.padding(root, metric(theme, "sectionPadding"))
	local title = tostring(options.Title or options.Name or "Section")
	local collapsibleOption = if options.Collapsible ~= nil then options.Collapsible else options.collapsible
	local collapsible = collapsibleOption ~= false
	local heading = Factory.plainButton(root, "", theme, {
		Active = collapsible,
		Selectable = collapsible,
		TextColor3 = theme.colors.textMuted,
		Size = UDim2.new(1, 0, 0, metric(theme, "sectionHeader")),
		Font = theme.font,
		TextSize = theme.typography.caption * theme.textScale,
		TextXAlignment = Enum.TextXAlignment.Left,
	})
	heading:SetAttribute("PotassiumFontRole", "medium")
	local headingContent = Factory.buttonContent(heading, string.upper(title), theme, {
		Icon = if collapsible then "chevrondown" else nil,
		IconSize = theme.typography.caption,
		Gap = metric(theme, "iconTextGap"),
		Insets = { left = theme.spacing.xxs },
		TextXAlignment = Enum.TextXAlignment.Left,
		Icons = self._context.Icons,
	})
	local headingIcon = headingContent.Icon
	heading:SetAttribute("AccessibleRole", if collapsible then "button" else "heading")
	heading:SetAttribute("AccessibleName", title)
	heading:SetAttribute("SectionStyle", sectionStyle)
	local descriptionText = options.Description or options.Desc
	local descriptionLabel: TextLabel? = nil
	if descriptionText ~= nil and tostring(descriptionText) ~= "" then
		descriptionLabel = Factory.text(root, tostring(descriptionText), theme.typography.caption * theme.textScale, theme.colors.textMuted, {
			AutomaticSize = Enum.AutomaticSize.Y,
			Size = UDim2.new(1, 0, 0, 0),
			TextWrapped = true,
			TextXAlignment = Enum.TextXAlignment.Left,
		})
	end
	local content = Factory.make("Frame", {
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, 0, 0, 0),
	}, root) :: Frame
	local contentLayout = Factory.list(content, metric(theme, "controlGap"))
	local section = setmetatable({
		_context = self._context,
		_window = self._window,
		_tab = self,
		_id = sectionId,
		_style = sectionStyle,
		_styleExplicit = explicitStyle,
		_surface = surface,
		_root = root,
		_padding = padding,
		_content = content,
		_contentLayout = contentLayout,
		_heading = heading,
		_headingIcon = headingIcon,
		_headingContent = headingContent,
		_description = descriptionLabel,
		_order = 0,
		_focusOrder = 0,
		_focusOrders = {},
		_controls = {},
		_collapsible = collapsible,
		_persistControls = options.PersistControls ~= false,
		_maid = Maid.new(),
		_folded = if collapsible then options.Open == false or options.StartOpen == false else false,
	}, Section)
	section._maid:Set("surface", surface)
	section._maid:GiveTask(headingContent)
	local function updateContentPosition()
		local header = metric(section._context.Theme, "sectionHeader")
		local gap = metric(section._context.Theme, "sectionGap")
		local descriptionHeight = if descriptionLabel and descriptionLabel.Visible then descriptionLabel.AbsoluteSize.Y + gap else 0
		if descriptionLabel then
			descriptionLabel.Position = UDim2.fromOffset(0, header)
		end
		content.Position = UDim2.fromOffset(0, header + descriptionHeight)
	end
	if descriptionLabel then
		section._maid:GiveTask(descriptionLabel:GetPropertyChangedSignal("AbsoluteSize"):Connect(updateContentPosition))
	end
	task.defer(updateContentPosition)
	local function setFolded(folded: boolean, immediate: boolean?)
		if not section._collapsible then
			return
		end
		section._folded = folded
		if folded then closeSectionControls(section) end
		content.Visible = not folded
		if descriptionLabel then
			descriptionLabel.Visible = not folded
		end
		local rotation = if folded then -90 else 0
		if immediate or section._context.Theme.reducedMotion then
			section._context.Motion:Cancel(section._headingIcon)
			section._headingIcon.Rotation = rotation
		else
			section._context.Motion:Animate(section._headingIcon, { Rotation = rotation }, "state")
		end
		heading:SetAttribute("Expanded", not folded)
		root:SetAttribute("Folded", folded)
		task.defer(updateContentPosition)
	end
	if collapsible then
		setFolded(section._folded, true)
		section._maid:GiveTask(heading.Activated:Connect(function()
			setFolded(not section._folded)
		end))
		self._window:_registerFocus(
			"section." .. self._id .. "." .. sectionId,
			heading,
			1000 + #self._sections,
			section._maid
		)
	else
		content.Visible = true
		if descriptionLabel then
			descriptionLabel.Visible = true
		end
		heading:SetAttribute("Expanded", true)
		root:SetAttribute("Folded", false)
	end
	function section:SetFolded(folded: boolean)
		if self._collapsible then
			setFolded(folded == true)
		end
		return self
	end
	function section:ToggleFold()
		if self._collapsible then
			setFolded(not self._folded)
		end
		return self
	end
	function section:IsFolded(): boolean
		return if self._collapsible then self._folded else false
	end
	table.insert(self._sections, section)
	self._window._empty.Visible = false
	return section
end
function Tab:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	for _, section in ipairs(self._sections) do
		section:Destroy()
	end
	self._maid:Destroy()
	self._pageHost:Destroy()
	self._wideButton:Destroy()
	self._compactButton:Destroy()
	self._subtabButton:Destroy()
	if not self._window._destroyed then
		for index = #self._window._tabs, 1, -1 do
			if self._window._tabs[index] == self then
				table.remove(self._window._tabs, index)
				break
			end
		end
		for index = #self._window._routeStack, 1, -1 do
			if self._window._routeStack[index].id == self._id then
				table.remove(self._window._routeStack, index)
			end
		end
		self._window._routeRevision += 1
		for index = #self._window._tabs, 1, -1 do
			local child = self._window._tabs[index]
			if child and child._parent == self then child:Destroy() end
		end
		if self._categoryRecord then
			self._categoryRecord.count -= 1
			if self._categoryRecord.count <= 0 then
				self._categoryRecord.wide:Destroy()
				self._categoryRecord.compact:Destroy()
				self._window._categories[self._category] = nil
			end
		end
		if self._window._settings == self then
			self._window._settings = nil
		end
		if self._window._selected == self then
			self._window._selected = nil
			local nextTab = self._window._tabs[1]
			if nextTab then
				nextTab:_select()
			else
				self._window._empty.Visible = true
				self._window:_updateSubtabContext(nil)
			end
		end
	end
end
Tab.Unload = Tab.Destroy

local function clampScale(value: any, minimum: number, maximum: number): number
	assert(type(value) == "number" and value == value and value > 0 and value < math.huge, "Window scale must be a positive finite number")
	return math.clamp(value, minimum, maximum)
end

function Window:_setScale(scale: number)
	local previousScale = self._scale
	if previousScale == scale then
		return
	end
	local offset = self._logicalSize * ((previousScale - scale) / 2)
	self._geometry.Position += UDim2.fromOffset(offset.X, offset.Y)
	self._scale = scale
	self._uiScale.Scale = scale
end

function Window:_updateScale()
	if not self._autoScale then
		return
	end
	local view, size = getViewport(), self._logicalSize
	local available = Vector2.new(math.max(1, view.X - self._scaleMargin * 2), math.max(1, view.Y - self._scaleMargin * 2))
	local fit = math.min(1, available.X / size.X, available.Y / size.Y)
	self:_setScale(math.clamp(fit, self._minScale, self._maxScale))
end

function Window:_setLogicalSize(size: Vector2)
	self._logicalSize = size
	self._geometry.Size = UDim2.fromOffset(size.X, size.Y)
end

function Window:_clampPosition()
	local view, size = getViewport(), self._geometry.AbsoluteSize
	local rootPosition = self._context.Root.AbsolutePosition
	local absolute = self._geometry.AbsolutePosition
	local maxX = math.max(EDGE, view.X - size.X - EDGE)
	local maxY = math.max(EDGE, view.Y - size.Y - EDGE)
	local desiredX = math.clamp(absolute.X, EDGE, maxX)
	local desiredY = math.clamp(absolute.Y, EDGE, maxY)
	self._geometry.Position = UDim2.fromOffset(desiredX - rootPosition.X, desiredY - rootPosition.Y)
end
function Window:_fit()
	self:_updateScale()
	local view, current = getViewport(), self._logicalSize
	local scale = self._scale
	local min = Vector2.new(
		math.min(MIN_SIZE.X, math.max(160 / scale, (view.X - EDGE * 2) / scale)),
		math.min(MIN_SIZE.Y, math.max(160 / scale, (view.Y - EDGE * 2) / scale))
	)
	local max = Vector2.new(math.max(min.X, (view.X - EDGE * 2) / scale), math.max(min.Y, (view.Y - EDGE * 2) / scale))
	if self._maxSize.X > 0 then
		max = Vector2.new(math.min(max.X, self._maxSize.X), max.Y)
	end
	if self._maxSize.Y > 0 then
		max = Vector2.new(max.X, math.min(max.Y, self._maxSize.Y))
	end
	self:_setLogicalSize(Vector2.new(math.clamp(current.X, min.X, max.X), math.clamp(current.Y, min.Y, max.Y)))
	self:_clampPosition()
	self:_layout()
end
local function fullyInsideViewport(object: GuiObject, viewport: GuiObject): boolean
	if not object.Visible or not viewport.Visible or object.Parent == nil or viewport.Parent == nil then
		return false
	end
	local position, size = object.AbsolutePosition, object.AbsoluteSize
	local viewportPosition, viewportSize = viewport.AbsolutePosition, viewport.AbsoluteSize
	local epsilon = 0.5
	return position.X >= viewportPosition.X - epsilon
		and position.Y >= viewportPosition.Y - epsilon
		and position.X + size.X <= viewportPosition.X + viewportSize.X + epsilon
		and position.Y + size.Y <= viewportPosition.Y + viewportSize.Y + epsilon
end

function Window:_updateNavigationContentVisibility()

	for _, tab in ipairs(self._tabs) do
		if tab._wideContent and tab._wideContent.Root then
			tab._wideContent.Root.Visible = fullyInsideViewport(tab._wideButton, self._sidebar)
		end
		if tab._compactContent and tab._compactContent.Root then
			tab._compactContent.Root.Visible = fullyInsideViewport(tab._compactButton, self._compactBar)
		end
		if tab._subtabContent and tab._subtabContent.Root then
			tab._subtabContent.Root.Visible = fullyInsideViewport(tab._subtabButton, self._subtabBar)
		end
	end
end
function Window:_updateSubtabContext(selected: any?)
	local active = selected or self._selected
	local familyRoot = if active then (active._parent or active) else nil
	local hasChildren = false
	if familyRoot then
		for _, tab in ipairs(self._tabs) do
			if tab._parent == familyRoot then
				hasChildren = true
				break
			end
		end
	end
	local barHeight = if hasChildren then metric(self._context.Theme, "tabHeight") + self._context.Theme.spacing.sm else 0
	self._subtabBar.Visible = hasChildren
	self._subtabBar.Size = UDim2.new(1, 0, 0, barHeight)
	for _, tab in ipairs(self._tabs) do
		local inFamily = hasChildren and (tab == familyRoot or tab._parent == familyRoot)
		tab._subtabButton.Visible = inFamily
		if inFamily then
			tab._subtabButton.Size = UDim2.fromOffset(
				math.max(80, #tab._label * self._context.Theme.typography.caption + self._context.Theme.spacing.xl),
				metric(self._context.Theme, "tabHeight")
			)
		end
		if tab == active then
			tab._pageHost.Position = UDim2.fromOffset(0, barHeight)
			tab._pageHost.Size = UDim2.new(1, 0, 1, -barHeight)
		end
	end
end

function Window:_layout()
	local mode = self._layoutMode
	local useTop
	if mode == "side" then useTop = false elseif mode == "top" then useTop = true else
		useTop = self._context.Theme.layout == "top" or (self._autoLayout and self._geometry.AbsoluteSize.X < self._navigationBreakpoint)
	end
	local shown = self._visibility == "shown"
	self._sidebar.Visible, self._compactBar.Visible = shown and not useTop, shown and useTop
	self._brandDivider.Visible = shown and not useTop
	local theme = self._context.Theme
	local header, sidebar, compact = metric(theme, "windowHeader"), metric(theme, "sidebarWidth"), metric(theme, "compactBarHeight")
	local bodyX, bodyWidthOffset = if useTop then 0 else sidebar, if useTop then 0 else -sidebar
	local statusHeight = if self._statusSlot and #self._statusSlot:GetChildren() > 0 then 22 else 0
	local footerHeight = if self._footerSlot and #self._footerSlot:GetChildren() > 0 then 22 else 0
	local chromeHeight = statusHeight + footerHeight
	self._body.Position = UDim2.fromOffset(bodyX, header + if useTop then compact else 0)
	self._body.Size = UDim2.new(1, bodyWidthOffset, 1, -(header + if useTop then compact else 0) - chromeHeight)
	if self._statusSlot and self._footerSlot then
		self._statusSlot.AnchorPoint, self._statusSlot.Position, self._statusSlot.Size = Vector2.new(0, 1), UDim2.new(0, bodyX, 1, -footerHeight), UDim2.new(1, bodyWidthOffset, 0, statusHeight)
		self._footerSlot.AnchorPoint, self._footerSlot.Position, self._footerSlot.Size = Vector2.new(0, 1), UDim2.new(0, bodyX, 1, 0), UDim2.new(1, bodyWidthOffset, 0, footerHeight)
	end
	local columnsWide = self._body.AbsoluteSize.X >= 520
	for _, tab in ipairs(self._tabs) do
		tab._wideButton.Visible, tab._compactButton.Visible = tab._parent == nil and shown and not useTop, tab._parent == nil and shown and useTop
		tab._columnsLayout.FillDirection = if columnsWide then Enum.FillDirection.Horizontal else Enum.FillDirection.Vertical
		local halfGap = math.floor(metric(theme, "pageGap") / 2)
		tab._left.Size = UDim2.new(if columnsWide then 0.5 else 1, if columnsWide then -halfGap else 0, 0, 0)
		tab._right.Size = UDim2.new(if columnsWide then 0.5 else 1, if columnsWide then -halfGap else 0, 0, 0)
		tab._left:SetAttribute("Collapsed", not columnsWide)
		tab._right:SetAttribute("Collapsed", not columnsWide)
	end
	self:_updateSubtabContext(self._selected)
	self:_updateNavigationContentVisibility()
	if not self._navigationVisibilityPending then
		self._navigationVisibilityPending = true
		task.defer(function()
			self._navigationVisibilityPending = false
			if not self._destroyed then self:_updateNavigationContentVisibility() end
		end)
	end
end
function Window:_registerFocus(name: string, object: GuiObject, order: number, ownerMaid: any?)
	local id, ring = self._id .. ".shell." .. name, Factory.focusRing(object, self._context.Theme)
	local cleanupMaid = ownerMaid or self._maid
	self._context.FocusManager:Register(id, object, {
		order = order, group = self._focusGroup, owner = self,
		eligible = function() return self._visibility ~= "hidden" end,
		onFocusChanged = function(focused)
			if focused then
				self._focusedId = id
				self._focusRevision += 1
			elseif self._focusedId == id then
				self._focusedId = nil
				self._focusRevision += 1
			end
			self._context.Motion:Animate(ring, { Transparency = if focused then 0 else 1 }, "quick")
		end,
	})
	self._focusTargets[id] = object
	cleanupMaid:GiveTask(function()
		self._context.FocusManager:Unregister(id)
		if self._focusTargets[id] == object then self._focusTargets[id] = nil end
	end)
end
function Window:_layoutHeader(theme: any)
	local header, sidebarPadding = metric(theme, "windowHeader"), metric(theme, "sidebarPadding")
	local shellControl = math.max(metric(theme, "hitTargetMin"), metric(theme, "compactControlHeight"))
	local searchHeight, desiredWidth = metric(theme, "searchHeight"), metric(theme, "searchWidth")
	local titleInset = if self._logo then header else sidebarPadding * 2
	local frameWidth = self._geometry.AbsoluteSize.X
	if frameWidth <= 0 then frameWidth = self._logicalSize.X end
	local shellRightInset = 0
	local closeLeft = frameWidth - shellRightInset - shellControl
	local controlsLeft = closeLeft - (if self._minimizeButton then shellControl else 0)
	local halfWidth = math.min(frameWidth / 2 - titleInset - sidebarPadding, controlsLeft - frameWidth / 2 - sidebarPadding)
	local searchVisible = halfWidth * 2 >= searchHeight
	local searchWidth = if searchVisible then math.min(desiredWidth, math.floor(halfWidth * 2)) else 0
	local iconOnly = searchVisible and searchWidth < math.min(176, desiredWidth)
	if self._searchButton then
		self._searchButton.Visible = searchVisible
		self._searchButton.AnchorPoint = Vector2.new(0.5, 0.5)
		self._searchButton.Position = UDim2.fromScale(0.5, 0.5)
		self._searchButton.Size = UDim2.fromOffset(searchWidth, searchHeight)
		self._searchButton:SetAttribute("IconOnly", iconOnly)
	end
	if self._minimizeButton then
		local minimizeOffset = shellRightInset + shellControl * 2
		self._minimizeButton.Position = UDim2.new(1, -minimizeOffset, 0.5, -math.floor(shellControl / 2))
		self._minimizeButton.Size = UDim2.fromOffset(shellControl, shellControl)
	end
	if self._closeButton then
		self._closeButton.Position = UDim2.new(1, -shellRightInset - shellControl, 0.5, -math.floor(shellControl / 2))
		self._closeButton.Size = UDim2.fromOffset(shellControl, shellControl)
	end
	local searchLeft = if searchVisible then math.floor((frameWidth - searchWidth) / 2) else controlsLeft
	local searchRight = if searchVisible then searchLeft + searchWidth else controlsLeft
	if self._headerDragRegion then
		local dragWidth = math.max(0, controlsLeft - searchRight)
		self._headerDragRegion.Position = UDim2.fromOffset(searchRight, 0)
		self._headerDragRegion.Size = UDim2.fromOffset(dragWidth, header)
		self._headerDragRegion.Visible = dragWidth > 0
	end
	local titleWidth = math.max(0, searchLeft - titleInset - sidebarPadding)
	if self._subtitle then
		self._title.AnchorPoint, self._title.Position, self._title.Size = Vector2.new(0, 0), UDim2.fromOffset(titleInset, 0), UDim2.fromOffset(titleWidth, math.ceil(header * 0.55))
		self._title.TextXAlignment = Enum.TextXAlignment.Left
		self._subtitle.Position, self._subtitle.Size = UDim2.fromOffset(titleInset, math.floor(header * 0.48)), UDim2.fromOffset(titleWidth, math.floor(header * 0.4))
	else
		self._title.AnchorPoint, self._title.Position, self._title.Size = Vector2.new(0, 0.5), UDim2.fromOffset(titleInset, math.floor(header / 2)), UDim2.fromOffset(titleWidth, header)
		self._title.TextXAlignment = Enum.TextXAlignment.Left
	end
	local searchText = if iconOnly then "" else self._searchPlaceholder
	if not iconOnly and self._searchShortcutHint ~= "" then searchText ..= "  " .. self._searchShortcutHint end
	local contentKey = tostring(searchVisible) .. ":" .. tostring(iconOnly) .. ":" .. searchText
	if self._searchContent and self._searchContentLayoutKey ~= contentKey then
		self._searchContentLayoutKey = contentKey
		self._searchContent:SetText(searchText)
		self._searchContent:Apply(theme, { Icon = "search", IconSize = metric(theme, "iconSize"), Gap = metric(theme, "iconTextGap"), Insets = { left = sidebarPadding, right = sidebarPadding }, Alignment = if iconOnly then "center" else "left", TextXAlignment = Enum.TextXAlignment.Left })
	end
end

local function logoSize(theme: any, requestedSize: any): number
	local header = metric(theme, "windowHeader")
	local inset = metric(theme, "sidebarPadding")
	local maximumLogo = math.max(metric(theme, "iconSize"), header - inset * 2)
	return math.clamp(tonumber(requestedSize) or maximumLogo, metric(theme, "iconSize"), maximumLogo)
end

function Window:_layoutLogo(theme: any)
	local logo = self._logo
	if not logo then
		return
	end
	local header = metric(theme, "windowHeader")
	local inset = metric(theme, "sidebarPadding")
	if self._logoUsesIconRegistry then
		logo.Position = UDim2.fromOffset(inset * 2, 0)
		logo.Size = UDim2.fromOffset(header - inset * 2, header)
		logo.ZIndex = theme.zIndex.content + 4
	else
		local size = logoSize(theme, self._logoRequestedSize)
		logo.Position = UDim2.fromOffset(inset * 2, math.floor((header - size) / 2))
		logo.Size = UDim2.fromOffset(size, size)
		logo.ZIndex = theme.zIndex.content + 2
	end
end

function Window:_mountLogo(source: any, requestedSize: any, theme: any, imageOwner: any): (boolean, any, boolean, boolean)
	if source == nil or source == "" then
		return true, nil, false, false
	end
	local usesIconRegistry = type(source) == "string" and self._context.Icons.Has(source)
	if usesIconRegistry then
		local staging = Instance.new("Frame")
		local renderOk, rendered = xpcall(function()
			return self._context.Icons.Render(
				staging,
				source,
				theme,
				logoSize(theme, requestedSize),
				{
					Position = UDim2.fromOffset(metric(theme, "sidebarPadding") * 2, 0),
					Size = UDim2.fromOffset(
						metric(theme, "windowHeader") - metric(theme, "sidebarPadding") * 2,
						metric(theme, "windowHeader")
					),
					ZIndex = theme.zIndex.content + 4,
				}
			)
		end, debug.traceback)
		if not renderOk or typeof(rendered) ~= "Instance" or not rendered:IsA("Frame") then
			staging:Destroy()
			return false, { code = "logo_unavailable", message = tostring(rendered) }, false, false
		end
		rendered.Parent = self._top
		staging:Destroy()
		return true, rendered, true, rendered:FindFirstChild("IconCanvas") ~= nil and rendered:GetAttribute("IconFallback") == false
	end
	local resolved, resolveError = resolveWindowImage(self, source, "$.window.logo", imageOwner)
	if not resolved then
		return false, resolveError, false, false
	end
	local image = Factory.make("ImageLabel", {
		BackgroundTransparency = 1,
		Image = resolved,
		ScaleType = Enum.ScaleType.Fit,
	}) :: ImageLabel
	image.Parent = self._top
	return true, image, false, false
end

function Window:_refreshLogo(theme: any)
	if not self._logo then
		return
	end
	if self._logoUsesIconRegistry and self._logoProcedural then
		local mounted, nextLogo, usesIconRegistry, procedural = self:_mountLogo(self._logoSource, self._logoRequestedSize, theme, self._imageOwners.logo)
		if mounted then
			local oldLogo = self._logo
			self._logo = nextLogo

			self._logoUsesIconRegistry = usesIconRegistry
			self._logoProcedural = procedural
			oldLogo:Destroy()
		end
	end
	self:_layoutLogo(theme)
end


function Window:_applyTheme()
	local theme = self._context.Theme
	self._frameSurface:Apply(theme, "background")
	self._shadow:Apply(theme)
	self._glow:Apply(theme)
	self._topSurface:Apply(theme, "surface")
	self._sidebarSurface:Apply(theme, "surface")
	self._compactBarSurface:Apply(theme, "surface")
	applyFont(self._title, theme)
	applyFont(self._empty, theme)
	if self._subtitle then
		applyFont(self._subtitle, theme)
	end
	local descendants = self._frame:GetDescendants()
	for _, descendant in ipairs(descendants) do
		if descendant:IsA("TextLabel") or descendant:IsA("TextButton") or descendant:IsA("TextBox") then
			applyFont(descendant, theme)
		end
	end
	for _, icon in ipairs(descendants) do
		if icon:IsA("Frame") and string.sub(icon.Name, 1, 5) == "Icon_" then
			recolorIcon(icon, theme.colors.text)
		end
	end
	if self._subtitle then
		self._subtitle.TextColor3 = theme.colors.textMuted
	end
	if self._logo and self._logo:IsA("TextLabel") then
		self._logo.TextColor3 = theme.colors.text
	end
	self._top.ZIndex = theme.zIndex.content + 3
	self._sidebar.ZIndex = theme.zIndex.content + 2
	self._compactBar.ZIndex = theme.zIndex.content + 2
	self._body.ZIndex = theme.zIndex.content + 2
	if self._backgroundImage then
		self._backgroundImage:SetZIndex(theme.zIndex.content + 1)
	end
	self._geometry.ZIndex = theme.zIndex.content
	self._frame.ZIndex = theme.zIndex.content
	local frameCorner = self._frame:FindFirstChildOfClass("UICorner")
	if frameCorner then
		frameCorner.CornerRadius = UDim.new(0, theme.radius.lg)
	end
	local header = metric(theme, "windowHeader")
	local sidebarWidth = metric(theme, "sidebarWidth")
	local sidebarPadding = metric(theme, "sidebarPadding")
	local compactBarHeight = metric(theme, "compactBarHeight")
	local shellControl = math.max(metric(theme, "hitTargetMin"), metric(theme, "compactControlHeight"))
	self._top.Size = UDim2.new(1, 0, 0, header)
	self._sidebar.Position = UDim2.fromOffset(0, header)
	self._sidebar.Size = UDim2.new(0, sidebarWidth, 1, -header)
	self._compactBar.Position = UDim2.fromOffset(0, header)
	self._compactBar.Size = UDim2.new(1, 0, 0, compactBarHeight)
	self._brandDivider.BackgroundColor3 = theme.colors.borderStrong:Lerp(theme.accentA, 0.18)
	self._brandDivider.BackgroundTransparency = 0.78
	self._brandDivider.Position = UDim2.fromOffset(sidebarPadding, header - 1)
	self._brandDivider.Size = UDim2.fromOffset(math.max(1, sidebarWidth - sidebarPadding * 2), 1)
	self._brandDivider.ZIndex = theme.zIndex.content + 4
	self:_refreshLogo(theme)
	self:_layoutHeader(theme)
	local sidebarInset = self._sidebar:FindFirstChildOfClass("UIPadding")
	if sidebarInset then
		local inset = UDim.new(0, sidebarPadding)
		sidebarInset.PaddingTop, sidebarInset.PaddingRight, sidebarInset.PaddingBottom, sidebarInset.PaddingLeft =
			inset, inset, inset, inset
	end
	local compactInset = self._compactBar:FindFirstChildOfClass("UIPadding")
	if compactInset then
		local inset = UDim.new(0, math.floor(sidebarPadding / 2))
		compactInset.PaddingTop, compactInset.PaddingRight, compactInset.PaddingBottom, compactInset.PaddingLeft =
			inset, inset, inset, inset
	end
	for _, navigation in ipairs({ self._sidebar, self._compactBar }) do
		local layout = navigation:FindFirstChildOfClass("UIListLayout")
		if layout then
			layout.Padding = UDim.new(0, metric(theme, "controlGap"))
		end
	end
	local subtabLayout = self._subtabBar:FindFirstChildOfClass("UIListLayout")
	if subtabLayout then
		subtabLayout.Padding = UDim.new(0, metric(theme, "controlGap"))
	end
	local subtabInset = self._subtabBar:FindFirstChildOfClass("UIPadding")
	if subtabInset then
		local inset = UDim.new(0, math.floor(theme.spacing.sm / 2))
		subtabInset.PaddingTop, subtabInset.PaddingRight, subtabInset.PaddingBottom, subtabInset.PaddingLeft =
			inset, inset, inset, inset
	end
	for _, button in ipairs(self._shellButtons or {}) do
		Factory.setButtonRole(button, if button == self._searchButton then "search" else "ghost", theme)
	end
	if self._minimizeContent then
		self._minimizeContent:Apply(theme, { Icon = "minus", IconSize = metric(theme, "iconSize"), Alignment = "center" })
	end
	if self._closeContent then
		self._closeContent:Apply(theme, { Icon = "close", IconSize = metric(theme, "iconSize"), Alignment = "center" })
	end
	if self._resizeGrip then
		local gripSize = math.max(metric(theme, "hitTargetMin"), metric(theme, "compactControlHeight"))
		self._resizeGrip.Size = UDim2.fromOffset(gripSize, gripSize)
		self._resizeGrip.Position =
			UDim2.new(1, -metric(theme, "borderWidth") * 4, 1, -metric(theme, "borderWidth") * 4)
		if self._resizeIcon then
			self._resizeIcon.Size = UDim2.fromOffset(metric(theme, "iconSize"), metric(theme, "iconSize"))
			self._resizeIcon.Position = UDim2.new(0.5, 0, 0.5, 0)
			self._resizeIcon.AnchorPoint = Vector2.new(0.5, 0.5)
		end
	end
	for _, categoryRecord in pairs(self._categories) do
		for _, heading in ipairs({ categoryRecord.wide, categoryRecord.compact }) do
			heading.TextColor3 = theme.colors.textMuted
			heading.TextSize = theme.typography.caption * theme.textScale
			heading.Size = if heading.Parent == self._sidebar
				then UDim2.new(1, 0, 0, metric(theme, "categoryHeight"))
				else UDim2.fromOffset(math.max(sidebarWidth / 2, heading.AbsoluteSize.X), metric(theme, "categoryHeight"))
		end
	end
	for _, tab in ipairs(self._tabs) do
		Factory.setButtonRole(tab._wideButton, "navigation", theme)
		Factory.setButtonRole(tab._compactButton, "navigation", theme)
		Factory.setButtonRole(tab._subtabButton, "navigation", theme)
		tab._wideButton.Size = UDim2.new(1, 0, 0, metric(theme, "tabHeight"))
		tab._compactButton.Size = UDim2.fromOffset(math.max(sidebarWidth / 2, tab._compactButton.AbsoluteSize.X), metric(theme, "tabHeight"))
		tab._subtabButton.Size = UDim2.fromOffset(
			math.max(80, #tab._label * theme.typography.caption + theme.spacing.xl),
			metric(theme, "tabHeight")
		)
		for _, navigationButton in ipairs({ tab._wideButton, tab._compactButton, tab._subtabButton }) do
			local indicator = navigationButton:FindFirstChild("PotassiumSelectionIndicator")
			if indicator and indicator:IsA("Frame") then
				indicator.Position = UDim2.new(0, 0, 0.5, 0)
				indicator.Size = UDim2.new(0, math.max(2, metric(theme, "borderWidth") * 2), 0.55, 0)
			end
		end
		local contentOptions = {
			Icon = tab._iconName,
			IconSize = metric(theme, "iconSize"),
			Gap = metric(theme, "iconTextGap"),
			Insets = {
				left = metric(theme, "sidebarPadding"),
				right = metric(theme, "sidebarPadding"),
			},
			TextXAlignment = Enum.TextXAlignment.Left,
			Icons = self._context.Icons,
		}
		tab._wideContent:Apply(theme, contentOptions)
		tab._compactContent:Apply(theme, contentOptions)
		tab._subtabContent:Apply(theme, contentOptions)
		local activeRoot = if self._selected then (self._selected._parent or self._selected) else nil
		paintButton(tab._wideButton, theme, tab == activeRoot)
		paintButton(tab._compactButton, theme, tab == activeRoot)
		paintButton(tab._subtabButton, theme, tab == self._selected)
		for _, container in ipairs({ tab._page, tab._full, tab._columns, tab._left, tab._right }) do
			local layout = container:FindFirstChildOfClass("UIListLayout")
			if layout then
				layout.Padding = UDim.new(0, metric(theme, "pageGap"))
			end
		end
		local pagePadding = tab._page:FindFirstChildOfClass("UIPadding")
		if pagePadding then
			local inset = UDim.new(0, metric(theme, "contentPadding"))
			pagePadding.PaddingTop, pagePadding.PaddingRight, pagePadding.PaddingBottom, pagePadding.PaddingLeft =
				inset, inset, inset, inset
		end
		for _, section in ipairs(tab._sections) do
			if not section._styleExplicit then
				section._style = theme.sectionStyle
				section._heading:SetAttribute("SectionStyle", section._style)
				section._surface = Factory.surface(section._root, theme, "surface", {
					role = if section._style == "flat" then "ghost" else "control",
					border = section._style == "surface",
				})
				section._maid:Set("surface", section._surface)
			else
				section._surface:Apply(theme, "surface")
			end
			if section._style == "flat" then
				section._root.BackgroundTransparency = 1
			end
			section._heading.TextColor3 = theme.colors.textMuted
			section._heading.TextSize = theme.typography.caption * theme.textScale
			section._heading.Size = UDim2.new(1, 0, 0, metric(theme, "sectionHeader"))
			section._headingContent:Apply(theme, {
				Icon = if section._collapsible then "chevrondown" else nil,
				IconSize = theme.typography.caption,
				Gap = metric(theme, "iconTextGap"),
				Insets = { left = theme.spacing.xxs },
				TextXAlignment = Enum.TextXAlignment.Left,
			})
			section._headingIcon = section._headingContent.Icon
			if section._headingIcon then
				section._headingIcon.Rotation = if section._folded then -90 else 0
			end
			if section._description then
				section._description.TextColor3, section._description.TextSize =
					theme.colors.textMuted, theme.typography.caption * theme.textScale
				section._description.Position = UDim2.fromOffset(0, metric(theme, "sectionHeader"))
			end
			local corner = section._root:FindFirstChildOfClass("UICorner")
			if corner then
				corner.CornerRadius = UDim.new(0, theme.radius.md)
			end
			local inset = UDim.new(0, metric(theme, "sectionPadding"))
			section._padding.PaddingTop, section._padding.PaddingRight, section._padding.PaddingBottom, section._padding.PaddingLeft =
				inset, inset, inset, inset
			section._contentLayout.Padding = UDim.new(0, metric(theme, "controlGap"))
			local descriptionHeight = if section._description and section._description.Visible
				then section._description.AbsoluteSize.Y + metric(theme, "sectionGap")
				else 0
			section._content.Position = UDim2.fromOffset(0, metric(theme, "sectionHeader") + descriptionHeight)
		end
	end
	self:_layout()
	if self._visibility ~= "shown" then
		self:_applyVisibilitySurface()
	end
end

function Window:_syncGlobalThemeSubscription()
	self._maid:Remove("global-theme")
	if self._inheritsTheme and self._globalContext.ThemeChanged then
		self._maid:Set("global-theme", self._globalContext.ThemeChanged:Connect(function(nextTheme: any)
			if not self._destroyed and self._inheritsTheme then
				if self._preparedInheritedTheme == nextTheme then
					self._preparedInheritedTheme = nil
					return
				end
				if self._themeTransitionActive then return end
				self._context.Theme = nextTheme
				self.Theme = nextTheme
				self._themeRevision += 1
				if self._themeTransition then self._themeTransition:Transition(nextTheme) end
				self._context.ThemeChanged:Fire(nextTheme)
			end
		end))
	end
end

function Window:_setThemeTransitionActive(active: boolean)
	self._themeTransitionActive = active
	self._context._themeTransitionActive = active
end

function Window:ApplyInheritedTheme(nextTheme: any, plan: any?): (boolean, any?)
	if self._destroyed or not self._inheritsTheme then return false, nil end
	local theme = if type(nextTheme) == "table" and type(nextTheme.theme) == "table" and type(nextTheme.provenance) == "table"
		then nextTheme.theme
		else nextTheme
	if type(theme) ~= "table" then return false, { code = "invalid_theme", message = "Inherited theme must be a table" } end
	self._preparedInheritedTheme = theme
	self._context.Theme = theme
	self.Theme = theme
	self._themeRevision += 1
	if self._themeTransition == nil then
		self._context.ThemeChanged:Fire(theme)
		return true, nil
	end
	self:_setThemeTransitionActive(true)
	self._themeTransitionGeneration += 1
	local transitionGeneration = self._themeTransitionGeneration
	local result = self._themeTransition:Transition(nextTheme, plan)
	self._context.ThemeChanged:Fire(theme)
	local function finish()
		if not self._destroyed and transitionGeneration == self._themeTransitionGeneration then
			self:_setThemeTransitionActive(false)
			self:_applyTheme()
		end
	end
	if result.completed then
		finish()
	else
		local remaining = #(result.handles or {})
		for _, handle in ipairs(result.handles or {}) do
			handle:OnCompleted(function()
				remaining -= 1
				if remaining == 0 then finish() end
			end)
		end
	end
	return true, nil
end

function Window:RegisterThemeTransition(binding: any): (any?, any?)
	if self._destroyed or self._themeTransition == nil then return nil, { code = "destroyed", message = "Window has been destroyed" } end
	return self._themeTransition:Register(binding), nil
end

function Window:UnregisterThemeTransition(binding: any)
	if self._themeTransition then self._themeTransition:Unregister(binding) end
end
function Window:_bringToFront()
	if self._geometry.Parent == self._context.Root then
		self._geometry.Parent = nil
		self._geometry.Parent = self._context.Root
	end
	if type(self._globalContext._setActiveWindow) == "function" then
		self._globalContext:_setActiveWindow(self)
	end
end

function Window:GetStackingIndex(): number?
	local parent = self._geometry.Parent
	if parent == nil then return nil end
	for index, child in ipairs(parent:GetChildren()) do
		if child == self._geometry then return index end
	end
	return nil
end
function Window:GetStackingSnapshot(): any?
	local parent = self._geometry.Parent
	if parent == nil then return nil end
	return { parent = parent, children = parent:GetChildren() }
end
function Window:RestoreStackingSnapshot(snapshot: any): boolean
	if type(snapshot) ~= "table" or typeof(snapshot.parent) ~= "Instance" or type(snapshot.children) ~= "table" then return false end
	for _, child in ipairs(snapshot.children) do
		if typeof(child) == "Instance" and child.Parent == snapshot.parent then child.Parent = nil end
	end
	for _, child in ipairs(snapshot.children) do
		if typeof(child) == "Instance" then child.Parent = snapshot.parent end
	end
	return true
end
function Window:BringToFront()
	self:_bringToFront()
	return self
end

local function resolveTabTransition(motion: any, defaultDistance: number, style: any, options: any?): (boolean, any)
	local transitionStyle = style or "slide"
	if transitionStyle ~= "slide" and transitionStyle ~= "rise" and transitionStyle ~= "none" then
		return false, { code = "invalid_tab_transition", message = "Tab transition style must be slide, rise, or none" }
	end
	if options ~= nil and type(options) ~= "table" then
		return false, { code = "invalid_tab_transition", message = "Tab transition options must be a table" }
	end
	local config = options or {}
	local preset = if config.Preset ~= nil then config.Preset else if config.preset ~= nil then config.preset else "rayfieldPanel"
	local distance = if config.Distance ~= nil then config.Distance else if config.distance ~= nil then config.distance else defaultDistance
	if type(preset) ~= "string" or preset == "" or motion:GetMotionPreset(preset) == nil then
		return false, { code = "invalid_tab_transition_preset", message = "Tab transition preset must name a registered motion preset" }
	end
	if type(distance) ~= "number" or distance ~= distance or distance == math.huge or distance == -math.huge or distance < 0 or distance > 32 then
		return false, { code = "invalid_tab_transition_distance", message = "Tab transition distance must be between 0 and 32" }
	end
	return true, table.freeze({ style = transitionStyle, preset = preset, distance = distance })
end

local function normalizePresence(value: any): string
	assert(value == nil or value == "none" or value == "rise" or value == "scale", "Window Presence must be none, rise, or scale")
	return value or "none"
end

local function validatePresence(context: any, style: string, preset: any, exitPreset: any, distance: any, scale: any)
	assert(type(preset) == "string" and preset ~= "", "Window PresencePreset must be a non-empty string")
	assert(type(exitPreset) == "string" and exitPreset ~= "", "Window PresenceExitPreset must be a non-empty string")
	assert(type(distance) == "number" and distance >= 0 and distance <= 64, "Window PresenceDistance must be from 0 to 64")
	assert(type(scale) == "number" and scale > 0 and scale <= 1, "Window PresenceScale must be from 0 to 1")
	assert(context.Motion:GetMotionPreset(preset) ~= nil, "Window PresencePreset must name a registered motion preset")
	assert(context.Motion:GetMotionPreset(exitPreset) ~= nil, "Window PresenceExitPreset must name a registered motion preset")
end

function Window:_setInteractionEnabled(enabled: boolean)
	self._geometry:SetAttribute("PotassiumPresenceGated", not enabled)
	setGuiSubtreeInteractionEnabled(self._geometry, enabled)
end

function Window:_setBodyInteractionEnabled(enabled: boolean)
	for _, root in ipairs({ self._body, self._sidebar, self._compactBar, self._statusSlot, self._footerSlot }) do
		root:SetAttribute("PotassiumPresenceGated", not enabled)
		setGuiSubtreeInteractionEnabled(root, enabled)
	end
end

function Window:_freeMouseCursor(): boolean
	if self._destroyed or self._mouseOverride ~= true or self._visibility ~= "shown" then
		return false
	end
	local userInputService = self._userInputService
	if userInputService == nil then
		return false
	end
	local pressedOk, rightMousePressed = pcall(function()
		return userInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
	end)
	if not pressedOk or rightMousePressed then
		return false
	end
	local behaviorOk = pcall(function()
		if userInputService.MouseBehavior ~= Enum.MouseBehavior.Default then
			userInputService.MouseBehavior = Enum.MouseBehavior.Default
		end
	end)
	local iconOk = pcall(function()
		if not userInputService.MouseIconEnabled then
			userInputService.MouseIconEnabled = true
		end
	end)
	return behaviorOk and iconOk
end

function Window:_applyVisibilitySurface()
	local visibility = self._visibility
	local shown = visibility == "shown"
	local minimized = visibility == "minimized"
	local hidden = visibility == "hidden"
	self._geometry.Visible = not hidden
	self._visual.Visible = not hidden
	self._top.Visible = not hidden
	self._headerSlot.Visible = not hidden
	self._body.Visible = shown
	self._sidebar.Visible = shown and self._sidebar.Visible
	self._compactBar.Visible = shown and self._compactBar.Visible
	self._statusSlot.Visible = shown
	self._footerSlot.Visible = shown
	self:_setInteractionEnabled(not hidden)
	self:_setBodyInteractionEnabled(shown)
	if minimized then
		self._geometry:SetAttribute("AccessibleState", "minimized")
	elseif hidden then
		self._geometry:SetAttribute("AccessibleState", "hidden")
	else
		self._geometry:SetAttribute("AccessibleState", "shown")
	end
	reflowRestorePills(self._globalContext)
end

function Window:_queueRevealElement(tab: any, root: GuiObject)
	local generation = self._bootstrapGeneration
	if generation == nil or self._context.Theme.reducedMotion then
		return
	end
	task.defer(function()
		if self._destroyed or self._bootstrapGeneration ~= generation or root.Parent == nil or self._selected ~= tab then
			return
		end
		local viewTop = tab._page.AbsolutePosition.Y
		local viewBottom = viewTop + math.max(tab._page.AbsoluteSize.Y, self._body.AbsoluteSize.Y)
		local elementTop = root.AbsolutePosition.Y
		local elementBottom = elementTop + root.AbsoluteSize.Y
		if elementBottom <= viewTop or elementTop >= viewBottom then
			return
		end
		self._bootstrapRevealCount = (self._bootstrapRevealCount or 0) + 1
		local revealIndex = self._bootstrapRevealCount
		local delay = math.min(revealIndex - 1, 66) * 0.03
		local goalsByInstance = {}
		local objects = { root :: Instance }
		for _, descendant in ipairs(root:GetDescendants()) do
			table.insert(objects, descendant)
		end
		for _, object in ipairs(objects) do
			local goals = {}
			if object:IsA("CanvasGroup") and object.GroupTransparency < 1 then
				goals.GroupTransparency = object.GroupTransparency
				object.GroupTransparency = 1
			end
			if object:IsA("GuiObject") and object.BackgroundTransparency < 1 then
				goals.BackgroundTransparency = object.BackgroundTransparency
				object.BackgroundTransparency = 1
			end
			if (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) and object.TextTransparency < 1 then
				goals.TextTransparency = object.TextTransparency
				object.TextTransparency = 1
			end
			if (object:IsA("ImageLabel") or object:IsA("ImageButton")) and object.ImageTransparency < 1 then
				goals.ImageTransparency = object.ImageTransparency
				object.ImageTransparency = 1
			end
			if object:IsA("UIStroke") and object.Transparency < 1 then
				goals.Transparency = object.Transparency
				object.Transparency = 1
			end
			if next(goals) ~= nil then
				goalsByInstance[object] = goals
			end
		end
		root:SetAttribute("RayfieldMotionElementReveal", true)
		root:SetAttribute("RayfieldMotionElementRevealDelay", delay)
		root:SetAttribute("RayfieldMotionElementRevealDuration", 0.4)
		task.delay(delay, function()
			if self._destroyed or root.Parent == nil then
				return
			end
			for object, goals in pairs(goalsByInstance) do
				if object.Parent ~= nil then
					self._context.Motion:Animate(object, goals, {
						Duration = 0.4,
						EasingStyle = Enum.EasingStyle.Exponential,
						EasingDirection = Enum.EasingDirection.Out,
					})
				end
			end
		end)
	end)
end

function Window:_closeOwnedSurfaces(reason: string)
	local presentation = self._globalContext.Presentation
	if presentation and type(presentation.CloseOwnedSurfaces) == "function" then
		presentation:CloseOwnedSurfaces(self._presentationOwner, reason)
	end
end

function Window:_configurePresence(style: string)
	self._maid:Remove("presence")
	self._presence = nil
	self._presenceStyle = style
	self._visual.Position = WINDOW_VISUAL_CENTER
	self._presenceScale.Scale = 1
	if style ~= "none" then
		self._presence = Presence.new(self._context.Motion, nil, if style == "scale" then self._presenceScale else self._visual)
		self._maid:Set("presence", self._presence)
	end
	self:_applyVisibilitySurface()
end

function Window:SetPresence(style: any, options: any?)
	local nextStyle = normalizePresence(style)
	local nextPreset, nextExitPreset = self._presencePreset, self._presenceExitPreset
	local nextDistance, nextScale = self._presenceDistance, self._presenceScaleValue
	if options ~= nil then
		assert(type(options) == "table", "Window presence options must be a table")
		if options.Preset ~= nil then nextPreset = options.Preset end
		if options.ExitPreset ~= nil then nextExitPreset = options.ExitPreset end
		if options.Distance ~= nil then nextDistance = options.Distance end
		if options.Scale ~= nil then nextScale = options.Scale end
	end
	validatePresence(self._context, nextStyle, nextPreset, nextExitPreset, nextDistance, nextScale)
	self._presencePreset, self._presenceExitPreset = nextPreset, nextExitPreset
	self._presenceDistance, self._presenceScaleValue = nextDistance, nextScale
	self:_configurePresence(nextStyle)
	return self
end

function Window:GetPresence()
	return {
		Style = self._presenceStyle,
		Preset = self._presencePreset,
		ExitPreset = self._presenceExitPreset,
		Distance = self._presenceDistance,
		Scale = self._presenceScaleValue,
	}
end

local function destroyPartialWindow(self: any)
	self._destroyed = true
	pcall(function() self:_closeOwnedSurfaces("construction-failed") end)
	pcall(function() self:_releaseFocus() end)
	pcall(releaseWindowImageOwner, self, "logo")
	pcall(releaseWindowImageOwner, self, "background")
	if self._globalContext.BackdropGlass ~= nil then
		pcall(self._globalContext.BackdropGlass.Release, self._globalContext.BackdropGlass, self)
	end
	for _, tab in ipairs(self._tabs) do
		pcall(tab.Destroy, tab)
	end
	pcall(self._maid.Destroy, self._maid)
	if type(self._globalContext._onWindowDestroyed) == "function" then
		pcall(self._globalContext._onWindowDestroyed, self._globalContext, self)
	end
	if self._frame ~= nil then pcall(self._frame.Destroy, self._frame) end
	if self._geometry ~= nil then pcall(self._geometry.Destroy, self._geometry) end
	reflowRestorePills(self._globalContext)
end

function Window.new(context: any, options: any)
	assert(type(options) == "table", "CreateWindow requires an options table")
	local title = option(options, "Title", "title", "Window")
	local baseId = context:_id(option(options, "Id", "id", title))
	for _, existing in ipairs(context._windows) do
		assert(existing._id ~= baseId, "Duplicate window id: " .. baseId)
	end
	local themeOverrides = option(options, "Theme", "theme", nil)
	local inheritsTheme = themeOverrides == nil
	local theme = context.Theme
	if themeOverrides ~= nil then
		assert(type(themeOverrides) == "table", "Window Theme must be a table")
		local base = context.Theme
		if themeOverrides.variant ~= nil and themeOverrides.variant ~= base.variant then
			local variant, variantError = Theme.resolve({ variant = themeOverrides.variant })
			if variant == nil then error(variantError.message, 2) end
			base = variant
		end
		local source = Util.deepMerge(base, themeOverrides)
		if type(themeOverrides.spacing) == "table" and themeOverrides.spacingBase == nil then
			source.spacingBase = Util.deepMerge(base.spacingBase or {}, themeOverrides.spacing)
		end
		if type(themeOverrides.metrics) == "table" and themeOverrides.metricsBase == nil then
			source.metricsBase = Util.deepMerge(base.metricsBase or {}, themeOverrides.metrics)
		end
		if themeOverrides.font ~= nil then
			local face, fontError = context.Fonts:Resolve(themeOverrides.font)
			if face == nil then error(fontError.message, 2) end
			source.fontFace = face
			source.font = context.Fonts:Legacy(themeOverrides.font) or base.font
		end
		local resolved, themeError = Theme.resolve(source)
		if resolved == nil then
			error(themeError.message, 2)
		end
		theme = resolved
	end
	local windowContext = localContext(context, theme)
	local size = asSize(option(options, "Size", "size", UDim2.fromOffset(700, 480)))
	local logicalSize = Vector2.new(size.X.Offset, size.Y.Offset)
	assert(logicalSize.X > 0 and logicalSize.Y > 0, "Window Size must use positive offset dimensions when scaling")
	local position = asPosition(option(
		options,
		"Position",
		"position",
		UDim2.new(0.5, -logicalSize.X / 2, 0.5, -logicalSize.Y / 2)
	))
	local menuKey = asKeyCode(option(options, "MenuKey", "menuKey", Enum.KeyCode.RightShift))
	local maxSize = option(options, "MaxSize", "maxSize", Vector2.new(0, 0))
	assert(typeof(maxSize) == "Vector2", "Window MaxSize must be Vector2")
	local layoutMode = option(options, "LayoutMode", "layoutMode", option(options, "Layout", "layout", "auto"))
	assert(layoutMode == "side" or layoutMode == "top" or layoutMode == "auto", "Window LayoutMode must be side, top, or auto")
	local navigationBreakpoint = tonumber(option(options, "NavigationBreakpoint", "navigationBreakpoint", 680))
	assert(
		navigationBreakpoint ~= nil and navigationBreakpoint > 0 and navigationBreakpoint <= 4096,
		"Window NavigationBreakpoint must be between 1 and 4096"
	)
	local minScale = tonumber(option(options, "MinScale", "minScale", 0.65)) or 0.65
	local maxScale = tonumber(option(options, "MaxScale", "maxScale", 1)) or 1
	assert(minScale > 0 and maxScale >= minScale, "Window scale bounds are invalid")
	local transitionOk, transition = resolveTabTransition(
		context.Motion,
		metric(theme, "tabTransitionDistance"),
		option(options, "TabTransition", "tabTransition", "slide"),
		{
