			end
			local valid, validationError = Theme.validate(value.theme)
			return valid, if valid then nil else validationError and validationError.message or "invalid window theme"
		end,
		onChange = function(value)
			if self._syncingThemeRecord or self._destroyed then
				return
			end
			self._inheritsTheme = value.inherit
			self:_syncGlobalThemeSubscription()
			local nextTheme = if value.inherit then self._globalContext.Theme else Util.deepCopy(value.theme)
			self._context.Theme = nextTheme
			self.Theme = nextTheme
			self._themeRevision += 1
			if self._themeTransition then self._themeTransition:Transition(nextTheme) end
			self._context.ThemeChanged:Fire(nextTheme)
		end,
	})
	if not registered then
		error(registerError.message, 2)
	end
	self._themeStoreId = themeStoreId
	self._maid:GiveTask(function()
		context.Store:Unregister(themeStoreId)
	end)
	local userInputService = self._userInputService
	local function connectMouseProperty(propertyName: string)
		local signalOk, signal = pcall(function()
			return userInputService:GetPropertyChangedSignal(propertyName)
		end)
		if signalOk and signal ~= nil then
			self._maid:GiveTask(signal:Connect(function()
				self:_freeMouseCursor()
			end))
		end
	end
	connectMouseProperty("MouseBehavior")
	connectMouseProperty("MouseIconEnabled")
	if userInputService.InputEnded ~= nil then
		self._maid:GiveTask(userInputService.InputEnded:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton2 then
				self:_freeMouseCursor()
			end
		end))
	end
self:_applyTheme()
self._themeTransition = Theme.newTransitionCoordinator(self, context.Motion)
self._maid:GiveTask(self._themeTransition)
self._themeTransition:Register({ instance = self._geometry, tokens = { BackgroundColor3 = "colors.background" } })
self._themeTransition:Register({ instance = self._top, tokens = { BackgroundColor3 = "colors.surface" } })
self._themeTransition:Register({ instance = self._sidebar, tokens = { BackgroundColor3 = "colors.surface" } })
self._themeTransition:Register({ instance = self._compactBar, tokens = { BackgroundColor3 = "colors.surface" } })
self:_configurePresence(presenceStyle)
local worldBlur = option(options, "WorldBlur", "worldBlur", nil)
if worldBlur ~= nil and worldBlur ~= false then
	local configured, configureError
	if type(worldBlur) == "number" then
		configured, configureError = self:ConfigureWorldBlur({ Size = worldBlur, WhileOpen = true })
	elseif type(worldBlur) == "table" then
		configured, configureError = self:ConfigureWorldBlur(worldBlur)
	else
		error("Window WorldBlur must be false, a number, or a table", 2)
	end
	if not configured then error((configureError and configureError.message) or "Window world blur could not be configured", 2) end
end
local opened, openError = self:SetVisibility(if option(options, "StartOpen", "startOpen", true) ~= false then "shown" else "hidden", "initial")
if opened == false then error((openError and openError.message) or "Window could not be opened", 2) end
local restorePill = option(options, "RestorePill", "restorePill", nil)
if restorePill ~= nil and restorePill ~= false then
	local configured, restoreError = self:ConfigureRestorePill(if type(restorePill) == "table" then restorePill else {})
	if not configured then error(restoreError.message, 2) end
end
	if type(context._setActiveWindow) == "function" then
		context:_setActiveWindow(self)
	end
end, debug.traceback)
if not constructed then
	destroyPartialWindow(self)
	error(constructionError, 0)
end
return self
end
function Window:_createTab(options: any, parent: any?)
	assert(type(options) == "table", "Tab requires an options table")
	local theme = self._context.Theme
	local id = self._context:_id(options.Id or options.Title or options.Name or "tab")
	for _, existing in ipairs(self._tabs) do
		assert(existing._id ~= id, "Duplicate tab id: " .. id)
	end
	local category = if parent
		then parent._category
		else options.Category or options.category or self._pendingCategory or self._context._pendingCategory
	self._pendingCategory = nil
	self._context._pendingCategory = nil
	self._globalContext._pendingCategory = nil
	local categoryRecord = if not parent and category and category ~= "" then self._categories[category] else nil
	if not parent and category and category ~= "" and not categoryRecord then
		local categoryText = string.upper(tostring(category))
		local categoryOrder = #self._tabs * 2 + 1
		local wideHeading = Factory.text(
			self._sidebar,
			categoryText,
			theme.typography.caption * theme.textScale,
			theme.colors.textMuted,
			{
				Size = UDim2.new(1, 0, 0, metric(theme, "categoryHeight")),
				LayoutOrder = categoryOrder,
				theme = theme,
				fontRole = "medium",
				typographyRole = "caption",
			}
		)
		local compactHeading = Factory.text(
			self._compactBar,
			categoryText,
			theme.typography.caption * theme.textScale,
			theme.colors.textMuted,
			{
				Size = UDim2.fromOffset(
					math.max(metric(theme, "sidebarWidth") / 2, #categoryText * theme.typography.caption + metric(theme, "sidebarPadding") * 2),
					metric(theme, "categoryHeight")
				),
				LayoutOrder = categoryOrder,
				TextXAlignment = Enum.TextXAlignment.Center,
				theme = theme,
				fontRole = "medium",
				typographyRole = "caption",
			}
		)
		wideHeading:SetAttribute("PotassiumFontRole", "medium")
		compactHeading:SetAttribute("PotassiumFontRole", "medium")
		applyFont(wideHeading, theme)
		applyFont(compactHeading, theme)
		categoryRecord = { wide = wideHeading, compact = compactHeading, count = 0 }
		self._categories[category] = categoryRecord
	end
	if categoryRecord then
		categoryRecord.count += 1
	end
	local rawLabel = tostring(options.Title or options.Name or id)
	local iconName = options.Icon or options.icon
	local order = #self._tabs * 2 + 2
	local wide = Factory.button(self._sidebar, "", theme, {
		Role = "navigation",
		ClipsDescendants = true,
		Size = UDim2.new(1, 0, 0, metric(theme, "tabHeight")),
		LayoutOrder = order,
		TextXAlignment = Enum.TextXAlignment.Left,
	})
	local compactWidth = #rawLabel * theme.typography.body
		+ metric(theme, "sidebarPadding") * 2
		+ (if iconName ~= nil and iconName ~= "" then metric(theme, "iconSize") + metric(theme, "iconTextGap") else 0)
	local compact = Factory.button(self._compactBar, "", theme, {
		Role = "navigation",
		ClipsDescendants = true,
		Size = UDim2.fromOffset(math.max(metric(theme, "sidebarWidth") / 2, compactWidth), metric(theme, "tabHeight")),
		LayoutOrder = order,
		TextXAlignment = Enum.TextXAlignment.Left,
	})
	local subtab = Factory.button(self._subtabBar, "", theme, {
		Role = "navigation",
		ClipsDescendants = true,
		Size = UDim2.fromOffset(
			math.max(80, #rawLabel * theme.typography.caption + theme.spacing.xl),
			metric(theme, "tabHeight")
		),
		LayoutOrder = #self._tabs + 1,
		TextXAlignment = Enum.TextXAlignment.Left,
		Visible = false,
	})
	wide:SetAttribute("PotassiumNavigationLevel", "tab")
	compact:SetAttribute("PotassiumNavigationLevel", "tab")
	subtab:SetAttribute("PotassiumNavigationLevel", "subtab")
	local contentOptions = {
		Icon = iconName,
		IconSize = metric(theme, "iconSize"),
		Gap = metric(theme, "iconTextGap"),
		Insets = {
			left = metric(theme, "sidebarPadding"),
			right = metric(theme, "sidebarPadding"),
		},
		TextXAlignment = Enum.TextXAlignment.Left,
		Icons = self._context.Icons,
	}
	local wideContent = Factory.buttonContent(wide, rawLabel, theme, contentOptions)
	local compactContent = Factory.buttonContent(compact, rawLabel, theme, contentOptions)
	local subtabContent = Factory.buttonContent(subtab, rawLabel, theme, contentOptions)
	for _, navigationButton in ipairs({ wide, compact, subtab }) do
		local indicator = Factory.make("Frame", {
			Name = "PotassiumSelectionIndicator",
			BackgroundColor3 = theme.accentA,
			BorderSizePixel = 0,
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 0, 0.5, 0),
			Size = UDim2.new(0, math.max(2, metric(theme, "borderWidth") * 2), 0.55, 0),
			Visible = false,
			ZIndex = navigationButton.ZIndex + 1,
		}, navigationButton) :: Frame
		Factory.corner(indicator, theme.radius.pill)
		local sweep = Factory.make("UIGradient", {
			Name = "RayfieldIndicatorSweep",
			Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, theme.accentB),
				ColorSequenceKeypoint.new(1, theme.accentA),
			}),
			Rotation = -270,
		}, indicator) :: UIGradient
		sweep:SetAttribute("RayfieldMotionIndicatorSweep", true)
	end
	wide:SetAttribute("Icon", iconName or "")
	wide:SetAttribute("Category", category or "")
	compact:SetAttribute("Icon", iconName or "")
	compact:SetAttribute("Category", category or "")
	subtab:SetAttribute("Icon", iconName or "")
	subtab:SetAttribute("Category", category or "")
	local pageHost = Factory.make("CanvasGroup", {
		BackgroundTransparency = 1,
		ClipsDescendants = true,
		GroupTransparency = 0,
		Size = UDim2.fromScale(1, 1),
		Visible = false,
	}, self._body) :: CanvasGroup
	local page = Factory.make("ScrollingFrame", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		ClipsDescendants = true,
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = math.max(metric(theme, "borderWidth") * 4, 4),
		Size = UDim2.fromScale(1, 1),
		Visible = false,
	}, pageHost) :: ScrollingFrame
	Factory.padding(page, metric(theme, "contentPadding"))
	Factory.list(page, metric(theme, "pageGap"))
	local full = Factory.make("Frame", {
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, 0, 0, 0),
		LayoutOrder = 1,
	}, page) :: Frame
	Factory.list(full, metric(theme, "pageGap"))
	local columns = Factory.make("Frame", {
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, 0, 0, 0),
		LayoutOrder = 2,
	}, page) :: Frame
	local columnsLayout = Factory.list(columns, metric(theme, "pageGap"), true)
	local halfGap = math.floor(metric(theme, "pageGap") / 2)
	local left = Factory.make(
		"Frame",
		{ BackgroundTransparency = 1, AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.new(0.5, -halfGap, 0, 0) },
		columns
	) :: Frame
	Factory.list(left, metric(theme, "pageGap"))
	local right = Factory.make(
		"Frame",
		{ BackgroundTransparency = 1, AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.new(0.5, -halfGap, 0, 0) },
		columns
	) :: Frame
	Factory.list(right, metric(theme, "pageGap"))
	local tab = setmetatable({
		_context = self._context,
		_window = self,
		_id = id,
		_label = rawLabel,
		_wideLabel = rawLabel,
		_compactLabel = rawLabel,
		_iconName = iconName,
		_wideContent = wideContent,
		_compactContent = compactContent,
		_subtabContent = subtabContent,
		_wideButton = wide,
		_compactButton = compact,
		_subtabButton = subtab,
		_button = wide,
		_page = page,
		_pageHost = pageHost,
		_full = full,
		_columns = columns,
		_columnsLayout = columnsLayout,
		_left = left,
		_right = right,
		_sections = {},
		_parent = parent,
		_category = category,
		_categoryRecord = categoryRecord,
		_maid = Maid.new(),
		_destroyed = false,
	}, Tab)
	table.insert(self._tabs, tab)
	for _, navigationButton in ipairs({ wide, compact, subtab }) do
		navigationButton:SetAttribute("RayfieldMotionHover", false)
		tab._maid:GiveTask(navigationButton.MouseEnter:Connect(function()
			animateNavigationHover(tab, navigationButton, true)
		end))
		tab._maid:GiveTask(navigationButton.MouseLeave:Connect(function()
			animateNavigationHover(tab, navigationButton, false)
		end))
	end
	if self._bootstrapGeneration ~= nil then
		local generation = self._bootstrapGeneration
		local delay = math.min(2, (#self._tabs - 1) * 0.15)
		for _, navigationButton in ipairs({ wide, compact, subtab }) do
			local targetTransparency = navigationButton.BackgroundTransparency
			navigationButton:SetAttribute("RayfieldMotionBootstrapDelay", delay)
			navigationButton.BackgroundTransparency = 1
			task.delay(delay, function()
				if not self._destroyed and not tab._destroyed and self._bootstrapGeneration == generation and not self._context.Theme.reducedMotion then
					self._context.Motion:Animate(navigationButton, { BackgroundTransparency = targetTransparency }, RAYFIELD_WINDOW)
				end
			end)
		end
	end
	tab._maid:GiveTask(wide.Activated:Connect(function()
		tab:_select()
	end))
	tab._maid:GiveTask(compact.Activated:Connect(function()
		tab:_select()
	end))
	tab._maid:GiveTask(subtab.Activated:Connect(function()
		tab:_select()
	end))
	tab._maid:GiveTask(page:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
		if not self._applyingWorkspaceScroll then
			self._workspaceScroll[id] = page.CanvasPosition
		end
	end))
	tab._maid:GiveTask(function()
		self._workspaceScroll[id] = nil
	end)
	if not parent then
		self:_registerFocus("tab." .. id .. ".wide", wide, 10 + #self._tabs * 3, tab._maid)
		self:_registerFocus("tab." .. id .. ".compact", compact, 11 + #self._tabs * 3, tab._maid)
	end
	self:_registerFocus("tab." .. id .. ".subtab", subtab, 12 + #self._tabs * 3, tab._maid)
	if not self._selected then
		tab:_select()
	end
	self:_layout()
	return tab
end
function Window:Tab(options: any, icon: any)
	if type(options) ~= "table" then
		options = { Title = options, Icon = icon }
	end
	return self:_createTab(options)
end
function Window:SetCategory(name: any)
	self._pendingCategory = if name == nil then nil else tostring(name)
	return self
end
function Window:AddSettingsTab(options: any)
	if self._settings then
		return self._settings
	end
	if type(options) ~= "table" then
		options = { Id = "settings", Title = "Settings", Icon = options or "settings" }
	else
		options.Id, options.Title, options.Icon =
			options.Id or "settings", options.Title or "Settings", options.Icon or "settings"
	end
	local tab = self:_createTab(options)
	self._settings = tab
	local settingsHash = 0
	for index = 1, #self._id do
		settingsHash = (settingsHash * 131 + string.byte(self._id, index)) % 1000000007
	end
	local prefix = "pui-global-settings-" .. tostring(settingsHash) .. "-"
	local global = self._globalContext
	local function call(title: string, fn: () -> (any, any))
		local ok, first, second = pcall(fn)
		if not ok or first == false or first == nil then
			report(self, title, resultMessage(if ok then second else first), "error")
			return false
		end
		report(self, title, "Done.", "success")
		return true
	end
	local presets = {
		"Custom",
		"Indigo",
		"NeverBlox",
		"Lemon",
		"Mono",
		"Sunset",
		"Mint",
		"Rose Gold",
		"Crimson",
		"Ocean",
		"Toxic",
		"Lavender",
		"Aqua",
		"Ember",
		"Cyber",
		"Bubblegum",
		"Forest",
		"Slate",
		"Cherry",
		"Aurora",
		"Sky",
		"Magma",
		"Grape",
		"Steel",
		"Peach",
		"Neon",
		"Waifu",
	}
	local fontNames = self._context.Fonts:List()
	local appearance = tab:Section({ Title = "Appearance", Side = "Left", PersistControls = false })
	appearance:Dropdown({
		Id = prefix .. "preset",
		Title = "Window preset",
		Choices = presets,
		Default = "Custom",
		Callback = function(value)
			if self._syncingSettings then
				return
			end
			self._selectedPreset = value
			self:ApplyThemePreset(value)
		end,
	})
	appearance:Dropdown({
		Id = prefix .. "variant",
		Title = "Color mode",
		Choices = { "Dark", "Light" },
		Default = if self._context.Theme.variant == "light" then "Light" else "Dark",
		Callback = function(value)
			if self._syncingSettings then
				return
			end
			self._selectedPreset = "Custom"
			self:ApplyTheme({ variant = string.lower(value) })
		end,
	})
	appearance:Dropdown({
		Id = prefix .. "font",
		Title = "Window font",
		Choices = fontNames,
		Default = "Default",
		Callback = function(value)
			if self._syncingSettings then
				return
			end
			self._selectedPreset = "Custom"
			self:SetFont(value)
		end,
	})
	appearance:Colorpicker({
		Id = prefix .. "accent_a",
		Title = "Primary accent",
		Default = self._context.Theme.accentA,
		Callback = function(value)
			if self._syncingSettings then
				return
			end
			self._selectedPreset = "Custom"
			self:SetAccent(value, self._context.Theme.accentB)
		end,
	})
	appearance:Colorpicker({
		Id = prefix .. "accent_b",
		Title = "Secondary accent",
		Default = self._context.Theme.accentB,
		Callback = function(value)
			if self._syncingSettings then
				return
			end
			self._selectedPreset = "Custom"
			self:SetAccent(self._context.Theme.accentA, value)
		end,
	})
	appearance:Dropdown({
		Id = prefix .. "layout",
		Title = "Window navigation",
		Choices = { "Side", "Top" },
		Default = if self._context.Theme.layout == "top" then "Top" else "Side",
		Callback = function(value)
			if self._syncingSettings then
				return
			end
			self._selectedPreset = "Custom"
			self:SetLayout(string.lower(value))
		end,
	})
	appearance:Slider({
		Id = prefix .. "opacity",
		Title = "Window opacity",
		Min = 20,
		Max = 100,
		Default = math.floor(self._context.Theme.opacity * 100 + 0.5),
		Callback = function(value)
			if self._syncingSettings then
				return
			end
			self._selectedPreset = "Custom"
			self:SetOpacity(value)
		end,
	})
	appearance:Slider({
		Id = prefix .. "rounding",
		Title = "Window rounding",
		Min = 0,
		Max = 24,
		Default = self._context.Theme.radius.md,
		Callback = function(value)
			if self._syncingSettings then
				return
			end
			self._selectedPreset = "Custom"
			self:SetRounding(value)
		end,
	})
	appearance:Toggle({
		Id = prefix .. "row_lines",
		Title = "Window row lines",
		Default = self._context.Theme.rowLines == true,
		Callback = function(value)
			if self._syncingSettings then
				return
			end
			self._selectedPreset = "Custom"
			self:SetRowLines(value)
		end,
	})
	appearance:Toggle({
		Id = prefix .. "checkbox_style",
		Title = "Window checkbox style",
		Default = self._context.Theme.checkboxStyle == true,
		Callback = function(value)
			if self._syncingSettings then
				return
			end
			self._selectedPreset = "Custom"
			self:SetCheckboxStyle(value)
		end,
	})
	appearance:Button({
		Title = "Inherit global theme",
		Callback = function()
			self._selectedPreset = "Custom"
			self:InheritGlobalTheme()
		end,
	})
	local function currentFontName(): string
		local current = self.Theme.fontFace
		if typeof(current) == "Font" then
			for _, name in ipairs(self._context.Fonts:List()) do
				local face = self._context.Fonts:Resolve(name)
				if face
					and face.Family == current.Family
					and face.Weight == current.Weight
					and face.Style == current.Style
				then
					return name
				end
			end
		end
		return "Default"
	end
	local function syncWindowSettings()
		if self._destroyed then
			return
		end
		self._syncingSettings = true
		global.Store:Set(prefix .. "preset", self._selectedPreset or "Custom")
		global.Store:Set(prefix .. "variant", if self.Theme.variant == "light" then "Light" else "Dark")
		global.Store:Set(prefix .. "font", currentFontName())
		global.Store:Set(prefix .. "accent_a", self.Theme.accentA)
		global.Store:Set(prefix .. "accent_b", self.Theme.accentB)
		global.Store:Set(prefix .. "layout", if self.Theme.layout == "top" then "Top" else "Side")
		global.Store:Set(prefix .. "opacity", math.floor(self.Theme.opacity * 100 + 0.5))
		global.Store:Set(prefix .. "rounding", self.Theme.radius.md)
		global.Store:Set(prefix .. "row_lines", self.Theme.rowLines == true)
		global.Store:Set(prefix .. "checkbox_style", self.Theme.checkboxStyle == true)
		self._syncingSettings = false
	end
	tab._maid:GiveTask(self.ThemeChanged:Connect(syncWindowSettings))
	task.defer(syncWindowSettings)
	local globalAppearance = select(1, global:_appearance())
		or {
			backgroundEffect = "Off",
			backgroundEffectColor = global.Theme.accentA,
			backgroundImage = { source = nil, transparency = 0.75 },
			performance = false,
			keybindOverlay = false,
			gameInput = true,
		}
	local accessibility = tab:Section({ Title = "Accessibility and input", Side = "Right", PersistControls = false })
	accessibility:Toggle({
		Id = prefix .. "reduced_motion",
		Title = "Global reduced motion",
		Default = global.Theme.reducedMotion == true,
		Callback = function(value)
			if self._syncingGlobalSettings then
				return
			end
			call("Reduced motion", function()
				return global:SetReducedMotion(value)
			end)
		end,
	})
	accessibility:Keybind({
		Id = prefix .. "menu_key",
		Title = "Menu key",
		Default = self._menuKey,
		Callback = function(value)
			local key = if typeof(value) == "EnumItem"
				then value
				elseif type(value) == "table" then value.keyCode
				else nil
			if typeof(key) == "EnumItem" then
				self:SetMenuKey(key)
			end
		end,
	})
	accessibility:Toggle({
		Id = prefix .. "keybind_overlay",
		Title = "Global keybind overlay",
		Default = globalAppearance.keybindOverlay == true,
		Callback = function(value)
			if self._syncingGlobalSettings then
				return
			end
			call("Keybind overlay", function()
				return global:SetKeybindOverlay(value)
			end)
		end,
	})
	accessibility:Toggle({
		Id = prefix .. "game_input",
		Title = "Global game input",
		Default = globalAppearance.gameInput ~= false,
		Callback = function(value)
			if self._syncingGlobalSettings then
				return
			end
			call("Game input", function()
				return global:SetGameInput(value)
			end)
		end,
	})
	local effects = tab:Section({ Title = "Global background and performance", Side = "Left", PersistControls = false })
	effects:Dropdown({
		Id = prefix .. "effect",
		Title = "Background effect",
		Choices = { "Off", "Snow", "Matrix", "Rain" },
		Default = globalAppearance.backgroundEffect or "Off",
		Callback = function(value)
			if self._syncingGlobalSettings then
				return
			end
			call("Background effect", function()
				return global:SetBackgroundEffect(value)
			end)
		end,
	})
	effects:Colorpicker({
		Id = prefix .. "effect_color",
		Title = "Effect color",
		Default = globalAppearance.backgroundEffectColor or global.Theme.accentA,
		Callback = function(value)
			if self._syncingGlobalSettings then
				return
			end
			call("Effect color", function()
				return global:SetBackgroundEffectColor(value)
			end)
		end,
	})
	effects:Textbox({
		Id = prefix .. "effect_image",
		Title = "Background image source",
		Default = if type(globalAppearance.backgroundImage) == "table"
				and type(globalAppearance.backgroundImage.source) == "string"
			then globalAppearance.backgroundImage.source
			else "",
		MaxLength = 512,
	})
	effects:Slider({
		Id = prefix .. "effect_image_opacity",
		Title = "Image transparency",
		Min = 0,
		Max = 100,
		Default = if type(globalAppearance.backgroundImage) == "table"
			then math.floor((tonumber(globalAppearance.backgroundImage.transparency) or 0.75) * 100 + 0.5)
			else 75,
	})
	effects:Button({
		Title = "Apply background image",
		Callback = function()
			local source = global.Store:Get(prefix .. "effect_image")
			local transparency = global.Store:Get(prefix .. "effect_image_opacity")
			call("Background image", function()
				return global:SetBackgroundImage(source, (tonumber(transparency) or 0) / 100)
			end)
		end,
	})
	effects:Toggle({
		Id = prefix .. "performance",
		Title = "Global performance mode",
		Default = globalAppearance.performance == true,
		Callback = function(value)
			if self._syncingGlobalSettings then
				return
			end
			call("Performance mode", function()
				return global:SetPerformance(value)
			end)
		end,
	})
	local function syncGlobalSettings(appearanceValue: any?)
		if self._destroyed then
			return
		end
		local current = appearanceValue or select(1, global:_appearance()) or globalAppearance
		self._syncingGlobalSettings = true
		global.Store:Set(prefix .. "reduced_motion", global.Theme.reducedMotion == true)
		global.Store:Set(prefix .. "menu_key", self._menuKey)
		global.Store:Set(prefix .. "keybind_overlay", current.keybindOverlay == true)
		global.Store:Set(prefix .. "game_input", current.gameInput ~= false)
		global.Store:Set(prefix .. "effect", current.backgroundEffect or "Off")
		global.Store:Set(prefix .. "effect_color", current.backgroundEffectColor or global.Theme.accentA)
		local image = current.backgroundImage
		global.Store:Set(
			prefix .. "effect_image",
			if type(image) == "table" and type(image.source) == "string" then image.source else ""
		)
		global.Store:Set(
			prefix .. "effect_image_opacity",
			if type(image) == "table" then math.floor((tonumber(image.transparency) or 0.75) * 100 + 0.5) else 75
		)
		global.Store:Set(prefix .. "performance", current.performance == true)
		self._syncingGlobalSettings = false
	end
	local appearanceConnection = select(
		1,
		global.Store:Subscribe(global._appearanceId, function(value)
			syncGlobalSettings(value)
		end)
	)
	if appearanceConnection then
		tab._maid:GiveTask(appearanceConnection)
	end
	tab._maid:GiveTask(global.ThemeChanged:Connect(function()
		syncGlobalSettings()
	end))
	task.defer(syncGlobalSettings)
	local config = tab:Section({ Title = "Profiles", Side = "Right", PersistControls = false })
	config:Textbox({ Id = prefix .. "profile", Title = "Profile name", Default = "default", MaxLength = 64 })
	local profilePicker = config:Dropdown({
		Id = prefix .. "profile_list",
		Title = "Saved profiles",
		Provider = function()
			local listed, names = global:ListConfigs()
			return if listed and type(names) == "table" then names else {}
		end,
		Callback = function(value)
			global.Store:Set(prefix .. "profile", tostring(value), "user")
		end,
	})
	local function profile(): string
		return tostring(global.Store:Get(prefix .. "profile") or "default")
	end
	local function refreshProfiles()
		local listed, names = global:ListConfigs()
		if listed and type(names) == "table" then
			profilePicker:UpdateChoices(names)
		end
	end
	config:Button({ Title = "Refresh profiles", Callback = refreshProfiles })
	config:Button({
		Title = "Save profile",
		Callback = function()
			if call("Save profile", function()
				return global:SaveConfig(profile())
			end) then
				refreshProfiles()
			end
		end,
	})
	config:Button({
		Title = "Load profile",
		Callback = function()
			call("Load profile", function()
				return global:LoadConfig(profile())
			end)
		end,
	})
	config:Button({
		Title = "Delete profile",
		Callback = function()
			if call("Delete profile", function()
				return global:DeleteConfig(profile())
			end) then
				refreshProfiles()
			end
		end,
	})
	config:Button({
		Title = "Autoload this profile",
		Callback = function()
			call("Autoload profile", function()
				return global:SetAutoLoad(profile())
			end)
		end,
	})
	config:Button({
		Title = "Export profile",
		Callback = function()
			local exported, encoded = global:ExportConfig(profile())
			if not exported then
				report(self, "Export profile", resultMessage(encoded), "error")
				return
			end
			local clipboard = global.Runtime.clipboard
			if clipboard and type(clipboard.write) == "function" then
				local copied = select(1, pcall(clipboard.write, encoded))
				report(
					self,
					"Export profile",
					if copied then "Copied to clipboard." else "Clipboard write failed.",
					if copied then "success" else "error"
				)
			else
				report(self, "Export profile", encoded, "info")
			end
		end,
	})
	config:Textbox({ Id = prefix .. "import", Title = "Import payload", Default = "", MaxLength = 200000 })
	config:Button({
		Title = "Import profile",
		Callback = function()
			local payload = global.Store:Get(prefix .. "import")
			if
				(payload == nil or payload == "")
				and global.Runtime.clipboard
				and type(global.Runtime.clipboard.read) == "function"
			then
				local readOk, clipboardValue = pcall(global.Runtime.clipboard.read)
				if readOk then
					payload = clipboardValue
				end
			end
			call("Import profile", function()
				return global:ImportConfig(profile(), tostring(payload or ""))
			end)
			refreshProfiles()
		end,
	})
	refreshProfiles()
	return tab
end
function Window:GetSettingsTab()
	return self._settings
end
function Window:SettingsSection(options: any, side: any?, description: any?)
	return (self._settings or self:AddSettingsTab()):Section(options, side, description)
end
function Window:Dock(edge: string)
	if not DOCK_EDGES[edge] then
		return false, { code = "invalid_dock_edge", message = "Unknown dock edge: " .. tostring(edge) }
	end
	if self._destroyed then
		return false, { code = "destroyed", message = "Window is destroyed" }
	end
	if not self._dockState then
		self._dockState = { edge = edge, position = self._geometry.Position, logicalSize = self._logicalSize }
	else
		self._dockState.edge = edge
	end
	self._globalContext:_reflowDocked()
	return self
end

function Window:Undock()
	if self._dockState then
		local saved = self._dockState
		self._dockState = nil
		self._geometry.Position = saved.position
		self:_setLogicalSize(saved.logicalSize)
		self:_fit()
		self._globalContext:_reflowDocked()
	end
	return self
end

function Window:GetDockState()
	return if self._dockState then { edge = self._dockState.edge } else nil
end

function Window:SetAlwaysOnTop(enabled: boolean)
	self._alwaysOnTop = enabled == true
	self._globalContext:_orderWindows()
	return self
end

function Window:GetAlwaysOnTop(): boolean
	return self._alwaysOnTop == true
end

function Window:CreateFloatingPanel(options: any)
	options = options or {}
	local panelPosition = asPosition(option(options, "Position", "position", UDim2.fromOffset(32, 32)))
	local panelSize = asSize(option(options, "Size", "size", UDim2.fromOffset(260, 180)))
	local panelPresenceStyle = normalizePresence(option(options, "Presence", "presence", "none"))
	local panelPresencePreset = option(options, "PresencePreset", "presencePreset", "enter")
	local panelPresenceExitPreset = option(options, "PresenceExitPreset", "presenceExitPreset", "exit")
	local panelPresenceDistance = tonumber(option(options, "PresenceDistance", "presenceDistance", 8)) or 8
	local panelPresenceScale = tonumber(option(options, "PresenceScale", "presenceScale", 0.97)) or 0.97
	validatePresence(self._context, panelPresenceStyle, panelPresencePreset, panelPresenceExitPreset, panelPresenceDistance, panelPresenceScale)

	local panelMaid = Maid.new()
	local frame = Factory.make("Frame", {
		Active = true,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = panelPosition,
		Size = panelSize,
		ZIndex = self.Theme.zIndex.popup,
	}, self._context.Portal) :: Frame
	local visual = Factory.make("Frame", {
		Active = true,
		BackgroundColor3 = self.Theme.colors.surface,
		BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1),
		ZIndex = self.Theme.zIndex.popup,
	}, frame) :: Frame
	local panelScale = Factory.make("UIScale", { Scale = 1 }, visual) :: UIScale
	local panelPresence = if panelPresenceStyle == "none"
		then nil
		else Presence.new(self._context.Motion, panelMaid, if panelPresenceStyle == "scale" then panelScale else visual)
	Factory.corner(visual, self.Theme.radius.md)
	panelMaid:GiveTask(Factory.surface(visual, self.Theme, "surface", { popup = true, glassDecorations = true }))
	local title = Factory.text(visual, tostring(option(options, "Title", "title", "Panel")), self.Theme.typography.label, self.Theme.colors.text, {
		Active = true,
		Size = UDim2.new(1, -16, 0, 32),
		Position = UDim2.fromOffset(8, 0),
	})
	local panel = {
		_frame = frame, _visual = visual, _maid = panelMaid, _window = self, _destroyed = false, _alwaysOnTop = false,
		_visible = true, _presence = panelPresence, _presenceStyle = panelPresenceStyle, _presenceScale = panelScale,
		_logicalPosition = panelPosition, _logicalSize = panelSize, Position = panelPosition, Size = panelSize,
	}
	local dragInput: InputObject? = nil
	local function cancelDrag()
		local input = dragInput
		dragInput = nil
		if input then self._context.InputRouter:EndPointerDrag(input) end
	end
	panelMaid:GiveTask(cancelDrag)
	local function synchronizeGeometry()
		panel._logicalPosition, panel._logicalSize = frame.Position, frame.Size
		panel.Position, panel.Size = frame.Position, frame.Size
	end
	local function clamp()
		local view, size, portal = getViewport(), frame.AbsoluteSize, self._context.Portal.AbsolutePosition
		frame.Position = UDim2.fromOffset(
			math.clamp(frame.AbsolutePosition.X, portal.X, portal.X + math.max(0, view.X - size.X)) - portal.X,
			math.clamp(frame.AbsolutePosition.Y, portal.Y, portal.Y + math.max(0, view.Y - size.Y)) - portal.Y
		)
		synchronizeGeometry()
	end
	function panel:SetPosition(position: any)
		frame.Position = asPosition(position)
		clamp()
		return self
	end
	function panel:SetSize(size: any)
		frame.Size = asSize(size)
		clamp()
		return self
	end
	function panel:SetVisible(visible: boolean)
		local nextVisible = visible == true
		self._visible = nextVisible
		if not nextVisible then cancelDrag() end
		if nextVisible then
			setGuiSubtreeInteractionEnabled(frame, true)
			frame.Visible = true
			if self._presenceStyle == "scale" and self._presence then
				self._presence:Enter({ Scale = panelPresenceScale }, { Scale = 1 }, panelPresencePreset)
			elseif self._presenceStyle == "rise" and self._presence then
				self._presence:Enter({ Position = UDim2.fromOffset(0, panelPresenceDistance) }, { Position = UDim2.fromOffset(0, 0) }, panelPresencePreset)
			end
		elseif self._presenceStyle == "scale" and self._presence and frame.Visible then
			setGuiSubtreeInteractionEnabled(frame, false)
			self._presence:Exit({ Scale = panelPresenceScale }, panelPresenceExitPreset, function()
				if not self._visible and not self._destroyed then frame.Visible = false; panelScale.Scale = 1 end
			end)
		elseif self._presenceStyle == "rise" and self._presence and frame.Visible then
			setGuiSubtreeInteractionEnabled(frame, false)
			self._presence:Exit({ Position = UDim2.fromOffset(0, panelPresenceDistance) }, panelPresenceExitPreset, function()
				if not self._visible and not self._destroyed then frame.Visible = false; visual.Position = UDim2.fromOffset(0, 0) end
			end)
		else
			setGuiSubtreeInteractionEnabled(frame, false)
			frame.Visible = false
		end
		return self
	end
	function panel:SetAlwaysOnTop(enabled: boolean)
		self._alwaysOnTop = enabled == true
		local zIndex = self._window.Theme.zIndex.popup + if self._alwaysOnTop then 100 else 0
		frame.ZIndex, visual.ZIndex, title.ZIndex = zIndex, zIndex, zIndex + 1
		return self
	end
	function panel:Destroy()
		if self._destroyed then return end
		self._destroyed = true
		self._maid:Destroy()
		self._frame:Destroy()
	end
	panelMaid:GiveTask(title.InputBegan:Connect(function(input)
		if panel._visible and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
			self._context.InputRouter:BeginPointerDrag(input, function(_, delta)
				if panel._destroyed or not panel._visible or dragInput ~= input then return end
				frame.Position += UDim2.fromOffset(delta.X, delta.Y)
				clamp()
			end, function()
				dragInput = nil
				if not panel._destroyed then clamp() end
			end)
			dragInput = input
		end
	end))
	local function cameraChanged(camera: Camera?)
		panelMaid:Remove("viewport")
		if camera then
			panelMaid:Set("viewport", camera:GetPropertyChangedSignal("ViewportSize"):Connect(clamp))
		end
		clamp()
	end
	panelMaid:GiveTask(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
		cameraChanged(workspace.CurrentCamera)
	end))
	cameraChanged(workspace.CurrentCamera)
	table.insert(self._floatingPanels, panel)
	panelMaid:GiveTask(function()
		for index = #self._floatingPanels, 1, -1 do
			if self._floatingPanels[index] == panel then table.remove(self._floatingPanels, index) break end
		end
	end)
	clamp()
	if panelPresenceStyle ~= "none" then

		panel:SetVisible(true)
	end
	return panel
end
function Window:_closePortalControls()
	for _, tab in ipairs(self._tabs) do
		for _, section in ipairs(tab._sections) do
			closeSectionControls(section)
		end
	end
end

function Window:_releaseFocus()
	for _, object in ipairs(self._frame:GetDescendants()) do
		if object:IsA("TextBox") then object:ReleaseFocus() end
	end
	self._context.FocusManager:CloseOwned(self, "windowVisibility")
	local focused = self._context.FocusManager._focused
	if focused ~= nil and focused:IsDescendantOf(self._visual) then
		self._context.FocusManager:SetFocused(nil, "windowVisibility")
	end
	self._focusedId = nil
end

function Window:SetVisibility(visibility: any, reason: any?): (any?, any?)
	if self._destroyed then return false, { code = "destroyed", message = "Window has been destroyed" } end
	if visibility ~= "shown" and visibility ~= "minimized" and visibility ~= "hidden" then
		return false, { code = "invalid_visibility", message = "Visibility must be shown, minimized, or hidden" }
	end
	if self._visibility == visibility then
		if visibility == "shown" then
			self:_freeMouseCursor()
		end
		return self
	end
	local previous = self._visibility
	self._visibilityGeneration += 1
	local generation = self._visibilityGeneration
	local shown = visibility == "shown"
	local reduced = self._context.Theme.reducedMotion
	if not shown then
		self:_closeOwnedSurfaces(tostring(reason or visibility))
		self:_closePortalControls()
		self:_releaseFocus()
	end
	local config = self._worldBlurConfig
	if config ~= nil and config.WhileOpen == true then
		local applied, applyError
		if shown then
			applied, applyError = self._globalContext.BackdropGlass:Set(self, config.Size, config)
		else
			applied, applyError = self._globalContext.BackdropGlass:Release(self, {
				Duration = config.CloseDuration or 0, EasingStyle = config.EasingStyle,
				EasingDirection = config.EasingDirection, ReducedMotion = self._globalContext.Theme.reducedMotion == true,
			})
		end
		if not applied then return false, applyError end
	end
	self._visibility = visibility
	if self._cancelHeaderDrag then self._cancelHeaderDrag() end
	if self._cancelResize then self._cancelResize() end
	if shown then
		self:_freeMouseCursor()
	end
	self._context.Motion:Cancel(self._visual)
	self._context.Motion:Cancel(self._top)
	self._context.Motion:Cancel(self._corner)
	self._context.Motion:Cancel(self._presenceScale)
	if self._selected then
		self._context.Motion:Cancel(self._selected._pageHost)
	end
	if shown then
		self._geometry.Visible, self._visual.Visible, self._top.Visible = true, true, true
		self._visual.Size = if previous == "minimized" and not reduced then UDim2.new(1, 0, 0, metric(self._context.Theme, "windowHeader")) else UDim2.fromScale(1, 1)
		self._visual.Position = if previous == "minimized" and not reduced then UDim2.new(0.5, 0, 0, metric(self._context.Theme, "windowHeader") / 2) else WINDOW_VISUAL_CENTER
		self._visual.GroupTransparency = if reduced then 0 else 1
		self._presenceScale.Scale = if reduced then 1 else 0.97
		self._corner.CornerRadius = UDim.new(0, if reduced then self._context.Theme.radius.lg else math.max(0, self._context.Theme.radius.lg - 4))
		if reduced then self._top.GroupTransparency = 0 end
		self:_applyVisibilitySurface()
		if self._selected then
			self._selected._pageHost.GroupTransparency = 0
		end
		if not reduced then
			local windowOptions = if reason == "initial" then RAYFIELD_WINDOW else "rayfieldHide"
			self._context.Motion:Animate(self._visual, {
				GroupTransparency = 0,
				Position = WINDOW_VISUAL_CENTER,
				Size = UDim2.fromScale(1, 1),
			}, windowOptions)
			self._context.Motion:Animate(self._presenceScale, { Scale = 1 }, windowOptions)
			self._context.Motion:Animate(self._corner, { CornerRadius = UDim.new(0, self._context.Theme.radius.lg) }, windowOptions)
			if previous == "minimized" and self._selected then
				self._selected._pageHost.GroupTransparency = 1
				self._context.Motion:Animate(self._selected._pageHost, { GroupTransparency = 0 }, {
					Duration = 0.4,
					EasingStyle = Enum.EasingStyle.Exponential,
					EasingDirection = Enum.EasingDirection.Out,
				})
			end
			self._top.GroupTransparency = 1
			local chromeDelay = if previous == "hidden" and reason ~= "initial" then 0.22 else 0
			local chromeOptions = if reason == "initial"
				then { Duration = 0.6, EasingStyle = Enum.EasingStyle.Exponential, EasingDirection = Enum.EasingDirection.Out }
				else RAYFIELD_CHROME_RESTORE
			task.delay(chromeDelay, function()
				if not self._destroyed and self._visibilityGeneration == generation and self._visibility == "shown" then
					self._context.Motion:Animate(self._top, { GroupTransparency = 0 }, chromeOptions)
				end
			end)
		end
		if reason == "initial" then
			self._bootstrapGeneration = generation
			self._bootstrapRevealCount = 0
			task.delay(2, function()
				if not self._destroyed and self._visibilityGeneration == generation then self._bootstrapGeneration = nil end
			end)
		else
			self._bootstrapGeneration = nil
		end
		self:_bringToFront()
		self:_fit()
		self._context.FocusManager:SetInitialFocus(self._focusGroup)
	elseif visibility == "minimized" then
		self._bootstrapGeneration = nil
		self._geometry.Visible, self._visual.Visible, self._top.Visible = true, true, true
		self._visual.GroupTransparency, self._top.GroupTransparency = 0, 0
		self._presenceScale.Scale = 1
		self:_setInteractionEnabled(true)
		self:_setBodyInteractionEnabled(false)
		local targetSize = UDim2.new(1, 0, 0, metric(self._context.Theme, "windowHeader"))
		local targetPosition = UDim2.new(0.5, 0, 0, metric(self._context.Theme, "windowHeader") / 2)
		if reduced then
			self._visual.Size, self._visual.Position = targetSize, targetPosition
			self:_applyVisibilitySurface()
		else
			if self._selected then self._context.Motion:Animate(self._selected._pageHost, { GroupTransparency = 1 }, { Duration = 0.4, EasingStyle = Enum.EasingStyle.Exponential, EasingDirection = Enum.EasingDirection.Out }) end
			self._visual:SetAttribute("RayfieldMotionMinimize", true)
			self._context.Motion:Animate(self._visual, { Size = targetSize, Position = targetPosition }, { Duration = 0.5, EasingStyle = Enum.EasingStyle.Exponential, EasingDirection = Enum.EasingDirection.Out })
			task.delay(0.4, function()
				if not self._destroyed and self._visibilityGeneration == generation and self._visibility == "minimized" then
					self:_applyVisibilitySurface()
				end
			end)
		end
	else
		self._bootstrapGeneration = nil
		self:_setInteractionEnabled(false)
		if reduced then
			self:_applyVisibilitySurface()
		else
			self._context.Motion:Animate(self._visual, {
				GroupTransparency = 1,
				Position = windowVisualPosition(8),
				Size = UDim2.fromScale(0.96, 0.96),
			}, "rayfieldHide")
			self._context.Motion:Animate(self._presenceScale, { Scale = 0.97 }, "rayfieldHide")
			self._context.Motion:Animate(self._corner, { CornerRadius = UDim.new(0, math.max(0, self._context.Theme.radius.lg - 4)) }, "rayfieldHide")
			self._top.GroupTransparency = 0
			self._context.Motion:Animate(self._top, { GroupTransparency = 1 }, RAYFIELD_CHROME_HIDE)
			task.delay(0.35, function()
				if not self._destroyed and self._visibilityGeneration == generation and self._visibility == "hidden" then
					self:_applyVisibilitySurface()
				end
			end)
		end
	end
	return self
end
function Window:GetWorkspaceSnapshot(): any
	local scroll = {}
	for _, tab in ipairs(self._tabs) do
		local retained = self._workspaceScroll[tab._id] or tab._page.CanvasPosition
		scroll[tab._id] = table.freeze({ x = retained.X, y = retained.Y })
	end
	local panels = {}
	for index, panel in ipairs(self._floatingPanels) do
		if not panel._destroyed then
			panels[index] = table.freeze({
				position = encodeUDim2(panel.Position),
				size = encodeUDim2(panel.Size),
				visible = panel._visible == true,
				alwaysOnTop = panel._alwaysOnTop == true,
			})
		end
	end
	local storedPosition = if self._dockState then self._dockState.position else self._geometry.Position
	local storedSize = if self._dockState
		then UDim2.fromOffset(self._dockState.logicalSize.X, self._dockState.logicalSize.Y)
		else self._geometry.Size
	return freezeWorkspace({
		id = self._id,
		visibility = self._visibility,
		position = table.freeze(encodeUDim2(storedPosition)),
		size = table.freeze(encodeUDim2(storedSize)),
		scale = self._scale,
		autoScale = self._autoScale,
		dock = if self._dockState then self._dockState.edge else false,
		alwaysOnTop = self._alwaysOnTop == true,
		category = if self._selected then self._selected._category else self._pendingCategory,
		panel = table.freeze(panels),
		route = if self._selected then self._selected._id else nil,
		scroll = table.freeze(scroll),
	})
end

function Window:ApplyWorkspaceSnapshot(snapshot: any): (boolean, any?)
	if type(snapshot) ~= "table" then
		return false, { code = "invalid_workspace_snapshot", message = "Workspace snapshot must be a table" }
	end
	local dockEdge = snapshot.dock
	local geometryChanged = snapshot.size ~= nil or snapshot.position ~= nil or snapshot.scale ~= nil or snapshot.autoScale ~= nil or dockEdge ~= nil
	if geometryChanged and self._dockState then
		if dockEdge == nil then dockEdge = self._dockState.edge end
		self:Undock()
	end
	local size = decodeUDim2(snapshot.size)
	if size then self:SetSize(size) end
	if snapshot.scale ~= nil then self:SetScale(snapshot.scale) end
	if snapshot.autoScale ~= nil then self:SetAutoScale(snapshot.autoScale) end
	local position = decodeUDim2(snapshot.position)
	if position then self:SetPosition(position) end
	if dockEdge ~= nil then
		local docked, dockError = self:SetDockEdge(if dockEdge == false then nil else dockEdge)
		if docked == false then return false, dockError end
	end
	if snapshot.alwaysOnTop ~= nil then self:SetAlwaysOnTop(snapshot.alwaysOnTop == true) end
	local category = if type(snapshot.category) == "string" then snapshot.category else nil
	if category ~= nil then self:SetCategory(category) end
	if type(snapshot.route) == "string" then
		local routed, routeError = self:Navigate(snapshot.route, nil, self._id)
		if routed == nil then return false, routeError end
	elseif category ~= nil then
		for _, tab in ipairs(self._tabs) do
			if tab._category == category then
				local routed, routeError = self:Navigate(tab._id, nil, self._id)
				if routed == nil then return false, routeError end
				break
			end
		end
	end
	if type(snapshot.scroll) == "table" then
		self._applyingWorkspaceScroll = true
		for _, tab in ipairs(self._tabs) do
			local offset = snapshot.scroll[tab._id]
			if type(offset) == "table" and type(offset.x) == "number" and type(offset.y) == "number" then
				local retained = Vector2.new(offset.x, offset.y)
				self._workspaceScroll[tab._id] = retained
				tab._page.CanvasPosition = retained
			end
		end
		self._applyingWorkspaceScroll = false
	end
	if type(snapshot.panel) == "table" then
		for index, panelState in ipairs(snapshot.panel) do
			local panel = self._floatingPanels[index]
			if panel and not panel._destroyed and type(panelState) == "table" then
				local panelSize = decodeUDim2(panelState.size)
				if panelSize then panel:SetSize(panelSize) end
				local panelPosition = decodeUDim2(panelState.position)
				if panelPosition then panel:SetPosition(panelPosition) end
				if panelState.alwaysOnTop ~= nil then panel:SetAlwaysOnTop(panelState.alwaysOnTop == true) end
				if panelState.visible ~= nil then panel:SetVisible(panelState.visible == true) end
			end
		end
	end
	return true, nil
end

function Window:SetMouseOverride(enabled: boolean)
	if self._destroyed then return false, { code = "destroyed", message = "Window has been destroyed" } end
	if type(enabled) ~= "boolean" then
		return false, { code = "invalid_mouse_override", message = "Mouse override must be a boolean" }
	end
	self._mouseOverride = enabled
	if enabled then
		self:_freeMouseCursor()
	end
	return self
end
function Window:GetMouseOverride(): boolean
	return self._mouseOverride == true
end

function Window:Show() return self:SetVisibility("shown", "show") end
function Window:Hide() return self:SetVisibility("hidden", "hide") end
function Window:Minimize() return self:SetVisibility("minimized", "minimize") end
function Window:Restore() return self:SetVisibility("shown", "restore") end
function Window:ToggleHidden()
	return self:SetVisibility(if self._visibility == "hidden" then "shown" else "hidden", "toggle")
end
function Window:SetOpen(open: boolean) return self:SetVisibility(if open == true then "shown" else "hidden", "setOpen") end
function Window:Toggle() return self:ToggleHidden() end
function Window:IsOpen(): boolean return self._visibility ~= "hidden" end
function Window:GetVisibilitySnapshot()
	return table.freeze({ visibility = self._visibility, generation = self._visibilityGeneration, minimized = self._visibility == "minimized", hidden = self._visibility == "hidden" })

end
function Window:SetCloseCallback(callback: any)
	if callback ~= nil and type(callback) ~= "function" then
		return false, { code = "invalid_close_callback", message = "Close callback must be a function or nil" }
	end
	self._onClose = callback
	return self
end
function Window:ConfigureRestorePill(config: any?)
	if config ~= nil and type(config) ~= "table" then
		return false, { code = "invalid_restore_pill", message = "Restore pill configuration must be a table" }
	end
	local options = config or {}
	local text = option(options, "Text", "text", "Restore")
	local icon = option(options, "Icon", "icon", nil)
	local position = option(options, "Position", "position", "bottom-right")
	if type(text) ~= "string" or text == "" then
		return false, { code = "invalid_restore_pill_text", message = "Restore pill Text must be a non-empty string" }
	end
	if icon ~= nil and type(icon) ~= "string" then
		return false, { code = "invalid_restore_pill_icon", message = "Restore pill Icon must be a string" }
	end
	if typeof(position) ~= "UDim2" and (type(position) ~= "string" or not ({ ["top-left"] = true, ["top-right"] = true, ["bottom-left"] = true, ["bottom-right"] = true })[string.lower(position)]) then
		return false, { code = "invalid_restore_pill_position", message = "Restore pill Position must be a corner name or UDim2" }
	end
	local enabled = options.Enabled ~= false and options.enabled ~= false
	local stagedIcon = nil
	if enabled and icon ~= nil and icon ~= "" and self._context.Icons and type(self._context.Icons.Render) == "function" then
		local staging = Instance.new("Frame")
		local rendered, iconValue = pcall(self._context.Icons.Render, staging, icon, self._context.Theme, metric(self._context.Theme, "iconSize"), {
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 12, 0.5, 0),
		})
		if not rendered then
			staging:Destroy()
			return false, { code = "invalid_restore_pill_icon", message = tostring(iconValue) }
		end
		stagedIcon = iconValue
		stagedIcon.Parent = nil
		staging:Destroy()
	end
	local pill = self._restorePill
	if pill == nil and enabled then
		pill = Factory.button(self._context.Root, text, self._context.Theme, {
			Role = "ghost", Size = UDim2.fromOffset(144, 44), ZIndex = self._context.Theme.zIndex.popup + 20,
		})
		pill.Name = "PotassiumRestorePill"
		self._maid:GiveTask(pill)
		pill:SetAttribute("AccessibleRole", "button")
		pill:SetAttribute("AccessibleDescription", "Restore the hidden window")
		pill:SetAttribute("AccessibleState", "hidden-window")
		self._maid:GiveTask(pill.Activated:Connect(function() self:Restore() end))
	end
	self._restorePillEnabled = enabled
	self._restorePillConfig = Util.deepCopy(options)
	self._restorePill = pill
	if pill then
		self._maid:Remove("restore-pill-localization")
		self._maid:Remove("restore-pill-icon")
		pill.Text = text
		pill:SetAttribute("AccessibleName", text)
		if stagedIcon then
			stagedIcon.Parent = pill
			self._maid:Set("restore-pill-icon", stagedIcon)
		end
		if text == "Restore" then
			local localization = self._context.Localization
			if localization and type(localization.CreateLocalizedLiteralText) == "function" then
				local localized = localization:CreateLocalizedLiteralText(text)
				self._maid:Set("restore-pill-localization", localized)
				self._maid:GiveTask(localized:Subscribe(function(value)
					if not self._destroyed and self._restorePill then self._restorePill.Text = value; self._restorePill:SetAttribute("AccessibleName", value) end
				end))
				pill.Text = localized:Get()
			end
		end
	end
	if self._cameraChanged then
		self._cameraChanged(workspace.CurrentCamera)
	else
		self._maid:Remove("restore-pill-viewport")
	end
	reflowRestorePills(self._globalContext)
	self:_applyVisibilitySurface()
	return self
end
function Window:ShowToast(options: any)
	local presentation = self._globalContext.Presentation
	if not presentation or type(presentation.ShowToast) ~= "function" then return nil, { code = "presentation_unavailable", message = "Toast presentation is unavailable" } end
	local forwarded = type(options) == "table" and Util.deepCopy(options) or { Text = tostring(options) }
	if type(options) == "table" then
		forwarded.Theme, forwarded.ThemeProvider, forwarded.ThemeChanged = options.Theme, options.ThemeProvider, options.ThemeChanged
	end
	forwarded.Owner = self._presentationOwner
	if forwarded.Theme == nil and forwarded.ThemeProvider == nil then forwarded.ThemeProvider = function() return self._context.Theme end end
	if forwarded.ThemeChanged == nil then forwarded.ThemeChanged = self.ThemeChanged end
	return presentation:ShowToast(forwarded)
end
function Window:ShowChangelog(options: any)
	local presentation = self._globalContext.Presentation
	if not presentation or type(presentation.ShowChangelog) ~= "function" then return nil, { code = "presentation_unavailable", message = "Changelog presentation is unavailable" } end
	local forwarded = type(options) == "table" and Util.deepCopy(options) or {}
	if type(options) == "table" then
		forwarded.Theme, forwarded.ThemeProvider, forwarded.ThemeChanged = options.Theme, options.ThemeProvider, options.ThemeChanged
	end
	forwarded.Owner = self._presentationOwner
	if forwarded.Theme == nil and forwarded.ThemeProvider == nil then forwarded.ThemeProvider = function() return self._context.Theme end end
	if forwarded.ThemeChanged == nil then forwarded.ThemeChanged = self.ThemeChanged end
	return presentation:ShowChangelog(forwarded)
end
function Window:SetSize(size: any, height: number?)
	local next = if type(size) == "number" and type(height) == "number"
		then Vector2.new(size, height)
		else asSize(size)
	local logicalSize = if typeof(next) == "Vector2" then next else Vector2.new(next.X.Offset, next.Y.Offset)
	assert(logicalSize.X > 0 and logicalSize.X < math.huge and logicalSize.Y > 0 and logicalSize.Y < math.huge, "Window size must be positive and finite")
	self._logicalSize = logicalSize
	self:_fit()
	return self
end

function Window:SetScale(scale: any)
	self:_setScale(clampScale(scale, self._minScale, self._maxScale))
	self._autoScale = false
	self:_fit()
	return self
end

function Window:GetScale(): number
	return self._scale
end

function Window:SetAutoScale(enabled: any)
	self._autoScale = enabled == true
	self:_fit()
	return self
end
function Window:SetPosition(position: any)
	return self:SetPos(position)
end
function Window:SetDockEdge(edge: any)
	if edge == nil then return self:Undock() end
	return self:Dock(edge)
end
function Window:ApplyGeometry(geometry: any)
	if type(geometry) ~= "table" then return false, { code = "invalid_geometry", message = "Geometry must be a table" } end
	if geometry.size ~= nil then self:SetSize(geometry.size) end
	if geometry.position ~= nil then self:SetPos(geometry.position) end
	if geometry.dockEdge ~= nil then
		local docked, dockError = self:SetDockEdge(geometry.dockEdge)
		if docked == false then return false, dockError end
	end
	return true, nil
end

function Window:GetAutoScale(): boolean
	return self._autoScale
end
function Window:SetPos(position: any, y: number?)
	self._geometry.Position = if type(position) == "number" and type(y) == "number"
		then UDim2.fromOffset(position, y)
		else asPosition(position)
	self:_clampPosition()
	return self
end
function Window:Center()
	local view, size = getViewport(), self._geometry.AbsoluteSize
	local rootPosition = self._context.Root.AbsolutePosition
	self._geometry.Position =
		UDim2.fromOffset((view.X - size.X) / 2 - rootPosition.X, (view.Y - size.Y) / 2 - rootPosition.Y)
	self:_clampPosition()
	return self
end
function Window:SetTitle(title: string)
	self._title.Text = tostring(title)
	return self
end
function Window:SetSearchPlaceholder(placeholder: string)
	assert(type(placeholder) == "string" and placeholder ~= "", "Search placeholder must be a non-empty string")
	self._searchPlaceholder = placeholder
	if self._searchButton then
		self._searchButton:SetAttribute("AccessibleName", placeholder)
	end
	self:_layoutHeader(self._context.Theme)
	return self
end

function Window:GetSearchButton(): TextButton
	return self._searchButton
end



function Window:GetGeometrySnapshot()
	return table.freeze({
		revision = self._geometryRevision or 0,
		bounds = publicBounds(self._frame),
		mode = self._layoutMode,
		sidebarVisible = self._sidebar.Visible,
		compactVisible = self._compactBar.Visible,
		clipsDescendants = self._frame.ClipsDescendants,
		regions = table.freeze({
			header = publicBounds(self._top),
			sidebar = publicBounds(self._sidebar),
			compact = publicBounds(self._compactBar),
			body = publicBounds(self._body),
		}),
		hitTargets = table.freeze({ search = publicBounds(self._searchButton) }),
	})
end

function Window:_publishGeometry()
	self._geometryRevision = (self._geometryRevision or 0) + 1
	if next(self._geometryChanged._connections) ~= nil then
		self._geometryChanged:Fire(self:GetGeometrySnapshot())
	end
end

function Window:ObserveGeometry(callback: any, options: any?)
	if type(callback) ~= "function" then
		return nil, { code = "invalid_observer", message = "Geometry observer must be a function" }
	end
	local connection = self._geometryChanged:Connect(callback)
	if type(options) == "table" and (options.EmitInitial == true or options.emitInitial == true) then callback(self:GetGeometrySnapshot()) end
	return connection, nil
end

function Window:GetNavigationSnapshot()
	local routes = {}
	for order, tab in ipairs(self._tabs) do
		table.insert(routes, table.freeze({
			id = tab._id,
			parent = if tab._parent then tab._parent._id else nil,
			order = order,
			selected = tab == self._selected,
		}))
	end
	return table.freeze({
		revision = self._navigationRevision or 0,
		mode = self._layoutMode,
		sidebarVisible = self._sidebar.Visible,
		compactVisible = self._compactBar.Visible,
		bounds = table.freeze({ sidebar = publicBounds(self._sidebar), compact = publicBounds(self._compactBar) }),
		routes = table.freeze(routes),
	})
end

function Window:GetRouteSnapshot(): any
	local stack = {}
	for index, route in ipairs(self._routeStack) do
		stack[index] = table.freeze({ id = route.id, params = route.params, source = route.source, generation = route.generation })
	end
	local selected = self._routeStack[#self._routeStack]
	return table.freeze({ stack = table.freeze(stack), selectedRoute = if selected then selected.id else nil, source = if selected then selected.source else nil, generation = self._routeRevision, revision = self._routeRevision })
end

function Window:_commitRoute(routeId: string, params: any, source: any, replace: boolean): any
	self._routeRevision += 1
	local route = { id = routeId, params = params, source = if type(source) == "string" then source else "programmatic", generation = self._routeRevision }
	if replace and #self._routeStack > 0 then self._routeStack[#self._routeStack] = route else table.insert(self._routeStack, route) end
	return self:GetRouteSnapshot()
end

function Window:_selectRoute(routeId: string, params: any, source: any, replace: boolean): (any?, any?)
	for _, tab in ipairs(self._tabs) do
		if tab._id == routeId then
			tab:_select({ _routeManaged = true })
			return self:_commitRoute(routeId, params, source, replace), nil
		end
	end
	return nil, { code = "unknown_route", message = "Window route id is not registered", details = { id = routeId, source = source } }
end

function Window:Navigate(routeId: string, params: any?, source: any?): (any?, any?)
	if self._destroyed then return nil, { code = "destroyed", message = "Window has been destroyed" } end
	return self:_selectRoute(routeId, params, source, false)
end

function Window:ReplaceRoute(routeId: string, params: any?, source: any?): (any?, any?)
	if self._destroyed then return nil, { code = "destroyed", message = "Window has been destroyed" } end
	return self:_selectRoute(routeId, params, source, true)
end

function Window:BackRoute(source: any?): (any?, any?)
	if self._destroyed then return nil, { code = "destroyed", message = "Window has been destroyed" } end
	if #self._routeStack <= 1 then return self:GetRouteSnapshot(), nil end
	table.remove(self._routeStack)
	self._routeRevision += 1
	local route = self._routeStack[#self._routeStack]
	route.source, route.generation = if type(source) == "string" then source else "back", self._routeRevision
	for _, tab in ipairs(self._tabs) do
		if tab._id == route.id then tab:_select({ _routeManaged = true }); break end
	end
	return self:GetRouteSnapshot(), nil
end
function Window:GetAdaptiveSnapshot(): any
	return self._globalContext.Adaptive:GetSnapshot()
end

function Window:TransitionAdaptive(policy: any, retainedState: any?): (any?, any?)
	if self._destroyed then
		return nil, { code = "destroyed", message = "Window has been destroyed" }
	end
	local retained = retainedState or {}
	if retained.route == nil and self._selected then
		retained = Util.deepCopy(retained)
		retained.route = self._selected._id
	end
	return self._globalContext.Adaptive:Transition(policy, retained)
end

function Window:GetVisualSnapshot()
	return table.freeze({
		revision = self._visualRevision or 0,
		materialRoles = table.freeze({ frame = "background", top = "surface", sidebar = "surface", compact = "surface" }),
		effects = table.freeze({ shadow = self._shadow ~= nil, glow = self._glow ~= nil, backgroundImage = self._backgroundImage ~= nil }),
		zOrder = table.freeze({ frame = self._frame.ZIndex, top = self._top.ZIndex, sidebar = self._sidebar.ZIndex, compact = self._compactBar.ZIndex }),
		textMetrics = table.freeze({
			title = table.freeze({ width = self._title.TextBounds.X, height = self._title.TextBounds.Y, truncated = self._title.TextTruncate ~= Enum.TextTruncate.None }),
			subtitle = if self._subtitle then table.freeze({ width = self._subtitle.TextBounds.X, height = self._subtitle.TextBounds.Y, truncated = self._subtitle.TextTruncate ~= Enum.TextTruncate.None }) else nil,
		}),
	})
end

function Window:GetSearchSnapshot()
	return table.freeze({
		revision = self._searchRevision or 0,
		placeholder = self._searchPlaceholder,
		bounds = publicBounds(self._searchButton),
		available = self._searchButton ~= nil and self._searchButton.Visible,
	})
end

function Window:GetFocusSnapshot()
	return table.freeze({ revision = self._focusRevision or 0, focusedId = self._focusedId, group = self._focusGroup })
end

function Window:GetMotionSnapshot()
	local transition = self._tabTransition
	return table.freeze({

		revision = self._motionRevision or 0,
		generation = self._motionGeneration or 0,
		state = self._visibility,
		duration = 0,
		preset = transition and transition.preset or nil,
	})
end
function Window:Mount(slotId: any, contribution: any): (any?, any?)
	if self._destroyed then
		return nil, { code = "destroyed_handle", message = "Window has been destroyed" }
	end
	return self._slotHost:Mount(slotId, contribution)
end

function Window:GetSlotSnapshot()
	return self._slotHost:GetSnapshot()
end

function Window:SetShellContent(content: any): (boolean, any?)
	if self._destroyed then return false, { code = "destroyed_handle", message = "Window has been destroyed" } end
	local codec = SchemaCodec.new()
	local portable, scanError = codec:PreScanPortable(content, "shellContent")
	if not portable then return false, scanError end
	if type(content) ~= "table" or rawget(content, "kind") ~= "shell-content" then
		return false, { code = "invalid_shell_content", message = "Shell content requires kind='shell-content'" }
	end
	for key in pairs(content) do
		if key ~= "kind" and key ~= "header" and key ~= "status" and key ~= "footer" then
			return false, { code = "unknown_shell_content_field", message = "Shell content contains an unknown field" }
		end
	end
	local normalized, normalizeError = codec:Normalize(content)
	if normalized == nil then return false, normalizeError end
	-- The slot host validates and stages every replacement before it mutates any live
	-- mount. Omitted shell slots are included as nil and therefore removed at commit.
	local replaced, replaceError = self._slotHost:ReplaceSlots({ "header", "status", "footer" }, {
		header = normalized.header,
		status = normalized.status,
		footer = normalized.footer,
	})
	if not replaced then return false, replaceError end
	self._shellContent = normalized
	self._shellRevision = (self._shellRevision or 0) + 1
	return true, nil
end

function Window:GetShellContentSnapshot()
	return table.freeze({ revision = self._shellRevision or 0, content = self._shellContent })
end

function Window:ObserveTheme(callback: any, options: any?)
	if type(callback) ~= "function" then
		return nil, { code = "invalid_observer", message = "Theme observer must be a function" }
	end
	local connection = self.ThemeChanged:Connect(function(theme)
		callback(Util.deepCopy(theme))
	end)
	if type(options) == "table" and (options.EmitInitial == true or options.emitInitial == true) then
		callback(Util.deepCopy(self._context.Theme))
	end
	return connection, nil
end

function Window:GetThemeSnapshot()
	return table.freeze({ revision = self._themeRevision or 0, theme = Util.deepCopy(self._context.Theme) })
end

function Window:Focus(id: any): (boolean, any?)
	if type(id) ~= "string" or id == "" then return false, { code = "invalid_focus_id", message = "Focus id must be a non-empty string" } end
	local target = self._focusTargets[id]
	if target == nil then return false, { code = "unknown_focus_id", message = "No focus target is registered for id" } end
	return self._context.FocusManager:SetFocused(target, "public")
end

function Window:FocusSearch(): boolean
	if self._searchButton == nil then return false end
	return self._context.FocusManager:SetFocused(self._searchButton, "search")
end

function Window:ActivateSearch(): boolean
	if self._destroyed or self._searchButton == nil then return false end
	self:FocusSearch()
	self:OpenSpotlight()
	return true
end

function Window:GetSearchEntriesSnapshot()
	local entries = {}
	for order, tab in ipairs(self._tabs) do
		table.insert(entries, table.freeze({ id = tab._id, title = tostring(tab._label or tab._id), order = order, selected = tab == self._selected }))
	end
	return table.freeze({ revision = self._searchRevision or 0, entries = table.freeze(entries) })
end

function Window:GetOwnershipSnapshot()
	local sections, controls = 0, 0
	for _, tab in ipairs(self._tabs) do
		sections += #tab._sections
		for _, section in ipairs(tab._sections) do controls += #section._controls end
	end
	return table.freeze({
		revision = self._ownershipRevision or 0,
		destroyed = self._destroyed == true,
		counts = table.freeze({ tabs = #self._tabs, sections = sections, controls = controls }),
	})
end
function Window:SetSubtitle(value: any)
	if self._subtitle then
		self._subtitle:Destroy()
		self._subtitle = nil
	end
	if value == "auto" then
		value = game.Name
	end
	if value ~= nil and tostring(value) ~= "" then
		local theme = self._context.Theme
		local header = metric(theme, "windowHeader")
		local inset = metric(theme, "sidebarPadding")
		local shellControl = math.max(metric(theme, "hitTargetMin"), metric(theme, "compactControlHeight"))
		local offset = if self._logo then header else inset * 2
		self._subtitle = Factory.text(
			self._top,
			tostring(value),
			theme.typography.caption * theme.textScale,
			theme.colors.textMuted,
			{
				Position = UDim2.fromOffset(offset, math.floor(header * 0.48)),
				Size = UDim2.new(1, -(offset + inset + shellControl * 4), 0, math.floor(header * 0.4)),
				TextTruncate = Enum.TextTruncate.AtEnd,
			}
		)
	end
	return self
end

function Window:SetLogo(source: any, size: any?)
	local nextOwner = {}
	local mounted, nextLogo, usesIconRegistry, procedural = self:_mountLogo(source, size, self._context.Theme, nextOwner)
	if not mounted then
		local policy = self._context.AssetPolicy
		if type(policy) == "table" and type(policy.ReleaseOwner) == "function" then policy:ReleaseOwner(nextOwner) end
		return false, nextLogo
	end
	releaseWindowImageOwner(self, "logo")
	self._imageOwners.logo = nextOwner
	local oldLogo = self._logo
	self._logo = nextLogo
	self._logoSource = if nextLogo then source else nil
	self._logoRequestedSize = if nextLogo then size else nil
	self._logoUsesIconRegistry = usesIconRegistry
	self._logoProcedural = procedural
	if oldLogo then
		oldLogo:Destroy()
	end
	if usesIconRegistry or nextLogo == nil then
		self._maid:Remove("image-cache-logo")
	end
	self:_layoutLogo(self._context.Theme)
	self:_layoutHeader(self._context.Theme)
	return true, nil
end

function Window:GetLogoSnapshot()
	return table.freeze({
		configured = self._logo ~= nil,
		source = self._logoSource,
		requestedSize = self._logoRequestedSize,
		iconRegistry = self._logoUsesIconRegistry == true,
		procedural = self._logoProcedural == true,
		bounds = publicBounds(self._logo),
	})
end
Window.SetIcon = Window.SetLogo

function Window:SetBackgroundImage(source: any, transparency: any?, options: any?)
	if self._destroyed then
		return false, { code = "destroyed", message = "Window has been destroyed" }
	end
	local targetTransparency = if transparency == nil then 0.75 else tonumber(transparency)
	if targetTransparency == nil or targetTransparency ~= targetTransparency or targetTransparency < 0 or targetTransparency > 1 then
		return false, { code = "invalid_transparency", message = "Background image transparency must be from 0 to 1" }
	end
	local nextOwner = {}
	local resolved = nil
	if source ~= nil and source ~= "" then
		local resolveError
		resolved, resolveError = resolveWindowImage(self, source, "$.window.background", nextOwner)
		if not resolved then
			local policy = self._context.AssetPolicy
			if type(policy) == "table" and type(policy.ReleaseOwner) == "function" then policy:ReleaseOwner(nextOwner) end
			return false, resolveError
		end
	end
	if self._backgroundImage == nil then
		self._backgroundImage = ImageCrossfade.new(self._context.Motion, self._maid, self._visual, {
			BackgroundTransparency = 1,
			ScaleType = Enum.ScaleType.Crop,
			Size = UDim2.fromScale(1, 1),
			ZIndex = self._context.Theme.zIndex.content + 1,
		})
	end
	local ok, failure = pcall(function()
		self._backgroundImage:Set(resolved, targetTransparency, options)
	end)
	if not ok then
		local policy = self._context.AssetPolicy
		if type(policy) == "table" and type(policy.ReleaseOwner) == "function" then policy:ReleaseOwner(nextOwner) end
		return false, { code = "invalid_background_options", message = tostring(failure) }
	end
	releaseWindowImageOwner(self, "background")
	self._imageOwners.background = nextOwner
	return true, nil
end

function Window:ApplyTheme(overrides: any)
	if type(overrides) ~= "table" then
		return false, { code = "invalid_theme", message = "Theme overrides must be a table" }
	end
	local base = Util.deepCopy(self._context.Theme)
	if overrides.variant ~= nil and overrides.variant ~= base.variant then
		local variant, variantError = Theme.resolve({ variant = overrides.variant })
		if variant == nil then return false, variantError end
		base = variant
	end
	local source = Util.deepMerge(base, overrides)
	if type(overrides.spacing) == "table" and overrides.spacingBase == nil then
		source.spacingBase = Util.deepMerge(base.spacingBase or {}, overrides.spacing)
	end
	if type(overrides.metrics) == "table" and overrides.metricsBase == nil then
		source.metricsBase = Util.deepMerge(base.metricsBase or {}, overrides.metrics)
	end
	if overrides.font ~= nil then
		local face, fontError = self._context.Fonts:Resolve(overrides.font)
		if face == nil then return false, fontError end
		source.fontFace = face
		source.font = self._context.Fonts:Legacy(overrides.font) or base.font
	end
	local nextTheme, themeError = Theme.resolve(source)
	if nextTheme == nil then return false, themeError end
	if self._themeStoreId then
		self._syncingThemeRecord = true
		local stored, storeError = self._globalContext.Store:Set(self._themeStoreId, { theme = nextTheme, inherit = false })
		self._syncingThemeRecord = false
		if not stored then return false, storeError end
	end
	self._inheritsTheme = false
	self:_syncGlobalThemeSubscription()
	self._context.Theme, self.Theme = nextTheme, nextTheme
	self._themeRevision += 1
	local plan = self._pendingThemeTransition
	if plan ~= nil and self._themeTransition then
		self:_setThemeTransitionActive(true)
		self._themeTransitionGeneration += 1
		local transitionGeneration = self._themeTransitionGeneration
		local result = self._themeTransition:Transition(nextTheme, plan)
		self._context.ThemeChanged:Fire(nextTheme)
		local function finish()
			if not self._destroyed and transitionGeneration == self._themeTransitionGeneration then
				self:_setThemeTransitionActive(false)
				self:_applyTheme()
			end
		end
		if result.completed then
			finish()
		else
			local remaining = #(result.handles or {})
			for _, handle in ipairs(result.handles or {}) do
				handle:OnCompleted(function()
					remaining -= 1
					if remaining == 0 then finish() end
				end)
			end
		end
	else
		if self._themeTransition then self._themeTransition:Transition(nextTheme) end
		self._context.ThemeChanged:Fire(nextTheme)
	end
	return self
end

function Window:TransitionTheme(overrides: any, options: any?)
	local plan, planError = Theme.compileTransitionPlan(options, self._context.Motion)
	if plan == nil then return false, planError end
	self._pendingThemeTransition = plan
	local result, applyError = self:ApplyTheme(overrides)
	self._pendingThemeTransition = nil
	return result, applyError
end
function Window:SetGlass(amount: any, options: any?)
	if type(amount) ~= "number" or amount ~= amount or amount < 0 or amount > 1 then
		return false, { code = "invalid_glass", message = "Glass must be a number from 0 to 1" }
	end
	if options ~= nil and type(options) ~= "table" then
		return false, { code = "invalid_glass_options", message = "Glass options must be a table" }
	end
	local configured = options or {}
	if configured.Blur ~= nil or configured.blur ~= nil then
		return false, {
			code = "unsupported_local_blur",
			message = "Per-Gui backdrop blur is unavailable; SetGlass only changes the window surface and never blurs the world",
		}
	end
	local effects = Util.deepCopy(self._context.Theme.effects)
	effects.glass = amount
	for optionName, token in pairs({ Tint = "glassTint", Border = "glassBorder", Frost = "glassFrost" }) do
		local value = configured[optionName]
		if value == nil then
			value = configured[string.lower(optionName)]
		end
		if value ~= nil then
			if type(value) ~= "number" or value ~= value or value < 0 or value > 1 then
				return false, {
					code = "invalid_glass",
					message = optionName .. " must be a number from 0 to 1",
				}
			end
			effects[token] = value
		end
	end
	return self:ApplyTheme({ effects = effects })
end
function Window:GetGlass()
	return Util.deepCopy(self._context.Theme.effects)
end
function Window:SetShadow(options: any)
	if self._destroyed then
		return false, { code = "destroyed", message = "Window has been destroyed" }
	end
	local effects, shadowError = Theme.withShadow(self._context.Theme.effects, options)
	if effects == nil then
		return false, shadowError
	end
	return self:ApplyTheme({ effects = effects })
end

function Window:GetShadow()
	local effects = self._context.Theme.effects
	return {
		shadow = effects.shadow,
		shadowColor = effects.shadowColor,
		shadowSpread = effects.shadowSpread,
		shadowOffset = effects.shadowOffset,
		accentGlow = effects.accentGlow,
	}
end

function Window:SetGlow(options: any)
	if self._destroyed then
		return false, { code = "destroyed", message = "Window has been destroyed" }
	end
	local effects, glowError = Theme.withGlow(self._context.Theme.effects, options)
	if effects == nil then
		return false, glowError
	end
	return self:ApplyTheme({ effects = effects })
end

function Window:GetGlow()
	return self._glow:Snapshot()
end



function Window:ConfigureWorldBlur(config: any)
	if self._destroyed then return false, { code = "destroyed", message = "Window has been destroyed" } end
	if type(config) ~= "table" then return false, { code = "invalid_world_blur_options", message = "World blur configuration must be a table" } end
	local size = config.Size
	if size == nil then size = config.size end
	if type(size) ~= "number" then return false, { code = "invalid_blur", message = "World blur Size is required" } end
	local nextConfig = Util.deepCopy(config)
	nextConfig.Size, nextConfig.size = size, nil
	if nextConfig.WhileOpen == nil then nextConfig.WhileOpen = nextConfig.whileOpen == true end
	nextConfig.whileOpen = nil
	local valid, validationError = self._globalContext.BackdropGlass:Validate(size, nextConfig)
	if not valid then return false, validationError end
	if nextConfig.WhileOpen == true then
		if self._visibility == "shown" then
			local applied, applyError = self:SetWorldBlur(size, nextConfig)
			if not applied then return false, applyError end
		end
	else
		local applied, applyError = self:SetWorldBlur(size, nextConfig)
		if not applied then return false, applyError end
	end
	self._worldBlurConfig = nextConfig
	return true, nil
end

function Window:GetWorldBlurConfig()
	return if self._worldBlurConfig == nil then nil else Util.deepCopy(self._worldBlurConfig)
end

function Window:SetWorldBlur(amount: any, options: any?)
	if self._destroyed then return false, { code = "destroyed", message = "Window has been destroyed" } end
	local configured = if type(options) == "table" then Util.deepCopy(options) else options
	if type(configured) == "table" then configured.ReducedMotion = self._globalContext.Theme.reducedMotion == true end
	return self._globalContext.BackdropGlass:Set(self, amount, configured)
end

function Window:AnimateWorldBlur(amount: any, options: any?)
	return self:SetWorldBlur(amount, options)
end

function Window:GetWorldBlur()
	if self._destroyed then return nil, { code = "destroyed", message = "Window has been destroyed" } end
	return self._globalContext.BackdropGlass:Snapshot()
end

Window.SetTheme = Window.ApplyTheme

function Window:SetDensity(density: any)
	return self:ApplyTheme({ density = density })
end

function Window:GetDensity(): number
	return self._context.Theme.density
end

function Window:SetMetrics(overrides: any)
	if type(overrides) ~= "table" then
		return false, { code = "invalid_theme", message = "Metrics overrides must be a table" }
	end
	local metricsBase = Util.deepMerge(self._context.Theme.metricsBase or {}, overrides)
	return self:ApplyTheme({ metrics = metricsBase, metricsBase = metricsBase })
end

function Window:GetMetrics(): { [string]: number }
	return Theme.metrics(self._context.Theme)
end

function Window:SetTabTransition(style: any, options: any?)
	if self._destroyed then
		return false, { code = "destroyed", message = "Window has been destroyed" }
	end
	local ok, transition = resolveTabTransition(
		self._context.Motion,
		metric(self._context.Theme, "tabTransitionDistance"),
		style,
		options
	)
	if not ok then
		return false, transition
	end
	self._tabTransition = transition
	return true, self:GetTabTransition()
end

function Window:GetTabTransition()
	local transition = self._tabTransition
	return { style = transition.style, preset = transition.preset, distance = transition.distance }
end

function Window:ApplyThemePreset(name: any)
	local nextTheme, themeError = Theme.applyPreset(name)
	if nextTheme == nil then
		return false, themeError
	end
	return self:ApplyTheme(nextTheme)
end

function Window:SetTextScale(textScale: any)
	return self:ApplyTheme({ textScale = textScale })
end

function Window:GetTextScale(): number
	return self._context.Theme.textScale
end

function Window:InheritGlobalTheme()
	if self._destroyed then
		return self
	end
	if self._themeStoreId then
		self._syncingThemeRecord = true
		local stored, storeError =
			self._globalContext.Store:Set(self._themeStoreId, { theme = self._globalContext.Theme, inherit = true })
		self._syncingThemeRecord = false
		if not stored then
			return false, storeError
		end
	end
	self._inheritsTheme = true
	self:_syncGlobalThemeSubscription()
	self._context.Theme = self._globalContext.Theme
	self.Theme = self._context.Theme
	self._themeRevision += 1
	if self._themeTransition then self._themeTransition:Transition(self._context.Theme) end
	self._context.ThemeChanged:Fire(self._context.Theme)
	return self
end

function Window:SetAccent(accentA: any, accentB: any?)
	if typeof(accentA) ~= "Color3" or (accentB ~= nil and typeof(accentB) ~= "Color3") then
		return false, { code = "invalid_accent", message = "Accent colors must be Color3 values" }
	end
	return self:ApplyTheme({
		accentA = accentA,
		accentB = accentB or accentA,
		colors = { focus = accentA },
		states = { selected = { border = accentB or accentA } },
	})
end
function Window:SetFont(font: any)
	local fonts = self._context.Fonts
	local face, fontError = fonts:Resolve(font)
	if face == nil then
		return false, fontError
	end
	local legacy = fonts:Legacy(font) or self.Theme.font
	return self:ApplyTheme({ font = legacy, fontFace = face })
end
function Window:SetOpacity(opacity: any)
	if type(opacity) ~= "number" or opacity ~= opacity then
		return false, { code = "invalid_opacity", message = "Opacity must be a finite number" }
	end
	if opacity > 1 then
		opacity /= 100
	end
	return self:ApplyTheme({ opacity = opacity })
end
function Window:SetRounding(rounding: any)
	if type(rounding) ~= "number" then
		return false, { code = "invalid_rounding", message = "Rounding must be a number" }
	end
	return self:ApplyTheme({ radius = { sm = rounding, md = rounding, lg = rounding } })
end
function Window:SetRowLines(enabled: any)
	return self:ApplyTheme({ rowLines = enabled == true })
end
function Window:SetCheckboxStyle(enabled: any)
	return self:ApplyTheme({ checkboxStyle = enabled == true })
end
function Window:SetMenuKey(key: any)
	local resolved = asKeyCode(key)
	if resolved ~= self._menuKey then
		removeMenuOwner(self, self._menuKey)
		self._menuKey = resolved
		addMenuOwner(self, resolved)
	end
	return self
end
function Window:OpenSettings()
	local tab = self._settings or self:AddSettingsTab()
	tab:_select()
	self:SetOpen(true)
	return self
end
function Window:OpenSpotlight()
	self._context:OpenSpotlight(self)
	return self
end
function Window:autoloadConfig(profile: string)
	return self._context:SetAutoLoad(profile)
end
function Window:Destroy()
	if self._destroyed then
		return
	end
	if self._cancelHeaderDrag then self._cancelHeaderDrag() end
	if self._cancelResize then self._cancelResize() end
	while #self._floatingPanels > 0 do
		self._floatingPanels[#self._floatingPanels]:Destroy()
	end
	self:_closeOwnedSurfaces("destroy")
	self:_releaseFocus()
	releaseWindowImageOwner(self, "logo")
	releaseWindowImageOwner(self, "background")
	self._destroyed = true
	if self._globalContext.BackdropGlass ~= nil then
		self._globalContext.BackdropGlass:Release(self)
	end
	if type(self._globalContext._onWindowDestroyed) == "function" then
		self._globalContext:_onWindowDestroyed(self)
	end
	for _, tab in ipairs(self._tabs) do
		tab:Destroy()
	end
	self._maid:Destroy()
	self._frame:Destroy()
	self._geometry:Destroy()
	if not self._context._destroyed then
		for index = #self._context._windows, 1, -1 do
			if self._context._windows[index] == self then
				table.remove(self._context._windows, index)
				break
			end
		end
	end
	reflowRestorePills(self._globalContext)
end
Window.Unload = Window.Destroy
return Window

end

__require = function(id)
	local cached = __cache[id]
	if cached ~= nil then
		return cached.value
	end
	local thread = coroutine.running() or "__main"
	local loading = __loading[thread]
	if loading == nil then
		loading = {}
		__loading[thread] = loading
		__stacks[thread] = {}
	end
	local factory = __modules[id]
	if factory == nil then
		error("unknown bundled module: " .. id, 2)
	end
	local pending = __pending[id]
	if pending ~= nil then
		if pending.owner == thread or loading[id] then
			error("circular module dependency: " .. table.concat(__stacks[thread], " -> ") .. " -> " .. id, 2)
		end
		if thread == "__main" then
			error("bundled module yielded while loading: " .. id, 2)
		end
		table.insert(pending.waiters, thread)
		local ok, result = coroutine.yield()
		if ok then
			return result
		end
		error(result, 2)
	end
	loading[id] = true
	local stack = __stacks[thread]
	table.insert(stack, id)
	pending = { owner = thread, waiters = {} }
	__pending[id] = pending
	local ok, result = pcall(factory)
	table.remove(stack)
	loading[id] = nil
	__pending[id] = nil
	if ok then
		__cache[id] = { value = result }
	end
	__settle(pending, ok, result)
	if not ok then
		error(result, 2)
	end
	return result
end

return __require("init")
